-- Navarin d'agneau printanier
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a939f34c-48e2-4fd3-bc1a-216d1801b422'::uuid, null, 'Navarin d''agneau printanier', 'seed', 'https://www.750g.com/navarin-printanier-r204373.htm', '750g', '/recipe-photos/navarin-d-agneau-printanier.webp', 'https://static.750g.com/images/1200-630/9c7fb919b249237bd4324f165cb64768/navarin.jpg',
    2, 4, 90, 20, 70, '["Saler et poivrer l''agneau, puis le saisir à feu vif dans l''huile chaude en cocotte, environ 3 min par face.","Ajouter carotte, navet et oignon coupés et les faire revenir 5 min à feu moyen.","Verser le vin, porter à ébullition et laisser réduire d''un tiers.","Ajouter ail, laurier, clous de girofle et thym, couvrir de bouillon, assaisonner et laisser frémir 30 min.","Ajouter les pommes de terre, le céleri et la tomate en morceaux ainsi que les petits pois.","Couvrir et poursuivre la cuisson à petit feu 20 à 30 min, jusqu''à ce que les pommes de terre soient tendres.","Parsemer de persil ciselé et servir."]'::jsonb,
    array['french', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'french', 889, 52.9,
    true, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Spring lamb navarin","steps":["Season the lamb with salt and pepper, then sear it over high heat in the hot oil in a casserole, about 3 min per side.","Add the chopped carrot, turnip and onion and sauté for 5 min over medium heat.","Pour in the wine, bring to the boil and reduce by a third.","Add the garlic, bay leaf, cloves and thyme, cover with stock, season and simmer gently for 30 min.","Add the potatoes, celery and tomato, cut into pieces, along with the peas.","Cover and continue cooking over low heat for 20 to 30 min, until the potatoes are tender.","Sprinkle with chopped parsley and serve."]},"it":{"title":"Navarin di agnello primaverile","steps":["Salare e pepare l''agnello, poi rosolarlo a fuoco vivo nell''olio caldo in una casseruola, circa 3 min per lato.","Aggiungere carota, rapa e cipolla tagliate e rosolarle per 5 min a fuoco medio.","Versare il vino, portare a ebollizione e far ridurre di un terzo.","Aggiungere aglio, alloro, chiodi di garofano e timo, coprire con il brodo, condire e lasciar sobbollire per 30 min.","Aggiungere le patate, il sedano e il pomodoro a pezzi, insieme ai piselli.","Coprire e proseguire la cottura a fuoco basso da 20 a 30 min, finché le patate sono tenere.","Cospargere di prezzemolo tritato e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a939f34c-48e2-4fd3-bc1a-216d1801b422')
  returning id
)
