-- Crispy scallion ginger salmon
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '00396751-d223-4187-b0ba-b2793c5f3b91'::uuid, null, 'Crispy scallion ginger salmon', 'seed', 'https://thewoksoflife.com/scallion-ginger-salmon/', 'The Woks of Life', '/recipe-photos/crispy-scallion-ginger-salmon.webp', 'https://thewoksoflife.com/wp-content/uploads/2017/03/scallion-ginger-salmon-7.jpg',
    2, 4, 25, 10, 15, '["Heat a frying pan over medium-high heat with half the oil and lay the salmon in skin-side down.","Leave it alone to sear, 4–7 minutes per side depending on thickness, until no raw centre remains; lift it out.","Mix the soy sauce, sugar, sesame oil and salt with about 60 ml water.","Add the remaining oil to the same pan and fry the ginger until crisp, then add the spring onion until wilted.","Pour in the soy mixture, bring to a boil and switch off the heat.","Serve the salmon on rice, spooning the ginger-scallion sauce over it and scattering coriander on top."]'::jsonb,
    array['chinese', 'asian', 'quick', 'light']::text[], 'chinese', 396, 23.9,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Saumon au gingembre et oignon nouveau croustillants","steps":["Faire chauffer une poêle à feu moyen-vif avec la moitié de l''huile et y déposer le saumon côté peau.","Le laisser saisir sans y toucher, 4 à 7 minutes par face selon l''épaisseur, jusqu''à ce que le centre ne soit plus cru ; le retirer.","Mélanger la sauce soja, le sucre, l''huile de sésame et le sel avec environ 60 ml d''eau.","Ajouter le reste de l''huile dans la même poêle et faire frire le gingembre jusqu''à ce qu''il soit croustillant, puis ajouter l''oignon nouveau et le laisser flétrir.","Verser le mélange à la sauce soja, porter à ébullition et éteindre le feu.","Servir le saumon sur du riz, le napper de sauce au gingembre et à l''oignon nouveau et parsemer de coriandre."]},"it":{"title":"Salmone con zenzero e cipollotto croccanti","steps":["Scaldare una padella a fuoco medio-alto con metà dell''olio e adagiarvi il salmone dal lato della pelle.","Lasciarlo rosolare senza toccarlo, 4–7 minuti per lato a seconda dello spessore, finché il centro non è più crudo; toglierlo.","Mescolare la salsa di soia, lo zucchero, l''olio di sesamo e il sale con circa 60 ml d''acqua.","Aggiungere l''olio rimasto nella stessa padella e friggere lo zenzero finché è croccante, poi aggiungere il cipollotto e farlo appassire.","Versare il composto di soia, portare a ebollizione e spegnere il fuoco.","Servire il salmone sul riso, irrorandolo con la salsa allo zenzero e cipollotto e cospargendo di coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '00396751-d223-4187-b0ba-b2793c5f3b91')
  returning id
)
