  select '61be8075-e45c-435e-8e16-5746e7dbddf4'::uuid, null, 'Malaysian nasi goreng with chicken, prawns and egg', 'seed', 'https://ayam.com/recipes/malaysian-nasi-goreng', 'Ayam', '/recipe-photos/malaysian-nasi-goreng-with-chicken-prawns-and-egg.webp', 'https://ayam.com/images/Ayam-Recipe-2019/main-pix/malaysian-nasi-goreng.jpg',
    2, 4, 30, 10, 20, '["Stir-fry the nasi goreng paste with the chicken and onion over medium heat for about 6 minutes.","Add the prawns and green beans and cook 5 minutes more.","Tip in the cooked rice and toss until every grain is coated and piping hot.","Divide between two bowls.","Fry the eggs and set one on each bowl; serve with lettuce, cucumber and tomato on the side."]'::jsonb,
    array['asian', 'malaysian', 'stir-fry', 'high protein']::text[], 'malaysian', 558, 43.2,
    true, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Nasi goreng malaisien au poulet, crevettes et œuf","steps":["Faire sauter la pâte de nasi goreng avec le poulet et l''oignon à feu moyen pendant environ 6 minutes.","Ajouter les crevettes et les haricots verts et poursuivre la cuisson 5 minutes.","Ajouter le riz cuit et mélanger jusqu''à ce que chaque grain soit enrobé et bien chaud.","Répartir dans deux bols.","Faire cuire les œufs au plat et en déposer un sur chaque bol ; servir avec la laitue, le concombre et la tomate à côté."]},"it":{"title":"Nasi goreng malese con pollo, gamberi e uovo","steps":["Saltare la pasta per nasi goreng con il pollo e la cipolla a fuoco medio per circa 6 minuti.","Aggiungere i gamberi e i fagiolini e cuocere per altri 5 minuti.","Versare il riso cotto e mescolare finché ogni chicco non è ben condito e bollente.","Dividere in due ciotole.","Friggere le uova e adagiarne una su ciascuna ciotola; servire con lattuga, cetriolo e pomodoro a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '61be8075-e45c-435e-8e16-5746e7dbddf4')
