-- Miso salmon with rice and greens
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ef7a2f1d-b2e6-44f8-b3e8-4198959fa625'::uuid, null, 'Miso salmon with rice and greens', 'seed', 'https://www.olivemagazine.com/recipes/healthy/miso-salmon/', 'Olive Magazine', '/recipe-photos/miso-salmon-with-rice-and-greens.webp', 'https://images.immediate.co.uk/production/volatile/sites/2/2020/08/OLI-0920-Healthy-MisoSalmon_05631_preview-ca3e82c.jpg?crop=2px%2C746px%2C1195px%2C514px&resize=1199%2C628',
    2, 2, 35, 10, 25, '["Boil the rice in salted water until tender, then drain.","Whisk the miso, rice vinegar, ginger and garlic with 100 ml water.","Season the salmon and pan-fry it skin-side down until crisp, then turn it over.","Pour the miso sauce into the pan and slide it under a hot grill until the sauce bubbles and reduces.","Meanwhile boil the bok choy, sugar snaps and baby corn briefly until just tender, then drain.","Plate the rice and greens, set the salmon on top, spoon over the sauce and finish with spring onion."]'::jsonb,
    array['japanese', 'asian', 'light', 'high protein']::text[], 'japanese', 547, 35.4,
    true, 'en', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Saumon au miso, riz et légumes verts","steps":["Faire cuire le riz dans de l''eau bouillante salée jusqu''à ce qu''il soit tendre, puis l''égoutter.","Fouetter le miso, le vinaigre de riz, le gingembre et l''ail avec 100 ml d''eau.","Assaisonner le saumon et le faire cuire à la poêle côté peau jusqu''à ce qu''il soit croustillant, puis le retourner.","Verser la sauce au miso dans la poêle et passer sous le gril bien chaud jusqu''à ce que la sauce bouillonne et réduise.","Pendant ce temps, faire cuire brièvement le pak choï, les pois gourmands et les mini-épis de maïs dans l''eau bouillante jusqu''à ce qu''ils soient juste tendres, puis les égoutter.","Dresser le riz et les légumes, déposer le saumon dessus, napper de sauce et parsemer d''oignon nouveau."]},"it":{"title":"Salmone al miso con riso e verdure","steps":["Lessare il riso in acqua salata finché non è tenero, poi scolarlo.","Sbattere il miso, l''aceto di riso, lo zenzero e l''aglio con 100 ml d''acqua.","Condire il salmone e cuocerlo in padella dal lato della pelle finché non è croccante, poi girarlo.","Versare la salsa al miso nella padella e passarla sotto il grill ben caldo finché la salsa non sobbolle e si riduce.","Nel frattempo lessare brevemente il pak choi, le taccole e le pannocchiette finché non sono appena tenere, poi scolarli.","Disporre nei piatti il riso e le verdure, adagiarvi sopra il salmone, irrorare con la salsa e completare con il cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ef7a2f1d-b2e6-44f8-b3e8-4198959fa625')
  returning id
)
