-- Brazilian fish stew (moqueca)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '66ead8f3-045d-4124-a93c-2ee801a03fef'::uuid, null, 'Brazilian fish stew (moqueca)', 'seed', 'https://www.feastingathome.com/brazilian-fish-stew-aka-moqueca', 'Feasting at Home', '/recipe-photos/brazilian-fish-stew-moqueca.webp', '/recipe-photos/brazilian-fish-stew-moqueca.webp',
    2, 4, 35, 10, 25, '["Pat the fish dry, cut into large chunks and rub with salt, lime zest and lime juice; set aside.","In a wide pan, sauté the onion in the oil with a pinch of salt until soft.","Add carrot, red pepper, garlic and jalapeño and cook a few minutes more.","Stir in the tomato paste, paprika, cumin and stock, bring to a simmer, add the tomatoes, cover and cook until the carrots are tender.","Pour in the coconut milk and adjust the salt.","Tuck the fish into the sauce and simmer gently, spooning broth over, until just cooked (thick pieces can finish in a 175°C oven).","Add a squeeze of lime, scatter with herbs and serve over rice."]'::jsonb,
    array['brazilian', 'stew', 'comfort', 'high protein']::text[], 'brazilian', 768, 42.7,
    true, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Ragoût de poisson brésilien (moqueca)","steps":["Éponger le poisson, le couper en gros morceaux et le frotter avec le sel, le zeste et le jus de citron vert ; réserver.","Dans une sauteuse large, faire revenir l''oignon dans l''huile avec une pincée de sel jusqu''à ce qu''il soit tendre.","Ajouter la carotte, le poivron rouge, l''ail et le jalapeño et poursuivre la cuisson quelques minutes.","Incorporer le concentré de tomate, le paprika, le cumin et le fumet, porter à frémissement, ajouter les tomates, couvrir et cuire jusqu''à ce que les carottes soient tendres.","Verser le lait de coco et rectifier le sel.","Enfoncer le poisson dans la sauce et laisser mijoter doucement en l''arrosant de bouillon, jusqu''à ce qu''il soit tout juste cuit (les morceaux épais peuvent finir de cuire au four à 175 °C).","Ajouter un filet de citron vert, parsemer d''herbes et servir sur du riz."]},"it":{"title":"Stufato di pesce brasiliano (moqueca)","steps":["Asciugare il pesce tamponandolo, tagliarlo a pezzi grandi e strofinarlo con il sale, la scorza e il succo di lime; tenere da parte.","In una padella larga, far appassire la cipolla nell''olio con un pizzico di sale finché non è morbida.","Aggiungere la carota, il peperone rosso, l''aglio e il jalapeño e cuocere ancora per qualche minuto.","Unire il concentrato di pomodoro, la paprika, il cumino e il brodo, portare a bollore leggero, aggiungere i pomodori, coprire e cuocere finché le carote non sono tenere.","Versare il latte di cocco e regolare di sale.","Adagiare il pesce nella salsa e cuocere delicatamente a fuoco lento, irrorandolo con il brodo, finché non è appena cotto (i pezzi spessi possono finire la cottura in forno a 175 °C).","Aggiungere una spruzzata di lime, cospargere di erbe aromatiche e servire sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '66ead8f3-045d-4124-a93c-2ee801a03fef')
  returning id
)
