-- Chicken with leeks and mushrooms
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a28a8bc9-457a-4379-b12a-e0367cc7a7cc'::uuid, null, 'Chicken with leeks and mushrooms', 'seed', null, 'Claude', '/recipe-photos/chicken-with-leeks-and-mushrooms.webp', '/recipe-photos/chicken-with-leeks-and-mushrooms.webp',
    2, null, 45, 15, 30, '["Cook the rice in a pan of boiling salted water for 12 min (or as the packet says), then drain.","Season the chicken. Brown it in the oil in a large sauté pan over medium-high heat for 5–6 min, until golden all over; set aside.","Add the butter and mushrooms to the pan and cook 4–5 min over high heat, until their water has evaporated and they colour.","Add the leeks, garlic, thyme and a pinch of salt and cook over medium heat for 6–8 min, until soft but not browned.","Pour in the wine and boil 1 min, then add the stock and the chicken. Cover and simmer 10 min, until the chicken is cooked through.","Stir in the crème fraîche and mustard and simmer uncovered for 2 min, until the sauce coats a spoon. Adjust the seasoning.","Serve with the rice, scattered with parsley."]'::jsonb,
    array['french', 'comfort', 'autumn', 'winter']::text[], 'french', 892, 42.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet aux poireaux et champignons","steps":["Cuire le riz dans une casserole d''eau bouillante salée 12 min (ou selon le paquet), puis l''égoutter.","Saler et poivrer le poulet. Le faire dorer dans l''huile dans une grande sauteuse à feu moyen-vif 5 à 6 min, jusqu''à ce qu''il soit doré de tous côtés ; réserver.","Mettre le beurre et les champignons dans la sauteuse et cuire 4 à 5 min à feu vif, jusqu''à ce que leur eau soit évaporée et qu''ils colorent.","Ajouter les poireaux, l''ail, le thym et une pincée de sel et cuire à feu moyen 6 à 8 min, jusqu''à ce qu''ils soient fondants sans colorer.","Verser le vin et faire bouillir 1 min, puis ajouter le bouillon et le poulet. Couvrir et laisser mijoter 10 min, jusqu''à ce que le poulet soit cuit à cœur.","Incorporer la crème fraîche et la moutarde et laisser frémir 2 min à découvert, jusqu''à ce que la sauce nappe la cuillère. Rectifier l''assaisonnement.","Servir avec le riz, parsemé de persil."]},"it":{"title":"Pollo con porri e funghi","steps":["Cuocere il riso in una pentola di acqua bollente salata per 12 min (o secondo la confezione), poi scolarlo.","Salare e pepare il pollo. Rosolarlo nell''olio in una padella larga e alta a fuoco medio-alto per 5-6 min, finché è dorato su tutti i lati; tenerlo da parte.","Mettere nella padella il burro e i funghi e cuocere 4-5 min a fuoco vivo, finché la loro acqua è evaporata e prendono colore.","Aggiungere i porri, l''aglio, il timo e un pizzico di sale e cuocere a fuoco medio 6-8 min, finché sono morbidi ma non coloriti.","Versare il vino e far bollire 1 min, poi aggiungere il brodo e il pollo. Coprire e cuocere a fuoco lento 10 min, finché il pollo è cotto all''interno.","Incorporare la crème fraîche e la senape e sobbollire senza coperchio per 2 min, finché la salsa vela il cucchiaio. Regolare di sale e pepe.","Servire con il riso, cosparso di prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a28a8bc9-457a-4379-b12a-e0367cc7a7cc')
  returning id
)
