-- Roasted pepper and mozzarella gnocchi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8ffa559e-9ee1-4db0-b46c-a4956b1290be'::uuid, null, 'Roasted pepper and mozzarella gnocchi', 'seed', null, 'Claude', '/recipe-photos/roasted-pepper-and-mozzarella-gnocchi.webp', '/recipe-photos/roasted-pepper-and-mozzarella-gnocchi.webp',
    2, null, 40, 10, 30, '["Heat the oven to 220°C.","Toss the peppers, onion, cherry tomatoes, garlic and thyme with 2 tbsp oil, salt and pepper in a large roasting dish.","Roast for 15 min, until the peppers are soft and blistered and the tomatoes have burst.","Squash the garlic and tomatoes with a fork to make a rough sauce and discard the thyme stalks.","Add the gnocchi straight from the pack with the remaining oil and a splash of water, toss well and roast for 10 min, until the gnocchi are tender.","Scatter over the mozzarella and parmesan and bake for 5 min more, until the cheese is melted and golden in places.","Serve topped with basil."]'::jsonb,
    array['italian', 'vegetarian', 'oven', 'comfort']::text[], 'italian', 886, 34.4,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Gnocchis aux poivrons rôtis et mozzarella","steps":["Préchauffer le four à 220 °C.","Mélanger les poivrons, l''oignon, les tomates cerises, l''ail et le thym avec 2 c. à soupe d''huile, du sel et du poivre dans un grand plat à rôtir.","Rôtir 15 min, jusqu''à ce que les poivrons soient fondants et cloqués et les tomates éclatées.","Écraser l''ail et les tomates à la fourchette pour obtenir une sauce rustique et retirer les tiges de thym.","Ajouter les gnocchis directement du paquet avec le reste d''huile et un peu d''eau, bien mélanger et rôtir 10 min, jusqu''à ce que les gnocchis soient tendres.","Parsemer de mozzarella et de parmesan et enfourner encore 5 min, jusqu''à ce que le fromage soit fondu et doré par endroits.","Servir parsemé de basilic."]},"it":{"title":"Gnocchi al forno con peperoni arrosto e mozzarella","steps":["Scaldare il forno a 220 °C.","Condire peperoni, cipolla, pomodorini, aglio e timo con 2 cucchiai d''olio, sale e pepe in una teglia grande.","Arrostire per 15 min, finché i peperoni sono morbidi e abbrustoliti e i pomodorini scoppiati.","Schiacciare l''aglio e i pomodorini con una forchetta per ottenere un sugo rustico ed eliminare i rametti di timo.","Aggiungere gli gnocchi direttamente dalla confezione con l''olio rimasto e un goccio d''acqua, mescolare bene e arrostire 10 min, finché gli gnocchi sono morbidi.","Distribuire la mozzarella e il parmigiano e infornare ancora 5 min, finché il formaggio è fuso e dorato qua e là.","Servire con il basilico."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8ffa559e-9ee1-4db0-b46c-a4956b1290be')
  returning id
)
