-- Orzotto ai funghi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '44542c57-7489-4eeb-ba0c-2a8923c197a8'::uuid, null, 'Orzotto ai funghi', 'seed', null, 'Claude', '/recipe-photos/orzotto-ai-funghi.webp', '/recipe-photos/orzotto-ai-funghi.webp',
    2, null, 50, 10, 40, '["Bring the stock to a gentle simmer in a saucepan and keep it hot.","In a wide pan, fry the mushrooms in the oil with the garlic and rosemary over high heat for 6–8 min, until golden; season, then set a third aside for the top and discard the garlic and rosemary.","Add half the butter and the shallot to the pan and soften over medium heat for 3 min.","Add the barley and toast it for 2 min, stirring, then pour in the wine and let it evaporate.","Add the hot stock a ladle at a time, stirring often and waiting until each is mostly absorbed, for 30–35 min, until the barley is tender but still has a little bite.","Off the heat, stir in the rest of the butter and the parmesan and rest for 1 min; it should be creamy and loose.","Serve topped with the reserved mushrooms, parsley and black pepper."]'::jsonb,
    array['italian', 'vegetarian', 'risotto', 'comfort', 'autumn']::text[], 'italian', 576, 19.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Orzotto aux champignons","steps":["Porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire sauter les champignons dans l''huile avec l''ail et le romarin à feu vif 6 à 8 min, jusqu''à ce qu''ils soient dorés ; assaisonner, réserver un tiers pour le dessus et retirer l''ail et le romarin.","Ajouter la moitié du beurre et l''échalote dans la sauteuse et faire fondre à feu moyen 3 min.","Ajouter l''orge et la nacrer 2 min en remuant, puis verser le vin et le laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant souvent et en attendant qu''il soit presque absorbé, pendant 30 à 35 min, jusqu''à ce que l''orge soit tendre mais encore légèrement ferme.","Hors du feu, incorporer le reste du beurre et le parmesan et laisser reposer 1 min ; l''orzotto doit être crémeux et souple.","Servir garni des champignons réservés, de persil et de poivre."]},"it":{"title":"Orzotto ai funghi","steps":["Portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga saltare i funghi nell''olio con l''aglio e il rosmarino a fuoco vivo per 6-8 min, finché sono dorati; salare, tenerne da parte un terzo per guarnire ed eliminare aglio e rosmarino.","Aggiungere metà del burro e lo scalogno nella padella e appassire a fuoco medio per 3 min.","Unire l''orzo e tostarlo 2 min mescolando, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando spesso e aspettando che sia quasi assorbito, per 30-35 min, finché l''orzo è tenero ma ancora leggermente al dente.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano e lasciare riposare 1 min; deve risultare cremoso e morbido.","Servire con i funghi tenuti da parte, il prezzemolo e pepe nero."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '44542c57-7489-4eeb-ba0c-2a8923c197a8')
  returning id
)
