-- Spinach and ricotta stuffed pasta shells
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '24abeaf1-16d2-4545-92bb-0c275f122522'::uuid, null, 'Spinach and ricotta stuffed pasta shells', 'seed', null, 'Claude', '/recipe-photos/spinach-and-ricotta-stuffed-pasta-shells.webp', '/recipe-photos/spinach-and-ricotta-stuffed-pasta-shells.webp',
    2, null, 55, 25, 30, '["Heat the oven to 200°C.","Wilt the spinach in a large pot with a splash of water for 2–3 min, drain, cool, squeeze dry and chop finely.","Mix the spinach with the ricotta, the egg, two thirds of the parmesan, a grating of nutmeg, salt and pepper.","Refill the pot with salted water and cook the shells for half the packet time (about 6 min); drain, rinse under cold water and toss with a little oil.","Mix the passata with the garlic, the rest of the oil, salt and the basil and spread it over the base of a baking dish.","Fill each shell with a heaped spoonful of the ricotta mixture and sit them side by side in the sauce.","Scatter over the remaining parmesan, bake for 20 min, until golden on top and the sauce is bubbling."]'::jsonb,
    array['italian', 'vegetarian', 'oven', 'comfort', 'make ahead']::text[], 'italian', 676, 37.1,
    false, 'en', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Conchiglioni farcis aux épinards et à la ricotta","steps":["Préchauffer le four à 200 °C.","Faire tomber les épinards dans une grande casserole avec un peu d''eau 2 à 3 min, les égoutter, les laisser refroidir, les presser et les hacher finement.","Mélanger les épinards avec la ricotta, l''œuf, les deux tiers du parmesan, un peu de muscade, du sel et du poivre.","Remplir à nouveau la casserole d''eau salée et cuire les conchiglioni la moitié du temps indiqué (environ 6 min) ; les égoutter, les passer sous l''eau froide et les huiler légèrement.","Mélanger le coulis de tomate avec l''ail, le reste de l''huile, du sel et le basilic et l''étaler au fond d''un plat à gratin.","Garnir chaque coquille d''une bonne cuillerée de farce et les disposer côte à côte dans la sauce.","Parsemer du reste de parmesan, enfourner 20 min, jusqu''à ce que le dessus soit doré et la sauce bouillonnante."]},"it":{"title":"Conchiglioni ripieni di ricotta e spinaci","steps":["Scaldare il forno a 200 °C.","Far appassire gli spinaci in una pentola capiente con un goccio d''acqua per 2-3 min, scolarli, lasciarli raffreddare, strizzarli e tritarli finemente.","Mescolare gli spinaci con la ricotta, l''uovo, due terzi del parmigiano, una grattata di noce moscata, sale e pepe.","Riempire di nuovo la pentola con acqua salata e cuocere i conchiglioni per metà del tempo indicato (circa 6 min); scolarli, passarli sotto l''acqua fredda e ungerli con un filo d''olio.","Mescolare la passata con l''aglio, l''olio rimasto, sale e il basilico e stenderla sul fondo di una pirofila.","Farcire ogni conchiglione con una cucchiaiata abbondante di ripieno e sistemarli vicini nel sugo.","Cospargere con il parmigiano rimasto, infornare per 20 min, finché la superficie è dorata e il sugo bolle."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '24abeaf1-16d2-4545-92bb-0c275f122522')
  returning id
)
