-- Turkey bolognese tagliatelle
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd05206b1-877d-46fa-bc31-639b46637ae4'::uuid, null, 'Turkey bolognese tagliatelle', 'seed', null, 'Claude', '/recipe-photos/turkey-bolognese-tagliatelle.webp', '/recipe-photos/turkey-bolognese-tagliatelle.webp',
    2, null, 45, 15, 30, '["Soften the carrot, onion and celery in the oil in a heavy pan over medium heat for 8 min.","Add the turkey and garlic, turn up the heat and cook for 6–8 min, breaking it up, until it loses its pink colour and starts to brown.","Stir in the tomato paste for 1 min, then pour in the wine and let it bubble until almost gone.","Add the tomatoes, milk, bay leaf, a grating of nutmeg, salt and pepper, bring to a simmer and cook gently, partly covered, for 15 min, until thick; add a splash of water if it catches.","Meanwhile cook the tagliatelle in salted boiling water until al dente, keeping a little cooking water.","Remove the bay leaf, toss the pasta with the sauce and a splash of cooking water, and serve with parmesan."]'::jsonb,
    array['italian', 'comfort', 'high protein', 'freezer-friendly']::text[], 'italian', 763, 45.2,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tagliatelle à la bolognaise de dinde","steps":["Faire revenir la carotte, l''oignon et le céleri dans l''huile dans une sauteuse à fond épais à feu moyen 8 min.","Ajouter la dinde et l''ail, monter le feu et cuire 6 à 8 min en l''émiettant, jusqu''à ce qu''elle ne soit plus rose et commence à dorer.","Incorporer le concentré de tomate 1 min, puis verser le vin et le laisser réduire presque entièrement.","Ajouter les tomates, le lait, le laurier, un peu de muscade, du sel et du poivre, porter à frémissement et cuire doucement à couvert partiel 15 min, jusqu''à ce que la sauce soit épaisse ; ajouter un peu d''eau si elle attache.","Pendant ce temps, cuire les tagliatelle al dente dans de l''eau bouillante salée en gardant un peu d''eau de cuisson.","Retirer le laurier, mélanger les pâtes avec la sauce et un peu d''eau de cuisson, et servir avec du parmesan."]},"it":{"title":"Tagliatelle al ragù di tacchino","steps":["Appassire carota, cipolla e sedano nell''olio in un tegame dal fondo spesso a fuoco medio per 8 min.","Aggiungere il tacchino e l''aglio, alzare la fiamma e cuocere 6-8 min sgranandolo, finché non è più rosa e inizia a rosolare.","Unire il concentrato per 1 min, poi sfumare con il vino e lasciarlo evaporare quasi del tutto.","Aggiungere i pomodori, il latte, l''alloro, una grattata di noce moscata, sale e pepe, portare a bollore leggero e cuocere dolcemente semicoperto per 15 min, finché il ragù è denso; aggiungere un goccio d''acqua se attacca.","Nel frattempo cuocere le tagliatelle al dente in acqua bollente salata, tenendo da parte un po'' di acqua di cottura.","Togliere l''alloro, condire la pasta con il ragù e un goccio di acqua di cottura e servire con il parmigiano."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd05206b1-877d-46fa-bc31-639b46637ae4')
  returning id
)
