-- Lemon prawn and pea risotto
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b52abd15-1267-4830-a431-c33e87f52e3d'::uuid, null, 'Lemon prawn and pea risotto', 'seed', null, 'Claude', '/recipe-photos/lemon-prawn-and-pea-risotto.webp', '/recipe-photos/lemon-prawn-and-pea-risotto.webp',
    2, null, 40, 10, 30, '["Bring the stock to a simmer in a saucepan and keep it hot.","In a wide pan, soften the shallot and garlic in the butter and 1 tbsp oil over medium heat for 4 min.","Add the rice and stir for 2 min, until the grains look translucent at the edges, then pour in the wine and let it evaporate.","Add the hot stock a ladle at a time, stirring and letting each be absorbed before the next, for about 12 min.","Stir in the peas and prawns and keep adding stock for 5–6 min more, until the prawns are pink and the rice is creamy and al dente.","Off the heat, stir in the lemon juice, the remaining oil, most of the parsley and a pinch of chili flakes; season, cover and rest for 1 min.","Serve topped with the lemon zest and the rest of the parsley."]'::jsonb,
    array['italian', 'risotto', 'high protein', 'spring']::text[], 'italian', 737, 41.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Risotto aux crevettes, petits pois et citron","steps":["Porter le fumet à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire fondre l''échalote et l''ail dans le beurre et 1 c. à soupe d''huile à feu moyen 4 min.","Ajouter le riz et remuer 2 min, jusqu''à ce que les grains deviennent translucides sur les bords, puis verser le vin et le laisser s''évaporer.","Ajouter le fumet chaud louche par louche en remuant et en le laissant absorber avant la suivante, pendant environ 12 min.","Incorporer les petits pois et les crevettes et continuer à ajouter du fumet 5 à 6 min, jusqu''à ce que les crevettes soient roses et le riz crémeux et al dente.","Hors du feu, incorporer le jus de citron, le reste d''huile, la majeure partie du persil et une pincée de piment ; assaisonner, couvrir et laisser reposer 1 min.","Servir parsemé du zeste de citron et du reste de persil."]},"it":{"title":"Risotto con gamberi, piselli e limone","steps":["Portare il fumetto a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga appassire lo scalogno e l''aglio nel burro e in 1 cucchiaio d''olio a fuoco medio per 4 min.","Unire il riso e tostarlo 2 min, finché i chicchi diventano traslucidi ai bordi, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il fumetto caldo un mestolo alla volta, mescolando e lasciandolo assorbire prima del successivo, per circa 12 min.","Unire i piselli e i gamberi e continuare ad aggiungere fumetto per altri 5-6 min, finché i gamberi sono rosa e il riso è cremoso e al dente.","Fuori dal fuoco mantecare con il succo di limone, l''olio rimasto, quasi tutto il prezzemolo e un pizzico di peperoncino; regolare di sale, coprire e lasciare riposare 1 min.","Servire con la scorza di limone e il prezzemolo rimasto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b52abd15-1267-4830-a431-c33e87f52e3d')
  returning id
)
