-- Baked gnocchi with pumpkin and blue cheese
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7f8f28eb-fb9c-48ec-9d27-6298066de40a'::uuid, null, 'Baked gnocchi with pumpkin and blue cheese', 'seed', null, 'Claude', '/recipe-photos/baked-gnocchi-with-pumpkin-and-blue-cheese.webp', '/recipe-photos/baked-gnocchi-with-pumpkin-and-blue-cheese.webp',
    2, null, 45, 15, 30, '["Heat the oven to 220°C and bring a pot of salted water to the boil.","Cook the pumpkin with the oil and sage in a large ovenproof frying pan over medium heat for 12–15 min, covered for the first 5 min, until tender; season and crush about half of it with a fork.","Push the pumpkin to one side, melt the butter in the pan, stir in the flour for 1 min, then whisk in the milk and simmer for 3 min until lightly thickened.","Add the gorgonzola and stir over low heat until melted and mixed with the pumpkin; season with pepper and a little nutmeg.","Cook the gnocchi in the boiling water until they rise to the surface, 2–3 min, then drain and fold them into the pan.","Scatter with the parmesan and walnuts and bake for 10 min, until bubbling with a golden crust; rest for 3 min before serving."]'::jsonb,
    array['italian', 'vegetarian', 'oven', 'comfort', 'gratin']::text[], 'italian', 866, 29.5,
    false, 'en', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Gnocchis gratinés au potiron et gorgonzola","steps":["Préchauffer le four à 220 °C et porter à ébullition une casserole d''eau salée.","Cuire le potiron avec l''huile et la sauge dans une grande poêle allant au four à feu moyen 12 à 15 min, à couvert les 5 premières minutes, jusqu''à ce qu''il soit tendre ; assaisonner et en écraser environ la moitié à la fourchette.","Pousser le potiron sur le côté, faire fondre le beurre dans la poêle, ajouter la farine et remuer 1 min, puis verser le lait en fouettant et laisser épaissir légèrement 3 min.","Ajouter le gorgonzola et remuer à feu doux jusqu''à ce qu''il soit fondu et mêlé au potiron ; poivrer et muscader légèrement.","Cuire les gnocchis dans l''eau bouillante jusqu''à ce qu''ils remontent à la surface, 2 à 3 min, puis les égoutter et les incorporer dans la poêle.","Parsemer de parmesan et de noix et enfourner 10 min, jusqu''à ce que le gratin bouillonne et soit doré ; laisser reposer 3 min avant de servir."]},"it":{"title":"Gnocchi gratinati con zucca e gorgonzola","steps":["Scaldare il forno a 220 °C e portare a bollore una pentola di acqua salata.","Cuocere la zucca con l''olio e la salvia in una padella grande adatta al forno a fuoco medio per 12-15 min, coperta per i primi 5 min, finché è tenera; salare, pepare e schiacciarne circa metà con una forchetta.","Spostare la zucca da un lato, sciogliere il burro nella padella, unire la farina e mescolare 1 min, poi aggiungere il latte con la frusta e cuocere 3 min finché si addensa leggermente.","Aggiungere il gorgonzola e mescolare a fuoco basso finché è fuso e amalgamato alla zucca; pepare e profumare con poca noce moscata.","Lessare gli gnocchi nell''acqua bollente finché salgono a galla, 2-3 min, poi scolarli e unirli nella padella.","Cospargere con il parmigiano e le noci e infornare per 10 min, finché bolle e si forma una crosticina dorata; lasciare riposare 3 min prima di servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7f8f28eb-fb9c-48ec-9d27-6298066de40a')
  returning id
)
