-- Chicken pesto and tomato traybake
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6c246a38-571f-4eb9-b95c-baad65375613'::uuid, null, 'Chicken pesto and tomato traybake', 'seed', null, 'Claude', '/recipe-photos/chicken-pesto-and-tomato-traybake.webp', '/recipe-photos/chicken-pesto-and-tomato-traybake.webp',
    2, null, 40, 10, 30, '["Heat the oven to 220°C (200°C fan). Toss the quartered potatoes with the oil, salt and pepper on a large baking tray and roast for 12 min.","Meanwhile, coat the chicken thighs with 2 tbsp of the pesto and a little salt and pepper.","Push the potatoes aside, add the chicken and onion wedges to the tray and roast for 12 min.","Add the cherry tomatoes and roast 6-8 min more, until the tomatoes blister and the chicken is cooked through, with clear juices.","Loosen the remaining pesto with the lemon juice and spoon it over the chicken. Scatter with basil and serve from the tray."]'::jsonb,
    array['italian', 'oven', 'high protein', 'kid-friendly', 'mediterranean']::text[], 'italian', 744, 44,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet au pesto et tomates cerises au four","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Mélanger les pommes de terre coupées en quatre avec l''huile, du sel et du poivre sur une grande plaque et rôtir 12 min.","Pendant ce temps, enrober les hauts de cuisse de poulet de 2 c. à soupe de pesto, d''un peu de sel et de poivre.","Pousser les pommes de terre sur le côté, ajouter le poulet et les quartiers d''oignon sur la plaque et rôtir 12 min.","Ajouter les tomates cerises et rôtir encore 6 à 8 min, jusqu''à ce que les tomates éclatent et que le poulet soit cuit à cœur, avec un jus clair.","Détendre le reste du pesto avec le jus de citron et le verser sur le poulet. Parsemer de basilic et servir sur la plaque."]},"it":{"title":"Teglia di pollo al pesto e pomodorini","steps":["Scaldare il forno a 220 °C (200 °C ventilato). Condire le patate tagliate in quattro con l''olio, sale e pepe su una grande teglia e arrostire 12 min.","Nel frattempo, ricoprire le sovracosce di pollo con 2 cucchiai di pesto, un po'' di sale e pepe.","Spostare le patate di lato, aggiungere il pollo e gli spicchi di cipolla nella teglia e arrostire 12 min.","Aggiungere i pomodorini e arrostire altri 6-8 min, finché i pomodorini si spaccano e il pollo è cotto all''interno, con succhi chiari.","Allungare il pesto rimasto con il succo di limone e versarlo sul pollo. Completare con il basilico e servire nella teglia."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6c246a38-571f-4eb9-b95c-baad65375613')
  returning id
)
