-- Orecchiette with broccoli and sausage
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3ee4b676-aad6-4e46-8795-8605729489d0'::uuid, null, 'Orecchiette with broccoli and sausage', 'seed', null, 'Claude', '/recipe-photos/orecchiette-with-broccoli-and-sausage.webp', '/recipe-photos/orecchiette-with-broccoli-and-sausage.webp',
    2, null, 35, 10, 25, '["Bring a large pot of salted water to the boil and cook the broccoli florets, covered, for 6-7 min until tender. Lift them out with a slotted spoon and keep the water.","Meanwhile, warm the oil in a large frying pan with the garlic, then add the crumbled sausage, rosemary, thyme and chilli and cook over medium-high heat for 6-7 min until browned.","Pour in the wine and let it bubble for 1 min until almost gone.","Add the broccoli and cook 3-4 min, crushing some of the florets with the spoon. Remove the garlic and season with pepper.","Bring the broccoli water back to the boil and cook the orecchiette until just al dente.","Transfer the pasta into the pan with a slotted spoon, add a ladle of cooking water and toss over the heat for 2 min until creamy. Serve with parmesan."]'::jsonb,
    array['italian', 'comfort', 'high protein']::text[], 'italian', 887, 34.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Orecchiette au brocoli et à la saucisse","steps":["Porter à ébullition une grande casserole d''eau salée et y cuire les fleurettes de brocoli à couvert 6 à 7 min, jusqu''à ce qu''elles soient tendres. Les retirer à l''écumoire et garder l''eau.","Pendant ce temps, chauffer l''huile dans une grande poêle avec l''ail, puis ajouter la chair à saucisse émiettée, le romarin, le thym et le piment et cuire à feu moyen-vif 6 à 7 min jusqu''à ce qu''elle soit dorée.","Verser le vin et laisser bouillonner 1 min jusqu''à ce qu''il ait presque disparu.","Ajouter le brocoli et cuire 3 à 4 min en écrasant une partie des fleurettes à la cuillère. Retirer l''ail et poivrer.","Remettre l''eau du brocoli à ébullition et y cuire les orecchiette juste al dente.","Transférer les pâtes dans la poêle à l''écumoire, ajouter une louche d''eau de cuisson et mélanger sur le feu 2 min jusqu''à ce que ce soit crémeux. Servir avec le parmesan."]},"it":{"title":"Orecchiette con broccoli e salsiccia","steps":["Portare a bollore una pentola grande di acqua salata e cuocere le cimette di broccoli, coperte, per 6-7 min finché sono tenere. Scolarle con una schiumarola e tenere l''acqua.","Nel frattempo, scaldare l''olio in una padella grande con l''aglio, poi aggiungere la salsiccia sbriciolata, il rosmarino, il timo e il peperoncino e rosolare a fuoco medio-alto 6-7 min finché è dorata.","Sfumare con il vino e lasciarlo evaporare per 1 min.","Aggiungere i broccoli e cuocere 3-4 min, schiacciando parte delle cimette con il cucchiaio. Togliere l''aglio e pepare.","Riportare a bollore l''acqua dei broccoli e cuocere le orecchiette al dente.","Trasferire la pasta nella padella con una schiumarola, aggiungere un mestolo di acqua di cottura e saltare sul fuoco per 2 min finché è cremosa. Servire con il parmigiano."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3ee4b676-aad6-4e46-8795-8605729489d0')
  returning id
)
