-- Tomato-poached cod with white beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6307f25f-d0c5-41b7-9da7-b1c9edcf87e7'::uuid, null, 'Tomato-poached cod with white beans', 'seed', null, 'Claude', '/recipe-photos/tomato-poached-cod-with-white-beans.webp', '/recipe-photos/tomato-poached-cod-with-white-beans.webp',
    2, null, 40, 10, 30, '["Soften the onion and pepper in the oil in a wide pan over medium heat for 8 min.","Add the garlic and paprika and stir for 30 s, then pour in the wine and let it bubble for 1 min.","Add the tomatoes and bay leaf, season and simmer for 10 min until the sauce thickens.","Stir in the beans and simmer 3 min.","Season the cod, nestle it into the sauce, cover and poach over low heat for 7-8 min until the fish is opaque and flakes easily.","Scatter with parsley and serve straight from the pan with crusty bread for the sauce."]'::jsonb,
    array['spanish', 'one-pot', 'stew', 'healthy', 'mediterranean']::text[], 'spanish', 659, 45,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Cabillaud poché à la tomate et aux haricots blancs","steps":["Faire revenir l''oignon et le poivron dans l''huile dans une sauteuse à feu moyen 8 min.","Ajouter l''ail et le paprika et remuer 30 s, puis verser le vin et laisser bouillonner 1 min.","Ajouter les tomates et le laurier, saler, poivrer et laisser mijoter 10 min jusqu''à ce que la sauce épaississe.","Incorporer les haricots et laisser mijoter 3 min.","Assaisonner le cabillaud, le déposer dans la sauce, couvrir et pocher à feu doux 7 à 8 min, jusqu''à ce que le poisson soit nacré et s''effeuille facilement.","Parsemer de persil et servir directement dans la sauteuse, avec du pain pour la sauce."]},"it":{"title":"Merluzzo in umido al pomodoro con fagioli bianchi","steps":["Far appassire la cipolla e il peperone nell''olio in una padella larga a fuoco medio per 8 min.","Aggiungere l''aglio e la paprika e mescolare 30 s, poi versare il vino e lasciarlo sobbollire 1 min.","Aggiungere i pomodori e l''alloro, regolare di sale e pepe e cuocere a fuoco lento 10 min finché il sugo si addensa.","Unire i fagioli e cuocere 3 min.","Condire il merluzzo, adagiarlo nel sugo, coprire e cuocere a fuoco basso 7-8 min, finché il pesce è opaco e si sfalda facilmente.","Completare con il prezzemolo e servire direttamente nella padella, con pane per il sugo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6307f25f-d0c5-41b7-9da7-b1c9edcf87e7')
  returning id
)
