-- Paprika hake with peppers and potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c47e6281-33c2-439b-ae58-28c4ee81253b'::uuid, null, 'Paprika hake with peppers and potatoes', 'seed', null, 'Claude', '/recipe-photos/paprika-hake-with-peppers-and-potatoes.webp', '/recipe-photos/paprika-hake-with-peppers-and-potatoes.webp',
    2, null, 45, 15, 30, '["Heat the oven to 220°C. Toss the potatoes, peppers and onion with 2 tbsp oil, salt and pepper in a roasting dish.","Roast for 20 min, stirring once, until the potatoes are tender and starting to colour.","Season the hake, lay it on the vegetables skin side down and roast for 8-10 min until the flesh is opaque and just flakes.","Meanwhile, fry the garlic in the remaining 2 tbsp oil in a small pan over medium-low heat for 2-3 min until pale golden.","Take the pan off the heat, stir in the paprika and then the vinegar.","Spoon the hot paprika oil over the fish, scatter with parsley and serve."]'::jsonb,
    array['spanish', 'oven', 'healthy', 'high protein', 'mediterranean']::text[], 'spanish', 658, 36.2,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Merlu au paprika, poivrons et pommes de terre","steps":["Préchauffer le four à 220 °C. Mélanger les pommes de terre, les poivrons et l''oignon avec 2 c. à soupe d''huile, du sel et du poivre dans un plat à rôtir.","Rôtir 20 min en remuant une fois, jusqu''à ce que les pommes de terre soient tendres et commencent à dorer.","Assaisonner le merlu, le poser sur les légumes côté peau dessous et rôtir 8 à 10 min, jusqu''à ce que la chair soit nacrée et s''effeuille tout juste.","Pendant ce temps, faire revenir l''ail dans les 2 c. à soupe d''huile restantes dans une petite poêle à feu moyen-doux 2 à 3 min, jusqu''à ce qu''il soit blond.","Retirer la poêle du feu, incorporer le paprika puis le vinaigre.","Napper le poisson de l''huile chaude au paprika, parsemer de persil et servir."]},"it":{"title":"Nasello alla paprika con peperoni e patate","steps":["Scaldare il forno a 220 °C. Condire le patate, i peperoni e la cipolla con 2 cucchiai d''olio, sale e pepe in una pirofila.","Arrostire 20 min, mescolando una volta, finché le patate sono tenere e iniziano a colorire.","Condire il nasello, adagiarlo sulle verdure con la pelle in basso e arrostire 8-10 min, finché la polpa è opaca e si sfalda appena.","Nel frattempo, soffriggere l''aglio nei 2 cucchiai d''olio rimasti in un padellino a fuoco medio-basso per 2-3 min, finché è appena dorato.","Togliere il padellino dal fuoco, unire la paprika e poi l''aceto.","Versare l''olio caldo alla paprika sul pesce, completare con il prezzemolo e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c47e6281-33c2-439b-ae58-28c4ee81253b')
  returning id
)
