-- Cod with crispy chickpeas and spinach
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5ad1bda9-8aca-4746-92bc-c6ea865e640e'::uuid, null, 'Cod with crispy chickpeas and spinach', 'seed', null, 'Claude', '/recipe-photos/cod-with-crispy-chickpeas-and-spinach.webp', '/recipe-photos/cod-with-crispy-chickpeas-and-spinach.webp',
    2, null, 35, 10, 25, '["Heat the oven to 220°C. Toss the well-dried chickpeas with 2 tbsp oil, the paprika, cumin and salt on a lined baking tray.","Roast the chickpeas for 15 min, shaking the tray once, until they start to crisp.","Push them to one side, add the seasoned cod, drizzle with a little oil and roast 10-12 min until the fish flakes easily and the chickpeas are crunchy.","Meanwhile, fry the garlic in the remaining oil in a large frying pan over medium heat for 1 min, add the spinach and stir 2-3 min until wilted. Season and add a squeeze of lemon.","Serve the cod on the spinach, scatter over the crispy chickpeas and add lemon wedges and crusty bread."]'::jsonb,
    array['spanish', 'oven', 'healthy', 'high protein', 'mediterranean']::text[], 'spanish', 684, 45,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Cabillaud, pois chiches croustillants et épinards","steps":["Préchauffer le four à 220 °C. Mélanger les pois chiches bien séchés avec 2 c. à soupe d''huile, le paprika, le cumin et du sel sur une plaque recouverte de papier cuisson.","Rôtir les pois chiches 15 min en secouant la plaque une fois, jusqu''à ce qu''ils commencent à croustiller.","Les pousser sur un côté, ajouter le cabillaud assaisonné, l''arroser d''un filet d''huile et rôtir 10 à 12 min, jusqu''à ce que le poisson s''effeuille facilement et que les pois chiches soient croquants.","Pendant ce temps, faire revenir l''ail dans le reste d''huile dans une grande poêle à feu moyen 1 min, ajouter les épinards et remuer 2 à 3 min jusqu''à ce qu''ils tombent. Assaisonner et ajouter un filet de citron.","Servir le cabillaud sur les épinards, parsemer de pois chiches croustillants et accompagner de quartiers de citron et de pain."]},"it":{"title":"Merluzzo con ceci croccanti e spinaci","steps":["Scaldare il forno a 220 °C. Condire i ceci ben asciugati con 2 cucchiai d''olio, la paprika, il cumino e il sale su una teglia rivestita di carta forno.","Arrostire i ceci 15 min, scuotendo la teglia una volta, finché iniziano a diventare croccanti.","Spostarli da un lato, aggiungere il merluzzo condito, irrorarlo con un filo d''olio e arrostire 10-12 min, finché il pesce si sfalda facilmente e i ceci sono croccanti.","Nel frattempo, soffriggere l''aglio nell''olio rimasto in una padella grande a fuoco medio per 1 min, aggiungere gli spinaci e mescolare 2-3 min finché appassiscono. Regolare di sale e aggiungere una spruzzata di limone.","Servire il merluzzo sugli spinaci, cospargere con i ceci croccanti e accompagnare con spicchi di limone e pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5ad1bda9-8aca-4746-92bc-c6ea865e640e')
  returning id
)
