-- Pisto manchego con huevo
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a6c31957-1d9a-4114-b952-8037f62d3528'::uuid, null, 'Pisto manchego con huevo', 'seed', null, 'Claude', '/recipe-photos/pisto-manchego-con-huevo.webp', '/recipe-photos/pisto-manchego-con-huevo.webp',
    2, null, 80, 20, 60, '["Halve the tomatoes and grate them on a box grater, discarding the skins.","Cook the onion and garlic in 3 tbsp oil in a wide pan over low heat for 12 min until soft.","Add the peppers and cook 15 min more, stirring now and then, until very tender.","Add the zucchini and cook 8 min.","Stir in the grated tomato, sugar, salt and pepper and cook over medium-low heat for 20-25 min, uncovered, until thick, jammy and no longer watery.","Make 4 hollows in the pisto, crack an egg into each, cover and cook on low for 5-6 min until the whites are set and the yolks still runny.","Serve straight from the pan with plenty of bread."]'::jsonb,
    array['spanish', 'comfort', 'budget', 'mediterranean', 'summer']::text[], 'spanish', 695, 24.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pisto manchego aux œufs","steps":["Couper les tomates en deux et les râper sur une râpe, en jetant la peau.","Faire revenir l''oignon et l''ail dans 3 c. à soupe d''huile dans une sauteuse à feu doux 12 min jusqu''à ce qu''ils soient tendres.","Ajouter les poivrons et cuire encore 15 min en remuant de temps en temps, jusqu''à ce qu''ils soient très tendres.","Ajouter la courgette et cuire 8 min.","Incorporer la tomate râpée, le sucre, du sel et du poivre et cuire à feu moyen-doux 20 à 25 min à découvert, jusqu''à ce que ce soit épais, confit et sans eau.","Creuser 4 puits dans le pisto, casser un œuf dans chacun, couvrir et cuire à feu doux 5 à 6 min jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Servir directement dans la sauteuse avec beaucoup de pain."]},"it":{"title":"Pisto manchego con uova","steps":["Tagliare i pomodori a metà e grattugiarli con una grattugia, eliminando la buccia.","Cuocere la cipolla e l''aglio in 3 cucchiai d''olio in una padella larga a fuoco basso per 12 min finché sono morbidi.","Aggiungere i peperoni e cuocere altri 15 min, mescolando ogni tanto, finché sono molto teneri.","Aggiungere la zucchina e cuocere 8 min.","Unire il pomodoro grattugiato, lo zucchero, sale e pepe e cuocere a fuoco medio-basso 20-25 min, scoperto, finché è denso, morbido e senza acqua.","Fare 4 conche nel pisto, rompere un uovo in ciascuna, coprire e cuocere a fuoco basso 5-6 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Servire direttamente nella padella con abbondante pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a6c31957-1d9a-4114-b952-8037f62d3528')
  returning id
)
