-- Menemen
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ba157b8e-c181-409e-b432-61f3f90fc64e'::uuid, null, 'Menemen', 'seed', null, 'Claude', '/recipe-photos/menemen.webp', '/recipe-photos/menemen.webp',
    2, null, 25, 10, 15, '["Heat the butter and 1 tbsp oil in a wide frying pan over medium heat. Add the pepper (and onion, if using) with a pinch of salt and cook 5 min until soft.","Add the tomatoes and Aleppo pepper, cover and cook 5-6 min, stirring once, until the tomatoes collapse into a thick sauce.","Beat the eggs lightly with salt and pepper.","Lower the heat, pour in the eggs and stir slowly with a spatula for 2-3 min, folding them into the sauce, until just set and still soft.","Scatter with feta and parsley and serve straight from the pan with the bread."]'::jsonb,
    array['turkish', 'quick', 'vegetarian', 'one-pot', 'budget']::text[], 'turkish', 619, 34.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Menemen","steps":["Faire chauffer le beurre et 1 c. à soupe d''huile dans une grande poêle à feu moyen. Ajouter le poivron (et l''oignon, si on en met) avec une pincée de sel et cuire 5 min jusqu''à ce qu''il soit tendre.","Ajouter les tomates et le piment d''Alep, couvrir et cuire 5 à 6 min en remuant une fois, jusqu''à ce que les tomates fondent en une sauce épaisse.","Battre légèrement les œufs avec du sel et du poivre.","Baisser le feu, verser les œufs et remuer lentement à la spatule 2 à 3 min en les mêlant à la sauce, jusqu''à ce qu''ils soient juste pris et encore moelleux.","Parsemer de feta et de persil et servir directement dans la poêle avec le pain."]},"it":{"title":"Menemen","steps":["Scaldare il burro e 1 cucchiaio d''olio in una padella larga a fuoco medio. Aggiungere il peperone (e la cipolla, se si usa) con un pizzico di sale e cuocere 5 min finché è morbido.","Unire i pomodori e il pepe di Aleppo, coprire e cuocere 5-6 min, mescolando una volta, finché i pomodori si disfano in un sugo denso.","Sbattere leggermente le uova con sale e pepe.","Abbassare il fuoco, versare le uova e mescolare lentamente con una spatola per 2-3 min, amalgamandole al sugo, finché sono appena rapprese e ancora morbide.","Cospargere di feta e prezzemolo e servire direttamente in padella con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ba157b8e-c181-409e-b432-61f3f90fc64e')
  returning id
)
