-- Tajine de kefta aux œufs
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5f6175e0-2fa4-486d-a240-ed5a45569174'::uuid, null, 'Tajine de kefta aux œufs', 'seed', null, 'Claude', '/recipe-photos/tajine-de-kefta-aux-oeufs.webp', '/recipe-photos/tajine-de-kefta-aux-oeufs.webp',
    2, null, 50, 20, 30, '["Mix the beef with the grated onion, half the parsley, 1 tsp cumin, 1 tsp paprika, the cinnamon, salt and pepper. Roll into small balls about 3 cm across.","Soften the chopped onion and garlic in 1 tbsp oil in a wide lidded pan (or a tagine) over medium heat, 4 min.","Add the remaining cumin and paprika, the turmeric and chilli, then the tomatoes and 100 ml water; season and simmer 8 min, until slightly thickened.","Lay the meatballs in the sauce, cover and simmer gently 12 min, turning them once.","Make 3 hollows between the meatballs and crack an egg into each. Cover and cook 5-6 min, until the whites are set and the yolks still soft.","Scatter with the rest of the parsley and the coriander and serve straight from the pan with bread."]'::jsonb,
    array['north african', 'moroccan', 'one-pot', 'comfort', 'high protein']::text[], 'north african', 738, 54.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tajine de kefta aux œufs","steps":["Mélanger le bœuf avec l''oignon râpé, la moitié du persil, 1 c. à café de cumin, 1 c. à café de paprika, la cannelle, du sel et du poivre. Former de petites boulettes d''environ 3 cm.","Faire fondre l''oignon haché et l''ail dans 1 c. à soupe d''huile dans une grande sauteuse avec couvercle (ou un tajine) à feu moyen, 4 min.","Ajouter le reste du cumin et du paprika, le curcuma et le piment, puis les tomates et 100 ml d''eau ; assaisonner et laisser mijoter 8 min, jusqu''à ce que la sauce épaississe légèrement.","Déposer les boulettes dans la sauce, couvrir et laisser mijoter doucement 12 min en les retournant une fois.","Creuser 3 puits entre les boulettes et y casser un œuf. Couvrir et cuire 5 à 6 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer du reste de persil et de coriandre et servir directement dans le plat avec du pain."]},"it":{"title":"Tajine di kefta con uova","steps":["Mescolare il manzo con la cipolla grattugiata, metà del prezzemolo, 1 cucchiaino di cumino, 1 cucchiaino di paprika, la cannella, sale e pepe. Formare piccole polpette di circa 3 cm.","Appassire la cipolla tritata e l''aglio in 1 cucchiaio d''olio in una padella larga con coperchio (o un tajine) a fuoco medio, 4 min.","Aggiungere il cumino e la paprika rimasti, la curcuma e il peperoncino, poi i pomodori e 100 ml d''acqua; salare e cuocere 8 min, finché il sugo si addensa leggermente.","Adagiare le polpette nel sugo, coprire e cuocere a fuoco dolce 12 min, girandole una volta.","Formare 3 incavi tra le polpette e rompervi un uovo ciascuno. Coprire e cuocere 5-6 min, finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere con il prezzemolo rimasto e il coriandolo e servire direttamente dalla padella con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5f6175e0-2fa4-486d-a240-ed5a45569174')
  returning id
)
