-- Merguez and roast vegetable couscous
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bbf7ab1c-0133-41c4-be33-4ff4253271c4'::uuid, null, 'Merguez and roast vegetable couscous', 'seed', null, 'Claude', '/recipe-photos/merguez-and-roast-vegetable-couscous.webp', '/recipe-photos/merguez-and-roast-vegetable-couscous.webp',
    2, null, 45, 15, 30, '["Heat the oven to 220°C. Toss the aubergine, courgette, pepper and onion on a large tray with 3 tbsp oil, the ras el hanout, salt and pepper, and spread in one layer.","Roast 12 min, then stir and lay the merguez on top.","Roast 15 min more, turning the merguez once, until they are browned and the vegetables soft and caramelised at the edges.","Meanwhile bring the stock to the boil, pour it over the couscous in a bowl with 1 tsp oil, cover and leave 5 min.","Fluff the couscous with a fork and fold in the roast vegetables with the tray juices and the lemon juice.","Serve topped with the merguez, mint and a little harissa."]'::jsonb,
    array['north african', 'oven', 'generous', 'summer']::text[], 'north african', 725, 32,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Couscous merguez et légumes rôtis","steps":["Préchauffer le four à 220 °C. Mélanger l''aubergine, la courgette, le poivron et l''oignon sur une grande plaque avec 3 c. à soupe d''huile, le ras el hanout, du sel et du poivre, et les étaler en une seule couche.","Rôtir 12 min, puis remuer et poser les merguez dessus.","Rôtir encore 15 min en retournant les merguez une fois, jusqu''à ce qu''elles soient dorées et les légumes fondants et caramélisés sur les bords.","Pendant ce temps, porter le bouillon à ébullition, le verser sur la semoule dans un saladier avec 1 c. à café d''huile, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette et y mélanger les légumes rôtis avec le jus de cuisson et le jus de citron.","Servir garni des merguez, de menthe et d''un peu de harissa."]},"it":{"title":"Cuscus con merguez e verdure arrosto","steps":["Scaldare il forno a 220 °C. Condire melanzana, zucchina, peperone e cipolla su una teglia grande con 3 cucchiai d''olio, il ras el hanout, sale e pepe, e distribuirli in un solo strato.","Arrostire 12 min, poi mescolare e adagiare sopra le merguez.","Arrostire ancora 15 min girando le merguez una volta, finché sono dorate e le verdure morbide e caramellate ai bordi.","Nel frattempo portare a bollore il brodo, versarlo sul cuscus in una ciotola con 1 cucchiaino d''olio, coprire e lasciare riposare 5 min.","Sgranare il cuscus con una forchetta e unire le verdure arrosto con il fondo di cottura e il succo di limone.","Servire con sopra le merguez, la menta e un po'' di harissa."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bbf7ab1c-0133-41c4-be33-4ff4253271c4')
  returning id
)
