-- Coconut chickpea and pumpkin curry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6bc1c089-e3e1-4387-b021-e752bd4966a1'::uuid, null, 'Coconut chickpea and pumpkin curry', 'seed', null, 'Claude', '/recipe-photos/coconut-chickpea-and-pumpkin-curry.webp', '/recipe-photos/coconut-chickpea-and-pumpkin-curry.webp',
    2, null, 45, 15, 30, '["Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Heat 2 tbsp oil in a wide pan over medium heat, add the mustard seeds and cumin and let them sizzle and pop for 30 s.","Add the onion, garlic, ginger and curry leaves and cook 5 min until the onion is soft, then the tomato, ground coriander, turmeric, chilli powder and salt, and cook 3 min until the tomato breaks down.","Add the pumpkin, chickpeas and 250 ml water, cover and simmer 15 min, until the pumpkin is tender.","Stir in the coconut milk and garam masala and simmer uncovered 3 min, until the sauce thickens slightly.","Finish with the lime juice and coriander and serve with the rice."]'::jsonb,
    array['indian', 'asian', 'curry', 'vegan', 'budget']::text[], 'indian', 841, 25.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Curry de pois chiches et potiron au lait de coco","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Chauffer 2 c. à soupe d''huile dans une grande sauteuse à feu moyen, ajouter les graines de moutarde et le cumin et les laisser grésiller et éclater 30 s.","Ajouter l''oignon, l''ail, le gingembre et les feuilles de curry et cuire 5 min jusqu''à ce que l''oignon soit tendre, puis la tomate, la coriandre moulue, le curcuma, le piment et du sel, et cuire 3 min jusqu''à ce que la tomate se défasse.","Ajouter le potiron, les pois chiches et 250 ml d''eau, couvrir et laisser mijoter 15 min, jusqu''à ce que le potiron soit tendre.","Incorporer le lait de coco et le garam masala et laisser frémir 3 min à découvert, jusqu''à ce que la sauce épaississe légèrement.","Finir avec le jus de citron vert et la coriandre et servir avec le riz."]},"it":{"title":"Curry di ceci e zucca al cocco","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare 2 cucchiai d''olio in una padella larga a fuoco medio, aggiungere i semi di senape e il cumino e lasciarli sfrigolare e scoppiettare 30 s.","Aggiungere cipolla, aglio, zenzero e foglie di curry e cuocere 5 min finché la cipolla è morbida, poi il pomodoro, il coriandolo in polvere, la curcuma, il peperoncino e il sale, e cuocere 3 min finché il pomodoro si disfa.","Aggiungere la zucca, i ceci e 250 ml d''acqua, coprire e cuocere 15 min, finché la zucca è tenera.","Unire il latte di cocco e il garam masala e cuocere scoperto 3 min, finché il sugo si addensa leggermente.","Completare con il succo di lime e il coriandolo e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6bc1c089-e3e1-4387-b021-e752bd4966a1')
  returning id
)
