-- Anda curry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '442ff452-d938-4eab-96a9-6d100a2a00df'::uuid, null, 'Anda curry', 'seed', null, 'Claude', '/recipe-photos/anda-curry.webp', '/recipe-photos/anda-curry.webp',
    2, null, 45, 15, 30, '["Boil the eggs 9 min in simmering water, cool them in cold water and peel. Prick each egg 3-4 times with a fork.","Rinse the rice, add it to the same pot with 300 ml salted water, cover and cook 12 min on low heat; rest 5 min off the heat.","Meanwhile, fry the eggs in the butter with a pinch of turmeric in a wide pan, 2-3 min, rolling them until golden and blistered. Set aside.","Heat the oil in the same pan, add the bay leaf, cinnamon and cardamom for 30 s, then the onions; cook 8 min on medium heat until golden.","Add the garlic and ginger for 1 min, then the tomatoes; cook 5 min until thick and mushy.","Stir in the chili powder, ground coriander, garam masala, the rest of the turmeric and salt; cook 2 min until the oil separates.","Pour in 250 ml water, cover and simmer 6 min until the gravy thickens.","Add the eggs and simmer 3-4 min so they take on the sauce; crumble in the fenugreek leaves, stir in the cream, scatter with coriander and serve with the rice."]'::jsonb,
    array['indian', 'asian', 'curry', 'vegetarian', 'comfort']::text[], 'indian', 844, 31.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Anda curry (curry d''œufs)","steps":["Cuire les œufs 9 min dans l''eau frémissante, les refroidir dans l''eau froide et les écaler. Piquer chaque œuf 3 ou 4 fois avec une fourchette.","Rincer le riz, le mettre dans la même casserole avec 300 ml d''eau salée, couvrir et cuire 12 min à feu doux ; laisser reposer 5 min hors du feu.","Pendant ce temps, faire dorer les œufs dans le beurre avec une pincée de curcuma dans une sauteuse, 2 à 3 min, en les roulant jusqu''à ce qu''ils soient dorés et cloqués. Réserver.","Chauffer l''huile dans la même sauteuse, ajouter le laurier, la cannelle et la cardamome 30 s, puis les oignons ; cuire 8 min à feu moyen jusqu''à ce qu''ils soient dorés.","Ajouter l''ail et le gingembre 1 min, puis les tomates ; cuire 5 min jusqu''à obtenir une sauce épaisse.","Incorporer le piment en poudre, la coriandre en poudre, le garam masala, le reste du curcuma et du sel ; cuire 2 min jusqu''à ce que l''huile se sépare.","Verser 250 ml d''eau, couvrir et laisser mijoter 6 min jusqu''à ce que la sauce épaississe.","Ajouter les œufs et laisser mijoter 3 à 4 min pour qu''ils prennent le goût de la sauce ; émietter les feuilles de fenugrec, incorporer la crème, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Anda curry (curry di uova)","steps":["Cuocere le uova 9 min in acqua che sobbolle, raffreddarle in acqua fredda e sgusciarle. Bucherellare ogni uovo 3-4 volte con una forchetta.","Sciacquare il riso, metterlo nella stessa pentola con 300 ml di acqua salata, coprire e cuocere 12 min a fuoco basso; lasciare riposare 5 min fuori dal fuoco.","Nel frattempo, rosolare le uova nel burro con un pizzico di curcuma in una padella larga, 2-3 min, girandole finché sono dorate e con qualche bolla. Tenere da parte.","Scaldare l''olio nella stessa padella, aggiungere alloro, cannella e cardamomo per 30 s, poi le cipolle; cuocere 8 min a fuoco medio finché sono dorate.","Aggiungere aglio e zenzero per 1 min, poi i pomodori; cuocere 5 min finché il sugo è denso.","Unire il peperoncino in polvere, il coriandolo macinato, il garam masala, il resto della curcuma e il sale; cuocere 2 min finché l''olio si separa.","Versare 250 ml di acqua, coprire e cuocere a fuoco lento 6 min finché il sugo si addensa.","Aggiungere le uova e cuocere 3-4 min perché prendano il sapore del sugo; sbriciolare il fieno greco, unire la panna, cospargere di coriandolo e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '442ff452-d938-4eab-96a9-6d100a2a00df')
  returning id
)
