-- Pork and cabbage stir-fry with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '24505ac8-cfec-4400-bede-ce4bae130d8a'::uuid, null, 'Pork and cabbage stir-fry with rice', 'seed', null, 'Claude', '/recipe-photos/pork-and-cabbage-stir-fry-with-rice.webp', '/recipe-photos/pork-and-cabbage-stir-fry-with-rice.webp',
    2, null, 35, 15, 20, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Toss the pork with the Shaoxing wine, 1 tsp dark soy sauce, a little of the ginger and 1 tsp cornstarch; leave 10 min.","Mix the soy sauce with the rest of the dark soy sauce and the sugar. Stir the remaining cornstarch into 1 tbsp water.","Heat 1 tbsp oil in a wok over high heat, spread the pork in one layer, leave 1 min, then stir-fry 1 min more until just cooked. Set aside.","Add the rest of the oil, the garlic and ginger and stir 20 s until fragrant.","Add the cabbage and stir-fry 3-4 min until it just turns tender but keeps some crunch.","Pour in the sauce, return the pork, add the cornstarch mix and stir 1 min until glossy. Season with salt and chili flakes and serve over the rice."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'high protein']::text[], 'chinese', 721, 40.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Sauté de porc au chou et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Mélanger le porc avec le vin de Shaoxing, 1 c. à café de sauce soja foncée, un peu de gingembre et 1 c. à café de fécule ; laisser reposer 10 min.","Mélanger la sauce soja avec le reste de la sauce soja foncée et le sucre. Délayer le reste de la fécule dans 1 c. à soupe d''eau.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif, étaler le porc en une couche, laisser 1 min, puis faire sauter encore 1 min jusqu''à ce qu''il soit juste cuit. Réserver.","Ajouter le reste de l''huile, l''ail et le gingembre et remuer 20 s jusqu''à ce qu''ils embaument.","Ajouter le chou et le faire sauter 3 à 4 min jusqu''à ce qu''il soit à peine tendre mais encore croquant.","Verser la sauce, remettre le porc, ajouter la fécule délayée et remuer 1 min jusqu''à ce que ce soit brillant. Assaisonner de sel et de piment et servir sur le riz."]},"it":{"title":"Maiale saltato con cavolo e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare il maiale con il vino di Shaoxing, 1 cucchiaino di salsa di soia scura, un po'' di zenzero e 1 cucchiaino di amido; lasciare riposare 10 min.","Mescolare la salsa di soia con il resto della salsa di soia scura e lo zucchero. Stemperare l''amido rimasto in 1 cucchiaio di acqua.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo, stendere il maiale in un solo strato, lasciarlo 1 min, poi saltarlo ancora 1 min finché è appena cotto. Tenere da parte.","Aggiungere il resto dell''olio, aglio e zenzero e mescolare 20 s finché profumano.","Aggiungere il cavolo e saltarlo 3-4 min finché è appena tenero ma ancora croccante.","Versare la salsa, rimettere il maiale, aggiungere l''amido stemperato e mescolare 1 min finché è lucido. Condire con sale e peperoncino e servire sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '24505ac8-cfec-4400-bede-ce4bae130d8a')
  returning id
)
