-- Mushroom and cabbage potstickers
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '03b4b489-6e9f-4433-8687-bbb43c7193ee'::uuid, null, 'Mushroom and cabbage potstickers', 'seed', null, 'Claude', '/recipe-photos/mushroom-and-cabbage-potstickers.webp', '/recipe-photos/mushroom-and-cabbage-potstickers.webp',
    2, null, 105, 75, 30, '["Mix the flour and salt with 120 ml warm water, knead 5 min until smooth, cover and rest 30 min.","Toss the cabbage with 0.5 tsp salt, leave 10 min, then squeeze out as much water as you can.","Fry the mushrooms and carrot in 1 tbsp oil 5-6 min until dry, add the garlic and ginger for 1 min and let cool.","Mix the tofu, cabbage, mushrooms, spring onion, 1 tbsp soy sauce, the sesame oil and cornstarch into a firm filling.","Cut the dough into 24 pieces, roll each into a thin 8 cm round and dust with cornstarch.","Put a heaped tablespoon of filling in the centre of each round, fold in half and pleat the edges to seal.","Cook in three batches: heat 1 tbsp oil in a lidded non-stick pan, fry the potstickers 3-4 min until the bases are golden, add 60 ml water, cover and steam 5-6 min until the water has gone, then uncover and crisp 1 min.","Mix the rest of the soy sauce with the black vinegar and chili flakes and serve as a dipping sauce."]'::jsonb,
    array['chinese', 'asian', 'vegetarian', 'freezer-friendly']::text[], 'chinese', 919, 32.5,
    false, 'en', 'hard', '{"pots":1,"oven":false,"special":["rolling pin"]}'::jsonb, true,
    '{"fr":{"title":"Raviolis grillés aux champignons et au chou","steps":["Mélanger la farine et le sel avec 120 ml d''eau tiède, pétrir 5 min jusqu''à obtenir une pâte lisse, couvrir et laisser reposer 30 min.","Mélanger le chou avec 0,5 c. à café de sel, laisser 10 min, puis le presser pour en extraire le plus d''eau possible.","Faire revenir les champignons et la carotte dans 1 c. à soupe d''huile 5 à 6 min jusqu''à ce qu''ils soient secs, ajouter l''ail et le gingembre 1 min et laisser refroidir.","Mélanger le tofu, le chou, les champignons, l''oignon nouveau, 1 c. à soupe de sauce soja, l''huile de sésame et la fécule pour obtenir une farce ferme.","Couper la pâte en 24 morceaux, abaisser chacun en un disque fin de 8 cm et le fariner de fécule.","Déposer une bonne cuillerée à soupe de farce au centre de chaque disque, plier en deux et plisser les bords pour souder.","Cuire en trois fois : chauffer 1 c. à soupe d''huile dans une poêle antiadhésive avec couvercle, faire dorer les raviolis 3 à 4 min, ajouter 60 ml d''eau, couvrir et cuire à la vapeur 5 à 6 min jusqu''à évaporation, puis découvrir et laisser croustiller 1 min.","Mélanger le reste de la sauce soja avec le vinaigre noir et le piment et servir comme sauce."]},"it":{"title":"Ravioli cinesi alla piastra con funghi e cavolo","steps":["Mescolare farina e sale con 120 ml di acqua tiepida, impastare 5 min fino a ottenere un impasto liscio, coprire e lasciare riposare 30 min.","Mescolare il cavolo con mezzo cucchiaino di sale, lasciare 10 min, poi strizzarlo per eliminare più acqua possibile.","Rosolare funghi e carota in 1 cucchiaio d''olio 5-6 min finché sono asciutti, aggiungere aglio e zenzero per 1 min e lasciare raffreddare.","Mescolare tofu, cavolo, funghi, cipollotto, 1 cucchiaio di salsa di soia, olio di sesamo e amido fino a ottenere un ripieno compatto.","Dividere l''impasto in 24 pezzi, stendere ciascuno in un disco sottile di 8 cm e spolverarlo di amido.","Mettere un cucchiaio abbondante di ripieno al centro di ogni disco, piegarlo a metà e pieghettare i bordi per sigillarlo.","Cuocere in tre volte: scaldare 1 cucchiaio d''olio in una padella antiaderente con coperchio, rosolare i ravioli 3-4 min finché la base è dorata, aggiungere 60 ml di acqua, coprire e cuocere al vapore 5-6 min finché l''acqua è evaporata, poi scoprire e far croccare 1 min.","Mescolare il resto della salsa di soia con l''aceto nero e il peperoncino e servire come salsa per intingere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '03b4b489-6e9f-4433-8687-bbb43c7193ee')
  returning id
)
