-- Hoisin pork and broccoli noodles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd7790ac8-391f-4ae9-92b6-2274a94cb910'::uuid, null, 'Hoisin pork and broccoli noodles', 'seed', null, 'Claude', '/recipe-photos/hoisin-pork-and-broccoli-noodles.webp', '/recipe-photos/hoisin-pork-and-broccoli-noodles.webp',
    2, null, 30, 15, 15, '["Toss the pork with 1 tbsp soy sauce and the cornstarch; leave 10 min.","Mix the hoisin with the rest of the soy sauce, the honey, vinegar, sesame oil and chili flakes.","Cook the noodles in boiling water as the packet says, adding the broccoli for the last 2 min. Keep 60 ml of the water, then drain.","Heat 1 tbsp oil in a wok over high heat and sear the pork in one layer 2-3 min, turning once, until browned and just cooked. Set aside.","Add the rest of the oil, the garlic, ginger and carrot and stir-fry 1 min.","Add the noodles, broccoli, pork, sauce and a splash of the cooking water and toss 1-2 min until glossy and hot.","Serve topped with the peanuts and spring onion."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'fakeaway', 'high protein']::text[], 'chinese', 808, 45,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Nouilles sautées au porc hoisin et brocoli","steps":["Mélanger le porc avec 1 c. à soupe de sauce soja et la fécule ; laisser reposer 10 min.","Mélanger la sauce hoisin avec le reste de la sauce soja, le miel, le vinaigre, l''huile de sésame et le piment.","Cuire les nouilles dans l''eau bouillante selon le paquet, en ajoutant le brocoli pour les 2 dernières minutes. Garder 60 ml d''eau de cuisson, puis égoutter.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif et saisir le porc en une couche 2 à 3 min, en le retournant une fois, jusqu''à ce qu''il soit doré et juste cuit. Réserver.","Ajouter le reste de l''huile, l''ail, le gingembre et la carotte et faire sauter 1 min.","Ajouter les nouilles, le brocoli, le porc, la sauce et un peu d''eau de cuisson et mélanger 1 à 2 min jusqu''à ce que ce soit brillant et chaud.","Servir parsemé de cacahuètes et d''oignon nouveau."]},"it":{"title":"Noodles saltati con maiale hoisin e broccoli","steps":["Mescolare il maiale con 1 cucchiaio di salsa di soia e l''amido; lasciare riposare 10 min.","Mescolare la salsa hoisin con il resto della salsa di soia, il miele, l''aceto, l''olio di sesamo e il peperoncino.","Cuocere i noodles in acqua bollente come indicato sulla confezione, aggiungendo i broccoli negli ultimi 2 min. Tenere da parte 60 ml di acqua di cottura, poi scolare.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo e scottare il maiale in un solo strato 2-3 min, girandolo una volta, finché è dorato e appena cotto. Tenere da parte.","Aggiungere il resto dell''olio, aglio, zenzero e carota e saltare 1 min.","Aggiungere noodles, broccoli, maiale, salsa e un goccio di acqua di cottura e saltare 1-2 min finché è tutto lucido e caldo.","Servire con arachidi e cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd7790ac8-391f-4ae9-92b6-2274a94cb910')
  returning id
)
