-- Ginger salmon with pak choi and noodles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '261d4acf-50fc-4e1b-be3f-9558751ad743'::uuid, null, 'Ginger salmon with pak choi and noodles', 'seed', null, 'Claude', '/recipe-photos/ginger-salmon-with-pak-choi-and-noodles.webp', '/recipe-photos/ginger-salmon-with-pak-choi-and-noodles.webp',
    2, null, 60, 10, 20, '["Mix the soy sauce, ginger, garlic, honey, sesame oil and sriracha. Pour two-thirds over the salmon and leave in the fridge 30 min.","Heat the oven to 220°C (200°C fan).","Bake the salmon on a lined tray 12-14 min until it flakes easily.","Meanwhile, cook the noodles as the packet says, adding the pak choi for the last 2 min, and drain.","Heat the oil in the empty pot, add the spring onion, the rest of the marinade and the vinegar and bubble 1 min, then toss in the noodles and pak choi.","Serve the salmon on the noodles and scatter with sesame seeds."]'::jsonb,
    array['chinese', 'asian', 'oven', 'light', 'high protein']::text[], 'chinese', 674, 34.8,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saumon au gingembre, pak-choï et nouilles","steps":["Mélanger la sauce soja, le gingembre, l''ail, le miel, l''huile de sésame et la sriracha. En verser les deux tiers sur le saumon et laisser 30 min au réfrigérateur.","Préchauffer le four à 220 °C (200 °C chaleur tournante).","Cuire le saumon sur une plaque recouverte de papier cuisson 12 à 14 min, jusqu''à ce qu''il s''effeuille facilement.","Pendant ce temps, cuire les nouilles selon le paquet en ajoutant le pak-choï pour les 2 dernières minutes, puis égoutter.","Chauffer l''huile dans la casserole vide, ajouter l''oignon nouveau, le reste de la marinade et le vinaigre et laisser bouillonner 1 min, puis ajouter les nouilles et le pak-choï et mélanger.","Servir le saumon sur les nouilles et parsemer de graines de sésame."]},"it":{"title":"Salmone allo zenzero con pak choi e noodles","steps":["Mescolare salsa di soia, zenzero, aglio, miele, olio di sesamo e sriracha. Versarne due terzi sul salmone e lasciarlo 30 min in frigo.","Preriscaldare il forno a 220 °C (200 °C ventilato).","Cuocere il salmone su una teglia foderata 12-14 min, finché si sfalda facilmente.","Nel frattempo, cuocere i noodles come indicato sulla confezione aggiungendo il pak choi negli ultimi 2 min, poi scolare.","Scaldare l''olio nella pentola vuota, aggiungere il cipollotto, il resto della marinata e l''aceto e far bollire 1 min, poi unire noodles e pak choi e mescolare.","Servire il salmone sui noodles e cospargere di semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '261d4acf-50fc-4e1b-be3f-9558751ad743')
  returning id
)
