-- Tomato and egg stir-fry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '2e88837a-8303-4192-b86e-937e56874383'::uuid, null, 'Tomato and egg stir-fry', 'seed', null, 'Claude', '/recipe-photos/tomato-and-egg-stir-fry.webp', '/recipe-photos/tomato-and-egg-stir-fry.webp',
    2, null, 25, 8, 17, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Beat the eggs with the Shaoxing wine, a pinch of salt and pepper.","Mix the tomato paste, cornstarch and sugar with 3 tbsp water.","Heat 2 tbsp oil in a wok over medium-high heat and scramble the eggs 1-2 min until just set but still glossy. Tip them into a bowl.","Add the rest of the oil, the tomatoes and spring onion whites with a pinch of salt and cook 3 min until soft and juicy but still holding their shape.","Stir in the tomato paste mixture until it thickens, return the eggs and fold for 30 s.","Turn off the heat, drizzle with sesame oil, scatter with the spring onion greens and serve over the rice."]'::jsonb,
    array['chinese', 'asian', 'quick', 'vegetarian', 'comfort']::text[], 'chinese', 787, 28.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Œufs brouillés sautés à la tomate","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Battre les œufs avec le vin de Shaoxing, une pincée de sel et du poivre.","Mélanger le concentré de tomate, la fécule et le sucre avec 3 c. à soupe d''eau.","Chauffer 2 c. à soupe d''huile dans un wok à feu moyen-vif et brouiller les œufs 1 à 2 min jusqu''à ce qu''ils soient juste pris mais encore brillants. Les verser dans un bol.","Ajouter le reste de l''huile, les tomates et le blanc des oignons nouveaux avec une pincée de sel et cuire 3 min jusqu''à ce qu''elles soient tendres et juteuses mais encore entières.","Incorporer le mélange au concentré de tomate jusqu''à ce qu''il épaississe, remettre les œufs et mélanger délicatement 30 s.","Éteindre le feu, arroser d''huile de sésame, parsemer du vert des oignons nouveaux et servir sur le riz."]},"it":{"title":"Uova strapazzate saltate al pomodoro","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Sbattere le uova con il vino di Shaoxing, un pizzico di sale e pepe.","Mescolare concentrato di pomodoro, amido e zucchero con 3 cucchiai di acqua.","Scaldare 2 cucchiai d''olio in un wok a fuoco medio-alto e strapazzare le uova 1-2 min finché sono appena rapprese ma ancora lucide. Versarle in una ciotola.","Aggiungere il resto dell''olio, i pomodori e la parte bianca dei cipollotti con un pizzico di sale e cuocere 3 min finché sono morbidi e succosi ma ancora interi.","Unire il composto al concentrato finché si addensa, rimettere le uova e mescolare delicatamente 30 s.","Spegnere il fuoco, condire con olio di sesamo, cospargere con la parte verde dei cipollotti e servire sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '2e88837a-8303-4192-b86e-937e56874383')
  returning id
)
