-- Tsukune donburi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '85118fd3-d36c-4fb3-83b3-c39289e6bc96'::uuid, null, 'Tsukune donburi', 'seed', null, 'Claude', '/recipe-photos/tsukune-donburi.webp', '/recipe-photos/tsukune-donburi.webp',
    2, null, 35, 15, 20, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Knead the chicken, most of the spring onion, the ginger, the egg, the cornstarch and a pinch of salt by hand for 1-2 min until sticky.","With wet hands, shape 10-12 small flat patties.","Cook the broccoli in a frying pan with 3 tbsp water, covered, 3-4 min until just tender; set aside.","Heat the oil in the pan over medium heat and cook the tsukune 3-4 min per side until browned and cooked through.","Mix the soy sauce, mirin, sake and sugar, pour into the pan and let it bubble 1-2 min, turning the meatballs until glossy and glazed.","Serve the tsukune and broccoli over the rice with the pan glaze, a raw yolk on top if you like, sesame seeds, chilli and the rest of the spring onion."]'::jsonb,
    array['japanese', 'asian', 'bowl', 'comfort', 'high protein']::text[], 'japanese', 868, 50.9,
    false, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Donburi de tsukune","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Pétrir à la main le poulet haché, presque tout l''oignon nouveau, le gingembre, l''œuf, la fécule et une pincée de sel 1 à 2 min, jusqu''à ce que le mélange colle.","Les mains mouillées, former 10 à 12 petites boulettes aplaties.","Cuire le brocoli dans une poêle avec 3 c. à soupe d''eau, à couvert, 3 à 4 min jusqu''à ce qu''il soit juste tendre ; réserver.","Chauffer l''huile dans la poêle à feu moyen et cuire les tsukune 3 à 4 min par face, jusqu''à ce qu''ils soient dorés et cuits à cœur.","Mélanger la sauce soja, le mirin, le saké et le sucre, verser dans la poêle et laisser bouillonner 1 à 2 min en retournant les boulettes jusqu''à ce qu''elles soient brillantes et laquées.","Servir les tsukune et le brocoli sur le riz avec la sauce de la poêle, un jaune d''œuf cru par-dessus si on le souhaite, le sésame, le piment et le reste de l''oignon nouveau."]},"it":{"title":"Donburi di tsukune","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Impastare a mano il pollo macinato, quasi tutto il cipollotto, lo zenzero, l''uovo, l''amido e un pizzico di sale per 1-2 min finché il composto è appiccicoso.","Con le mani bagnate formare 10-12 piccole polpette appiattite.","Cuocere i broccoli in padella con 3 cucchiai d''acqua, coperti, 3-4 min finché sono appena teneri; tenerli da parte.","Scaldare l''olio nella padella a fuoco medio e cuocere gli tsukune 3-4 min per lato finché sono dorati e cotti all''interno.","Mescolare la salsa di soia, il mirin, il sake e lo zucchero, versare nella padella e far sobbollire 1-2 min girando le polpette finché sono lucide e glassate.","Servire gli tsukune e i broccoli sul riso con la glassa della padella, un tuorlo crudo sopra a piacere, sesamo, peperoncino e il cipollotto rimasto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '85118fd3-d36c-4fb3-83b3-c39289e6bc96')
  returning id
)
