-- Butaniku shōgayaki
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f2f27077-f5bc-493c-9769-5f62aefa34eb'::uuid, null, 'Butaniku shōgayaki', 'seed', null, 'Claude', '/recipe-photos/butaniku-shogayaki.webp', '/recipe-photos/butaniku-shogayaki.webp',
    2, null, 25, 8, 17, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Mix the ginger, garlic, soy sauce, mirin, sake and sugar into the sauce. Season the pork lightly with salt and pepper.","Heat the oil in a large frying pan over medium-high heat and cook the onion 2 min.","Spread the pork slices in the pan and cook 1-2 min per side until browned.","Pour in the sauce and let it bubble 1-2 min, turning the pork, until the sauce reduces and coats the meat.","Serve the pork and its sauce with a mound of raw shredded cabbage and the rice, topped with spring onion."]'::jsonb,
    array['japanese', 'asian', 'quick', 'stir-fry', 'high protein']::text[], 'japanese', 771, 34.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Butaniku shōgayaki (porc au gingembre)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Mélanger le gingembre, l''ail, la sauce soja, le mirin, le saké et le sucre pour la sauce. Saler et poivrer légèrement le porc.","Chauffer l''huile dans une grande poêle à feu moyen-vif et faire revenir l''oignon 2 min.","Étaler les tranches de porc dans la poêle et les cuire 1 à 2 min par face jusqu''à ce qu''elles soient dorées.","Verser la sauce et laisser bouillonner 1 à 2 min en retournant le porc, jusqu''à ce qu''elle réduise et nappe la viande.","Servir le porc et sa sauce avec un dôme de chou cru émincé et le riz, parsemé d''oignon nouveau."]},"it":{"title":"Butaniku shōgayaki (maiale allo zenzero)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mescolare zenzero, aglio, salsa di soia, mirin, sake e zucchero per la salsa. Salare e pepare leggermente il maiale.","Scaldare l''olio in una padella grande a fuoco medio-alto e soffriggere la cipolla 2 min.","Distendere le fette di maiale nella padella e cuocerle 1-2 min per lato finché sono dorate.","Versare la salsa e farla sobbollire 1-2 min girando il maiale, finché si riduce e avvolge la carne.","Servire il maiale con la sua salsa insieme a un mucchietto di cavolo crudo affettato e al riso, con cipollotto sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f2f27077-f5bc-493c-9769-5f62aefa34eb')
  returning id
)
