-- Cold soba with tofu and edamame
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '090b603f-91ab-4c37-8c40-93b84e835d51'::uuid, null, 'Cold soba with tofu and edamame', 'seed', null, 'Claude', '/recipe-photos/cold-soba-with-tofu-and-edamame.webp', '/recipe-photos/cold-soba-with-tofu-and-edamame.webp',
    2, null, 30, 15, 15, '["Bring 240 ml water, the dashi, soy sauce, sake and sugar to the boil in a pot and boil 1 min. Pour into a bowl and chill it (a few ice cubes speed this up).","Pat the tofu dry and fry it in the oil in a frying pan over medium-high heat, 3 min per side, until golden. Cut into strips.","Bring a large pot of water to a rolling boil, add the edamame and soba, stir, and cook for the time on the soba packet (usually 4-5 min).","Drain and rinse under cold running water, rubbing the noodles to wash off the starch, then plunge briefly into iced water and drain well.","Pile the soba and edamame on plates with the tofu and cucumber.","Serve the cold dipping sauce in small bowls with spring onion and grated daikon to stir in, and sesame seeds to sprinkle."]'::jsonb,
    array['japanese', 'asian', 'light', 'vegetarian', 'high protein', 'summer']::text[], 'japanese', 690, 42.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Soba froides au tofu et edamame","steps":["Porter 240 ml d''eau, le dashi, la sauce soja, le saké et le sucre à ébullition dans une casserole et laisser bouillir 1 min. Verser dans un bol et le mettre au frais (quelques glaçons accélèrent le refroidissement).","Sécher le tofu et le faire dorer dans l''huile dans une poêle à feu moyen-vif, 3 min par face. Le couper en lanières.","Porter une grande casserole d''eau à gros bouillons, ajouter les edamame et les soba, remuer et cuire le temps indiqué sur le paquet de soba (souvent 4 à 5 min).","Égoutter et rincer sous l''eau froide en frottant les nouilles pour enlever l''amidon, puis les plonger un instant dans de l''eau glacée et bien égoutter.","Dresser les soba et les edamame sur des assiettes avec le tofu et le concombre.","Servir la sauce froide dans de petits bols avec l''oignon nouveau et le daikon râpé à y ajouter, et le sésame à parsemer."]},"it":{"title":"Soba freddi con tofu ed edamame","steps":["Portare a bollore 240 ml d''acqua, dashi, salsa di soia, sake e zucchero in una pentola e bollire 1 min. Versare in una ciotola e farla raffreddare (qualche cubetto di ghiaccio aiuta).","Asciugare il tofu e rosolarlo nell''olio in una padella a fuoco medio-alto, 3 min per lato, finché è dorato. Tagliarlo a strisce.","Portare a bollore una pentola grande d''acqua, aggiungere edamame e soba, mescolare e cuocere per il tempo indicato sulla confezione dei soba (di solito 4-5 min).","Scolare e sciacquare sotto l''acqua fredda strofinando i noodles per eliminare l''amido, poi immergerli un attimo in acqua ghiacciata e scolarli bene.","Disporre soba ed edamame nei piatti con il tofu e il cetriolo.","Servire la salsa fredda in ciotoline con il cipollotto e il daikon grattugiato da aggiungere, e il sesamo da cospargere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '090b603f-91ab-4c37-8c40-93b84e835d51')
  returning id
)
