-- Pad Thai with prawns
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bd6e4d1a-f6e3-4a40-b674-40721b9a6a01'::uuid, null, 'Pad Thai with prawns', 'seed', null, 'Claude', '/recipe-photos/pad-thai-with-prawns.webp', '/recipe-photos/pad-thai-with-prawns.webp',
    2, null, 25, 15, 10, '["Soak the noodles in warm water for 15-20 min until pliable but still firm; drain.","Warm the sugar with 2 tbsp water until it melts, then stir in the tamarind paste and fish sauce.","Stir-fry the tofu and prawns in 1 tbsp oil in a wok over high heat, 2-3 min until the prawns turn pink. Set aside.","Add the rest of the oil and fry the garlic and shallot 30 s until fragrant.","Add the noodles and sauce and toss over high heat 1-2 min until the noodles soften and soak up the sauce.","Push the noodles aside, crack in the eggs, let them set 30 s, then return the prawns and tofu and toss everything together.","Add the bean sprouts and spring onion, toss 30 s, and serve with the peanuts, the lime in wedges and chilli flakes."]'::jsonb,
    array['thai', 'asian', 'stir-fry', 'quick', 'fakeaway', 'high protein']::text[], 'thai', 828, 55.3,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pad thaï aux crevettes","steps":["Faire tremper les nouilles 15 à 20 min dans l''eau tiède jusqu''à ce qu''elles soient souples mais encore fermes ; égoutter.","Faire fondre le sucre avec 2 c. à soupe d''eau, puis incorporer la pâte de tamarin et la sauce de poisson.","Faire sauter le tofu et les crevettes dans 1 c. à soupe d''huile dans un wok à feu vif, 2 à 3 min jusqu''à ce que les crevettes soient roses. Réserver.","Ajouter le reste de l''huile et faire revenir l''ail et l''échalote 30 s jusqu''à ce qu''ils embaument.","Ajouter les nouilles et la sauce et faire sauter à feu vif 1 à 2 min jusqu''à ce que les nouilles soient tendres et aient absorbé la sauce.","Pousser les nouilles sur le côté, casser les œufs, les laisser prendre 30 s, puis remettre les crevettes et le tofu et mélanger le tout.","Ajouter les germes de soja et l''oignon nouveau, faire sauter 30 s et servir avec les cacahuètes, le citron vert en quartiers et le piment."]},"it":{"title":"Pad thai con gamberi","steps":["Ammollare i noodles in acqua tiepida per 15-20 min finché sono flessibili ma ancora sodi; scolarli.","Sciogliere lo zucchero con 2 cucchiai d''acqua, poi unire la pasta di tamarindo e la salsa di pesce.","Saltare tofu e gamberi in 1 cucchiaio d''olio nel wok a fuoco vivo per 2-3 min finché i gamberi diventano rosa. Tenerli da parte.","Aggiungere l''olio rimasto e soffriggere aglio e scalogno per 30 s finché profumano.","Aggiungere i noodles e la salsa e saltare a fuoco vivo 1-2 min finché i noodles si ammorbidiscono e assorbono la salsa.","Spostare i noodles di lato, rompere le uova, lasciarle rapprendere 30 s, poi rimettere gamberi e tofu e mescolare tutto.","Aggiungere germogli di soia e cipollotto, saltare 30 s e servire con le arachidi, il lime a spicchi e il peperoncino."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bd6e4d1a-f6e3-4a40-b674-40721b9a6a01')
  returning id
)
