-- Prawn and avocado rice paper rolls
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b5647c45-2692-45ca-8ee6-c01a1edcf529'::uuid, null, 'Prawn and avocado rice paper rolls', 'seed', null, 'Claude', '/recipe-photos/prawn-and-avocado-rice-paper-rolls.webp', '/recipe-photos/prawn-and-avocado-rice-paper-rolls.webp',
    2, null, 30, 25, 5, '["Cook the vermicelli in boiling water for 3-4 min (or as the packet says), rinse under cold water and drain well.","Whisk the peanut butter, soy sauce, honey, juice of half the lime, chilli and 3-4 tbsp warm water into a smooth dipping sauce.","Squeeze the rest of the lime over the avocado so it does not brown.","Dip one rice paper sheet in warm water for 10-15 s until just soft and lay it on a damp tea towel.","Lay a row of prawn halves, cut side up, across the middle, then lettuce, noodles, carrot, avocado and herbs on top.","Fold the bottom over the filling, fold in the sides and roll up tightly. Repeat to make 8 rolls.","Serve straight away with the peanut sauce for dipping."]'::jsonb,
    array['vietnamese', 'asian', 'light', 'healthy', 'high protein', 'summer']::text[], 'vietnamese', 724, 52.8,
    false, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Rouleaux de printemps crevettes et avocat","steps":["Cuire les vermicelles 3 à 4 min dans l''eau bouillante (ou selon le paquet), les rincer à l''eau froide et bien les égoutter.","Fouetter le beurre de cacahuète, la sauce soja, le miel, le jus d''un demi-citron vert, le piment et 3 à 4 c. à soupe d''eau tiède pour une sauce lisse.","Arroser l''avocat du reste du citron vert pour qu''il ne noircisse pas.","Tremper une feuille de riz 10 à 15 s dans l''eau tiède jusqu''à ce qu''elle soit juste souple et la poser sur un torchon humide.","Disposer une rangée de demi-crevettes, côté coupé vers le haut, au centre, puis la salade, les vermicelles, la carotte, l''avocat et les herbes par-dessus.","Rabattre le bas sur la garniture, replier les côtés et rouler bien serré. Recommencer pour faire 8 rouleaux.","Servir aussitôt avec la sauce aux cacahuètes pour tremper."]},"it":{"title":"Involtini di carta di riso con gamberi e avocado","steps":["Cuocere i vermicelli in acqua bollente per 3-4 min (o secondo la confezione), sciacquarli in acqua fredda e scolarli bene.","Sbattere burro di arachidi, salsa di soia, miele, succo di mezzo lime, peperoncino e 3-4 cucchiai d''acqua tiepida fino a ottenere una salsa liscia.","Irrorare l''avocado con il resto del lime perché non annerisca.","Immergere un foglio di carta di riso in acqua tiepida per 10-15 s finché è appena morbido e stenderlo su un canovaccio umido.","Disporre al centro una fila di mezzi gamberi con il lato tagliato verso l''alto, poi sopra lattuga, vermicelli, carota, avocado ed erbe.","Ripiegare il lembo inferiore sul ripieno, chiudere i lati e arrotolare stretto. Ripetere per ottenere 8 involtini.","Servire subito con la salsa di arachidi per intingere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b5647c45-2692-45ca-8ee6-c01a1edcf529')
  returning id
)
