-- Massaman beef curry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '788cd98a-23e9-42b2-94d2-c323fbb2ec0b'::uuid, null, 'Massaman beef curry', 'seed', null, 'Claude', '/recipe-photos/massaman-beef-curry.webp', '/recipe-photos/massaman-beef-curry.webp',
    2, null, 155, 15, 140, '["Heat the oven to 160°C. Brown the beef in the oil in a flameproof casserole over high heat, 5 min.","Add the onion, garlic and curry paste and stir 2 min until fragrant.","Add the cinnamon, cardamom, stock and half the coconut milk, bring to a simmer, cover and braise in the oven for 1 h 15 min.","Stir in the potatoes, peanuts, the rest of the coconut milk, the fish sauce and sugar, and return to the oven uncovered for 50-60 min, until the beef is tender and the potatoes cooked.","About 20 min before the end, rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Season the curry with the juice of half the lime and more fish sauce or sugar to balance sweet, salty and sour.","Serve with the rice, coriander and the rest of the lime in wedges."]'::jsonb,
    array['thai', 'asian', 'curry', 'comfort', 'oven', 'batch cooking']::text[], 'thai', 1167, 51.9,
    false, 'en', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Curry massaman au bœuf","steps":["Préchauffer le four à 160 °C. Faire dorer le bœuf dans l''huile dans une cocotte allant au four à feu vif, 5 min.","Ajouter l''oignon, l''ail et la pâte de curry et remuer 2 min jusqu''à ce qu''ils embaument.","Ajouter la cannelle, la cardamome, le bouillon et la moitié du lait de coco, porter à frémissement, couvrir et cuire au four 1 h 15.","Ajouter les pommes de terre, les cacahuètes, le reste du lait de coco, la sauce de poisson et le sucre, et remettre au four sans couvercle 50 à 60 min, jusqu''à ce que le bœuf soit tendre et les pommes de terre cuites.","Environ 20 min avant la fin, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Assaisonner le curry avec le jus d''un demi-citron vert, et un peu de sauce de poisson ou de sucre pour équilibrer le sucré, le salé et l''acide.","Servir avec le riz, la coriandre et le reste du citron vert en quartiers."]},"it":{"title":"Curry massaman di manzo","steps":["Scaldare il forno a 160 °C. Rosolare il manzo nell''olio in una casseruola adatta al forno a fuoco vivo, 5 min.","Aggiungere cipolla, aglio e pasta di curry e mescolare 2 min finché profumano.","Aggiungere cannella, cardamomo, brodo e metà del latte di cocco, portare a sobbollire, coprire e brasare in forno per 1 h 15 min.","Unire patate, arachidi, il resto del latte di cocco, la salsa di pesce e lo zucchero e rimettere in forno scoperto per 50-60 min, finché il manzo è tenero e le patate cotte.","Circa 20 min prima della fine sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Condire il curry con il succo di mezzo lime e altra salsa di pesce o zucchero per bilanciare dolce, salato e acido.","Servire con il riso, il coriandolo e il resto del lime a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '788cd98a-23e9-42b2-94d2-c323fbb2ec0b')
  returning id
)
