-- Thai red curry with butternut and chicken
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6ea6bed6-f994-4c4e-b9dc-7e3c29d833b6'::uuid, null, 'Thai red curry with butternut and chicken', 'seed', null, 'Claude', '/recipe-photos/thai-red-curry-with-butternut-and-chicken.webp', '/recipe-photos/thai-red-curry-with-butternut-and-chicken.webp',
    2, null, 35, 10, 25, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Fry the curry paste gently in the oil in a wok for 1-2 min until it sizzles and smells fragrant.","Stir in the coconut milk and 100 ml water, bring to a simmer, add the squash and simmer 10 min until nearly tender.","Add the chicken and simmer 6-8 min until cooked through.","Add the tomatoes and cook 2 min until they begin to split.","Season with the fish sauce a little at a time and the juice of half the lime, then scatter over the Thai basil. Serve with the rice and the rest of the lime."]'::jsonb,
    array['thai', 'asian', 'curry', 'comfort', 'high protein']::text[], 'thai', 885, 39.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Curry rouge thaï au butternut et poulet","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Faire revenir doucement la pâte de curry dans l''huile dans un wok 1 à 2 min, jusqu''à ce qu''elle grésille et embaume.","Ajouter le lait de coco et 100 ml d''eau, porter à frémissement, ajouter la courge et laisser mijoter 10 min jusqu''à ce qu''elle soit presque tendre.","Ajouter le poulet et laisser mijoter 6 à 8 min jusqu''à ce qu''il soit cuit à cœur.","Ajouter les tomates et cuire 2 min jusqu''à ce qu''elles commencent à éclater.","Assaisonner avec la sauce de poisson petit à petit et le jus d''un demi-citron vert, puis parsemer de basilic thaï. Servir avec le riz et le reste du citron vert."]},"it":{"title":"Curry rosso thai con zucca butternut e pollo","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Soffriggere dolcemente la pasta di curry nell''olio in un wok per 1-2 min finché sfrigola e profuma.","Unire il latte di cocco e 100 ml d''acqua, portare a sobbollire, aggiungere la zucca e cuocere 10 min finché è quasi tenera.","Aggiungere il pollo e cuocere 6-8 min finché è cotto all''interno.","Aggiungere i pomodorini e cuocere 2 min finché iniziano a spaccarsi.","Condire con la salsa di pesce poco alla volta e il succo di mezzo lime, poi cospargere di basilico thai. Servire con il riso e il resto del lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6ea6bed6-f994-4c4e-b9dc-7e3c29d833b6')
  returning id
)
