-- Smoked haddock and sweetcorn chowder
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a3d15426-1a21-4284-8cf5-5d39c27353d5'::uuid, null, 'Smoked haddock and sweetcorn chowder', 'seed', null, 'Claude', '/recipe-photos/smoked-haddock-and-sweetcorn-chowder.webp', '/recipe-photos/smoked-haddock-and-sweetcorn-chowder.webp',
    2, null, 40, 10, 30, '["Melt the butter in a saucepan and soften the onion, celery and potato over low heat for 10 min without colouring.","Pour in the stock and milk and bring to a gentle simmer. Cook 15 min until the potato is tender; don''t let it boil hard.","Crush a few potato pieces against the side of the pan to thicken the soup.","Add the sweetcorn, lay the haddock on top and poach very gently for 5 min until it just flakes.","Break the fish into large flakes and season with pepper. Taste before adding salt, as smoked fish is salty.","Serve in bowls scattered with parsley, with crusty bread on the side."]'::jsonb,
    array['british', 'soup', 'comfort', 'one-pot', 'high protein', 'winter']::text[], 'british', 642, 52.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Chowder de haddock fumé et maïs","steps":["Faire fondre le beurre dans une casserole et faire suer l''oignon, le céleri et la pomme de terre à feu doux 10 min, sans coloration.","Verser le bouillon et le lait et porter à petits frémissements. Cuire 15 min, jusqu''à ce que la pomme de terre soit tendre, sans faire bouillir fort.","Écraser quelques morceaux de pomme de terre contre la paroi pour épaissir la soupe.","Ajouter le maïs, poser le haddock dessus et le pocher très doucement 5 min, jusqu''à ce qu''il s''effeuille.","Défaire le poisson en gros morceaux et poivrer. Goûter avant de saler, le poisson fumé est déjà salé.","Servir dans des bols, parsemé de persil, avec du pain croustillant à côté."]},"it":{"title":"Chowder di eglefino affumicato e mais","steps":["Sciogliere il burro in una pentola e stufare cipolla, sedano e patata a fuoco basso per 10 min senza farli colorire.","Versare il brodo e il latte e portare a un leggero bollore. Cuocere 15 min finché la patata è tenera, senza far bollire forte.","Schiacciare qualche pezzo di patata contro la parete della pentola per addensare la zuppa.","Aggiungere il mais, adagiare sopra l''eglefino e farlo cuocere molto dolcemente per 5 min, finché si sfalda.","Spezzare il pesce in grosse scaglie e pepare. Assaggiare prima di salare, perché il pesce affumicato è già sapido.","Servire nelle ciotole con il prezzemolo e pane croccante a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a3d15426-1a21-4284-8cf5-5d39c27353d5')
  returning id
)
