-- Sausage and root vegetable tray roast
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b76ef299-3036-48ea-94ff-e8d5f575d475'::uuid, null, 'Sausage and root vegetable tray roast', 'seed', null, 'Claude', '/recipe-photos/sausage-and-root-vegetable-tray-roast.webp', '/recipe-photos/sausage-and-root-vegetable-tray-roast.webp',
    2, null, 45, 15, 30, '["Heat the oven to 220 °C (200 °C fan) with a large baking tray inside.","Toss the parsnips, carrots, potatoes and onion with the oil, thyme, salt and pepper.","Spread them on the hot tray in one layer, tuck the sausages in among them and roast 15 min.","Turn everything and roast 10 min more.","Mix the honey and mustard, toss it over the sausages and parsnips and roast a final 5 min until sticky and the sausages are cooked through."]'::jsonb,
    array['british', 'oven', 'comfort', 'one-pot', 'autumn', 'winter']::text[], 'british', 876, 29.4,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saucisses et légumes racines rôtis à la plaque","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante) avec une grande plaque à l''intérieur.","Mélanger les panais, les carottes, les pommes de terre et l''oignon avec l''huile, le thym, le sel et le poivre.","Les étaler sur la plaque chaude en une seule couche, glisser les saucisses entre eux et rôtir 15 min.","Tout retourner et rôtir encore 10 min.","Mélanger le miel et la moutarde, en enrober les saucisses et les panais et rôtir encore 5 min, jusqu''à ce que ce soit caramélisé et que les saucisses soient cuites à cœur."]},"it":{"title":"Salsicce e ortaggi a radice in teglia","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato) con una grande teglia all''interno.","Condire pastinache, carote, patate e cipolla con l''olio, il timo, sale e pepe.","Stenderle sulla teglia calda in un solo strato, sistemare le salsicce in mezzo e arrostire 15 min.","Girare tutto e arrostire altri 10 min.","Mescolare il miele e la senape, versarli sulle salsicce e sulle pastinache e arrostire altri 5 min, finché sono glassate e le salsicce cotte all''interno."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b76ef299-3036-48ea-94ff-e8d5f575d475')
  returning id
)
