-- Lamb chops with crushed peas and potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '86ac5a18-9832-4b71-b7a5-72f531f53ddf'::uuid, null, 'Lamb chops with crushed peas and potatoes', 'seed', null, 'Claude', '/recipe-photos/lamb-chops-with-crushed-peas-and-potatoes.webp', '/recipe-photos/lamb-chops-with-crushed-peas-and-potatoes.webp',
    2, null, 50, 10, 25, '["Rub the chops with the garlic, rosemary, 1 tbsp oil and pepper. Leave 20 min at room temperature.","Boil the potatoes in salted water for 15 min until tender, adding the peas for the last 3 min.","Drain, then crush the potatoes and peas roughly with the butter, 1 tbsp oil, the mint, lemon zest and salt. Keep warm.","Season the chops with salt. Heat a frying pan over high heat and stand the chops on their fat edge for 2 min to render it.","Lay them flat and cook 3 min per side for pink. Rest 5 min.","Serve the chops on the crushed peas and potatoes with lemon wedges."]'::jsonb,
    array['british', 'high protein', 'fancy', 'spring']::text[], 'british', 871, 43.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Côtelettes d''agneau, écrasé de petits pois et pommes de terre","steps":["Frotter les côtelettes avec l''ail, le romarin, 1 c. à soupe d''huile et du poivre. Laisser 20 min à température ambiante.","Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les petits pois les 3 dernières minutes.","Égoutter, puis écraser grossièrement pommes de terre et petits pois avec le beurre, 1 c. à soupe d''huile, la menthe, le zeste de citron et du sel. Garder au chaud.","Saler les côtelettes. Chauffer une poêle à feu vif et poser les côtelettes debout sur leur gras 2 min pour le faire fondre.","Les coucher et cuire 3 min de chaque côté pour une viande rosée. Laisser reposer 5 min.","Servir les côtelettes sur l''écrasé avec des quartiers de citron."]},"it":{"title":"Costolette d''agnello con piselli e patate schiacciati","steps":["Massaggiare le costolette con l''aglio, il rosmarino, 1 cucchiaio d''olio e il pepe. Lasciarle 20 min a temperatura ambiente.","Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo i piselli negli ultimi 3 min.","Scolare, poi schiacciare grossolanamente patate e piselli con il burro, 1 cucchiaio d''olio, la menta, la scorza di limone e il sale. Tenere in caldo.","Salare le costolette. Scaldare una padella a fuoco alto e appoggiare le costolette sul lato del grasso per 2 min per farlo sciogliere.","Adagiarle di piatto e cuocere 3 min per lato per una carne rosata. Lasciarle riposare 5 min.","Servire le costolette sui piselli e patate schiacciati con spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '86ac5a18-9832-4b71-b7a5-72f531f53ddf')
  returning id
)
