-- Frikadeller with potatoes and cucumber salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '751145c3-7b69-4ccb-a0f5-a608ed92d0d8'::uuid, null, 'Frikadeller with potatoes and cucumber salad', 'seed', null, 'Claude', '/recipe-photos/frikadeller-with-potatoes-and-cucumber-salad.webp', '/recipe-photos/frikadeller-with-potatoes-and-cucumber-salad.webp',
    2, null, 45, 20, 25, '["Put the potatoes in cold salted water, bring to the boil and simmer 15-20 min until tender.","Stir the vinegar, sugar, 1 tbsp water and a pinch of salt until dissolved and toss in the cucumber; leave to steep.","Mix the pork, veal, onion, egg, flour, milk, nutmeg, 1 tsp salt and pepper until sticky and smooth. Fry a teaspoon to check the seasoning.","Shape into 8 oval patties with a wet spoon or wet hands.","Fry them in the butter and oil in a frying pan over medium heat for 10-12 min, turning halfway, until well browned and cooked through.","Drain the potatoes and toss them with a little of the pan butter and parsley. Serve with the frikadeller and the drained cucumber scattered with dill."]'::jsonb,
    array['danish', 'comfort', 'kid-friendly', 'high protein']::text[], 'danish', 812, 50.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Frikadeller, pommes de terre et salade de concombre","steps":["Mettre les pommes de terre dans de l''eau froide salée, porter à ébullition et cuire 15 à 20 min jusqu''à ce qu''elles soient tendres.","Mélanger le vinaigre, le sucre, 1 c. à soupe d''eau et une pincée de sel jusqu''à dissolution et y ajouter le concombre ; laisser mariner.","Mélanger le porc, le veau, l''oignon, l''œuf, la farine, le lait, la muscade, 1 c. à café de sel et du poivre jusqu''à obtenir une farce lisse et collante. Faire cuire une cuillerée pour goûter l''assaisonnement.","Façonner 8 boulettes ovales à l''aide d''une cuillère ou des mains mouillées.","Les faire cuire dans le beurre et l''huile dans une poêle à feu moyen 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et cuites à cœur.","Égoutter les pommes de terre et les enrober d''un peu du beurre de cuisson et de persil. Servir avec les frikadeller et le concombre égoutté parsemé d''aneth."]},"it":{"title":"Frikadeller con patate e insalata di cetrioli","steps":["Mettere le patate in acqua fredda salata, portare a bollore e cuocere 15-20 min finché sono tenere.","Mescolare l''aceto, lo zucchero, 1 cucchiaio d''acqua e un pizzico di sale finché si sciolgono e unire il cetriolo; lasciare marinare.","Impastare il maiale, il vitello, la cipolla, l''uovo, la farina, il latte, la noce moscata, 1 cucchiaino di sale e il pepe finché l''impasto è liscio e appiccicoso. Cuocerne un cucchiaino per assaggiare il sale.","Formare 8 polpette ovali con un cucchiaio o con le mani bagnate.","Cuocerle nel burro e nell''olio in una padella a fuoco medio per 10-12 min, girandole a metà, finché sono ben dorate e cotte all''interno.","Scolare le patate e condirle con un po'' del burro di cottura e il prezzemolo. Servire con le frikadeller e il cetriolo scolato cosparso di aneto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '751145c3-7b69-4ccb-a0f5-a608ed92d0d8')
  returning id
)
