-- Pea and mint omelette with potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd473cbb0-83df-4bdb-bd0c-3fac1f8b2c83'::uuid, null, 'Pea and mint omelette with potatoes', 'seed', null, 'Claude', '/recipe-photos/pea-and-mint-omelette-with-potatoes.webp', '/recipe-photos/pea-and-mint-omelette-with-potatoes.webp',
    2, null, 25, 5, 20, '["Heat the oil in a 24 cm ovenproof non-stick pan over medium heat. Add the potato slices with a pinch of salt, cover and cook 10-12 min, turning now and then, until tender and golden in places.","Add the spring onions and frozen peas and cook uncovered 2 min until the peas are thawed.","Heat the oven grill. Beat the eggs with most of the mint, salt and pepper.","Pour the eggs into the pan, scatter over the feta and cook on medium-low heat 4-5 min, drawing the edges in once or twice, until the base is set and golden.","Slide the pan under the grill for 2-3 min until the top is puffed and just set.","Scatter with the remaining mint, cut into wedges and serve."]'::jsonb,
    array['british', 'vegetarian', 'quick', 'light', 'budget', 'spring']::text[], 'british', 622, 31.9,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Omelette aux petits pois, menthe et pommes de terre","steps":["Faire chauffer l''huile dans une poêle antiadhésive de 24 cm allant au four, à feu moyen. Ajouter les rondelles de pomme de terre avec une pincée de sel, couvrir et cuire 10 à 12 min en remuant de temps en temps, jusqu''à ce qu''elles soient tendres et dorées par endroits.","Ajouter les oignons nouveaux et les petits pois surgelés et cuire 2 min à découvert jusqu''à ce que les petits pois soient décongelés.","Allumer le gril du four. Battre les œufs avec la plus grande partie de la menthe, du sel et du poivre.","Verser les œufs dans la poêle, parsemer de feta et cuire à feu moyen-doux 4 à 5 min, en ramenant les bords vers le centre une ou deux fois, jusqu''à ce que le dessous soit pris et doré.","Glisser la poêle sous le gril 2 à 3 min, jusqu''à ce que le dessus soit gonflé et juste pris.","Parsemer du reste de menthe, couper en parts et servir."]},"it":{"title":"Frittata di piselli, menta e patate","steps":["Scaldare l''olio in una padella antiaderente da 24 cm adatta al forno, a fuoco medio. Aggiungere le fette di patata con un pizzico di sale, coprire e cuocere 10-12 min, girandole ogni tanto, finché sono tenere e dorate qua e là.","Aggiungere i cipollotti e i piselli surgelati e cuocere scoperto 2 min finché i piselli sono scongelati.","Accendere il grill del forno. Sbattere le uova con gran parte della menta, sale e pepe.","Versare le uova nella padella, cospargere di feta e cuocere a fuoco medio-basso 4-5 min, riportando i bordi verso il centro una o due volte, finché il fondo è rappreso e dorato.","Passare la padella sotto il grill per 2-3 min, finché la superficie è gonfia e appena rappresa.","Cospargere con la menta rimasta, tagliare a spicchi e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd473cbb0-83df-4bdb-bd0c-3fac1f8b2c83')
  returning id
)
