-- Turkey burgers with roasted peppers and feta
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '946f92ac-6411-45df-8501-3e4e1c32c64b'::uuid, null, 'Turkey burgers with roasted peppers and feta', 'seed', null, 'Claude', '/recipe-photos/turkey-burgers-with-roasted-peppers-and-feta.webp', '/recipe-photos/turkey-burgers-with-roasted-peppers-and-feta.webp',
    2, null, 40, 15, 25, '["Heat the oven to 220°C. Toss the pepper strips with 1 tbsp oil and salt on a tray and roast 20-25 min until soft and charred at the edges.","Mix the turkey with the oregano, half the garlic, the breadcrumbs, salt and pepper, and shape into 2 patties about 2 cm thick.","Stir the yogurt with the rest of the garlic, a squeeze of lemon and a pinch of salt.","Cook the patties in the rest of the oil in a frying pan over medium heat for 5-6 min per side until cooked through (74°C in the centre, no pink).","Top the patties with the feta for the last minute and cover the pan so it softens. Toast the buns cut side down in the pan or oven.","Fill the buns with lettuce, the burgers, the roasted peppers and a spoonful of the yogurt sauce."]'::jsonb,
    array['mediterranean', 'burger', 'high protein', 'kid-friendly']::text[], 'mediterranean', 816, 53.2,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Burgers de dinde, poivrons rôtis et feta","steps":["Préchauffer le four à 220 °C. Mélanger les lanières de poivron avec 1 c. à soupe d''huile et du sel sur une plaque et rôtir 20 à 25 min, jusqu''à ce qu''elles soient tendres et grillées sur les bords.","Mélanger la dinde avec l''origan, la moitié de l''ail, la chapelure, du sel et du poivre, et façonner 2 steaks d''environ 2 cm d''épaisseur.","Mélanger le yaourt avec le reste de l''ail, un filet de citron et une pincée de sel.","Cuire les steaks dans le reste de l''huile dans une poêle à feu moyen 5 à 6 min de chaque côté, jusqu''à cuisson complète (74 °C à cœur, plus de rose).","Garnir les steaks de feta la dernière minute et couvrir la poêle pour qu''elle ramollisse. Toaster les pains côté mie dans la poêle ou au four.","Garnir les pains de salade, des steaks, des poivrons rôtis et d''une cuillerée de sauce au yaourt."]},"it":{"title":"Burger di tacchino con peperoni arrosto e feta","steps":["Scaldare il forno a 220 °C. Condire le strisce di peperone con 1 cucchiaio d''olio e sale su una teglia e arrostirle 20-25 min, finché sono morbide e abbrustolite ai bordi.","Mescolare il tacchino con l''origano, metà dell''aglio, il pangrattato, sale e pepe, e formare 2 hamburger spessi circa 2 cm.","Mescolare lo yogurt con il resto dell''aglio, una spruzzata di limone e un pizzico di sale.","Cuocere gli hamburger nel resto dell''olio in una padella a fuoco medio 5-6 min per lato, finché sono cotti (74 °C al centro, niente rosa).","Coprire gli hamburger con la feta nell''ultimo minuto e mettere il coperchio perché si ammorbidisca. Tostare i panini dal lato tagliato in padella o in forno.","Farcire i panini con lattuga, hamburger, peperoni arrosto e una cucchiaiata di salsa allo yogurt."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '946f92ac-6411-45df-8501-3e4e1c32c64b')
  returning id
)
