-- Sweet potato and feta hash with eggs
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, null, 'Sweet potato and feta hash with eggs', 'seed', null, 'Claude', '/recipe-photos/sweet-potato-and-feta-hash-with-eggs.webp', '/recipe-photos/sweet-potato-and-feta-hash-with-eggs.webp',
    2, null, 25, 8, 17, '["Heat the oil in a large lidded frying pan over medium-high heat. Add the sweet potato and onion with salt, cover and cook 8 min, stirring twice.","Uncover and cook 4-5 min more, stirring now and then, until the sweet potato is tender and browned at the edges.","Stir in the garlic, paprika and cumin for 1 min, then add the spinach and a squeeze of lemon and stir until wilted.","Make 4 wells in the hash, crack an egg into each, season and scatter the feta around.","Cover and cook on medium-low heat 4-5 min until the whites are set and the yolks still runny. Serve with chili flakes."]'::jsonb,
    array['american', 'vegetarian', 'quick', 'one-pot', 'healthy']::text[], 'american', 638, 26,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poêlée de patate douce, feta et œufs","steps":["Faire chauffer l''huile dans une grande poêle avec couvercle à feu moyen-vif. Ajouter la patate douce et l''oignon avec du sel, couvrir et cuire 8 min en remuant deux fois.","Découvrir et cuire encore 4 à 5 min en remuant de temps en temps, jusqu''à ce que la patate douce soit tendre et dorée sur les bords.","Incorporer l''ail, le paprika et le cumin 1 min, puis ajouter les épinards et un filet de citron et remuer jusqu''à ce qu''ils tombent.","Creuser 4 puits dans la poêlée, casser un œuf dans chacun, assaisonner et répartir la feta autour.","Couvrir et cuire à feu moyen-doux 4 à 5 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants. Servir avec du piment."]},"it":{"title":"Padellata di patate dolci, feta e uova","steps":["Scaldare l''olio in una padella grande con coperchio a fuoco medio-alto. Aggiungere la patata dolce e la cipolla con il sale, coprire e cuocere 8 min, mescolando due volte.","Scoprire e cuocere altri 4-5 min mescolando ogni tanto, finché la patata dolce è tenera e dorata ai bordi.","Unire l''aglio, la paprika e il cumino per 1 min, poi aggiungere gli spinaci e una spruzzata di limone e mescolare finché appassiscono.","Formare 4 incavi nella padellata, rompere un uovo in ognuno, condire e distribuire la feta intorno.","Coprire e cuocere a fuoco medio-basso 4-5 min, finché gli albumi sono rappresi e i tuorli ancora morbidi. Servire con peperoncino."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '57241a46-da29-4c3f-93d2-72bf15f30c03')
  returning id
)
