-- Kotopoulo me araka
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b7df0ef0-eeb6-4a50-95f6-c661bca1e47d'::uuid, null, 'Kotopoulo me araka', 'seed', null, 'Claude', '/recipe-photos/kotopoulo-me-araka.webp', '/recipe-photos/kotopoulo-me-araka.webp',
    2, null, 70, 15, 55, '["Season the chicken and brown it in the oil in a wide pot over medium-high heat, about 4 min a side; set aside.","Soften the onion and spring onions in the same pot for 5 min, then add the garlic for 1 min and the tomato paste for 1 min.","Add the tomatoes and 250 ml water, return the chicken, cover and simmer 20 min.","Add the potatoes and carrots with enough water to almost cover, season and simmer covered 15 min.","Add the peas and most of the dill and simmer uncovered 15 min, until the peas are soft, the potatoes tender and the sauce reduced and glossy with oil.","Rest 10 min off the heat, scatter with the remaining dill and serve warm, with feta if you like."]'::jsonb,
    array['greek', 'stew', 'one-pot', 'comfort', 'spring']::text[], 'greek', 982, 64.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet aux petits pois à la grecque (kotopoulo me araka)","steps":["Saler et poivrer le poulet et le faire dorer dans l''huile dans une grande cocotte à feu moyen-vif, environ 4 min par face ; réserver.","Faire fondre l''oignon et les oignons nouveaux dans la même cocotte 5 min, puis ajouter l''ail 1 min et le concentré de tomate 1 min.","Ajouter les tomates et 250 ml d''eau, remettre le poulet, couvrir et laisser mijoter 20 min.","Ajouter les pommes de terre et les carottes avec assez d''eau pour presque les couvrir, assaisonner et laisser mijoter 15 min à couvert.","Ajouter les petits pois et la plus grande partie de l''aneth et laisser mijoter 15 min à découvert, jusqu''à ce que les pois soient fondants, les pommes de terre tendres et la sauce réduite et brillante d''huile.","Laisser reposer 10 min hors du feu, parsemer du reste d''aneth et servir tiède, avec de la feta si on le souhaite."]},"it":{"title":"Pollo con piselli alla greca (kotopoulo me araka)","steps":["Salare e pepare il pollo e rosolarlo nell''olio in una pentola larga a fuoco medio-alto, circa 4 min per lato; mettere da parte.","Appassire la cipolla e i cipollotti nella stessa pentola per 5 min, poi aggiungere l''aglio per 1 min e il concentrato per 1 min.","Unire i pomodori e 250 ml d''acqua, rimettere il pollo, coprire e cuocere 20 min.","Aggiungere patate e carote con acqua sufficiente quasi a coprirle, salare e cuocere coperto 15 min.","Unire i piselli e quasi tutto l''aneto e cuocere scoperto 15 min, finché i piselli sono morbidi, le patate tenere e il sugo ristretto e lucido d''olio.","Far riposare 10 min fuori dal fuoco, cospargere con l''aneto rimasto e servire tiepido, con la feta se piace."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b7df0ef0-eeb6-4a50-95f6-c661bca1e47d')
  returning id
)
