-- Ispanaklı yumurta
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '10a782bb-b319-44ce-9ab0-8507659369f8'::uuid, null, 'Ispanaklı yumurta', 'seed', null, 'Claude', '/recipe-photos/ispanakli-yumurta.webp', '/recipe-photos/ispanakli-yumurta.webp',
    2, null, 25, 10, 15, '["Stir the yogurt with the garlic and a pinch of salt and set aside.","Soften the onion in the oil and half the butter in a wide lidded pan over medium heat for 5 min; add the tomato paste, cumin and half the Aleppo pepper for 1 min, then the grated tomato for 2 min.","Add the spinach by handfuls and stir until wilted, 2-3 min; season and cook off most of the liquid for 1-2 min.","Make 4 hollows, crack an egg into each, season, cover and cook over low heat 5-7 min, until the whites are set and the yolks still runny.","Melt the remaining butter in a small pan with the rest of the Aleppo pepper until it sizzles, about 30 s.","Spoon the garlic yogurt alongside, drizzle the pepper butter over the eggs and serve with bread."]'::jsonb,
    array['turkish', 'quick', 'vegetarian', 'light', 'spring']::text[], 'turkish', 631, 34.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Œufs aux épinards à la turque (ıspanaklı yumurta)","steps":["Mélanger le yaourt avec l''ail et une pincée de sel et réserver.","Faire fondre l''oignon dans l''huile et la moitié du beurre dans une grande sauteuse avec couvercle à feu moyen 5 min ; ajouter le concentré de tomate, le cumin et la moitié du piment d''Alep 1 min, puis la tomate râpée 2 min.","Ajouter les épinards par poignées et remuer jusqu''à ce qu''ils tombent, 2 à 3 min ; assaisonner et faire évaporer la plus grande partie du liquide 1 à 2 min.","Former 4 creux, casser un œuf dans chacun, assaisonner, couvrir et cuire à feu doux 5 à 7 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Faire fondre le reste du beurre dans une petite poêle avec le reste du piment d''Alep jusqu''à ce qu''il grésille, environ 30 s.","Servir le yaourt à l''ail à côté, arroser les œufs de beurre pimenté et accompagner de pain."]},"it":{"title":"Uova con spinaci alla turca (ıspanaklı yumurta)","steps":["Mescolare lo yogurt con l''aglio e un pizzico di sale e mettere da parte.","Appassire la cipolla nell''olio e metà del burro in una padella larga con coperchio a fuoco medio per 5 min; aggiungere il concentrato, il cumino e metà del pepe di Aleppo per 1 min, poi il pomodoro grattugiato per 2 min.","Aggiungere gli spinaci a manciate e mescolare finché appassiscono, 2-3 min; regolare di sale e far evaporare quasi tutto il liquido per 1-2 min.","Formare 4 incavi, rompere un uovo in ciascuno, salare, coprire e cuocere a fuoco basso 5-7 min, finché gli albumi sono rappresi e i tuorli ancora morbidi.","Sciogliere il burro rimasto in un padellino con il resto del pepe di Aleppo finché sfrigola, circa 30 s.","Servire lo yogurt all''aglio a parte, versare il burro piccante sulle uova e accompagnare con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '10a782bb-b319-44ce-9ab0-8507659369f8')
  returning id
)
