-- Méchoui-style slow-roast lamb shoulder
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '66f1f64b-259c-441a-8fe9-bef4680372ca'::uuid, null, 'Méchoui-style slow-roast lamb shoulder', 'seed', null, 'Claude', '/recipe-photos/mechoui-style-slow-roast-lamb-shoulder.webp', '/recipe-photos/mechoui-style-slow-roast-lamb-shoulder.webp',
    2, null, 225, 15, 210, '["Heat the oven to 160°C. Lightly score the fat of the lamb and rub it all over with the butter mashed with the garlic, 2 tsp cumin, the paprika, coriander and 1 tsp salt.","Set the lamb in a snug roasting dish with 150 ml water, cover tightly with foil and roast 3 h, basting with the juices every hour.","Uncover, raise the oven to 210°C and roast 25-30 min more, basting twice, until deep brown and the meat pulls easily from the bone.","Rest 10 min under loose foil.","Meanwhile mix 1 tsp cumin with 1 tsp salt for dipping, and toss the tomato, onion and parsley with the oil and a pinch of salt if making the salad.","Pull the meat off the bone with two forks, moisten with the pan juices and serve with the cumin salt, bread and salad."]'::jsonb,
    array['north african', 'moroccan', 'oven', 'generous', 'comfort']::text[], 'north african', 1088, 62.7,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Épaule d''agneau façon méchoui","steps":["Préchauffer le four à 160 °C. Inciser légèrement le gras de l''agneau et le frotter entièrement avec le beurre écrasé avec l''ail, 2 c. à café de cumin, le paprika, la coriandre et 1 c. à café de sel.","Poser l''agneau dans un plat juste à sa taille avec 150 ml d''eau, couvrir hermétiquement de papier aluminium et rôtir 3 h en arrosant de jus toutes les heures.","Découvrir, monter le four à 210 °C et rôtir encore 25 à 30 min en arrosant deux fois, jusqu''à ce que la viande soit bien brune et se détache facilement de l''os.","Laisser reposer 10 min sous une feuille d''aluminium posée sans serrer.","Pendant ce temps, mélanger 1 c. à café de cumin et 1 c. à café de sel pour tremper la viande, et mélanger la tomate, l''oignon et le persil avec l''huile et une pincée de sel si on fait la salade.","Effilocher la viande avec deux fourchettes, l''arroser du jus de cuisson et servir avec le sel au cumin, le pain et la salade."]},"it":{"title":"Spalla d''agnello al forno in stile méchoui","steps":["Scaldare il forno a 160°C. Incidere leggermente il grasso dell''agnello e massaggiarlo ovunque con il burro schiacciato con l''aglio, 2 cucchiaini di cumino, la paprika, il coriandolo e 1 cucchiaino di sale.","Mettere l''agnello in una teglia della sua misura con 150 ml d''acqua, coprire bene con alluminio e arrostire 3 h, irrorando con il fondo ogni ora.","Scoprire, alzare il forno a 210°C e arrostire ancora 25-30 min irrorando due volte, finché è ben bruno e la carne si stacca facilmente dall''osso.","Far riposare 10 min sotto un foglio di alluminio appoggiato.","Nel frattempo mescolare 1 cucchiaino di cumino con 1 cucchiaino di sale per intingere, e condire pomodoro, cipolla e prezzemolo con l''olio e un pizzico di sale se si fa l''insalata.","Sfilacciare la carne con due forchette, bagnarla con il fondo di cottura e servire con il sale al cumino, il pane e l''insalata."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '66f1f64b-259c-441a-8fe9-bef4680372ca')
  returning id
)
