-- Lablabi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c51f2da3-e80a-4036-a893-3720852ff2cb'::uuid, null, 'Lablabi', 'seed', null, 'Claude', '/recipe-photos/lablabi.webp', '/recipe-photos/lablabi.webp',
    2, null, 30, 10, 20, '["Crush the garlic with 1 tsp salt and 1.5 tsp cumin into a paste.","Warm 1 tbsp oil in a pot, fry the garlic paste 1 min, then add the chickpeas, stock and harissa and simmer 15 min; crush a few chickpeas against the side to thicken the broth a little.","Meanwhile lower the eggs into boiling water for 6 min, cool them in cold water and peel.","Put the torn bread into 2 deep bowls.","Ladle the chickpeas and broth over the bread and let it soak 1 min.","Top each bowl with an egg broken open, the capers, the tuna and parsley if using, the remaining cumin, a squeeze of lemon and the rest of the oil, with extra harissa to stir in."]'::jsonb,
    array['north african', 'soup', 'quick', 'budget', 'spicy']::text[], 'north african', 867, 43.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Lablabi (soupe tunisienne de pois chiches)","steps":["Écraser l''ail avec 1 c. à café de sel et 1,5 c. à café de cumin pour obtenir une pâte.","Chauffer 1 c. à soupe d''huile dans une casserole, faire revenir la pâte d''ail 1 min, puis ajouter les pois chiches, le bouillon et la harissa et laisser frémir 15 min ; écraser quelques pois chiches contre la paroi pour épaissir un peu le bouillon.","Pendant ce temps, plonger les œufs 6 min dans l''eau bouillante, les refroidir à l''eau froide et les écaler.","Répartir le pain déchiré dans 2 bols creux.","Verser les pois chiches et le bouillon à la louche sur le pain et laisser imbiber 1 min.","Garnir chaque bol d''un œuf ouvert, des câpres, du thon et du persil si on en met, du reste de cumin, d''un filet de citron et du reste d''huile, avec de la harissa en plus à mélanger."]},"it":{"title":"Lablabi (zuppa tunisina di ceci)","steps":["Pestare l''aglio con 1 cucchiaino di sale e 1,5 cucchiaini di cumino fino a ottenere una pasta.","Scaldare 1 cucchiaio d''olio in una pentola, soffriggere la pasta d''aglio 1 min, poi aggiungere ceci, brodo e harissa e cuocere 15 min; schiacciare qualche cece contro la parete per addensare un po'' il brodo.","Nel frattempo calare le uova in acqua bollente per 6 min, raffreddarle in acqua fredda e sgusciarle.","Mettere il pane spezzettato in 2 ciotole fonde.","Versare con il mestolo ceci e brodo sul pane e lasciarlo inzuppare 1 min.","Completare ogni ciotola con un uovo aperto, i capperi, il tonno e il prezzemolo se si usano, il cumino rimasto, una spruzzata di limone e il resto dell''olio, con altra harissa da mescolare."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c51f2da3-e80a-4036-a893-3720852ff2cb')
  returning id
)
