-- Loubia with lamb
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4ee738a3-579e-4c06-8cfa-0037f8174975'::uuid, null, 'Loubia with lamb', 'seed', null, 'Claude', '/recipe-photos/loubia-with-lamb.webp', '/recipe-photos/loubia-with-lamb.webp',
    2, null, 120, 15, 105, '["Brown the lamb in the oil in a heavy pot over medium-high heat for 5 min, then add the onion and cook 5 min more.","Stir in the garlic, tomato paste, paprika, cumin and chili powder for 1 min.","Add the tomatoes, bay leaf, 700 ml water, salt and pepper; cover and simmer gently 75 min, until the lamb is tender. (With soaked dried beans, add them now and allow 1 h 30.)","Add the canned beans and simmer uncovered 20 min, until the sauce is thick and the beans creamy.","Rest 5 min, scatter with coriander and serve with bread."]'::jsonb,
    array['north african', 'stew', 'comfort', 'one-pot', 'winter']::text[], 'north african', 984, 55.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Loubia à l''agneau","steps":["Faire dorer l''agneau dans l''huile dans une cocotte à feu moyen-vif 5 min, puis ajouter l''oignon et cuire encore 5 min.","Incorporer l''ail, le concentré de tomate, le paprika, le cumin et le piment en poudre 1 min.","Ajouter les tomates, le laurier, 700 ml d''eau, du sel et du poivre ; couvrir et laisser mijoter doucement 75 min, jusqu''à ce que l''agneau soit tendre. (Avec des haricots secs trempés, les ajouter maintenant et compter 1 h 30.)","Ajouter les haricots en conserve et laisser mijoter 20 min à découvert, jusqu''à ce que la sauce soit épaisse et les haricots crémeux.","Laisser reposer 5 min, parsemer de coriandre et servir avec du pain."]},"it":{"title":"Loubia con agnello","steps":["Rosolare l''agnello nell''olio in una casseruola pesante a fuoco medio-alto per 5 min, poi aggiungere la cipolla e cuocere altri 5 min.","Unire aglio, concentrato, paprika, cumino e peperoncino in polvere per 1 min.","Aggiungere i pomodori, l''alloro, 700 ml d''acqua, sale e pepe; coprire e cuocere dolcemente 75 min, finché l''agnello è tenero. (Con fagioli secchi ammollati, aggiungerli ora e calcolare 1 h 30.)","Unire i fagioli in scatola e cuocere scoperto 20 min, finché il sugo è denso e i fagioli cremosi.","Far riposare 5 min, cospargere di coriandolo e servire con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4ee738a3-579e-4c06-8cfa-0037f8174975')
  returning id
)
