-- Salmon, asparagus and new potato traybake
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0a6c1c2e-111e-451b-8264-41a7301d11c7'::uuid, null, 'Salmon, asparagus and new potato traybake', 'seed', null, 'Claude', '/recipe-photos/salmon-asparagus-and-new-potato-traybake.webp', '/recipe-photos/salmon-asparagus-and-new-potato-traybake.webp',
    2, null, 40, 10, 30, '["Heat the oven to 220°C. Boil the potatoes in salted water for 8 min, drain and leave to steam dry 2 min.","Toss the potatoes on a large tray with 1 tbsp oil, salt and pepper and roast 10 min.","Snap the woody ends off the asparagus and toss the spears with 1 tbsp oil, the garlic and a pinch of salt.","Push the potatoes to the sides, add the asparagus and lay the salmon on top skin-side down; season and top with the lemon slices.","Roast 12-15 min, until the salmon is opaque and just flakes and the asparagus is tender.","Mix the dill, lemon juice, mustard and remaining oil with a pinch of salt.","Spoon the dressing over the salmon and vegetables and serve straight from the tray."]'::jsonb,
    array['british', 'oven', 'healthy', 'high protein']::text[], 'british', 713, 34.9,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saumon, asperges et pommes de terre nouvelles au four","steps":["Préchauffer le four à 220 °C. Cuire les pommes de terre 8 min dans de l''eau salée, les égoutter et les laisser sécher 2 min.","Mélanger les pommes de terre sur une grande plaque avec 1 c. à soupe d''huile, du sel et du poivre et rôtir 10 min.","Casser la base ligneuse des asperges et les mélanger avec 1 c. à soupe d''huile, l''ail et une pincée de sel.","Repousser les pommes de terre sur les côtés, ajouter les asperges et poser le saumon dessus, peau dessous ; assaisonner et couvrir des rondelles de citron.","Rôtir 12 à 15 min, jusqu''à ce que le saumon soit opaque et s''effeuille tout juste et que les asperges soient tendres.","Mélanger l''aneth, le jus de citron, la moutarde et le reste d''huile avec une pincée de sel.","Napper le saumon et les légumes de cette sauce et servir directement sur la plaque."]},"it":{"title":"Teglia di salmone, asparagi e patate novelle","steps":["Scaldare il forno a 220°C. Lessare le patate in acqua salata per 8 min, scolarle e lasciarle asciugare 2 min.","Condire le patate su una teglia grande con 1 cucchiaio d''olio, sale e pepe e arrostire 10 min.","Spezzare la parte legnosa degli asparagi e condirli con 1 cucchiaio d''olio, l''aglio e un pizzico di sale.","Spostare le patate ai lati, aggiungere gli asparagi e adagiarvi il salmone con la pelle sotto; salare e coprire con le fette di limone.","Arrostire 12-15 min, finché il salmone è opaco e si sfalda appena e gli asparagi sono teneri.","Mescolare aneto, succo di limone, senape e olio rimasto con un pizzico di sale.","Versare il condimento su salmone e verdure e servire direttamente dalla teglia."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0a6c1c2e-111e-451b-8264-41a7301d11c7')
  returning id
)
