-- Cà ri gà (Vietnamese chicken curry)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '21c5d365-a70b-47b4-86f0-da46e6a9f976'::uuid, null, 'Cà ri gà (Vietnamese chicken curry)', 'seed', null, 'Claude', '/recipe-photos/ca-ri-ga-vietnamese-chicken-curry.webp', '/recipe-photos/ca-ri-ga-vietnamese-chicken-curry.webp',
    2, null, 80, 20, 30, '["Toss the chicken with 1 tbsp curry powder, 1 tbsp fish sauce, the sugar and a third of the garlic and leave 30 min.","Heat the oil in a pot over medium heat and fry the shallot, the rest of the garlic, the ginger and the lemongrass for 2 min, then stir in the rest of the curry powder for 30 seconds.","Add the chicken and brown it 5 min, turning.","Pour in the stock and coconut milk, add the carrot and sweet potato and bring to a simmer.","Simmer uncovered 20 min, until the chicken is cooked through, the vegetables are tender and the sauce has thickened a little.","Season with the rest of the fish sauce and salt and take out the lemongrass.","Serve in bowls topped with spring onion and coriander, with the baguette for dipping."]'::jsonb,
    array['vietnamese', 'asian', 'curry', 'one-pot', 'comfort']::text[], 'vietnamese', 899, 45.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Cà ri gà (curry de poulet vietnamien)","steps":["Mélanger le poulet avec 1 c. à soupe de curry, 1 c. à soupe de sauce de poisson, le sucre et un tiers de l''ail et laisser mariner 30 min.","Chauffer l''huile dans une cocotte à feu moyen et faire revenir l''échalote, le reste de l''ail, le gingembre et la citronnelle 2 min, puis ajouter le reste du curry 30 secondes.","Ajouter le poulet et le dorer 5 min en le retournant.","Verser le bouillon et le lait de coco, ajouter la carotte et la patate douce et porter à frémissement.","Laisser mijoter à découvert 20 min, jusqu''à ce que le poulet soit cuit à cœur, les légumes tendres et la sauce un peu épaissie.","Assaisonner avec le reste de sauce de poisson et du sel, puis retirer la citronnelle.","Servir dans des bols, garni d''oignon nouveau et de coriandre, avec la baguette pour saucer."]},"it":{"title":"Cà ri gà (curry di pollo vietnamita)","steps":["Condire il pollo con 1 cucchiaio di curry, 1 cucchiaio di salsa di pesce, lo zucchero e un terzo dell''aglio e lasciare marinare 30 min.","Scaldare l''olio in una pentola a fuoco medio e soffriggere scalogno, il resto dell''aglio, zenzero e citronella per 2 min, poi unire il resto del curry per 30 secondi.","Aggiungere il pollo e rosolarlo 5 min, girandolo.","Versare il brodo e il latte di cocco, aggiungere carota e patata dolce e portare a sobbollire.","Cuocere scoperto 20 min, finché il pollo è cotto, le verdure sono tenere e la salsa si è un po'' addensata.","Regolare con il resto della salsa di pesce e sale ed eliminare la citronella.","Servire nelle ciotole con cipollotto e coriandolo, accompagnando con la baguette per la scarpetta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '21c5d365-a70b-47b4-86f0-da46e6a9f976')
  returning id
)
