-- Radish, egg and smoked trout salad with new potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '1a70bffe-f24f-41c8-871e-d950aaa404e7'::uuid, null, 'Radish, egg and smoked trout salad with new potatoes', 'seed', null, 'Claude', '/recipe-photos/radish-egg-and-smoked-trout-salad-with-new-potatoes.webp', '/recipe-photos/radish-egg-and-smoked-trout-salad-with-new-potatoes.webp',
    2, null, 35, 15, 20, '["Boil the potatoes in salted water 15-18 min until tender, adding the eggs for the last 8 min.","Drain, cool the eggs in cold water, then peel and quarter them. Halve the potatoes while still warm.","Mix the crème fraîche, mustard, lemon juice, half the dill, salt and pepper into a dressing.","Toss the warm potatoes with the shallot and half the dressing.","Add the radishes, cucumber and arugula, then arrange the eggs and flaked trout on top.","Spoon over the rest of the dressing and finish with the remaining dill and the chives."]'::jsonb,
    array['danish', 'salad', 'light', 'spring']::text[], 'danish', 692, 42.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Salade de pommes de terre nouvelles, radis, œufs et truite fumée","steps":["Cuire les pommes de terre à l''eau salée 15 à 18 min jusqu''à ce qu''elles soient tendres, en ajoutant les œufs pour les 8 dernières minutes.","Égoutter, refroidir les œufs dans l''eau froide, puis les écaler et les couper en quartiers. Couper les pommes de terre en deux encore tièdes.","Mélanger la crème fraîche, la moutarde, le jus de citron, la moitié de l''aneth, du sel et du poivre pour la sauce.","Mélanger les pommes de terre tièdes avec l''échalote et la moitié de la sauce.","Ajouter les radis, le concombre et la roquette, puis disposer les œufs et la truite émiettée par-dessus.","Napper du reste de sauce et finir avec le reste d''aneth et la ciboulette."]},"it":{"title":"Insalata di patate novelle, ravanelli, uova e trota affumicata","steps":["Lessare le patate in acqua salata 15-18 min finché sono tenere, aggiungendo le uova negli ultimi 8 min.","Scolare, raffreddare le uova in acqua fredda, poi sgusciarle e tagliarle in quarti. Tagliare a metà le patate ancora tiepide.","Mescolare crème fraîche, senape, succo di limone, metà dell''aneto, sale e pepe per il condimento.","Condire le patate tiepide con lo scalogno e metà del condimento.","Aggiungere ravanelli, cetriolo e rucola, poi disporre sopra le uova e la trota sbriciolata.","Versare il resto del condimento e completare con l''aneto rimasto e l''erba cipollina."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '1a70bffe-f24f-41c8-871e-d950aaa404e7')
  returning id
)
