-- Peanut-lime chicken noodles with carrot and pepper
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '64156951-1c4e-5eff-aae3-b139edfc8c3c'::uuid, null, 'Peanut-lime chicken noodles with carrot and pepper', 'seed', null, 'Claude', '/recipe-photos/peanut-lime-chicken-noodles-with-carrot-and-pepper.webp', '/recipe-photos/peanut-lime-chicken-noodles-with-carrot-and-pepper.webp',
    2, null, 27, 15, 12, '["Cook the rice noodles in a pot of boiling water as the pack says (usually 4–6 min), drain and rinse under cold water.","Whisk the peanut butter, soy sauce, lime zest and juice, honey, sriracha, garlic and ginger with 3–4 tbsp hot water until smooth and pourable.","Heat the oil in a wok or large frying pan over high heat and stir-fry the chicken for 4–5 min until golden and cooked through.","Add the pepper and carrot and stir-fry 2 min so they stay crisp.","Add the noodles and the sauce and toss over the heat for 1 min until everything is coated; loosen with a splash of water if needed.","Serve scattered with spring onion, coriander and chopped peanuts."]'::jsonb,
    array['asian', 'stir-fry', 'high protein', 'kid-friendly']::text[], 'asian', 815, 51.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Nouilles au poulet, sauce cacahuète-citron vert, carotte et poivron","steps":["Cuire les nouilles de riz dans une casserole d''eau bouillante selon le paquet (4 à 6 min en général), égoutter et rincer à l''eau froide.","Fouetter le beurre de cacahuète, la sauce soja, le zeste et le jus de citron vert, le miel, la sriracha, l''ail et le gingembre avec 3 à 4 c. à soupe d''eau chaude jusqu''à obtenir une sauce lisse et fluide.","Chauffer l''huile dans un wok ou une grande poêle à feu vif et faire sauter le poulet 4 à 5 min jusqu''à ce qu''il soit doré et cuit.","Ajouter le poivron et la carotte et faire sauter 2 min pour qu''ils restent croquants.","Ajouter les nouilles et la sauce et mélanger sur le feu 1 min pour bien enrober ; détendre avec un peu d''eau si besoin.","Servir parsemé d''oignon nouveau, de coriandre et de cacahuètes concassées."]},"it":{"title":"Noodles di pollo al burro di arachidi e lime con carota e peperone","steps":["Cuocere i noodles di riso in una pentola d''acqua bollente come indicato sulla confezione (di solito 4–6 min), scolarli e sciacquarli in acqua fredda.","Sbattere il burro di arachidi, la salsa di soia, scorza e succo di lime, il miele, la sriracha, l''aglio e lo zenzero con 3–4 cucchiai d''acqua calda fino a ottenere una salsa liscia e fluida.","Scaldare l''olio in un wok o in una padella grande a fuoco vivo e saltare il pollo 4–5 min finché è dorato e cotto.","Aggiungere il peperone e la carota e saltare 2 min perché restino croccanti.","Unire i noodles e la salsa e mescolare sul fuoco 1 min finché tutto è ben condito; allungare con un goccio d''acqua se serve.","Servire con cipollotto, coriandolo e arachidi tritate."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '64156951-1c4e-5eff-aae3-b139edfc8c3c')
  returning id
)
