-- Air-fryer pesto chicken with crushed new potatoes and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '43b6a6ab-8a49-504d-a5d0-0bdff76e2627'::uuid, null, 'Air-fryer pesto chicken with crushed new potatoes and green beans', 'seed', null, 'Claude', '/recipe-photos/air-fryer-pesto-chicken-with-crushed-new-potatoes-and-green-beans.webp', '/recipe-photos/air-fryer-pesto-chicken-with-crushed-new-potatoes-and-green-beans.webp',
    2, null, 30, 10, 20, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer for 15 min.","Season the chicken and spread it with 2 tbsp of the pesto.","Air-fry the chicken at 200°C for 12–14 min, until it reaches 75°C in the thickest part; rest it 3 min.","Add the green beans to the potatoes for their last 4 min, then drain everything well.","Lift out the beans, then lightly crush the potatoes in the pot with the olive oil, the rest of the pesto, a squeeze of lemon, salt and pepper.","Slice the chicken and serve it with the potatoes and beans, with parmesan on top."]'::jsonb,
    array['italian', 'high protein', 'kid-friendly']::text[], 'italian', 601, 46.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet au pesto au air fryer, pommes de terre nouvelles écrasées et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min à frémissement.","Saler et poivrer le poulet et le badigeonner de 2 c. à soupe de pesto.","Cuire le poulet au air fryer à 200 °C pendant 12 à 14 min, jusqu''à 75 °C à cœur ; le laisser reposer 3 min.","Ajouter les haricots verts aux pommes de terre pour les 4 dernières minutes, puis bien égoutter le tout.","Retirer les haricots, puis écraser grossièrement les pommes de terre dans la casserole avec l''huile d''olive, le reste du pesto, un filet de citron, du sel et du poivre.","Trancher le poulet et le servir avec les pommes de terre et les haricots, parsemé de parmesan."]},"it":{"title":"Pollo al pesto in friggitrice ad aria con patate novelle schiacciate e fagiolini","steps":["Mettere le patate in una pentola d''acqua fredda salata, portare a bollore e cuocere 15 min a fuoco medio.","Salare e pepare il pollo e spalmarlo con 2 cucchiai di pesto.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–14 min, finché raggiunge 75 °C al cuore; farlo riposare 3 min.","Aggiungere i fagiolini alle patate negli ultimi 4 min, poi scolare bene tutto.","Togliere i fagiolini, poi schiacciare grossolanamente le patate nella pentola con l''olio, il resto del pesto, una spruzzata di limone, sale e pepe.","Affettare il pollo e servirlo con le patate e i fagiolini, con il parmigiano sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '43b6a6ab-8a49-504d-a5d0-0bdff76e2627')
  returning id
)
