-- Air-fryer harissa chicken with pepper and chickpea couscous
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '2ad7bb6d-b208-58bf-b258-1f95e64ea400'::uuid, null, 'Air-fryer harissa chicken with pepper and chickpea couscous', 'seed', null, 'Claude', '/recipe-photos/air-fryer-harissa-chicken-with-pepper-and-chickpea-couscous.webp', '/recipe-photos/air-fryer-harissa-chicken-with-pepper-and-chickpea-couscous.webp',
    2, null, 30, 15, 15, '["Mix the harissa with 1 tbsp of the oil, half the lemon juice and a pinch of salt, and coat the chicken; leave it while you prepare the rest.","Air-fry the chicken at 200°C for 12–15 min, turning halfway, until it reaches 75°C in the thickest part; rest it 3 min.","Meanwhile heat the rest of the oil in a deep frying pan and soften the pepper and onion for 6 min over medium heat.","Add the chickpeas and cumin and cook 1 min, then stir in the couscous and pour over the boiling stock.","Take off the heat, cover and leave 5 min, then fluff with a fork with the rest of the lemon juice and half the mint.","Slice the chicken and serve it on the couscous with the yogurt and the rest of the mint."]'::jsonb,
    array['north african', 'spicy', 'high protein', 'healthy']::text[], 'north african', 789, 54.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet à la harissa au air fryer, couscous aux poivrons et pois chiches","steps":["Mélanger la harissa avec 1 c. à soupe d''huile, la moitié du jus de citron et une pincée de sel, et en enrober le poulet ; le laisser mariner pendant la préparation du reste.","Cuire le poulet au air fryer à 200 °C pendant 12 à 15 min en le retournant à mi-cuisson, jusqu''à 75 °C à cœur ; le laisser reposer 3 min.","Pendant ce temps, chauffer le reste de l''huile dans une sauteuse et faire revenir le poivron et l''oignon 6 min à feu moyen.","Ajouter les pois chiches et le cumin et cuire 1 min, puis incorporer la semoule et verser le bouillon bouillant.","Retirer du feu, couvrir et laisser gonfler 5 min, puis égrener à la fourchette avec le reste du jus de citron et la moitié de la menthe.","Trancher le poulet et le servir sur la semoule avec le yaourt et le reste de la menthe."]},"it":{"title":"Pollo all''harissa in friggitrice ad aria con cous cous di peperoni e ceci","steps":["Mescolare l''harissa con 1 cucchiaio d''olio, metà del succo di limone e un pizzico di sale e ricoprirne il pollo; lasciarlo insaporire mentre si prepara il resto.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–15 min, girandolo a metà, finché raggiunge 75 °C al cuore; farlo riposare 3 min.","Nel frattempo scaldare il resto dell''olio in una padella fonda e far appassire peperone e cipolla per 6 min a fuoco medio.","Aggiungere i ceci e il cumino e cuocere 1 min, poi unire il cous cous e versare il brodo bollente.","Togliere dal fuoco, coprire e lasciar riposare 5 min, poi sgranare con la forchetta con il resto del succo di limone e metà della menta.","Affettare il pollo e servirlo sul cous cous con lo yogurt e il resto della menta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '2ad7bb6d-b208-58bf-b258-1f95e64ea400')
  returning id
)
