-- Miso-ginger chicken with soba and broccoli
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '733ec69d-3777-5784-86c3-674f2fc480d3'::uuid, null, 'Miso-ginger chicken with soba and broccoli', 'seed', null, 'Claude', '/recipe-photos/miso-ginger-chicken-with-soba-and-broccoli.webp', '/recipe-photos/miso-ginger-chicken-with-soba-and-broccoli.webp',
    2, null, 25, 10, 15, '["Whisk the miso, soy sauce, mirin, honey, ginger, garlic, rice vinegar and sesame oil with 3 tbsp water.","Cook the soba in a pot of boiling water for 4–5 min, adding the broccoli for the last 2 min; drain and rinse briefly under cold water.","Heat the oil in a large frying pan over medium-high heat and cook the chicken for 5–6 min until golden and cooked through.","Pour in the miso sauce and let it bubble for 1 min until it glazes the chicken.","Add the noodles and broccoli and toss for 1 min to warm through and coat.","Serve sprinkled with sesame seeds and spring onion."]'::jsonb,
    array['japanese', 'high protein', 'quick', 'healthy']::text[], 'japanese', 670, 53.2,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet miso-gingembre, nouilles soba et brocoli","steps":["Fouetter le miso, la sauce soja, le mirin, le miel, le gingembre, l''ail, le vinaigre de riz et l''huile de sésame avec 3 c. à soupe d''eau.","Cuire les soba 4 à 5 min dans une casserole d''eau bouillante en ajoutant le brocoli pour les 2 dernières minutes ; égoutter et rincer rapidement à l''eau froide.","Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire le poulet 5 à 6 min jusqu''à ce qu''il soit doré et cuit.","Verser la sauce au miso et laisser bouillonner 1 min jusqu''à ce qu''elle nappe le poulet.","Ajouter les nouilles et le brocoli et mélanger 1 min pour réchauffer et enrober.","Servir parsemé de graines de sésame et d''oignon nouveau."]},"it":{"title":"Pollo al miso e zenzero con soba e broccoli","steps":["Sbattere il miso, la salsa di soia, il mirin, il miele, lo zenzero, l''aglio, l''aceto di riso e l''olio di sesamo con 3 cucchiai d''acqua.","Cuocere la soba in una pentola d''acqua bollente per 4–5 min, aggiungendo i broccoli negli ultimi 2 min; scolare e sciacquare velocemente in acqua fredda.","Scaldare l''olio in una padella grande a fuoco medio-alto e cuocere il pollo 5–6 min finché è dorato e cotto.","Versare la salsa al miso e lasciar sobbollire 1 min finché glassa il pollo.","Unire la soba e i broccoli e mescolare 1 min per scaldare e condire.","Servire con semi di sesamo e cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '733ec69d-3777-5784-86c3-674f2fc480d3')
  returning id
)
