-- Air-fryer honey gochujang chicken thighs with rice and cucumber
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4624f1fb-2e42-5728-bc55-0198cd2918ca'::uuid, null, 'Air-fryer honey gochujang chicken thighs with rice and cucumber', 'seed', null, 'Claude', '/recipe-photos/air-fryer-honey-gochujang-chicken-thighs-with-rice-and-cucumber.webp', '/recipe-photos/air-fryer-honey-gochujang-chicken-thighs-with-rice-and-cucumber.webp',
    2, null, 28, 10, 18, '["Rinse the rice and cook it in a pot with 300 ml water: bring to the boil, cover and simmer on low for 12 min, then rest 5 min off the heat.","Mix the gochujang, honey, soy sauce, sesame oil and garlic into a glaze; toss the chicken in a third of it.","Air-fry the chicken at 200°C for 8 min, then turn it, brush with the rest of the glaze and cook 4–6 min more until sticky and 75°C inside.","Meanwhile lightly smash the cucumber with a rolling pin or the flat of a knife and break it into bite-size pieces.","Toss the cucumber with the rice vinegar, sugar, a pinch of salt and half the sesame seeds.","Slice the chicken and serve it over the rice with the cucumber, the rest of the sesame seeds and the spring onion."]'::jsonb,
    array['korean', 'asian', 'spicy', 'bowl']::text[], 'korean', 717, 38.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Hauts de cuisse de poulet miel-gochujang au air fryer, riz et concombre","steps":["Rincer le riz et le cuire dans une casserole avec 300 ml d''eau : porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer 5 min hors du feu.","Mélanger le gochujang, le miel, la sauce soja, l''huile de sésame et l''ail pour faire un glaçage ; en enrober le poulet avec un tiers.","Cuire le poulet au air fryer à 200 °C pendant 8 min, puis le retourner, le badigeonner du reste du glaçage et cuire encore 4 à 6 min jusqu''à ce qu''il soit laqué et à 75 °C à cœur.","Pendant ce temps, écraser légèrement le concombre avec un rouleau ou le plat d''un couteau et le casser en bouchées.","Mélanger le concombre avec le vinaigre de riz, le sucre, une pincée de sel et la moitié des graines de sésame.","Trancher le poulet et le servir sur le riz avec le concombre, le reste des graines de sésame et l''oignon nouveau."]},"it":{"title":"Sovracosce di pollo al miele e gochujang in friggitrice ad aria con riso e cetriolo","steps":["Sciacquare il riso e cuocerlo in una pentola con 300 ml d''acqua: portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Mescolare gochujang, miele, salsa di soia, olio di sesamo e aglio per ottenere una glassa; condire il pollo con un terzo.","Cuocere il pollo in friggitrice ad aria a 200 °C per 8 min, poi girarlo, spennellarlo con il resto della glassa e cuocere altri 4–6 min finché è laccato e a 75 °C al cuore.","Nel frattempo schiacciare leggermente il cetriolo con un mattarello o con la lama piatta di un coltello e spezzarlo a bocconi.","Condire il cetriolo con l''aceto di riso, lo zucchero, un pizzico di sale e metà dei semi di sesamo.","Affettare il pollo e servirlo sul riso con il cetriolo, il resto dei semi di sesamo e il cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4624f1fb-2e42-5728-bc55-0198cd2918ca')
  returning id
)
