-- Air-fryer chicken thighs with tahini-lemon sauce, quinoa and kale
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '079ff286-d35c-5eda-b67b-aee1962e87e9'::uuid, null, 'Air-fryer chicken thighs with tahini-lemon sauce, quinoa and kale', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chicken-thighs-with-tahini-lemon-sauce-quinoa-and-kale.webp', '/recipe-photos/air-fryer-chicken-thighs-with-tahini-lemon-sauce-quinoa-and-kale.webp',
    2, null, 28, 10, 18, '["Simmer the quinoa in a pot with 280 ml salted water, covered, for 15 min until the water is absorbed; rest 5 min.","Rub the chicken with the cumin, paprika, half the oil, salt and pepper.","Air-fry the chicken at 200°C for 12–14 min, turning halfway, until browned and 75°C inside.","Whisk the tahini with half the lemon juice, 1 grated garlic clove, a pinch of salt and 4–5 tbsp cold water until smooth and pourable.","Heat the rest of the oil in a frying pan, add the second garlic clove, sliced, and the kale with a splash of water and cook 3–4 min until tender.","Fold the kale and the rest of the lemon juice into the quinoa, top with the sliced chicken, the tahini sauce and the parsley."]'::jsonb,
    array['middle eastern', 'healthy', 'high protein', 'bowl']::text[], 'middle eastern', 836, 49.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Hauts de cuisse de poulet au air fryer, sauce tahini-citron, quinoa et chou kale","steps":["Cuire le quinoa à couvert dans une casserole avec 280 ml d''eau salée pendant 15 min, jusqu''à absorption ; laisser reposer 5 min.","Frotter le poulet avec le cumin, le paprika, la moitié de l''huile, du sel et du poivre.","Cuire le poulet au air fryer à 200 °C pendant 12 à 14 min en le retournant à mi-cuisson, jusqu''à ce qu''il soit doré et à 75 °C à cœur.","Fouetter le tahini avec la moitié du jus de citron, 1 gousse d''ail râpée, une pincée de sel et 4 à 5 c. à soupe d''eau froide jusqu''à obtenir une sauce lisse et fluide.","Chauffer le reste de l''huile dans une poêle, ajouter la seconde gousse d''ail émincée et le chou kale avec un peu d''eau et cuire 3 à 4 min jusqu''à ce qu''il soit tendre.","Incorporer le chou kale et le reste du jus de citron au quinoa, garnir du poulet tranché, de la sauce tahini et du persil."]},"it":{"title":"Sovracosce di pollo in friggitrice ad aria con salsa tahina e limone, quinoa e cavolo riccio","steps":["Cuocere la quinoa coperta in una pentola con 280 ml d''acqua salata per 15 min, finché l''acqua è assorbita; lasciarla riposare 5 min.","Massaggiare il pollo con cumino, paprika, metà dell''olio, sale e pepe.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–14 min, girandolo a metà, finché è dorato e a 75 °C al cuore.","Sbattere la tahina con metà del succo di limone, 1 spicchio d''aglio grattugiato, un pizzico di sale e 4–5 cucchiai d''acqua fredda fino a ottenere una salsa liscia e fluida.","Scaldare il resto dell''olio in una padella, aggiungere il secondo spicchio d''aglio a fettine e il cavolo con un goccio d''acqua e cuocere 3–4 min finché è tenero.","Unire il cavolo e il resto del succo di limone alla quinoa, completare con il pollo affettato, la salsa tahina e il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '079ff286-d35c-5eda-b67b-aee1962e87e9')
  returning id
)
