-- Cajun chicken wraps with sweetcorn salsa
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f006e547-e528-5078-be45-4fe999de4982'::uuid, null, 'Cajun chicken wraps with sweetcorn salsa', 'seed', null, 'Claude', '/recipe-photos/cajun-chicken-wraps-with-sweetcorn-salsa.webp', '/recipe-photos/cajun-chicken-wraps-with-sweetcorn-salsa.webp',
    2, null, 27, 15, 12, '["Toss the chicken with the Cajun seasoning and a pinch of salt.","Mix the corn, tomato, red onion, coriander and the juice of half the lime for the salsa; season with salt.","Stir the zest and remaining lime juice into the yogurt.","Heat the oil in a large frying pan over medium-high heat and cook the chicken and pepper for 8–10 min, stirring, until the chicken is charred at the edges and cooked through.","Wipe the pan and warm the tortillas in it for 20 seconds a side.","Spread each tortilla with lime yogurt, add lettuce, chicken and pepper and a spoonful of salsa, and roll up."]'::jsonb,
    array['american', 'wrap', 'spicy', 'kid-friendly']::text[], 'american', 881, 45,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Wraps au poulet cajun et salsa de maïs","steps":["Mélanger le poulet avec les épices cajun et une pincée de sel.","Mélanger le maïs, la tomate, l''oignon rouge, la coriandre et le jus d''un demi-citron vert pour la salsa ; saler.","Incorporer le zeste et le reste du jus de citron vert au yaourt.","Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire le poulet et le poivron 8 à 10 min en remuant, jusqu''à ce que le poulet soit grillé sur les bords et cuit.","Essuyer la poêle et y réchauffer les tortillas 20 secondes de chaque côté.","Tartiner chaque tortilla de yaourt au citron vert, ajouter la salade, le poulet et le poivron et une cuillerée de salsa, puis rouler."]},"it":{"title":"Wrap di pollo cajun con salsa di mais","steps":["Condire il pollo con le spezie cajun e un pizzico di sale.","Mescolare mais, pomodoro, cipolla rossa, coriandolo e il succo di mezzo lime per la salsa; salare.","Unire allo yogurt la scorza e il resto del succo di lime.","Scaldare l''olio in una padella grande a fuoco medio-alto e cuocere pollo e peperone per 8–10 min, mescolando, finché il pollo è abbrustolito ai bordi e cotto.","Pulire la padella e scaldarvi le tortillas 20 secondi per lato.","Spalmare ogni tortilla con lo yogurt al lime, aggiungere insalata, pollo e peperone e un cucchiaio di salsa, poi arrotolare."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f006e547-e528-5078-be45-4fe999de4982')
  returning id
)
