-- Air-fryer sweet chilli-lime chicken thighs with rice noodle salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7279a898-d04d-57eb-b82b-e31b57e6571a'::uuid, null, 'Air-fryer sweet chilli-lime chicken thighs with rice noodle salad', 'seed', null, 'Claude', '/recipe-photos/air-fryer-sweet-chilli-lime-chicken-thighs-with-rice-noodle-salad.webp', '/recipe-photos/air-fryer-sweet-chilli-lime-chicken-thighs-with-rice-noodle-salad.webp',
    2, null, 45, 15, 14, '["Mix 2 tbsp of the sweet chilli sauce with the soy sauce, the zest of 1 lime, the garlic and the ginger; coat the chicken and leave 15 min.","Air-fry the chicken at 200°C for 12–14 min, turning halfway and brushing with 1 tbsp more sweet chilli sauce for the last 3 min, until sticky and 75°C inside.","Meanwhile cook the noodles in a pot of boiling water as the pack says (usually 3–4 min), then drain and rinse under cold water.","Whisk the rest of the sweet chilli sauce with the fish sauce, the juice of both limes and 1 tbsp water.","Toss the noodles with the carrot, cucumber, herbs and most of the dressing.","Slice the chicken, lay it on the noodles, drizzle with the last of the dressing and scatter with peanuts."]'::jsonb,
    array['asian', 'salad', 'high protein']::text[], 'asian', 774, 40.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Hauts de cuisse de poulet chili doux-citron vert au air fryer, salade de nouilles de riz","steps":["Mélanger 2 c. à soupe de sauce chili douce avec la sauce soja, le zeste d''un citron vert, l''ail et le gingembre ; en enrober le poulet et laisser mariner 15 min.","Cuire le poulet au air fryer à 200 °C pendant 12 à 14 min, en le retournant à mi-cuisson et en le badigeonnant d''1 c. à soupe de sauce chili douce pour les 3 dernières minutes, jusqu''à ce qu''il soit laqué et à 75 °C à cœur.","Pendant ce temps, cuire les vermicelles dans une casserole d''eau bouillante selon le paquet (3 à 4 min en général), puis égoutter et rincer à l''eau froide.","Fouetter le reste de sauce chili douce avec la sauce de poisson, le jus des deux citrons verts et 1 c. à soupe d''eau.","Mélanger les nouilles avec la carotte, le concombre, les herbes et presque toute la sauce.","Trancher le poulet, le poser sur les nouilles, arroser du reste de sauce et parsemer de cacahuètes."]},"it":{"title":"Sovracosce di pollo chili dolce e lime in friggitrice ad aria con insalata di noodles di riso","steps":["Mescolare 2 cucchiai di salsa chili dolce con la salsa di soia, la scorza di 1 lime, l''aglio e lo zenzero; ricoprirne il pollo e lasciar marinare 15 min.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–14 min, girandolo a metà e spennellandolo con 1 cucchiaio di salsa chili dolce negli ultimi 3 min, finché è laccato e a 75 °C al cuore.","Nel frattempo cuocere i vermicelli in una pentola d''acqua bollente come indicato sulla confezione (di solito 3–4 min), poi scolarli e sciacquarli in acqua fredda.","Sbattere il resto della salsa chili dolce con la salsa di pesce, il succo dei due lime e 1 cucchiaio d''acqua.","Condire i noodles con carota, cetriolo, erbe e quasi tutto il condimento.","Affettare il pollo, adagiarlo sui noodles, irrorare con il resto del condimento e cospargere di arachidi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7279a898-d04d-57eb-b82b-e31b57e6571a')
  returning id
)
