-- Chicken thighs with salsa verde, new potatoes and asparagus
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0cabb57a-3d4c-5c88-9932-e0c5a59cac95'::uuid, null, 'Chicken thighs with salsa verde, new potatoes and asparagus', 'seed', null, 'Claude', '/recipe-photos/chicken-thighs-with-salsa-verde-new-potatoes-and-asparagus.webp', '/recipe-photos/chicken-thighs-with-salsa-verde-new-potatoes-and-asparagus.webp',
    2, null, 40, 15, 25, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer 15–18 min until tender.","Season the chicken and cook it in 1 tbsp oil in a frying pan over medium-high heat, 6–7 min a side, until well browned and 75°C inside; rest 3 min.","Meanwhile mix the parsley, basil, capers, anchovies, garlic, mustard and vinegar, then stir in the 3 tbsp olive oil and season with pepper.","Add the asparagus to the potatoes for their last 3 min, then drain.","Toss the potatoes and asparagus with a spoonful of the salsa verde.","Slice the chicken and serve it with the vegetables and the rest of the salsa verde spooned over."]'::jsonb,
    array['italian', 'high protein']::text[], 'italian', 806, 40.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Hauts de cuisse de poulet, salsa verde, pommes de terre nouvelles et asperges","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 à 18 min jusqu''à ce qu''elles soient tendres.","Saler et poivrer le poulet et le cuire dans 1 c. à soupe d''huile dans une poêle à feu moyen-vif, 6 à 7 min de chaque côté, jusqu''à ce qu''il soit bien doré et à 75 °C à cœur ; laisser reposer 3 min.","Pendant ce temps, mélanger le persil, le basilic, les câpres, les anchois, l''ail, la moutarde et le vinaigre, puis incorporer les 3 c. à soupe d''huile d''olive et poivrer.","Ajouter les asperges aux pommes de terre pour les 3 dernières minutes, puis égoutter.","Mélanger les pommes de terre et les asperges avec une cuillerée de salsa verde.","Trancher le poulet et le servir avec les légumes, nappé du reste de salsa verde."]},"it":{"title":"Sovracosce di pollo con salsa verde, patate novelle e asparagi","steps":["Mettere le patate in una pentola d''acqua fredda salata, portare a bollore e cuocere 15–18 min finché sono tenere.","Salare e pepare il pollo e cuocerlo con 1 cucchiaio d''olio in una padella a fuoco medio-alto, 6–7 min per lato, finché è ben dorato e a 75 °C al cuore; farlo riposare 3 min.","Nel frattempo mescolare prezzemolo, basilico, capperi, acciughe, aglio, senape e aceto, poi unire i 3 cucchiai d''olio e pepare.","Aggiungere gli asparagi alle patate negli ultimi 3 min, poi scolare.","Condire patate e asparagi con un cucchiaio di salsa verde.","Affettare il pollo e servirlo con le verdure e il resto della salsa verde sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0cabb57a-3d4c-5c88-9932-e0c5a59cac95')
  returning id
)
