-- Air-fryer turkey shawarma flatbreads with tahini sauce
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6964efee-3927-5498-af12-87b83d2534ae'::uuid, null, 'Air-fryer turkey shawarma flatbreads with tahini sauce', 'seed', null, 'Claude', '/recipe-photos/air-fryer-turkey-shawarma-flatbreads-with-tahini-sauce.webp', '/recipe-photos/air-fryer-turkey-shawarma-flatbreads-with-tahini-sauce.webp',
    2, null, 47, 15, 12, '["Mix the spices, 1 garlic clove, half the lemon juice, the olive oil and a good pinch of salt, and toss the turkey in it; leave 20 min (or up to a day in the fridge).","Whisk the tahini, yogurt, the rest of the garlic and a squeeze of lemon with 1–2 tbsp water and a pinch of salt.","Toss the cabbage with the rest of the lemon juice and a pinch of salt.","Spread the turkey in the air-fryer basket and cook at 200°C for 8–10 min, shaking halfway, until charred at the edges and cooked through.","Warm the pitas in a dry frying pan for 30 seconds a side.","Spread the pitas with tahini sauce and fill with cabbage, tomato, turkey, gherkins and parsley."]'::jsonb,
    array['middle eastern', 'street food', 'wrap', 'high protein']::text[], 'middle eastern', 806, 59.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Pains plats au shawarma de dinde au air fryer, sauce tahini","steps":["Mélanger les épices, 1 gousse d''ail, la moitié du jus de citron, l''huile d''olive et une bonne pincée de sel, et y enrober la dinde ; laisser mariner 20 min (ou jusqu''à un jour au réfrigérateur).","Fouetter le tahini, le yaourt, le reste de l''ail et un filet de citron avec 1 à 2 c. à soupe d''eau et une pincée de sel.","Mélanger le chou avec le reste du jus de citron et une pincée de sel.","Étaler la dinde dans le panier du air fryer et cuire à 200 °C pendant 8 à 10 min en secouant à mi-cuisson, jusqu''à ce qu''elle soit grillée sur les bords et cuite.","Réchauffer les pitas dans une poêle sèche 30 secondes de chaque côté.","Tartiner les pitas de sauce tahini et garnir de chou, de tomate, de dinde, de cornichons et de persil."]},"it":{"title":"Piadine di shawarma di tacchino in friggitrice ad aria con salsa tahina","steps":["Mescolare le spezie, 1 spicchio d''aglio, metà del succo di limone, l''olio e un bel pizzico di sale e condirvi il tacchino; lasciar marinare 20 min (o fino a un giorno in frigo).","Sbattere la tahina, lo yogurt, il resto dell''aglio e una spruzzata di limone con 1–2 cucchiai d''acqua e un pizzico di sale.","Condire il cavolo con il resto del succo di limone e un pizzico di sale.","Distribuire il tacchino nel cestello della friggitrice e cuocere a 200 °C per 8–10 min, scuotendo a metà, finché è abbrustolito ai bordi e cotto.","Scaldare le pite in una padella asciutta 30 secondi per lato.","Spalmare le pite con la salsa tahina e farcire con cavolo, pomodoro, tacchino, cetriolini e prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6964efee-3927-5498-af12-87b83d2534ae')
  returning id
)
