-- Air-fryer turkey tikka with spinach pilau rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b91c4fb8-73a7-5b7f-87e3-3b902ea315a9'::uuid, null, 'Air-fryer turkey tikka with spinach pilau rice', 'seed', null, 'Claude', '/recipe-photos/air-fryer-turkey-tikka-with-spinach-pilau-rice.webp', '/recipe-photos/air-fryer-turkey-tikka-with-spinach-pilau-rice.webp',
    2, null, 53, 15, 18, '["Mix the yogurt, garam masala, paprika, chilli powder, turmeric, half the cumin, the garlic, ginger, the juice of half the lemon, the fenugreek and a good pinch of salt; coat the turkey and leave at least 20 min.","Heat the oil in a pot, soften the onion with the bay leaf and the rest of the cumin for 4 min, then stir in the rice.","Add 300 ml water and a pinch of salt, bring to the boil, cover and cook on low for 12 min.","Meanwhile air-fry the turkey at 200°C for 10–12 min, turning halfway, until charred at the edges and 74°C inside.","Lay the spinach on top of the rice, cover again and leave off the heat for 5 min, then fold it through.","Serve the turkey on the rice with coriander and the rest of the lemon in wedges."]'::jsonb,
    array['indian', 'curry', 'high protein', 'spicy']::text[], 'indian', 679, 55.7,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Tikka de dinde au air fryer, riz pilaf aux épinards","steps":["Mélanger le yaourt, le garam masala, le paprika, le piment, le curcuma, la moitié du cumin, l''ail, le gingembre, le jus d''un demi-citron, le fenugrec et une bonne pincée de sel ; en enrober la dinde et laisser mariner au moins 20 min.","Chauffer l''huile dans une casserole, faire revenir l''oignon avec le laurier et le reste du cumin 4 min, puis ajouter le riz en remuant.","Ajouter 300 ml d''eau et une pincée de sel, porter à ébullition, couvrir et cuire 12 min à feu doux.","Pendant ce temps, cuire la dinde au air fryer à 200 °C pendant 10 à 12 min en la retournant à mi-cuisson, jusqu''à ce qu''elle soit grillée sur les bords et à 74 °C à cœur.","Déposer les épinards sur le riz, recouvrir et laisser 5 min hors du feu, puis les mélanger au riz.","Servir la dinde sur le riz avec la coriandre et le reste du citron en quartiers."]},"it":{"title":"Tikka di tacchino in friggitrice ad aria con riso pilaf agli spinaci","steps":["Mescolare yogurt, garam masala, paprika, peperoncino in polvere, curcuma, metà del cumino, aglio, zenzero, il succo di mezzo limone, il fieno greco e un bel pizzico di sale; ricoprirne il tacchino e lasciar marinare almeno 20 min.","Scaldare l''olio in una pentola, far appassire la cipolla con l''alloro e il resto del cumino per 4 min, poi unire il riso mescolando.","Aggiungere 300 ml d''acqua e un pizzico di sale, portare a bollore, coprire e cuocere 12 min a fuoco basso.","Nel frattempo cuocere il tacchino in friggitrice ad aria a 200 °C per 10–12 min, girandolo a metà, finché è abbrustolito ai bordi e a 74 °C al cuore.","Adagiare gli spinaci sul riso, coprire di nuovo e lasciare 5 min fuori dal fuoco, poi mescolarli al riso.","Servire il tacchino sul riso con il coriandolo e il resto del limone a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b91c4fb8-73a7-5b7f-87e3-3b902ea315a9')
  returning id
)
