-- Turkey escalopes with honey mustard leeks and potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '71449b68-635a-5e6a-9e94-d662693b30d1'::uuid, null, 'Turkey escalopes with honey mustard leeks and potatoes', 'seed', null, 'Claude', '/recipe-photos/turkey-escalopes-with-honey-mustard-leeks-and-potatoes.webp', '/recipe-photos/turkey-escalopes-with-honey-mustard-leeks-and-potatoes.webp',
    2, null, 35, 10, 25, '["Boil the potatoes in salted water for 15–18 min until tender, then drain.","Season the escalopes and dust them with the flour.","Heat the oil in a large frying pan over medium-high heat and cook the turkey 3 min a side until golden and just cooked through; set aside on a plate.","Lower the heat, add the butter, leeks, thyme and a pinch of salt and cook 6–8 min until soft.","Stir in the stock, both mustards and the honey and bubble for 2 min, then stir in the crème fraîche.","Return the turkey and its juices to the pan for 1–2 min to heat through, and serve with the potatoes and parsley."]'::jsonb,
    array['french', 'high protein', 'comfort']::text[], 'french', 721, 50.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Escalopes de dinde, poireaux au miel et à la moutarde, pommes de terre","steps":["Cuire les pommes de terre 15 à 18 min à l''eau salée jusqu''à ce qu''elles soient tendres, puis égoutter.","Saler et poivrer les escalopes et les fariner légèrement.","Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire la dinde 3 min de chaque côté jusqu''à ce qu''elle soit dorée et juste cuite ; réserver sur une assiette.","Baisser le feu, ajouter le beurre, les poireaux, le thym et une pincée de sel et cuire 6 à 8 min jusqu''à ce qu''ils soient fondants.","Ajouter le bouillon, les deux moutardes et le miel et laisser bouillonner 2 min, puis incorporer la crème fraîche.","Remettre la dinde et son jus dans la poêle 1 à 2 min pour la réchauffer, et servir avec les pommes de terre et le persil."]},"it":{"title":"Scaloppine di tacchino con porri al miele e senape e patate","steps":["Lessare le patate in acqua salata per 15–18 min finché sono tenere, poi scolarle.","Salare e pepare le scaloppine e infarinarle leggermente.","Scaldare l''olio in una padella grande a fuoco medio-alto e cuocere il tacchino 3 min per lato finché è dorato e appena cotto; tenerlo da parte su un piatto.","Abbassare il fuoco, aggiungere burro, porri, timo e un pizzico di sale e cuocere 6–8 min finché sono morbidi.","Unire il brodo, le due senapi e il miele e far sobbollire 2 min, poi incorporare la crème fraîche.","Rimettere il tacchino con il suo sugo nella padella per 1–2 min per scaldarlo e servire con le patate e il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '71449b68-635a-5e6a-9e94-d662693b30d1')
  returning id
)
