-- Air-fryer teriyaki beef meatballs with rice and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ab56082b-eb3f-5fe6-9fb7-ef4cf68508ad'::uuid, null, 'Air-fryer teriyaki beef meatballs with rice and green beans', 'seed', null, 'Claude', '/recipe-photos/air-fryer-teriyaki-beef-meatballs-with-rice-and-green-beans.webp', '/recipe-photos/air-fryer-teriyaki-beef-meatballs-with-rice-and-green-beans.webp',
    2, null, 33, 15, 18, '["Rinse the rice and put it in a pot with 300 ml water; bring to the boil, cover and simmer on low for 12 min.","Mix the beef, panko, egg, half the spring onion, the garlic, the ginger and a pinch of salt, and roll into 12 meatballs.","Air-fry the meatballs at 200°C for 10–12 min, shaking halfway, until browned and cooked through.","Lay the green beans on top of the rice for its last 6 min, cover again, then leave everything to rest 5 min off the heat.","For the teriyaki, bring the soy sauce, mirin, honey and 3 tbsp water to a simmer in a small pan, stir in the cornstarch mixed with 1 tbsp cold water and bubble 1 min until glossy.","Toss the meatballs in the sauce and serve on the rice with the beans, sesame seeds and the rest of the spring onion."]'::jsonb,
    array['japanese', 'asian', 'kid-friendly']::text[], 'japanese', 870, 53.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Boulettes de bœuf teriyaki au air fryer, riz et haricots verts","steps":["Rincer le riz et le mettre dans une casserole avec 300 ml d''eau ; porter à ébullition, couvrir et cuire 12 min à feu doux.","Mélanger le bœuf, le panko, l''œuf, la moitié de l''oignon nouveau, l''ail, le gingembre et une pincée de sel, et former 12 boulettes.","Cuire les boulettes au air fryer à 200 °C pendant 10 à 12 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient dorées et cuites.","Déposer les haricots verts sur le riz pour les 6 dernières minutes, recouvrir, puis laisser reposer le tout 5 min hors du feu.","Pour le teriyaki, porter à frémissement la sauce soja, le mirin, le miel et 3 c. à soupe d''eau dans une petite casserole, ajouter la fécule délayée dans 1 c. à soupe d''eau froide et laisser bouillonner 1 min jusqu''à ce que la sauce soit brillante.","Enrober les boulettes de sauce et servir sur le riz avec les haricots, les graines de sésame et le reste de l''oignon nouveau."]},"it":{"title":"Polpette di manzo teriyaki in friggitrice ad aria con riso e fagiolini","steps":["Sciacquare il riso e metterlo in una pentola con 300 ml d''acqua; portare a bollore, coprire e cuocere 12 min a fuoco basso.","Mescolare manzo, panko, uovo, metà del cipollotto, aglio, zenzero e un pizzico di sale e formare 12 polpette.","Cuocere le polpette in friggitrice ad aria a 200 °C per 10–12 min, scuotendo a metà, finché sono dorate e cotte.","Adagiare i fagiolini sul riso negli ultimi 6 min, coprire di nuovo, poi lasciar riposare tutto 5 min fuori dal fuoco.","Per il teriyaki portare a sobbollire salsa di soia, mirin, miele e 3 cucchiai d''acqua in un pentolino, unire l''amido sciolto in 1 cucchiaio d''acqua fredda e cuocere 1 min finché è lucida.","Ripassare le polpette nella salsa e servirle sul riso con i fagiolini, i semi di sesamo e il resto del cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ab56082b-eb3f-5fe6-9fb7-ef4cf68508ad')
  returning id
)
