-- Harissa beef with roasted squash and couscous
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '68a03d91-944b-5da3-954a-1d168df79923'::uuid, null, 'Harissa beef with roasted squash and couscous', 'seed', null, 'Claude', '/recipe-photos/harissa-beef-with-roasted-squash-and-couscous.webp', '/recipe-photos/harissa-beef-with-roasted-squash-and-couscous.webp',
    2, null, 40, 15, 25, '["Heat the oven to 220°C. Toss the squash with the 1 tbsp oil, half the cumin and salt on a tray and roast for 25 min, turning once, until soft and caramelised.","Heat the 1 tsp oil in a frying pan and soften the onion for 5 min.","Add the beef and garlic and cook over high heat for 5–6 min, breaking it up, until browned.","Stir in the harissa, tomato paste, the rest of the cumin and 100 ml water and simmer 5 min until saucy; season with salt.","Meanwhile pour the boiling stock over the couscous in a bowl, cover and leave 5 min, then fluff with a fork.","Serve the couscous topped with the beef and squash, a spoonful of yogurt and the mint."]'::jsonb,
    array['north african', 'spicy', 'high protein']::text[], 'north african', 873, 51.8,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Bœuf haché à la harissa, courge rôtie et semoule","steps":["Préchauffer le four à 220 °C. Mélanger la courge avec 1 c. à soupe d''huile, la moitié du cumin et du sel sur une plaque et rôtir 25 min en retournant une fois, jusqu''à ce qu''elle soit tendre et caramélisée.","Chauffer la cuillère à café d''huile dans une poêle et faire revenir l''oignon 5 min.","Ajouter le bœuf et l''ail et cuire à feu vif 5 à 6 min en émiettant, jusqu''à ce qu''il soit bien doré.","Ajouter la harissa, le concentré de tomate, le reste du cumin et 100 ml d''eau et laisser mijoter 5 min jusqu''à obtenir une sauce ; saler.","Pendant ce temps, verser le bouillon bouillant sur la semoule dans un saladier, couvrir et laisser gonfler 5 min, puis égrener à la fourchette.","Servir la semoule garnie du bœuf et de la courge, d''une cuillerée de yaourt et de menthe."]},"it":{"title":"Manzo macinato all''harissa con zucca arrosto e cous cous","steps":["Scaldare il forno a 220 °C. Condire la zucca con 1 cucchiaio d''olio, metà del cumino e sale su una teglia e arrostirla 25 min, girandola una volta, finché è morbida e caramellata.","Scaldare il cucchiaino d''olio in una padella e far appassire la cipolla per 5 min.","Aggiungere il manzo e l''aglio e cuocere a fuoco vivo 5–6 min, sgranandolo, finché è ben rosolato.","Unire harissa, concentrato, il resto del cumino e 100 ml d''acqua e cuocere 5 min finché si forma un sugo; salare.","Nel frattempo versare il brodo bollente sul cous cous in una ciotola, coprire e lasciar riposare 5 min, poi sgranare con la forchetta.","Servire il cous cous con il manzo e la zucca sopra, un cucchiaio di yogurt e la menta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '68a03d91-944b-5da3-954a-1d168df79923')
  returning id
)
