-- Honey gochujang beef noodles with spinach
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'eb23031d-172b-5243-816a-c74788837fc3'::uuid, null, 'Honey gochujang beef noodles with spinach', 'seed', null, 'Claude', '/recipe-photos/honey-gochujang-beef-noodles-with-spinach.webp', '/recipe-photos/honey-gochujang-beef-noodles-with-spinach.webp',
    2, null, 25, 10, 15, '["Toss the beef with the cornstarch and 1 tsp soy sauce.","Whisk the gochujang, honey, 1 tbsp soy sauce, rice vinegar, garlic and sesame oil with 2 tbsp water.","Cook the noodles in a pot of boiling water as the pack says (usually 4 min), then drain.","Heat the oil in a wok over high heat and stir-fry the beef for 2 min until browned; lift it out.","Stir-fry the onion and spring onion for 2 min, then add the spinach and stir 1 min until it just wilts.","Return the beef with the noodles and sauce and toss for 1 min until sticky; serve with sesame seeds."]'::jsonb,
    array['korean', 'asian', 'stir-fry', 'spicy', 'quick']::text[], 'korean', 746, 41.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Nouilles au bœuf miel-gochujang et épinards","steps":["Mélanger le bœuf avec la fécule et 1 c. à café de sauce soja.","Fouetter le gochujang, le miel, 1 c. à soupe de sauce soja, le vinaigre de riz, l''ail et l''huile de sésame avec 2 c. à soupe d''eau.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet (4 min en général), puis égoutter.","Chauffer l''huile dans un wok à feu vif et faire sauter le bœuf 2 min jusqu''à ce qu''il soit saisi ; le retirer.","Faire sauter l''oignon et l''oignon nouveau 2 min, puis ajouter les épinards et remuer 1 min jusqu''à ce qu''ils tombent à peine.","Remettre le bœuf avec les nouilles et la sauce et mélanger 1 min jusqu''à ce que tout soit bien laqué ; servir avec les graines de sésame."]},"it":{"title":"Noodles di manzo al miele e gochujang con spinaci","steps":["Condire il manzo con l''amido e 1 cucchiaino di salsa di soia.","Sbattere gochujang, miele, 1 cucchiaio di salsa di soia, aceto di riso, aglio e olio di sesamo con 2 cucchiai d''acqua.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione (di solito 4 min), poi scolarli.","Scaldare l''olio in un wok a fuoco vivo e saltare il manzo 2 min finché è rosolato; toglierlo.","Saltare cipolla e cipollotto per 2 min, poi aggiungere gli spinaci e mescolare 1 min finché appassiscono appena.","Rimettere il manzo con i noodles e la salsa e saltare 1 min finché tutto è ben laccato; servire con i semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'eb23031d-172b-5243-816a-c74788837fc3')
  returning id
)
