-- Black pepper beef udon with cabbage
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c6ba679c-0cf6-522d-a8e9-237a8b75c15d'::uuid, null, 'Black pepper beef udon with cabbage', 'seed', null, 'Claude', '/recipe-photos/black-pepper-beef-udon-with-cabbage.webp', '/recipe-photos/black-pepper-beef-udon-with-cabbage.webp',
    2, null, 22, 10, 12, '["Toss the beef with the cornstarch and 1 tsp soy sauce; mix the 2 tbsp soy sauce, oyster sauce, sugar, pepper and 4 tbsp water for the sauce.","Put the udon in a bowl, cover with boiling water from the kettle for 1 min to loosen, then drain.","Heat the oil in a wok over high heat and stir-fry the beef for 2 min until browned; lift it out.","Stir-fry the onion, garlic and cabbage for 3–4 min until the cabbage is wilted but still crunchy.","Add the udon, the beef and the sauce and toss for 2 min until the noodles are hot and coated in the peppery sauce.","Serve straight away with spring onion."]'::jsonb,
    array['asian', 'chinese', 'stir-fry', 'quick']::text[], 'asian', 672, 43.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Udon au bœuf et au poivre noir, chou sauté","steps":["Mélanger le bœuf avec la fécule et 1 c. à café de sauce soja ; mélanger les 2 c. à soupe de sauce soja, la sauce d''huître, le sucre, le poivre et 4 c. à soupe d''eau pour la sauce.","Mettre les udon dans un saladier, les couvrir d''eau bouillante 1 min pour les détacher, puis égoutter.","Chauffer l''huile dans un wok à feu vif et faire sauter le bœuf 2 min jusqu''à ce qu''il soit saisi ; le retirer.","Faire sauter l''oignon, l''ail et le chou 3 à 4 min jusqu''à ce que le chou soit tombé mais encore croquant.","Ajouter les udon, le bœuf et la sauce et mélanger 2 min jusqu''à ce que les nouilles soient chaudes et enrobées de sauce poivrée.","Servir aussitôt avec l''oignon nouveau."]},"it":{"title":"Udon al manzo e pepe nero con cavolo","steps":["Condire il manzo con l''amido e 1 cucchiaino di salsa di soia; mescolare i 2 cucchiai di salsa di soia, la salsa d''ostrica, lo zucchero, il pepe e 4 cucchiai d''acqua per la salsa.","Mettere gli udon in una ciotola, coprirli con acqua bollente per 1 min per separarli, poi scolarli.","Scaldare l''olio in un wok a fuoco vivo e saltare il manzo 2 min finché è rosolato; toglierlo.","Saltare cipolla, aglio e cavolo per 3–4 min finché il cavolo è appassito ma ancora croccante.","Unire gli udon, il manzo e la salsa e saltare 2 min finché i noodles sono caldi e avvolti dalla salsa pepata.","Servire subito con il cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c6ba679c-0cf6-522d-a8e9-237a8b75c15d')
  returning id
)
