-- Air-fryer honey mustard pork chops with potatoes and Brussels sprouts
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'be62c0b2-60d2-547b-84c7-e6d0a13b3c07'::uuid, null, 'Air-fryer honey mustard pork chops with potatoes and Brussels sprouts', 'seed', null, 'Claude', '/recipe-photos/air-fryer-honey-mustard-pork-chops-with-potatoes-and-brussels-sprouts.webp', '/recipe-photos/air-fryer-honey-mustard-pork-chops-with-potatoes-and-brussels-sprouts.webp',
    2, null, 32, 10, 22, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer 15 min.","Mix both mustards, the honey, olive oil and garlic; season the chops and brush them with half of it.","Air-fry the chops at 200°C for 10–12 min, turning halfway, until 63°C in the centre; rest them 5 min.","Add the sprouts to the potatoes for their last 6 min, then drain and toss with the butter, salt and pepper.","Bring the rest of the honey mustard and the stock to the boil in a small pan and bubble 1–2 min until slightly thickened.","Serve the chops with the potatoes and sprouts, with the sauce poured over."]'::jsonb,
    array['british', 'high protein', 'comfort']::text[], 'british', 728, 44.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Côtes de porc miel-moutarde au air fryer, pommes de terre et choux de Bruxelles","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min à frémissement.","Mélanger les deux moutardes, le miel, l''huile d''olive et l''ail ; saler et poivrer les côtes et les badigeonner de la moitié du mélange.","Cuire les côtes au air fryer à 200 °C pendant 10 à 12 min en les retournant à mi-cuisson, jusqu''à 63 °C à cœur ; les laisser reposer 5 min.","Ajouter les choux de Bruxelles aux pommes de terre pour les 6 dernières minutes, puis égoutter et mélanger avec le beurre, du sel et du poivre.","Porter à ébullition le reste du mélange miel-moutarde avec le bouillon dans une petite casserole et laisser réduire 1 à 2 min jusqu''à ce qu''il épaississe légèrement.","Servir les côtes avec les pommes de terre et les choux de Bruxelles, nappées de sauce."]},"it":{"title":"Braciole di maiale al miele e senape in friggitrice ad aria con patate e cavolini di Bruxelles","steps":["Mettere le patate in una pentola d''acqua fredda salata, portare a bollore e cuocere 15 min a fuoco medio.","Mescolare le due senapi, il miele, l''olio e l''aglio; salare e pepare le braciole e spennellarle con metà del composto.","Cuocere le braciole in friggitrice ad aria a 200 °C per 10–12 min, girandole a metà, finché raggiungono 63 °C al cuore; farle riposare 5 min.","Aggiungere i cavolini alle patate negli ultimi 6 min, poi scolare e condire con il burro, sale e pepe.","Portare a bollore il resto del composto al miele e senape con il brodo in un pentolino e far ridurre 1–2 min finché si addensa leggermente.","Servire le braciole con patate e cavolini, con la salsa versata sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'be62c0b2-60d2-547b-84c7-e6d0a13b3c07')
  returning id
)
