-- Air-fryer jerk pork tenderloin with rice and peas and slaw
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '05a8e01f-949a-5a2e-bf71-1b877f338bc1'::uuid, null, 'Air-fryer jerk pork tenderloin with rice and peas and slaw', 'seed', null, 'Claude', '/recipe-photos/air-fryer-jerk-pork-tenderloin-with-rice-and-peas-and-slaw.webp', '/recipe-photos/air-fryer-jerk-pork-tenderloin-with-rice-and-peas-and-slaw.webp',
    2, null, 50, 15, 20, '["Rub the pork with the jerk seasoning, the oil and the juice of half a lime; leave 15 min (or up to a day in the fridge).","Put the rice, coconut milk, 150 ml water, beans, half the spring onion, the garlic, thyme, allspice and a pinch of salt in a pot; bring to the boil, cover and simmer on low for 15 min, then rest 5 min.","Cut the tenderloin into two shorter pieces and air-fry at 200°C for 16–18 min, turning halfway, until 63°C in the centre.","Rest the pork 5 min while you toss the cabbage and carrot with the juice of 1 lime and a pinch of salt.","Remove the thyme from the rice and fluff it with a fork.","Slice the pork and serve with the rice and peas, the slaw, the rest of the spring onion and lime wedges."]'::jsonb,
    array['caribbean', 'spicy', 'high protein', 'generous']::text[], 'caribbean', 860, 49.4,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Filet mignon de porc jerk au air fryer, riz aux haricots rouges et coleslaw","steps":["Frotter le porc avec l''assaisonnement jerk, l''huile et le jus d''un demi-citron vert ; laisser mariner 15 min (ou jusqu''à un jour au réfrigérateur).","Mettre le riz, le lait de coco, 150 ml d''eau, les haricots, la moitié de l''oignon nouveau, l''ail, le thym, le piment de la Jamaïque et une pincée de sel dans une casserole ; porter à ébullition, couvrir et cuire 15 min à feu doux, puis laisser reposer 5 min.","Couper le filet mignon en deux morceaux plus courts et le cuire au air fryer à 200 °C pendant 16 à 18 min en le retournant à mi-cuisson, jusqu''à 63 °C à cœur.","Laisser reposer le porc 5 min pendant que l''on mélange le chou et la carotte avec le jus d''un citron vert et une pincée de sel.","Retirer le thym du riz et l''égrener à la fourchette.","Trancher le porc et servir avec le riz, le coleslaw, le reste de l''oignon nouveau et des quartiers de citron vert."]},"it":{"title":"Filetto di maiale jerk in friggitrice ad aria con riso e fagioli e insalata di cavolo","steps":["Massaggiare il maiale con le spezie jerk, l''olio e il succo di mezzo lime; lasciar marinare 15 min (o fino a un giorno in frigo).","Mettere in una pentola riso, latte di cocco, 150 ml d''acqua, fagioli, metà del cipollotto, aglio, timo, pimento e un pizzico di sale; portare a bollore, coprire e cuocere 15 min a fuoco basso, poi lasciar riposare 5 min.","Tagliare il filetto in due pezzi più corti e cuocerlo in friggitrice ad aria a 200 °C per 16–18 min, girandolo a metà, finché raggiunge 63 °C al cuore.","Far riposare il maiale 5 min mentre si condiscono cavolo e carota con il succo di 1 lime e un pizzico di sale.","Togliere il timo dal riso e sgranarlo con la forchetta.","Affettare il maiale e servirlo con riso e fagioli, l''insalata di cavolo, il resto del cipollotto e spicchi di lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '05a8e01f-949a-5a2e-bf71-1b877f338bc1')
  returning id
)
