-- Pork and green bean stir-fry with chilli-garlic sauce and rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b0dcc451-b61c-5159-81e5-e140eb635520'::uuid, null, 'Pork and green bean stir-fry with chilli-garlic sauce and rice', 'seed', null, 'Claude', '/recipe-photos/pork-and-green-bean-stir-fry-with-chilli-garlic-sauce-and-rice.webp', '/recipe-photos/pork-and-green-bean-stir-fry-with-chilli-garlic-sauce-and-rice.webp',
    2, null, 25, 10, 15, '["Cook the rice in a pot with 300 ml water: bring to the boil, cover and simmer on low for 12 min, then rest 5 min.","Mix the sriracha, soy sauce, oyster sauce, sugar, rice vinegar and sesame oil with 2 tbsp water.","Heat the oil in a wok over high heat and stir-fry the green beans for 4–5 min until blistered and just tender; push them to the side.","Add the pork and cook 4–5 min, breaking it up, until browned and a little crisp.","Add the garlic, ginger and chilli and stir-fry 1 min until fragrant.","Pour in the sauce and toss 1 min until it coats everything; serve over the rice with spring onion."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'spicy', 'quick']::text[], 'chinese', 795, 36.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Porc haché sauté aux haricots verts, sauce ail-piment et riz","steps":["Cuire le riz dans une casserole avec 300 ml d''eau : porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer 5 min.","Mélanger la sriracha, la sauce soja, la sauce d''huître, le sucre, le vinaigre de riz et l''huile de sésame avec 2 c. à soupe d''eau.","Chauffer l''huile dans un wok à feu vif et faire sauter les haricots verts 4 à 5 min jusqu''à ce qu''ils soient cloqués et juste tendres ; les pousser sur le côté.","Ajouter le porc et cuire 4 à 5 min en l''émiettant, jusqu''à ce qu''il soit doré et un peu croustillant.","Ajouter l''ail, le gingembre et le piment et faire sauter 1 min jusqu''à ce qu''ils embaument.","Verser la sauce et mélanger 1 min pour tout enrober ; servir sur le riz avec l''oignon nouveau."]},"it":{"title":"Maiale macinato saltato con fagiolini, salsa aglio e peperoncino e riso","steps":["Cuocere il riso in una pentola con 300 ml d''acqua: portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare 5 min.","Mescolare sriracha, salsa di soia, salsa d''ostrica, zucchero, aceto di riso e olio di sesamo con 2 cucchiai d''acqua.","Scaldare l''olio in un wok a fuoco vivo e saltare i fagiolini per 4–5 min finché sono abbrustoliti e appena teneri; spingerli di lato.","Aggiungere il maiale e cuocere 4–5 min, sgranandolo, finché è rosolato e un po'' croccante.","Aggiungere aglio, zenzero e peperoncino e saltare 1 min finché sprigionano il profumo.","Versare la salsa e saltare 1 min finché avvolge tutto; servire sul riso con il cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b0dcc451-b61c-5159-81e5-e140eb635520')
  returning id
)
