-- Air-fryer pork satay with rice and quick cucumber pickle
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a043608c-b12a-5954-9def-cfb521936032'::uuid, null, 'Air-fryer pork satay with rice and quick cucumber pickle', 'seed', null, 'Claude', '/recipe-photos/air-fryer-pork-satay-with-rice-and-quick-cucumber-pickle.webp', '/recipe-photos/air-fryer-pork-satay-with-rice-and-quick-cucumber-pickle.webp',
    2, null, 55, 20, 15, '["Mix the soy sauce, coriander, turmeric, sugar, oil and garlic, toss the pork in it and leave 20 min; thread onto skewers that fit your air fryer.","Cook the rice in a pot with 300 ml water: bring to the boil, cover and simmer on low for 12 min, then rest 5 min.","Toss the cucumber and red onion with the rice vinegar, the pickle sugar and a pinch of salt.","Air-fry the skewers at 200°C for 8–10 min, turning once, until charred at the edges and cooked through.","Meanwhile warm the peanut butter, coconut milk, soy sauce, honey and sriracha in a small pan, stirring, for 2–3 min until smooth and thick; add lime juice to taste.","Serve the skewers on the rice with the satay sauce and the cucumber pickle."]'::jsonb,
    array['indonesian', 'asian', 'high protein', 'street food']::text[], 'indonesian', 838, 49.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Satay de porc au air fryer, riz et pickles minute de concombre","steps":["Mélanger la sauce soja, la coriandre, le curcuma, le sucre, l''huile et l''ail, y enrober le porc et laisser mariner 20 min ; l''enfiler sur des brochettes adaptées au air fryer.","Cuire le riz dans une casserole avec 300 ml d''eau : porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer 5 min.","Mélanger le concombre et l''oignon rouge avec le vinaigre de riz, le sucre du pickle et une pincée de sel.","Cuire les brochettes au air fryer à 200 °C pendant 8 à 10 min en les retournant une fois, jusqu''à ce qu''elles soient grillées sur les bords et cuites.","Pendant ce temps, chauffer le beurre de cacahuète, le lait de coco, la sauce soja, le miel et la sriracha dans une petite casserole 2 à 3 min en remuant, jusqu''à obtenir une sauce lisse et épaisse ; ajouter du jus de citron vert selon le goût.","Servir les brochettes sur le riz avec la sauce satay et les pickles de concombre."]},"it":{"title":"Satay di maiale in friggitrice ad aria con riso e cetriolo marinato","steps":["Mescolare salsa di soia, coriandolo, curcuma, zucchero, olio e aglio, condirvi il maiale e lasciar marinare 20 min; infilarlo su spiedini adatti alla friggitrice.","Cuocere il riso in una pentola con 300 ml d''acqua: portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare 5 min.","Condire cetriolo e cipolla rossa con l''aceto di riso, lo zucchero per il marinato e un pizzico di sale.","Cuocere gli spiedini in friggitrice ad aria a 200 °C per 8–10 min, girandoli una volta, finché sono abbrustoliti ai bordi e cotti.","Nel frattempo scaldare burro di arachidi, latte di cocco, salsa di soia, miele e sriracha in un pentolino per 2–3 min, mescolando, finché la salsa è liscia e densa; aggiungere succo di lime a piacere.","Servire gli spiedini sul riso con la salsa satay e il cetriolo marinato."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a043608c-b12a-5954-9def-cfb521936032')
  returning id
)
