-- Pesto salmon pasta with peas and spinach
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '38b6fe91-83fe-46ac-8292-00b83183c374'::uuid, null, 'Pesto salmon pasta with peas and spinach', 'seed', null, 'Claude', '/recipe-photos/pesto-salmon-pasta-with-peas-and-spinach.webp', '/recipe-photos/pesto-salmon-pasta-with-peas-and-spinach.webp',
    2, null, 25, 5, 20, '["Bring a large pot of salted water to the boil and cook the pasta for the time on the packet.","Meanwhile, season the salmon and fry it in the oil in a non-stick pan over medium-high heat, 4 min on the first side and 2-3 min on the second, until just cooked. Lift it out and break it into large flakes.","Add the peas to the pasta for its last 2 min of cooking.","Scoop out a mug of the cooking water, then drain the pasta and peas and tip them into the salmon pan off the heat.","Stir in the spinach, the pesto, the lemon zest and juice and 3-4 tbsp of the cooking water, tossing until the spinach wilts and the sauce turns glossy; add a little more water if it is thick.","Fold the salmon flakes through gently, season with pepper and serve with the parmesan."]'::jsonb,
    array['italian', 'healthy', 'high protein', 'quick']::text[], 'italian', 810, 45.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pâtes au saumon et au pesto, petits pois et épinards","steps":["Porter une grande casserole d''eau salée à ébullition et cuire les pâtes le temps indiqué sur le paquet.","Pendant ce temps, saler et poivrer le saumon et le saisir dans l''huile dans une poêle antiadhésive à feu moyen-vif, 4 min sur la première face et 2 à 3 min sur la seconde, jusqu''à ce qu''il soit juste cuit. Le retirer et l''effeuiller en gros morceaux.","Ajouter les petits pois aux pâtes pour leurs 2 dernières minutes de cuisson.","Prélever une tasse d''eau de cuisson, puis égoutter les pâtes et les petits pois et les verser dans la poêle du saumon, hors du feu.","Incorporer les épinards, le pesto, le zeste et le jus de citron et 3 à 4 c. à soupe d''eau de cuisson, en mélangeant jusqu''à ce que les épinards tombent et que la sauce soit brillante ; ajouter un peu d''eau si elle est épaisse.","Incorporer délicatement le saumon, poivrer et servir avec le parmesan."]},"it":{"title":"Pasta al pesto con salmone, piselli e spinaci","steps":["Portare a bollore una pentola capiente di acqua salata e cuocere la pasta per il tempo indicato sulla confezione.","Intanto salare il salmone e rosolarlo nell''olio in una padella antiaderente a fuoco medio-alto, 4 min sul primo lato e 2-3 min sul secondo, finché è appena cotto. Toglierlo e spezzarlo in grosse scaglie.","Aggiungere i piselli alla pasta negli ultimi 2 min di cottura.","Prelevare una tazza di acqua di cottura, poi scolare pasta e piselli e versarli nella padella del salmone, fuori dal fuoco.","Unire gli spinaci, il pesto, la scorza e il succo di limone e 3-4 cucchiai di acqua di cottura, mescolando finché gli spinaci appassiscono e il condimento diventa lucido; aggiungere un po'' d''acqua se è denso.","Incorporare delicatamente il salmone, pepare e servire con il parmigiano."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '38b6fe91-83fe-46ac-8292-00b83183c374')
  returning id
)
