-- Salmon with peanut-lime noodles and crunchy veg
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a4e50e5b-ed5a-49de-84e0-dca7c097cc76'::uuid, null, 'Salmon with peanut-lime noodles and crunchy veg', 'seed', null, 'Claude', '/recipe-photos/salmon-with-peanut-lime-noodles-and-crunchy-veg.webp', '/recipe-photos/salmon-with-peanut-lime-noodles-and-crunchy-veg.webp',
    2, null, 25, 15, 10, '["Soak or boil the rice noodles as the packet says, then drain and rinse under cold water so they don''t stick.","Whisk the peanut butter with the soy sauce, lime juice, honey, garlic, ginger, sriracha and 3-4 tbsp warm water into a pourable sauce.","Season the salmon with salt and fry it in the oil in a non-stick pan over medium-high heat, 3-4 min per side, until golden and just cooked through.","Toss the noodles with the carrot, cucumber and most of the sauce.","Divide the noodles between bowls, break the salmon over the top in large flakes and spoon over the rest of the sauce.","Finish with the peanuts and coriander."]'::jsonb,
    array['asian', 'thai', 'healthy', 'high protein', 'quick', 'bowl']::text[], 'asian', 809, 41.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saumon et nouilles cacahuète-citron vert aux légumes croquants","steps":["Faire tremper ou cuire les nouilles de riz selon le paquet, puis les égoutter et les rincer à l''eau froide pour qu''elles ne collent pas.","Fouetter le beurre de cacahuète avec la sauce soja, le jus de citron vert, le miel, l''ail, le gingembre, la sriracha et 3 à 4 c. à soupe d''eau tiède pour obtenir une sauce fluide.","Saler le saumon et le saisir dans l''huile dans une poêle antiadhésive à feu moyen-vif, 3 à 4 min par face, jusqu''à ce qu''il soit doré et juste cuit.","Mélanger les nouilles avec la carotte, le concombre et la plus grande partie de la sauce.","Répartir les nouilles dans des bols, effeuiller le saumon par-dessus en gros morceaux et napper du reste de sauce.","Finir avec les cacahuètes et la coriandre."]},"it":{"title":"Salmone con noodles arachidi e lime e verdure croccanti","steps":["Ammollare o lessare i noodles di riso come indicato sulla confezione, poi scolarli e sciacquarli sotto l''acqua fredda perché non si attacchino.","Sbattere il burro di arachidi con salsa di soia, succo di lime, miele, aglio, zenzero, sriracha e 3-4 cucchiai d''acqua tiepida fino a ottenere una salsa fluida.","Salare il salmone e rosolarlo nell''olio in una padella antiaderente a fuoco medio-alto, 3-4 min per lato, finché è dorato e appena cotto.","Condire i noodles con carota, cetriolo e gran parte della salsa.","Dividere i noodles nelle ciotole, spezzare sopra il salmone in grosse scaglie e versare il resto della salsa.","Finire con arachidi e coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a4e50e5b-ed5a-49de-84e0-dca7c097cc76')
  returning id
)
