-- Air-fryer salmon pittas with tzatziki
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '299a87a7-23bf-411f-87b5-7eaaa7301c7c'::uuid, null, 'Air-fryer salmon pittas with tzatziki', 'seed', null, 'Claude', '/recipe-photos/air-fryer-salmon-pittas-with-tzatziki.webp', '/recipe-photos/air-fryer-salmon-pittas-with-tzatziki.webp',
    2, null, 25, 15, 10, '["Toss the salmon with the oil, oregano, paprika, lemon zest, salt and pepper.","For the tzatziki, mix the yogurt with the cucumber, garlic, dill, a squeeze of lemon and a pinch of salt.","Heat the air fryer to 200°C. Spread the salmon cubes in one layer in the basket and air-fry 6-7 min, until lightly charred at the edges and just cooked.","Meanwhile, warm the pittas in a dry frying pan, 1 min per side.","Rinse the red onion under cold water and toss with a squeeze of lemon.","Spread the pittas with tzatziki, fill with lettuce, tomato, onion and the salmon, and add a last spoonful of tzatziki."]'::jsonb,
    array['greek', 'mediterranean', 'healthy', 'high protein', 'quick', 'sandwich']::text[], 'greek', 854, 50.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Pitas au saumon au air fryer et tzatziki","steps":["Mélanger le saumon avec l''huile, l''origan, le paprika, le zeste de citron, du sel et du poivre.","Pour le tzatziki, mélanger le yaourt avec le concombre, l''ail, l''aneth, un filet de citron et une pincée de sel.","Préchauffer le air fryer à 200 °C. Étaler les cubes de saumon en une seule couche dans le panier et cuire 6 à 7 min, jusqu''à ce qu''ils soient légèrement grillés sur les bords et juste cuits.","Pendant ce temps, réchauffer les pitas dans une poêle sèche, 1 min par face.","Rincer l''oignon rouge à l''eau froide et l''arroser d''un filet de citron.","Tartiner les pitas de tzatziki, les garnir de salade, de tomate, d''oignon et de saumon, et ajouter une dernière cuillerée de tzatziki."]},"it":{"title":"Pita con salmone in friggitrice ad aria e tzatziki","steps":["Condire il salmone con olio, origano, paprika, scorza di limone, sale e pepe.","Per lo tzatziki, mescolare lo yogurt con cetriolo, aglio, aneto, un po'' di succo di limone e un pizzico di sale.","Scaldare la friggitrice ad aria a 200 °C. Disporre i cubetti di salmone in un solo strato nel cestello e cuocere 6-7 min, finché sono leggermente abbrustoliti ai bordi e appena cotti.","Intanto scaldare le pita in una padella asciutta, 1 min per lato.","Sciacquare la cipolla rossa sotto l''acqua fredda e condirla con un po'' di limone.","Spalmare le pita di tzatziki, farcirle con lattuga, pomodoro, cipolla e salmone e aggiungere un''ultima cucchiaiata di tzatziki."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '299a87a7-23bf-411f-87b5-7eaaa7301c7c')
  returning id
)
