-- Cod with romesco, potatoes and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8e9b0f20-5586-444c-8b0a-15a882664811'::uuid, null, 'Cod with romesco, potatoes and green beans', 'seed', null, 'Claude', '/recipe-photos/cod-with-romesco-potatoes-and-green-beans.webp', '/recipe-photos/cod-with-romesco-potatoes-and-green-beans.webp',
    2, null, 35, 15, 20, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer 15 min; add the green beans for the last 5 min. Drain.","Meanwhile, blend the peppers, almonds, garlic, paprika, vinegar, 1 tbsp of the oil and a pinch of salt into a thick, slightly coarse romesco.","Pat the cod dry, season it and dust it lightly with the flour.","Heat the rest of the oil in a non-stick pan over medium-high heat and fry the cod 4 min without moving it, until golden underneath; turn and cook 2-3 min more, until it flakes.","Toss the potatoes and beans with a pinch of salt and any oil left in the pan.","Spread a thick spoonful of romesco on each plate, set the cod on top and serve with the potatoes and beans and the parsley."]'::jsonb,
    array['spanish', 'mediterranean', 'healthy', 'high protein']::text[], 'spanish', 643, 42.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, true,
    '{"fr":{"title":"Cabillaud sauce romesco, pommes de terre et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min ; ajouter les haricots verts pour les 5 dernières minutes. Égoutter.","Pendant ce temps, mixer les poivrons, les amandes, l''ail, le paprika, le vinaigre, 1 c. à soupe d''huile et une pincée de sel en une sauce romesco épaisse et un peu rustique.","Sécher le cabillaud, le saler, le poivrer et le fariner légèrement.","Chauffer le reste d''huile dans une poêle antiadhésive à feu moyen-vif et saisir le cabillaud 4 min sans le bouger, jusqu''à ce qu''il soit doré dessous ; le retourner et cuire 2 à 3 min de plus, jusqu''à ce qu''il s''effeuille.","Mélanger les pommes de terre et les haricots avec une pincée de sel et l''huile restée dans la poêle.","Étaler une bonne cuillerée de romesco dans chaque assiette, poser le cabillaud dessus et servir avec les pommes de terre, les haricots et le persil."]},"it":{"title":"Merluzzo con salsa romesco, patate e fagiolini","steps":["Mettere le patate in una pentola di acqua fredda salata, portare a bollore e cuocere 15 min; aggiungere i fagiolini negli ultimi 5 min. Scolare.","Intanto frullare peperoni, mandorle, aglio, paprika, aceto, 1 cucchiaio d''olio e un pizzico di sale fino a ottenere una romesco densa e un po'' rustica.","Asciugare il merluzzo, salarlo, peparlo e infarinarlo leggermente.","Scaldare il resto dell''olio in una padella antiaderente a fuoco medio-alto e rosolare il merluzzo 4 min senza muoverlo, finché è dorato sotto; girarlo e cuocere altri 2-3 min, finché si sfalda.","Condire patate e fagiolini con un pizzico di sale e l''olio rimasto in padella.","Stendere una bella cucchiaiata di romesco in ogni piatto, adagiarvi il merluzzo e servire con patate, fagiolini e prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8e9b0f20-5586-444c-8b0a-15a882664811')
  returning id
)
