-- Hake with salsa verde, new potatoes and asparagus
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8d8e85d0-95ef-45dc-b599-bcb0846aed0a'::uuid, null, 'Hake with salsa verde, new potatoes and asparagus', 'seed', null, 'Claude', '/recipe-photos/hake-with-salsa-verde-new-potatoes-and-asparagus.webp', '/recipe-photos/hake-with-salsa-verde-new-potatoes-and-asparagus.webp',
    2, null, 35, 15, 20, '["Cover the potatoes with cold salted water in a pot, bring to the boil and simmer 15 min; add the asparagus for the last 3 min. Drain.","For the salsa verde, mix the parsley, mint, capers, anchovies, mustard, vinegar and 2 tbsp of the oil with a little pepper; loosen with a spoon of water if needed.","Pat the hake dry and season it. Heat the rest of the oil in a non-stick pan over medium-high heat and fry the hake skin-side down for 4 min, pressing it flat for the first few seconds, until the skin is crisp.","Turn the fish and cook 1-2 min more, until it just flakes; squeeze over the lemon.","Toss the potatoes and asparagus with a spoonful of the salsa verde.","Serve the hake on the potatoes and asparagus with the rest of the salsa verde spooned over."]'::jsonb,
    array['italian', 'mediterranean', 'healthy', 'high protein']::text[], 'italian', 556, 40.5,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Merlu sauce verte, pommes de terre nouvelles et asperges","steps":["Couvrir les pommes de terre d''eau froide salée dans une casserole, porter à ébullition et cuire 15 min ; ajouter les asperges pour les 3 dernières minutes. Égoutter.","Pour la sauce verte, mélanger le persil, la menthe, les câpres, les anchois, la moutarde, le vinaigre et 2 c. à soupe d''huile avec un peu de poivre ; détendre d''une cuillerée d''eau si besoin.","Sécher le merlu et l''assaisonner. Chauffer le reste d''huile dans une poêle antiadhésive à feu moyen-vif et cuire le merlu côté peau 4 min en l''aplatissant les premières secondes, jusqu''à ce que la peau soit croustillante.","Retourner le poisson et cuire 1 à 2 min de plus, jusqu''à ce qu''il s''effeuille tout juste ; arroser de jus de citron.","Mélanger les pommes de terre et les asperges avec une cuillerée de sauce verte.","Servir le merlu sur les pommes de terre et les asperges, nappé du reste de sauce verte."]},"it":{"title":"Nasello con salsa verde, patate novelle e asparagi","steps":["Coprire le patate con acqua fredda salata in una pentola, portare a bollore e cuocere 15 min; aggiungere gli asparagi negli ultimi 3 min. Scolare.","Per la salsa verde, mescolare prezzemolo, menta, capperi, acciughe, senape, aceto e 2 cucchiai d''olio con un po'' di pepe; allungare con un cucchiaio d''acqua se serve.","Asciugare il nasello e condirlo. Scaldare il resto dell''olio in una padella antiaderente a fuoco medio-alto e cuocere il nasello dal lato della pelle per 4 min, premendolo i primi secondi, finché la pelle è croccante.","Girare il pesce e cuocere ancora 1-2 min, finché si sfalda appena; spremere sopra il limone.","Condire patate e asparagi con una cucchiaiata di salsa verde.","Servire il nasello su patate e asparagi con il resto della salsa verde sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8d8e85d0-95ef-45dc-b599-bcb0846aed0a')
  returning id
)
