-- Black pepper prawn noodles with mangetout
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a41c4225-ba5e-410f-83b8-44767b52d719'::uuid, null, 'Black pepper prawn noodles with mangetout', 'seed', null, 'Claude', '/recipe-photos/black-pepper-prawn-noodles-with-mangetout.webp', '/recipe-photos/black-pepper-prawn-noodles-with-mangetout.webp',
    2, null, 20, 10, 10, '["Cook the noodles in boiling water as the packet says, drain and rinse briefly so they don''t clump.","Mix the oyster sauce, soy sauce, sugar, black pepper and cornstarch with 4 tbsp water.","Heat the oil in a wok over high heat and stir-fry the prawns 2 min, until pink on both sides; lift them out.","Add the butter, garlic, ginger and the white part of the spring onions and stir 30 seconds until fragrant.","Add the mangetout and pepper and stir-fry 2 min, until bright but still crisp.","Return the prawns with the noodles and the sauce and toss 1-2 min, until everything is glossy and the prawns are cooked through.","Stir in the green spring onion and serve straight away."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'high protein', 'quick']::text[], 'chinese', 665, 48.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Nouilles sautées aux crevettes et au poivre noir, pois gourmands","steps":["Cuire les nouilles dans l''eau bouillante selon le paquet, les égoutter et les rincer rapidement pour qu''elles ne collent pas.","Mélanger la sauce d''huître, la sauce soja, le sucre, le poivre noir et la fécule avec 4 c. à soupe d''eau.","Chauffer l''huile dans un wok à feu vif et faire sauter les crevettes 2 min, jusqu''à ce qu''elles soient roses des deux côtés ; les retirer.","Ajouter le beurre, l''ail, le gingembre et le blanc des oignons nouveaux et remuer 30 secondes jusqu''à ce que ça embaume.","Ajouter les pois gourmands et le poivron et faire sauter 2 min, jusqu''à ce qu''ils soient bien verts mais encore croquants.","Remettre les crevettes avec les nouilles et la sauce et mélanger 1 à 2 min, jusqu''à ce que tout soit brillant et les crevettes cuites.","Ajouter le vert des oignons nouveaux et servir aussitôt."]},"it":{"title":"Noodles saltati con gamberi al pepe nero e taccole","steps":["Cuocere i noodles in acqua bollente come indicato sulla confezione, scolarli e sciacquarli brevemente perché non si attacchino.","Mescolare salsa d''ostriche, salsa di soia, zucchero, pepe nero e amido con 4 cucchiai d''acqua.","Scaldare l''olio in un wok a fuoco vivo e saltare i gamberi 2 min, finché sono rosa su entrambi i lati; toglierli.","Aggiungere il burro, l''aglio, lo zenzero e la parte bianca dei cipollotti e mescolare 30 secondi finché profumano.","Aggiungere taccole e peperone e saltare 2 min, finché sono brillanti ma ancora croccanti.","Rimettere i gamberi con i noodles e la salsa e saltare 1-2 min, finché tutto è lucido e i gamberi sono cotti.","Unire la parte verde dei cipollotti e servire subito."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a41c4225-ba5e-410f-83b8-44767b52d719')
  returning id
)
