-- Satay prawn noodles with pak choi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e734e3d4-55e6-4745-a4e1-23a64efe8e9e'::uuid, null, 'Satay prawn noodles with pak choi', 'seed', null, 'Claude', '/recipe-photos/satay-prawn-noodles-with-pak-choi.webp', '/recipe-photos/satay-prawn-noodles-with-pak-choi.webp',
    2, null, 22, 10, 12, '["Soak or boil the rice noodles as the packet says, then drain.","Whisk the peanut butter, coconut milk, soy sauce, lime juice, honey and curry powder into a smooth sauce.","Heat the oil in a wok over high heat, add the garlic, ginger, carrot and pak choi stems and stir-fry 2 min.","Add the prawns and stir-fry 2-3 min, until they turn pink.","Pour in the sauce and the pak choi leaves and bubble 1 min, until the leaves wilt; loosen with a splash of water if thick.","Toss in the noodles until coated and hot, then serve with the chilli and coriander."]'::jsonb,
    array['malaysian', 'asian', 'stir-fry', 'high protein', 'quick']::text[], 'malaysian', 732, 50.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Nouilles sautées aux crevettes sauce satay et pak choï","steps":["Faire tremper ou cuire les nouilles de riz selon le paquet, puis les égoutter.","Fouetter le beurre de cacahuète, le lait de coco, la sauce soja, le jus de citron vert, le miel et le curry en une sauce lisse.","Chauffer l''huile dans un wok à feu vif, ajouter l''ail, le gingembre, la carotte et les tiges de pak choï et faire sauter 2 min.","Ajouter les crevettes et faire sauter 2 à 3 min, jusqu''à ce qu''elles deviennent roses.","Verser la sauce et les feuilles de pak choï et laisser bouillonner 1 min, jusqu''à ce que les feuilles tombent ; détendre d''un peu d''eau si c''est épais.","Ajouter les nouilles et mélanger jusqu''à ce qu''elles soient enrobées et chaudes, puis servir avec le piment et la coriandre."]},"it":{"title":"Noodles con gamberi in salsa satay e pak choi","steps":["Ammollare o lessare i noodles di riso come indicato sulla confezione, poi scolarli.","Sbattere burro di arachidi, latte di cocco, salsa di soia, succo di lime, miele e curry fino a ottenere una salsa liscia.","Scaldare l''olio in un wok a fuoco vivo, aggiungere aglio, zenzero, carota e gambi di pak choi e saltare 2 min.","Aggiungere i gamberi e saltare 2-3 min, finché diventano rosa.","Versare la salsa e le foglie di pak choi e far bollire 1 min, finché le foglie appassiscono; allungare con un goccio d''acqua se è densa.","Unire i noodles e mescolare finché sono ben conditi e caldi, poi servire con peperoncino e coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e734e3d4-55e6-4745-a4e1-23a64efe8e9e')
  returning id
)
