-- Air-fryer sweet chilli tofu with noodles and peppers
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ee123b44-5c1b-473b-ac0c-bd5f9c59c493'::uuid, null, 'Air-fryer sweet chilli tofu with noodles and peppers', 'seed', null, 'Claude', '/recipe-photos/air-fryer-sweet-chilli-tofu-with-noodles-and-peppers.webp', '/recipe-photos/air-fryer-sweet-chilli-tofu-with-noodles-and-peppers.webp',
    2, null, 33, 15, 18, '["Pat the tofu dry, toss it with 1 tsp of the oil and a pinch of salt, then with the cornstarch until coated.","Heat the air fryer to 200°C and air-fry the tofu 15 min, shaking twice, until golden and crisp.","Meanwhile, cook the noodles as the packet says, drain and rinse briefly.","Mix the sweet chilli sauce, soy sauce, lime juice and garlic.","Heat the rest of the oil in a wok over high heat and stir-fry the peppers and white spring onion 3 min, until just tender.","Add the noodles and half the sauce and toss 1 min; toss the hot tofu with the rest of the sauce.","Serve the noodles topped with the tofu, green spring onion, sesame seeds and coriander."]'::jsonb,
    array['thai', 'asian', 'vegan', 'stir-fry', 'high protein']::text[], 'thai', 838, 39.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Tofu sauce chili douce au air fryer, nouilles et poivrons","steps":["Sécher le tofu, le mélanger avec 1 c. à café d''huile et une pincée de sel, puis avec la fécule jusqu''à ce qu''il soit enrobé.","Préchauffer le air fryer à 200 °C et cuire le tofu 15 min en secouant deux fois, jusqu''à ce qu''il soit doré et croustillant.","Pendant ce temps, cuire les nouilles selon le paquet, les égoutter et les rincer rapidement.","Mélanger la sauce chili douce, la sauce soja, le jus de citron vert et l''ail.","Chauffer le reste d''huile dans un wok à feu vif et faire sauter les poivrons et le blanc des oignons nouveaux 3 min, jusqu''à ce qu''ils soient juste tendres.","Ajouter les nouilles et la moitié de la sauce et mélanger 1 min ; enrober le tofu chaud du reste de sauce.","Servir les nouilles garnies de tofu, de vert d''oignon nouveau, de sésame et de coriandre."]},"it":{"title":"Tofu alla salsa chili dolce in friggitrice ad aria con noodles e peperoni","steps":["Asciugare il tofu, condirlo con 1 cucchiaino d''olio e un pizzico di sale, poi con l''amido finché è ricoperto.","Scaldare la friggitrice ad aria a 200 °C e cuocere il tofu 15 min, scuotendo due volte, finché è dorato e croccante.","Intanto cuocere i noodles come indicato sulla confezione, scolarli e sciacquarli brevemente.","Mescolare salsa chili dolce, salsa di soia, succo di lime e aglio.","Scaldare il resto dell''olio in un wok a fuoco vivo e saltare i peperoni e la parte bianca dei cipollotti 3 min, finché sono appena teneri.","Aggiungere i noodles e metà della salsa e saltare 1 min; condire il tofu caldo con il resto della salsa.","Servire i noodles con sopra il tofu, la parte verde dei cipollotti, sesamo e coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ee123b44-5c1b-473b-ac0c-bd5f9c59c493')
  returning id
)
