-- Tahini-lemon tofu with roast squash and quinoa
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5eed3550-e582-4410-9023-f70fde4cac4f'::uuid, null, 'Tahini-lemon tofu with roast squash and quinoa', 'seed', null, 'Claude', '/recipe-photos/tahini-lemon-tofu-with-roast-squash-and-quinoa.webp', '/recipe-photos/tahini-lemon-tofu-with-roast-squash-and-quinoa.webp',
    2, null, 43, 15, 28, '["Heat the oven to 220°C. Toss the squash with 2 tsp of the oil, half the cumin and paprika and a pinch of salt, spread it on a large tray and roast 10 min.","Toss the tofu with the rest of the oil and spices and a pinch of salt, add it to the tray and roast 15-18 min more, turning once, until the squash is soft and browned and the tofu golden.","Meanwhile, simmer the quinoa covered in 280 ml salted water for 12-15 min, until the water is absorbed; rest it 5 min.","Whisk the tahini with the lemon juice, garlic, maple syrup, a pinch of salt and 2-3 tbsp water into a pourable sauce.","Stir the spinach into the hot quinoa so it wilts, then the parsley.","Serve the quinoa topped with the squash and tofu and drizzled with the tahini-lemon sauce."]'::jsonb,
    array['middle eastern', 'vegan', 'healthy', 'oven', 'gluten-free']::text[], 'middle eastern', 878, 48.1,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tofu sauce tahini-citron, courge rôtie et quinoa","steps":["Préchauffer le four à 220 °C. Mélanger la courge avec 2 c. à café d''huile, la moitié du cumin et du paprika et une pincée de sel, l''étaler sur une grande plaque et rôtir 10 min.","Mélanger le tofu avec le reste d''huile et d''épices et une pincée de sel, l''ajouter sur la plaque et rôtir encore 15 à 18 min en retournant une fois, jusqu''à ce que la courge soit tendre et dorée et le tofu bien doré.","Pendant ce temps, cuire le quinoa à couvert dans 280 ml d''eau salée 12 à 15 min, jusqu''à absorption ; le laisser reposer 5 min.","Fouetter le tahini avec le jus de citron, l''ail, le sirop d''érable, une pincée de sel et 2 à 3 c. à soupe d''eau en une sauce fluide.","Incorporer les épinards au quinoa chaud pour qu''ils tombent, puis le persil.","Servir le quinoa garni de courge et de tofu, arrosé de sauce tahini-citron."]},"it":{"title":"Tofu con salsa tahina e limone, zucca arrosto e quinoa","steps":["Scaldare il forno a 220 °C. Condire la zucca con 2 cucchiaini d''olio, metà del cumino e della paprika e un pizzico di sale, stenderla su una grande teglia e arrostire 10 min.","Condire il tofu con il resto dell''olio e delle spezie e un pizzico di sale, aggiungerlo alla teglia e arrostire altri 15-18 min, girando una volta, finché la zucca è morbida e dorata e il tofu ben dorato.","Intanto cuocere la quinoa coperta in 280 ml d''acqua salata per 12-15 min, finché l''acqua è assorbita; lasciarla riposare 5 min.","Sbattere la tahina con succo di limone, aglio, sciroppo d''acero, un pizzico di sale e 2-3 cucchiai d''acqua fino a ottenere una salsa fluida.","Unire gli spinaci alla quinoa calda perché appassiscano, poi il prezzemolo.","Servire la quinoa con sopra zucca e tofu e la salsa tahina e limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5eed3550-e582-4410-9023-f70fde4cac4f')
  returning id
)
