-- Air-fryer halloumi with chickpea couscous and tahini-lemon
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'cdbeba47-7c9a-4b38-b153-1ef98c28b768'::uuid, null, 'Air-fryer halloumi with chickpea couscous and tahini-lemon', 'seed', null, 'Claude', '/recipe-photos/air-fryer-halloumi-with-chickpea-couscous-and-tahini-lemon.webp', '/recipe-photos/air-fryer-halloumi-with-chickpea-couscous-and-tahini-lemon.webp',
    2, null, 25, 10, 15, '["Heat the air fryer to 200°C. Toss the chickpeas and pepper with 2 tsp of the oil, the cumin, paprika and a pinch of salt and air-fry 8 min, shaking halfway.","Lay the halloumi slices on top and air-fry 6-7 min more, until the halloumi is golden at the edges and the chickpeas are crisp.","Meanwhile, bring the stock to the boil in a saucepan, stir in the couscous and the lemon zest, cover off the heat and leave 5 min.","Whisk the tahini with half the lemon juice, the garlic, a pinch of salt and 2-3 tbsp water into a pourable sauce.","Fluff the couscous with a fork and stir in the cucumber, herbs, the rest of the lemon juice and oil, and the chickpeas and pepper.","Serve the couscous topped with the halloumi and drizzled with the tahini-lemon sauce."]'::jsonb,
    array['mediterranean', 'middle eastern', 'vegetarian', 'healthy', 'high protein', 'quick']::text[], 'mediterranean', 874, 40.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Halloumi au air fryer, semoule aux pois chiches et sauce tahini-citron","steps":["Préchauffer le air fryer à 200 °C. Mélanger les pois chiches et le poivron avec 2 c. à café d''huile, le cumin, le paprika et une pincée de sel et cuire 8 min en secouant à mi-cuisson.","Poser les tranches d''halloumi dessus et cuire encore 6 à 7 min, jusqu''à ce que l''halloumi soit doré sur les bords et les pois chiches croustillants.","Pendant ce temps, porter le bouillon à ébullition dans une casserole, ajouter la semoule et le zeste de citron, couvrir hors du feu et laisser gonfler 5 min.","Fouetter le tahini avec la moitié du jus de citron, l''ail, une pincée de sel et 2 à 3 c. à soupe d''eau en une sauce fluide.","Égrener la semoule à la fourchette et y mélanger le concombre, les herbes, le reste du jus de citron et d''huile, puis les pois chiches et le poivron.","Servir la semoule garnie d''halloumi et arrosée de sauce tahini-citron."]},"it":{"title":"Halloumi in friggitrice ad aria con cous cous ai ceci e salsa tahina e limone","steps":["Scaldare la friggitrice ad aria a 200 °C. Condire ceci e peperone con 2 cucchiaini d''olio, cumino, paprika e un pizzico di sale e cuocere 8 min, scuotendo a metà.","Adagiare sopra le fette di halloumi e cuocere altri 6-7 min, finché l''halloumi è dorato ai bordi e i ceci croccanti.","Intanto portare a bollore il brodo in una casseruola, versare il cous cous e la scorza di limone, coprire fuori dal fuoco e lasciare 5 min.","Sbattere la tahina con metà del succo di limone, l''aglio, un pizzico di sale e 2-3 cucchiai d''acqua fino a ottenere una salsa fluida.","Sgranare il cous cous con una forchetta e unire cetriolo, erbe, il resto del succo di limone e dell''olio, poi ceci e peperone.","Servire il cous cous con sopra l''halloumi e la salsa tahina e limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'cdbeba47-7c9a-4b38-b153-1ef98c28b768')
  returning id
)
