-- Air-fryer chicken yakitori rice bowls with green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '63e8ac66-626b-56dc-ad74-a1f52919bee4'::uuid, null, 'Air-fryer chicken yakitori rice bowls with green beans', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chicken-yakitori-rice-bowls-with-green-beans.webp', '/recipe-photos/air-fryer-chicken-yakitori-rice-bowls-with-green-beans.webp',
    2, null, 30, 10, 20, '["Rinse the rice, put it in a pot with 210 ml water, bring to the boil, cover and cook on low heat for 12 min, then rest off the heat with the lid on.","Boil the green beans in a small pan of salted water for 4 min, drain and keep warm.","In the same small pan, simmer the soy sauce, mirin, sake and sugar for 3–4 min until syrupy; this is the tare.","Thread the chicken and spring onion alternately onto short skewers that fit the basket and brush with the oil.","Air-fry at 190°C for 6 min, brush with tare, turn, brush again and cook 5–6 min more, until glossy and 75°C in the centre.","Spoon the rice into bowls, add the beans and skewers, drizzle over the rest of the tare and finish with sesame seeds and chilli."]'::jsonb,
    array['japanese', 'asian', 'bowl', 'healthy', 'high protein']::text[], 'japanese', 635, 45.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Bols de riz au poulet yakitori à l''air fryer et haricots verts","steps":["Rincer le riz, le mettre dans une casserole avec 210 ml d''eau, porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer hors du feu à couvert.","Cuire les haricots verts 4 min dans une petite casserole d''eau salée bouillante, égoutter et réserver au chaud.","Dans la même petite casserole, faire frémir la sauce soja, le mirin, le saké et le sucre 3 à 4 min jusqu''à consistance sirupeuse : c''est la sauce tare.","Enfiler le poulet et l''oignon nouveau en alternance sur de petites brochettes adaptées au panier et les badigeonner d''huile.","Cuire à l''air fryer à 190 °C pendant 6 min, badigeonner de tare, retourner, badigeonner à nouveau et cuire encore 5 à 6 min, jusqu''à ce que ce soit laqué et à 75 °C à cœur.","Répartir le riz dans des bols, ajouter les haricots et les brochettes, arroser du reste de tare et finir avec les graines de sésame et le piment."]},"it":{"title":"Ciotole di riso con pollo yakitori in friggitrice ad aria e fagiolini","steps":["Sciacquare il riso, metterlo in una pentola con 210 ml d''acqua, portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare coperto fuori dal fuoco.","Lessare i fagiolini 4 min in un pentolino d''acqua salata, scolarli e tenerli al caldo.","Nello stesso pentolino far sobbollire salsa di soia, mirin, sake e zucchero per 3–4 min finché diventa sciropposa: è la salsa tare.","Infilare pollo e cipollotto alternati su spiedini corti adatti al cestello e spennellarli con l''olio.","Cuocere in friggitrice ad aria a 190 °C per 6 min, spennellare con la tare, girare, spennellare di nuovo e cuocere altri 5–6 min, finché sono lucidi e a 75 °C al cuore.","Distribuire il riso nelle ciotole, aggiungere fagiolini e spiedini, irrorare con il resto della tare e finire con sesamo e peperoncino."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '63e8ac66-626b-56dc-ad74-a1f52919bee4')
  returning id
)
