-- Air-fryer chermoula chicken with tomato and cucumber couscous
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '43a904db-41c6-56c6-9efe-ee6b7ae30125'::uuid, null, 'Air-fryer chermoula chicken with tomato and cucumber couscous', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chermoula-chicken-with-tomato-and-cucumber-couscous.webp', '/recipe-photos/air-fryer-chermoula-chicken-with-tomato-and-cucumber-couscous.webp',
    2, null, 28, 12, 16, '["Make the chermoula: mix the parsley, coriander, garlic, cumin, paprika, chilli flakes, lemon zest, half the lemon juice, 1 tbsp olive oil and a pinch of salt.","Halve the chicken fillets horizontally into thinner steaks and rub them with two-thirds of the chermoula.","Air-fry at 200°C for 12–15 min, turning halfway, until charred at the edges and 75°C in the thickest part.","Meanwhile pour the hot stock over the couscous in a pot off the heat, cover and leave 5 min.","Fluff the couscous with a fork and stir in the tomato, cucumber, red onion, the rest of the lemon juice and oil.","Stir the remaining chermoula into the yogurt.","Slice the chicken and serve it on the couscous with the chermoula yogurt."]'::jsonb,
    array['north african', 'moroccan', 'healthy', 'high protein', 'bowl']::text[], 'north african', 684, 52.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet à la chermoula à l''air fryer, semoule à la tomate et au concombre","steps":["Préparer la chermoula : mélanger le persil, la coriandre, l''ail, le cumin, le paprika, le piment, le zeste de citron, la moitié du jus, 1 c. à soupe d''huile d''olive et une pincée de sel.","Couper les filets de poulet en deux dans l''épaisseur et les frotter avec les deux tiers de la chermoula.","Cuire à l''air fryer à 200 °C pendant 12 à 15 min en retournant à mi-cuisson, jusqu''à ce que les bords soient grillés et à 75 °C au plus épais.","Pendant ce temps, verser le bouillon chaud sur la semoule dans une casserole hors du feu, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette et incorporer la tomate, le concombre, l''oignon rouge, le reste du jus de citron et de l''huile.","Mélanger le reste de chermoula avec le yaourt.","Trancher le poulet et le servir sur la semoule avec le yaourt à la chermoula."]},"it":{"title":"Pollo alla chermoula in friggitrice ad aria con cous cous di pomodoro e cetriolo","steps":["Preparare la chermoula: mescolare prezzemolo, coriandolo, aglio, cumino, paprica, peperoncino, scorza di limone, metà del succo, 1 cucchiaio d''olio d''oliva e un pizzico di sale.","Tagliare i filetti di pollo a metà nello spessore e massaggiarli con due terzi della chermoula.","Cuocere in friggitrice ad aria a 200 °C per 12–15 min, girando a metà, finché i bordi sono abbrustoliti e il cuore è a 75 °C.","Nel frattempo versare il brodo caldo sul cous cous in una pentola fuori dal fuoco, coprire e lasciar riposare 5 min.","Sgranare il cous cous con la forchetta e unire pomodoro, cetriolo, cipolla rossa, il resto del succo di limone e dell''olio.","Mescolare la chermoula rimasta con lo yogurt.","Affettare il pollo e servirlo sul cous cous con lo yogurt alla chermoula."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '43a904db-41c6-56c6-9efe-ee6b7ae30125')
  returning id
)
