-- Penne arrabbiata with chicken and courgette
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c7c319b4-d176-59d8-9705-957d1456be40'::uuid, null, 'Penne arrabbiata with chicken and courgette', 'seed', null, 'Claude', '/recipe-photos/penne-arrabbiata-with-chicken-and-courgette.webp', '/recipe-photos/penne-arrabbiata-with-chicken-and-courgette.webp',
    2, null, 28, 8, 20, '["Bring a large pot of salted water to the boil for the penne.","Heat the oil in a large frying pan over medium-high heat, season the chicken and brown it for 4–5 min until golden; lift out.","Add the courgette to the pan and cook 3 min, then add the garlic and chilli flakes for 1 min without letting the garlic brown.","Stir in the tomatoes and tomato paste, return the chicken and simmer for 10 min until the sauce thickens.","Meanwhile cook the penne until al dente, about 10–11 min, and keep a cup of the water.","Drain the penne and toss them in the sauce with a splash of the water until glossy; serve with basil and a little parmesan."]'::jsonb,
    array['italian', 'spicy', 'healthy', 'high protein']::text[], 'italian', 649, 50.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Penne all''arrabbiata au poulet et à la courgette","steps":["Porter à ébullition une grande casserole d''eau salée pour les penne.","Chauffer l''huile dans une grande poêle à feu moyen-vif, assaisonner le poulet et le dorer 4 à 5 min ; le retirer.","Mettre la courgette dans la poêle et cuire 3 min, puis ajouter l''ail et le piment 1 min sans laisser l''ail colorer.","Ajouter les tomates et le concentré, remettre le poulet et laisser mijoter 10 min jusqu''à ce que la sauce épaississe.","Pendant ce temps, cuire les penne al dente, 10 à 11 min environ, et garder une tasse d''eau de cuisson.","Égoutter les penne et les mélanger à la sauce avec un peu d''eau de cuisson jusqu''à ce qu''elles soient nappées ; servir avec le basilic et un peu de parmesan."]},"it":{"title":"Penne all''arrabbiata con pollo e zucchina","steps":["Portare a bollore una pentola capiente d''acqua salata per le penne.","Scaldare l''olio in una padella grande a fuoco medio-alto, condire il pollo e rosolarlo per 4–5 min finché è dorato; toglierlo.","Mettere la zucchina nella padella e cuocere 3 min, poi unire aglio e peperoncino per 1 min senza far scurire l''aglio.","Unire i pomodori e il concentrato, rimettere il pollo e cuocere a fuoco dolce 10 min finché il sugo si addensa.","Nel frattempo cuocere le penne al dente, circa 10–11 min, e tenere da parte una tazza d''acqua di cottura.","Scolare le penne e saltarle nel sugo con un goccio d''acqua di cottura finché sono lucide; servire con basilico e poco parmigiano."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c7c319b4-d176-59d8-9705-957d1456be40')
  returning id
)
