-- Air-fryer chipotle chicken tacos with charred corn and cabbage slaw
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8ab64d4f-2865-591c-a2ca-1d6d643e0ad1'::uuid, null, 'Air-fryer chipotle chicken tacos with charred corn and cabbage slaw', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chipotle-chicken-tacos-with-charred-corn-and-cabbage-slaw.webp', '/recipe-photos/air-fryer-chipotle-chicken-tacos-with-charred-corn-and-cabbage-slaw.webp',
    2, null, 27, 12, 15, '["Mix the chipotle paste, garlic, cumin, oregano, the juice of half a lime, the oil and a pinch of salt; toss the chicken in it.","Air-fry the chicken at 200°C for 10–12 min, shaking halfway, until lightly charred and cooked through.","Meanwhile toss the cabbage and red onion with the juice of 1 lime and a pinch of salt.","Char the corn in a dry frying pan over high heat for 4–5 min, stirring now and then; tip it out.","Warm the tortillas in the same pan for 20–30 seconds a side.","Fill the tortillas with slaw, chicken and corn, add a spoonful of yogurt, coriander and the last lime in wedges."]'::jsonb,
    array['mexican', 'street food', 'spicy', 'healthy', 'high protein']::text[], 'mexican', 650, 52.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Tacos au poulet chipotle à l''air fryer, maïs grillé et salade de chou","steps":["Mélanger la pâte de chipotle, l''ail, le cumin, l''origan, le jus d''un demi-citron vert, l''huile et une pincée de sel ; y enrober le poulet.","Cuire le poulet à l''air fryer à 200 °C pendant 10 à 12 min en secouant à mi-cuisson, jusqu''à ce qu''il soit légèrement grillé et cuit.","Pendant ce temps, mélanger le chou et l''oignon rouge avec le jus d''un citron vert et une pincée de sel.","Faire griller le maïs dans une poêle sèche à feu vif 4 à 5 min en remuant de temps en temps ; le réserver.","Réchauffer les tortillas dans la même poêle 20 à 30 secondes de chaque côté.","Garnir les tortillas de salade de chou, de poulet et de maïs, ajouter une cuillerée de yaourt, la coriandre et le dernier citron vert en quartiers."]},"it":{"title":"Tacos di pollo al chipotle in friggitrice ad aria con mais abbrustolito e insalata di cavolo","steps":["Mescolare pasta di chipotle, aglio, cumino, origano, il succo di mezzo lime, l''olio e un pizzico di sale; condire il pollo.","Cuocere il pollo in friggitrice ad aria a 200 °C per 10–12 min, scuotendo a metà, finché è leggermente abbrustolito e cotto.","Nel frattempo condire cavolo e cipolla rossa con il succo di un lime e un pizzico di sale.","Abbrustolire il mais in una padella asciutta a fuoco vivo per 4–5 min, mescolando ogni tanto; tenerlo da parte.","Scaldare le tortillas nella stessa padella per 20–30 secondi per lato.","Farcire le tortillas con insalata di cavolo, pollo e mais, aggiungere un cucchiaio di yogurt, coriandolo e l''ultimo lime a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8ab64d4f-2865-591c-a2ca-1d6d643e0ad1')
  returning id
)
