-- Air-fryer chicken pinchos morunos with new potatoes and pepper salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '149d32ed-4e91-5b66-b0fe-145e8bd1f1f5'::uuid, null, 'Air-fryer chicken pinchos morunos with new potatoes and pepper salad', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chicken-pinchos-morunos-with-new-potatoes-and-pepper-salad.webp', '/recipe-photos/air-fryer-chicken-pinchos-morunos-with-new-potatoes-and-pepper-salad.webp',
    2, null, 30, 12, 18, '["Cook the potatoes in a pot of salted boiling water for 15–18 min until tender; drain.","Meanwhile mix the cumin, smoked paprika, coriander, thyme, garlic, half the lemon juice, 1 tbsp olive oil and a good pinch of salt; toss the chicken in it.","Thread the chicken onto short skewers that fit the basket.","Air-fry at 190°C for 12–14 min, turning halfway, until browned and cooked through.","For the salad, toss the pepper, tomato and red onion with the vinegar, the rest of the oil and a pinch of salt.","Toss the warm potatoes with the parsley and the rest of the lemon juice, and serve with the skewers and salad."]'::jsonb,
    array['spanish', 'mediterranean', 'grill', 'healthy', 'high protein']::text[], 'spanish', 609, 45,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Pinchos morunos de poulet à l''air fryer, pommes de terre nouvelles et salade de poivrons","steps":["Cuire les pommes de terre 15 à 18 min dans une casserole d''eau salée bouillante jusqu''à ce qu''elles soient tendres ; égoutter.","Pendant ce temps, mélanger le cumin, le paprika fumé, la coriandre, le thym, l''ail, la moitié du jus de citron, 1 c. à soupe d''huile et une bonne pincée de sel ; y enrober le poulet.","Enfiler le poulet sur de petites brochettes adaptées au panier.","Cuire à l''air fryer à 190 °C pendant 12 à 14 min en retournant à mi-cuisson, jusqu''à ce qu''ils soient dorés et cuits.","Pour la salade, mélanger le poivron, la tomate et l''oignon rouge avec le vinaigre, le reste de l''huile et une pincée de sel.","Mélanger les pommes de terre chaudes avec le persil et le reste du jus de citron, et servir avec les brochettes et la salade."]},"it":{"title":"Pinchos morunos di pollo in friggitrice ad aria con patate novelle e insalata di peperoni","steps":["Lessare le patate in una pentola d''acqua salata per 15–18 min finché sono tenere; scolarle.","Nel frattempo mescolare cumino, paprica affumicata, coriandolo, timo, aglio, metà del succo di limone, 1 cucchiaio d''olio e un buon pizzico di sale; condire il pollo.","Infilare il pollo su spiedini corti adatti al cestello.","Cuocere in friggitrice ad aria a 190 °C per 12–14 min, girando a metà, finché sono dorati e cotti.","Per l''insalata condire peperone, pomodoro e cipolla rossa con l''aceto, il resto dell''olio e un pizzico di sale.","Condire le patate calde con prezzemolo e il resto del succo di limone e servirle con gli spiedini e l''insalata."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '149d32ed-4e91-5b66-b0fe-145e8bd1f1f5')
  returning id
)
