-- Pad prik khing with chicken, green beans and jasmine rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c18003ce-3b5d-56be-acc1-86393d87785b'::uuid, null, 'Pad prik khing with chicken, green beans and jasmine rice', 'seed', null, 'Claude', '/recipe-photos/pad-prik-khing-with-chicken-green-beans-and-jasmine-rice.webp', '/recipe-photos/pad-prik-khing-with-chicken-green-beans-and-jasmine-rice.webp',
    2, null, 25, 10, 15, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min, then rest 5 min with the lid on.","Heat the oil in a wok over medium heat and fry the curry paste for 1 min, stirring, until fragrant.","Turn the heat up, add the chicken and stir-fry 3 min until it turns white all over.","Add the green beans and 3 tbsp water and stir-fry 4–5 min until the beans are tender-crisp and the chicken is cooked.","Season with the fish sauce and sugar, toss in the lime leaves and cook 30 seconds more.","Serve over the jasmine rice with sliced chilli if you like more heat."]'::jsonb,
    array['thai', 'asian', 'stir-fry', 'spicy', 'healthy', 'high protein', 'quick']::text[], 'thai', 601, 44.5,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pad prik khing au poulet, haricots verts et riz jasmin","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis laisser reposer 5 min à couvert.","Chauffer l''huile dans un wok à feu moyen et faire revenir la pâte de curry 1 min en remuant jusqu''à ce qu''elle embaume.","Monter le feu, ajouter le poulet et le faire sauter 3 min jusqu''à ce qu''il soit blanc partout.","Ajouter les haricots verts et 3 c. à soupe d''eau et faire sauter 4 à 5 min jusqu''à ce que les haricots soient tendres mais croquants et le poulet cuit.","Assaisonner avec la sauce poisson et le sucre, ajouter les feuilles de combava et cuire encore 30 secondes.","Servir sur le riz jasmin avec le piment émincé pour plus de piquant."]},"it":{"title":"Pad prik khing con pollo, fagiolini e riso jasmine","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min coperto.","Scaldare l''olio in un wok a fuoco medio e soffriggere la pasta di curry per 1 min, mescolando, finché profuma.","Alzare la fiamma, unire il pollo e saltarlo 3 min finché è bianco ovunque.","Unire i fagiolini e 3 cucchiai d''acqua e saltare 4–5 min finché i fagiolini sono teneri ma croccanti e il pollo è cotto.","Condire con salsa di pesce e zucchero, unire le foglie di lime kaffir e cuocere ancora 30 secondi.","Servire sul riso jasmine con il peperoncino a fettine per chi lo vuole più piccante."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c18003ce-3b5d-56be-acc1-86393d87785b')
  returning id
)
