-- Air-fryer achari chicken with naan and kachumber
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '03cda661-245c-51fc-9d5e-8eb63aae54ee'::uuid, null, 'Air-fryer achari chicken with naan and kachumber', 'seed', null, 'Claude', '/recipe-photos/air-fryer-achari-chicken-with-naan-and-kachumber.webp', '/recipe-photos/air-fryer-achari-chicken-with-naan-and-kachumber.webp',
    2, null, 29, 15, 14, '["Toast the mustard, fennel and nigella seeds in a dry small pan for 1 min until they pop, then crush them roughly.","Mix the crushed seeds with the cumin, chilli powder, turmeric, garlic, ginger, yogurt, half the lemon juice and a good pinch of salt.","Coat the chicken in the achari yogurt and spread it in one layer in the air-fryer basket.","Air-fry at 200°C for 12–14 min, shaking halfway, until charred at the edges and cooked through.","Meanwhile make the kachumber: toss the cucumber, tomato, red onion, coriander and mint with the rest of the lemon juice and a pinch of salt.","Warm the naan in the air fryer for the last 2 min, then serve with the chicken and the kachumber."]'::jsonb,
    array['indian', 'spicy', 'healthy', 'high protein']::text[], 'indian', 687, 45.7,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet achari à l''air fryer, naan et kachumber","steps":["Torréfier les graines de moutarde, de fenouil et de nigelle 1 min à sec dans une petite poêle jusqu''à ce qu''elles crépitent, puis les concasser grossièrement.","Mélanger les graines concassées avec le cumin, le piment en poudre, le curcuma, l''ail, le gingembre, le yaourt, la moitié du jus de citron et une bonne pincée de sel.","Enrober le poulet du yaourt achari et l''étaler en une seule couche dans le panier de l''air fryer.","Cuire à l''air fryer à 200 °C pendant 12 à 14 min en secouant à mi-cuisson, jusqu''à ce que les bords soient grillés et la viande cuite.","Pendant ce temps, préparer le kachumber : mélanger le concombre, la tomate, l''oignon rouge, la coriandre et la menthe avec le reste du jus de citron et une pincée de sel.","Réchauffer les naans dans l''air fryer les 2 dernières minutes, puis servir avec le poulet et le kachumber."]},"it":{"title":"Pollo achari in friggitrice ad aria con naan e kachumber","steps":["Tostare i semi di senape, finocchio e nigella in un padellino asciutto per 1 min finché scoppiettano, poi pestarli grossolanamente.","Mescolare i semi pestati con cumino, peperoncino in polvere, curcuma, aglio, zenzero, yogurt, metà del succo di limone e un buon pizzico di sale.","Ricoprire il pollo con lo yogurt achari e disporlo in un solo strato nel cestello della friggitrice ad aria.","Cuocere in friggitrice ad aria a 200 °C per 12–14 min, scuotendo a metà, finché i bordi sono abbrustoliti e la carne è cotta.","Nel frattempo preparare il kachumber: condire cetriolo, pomodoro, cipolla rossa, coriandolo e menta con il resto del succo di limone e un pizzico di sale.","Scaldare i naan nella friggitrice ad aria negli ultimi 2 min, poi servirli con il pollo e il kachumber."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '03cda661-245c-51fc-9d5e-8eb63aae54ee')
  returning id
)
