-- Greek lemon chicken orzo with spinach and cherry tomatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a11d46fd-8dc9-521a-bcc0-ae7cb3f950f9'::uuid, null, 'Greek lemon chicken orzo with spinach and cherry tomatoes', 'seed', null, 'Claude', '/recipe-photos/greek-lemon-chicken-orzo-with-spinach-and-cherry-tomatoes.webp', '/recipe-photos/greek-lemon-chicken-orzo-with-spinach-and-cherry-tomatoes.webp',
    2, null, 30, 8, 22, '["Season the chicken with salt, pepper and half the oregano and brown it in the oil in a wide lidded pan over medium-high heat for 5 min.","Add the onion and cook 3 min, then the garlic and the rest of the oregano for 30 seconds.","Stir in the orzo, the stock and the lemon zest and bring to the boil.","Cover and simmer for 10–12 min, stirring now and then, until the orzo is tender and most of the stock is absorbed.","Stir in the cherry tomatoes and spinach and cook 2 min until the spinach wilts.","Add the lemon juice, check the seasoning and serve with feta and dill on top."]'::jsonb,
    array['greek', 'mediterranean', 'one-pot', 'healthy', 'high protein']::text[], 'greek', 769, 47.3,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Orzo au poulet et au citron à la grecque, épinards et tomates cerises","steps":["Assaisonner le poulet de sel, de poivre et de la moitié de l''origan et le dorer 5 min dans l''huile, dans une sauteuse avec couvercle à feu moyen-vif.","Ajouter l''oignon et cuire 3 min, puis l''ail et le reste de l''origan 30 secondes.","Ajouter l''orzo, le bouillon et le zeste de citron et porter à ébullition.","Couvrir et laisser mijoter 10 à 12 min en remuant de temps en temps, jusqu''à ce que l''orzo soit tendre et ait absorbé presque tout le bouillon.","Incorporer les tomates cerises et les épinards et cuire 2 min jusqu''à ce que les épinards tombent.","Ajouter le jus de citron, rectifier l''assaisonnement et servir parsemé de feta et d''aneth."]},"it":{"title":"Orzo greco al pollo e limone con spinaci e pomodorini","steps":["Condire il pollo con sale, pepe e metà dell''origano e rosolarlo nell''olio per 5 min in un tegame largo con coperchio a fuoco medio-alto.","Unire la cipolla e cuocere 3 min, poi aglio e il resto dell''origano per 30 secondi.","Unire l''orzo, il brodo e la scorza di limone e portare a bollore.","Coprire e cuocere a fuoco dolce 10–12 min, mescolando ogni tanto, finché l''orzo è tenero e ha assorbito quasi tutto il brodo.","Unire pomodorini e spinaci e cuocere 2 min finché gli spinaci appassiscono.","Aggiungere il succo di limone, regolare di sale e servire con feta e aneto sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a11d46fd-8dc9-521a-bcc0-ae7cb3f950f9')
  returning id
)
