-- Chicken in black bean sauce with peppers and noodles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bf976172-3ded-5855-82f6-e6f0db648843'::uuid, null, 'Chicken in black bean sauce with peppers and noodles', 'seed', null, 'Claude', '/recipe-photos/chicken-in-black-bean-sauce-with-peppers-and-noodles.webp', '/recipe-photos/chicken-in-black-bean-sauce-with-peppers-and-noodles.webp',
    2, null, 27, 12, 15, '["Toss the chicken with the Shaoxing wine, 1 tsp cornstarch and 1 tsp of the soy sauce. Mix the rest of the soy sauce, the sugar, stock and remaining cornstarch.","Cook the noodles in a pot of boiling water as the pack says, drain and rinse briefly.","Heat the oil in a wok over high heat and stir-fry the chicken for 3–4 min until browned; lift out.","Stir-fry the onion and peppers for 2 min, then add the black beans, garlic and ginger for 30 seconds.","Return the chicken, pour in the sauce and toss for 1–2 min until thick and glossy.","Serve over the noodles, with sliced chilli if you like."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'healthy', 'high protein']::text[], 'chinese', 788, 40,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet sauce aux haricots noirs, poivrons et nouilles","steps":["Mélanger le poulet avec le vin de Shaoxing, 1 c. à café de fécule et 1 c. à café de sauce soja. Mélanger le reste de sauce soja, le sucre, le bouillon et le reste de fécule.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet, égoutter et rincer brièvement.","Chauffer l''huile dans un wok à feu vif et faire sauter le poulet 3 à 4 min jusqu''à ce qu''il soit doré ; le retirer.","Faire sauter l''oignon et les poivrons 2 min, puis ajouter les haricots noirs, l''ail et le gingembre 30 secondes.","Remettre le poulet, verser la sauce et mélanger 1 à 2 min jusqu''à ce qu''elle soit épaisse et brillante.","Servir sur les nouilles, avec du piment émincé si on aime."]},"it":{"title":"Pollo in salsa di fagioli neri con peperoni e noodles","steps":["Condire il pollo con vino Shaoxing, 1 cucchiaino di amido e 1 cucchiaino di salsa di soia. Mescolare il resto della soia, zucchero, brodo e l''amido rimasto.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione, scolarli e sciacquarli brevemente.","Scaldare l''olio in un wok a fuoco vivo e saltare il pollo per 3–4 min finché è dorato; toglierlo.","Saltare cipolla e peperoni per 2 min, poi unire fagioli neri, aglio e zenzero per 30 secondi.","Rimettere il pollo, versare la salsa e saltare 1–2 min finché è densa e lucida.","Servire sui noodles, con peperoncino a fettine a piacere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bf976172-3ded-5855-82f6-e6f0db648843')
  returning id
)
