-- Gà kho gừng (Vietnamese ginger chicken) with rice and pak choi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8abe1f0a-a0f1-5620-b8e9-123b6e298553'::uuid, null, 'Gà kho gừng (Vietnamese ginger chicken) with rice and pak choi', 'seed', null, 'Claude', '/recipe-photos/ga-kho-gung-vietnamese-ginger-chicken-with-rice-and-pak-choi.webp', '/recipe-photos/ga-kho-gung-vietnamese-ginger-chicken-with-rice-and-pak-choi.webp',
    2, null, 30, 10, 20, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min.","Toss the chicken with 1 tbsp of the fish sauce and plenty of black pepper.","Melt the sugar with 1 tbsp water in a lidded frying pan over medium heat, without stirring, for 3–4 min until it turns a deep amber caramel.","Add the oil, shallot, garlic and ginger and stir 30 seconds, then add the chicken and turn it in the caramel for 2 min.","Pour in the rest of the fish sauce and 100 ml water, cover and simmer 10 min, then uncover and reduce 3 min until the sauce is dark and sticky.","Meanwhile lay the pak choi on the rice for its last 4 min, put the lid back on and let it steam.","Serve the chicken and its sauce with the rice and pak choi, scattered with spring onion."]'::jsonb,
    array['vietnamese', 'asian', 'healthy', 'high protein']::text[], 'vietnamese', 676, 38.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Gà kho gừng (poulet vietnamien au gingembre), riz et pak choï","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux.","Mélanger le poulet avec 1 c. à soupe de sauce poisson et beaucoup de poivre noir.","Faire fondre le sucre avec 1 c. à soupe d''eau dans une poêle avec couvercle à feu moyen, sans remuer, 3 à 4 min jusqu''à obtenir un caramel ambré foncé.","Ajouter l''huile, l''échalote, l''ail et le gingembre et remuer 30 secondes, puis ajouter le poulet et l''enrober de caramel 2 min.","Verser le reste de sauce poisson et 100 ml d''eau, couvrir et laisser mijoter 10 min, puis découvrir et faire réduire 3 min jusqu''à ce que la sauce soit foncée et collante.","Pendant ce temps, poser le pak choï sur le riz pour ses 4 dernières minutes, remettre le couvercle et laisser cuire à la vapeur.","Servir le poulet et sa sauce avec le riz et le pak choï, parsemés d''oignon nouveau."]},"it":{"title":"Gà kho gừng (pollo vietnamita allo zenzero) con riso e pak choi","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min.","Condire il pollo con 1 cucchiaio di salsa di pesce e abbondante pepe nero.","Sciogliere lo zucchero con 1 cucchiaio d''acqua in una padella con coperchio a fuoco medio, senza mescolare, per 3–4 min finché diventa un caramello ambrato scuro.","Unire olio, scalogno, aglio e zenzero e mescolare 30 secondi, poi aggiungere il pollo e girarlo nel caramello per 2 min.","Versare il resto della salsa di pesce e 100 ml d''acqua, coprire e cuocere a fuoco dolce 10 min, poi scoprire e far ridurre 3 min finché la salsa è scura e appiccicosa.","Nel frattempo adagiare il pak choi sul riso negli ultimi 4 min, rimettere il coperchio e lasciarlo cuocere a vapore.","Servire il pollo con la sua salsa insieme a riso e pak choi, con cipollotto sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8abe1f0a-a0f1-5620-b8e9-123b6e298553')
  returning id
)
