-- Air-fryer mojo chicken with rice and black beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '020a9392-2512-55f1-9700-d31508a57a3e'::uuid, null, 'Air-fryer mojo chicken with rice and black beans', 'seed', null, 'Claude', '/recipe-photos/air-fryer-mojo-chicken-with-rice-and-black-beans.webp', '/recipe-photos/air-fryer-mojo-chicken-with-rice-and-black-beans.webp',
    2, null, 30, 10, 20, '["Whisk the orange and lime juice with the garlic, half the cumin, the oregano, the oil, salt and pepper: this is the mojo.","Toss the chicken in a third of the mojo and air-fry at 200°C for 16–18 min, turning halfway, until browned and 75°C inside.","Meanwhile rinse the rice and cook it covered in 180 ml salted water on low heat for 12 min.","In a second pan, soften the onion and green pepper in 2 tbsp of the mojo for 5 min, then add the black beans, bay leaf, the rest of the cumin and 4 tbsp water and simmer 8 min.","Slice the chicken and spoon the remaining mojo over it.","Serve with the rice and black beans, scattered with coriander."]'::jsonb,
    array['cuban', 'caribbean', 'healthy', 'high protein']::text[], 'cuban', 867, 47.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet mojo à l''air fryer, riz et haricots noirs","steps":["Fouetter les jus d''orange et de citron vert avec l''ail, la moitié du cumin, l''origan, l''huile, du sel et du poivre : c''est le mojo.","Enrober le poulet d''un tiers du mojo et le cuire à l''air fryer à 200 °C pendant 16 à 18 min en le retournant à mi-cuisson, jusqu''à ce qu''il soit doré et à 75 °C à cœur.","Pendant ce temps, rincer le riz et le cuire à couvert dans 180 ml d''eau salée 12 min à feu doux.","Dans une seconde casserole, faire revenir l''oignon et le poivron vert dans 2 c. à soupe de mojo 5 min, puis ajouter les haricots noirs, le laurier, le reste du cumin et 4 c. à soupe d''eau et laisser mijoter 8 min.","Trancher le poulet et l''arroser du reste de mojo.","Servir avec le riz et les haricots noirs, parsemés de coriandre."]},"it":{"title":"Pollo al mojo in friggitrice ad aria con riso e fagioli neri","steps":["Sbattere i succhi d''arancia e lime con aglio, metà del cumino, origano, olio, sale e pepe: è il mojo.","Condire il pollo con un terzo del mojo e cuocerlo in friggitrice ad aria a 200 °C per 16–18 min, girandolo a metà, finché è dorato e a 75 °C al cuore.","Nel frattempo sciacquare il riso e cuocerlo coperto in 180 ml d''acqua salata a fuoco basso per 12 min.","In un secondo tegame stufare cipolla e peperone verde in 2 cucchiai di mojo per 5 min, poi unire fagioli neri, alloro, il resto del cumino e 4 cucchiai d''acqua e cuocere 8 min.","Affettare il pollo e irrorarlo con il resto del mojo.","Servire con riso e fagioli neri, con coriandolo sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '020a9392-2512-55f1-9700-d31508a57a3e')
  returning id
)
