-- Turkey keema matar with chapatis
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6ade88fa-f405-5314-bbfb-0c109e97ec93'::uuid, null, 'Turkey keema matar with chapatis', 'seed', null, 'Claude', '/recipe-photos/turkey-keema-matar-with-chapatis.webp', '/recipe-photos/turkey-keema-matar-with-chapatis.webp',
    2, null, 30, 10, 20, '["Heat the oil in a large frying pan over medium heat and sizzle the cumin seeds for 30 seconds.","Add the onion and cook 5–6 min until golden, then add the garlic, ginger and green chilli for 1 min.","Add the turkey and cook 5 min over high heat, breaking it up with a spoon, until it loses its pink colour.","Stir in the ground coriander, turmeric, chilli powder and tomato with a pinch of salt and cook 4 min until the tomato breaks down.","Add the peas and 4 tbsp water and simmer 4 min until the peas are tender and the keema is moist but not runny.","Stir in the garam masala and lemon juice.","Warm the chapatis in a dry frying pan for 20 seconds a side and serve with the keema and coriander."]'::jsonb,
    array['indian', 'curry', 'healthy', 'high protein']::text[], 'indian', 707, 48,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Keema matar à la dinde et chapatis","steps":["Chauffer l''huile dans une grande poêle à feu moyen et faire grésiller les graines de cumin 30 secondes.","Ajouter l''oignon et cuire 5 à 6 min jusqu''à ce qu''il soit doré, puis ajouter l''ail, le gingembre et le piment vert 1 min.","Ajouter la dinde et cuire 5 min à feu vif en l''émiettant à la cuillère, jusqu''à ce qu''elle ne soit plus rosée.","Ajouter la coriandre moulue, le curcuma, le piment en poudre et la tomate avec une pincée de sel et cuire 4 min jusqu''à ce que la tomate se défasse.","Ajouter les petits pois et 4 c. à soupe d''eau et laisser mijoter 4 min, jusqu''à ce que les pois soient tendres et le keema moelleux sans être liquide.","Incorporer le garam masala et le jus de citron.","Réchauffer les chapatis 20 secondes de chaque côté dans une poêle sèche et servir avec le keema et la coriandre."]},"it":{"title":"Keema matar di tacchino con chapati","steps":["Scaldare l''olio in una padella grande a fuoco medio e far sfrigolare i semi di cumino per 30 secondi.","Unire la cipolla e cuocere 5–6 min finché è dorata, poi aggiungere aglio, zenzero e peperoncino verde per 1 min.","Unire il tacchino e cuocere 5 min a fuoco vivo, sbriciolandolo con un cucchiaio, finché non è più rosa.","Unire coriandolo macinato, curcuma, peperoncino in polvere e pomodoro con un pizzico di sale e cuocere 4 min finché il pomodoro si disfa.","Unire i piselli e 4 cucchiai d''acqua e cuocere 4 min finché i piselli sono teneri e il keema è umido ma non brodoso.","Incorporare il garam masala e il succo di limone.","Scaldare i chapati in una padella asciutta per 20 secondi per lato e servirli con il keema e il coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6ade88fa-f405-5314-bbfb-0c109e97ec93')
  returning id
)
