-- Air-fryer piri-piri turkey with spicy rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7796bb98-ab0a-5372-8642-dff105dc2ccd'::uuid, null, 'Air-fryer piri-piri turkey with spicy rice', 'seed', null, 'Claude', '/recipe-photos/air-fryer-piri-piri-turkey-with-spicy-rice.webp', '/recipe-photos/air-fryer-piri-piri-turkey-with-spicy-rice.webp',
    2, null, 30, 10, 20, '["Mash or blend the chillies, garlic, smoked paprika, oregano, lemon juice, vinegar, olive oil and a good pinch of salt into a loose piri-piri sauce.","Fry the onion and pepper in 1 tbsp of the sauce in a lidded pan for 4 min.","Stir in the rinsed rice and turmeric, pour in the stock, bring to the boil, cover and cook on low heat for 12 min.","Meanwhile brush the turkey steaks with half the remaining sauce.","Air-fry at 200°C for 10–12 min, turning halfway, until lightly charred and 75°C in the centre; rest 3 min.","Scatter the peas and corn over the rice, cover and cook 3 min more, then fluff with a fork.","Slice the turkey and serve on the rice with the rest of the piri-piri sauce."]'::jsonb,
    array['portuguese', 'spicy', 'healthy', 'high protein']::text[], 'portuguese', 674, 51.4,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Dinde piri-piri à l''air fryer et riz épicé","steps":["Écraser ou mixer les piments, l''ail, le paprika fumé, l''origan, le jus de citron, le vinaigre, l''huile d''olive et une bonne pincée de sel pour obtenir une sauce piri-piri fluide.","Faire revenir l''oignon et le poivron 4 min dans 1 c. à soupe de sauce, dans une casserole avec couvercle.","Ajouter le riz rincé et le curcuma, verser le bouillon, porter à ébullition, couvrir et cuire 12 min à feu doux.","Pendant ce temps, badigeonner les escalopes de dinde avec la moitié de la sauce restante.","Cuire à l''air fryer à 200 °C pendant 10 à 12 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient légèrement grillées et à 75 °C à cœur ; laisser reposer 3 min.","Répartir les petits pois et le maïs sur le riz, couvrir et cuire encore 3 min, puis égrener à la fourchette.","Trancher la dinde et la servir sur le riz avec le reste de sauce piri-piri."]},"it":{"title":"Tacchino piri-piri in friggitrice ad aria con riso piccante","steps":["Pestare o frullare peperoncini, aglio, paprica affumicata, origano, succo di limone, aceto, olio d''oliva e un buon pizzico di sale in una salsa piri-piri fluida.","Soffriggere cipolla e peperone in 1 cucchiaio di salsa in un tegame con coperchio per 4 min.","Unire il riso sciacquato e la curcuma, versare il brodo, portare a bollore, coprire e cuocere a fuoco basso per 12 min.","Nel frattempo spennellare le fette di tacchino con metà della salsa rimasta.","Cuocere in friggitrice ad aria a 200 °C per 10–12 min, girando a metà, finché sono leggermente abbrustolite e a 75 °C al cuore; far riposare 3 min.","Distribuire piselli e mais sul riso, coprire e cuocere altri 3 min, poi sgranare con la forchetta.","Affettare il tacchino e servirlo sul riso con il resto della salsa piri-piri."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7796bb98-ab0a-5372-8642-dff105dc2ccd')
  returning id
)
