-- Turkey soboro don with egg and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3bf77e79-a503-567b-86b2-d41c2d351516'::uuid, null, 'Turkey soboro don with egg and green beans', 'seed', null, 'Claude', '/recipe-photos/turkey-soboro-don-with-egg-and-green-beans.webp', '/recipe-photos/turkey-soboro-don-with-egg-and-green-beans.webp',
    2, null, 30, 10, 20, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min.","Lay the green beans on top of the rice for the last 4 min, put the lid back on and let them steam; then rest off the heat.","Beat the eggs with 1 tsp sugar and a pinch of salt and cook them in a non-stick frying pan over medium-low heat, stirring constantly with chopsticks, for 2 min into fine soft crumbs; tip out.","Put the turkey, ginger, soy sauce, mirin, sake and the rest of the sugar in the same pan, cold, and stir well to break up the meat.","Cook over medium heat for 6–7 min, stirring all the time with chopsticks, until the meat is in fine crumbs and the liquid has nearly gone.","Fill the bowls with rice and arrange the turkey, egg and green beans on top in three sections; add pickled ginger."]'::jsonb,
    array['japanese', 'asian', 'bowl', 'kid-friendly', 'healthy', 'high protein']::text[], 'japanese', 635, 41.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Soboro don à la dinde, œufs brouillés et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux.","Poser les haricots verts sur le riz pour les 4 dernières minutes, remettre le couvercle et laisser cuire à la vapeur ; puis laisser reposer hors du feu.","Battre les œufs avec 1 c. à café de sucre et une pincée de sel et les cuire dans une poêle antiadhésive à feu moyen-doux en remuant sans cesse avec des baguettes, 2 min, en fines miettes moelleuses ; réserver.","Mettre la dinde, le gingembre, la sauce soja, le mirin, le saké et le reste du sucre dans la même poêle froide et bien mélanger pour séparer la viande.","Cuire à feu moyen 6 à 7 min en remuant sans cesse avec des baguettes, jusqu''à ce que la viande soit en fines miettes et le liquide presque évaporé.","Remplir les bols de riz et disposer dessus la dinde, l''œuf et les haricots verts en trois parts ; ajouter le gingembre mariné."]},"it":{"title":"Soboro don di tacchino con uova e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min.","Adagiare i fagiolini sul riso negli ultimi 4 min, rimettere il coperchio e lasciarli cuocere a vapore; poi far riposare fuori dal fuoco.","Sbattere le uova con 1 cucchiaino di zucchero e un pizzico di sale e cuocerle in una padella antiaderente a fuoco medio-basso mescolando di continuo con le bacchette, per 2 min, in briciole fini e morbide; tenerle da parte.","Mettere nella stessa padella fredda tacchino, zenzero, salsa di soia, mirin, sake e il resto dello zucchero e mescolare bene per sgranare la carne.","Cuocere a fuoco medio per 6–7 min mescolando sempre con le bacchette, finché la carne è in briciole fini e il liquido è quasi evaporato.","Riempire le ciotole di riso e disporvi sopra tacchino, uovo e fagiolini in tre settori; aggiungere lo zenzero marinato."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3bf77e79-a503-567b-86b2-d41c2d351516')
  returning id
)
