-- Air-fryer turkey escalopes with sauce vierge and crushed potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a7902387-e1b1-5e72-8f75-c3b7264fddfc'::uuid, null, 'Air-fryer turkey escalopes with sauce vierge and crushed potatoes', 'seed', null, 'Claude', '/recipe-photos/air-fryer-turkey-escalopes-with-sauce-vierge-and-crushed-potatoes.webp', '/recipe-photos/air-fryer-turkey-escalopes-with-sauce-vierge-and-crushed-potatoes.webp',
    2, null, 30, 12, 18, '["Boil the potatoes in a pot of salted water for 15–18 min until tender, adding the green beans for the last 5 min.","Meanwhile make the sauce vierge: mix the tomato, shallot, lemon juice, basil, olives, 1.5 tbsp olive oil, salt and pepper and leave it to stand.","Rub the escalopes with 1 tsp olive oil, the herbes de Provence, salt and pepper.","Air-fry at 200°C for 8–10 min, turning halfway, until golden and no longer pink inside.","Drain the potatoes and beans, lightly crush the potatoes with a fork and the rest of the oil, and season.","Serve the turkey on the crushed potatoes with the green beans, and spoon the sauce vierge over."]'::jsonb,
    array['french', 'mediterranean', 'healthy', 'high protein']::text[], 'french', 637, 47.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Escalopes de dinde à l''air fryer, sauce vierge et pommes de terre écrasées","steps":["Cuire les pommes de terre 15 à 18 min dans une casserole d''eau salée bouillante jusqu''à ce qu''elles soient tendres, en ajoutant les haricots verts les 5 dernières minutes.","Pendant ce temps, préparer la sauce vierge : mélanger la tomate, l''échalote, le jus de citron, le basilic, les olives, 1,5 c. à soupe d''huile d''olive, du sel et du poivre et laisser reposer.","Frotter les escalopes avec 1 c. à café d''huile d''olive, les herbes de Provence, du sel et du poivre.","Cuire à l''air fryer à 200 °C pendant 8 à 10 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et plus rosées à cœur.","Égoutter les pommes de terre et les haricots, écraser grossièrement les pommes de terre à la fourchette avec le reste de l''huile et assaisonner.","Servir la dinde sur les pommes de terre écrasées avec les haricots verts et napper de sauce vierge."]},"it":{"title":"Scaloppine di tacchino in friggitrice ad aria con salsa vergine e patate schiacciate","steps":["Lessare le patate in una pentola d''acqua salata per 15–18 min finché sono tenere, aggiungendo i fagiolini negli ultimi 5 min.","Nel frattempo preparare la salsa vergine: mescolare pomodoro, scalogno, succo di limone, basilico, olive, 1,5 cucchiai d''olio d''oliva, sale e pepe e lasciarla riposare.","Massaggiare le scaloppine con 1 cucchiaino d''olio d''oliva, le erbe di Provenza, sale e pepe.","Cuocere in friggitrice ad aria a 200 °C per 8–10 min, girando a metà, finché sono dorate e non più rosa all''interno.","Scolare patate e fagiolini, schiacciare grossolanamente le patate con la forchetta e il resto dell''olio e regolare di sale.","Servire il tacchino sulle patate schiacciate con i fagiolini e versarci sopra la salsa vergine."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a7902387-e1b1-5e72-8f75-c3b7264fddfc')
  returning id
)
