-- Air-fryer turkey albóndigas with potatoes in tomato sauce
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8e59d959-5ac0-5c4a-a475-c526e235adf0'::uuid, null, 'Air-fryer turkey albóndigas with potatoes in tomato sauce', 'seed', null, 'Claude', '/recipe-photos/air-fryer-turkey-albondigas-with-potatoes-in-tomato-sauce.webp', '/recipe-photos/air-fryer-turkey-albondigas-with-potatoes-in-tomato-sauce.webp',
    2, null, 30, 12, 18, '["Heat the oil in a wide lidded pan and soften the onion and carrot for 4 min, then add the sliced garlic and paprika for 30 seconds.","Pour in the wine and let it bubble 1 min, then add the tomatoes, potatoes, stock, bay leaf and a pinch of salt; cover and simmer 15 min.","Meanwhile mix the turkey, breadcrumbs, egg, grated garlic, parsley and a good pinch of salt and roll into 12 balls with wet hands.","Air-fry the meatballs at 200°C for 9–10 min, shaking halfway, until browned.","Add the meatballs and peas to the sauce and simmer uncovered for 3–4 min until the potatoes are tender and the meatballs cooked through.","Serve in shallow bowls with plenty of the sauce."]'::jsonb,
    array['spanish', 'comfort', 'kid-friendly', 'healthy', 'high protein']::text[], 'spanish', 741, 49.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Albóndigas de dinde à l''air fryer, pommes de terre en sauce tomate","steps":["Chauffer l''huile dans une sauteuse avec couvercle et faire revenir l''oignon et la carotte 4 min, puis ajouter l''ail émincé et le paprika 30 secondes.","Verser le vin et laisser bouillonner 1 min, puis ajouter les tomates, les pommes de terre, le bouillon, le laurier et une pincée de sel ; couvrir et laisser mijoter 15 min.","Pendant ce temps, mélanger la dinde, la chapelure, l''œuf, l''ail râpé, le persil et une bonne pincée de sel et former 12 boulettes avec les mains mouillées.","Cuire les boulettes à l''air fryer à 200 °C pendant 9 à 10 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient dorées.","Ajouter les boulettes et les petits pois à la sauce et laisser mijoter 3 à 4 min à découvert, jusqu''à ce que les pommes de terre soient tendres et les boulettes cuites.","Servir dans des assiettes creuses avec beaucoup de sauce."]},"it":{"title":"Albóndigas di tacchino in friggitrice ad aria con patate al pomodoro","steps":["Scaldare l''olio in un tegame largo con coperchio e stufare cipolla e carota per 4 min, poi aggiungere l''aglio a fettine e la paprica per 30 secondi.","Versare il vino e farlo sfumare 1 min, poi unire pomodori, patate, brodo, alloro e un pizzico di sale; coprire e cuocere a fuoco dolce 15 min.","Nel frattempo impastare tacchino, pangrattato, uovo, aglio grattugiato, prezzemolo e un buon pizzico di sale e formare 12 polpette con le mani bagnate.","Cuocere le polpette in friggitrice ad aria a 200 °C per 9–10 min, scuotendo a metà, finché sono dorate.","Unire polpette e piselli al sugo e cuocere scoperto per 3–4 min finché le patate sono tenere e le polpette cotte.","Servire in piatti fondi con abbondante sugo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8e59d959-5ac0-5c4a-a475-c526e235adf0')
  returning id
)
