-- Huevos a la flamenca with potatoes and peas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'af2d856a-7536-5d5f-8b81-f02327abae2a'::uuid, null, 'Huevos a la flamenca with potatoes and peas', 'seed', null, 'Claude', '/recipe-photos/huevos-a-la-flamenca-with-potatoes-and-peas.webp', '/recipe-photos/huevos-a-la-flamenca-with-potatoes-and-peas.webp',
    2, null, 30, 8, 22, '["Boil the potatoes in a pot of salted water for 8 min, adding the peas and green beans for the last 3 min; drain.","Meanwhile heat the oil in a large lidded frying pan and fry the chorizo and half the ham for 2 min until the chorizo releases its red fat.","Add the onion and pepper and cook 5 min until soft, then the garlic and paprika for 30 seconds.","Pour in the tomatoes with a pinch of salt and simmer 5 min until thick.","Stir in the potatoes, peas and beans, make four wells and crack an egg into each.","Scatter over the rest of the ham, cover and cook on low heat for 6–8 min until the whites are set and the yolks still runny.","Sprinkle with parsley and serve straight from the pan."]'::jsonb,
    array['spanish', 'comfort', 'healthy', 'high protein']::text[], 'spanish', 700, 38,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Huevos a la flamenca, pommes de terre et petits pois","steps":["Cuire les pommes de terre 8 min dans une casserole d''eau salée bouillante en ajoutant les petits pois et les haricots verts les 3 dernières minutes ; égoutter.","Pendant ce temps, chauffer l''huile dans une grande poêle avec couvercle et faire revenir le chorizo et la moitié du jambon 2 min, jusqu''à ce que le chorizo rende son gras rouge.","Ajouter l''oignon et le poivron et cuire 5 min jusqu''à ce qu''ils soient tendres, puis l''ail et le paprika 30 secondes.","Verser les tomates avec une pincée de sel et laisser mijoter 5 min jusqu''à ce que la sauce épaississe.","Incorporer les pommes de terre, les petits pois et les haricots, creuser quatre puits et y casser un œuf dans chacun.","Parsemer du reste de jambon, couvrir et cuire à feu doux 6 à 8 min jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer de persil et servir directement dans la poêle."]},"it":{"title":"Huevos a la flamenca con patate e piselli","steps":["Lessare le patate in una pentola d''acqua salata per 8 min, aggiungendo piselli e fagiolini negli ultimi 3 min; scolare.","Nel frattempo scaldare l''olio in una padella grande con coperchio e rosolare il chorizo e metà del prosciutto per 2 min finché il chorizo rilascia il suo grasso rosso.","Unire cipolla e peperone e cuocere 5 min finché sono morbidi, poi aglio e paprica per 30 secondi.","Versare i pomodori con un pizzico di sale e cuocere 5 min finché il sugo si addensa.","Incorporare patate, piselli e fagiolini, formare quattro conche e rompervi un uovo ciascuna.","Distribuire sopra il resto del prosciutto, coprire e cuocere a fuoco basso per 6–8 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere di prezzemolo e servire direttamente in padella."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'af2d856a-7536-5d5f-8b81-f02327abae2a')
  returning id
)
