-- Chicken tinola with green papaya, spinach and rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a021169b-4ba3-50ef-9b7a-deec16739d7e'::uuid, null, 'Chicken tinola with green papaya, spinach and rice', 'seed', null, 'Claude', '/recipe-photos/chicken-tinola-with-green-papaya-spinach-and-rice.webp', '/recipe-photos/chicken-tinola-with-green-papaya-spinach-and-rice.webp',
    2, null, 30, 10, 20, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min, then rest with the lid on.","Heat the oil in a large pot and cook the onion, garlic and ginger over medium heat for 2–3 min until fragrant.","Add the chicken and fish sauce and stir for 3 min until the chicken turns opaque.","Pour in the stock, bring to the boil and simmer 5 min, skimming any foam.","Add the green papaya and simmer 8–10 min until it is tender when pierced with a knife.","Stir in the spinach off the heat until it wilts, then season with pepper and more fish sauce to taste.","Serve the tinola in bowls with the rice on the side."]'::jsonb,
    array['filipino', 'asian', 'soup', 'healthy', 'high protein']::text[], 'filipino', 775, 42,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tinola de poulet à la papaye verte, épinards et riz","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis laisser reposer à couvert.","Chauffer l''huile dans une grande casserole et faire revenir l''oignon, l''ail et le gingembre à feu moyen 2 à 3 min jusqu''à ce qu''ils embaument.","Ajouter le poulet et la sauce poisson et remuer 3 min jusqu''à ce que le poulet devienne opaque.","Verser le bouillon, porter à ébullition et laisser frémir 5 min en écumant.","Ajouter la papaye verte et laisser frémir 8 à 10 min jusqu''à ce qu''elle soit tendre sous la pointe d''un couteau.","Incorporer les épinards hors du feu jusqu''à ce qu''ils tombent, puis poivrer et rectifier avec de la sauce poisson.","Servir la tinola dans des bols avec le riz à côté."]},"it":{"title":"Tinola di pollo con papaya verde, spinaci e riso","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare coperto.","Scaldare l''olio in una pentola capiente e soffriggere cipolla, aglio e zenzero a fuoco medio per 2–3 min finché profumano.","Unire il pollo e la salsa di pesce e mescolare per 3 min finché il pollo diventa opaco.","Versare il brodo, portare a bollore e cuocere a fuoco dolce 5 min, schiumando.","Unire la papaya verde e cuocere 8–10 min finché è tenera alla punta del coltello.","Incorporare gli spinaci fuori dal fuoco finché appassiscono, poi pepare e regolare con altra salsa di pesce.","Servire la tinola nelle ciotole con il riso a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a021169b-4ba3-50ef-9b7a-deec16739d7e')
  returning id
)
