-- Tavuk sote with bulgur pilavı and cacık
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '77465ae6-5bc1-5aec-8bde-63d806d4b60a'::uuid, null, 'Tavuk sote with bulgur pilavı and cacık', 'seed', null, 'Claude', '/recipe-photos/tavuk-sote-with-bulgur-pilavi-and-cacik.webp', '/recipe-photos/tavuk-sote-with-bulgur-pilavi-and-cacik.webp',
    2, null, 30, 10, 20, '["For the pilaf, stir the bulgur and 1 tsp tomato paste in a pot with the stock and a pinch of salt, bring to the boil, cover and simmer on low heat for 12 min; rest 5 min off the heat.","Heat the oil in a large frying pan over high heat, season the chicken and sear it for 4–5 min until golden; lift out.","Cook the onion and peppers in the same pan for 5 min until soft, then add the garlic for 30 seconds.","Stir in the red pepper paste and the rest of the tomato paste for 1 min, then add the tomato, paprika, oregano and 4 tbsp water.","Return the chicken and simmer 5–6 min until the tomato has broken down into a thick sauce and the chicken is cooked through.","For the cacık, mix the yogurt with the squeezed cucumber and a pinch of salt.","Fluff the bulgur and serve with the tavuk sote, the cacık, a pinch of Aleppo pepper and parsley."]'::jsonb,
    array['turkish', 'middle eastern', 'healthy', 'high protein']::text[], 'turkish', 701, 54.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tavuk sote, pilaf de boulgour et cacık","steps":["Pour le pilaf, mélanger le boulgour et 1 c. à café de concentré de tomate avec le bouillon et une pincée de sel dans une casserole, porter à ébullition, couvrir et cuire 12 min à feu doux ; laisser reposer 5 min hors du feu.","Chauffer l''huile dans une grande poêle à feu vif, assaisonner le poulet et le saisir 4 à 5 min jusqu''à ce qu''il soit doré ; le retirer.","Faire revenir l''oignon et les poivrons 5 min dans la même poêle jusqu''à ce qu''ils soient tendres, puis ajouter l''ail 30 secondes.","Ajouter la pâte de poivron et le reste du concentré de tomate 1 min, puis la tomate, le paprika, l''origan et 4 c. à soupe d''eau.","Remettre le poulet et laisser mijoter 5 à 6 min jusqu''à ce que la tomate forme une sauce épaisse et que le poulet soit cuit.","Pour le cacık, mélanger le yaourt avec le concombre pressé et une pincée de sel.","Égrener le boulgour et servir avec le tavuk sote, le cacık, une pincée de piment d''Alep et le persil."]},"it":{"title":"Tavuk sote con pilaf di bulgur e cacık","steps":["Per il pilaf mescolare in una pentola il bulgur e 1 cucchiaino di concentrato con il brodo e un pizzico di sale, portare a bollore, coprire e cuocere 12 min a fuoco basso; far riposare 5 min fuori dal fuoco.","Scaldare l''olio in una padella grande a fuoco vivo, condire il pollo e rosolarlo per 4–5 min finché è dorato; toglierlo.","Stufare cipolla e peperoni nella stessa padella per 5 min finché sono morbidi, poi unire l''aglio per 30 secondi.","Unire la pasta di peperoni e il resto del concentrato per 1 min, poi pomodoro, paprica, origano e 4 cucchiai d''acqua.","Rimettere il pollo e cuocere a fuoco dolce 5–6 min finché il pomodoro diventa un sugo denso e il pollo è cotto.","Per il cacık mescolare lo yogurt con il cetriolo strizzato e un pizzico di sale.","Sgranare il bulgur e servirlo con il tavuk sote, il cacık, un pizzico di pepe di Aleppo e il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '77465ae6-5bc1-5aec-8bde-63d806d4b60a')
  returning id
)
