-- Beef chow fun with bean sprouts and pak choi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd5b912f8-0d70-4774-a415-1a5fa020a743'::uuid, null, 'Beef chow fun with bean sprouts and pak choi', 'seed', null, 'Claude', '/recipe-photos/beef-chow-fun-with-bean-sprouts-and-pak-choi.webp', '/recipe-photos/beef-chow-fun-with-bean-sprouts-and-pak-choi.webp',
    2, null, 25, 15, 10, '["Toss the beef with the cornstarch, rice wine and 1 tsp of the soy sauce.","Soak the noodles in just-boiled water in a large bowl for 8-10 min, until pliable but still firm. Drain, rinse under cold water and shake dry.","Mix the dark soy, the rest of the soy sauce, the oyster sauce and sugar.","Heat half the oil in a wok over high heat until smoking. Sear the beef in one layer 1 min a side until browned but still pink, then lift it out.","Add the rest of the oil, the ginger and onion and stir-fry 1 min, then the pak choi for 1 min.","Add the noodles and sauce and toss over high heat 2 min, lifting from the bottom, until the noodles are evenly brown and slightly charred.","Return the beef with the bean sprouts and spring onions and toss 30 s, just until the sprouts wilt. Serve at once."]'::jsonb,
    array['chinese', 'asian', 'healthy', 'high protein', 'stir-fry', 'fakeaway', 'quick']::text[], 'chinese', 784, 44.3,
    false, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Chow fun au bœuf, germes de soja et pak choï","steps":["Mélanger le bœuf avec la fécule, le vin de riz et 1 c. à café de sauce soja.","Faire tremper les nouilles dans de l''eau tout juste bouillante dans un grand saladier 8 à 10 min, jusqu''à ce qu''elles soient souples mais encore fermes. Égoutter, rincer à l''eau froide et bien secouer.","Mélanger la sauce soja noire, le reste de sauce soja, la sauce huître et le sucre.","Chauffer la moitié de l''huile dans un wok à feu vif jusqu''à ce qu''elle fume. Saisir le bœuf en une couche 1 min par face, jusqu''à ce qu''il soit doré mais encore rosé, puis le retirer.","Ajouter le reste d''huile, le gingembre et l''oignon et faire sauter 1 min, puis le pak choï 1 min.","Ajouter les nouilles et la sauce et faire sauter à feu vif 2 min en soulevant depuis le fond, jusqu''à ce que les nouilles soient uniformément brunes et un peu grillées.","Remettre le bœuf avec les germes de soja et les oignons nouveaux et faire sauter 30 s, juste le temps que les germes s''attendrissent. Servir aussitôt."]},"it":{"title":"Chow fun di manzo con germogli di soia e pak choi","steps":["Condire il manzo con amido, vino di riso e 1 cucchiaino di salsa di soia.","Mettere in ammollo i noodles in acqua appena bollita in una ciotola capiente per 8-10 min, finché sono flessibili ma ancora sodi. Scolare, sciacquare sotto l''acqua fredda e scuotere bene.","Mescolare la salsa di soia scura, il resto della salsa di soia, la salsa d''ostriche e lo zucchero.","Scaldare metà dell''olio nel wok a fuoco vivo finché fuma. Scottare il manzo in un solo strato 1 min per lato finché è rosolato ma ancora rosa, poi toglierlo.","Aggiungere il resto dell''olio, lo zenzero e la cipolla e saltare 1 min, poi il pak choi per 1 min.","Unire i noodles e la salsa e saltare a fuoco vivo 2 min sollevando dal fondo, finché i noodles sono uniformemente bruniti e un po'' abbrustoliti.","Rimettere il manzo con germogli e cipollotti e saltare 30 s, giusto finché i germogli appassiscono. Servire subito."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd5b912f8-0d70-4774-a415-1a5fa020a743')
  returning id
)
