-- Air-fryer pinchos morunos with flatbread and pepper salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ff31b27c-f7a0-4a2c-8178-b6c5f0362213'::uuid, null, 'Air-fryer pinchos morunos with flatbread and pepper salad', 'seed', null, 'Claude', '/recipe-photos/air-fryer-pinchos-morunos-with-flatbread-and-pepper-salad.webp', '/recipe-photos/air-fryer-pinchos-morunos-with-flatbread-and-pepper-salad.webp',
    2, null, 27, 15, 12, '["Mix the oil, paprika, cumin, coriander, turmeric, oregano, garlic, lemon juice and a good pinch of salt. Toss the pork in it and thread onto 4 short skewers.","Toss the tomatoes, pepper, onion and parsley with the vinegar, 1 tsp oil and a pinch of salt, and leave the salad to sit while the pork cooks.","Air-fry the skewers at 200°C for 10-12 min, turning halfway, until browned and 63°C in the centre.","Warm the flatbreads in a dry frying pan over medium heat, 1 min a side.","Rest the skewers 2 min, then serve with the flatbreads and pepper salad, spooning the salad juices over the bread."]'::jsonb,
    array['spanish', 'healthy', 'high protein', 'grill', 'street food']::text[], 'spanish', 591, 43.4,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Pinchos morunos au air fryer, pain plat et salade de poivrons","steps":["Mélanger l''huile, le paprika, le cumin, la coriandre, le curcuma, l''origan, l''ail, le jus de citron et une bonne pincée de sel. Y enrober le porc et l''enfiler sur 4 petites brochettes.","Mélanger les tomates, le poivron, l''oignon et le persil avec le vinaigre, 1 c. à café d''huile et une pincée de sel, et laisser reposer la salade pendant la cuisson du porc.","Cuire les brochettes au air fryer à 200 °C 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et à 63 °C à cœur.","Réchauffer les pains plats dans une poêle sèche à feu moyen, 1 min par face.","Laisser reposer les brochettes 2 min, puis servir avec les pains et la salade de poivrons, en versant le jus de la salade sur le pain."]},"it":{"title":"Pinchos morunos in friggitrice ad aria con pane piatto e insalata di peperoni","steps":["Mescolare olio, paprika, cumino, coriandolo, curcuma, origano, aglio, succo di limone e un buon pizzico di sale. Condire il maiale e infilarlo su 4 spiedini corti.","Condire pomodori, peperone, cipolla e prezzemolo con aceto, 1 cucchiaino d''olio e un pizzico di sale, e lasciar riposare l''insalata mentre cuoce il maiale.","Cuocere gli spiedini in friggitrice ad aria a 200 °C per 10-12 min, girandoli a metà, finché sono rosolati e a 63 °C al cuore.","Scaldare i pani piatti in una padella asciutta a fuoco medio, 1 min per lato.","Far riposare gli spiedini 2 min, poi servire con i pani e l''insalata di peperoni, versando il sugo dell''insalata sul pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ff31b27c-f7a0-4a2c-8178-b6c5f0362213')
  returning id
)
