-- Mie goreng with prawns
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '02e62558-d688-467d-ac0d-e78729da69be'::uuid, null, 'Mie goreng with prawns', 'seed', null, 'Claude', '/recipe-photos/mie-goreng-with-prawns.webp', '/recipe-photos/mie-goreng-with-prawns.webp',
    2, null, 22, 10, 12, '["Cook the noodles in boiling water as the packet says, drain, rinse briefly and toss with a few drops of the oil.","Mix the kecap manis, soy sauce and ketchup.","Heat half the oil in a wok over high heat. Scramble the eggs 1 min until just set, then push them to one side.","Add the rest of the oil, the garlic, shallot and chilli and stir-fry 30 s, then the prawns for 1-2 min until they just turn pink.","Add the cabbage and carrot and stir-fry 2 min, until the cabbage starts to wilt.","Add the noodles and sauce and toss vigorously 2 min until evenly coated and slightly sticky. Toss in the bean sprouts and spring onions for 30 s and serve with lime."]'::jsonb,
    array['indonesian', 'asian', 'healthy', 'high protein', 'stir-fry', 'street food', 'quick']::text[], 'indonesian', 711, 55,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Mie goreng aux crevettes","steps":["Cuire les nouilles dans l''eau bouillante selon le paquet, égoutter, rincer rapidement et mélanger avec quelques gouttes d''huile.","Mélanger le kecap manis, la sauce soja et le ketchup.","Chauffer la moitié de l''huile dans un wok à feu vif. Brouiller les œufs 1 min jusqu''à ce qu''ils soient juste pris, puis les pousser sur le côté.","Ajouter le reste d''huile, l''ail, l''échalote et le piment et faire sauter 30 s, puis les crevettes 1 à 2 min jusqu''à ce qu''elles deviennent roses.","Ajouter le chou et la carotte et faire sauter 2 min, jusqu''à ce que le chou commence à s''attendrir.","Ajouter les nouilles et la sauce et faire sauter vigoureusement 2 min jusqu''à ce qu''elles soient bien enrobées et un peu collantes. Ajouter les germes de soja et les oignons nouveaux 30 s et servir avec le citron vert."]},"it":{"title":"Mie goreng con gamberi","steps":["Cuocere i noodles in acqua bollente come indicato sulla confezione, scolarli, sciacquarli velocemente e condirli con qualche goccia d''olio.","Mescolare kecap manis, salsa di soia e ketchup.","Scaldare metà dell''olio nel wok a fuoco vivo. Strapazzare le uova 1 min finché sono appena rapprese, poi spingerle da un lato.","Aggiungere il resto dell''olio, aglio, scalogno e peperoncino e saltare 30 s, poi i gamberi per 1-2 min finché diventano rosa.","Unire cavolo e carota e saltare 2 min, finché il cavolo inizia ad appassire.","Aggiungere noodles e salsa e saltare energicamente 2 min finché sono ben conditi e un po'' appiccicosi. Unire germogli di soia e cipollotti per 30 s e servire con il lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '02e62558-d688-467d-ac0d-e78729da69be')
  returning id
)
