-- Garides saganaki with orzo
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '241db188-c71f-493f-bdb8-6799bb6b8cb7'::uuid, null, 'Garides saganaki with orzo', 'seed', null, 'Claude', '/recipe-photos/garides-saganaki-with-orzo.webp', '/recipe-photos/garides-saganaki-with-orzo.webp',
    2, null, 30, 10, 20, '["Cook the orzo in boiling salted water as the packet says, about 9 min, then drain.","Meanwhile, heat the oil in a wide frying pan over medium heat and soften the onion 5 min. Add the garlic and chili flakes for 1 min.","Pour in the wine and let it bubble 1 min, then add the tomatoes and oregano and simmer 8 min until thickened. Season.","Nestle the prawns into the sauce and simmer 3-4 min, turning once, until pink and just cooked.","Stir the spinach into the drained orzo so it wilts in the heat.","Crumble the feta over the prawns, scatter with parsley and serve with the orzo."]'::jsonb,
    array['greek', 'healthy', 'high protein', 'mediterranean']::text[], 'greek', 716, 57.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Garides saganaki (crevettes à la tomate et à la feta) et orzo","steps":["Cuire l''orzo dans l''eau bouillante salée selon le paquet, environ 9 min, puis égoutter.","Pendant ce temps, chauffer l''huile dans une grande poêle à feu moyen et faire fondre l''oignon 5 min. Ajouter l''ail et le piment 1 min.","Verser le vin et laisser bouillonner 1 min, puis ajouter les tomates et l''origan et laisser mijoter 8 min jusqu''à ce que la sauce épaississe. Assaisonner.","Enfoncer les crevettes dans la sauce et laisser mijoter 3 à 4 min en les retournant une fois, jusqu''à ce qu''elles soient roses et juste cuites.","Incorporer les épinards à l''orzo égoutté pour qu''ils tombent à la chaleur.","Émietter la feta sur les crevettes, parsemer de persil et servir avec l''orzo."]},"it":{"title":"Garides saganaki (gamberi al pomodoro e feta) con orzo","steps":["Cuocere l''orzo in acqua bollente salata come indicato sulla confezione, circa 9 min, poi scolarlo.","Intanto scaldare l''olio in un''ampia padella a fuoco medio e appassire la cipolla 5 min. Aggiungere aglio e peperoncino per 1 min.","Sfumare con il vino e far sobbollire 1 min, poi unire pomodori e origano e cuocere 8 min finché il sugo si addensa. Regolare di sale.","Adagiare i gamberi nel sugo e cuocere 3-4 min, girandoli una volta, finché sono rosa e appena cotti.","Mescolare gli spinaci all''orzo scolato perché appassiscano con il calore.","Sbriciolare la feta sui gamberi, cospargere di prezzemolo e servire con l''orzo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '241db188-c71f-493f-bdb8-6799bb6b8cb7')
  returning id
)
