-- Prawn yaki udon with cabbage and mushrooms
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3c207655-1bf3-4635-8387-61f1ffd51f09'::uuid, null, 'Prawn yaki udon with cabbage and mushrooms', 'seed', null, 'Claude', '/recipe-photos/prawn-yaki-udon-with-cabbage-and-mushrooms.webp', '/recipe-photos/prawn-yaki-udon-with-cabbage-and-mushrooms.webp',
    2, null, 20, 10, 10, '["Put the udon in a bowl, cover with just-boiled water for 1 min to loosen, then drain.","Mix the soy sauce, oyster sauce, mirin and sesame oil.","Heat the oil in a wok or large frying pan over high heat. Stir-fry the prawns 1-2 min until pink, then lift them out.","Add the garlic, onion and carrot and stir-fry 1 min, then the cabbage and mushrooms for 2-3 min, until the cabbage is wilted but still has bite.","Add the udon, sauce and spring onions and toss 1-2 min until the noodles are hot and glossy.","Return the prawns, toss 30 s and serve with sesame seeds."]'::jsonb,
    array['japanese', 'asian', 'healthy', 'high protein', 'stir-fry', 'quick']::text[], 'japanese', 617, 48.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Yaki udon aux crevettes, chou et champignons","steps":["Mettre les udon dans un saladier, couvrir d''eau tout juste bouillante 1 min pour les détacher, puis égoutter.","Mélanger la sauce soja, la sauce huître, le mirin et l''huile de sésame.","Chauffer l''huile dans un wok ou une grande poêle à feu vif. Faire sauter les crevettes 1 à 2 min jusqu''à ce qu''elles soient roses, puis les retirer.","Ajouter l''ail, l''oignon et la carotte et faire sauter 1 min, puis le chou et les champignons 2 à 3 min, jusqu''à ce que le chou soit tombé mais encore croquant.","Ajouter les udon, la sauce et les oignons nouveaux et faire sauter 1 à 2 min jusqu''à ce que les nouilles soient chaudes et brillantes.","Remettre les crevettes, faire sauter 30 s et servir avec les graines de sésame."]},"it":{"title":"Yaki udon con gamberi, cavolo e funghi","steps":["Mettere gli udon in una ciotola, coprirli con acqua appena bollita per 1 min per staccarli, poi scolarli.","Mescolare salsa di soia, salsa d''ostriche, mirin e olio di sesamo.","Scaldare l''olio nel wok o in un''ampia padella a fuoco vivo. Saltare i gamberi 1-2 min finché sono rosa, poi toglierli.","Aggiungere aglio, cipolla e carota e saltare 1 min, poi cavolo e funghi per 2-3 min, finché il cavolo è appassito ma ancora croccante.","Unire udon, salsa e cipollotti e saltare 1-2 min finché i noodles sono caldi e lucidi.","Rimettere i gamberi, saltare 30 s e servire con i semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3c207655-1bf3-4635-8387-61f1ffd51f09')
  returning id
)
