-- Squid with chickpeas, chorizo and smoked paprika
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'fe97a411-d8af-458a-8532-f3fab76ba358'::uuid, null, 'Squid with chickpeas, chorizo and smoked paprika', 'seed', null, 'Claude', '/recipe-photos/squid-with-chickpeas-chorizo-and-smoked-paprika.webp', '/recipe-photos/squid-with-chickpeas-chorizo-and-smoked-paprika.webp',
    2, null, 30, 10, 20, '["Heat the oil in a wide pan over medium heat and fry the chorizo 2 min until it releases its red oil.","Add the onion and pepper and soften 6 min, then the garlic for 1 min.","Stir in the paprika, then straight away the grated tomato and wine, and simmer 4 min until jammy.","Add the chickpeas and 100 ml water and simmer 4 min.","Turn the heat up, add the squid and cook 2 min, just until it turns opaque, then stir in the spinach until it wilts.","Season, add the lemon juice and parsley and serve in bowls."]'::jsonb,
    array['spanish', 'healthy', 'high protein', 'stew', 'one-pot']::text[], 'spanish', 687, 50.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Calamars aux pois chiches, chorizo et paprika fumé","steps":["Chauffer l''huile dans une grande sauteuse à feu moyen et faire revenir le chorizo 2 min jusqu''à ce qu''il rende son huile rouge.","Ajouter l''oignon et le poivron et les faire fondre 6 min, puis l''ail 1 min.","Incorporer le paprika, puis aussitôt la tomate râpée et le vin, et laisser mijoter 4 min jusqu''à consistance de confiture.","Ajouter les pois chiches et 100 ml d''eau et laisser mijoter 4 min.","Monter le feu, ajouter les calamars et cuire 2 min, juste jusqu''à ce qu''ils deviennent opaques, puis incorporer les épinards jusqu''à ce qu''ils tombent.","Assaisonner, ajouter le jus de citron et le persil et servir dans des bols."]},"it":{"title":"Calamari con ceci, chorizo e paprika affumicata","steps":["Scaldare l''olio in un''ampia padella a fuoco medio e rosolare il chorizo 2 min finché rilascia il suo olio rosso.","Aggiungere cipolla e peperone e appassirli 6 min, poi l''aglio per 1 min.","Unire la paprika, poi subito il pomodoro grattugiato e il vino, e cuocere 4 min finché è denso come una marmellata.","Aggiungere i ceci e 100 ml d''acqua e cuocere 4 min.","Alzare la fiamma, unire i calamari e cuocere 2 min, giusto finché diventano opachi, poi aggiungere gli spinaci finché appassiscono.","Regolare di sale, aggiungere succo di limone e prezzemolo e servire in ciotole."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'fe97a411-d8af-458a-8532-f3fab76ba358')
  returning id
)
