-- Ojingeo bokkeum (Korean spicy squid) with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b691ac47-1e7f-4fcc-a0c8-e540b5d03fe1'::uuid, null, 'Ojingeo bokkeum (Korean spicy squid) with rice', 'seed', null, 'Claude', '/recipe-photos/ojingeo-bokkeum-korean-spicy-squid-with-rice.webp', '/recipe-photos/ojingeo-bokkeum-korean-spicy-squid-with-rice.webp',
    2, null, 25, 15, 10, '["Rinse the rice and simmer it covered in 195 ml water for 12 min on low heat, then rest it off the heat.","Mix the gochugaru, gochujang, soy sauce, sugar, garlic, ginger and 1 tbsp water to a paste.","Heat the oil in a wok over high heat and stir-fry the onion, carrot and cabbage 2-3 min, until just softening.","Add the squid and the paste and stir-fry 2-3 min, just until the squid turns opaque and curls.","Add the chilli and spring onions and toss 30 s, then take off the heat and stir in the sesame oil.","Serve over the rice with sesame seeds."]'::jsonb,
    array['korean', 'asian', 'healthy', 'high protein', 'stir-fry', 'spicy', 'quick']::text[], 'korean', 702, 39,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Ojingeo bokkeum (calamars sautés épicés à la coréenne) et riz","steps":["Rincer le riz et le cuire à couvert dans 195 ml d''eau 12 min à feu doux, puis le laisser reposer hors du feu.","Mélanger le gochugaru, le gochujang, la sauce soja, le sucre, l''ail, le gingembre et 1 c. à soupe d''eau en pâte.","Chauffer l''huile dans un wok à feu vif et faire sauter l''oignon, la carotte et le chou 2 à 3 min, jusqu''à ce qu''ils commencent à s''attendrir.","Ajouter les calamars et la pâte et faire sauter 2 à 3 min, juste jusqu''à ce que les calamars deviennent opaques et s''enroulent.","Ajouter le piment et les oignons nouveaux et faire sauter 30 s, puis retirer du feu et incorporer l''huile de sésame.","Servir sur le riz avec les graines de sésame."]},"it":{"title":"Ojingeo bokkeum (calamari saltati piccanti alla coreana) con riso","steps":["Sciacquare il riso e cuocerlo coperto in 195 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Mescolare gochugaru, gochujang, salsa di soia, zucchero, aglio, zenzero e 1 cucchiaio d''acqua fino a ottenere una pasta.","Scaldare l''olio nel wok a fuoco vivo e saltare cipolla, carota e cavolo 2-3 min, finché iniziano ad ammorbidirsi.","Unire i calamari e la pasta e saltare 2-3 min, giusto finché i calamari diventano opachi e si arricciano.","Aggiungere peperoncino e cipollotti e saltare 30 s, poi togliere dal fuoco e unire l''olio di sesamo.","Servire sul riso con i semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b691ac47-1e7f-4fcc-a0c8-e540b5d03fe1')
  returning id
)
