-- Thai green curry salmon with jasmine rice and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bd2199fd-6c52-4d10-a4ca-386b688186d8'::uuid, null, 'Thai green curry salmon with jasmine rice and green beans', 'seed', null, 'Claude', '/recipe-photos/thai-green-curry-salmon-with-jasmine-rice-and-green-beans.webp', '/recipe-photos/thai-green-curry-salmon-with-jasmine-rice-and-green-beans.webp',
    2, null, 30, 10, 20, '["Rinse the rice and simmer it covered in 230 ml water for 12 min on low heat, then rest it 5 min off the heat.","Heat the oil in a deep frying pan and fry the curry paste for 1 min, stirring, until fragrant.","Stir in the coconut milk, stock, fish sauce, sugar and lime leaves and bring to a simmer.","Add the green beans and pepper and simmer 4 min, until just tender.","Slide in the salmon, cover and simmer gently 5-6 min, without stirring much, until the chunks are opaque.","Season with the lime juice, more fish sauce if needed, scatter the Thai basil over and serve with the rice."]'::jsonb,
    array['thai', 'asian', 'curry', 'healthy', 'high protein', 'spicy']::text[], 'thai', 896, 41.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Curry vert thaï au saumon, riz jasmin et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 230 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Chauffer l''huile dans une sauteuse et faire revenir la pâte de curry 1 min en remuant, jusqu''à ce qu''elle embaume.","Ajouter le lait de coco, le bouillon, la sauce de poisson, le sucre et les feuilles de combava, et porter à frémissement.","Ajouter les haricots verts et le poivron et laisser frémir 4 min, jusqu''à ce qu''ils soient juste tendres.","Glisser le saumon, couvrir et laisser frémir doucement 5 à 6 min, sans trop remuer, jusqu''à ce que les morceaux soient opaques.","Assaisonner avec le jus de citron vert, un peu plus de sauce de poisson si besoin, parsemer de basilic thaï et servir avec le riz."]},"it":{"title":"Curry verde thai di salmone con riso jasmine e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 230 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare l''olio in una padella profonda e soffriggere la pasta di curry per 1 min mescolando, finché profuma.","Unire latte di cocco, brodo, salsa di pesce, zucchero e foglie di lime kaffir e portare a sobbollire.","Aggiungere fagiolini e peperone e sobbollire 4 min, finché sono appena teneri.","Unire il salmone, coprire e sobbollire piano 5-6 min, mescolando poco, finché i pezzi sono opachi.","Insaporire con il succo di lime e, se serve, altra salsa di pesce, cospargere di basilico thai e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bd2199fd-6c52-4d10-a4ca-386b688186d8')
  returning id
)
