-- Lemon-oregano salmon with orzo, spinach and tomatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f708ce15-5178-43bc-b7ee-702b77e3e205'::uuid, null, 'Lemon-oregano salmon with orzo, spinach and tomatoes', 'seed', null, 'Claude', '/recipe-photos/lemon-oregano-salmon-with-orzo-spinach-and-tomatoes.webp', '/recipe-photos/lemon-oregano-salmon-with-orzo-spinach-and-tomatoes.webp',
    2, null, 30, 8, 22, '["Season the salmon with salt, pepper, the lemon zest and half the oregano.","Heat the oil in a wide lidded pan and sear the salmon 2 min on each side. Lift it onto a plate.","Soften the onion in the same pan for 3 min, add the garlic, the orzo and the rest of the oregano and stir 1 min.","Pour in the stock and simmer 8 min, stirring often so the orzo doesn''t stick.","Stir in the tomatoes, nestle the salmon on top, cover and cook 6 min on low heat, until the orzo is tender and the salmon flakes.","Lift the salmon out, stir the spinach and lemon juice into the orzo until the leaves wilt, then serve with the salmon on top and the dill over."]'::jsonb,
    array['greek', 'mediterranean', 'one-pot', 'healthy', 'high protein']::text[], 'greek', 764, 46.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saumon citron-origan, orzo, épinards et tomates","steps":["Assaisonner le saumon de sel, de poivre, du zeste de citron et de la moitié de l''origan.","Chauffer l''huile dans une grande sauteuse avec couvercle et saisir le saumon 2 min de chaque côté. Le réserver sur une assiette.","Faire fondre l''oignon dans la même sauteuse 3 min, ajouter l''ail, l''orzo et le reste de l''origan et remuer 1 min.","Verser le bouillon et laisser frémir 8 min en remuant souvent pour que l''orzo n''attache pas.","Ajouter les tomates, poser le saumon dessus, couvrir et cuire 6 min à feu doux, jusqu''à ce que l''orzo soit tendre et que le saumon s''effeuille.","Retirer le saumon, incorporer les épinards et le jus de citron à l''orzo jusqu''à ce que les feuilles tombent, puis servir avec le saumon dessus et l''aneth."]},"it":{"title":"Salmone al limone e origano con orzo, spinaci e pomodorini","steps":["Condire il salmone con sale, pepe, la scorza di limone e metà dell''origano.","Scaldare l''olio in un''ampia padella con coperchio e rosolare il salmone 2 min per lato. Trasferirlo su un piatto.","Appassire la cipolla nella stessa padella per 3 min, unire aglio, orzo e il resto dell''origano e mescolare 1 min.","Versare il brodo e sobbollire 8 min, mescolando spesso perché l''orzo non si attacchi.","Unire i pomodorini, adagiare sopra il salmone, coprire e cuocere 6 min a fuoco basso, finché l''orzo è tenero e il salmone si sfalda.","Togliere il salmone, mescolare spinaci e succo di limone nell''orzo finché le foglie appassiscono, poi servire con il salmone sopra e l''aneto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f708ce15-5178-43bc-b7ee-702b77e3e205')
  returning id
)
