-- Salmon in black bean sauce with noodles and broccoli
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8cd2d154-7c73-419f-bd7a-7e5867400f4e'::uuid, null, 'Salmon in black bean sauce with noodles and broccoli', 'seed', null, 'Claude', '/recipe-photos/salmon-in-black-bean-sauce-with-noodles-and-broccoli.webp', '/recipe-photos/salmon-in-black-bean-sauce-with-noodles-and-broccoli.webp',
    2, null, 27, 12, 15, '["Cook the noodles in boiling water as the packet says, adding the broccoli for the last 2 min. Drain.","Mix the rice wine, soy sauce, sugar and cornstarch with 80 ml water.","Heat half the oil in a wok over high heat, brown the salmon 2 min, turning carefully, and lift it out.","Add the rest of the oil and stir-fry the black beans, garlic, ginger and the white of the spring onions 30 s, then the pepper 2 min.","Pour in the sauce and let it bubble until glossy, about 1 min. Return the salmon and the green of the spring onions and turn gently 1-2 min, until the fish is just cooked.","Serve over the noodles and broccoli."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'healthy', 'high protein']::text[], 'chinese', 806, 43.6,
    false, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saumon sauce aux haricots noirs, nouilles et brocoli","steps":["Cuire les nouilles dans l''eau bouillante selon le paquet en ajoutant le brocoli pour les 2 dernières minutes. Égoutter.","Mélanger le vin de riz, la sauce soja, le sucre et la fécule avec 80 ml d''eau.","Chauffer la moitié de l''huile dans un wok à feu vif, dorer le saumon 2 min en le retournant délicatement, puis le retirer.","Ajouter le reste d''huile et faire sauter les haricots noirs, l''ail, le gingembre et le blanc des oignons nouveaux 30 s, puis le poivron 2 min.","Verser la sauce et laisser bouillonner jusqu''à ce qu''elle soit brillante, environ 1 min. Remettre le saumon et le vert des oignons nouveaux et remuer délicatement 1 à 2 min, jusqu''à ce que le poisson soit juste cuit.","Servir sur les nouilles et le brocoli."]},"it":{"title":"Salmone in salsa di fagioli neri fermentati con noodles e broccoli","steps":["Cuocere i noodles in acqua bollente come indicato sulla confezione, aggiungendo i broccoli negli ultimi 2 min. Scolare.","Mescolare vino di riso, salsa di soia, zucchero e amido con 80 ml d''acqua.","Scaldare metà dell''olio nel wok a fuoco vivo, rosolare il salmone 2 min girandolo con delicatezza e toglierlo.","Aggiungere il resto dell''olio e saltare fagioli neri, aglio, zenzero e la parte bianca dei cipollotti per 30 s, poi il peperone per 2 min.","Versare la salsa e lasciarla bollire finché è lucida, circa 1 min. Rimettere il salmone e la parte verde dei cipollotti e girare piano 1-2 min, finché il pesce è appena cotto.","Servire sopra i noodles e i broccoli."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8cd2d154-7c73-419f-bd7a-7e5867400f4e')
  returning id
)
