-- Sinigang na isda (Filipino sour tamarind hake soup) with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '33a89e95-3c35-4277-a5b4-880b975634ef'::uuid, null, 'Sinigang na isda (Filipino sour tamarind hake soup) with rice', 'seed', null, 'Claude', '/recipe-photos/sinigang-na-isda-filipino-sour-tamarind-hake-soup-with-rice.webp', '/recipe-photos/sinigang-na-isda-filipino-sour-tamarind-hake-soup-with-rice.webp',
    2, null, 30, 10, 20, '["Rinse the rice and simmer it covered in 240 ml water for 12 min on low heat, then rest it 5 min off the heat.","Bring 900 ml water to the boil with the onion and tomatoes and simmer 5 min, until the tomatoes soften.","Add the daikon and eggplant and simmer 5 min.","Stir in the tamarind paste and fish sauce, then add the green beans and chilli and simmer 3 min. Taste: the broth should be clearly sour and salty.","Slide in the hake and poach gently 4-5 min, without stirring, until it flakes.","Add the spinach, let it wilt for 1 min and serve the soup in bowls with the rice alongside."]'::jsonb,
    array['filipino', 'asian', 'soup', 'healthy', 'high protein']::text[], 'filipino', 621, 45.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Sinigang na isda (soupe aigre au tamarin et merlu) et riz","steps":["Rincer le riz et le cuire à couvert dans 240 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Porter 900 ml d''eau à ébullition avec l''oignon et les tomates et laisser frémir 5 min, jusqu''à ce que les tomates ramollissent.","Ajouter le daikon et l''aubergine et laisser frémir 5 min.","Incorporer la pâte de tamarin et la sauce de poisson, puis ajouter les haricots verts et le piment et laisser frémir 3 min. Goûter : le bouillon doit être franchement acide et salé.","Glisser le merlu et le pocher doucement 4 à 5 min, sans remuer, jusqu''à ce qu''il s''effeuille.","Ajouter les épinards, les laisser tomber 1 min et servir la soupe dans des bols avec le riz à côté."]},"it":{"title":"Sinigang na isda (zuppa acidula al tamarindo con nasello) e riso","steps":["Sciacquare il riso e cuocerlo coperto in 240 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Portare a bollore 900 ml d''acqua con cipolla e pomodori e sobbollire 5 min, finché i pomodori si ammorbidiscono.","Aggiungere daikon e melanzana e sobbollire 5 min.","Unire pasta di tamarindo e salsa di pesce, poi aggiungere fagiolini e peperoncino e sobbollire 3 min. Assaggiare: il brodo deve essere decisamente acidulo e sapido.","Unire il nasello e cuocerlo piano 4-5 min, senza mescolare, finché si sfalda.","Aggiungere gli spinaci, lasciarli appassire 1 min e servire la zuppa nelle ciotole con il riso a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '33a89e95-3c35-4277-a5b4-880b975634ef')
  returning id
)
