-- Pescado sudado (Peruvian steamed cod in tomato and ají) with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4ef6481f-d6d1-443e-923f-912d65ebac62'::uuid, null, 'Pescado sudado (Peruvian steamed cod in tomato and ají) with rice', 'seed', null, 'Claude', '/recipe-photos/pescado-sudado-peruvian-steamed-cod-in-tomato-and-aji-with-rice.webp', '/recipe-photos/pescado-sudado-peruvian-steamed-cod-in-tomato-and-aji-with-rice.webp',
    2, null, 30, 10, 20, '["Rinse the rice and simmer it covered in 240 ml salted water for 12 min on low heat, then rest it 5 min off the heat.","Heat the oil in a wide lidded pan and fry the garlic, ají amarillo and cumin 1 min.","Lay in half the onion, pepper and tomato, put the salted cod on top and cover it with the rest of the vegetables.","Pour in the stock and vinegar, scatter half the coriander, cover tightly and steam 10 min over medium-low heat, until the fish flakes.","Taste the juices for salt, then serve the fish and vegetables with their broth over the rice, with the rest of the coriander and lime wedges."]'::jsonb,
    array['peruvian', 'healthy', 'high protein', 'stew']::text[], 'peruvian', 616, 40.2,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pescado sudado (cabillaud à l''étouffée, tomate et ají) et riz","steps":["Rincer le riz et le cuire à couvert dans 240 ml d''eau salée 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Chauffer l''huile dans une grande sauteuse avec couvercle et faire revenir l''ail, l''ají amarillo et le cumin 1 min.","Disposer la moitié de l''oignon, du poivron et de la tomate, poser le cabillaud salé dessus et le recouvrir du reste des légumes.","Verser le fumet et le vinaigre, parsemer de la moitié de la coriandre, couvrir hermétiquement et cuire à l''étouffée 10 min à feu moyen-doux, jusqu''à ce que le poisson s''effeuille.","Goûter le jus et rectifier le sel, puis servir le poisson et les légumes avec leur jus sur le riz, avec le reste de la coriandre et des quartiers de citron vert."]},"it":{"title":"Pescado sudado (merluzzo stufato al pomodoro e ají) con riso","steps":["Sciacquare il riso e cuocerlo coperto in 240 ml d''acqua salata per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare l''olio in un''ampia padella con coperchio e soffriggere aglio, ají amarillo e cumino per 1 min.","Disporre metà della cipolla, del peperone e del pomodoro, adagiare sopra il merluzzo salato e ricoprirlo con il resto delle verdure.","Versare il brodo e l''aceto, cospargere con metà del coriandolo, coprire bene e cuocere al vapore 10 min a fuoco medio-basso, finché il pesce si sfalda.","Assaggiare il sugo e regolare di sale, poi servire pesce e verdure con il loro brodo sul riso, con il resto del coriandolo e spicchi di lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4ef6481f-d6d1-443e-923f-912d65ebac62')
  returning id
)
