-- Chả cá Lã Vọng (turmeric hake with dill and rice noodles)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bb3fc801-6cbe-481c-b05d-fb04dd359d6b'::uuid, null, 'Chả cá Lã Vọng (turmeric hake with dill and rice noodles)', 'seed', null, 'Claude', '/recipe-photos/cha-ca-la-vong-turmeric-hake-with-dill-and-rice-noodles.webp', '/recipe-photos/cha-ca-la-vong-turmeric-hake-with-dill-and-rice-noodles.webp',
    2, null, 30, 15, 15, '["Toss the hake with the turmeric, ginger, half the garlic, 1 tbsp fish sauce, 1 tsp sugar and the cornstarch.","For the dipping sauce, stir the rest of the fish sauce and sugar with the lime juice, 4 tbsp water, the rest of the garlic and the chilli.","Cook the noodles in boiling water as the packet says, rinse under cold water and drain well.","Heat the oil in a frying pan over medium-high heat and fry the fish 2-3 min on each side, until golden and just cooked.","Add the spring onions and dill to the pan and turn them through the fish for 30 s, just until they wilt.","Serve the fish and herbs over the noodles with the lettuce, peanuts and coriander, and the dipping sauce to pour over."]'::jsonb,
    array['vietnamese', 'asian', 'healthy', 'high protein']::text[], 'vietnamese', 705, 41.9,
    false, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Chả cá Lã Vọng (merlu au curcuma, aneth et vermicelles de riz)","steps":["Mélanger le merlu avec le curcuma, le gingembre, la moitié de l''ail, 1 c. à soupe de sauce de poisson, 1 c. à café de sucre et la fécule.","Pour la sauce, mélanger le reste de sauce de poisson et de sucre avec le jus de citron vert, 4 c. à soupe d''eau, le reste de l''ail et le piment.","Cuire les vermicelles dans l''eau bouillante selon le paquet, les rincer à l''eau froide et bien égoutter.","Chauffer l''huile dans une poêle à feu moyen-vif et faire dorer le poisson 2 à 3 min de chaque côté, jusqu''à ce qu''il soit juste cuit.","Ajouter les oignons nouveaux et l''aneth dans la poêle et les mélanger au poisson 30 s, juste le temps qu''ils tombent.","Servir le poisson et les herbes sur les vermicelles avec la salade, les cacahuètes et la coriandre, et la sauce à verser dessus."]},"it":{"title":"Chả cá Lã Vọng (nasello alla curcuma con aneto e vermicelli di riso)","steps":["Condire il nasello con curcuma, zenzero, metà dell''aglio, 1 cucchiaio di salsa di pesce, 1 cucchiaino di zucchero e l''amido.","Per la salsa, mescolare il resto della salsa di pesce e dello zucchero con il succo di lime, 4 cucchiai d''acqua, il resto dell''aglio e il peperoncino.","Cuocere i vermicelli in acqua bollente come indicato sulla confezione, sciacquarli sotto l''acqua fredda e scolarli bene.","Scaldare l''olio in padella a fuoco medio-alto e rosolare il pesce 2-3 min per lato, finché è dorato e appena cotto.","Aggiungere cipollotti e aneto nella padella e girarli con il pesce per 30 s, giusto finché appassiscono.","Servire pesce ed erbe sui vermicelli con lattuga, arachidi e coriandolo, e la salsa da versare sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bb3fc801-6cbe-481c-b05d-fb04dd359d6b')
  returning id
)
