-- Sea bass acqua pazza with cherry tomatoes, fennel and crusty bread
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'da238c68-2dc8-45fe-8dc5-e6e86a857332'::uuid, null, 'Sea bass acqua pazza with cherry tomatoes, fennel and crusty bread', 'seed', null, 'Claude', '/recipe-photos/sea-bass-acqua-pazza-with-cherry-tomatoes-fennel-and-crusty-bread.webp', '/recipe-photos/sea-bass-acqua-pazza-with-cherry-tomatoes-fennel-and-crusty-bread.webp',
    2, null, 28, 10, 18, '["Warm the oil, garlic and chilli in a wide lidded pan over medium heat for 1 min, without letting the garlic brown.","Add the fennel and soften it 4 min, then the tomatoes for 2 min, until they start to collapse.","Pour in the wine and 150 ml water, season with salt and simmer 3 min.","Lay the salted fillets in skin-side down, spoon some broth over, cover and poach on low heat 5-6 min, until the flesh is opaque.","Toast the bread meanwhile.","Serve the fish in shallow bowls with the tomatoes and broth, scatter the parsley over and mop up with the bread."]'::jsonb,
    array['italian', 'mediterranean', 'one-pot', 'healthy', 'high protein']::text[], 'italian', 574, 41.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Bar à l''acqua pazza, tomates cerises, fenouil et pain croustillant","steps":["Chauffer l''huile, l''ail et le piment dans une grande sauteuse avec couvercle à feu moyen 1 min, sans laisser colorer l''ail.","Ajouter le fenouil et le faire fondre 4 min, puis les tomates 2 min, jusqu''à ce qu''elles commencent à s''affaisser.","Verser le vin et 150 ml d''eau, saler et laisser frémir 3 min.","Déposer les filets salés côté peau, les arroser d''un peu de bouillon, couvrir et pocher à feu doux 5 à 6 min, jusqu''à ce que la chair soit opaque.","Pendant ce temps, faire griller le pain.","Servir le poisson dans des assiettes creuses avec les tomates et le bouillon, parsemer de persil et saucer avec le pain."]},"it":{"title":"Branzino all''acqua pazza con pomodorini, finocchio e pane croccante","steps":["Scaldare olio, aglio e peperoncino in un''ampia padella con coperchio a fuoco medio per 1 min, senza far colorire l''aglio.","Aggiungere il finocchio e appassirlo 4 min, poi i pomodorini per 2 min, finché iniziano ad afflosciarsi.","Versare il vino e 150 ml d''acqua, salare e sobbollire 3 min.","Adagiare i filetti salati con la pelle in basso, irrorarli con un po'' di brodo, coprire e cuocere a fuoco basso 5-6 min, finché la carne è opaca.","Intanto tostare il pane.","Servire il pesce in piatti fondi con pomodorini e brodo, cospargere di prezzemolo e fare la scarpetta con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'da238c68-2dc8-45fe-8dc5-e6e86a857332')
  returning id
)
