-- Air-fryer samke harra (spicy cod with tahini) and bulgur
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '17a428e4-0b49-4531-8331-a55c82dad034'::uuid, null, 'Air-fryer samke harra (spicy cod with tahini) and bulgur', 'seed', null, 'Claude', '/recipe-photos/air-fryer-samke-harra-spicy-cod-with-tahini-and-bulgur.webp', '/recipe-photos/air-fryer-samke-harra-spicy-cod-with-tahini-and-bulgur.webp',
    2, null, 30, 10, 20, '["Simmer the bulgur in 300 ml salted water, covered, for 12 min, then leave it 5 min off the heat.","Rub the cod with 1 tsp of the oil, the paprika, cumin and salt, and air-fry at 200°C for 9-10 min, until it flakes.","Meanwhile, soften the onion in the rest of the oil in a frying pan for 6 min, add the garlic, chilli and walnuts and cook 2 min more, then stir in most of the coriander.","Whisk the tahini, yogurt and three quarters of the lemon juice with 3-4 tbsp water and a pinch of salt into a pourable sauce.","Toss the tomato and cucumber with the rest of the lemon juice and a pinch of salt.","Serve the cod on the bulgur, pour over the tahini sauce, pile the spicy onion mixture on top and finish with the rest of the coriander, with the salad on the side."]'::jsonb,
    array['lebanese', 'middle eastern', 'healthy', 'high protein', 'spicy']::text[], 'lebanese', 724, 49,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Samke harra au air fryer (cabillaud épicé au tahini) et boulgour","steps":["Cuire le boulgour à couvert dans 300 ml d''eau salée 12 min, puis le laisser gonfler 5 min hors du feu.","Frotter le cabillaud avec 1 c. à café d''huile, le paprika, le cumin et du sel, puis le cuire au air fryer à 200 °C 9 à 10 min, jusqu''à ce qu''il s''effeuille.","Pendant ce temps, faire fondre l''oignon dans le reste d''huile à la poêle 6 min, ajouter l''ail, le piment et les noix et cuire encore 2 min, puis incorporer presque toute la coriandre.","Fouetter le tahini, le yaourt et les trois quarts du jus de citron avec 3 à 4 c. à soupe d''eau et une pincée de sel pour obtenir une sauce nappante.","Mélanger la tomate et le concombre avec le reste du jus de citron et une pincée de sel.","Servir le cabillaud sur le boulgour, napper de sauce au tahini, couvrir du mélange d''oignons épicés et finir avec le reste de la coriandre, avec la salade à côté."]},"it":{"title":"Samke harra in friggitrice ad aria (merluzzo piccante al tahini) con bulgur","steps":["Cuocere il bulgur coperto in 300 ml d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Massaggiare il merluzzo con 1 cucchiaino d''olio, paprica, cumino e sale, e cuocerlo in friggitrice ad aria a 200 °C per 9-10 min, finché si sfalda.","Intanto appassire la cipolla nel resto dell''olio in padella per 6 min, unire aglio, peperoncino e noci e cuocere altri 2 min, poi aggiungere quasi tutto il coriandolo.","Sbattere tahini, yogurt e tre quarti del succo di limone con 3-4 cucchiai d''acqua e un pizzico di sale fino a ottenere una salsa fluida.","Condire pomodoro e cetriolo con il resto del succo di limone e un pizzico di sale.","Servire il merluzzo sul bulgur, versare la salsa al tahini, coprire con il misto di cipolla piccante e finire con il resto del coriandolo, con l''insalata a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '17a428e4-0b49-4531-8331-a55c82dad034')
  returning id
)
