-- Pasta tonno e zucchine (tuna and courgette pasta with lemon)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd75b1169-6877-4ca8-8496-deb6828a39b3'::uuid, null, 'Pasta tonno e zucchine (tuna and courgette pasta with lemon)', 'seed', null, 'Claude', '/recipe-photos/pasta-tonno-e-zucchine-tuna-and-courgette-pasta-with-lemon.webp', '/recipe-photos/pasta-tonno-e-zucchine-tuna-and-courgette-pasta-with-lemon.webp',
    2, null, 23, 8, 15, '["Cook the pasta in well-salted boiling water until al dente, about 11 min. Keep a cup of the cooking water.","Meanwhile, heat the oil in a large frying pan and soften the shallot and garlic 2 min.","Add the courgettes with a pinch of salt and cook 6-7 min over medium-high heat, until golden in places and tender.","Pour in the wine and let it evaporate, then add the tuna in flakes and the chilli and warm through 2 min.","Drain the pasta and toss it in the pan with a splash of cooking water, the lemon zest and juice and the parsley until glossy.","Serve with the basil and a grind of pepper."]'::jsonb,
    array['italian', 'healthy', 'high protein', 'quick']::text[], 'italian', 605, 33.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pasta tonno e zucchine (pâtes au thon, courgettes et citron)","steps":["Cuire les pâtes al dente dans une grande quantité d''eau bien salée, environ 11 min. Garder une tasse d''eau de cuisson.","Pendant ce temps, chauffer l''huile dans une grande poêle et faire fondre l''échalote et l''ail 2 min.","Ajouter les courgettes avec une pincée de sel et cuire 6 à 7 min à feu moyen-vif, jusqu''à ce qu''elles soient tendres et dorées par endroits.","Verser le vin et le laisser s''évaporer, puis ajouter le thon émietté et le piment et réchauffer 2 min.","Égoutter les pâtes et les faire sauter dans la poêle avec un peu d''eau de cuisson, le zeste et le jus de citron et le persil, jusqu''à ce qu''elles soient brillantes.","Servir avec le basilic et un tour de moulin à poivre."]},"it":{"title":"Pasta tonno e zucchine al limone","steps":["Cuocere la pasta al dente in abbondante acqua ben salata, circa 11 min. Tenere da parte una tazza di acqua di cottura.","Intanto scaldare l''olio in un''ampia padella e appassire scalogno e aglio per 2 min.","Aggiungere le zucchine con un pizzico di sale e cuocere 6-7 min a fuoco medio-alto, finché sono tenere e dorate qua e là.","Sfumare con il vino e lasciarlo evaporare, poi unire il tonno sbriciolato e il peperoncino e scaldare 2 min.","Scolare la pasta e saltarla in padella con un goccio di acqua di cottura, scorza e succo di limone e prezzemolo, finché è lucida.","Servire con il basilico e una macinata di pepe."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd75b1169-6877-4ca8-8496-deb6828a39b3')
  returning id
)
