-- Atún encebollado (tuna with sweet onions) and potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b3af1747-1bd4-4ce2-a8ba-1bed3e564400'::uuid, null, 'Atún encebollado (tuna with sweet onions) and potatoes', 'seed', null, 'Claude', '/recipe-photos/atun-encebollado-tuna-with-sweet-onions-and-potatoes.webp', '/recipe-photos/atun-encebollado-tuna-with-sweet-onions-and-potatoes.webp',
    2, null, 30, 10, 20, '["Boil the potatoes in salted water for 12-14 min, until tender, and drain.","Meanwhile, heat the oil in a wide pan and cook the onions, pepper, garlic and bay leaf with a pinch of salt over medium heat for 12 min, stirring often, until soft and lightly golden.","Stir in the paprika, then the wine and vinegar, and let them bubble 2 min.","Season the tuna with salt, nestle it into the onions, cover and cook 3-4 min on low heat, turning once, until just pink in the centre.","Serve the tuna and onions with the potatoes, spooning the juices over, and scatter with parsley."]'::jsonb,
    array['spanish', 'healthy', 'high protein']::text[], 'spanish', 615, 46.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Atún encebollado (thon aux oignons fondants) et pommes de terre","steps":["Cuire les pommes de terre 12 à 14 min dans l''eau salée, jusqu''à ce qu''elles soient tendres, et égoutter.","Pendant ce temps, chauffer l''huile dans une grande sauteuse et cuire les oignons, le poivron, l''ail et le laurier avec une pincée de sel à feu moyen 12 min en remuant souvent, jusqu''à ce qu''ils soient fondants et légèrement dorés.","Ajouter le paprika, puis le vin et le vinaigre, et laisser bouillonner 2 min.","Saler le thon, l''enfouir dans les oignons, couvrir et cuire 3 à 4 min à feu doux en le retournant une fois, jusqu''à ce qu''il soit juste rosé à cœur.","Servir le thon et les oignons avec les pommes de terre en les arrosant du jus, et parsemer de persil."]},"it":{"title":"Atún encebollado (tonno con cipolle stufate) e patate","steps":["Lessare le patate in acqua salata per 12-14 min, finché sono tenere, e scolarle.","Intanto scaldare l''olio in un''ampia padella e cuocere cipolle, peperone, aglio e alloro con un pizzico di sale a fuoco medio per 12 min, mescolando spesso, finché sono morbidi e leggermente dorati.","Unire la paprica, poi vino e aceto, e lasciar bollire 2 min.","Salare il tonno, adagiarlo tra le cipolle, coprire e cuocere 3-4 min a fuoco basso girandolo una volta, finché è appena rosato al centro.","Servire tonno e cipolle con le patate, irrorando con il sugo, e cospargere di prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b3af1747-1bd4-4ce2-a8ba-1bed3e564400')
  returning id
)
