-- Pan bagnat (Niçoise tuna, egg and tomato sandwich)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a68ec850-a7a8-4494-abc8-c41fa57e15e4'::uuid, null, 'Pan bagnat (Niçoise tuna, egg and tomato sandwich)', 'seed', null, 'Claude', '/recipe-photos/pan-bagnat-nicoise-tuna-egg-and-tomato-sandwich.webp', '/recipe-photos/pan-bagnat-nicoise-tuna-egg-and-tomato-sandwich.webp',
    2, null, 25, 15, 10, '["Lower the eggs into boiling water and cook 9 min, then cool them in cold water, peel and slice.","Split the rolls and rub the cut sides with the garlic.","Whisk the oil and vinegar with a pinch of salt and brush most of it over the cut sides.","Lay the tomatoes on the bottom halves so their juice soaks into the bread, then the pepper, radish and onion.","Add the tuna, egg slices, anchovies, olives and basil, drizzle over the rest of the dressing and close the rolls.","Press each one down firmly with your hand, or wrap and weigh it down for a few minutes, so the bread takes up the juices. Eat now or wrapped on a picnic."]'::jsonb,
    array['french', 'sandwich', 'picnic', 'summer', 'healthy', 'high protein', 'quick']::text[], 'french', 678, 43.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pan bagnat au thon, œuf et tomate","steps":["Plonger les œufs dans l''eau bouillante et les cuire 9 min, puis les refroidir dans l''eau froide, les écaler et les trancher.","Ouvrir les pains et frotter les faces coupées avec l''ail.","Fouetter l''huile et le vinaigre avec une pincée de sel et en badigeonner presque tout sur les faces coupées.","Disposer les tomates sur les moitiés inférieures pour que leur jus imbibe le pain, puis le poivron, les radis et l''oignon.","Ajouter le thon, les tranches d''œuf, les anchois, les olives et le basilic, arroser du reste de vinaigrette et refermer les pains.","Presser fermement chaque pain avec la main, ou l''emballer et le lester quelques minutes, pour que le pain s''imbibe des jus. Déguster aussitôt ou emballé pour un pique-nique."]},"it":{"title":"Pan bagnat (panino nizzardo con tonno, uova e pomodoro)","steps":["Calare le uova in acqua bollente e cuocerle 9 min, poi raffreddarle in acqua fredda, sgusciarle e affettarle.","Aprire i panini e strofinare le superfici tagliate con l''aglio.","Emulsionare olio e aceto con un pizzico di sale e spennellarne quasi tutto sulle superfici tagliate.","Disporre i pomodori sulle metà inferiori perché il loro succo bagni il pane, poi peperone, ravanelli e cipolla.","Aggiungere tonno, fette di uovo, acciughe, olive e basilico, condire con il resto della vinaigrette e chiudere i panini.","Premere bene ogni panino con la mano, oppure avvolgerlo e metterci sopra un peso per qualche minuto, perché il pane assorba i succhi. Mangiare subito o portare incartato per un picnic."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a68ec850-a7a8-4494-abc8-c41fa57e15e4')
  returning id
)
