-- Air-fryer Portuguese sardines with potatoes and roasted pepper salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a2384340-1caf-457a-90aa-b35463171d1f'::uuid, null, 'Air-fryer Portuguese sardines with potatoes and roasted pepper salad', 'seed', null, 'Claude', '/recipe-photos/air-fryer-portuguese-sardines-with-potatoes-and-roasted-pepper-salad.webp', '/recipe-photos/air-fryer-portuguese-sardines-with-potatoes-and-roasted-pepper-salad.webp',
    2, null, 30, 8, 22, '["Boil the potatoes in salted water for 15-18 min, until tender, and drain.","Meanwhile, toss the peppers with 1 tsp of the oil and air-fry at 200°C for 12 min, until soft and blistered.","Toss the hot peppers with the onion, garlic, vinegar, half the remaining oil and a pinch of salt.","Rub the sardines with coarse salt and air-fry them in one layer at 200°C for 8-10 min, turning once, until the skin is crisp and the flesh lifts off the bone.","Toss the potatoes with the rest of the oil, the parsley and salt, and serve with the sardines, the pepper salad and lemon wedges."]'::jsonb,
    array['portuguese', 'mediterranean', 'healthy', 'high protein']::text[], 'portuguese', 682, 44.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Sardines à la portugaise au air fryer, pommes de terre et salade de poivrons grillés","steps":["Cuire les pommes de terre 15 à 18 min dans l''eau salée, jusqu''à ce qu''elles soient tendres, et égoutter.","Pendant ce temps, mélanger les poivrons avec 1 c. à café d''huile et les cuire au air fryer à 200 °C 12 min, jusqu''à ce qu''ils soient tendres et cloqués.","Mélanger les poivrons chauds avec l''oignon, l''ail, le vinaigre, la moitié de l''huile restante et une pincée de sel.","Frotter les sardines de gros sel et les cuire au air fryer en une seule couche à 200 °C 8 à 10 min en les retournant une fois, jusqu''à ce que la peau soit croustillante et que la chair se détache de l''arête.","Mélanger les pommes de terre avec le reste d''huile, le persil et du sel, et servir avec les sardines, la salade de poivrons et des quartiers de citron."]},"it":{"title":"Sardine alla portoghese in friggitrice ad aria con patate e insalata di peperoni arrostiti","steps":["Lessare le patate in acqua salata per 15-18 min, finché sono tenere, e scolarle.","Intanto condire i peperoni con 1 cucchiaino d''olio e cuocerli in friggitrice ad aria a 200 °C per 12 min, finché sono morbidi e abbrustoliti.","Condire i peperoni caldi con cipolla, aglio, aceto, metà dell''olio rimasto e un pizzico di sale.","Strofinare le sardine con sale grosso e cuocerle in friggitrice ad aria in un solo strato a 200 °C per 8-10 min, girandole una volta, finché la pelle è croccante e la carne si stacca dalla lisca.","Condire le patate con il resto dell''olio, il prezzemolo e sale, e servire con le sardine, l''insalata di peperoni e spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a2384340-1caf-457a-90aa-b35463171d1f')
  returning id
)
