-- Pan-fried trout with harissa chickpeas, tomatoes and spinach
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bb8f91b7-7ead-48a7-b419-e1476bfc8284'::uuid, null, 'Pan-fried trout with harissa chickpeas, tomatoes and spinach', 'seed', null, 'Claude', '/recipe-photos/pan-fried-trout-with-harissa-chickpeas-tomatoes-and-spinach.webp', '/recipe-photos/pan-fried-trout-with-harissa-chickpeas-tomatoes-and-spinach.webp',
    2, null, 25, 8, 17, '["Heat two thirds of the oil in a saucepan and soften the onion 4 min, then stir in the garlic, harissa and cumin for 1 min.","Add the tomatoes, chickpeas and stock and simmer 6-8 min, crushing a few chickpeas, until the tomatoes collapse and the sauce thickens.","Stir in the spinach until it wilts and season with salt and a squeeze of lemon.","Meanwhile, season the trout, heat the rest of the oil in a frying pan and cook it skin-side down 3 min, until crisp, then 1 min on the other side.","Serve the trout on the harissa chickpeas with a spoonful of yogurt, the coriander, and lemon wedges."]'::jsonb,
    array['north african', 'healthy', 'high protein', 'quick']::text[], 'north african', 563, 46.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Truite poêlée, pois chiches à la harissa, tomates et épinards","steps":["Chauffer les deux tiers de l''huile dans une casserole et faire fondre l''oignon 4 min, puis ajouter l''ail, la harissa et le cumin 1 min.","Ajouter les tomates, les pois chiches et le bouillon et laisser mijoter 6 à 8 min en écrasant quelques pois chiches, jusqu''à ce que les tomates s''affaissent et que la sauce épaississe.","Incorporer les épinards jusqu''à ce qu''ils tombent et assaisonner de sel et d''un filet de citron.","Pendant ce temps, assaisonner la truite, chauffer le reste de l''huile dans une poêle et la cuire côté peau 3 min, jusqu''à ce qu''elle soit croustillante, puis 1 min de l''autre côté.","Servir la truite sur les pois chiches à la harissa avec une cuillerée de yaourt, la coriandre, et des quartiers de citron."]},"it":{"title":"Trota in padella con ceci alla harissa, pomodorini e spinaci","steps":["Scaldare due terzi dell''olio in una casseruola e appassire la cipolla per 4 min, poi unire aglio, harissa e cumino per 1 min.","Aggiungere pomodorini, ceci e brodo e sobbollire 6-8 min schiacciando qualche cece, finché i pomodorini si disfano e il sugo si addensa.","Unire gli spinaci finché appassiscono e condire con sale e una spruzzata di limone.","Intanto condire la trota, scaldare il resto dell''olio in padella e cuocerla dal lato della pelle per 3 min, finché è croccante, poi 1 min dall''altro lato.","Servire la trota sui ceci alla harissa con un cucchiaio di yogurt, il coriandolo, e spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bb8f91b7-7ead-48a7-b419-e1476bfc8284')
  returning id
