-- Air-fryer balık ekmek (Istanbul mackerel sandwich) with sumac onions
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '22b6241d-3e59-411e-9fd3-2c7eda838123'::uuid, null, 'Air-fryer balık ekmek (Istanbul mackerel sandwich) with sumac onions', 'seed', null, 'Claude', '/recipe-photos/air-fryer-balik-ekmek-istanbul-mackerel-sandwich-with-sumac-onions.webp', '/recipe-photos/air-fryer-balik-ekmek-istanbul-mackerel-sandwich-with-sumac-onions.webp',
    2, null, 22, 12, 10, '["Toss the onion with the sumac, parsley, half the lemon juice and a pinch of salt and leave it to soften.","Rub the mackerel with the oil, chilli flakes and salt.","Air-fry skin-side up at 200°C for 7-8 min, until the skin is crisp and the flesh flakes.","Meanwhile, split the bread and toast the cut sides in a hot dry frying pan for 1-2 min.","Fill the bread with lettuce, tomato and the mackerel, squeeze the rest of the lemon over the fish and pile on the sumac onions."]'::jsonb,
    array['turkish', 'street food', 'sandwich', 'healthy', 'high protein', 'quick']::text[], 'turkish', 679, 40.4,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Balık ekmek au air fryer (sandwich au maquereau d''Istanbul) et oignons au sumac","steps":["Mélanger l''oignon avec le sumac, le persil, la moitié du jus de citron et une pincée de sel, et laisser attendrir.","Frotter le maquereau avec l''huile, le piment et du sel.","Cuire au air fryer côté peau vers le haut à 200 °C 7 à 8 min, jusqu''à ce que la peau soit croustillante et la chair s''effeuille.","Pendant ce temps, ouvrir le pain et toaster les faces coupées dans une poêle sèche bien chaude 1 à 2 min.","Garnir le pain de salade, de tomate et du maquereau, presser le reste du citron sur le poisson et ajouter les oignons au sumac."]},"it":{"title":"Balık ekmek in friggitrice ad aria (panino di sgombro di Istanbul) con cipolle al sommacco","steps":["Condire la cipolla con sommacco, prezzemolo, metà del succo di limone e un pizzico di sale e lasciarla ammorbidire.","Massaggiare lo sgombro con olio, peperoncino e sale.","Cuocere in friggitrice ad aria con la pelle in alto a 200 °C per 7-8 min, finché la pelle è croccante e la carne si sfalda.","Intanto aprire il pane e tostare le superfici tagliate in una padella asciutta ben calda per 1-2 min.","Farcire il pane con lattuga, pomodoro e sgombro, spremere il resto del limone sul pesce e aggiungere le cipolle al sommacco."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '22b6241d-3e59-411e-9fd3-2c7eda838123')
  returning id
)
