-- Pasta con le sarde (Sicilian sardine pasta with fennel, raisins and pine nuts)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3cdabe28-1cd3-448c-8f71-eaae284a4ce1'::uuid, null, 'Pasta con le sarde (Sicilian sardine pasta with fennel, raisins and pine nuts)', 'seed', null, 'Claude', '/recipe-photos/pasta-con-le-sarde-sicilian-sardine-pasta-with-fennel-raisins-and-pine-nuts.webp', '/recipe-photos/pasta-con-le-sarde-sicilian-sardine-pasta-with-fennel-raisins-and-pine-nuts.webp',
    2, null, 30, 10, 20, '["Soak the raisins in hot water and the saffron in 2 tbsp hot water while you start.","Boil the sliced fennel in a large pan of salted water for 6 min, lift it out, then cook the pasta in the same fennel water until al dente.","Meanwhile, toast the breadcrumbs in a large dry frying pan for 2 min, until golden, and tip them out.","Heat the oil in the pan and soften the onion 4 min, then melt in the anchovies.","Add the sardine fillets and cook 3-4 min, breaking them up a little, then stir in the fennel, drained raisins, saffron water, pine nuts and a ladle of pasta water and simmer 2 min.","Drain the pasta, toss it in the sauce until coated, and serve topped with the toasted breadcrumbs and chopped fennel fronds."]'::jsonb,
    array['italian', 'mediterranean', 'healthy', 'high protein']::text[], 'italian', 876, 48.2,
    false, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pasta con le sarde (pâtes siciliennes aux sardines, fenouil, raisins secs et pignons)","steps":["Faire tremper les raisins secs dans de l''eau chaude et le safran dans 2 c. à soupe d''eau chaude pendant que vous commencez.","Cuire le fenouil émincé 6 min dans une grande casserole d''eau salée, le retirer, puis cuire les pâtes al dente dans la même eau.","Pendant ce temps, faire dorer la chapelure 2 min dans une grande poêle sèche et la réserver.","Chauffer l''huile dans la poêle et faire fondre l''oignon 4 min, puis y faire fondre les anchois.","Ajouter les filets de sardine et cuire 3 à 4 min en les émiettant un peu, puis incorporer le fenouil, les raisins égouttés, l''eau safranée, les pignons et une louche d''eau des pâtes, et laisser frémir 2 min.","Égoutter les pâtes, les mélanger à la sauce jusqu''à ce qu''elles soient bien enrobées et servir parsemées de chapelure grillée et de pluches de fenouil hachées."]},"it":{"title":"Pasta con le sarde","steps":["Mettere a bagno l''uvetta in acqua calda e lo zafferano in 2 cucchiai d''acqua calda mentre si inizia.","Lessare il finocchio affettato in una pentola d''acqua salata per 6 min, toglierlo, poi cuocere la pasta al dente nella stessa acqua.","Intanto tostare il pangrattato in un''ampia padella asciutta per 2 min, finché è dorato, e metterlo da parte.","Scaldare l''olio nella padella e appassire la cipolla per 4 min, poi farvi sciogliere le acciughe.","Aggiungere i filetti di sarda e cuocere 3-4 min sbriciolandoli un po'', poi unire finocchio, uvetta scolata, acqua allo zafferano, pinoli e un mestolo di acqua della pasta e sobbollire 2 min.","Scolare la pasta, saltarla nel condimento finché è ben condita e servire con il pangrattato tostato e le barbe di finocchio tritate."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3cdabe28-1cd3-448c-8f71-eaae284a4ce1')
  returning id
)
