-- Air-fryer trout with salsa criolla and corn quinoa
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '15925b98-3003-474e-bb56-1d95b3da4213'::uuid, null, 'Air-fryer trout with salsa criolla and corn quinoa', 'seed', null, 'Claude', '/recipe-photos/air-fryer-trout-with-salsa-criolla-and-corn-quinoa.webp', '/recipe-photos/air-fryer-trout-with-salsa-criolla-and-corn-quinoa.webp',
    2, null, 28, 12, 16, '["Simmer the quinoa in 280 ml salted water, covered, for 15 min. Stir in the corn and leave it 5 min off the heat, lid on.","For the salsa criolla, rinse the onion in cold water, drain and toss with the ají amarillo, the juice of 1.5 limes, 1 tsp oil, half the coriander and a pinch of salt.","Rub the trout with the garlic, cumin, the rest of the oil and salt.","Air-fry skin-side up at 200°C for 6-7 min, until the flesh flakes.","Fluff the quinoa with the rest of the lime juice and coriander, and serve with the trout and the salsa criolla piled on top."]'::jsonb,
    array['peruvian', 'healthy', 'high protein']::text[], 'peruvian', 652, 45.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Truite au air fryer, salsa criolla et quinoa au maïs","steps":["Cuire la quinoa à couvert dans 280 ml d''eau salée 15 min. Ajouter le maïs et laisser 5 min hors du feu, couvercle fermé.","Pour la salsa criolla, rincer l''oignon à l''eau froide, égoutter et le mélanger avec l''ají amarillo, le jus d''un citron vert et demi, 1 c. à café d''huile, la moitié de la coriandre et une pincée de sel.","Frotter la truite avec l''ail, le cumin, le reste de l''huile et du sel.","Cuire au air fryer côté peau vers le haut à 200 °C 6 à 7 min, jusqu''à ce que la chair s''effeuille.","Égrener la quinoa avec le reste du jus de citron vert et de la coriandre, et servir avec la truite et la salsa criolla par-dessus."]},"it":{"title":"Trota in friggitrice ad aria con salsa criolla e quinoa al mais","steps":["Cuocere la quinoa coperta in 280 ml d''acqua salata per 15 min. Unire il mais e lasciare 5 min fuori dal fuoco, con il coperchio.","Per la salsa criolla, sciacquare la cipolla in acqua fredda, scolarla e condirla con ají amarillo, il succo di un lime e mezzo, 1 cucchiaino d''olio, metà del coriandolo e un pizzico di sale.","Massaggiare la trota con aglio, cumino, il resto dell''olio e sale.","Cuocere in friggitrice ad aria con la pelle in alto a 200 °C per 6-7 min, finché la carne si sfalda.","Sgranare la quinoa con il resto del succo di lime e del coriandolo e servire con la trota e la salsa criolla sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '15925b98-3003-474e-bb56-1d95b3da4213')
  returning id
)
