-- Air-fryer tofu satay with rice, cucumber and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5f5e4869-7d40-56ba-bd0a-2e009c50c98d'::uuid, null, 'Air-fryer tofu satay with rice, cucumber and green beans', 'seed', null, 'Claude', '/recipe-photos/air-fryer-tofu-satay-with-rice-cucumber-and-green-beans.webp', '/recipe-photos/air-fryer-tofu-satay-with-rice-cucumber-and-green-beans.webp',
    2, null, 27, 10, 17, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min.","Pat the tofu dry and toss it with the soy sauce, curry powder and turmeric, then with the cornstarch and oil.","Air-fry the tofu at 200°C for 15 min, shaking the basket halfway, until crisp and golden at the edges.","Lay the green beans over the rice, cover again and steam 5 min, then leave off the heat.","Whisk the peanut butter with the soy sauce, lime juice, honey, sriracha, garlic and 3-4 tbsp hot water into a pourable sauce.","Serve the tofu on the rice with the beans and cucumber, spoon the satay sauce over and scatter with spring onion and coriander."]'::jsonb,
    array['malaysian', 'asian', 'vegetarian', 'healthy', 'high protein', 'bowl']::text[], 'malaysian', 771, 41.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Tofu satay au air fryer, riz, concombre et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux pendant 12 min.","Sécher le tofu et l''enrober de sauce soja, de curry et de curcuma, puis de fécule et d''huile.","Cuire le tofu au air fryer à 200 °C pendant 15 min en secouant le panier à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant sur les bords.","Poser les haricots verts sur le riz, recouvrir et cuire à la vapeur 5 min, puis retirer du feu.","Fouetter le beurre de cacahuète avec la sauce soja, le jus de citron vert, le miel, la sriracha, l''ail et 3 à 4 c. à soupe d''eau chaude pour obtenir une sauce fluide.","Servir le tofu sur le riz avec les haricots et le concombre, napper de sauce satay et parsemer d''oignon nouveau et de coriandre."]},"it":{"title":"Tofu satay in friggitrice ad aria con riso, cetriolo e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min.","Asciugare il tofu e condirlo con salsa di soia, curry e curcuma, poi con l''amido e l''olio.","Cuocere il tofu in friggitrice ad aria a 200 °C per 15 min, scuotendo il cestello a metà, finché è dorato e croccante ai bordi.","Disporre i fagiolini sul riso, coprire di nuovo e cuocere a vapore 5 min, poi togliere dal fuoco.","Sbattere il burro di arachidi con salsa di soia, succo di lime, miele, sriracha, aglio e 3-4 cucchiai d''acqua calda fino a una salsa fluida.","Servire il tofu sul riso con fagiolini e cetriolo, nappare con la salsa satay e completare con cipollotto e coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5f5e4869-7d40-56ba-bd0a-2e009c50c98d')
  returning id
)
