-- Air-fryer lemongrass chilli tofu with rice noodles and herbs
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '72a7a213-1c8e-5209-9e43-c124015224dd'::uuid, null, 'Air-fryer lemongrass chilli tofu with rice noodles and herbs', 'seed', null, 'Claude', '/recipe-photos/air-fryer-lemongrass-chilli-tofu-with-rice-noodles-and-herbs.webp', '/recipe-photos/air-fryer-lemongrass-chilli-tofu-with-rice-noodles-and-herbs.webp',
    2, null, 30, 15, 15, '["Mix the lemongrass, shallot, two thirds of the garlic, half the chilli, the soy sauce, sugar, turmeric and oil. Toss the tofu in it.","Air-fry the tofu with all its lemongrass bits at 190°C for 12-15 min, shaking halfway, until golden and crisp.","Cook the noodles in boiling water for 3-4 min, until just tender, then drain and rinse under cold water.","Stir the lime juice, soy sauce, sugar, the rest of the garlic and chilli and 3 tbsp water into a dressing, until the sugar dissolves.","Fill two bowls with lettuce, noodles, cucumber, carrot and bean sprouts.","Top with the tofu, scrape over the crisp lemongrass from the basket, add the herbs and peanuts and pour over the dressing."]'::jsonb,
    array['vietnamese', 'asian', 'vegetarian', 'healthy', 'high protein', 'bowl']::text[], 'vietnamese', 808, 41.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Tofu citronnelle et piment au air fryer, vermicelles de riz et herbes","steps":["Mélanger la citronnelle, l''échalote, les deux tiers de l''ail, la moitié du piment, la sauce soja, le sucre, le curcuma et l''huile. Y rouler le tofu.","Cuire le tofu avec toute sa citronnelle au air fryer à 190 °C pendant 12 à 15 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant.","Cuire les vermicelles 3 à 4 min dans l''eau bouillante, jusqu''à ce qu''ils soient juste tendres, puis les égoutter et les rincer à l''eau froide.","Mélanger le jus de citron vert, la sauce soja, le sucre, le reste d''ail et de piment et 3 c. à soupe d''eau jusqu''à ce que le sucre soit dissous.","Garnir deux bols de salade, de vermicelles, de concombre, de carotte et de germes de soja.","Ajouter le tofu, gratter par-dessus la citronnelle croustillante restée dans le panier, ajouter les herbes et les cacahuètes et arroser de sauce."]},"it":{"title":"Tofu alla citronella e peperoncino in friggitrice ad aria con spaghetti di riso ed erbe","steps":["Mescolare citronella, scalogno, due terzi dell''aglio, metà del peperoncino, salsa di soia, zucchero, curcuma e olio. Passarvi il tofu.","Cuocere il tofu con tutta la sua citronella in friggitrice ad aria a 190 °C per 12-15 min, scuotendo a metà, finché è dorato e croccante.","Cuocere gli spaghetti di riso in acqua bollente per 3-4 min, finché sono appena teneri, poi scolarli e sciacquarli sotto l''acqua fredda.","Mescolare succo di lime, salsa di soia, zucchero, il resto di aglio e peperoncino e 3 cucchiai d''acqua finché lo zucchero si scioglie.","Riempire due ciotole con insalata, spaghetti di riso, cetriolo, carota e germogli di soia.","Aggiungere il tofu, raschiarvi sopra la citronella croccante rimasta nel cestello, unire erbe e arachidi e condire con la salsa."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '72a7a213-1c8e-5209-9e43-c124015224dd')
  returning id
)
