-- Tofu shogayaki with rice and shredded cabbage
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '93f84af9-8cb0-52ab-a5c0-55db1ea75204'::uuid, null, 'Tofu shogayaki with rice and shredded cabbage', 'seed', null, 'Claude', '/recipe-photos/tofu-shogayaki-with-rice-and-shredded-cabbage.webp', '/recipe-photos/tofu-shogayaki-with-rice-and-shredded-cabbage.webp',
    2, null, 28, 10, 18, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Mix the ginger, garlic, soy sauce, mirin, sake and sugar.","Pat the tofu dry and dust it with the cornstarch. Fry it in the oil in a large frying pan over medium-high heat, 3 min per side, until golden.","Push the tofu to the side, add the onion and cook 3 min, until soft.","Pour in the sauce and let it bubble 1-2 min, turning the tofu, until it glazes the slices.","Serve the tofu and onion with their sauce next to the rice, a mound of shredded cabbage and the tomato, with spring onion on top."]'::jsonb,
    array['japanese', 'asian', 'vegetarian', 'healthy', 'high protein']::text[], 'japanese', 753, 36.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tofu shogayaki, riz et chou émincé","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Mélanger le gingembre, l''ail, la sauce soja, le mirin, le saké et le sucre.","Sécher le tofu et le fariner de fécule. Le dorer dans l''huile dans une grande poêle à feu moyen-vif, 3 min de chaque côté.","Pousser le tofu sur le côté, ajouter l''oignon et cuire 3 min, jusqu''à ce qu''il soit tendre.","Verser la sauce et laisser bouillonner 1 à 2 min en retournant le tofu, jusqu''à ce qu''elle le laque.","Servir le tofu et l''oignon avec leur sauce à côté du riz, d''un petit tas de chou émincé et de la tomate, parsemés d''oignon nouveau."]},"it":{"title":"Tofu shogayaki con riso e cavolo a julienne","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Mescolare zenzero, aglio, salsa di soia, mirin, sake e zucchero.","Asciugare il tofu e infarinarlo con l''amido. Rosolarlo nell''olio in una padella larga a fuoco medio-alto, 3 min per lato, finché è dorato.","Spostare il tofu di lato, aggiungere la cipolla e cuocerla 3 min, finché è morbida.","Versare la salsa e lasciarla sobbollire 1-2 min girando il tofu, finché lo glassa.","Servire tofu e cipolla con il loro sugo accanto al riso, a un mucchietto di cavolo a julienne e al pomodoro, con cipollotto sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '93f84af9-8cb0-52ab-a5c0-55db1ea75204')
  returning id
)
