-- Mie goreng with tempeh and egg
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8ec374bf-9573-5d4e-80e0-8501c425e6b4'::uuid, null, 'Mie goreng with tempeh and egg', 'seed', null, 'Claude', '/recipe-photos/mie-goreng-with-tempeh-and-egg.webp', '/recipe-photos/mie-goreng-with-tempeh-and-egg.webp',
    2, null, 25, 10, 15, '["Cook the noodles in boiling water for 3-4 min, drain and rinse under cold water.","Fry the tempeh in 1 tbsp oil in a wok over medium-high heat for 4-5 min, turning, until golden. Lift out.","Add the rest of the oil and stir-fry the shallot, garlic and chilli for 1 min, then the carrot and cabbage for 2 min.","Push the vegetables aside, crack in the eggs and scramble them until just set.","Add the noodles, kecap manis, soy sauce and bean sprouts and toss over high heat for 2 min, until the noodles are glossy and hot.","Toss the tempeh and spring onion back in and serve with lime wedges."]'::jsonb,
    array['indonesian', 'asian', 'vegetarian', 'healthy', 'high protein', 'stir-fry', 'quick']::text[], 'indonesian', 774, 36.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Mie goreng au tempeh et à l''œuf","steps":["Cuire les nouilles 3 à 4 min dans l''eau bouillante, les égoutter et les rincer à l''eau froide.","Faire dorer le tempeh dans 1 c. à soupe d''huile dans un wok à feu moyen-vif 4 à 5 min en le retournant. Le réserver.","Ajouter le reste d''huile et faire sauter l''échalote, l''ail et le piment 1 min, puis la carotte et le chou 2 min.","Pousser les légumes sur le côté, casser les œufs et les brouiller jusqu''à ce qu''ils soient juste pris.","Ajouter les nouilles, le kecap manis, la sauce soja et les germes de soja et faire sauter à feu vif 2 min, jusqu''à ce que les nouilles soient brillantes et chaudes.","Remettre le tempeh et l''oignon nouveau, mélanger et servir avec des quartiers de citron vert."]},"it":{"title":"Mie goreng con tempeh e uovo","steps":["Cuocere i noodles in acqua bollente per 3-4 min, scolarli e sciacquarli sotto l''acqua fredda.","Rosolare il tempeh in 1 cucchiaio d''olio nel wok a fuoco medio-alto per 4-5 min, girandolo, finché è dorato. Toglierlo.","Aggiungere il resto dell''olio e saltare scalogno, aglio e peperoncino per 1 min, poi carota e cavolo per 2 min.","Spostare le verdure di lato, rompere le uova e strapazzarle finché sono appena rapprese.","Aggiungere noodles, kecap manis, salsa di soia e germogli e saltare a fuoco vivo per 2 min, finché i noodles sono lucidi e caldi.","Rimettere tempeh e cipollotto, mescolare e servire con spicchi di lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8ec374bf-9573-5d4e-80e0-8501c425e6b4')
  returning id
)
