-- Pasta e fagioli
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '18921f2f-7942-5bfa-8c44-66a4de953264'::uuid, null, 'Pasta e fagioli', 'seed', null, 'Claude', '/recipe-photos/pasta-e-fagioli.webp', '/recipe-photos/pasta-e-fagioli.webp',
    2, null, 30, 10, 20, '["Soften the onion, carrot and celery in 1 tbsp of the oil in a large pot over medium heat for 6 min.","Add the garlic, rosemary and tomato paste and stir 1 min.","Add the tomatoes, beans and stock, bring to the boil and simmer 3 min.","Scoop out a ladle of beans, mash them with a fork and stir them back in to thicken the soup.","Add the pasta and cook 9-10 min, stirring often, until al dente and the soup is thick. Add a splash of water if it gets too dry.","Remove the rosemary, rest 2 min, then serve with the rest of the oil, black pepper and parmesan."]'::jsonb,
    array['italian', 'vegetarian', 'healthy', 'high protein', 'soup', 'one-pot']::text[], 'italian', 776, 35.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pasta e fagioli (soupe de pâtes aux haricots)","steps":["Faire suer l''oignon, la carotte et le céleri dans 1 c. à soupe d''huile dans une grande casserole à feu moyen 6 min.","Ajouter l''ail, le romarin et le concentré de tomate et remuer 1 min.","Ajouter les tomates, les haricots et le bouillon, porter à ébullition et laisser frémir 3 min.","Prélever une louche de haricots, les écraser à la fourchette et les remettre pour épaissir la soupe.","Ajouter les pâtes et cuire 9 à 10 min en remuant souvent, jusqu''à ce qu''elles soient al dente et la soupe épaisse. Ajouter un peu d''eau si elle devient trop sèche.","Retirer le romarin, laisser reposer 2 min, puis servir avec le reste d''huile, du poivre noir et le parmesan."]},"it":{"title":"Pasta e fagioli","steps":["Far appassire cipolla, carota e sedano in 1 cucchiaio d''olio in una pentola capiente a fuoco medio per 6 min.","Aggiungere aglio, rosmarino e concentrato di pomodoro e mescolare 1 min.","Aggiungere pomodori, fagioli e brodo, portare a bollore e sobbollire 3 min.","Prelevare un mestolo di fagioli, schiacciarli con una forchetta e rimetterli per addensare la minestra.","Aggiungere la pasta e cuocere 9-10 min mescolando spesso, finché è al dente e la minestra è densa. Allungare con poca acqua se si asciuga troppo.","Togliere il rosmarino, lasciar riposare 2 min, poi servire con il resto dell''olio, pepe nero e parmigiano."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '18921f2f-7942-5bfa-8c44-66a4de953264')
  returning id
)
