-- Musabaha with warm pitta and chopped salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0bea3390-8cab-59e2-96c7-b2464bd0572a'::uuid, null, 'Musabaha with warm pitta and chopped salad', 'seed', null, 'Claude', '/recipe-photos/musabaha-with-warm-pitta-and-chopped-salad.webp', '/recipe-photos/musabaha-with-warm-pitta-and-chopped-salad.webp',
    2, null, 25, 10, 15, '["Cover the chickpeas with water in a pan, add the cumin and simmer 10-12 min, until very soft.","Whisk the tahini with three quarters of the lemon juice, the garlic, a pinch of salt and 3-4 tbsp cold water into a smooth sauce.","Mix the tomato, cucumber, onion and parsley with the rest of the lemon juice, 1 tsp of the oil and salt.","Drain the chickpeas, keeping a little liquid. Roughly mash a third of them with half the tahini sauce and 2-3 tbsp of the liquid.","Warm the pitta in the empty pan for 1 min per side.","Spread the mash in bowls, pile the whole chickpeas on top, pour over the rest of the sauce and oil, dust with paprika and serve with the salad and pitta."]'::jsonb,
    array['middle eastern', 'lebanese', 'vegetarian', 'healthy', 'high protein', 'quick']::text[], 'middle eastern', 751, 28.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Musabaha, pita chaude et salade hachée","steps":["Couvrir les pois chiches d''eau dans une casserole, ajouter le cumin et laisser frémir 10 à 12 min, jusqu''à ce qu''ils soient très tendres.","Fouetter le tahini avec les trois quarts du jus de citron, l''ail, une pincée de sel et 3 à 4 c. à soupe d''eau froide pour obtenir une sauce lisse.","Mélanger la tomate, le concombre, l''oignon et le persil avec le reste du jus de citron, 1 c. à café d''huile et du sel.","Égoutter les pois chiches en gardant un peu d''eau de cuisson. Écraser grossièrement un tiers des pois chiches avec la moitié de la sauce tahini et 2 à 3 c. à soupe de liquide.","Réchauffer les pitas dans la casserole vide 1 min de chaque côté.","Étaler la purée dans des bols, poser les pois chiches entiers dessus, arroser du reste de sauce et d''huile, saupoudrer de paprika et servir avec la salade et la pita."]},"it":{"title":"Musabaha con pita calda e insalata tritata","steps":["Coprire i ceci d''acqua in un pentolino, aggiungere il cumino e sobbollire 10-12 min, finché sono molto morbidi.","Sbattere la tahina con tre quarti del succo di limone, l''aglio, un pizzico di sale e 3-4 cucchiai d''acqua fredda fino a una salsa liscia.","Mescolare pomodoro, cetriolo, cipolla e prezzemolo con il resto del succo di limone, 1 cucchiaino d''olio e sale.","Scolare i ceci tenendo un po'' di liquido. Schiacciarne grossolanamente un terzo con metà della salsa tahina e 2-3 cucchiai di liquido.","Scaldare le pite nel pentolino vuoto 1 min per lato.","Stendere la purea nelle ciotole, disporre sopra i ceci interi, condire con il resto della salsa e dell''olio, spolverare di paprika e servire con l''insalata e la pita."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0bea3390-8cab-59e2-96c7-b2464bd0572a')
  returning id
)
