-- Ezogelin soup with mint butter and bread
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '14e68d98-f16b-54ea-bb06-2b58e9a9b9fc'::uuid, null, 'Ezogelin soup with mint butter and bread', 'seed', null, 'Claude', '/recipe-photos/ezogelin-soup-with-mint-butter-and-bread.webp', '/recipe-photos/ezogelin-soup-with-mint-butter-and-bread.webp',
    2, null, 30, 5, 25, '["Soften the onion in the oil in a large pot over medium heat for 4 min.","Stir in the tomato paste and paprika for 1 min, then the grated tomato for 1 min.","Add the lentils, bulgur and stock, bring to the boil and simmer partly covered for 18-20 min, stirring now and then, until the lentils collapse and the soup is thick.","Season with salt, adding a little hot water if it is too thick.","Melt the butter in a small pan, add the dried mint and Aleppo pepper and let it sizzle 30 seconds.","Ladle the soup into bowls, drizzle with the mint butter and serve with lemon wedges and bread."]'::jsonb,
    array['turkish', 'vegetarian', 'healthy', 'high protein', 'soup']::text[], 'turkish', 712, 33.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Soupe ezogelin au beurre de menthe et pain","steps":["Faire suer l''oignon dans l''huile dans une grande casserole à feu moyen 4 min.","Ajouter le concentré de tomate et le paprika et remuer 1 min, puis la tomate râpée 1 min.","Ajouter les lentilles, le boulgour et le bouillon, porter à ébullition et laisser frémir à demi couvert 18 à 20 min en remuant de temps en temps, jusqu''à ce que les lentilles se défassent et que la soupe épaississe.","Saler et ajouter un peu d''eau chaude si elle est trop épaisse.","Faire fondre le beurre dans une petite poêle, ajouter la menthe séchée et le piment d''Alep et laisser grésiller 30 secondes.","Servir la soupe en bols, arroser de beurre à la menthe et servir avec des quartiers de citron et du pain."]},"it":{"title":"Zuppa ezogelin al burro alla menta e pane","steps":["Far appassire la cipolla nell''olio in una pentola capiente a fuoco medio per 4 min.","Unire concentrato di pomodoro e paprika e mescolare 1 min, poi il pomodoro grattugiato per 1 min.","Aggiungere lenticchie, bulgur e brodo, portare a bollore e sobbollire semicoperto per 18-20 min mescolando ogni tanto, finché le lenticchie si sfaldano e la zuppa è densa.","Salare, aggiungendo poca acqua calda se è troppo densa.","Sciogliere il burro in un padellino, aggiungere menta secca e pepe di Aleppo e lasciar sfrigolare 30 secondi.","Versare la zuppa nelle ciotole, condire con il burro alla menta e servire con spicchi di limone e pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '14e68d98-f16b-54ea-bb06-2b58e9a9b9fc')
  returning id
)
