-- Huevos motuleños with black beans and peas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '984accea-cf2e-515c-adc4-8fe25da6a904'::uuid, null, 'Huevos motuleños with black beans and peas', 'seed', null, 'Claude', '/recipe-photos/huevos-motulenos-with-black-beans-and-peas.webp', '/recipe-photos/huevos-motulenos-with-black-beans-and-peas.webp',
    2, null, 28, 10, 18, '["Cook the tomato, onion, garlic and scotch bonnet in 1 tsp of the oil in a pan for 8 min, crushing with a spoon into a chunky sauce. Add the peas for the last 3 min and season.","Meanwhile, warm the beans in a frying pan with 4 tbsp water for 4 min, mashing them into a thick purée. Season and spoon into a bowl; wipe the pan.","Brush the tortillas with a little oil and air-fry them at 180°C for 3-4 min, until lightly crisp but still pliable.","Fry the eggs in the rest of the oil in the frying pan for 3 min, until the whites are set and the yolks runny.","Spread each tortilla with beans and top with a fried egg.","Spoon the tomato and pea sauce over and finish with queso fresco and coriander."]'::jsonb,
    array['mexican', 'vegetarian', 'healthy', 'high protein', 'spicy']::text[], 'mexican', 743, 39.5,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Huevos motuleños aux haricots noirs et petits pois","steps":["Cuire la tomate, l''oignon, l''ail et le piment dans 1 c. à café d''huile dans une casserole 8 min en écrasant à la cuillère pour obtenir une sauce épaisse. Ajouter les petits pois les 3 dernières minutes et assaisonner.","Pendant ce temps, réchauffer les haricots dans une poêle avec 4 c. à soupe d''eau 4 min en les écrasant en purée épaisse. Assaisonner, réserver dans un bol et essuyer la poêle.","Badigeonner les tortillas d''un peu d''huile et les cuire au air fryer à 180 °C pendant 3 à 4 min, jusqu''à ce qu''elles soient légèrement croustillantes mais encore souples.","Faire cuire les œufs au plat dans le reste d''huile dans la poêle 3 min, jusqu''à ce que les blancs soient pris et les jaunes coulants.","Tartiner chaque tortilla de haricots et poser un œuf au plat dessus.","Napper de sauce tomate aux petits pois et finir avec le queso fresco et la coriandre."]},"it":{"title":"Huevos motuleños con fagioli neri e piselli","steps":["Cuocere pomodoro, cipolla, aglio e peperoncino in 1 cucchiaino d''olio in un pentolino per 8 min, schiacciando con un cucchiaio fino a un sugo rustico. Aggiungere i piselli negli ultimi 3 min e regolare di sale.","Nel frattempo scaldare i fagioli in padella con 4 cucchiai d''acqua per 4 min, schiacciandoli in una purea densa. Salare, metterli in una ciotola e pulire la padella.","Spennellare le tortillas con poco olio e cuocerle in friggitrice ad aria a 180 °C per 3-4 min, finché sono appena croccanti ma ancora flessibili.","Cuocere le uova all''occhio di bue nel resto dell''olio nella padella per 3 min, finché l''albume è rappreso e il tuorlo morbido.","Spalmare ogni tortilla di fagioli e metterci sopra un uovo.","Nappare con il sugo di pomodoro e piselli e finire con queso fresco e coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '984accea-cf2e-515c-adc4-8fe25da6a904')
  returning id
)
