-- Egg foo young with rice and soy gravy
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'eceda964-0519-5e5a-b221-5f8a182e1afc'::uuid, null, 'Egg foo young with rice and soy gravy', 'seed', null, 'Claude', '/recipe-photos/egg-foo-young-with-rice-and-soy-gravy.webp', '/recipe-photos/egg-foo-young-with-rice-and-soy-gravy.webp',
    2, null, 28, 10, 18, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Beat the eggs with the soy sauce and white pepper, then stir in the bean sprouts, mushrooms, carrot, peas and spring onion.","Heat half the oil in a frying pan over medium-high heat. Ladle in three patties of the mixture and fry 2 min per side, until golden and set.","Keep them warm on a plate and fry the rest of the mixture the same way in the rest of the oil.","Whisk the stock, both soy sauces, sugar, cornstarch and sesame oil, pour into the pan and stir 1-2 min, until glossy and thickened.","Serve the patties on the rice with the gravy poured over."]'::jsonb,
    array['chinese', 'asian', 'vegetarian', 'healthy', 'high protein']::text[], 'chinese', 766, 35.2,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Egg foo young, riz et sauce au soja","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Battre les œufs avec la sauce soja et le poivre blanc, puis incorporer les germes de soja, les champignons, la carotte, les petits pois et l''oignon nouveau.","Chauffer la moitié de l''huile dans une poêle à feu moyen-vif. Y verser trois galettes de mélange à la louche et les cuire 2 min de chaque côté, jusqu''à ce qu''elles soient dorées et prises.","Les garder au chaud sur une assiette et cuire le reste du mélange de la même façon dans le reste d''huile.","Fouetter le bouillon, les deux sauces soja, le sucre, la fécule et l''huile de sésame, verser dans la poêle et remuer 1 à 2 min, jusqu''à ce que la sauce soit brillante et épaisse.","Servir les galettes sur le riz, nappées de sauce."]},"it":{"title":"Egg foo young con riso e salsa di soia","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Sbattere le uova con salsa di soia e pepe bianco, poi unire germogli, funghi, carota, piselli e cipollotto.","Scaldare metà dell''olio in padella a fuoco medio-alto. Versare con il mestolo tre frittatine di composto e cuocerle 2 min per lato, finché sono dorate e rapprese.","Tenerle in caldo su un piatto e cuocere il resto del composto allo stesso modo nel resto dell''olio.","Sbattere brodo, le due salse di soia, zucchero, amido e olio di sesamo, versare in padella e mescolare 1-2 min, finché la salsa è lucida e densa.","Servire le frittatine sul riso, nappate con la salsa."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'eceda964-0519-5e5a-b221-5f8a182e1afc')
  returning id
)
