-- Air-fryer chilli paneer with Hakka noodles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '2dab32e5-2df9-5f3a-97c8-0e1b1330c3c5'::uuid, null, 'Air-fryer chilli paneer with Hakka noodles', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chilli-paneer-with-hakka-noodles.webp', '/recipe-photos/air-fryer-chilli-paneer-with-hakka-noodles.webp',
    2, null, 25, 10, 15, '["Toss the paneer with 1 tbsp soy sauce and the chili powder, then the cornstarch and 1 tsp of the oil.","Air-fry at 200°C for 10 min, shaking halfway, until golden and crisp at the edges.","Meanwhile, cook the noodles in boiling water for 3-4 min, drain and rinse under cold water.","Heat the rest of the oil in a wok and stir-fry the garlic, ginger and chilli for 30 seconds, then the onion, pepper, cabbage and carrot for 3 min over high heat.","Add the soy sauce, ketchup, vinegar and sriracha with the noodles and toss 2 min, until hot and coated.","Toss in the paneer and spring onion and serve straight away."]'::jsonb,
    array['indian', 'chinese', 'vegetarian', 'healthy', 'high protein', 'stir-fry', 'quick']::text[], 'indian', 795, 28.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Chilli paneer au air fryer et nouilles Hakka","steps":["Enrober le paneer d''1 c. à soupe de sauce soja et du piment du Cachemire, puis de la fécule et d''1 c. à café d''huile.","Cuire au air fryer à 200 °C pendant 10 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant sur les bords.","Pendant ce temps, cuire les nouilles 3 à 4 min dans l''eau bouillante, les égoutter et les rincer à l''eau froide.","Chauffer le reste d''huile dans un wok et faire sauter l''ail, le gingembre et le piment 30 secondes, puis l''oignon, le poivron, le chou et la carotte 3 min à feu vif.","Ajouter la sauce soja, le ketchup, le vinaigre et la sriracha avec les nouilles et faire sauter 2 min, jusqu''à ce que tout soit chaud et enrobé.","Ajouter le paneer et l''oignon nouveau, mélanger et servir aussitôt."]},"it":{"title":"Chilli paneer in friggitrice ad aria con noodles Hakka","steps":["Condire il paneer con 1 cucchiaio di salsa di soia e il peperoncino del Kashmir, poi con l''amido e 1 cucchiaino d''olio.","Cuocere in friggitrice ad aria a 200 °C per 10 min, scuotendo a metà, finché è dorato e croccante ai bordi.","Nel frattempo cuocere i noodles in acqua bollente per 3-4 min, scolarli e sciacquarli sotto l''acqua fredda.","Scaldare il resto dell''olio nel wok e saltare aglio, zenzero e peperoncino per 30 secondi, poi cipolla, peperone, cavolo e carota per 3 min a fuoco vivo.","Aggiungere salsa di soia, ketchup, aceto e sriracha con i noodles e saltare 2 min, finché tutto è caldo e ben condito.","Unire paneer e cipollotto, mescolare e servire subito."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '2dab32e5-2df9-5f3a-97c8-0e1b1330c3c5')
  returning id
)
