-- Halloumi souvlaki with air-fryer lemon potatoes and tzatziki
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b98b523a-deb3-5ab2-9dac-6d5aa531cac0'::uuid, null, 'Halloumi souvlaki with air-fryer lemon potatoes and tzatziki', 'seed', null, 'Claude', '/recipe-photos/halloumi-souvlaki-with-air-fryer-lemon-potatoes-and-tzatziki.webp', '/recipe-photos/halloumi-souvlaki-with-air-fryer-lemon-potatoes-and-tzatziki.webp',
    2, null, 30, 10, 20, '["Toss the potatoes with 2 tsp of the oil, half the oregano, the lemon zest and salt. Air-fry at 200°C for 18-20 min, shaking twice, until golden and tender.","Squeeze the cucumber dry and stir it into the yogurt with the garlic, mint and a pinch of salt to make the tzatziki.","Thread the halloumi, pepper and onion onto skewers and brush with the rest of the oil and oregano.","Cook the skewers in a hot griddle pan for 6-8 min, turning, until the halloumi is golden and the vegetables charred.","Squeeze half the lemon over the potatoes and the rest over the skewers.","Serve the skewers with the potatoes, cherry tomatoes and tzatziki."]'::jsonb,
    array['greek', 'mediterranean', 'vegetarian', 'healthy', 'high protein', 'grill']::text[], 'greek', 784, 39.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Souvlaki de halloumi, pommes de terre au citron au air fryer et tzatziki","steps":["Mélanger les pommes de terre avec 2 c. à café d''huile, la moitié de l''origan, le zeste du citron et du sel. Cuire au air fryer à 200 °C pendant 18 à 20 min en secouant deux fois, jusqu''à ce qu''elles soient dorées et tendres.","Presser le concombre et le mélanger au yaourt avec l''ail, la menthe et une pincée de sel pour faire le tzatziki.","Enfiler le halloumi, le poivron et l''oignon sur des brochettes et les badigeonner du reste d''huile et d''origan.","Cuire les brochettes dans une poêle-gril bien chaude 6 à 8 min en les retournant, jusqu''à ce que le halloumi soit doré et les légumes grillés.","Presser la moitié du citron sur les pommes de terre et le reste sur les brochettes.","Servir les brochettes avec les pommes de terre, les tomates cerises et le tzatziki."]},"it":{"title":"Souvlaki di halloumi con patate al limone in friggitrice ad aria e tzatziki","steps":["Condire le patate con 2 cucchiaini d''olio, metà dell''origano, la scorza del limone e sale. Cuocere in friggitrice ad aria a 200 °C per 18-20 min, scuotendo due volte, finché sono dorate e tenere.","Strizzare il cetriolo e mescolarlo allo yogurt con aglio, menta e un pizzico di sale per fare lo tzatziki.","Infilare halloumi, peperone e cipolla sugli spiedini e spennellarli con il resto dell''olio e dell''origano.","Cuocere gli spiedini su una piastra rovente per 6-8 min, girandoli, finché l''halloumi è dorato e le verdure abbrustolite.","Spremere metà del limone sulle patate e il resto sugli spiedini.","Servire gli spiedini con le patate, i pomodorini e lo tzatziki."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b98b523a-deb3-5ab2-9dac-6d5aa531cac0')
  returning id
)
