-- Air-fryer halloumi fajitas with pico de gallo
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '1083724c-2fbf-5649-a032-0662c173bfc0'::uuid, null, 'Air-fryer halloumi fajitas with pico de gallo', 'seed', null, 'Claude', '/recipe-photos/air-fryer-halloumi-fajitas-with-pico-de-gallo.webp', '/recipe-photos/air-fryer-halloumi-fajitas-with-pico-de-gallo.webp',
    2, null, 25, 10, 15, '["Toss the peppers and three quarters of the onion with the oil, cumin, paprika, chili powder, oregano and a pinch of salt.","Air-fry at 200°C for 8 min, shaking halfway.","Lay the halloumi on top (no salt: it is salty already) and air-fry at 180°C for 6-7 min more, until golden.","Mix the tomatoes, the rest of the onion, finely chopped, the chilli, coriander and the juice of half the lime into a pico de gallo. Stir the rest of the lime juice into the yogurt.","Warm the tortillas in a dry frying pan for 30 seconds per side.","Fill the tortillas with the peppers and halloumi, pico de gallo and lime yogurt."]'::jsonb,
    array['mexican', 'vegetarian', 'healthy', 'high protein', 'wrap', 'quick']::text[], 'mexican', 846, 41.3,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Fajitas de halloumi au air fryer et pico de gallo","steps":["Mélanger les poivrons et les trois quarts de l''oignon avec l''huile, le cumin, le paprika, le piment, l''origan et une pincée de sel.","Cuire au air fryer à 200 °C pendant 8 min en secouant à mi-cuisson.","Poser le halloumi par-dessus (sans saler, il l''est déjà) et cuire au air fryer à 180 °C encore 6 à 7 min, jusqu''à ce qu''il soit doré.","Mélanger les tomates, le reste d''oignon haché fin, le piment, la coriandre et le jus d''un demi-citron vert pour faire le pico de gallo. Ajouter le reste du jus de citron vert au yaourt.","Réchauffer les tortillas dans une poêle sèche 30 secondes de chaque côté.","Garnir les tortillas de poivrons et de halloumi, de pico de gallo et de yaourt au citron vert."]},"it":{"title":"Fajitas di halloumi in friggitrice ad aria con pico de gallo","steps":["Condire i peperoni e tre quarti della cipolla con olio, cumino, paprika, peperoncino, origano e un pizzico di sale.","Cuocere in friggitrice ad aria a 200 °C per 8 min, scuotendo a metà.","Disporre sopra l''halloumi (senza sale, è già sapido) e cuocere in friggitrice ad aria a 180 °C per altri 6-7 min, finché è dorato.","Mescolare pomodori, il resto della cipolla tritata fine, peperoncino, coriandolo e il succo di mezzo lime per il pico de gallo. Unire il resto del succo di lime allo yogurt.","Scaldare le tortillas in una padella asciutta per 30 secondi per lato.","Farcire le tortillas con peperoni e halloumi, pico de gallo e yogurt al lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '1083724c-2fbf-5649-a032-0662c173bfc0')
  returning id
)
