-- Lemon orzo with spinach, chickpeas and feta
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a476feca-aa30-5999-a7c5-c8719997ae14'::uuid, null, 'Lemon orzo with spinach, chickpeas and feta', 'seed', null, 'Claude', '/recipe-photos/lemon-orzo-with-spinach-chickpeas-and-feta.webp', '/recipe-photos/lemon-orzo-with-spinach-chickpeas-and-feta.webp',
    2, null, 23, 8, 15, '["Soften the shallot and garlic in the oil in a deep frying pan over medium heat for 2 min.","Add the orzo and stir 1 min to toast it lightly.","Pour in the stock, bring to a simmer and cook 8 min, stirring often so it doesn''t stick.","Add the chickpeas and cook 2-3 min more, until the orzo is tender and most of the stock is absorbed.","Stir in the spinach until it wilts, then take off the heat and add the lemon zest, the juice of half the lemon and the dill. Season.","Serve topped with the feta and the rest of the lemon in wedges."]'::jsonb,
    array['greek', 'mediterranean', 'vegetarian', 'healthy', 'high protein', 'one-pot', 'quick']::text[], 'greek', 692, 29.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Orzo au citron, épinards, pois chiches et feta","steps":["Faire suer l''échalote et l''ail dans l''huile dans une sauteuse à feu moyen 2 min.","Ajouter l''orzo et remuer 1 min pour le nacrer légèrement.","Verser le bouillon, porter à frémissement et cuire 8 min en remuant souvent pour que ça n''attache pas.","Ajouter les pois chiches et cuire encore 2 à 3 min, jusqu''à ce que l''orzo soit tendre et ait absorbé presque tout le bouillon.","Incorporer les épinards jusqu''à ce qu''ils tombent, puis retirer du feu et ajouter le zeste du citron, le jus d''un demi-citron et l''aneth. Assaisonner.","Servir parsemé de feta, avec le reste du citron en quartiers."]},"it":{"title":"Orzo al limone con spinaci, ceci e feta","steps":["Far appassire scalogno e aglio nell''olio in una padella profonda a fuoco medio per 2 min.","Aggiungere l''orzo e mescolare 1 min per tostarlo leggermente.","Versare il brodo, portare a sobbollire e cuocere 8 min mescolando spesso perché non attacchi.","Aggiungere i ceci e cuocere altri 2-3 min, finché l''orzo è tenero e ha assorbito quasi tutto il brodo.","Unire gli spinaci finché appassiscono, poi togliere dal fuoco e aggiungere la scorza del limone, il succo di mezzo limone e l''aneto. Regolare di sale.","Servire con la feta sopra e il resto del limone a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a476feca-aa30-5999-a7c5-c8719997ae14')
  returning id
)
