-- Ful medames with eggs, pitta and tomato salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '32a459d6-6e4c-5c14-99e3-530a6b68ae80'::uuid, null, 'Ful medames with eggs, pitta and tomato salad', 'seed', null, 'Claude', '/recipe-photos/ful-medames-with-eggs-pitta-and-tomato-salad.webp', '/recipe-photos/ful-medames-with-eggs-pitta-and-tomato-salad.webp',
    2, null, 25, 10, 15, '["Boil the eggs for 8 min, cool them in cold water and peel.","Fry the onion and cumin in 2 tsp of the oil in a pan over medium heat for 3 min, then add the garlic and chilli for 1 min.","Add the beans and 100 ml water, bring to the boil and simmer 5 min.","Crush the beans roughly with a potato masher, leaving some whole, and stir in two thirds of the lemon juice and salt.","Toss the tomato, cucumber and parsley with the rest of the lemon juice and salt. Warm the pitta in a dry pan for 1 min per side.","Spoon the ful into bowls, drizzle with the tahini thinned with a little water and the rest of the oil, and serve with the halved eggs, salad and pitta."]'::jsonb,
    array['middle eastern', 'african', 'vegetarian', 'healthy', 'high protein', 'quick']::text[], 'middle eastern', 664, 34.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Ful medames aux œufs, pita et salade de tomates","steps":["Cuire les œufs 8 min dans l''eau bouillante, les refroidir à l''eau froide et les écaler.","Faire revenir l''oignon et le cumin dans 2 c. à café d''huile dans une casserole à feu moyen 3 min, puis ajouter l''ail et le piment 1 min.","Ajouter les fèves et 100 ml d''eau, porter à ébullition et laisser frémir 5 min.","Écraser grossièrement les fèves au presse-purée en en laissant quelques-unes entières, puis ajouter les deux tiers du jus de citron et du sel.","Mélanger la tomate, le concombre et le persil avec le reste du jus de citron et du sel. Réchauffer les pitas dans une poêle sèche 1 min de chaque côté.","Répartir le ful dans des bols, arroser du tahini allongé d''un peu d''eau et du reste d''huile, et servir avec les œufs coupés en deux, la salade et la pita."]},"it":{"title":"Ful medames con uova, pita e insalata di pomodori","steps":["Cuocere le uova in acqua bollente per 8 min, raffreddarle in acqua fredda e sgusciarle.","Soffriggere cipolla e cumino in 2 cucchiaini d''olio in un pentolino a fuoco medio per 3 min, poi aggiungere aglio e peperoncino per 1 min.","Aggiungere le fave e 100 ml d''acqua, portare a bollore e sobbollire 5 min.","Schiacciare grossolanamente le fave con lo schiacciapatate lasciandone alcune intere, poi unire due terzi del succo di limone e sale.","Condire pomodoro, cetriolo e prezzemolo con il resto del succo di limone e sale. Scaldare le pite in una padella asciutta 1 min per lato.","Distribuire il ful nelle ciotole, condire con la tahina allungata con poca acqua e il resto dell''olio e servire con le uova tagliate a metà, l''insalata e la pita."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '32a459d6-6e4c-5c14-99e3-530a6b68ae80')
  returning id
)
