-- Kuru fasulye with rice pilaf and cacık
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f2420a6b-ce8c-5857-8883-92d0993e81dc'::uuid, null, 'Kuru fasulye with rice pilaf and cacık', 'seed', null, 'Claude', '/recipe-photos/kuru-fasulye-with-rice-pilaf-and-cacik.webp', '/recipe-photos/kuru-fasulye-with-rice-pilaf-and-cacik.webp',
    2, null, 30, 8, 22, '["Rinse the rice and fry it in the butter in a small pan for 1 min, then add 250 ml boiling water and a pinch of salt, cover and cook on low heat 12 min. Rest 5 min off the heat.","Soften the onion and pepper in the oil in a pan over medium heat for 5 min, then add the garlic for 1 min.","Stir in the tomato paste and Aleppo pepper for 1 min, then the tomatoes.","Add the beans and 250 ml water and simmer 12-15 min, until the sauce is thick and the beans have soaked up the flavour. Season.","For the cacık, squeeze the cucumber and stir it into the yogurt with the garlic, half the mint, a splash of water and salt.","Fluff the rice, top it with the beans and serve with the cacık sprinkled with the rest of the mint."]'::jsonb,
    array['turkish', 'vegetarian', 'healthy', 'high protein', 'stew']::text[], 'turkish', 846, 35.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Kuru fasulye (haricots blancs à la turque), pilaf de riz et cacık","steps":["Rincer le riz et le nacrer dans le beurre dans une petite casserole 1 min, puis ajouter 250 ml d''eau bouillante et une pincée de sel, couvrir et cuire à feu doux 12 min. Laisser reposer 5 min hors du feu.","Faire suer l''oignon et le poivron dans l''huile dans une casserole à feu moyen 5 min, puis ajouter l''ail 1 min.","Ajouter le concentré de tomate et le piment d''Alep et remuer 1 min, puis les tomates.","Ajouter les haricots et 250 ml d''eau et laisser mijoter 12 à 15 min, jusqu''à ce que la sauce épaississe et que les haricots s''en imprègnent. Assaisonner.","Pour le cacık, presser le concombre et le mélanger au yaourt avec l''ail, la moitié de la menthe, un peu d''eau et du sel.","Égrener le riz, le napper de haricots et servir avec le cacık parsemé du reste de menthe."]},"it":{"title":"Kuru fasulye (fagioli bianchi alla turca) con pilaf di riso e cacık","steps":["Sciacquare il riso e tostarlo nel burro in un pentolino per 1 min, poi aggiungere 250 ml d''acqua bollente e un pizzico di sale, coprire e cuocere a fuoco basso 12 min. Lasciar riposare 5 min fuori dal fuoco.","Far appassire cipolla e peperone nell''olio in una casseruola a fuoco medio per 5 min, poi aggiungere l''aglio per 1 min.","Unire concentrato di pomodoro e pepe di Aleppo e mescolare 1 min, poi i pomodori.","Aggiungere i fagioli e 250 ml d''acqua e sobbollire 12-15 min, finché il sugo è denso e i fagioli si sono insaporiti. Regolare di sale.","Per il cacık, strizzare il cetriolo e mescolarlo allo yogurt con aglio, metà della menta, un goccio d''acqua e sale.","Sgranare il riso, coprirlo con i fagioli e servire con il cacık cosparso con il resto della menta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f2420a6b-ce8c-5857-8883-92d0993e81dc')
  returning id
)
