-- Piperade with soft scrambled eggs and country bread
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'da583daf-e2c4-5b19-a514-ea13247580cd'::uuid, null, 'Piperade with soft scrambled eggs and country bread', 'seed', null, 'Claude', '/recipe-photos/piperade-with-soft-scrambled-eggs-and-country-bread.webp', '/recipe-photos/piperade-with-soft-scrambled-eggs-and-country-bread.webp',
    2, null, 30, 10, 20, '["Soften the onion and peppers in the oil in a wide frying pan over medium heat for 10 min, stirring, until soft but not browned.","Add the garlic and thyme for 1 min, then the tomatoes and half the Espelette pepper. Cook 6-7 min, until the juices have mostly evaporated. Season.","Toast the bread while the vegetables finish.","Beat the eggs with a pinch of salt, lower the heat and pour them over the vegetables.","Stir gently for 1-2 min, until the eggs form soft, creamy curds, and take the pan off the heat while they are still slightly loose.","Sprinkle with the rest of the Espelette pepper and the parsley and serve with the toasted bread."]'::jsonb,
    array['french', 'vegetarian', 'healthy', 'high protein']::text[], 'french', 616, 31.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Piperade aux œufs brouillés et pain de campagne","steps":["Faire fondre l''oignon et les poivrons dans l''huile dans une grande poêle à feu moyen 10 min en remuant, jusqu''à ce qu''ils soient tendres sans colorer.","Ajouter l''ail et le thym 1 min, puis les tomates et la moitié du piment d''Espelette. Cuire 6 à 7 min, jusqu''à ce que le jus soit presque évaporé. Assaisonner.","Griller le pain pendant que les légumes finissent de cuire.","Battre les œufs avec une pincée de sel, baisser le feu et les verser sur les légumes.","Remuer doucement 1 à 2 min, jusqu''à ce que les œufs forment des grumeaux moelleux et crémeux, et retirer la poêle du feu quand ils sont encore un peu baveux.","Saupoudrer du reste de piment d''Espelette et de persil et servir avec le pain grillé."]},"it":{"title":"Piperade con uova strapazzate morbide e pane casereccio","steps":["Far appassire cipolla e peperoni nell''olio in una padella larga a fuoco medio per 10 min, mescolando, finché sono morbidi ma non coloriti.","Aggiungere aglio e timo per 1 min, poi i pomodori e metà del peperoncino d''Espelette. Cuocere 6-7 min, finché il liquido è quasi evaporato. Regolare di sale.","Tostare il pane mentre le verdure finiscono di cuocere.","Sbattere le uova con un pizzico di sale, abbassare il fuoco e versarle sulle verdure.","Mescolare delicatamente per 1-2 min, finché le uova formano grumi morbidi e cremosi, e togliere dal fuoco quando sono ancora leggermente morbide.","Cospargere con il resto del peperoncino d''Espelette e il prezzemolo e servire con il pane tostato."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'da583daf-e2c4-5b19-a514-ea13247580cd')
  returning id
)
