-- Black bean and quinoa bowls with corn salsa and avocado
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '52eefa89-ce22-5513-9f00-9911d9455167'::uuid, null, 'Black bean and quinoa bowls with corn salsa and avocado', 'seed', null, 'Claude', '/recipe-photos/black-bean-and-quinoa-bowls-with-corn-salsa-and-avocado.webp', '/recipe-photos/black-bean-and-quinoa-bowls-with-corn-salsa-and-avocado.webp',
    2, null, 25, 10, 15, '["Simmer the quinoa in 300 ml salted water, covered, for 13-15 min, until the water is absorbed. Rest 2 min and fluff.","Warm the oil in a pan with the garlic, cumin and chili powder for 1 min, add the beans and 3 tbsp water and heat 4-5 min. Add the juice of half a lime and salt.","Mix the corn, pepper, tomato, onion, chilli and half the coriander with the juice of 1 lime and salt.","Toss the avocado with the rest of the lime juice.","Fill bowls with quinoa, add the beans, corn salsa and avocado and finish with the rest of the coriander."]'::jsonb,
    array['american', 'mexican', 'vegetarian', 'healthy', 'high protein', 'bowl', 'quick']::text[], 'american', 837, 35.3,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Bols de quinoa aux haricots noirs, salsa de maïs et avocat","steps":["Cuire le quinoa à couvert dans 300 ml d''eau salée 13 à 15 min, jusqu''à absorption de l''eau. Laisser reposer 2 min et l''égrener.","Chauffer l''huile dans une poêle avec l''ail, le cumin et le piment 1 min, ajouter les haricots et 3 c. à soupe d''eau et réchauffer 4 à 5 min. Ajouter le jus d''un demi-citron vert et du sel.","Mélanger le maïs, le poivron, la tomate, l''oignon, le piment et la moitié de la coriandre avec le jus d''un citron vert et du sel.","Arroser l''avocat du reste de jus de citron vert.","Remplir des bols de quinoa, ajouter les haricots, la salsa de maïs et l''avocat et finir avec le reste de coriandre."]},"it":{"title":"Bowl di quinoa e fagioli neri con salsa di mais e avocado","steps":["Cuocere la quinoa coperta in 300 ml d''acqua salata per 13-15 min, finché l''acqua è assorbita. Lasciar riposare 2 min e sgranarla.","Scaldare l''olio in padella con aglio, cumino e peperoncino per 1 min, aggiungere i fagioli e 3 cucchiai d''acqua e scaldare 4-5 min. Unire il succo di mezzo lime e sale.","Mescolare mais, peperone, pomodoro, cipolla, peperoncino e metà del coriandolo con il succo di 1 lime e sale.","Condire l''avocado con il resto del succo di lime.","Riempire le ciotole con la quinoa, aggiungere fagioli, salsa di mais e avocado e finire con il resto del coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '52eefa89-ce22-5513-9f00-9911d9455167')
  returning id
)
