-- Poulet à la moutarde with steamed potatoes and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7c0e8388-e897-555c-9ea0-ba6b55bb6a19'::uuid, null, 'Poulet à la moutarde with steamed potatoes and green beans', 'seed', null, 'Claude', '/recipe-photos/poulet-a-la-moutarde-with-steamed-potatoes-and-green-beans.webp', '/recipe-photos/poulet-a-la-moutarde-with-steamed-potatoes-and-green-beans.webp',
    2, null, 30, 10, 20, '["Boil the potatoes in salted water for 15 min, adding the green beans for the last 6 min, then drain.","Season the chicken and brown it in the oil and butter over medium-high heat for 4-5 min until golden all over, then lift it out.","Soften the shallots in the same pan for 2 min, pour in the wine and let it bubble until reduced by half, about 2 min.","Add the stock, thyme and chicken and simmer for 5 min until the chicken is cooked through.","Stir in both mustards and the crème fraîche and simmer gently for 2 min until the sauce coats a spoon; do not let it boil hard.","Serve the chicken and sauce with the potatoes and beans, scattered with parsley."]'::jsonb,
    array['french', 'quick', 'comfort']::text[], 'french', 773, 49.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet à la moutarde, pommes vapeur et haricots verts","steps":["Cuire les pommes de terre 15 min dans l''eau salée en ajoutant les haricots verts pour les 6 dernières minutes, puis égoutter.","Saler et poivrer le poulet et le dorer dans l''huile et le beurre à feu moyen-vif 4 à 5 min, puis le réserver.","Faire revenir les échalotes 2 min dans la même poêle, verser le vin et laisser réduire de moitié, environ 2 min.","Ajouter le bouillon, le thym et le poulet et laisser mijoter 5 min jusqu''à ce que le poulet soit cuit à cœur.","Incorporer les deux moutardes et la crème fraîche et mijoter doucement 2 min jusqu''à ce que la sauce nappe la cuillère, sans faire bouillir fort.","Servir le poulet et sa sauce avec les pommes de terre et les haricots, parsemé de persil."]},"it":{"title":"Pollo alla senape con patate al vapore e fagiolini","steps":["Lessare le patate in acqua salata per 15 min aggiungendo i fagiolini negli ultimi 6 min, poi scolare.","Salare e pepare il pollo e rosolarlo nell''olio e nel burro a fuoco medio-alto per 4-5 min, poi metterlo da parte.","Appassire gli scalogni nella stessa padella per 2 min, versare il vino e lasciarlo ridurre della metà, circa 2 min.","Aggiungere il brodo, il timo e il pollo e sobbollire 5 min finché il pollo è cotto.","Unire le due senapi e la crème fraîche e sobbollire piano 2 min finché la salsa vela il cucchiaio, senza farla bollire forte.","Servire il pollo con la salsa, le patate e i fagiolini, con prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7c0e8388-e897-555c-9ea0-ba6b55bb6a19')
  returning id
)
