-- Chicken marsala with tagliatelle and spinach
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e4d19897-95ca-5b08-bc75-a7524f426999'::uuid, null, 'Chicken marsala with tagliatelle and spinach', 'seed', null, 'Claude', '/recipe-photos/chicken-marsala-with-tagliatelle-and-spinach.webp', '/recipe-photos/chicken-marsala-with-tagliatelle-and-spinach.webp',
    2, null, 28, 10, 18, '["Bring a large pan of salted water to the boil for the pasta.","Pound the chicken pieces to an even 1 cm, season them and dust lightly with the flour.","Fry the chicken in the oil over medium-high heat for 3 min a side until golden and cooked through, then set aside.","Brown the mushrooms in the same pan for 5 min, then add the garlic for 30 seconds.","Cook the tagliatelle as the packet says, about 8 min.","Pour the marsala into the mushrooms and let it bubble for 2 min, add the stock and simmer 3 min until slightly syrupy.","Return the chicken for 1-2 min to warm through, then swirl in the butter off the heat.","Drain the pasta, toss the spinach through it until wilted, and serve with the chicken and mushroom sauce and parsley."]'::jsonb,
    array['italian', 'quick']::text[], 'italian', 779, 54.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet au marsala, tagliatelles et épinards","steps":["Porter à ébullition une grande casserole d''eau salée pour les pâtes.","Aplatir les morceaux de poulet à 1 cm d''épaisseur, les assaisonner et les fariner légèrement.","Cuire le poulet dans l''huile à feu moyen-vif 3 min de chaque côté jusqu''à ce qu''il soit doré et cuit, puis le réserver.","Faire dorer les champignons 5 min dans la même poêle, puis ajouter l''ail 30 secondes.","Cuire les tagliatelles selon le paquet, environ 8 min.","Verser le marsala sur les champignons et laisser bouillonner 2 min, ajouter le bouillon et mijoter 3 min jusqu''à une sauce un peu sirupeuse.","Remettre le poulet 1 à 2 min pour le réchauffer, puis incorporer le beurre hors du feu.","Égoutter les pâtes, y mélanger les épinards jusqu''à ce qu''ils tombent, et servir avec le poulet, la sauce aux champignons et le persil."]},"it":{"title":"Pollo al marsala con tagliatelle e spinaci","steps":["Portare a bollore una pentola capiente di acqua salata per la pasta.","Battere i pezzi di pollo a 1 cm di spessore, condirli e infarinarli leggermente.","Cuocere il pollo nell''olio a fuoco medio-alto 3 min per lato finché è dorato e cotto, poi metterlo da parte.","Rosolare i funghi nella stessa padella per 5 min, poi aggiungere l''aglio per 30 secondi.","Cuocere le tagliatelle come indicato sulla confezione, circa 8 min.","Sfumare i funghi con il marsala per 2 min, aggiungere il brodo e sobbollire 3 min finché la salsa è leggermente sciropposa.","Rimettere il pollo per 1-2 min, poi mantecare con il burro a fuoco spento.","Scolare la pasta, mescolarvi gli spinaci finché appassiscono e servire con il pollo, la salsa ai funghi e il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e4d19897-95ca-5b08-bc75-a7524f426999')
  returning id
)
