-- Riz a djej (Lebanese chicken and vermicelli rice) with toasted nuts and salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bb33dad4-b7b9-5152-8e07-42e7fc9d9b6b'::uuid, null, 'Riz a djej (Lebanese chicken and vermicelli rice) with toasted nuts and salad', 'seed', null, 'Claude', '/recipe-photos/riz-a-djej-lebanese-chicken-and-vermicelli-rice-with-toasted-nuts-and-salad.webp', '/recipe-photos/riz-a-djej-lebanese-chicken-and-vermicelli-rice-with-toasted-nuts-and-salad.webp',
    2, null, 30, 10, 20, '["Simmer the chicken in the stock with the cinnamon stick, bay leaf and cardamom, covered, for 15 min until cooked through.","Meanwhile fry the vermicelli in the oil over medium heat for 2 min, stirring, until deep golden.","Stir in the rice, allspice, ground cinnamon and plenty of black pepper, then ladle in 300 ml of the hot stock from the chicken pan.","Cover the rice and cook on low heat for 15 min, then leave it to steam off the heat for 3 min.","Toast the almonds and pine nuts in a dry pan for 2-3 min until golden.","Toss the tomato, cucumber and parsley with the lemon juice and a pinch of salt.","Lift out the chicken, shred it, season with salt and a little allspice and moisten with a spoon of stock.","Pile the chicken on the rice, scatter with the nuts and serve with the salad and yogurt."]'::jsonb,
    array['lebanese', 'middle eastern', 'healthy']::text[], 'lebanese', 808, 57.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Riz a djej (poulet et riz aux vermicelles libanais), fruits secs grillés et salade","steps":["Cuire le poulet à couvert dans le bouillon avec le bâton de cannelle, le laurier et la cardamome 15 min, jusqu''à cuisson à cœur.","Pendant ce temps, faire revenir les vermicelles dans l''huile à feu moyen 2 min en remuant, jusqu''à ce qu''ils soient bien dorés.","Ajouter le riz, le piment de la Jamaïque, la cannelle moulue et du poivre, puis verser 300 ml du bouillon chaud du poulet.","Couvrir et cuire le riz à feu doux 15 min, puis le laisser gonfler hors du feu 3 min.","Faire griller les amandes et les pignons à sec 2 à 3 min jusqu''à ce qu''ils soient dorés.","Mélanger la tomate, le concombre et le persil avec le jus de citron et une pincée de sel.","Sortir le poulet, l''effilocher, l''assaisonner de sel et d''un peu de piment de la Jamaïque et l''humidifier d''une cuillerée de bouillon.","Disposer le poulet sur le riz, parsemer de fruits secs et servir avec la salade et le yaourt."]},"it":{"title":"Riz a djej (pollo e riso con vermicelli alla libanese) con frutta secca tostata e insalata","steps":["Cuocere il pollo coperto nel brodo con la stecca di cannella, l''alloro e il cardamomo per 15 min, finché è cotto.","Nel frattempo tostare i vermicelli nell''olio a fuoco medio per 2 min, mescolando, finché sono ben dorati.","Unire il riso, il pimento, la cannella in polvere e abbondante pepe, poi versare 300 ml del brodo caldo del pollo.","Coprire e cuocere il riso a fuoco basso per 15 min, poi lasciarlo riposare fuori dal fuoco 3 min.","Tostare mandorle e pinoli in padella asciutta per 2-3 min finché sono dorati.","Condire pomodoro, cetriolo e prezzemolo con il succo di limone e un pizzico di sale.","Togliere il pollo, sfilacciarlo, condirlo con sale e un po'' di pimento e bagnarlo con un cucchiaio di brodo.","Disporre il pollo sul riso, cospargere di frutta secca e servire con l''insalata e lo yogurt."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bb33dad4-b7b9-5152-8e07-42e7fc9d9b6b')
  returning id
)
