-- Hunter's chicken with air-fryer wedges and peas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c89ba93f-ed33-576d-9ff1-98d36515c932'::uuid, null, 'Hunter''s chicken with air-fryer wedges and peas', 'seed', null, 'Claude', '/recipe-photos/hunter-s-chicken-with-air-fryer-wedges-and-peas.webp', '/recipe-photos/hunter-s-chicken-with-air-fryer-wedges-and-peas.webp',
    2, null, 30, 8, 22, '["Heat the oven to 200°C.","Toss the potato wedges with the oil, paprika and salt and air-fry at 200°C for 20-22 min, shaking twice, until crisp and golden.","Season the chicken breasts, wrap each in bacon rashers and lay them seam-side down on a lined tray.","Bake the chicken for 18 min until the bacon is crisp and the chicken is nearly cooked through.","Spoon the barbecue sauce over the chicken, top with the cheddar and bake 5 min more until bubbling and cooked through (75°C inside).","Simmer the peas in salted water for 3 min and drain.","Serve the chicken with the wedges and peas."]'::jsonb,
    array['british', 'comfort', 'kid-friendly', 'fakeaway']::text[], 'british', 821, 56.1,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet hunter''s (lard, sauce barbecue et cheddar), potatoes au air fryer et petits pois","steps":["Préchauffer le four à 200 °C.","Mélanger les quartiers de pommes de terre avec l''huile, le paprika et du sel et les cuire au air fryer à 200 °C pendant 20 à 22 min en secouant deux fois, jusqu''à ce qu''ils soient dorés et croustillants.","Assaisonner les blancs de poulet, les enrouler de tranches de lard et les poser jointure dessous sur une plaque recouverte de papier.","Cuire le poulet 18 min au four jusqu''à ce que le lard soit croustillant et le poulet presque cuit.","Napper le poulet de sauce barbecue, couvrir de cheddar et cuire encore 5 min jusqu''à ce que ça bouillonne et que le poulet soit cuit (75 °C à cœur).","Cuire les petits pois 3 min dans l''eau salée et les égoutter.","Servir le poulet avec les potatoes et les petits pois."]},"it":{"title":"Pollo hunter''s (pancetta, salsa barbecue e cheddar) con spicchi di patate in friggitrice ad aria e piselli","steps":["Scaldare il forno a 200 °C.","Condire gli spicchi di patate con olio, paprika e sale e cuocerli in friggitrice ad aria a 200 °C per 20-22 min, scuotendo due volte, finché sono dorati e croccanti.","Condire i petti di pollo, avvolgerli nelle fette di pancetta e disporli con la chiusura verso il basso su una teglia foderata.","Cuocere il pollo in forno per 18 min finché la pancetta è croccante e il pollo quasi cotto.","Coprire il pollo con la salsa barbecue e il cheddar e cuocere altri 5 min finché bolle e il pollo è cotto (75 °C al cuore).","Lessare i piselli in acqua salata per 3 min e scolarli.","Servire il pollo con gli spicchi di patate e i piselli."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c89ba93f-ed33-576d-9ff1-98d36515c932')
  returning id
)
