-- Moroccan chicken tagine with potatoes and peas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '80957d70-d4e9-5143-b879-cbd5c4ce5d2e'::uuid, null, 'Moroccan chicken tagine with potatoes and peas', 'seed', null, 'Claude', '/recipe-photos/moroccan-chicken-tagine-with-potatoes-and-peas.webp', '/recipe-photos/moroccan-chicken-tagine-with-potatoes-and-peas.webp',
    2, null, 30, 8, 22, '["Toss the chicken with the ginger, turmeric, pepper, saffron and a pinch of salt.","Cook the onion and garlic in the oil in a wide pan or tagine over medium heat for 3 min, add the chicken and turn it in the spices for 3 min, then lift the chicken out.","Add the potatoes and water, cover and simmer for 10 min until the potatoes are almost tender.","Return the chicken with the peas, half the herbs and the preserved lemon and olives, cover and simmer 6-7 min until the chicken is cooked through.","Uncover and let the sauce reduce for 1-2 min, then serve scattered with the rest of the herbs."]'::jsonb,
    array['moroccan', 'north african', 'healthy', 'one-pot']::text[], 'moroccan', 626, 51.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tajine de poulet aux pommes de terre et petits pois","steps":["Enrober le poulet de gingembre, de curcuma, de poivre, de safran et d''une pincée de sel.","Faire revenir l''oignon et l''ail dans l''huile dans une sauteuse ou un tajine à feu moyen 3 min, ajouter le poulet et le tourner dans les épices 3 min, puis le réserver.","Ajouter les pommes de terre et l''eau, couvrir et mijoter 10 min jusqu''à ce qu''elles soient presque tendres.","Remettre le poulet avec les petits pois, la moitié des herbes, le citron confit et les olives, couvrir et mijoter 6 à 7 min jusqu''à ce que le poulet soit cuit.","Découvrir et laisser réduire la sauce 1 à 2 min, puis servir parsemé du reste des herbes."]},"it":{"title":"Tajine di pollo con patate e piselli","steps":["Condire il pollo con zenzero, curcuma, pepe, zafferano e un pizzico di sale.","Soffriggere cipolla e aglio nell''olio in una padella larga o in un tajine a fuoco medio per 3 min, aggiungere il pollo e girarlo nelle spezie per 3 min, poi toglierlo.","Aggiungere le patate e l''acqua, coprire e sobbollire 10 min finché le patate sono quasi tenere.","Rimettere il pollo con i piselli, metà delle erbe, il limone confit e le olive, coprire e sobbollire 6-7 min finché il pollo è cotto.","Scoprire e far restringere il sugo 1-2 min, poi servire con il resto delle erbe."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '80957d70-d4e9-5143-b879-cbd5c4ce5d2e')
  returning id
)
