-- Air-fryer piri-piri chicken thighs with rice and mixed salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '546e41d8-88ea-522b-8bd4-783564dc0901'::uuid, null, 'Air-fryer piri-piri chicken thighs with rice and mixed salad', 'seed', null, 'Claude', '/recipe-photos/air-fryer-piri-piri-chicken-thighs-with-rice-and-mixed-salad.webp', '/recipe-photos/air-fryer-piri-piri-chicken-thighs-with-rice-and-mixed-salad.webp',
    2, null, 28, 10, 18, '["Mash or blitz the chillies, garlic, paprika, oregano, lemon juice, vinegar, 2 tbsp oil and a good pinch of salt into a loose piri-piri sauce.","Toss the chicken with half the sauce and air-fry at 200°C for 16-18 min, turning halfway and brushing with a little more sauce, until charred and cooked through.","Meanwhile rinse the rice and simmer it covered in 300 ml salted water for 12 min, then rest 5 min off the heat.","Toss the tomatoes, onion and lettuce with the oil, a splash of vinegar and salt.","Serve the chicken on the rice with the salad, with the remaining sauce for spooning over."]'::jsonb,
    array['portuguese', 'spicy', 'healthy', 'quick']::text[], 'portuguese', 825, 41.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Hauts de cuisse de poulet piri-piri au air fryer, riz et salade mixte","steps":["Écraser ou mixer les piments, l''ail, le paprika, l''origan, le jus de citron, le vinaigre, 2 c. à soupe d''huile et une bonne pincée de sel en une sauce piri-piri fluide.","Enrober le poulet de la moitié de la sauce et le cuire au air fryer à 200 °C pendant 16 à 18 min en le retournant à mi-cuisson et en le badigeonnant d''un peu de sauce, jusqu''à ce qu''il soit grillé et cuit.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Mélanger les tomates, l''oignon et la salade avec l''huile, un trait de vinaigre et du sel.","Servir le poulet sur le riz avec la salade et le reste de sauce à côté."]},"it":{"title":"Sovracosce di pollo piri-piri in friggitrice ad aria con riso e insalata mista","steps":["Pestare o frullare peperoncini, aglio, paprika, origano, succo di limone, aceto, 2 cucchiai d''olio e un bel pizzico di sale in una salsa piri-piri fluida.","Condire il pollo con metà della salsa e cuocerlo in friggitrice ad aria a 200 °C per 16-18 min, girandolo a metà e spennellandolo con altra salsa, finché è abbrustolito e cotto.","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Condire pomodori, cipolla e lattuga con l''olio, un goccio d''aceto e sale.","Servire il pollo sul riso con l''insalata e la salsa rimasta a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '546e41d8-88ea-522b-8bd4-783564dc0901')
  returning id
)
