-- Pollo al chilindrón with crusty bread
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '79f06879-912e-5951-aac6-7802f2f96566'::uuid, null, 'Pollo al chilindrón with crusty bread', 'seed', null, 'Claude', '/recipe-photos/pollo-al-chilindron-with-crusty-bread.webp', '/recipe-photos/pollo-al-chilindron-with-crusty-bread.webp',
    2, null, 30, 8, 22, '["Season the chicken and brown it in the oil in a wide pan over medium-high heat for 4 min, then lift it out.","Add the ham, onion and peppers and cook for 5 min until softened, then stir in the garlic and paprika for 30 seconds.","Pour in the wine and let it bubble for 1 min.","Add the tomatoes, bay leaf and chicken, cover and simmer for 12 min, stirring now and then, until the chicken is tender and the sauce thick.","Taste for salt and serve with parsley and the bread for mopping up the sauce."]'::jsonb,
    array['spanish', 'stew', 'healthy', 'one-pot']::text[], 'spanish', 839, 51.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet al chilindrón (poivrons, tomate et jambon serrano) et pain de campagne","steps":["Assaisonner le poulet et le dorer dans l''huile dans une sauteuse à feu moyen-vif 4 min, puis le réserver.","Ajouter le jambon, l''oignon et les poivrons et cuire 5 min jusqu''à ce qu''ils s''attendrissent, puis ajouter l''ail et le paprika 30 secondes.","Verser le vin et laisser bouillonner 1 min.","Ajouter les tomates, le laurier et le poulet, couvrir et mijoter 12 min en remuant de temps en temps, jusqu''à ce que le poulet soit tendre et la sauce épaisse.","Rectifier le sel et servir avec le persil et le pain pour saucer."]},"it":{"title":"Pollo al chilindrón (peperoni, pomodoro e prosciutto serrano) con pane casereccio","steps":["Condire il pollo e rosolarlo nell''olio in una padella larga a fuoco medio-alto per 4 min, poi toglierlo.","Aggiungere prosciutto, cipolla e peperoni e cuocere 5 min finché si ammorbidiscono, poi unire aglio e paprika per 30 secondi.","Sfumare con il vino per 1 min.","Aggiungere i pomodori, l''alloro e il pollo, coprire e sobbollire 12 min mescolando ogni tanto, finché il pollo è tenero e il sugo denso.","Regolare di sale e servire con prezzemolo e il pane per fare la scarpetta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '79f06879-912e-5951-aac6-7802f2f96566')
  returning id
)
