-- Air-fryer musakhan rolls with yogurt and chopped salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '504053fb-d532-5d57-a3af-20c5bba801ee'::uuid, null, 'Air-fryer musakhan rolls with yogurt and chopped salad', 'seed', null, 'Claude', '/recipe-photos/air-fryer-musakhan-rolls-with-yogurt-and-chopped-salad.webp', '/recipe-photos/air-fryer-musakhan-rolls-with-yogurt-and-chopped-salad.webp',
    2, null, 30, 6, 24, '["Cook the onions in 2 tbsp of the oil with a pinch of salt over medium heat for 10-12 min, stirring often, until soft and sweet but not crisp.","Toast the pine nuts in a dry pan for 2 min until golden and set aside.","Add the chicken to the onions with the allspice, cinnamon, cardamom and pepper and cook for 6-7 min until cooked through.","Stir in the sumac and pine nuts and check the salt.","Spoon the filling along the lower edge of each flatbread, fold in the sides and roll up tightly.","Brush the rolls with the last of the oil and air-fry seam-side down at 190°C for 6-7 min until crisp and golden.","Toss the tomato and cucumber with the lemon juice, parsley and salt and serve with the rolls and the yogurt, dusted with a little more sumac."]'::jsonb,
    array['middle eastern', 'wrap', 'street food']::text[], 'middle eastern', 1036, 50.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Rouleaux musakhan au air fryer (poulet au sumac et oignons), yaourt et salade","steps":["Cuire les oignons dans 2 c. à soupe d''huile avec une pincée de sel à feu moyen 10 à 12 min en remuant souvent, jusqu''à ce qu''ils soient fondants et doux sans croustiller.","Faire griller les pignons à sec 2 min et les réserver.","Ajouter le poulet aux oignons avec le piment de la Jamaïque, la cannelle, la cardamome et le poivre et cuire 6 à 7 min jusqu''à cuisson complète.","Incorporer le sumac et les pignons et rectifier le sel.","Répartir la farce le long du bord de chaque galette, rabattre les côtés et rouler bien serré.","Badigeonner les rouleaux du reste d''huile et les cuire au air fryer, jointure dessous, à 190 °C pendant 6 à 7 min jusqu''à ce qu''ils soient dorés et croustillants.","Mélanger la tomate et le concombre avec le jus de citron, le persil et du sel, et servir avec les rouleaux et le yaourt, saupoudré d''un peu de sumac."]},"it":{"title":"Rotoli musakhan in friggitrice ad aria (pollo al sommacco e cipolle) con yogurt e insalata","steps":["Cuocere le cipolle in 2 cucchiai d''olio con un pizzico di sale a fuoco medio per 10-12 min, mescolando spesso, finché sono morbide e dolci ma non croccanti.","Tostare i pinoli in padella asciutta per 2 min e metterli da parte.","Unire il pollo alle cipolle con pimento, cannella, cardamomo e pepe e cuocere 6-7 min finché è cotto.","Aggiungere il sommacco e i pinoli e regolare di sale.","Distribuire il ripieno lungo il bordo di ogni piadina, ripiegare i lati e arrotolare stretto.","Spennellare i rotoli con l''olio rimasto e cuocerli in friggitrice ad aria con la chiusura in basso a 190 °C per 6-7 min finché sono dorati e croccanti.","Condire pomodoro e cetriolo con succo di limone, prezzemolo e sale e servire con i rotoli e lo yogurt, spolverizzato di altro sommacco."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '504053fb-d532-5d57-a3af-20c5bba801ee')
  returning id
)
