-- Tunisian chicken couscous with chickpeas, carrots and courgette
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '1186e3b2-9887-52a7-90d7-c900d587fc90'::uuid, null, 'Tunisian chicken couscous with chickpeas, carrots and courgette', 'seed', null, 'Claude', '/recipe-photos/tunisian-chicken-couscous-with-chickpeas-carrots-and-courgette.webp', '/recipe-photos/tunisian-chicken-couscous-with-chickpeas-carrots-and-courgette.webp',
    2, null, 30, 10, 20, '["Brown the chicken and onion in the oil in a wide pan over medium-high heat for 5 min.","Stir in the garlic, tomato paste, harissa, paprika, caraway and coriander and fry for 1 min until the paste darkens.","Add the carrots and stock, cover and simmer for 8 min.","Add the courgette and chickpeas and simmer, uncovered, for 8 min until the vegetables are tender and the chicken cooked through.","Put the couscous in a bowl with the oil and a pinch of salt, pour over 200 ml of the hot red broth from the pan, cover for 5 min, then fluff with a fork.","Serve the couscous in bowls topped with the chicken, vegetables and more of the broth, with parsley."]'::jsonb,
    array['north african', 'spicy', 'healthy', 'one-pot']::text[], 'north african', 950, 54.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Couscous tunisien au poulet, pois chiches, carottes et courgette","steps":["Faire dorer le poulet et l''oignon dans l''huile dans une sauteuse à feu moyen-vif 5 min.","Ajouter l''ail, le concentré de tomate, la harissa, le paprika, le carvi et la coriandre et faire revenir 1 min jusqu''à ce que le concentré fonce.","Ajouter les carottes et le bouillon, couvrir et mijoter 8 min.","Ajouter la courgette et les pois chiches et mijoter à découvert 8 min jusqu''à ce que les légumes soient tendres et le poulet cuit.","Mettre la semoule dans un saladier avec l''huile et une pincée de sel, verser 200 ml du bouillon rouge chaud de la sauteuse, couvrir 5 min puis égrainer à la fourchette.","Servir la semoule en bols, garnie du poulet, des légumes et d''un peu plus de bouillon, avec du persil."]},"it":{"title":"Cuscus tunisino di pollo con ceci, carote e zucchina","steps":["Rosolare pollo e cipolla nell''olio in una padella larga a fuoco medio-alto per 5 min.","Unire aglio, concentrato di pomodoro, harissa, paprika, carvi e coriandolo e soffriggere 1 min finché il concentrato scurisce.","Aggiungere le carote e il brodo, coprire e sobbollire 8 min.","Aggiungere la zucchina e i ceci e sobbollire scoperto 8 min finché le verdure sono tenere e il pollo cotto.","Mettere il cuscus in una ciotola con l''olio e un pizzico di sale, versarvi 200 ml del brodo rosso caldo della padella, coprire 5 min e sgranare con una forchetta.","Servire il cuscus nelle ciotole con pollo, verdure e altro brodo, con prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '1186e3b2-9887-52a7-90d7-c900d587fc90')
  returning id
)
