-- Poulet au vinaigre with rice and glazed carrots
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4011ea03-d3f9-5415-8dfb-79349ee13da5'::uuid, null, 'Poulet au vinaigre with rice and glazed carrots', 'seed', null, 'Claude', '/recipe-photos/poulet-au-vinaigre-with-rice-and-glazed-carrots.webp', '/recipe-photos/poulet-au-vinaigre-with-rice-and-glazed-carrots.webp',
    2, null, 30, 8, 22, '["Rinse the rice and simmer it covered in 300 ml salted water for 12 min, then rest 5 min off the heat.","Put the carrots in a small pan with the butter, sugar, a pinch of salt and water just to cover, and boil for 12-15 min until the water has gone and they are glazed.","Season the chicken and brown it in the oil over medium-high heat for 4 min a side, then lift it out.","Soften the shallots and garlic in the pan for 2 min, then pour in the vinegar and let it reduce by half, about 2 min.","Stir in the wine, tomato paste, tomatoes and stock, return the chicken, cover and simmer 8 min until cooked through.","Lift out the chicken, boil the sauce 2 min until syrupy, then whisk in the butter off the heat.","Serve the chicken and sauce with the rice and carrots, scattered with tarragon."]'::jsonb,
    array['french', 'healthy']::text[], 'french', 896, 42.4,
    false, 'en', 'easy', '{"pots":3,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Poulet au vinaigre, riz et carottes glacées","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Mettre les carottes dans une petite casserole avec le beurre, le sucre, une pincée de sel et de l''eau à hauteur, et cuire 12 à 15 min à gros bouillons jusqu''à évaporation et qu''elles soient glacées.","Assaisonner le poulet et le dorer dans l''huile à feu moyen-vif 4 min de chaque côté, puis le réserver.","Faire revenir les échalotes et l''ail 2 min, puis verser le vinaigre et laisser réduire de moitié, environ 2 min.","Ajouter le vin, le concentré, les tomates et le bouillon, remettre le poulet, couvrir et mijoter 8 min jusqu''à cuisson complète.","Sortir le poulet, faire bouillir la sauce 2 min jusqu''à ce qu''elle soit sirupeuse, puis y fouetter le beurre hors du feu.","Servir le poulet et la sauce avec le riz et les carottes, parsemé d''estragon."]},"it":{"title":"Pollo all''aceto con riso e carote glassate","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Mettere le carote in un pentolino con burro, zucchero, un pizzico di sale e acqua a filo e cuocere a fuoco vivace 12-15 min finché l''acqua evapora e sono glassate.","Condire il pollo e rosolarlo nell''olio a fuoco medio-alto 4 min per lato, poi toglierlo.","Appassire scalogni e aglio 2 min, poi versare l''aceto e lasciarlo ridurre della metà, circa 2 min.","Unire vino, concentrato, pomodori e brodo, rimettere il pollo, coprire e sobbollire 8 min finché è cotto.","Togliere il pollo, far bollire il sugo 2 min finché è sciropposo, poi montarlo con il burro a fuoco spento.","Servire il pollo con il sugo, il riso e le carote, con dragoncello."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4011ea03-d3f9-5415-8dfb-79349ee13da5')
  returning id
)
