-- Ragù bianco di pollo with rigatoni
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '96f7ec19-afcf-5e6a-9d55-7b131db9d31d'::uuid, null, 'Ragù bianco di pollo with rigatoni', 'seed', null, 'Claude', '/recipe-photos/ragu-bianco-di-pollo-with-rigatoni.webp', '/recipe-photos/ragu-bianco-di-pollo-with-rigatoni.webp',
    2, null, 30, 10, 20, '["Cook the onion, carrot and celery in the oil over medium heat for 6 min until soft.","Add the chicken, garlic, rosemary and sage and cook for 5 min, breaking up the mince, until it loses its pink colour and starts to colour.","Pour in the wine and let it evaporate, about 2 min.","Add the stock, season and simmer, half-covered, for 8-10 min until the ragù is moist but not runny.","Meanwhile cook the rigatoni in boiling salted water for 1 min less than the packet says.","Drain the pasta, keeping a cup of the water, and toss it in the ragù with half the parmesan and a splash of the water until glossy.","Serve with the rest of the parmesan, black pepper and parsley."]'::jsonb,
    array['italian', 'healthy']::text[], 'italian', 741, 44.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Ragù blanc de poulet aux rigatoni","steps":["Faire revenir l''oignon, la carotte et le céleri dans l''huile à feu moyen 6 min jusqu''à ce qu''ils soient tendres.","Ajouter le poulet, l''ail, le romarin et la sauge et cuire 5 min en émiettant la viande, jusqu''à ce qu''elle ne soit plus rose et commence à dorer.","Verser le vin et le laisser s''évaporer, environ 2 min.","Ajouter le bouillon, assaisonner et mijoter à demi-couvert 8 à 10 min jusqu''à ce que le ragù soit moelleux sans être liquide.","Pendant ce temps, cuire les rigatoni dans l''eau bouillante salée 1 min de moins que le temps indiqué.","Égoutter les pâtes en gardant une tasse d''eau de cuisson et les mélanger au ragù avec la moitié du parmesan et un peu d''eau jusqu''à ce qu''elles soient brillantes.","Servir avec le reste du parmesan, du poivre et du persil."]},"it":{"title":"Rigatoni al ragù bianco di pollo","steps":["Soffriggere cipolla, carota e sedano nell''olio a fuoco medio per 6 min finché sono morbidi.","Aggiungere il pollo, l''aglio, il rosmarino e la salvia e cuocere 5 min sgranando la carne, finché non è più rosa e inizia a colorire.","Sfumare con il vino e lasciarlo evaporare, circa 2 min.","Aggiungere il brodo, regolare di sale e pepe e sobbollire semicoperto 8-10 min finché il ragù è morbido ma non brodoso.","Nel frattempo cuocere i rigatoni in acqua bollente salata 1 min meno del tempo indicato.","Scolare la pasta tenendo una tazza d''acqua di cottura e saltarla nel ragù con metà del parmigiano e un goccio d''acqua finché è lucida.","Servire con il resto del parmigiano, pepe nero e prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '96f7ec19-afcf-5e6a-9d55-7b131db9d31d')
  returning id
)
