-- Phở gà (Vietnamese chicken noodle soup)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b96227fc-a4ea-4f49-ae27-f7234eccf631'::uuid, null, 'Phở gà (Vietnamese chicken noodle soup)', 'seed', null, 'Claude', '/recipe-photos/pho-ga-vietnamese-chicken-noodle-soup.webp', '/recipe-photos/pho-ga-vietnamese-chicken-noodle-soup.webp',
    2, null, 30, 10, 20, '["Char the onion halves and ginger cut side down in a dry soup pot over high heat for 5 min, until blackened in patches.","Add the star anise, coriander seeds and cinnamon and toast 30 s, then pour in the stock and bring to the boil.","Lower in the chicken breasts, cover and simmer very gently for 12-14 min until cooked through (no pink at the thickest point), then lift them out to rest.","Meanwhile cook the rice noodles in a pan of boiling water as the packet says (usually 4-6 min), drain and rinse briefly in hot water.","Season the broth with the fish sauce and sugar, simmer 2 min more, then strain out the aromatics and bring it back to a rolling boil.","Slice the chicken thinly across the grain.","Divide the noodles between deep bowls, top with the chicken and half the bean sprouts, and ladle over the boiling broth.","Scatter with spring onion and serve with the coriander, Thai basil, chilli, lime wedges and remaining bean sprouts to add at the table."]'::jsonb,
    array['vietnamese', 'asian', 'soup', 'healthy', 'light', 'dairy-free']::text[], 'vietnamese', 620, 51.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Phở gà (soupe vietnamienne de nouilles au poulet)","steps":["Faire noircir les moitiés d''oignon et le gingembre côté coupé dans une marmite à sec à feu vif pendant 5 min, jusqu''à ce qu''ils soient brûlés par endroits.","Ajouter l''anis étoilé, les graines de coriandre et la cannelle, torréfier 30 s, puis verser le bouillon et porter à ébullition.","Plonger les blancs de poulet, couvrir et frémir très doucement 12 à 14 min jusqu''à cuisson à cœur (plus de rose au plus épais), puis les sortir et les laisser reposer.","Pendant ce temps, cuire les nouilles de riz dans une casserole d''eau bouillante selon le paquet (en général 4 à 6 min), égoutter et rincer rapidement à l''eau chaude.","Assaisonner le bouillon avec la sauce de poisson et le sucre, frémir encore 2 min, puis le filtrer et le remettre à gros bouillons.","Trancher finement le poulet dans le sens contraire des fibres.","Répartir les nouilles dans des bols creux, ajouter le poulet et la moitié des germes de soja, puis verser le bouillon bouillant.","Parsemer d''oignon nouveau et servir avec la coriandre, le basilic thaï, le piment, les quartiers de citron vert et le reste des germes de soja à ajouter à table."]},"it":{"title":"Phở gà (zuppa vietnamita di noodles al pollo)","steps":["Abbrustolire le metà di cipolla e lo zenzero dal lato tagliato in una pentola asciutta a fuoco vivo per 5 min, finché sono anneriti a chiazze.","Aggiungere anice stellato, semi di coriandolo e cannella, tostare 30 s, poi versare il brodo e portare a bollore.","Immergere i petti di pollo, coprire e sobbollire molto dolcemente 12-14 min finché cotti (niente rosa nel punto più spesso), poi toglierli e farli riposare.","Nel frattempo cuocere i noodles di riso in una pentola d''acqua bollente come indicato sulla confezione (di solito 4-6 min), scolarli e sciacquarli rapidamente in acqua calda.","Insaporire il brodo con salsa di pesce e zucchero, sobbollire altri 2 min, poi filtrarlo e riportarlo a bollore vivace.","Tagliare il pollo a fettine sottili contro fibra.","Dividere i noodles in ciotole fonde, aggiungere il pollo e metà dei germogli di soia e versare sopra il brodo bollente.","Completare con il cipollotto e servire con coriandolo, basilico thai, peperoncino, spicchi di lime e i germogli rimasti da aggiungere a tavola."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b96227fc-a4ea-4f49-ae27-f7234eccf631')
  returning id
)
