-- Air-fryer sweet and sour chicken with peppers, pineapple and rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '1dbeb2e6-6a34-4c40-a9cc-75487a348f8c'::uuid, null, 'Air-fryer sweet and sour chicken with peppers, pineapple and rice', 'seed', null, 'Claude', '/recipe-photos/air-fryer-sweet-and-sour-chicken-with-peppers-pineapple-and-rice.webp', '/recipe-photos/air-fryer-sweet-and-sour-chicken-with-peppers-pineapple-and-rice.webp',
    2, null, 28, 10, 18, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Toss the chicken with a pinch of salt and 1 tsp soy sauce, then with the cornstarch and half the oil until every piece is coated.","Air-fry the chicken at 200°C for 12 min in a single layer, shaking halfway, until golden and cooked through.","Meanwhile whisk the ketchup, vinegar, sugar, soy sauce, pineapple juice, 3 tbsp water and the cornstarch for the sauce.","Stir-fry the onion, peppers and garlic in the remaining oil in a very hot wok for 3 min, until just softened but still crisp.","Add the pineapple for 1 min, then pour in the sauce and bubble for 1 min until thick and glossy.","Toss in the chicken until coated and serve straight away over the rice."]'::jsonb,
    array['chinese', 'asian', 'fakeaway', 'kid-friendly', 'dairy-free']::text[], 'chinese', 734, 45.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet aigre-doux au air fryer, poivrons, ananas et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Mélanger le poulet avec une pincée de sel et 1 c. à café de sauce soja, puis avec la fécule et la moitié de l''huile pour bien enrober chaque morceau.","Cuire le poulet au air fryer à 200 °C pendant 12 min en une seule couche, en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et cuit.","Pendant ce temps, fouetter le ketchup, le vinaigre, le sucre, la sauce soja, le jus d''ananas, 3 c. à soupe d''eau et la fécule pour la sauce.","Faire sauter l''oignon, les poivrons et l''ail dans le reste d''huile dans un wok très chaud pendant 3 min, jusqu''à ce qu''ils soient juste tendres mais encore croquants.","Ajouter l''ananas 1 min, puis verser la sauce et laisser bouillonner 1 min jusqu''à ce qu''elle épaississe et brille.","Ajouter le poulet, bien l''enrober et servir aussitôt sur le riz."]},"it":{"title":"Pollo in agrodolce in friggitrice ad aria con peperoni, ananas e riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Condire il pollo con un pizzico di sale e 1 cucchiaino di salsa di soia, poi con l''amido e metà dell''olio finché ogni pezzo è ricoperto.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12 min in un solo strato, scuotendo a metà, finché è dorato e cotto.","Nel frattempo sbattere ketchup, aceto, zucchero, salsa di soia, succo d''ananas, 3 cucchiai d''acqua e l''amido per la salsa.","Saltare cipolla, peperoni e aglio nell''olio rimasto in un wok rovente per 3 min, finché appena ammorbiditi ma ancora croccanti.","Aggiungere l''ananas per 1 min, poi versare la salsa e farla bollire 1 min finché densa e lucida.","Unire il pollo, mescolare per ricoprirlo e servire subito sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '1dbeb2e6-6a34-4c40-a9cc-75487a348f8c')
  returning id
)
