-- Chicken chow mein with cabbage and bean sprouts
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8113b4b3-f76a-494e-a5c5-d84d0356e3d6'::uuid, null, 'Chicken chow mein with cabbage and bean sprouts', 'seed', null, 'Claude', '/recipe-photos/chicken-chow-mein-with-cabbage-and-bean-sprouts.webp', '/recipe-photos/chicken-chow-mein-with-cabbage-and-bean-sprouts.webp',
    2, null, 22, 10, 12, '["Toss the chicken with 1 tsp soy sauce, 1 tsp of the rice wine and the cornstarch.","Cook the noodles in boiling water as the packet says (usually 3-4 min), drain, rinse under cold water, shake dry and toss with the sesame oil.","Mix the oyster sauce, soy sauce, dark soy sauce, the rest of the rice wine, the sugar, a good pinch of white pepper and 2 tbsp water.","Stir-fry the chicken in 1 tbsp oil in a very hot wok for 3-4 min until cooked through, then tip it onto a plate.","Add the remaining oil, then the garlic, carrot and cabbage, and stir-fry 2 min.","Add the noodles and the sauce and toss over high heat for 2 min, until the noodles are evenly coloured and starting to crisp in places.","Return the chicken with the bean sprouts and spring onions, toss 1 min more and serve."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'fakeaway', 'quick', 'dairy-free']::text[], 'chinese', 683, 42.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Chow mein au poulet, chou et germes de soja","steps":["Mélanger le poulet avec 1 c. à café de sauce soja, 1 c. à café de vin de riz et la fécule.","Cuire les nouilles dans l''eau bouillante selon le paquet (en général 3 à 4 min), égoutter, rincer à l''eau froide, bien secouer et mélanger avec l''huile de sésame.","Mélanger la sauce d''huître, la sauce soja, la sauce soja foncée, le reste du vin de riz, le sucre, une bonne pincée de poivre blanc et 2 c. à soupe d''eau.","Faire sauter le poulet dans 1 c. à soupe d''huile dans un wok très chaud 3 à 4 min jusqu''à cuisson complète, puis le réserver sur une assiette.","Ajouter le reste d''huile, puis l''ail, la carotte et le chou, et faire sauter 2 min.","Ajouter les nouilles et la sauce et mélanger à feu vif 2 min, jusqu''à ce que les nouilles soient bien colorées et commencent à croustiller par endroits.","Remettre le poulet avec les germes de soja et les oignons nouveaux, faire sauter encore 1 min et servir."]},"it":{"title":"Chow mein di pollo con cavolo e germogli di soia","steps":["Condire il pollo con 1 cucchiaino di salsa di soia, 1 cucchiaino di vino di riso e l''amido.","Cuocere i noodles in acqua bollente come indicato sulla confezione (di solito 3-4 min), scolarli, sciacquarli in acqua fredda, sgocciolarli bene e condirli con l''olio di sesamo.","Mescolare salsa d''ostrica, salsa di soia, salsa di soia scura, il resto del vino di riso, lo zucchero, un bel pizzico di pepe bianco e 2 cucchiai d''acqua.","Saltare il pollo in 1 cucchiaio d''olio in un wok rovente per 3-4 min finché cotto, poi metterlo da parte su un piatto.","Aggiungere l''olio rimasto, poi aglio, carota e cavolo e saltare 2 min.","Unire noodles e salsa e saltare a fuoco vivo per 2 min, finché i noodles sono colorati in modo uniforme e iniziano a diventare croccanti qua e là.","Rimettere il pollo con germogli di soia e cipollotti, saltare ancora 1 min e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8113b4b3-f76a-494e-a5c5-d84d0356e3d6')
  returning id
)
