-- Dak kalguksu (Korean chicken noodle soup)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7a3a5822-8944-4bae-8473-493e30aee3a1'::uuid, null, 'Dak kalguksu (Korean chicken noodle soup)', 'seed', null, 'Claude', '/recipe-photos/dak-kalguksu-korean-chicken-noodle-soup.webp', '/recipe-photos/dak-kalguksu-korean-chicken-noodle-soup.webp',
    2, null, 30, 8, 22, '["Bring the stock to the boil with the onion and the 2 crushed garlic cloves, add the chicken, cover and simmer gently for 12-14 min until cooked through.","Meanwhile mix the soy sauce, gochugaru, grated garlic, half the spring onion, the sesame oil and sesame seeds into a dipping sauce.","Lift out the chicken and shred it with two forks.","Add the potato to the broth and simmer 5 min.","Shake the excess flour off the noodles, add them with the courgette and simmer 3-4 min, until the noodles are tender and the potato is soft.","Return the chicken and season the broth with salt to taste.","Ladle into deep bowls, scatter with the remaining spring onion and serve with the sauce to stir in."]'::jsonb,
    array['korean', 'asian', 'soup', 'comfort', 'healthy', 'dairy-free']::text[], 'korean', 658, 52.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Dak kalguksu (soupe coréenne de nouilles au poulet)","steps":["Porter le bouillon à ébullition avec l''oignon et les 2 gousses d''ail écrasées, ajouter le poulet, couvrir et frémir doucement 12 à 14 min jusqu''à cuisson complète.","Pendant ce temps, mélanger la sauce soja, le gochugaru, l''ail râpé, la moitié de l''oignon nouveau, l''huile et les graines de sésame pour la sauce.","Sortir le poulet et l''effilocher avec deux fourchettes.","Ajouter la pomme de terre au bouillon et frémir 5 min.","Secouer les nouilles pour ôter l''excès de farine, les ajouter avec la courgette et frémir 3 à 4 min, jusqu''à ce que les nouilles soient tendres et la pomme de terre fondante.","Remettre le poulet et saler le bouillon à son goût.","Servir dans des bols creux, parsemer du reste d''oignon nouveau et accompagner de la sauce à mélanger."]},"it":{"title":"Dak kalguksu (zuppa coreana di noodles al pollo)","steps":["Portare a bollore il brodo con la cipolla e i 2 spicchi d''aglio schiacciati, aggiungere il pollo, coprire e sobbollire dolcemente 12-14 min finché cotto.","Nel frattempo mescolare salsa di soia, gochugaru, aglio grattugiato, metà del cipollotto, olio e semi di sesamo per la salsa.","Togliere il pollo e sfilacciarlo con due forchette.","Aggiungere la patata al brodo e sobbollire 5 min.","Scuotere i noodles per togliere la farina in eccesso, unirli con la zucchina e sobbollire 3-4 min, finché i noodles sono teneri e la patata morbida.","Rimettere il pollo e regolare di sale il brodo.","Servire in ciotole fonde con il cipollotto rimasto e accompagnare con la salsa da mescolare."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7a3a5822-8944-4bae-8473-493e30aee3a1')
  returning id
)
