-- Pad see ew with chicken and broccoli
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c234f8c1-e739-4a1b-abe2-4a0cda115c49'::uuid, null, 'Pad see ew with chicken and broccoli', 'seed', null, 'Claude', '/recipe-photos/pad-see-ew-with-chicken-and-broccoli.webp', '/recipe-photos/pad-see-ew-with-chicken-and-broccoli.webp',
    2, null, 24, 12, 12, '["Soak the noodles in very hot water as the packet says (about 8-10 min) until pliable but still firm, drain and toss with 1 tsp of the dark soy sauce.","Mix the remaining dark soy sauce, the soy sauce, oyster sauce, sugar, vinegar and 2 tbsp water.","Heat 1 tbsp oil in a wok over high heat, fry the garlic 10 s, then stir-fry the chicken 3-4 min until cooked through.","Add the broccoli stems, then the florets and leaves with a splash of water, and stir-fry 2 min until bright green.","Push everything to one side, add the remaining oil, crack in the eggs and scramble until just set.","Add the noodles and sauce and toss for 2-3 min, letting them sit against the hot wok now and then so they char in places.","Serve with a pinch of white pepper and chilli flakes."]'::jsonb,
    array['thai', 'asian', 'stir-fry', 'fakeaway', 'quick', 'dairy-free']::text[], 'thai', 796, 43.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pad see ew au poulet et brocoli","steps":["Faire tremper les nouilles dans de l''eau très chaude selon le paquet (environ 8 à 10 min) jusqu''à ce qu''elles soient souples mais encore fermes, égoutter et mélanger avec 1 c. à café de sauce soja foncée.","Mélanger le reste de sauce soja foncée, la sauce soja, la sauce d''huître, le sucre, le vinaigre et 2 c. à soupe d''eau.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif, faire revenir l''ail 10 s, puis faire sauter le poulet 3 à 4 min jusqu''à cuisson complète.","Ajouter les tiges de brocoli, puis les fleurettes et les feuilles avec un trait d''eau, et faire sauter 2 min jusqu''à ce qu''ils soient bien verts.","Pousser le tout sur le côté, ajouter le reste d''huile, casser les œufs et les brouiller jusqu''à ce qu''ils soient juste pris.","Ajouter les nouilles et la sauce et mélanger 2 à 3 min en les laissant de temps en temps contre le wok brûlant pour qu''elles grillent par endroits.","Servir avec une pincée de poivre blanc et de piment en flocons."]},"it":{"title":"Pad see ew con pollo e broccoli","steps":["Ammollare i noodles in acqua molto calda come indicato sulla confezione (circa 8-10 min) finché morbidi ma ancora sodi, scolarli e condirli con 1 cucchiaino di salsa di soia scura.","Mescolare il resto della salsa di soia scura, la salsa di soia, la salsa d''ostrica, lo zucchero, l''aceto e 2 cucchiai d''acqua.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo, soffriggere l''aglio 10 s, poi saltare il pollo 3-4 min finché cotto.","Aggiungere i gambi di broccolo, poi le cimette e le foglie con un goccio d''acqua e saltare 2 min finché verde brillante.","Spostare tutto su un lato, aggiungere l''olio rimasto, rompere le uova e strapazzarle finché appena rapprese.","Unire noodles e salsa e saltare 2-3 min, lasciandoli ogni tanto a contatto con il wok rovente perché si abbrustoliscano qua e là.","Servire con un pizzico di pepe bianco e peperoncino in fiocchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c234f8c1-e739-4a1b-abe2-4a0cda115c49')
  returning id
)
