-- Air-fryer Sri Lankan devilled chicken with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7bcf6900-1eeb-4919-8de4-c5ca6830b771'::uuid, null, 'Air-fryer Sri Lankan devilled chicken with rice', 'seed', null, 'Claude', '/recipe-photos/air-fryer-sri-lankan-devilled-chicken-with-rice.webp', '/recipe-photos/air-fryer-sri-lankan-devilled-chicken-with-rice.webp',
    2, null, 28, 10, 18, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Toss the chicken with the soy sauce, chilli powder and plenty of black pepper, then with the cornstarch and 1 tsp of the oil.","Air-fry at 200°C for 12 min, shaking halfway, until browned and cooked through.","Meanwhile mix the ketchup, soy sauce, chilli flakes, vinegar and 2 tbsp water.","Heat the remaining oil in a wok over high heat, fry the garlic and ginger 30 s, then the onion and pepper for 3 min until charred at the edges but still crisp.","Add the tomato for 1 min, then the sauce, and bubble 1 min.","Toss in the chicken for 1 min until glossy and serve with the rice."]'::jsonb,
    array['asian', 'spicy', 'stir-fry', 'fakeaway', 'dairy-free']::text[], 'asian', 785, 40.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Poulet « devilled » sri-lankais au air fryer et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Mélanger le poulet avec la sauce soja, le piment en poudre et beaucoup de poivre noir, puis avec la fécule et 1 c. à café d''huile.","Cuire au air fryer à 200 °C pendant 12 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et cuit.","Pendant ce temps, mélanger le ketchup, la sauce soja, le piment en flocons, le vinaigre et 2 c. à soupe d''eau.","Chauffer le reste d''huile dans un wok à feu vif, faire revenir l''ail et le gingembre 30 s, puis l''oignon et le poivron 3 min jusqu''à ce qu''ils soient grillés sur les bords mais encore croquants.","Ajouter la tomate 1 min, puis la sauce, et laisser bouillonner 1 min.","Ajouter le poulet 1 min pour qu''il soit bien laqué et servir avec le riz."]},"it":{"title":"Pollo devilled dello Sri Lanka in friggitrice ad aria con riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Condire il pollo con salsa di soia, peperoncino in polvere e abbondante pepe nero, poi con l''amido e 1 cucchiaino d''olio.","Cuocere in friggitrice ad aria a 200 °C per 12 min, scuotendo a metà, finché dorato e cotto.","Nel frattempo mescolare ketchup, salsa di soia, peperoncino in fiocchi, aceto e 2 cucchiai d''acqua.","Scaldare l''olio rimasto in un wok a fuoco vivo, soffriggere aglio e zenzero 30 s, poi cipolla e peperone per 3 min finché abbrustoliti ai bordi ma ancora croccanti.","Aggiungere il pomodoro per 1 min, poi la salsa, e far bollire 1 min.","Unire il pollo per 1 min finché lucido e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7bcf6900-1eeb-4919-8de4-c5ca6830b771')
  returning id
)
