-- Pancit bihon with chicken, cabbage and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '831a6241-ea1d-4c9f-b882-78713c367a20'::uuid, null, 'Pancit bihon with chicken, cabbage and green beans', 'seed', null, 'Claude', '/recipe-photos/pancit-bihon-with-chicken-cabbage-and-green-beans.webp', '/recipe-photos/pancit-bihon-with-chicken-cabbage-and-green-beans.webp',
    2, null, 27, 12, 15, '["Soak the noodles in cold water for 5-10 min until pliable, then drain.","Heat the oil in a wok or large frying pan and fry the onion and garlic 2 min until soft.","Add the chicken and stir-fry 4 min until cooked through.","Add the carrot and green beans for 2 min, then the cabbage for 1 min; lift out half the vegetables and set aside.","Pour in the stock and soy sauce with plenty of black pepper and bring to the boil.","Add the noodles and toss over medium-high heat for 4-5 min, until they have absorbed the liquid and are tender.","Return the reserved vegetables, toss and serve with lemon wedges to squeeze over."]'::jsonb,
    array['filipino', 'asian', 'stir-fry', 'healthy', 'dairy-free']::text[], 'filipino', 735, 39.3,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pancit bihon au poulet, chou et haricots verts","steps":["Faire tremper les vermicelles dans l''eau froide 5 à 10 min jusqu''à ce qu''ils soient souples, puis égoutter.","Chauffer l''huile dans un wok ou une grande poêle et faire revenir l''oignon et l''ail 2 min jusqu''à ce qu''ils soient tendres.","Ajouter le poulet et le faire sauter 4 min jusqu''à cuisson complète.","Ajouter la carotte et les haricots verts 2 min, puis le chou 1 min ; retirer la moitié des légumes et les réserver.","Verser le bouillon et la sauce soja avec beaucoup de poivre noir et porter à ébullition.","Ajouter les vermicelles et mélanger à feu moyen-vif 4 à 5 min, jusqu''à ce qu''ils aient absorbé le liquide et soient tendres.","Remettre les légumes réservés, mélanger et servir avec des quartiers de citron à presser."]},"it":{"title":"Pancit bihon con pollo, cavolo e fagiolini","steps":["Ammollare i vermicelli in acqua fredda 5-10 min finché morbidi, poi scolarli.","Scaldare l''olio in un wok o in una padella larga e soffriggere cipolla e aglio 2 min finché morbidi.","Aggiungere il pollo e saltarlo 4 min finché cotto.","Aggiungere carota e fagiolini per 2 min, poi il cavolo per 1 min; togliere metà delle verdure e tenerle da parte.","Versare brodo e salsa di soia con abbondante pepe nero e portare a bollore.","Unire i vermicelli e saltarli a fuoco medio-alto 4-5 min, finché hanno assorbito il liquido e sono teneri.","Rimettere le verdure tenute da parte, mescolare e servire con spicchi di limone da spremere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '831a6241-ea1d-4c9f-b882-78713c367a20')
  returning id
)
