-- Gaeng jued woon sen (Thai glass noodle soup with chicken meatballs)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6c5bdac0-bd42-458f-b0a0-1afc9a981ced'::uuid, null, 'Gaeng jued woon sen (Thai glass noodle soup with chicken meatballs)', 'seed', null, 'Claude', '/recipe-photos/gaeng-jued-woon-sen-thai-glass-noodle-soup-with-chicken-meatballs.webp', '/recipe-photos/gaeng-jued-woon-sen-thai-glass-noodle-soup-with-chicken-meatballs.webp',
    2, null, 27, 12, 15, '["Soak the glass noodles in warm water for 10 min, drain and cut them into shorter lengths with scissors.","Mix the chicken with the soy sauce, grated garlic, coriander stalks, cornstarch and a good pinch of white pepper.","Bring the stock to the boil with the smashed garlic and carrot.","Drop in heaped teaspoons of the chicken mixture and simmer 5 min, until the meatballs float and are cooked through.","Add the cabbage and mushrooms and simmer 4 min until the cabbage is tender.","Add the glass noodles and simmer 2 min until they turn clear, then season with the fish sauce, soy sauce and white pepper.","Ladle into bowls and scatter with spring onion and coriander leaves."]'::jsonb,
    array['thai', 'asian', 'soup', 'healthy', 'light', 'dairy-free']::text[], 'thai', 521, 37,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Gaeng jued woon sen (soupe thaïe aux vermicelles de soja et boulettes de poulet)","steps":["Faire tremper les vermicelles de soja 10 min dans l''eau tiède, égoutter et les couper plus courts aux ciseaux.","Mélanger le poulet avec la sauce soja, l''ail râpé, les tiges de coriandre, la fécule et une bonne pincée de poivre blanc.","Porter le bouillon à ébullition avec l''ail écrasé et la carotte.","Y déposer des cuillerées à café bombées de farce et frémir 5 min, jusqu''à ce que les boulettes remontent et soient cuites.","Ajouter le chou et les champignons et frémir 4 min jusqu''à ce que le chou soit tendre.","Ajouter les vermicelles et frémir 2 min jusqu''à ce qu''ils deviennent translucides, puis assaisonner avec la sauce de poisson, la sauce soja et le poivre blanc.","Servir dans des bols et parsemer d''oignon nouveau et de feuilles de coriandre."]},"it":{"title":"Gaeng jued woon sen (zuppa thai di spaghetti di soia con polpettine di pollo)","steps":["Ammollare gli spaghetti di soia in acqua tiepida per 10 min, scolarli e accorciarli con le forbici.","Mescolare il pollo con salsa di soia, aglio grattugiato, gambi di coriandolo, amido e un bel pizzico di pepe bianco.","Portare a bollore il brodo con l''aglio schiacciato e la carota.","Versarvi cucchiaini colmi di impasto e sobbollire 5 min, finché le polpettine salgono a galla e sono cotte.","Aggiungere cavolo e funghi e sobbollire 4 min finché il cavolo è tenero.","Unire gli spaghetti di soia e sobbollire 2 min finché diventano trasparenti, poi insaporire con salsa di pesce, salsa di soia e pepe bianco.","Servire nelle ciotole con cipollotto e foglie di coriandolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6c5bdac0-bd42-458f-b0a0-1afc9a981ced')
  returning id
)
