-- Mie ayam (Indonesian chicken noodles with pak choi and mushrooms)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '25df8f45-66ea-40af-a171-c28749ca3e5b'::uuid, null, 'Mie ayam (Indonesian chicken noodles with pak choi and mushrooms)', 'seed', null, 'Claude', '/recipe-photos/mie-ayam-indonesian-chicken-noodles-with-pak-choi-and-mushrooms.webp', '/recipe-photos/mie-ayam-indonesian-chicken-noodles-with-pak-choi-and-mushrooms.webp',
    2, null, 28, 10, 18, '["Fry the shallots in the oil in a frying pan over medium heat for 2 min, then add the garlic and ginger for 1 min.","Add the chicken and cook 5 min, breaking it up, until it is no longer pink.","Add the mushrooms for 2 min, then the kecap manis, soy sauce, oyster sauce, a pinch of white pepper and 100 ml water, and simmer 4 min until glossy and thick.","Meanwhile heat the stock in a small pan with half the spring onion and keep it at a simmer.","Cook the noodles in a pan of boiling water as the packet says (usually 3-4 min), adding the pak choi for the last 2 min, then drain.","Toss the noodles in the serving bowls with the sesame oil and soy sauce.","Top with the chicken and pak choi, scatter with the rest of the spring onion and serve the hot broth and chilli alongside."]'::jsonb,
    array['indonesian', 'asian', 'healthy', 'comfort', 'dairy-free']::text[], 'indonesian', 761, 40.7,
    false, 'en', 'easy', '{"pots":3,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Mie ayam (nouilles indonésiennes au poulet, pak-choï et champignons)","steps":["Faire revenir les échalotes dans l''huile dans une poêle à feu moyen 2 min, puis ajouter l''ail et le gingembre 1 min.","Ajouter le poulet et le cuire 5 min en l''émiettant, jusqu''à ce qu''il ne soit plus rose.","Ajouter les champignons 2 min, puis le kecap manis, la sauce soja, la sauce d''huître, une pincée de poivre blanc et 100 ml d''eau, et mijoter 4 min jusqu''à ce que ce soit brillant et épais.","Pendant ce temps, chauffer le bouillon dans une petite casserole avec la moitié de l''oignon nouveau et le maintenir frémissant.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet (en général 3 à 4 min), en ajoutant le pak-choï les 2 dernières minutes, puis égoutter.","Mélanger les nouilles dans les bols avec l''huile de sésame et la sauce soja.","Garnir de poulet et de pak-choï, parsemer du reste d''oignon nouveau et servir le bouillon chaud et le piment à côté."]},"it":{"title":"Mie ayam (noodles indonesiani al pollo con pak choi e funghi)","steps":["Soffriggere gli scalogni nell''olio in una padella a fuoco medio per 2 min, poi aggiungere aglio e zenzero per 1 min.","Aggiungere il pollo e cuocerlo 5 min sgranandolo, finché non è più rosa.","Aggiungere i funghi per 2 min, poi kecap manis, salsa di soia, salsa d''ostrica, un pizzico di pepe bianco e 100 ml d''acqua, e sobbollire 4 min finché lucido e denso.","Nel frattempo scaldare il brodo in un pentolino con metà del cipollotto e tenerlo a sobbollire.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione (di solito 3-4 min), aggiungendo il pak choi negli ultimi 2 min, poi scolare.","Condire i noodles nelle ciotole con olio di sesamo e salsa di soia.","Completare con pollo e pak choi, il cipollotto rimasto e servire a parte il brodo caldo e il peperoncino."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '25df8f45-66ea-40af-a171-c28749ca3e5b')
  returning id
)
