-- Air-fryer anticuchos de pollo with potatoes and corn
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5864a3c5-72aa-4762-aff5-8cd8914c7334'::uuid, null, 'Air-fryer anticuchos de pollo with potatoes and corn', 'seed', null, 'Claude', '/recipe-photos/air-fryer-anticuchos-de-pollo-with-potatoes-and-corn.webp', '/recipe-photos/air-fryer-anticuchos-de-pollo-with-potatoes-and-corn.webp',
    2, null, 28, 10, 18, '["Put the potatoes in a pan of cold salted water, bring to the boil and cook 15 min until tender, adding the corn rounds for the last 6 min.","Mix the ají panca paste, garlic, vinegar, cumin, oregano, oil, ½ tsp salt and some pepper. Toss the chicken in it and thread onto 4 short skewers, keeping the leftover marinade.","Air-fry the skewers at 200 °C for 12-14 min, turning and brushing with the leftover marinade halfway, until charred at the edges and cooked through (74 °C inside).","Stir the ají amarillo paste with the lime juice, spring onion, coriander, 1 tbsp water and a pinch of salt for the dipping sauce.","Drain the potatoes and corn.","Serve the skewers with the potatoes and corn, with the ají sauce to dip."]'::jsonb,
    array['peruvian', 'street food', 'grill', 'quick', 'healthy']::text[], 'peruvian', 700, 41.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Anticuchos de pollo à l''air fryer, pommes de terre et maïs","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min jusqu''à ce qu''elles soient tendres, en ajoutant les tronçons de maïs pour les 6 dernières minutes.","Mélanger la pâte d''ají panca, l''ail, le vinaigre, le cumin, l''origan, l''huile, ½ c. à café de sel et du poivre. Y enrober le poulet et l''enfiler sur 4 petites brochettes, en gardant le reste de marinade.","Cuire les brochettes à l''air fryer à 200 °C pendant 12 à 14 min, en les retournant et en les badigeonnant du reste de marinade à mi-cuisson, jusqu''à ce qu''elles soient grillées sur les bords et cuites à cœur (74 °C).","Mélanger la pâte d''ají amarillo avec le jus de citron vert, l''oignon nouveau, la coriandre, 1 c. à soupe d''eau et une pincée de sel pour la sauce.","Égoutter les pommes de terre et le maïs.","Servir les brochettes avec les pommes de terre et le maïs, et la sauce à l''ají pour tremper."]},"it":{"title":"Anticuchos de pollo in friggitrice ad aria con patate e mais","steps":["Mettere le patate in una pentola di acqua fredda salata, portare a bollore e cuocere 15 min finché sono tenere, aggiungendo le rondelle di mais negli ultimi 6 min.","Mescolare la pasta di ají panca, l''aglio, l''aceto, il cumino, l''origano, l''olio, ½ cucchiaino di sale e pepe. Condire il pollo e infilarlo su 4 spiedini corti, tenendo da parte la marinata avanzata.","Cuocere gli spiedini in friggitrice ad aria a 200 °C per 12-14 min, girandoli e spennellandoli con la marinata a metà cottura, finché sono abbrustoliti ai bordi e cotti al cuore (74 °C).","Mescolare la pasta di ají amarillo con succo di lime, cipollotto, coriandolo, 1 cucchiaio d''acqua e un pizzico di sale per la salsa.","Scolare patate e mais.","Servire gli spiedini con patate e mais e la salsa all''ají per intingere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5864a3c5-72aa-4762-aff5-8cd8914c7334')
  returning id
)
