-- Galinhada (Brazilian chicken and turmeric rice)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '862414f6-3de8-4073-8567-200d720b2563'::uuid, null, 'Galinhada (Brazilian chicken and turmeric rice)', 'seed', null, 'Claude', '/recipe-photos/galinhada-brazilian-chicken-and-turmeric-rice.webp', '/recipe-photos/galinhada-brazilian-chicken-and-turmeric-rice.webp',
    2, null, 30, 8, 22, '["Season the chicken with the lime juice, half the garlic, ½ tsp salt and pepper.","Heat the oil in a wide pot over medium-high heat and brown the chicken for 5 min, stirring now and then.","Add the onion and pepper and cook 3 min until softened, then the rest of the garlic, the tomato and the turmeric for 1 min.","Stir in the rice for 1 min to coat it, pour in the hot stock, bring to the boil, cover and cook on low heat for 12 min.","Scatter the peas over the rice, cover again and cook 4-5 min more until the rice is tender and the liquid is absorbed.","Rest 2 min off the heat, then fold in the parsley and spring onions (cheiro-verde) and check the salt."]'::jsonb,
    array['brazilian', 'one-pot', 'quick', 'healthy', 'kid-friendly']::text[], 'brazilian', 787, 44,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Galinhada (riz brésilien au poulet et au curcuma)","steps":["Assaisonner le poulet avec le jus de citron vert, la moitié de l''ail, ½ c. à café de sel et du poivre.","Chauffer l''huile dans une cocotte large à feu moyen-vif et faire dorer le poulet 5 min en remuant de temps en temps.","Ajouter l''oignon et le poivron et cuire 3 min jusqu''à ce qu''ils ramollissent, puis le reste de l''ail, la tomate et le curcuma pendant 1 min.","Incorporer le riz 1 min pour bien l''enrober, verser le bouillon chaud, porter à ébullition, couvrir et cuire à feu doux 12 min.","Répartir les petits pois sur le riz, couvrir de nouveau et cuire encore 4 à 5 min jusqu''à ce que le riz soit tendre et le liquide absorbé.","Laisser reposer 2 min hors du feu, puis incorporer le persil et les oignons nouveaux et rectifier le sel."]},"it":{"title":"Galinhada (riso brasiliano con pollo e curcuma)","steps":["Condire il pollo con il succo di lime, metà dell''aglio, ½ cucchiaino di sale e pepe.","Scaldare l''olio in una pentola larga a fuoco medio-alto e rosolare il pollo per 5 min, mescolando ogni tanto.","Aggiungere cipolla e peperone e cuocere 3 min finché si ammorbidiscono, poi il resto dell''aglio, il pomodoro e la curcuma per 1 min.","Unire il riso e tostarlo 1 min, versare il brodo caldo, portare a bollore, coprire e cuocere a fuoco basso 12 min.","Distribuire i piselli sul riso, coprire di nuovo e cuocere altri 4-5 min finché il riso è tenero e il liquido assorbito.","Lasciar riposare 2 min fuori dal fuoco, poi incorporare prezzemolo e cipollotti e regolare di sale."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '862414f6-3de8-4073-8567-200d720b2563')
  returning id
)
