-- Strogonoff de frango with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3c498c93-195c-4b11-a061-ca0fc9abf27e'::uuid, null, 'Strogonoff de frango with rice', 'seed', null, 'Claude', '/recipe-photos/strogonoff-de-frango-with-rice.webp', '/recipe-photos/strogonoff-de-frango-with-rice.webp',
    2, null, 28, 8, 20, '["Put the rice in a pan with 300 ml water and a pinch of salt, cover and cook on low heat for 12 min, then rest off the heat.","Season the chicken with salt and pepper and brown it in the oil in a large frying pan over high heat for 4-5 min. Lift out onto a plate.","Lower the heat, add the butter and onion and cook 3 min, then the garlic and mushrooms for 5 min until the mushrooms have given off their liquid and it has evaporated.","Return the chicken with the tomato paste, ketchup, mustard and stock and simmer 3 min until the chicken is cooked through.","Stir in the cream and warm 1-2 min without boiling. Season to taste.","Serve the strogonoff over the rice with the parsley on top."]'::jsonb,
    array['brazilian', 'comfort', 'quick', 'kid-friendly']::text[], 'brazilian', 800, 47.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Strogonoff de frango (émincé de poulet à la crème) et riz","steps":["Mettre le riz dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu.","Saler et poivrer le poulet et le faire dorer dans l''huile dans une grande poêle à feu vif 4 à 5 min. Le réserver sur une assiette.","Baisser le feu, ajouter le beurre et l''oignon et cuire 3 min, puis l''ail et les champignons pendant 5 min jusqu''à ce que leur eau se soit évaporée.","Remettre le poulet avec le concentré de tomate, le ketchup, la moutarde et le bouillon et laisser mijoter 3 min jusqu''à ce que le poulet soit cuit.","Incorporer la crème et chauffer 1 à 2 min sans faire bouillir. Rectifier l''assaisonnement.","Servir le strogonoff sur le riz, parsemé de persil."]},"it":{"title":"Strogonoff de frango (straccetti di pollo alla panna) con riso","steps":["Mettere il riso in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco.","Salare e pepare il pollo e rosolarlo nell''olio in una padella grande a fuoco vivo per 4-5 min. Metterlo da parte su un piatto.","Abbassare il fuoco, aggiungere il burro e la cipolla e cuocere 3 min, poi l''aglio e i funghi per 5 min finché la loro acqua è evaporata.","Rimettere il pollo con concentrato di pomodoro, ketchup, senape e brodo e cuocere 3 min finché il pollo è cotto.","Unire la panna e scaldare 1-2 min senza far bollire. Regolare di sale e pepe.","Servire lo strogonoff sul riso con il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3c498c93-195c-4b11-a061-ca0fc9abf27e')
  returning id
)
