-- Pollo a la provenzal with air-fryer potatoes and mixed salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '65496410-7e58-455e-b55c-83c49578e92b'::uuid, null, 'Pollo a la provenzal with air-fryer potatoes and mixed salad', 'seed', null, 'Claude', '/recipe-photos/pollo-a-la-provenzal-with-air-fryer-potatoes-and-mixed-salad.webp', '/recipe-photos/pollo-a-la-provenzal-with-air-fryer-potatoes-and-mixed-salad.webp',
    2, null, 30, 10, 20, '["Toss the potatoes with 1 tsp of the oil and a pinch of salt and air-fry at 200 °C for 20 min, shaking twice, until golden and crisp.","Mix the garlic, parsley, chili flakes, 1.5 tbsp of the oil and a pinch of salt: this is the provenzal.","Season the chicken and cook it in 1 tsp oil in a frying pan over medium-high heat for 4-5 min a side until golden and cooked through (74 °C inside).","Lower the heat, spoon half the provenzal over the chicken and warm for 30 s, without letting the garlic brown.","Toss the lettuce, tomatoes and red onion with the vinegar, the remaining oil and a pinch of salt.","Toss the hot potatoes with the rest of the provenzal and serve with the chicken and the salad."]'::jsonb,
    array['argentinian', 'quick', 'healthy', 'kid-friendly']::text[], 'argentinian', 640, 45.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Pollo a la provenzal, pommes de terre à l''air fryer et salade composée","steps":["Mélanger les pommes de terre avec 1 c. à café d''huile et une pincée de sel et les cuire à l''air fryer à 200 °C pendant 20 min, en secouant deux fois, jusqu''à ce qu''elles soient dorées et croustillantes.","Mélanger l''ail, le persil, le piment, 1,5 c. à soupe d''huile et une pincée de sel : c''est la provenzal.","Assaisonner le poulet et le cuire dans 1 c. à café d''huile dans une poêle à feu moyen-vif 4 à 5 min de chaque côté, jusqu''à ce qu''il soit doré et cuit à cœur (74 °C).","Baisser le feu, napper le poulet de la moitié de la provenzal et chauffer 30 s sans laisser l''ail colorer.","Mélanger la laitue, les tomates et l''oignon rouge avec le vinaigre, le reste d''huile et une pincée de sel.","Mélanger les pommes de terre chaudes avec le reste de provenzal et servir avec le poulet et la salade."]},"it":{"title":"Pollo a la provenzal con patate in friggitrice ad aria e insalata mista","steps":["Condire le patate con 1 cucchiaino d''olio e un pizzico di sale e cuocerle in friggitrice ad aria a 200 °C per 20 min, scuotendo due volte, finché sono dorate e croccanti.","Mescolare aglio, prezzemolo, peperoncino, 1,5 cucchiai d''olio e un pizzico di sale: è la provenzal.","Condire il pollo e cuocerlo con 1 cucchiaino d''olio in padella a fuoco medio-alto per 4-5 min per lato, finché è dorato e cotto al cuore (74 °C).","Abbassare il fuoco, versare sul pollo metà della provenzal e scaldare 30 s senza far colorire l''aglio.","Condire lattuga, pomodori e cipolla rossa con l''aceto, l''olio rimasto e un pizzico di sale.","Saltare le patate calde con il resto della provenzal e servire con il pollo e l''insalata."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '65496410-7e58-455e-b55c-83c49578e92b')
  returning id
)
