-- Air-fryer chicken suya with flatbread, tomato and onion
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '413dc209-59c0-4ec8-8329-7f9a9305613c'::uuid, null, 'Air-fryer chicken suya with flatbread, tomato and onion', 'seed', null, 'Claude', '/recipe-photos/air-fryer-chicken-suya-with-flatbread-tomato-and-onion.webp', '/recipe-photos/air-fryer-chicken-suya-with-flatbread-tomato-and-onion.webp',
    2, null, 24, 10, 14, '["Grind the peanuts to a fine powder in a blender or spice grinder, in short pulses so they don''t turn to butter. Mix with the paprika, cayenne, ginger and ½ tsp salt (yaji) and set 2 tbsp aside.","Toss the chicken with the garlic, oil and the rest of the yaji until well coated, then thread onto skewers.","Air-fry at 200 °C for 12-14 min, turning halfway, until charred at the edges and cooked through (74 °C inside).","Meanwhile slice the onion, tomatoes and cucumber.","Warm the flatbreads in a dry frying pan for 30 s a side.","Sprinkle the hot suya with the reserved yaji and serve with the onion, tomato, cucumber, flatbreads and lime."]'::jsonb,
    array['african', 'street food', 'grill', 'spicy', 'quick', 'healthy']::text[], 'african', 740, 44.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":["blender","air fryer"]}'::jsonb, true,
    '{"fr":{"title":"Suya de poulet à l''air fryer, pain plat, tomate et oignon","steps":["Moudre finement les cacahuètes au mixeur ou au moulin à épices, par à-coups pour qu''elles ne tournent pas en beurre. Mélanger avec le paprika, le cayenne, le gingembre et ½ c. à café de sel (yaji) et en réserver 2 c. à soupe.","Enrober le poulet de l''ail, de l''huile et du reste de yaji, puis l''enfiler sur des brochettes.","Cuire à l''air fryer à 200 °C pendant 12 à 14 min en retournant à mi-cuisson, jusqu''à ce qu''il soit grillé sur les bords et cuit à cœur (74 °C).","Pendant ce temps, émincer l''oignon, les tomates et le concombre.","Chauffer les pains plats dans une poêle sèche 30 s de chaque côté.","Saupoudrer le suya chaud du yaji réservé et servir avec l''oignon, la tomate, le concombre, les pains et le citron vert."]},"it":{"title":"Suya di pollo in friggitrice ad aria con pane piatto, pomodoro e cipolla","steps":["Macinare finemente le arachidi nel frullatore o nel macinaspezie, a impulsi perché non diventino burro. Mescolarle con paprica, cayenna, zenzero e ½ cucchiaino di sale (yaji) e tenerne da parte 2 cucchiai.","Condire il pollo con aglio, olio e il resto dello yaji, poi infilarlo su spiedini.","Cuocere in friggitrice ad aria a 200 °C per 12-14 min, girando a metà, finché è abbrustolito ai bordi e cotto al cuore (74 °C).","Nel frattempo affettare cipolla, pomodori e cetriolo.","Scaldare i pani piatti in una padella asciutta 30 s per lato.","Cospargere il suya caldo con lo yaji tenuto da parte e servire con cipolla, pomodoro, cetriolo, pane e lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '413dc209-59c0-4ec8-8329-7f9a9305613c')
  returning id
)
