-- Chakhokhbili (Georgian chicken and tomato stew) with bread
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '385b83b5-8fee-43d8-8d1f-2c5863cbf5c4'::uuid, null, 'Chakhokhbili (Georgian chicken and tomato stew) with bread', 'seed', null, 'Claude', '/recipe-photos/chakhokhbili-georgian-chicken-and-tomato-stew-with-bread.webp', '/recipe-photos/chakhokhbili-georgian-chicken-and-tomato-stew-with-bread.webp',
    2, null, 30, 8, 22, '["Season the chicken and brown it in the butter in a wide pan over medium-high heat for 5 min, turning once. Lift out.","Add the onions to the pan and cook over medium heat for 6 min until soft and lightly golden.","Stir in the garlic, khmeli suneli and chilli for 1 min, then add the tomatoes and a pinch of salt.","Return the chicken, cover partly and simmer 10-12 min, until the sauce is thick and the chicken is tender and cooked through.","Stir in half the herbs, take off the heat and rest 2 min, then scatter over the rest.","Slice the bread and serve it with the stew to mop up the sauce."]'::jsonb,
    array['georgian', 'stew', 'quick', 'healthy']::text[], 'georgian', 742, 45.7,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tchakhokhbili (ragoût géorgien de poulet à la tomate) et pain","steps":["Assaisonner le poulet et le faire dorer dans le beurre dans une sauteuse à feu moyen-vif 5 min en le retournant une fois. Le réserver.","Mettre les oignons dans la sauteuse et cuire à feu moyen 6 min jusqu''à ce qu''ils soient tendres et légèrement dorés.","Incorporer l''ail, le khmeli suneli et le piment 1 min, puis ajouter les tomates et une pincée de sel.","Remettre le poulet, couvrir à moitié et laisser mijoter 10 à 12 min, jusqu''à ce que la sauce soit épaisse et le poulet tendre et cuit.","Incorporer la moitié des herbes, retirer du feu et laisser reposer 2 min, puis parsemer du reste.","Trancher le pain et le servir avec le ragoût pour saucer."]},"it":{"title":"Chakhokhbili (spezzatino georgiano di pollo e pomodoro) con pane","steps":["Condire il pollo e rosolarlo nel burro in una padella larga a fuoco medio-alto per 5 min, girandolo una volta. Toglierlo.","Mettere le cipolle in padella e cuocerle a fuoco medio per 6 min finché sono morbide e leggermente dorate.","Unire aglio, khmeli suneli e peperoncino per 1 min, poi aggiungere i pomodori e un pizzico di sale.","Rimettere il pollo, coprire parzialmente e cuocere 10-12 min, finché il sugo è denso e il pollo tenero e cotto.","Incorporare metà delle erbe, togliere dal fuoco e lasciar riposare 2 min, poi cospargere con il resto.","Affettare il pane e servirlo con lo spezzatino per raccogliere il sugo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '385b83b5-8fee-43d8-8d1f-2c5863cbf5c4')
  returning id
)
