  ('94ae4d11-dd1b-48dd-9273-97d720194328'::uuid, '7be6c3d7-5a6e-4703-93fc-0a652a74598e'::uuid, 15, 'zucchini', 'produce'::public.aisle, false, false),
  ('4ccc96fe-bab9-4dce-9973-516efa1ef7d0'::uuid, '7be6c3d7-5a6e-4703-93fc-0a652a74598e'::uuid, 16, 'fresh coriander', 'produce'::public.aisle, false, true)
) as v(id, recipe_id, position, name, aisle, is_staple, optional)
where (i.id = v.id or (i.position = v.position and exists (select 1 from public.recipes x where x.id = i.recipe_id and x.copied_from = v.recipe_id))) and i.optional is distinct from v.optional;

-- Translations for seed recipes and copies of them.
update public.recipes x set translations = v.translations
from (values
  ('d8e4ac12-403d-4d06-97cf-022682d08894'::uuid, '{"en":{"title":"Herb roast turkey","steps":["Tie the turkey breast with kitchen string.","Rub it with rosemary, sage, oregano, curry powder, salt and pepper.","Heat the oil in a pan with the carrot, onion, celery and garlic cut into large chunks, and brown the meat on all sides.","Deglaze with the white wine.","Cook covered over low heat for about 45 minutes, or in the oven at 180 °C covered with foil for about an hour.","Let the meat rest before slicing it.","Blend the cooked vegetables with a little of the pan juices, heat the sauce and serve it with the roast."]},"fr":{"title":"Rôti de dinde aux herbes","steps":["Ficeler le blanc de dinde avec de la ficelle de cuisine.","Le masser avec le romarin, la sauge, l''origan, le curry, le sel et le poivre.","Faire chauffer l''huile dans une sauteuse avec la carotte, l''oignon, le céleri et l''ail coupés en gros morceaux, puis faire revenir la viande sur toutes ses faces.","Déglacer au vin blanc.","Cuire à couvert à feu doux pendant environ 45 minutes, ou au four à 180 °C, couvert de papier aluminium, pendant environ une heure.","Laisser reposer la viande avant de la couper en tranches.","Mixer les légumes de cuisson avec un peu de jus de cuisson, réchauffer la sauce et la servir avec le rôti."]}}'::jsonb),
  ('7cb87b97-df20-4ea6-8837-a97aa96c651f'::uuid, '{"en":{"title":"Ligurian rabbit with Taggiasca olives","steps":["Cut the rabbit into pieces, remove the fat, liver and kidneys, rinse it and pat it dry.","Finely chop the onion, and chop the garlic, germ removed, together with the rosemary needles.","Heat the oil with the chopped aromatics and the rabbit, and brown the meat on all sides over low heat without letting the aromatics burn.","Deglaze with the red wine, raising the heat until the alcohol has evaporated.","Add the bay leaf, thyme, olives and a ladle of hot stock, cover and cook gently, adding more stock only if needed.","After about an hour, when the meat comes away from the bone, uncover and reduce any excess sauce."]},"fr":{"title":"Lapin à la ligure aux olives taggiasche","steps":["Découper le lapin en morceaux, retirer le gras, le foie et les rognons, le rincer et le sécher.","Hacher finement l''oignon, et hacher l''ail dégermé avec les aiguilles de romarin.","Faire chauffer l''huile avec le hachis et le lapin, et faire revenir la viande sur toutes ses faces à feu doux sans brûler les aromates.","Déglacer au vin rouge en augmentant le feu jusqu''à ce que l''alcool soit évaporé.","Ajouter le laurier, le thym, les olives et une louche de bouillon chaud, couvrir et laisser mijoter doucement, en ajoutant du bouillon seulement si nécessaire.","Au bout d''environ une heure, lorsque la viande se détache de l''os, découvrir et faire réduire l''excédent de sauce."]}}'::jsonb),
  ('17c37e4b-5dc1-4114-8e36-27664bd290ca'::uuid, '{"en":{"title":"Taranto-style mussels","steps":["Soak the mussels in salted water for at least an hour, then scrub the shells and pull off the beards.","In a frying pan, gently fry one crushed garlic clove in half the oil without letting it brown.","Add the mussels and a sprig of parsley, deglaze with the wine and cover until they open.","Strain the cooking liquid through a fine sieve and set the mussels aside.","In a clean frying pan, heat the remaining oil with the sliced garlic and the crumbled chilli.","Add the peeled tomatoes, crushing them with a fork, add the mussel liquid and reduce over low heat for about 10 minutes.","Return the mussels to the sauce with the chopped parsley, leave to take on flavour for a few minutes and serve with toasted bread."]},"fr":{"title":"Moules à la mode de Tarente","steps":["Laisser tremper les moules dans de l''eau salée pendant au moins une heure, puis brosser les coquilles et retirer le byssus.","Dans une poêle, faire revenir une gousse d''ail écrasée dans la moitié de l''huile, sans la laisser colorer.","Ajouter les moules et un brin de persil, déglacer au vin et couvrir jusqu''à ce qu''elles s''ouvrent.","Filtrer le jus de cuisson à travers une passoire fine et réserver les moules.","Dans une poêle propre, faire chauffer le reste de l''huile avec l''ail émincé et le piment émietté.","Ajouter les tomates pelées en les écrasant à la fourchette, ajouter le jus des moules et laisser réduire à feu doux pendant environ 10 minutes.","Remettre les moules dans la sauce avec le persil haché, laisser s''imprégner quelques minutes et servir avec du pain grillé."]}}'::jsonb),
  ('bacd2ed3-0463-40f3-bb43-f496642a30b8'::uuid, '{"en":{"title":"Baked courgette and ricotta frittata","steps":["Preheat the oven to 180 °C (conventional, no fan).","Wash and dry the courgettes, trim the ends and cut them into thin rounds.","Beat the eggs in a bowl, stir in the ricotta and parmesan, season with salt and pepper and add the courgettes.","Line a small cake tin with baking paper (lightly greased or dampened), pour in the mixture and level it.","Bake for 30 minutes on the conventional setting, then another 5 minutes with the fan until the top is golden.","Remove from the oven, cut into slices and serve warm or cold."]},"fr":{"title":"Frittata courgettes et ricotta au four","steps":["Préchauffer le four à 180 °C en chaleur statique.","Laver et sécher les courgettes, les équeuter et les couper en fines rondelles.","Battre les œufs dans un saladier, incorporer la ricotta et le parmesan, saler, poivrer et ajouter les courgettes.","Chemiser un petit moule à manqué de papier cuisson (légèrement huilé ou humidifié), verser la préparation et la lisser.","Cuire 30 minutes en chaleur statique, puis encore 5 minutes en chaleur tournante jusqu''à ce que le dessus soit doré.","Sortir du four, couper en parts et servir tiède ou froide."]}}'::jsonb),
  ('27b821b2-edb6-4621-9429-c3073510739c'::uuid, '{"en":{"title":"Farro salad with tuna and chickpeas","steps":["Boil the farro in plenty of salted water for the time given on the packet, drain and leave to cool.","Drain and rinse the chickpeas; drain the tuna well.","Add the chickpeas and flaked tuna to the farro, dress with oil and a pinch of salt and stir.","Quarter the cherry tomatoes; wash and dry the rocket.","Add the cherry tomatoes and rocket to the farro, stir, adjust the seasoning and serve straight away or keep in the fridge until needed."]},"fr":{"title":"Salade d''épeautre au thon et aux pois chiches","steps":["Cuire l''épeautre dans un grand volume d''eau salée selon le temps indiqué sur l''emballage, l''égoutter et le laisser refroidir.","Égoutter et rincer les pois chiches ; bien égoutter le thon.","Ajouter à l''épeautre les pois chiches et le thon émietté, assaisonner avec l''huile et une pincée de sel et mélanger.","Couper les tomates cerises en quatre, laver et sécher la roquette.","Ajouter les tomates cerises et la roquette à l''épeautre, mélanger, rectifier l''assaisonnement et servir aussitôt ou conserver au réfrigérateur jusqu''au moment de servir."]}}'::jsonb),
  ('78ed85bf-8d00-444e-b619-63a462d21934'::uuid, '{"en":{"title":"Baked chicken rolls","steps":["Lay the chicken slices out on a chopping board.","Top each one with a thin slice of fontina and a slice of cooked ham.","Roll them up tightly.","Lightly beat the egg with salt and pepper and dip the rolls in it.","Roll them in the breadcrumbs and arrange them in a baking tray lined with baking paper, with a drizzle of oil.","Bake at 180 °C for 25 minutes."]},"fr":{"title":"Roulés de poulet au four","steps":["Étaler les tranches de poulet sur une planche à découper.","Recouvrir chacune d''une fine tranche de fontina et d''une tranche de jambon blanc.","Les rouler bien serré sur elles-mêmes.","Battre légèrement l''œuf avec du sel et du poivre et y passer les roulés.","Les rouler dans la chapelure et les disposer dans un plat recouvert de papier cuisson, avec un filet d''huile.","Cuire au four à 180 °C pendant 25 minutes."]}}'::jsonb),
  ('e895582c-375e-49f7-95de-d738448185c2'::uuid, '{"en":{"title":"Pork tenderloin medallions with mushrooms","steps":["Trim the fat and silverskin from the tenderloin, cut it into medallions at least 3 cm thick and pat them dry with kitchen paper.","Melt the clarified butter with the sage in a non-stick frying pan and sear the medallions over high heat for about 2 minutes per side, seasoning lightly with salt and pepper.","Deglaze with the white wine and let the alcohol evaporate, then set the meat aside and keep it warm.","In the same pan, cook the thinly sliced mushrooms with the cream, covered, over low heat.","Season with salt, thicken the sauce with the cornflour, return the medallions to the pan to heat through and serve."]},"fr":{"title":"Médaillons de filet mignon aux champignons","steps":["Parer le filet mignon en retirant le gras et les membranes, le couper en médaillons d''au moins 3 cm d''épaisseur et les éponger avec du papier absorbant.","Faire fondre le beurre clarifié avec la sauge dans une poêle antiadhésive et saisir les médaillons à feu vif environ 2 minutes de chaque côté, en salant et poivrant légèrement.","Déglacer au vin blanc et laisser évaporer l''alcool, puis réserver la viande au chaud.","Dans la même poêle, cuire les champignons finement émincés avec la crème, à couvert et à feu doux.","Saler, épaissir la sauce avec la fécule de maïs, remettre les médaillons à réchauffer et servir."]}}'::jsonb),
  ('5bdecccd-5a1b-46a8-8887-5bdebc040da6'::uuid, '{"en":{"title":"Livorno-style cod","steps":["Peel the garlic and remove the green germ.","Fry the garlic in the oil until golden without burning it, then remove it from the pan.","Lay the cod fillets in the pan and brown them for about 5 minutes per side.","Pour in the white wine and let it evaporate over high heat.","Add the passata, the rinsed capers and the olives, and cook until the sauce thickens.","Just before turning off the heat, add the finely chopped parsley and a grind of pepper."]},"fr":{"title":"Cabillaud à la livournaise","steps":["Éplucher l''ail et retirer le germe.","Faire dorer l''ail dans l''huile sans le brûler, puis le retirer de la poêle.","Déposer les filets de cabillaud et les faire dorer environ 5 minutes de chaque côté.","Mouiller avec le vin blanc et laisser évaporer à feu vif.","Ajouter le coulis de tomate, les câpres rincées et les olives, et cuire jusqu''à ce que la sauce réduise.","Juste avant d''éteindre le feu, ajouter le persil finement haché et un tour de moulin à poivre."]}}'::jsonb),
  ('686a6848-a856-4bbe-b6f3-f2f4dae462d8'::uuid, '{"en":{"title":"Sea bream baked in foil","steps":["Preheat the oven to 180 °C.","Clean the sea bream by slitting open the belly, gut it, scale it by scraping against the direction of the scales, then wash and dry it.","Slice the garlic, onion, carrots and lemon.","Stuff the belly of the fish with the bay leaf, garlic, rosemary, thyme and a pinch of salt.","Lay the sea bream on a sheet of foil with the carrots, onion and lemon, season with oil, salt and pepper and seal the parcel tightly.","Bake for about 40 minutes.","Open the parcel, discard the herbs and aromatic vegetables and serve with a drizzle of fresh olive oil."]},"fr":{"title":"Dorade en papillote","steps":["Préchauffer le four à 180 °C.","Nettoyer la dorade en incisant le ventre, la vider, l''écailler en grattant à rebrousse-écailles, puis la laver et la sécher.","Émincer l''ail, l''oignon, les carottes et le citron.","Farcir le ventre du poisson avec le laurier, l''ail, le romarin, le thym et une pincée de sel.","Déposer la dorade sur une feuille de papier aluminium avec les carottes, l''oignon et le citron, arroser d''huile, saler, poivrer et bien fermer la papillote.","Cuire au four pendant environ 40 minutes.","Ouvrir la papillote, retirer les herbes et les légumes aromatiques et servir avec un filet d''huile d''olive crue."]}}'::jsonb),
  ('5d1e5db1-40e3-4f53-9d61-d92916584684'::uuid, '{"en":{"title":"Pasta with lentils","steps":["If using dried lentils, soak them for about 2 hours (this shortens the cooking time); if using canned, just rinse them.","Finely chop the celery, carrot and onion.","Heat the oil in a pot and gently fry the vegetables with the rosemary and garlic for a few minutes.","Add the pancetta and lentils, cover with the hot stock and cook over low heat: about 25 minutes if soaked, 50 if dried and unsoaked.","When the lentils are tender, add the pasta with just enough extra stock to cover it and cook for about 10 minutes, stirring.","Season with salt and pepper and serve hot with a drizzle of fresh olive oil."]},"fr":{"title":"Pâtes aux lentilles","steps":["Pour des lentilles sèches, les faire tremper environ 2 heures (cela raccourcit la cuisson) ; pour des lentilles en conserve, simplement les rincer.","Hacher finement le céleri, la carotte et l''oignon.","Faire chauffer l''huile dans une casserole et faire revenir les légumes avec le romarin et l''ail pendant quelques minutes.","Ajouter les lardons et les lentilles, couvrir de bouillon chaud et cuire à feu doux : environ 25 minutes si elles ont trempé, 50 si elles sont sèches sans trempage.","Lorsque les lentilles sont tendres, ajouter les pâtes avec juste assez de bouillon pour les couvrir et cuire environ 10 minutes en remuant.","Saler, poivrer et servir chaud avec un filet d''huile d''olive crue."]}}'::jsonb),
  ('17aad271-1907-4d68-b566-8d66d014c39e'::uuid, '{"en":{"title":"Creamy tuna and chickpea pasta","steps":["Bring a pot of salted water to the boil for the pasta.","In a frying pan, heat the oil from the tuna together with the extra virgin olive oil.","Finely chop the onion and soften it in the oil over medium heat.","Add the drained chickpeas and flaked tuna; for a creamier sauce, blend half the chickpeas with a little water.","Cook the pasta al dente and drain it, reserving a ladle of the cooking water.","Tip the pasta into the frying pan, add the cooking water and toss for a few moments until creamy.","Serve with chopped chives."]},"fr":{"title":"Pâtes crémeuses au thon et aux pois chiches","steps":["Porter à ébullition l''eau salée pour les pâtes.","Dans une poêle, faire chauffer l''huile du thon avec l''huile d''olive vierge extra.","Hacher finement l''oignon et le faire suer dans l''huile à feu moyen.","Ajouter les pois chiches égouttés et le thon émietté ; pour une sauce plus crémeuse, mixer la moitié des pois chiches avec un peu d''eau.","Cuire les pâtes al dente et les égoutter en réservant une louche d''eau de cuisson.","Verser les pâtes dans la poêle, ajouter l''eau de cuisson et remuer quelques instants pour lier la sauce.","Servir avec la ciboulette ciselée."]}}'::jsonb),
  ('99a3f1c7-6d4d-4439-a8b2-a3e06f9c8a07'::uuid, '{"en":{"title":"Sicilian-style swordfish","steps":["Wash and halve the cherry tomatoes; peel the garlic and chop the chilli if using.","In a large frying pan, heat a drizzle of oil with the garlic, chilli, capers and olives for a couple of minutes.","Add the cherry tomatoes with oregano, basil and a pinch of salt; cover and cook for 10 minutes.","Lay the swordfish slices in the pan in a single layer, cover and cook for another 10 minutes.","Uncover, turn the fish and cook for 5 minutes so the sauce reduces a little; serve straight away."]},"fr":{"title":"Espadon à la sicilienne","steps":["Laver les tomates cerises et les couper en deux ; éplucher l''ail et hacher le piment, le cas échéant.","Dans une grande poêle, faire chauffer un filet d''huile avec l''ail, le piment, les câpres et les olives pendant deux minutes environ.","Ajouter les tomates cerises avec l''origan, le basilic et une pincée de sel ; couvrir et cuire 10 minutes.","Déposer les tranches d''espadon au fond de la poêle en une seule couche, couvrir et cuire encore 10 minutes.","Découvrir, retourner le poisson et laisser cuire 5 minutes pour que la sauce réduise un peu ; servir aussitôt."]}}'::jsonb),
  ('61e1e664-8f21-4039-82b4-008367e27c96'::uuid, '{"en":{"title":"Chicken breast cacciatore","steps":["Clean the mushrooms and cut them into pieces.","Cut the chicken breast into fairly large chunks.","Peel the garlic, removing the germ, and slice the shallot.","Heat the oil with the garlic and mushrooms over low heat for about 10 minutes.","Add the shallot and chicken, deglaze with the wine and brown until the meat is evenly coloured.","Add the crushed peeled tomatoes and the olives, and season with salt and pepper.","Cook gently for about 10 minutes and serve with fresh basil."]},"fr":{"title":"Blanc de poulet à la chasseur","steps":["Nettoyer les champignons et les couper en morceaux.","Couper le blanc de poulet en morceaux assez gros.","Éplucher l''ail en retirant le germe et émincer l''échalote.","Faire chauffer l''huile avec l''ail et les champignons à feu doux pendant environ 10 minutes.","Ajouter l''échalote et le poulet, déglacer au vin et faire revenir jusqu''à ce que la viande soit uniformément dorée.","Ajouter les tomates pelées écrasées et les olives, saler et poivrer.","Laisser mijoter doucement environ 10 minutes et servir avec du basilic frais."]}}'::jsonb),
  ('567369ff-11d7-4696-a56a-38bcb709f826'::uuid, '{"en":{"title":"Light chicken pizzaiola","steps":["In a large frying pan, cook the tomato pulp with the crushed garlic, salt, pepper and oregano over low heat for 10-15 minutes.","Adjust the salt, thin with half a glass of water and cook for another couple of minutes.","Lay the chicken slices in the sauce, cover them with sauce and sprinkle with more oregano.","Cook over medium heat with the lid ajar for about 10 minutes, turning the meat halfway through.","Off the heat, add a drizzle of fresh olive oil if you like and serve with the sauce."]},"fr":{"title":"Blanc de poulet à la pizzaiola allégé","steps":["Dans une grande poêle, cuire la pulpe de tomate avec l''ail écrasé, le sel, le poivre et l''origan à feu doux pendant 10-15 minutes.","Rectifier le sel, allonger avec un demi-verre d''eau et cuire encore deux minutes environ.","Déposer les escalopes de poulet dans la sauce, les napper de sauce et saupoudrer d''un peu plus d''origan.","Cuire à feu moyen avec le couvercle entrouvert pendant environ 10 minutes, en retournant la viande à mi-cuisson.","Hors du feu, ajouter si on le souhaite un filet d''huile d''olive crue et servir avec la sauce."]}}'::jsonb),
  ('2523169e-7128-44b0-9c23-174778b41c14'::uuid, '{"en":{"title":"Octopus stew with potatoes","steps":["Clean the octopus by removing the eyes, beak and innards, rinse it well and cut it into small pieces.","Thinly slice the onion and put it in a pot with the oil, passata, garlic and octopus; season with salt and pepper and stir.","Cover and cook over low heat for 40 minutes without adding water: the octopus cooks in its own liquid.","Peel the potatoes, cut them into even pieces, rinse them and add them to the pot.","Continue cooking, covered, for another 20 minutes (up to 30 more if the octopus is large), until a fork pierces it without resistance.","Adjust the salt and pepper, finish with fresh parsley and a pinch of chilli and serve hot with the sauce."]},"fr":{"title":"Poulpe mijoté aux pommes de terre","steps":["Nettoyer le poulpe en retirant les yeux, le bec et les viscères, bien le rincer et le couper en petits morceaux.","Émincer finement l''oignon et le mettre dans une cocotte avec l''huile, le coulis de tomate, l''ail et le poulpe ; saler, poivrer et mélanger.","Couvrir et cuire à feu doux pendant 40 minutes sans ajouter d''eau : le poulpe cuit dans son propre jus.","Éplucher les pommes de terre, les couper en morceaux réguliers, les rincer et les ajouter dans la cocotte.","Poursuivre la cuisson à couvert pendant encore 20 minutes (jusqu''à 30 de plus si le poulpe est gros), jusqu''à ce qu''une fourchette le transperce sans résistance.","Rectifier l''assaisonnement en sel et en poivre, parsemer de persil frais et d''une pincée de piment et servir chaud avec la sauce."]}}'::jsonb),
  ('99e6987f-43cf-4bb6-a6d2-33eca8e6d6c9'::uuid, '{"en":{"title":"Prawn and orange risotto","steps":["Peel the prawns, removing the heads and shells.","Fry them in a frying pan with the oil and garlic until they change colour, then set them aside.","In a saucepan, soften the chopped shallot in the butter, add the rice and toast it for 2-3 minutes.","Deglaze with the white wine and let it evaporate.","Cook the rice through, adding the boiling stock one ladle at a time and stirring often (about 16-18 minutes).","A few minutes before the end, add the prawns and orange zest; season with salt.","Turn off the heat, stir in the cold butter until creamy, leave to rest for a couple of minutes and serve."]},"fr":{"title":"Risotto aux crevettes et à l''orange","steps":["Décortiquer les crevettes en retirant la tête et la carapace.","Les faire revenir à la poêle avec l''huile et l''ail jusqu''à ce qu''elles changent de couleur, puis les réserver.","Dans une casserole, faire suer l''échalote hachée dans le beurre, ajouter le riz et le faire nacrer 2-3 minutes.","Déglacer au vin blanc et laisser évaporer.","Poursuivre la cuisson en ajoutant le bouillon bouillant louche par louche, en remuant souvent (environ 16-18 minutes).","Quelques minutes avant la fin, ajouter les crevettes et le zeste d''orange ; saler.","Éteindre le feu, incorporer le beurre froid pour lier le risotto, laisser reposer deux minutes environ et servir."]}}'::jsonb),
  ('48ebc83a-a38f-414e-9c34-86c41a6e7c2c'::uuid, '{"en":{"title":"Pistachio and almond crusted salmon","steps":["Preheat the oven to 200 °C.","Chop the pistachios and almonds and mix them with the breadcrumbs, a pinch of salt and the oil until you have a firm mixture.","Lightly grease an ovenproof dish and arrange the salmon fillets in it.","Spread the crust over the top of the fillets, pressing down well.","Bake for about 15 minutes, until the crust is golden, and serve."]},"fr":{"title":"Saumon en croûte de pistaches et d''amandes","steps":["Préchauffer le four à 200 °C.","Hacher les pistaches et les amandes et les mélanger avec la chapelure, une pincée de sel et l''huile jusqu''à obtenir une préparation compacte.","Huiler légèrement un plat allant au four et y disposer les pavés de saumon.","Répartir la croûte sur le dessus des pavés en pressant bien.","Cuire au four pendant environ 15 minutes, jusqu''à ce que la croûte soit dorée, et servir."]}}'::jsonb),
  ('620775f7-df12-48a6-acee-5a00dcdfeba6'::uuid, '{"en":{"title":"Saltimbocca alla romana","steps":["Trim the fat and sinew from the veal slices and salt them very lightly, as the prosciutto is already salty.","Coat the slices evenly in flour.","Place a slice of prosciutto and a sage leaf on each one, securing them with a cocktail stick.","Melt the butter in a frying pan and brown the slices.","Pour in the white wine and let it evaporate completely.","Cover and continue cooking for about 2 minutes, then serve immediately, piping hot."]},"fr":{"title":"Saltimbocca alla romana","steps":["Retirer le gras et les nerfs des escalopes de veau et les saler à peine, le jambon cru étant déjà salé.","Fariner les escalopes de manière uniforme.","Déposer sur chacune une tranche de jambon cru et une feuille de sauge, et les fixer avec un cure-dent.","Faire fondre le beurre dans une poêle et faire dorer les escalopes.","Mouiller avec le vin blanc et le laisser s''évaporer complètement.","Couvrir et poursuivre la cuisson environ 2 minutes, puis servir aussitôt bien chaud."]}}'::jsonb),
  ('015f5e6a-260f-4598-bd56-b3e794d5a80f'::uuid, '{"en":{"title":"Lemon chicken escalopes","steps":["Dust the chicken slices with flour on both sides, shaking off the excess.","Heat a drizzle of oil with the pinch of garlic powder in a non-stick frying pan.","Brown the escalopes on both sides until golden, then season with salt.","Pour in the lemon juice and a glass of water and let it reduce until a creamy sauce forms.","Stir in the honey to soften the acidity and turn the slices again in the pan juices.","Finish with grated lemon zest and ground pepper, leave to rest for a moment and serve with parsley and the sauce."]},"fr":{"title":"Escalopes de poulet au citron","steps":["Fariner les escalopes de poulet des deux côtés en secouant l''excédent.","Faire chauffer un filet d''huile avec la pincée d''ail en poudre dans une poêle antiadhésive.","Faire dorer les escalopes des deux côtés, puis les saler.","Verser le jus de citron et un verre d''eau et laisser réduire jusqu''à obtenir une petite sauce onctueuse.","Incorporer le miel pour adoucir l''acidité et retourner de nouveau les escalopes dans le jus.","Terminer avec le zeste de citron râpé et du poivre moulu, laisser reposer un instant et servir avec le persil et la sauce."]}}'::jsonb),
  ('60fe0e85-846c-4255-941b-f36927ddbfb8'::uuid, '{"en":{"title":"Pan-cooked lemon turkey thigh","steps":["Remove any remaining feathers and, if you like, bone the thigh with a knife.","Heat the oil in a frying pan and add the meat with the lemon slices and juice, salt, pepper, rosemary and bay leaves.","Brown over high heat until golden, then turn it and brown the other side.","Deglaze with the white wine and let the alcohol evaporate.","Cover, turn the heat down to the minimum and cook for about an hour, without adding water.","Raise the heat to reduce the liquid and caramelise the meat in its juices, turning it.","Leave to rest, covered, for 5-10 minutes before serving."]},"fr":{"title":"Haut de cuisse de dinde au citron à la poêle","steps":["Retirer les éventuelles plumes restantes et, si on le souhaite, désosser le haut de cuisse au couteau.","Faire chauffer l''huile dans une poêle et y déposer la viande avec les tranches et le jus de citron, le sel, le poivre, le romarin et le laurier.","Faire dorer à feu vif, puis la retourner et faire dorer l''autre face.","Déglacer au vin blanc et laisser évaporer l''alcool.","Couvrir, baisser le feu au minimum et cuire environ une heure, sans ajouter d''eau.","Monter le feu pour faire réduire les liquides et caraméliser la viande dans son jus, en la retournant.","Laisser reposer à couvert 5-10 minutes avant de servir."]}}'::jsonb),
  ('63131dca-fae3-4d10-8d21-eb0d75a2cdc5'::uuid, '{"en":{"title":"Spaghetti alle vongole","steps":["Soak the clams in cold water with the coarse salt for about 2 hours so they release their sand.","In a large frying pan, heat the oil with the garlic clove and the parsley stems for about 1 minute.","Add the drained clams, cover and cook over high heat until they have all opened.","Strain and keep the cooking liquid, shell about two thirds of the clams and discard the garlic and stems.","Boil the spaghetti in salted water and drain them 5 minutes before the stated cooking time, setting aside some of the cooking water.","Return the spaghetti to the pan with the clams, their strained liquid and a little cooking water; toss until the sauce turns thick and creamy.","Finish with finely chopped parsley and a grind of pepper, then serve immediately."]},"fr":{"title":"Spaghetti alle vongole","steps":["Faire tremper les palourdes dans de l''eau froide avec le gros sel pendant environ 2 heures, pour qu''elles rejettent leur sable.","Dans une grande poêle, faire chauffer l''huile avec la gousse d''ail et les tiges de persil pendant environ 1 minute.","Ajouter les palourdes égouttées, couvrir et cuire à feu vif jusqu''à ce qu''elles soient toutes ouvertes.","Filtrer et conserver le jus de cuisson, décortiquer environ les deux tiers des palourdes et retirer l''ail et les tiges.","Cuire les spaghetti dans de l''eau salée et les égoutter 5 minutes avant le temps indiqué, en réservant un peu d''eau de cuisson.","Remettre les spaghetti dans la poêle avec les palourdes, leur jus filtré et un peu d''eau de cuisson ; faire sauter jusqu''à ce que la sauce devienne épaisse et crémeuse.","Terminer avec du persil finement ciselé et un tour de moulin à poivre, puis servir aussitôt."]}}'::jsonb),
  ('10e1f9f4-df57-4d78-9f93-c707704a3740'::uuid, '{"en":{"title":"Veal stew with potatoes","steps":["Peel the carrot and onion, trim the celery and cut everything into rough chunks.","Heat the oil and gently soften the vegetables with the herbs over low heat for 20-25 minutes, without water.","Cut the veal into 3-5 cm cubes, removing fat and gristle.","Add the meat to the softened vegetables and stir until it changes colour on all sides.","Deglaze with the red wine over high heat until it has completely evaporated.","Pour in the hot stock and cook over very low heat for about an hour, covering if the liquid reduces too much.","Peel the potatoes, cut them into pieces of at least 4 cm and add them to the stew.","Cook for about 20 more minutes, until the potatoes are tender and the sauce is thick."]},"fr":{"title":"Sauté de veau aux pommes de terre","steps":["Éplucher la carotte et l''oignon, nettoyer le céleri et couper le tout en gros morceaux.","Faire chauffer l''huile et faire suer les légumes avec les herbes aromatiques à feu doux pendant 20-25 minutes, sans eau.","Couper le veau en cubes de 3-5 cm, en retirant le gras et les cartilages.","Ajouter la viande aux légumes et remuer jusqu''à ce qu''elle change de couleur sur toutes les faces.","Déglacer au vin rouge à feu vif jusqu''à complète évaporation.","Verser le bouillon chaud et cuire à feu très doux pendant environ une heure, en couvrant si le liquide réduit trop.","Éplucher les pommes de terre, les couper en morceaux d''au moins 4 cm et les ajouter au sauté.","Poursuivre la cuisson environ 20 minutes, jusqu''à ce que les pommes de terre soient tendres et la sauce épaisse."]}}'::jsonb),
  ('e602a672-019f-4399-a580-26a8268d9a62'::uuid, '{"en":{"title":"Beef strips with rocket and cherry tomatoes","steps":["Wash and dry the rocket; wash the cherry tomatoes and halve them.","Pound the beef slices to thin them, cut them into strips and quickly dredge them in the sifted flour.","Heat the oil with the garlic in a non-stick frying pan and brown the beef strips over high heat for 2-3 minutes.","Season with salt and pepper, add the cherry tomatoes and toss for about a minute.","Add half the rocket, stir for one more minute and turn off the heat.","Plate on a bed of raw rocket and cherry tomatoes, lay the meat on top and finish with a drizzle of oil and balsamic vinegar."]},"fr":{"title":"Émincé de bœuf à la roquette et aux tomates cerises","steps":["Laver et sécher la roquette ; laver les tomates cerises et les couper en deux.","Aplatir les tranches de bœuf pour les affiner, les tailler en lanières et les passer rapidement dans la farine tamisée.","Faire chauffer l''huile avec l''ail dans une poêle antiadhésive et faire dorer les lanières de bœuf à feu vif pendant 2-3 minutes.","Saler et poivrer, ajouter les tomates cerises et faire sauter environ une minute.","Ajouter la moitié de la roquette, mélanger encore une minute et éteindre le feu.","Dresser sur un lit de roquette et de tomates cerises crues, déposer la viande dessus et terminer par un filet d''huile et de vinaigre balsamique."]}}'::jsonb),
  ('4147d3f8-71f3-493a-987d-035d634235c5'::uuid, '{"en":{"title":"Beef strips with vegetables","steps":["Cut the meat into thin strips and marinate for about 15 minutes with the soy sauce, a drizzle of oil, the ginger, crushed garlic and cornflour.","Cut the carrot and courgettes into sticks and the spring onion into rounds.","Stir-fry the vegetables in a frying pan with a little oil and a pinch of salt over high heat for a few minutes, keeping them crunchy.","In another frying pan with a drizzle of oil, brown the beef strips for a couple of minutes, stirring constantly.","Combine the meat and vegetables, add the sesame seeds and stir-fry over high heat for 1-2 minutes; serve immediately."]},"fr":{"title":"Émincé de bœuf aux légumes","steps":["Tailler la viande en fines lanières et la faire mariner environ 15 minutes avec la sauce soja, un filet d''huile, le gingembre, l''ail écrasé et la fécule de maïs.","Tailler la carotte et les courgettes en bâtonnets et l''oignon nouveau en rondelles.","Faire sauter les légumes à la poêle avec un peu d''huile et une pincée de sel à feu vif pendant quelques minutes, en les gardant croquants.","Dans une autre poêle avec un filet d''huile, faire revenir les lanières de bœuf pendant deux minutes environ, en remuant sans cesse.","Réunir la viande et les légumes, ajouter les graines de sésame et faire sauter à feu vif 1-2 minutes ; servir aussitôt."]}}'::jsonb),
  ('6293ce0d-a630-48c6-b558-37f7a09ff101'::uuid, '{"en":{"title":"Beef tagliata with rocket and Parmesan","steps":["Take the meat out of the fridge an hour beforehand to bring it to room temperature.","Heat the grill pan well and sprinkle it with coarse salt.","Cook the sirloin for 3 minutes per side.","Let it rest for a minute on a chopping board, then slice it about half a centimetre thick and season with pepper.","Wash and dry the rocket, removing the long stems.","Arrange the rocket and beef slices on the plate, finish with Parmesan shavings and a drizzle of oil."]},"fr":{"title":"Tagliata de bœuf, roquette et parmesan","steps":["Sortir la viande du réfrigérateur une heure avant pour la mettre à température ambiante.","Bien faire chauffer le gril et le parsemer de gros sel.","Cuire le faux-filet 3 minutes de chaque côté.","Le laisser reposer une minute sur une planche, puis le trancher à environ un demi-centimètre d''épaisseur et poivrer.","Laver et sécher la roquette en retirant les longues tiges.","Disposer la roquette et les tranches de viande dans l''assiette, terminer avec des copeaux de parmesan et un filet d''huile."]}}'::jsonb),
  ('eed99dab-45c0-4360-afbb-73c4b4ebc594'::uuid, '{"en":{"title":"Basque-style chicken breast","steps":["Slice each chicken breast in half horizontally to make thin escalopes.","Thinly slice the onion and garlic, deseed the pepper and cut it into thin strips.","Blanch the tomato in boiling water for 30 s, peel it and chop it roughly; cut the ham into strips.","Sear the onion, garlic and pepper in the oil over high heat for about 8 min, then set aside.","In the same frying pan, brown the escalopes for a few minutes on each side.","Return the vegetables, add the ham, tomato and Espelette pepper, season with salt and pepper and stir gently.","Pour in the white wine and reduce at a rolling boil for 3 min.","Lower the heat and simmer for about 15 min, stirring often."]},"it":{"title":"Petto di pollo alla basca","steps":["Aprire ogni petto di pollo a metà nello spessore per ottenere delle fettine sottili.","Affettare la cipolla e l''aglio, eliminare i semi dal peperone e tagliarlo a listarelle sottili.","Sbollentare il pomodoro 30 s in acqua bollente, pelarlo e tagliarlo a pezzetti; tagliare il prosciutto a listarelle.","Saltare cipolla, aglio e peperone nell''olio a fuoco vivo per circa 8 min, poi tenerli da parte.","Nella stessa padella, dorare le fettine per qualche minuto per lato.","Rimettere le verdure, aggiungere prosciutto, pomodoro e peperoncino di Espelette, salare, pepare e mescolare delicatamente.","Versare il vino bianco e farlo ridurre a fuoco vivace per 3 min.","Abbassare la fiamma e cuocere a fuoco lento per circa 15 min, mescolando spesso."]}}'::jsonb),
  ('f57e24d7-670a-41d7-89de-13783e359454'::uuid, '{"en":{"title":"Light veal blanquette","steps":["Bring a casserole of water to the boil; meanwhile, peel and slice the onion, shallot and carrots.","Add the meat and vegetables to the boiling water with the thyme, season with salt and pepper, cover and cook for 30 min.","Drain everything, return it to the casserole with the drained mushrooms and sauté briefly.","Stir in the cream and lemon juice, mixing well until the sauce is thick enough to coat.","Serve immediately, for example with green beans."]},"it":{"title":"Blanquette di vitello leggera","steps":["Portare a ebollizione una casseruola d''acqua; nel frattempo, pelare e affettare cipolla, scalogno e carote.","Immergere la carne e le verdure nell''acqua bollente con il timo, salare, pepare, coprire e cuocere per 30 min.","Scolare il tutto, rimetterlo nella casseruola con i funghi sgocciolati e farlo saltare brevemente.","Incorporare la panna e il succo di limone mescolando bene, finché la salsa risulta abbastanza densa da velare.","Servire subito, per esempio con fagiolini."]}}'::jsonb),
  ('449a378d-34ee-45e9-b50d-4fd3ee78ab88'::uuid, '{"en":{"title":"One-pot veal blanquette","steps":["Cut the veal into large pieces, the carrots into rounds and the mushrooms into quarters; chop the onion and garlic, and peel and dice the potato.","In a large casserole, quickly sear the veal in the oil without browning it too much.","Add the onion and garlic, sprinkle with the flour and stir for 1 min.","Add the carrots, mushrooms, potato, thyme and bay leaf, pour in the hot stock, season lightly with salt, add pepper and stir.","Cover and cook over low heat for 1 h 15 to 1 h 30, stirring from time to time, until the meat is meltingly tender.","Off the heat, whisk the cream with the egg yolk and lemon juice, then stir it in gently without letting it boil again.","Sprinkle with parsley and serve."]},"it":{"title":"Blanquette di vitello one pot","steps":["Tagliare il vitello a pezzi grossi, le carote a rondelle e i funghi in quarti; tritare cipolla e aglio, pelare la patata e tagliarla a dadini.","In una casseruola capiente, rosolare velocemente il vitello nell''olio senza farlo colorire troppo.","Aggiungere cipolla e aglio, spolverizzare con la farina e mescolare per 1 min.","Aggiungere carote, funghi, patata, timo e alloro, versare il brodo caldo, salare leggermente, pepare e mescolare.","Coprire e cuocere a fuoco basso da 1 h 15 a 1 h 30, mescolando di tanto in tanto, finché la carne è tenerissima.","Fuori dal fuoco, sbattere la panna con il tuorlo e il succo di limone, poi incorporarla delicatamente senza far riprendere il bollore.","Cospargere di prezzemolo e servire."]}}'::jsonb),
  ('50ecea78-6439-45fa-8702-4656b35e676d'::uuid, '{"en":{"title":"Light salt cod brandade","steps":["The day before, rinse the salt cod and leave it to desalt for 24 h in the fridge in cold water, changing the water 3 to 4 times.","Peel and cut the potatoes, then cook them in boiling water until tender.","Put the cod and crushed garlic in cold water and poach for 8 to 10 minutes at a gentle simmer, without boiling.","Drain the cod, remove the skin and bones, then flake it finely.","Mash the potatoes, adding the warm milk little by little, then stir in the yoghurt or skyr.","Mix the cod into the mash while drizzling in the olive oil, then season with pepper and add a little nutmeg.","Reheat over low heat or for 10 minutes in the oven at 180 °C, then serve sprinkled with parsley."]},"it":{"title":"Brandade di baccalà leggera","steps":["Il giorno prima, sciacquare il baccalà e lasciarlo dissalare 24 h in frigorifero in acqua fredda, cambiando l''acqua 3 o 4 volte.","Pelare e tagliare le patate, poi lessarle in acqua bollente finché sono tenere.","Mettere il baccalà e l''aglio schiacciato in acqua fredda e cuocerlo da 8 a 10 minuti a fuoco dolcissimo, appena sobbollente, senza farlo bollire.","Scolare il baccalà, eliminare pelle e spine, poi sfilacciarlo finemente.","Schiacciare le patate aggiungendo poco alla volta il latte tiepido, poi incorporare lo yogurt o lo skyr.","Mescolare il baccalà al purè versando l''olio d''oliva a filo, poi pepare e aggiungere un po'' di noce moscata.","Scaldare a fuoco basso o per 10 minuti in forno a 180 °C, poi servire cosparso di prezzemolo."]}}'::jsonb),
  ('e1a56986-8c34-4f97-b92c-a9595a04b081'::uuid, '{"en":{"title":"Bœuf bourguignon","steps":["Optional: the day before, marinate the beef cubes in the fridge in the wine with a little carrot, the crushed garlic and the bouquet garni.","Drain the meat, keeping the liquid, pat it dry, season with salt and pepper and dust lightly with flour.","Sear the beef in small batches over high heat in hot oil in a casserole, then set aside.","In the casserole, brown the lardons, then the carrot rounds, for 5 min.","Return the meat, sprinkle with the remaining flour, add the tomato purée, then the wine (or the strained marinade), the stock and the bouquet garni; bring to the boil.","Cover and cook in the oven at 150 °C for 2 h 30 to 3 h, stirring from time to time.","About 45 min before the end, fry the mushrooms in butter; in another frying pan, glaze the pearl onions with a little butter, sugar and water.","Add the mushrooms and onions to the casserole for the last 30 minutes and adjust the seasoning.","Remove the bouquet garni, sprinkle with parsley and serve piping hot."]},"it":{"title":"Bœuf bourguignon","steps":["Facoltativo: il giorno prima, marinare i cubetti di manzo in frigorifero nel vino con un po'' di carota, l''aglio schiacciato e il mazzetto aromatico.","Scolare la carne conservando il liquido, asciugarla, salarla, peparla e infarinarla leggermente.","Rosolare il manzo poco alla volta a fuoco vivo nell''olio caldo in una casseruola, poi tenerlo da parte.","Nella casseruola, rosolare la pancetta a cubetti, poi la carota a rondelle per 5 min.","Rimettere la carne, spolverizzare con la farina rimasta, aggiungere il concentrato di pomodoro, poi il vino (o la marinata filtrata), il brodo e il mazzetto aromatico; portare a ebollizione.","Coprire e cuocere in forno a 150 °C da 2 h 30 a 3 h, mescolando di tanto in tanto.","Circa 45 min prima della fine, saltare i funghi nel burro; in un''altra padella, glassare le cipolline con un po'' di burro, zucchero e acqua.","Aggiungere funghi e cipolline nella casseruola per gli ultimi 30 minuti e regolare di sale e pepe.","Togliere il mazzetto aromatico, cospargere di prezzemolo e servire ben caldo."]}}'::jsonb),
  ('589fb2e8-d8cb-4568-93b3-16cca96d832b'::uuid, '{"en":{"title":"Spiced baked cod with vegetables","steps":["Preheat the oven to 200 °C.","Slice the potatoes and courgettes into rounds, dice the onion and cut the pepper into strips.","Mix these vegetables with the cherry tomatoes, olive oil, lemon juice, peeled garlic cloves and a little salt.","Spread everything out in a large dish and roast for 25 minutes.","Meanwhile, mix the oil, lemon juice, paprika, turmeric and Espelette pepper, then brush it over the cod pieces.","Place the fish on the vegetables and cook for a further 15 minutes.","Serve sprinkled with chopped parsley, with lemon wedges."]},"it":{"title":"Merluzzo speziato al forno con verdure","steps":["Preriscaldare il forno a 200 °C.","Tagliare patate e zucchine a rondelle, la cipolla a dadini e il peperone a listarelle.","Mescolare queste verdure con i pomodorini, l''olio d''oliva, il succo di limone, gli spicchi d''aglio pelati e un po'' di sale.","Distribuire il tutto in una teglia grande e arrostire in forno per 25 minuti.","Nel frattempo, mescolare l''olio, il succo di limone, la paprika, la curcuma e il peperoncino di Espelette, poi spennellarne i pezzi di merluzzo.","Adagiare il pesce sulle verdure e proseguire la cottura per 15 minuti.","Servire cosparso di prezzemolo tritato, con spicchi di limone."]}}'::jsonb),
  ('c4df5fda-28c9-43a2-96e7-7e5561d1ce17'::uuid, '{"en":{"title":"Basque-style cod loin","steps":["Preheat the oven to 210 °C. Plunge the tomatoes into boiling water for 30 seconds so they peel easily.","Deseed the tomatoes and dice them; cut the pepper into cubes, thinly slice the onion and chop the garlic.","Put the vegetables in a sauté pan with a small glass of water, the chilli and the bouquet garni, cover and leave to stew gently over low heat.","Season with salt and pepper, then remove the chilli and the bouquet garni.","Cook the rice for about 20 minutes in boiling salted water, drain it and keep it warm.","Spread the stewed vegetables in a gratin dish, place the cod pieces on top, season with salt and pepper and bake for 10 minutes.","Serve the fish and its Basque-style vegetables with the rice."]},"it":{"title":"Trancio di merluzzo alla basca","steps":["Preriscaldare il forno a 210 °C. Immergere i pomodori per 30 secondi in acqua bollente per pelarli facilmente.","Eliminare i semi dai pomodori e tagliarli a dadini; tagliare il peperone a cubetti, affettare la cipolla e tritare l''aglio.","Mettere le verdure in una padella dai bordi alti con un bicchierino d''acqua, il peperoncino e il mazzetto aromatico, coprire e lasciar stufare a fuoco basso.","Salare, pepare, poi togliere il peperoncino e il mazzetto aromatico.","Cuocere il riso per circa 20 minuti in acqua bollente salata, scolarlo e tenerlo in caldo.","Distribuire le verdure stufate in una pirofila, adagiarvi sopra i tranci di merluzzo, salare, pepare e infornare per 10 minuti.","Servire il pesce e le sue verdure alla basca con il riso."]}}'::jsonb),
  ('484ced08-5bb5-47ec-ac0a-be7990951eef'::uuid, '{"en":{"title":"Pork tenderloin with mustard","steps":["Thinly slice the onion.","Heat the butter and oil in a sauté pan and sear the pork tenderloin on all sides.","Soften the onion in the fat for 5 min, deglaze with the white wine and return the meat.","Cover and cook for 20 min over medium heat, then set the meat aside on a plate.","Pour the cream into the pan, scraping up the browned bits, season with salt and pepper and stir in both mustards.","Cut the tenderloin into thick slices, return them to the sauce, spoon it over and simmer gently for 10 min."]},"it":{"title":"Filetto di maiale alla senape","steps":["Affettare finemente la cipolla.","Scaldare burro e olio in una padella dai bordi alti e rosolare il filetto su tutti i lati.","Far appassire la cipolla nel grasso di cottura per 5 min, sfumare con il vino bianco e rimettere la carne.","Coprire e cuocere 20 min a fuoco medio, poi tenere da parte la carne su un piatto.","Versare la panna nella padella raschiando il fondo, salare, pepare e stemperarvi le due senapi.","Tagliare il filetto a fette spesse, rimetterle nella salsa, ricoprirle di salsa e cuocere a fuoco lento per 10 min."]}}'::jsonb),
  ('77447388-35a3-4563-83f0-2ca7a120c528'::uuid, '{"en":{"title":"Mustard pork tenderloin with potatoes and broccoli","steps":["Whisk the mustard, maple syrup, soy sauce and a little oil, coat the pork tenderloin and leave it to marinate in the fridge for at least 30 min.","Preheat the oven to 190 °C and thinly slice the potatoes.","Spread the potatoes in a dish, season with salt, pepper, thyme and oil, then bake for 15 min.","Cut the broccoli into florets.","Add the tenderloin and broccoli alongside the potatoes, season and roast for 25 to 30 min, until the core temperature reaches 63 °C.","Let the meat rest for a few minutes, slice it and serve with the vegetables."]},"it":{"title":"Filetto di maiale alla senape con patate e broccoli","steps":["Sbattere senape, sciroppo d''acero, salsa di soia e un po'' d''olio, ricoprire il filetto e lasciarlo marinare in frigorifero per almeno 30 min.","Preriscaldare il forno a 190 °C e affettare sottilmente le patate.","Distribuire le patate in una teglia, condire con sale, pepe, timo e olio, poi infornare per 15 min.","Dividere il broccolo in cimette.","Aggiungere il filetto e il broccolo accanto alle patate, condire e arrostire da 25 a 30 min, finché la carne raggiunge 63 °C al cuore.","Lasciar riposare la carne qualche minuto, affettarla e servire con le verdure."]}}'::jsonb),
  ('9b3c2f12-57fa-470a-81df-b5393ed78c87'::uuid, '{"en":{"title":"Moules marinières","steps":["Rinse the mussels thoroughly and discard any that are broken or stay open when tapped.","Cut the celery into small dice, and chop the shallots and parsley.","Melt the butter in a casserole and gently sweat the shallots and celery without letting them colour.","Add the mussels, white wine, a generous amount of pepper, the bouquet garni and the parsley.","Cover and cook over high heat for 3 to 4 minutes, stirring halfway through, until all the mussels have opened.","Stir one last time to coat the mussels in the juices, remove the bouquet garni and serve immediately."]},"it":{"title":"Moules marinières","steps":["Sciacquare accuratamente le cozze ed eliminare quelle rotte o che restano aperte quando si picchiettano.","Tagliare il sedano a dadini, tritare gli scalogni e il prezzemolo.","Far sciogliere il burro in una casseruola e farvi appassire dolcemente scalogni e sedano, senza farli colorire.","Aggiungere le cozze, il vino bianco, una generosa macinata di pepe, il mazzetto aromatico e il prezzemolo.","Coprire e cuocere a fuoco vivo da 3 a 4 minuti mescolando a metà cottura, finché tutte le cozze si sono aperte.","Mescolare un''ultima volta per avvolgere le cozze nel loro sugo, togliere il mazzetto aromatico e servire subito."]}}'::jsonb),
  ('3716d87e-51ea-489d-9fc2-2d1322423904'::uuid, '{"en":{"title":"Light lamb navarin","steps":["Peel and cut the carrot, turnip and potatoes; slice the leek and onion, chop the tomato and top and tail the beans. Trim the fat from the lamb.","Sear the lamb in the hot oil for 5 to 7 min, then set aside.","Sweat the onion and garlic in the casserole and, if desired, sprinkle them with flour.","Return the lamb, add the stock, tomato, carrot, turnip, leek and bouquet garni; cover and simmer gently for 45 min.","Add the potatoes and green beans and cook for another 15 to 20 min until tender.","Adjust the seasoning, remove the bouquet garni and serve in shallow bowls sprinkled with parsley."]},"it":{"title":"Navarin di agnello leggero","steps":["Pelare e tagliare carota, rapa e patate; affettare porro e cipolla, tagliare a pezzetti il pomodoro e spuntare i fagiolini. Sgrassare l''agnello.","Rosolare l''agnello da 5 a 7 min nell''olio caldo, poi tenerlo da parte.","Far appassire la cipolla e l''aglio nella casseruola e, se si desidera, spolverizzarli con la farina.","Rimettere l''agnello, aggiungere brodo, pomodoro, carota, rapa, porro e mazzetto aromatico; coprire e lasciar sobbollire per 45 min.","Aggiungere patate e fagiolini e cuocere ancora da 15 a 20 min, finché sono teneri.","Regolare di sale e pepe, togliere il mazzetto aromatico e servire in piatti fondi cosparsi di prezzemolo."]}}'::jsonb),
  ('a939f34c-48e2-4fd3-bc1a-216d1801b422'::uuid, '{"en":{"title":"Spring lamb navarin","steps":["Season the lamb with salt and pepper, then sear it over high heat in the hot oil in a casserole, about 3 min per side.","Add the chopped carrot, turnip and onion and sauté for 5 min over medium heat.","Pour in the wine, bring to the boil and reduce by a third.","Add the garlic, bay leaf, cloves and thyme, cover with stock, season and simmer gently for 30 min.","Add the potatoes, celery and tomato, cut into pieces, along with the peas.","Cover and continue cooking over low heat for 20 to 30 min, until the potatoes are tender.","Sprinkle with chopped parsley and serve."]},"it":{"title":"Navarin di agnello primaverile","steps":["Salare e pepare l''agnello, poi rosolarlo a fuoco vivo nell''olio caldo in una casseruola, circa 3 min per lato.","Aggiungere carota, rapa e cipolla tagliate e rosolarle per 5 min a fuoco medio.","Versare il vino, portare a ebollizione e far ridurre di un terzo.","Aggiungere aglio, alloro, chiodi di garofano e timo, coprire con il brodo, condire e lasciar sobbollire per 30 min.","Aggiungere le patate, il sedano e il pomodoro a pezzi, insieme ai piselli.","Coprire e proseguire la cottura a fuoco basso da 20 a 30 min, finché le patate sono tenere.","Cospargere di prezzemolo tritato e servire."]}}'::jsonb),
  ('f2fd383a-9f87-4d59-8b6f-1bcb8af6b4ba'::uuid, '{"en":{"title":"Cod en papillote with cheese and peppers","steps":["Preheat the oven to 180 °C.","Wash, deseed and peel the peppers, then cut them into thin strips.","Finely chop the tarragon and cut the cheese into 3 mm slices.","Soften the pepper strips in a hot frying pan with a little olive oil, add the tarragon at the end of cooking, season and set aside.","Remove the skin from the cod and cover each fillet with slices of cheese.","On sheets of baking paper, lay the peppers then a fish fillet, drizzle with oil, season and seal the parcels tightly.","Bake for 10 minutes, then serve the parcels and open them at the table."]},"it":{"title":"Merluzzo al cartoccio con formaggio e peperoni","steps":["Preriscaldare il forno a 180 °C.","Lavare, privare dei semi e pelare i peperoni, poi tagliarli a listarelle sottili.","Tritare finemente il dragoncello e tagliare il formaggio a fette di 3 mm.","Far appassire le listarelle di peperone in una padella calda con un po'' d''olio d''oliva, aggiungere il dragoncello a fine cottura, condire e tenere da parte.","Togliere la pelle al merluzzo e coprire ogni filetto con fette di formaggio.","Su fogli di carta forno, disporre i peperoni e poi un filetto di pesce, irrorare con un filo d''olio, condire e chiudere ermeticamente i cartocci.","Cuocere in forno per 10 minuti, poi servire i cartocci aprendoli a tavola."]}}'::jsonb),
  ('6fd24020-984a-437d-8c7e-66f378f054a4'::uuid, '{"en":{"title":"Cod en papillote with ginger and lime","steps":["Make the marinade: mix the chopped garlic, the lime zest and juice, the grated ginger, honey, olive oil and soy sauce.","Coat the cod fillets in the marinade, cover and refrigerate for 1 hour.","Preheat the oven to 210 °C. Cut the carrots into sticks and slice the courgette and mangetout.","Par-cook the carrots in boiling water for 10 minutes, then the mangetout and courgette for 2 minutes; drain.","Divide the vegetables among large sheets of baking paper, place the cod on top, drizzle with the remaining marinade and sprinkle with chopped coriander.","Seal the parcels and bake for 20 minutes."]},"it":{"title":"Merluzzo al cartoccio con zenzero e lime","steps":["Preparare la marinata: mescolare l''aglio tritato, la scorza e il succo del lime, lo zenzero grattugiato, il miele, l''olio d''oliva e la salsa di soia.","Ricoprire i tranci di merluzzo con la marinata, coprire e lasciar riposare 1 ora in frigorifero.","Preriscaldare il forno a 210 °C. Tagliare le carote a bastoncini e affettare la zucchina e le taccole.","Precuocere le carote per 10 minuti in acqua bollente, poi le taccole e la zucchina per 2 minuti; scolare.","Distribuire le verdure su grandi fogli di carta forno, adagiarvi sopra il merluzzo, irrorare con la marinata rimasta e cospargere di coriandolo tritato.","Chiudere i cartocci e cuocere in forno per 20 minuti."]}}'::jsonb),
  ('7e1759e4-48d3-4b1a-9b65-d3c31e93172d'::uuid, '{"en":{"title":"Salmon fillets on a bed of lentils","steps":["Stud the onion with the cloves, then put it in a saucepan of water with the lentils, bay leaf, 1 tbsp of oil, salt and pepper.","Simmer for about 25 minutes until the lentils are tender, then drain and remove the onion and bay leaf.","In a frying pan, sweat the shallots in the remaining oil.","Pour in the white wine, add the lemon zest and reduce by half.","Add the lentils, heat through for 2 minutes, stir in the basil, adjust the seasoning and keep warm.","Turn on the oven grill. Place the salmon in a dish, brush it with honey and sprinkle with breadcrumbs.","Place under the grill, on the top shelf, for 5 to 7 minutes depending on thickness.","Cut the salmon into portions and serve them on the lentils."]},"it":{"title":"Tranci di salmone su letto di lenticchie","steps":["Steccare la cipolla con i chiodi di garofano, poi metterla in una pentola d''acqua con le lenticchie, l''alloro, 1 cucchiaio d''olio, sale e pepe.","Lasciar sobbollire per circa 25 minuti finché le lenticchie sono tenere, poi scolarle ed eliminare la cipolla e l''alloro.","In una padella, far appassire gli scalogni nell''olio rimasto.","Versare il vino bianco, aggiungere la scorza di limone e far ridurre della metà.","Aggiungere le lenticchie, scaldare per 2 minuti, incorporare il basilico, regolare di sale e pepe e tenere in caldo.","Accendere il grill del forno. Mettere il salmone in una pirofila, spennellarlo di miele e cospargerlo di pangrattato.","Passare sotto il grill, sul ripiano più alto, da 5 a 7 minuti a seconda dello spessore.","Tagliare il salmone a tranci e servirli sulle lenticchie."]}}'::jsonb),
  ('0987bb18-6284-465e-9872-55a3a4917212'::uuid, '{"en":{"title":"Petit salé (salt pork with lentils)","steps":["Rinse the lentils in cold water and drain them.","In a casserole dish, sauté the diced onion in the olive oil.","Add the diced carrots and the garlic, then the lentils, and stir for about 1 minute.","Lay the salt pork and the sausage on top, pour in the stock, then add the bay leaf, thyme and some pepper.","Cover and simmer for 45 minutes to 1 hour, until the lentils are tender and the meat is cooked; add a little hot water if needed.","Remove the bay leaf and thyme, slice the sausage and sprinkle with parsley.","Serve piping hot with the wholegrain mustard."]},"it":{"title":"Petit salé con lenticchie","steps":["Sciacquare le lenticchie in acqua fredda e scolarle.","In una casseruola, soffriggere la cipolla a dadini nell''olio d''oliva.","Aggiungere le carote a dadini e l''aglio, poi le lenticchie, e mescolare per circa 1 minuto.","Adagiare il petit salé e la salsiccia, versare il brodo, poi aggiungere l''alloro, il timo e il pepe.","Coprire e cuocere a fuoco lento da 45 minuti a 1 ora, finché le lenticchie sono tenere e la carne è cotta; aggiungere un po'' d''acqua calda se necessario.","Togliere l''alloro e il timo, affettare la salsiccia e cospargere di prezzemolo.","Servire ben caldo con la senape in grani."]}}'::jsonb),
  ('e28bf347-b869-4708-97e6-b7edec18d66e'::uuid, '{"en":{"title":"White wine and tarragon chicken with carrots","steps":["Preheat the oven to 190 °C (170 °C fan).","Arrange the chicken breasts in a baking dish and season them with salt.","Brown the sliced shallots in the oil, then spread them over the chicken.","Mix most of the stock with the wine and the fromage frais, add the chopped tarragon and season with pepper.","Pour over the chicken, cover and bake for 30 to 35 min until cooked through.","Meanwhile, sauté the carrots in the melted butter, add the rest of the stock and cook for about 15 min.","Add the parsley to the carrots, season and serve with the chicken, garnished with tarragon."]},"it":{"title":"Pollo al vino bianco e dragoncello con carote","steps":["Preriscaldare il forno a 190 °C (170 °C ventilato).","Disporre i petti di pollo in una pirofila e salarli.","Far dorare gli scalogni affettati nell''olio, poi distribuirli sul pollo.","Mescolare la maggior parte del brodo con il vino e il formaggio fresco, aggiungere il dragoncello tritato e pepare.","Versare sul pollo, coprire e infornare per 30-35 min, fino a cottura completa.","Nel frattempo, rosolare le carote nel burro fuso, bagnare con il resto del brodo e cuocere per circa 15 min.","Aggiungere il prezzemolo alle carote, aggiustare di sale e pepe e servire con il pollo, guarnendo con il dragoncello."]}}'::jsonb),
  ('c342d26f-6184-4e3a-898e-bf58347b4ac2'::uuid, '{"en":{"title":"Braised chicken with olives","steps":["Season the chicken pieces with salt and pepper, then brown them for about 10 min in a casserole dish with a drizzle of olive oil.","Remove the chicken and soften the sliced onion and garlic in the casserole dish.","Return the chicken, pour in the white wine and a small glass of water, then add the drained olives.","Season with the herbes de Provence, salt and pepper, cover and simmer for 40 min over low heat.","Taste, adjust the seasoning, cook a few minutes longer if needed and serve."]},"it":{"title":"Pollo in umido alle olive","steps":["Salare e pepare i pezzi di pollo, poi rosolarli per circa 10 min in una casseruola con un filo d''olio d''oliva.","Togliere il pollo e far appassire la cipolla e l''aglio affettati nella casseruola.","Rimettere il pollo, bagnare con il vino bianco e un bicchierino d''acqua, poi aggiungere le olive sgocciolate.","Insaporire con le erbe di Provenza, sale e pepe, coprire e cuocere a fuoco lento per 40 min.","Assaggiare, regolare di sale e pepe, prolungare la cottura di qualche minuto se necessario e servire."]}}'::jsonb),
  ('a317f775-694d-4e3d-80c1-cdd2f0e6368a'::uuid, '{"en":{"title":"Tarragon chicken","steps":["Finely chop the garlic and shallots and cut each chicken leg in half.","Heat the oil in a sauté pan, melt the butter in it and brown the chicken on all sides over medium heat.","Add the garlic, shallots and tarragon, then deglaze with the white wine.","Season with salt and pepper, cover and simmer for about 20 min, stirring from time to time.","Remove the chicken, stir the crème fraîche into the sauce and heat gently until it just starts to simmer.","Return the chicken to the tarragon sauce and serve."]},"it":{"title":"Pollo al dragoncello","steps":["Tritare finemente l''aglio e gli scalogni e tagliare ogni coscia a metà.","Scaldare l''olio in una padella dai bordi alti, farvi sciogliere il burro e rosolare il pollo a fuoco medio su tutti i lati.","Aggiungere aglio, scalogni e dragoncello, poi sfumare con il vino bianco.","Salare, pepare, coprire e cuocere a fuoco lento per circa 20 min, mescolando di tanto in tanto.","Togliere il pollo, incorporare la panna alla salsa e scaldare dolcemente fino al primo bollore.","Rimettere il pollo nella salsa al dragoncello e servire."]}}'::jsonb),
  ('c0a07491-dc99-4dc0-8895-b6358173175c'::uuid, '{"en":{"title":"Pork roast with milk and mustard","steps":["Preheat the oven to 150 °C.","Peel the garlic and remove the green germ, then put it in a saucepan with the milk, bay leaf, mustard and stock; season with salt and pepper and stir.","Bring to the boil, then simmer very gently for about 15 min.","Sear the roast over high heat on all sides in the oil, in an ovenproof casserole dish, then discard the fat.","Pour the infused milk over the meat, cover and bake for 1 hr 30 min.","Slice the roast and serve it with the sauce spooned over."]},"it":{"title":"Arrosto di maiale al latte e senape","steps":["Preriscaldare il forno a 150 °C.","Sbucciare l''aglio ed eliminare l''anima, poi metterlo in una casseruola con il latte, l''alloro, la senape e il brodo; salare, pepare e mescolare.","Portare a ebollizione, poi lasciar sobbollire molto dolcemente per circa 15 min.","Rosolare l''arrosto a fuoco vivace su tutti i lati nell''olio, in una casseruola adatta al forno, poi eliminare il grasso.","Versare il latte aromatizzato sulla carne, coprire e infornare per 1 ora e 30 min.","Affettare l''arrosto e servirlo irrorato con la salsa."]}}'::jsonb),
  ('8e07faeb-77dd-4637-ac75-c74706aeb411'::uuid, '{"en":{"title":"Roast salmon with green lentils","steps":["Peel the carrots and dice them; peel the garlic and onion, then stud the onion with the clove.","Tie the bouquet garni herbs together with string.","Put the rinsed lentils in a saucepan of cold water with the carrots, onion, garlic, the piece of bacon and the bouquet garni.","Bring to the boil, then simmer for 30 minutes half-covered, adding salt halfway through cooking.","About 10 minutes before the end, put the salmon fillets under the oven grill, skin side towards the heat.","Drain the lentils, removing the onion and the bouquet garni; dice the bacon and brown it in half the oil.","Add the lentils to the bacon, mix and keep warm.","Remove the skin from the salmon, season with salt and pepper, drizzle with the remaining oil and serve on the lentils."]},"it":{"title":"Salmone arrosto con lenticchie verdi","steps":["Pelare le carote e tagliarle a dadini; sbucciare l''aglio e la cipolla, poi steccare la cipolla con il chiodo di garofano.","Legare con lo spago le erbe del bouquet garni.","Mettere le lenticchie sciacquate in una casseruola di acqua fredda con le carote, la cipolla, l''aglio, il pezzo di pancetta e il bouquet garni.","Portare a ebollizione, poi lasciar sobbollire per 30 minuti con il coperchio socchiuso, salando a metà cottura.","Circa 10 minuti prima della fine, passare i tranci di salmone sotto il grill del forno, con la pelle rivolta verso il calore.","Scolare le lenticchie eliminando la cipolla e il bouquet garni; tagliare la pancetta a dadini e farla dorare in metà dell''olio.","Aggiungere le lenticchie alla pancetta, mescolare e tenere in caldo.","Togliere la pelle al salmone, salare, pepare, irrorare con l''olio rimasto e servire sulle lenticchie."]}}'::jsonb),
  ('419c8ae2-41ee-4db8-afd8-c6f6ff0e11be'::uuid, '{"en":{"title":"Troisgros brothers'' salmon with sorrel","steps":["Remove the pin bones from the salmon with tweezers, then cut it into thin escalopes of about 140 g.","Lightly flatten the escalopes between two sheets of oiled baking paper to get an even thickness.","Strip the sorrel, removing the stems and ribs, rinse it and tear the large leaves.","In a sauté pan, combine the finely chopped shallot, the fish stock, the wine and the vermouth, then reduce until syrupy.","Add the cream and simmer until the sauce lightly coats a spoon.","Plunge the sorrel in for 10 seconds, swirling the pan without whisking, then season with a few drops of lemon and some salt.","Sear the salted escalopes in a very hot non-stick frying pan, about 10 seconds per side, leaving them barely cooked.","Spoon the sauce onto warm plates, lay the salmon on top and serve immediately."]},"it":{"title":"Salmone all''acetosa dei fratelli Troisgros","steps":["Eliminare le spine del salmone con una pinzetta, poi tagliarlo in sottili scaloppe di circa 140 g.","Appiattire leggermente le scaloppe tra due fogli di carta forno unti d''olio per ottenere uno spessore uniforme.","Sfogliare l''acetosa eliminando gambi e nervature, sciacquarla e spezzettare le foglie grandi.","In una padella dai bordi alti, riunire lo scalogno tritato finemente, il fumetto, il vino e il vermouth, poi far ridurre fino a ottenere un liquido sciropposo.","Aggiungere la panna e lasciar sobbollire finché la salsa vela leggermente il cucchiaio.","Immergere l''acetosa per 10 secondi muovendo la padella senza sbattere, poi condire con qualche goccia di limone e il sale.","Scottare le scaloppe salate in una padella antiaderente molto calda, circa 10 secondi per lato, lasciandole appena cotte.","Velare di salsa dei piatti caldi, adagiarvi sopra il salmone e servire subito."]}}'::jsonb),
  ('df8c039d-295f-4d5a-b25a-7f45780c4209'::uuid, '{"en":{"title":"Turbot with sauce vierge","steps":["Preheat the oven to 175 °C (350 °F).","Season the fish with salt and pepper and place it in a dish or on a baking tray lined with baking paper.","Bake for 10 to 15 minutes depending on the thickness of the fillets.","Meanwhile, mix the diced tomato, olive oil, capers, vinegar and herbs, then season with salt and pepper; add a little sugar if the tomatoes lack flavour.","Take the fish out and serve it straight away topped with the sauce vierge, with rice or mash and a vegetable."]},"it":{"title":"Rombo con salsa vierge","steps":["Preriscaldare il forno a 175 °C (350 °F).","Salare e pepare il pesce e disporlo in una pirofila o su una teglia rivestita di carta forno.","Infornare per 10-15 minuti a seconda dello spessore dei filetti.","Nel frattempo, mescolare i dadini di pomodoro, l''olio d''oliva, i capperi, l''aceto e le erbe, poi salare e pepare; aggiungere un po'' di zucchero se i pomodori sono poco saporiti.","Sfornare il pesce e servirlo subito coperto di salsa vierge, con riso o purè e una verdura."]}}'::jsonb),
  ('caa6c099-644e-4533-b07e-55ea51423d4c'::uuid, '{"en":{"title":"Poached eggs with spinach and lentils","steps":["In a large frying pan, sauté the onion, garlic and ginger in the oil for about 3 minutes.","Add the garam masala and turmeric and stir for 30 seconds.","Add the grated tomato, the lentils and half the spinach, cover and cook for about 5 minutes until the spinach wilts.","Uncover, add the rest of the spinach, let it wilt, then season with salt and pepper.","Make hollows in the mixture and crack the eggs into them.","Cover and simmer for 5 to 6 minutes, until the whites are set.","Sprinkle with feta, add a dash of sriracha and serve."]},"it":{"title":"Uova in camicia con spinaci e lenticchie","steps":["In una padella grande, soffriggere la cipolla, l''aglio e lo zenzero nell''olio per circa 3 minuti.","Aggiungere il garam masala e la curcuma e mescolare per 30 secondi.","Aggiungere il pomodoro grattugiato, le lenticchie e metà degli spinaci, coprire e cuocere per circa 5 minuti, finché gli spinaci appassiscono.","Togliere il coperchio, aggiungere il resto degli spinaci, lasciarli appassire, poi salare e pepare.","Formare delle conche nel composto e rompervi dentro le uova.","Coprire e cuocere a fuoco lento per 5-6 minuti, finché gli albumi sono rappresi.","Cospargere di feta, aggiungere un goccio di sriracha e servire."]}}'::jsonb),
  ('5a5c66cd-2943-431e-8885-d31eebc8d30e'::uuid, '{"fr":{"title":"Bols de riz au bœuf bulgogi","steps":["Émincer le bœuf très finement et le mettre dans un saladier.","Mixer la poire, l''oignon, l''ail de la marinade, le gingembre, la sauce soja, le sucre roux, le poivre et l''huile de sésame jusqu''à obtenir une purée lisse.","Verser la purée sur le bœuf, ajouter la moitié de l''oignon nouveau et la carotte, mélanger et réfrigérer au moins 1 heure (idéalement toute une nuit).","Cuire le riz.","Faire chauffer une poêle en fonte à feu vif et saisir le bœuf en plusieurs fois avec un peu d''huile, 1 à 2 minutes jusqu''à ce qu''il caramélise, en le retournant une fois ; gratter la poêle pour la nettoyer entre chaque fournée.","Répartir le riz dans des bols et garnir de bœuf, de kimchi, d''ail cru émincé, de piments shishito et du reste d''oignon nouveau.","Parsemer de graines de sésame et servir avec le ssamjang à part."]},"it":{"title":"Ciotole di riso con manzo bulgogi","steps":["Affettare il manzo molto sottile e metterlo in una ciotola.","Frullare la pera, la cipolla, l''aglio per la marinata, lo zenzero, la salsa di soia, lo zucchero di canna, il pepe e l''olio di sesamo fino a ottenere una purea liscia.","Versare la purea sul manzo, aggiungere metà del cipollotto e la carota, mescolare e mettere in frigorifero per almeno 1 ora (meglio tutta la notte).","Cuocere il riso.","Scaldare una padella di ghisa a fuoco vivace e scottare il manzo poco alla volta con un filo d''olio, 1–2 minuti finché è caramellato, girandolo una volta; raschiare e pulire la padella tra una porzione e l''altra.","Riempire le ciotole con il riso e completare con il manzo, il kimchi, l''aglio crudo affettato, i peperoni shishito e il cipollotto rimasto.","Finire con i semi di sesamo e servire con il ssamjang a parte."]}}'::jsonb),
  ('39fd3a34-7eb2-497f-8ff1-3d247f845ea0'::uuid, '{"fr":{"title":"Rendang de bœuf","steps":["Mixer au robot les piments, l''oignon, l''ail, la citronnelle émincée, le galanga, le gingembre et l''huile de la pâte jusqu''à obtenir une pâte très fine.","Faire chauffer l''huile de saisie dans une cocotte à fond épais à feu vif et saisir le bœuf en plusieurs fois ; réserver.","Baisser à feu moyen-doux et faire revenir la pâte d''épices 2 à 3 minutes jusqu''à ce qu''elle fonce.","Remettre le bœuf avec tous les autres ingrédients du curry, porter à frémissement puis baisser le feu pour obtenir un très léger bouillonnement.","Couvrir et cuire 1 heure 15 minutes, puis vérifier le bœuf.","Découvrir, monter à feu moyen et cuire 30 à 40 minutes en remuant souvent, jusqu''à ce que l''huile se sépare et que la sauce réduise en une pâte sombre qui enrobe le bœuf (ajouter un peu d''eau et poursuivre si la viande n''est pas encore tendre).","Servir avec du riz vapeur."]},"it":{"title":"Rendang di manzo","steps":["Frullare nel mixer i peperoncini, la cipolla, l''aglio, la citronella affettata, il galanga, lo zenzero e l''olio per la pasta fino a ottenere un composto finissimo.","Scaldare l''olio per rosolare in una pentola dal fondo spesso a fuoco vivace e rosolare il manzo poco alla volta; tenere da parte.","Abbassare a fuoco medio-basso e soffriggere la pasta di spezie per 2–3 minuti, finché si scurisce.","Rimettere il manzo con tutti gli altri ingredienti del curry, portare a leggero bollore e abbassare la fiamma fino a un bollore leggerissimo.","Coprire e cuocere per 1 ora e 15 minuti, poi controllare il manzo.","Scoprire, alzare a fuoco medio e cuocere per 30–40 minuti mescolando spesso, finché l''olio si separa e la salsa si riduce a una pasta scura che avvolge la carne (aggiungere un goccio d''acqua e continuare se la carne non è ancora tenera).","Servire con riso al vapore."]}}'::jsonb),
  ('48233154-365a-485a-b65e-f5d981d9d5f7'::uuid, '{"fr":{"title":"Bibimbap au bœuf coréen","steps":["Mélanger le gochujang, le mirin, le vinaigre de riz, la sauce soja, le sucre, l''ail râpé et l''huile de sésame jusqu''à dissolution du sucre.","Mélanger la pomme râpée, l''ail, le gingembre, la sauce soja, le miel et l''huile de sésame, ajouter le bœuf et laisser mariner 30 minutes (ou jusqu''au lendemain).","Faire tremper les shiitakés séchés 30 minutes dans de l''eau bouillante, puis les essorer et les émincer ; cuire le riz.","Faire sauter successivement les shiitakés, la carotte, la courgette et les épinards dans un peu d''huile, en assaisonnant légèrement chacun de sel, d''ail, de sauce soja et de sucre.","Blanchir les pousses de soja, les égoutter et les laisser refroidir, puis les assaisonner d''huile de sésame, d''un peu d''ail et de la sauce poisson.","Égoutter le bœuf et le saisir 3 à 4 minutes dans une poêle très chaude avec un peu d''huile ; réserver au chaud.","Cuire les œufs au plat selon les goûts.","Répartir le riz chaud dans des bols, disposer les légumes et le bœuf par-dessus, ajouter l''œuf, parsemer de graines de sésame, arroser d''un filet d''huile de sésame et servir avec la sauce à mélanger."]},"it":{"title":"Bibimbap con manzo alla coreana","steps":["Mescolare il gochujang, il mirin, l''aceto di riso, la salsa di soia, lo zucchero, l''aglio grattugiato e l''olio di sesamo finché lo zucchero si scioglie.","Mescolare la mela grattugiata, l''aglio, lo zenzero, la salsa di soia, il miele e l''olio di sesamo, aggiungere il manzo e lasciar marinare per 30 minuti (o fino al giorno dopo).","Mettere in ammollo gli shiitake secchi in acqua bollente per 30 minuti, poi strizzarli e affettarli; cuocere il riso.","Saltare in padella uno dopo l''altro gli shiitake, la carota, la zucchina e gli spinaci con un filo d''olio, condendo ciascuno leggermente con sale, aglio, salsa di soia e zucchero.","Sbollentare i germogli di soia, scolarli e farli raffreddare, poi condirli con olio di sesamo, un po'' d''aglio e la salsa di pesce.","Scolare il manzo e scottarlo in una padella molto calda con un filo d''olio per 3–4 minuti; tenere in caldo.","Cuocere le uova al tegamino a piacere.","Riempire le ciotole con il riso caldo, disporvi sopra le verdure e il manzo, aggiungere l''uovo, cospargere di semi di sesamo e di un filo d''olio di sesamo e servire con la salsa da mescolare."]}}'::jsonb),
  ('df078eb0-325b-4dde-897e-a5fdefb5ec92'::uuid, '{"fr":{"title":"Poisson vapeur cantonais au gingembre et à l''oignon nouveau","steps":["Tailler les oignons nouveaux et le gingembre en julienne et hacher grossièrement la coriandre ; en réserver environ un tiers pour la garniture.","Mélanger la sauce soja, le sel et le sucre dans 2 c. à soupe d''eau chaude jusqu''à dissolution.","Porter à ébullition 2 à 5 cm d''eau dans un cuit-vapeur (un wok avec une grille et un couvercle fait l''affaire).","Déposer le filet rincé sur une assiette résistant à la chaleur, la placer dans le cuit-vapeur, couvrir et cuire à la vapeur à feu moyen 7 à 10 minutes (4 à 5 pour des filets fins), jusqu''à ce qu''un couteau traverse facilement la partie la plus épaisse.","Jeter le liquide de l''assiette et parsemer le poisson des aromates réservés.","Faire chauffer l''huile dans une petite poêle, faire revenir le reste du gingembre environ 1 minute, ajouter le blanc des oignons nouveaux 30 secondes, puis le vert et la coriandre.","Ajouter le mélange à la sauce soja, laisser bouillonner environ 30 secondes jusqu''à ce que les herbes commencent tout juste à flétrir, puis verser sur le poisson et servir avec du riz vapeur."]},"it":{"title":"Pesce al vapore alla cantonese con zenzero e cipollotto","steps":["Tagliare a julienne i cipollotti e lo zenzero e tritare grossolanamente il coriandolo; tenerne da parte circa un terzo per guarnire.","Sciogliere la salsa di soia, il sale e lo zucchero in 2 cucchiai di acqua calda.","Portare a ebollizione 2–5 cm d''acqua in una vaporiera (va bene anche un wok con griglia e coperchio).","Mettere il filetto sciacquato su un piatto resistente al calore, sistemarlo nella vaporiera, coprire e cuocere a vapore a fuoco medio per 7–10 minuti (4–5 per filetti sottili), finché un coltello affonda facilmente nella parte più spessa.","Eliminare il liquido nel piatto e distribuire sul pesce gli aromi tenuti da parte.","Scaldare l''olio in un padellino, friggere lo zenzero rimasto per circa 1 minuto, aggiungere la parte bianca dei cipollotti per 30 secondi, poi la parte verde e il coriandolo.","Aggiungere il composto di soia, lasciar bollire per circa 30 secondi finché le erbe appassiscono appena, poi versarlo sul pesce e servire con riso al vapore."]}}'::jsonb),
  ('a7ed4529-c101-447e-8900-f9b038ec9bf2'::uuid, '{"fr":{"title":"Larb de poulet en feuilles de laitue","steps":["Faire griller le riz cru dans un wok à sec à feu doux environ 10 minutes jusqu''à ce qu''il soit doré et parfumé, puis le moudre en poudre grossière.","Faire chauffer l''huile dans le wok à feu vif et faire frire la moitié des échalotes jusqu''à ce qu''elles soient croustillantes ; les retirer en gardant l''huile dans le wok.","Faire chauffer de nouveau le wok jusqu''à ce qu''il fume, ajouter le poulet haché et le faire sauter jusqu''à ce qu''il soit doré et légèrement croustillant.","Assaisonner avec le sucre, la sauce poisson et le jus de citron vert.","Incorporer la poudre de riz grillé, le piment, le reste des échalotes crues, l''oignon nouveau, la coriandre et la menthe, et faire sauter environ une minute.","Goûter et équilibrer avec du sel, du piment, de la sauce poisson ou du citron vert selon les besoins.","Répartir à la cuillère dans les feuilles de laitue et parsemer d''échalotes croustillantes."]},"it":{"title":"Larb di pollo in coppette di lattuga","steps":["Tostare il riso crudo in un wok asciutto a fuoco basso per circa 10 minuti, finché è dorato e profumato, poi macinarlo in una polvere grossolana.","Scaldare l''olio nel wok a fuoco vivace e friggere metà degli scalogni finché sono croccanti; toglierli e lasciare l''olio nel wok.","Riscaldare il wok finché fuma, aggiungere il pollo macinato e saltarlo finché è rosolato e leggermente croccante.","Condire con lo zucchero, la salsa di pesce e il succo di lime.","Incorporare la polvere di riso tostato, il peperoncino, gli scalogni crudi rimasti, il cipollotto, il coriandolo e la menta e saltare per circa un minuto.","Assaggiare e bilanciare con sale, peperoncino, salsa di pesce o lime secondo necessità.","Distribuire con un cucchiaio nelle foglie di lattuga e cospargere con gli scalogni croccanti."]}}'::jsonb),
  ('79682a8a-d507-4826-91a4-133add95113d'::uuid, '{"fr":{"title":"Bœuf aux brocolis à la chinoise","steps":["Délayer la fécule de maïs dans un peu d''eau jusqu''à ce qu''elle soit lisse, puis incorporer le sucre, les deux sauces soja, le vin de riz, le cinq-épices, l''huile de sésame et le poivre.","Émincer finement le bœuf et le mélanger avec environ 1,5 c. à soupe de sauce.","Faire chauffer l''huile dans une poêle ou un wok à feu vif, étaler le bœuf et le laisser dorer sans y toucher environ 1 minute.","Remuer le bœuf, ajouter l''ail et le gingembre et faire sauter jusqu''à ce que la viande ne soit plus rosée.","Verser le reste de la sauce et environ 170 ml d''eau, et remuer rapidement.","Dès que ça bouillonne, ajouter les brocolis cuits, bien les enrober de sauce et laisser mijoter environ 1 minute jusqu''à ce que la sauce soit brillante et épaisse.","Retirer du feu et servir sur du riz, parsemé de graines de sésame."]},"it":{"title":"Manzo e broccoli alla cinese","steps":["Stemperare l''amido di mais in poca acqua fino a renderlo liscio, poi unire lo zucchero, le due salse di soia, il vino di riso, le cinque spezie, l''olio di sesamo e il pepe.","Affettare sottilmente il manzo e mescolarlo con circa 1,5 cucchiai di salsa.","Scaldare l''olio in una padella o nel wok a fuoco vivace, distribuire il manzo e lasciarlo rosolare senza toccarlo per circa 1 minuto.","Mescolare il manzo, aggiungere l''aglio e lo zenzero e saltare finché la carne non è più rosa.","Versare il resto della salsa e circa 170 ml d''acqua e mescolare rapidamente.","Quando bolle, aggiungere i broccoli cotti, ricoprirli di salsa e cuocere a fuoco lento per circa 1 minuto, finché la salsa è lucida e densa.","Togliere dal fuoco e servire sul riso, cospargendo di semi di sesamo."]}}'::jsonb),
  ('28d94d63-942b-407b-b0b5-b31c5de37faa'::uuid, '{"fr":{"title":"Poulet aux noix de cajou à la chinoise","steps":["Délayer au fouet la fécule de maïs dans la sauce soja jusqu''à ce qu''elle soit lisse, puis ajouter le vin de riz, la sauce d''huître, l''huile de sésame et le poivre blanc.","Mélanger le poulet avec environ 1 c. à soupe de sauce et laisser reposer au moins 10 minutes.","Faire chauffer l''huile dans un wok à feu vif et faire sauter l''ail et l''oignon environ 1 minute.","Ajouter le poulet et cuire environ 2 minutes, puis ajouter le poivron et cuire encore une minute.","Verser le reste de la sauce avec environ 3 c. à soupe d''eau et remuer environ 1 minute jusqu''à ce qu''elle frémisse et épaississe.","Ajouter les noix de cajou, mélanger, retirer du feu et servir aussitôt avec du riz."]},"it":{"title":"Pollo agli anacardi alla cinese","steps":["Sbattere con una frusta l''amido di mais nella salsa di soia fino a renderlo liscio, poi aggiungere il vino di riso, la salsa di ostriche, l''olio di sesamo e il pepe bianco.","Mescolare il pollo con circa 1 cucchiaio di salsa e lasciar riposare almeno 10 minuti.","Scaldare l''olio nel wok a fuoco vivace e saltare l''aglio e la cipolla per circa 1 minuto.","Aggiungere il pollo e cuocere per circa 2 minuti, poi aggiungere il peperone per un altro minuto.","Versare la salsa rimasta con circa 3 cucchiai d''acqua e mescolare per circa 1 minuto, finché sobbolle e si addensa.","Unire gli anacardi, mescolare, togliere dal fuoco e servire subito con il riso."]}}'::jsonb),
  ('00396751-d223-4187-b0ba-b2793c5f3b91'::uuid, '{"fr":{"title":"Saumon au gingembre et oignon nouveau croustillants","steps":["Faire chauffer une poêle à feu moyen-vif avec la moitié de l''huile et y déposer le saumon côté peau.","Le laisser saisir sans y toucher, 4 à 7 minutes par face selon l''épaisseur, jusqu''à ce que le centre ne soit plus cru ; le retirer.","Mélanger la sauce soja, le sucre, l''huile de sésame et le sel avec environ 60 ml d''eau.","Ajouter le reste de l''huile dans la même poêle et faire frire le gingembre jusqu''à ce qu''il soit croustillant, puis ajouter l''oignon nouveau et le laisser flétrir.","Verser le mélange à la sauce soja, porter à ébullition et éteindre le feu.","Servir le saumon sur du riz, le napper de sauce au gingembre et à l''oignon nouveau et parsemer de coriandre."]},"it":{"title":"Salmone con zenzero e cipollotto croccanti","steps":["Scaldare una padella a fuoco medio-alto con metà dell''olio e adagiarvi il salmone dal lato della pelle.","Lasciarlo rosolare senza toccarlo, 4–7 minuti per lato a seconda dello spessore, finché il centro non è più crudo; toglierlo.","Mescolare la salsa di soia, lo zucchero, l''olio di sesamo e il sale con circa 60 ml d''acqua.","Aggiungere l''olio rimasto nella stessa padella e friggere lo zenzero finché è croccante, poi aggiungere il cipollotto e farlo appassire.","Versare il composto di soia, portare a ebollizione e spegnere il fuoco.","Servire il salmone sul riso, irrorandolo con la salsa allo zenzero e cipollotto e cospargendo di coriandolo."]}}'::jsonb),
  ('2d025e3c-c006-4ef1-873b-677587924532'::uuid, '{"fr":{"title":"Cá kho (maquereau braisé au caramel à la vietnamienne)","steps":["Couper le maquereau en tranches épaisses d''environ 4 cm en jetant les têtes ; frotter de sel, rincer et sécher en tamponnant.","Faire fondre le sucre avec un peu d''eau dans une petite casserole et laisser bouillonner, puis baisser le feu et cuire jusqu''à obtenir un caramel foncé.","Retirer le caramel du feu et y incorporer prudemment environ 140 ml d''eau pour obtenir un liquide de braisage ambré foncé.","Tapisser le fond d''une cocotte à fond épais de galanga, d''échalote et de la majeure partie de la tomate, poser le poisson dessus en une seule couche et répartir le reste des aromates, de la tomate et le piment.","Ajouter la sauce poisson, la sauce soja, le caramel et le poivre noir ; compléter avec un peu d''eau pour que le poisson soit tout juste couvert.","Porter à ébullition, ajouter le jus de citron vert, puis couvrir et laisser mijoter doucement environ 1 heure et demie, en arrosant le poisson de temps en temps (ajouter de l''eau chaude si ça accroche).","Découvrir, goûter et poursuivre le braisage couvercle entrouvert jusqu''à ce qu''il ne reste qu''une fine couche de sauce brillante au fond de la cocotte.","Servir avec du riz vapeur."]},"it":{"title":"Cá kho (sgombro brasato al caramello alla vietnamita)","steps":["Tagliare lo sgombro in tranci spessi circa 4 cm, eliminando le teste; strofinarli con il sale, sciacquarli e tamponarli.","Sciogliere lo zucchero con un goccio d''acqua in un pentolino e lasciarlo bollire, poi abbassare la fiamma e cuocere finché diventa un caramello scuro.","Togliere il caramello dal fuoco e incorporare con cautela circa 140 ml d''acqua per ottenere un liquido di cottura ambrato scuro.","Foderare il fondo di una pentola dal fondo spesso con galanga, scalogno e gran parte del pomodoro, adagiarvi sopra il pesce in un solo strato e distribuire il resto degli aromi, del pomodoro e il peperoncino.","Aggiungere la salsa di pesce, la salsa di soia, il caramello e il pepe nero; aggiungere un po'' d''acqua in modo che il pesce sia appena coperto.","Portare a ebollizione, aggiungere il succo di lime, poi coprire e cuocere a fuoco lento per circa 1 ora e mezza, bagnando il pesce di tanto in tanto (aggiungere acqua calda se si asciuga).","Scoprire, assaggiare e continuare la cottura con il coperchio socchiuso finché resta solo un velo di salsa lucida sul fondo della pentola.","Servire con riso al vapore."]}}'::jsonb),
  ('cb707aa6-b026-4732-a344-0eb8ba339d56'::uuid, '{"fr":{"title":"Dak galbi (poulet sauté épicé)","steps":["Si les gâteaux de riz sont achetés emballés, les séparer et les faire tremper 10 minutes dans de l''eau tiède.","Mélanger le gochujang, le vin de riz, le gochugaru, la sauce soja, le sucre, l''ail, le gingembre, le curry en poudre, l''oignon râpé et un peu de poivre.","Enrober le poulet de marinade et laisser reposer au moins 30 minutes (jusqu''au lendemain pour plus de saveur).","Faire chauffer l''huile dans une grande poêle à feu moyen-vif et étaler la patate douce, la carotte, le chou, les feuilles de périlla et les gâteaux de riz, avec le poulet par-dessus.","Cuire 3 à 4 minutes, puis baisser à feu moyen/moyen-doux et poursuivre la cuisson 10 à 15 minutes en remuant souvent, jusqu''à ce que le poulet et la patate douce soient bien cuits (un couvercle accélère la cuisson).","Servir chaud avec du riz."]},"it":{"title":"Dak galbi (pollo saltato piccante)","steps":["Se gli gnocchi di riso sono confezionati, separarli e metterli in ammollo in acqua tiepida per 10 minuti.","Mescolare il gochujang, il vino di riso, il gochugaru, la salsa di soia, lo zucchero, l''aglio, lo zenzero, il curry in polvere, la cipolla grattugiata e un po'' di pepe.","Ricoprire il pollo con la marinata e lasciar riposare almeno 30 minuti (fino al giorno dopo per più sapore).","Scaldare l''olio in una padella grande a fuoco medio-alto e distribuire la patata dolce, la carota, il cavolo, le foglie di perilla e gli gnocchi di riso, con il pollo sopra.","Cuocere per 3–4 minuti, poi abbassare a fuoco medio/medio-basso e continuare la cottura per 10–15 minuti mescolando spesso, finché il pollo e la patata dolce sono ben cotti (con un coperchio si fa prima).","Servire caldo con il riso."]}}'::jsonb),
  ('7604daa9-9518-4943-8ab8-875c445fe5b9'::uuid, '{"fr":{"title":"Adobo de poulet philippin","steps":["Écraser l''ail au mortier, puis le mélanger avec le poulet et la sauce soja et laisser mariner au moins 1 heure.","Retirer le poulet en réservant séparément la marinade et l''ail.","Faire chauffer la majeure partie de l''huile dans une cocotte et saisir le poulet environ 2 minutes par face ; réserver.","Ajouter le reste de l''huile et l''ail mariné et le faire revenir jusqu''à ce qu''il commence tout juste à colorer.","Remettre le poulet avec le reste de la marinade, les grains de poivre, les feuilles de laurier et environ 180 ml d''eau ; porter à ébullition, couvrir et laisser mijoter environ 30 minutes jusqu''à ce qu''il soit tendre.","Verser le vinaigre et laisser bouillir 1 minute sans remuer, puis remuer et laisser mijoter 15 minutes à découvert pour réduire.","Assaisonner avec le sucre et le sel et servir chaud avec du riz."]},"it":{"title":"Adobo di pollo alla filippina","steps":["Schiacciare l''aglio nel mortaio, poi unirlo al pollo e alla salsa di soia e lasciar marinare per almeno 1 ora.","Togliere il pollo, tenendo da parte separatamente la marinata e l''aglio.","Scaldare la maggior parte dell''olio in una pentola e rosolare il pollo per circa 2 minuti per lato; tenere da parte.","Aggiungere il resto dell''olio e l''aglio marinato e soffriggere finché inizia appena a colorirsi.","Rimettere il pollo con la marinata rimasta, i grani di pepe, le foglie di alloro e circa 180 ml d''acqua; portare a ebollizione, coprire e cuocere a fuoco lento per circa 30 minuti, finché è tenero.","Versare l''aceto e lasciar bollire per 1 minuto senza mescolare, poi mescolare e cuocere a fuoco lento senza coperchio per 15 minuti per far ridurre.","Insaporire con zucchero e sale e servire caldo con il riso."]}}'::jsonb),
  ('f6b65e75-59a5-479d-908f-dcb0781077a6'::uuid, '{"fr":{"title":"Curry de poisson façon Goa","steps":["Mixer la majeure partie de la coriandre avec le gingembre, le piment, l''ail, l''oignon nouveau haché, la moitié du jus de citron, le curry en poudre prévu pour la pâte, une pincée de sel et la moitié du lait de coco jusqu''à obtenir une pâte lisse.","Faire cuire la pâte quelques minutes dans une sauteuse profonde jusqu''à ce qu''elle embaume, puis ajouter le reste du lait de coco et laisser mijoter jusqu''à ce que la sauce épaississe légèrement.","Rincer le riz et le faire cuire à frémissement, à couvert, dans de l''eau jusqu''à ce qu''il soit tendre et que le liquide soit absorbé ; garder à couvert.","Couper le poisson en lanières et l''enrober de farine assaisonnée de sel et du reste de curry en poudre.","Faire frire le poisson à la poêle dans l''huile jusqu''à ce qu''il soit doré et tout juste cuit à cœur.","Rectifier l''assaisonnement de la sauce, ajouter le jus de citron selon le goût, y glisser le poisson pour le réchauffer et servir avec le riz, l''oignon nouveau émincé finement et le reste de la coriandre."]},"it":{"title":"Curry di pesce in stile Goa","steps":["Frullare gran parte del coriandolo con lo zenzero, il peperoncino, l''aglio, il cipollotto tritato, metà del succo di limone, il curry in polvere per la pasta, un pizzico di sale e metà del latte di cocco fino a ottenere un composto liscio.","Cuocere la pasta in una padella profonda per qualche minuto finché non sprigiona il suo aroma, poi aggiungere il resto del latte di cocco e cuocere a fuoco lento finché non si addensa leggermente.","Sciacquare il riso e cuocerlo a fuoco lento, coperto, in acqua finché non è tenero e ha assorbito il liquido; tenere coperto.","Tagliare il pesce a listarelle e passarlo nella farina condita con sale e il curry in polvere rimasto.","Friggere il pesce in padella nell''olio finché non è dorato e appena cotto all''interno.","Regolare di sapore la salsa, aggiungere il succo di limone a piacere, unire il pesce per scaldarlo e servire con il riso, il cipollotto a julienne e il coriandolo rimasto."]}}'::jsonb),
  ('25a49043-ae42-4755-8b99-fe6b204a5964'::uuid, '{"fr":{"title":"Gyudon (bol de riz au bœuf et aux oignons)","steps":["Faire cuire le riz.","Faire chauffer la moitié de l''huile dans une poêle à feu moyen-vif et faire cuire les oignons environ 10 minutes en remuant souvent, jusqu''à ce qu''ils soient tendres.","Ajouter le bœuf et le sucre et remuer jusqu''à ce que le bœuf soit légèrement doré.","Verser le mirin, la sauce soja et le dashi et laisser mijoter 10–15 minutes jusqu''à obtenir une sauce légère ; goûter et rectifier.","Pendant ce temps, faire cuire les œufs au plat dans une autre poêle avec le reste de l''huile, en gardant les jaunes coulants.","Répartir le riz dans des bols, y disposer le bœuf et les oignons avec un peu de sauce, déposer un œuf sur chaque bol et parsemer d''oignon nouveau et de graines de sésame."]},"it":{"title":"Gyudon (ciotola di riso con manzo e cipolle)","steps":["Cuocere il riso.","Scaldare metà dell''olio in una padella a fuoco medio-alto e cuocere le cipolle per circa 10 minuti, mescolando spesso, finché non sono morbide.","Aggiungere il manzo e lo zucchero e mescolare finché la carne non è leggermente rosolata.","Versare il mirin, la salsa di soia e il dashi e cuocere a fuoco lento per 10–15 minuti finché non si riduce a una salsa leggera; assaggiare e regolare.","Nel frattempo cuocere le uova all''occhio di bue in un''altra padella con l''olio rimasto, lasciando i tuorli morbidi.","Distribuire il riso nelle ciotole, adagiarvi sopra il manzo e le cipolle con un po'' di salsa, completare ciascuna con un uovo e finire con cipollotto e semi di sesamo."]}}'::jsonb),
  ('63ace58e-5c2b-45c1-9b70-599b42c3908e'::uuid, '{"fr":{"title":"Gà nướng sả (poulet grillé vietnamien à la citronnelle)","steps":["Fouetter ensemble tous les ingrédients de la marinade dans un bol.","Bien enrober le poulet et le laisser au réfrigérateur au moins 3 heures, idéalement toute une nuit.","Faire chauffer le barbecue (ou une poêle-gril) à environ 200 °C.","Faire griller le poulet en le retournant de temps en temps, jusqu''à ce qu''il soit bien grillé des deux côtés et atteigne 74 °C dans la partie la plus épaisse.","Laisser reposer 5 minutes, puis trancher.","Servir chaud avec du riz ou des vermicelles de riz."]},"it":{"title":"Gà nướng sả (pollo vietnamita alla griglia con citronella)","steps":["Sbattere insieme in una ciotola tutti gli ingredienti della marinata.","Ricoprire bene il pollo e metterlo in frigorifero per almeno 3 ore, meglio ancora per tutta la notte.","Scaldare la griglia (o una bistecchiera) a circa 200 °C.","Grigliare il pollo, girandolo di tanto in tanto, finché non è abbrustolito su entrambi i lati e raggiunge 74 °C nella parte più spessa.","Lasciare riposare per 5 minuti, poi affettare.","Servire caldo con riso o vermicelli di riso."]}}'::jsonb),
  ('60542698-8098-4b4a-9ff6-37e012332afc'::uuid, '{"fr":{"title":"Poulet tikka masala léger aux épinards","steps":["Mixer l''oignon, l''ail et le gingembre jusqu''à obtenir une pâte lisse.","Faire revenir la pâte dans la moitié de l''huile à feu moyen pendant environ 15 minutes jusqu''à ce qu''elle soit dorée et sucrée ; la retirer en raclant la poêle, puis essuyer celle-ci.","Faire dorer le poulet dans le reste de l''huile, puis incorporer les épices tikka et le piment de Cayenne.","Remettre la pâte d''oignon avec les tomates et environ 200 ml d''eau et laisser mijoter 15 minutes à découvert.","Incorporer la poudre d''amandes et les épinards et poursuivre la cuisson 10 minutes.","Saler, retirer du feu, incorporer le yaourt et la coriandre et servir avec du riz basmati complet."]},"it":{"title":"Pollo tikka masala leggero con spinaci","steps":["Frullare la cipolla, l''aglio e lo zenzero fino a ottenere una pasta liscia.","Soffriggere la pasta in metà dell''olio a fuoco medio per circa 15 minuti finché non è dorata e dolce; raccoglierla raschiando la padella e pulire la padella.","Rosolare il pollo nell''olio rimasto, poi unire le spezie tikka e il pepe di Caienna.","Rimettere la pasta di cipolla con i pomodori e circa 200 ml d''acqua e cuocere a fuoco lento senza coperchio per 15 minuti.","Unire le mandorle tritate e gli spinaci e cuocere per altri 10 minuti.","Regolare di sale, togliere dal fuoco, incorporare lo yogurt e il coriandolo e servire con riso basmati integrale."]}}'::jsonb),
  ('072df74c-2984-46e1-b4fc-241bd3c22c69'::uuid, '{"fr":{"title":"Poulet kung pao","steps":["Faire griller les cacahuètes dans le peu d''huile prévu à feu moyen, en remuant sans arrêt pendant environ 3 minutes ; retirer du feu, continuer à remuer encore une minute, puis les laisser refroidir pour qu''elles deviennent croustillantes.","Mélanger les dés de poulet avec l''huile, la fécule de maïs, le vin de riz, le sel et le poivre blanc de la marinade et laisser reposer 20 minutes.","Mélanger les deux sauces soja, le vinaigre, le sucre, la fécule de maïs et environ 1,5 c. à soupe d''eau dans un petit bol.","Faire chauffer un wok à feu très vif, ajouter les deux tiers de l''huile de friture et saisir le poulet jusqu''à ce qu''il soit doré et tout juste cuit ; le retirer.","Baisser le feu, ajouter le reste de l''huile et faire revenir l''ail, le gingembre, les piments, le poivre du Sichuan et l''oignon nouveau jusqu''à ce qu''ils embaument.","Remettre le poulet, monter à feu vif et faire sauter 1 minute.","Remuer de nouveau la sauce, la verser et faire sauter environ 1 minute jusqu''à ce qu''elle épaississe et nappe le poulet.","Incorporer les cacahuètes et servir aussitôt avec du riz."]},"it":{"title":"Pollo kung pao","steps":["Tostare le arachidi nel poco olio a fuoco medio, mescolando di continuo per circa 3 minuti; togliere dal fuoco, continuare a mescolare per un altro minuto, poi lasciarle raffreddare in modo che diventino croccanti.","Mescolare i cubetti di pollo con l''olio, l''amido di mais, il vino di riso, il sale e il pepe bianco della marinata e lasciare riposare per 20 minuti.","Mescolare in una ciotolina le due salse di soia, l''aceto, lo zucchero, l''amido di mais e circa 1,5 cucchiai d''acqua.","Scaldare bene il wok, aggiungere due terzi dell''olio per friggere e scottare il pollo finché non è dorato e appena cotto; toglierlo dal wok.","Abbassare la fiamma, aggiungere l''olio rimasto e soffriggere l''aglio, lo zenzero, i peperoncini, il pepe di Sichuan e il cipollotto finché non sprigionano il loro aroma.","Rimettere il pollo, alzare la fiamma al massimo e saltare per 1 minuto.","Mescolare di nuovo la salsa, versarla e saltare per circa 1 minuto finché non si addensa e avvolge il pollo.","Incorporare le arachidi e servire subito con il riso."]}}'::jsonb),
  ('61be8075-e45c-435e-8e16-5746e7dbddf4'::uuid, '{"fr":{"title":"Nasi goreng malaisien au poulet, crevettes et œuf","steps":["Faire sauter la pâte de nasi goreng avec le poulet et l''oignon à feu moyen pendant environ 6 minutes.","Ajouter les crevettes et les haricots verts et poursuivre la cuisson 5 minutes.","Ajouter le riz cuit et mélanger jusqu''à ce que chaque grain soit enrobé et bien chaud.","Répartir dans deux bols.","Faire cuire les œufs au plat et en déposer un sur chaque bol ; servir avec la laitue, le concombre et la tomate à côté."]},"it":{"title":"Nasi goreng malese con pollo, gamberi e uovo","steps":["Saltare la pasta per nasi goreng con il pollo e la cipolla a fuoco medio per circa 6 minuti.","Aggiungere i gamberi e i fagiolini e cuocere per altri 5 minuti.","Versare il riso cotto e mescolare finché ogni chicco non è ben condito e bollente.","Dividere in due ciotole.","Friggere le uova e adagiarne una su ciascuna ciotola; servire con lattuga, cetriolo e pomodoro a parte."]}}'::jsonb),
  ('ef7a2f1d-b2e6-44f8-b3e8-4198959fa625'::uuid, '{"fr":{"title":"Saumon au miso, riz et légumes verts","steps":["Faire cuire le riz dans de l''eau bouillante salée jusqu''à ce qu''il soit tendre, puis l''égoutter.","Fouetter le miso, le vinaigre de riz, le gingembre et l''ail avec 100 ml d''eau.","Assaisonner le saumon et le faire cuire à la poêle côté peau jusqu''à ce qu''il soit croustillant, puis le retourner.","Verser la sauce au miso dans la poêle et passer sous le gril bien chaud jusqu''à ce que la sauce bouillonne et réduise.","Pendant ce temps, faire cuire brièvement le pak choï, les pois gourmands et les mini-épis de maïs dans l''eau bouillante jusqu''à ce qu''ils soient juste tendres, puis les égoutter.","Dresser le riz et les légumes, déposer le saumon dessus, napper de sauce et parsemer d''oignon nouveau."]},"it":{"title":"Salmone al miso con riso e verdure","steps":["Lessare il riso in acqua salata finché non è tenero, poi scolarlo.","Sbattere il miso, l''aceto di riso, lo zenzero e l''aglio con 100 ml d''acqua.","Condire il salmone e cuocerlo in padella dal lato della pelle finché non è croccante, poi girarlo.","Versare la salsa al miso nella padella e passarla sotto il grill ben caldo finché la salsa non sobbolle e si riduce.","Nel frattempo lessare brevemente il pak choi, le taccole e le pannocchiette finché non sono appena tenere, poi scolarli.","Disporre nei piatti il riso e le verdure, adagiarvi sopra il salmone, irrorare con la salsa e completare con il cipollotto."]}}'::jsonb),
  ('52ce91db-4179-47c8-8c68-268c31a607be'::uuid, '{"fr":{"title":"Poulet tandoori au four","steps":["Mélanger le yaourt, la pâte gingembre-ail, les épices moulues, le sel, les feuilles de fenugrec, l''huile et le jus de citron ; goûter et rectifier le sel et le piquant.","Faire 2–3 entailles profondes dans chaque morceau de poulet, bien l''enrober de marinade et réserver au réfrigérateur 6 heures ou toute une nuit.","Sortir le poulet du réfrigérateur 20 minutes avant la cuisson et préchauffer le four à 240 °C.","Mélanger le piment en poudre et l''huile pour l''huile pimentée.","Poser une grille huilée sur une plaque tapissée de papier aluminium, y disposer le poulet en espaçant les morceaux et enfourner 15 minutes ; badigeonner avec le reste de marinade ou d''huile pimentée.","Retourner les morceaux et poursuivre la cuisson 12–15 minutes, puis badigeonner d''huile pimentée.","Placer en haut du four sous le gril pendant 3–4 minutes jusqu''à ce que le poulet soit légèrement grillé ; la partie la plus épaisse doit atteindre 75 °C.","Parsemer de coriandre et servir avec de l''oignon, du concombre et des quartiers de citron."]},"it":{"title":"Pollo tandoori al forno","steps":["Mescolare lo yogurt, la pasta di zenzero e aglio, le spezie macinate, il sale, le foglie di fieno greco, l''olio e il succo di limone; assaggiare e regolare di sale e piccantezza.","Praticare 2–3 tagli profondi in ogni pezzo di pollo, ricoprirlo bene con la marinata e lasciarlo in frigorifero per 6 ore o per tutta la notte.","Togliere il pollo dal frigorifero 20 minuti prima della cottura e preriscaldare il forno a 240 °C.","Mescolare il peperoncino in polvere e l''olio per l''olio piccante.","Sistemare una griglia unta su una teglia rivestita di carta stagnola, disporvi il pollo ben distanziato e cuocere in forno per 15 minuti; spennellare con la marinata avanzata o con l''olio piccante.","Girare i pezzi e cuocere per altri 12–15 minuti, poi spennellare con l''olio piccante.","Spostare sul ripiano più alto sotto il grill per 3–4 minuti finché non è leggermente abbrustolito; la parte più spessa deve raggiungere 75 °C.","Guarnire con il coriandolo e servire con cipolla, cetriolo e spicchi di limone."]}}'::jsonb),
  ('d5fbc6b0-5548-4b44-a525-d4671dd07f89'::uuid, '{"fr":{"title":"Oyakodon (bol de riz au poulet et à l''œuf)","steps":["Faire cuire le riz.","Couper le poulet en biais en morceaux d''environ 2,5 cm.","Porter le mirin et le saké à ébullition dans une grande poêle à feu moyen-vif, puis ajouter le dashi, la sauce soja et le sucre et porter de nouveau à ébullition.","Répartir l''oignon en une seule couche dans la poêle, disposer le poulet par-dessus, couvrir et porter de nouveau à ébullition.","Écumer la mousse et la graisse, puis laisser mijoter à feu moyen environ 10 minutes jusqu''à ce que le poulet soit cuit.","Verser lentement les œufs battus en filet sur l''ensemble, couvrir et cuire juste jusqu''à ce que l''œuf soit pris mais encore moelleux, en secouant la poêle de temps en temps.","Parsemer d''oignon nouveau, puis faire glisser le poulet, l''œuf et un peu de sauce sur les bols de riz."]},"it":{"title":"Oyakodon (ciotola di riso con pollo e uovo)","steps":["Cuocere il riso.","Tagliare il pollo in diagonale a pezzi di circa 2,5 cm.","Portare a bollore il mirin e il sakè in una padella grande a fuoco medio-alto, poi aggiungere il dashi, la salsa di soia e lo zucchero e riportare a bollore.","Distribuire la cipolla nella padella in un solo strato, adagiarvi sopra il pollo, coprire e riportare a bollore.","Eliminare la schiuma e il grasso, poi far sobbollire a fuoco medio per circa 10 minuti finché il pollo non è cotto.","Versare lentamente le uova sbattute a filo su tutto, coprire e cuocere solo finché l''uovo non si è rappreso ma è ancora morbido, scuotendo la padella di tanto in tanto.","Cospargere con il cipollotto, poi far scivolare il pollo, l''uovo e un po'' di salsa sulle ciotole di riso."]}}'::jsonb),
  ('b47b1a25-61a8-4ea7-8e06-77330e0d02d0'::uuid, '{"fr":{"title":"Pad krapow gai (poulet thaï au basilic et œuf frit)","steps":["Faire frire les œufs au wok dans l''huile de friture, en arrosant le dessus d''huile chaude au lieu de les retourner, jusqu''à ce que les bords soient croustillants ; égoutter et réserver.","Couper le poulet en bouchées ; piler grossièrement l''ail et les piments au mortier (ou les hacher) et effeuiller le basilic.","Faire chauffer le wok à feu vif avec l''huile de cuisson et faire sauter l''ail et le piment environ 20 secondes jusqu''à ce qu''ils embaument, sans les laisser brûler.","Ajouter le poulet et le faire sauter jusqu''à ce qu''il soit presque cuit, en ajoutant une goutte d''eau si le wok devient trop sec.","Assaisonner avec la sauce d''huître, les sauces soja claire et foncée et le sucre, et continuer à faire sauter environ 30 secondes.","Ajouter le basilic sacré, l''incorporer et retirer le wok du feu dès qu''il flétrit.","Servir sur du riz jasmin cuit à la vapeur, avec l''œuf frit par-dessus."]},"it":{"title":"Pad krapow gai (pollo thai al basilico con uovo fritto)","steps":["Friggere le uova nel wok con l''olio per friggere, irrorando la superficie con l''olio caldo invece di girarle, finché i bordi non sono croccanti; scolarle e tenerle da parte.","Tagliare il pollo a bocconcini; pestare grossolanamente l''aglio e i peperoncini nel mortaio (o tritarli) e staccare le foglie di basilico.","Scaldare il wok a fuoco vivo con l''olio per saltare e far saltare l''aglio e il peperoncino per circa 20 secondi finché non sprigionano il loro aroma, senza farli bruciare.","Aggiungere il pollo e saltarlo finché non è quasi cotto, aggiungendo un goccio d''acqua se il wok si asciuga troppo.","Condire con la salsa di ostriche, la salsa di soia chiara e quella scura e lo zucchero, e continuare a saltare per circa 30 secondi.","Unire il basilico sacro, mescolarlo e togliere il wok dal fuoco appena appassisce.","Servire su riso jasmine cotto al vapore con l''uovo fritto sopra."]}}'::jsonb),
  ('7b6d0406-a5ed-4bfa-839a-a993a3868f64'::uuid, '{"fr":{"title":"Pilons de poulet satay, sauce cacahuète","steps":["Pratiquer trois entailles peu profondes (environ 5 mm) sur le côté charnu de chaque pilon.","Mélanger les ingrédients de la marinade, en enrober les pilons et faire pénétrer le mélange dans les entailles ; laisser mariner 3 heures ou toute une nuit au réfrigérateur (facultatif, mais c''est meilleur).","Préchauffer le four à 200 °C (180 °C chaleur tournante) et poser une grille sur une plaque tapissée de papier aluminium.","Disposer les pilons sur la grille et répartir le reste de marinade sur le dessus en tapotant.","Enfourner 35 minutes, puis passer en position gril, puissance maximale, pendant 3–5 minutes pour faire griller la peau.","Pendant ce temps, fouetter tous les ingrédients de la sauce dans une petite casserole et laisser mijoter à feu moyen-doux environ 5 minutes en remuant, jusqu''à ce qu''elle soit fluide mais nappe la cuillère ; garder au chaud.","Servir les pilons avec du riz jasmin et la sauce cacahuète pour les tremper."]},"it":{"title":"Fusi di pollo satay con salsa di arachidi","steps":["Praticare tre tagli poco profondi (circa 5 mm) sul lato più carnoso di ogni fuso.","Mescolare gli ingredienti della marinata, ricoprire i fusi e far penetrare il composto nei tagli; marinare per 3 ore o per tutta la notte in frigorifero (facoltativo ma consigliato).","Preriscaldare il forno a 200 °C (180 °C ventilato) e sistemare una griglia su una teglia rivestita di carta stagnola.","Disporre i fusi sulla griglia e distribuire sopra la marinata rimasta.","Cuocere in forno per 35 minuti, poi passare alla funzione grill al massimo per 3–5 minuti per abbrustolire la pelle.","Nel frattempo sbattere tutti gli ingredienti della salsa in un pentolino e cuocere a fuoco medio-basso per circa 5 minuti, mescolando, finché non è fluida ma vela il cucchiaio; tenere in caldo.","Servire i fusi con riso jasmine e la salsa di arachidi per intingerli."]}}'::jsonb),
  ('57abb0a5-0fc5-4e5e-b5e7-7130b2e204ed'::uuid, '{"fr":{"title":"Poulet trois tasses taïwanais","steps":["Mélanger les sauces soja claire et foncée, le sucre et le vin de riz dans un petit bol.","Faire chauffer l''huile dans une poêle antiadhésive à feu moyen-doux et faire grésiller le gingembre et le piment environ 30 secondes.","Monter à feu vif, ajouter le poulet et le faire cuire jusqu''à ce que l''extérieur blanchisse tout en restant cru à l''intérieur ; ajouter l''ail et remuer 30 secondes.","Verser la sauce, porter à frémissement, puis baisser à feu moyen/moyen-vif pour un frémissement régulier.","Laisser mijoter environ 5 minutes en remuant, jusqu''à ce que le poulet soit coloré et que la sauce ait réduit en un sirop léger (ajouter un peu d''eau si elle réduit trop vite).","Incorporer l''huile de sésame et le basilic jusqu''à ce que les feuilles flétrissent, puis servir sur du riz avec tout le sirop de la poêle."]},"it":{"title":"Pollo tre tazze taiwanese","steps":["Mescolare in una ciotolina la salsa di soia chiara e quella scura, lo zucchero e il vino di riso.","Scaldare l''olio in una padella antiaderente a fuoco medio-basso e far sfrigolare lo zenzero e il peperoncino per circa 30 secondi.","Alzare la fiamma al massimo, aggiungere il pollo e cuocerlo finché l''esterno non diventa bianco pur restando crudo all''interno; aggiungere l''aglio e mescolare per 30 secondi.","Versare la salsa, portare a bollore, poi abbassare a fuoco medio/medio-alto per mantenere un sobbollire costante.","Cuocere a fuoco lento per circa 5 minuti, mescolando, finché il pollo non ha preso colore e la salsa non si è ridotta a uno sciroppo leggero (aggiungere un goccio d''acqua se si riduce troppo in fretta).","Unire l''olio di sesamo e il basilico finché le foglie non appassiscono, poi servire sul riso con tutto lo sciroppo della padella."]}}'::jsonb),
  ('6001b71f-a4b5-458e-b945-13665dd61028'::uuid, '{"fr":{"title":"Poulet teriyaki et riz","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Fouetter ensemble la sauce soja, le sucre, le vinaigre, la moitié de l''huile, l''ail et le gingembre.","Mélanger le poulet avec la moitié de cette sauce dans un plat à four et enfourner 20–25 minutes jusqu''à ce qu''il soit bien cuit et laqué.","Pendant ce temps, faire cuire le riz selon les indications du paquet.","Faire revenir doucement l''oignon dans le reste de l''huile à feu moyen pendant 5–8 minutes jusqu''à ce qu''il soit légèrement doré ; réserver.","Incorporer la fécule de maïs au reste de la sauce et la faire bouillonner dans la poêle jusqu''à ce qu''elle épaississe, puis remettre l''oignon et ajouter le poulet rôti.","Servir sur le riz avec le jus du plat de cuisson et l''oignon nouveau par-dessus."]},"it":{"title":"Pollo teriyaki con riso","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Sbattere insieme la salsa di soia, lo zucchero, l''aceto, metà dell''olio, l''aglio e lo zenzero.","Mescolare il pollo con metà di questa salsa in una pirofila e cuocere in forno per 20–25 minuti finché non è ben cotto e glassato.","Nel frattempo cuocere il riso seguendo le istruzioni sulla confezione.","Far appassire la cipolla nell''olio rimasto a fuoco medio per 5–8 minuti finché non è leggermente dorata; tenere da parte.","Incorporare l''amido di mais alla salsa rimasta e farla sobbollire nella padella finché non si addensa, poi rimettere la cipolla e aggiungere il pollo cotto in forno.","Servire sul riso con il fondo di cottura della pirofila e il cipollotto sopra."]}}'::jsonb),
  ('133f9e39-76f2-420d-954d-e311510897f2'::uuid, '{"fr":{"title":"Curry vert thaï au poulet","steps":["Faire chauffer l''huile dans une casserole à fond épais à feu moyen-vif.","Faire revenir la pâte de curry vert avec l''ail, le gingembre et la citronnelle pendant 2–3 minutes jusqu''à ce que la majeure partie de l''humidité se soit évaporée (garder le visage à l''écart des vapeurs).","Verser le bouillon et le lait de coco et remuer jusqu''à ce que la pâte soit dissoute.","Assaisonner avec la sauce poisson et le sucre, ajouter les feuilles de citron kaffir et porter à frémissement.","Ajouter le poulet, baisser le feu pour obtenir un léger frémissement et cuire 7 minutes.","Ajouter l''aubergine et laisser mijoter environ 5 minutes jusqu''à ce qu''elle soit tendre ; goûter et rectifier le sel et le sucre.","Ajouter les pois gourmands pendant 2 minutes, puis incorporer le basilic et le jus de citron vert et retirer aussitôt du feu.","Servir sur du riz jasmin."]},"it":{"title":"Curry verde thai con pollo","steps":["Scaldare l''olio in una pentola dal fondo spesso a fuoco medio-alto.","Soffriggere la pasta di curry verde con l''aglio, lo zenzero e la citronella per 2–3 minuti finché gran parte dell''umidità non è evaporata (tenere il viso lontano dai vapori).","Versare il brodo e il latte di cocco e mescolare finché la pasta non si scioglie.","Condire con la salsa di pesce e lo zucchero, aggiungere le foglie di lime kaffir e portare a bollore leggero.","Aggiungere il pollo, abbassare la fiamma per un sobbollire delicato e cuocere per 7 minuti.","Aggiungere la melanzana e cuocere a fuoco lento per circa 5 minuti finché non è morbida; assaggiare e regolare di sale e dolcezza.","Aggiungere le taccole per 2 minuti, poi unire il basilico e il succo di lime e togliere subito dal fuoco.","Servire su riso jasmine."]}}'::jsonb),
  ('66ead8f3-045d-4124-a93c-2ee801a03fef'::uuid, '{"fr":{"title":"Ragoût de poisson brésilien (moqueca)","steps":["Éponger le poisson, le couper en gros morceaux et le frotter avec le sel, le zeste et le jus de citron vert ; réserver.","Dans une sauteuse large, faire revenir l''oignon dans l''huile avec une pincée de sel jusqu''à ce qu''il soit tendre.","Ajouter la carotte, le poivron rouge, l''ail et le jalapeño et poursuivre la cuisson quelques minutes.","Incorporer le concentré de tomate, le paprika, le cumin et le fumet, porter à frémissement, ajouter les tomates, couvrir et cuire jusqu''à ce que les carottes soient tendres.","Verser le lait de coco et rectifier le sel.","Enfoncer le poisson dans la sauce et laisser mijoter doucement en l''arrosant de bouillon, jusqu''à ce qu''il soit tout juste cuit (les morceaux épais peuvent finir de cuire au four à 175 °C).","Ajouter un filet de citron vert, parsemer d''herbes et servir sur du riz."]},"it":{"title":"Stufato di pesce brasiliano (moqueca)","steps":["Asciugare il pesce tamponandolo, tagliarlo a pezzi grandi e strofinarlo con il sale, la scorza e il succo di lime; tenere da parte.","In una padella larga, far appassire la cipolla nell''olio con un pizzico di sale finché non è morbida.","Aggiungere la carota, il peperone rosso, l''aglio e il jalapeño e cuocere ancora per qualche minuto.","Unire il concentrato di pomodoro, la paprika, il cumino e il brodo, portare a bollore leggero, aggiungere i pomodori, coprire e cuocere finché le carote non sono tenere.","Versare il latte di cocco e regolare di sale.","Adagiare il pesce nella salsa e cuocere delicatamente a fuoco lento, irrorandolo con il brodo, finché non è appena cotto (i pezzi spessi possono finire la cottura in forno a 175 °C).","Aggiungere una spruzzata di lime, cospargere di erbe aromatiche e servire sul riso."]}}'::jsonb),
  ('259ada42-4c9b-4936-88ec-79c0ba6bb82b'::uuid, '{"fr":{"title":"Chaudrée de saumon cajun et patate douce","steps":["Faire chauffer l''huile dans une casserole à feu moyen-vif, ajouter la carotte, l''oignon et le céleri, couvrir et cuire environ 5 minutes jusqu''à ce qu''ils soient tendres.","Ajouter le poivron et l''assaisonnement cajun et poursuivre la cuisson 2 minutes.","Ajouter la patate douce, le bouillon et environ 120 ml d''eau, porter à ébullition, puis couvrir et laisser mijoter environ 10 minutes jusqu''à ce que la patate douce soit tendre.","Ajouter le saumon et le maïs et laisser mijoter environ 3 minutes jusqu''à ce que le poisson soit tout juste opaque à cœur.","Baisser à feu doux, incorporer le mélange lait-crème, le basilic et le sel et réchauffer 1 minute.","Retirer du feu, incorporer le jus de citron et servir."]},"it":{"title":"Zuppa cremosa di salmone cajun e patate dolci","steps":["Scaldare l''olio in una casseruola a fuoco medio-alto, aggiungere la carota, la cipolla e il sedano, coprire e cuocere per circa 5 minuti finché non si ammorbidiscono.","Aggiungere il peperone e il condimento cajun e cuocere per altri 2 minuti.","Aggiungere la patata dolce, il brodo e circa 120 ml d''acqua, portare a bollore, poi coprire e cuocere a fuoco lento per circa 10 minuti finché la patata non è tenera.","Aggiungere il salmone e il mais e cuocere a fuoco lento per circa 3 minuti finché il pesce non è appena opaco al centro.","Abbassare la fiamma al minimo, unire la miscela di latte e panna, il basilico e il sale e scaldare per 1 minuto.","Togliere dal fuoco, unire il succo di limone e servire."]}}'::jsonb),
  ('d939ecdf-9a41-49f5-87f1-33289d9daeea'::uuid, '{"fr":{"title":"Saumon cajun et quartiers de patate douce","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger les quartiers sur une plaque antiadhésive avec la moitié de l''huile, le romarin et un peu de sel et enfourner 25-30 minutes jusqu''à ce qu''ils soient croustillants à l''extérieur et fondants à l''intérieur.","Frotter le saumon avec un peu d''huile et l''enrober d''assaisonnement cajun.","Pendant les 10 dernières minutes de cuisson des quartiers, faire rôtir le saumon à côté sur une petite plaque.","Assaisonner la roquette avec le reste de l''huile et le vinaigre et servir avec le saumon et les quartiers."]},"it":{"title":"Salmone cajun con spicchi di patate dolci","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Mescolare gli spicchi su una teglia antiaderente con metà dell''olio, il rosmarino e un po'' di sale e cuocere in forno per 25-30 minuti finché non sono croccanti fuori e morbidi dentro.","Strofinare il salmone con un filo d''olio e ricoprirlo con il condimento cajun.","Negli ultimi 10 minuti di cottura degli spicchi, cuocere in forno il salmone accanto, su una teglia piccola.","Condire la rucola con l''olio rimasto e l''aceto e servire con il salmone e gli spicchi."]}}'::jsonb),
  ('376e8ca0-3d31-4b62-852c-ac2fdc9e9648'::uuid, '{"fr":{"title":"Bols de carne asada, crème au chipotle","steps":["Mélanger l''huile, la sauce soja, le jus de citron vert, le cumin, le chipotle en poudre, la coriandre et l''ail dans un sac de congélation zippé.","Ajouter le steak et laisser mariner au réfrigérateur au moins 30 minutes (jusqu''à 8 heures).","Faire chauffer un barbecue à feu vif, sortir le steak de la marinade, le saler des deux côtés et le faire griller environ 5 minutes de chaque côté.","Laisser reposer le steak 5-10 minutes, couvert sans serrer, puis le trancher perpendiculairement aux fibres et le couper en dés.","Mélanger le riz cuit avec la coriandre et le jus de citron vert.","Mixer la crème, le chipotle, l''ail, le citron vert et le sel jusqu''à obtenir une crème lisse.","Garnir les bols de riz, de steak, de pico de gallo, d''avocat, de jalapeño, de radis et de fromage, puis arroser de crème au chipotle."]},"it":{"title":"Ciotole di carne asada con crema al chipotle","steps":["Mescolare in un sacchetto con chiusura zip l''olio, la salsa di soia, il succo di lime, il cumino, il chipotle in polvere, il coriandolo e l''aglio.","Aggiungere la bistecca e lasciarla marinare in frigorifero per almeno 30 minuti (fino a 8 ore).","Scaldare la griglia al massimo, togliere la bistecca dalla marinata, salarla su entrambi i lati e grigliarla per circa 5 minuti per lato.","Lasciare riposare la bistecca coperta senza stringere per 5-10 minuti, poi tagliarla contro fibra e ridurla a cubetti.","Mescolare il riso cotto con il coriandolo e il succo di lime.","Frullare la crema, il chipotle, l''aglio, il lime e il sale fino a ottenere un composto liscio.","Riempire le ciotole con riso, bistecca, pico de gallo, avocado, jalapeño, ravanelli e formaggio, poi condire con un filo di crema al chipotle."]}}'::jsonb),
  ('7dfb17b4-788e-4166-8e3f-0327f79e3794'::uuid, '{"fr":{"title":"Poulet et patate douce rôtis au four","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger la patate douce, l''oignon et l''ail avec le thym, le romarin, la majeure partie de l''huile, du sel et du poivre, et enfourner 15 minutes.","Remuer, caler le poulet entre les légumes, l''arroser du reste de l''huile, ajouter le jus de citron et le paprika fumé et poursuivre la cuisson 15 minutes.","Ajouter le brocoli et la majeure partie du bouillon et enfourner encore 15-20 minutes, en ajoutant du bouillon si la plaque se dessèche, jusqu''à ce que le poulet soit bien cuit.","Presser l''ail fondant hors de sa peau au-dessus de la plaque et servir avec les quartiers de citron."]},"it":{"title":"Pollo e patate dolci in teglia","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Mescolare la patata dolce, la cipolla e l''aglio con il timo, il rosmarino, gran parte dell''olio, sale e pepe, e cuocere in forno per 15 minuti.","Mescolare, sistemare il pollo tra le verdure, irrorarlo con l''olio rimasto, aggiungere il succo di limone e la paprika affumicata e cuocere in forno per altri 15 minuti.","Aggiungere i broccoli e gran parte del brodo e cuocere in forno per altri 15-20 minuti, aggiungendo altro brodo se la teglia si asciuga, finché il pollo non è ben cotto.","Spremere l''aglio morbido dalla buccia direttamente sulla teglia e servire con gli spicchi di limone."]}}'::jsonb),
  ('27e46b96-2742-476c-bc1f-e5c23aa41f11'::uuid, '{"fr":{"title":"Souvlaki de poulet au tzatziki","steps":["Fouetter l''huile, le jus de citron, l''ail, l''origan, le sel et le poivre pour obtenir une marinade.","Y enrober les cubes de poulet et laisser au réfrigérateur 3-4 heures.","Faire tremper des brochettes en bois dans l''eau, puis y enfiler le poulet et le badigeonner du reste de marinade.","Faire griller 10-15 minutes en retournant de temps en temps, jusqu''à ce que le poulet soit bien cuit.","Réchauffer les pitas sur le gril.","Servir les brochettes sur les pitas avec des rondelles de tomate et du tzatziki."]},"it":{"title":"Souvlaki di pollo con tzatziki","steps":["Sbattere l''olio, il succo di limone, l''aglio, l''origano, il sale e il pepe per preparare una marinata.","Ricoprire i cubetti di pollo con la marinata e lasciarli in frigorifero per 3-4 ore.","Mettere a bagno in acqua gli spiedini di legno, poi infilzarvi il pollo e spennellarlo con la marinata avanzata.","Grigliare per 10-15 minuti, girando di tanto in tanto, finché non è ben cotto.","Scaldare le pita sulla griglia.","Servire gli spiedini sulle pita con fette di pomodoro e tzatziki."]}}'::jsonb),
  ('7fa7da2a-36aa-4a38-95f7-b0269eae6257'::uuid, '{"fr":{"title":"Tinga de poulet","steps":["Faire chauffer l''huile à feu moyen et faire revenir l''oignon émincé environ 3 minutes.","Ajouter l''ail et cuire encore 2 minutes, jusqu''à ce qu''il soit parfumé.","Incorporer les tomates et le persil, baisser le feu et cuire 6-7 minutes jusqu''à ce que les tomates se défassent (ajouter un trait d''eau si c''est trop sec).","Ajouter le poulet effiloché et le chipotle haché et laisser mijoter environ 8 minutes pour que les saveurs se mêlent.","Saler, poivrer, parsemer de persil et servir avec du riz et de la salade ou sur des tostadas."]},"it":{"title":"Tinga di pollo","steps":["Scaldare l''olio a fuoco medio e soffriggere la cipolla affettata per circa 3 minuti.","Aggiungere l''aglio e cuocere ancora 2 minuti, finché non diventa profumato.","Unire i pomodori e il prezzemolo, abbassare la fiamma e cuocere 6-7 minuti finché i pomodori non si disfano (aggiungere un goccio d''acqua se si asciuga troppo).","Aggiungere il pollo sfilacciato e il chipotle tritato e cuocere a fuoco lento per circa 8 minuti, così che i sapori si amalgamino.","Regolare di sale e pepe, guarnire con prezzemolo e servire con riso e insalata oppure sulle tostadas."]}}'::jsonb),
  ('c48e4b57-7ea0-42c9-b482-1f84126f5951'::uuid, '{"fr":{"title":"Doro wat","steps":["Frotter le poulet avec le jus de citron, bien le rincer, saler et laisser reposer 30 minutes.","Cuire les oignons à sec dans une casserole à feu moyen-doux, en remuant de temps en temps, pendant au moins une heure, jusqu''à ce qu''ils soient bien caramélisés.","Ajouter l''huile et poursuivre la cuisson des oignons 15-20 minutes, jusqu''à ce qu''ils foncent.","Incorporer le berbéré, l''ail, le gingembre, la cardamome et le ghee.","Ajouter le poulet, couvrir et cuire 10 minutes, puis ajouter environ 250 ml d''eau, couvrir de nouveau et cuire encore 30 minutes.","Pendant ce temps, faire cuire les œufs environ 10 minutes dans l''eau bouillante, les plonger dans de l''eau glacée, les écaler et les couper en morceaux.","Ajouter les œufs au ragoût, assaisonner de mekelesha et de sel, et servir avec du riz ou de l''injera."]},"it":{"title":"Doro wat","steps":["Strofinare il pollo con il succo di limone, sciacquarlo bene, salarlo e lasciarlo riposare 30 minuti.","Cuocere le cipolle in una casseruola senza grassi a fuoco medio-basso, mescolando di tanto in tanto, per almeno un''ora, finché non sono ben caramellate.","Aggiungere l''olio e continuare a cuocere le cipolle per 15-20 minuti, finché non diventano più scure.","Unire il berbere, l''aglio, lo zenzero, il cardamomo e il ghee.","Aggiungere il pollo, coprire e cuocere 10 minuti, poi aggiungere circa 250 ml d''acqua, coprire di nuovo e cuocere ancora 30 minuti.","Nel frattempo lessare le uova per circa 10 minuti, raffreddarle in acqua e ghiaccio, sgusciarle e tagliarle a pezzi.","Aggiungere le uova allo spezzatino, insaporire con il mekelesha e il sale e servire con riso o injera."]}}'::jsonb),
  ('eab5838e-660b-4b5f-9444-00603cb201fa'::uuid, '{"fr":{"title":"Poisson au four à la grecque (psari plaki)","steps":["Préchauffer le four à 200 °C (400 °F), avec une grille au milieu.","Dans une poêle allant au four, faire revenir l''oignon dans l''huile d''olive avec une pincée de sel jusqu''à ce qu''il soit tendre et légèrement doré.","Incorporer l''ail, puis les tomates, l''origan et le poivre ; écraser les tomates, porter à ébullition et laisser mijoter 10-15 minutes.","Sécher le poisson et l''assaisonner des deux côtés de sel, d''origan, de paprika et de cumin ; presser la moitié du citron par-dessus.","Déposer le poisson dans la sauce et le napper d''un peu de sauce.","Enfourner 15-25 minutes, jusqu''à ce que le poisson soit opaque et s''effeuille facilement ; surveiller pour qu''il ne soit pas trop cuit.","Parsemer de persil et servir avec le reste du citron en quartiers, ainsi que du pain ou du riz."]},"it":{"title":"Pesce al forno alla greca (psari plaki)","steps":["Preriscaldare il forno a 200 °C (400 °F) con una griglia al centro.","In una padella adatta al forno, far appassire la cipolla nell''olio d''oliva con un pizzico di sale finché non è morbida e leggermente dorata.","Unire l''aglio, poi i pomodori, l''origano e il pepe; schiacciare i pomodori, portare a bollore e cuocere a fuoco lento per 10-15 minuti.","Asciugare il pesce e condirlo su entrambi i lati con sale, origano, paprika e cumino; spremerci sopra metà del limone.","Adagiare il pesce nel sugo e coprirlo con un po'' di sugo.","Cuocere in forno 15-25 minuti, finché il pesce non è opaco e si sfalda facilmente; controllare che non cuocia troppo.","Cospargere di prezzemolo e servire con il limone rimasto a spicchi, accompagnando con pane o riso."]}}'::jsonb),
  ('88cbc523-853f-41c7-b63a-f0f761e56e3b'::uuid, '{"fr":{"title":"Saumon rôti à la harissa et céréales aux herbes","steps":["Faire cuire les céréales à petit bouillon dans de l''eau salée 20-25 minutes, jusqu''à ce qu''elles soient juste tendres.","Préchauffer le four à 180 °C (160 °C chaleur tournante) ; mélanger la harissa, l''huile, le miel et le jus d''un demi-citron.","Enrober le saumon et les tomates du mélange à la harissa dans un plat à four et rôtir 15 minutes.","Dans un grand saladier, mélanger les oignons nouveaux, la majeure partie des herbes, le reste du jus de citron et un filet d''huile.","Ajouter les petits pois aux céréales pendant la dernière minute, puis bien égoutter.","Mélanger le reste des herbes au yaourt avec du sel et un trait d''eau pour le détendre.","Mélanger les céréales et les petits pois avec les oignons nouveaux, dresser dans les assiettes, garnir de saumon et de tomates et ajouter la sauce au yaourt."]},"it":{"title":"Salmone al forno all''harissa con cereali alle erbe","steps":["Cuocere i cereali in acqua salata a fuoco lento per 20-25 minuti, finché non sono appena teneri.","Preriscaldare il forno a 180 °C (160 °C ventilato); mescolare harissa, olio, miele e il succo di mezzo limone.","In una pirofila, condire il salmone e i pomodorini con il mix all''harissa e cuocere in forno 15 minuti.","In una ciotola capiente unire i cipollotti, la maggior parte delle erbe, il resto del succo di limone e un filo d''olio.","Aggiungere i piselli ai cereali nell''ultimo minuto di cottura, poi scolare bene.","Mescolare le erbe rimaste allo yogurt con sale e un goccio d''acqua per renderlo più fluido.","Condire cereali e piselli con il mix di cipollotti, impiattare, aggiungere sopra salmone e pomodorini e completare con la salsa allo yogurt."]}}'::jsonb),
  ('21e7d4dc-7424-4a23-b4c8-b3410109c188'::uuid, '{"fr":{"title":"Cottage pie allégé","steps":["Vaporiser une cocotte d''huile et faire suer l''oignon à feu moyen.","Ajouter l''ail, la carotte, le céleri, le sel, les herbes, le sucre et la feuille de laurier et cuire environ 8 minutes.","Ajouter le bœuf haché en l''émiettant et cuire jusqu''à ce qu''il soit bien doré.","Incorporer le concentré de tomates, puis le vinaigre balsamique, la sauce soja et la sauce Worcestershire.","Ajouter la courge butternut et le bouillon, couvrir partiellement et laisser mijoter 30 minutes ; épaissir avec la fécule de maïs délayée dans un peu d''eau froide et retirer la feuille de laurier.","Pendant ce temps, cuire les pommes de terre dans l''eau salée environ 15 minutes jusqu''à ce qu''elles soient tendres, les égoutter (en gardant un peu d''eau de cuisson) et les écraser avec le yaourt ou le fromage blanc.","Préchauffer le four à 220 °C, étaler la garniture dans un plat à four, recouvrir de purée et strier la surface à la fourchette.","Parsemer de parmesan et enfourner 30-35 minutes jusqu''à ce que le dessus soit doré ; laisser reposer 10 minutes avant de servir avec des légumes verts."]},"it":{"title":"Cottage pie light","steps":["Spruzzare una casseruola con l''olio e far appassire la cipolla a fuoco medio.","Aggiungere l''aglio, la carota, il sedano, il sale, le erbe, lo zucchero e l''alloro e cuocere per circa 8 minuti.","Aggiungere il macinato, sgranandolo, e cuocere finché non è ben rosolato.","Unire il concentrato di pomodoro, poi l''aceto balsamico, la salsa di soia e la salsa Worcestershire.","Aggiungere la zucca e il brodo, coprire parzialmente e cuocere a fuoco lento per 30 minuti; addensare con l''amido di mais stemperato in poca acqua fredda ed eliminare la foglia di alloro.","Nel frattempo lessare le patate in acqua salata per circa 15 minuti finché non sono tenere, scolarle (tenendo da parte un goccio dell''acqua di cottura) e schiacciarle con lo yogurt o il formaggio fresco magro.","Preriscaldare il forno a 220 °C, distribuire il ripieno in una pirofila, coprire con il purè e rigare la superficie con una forchetta.","Cospargere di parmigiano e cuocere in forno 30-35 minuti finché non è dorato; lasciar riposare 10 minuti prima di servire con verdure verdi."]}}'::jsonb),
  ('b0816cc0-d7b8-4649-88e0-b13c37a64404'::uuid, '{"fr":{"title":"Chili de dinde allégé","steps":["Faire chauffer l''huile dans une grande marmite à feu moyen-vif et faire revenir l''oignon, l''ail et le poivron 5-7 minutes en remuant souvent.","Ajouter la dinde et l''émietter à la cuillère jusqu''à ce qu''elle ne soit plus rose.","Incorporer le piment en poudre, le cumin, l''origan, le piment de Cayenne et le sel et faire griller environ 20 secondes.","Ajouter les tomates, le bouillon, les haricots rouges et le maïs et porter à ébullition.","Baisser le feu et laisser mijoter 30-45 minutes jusqu''à ce que ce soit épais, puis rectifier l''assaisonnement.","Servir garni d''un peu de fromage, d''avocat ou de coriandre, selon les envies."]},"it":{"title":"Chili di tacchino light","steps":["Scaldare l''olio in una pentola capiente a fuoco medio-alto e soffriggere cipolla, aglio e peperone per 5-7 minuti, mescolando spesso.","Aggiungere il tacchino e sgranarlo con un cucchiaio finché non è più rosa.","Unire il chili in polvere, il cumino, l''origano, il pepe di Cayenna e il sale e tostare per circa 20 secondi.","Aggiungere i pomodori, il brodo, i fagioli rossi e il mais e portare a bollore.","Abbassare la fiamma e cuocere a fuoco lento per 30-45 minuti finché non si addensa, poi aggiustare di sapore.","Servire con un po'' di formaggio, avocado o coriandolo, a piacere."]}}'::jsonb),
  ('72202527-c9b6-4d93-a159-0f71b4d22001'::uuid, '{"fr":{"title":"Ragoût d''agneau irlandais","steps":["Mélanger l''agneau avec la moitié de l''ail, le romarin et le vin blanc et laisser mariner 1 heure ; égoutter et jeter le liquide.","Faire chauffer l''huile dans une cocotte en fonte et faire dorer l''agneau sur toutes les faces, par petites quantités ; réserver.","Faire suer l''oignon dans la même cocotte environ 4 minutes, puis ajouter le reste de l''ail pendant 1 minute.","Remettre l''agneau avec les flocons de piment, les poivrons grillés, la tomate, la feuille de laurier et le vin rouge ; porter à ébullition et laisser mijoter 15 minutes.","Verser le bouillon et cuire doucement à feu doux 1,5-2 heures, jusqu''à ce que l''agneau soit très tendre.","Saler, poivrer et servir avec du riz ou du pain croustillant."]},"it":{"title":"Spezzatino d''agnello irlandese","steps":["Mescolare l''agnello con metà dell''aglio, il rosmarino e il vino bianco e lasciar marinare per 1 ora; scolare ed eliminare il liquido.","Scaldare l''olio in una pentola dal fondo spesso e rosolare l''agnello su tutti i lati, poco per volta; tenere da parte.","Far appassire la cipolla nella stessa pentola per circa 4 minuti, poi aggiungere l''aglio rimasto per 1 minuto.","Rimettere l''agnello con il peperoncino in fiocchi, i peperoni arrostiti, il pomodoro, l''alloro e il vino rosso; portare a bollore e cuocere a fuoco lento per 15 minuti.","Versare il brodo e cuocere dolcemente a fuoco basso per 1,5-2 ore, finché l''agnello non è molto tenero.","Regolare di sale e pepe e servire con riso o pane croccante."]}}'::jsonb),
  ('8415659c-0fbe-4c0f-879f-6902ec41c28b'::uuid, '{"fr":{"title":"Curry de poulet jerk aux haricots","steps":["Frotter les pilons avec un peu d''assaisonnement jerk, du sel et du poivre.","Les faire dorer dans la moitié de l''huile, puis les réserver sur une assiette.","Ajouter le reste de l''huile et faire suer l''oignon et les tiges de coriandre environ 5 minutes, en incorporant le reste de l''assaisonnement jerk pendant la dernière minute.","Remettre le poulet, ajouter les tomates, porter à frémissement, couvrir et cuire 20 minutes ; lancer la cuisson du riz pendant ce temps.","Découvrir, ajouter les haricots et laisser mijoter encore 10 minutes, jusqu''à ce que le poulet soit cuit à cœur.","Parsemer de feuilles de coriandre et servir avec le riz."]},"it":{"title":"Curry di pollo jerk con fagioli","steps":["Massaggiare i fusi di pollo con un po'' di condimento jerk, sale e pepe.","Rosolarli in metà dell''olio, poi toglierli e metterli su un piatto.","Aggiungere il resto dell''olio e far appassire la cipolla e i gambi di coriandolo per circa 5 minuti, unendo il condimento jerk rimasto nell''ultimo minuto.","Rimettere il pollo, aggiungere i pomodori, portare a sobbollire, coprire e cuocere 20 minuti; nel frattempo mettere a cuocere il riso.","Scoprire, aggiungere i fagioli e cuocere a fuoco lento per altri 10 minuti, finché il pollo non è cotto.","Cospargere di foglie di coriandolo e servire con il riso."]}}'::jsonb),
  ('ff2f10ad-8161-4b4b-aba7-4d79a27d86cb'::uuid, '{"fr":{"title":"Poulet jerk et frites de patate douce","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante) et chemiser deux plaques de cuisson.","Couper les patates douces en frites de l''épaisseur d''un doigt, les mélanger avec la majeure partie de l''huile et une pincée de sel et les étaler sur une plaque.","Frotter le poulet avec l''assaisonnement jerk et le disposer sur la seconde plaque.","Rôtir 20 minutes, le poulet sur la grille du haut et les frites en dessous, puis intervertir les plaques et rôtir encore 15-20 minutes, jusqu''à ce que les frites soient tendres et grillées et que le poulet soit cuit.","Pendant ce temps, mélanger les tomates, l''oignon et le piment avec le zeste du citron vert, la moitié de son jus, un filet d''huile et une pincée de sel.","Servir le poulet et les frites avec la salade de tomates, la mâche et le reste du citron vert en quartiers."]},"it":{"title":"Pollo jerk con patatine di patate dolci","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato) e foderare due teglie.","Tagliare le patate dolci a bastoncini spessi un dito, condirle con la maggior parte dell''olio e un pizzico di sale e distribuirle su una teglia.","Massaggiare il pollo con il condimento jerk e disporlo sulla seconda teglia.","Cuocere in forno 20 minuti con il pollo sul ripiano alto e le patate sotto, poi invertire le teglie e cuocere altri 15-20 minuti, finché le patate non sono tenere e abbrustolite e il pollo è cotto.","Nel frattempo mescolare i pomodorini, la cipolla e il peperoncino con la scorza del lime, metà del succo, un filo d''olio e un pizzico di sale.","Servire il pollo e le patate con l''insalata di pomodorini, la valeriana e il lime rimasto a spicchi."]}}'::jsonb),
  ('7ff5c0bd-3b85-48ab-8595-8379faa87fc3'::uuid, '{"fr":{"title":"Kofta d''agneau, yaourt aux herbes","steps":["Mélanger l''agneau avec l''ail, l''oignon râpé, les épices, les herbes, le sel et le poivre.","Diviser en 4 portions, presser chacune autour d''une brochette pour former une kofta allongée et réfrigérer 10-15 minutes si le temps le permet.","Mélanger le yaourt avec l''ail, le jus de citron, les herbes, du sel et du poivre ; garder au frais.","Faire chauffer un gril ou un barbecue à feu moyen-vif et badigeonner les koftas d''huile.","Griller 12-15 minutes en retournant souvent, jusqu''à ce qu''elles soient dorées et cuites à cœur (70 °C à l''intérieur).","Servir avec des pains plats chauds, la sauce au yaourt, la laitue, le concombre et l''oignon rouge."]},"it":{"title":"Kofta d''agnello con yogurt alle erbe","steps":["Mescolare l''agnello con l''aglio, la cipolla grattugiata, le spezie, le erbe, il sale e il pepe.","Dividere in 4 porzioni, modellare ciascuna attorno a uno spiedino formando una kofta allungata e far riposare in frigo 10-15 minuti se c''è tempo.","Mescolare lo yogurt con l''aglio, il succo di limone, le erbe, sale e pepe; tenere in fresco.","Scaldare una griglia o un barbecue a fuoco medio-alto e spennellare le kofta con l''olio.","Grigliare 12-15 minuti, girando spesso, finché non sono dorate e cotte all''interno (70 °C al cuore).","Servire con pane arabo caldo, la salsa allo yogurt, la lattuga, il cetriolo e la cipolla rossa."]}}'::jsonb),
  ('1e932845-59bf-429a-9ef5-73ddfd24e7ee'::uuid, '{"fr":{"title":"Wraps shawarma au poulet à la libanaise","steps":["Mélanger l''ail, le jus de citron, le yaourt, le sel, les épices et l''huile d''olive pour préparer une marinade.","Y enrober le poulet et réfrigérer 3 heures ou toute une nuit (au moins 1 heure si on est pressé).","Faire chauffer l''huile de cuisson dans une grande poêle jusqu''à ce qu''elle soit très chaude.","Cuire le poulet en une seule couche sans surcharger la poêle, environ 2 minutes de chaque côté pour de fines tranches de blanc, jusqu''à ce qu''il soit doré et cuit à cœur.","Couper le poulet cuit en lanières.","Étaler de la toum au centre de chaque pita, ajouter le poulet, les cornichons et les frites si on en utilise.","Rouler bien serré et couper en deux pour servir."]},"it":{"title":"Wrap di shawarma di pollo alla libanese","steps":["Mescolare aglio, succo di limone, yogurt, sale, spezie e olio d''oliva per preparare la marinata.","Ricoprire il pollo con la marinata e lasciarlo in frigo 3 ore o tutta la notte (almeno 1 ora se si ha fretta).","Scaldare l''olio per friggere in una padella ampia finché non è molto caldo.","Cuocere il pollo in un solo strato senza affollare la padella, circa 2 minuti per lato per fettine sottili di petto, finché non è dorato e cotto.","Tagliare il pollo cotto a striscioline.","Spalmare la toum al centro di ogni pita, aggiungere il pollo, i cetriolini sottaceto e, se si usano, le patatine.","Arrotolare stretto e tagliare a metà per servire."]}}'::jsonb),
  ('e31d848c-77d0-4a82-852f-d6885f91706a'::uuid, '{"fr":{"title":"Boulettes suédoises allégées","steps":["Faire suer l''oignon et l''ail dans l''huile, ajouter le céleri et le persil pendant quelques minutes, puis laisser refroidir le mélange.","Mélanger la dinde, le bœuf, l''œuf, les légumes refroidis, la chapelure, le sel, le poivre et le piment de la Jamaïque ; façonner 8 boulettes.","Porter le bouillon à ébullition dans une sauteuse, baisser à frémissement et ajouter les boulettes.","Couvrir et pocher environ 20 minutes jusqu''à ce qu''elles soient cuites à cœur, puis retirer les boulettes.","Filtrer le bouillon et le mixer avec le fromage frais jusqu''à obtenir une sauce lisse.","Remettre la sauce et les boulettes dans la sauteuse et laisser mijoter quelques minutes jusqu''à ce que la sauce épaississe légèrement ; parsemer de persil."]},"it":{"title":"Polpette svedesi light","steps":["Far appassire la cipolla e l''aglio nell''olio, aggiungere il sedano e il prezzemolo per un paio di minuti, poi lasciar raffreddare il composto.","Unire il tacchino, il manzo, l''uovo, le verdure raffreddate, il pangrattato, il sale, il pepe e il pimento; formare 8 polpette.","Portare a bollore il brodo in una padella, abbassare la fiamma a sobbollire e aggiungere le polpette.","Coprire e cuocere dolcemente nel brodo per circa 20 minuti finché non sono cotte, poi togliere le polpette dalla padella.","Filtrare il brodo e frullarlo con il formaggio spalmabile fino a ottenere una salsa liscia.","Rimettere la salsa e le polpette nella padella e cuocere a fuoco lento qualche minuto finché la salsa non si addensa leggermente; guarnire con prezzemolo."]}}'::jsonb),
  ('fc33d4ff-b75f-430a-b4e4-bff6fcb450a4'::uuid, '{"fr":{"title":"Poulet paprikash allégé","steps":["Mettre à bouillir une casserole d''eau salée et y cuire les nouilles aux œufs pendant la préparation de la sauce.","Faire chauffer l''huile dans une grande sauteuse à feu moyen-vif et cuire le poulet jusqu''à ce qu''il ne soit plus rose ; le retirer.","Faire suer l''oignon dans la même sauteuse, puis ajouter l''ail environ une minute.","Remettre le poulet avec les deux paprikas, le bouillon, les tomates, le sel et le poivre ; porter à ébullition et cuire environ 2 minutes jusqu''à ce que la sauce épaississe un peu.","Retirer la sauteuse du feu et incorporer le yaourt (hors du feu pour qu''il ne tranche pas) ; rectifier l''assaisonnement.","Napper les nouilles de la préparation et parsemer de persil."]},"it":{"title":"Pollo paprikash light","steps":["Mettere sul fuoco una pentola di acqua salata e cuocere le tagliatelle all''uovo mentre si prepara il sugo.","Scaldare l''olio in una padella capiente a fuoco medio-alto e cuocere il pollo finché non è più rosa; toglierlo dalla padella.","Far appassire la cipolla nella stessa padella, poi aggiungere l''aglio per circa un minuto.","Rimettere il pollo con entrambe le paprike, il brodo, i pomodori, sale e pepe; portare a bollore e cuocere circa 2 minuti finché il sugo non si addensa un po''.","Togliere la padella dal fuoco e incorporare lo yogurt (a fuoco spento, così non impazzisce); regolare di sale e pepe.","Versare sulle tagliatelle e completare con il prezzemolo."]}}'::jsonb),
  ('5bfdb175-f3b8-4a0a-a4ac-d972e6504617'::uuid, '{"fr":{"title":"Tajine de poulet aux olives et au citron","steps":["Mélanger la majeure partie de l''ail avec toutes les épices moulues ; hacher finement un ruban de zeste et le mélanger avec le reste de l''ail.","Sécher le poulet en le tamponnant, l''assaisonner et le faire bien dorer dans l''huile chaude dans une cocotte en fonte, en plusieurs fois ; réserver.","Retirer la majeure partie de la graisse, puis faire suer l''oignon avec les rubans de zeste restants.","Incorporer la pâte d''épices environ 30 secondes, puis ajouter les carottes, le bouillon et le miel en grattant le fond de la cocotte.","Remettre le poulet et son jus, couvrir et laisser mijoter doucement jusqu''à ce qu''il soit tendre, environ 1 heure pour des cuisses (n''ajouter les morceaux de blanc que pour les 20 dernières minutes).","Retirer le poulet et le garder au chaud ; dégraisser la sauce, ajouter les olives et laisser mijoter jusqu''à ce qu''elle épaississe légèrement et que les carottes soient tendres.","Remettre le poulet, incorporer le mélange ail-zeste, la coriandre et le jus de citron, rectifier l''assaisonnement et servir."]},"it":{"title":"Tajine di pollo marocchino con olive e limone","steps":["Mescolare la maggior parte dell''aglio con tutte le spezie in polvere; tritare finemente una scorzetta di limone e mescolarla con l''aglio rimasto.","Asciugare bene il pollo tamponandolo, condirlo e rosolarlo bene nell''olio caldo in una pentola dal fondo spesso, poco per volta; tenere da parte.","Eliminare la maggior parte del grasso, poi far appassire la cipolla con le scorzette rimaste.","Unire la pasta di spezie per circa 30 secondi, poi aggiungere le carote, il brodo e il miele, raschiando il fondo della pentola.","Rimettere il pollo con i suoi succhi, coprire e cuocere a fuoco lento finché non è tenero, circa 1 ora per le cosce (aggiungere i pezzi di petto solo negli ultimi 20 minuti).","Togliere il pollo e tenerlo in caldo; sgrassare il sugo, aggiungere le olive e cuocere a fuoco lento finché non si addensa leggermente e le carote sono morbide.","Rimettere il pollo, unire il mix di aglio e scorza, il coriandolo e il succo di limone, regolare di sale e pepe e servire."]}}'::jsonb),
  ('89dd9707-0a47-4448-9592-cdae9bfb9fb4'::uuid, '{"fr":{"title":"Poulet rôti péruvien, sauce verte","steps":["Mixer les ingrédients de la marinade (huile, jus de citron vert, ail, sel, épices, origan, sucre) jusqu''à obtenir un mélange lisse.","Sécher le poulet, décoller la peau des blancs et des cuisses, glisser la majeure partie de la marinade dessous et frotter l''extérieur avec le reste.","Réfrigérer au moins 6 heures ou toute une nuit.","Préchauffer le four à 220 °C (425 °F) avec une grille entre le bas et le milieu ; poser le poulet sur une grille huilée au-dessus d''un plat tapissé de papier aluminium et ficeler les cuisses.","Rôtir 20 minutes jusqu''à ce qu''il soit doré, puis baisser à 190 °C (375 °F) et rôtir jusqu''à ce que le jus soit clair (environ 70 minutes pour une volaille de 1,8 kg, moins pour une plus petite) ; couvrir de papier aluminium s''il dore trop vite.","Mixer les jalapeños, la coriandre, l''ail, la mayonnaise, la crème fraîche, le jus de citron vert, le sel et le poivre, puis verser l''huile en filet sans arrêter le blender ; réfrigérer pour que la sauce épaississe.","Laisser reposer le poulet sous une feuille d''aluminium environ 20 minutes, le découper et servir avec la sauce verte."]},"it":{"title":"Pollo arrosto peruviano con salsa verde","steps":["Frullare gli ingredienti della marinata (olio, succo di lime, aglio, sale, spezie, origano, zucchero) fino a ottenere un composto liscio.","Asciugare il pollo, staccare la pelle su petto e cosce, infilarci sotto la maggior parte della marinata e massaggiare l''esterno con il resto.","Lasciare in frigorifero almeno 6 ore o tutta la notte.","Preriscaldare il forno a 220 °C (425 °F) con una griglia nella parte medio-bassa; sistemare il pollo su una griglia unta sopra una teglia foderata di alluminio e legare le cosce.","Arrostire 20 minuti finché non è dorato, poi abbassare a 190 °C (375 °F) e cuocere finché i succhi non escono limpidi (circa 70 minuti per un pollo da 1,8 kg, meno per uno più piccolo); coprire con alluminio se si colorisce troppo in fretta.","Frullare jalapeños, coriandolo, aglio, maionese, panna acida, succo di lime, sale e pepe, poi versare l''olio a filo con il frullatore in funzione; mettere in frigo per far addensare.","Far riposare il pollo coperto con alluminio per circa 20 minuti, tagliarlo e servire con la salsa verde."]}}'::jsonb),
  ('f0116db7-383f-4d62-870c-ab0b0417a431'::uuid, '{"fr":{"title":"Saumon poêlé à la harissa, chou-fleur et pois chiches","steps":["Mélanger la harissa et le miel ; réserver.","Dans un grand saladier, mélanger les pois chiches avec une partie de l''huile, le jus de citron et l''échalote.","Cuire le chou-fleur avec la majeure partie de la coriandre moulue, la moitié du sel et un peu plus d''huile dans une poêle antiadhésive couverte jusqu''à ce qu''il commence à ramollir, puis découvrir et cuire jusqu''à ce qu''il soit doré par endroits.","Ajouter le chou-fleur aux pois chiches avec les olives, la coriandre et la menthe ; garder au chaud et essuyer la poêle.","Assaisonner le saumon avec le reste de la coriandre moulue et du sel et le saisir, côté peau vers le haut, dans le reste de l''huile jusqu''à ce qu''il soit bien doré.","Retourner et cuire jusqu''à ce que le centre atteigne environ 50 °C (125 °F) pour une cuisson rosée.","Hors du feu, badigeonner les pavés de harissa au miel, remélanger les légumes, assaisonner et servir ensemble."]},"it":{"title":"Salmone scottato all''harissa con cavolfiore e ceci","steps":["Mescolare l''harissa con il miele; tenere da parte.","In una ciotola capiente condire i ceci con una parte dell''olio, il succo di limone e lo scalogno.","Cuocere il cavolfiore con la maggior parte del coriandolo in polvere, metà del sale e altro olio in una padella antiaderente coperta finché non inizia ad ammorbidirsi, poi scoprire e cuocere finché non è dorato qua e là.","Unire il cavolfiore ai ceci con le olive, il coriandolo e la menta; tenere in caldo e pulire la padella.","Condire il salmone con il resto del coriandolo in polvere e del sale e scottarlo, con il lato della pelle rivolto verso l''alto, nell''olio rimasto finché non è ben dorato.","Girarlo e cuocere finché il centro non raggiunge circa 50 °C (125 °F) per una cottura rosata.","A fuoco spento spennellare i filetti con l''harissa al miele, mescolare di nuovo le verdure, regolare di sale e servire insieme."]}}'::jsonb),
  ('a609b57d-8c52-4d05-a917-cc6e7675b365'::uuid, '{"fr":{"title":"Poulet braisé au xérès, chorizo et pois chiches","steps":["Retirer l''excès de gras des hauts de cuisse et couper chacun en 2-3 morceaux.","Assaisonner le poulet et le faire dorer des deux côtés dans la moitié de l''huile à feu vif ; le retirer.","Déglacer la poêle chaude avec le xérès en grattant les sucs, et verser le tout dans un pichet.","Baisser un peu le feu, ajouter le reste de l''huile avec le chorizo, l''oignon et l''ail, et cuire jusqu''à ce que l''oignon devienne translucide.","Remettre le xérès et le poulet avec le bouillon, les pois chiches, les poivrons, du sel et du poivre ; porter à frémissement.","Couvrir et cuire doucement environ 15 minutes jusqu''à ce que le poulet soit cuit à cœur.","Parsemer de persil haché."]},"it":{"title":"Pollo brasato allo sherry con chorizo e ceci","steps":["Eliminare il grasso in eccesso dalle sovracosce e tagliarle ciascuna in 2-3 pezzi.","Condire il pollo e rosolarlo su entrambi i lati in metà dell''olio a fuoco vivo; toglierlo dalla padella.","Sfumare la padella calda con lo sherry, raschiando il fondo di cottura, e versare il tutto in una caraffa.","Abbassare un po'' la fiamma, aggiungere il resto dell''olio con il chorizo, la cipolla e l''aglio e cuocere finché la cipolla non diventa trasparente.","Rimettere lo sherry e il pollo con il brodo, i ceci, i peperoni, sale e pepe; portare a sobbollire.","Coprire e cuocere dolcemente per circa 15 minuti finché il pollo non è cotto.","Completare con prezzemolo tritato."]}}'::jsonb),
  ('9a677bea-e590-4684-94e4-663476eb8ad3'::uuid, '{"fr":{"title":"Mafé de poulet","steps":["Faire suer l''oignon dans la moitié de l''huile environ 5 minutes, puis ajouter la patate douce et le poivron et cuire encore 10 minutes ; réserver.","Délayer au fouet le beurre de cacahuète dans le bouillon chaud jusqu''à obtenir un mélange lisse.","Cuire le riz selon les indications du paquet.","Faire chauffer le reste de l''huile et faire revenir le poulet avec l''ail, le gingembre, la coriandre moulue, le cumin et le piment environ 5 minutes, jusqu''à ce qu''il soit doré.","Remettre les légumes, verser le bouillon aux cacahuètes et laisser mijoter environ 20 minutes, jusqu''à ce que la sauce épaississe et que le poulet soit cuit à cœur.","Servir sur le riz, parsemé de feuilles de coriandre et de cacahuètes concassées."]},"it":{"title":"Stufato di pollo e arachidi dell''Africa occidentale","steps":["Far appassire la cipolla in metà dell''olio per circa 5 minuti, poi aggiungere la patata dolce e il peperone e cuocere altri 10 minuti; tenere da parte.","Stemperare il burro di arachidi nel brodo caldo con una frusta fino a ottenere un composto liscio.","Cuocere il riso seguendo le indicazioni della confezione.","Scaldare l''olio rimasto e rosolare il pollo con l''aglio, lo zenzero, il coriandolo in polvere, il cumino e il peperoncino per circa 5 minuti, finché non è dorato.","Rimettere le verdure, versare il brodo alle arachidi e cuocere a fuoco lento per circa 20 minuti, finché non si addensa e il pollo è cotto.","Servire sul riso, cosparso di foglie di coriandolo e arachidi tritate."]}}'::jsonb),
  ('a726112c-2fbf-49c6-b3bc-784875bbf69e'::uuid, '{"fr":{"title":"Çılbır (œufs à la turque au yaourt à l''ail)","steps":["Laisser le yaourt revenir à température ambiante (le sortir environ 30 minutes à l''avance).","Écraser l''ail avec une pincée de sel pour obtenir une pâte, l''incorporer au yaourt et étaler celui-ci dans deux assiettes.","Porter à ébullition une petite casserole d''eau salée additionnée du vinaigre.","Faire tourbillonner l''eau, y glisser un œuf et le pocher 2-3 minutes jusqu''à ce que le blanc soit pris mais que le jaune reste coulant ; recommencer avec le second.","Pendant ce temps, faire chauffer l''huile d''olive à feu doux à moyen, ajouter le pul biber, laisser infuser environ 30 secondes et retirer du feu.","Égoutter les œufs sur du papier absorbant, les déposer sur le yaourt, les arroser d''huile pimentée, saler et parsemer d''herbes.","Servir aussitôt avec du pain."]},"it":{"title":"Çılbır (uova alla turca con yogurt all''aglio)","steps":["Lasciare che lo yogurt arrivi a temperatura ambiente (tirarlo fuori dal frigo circa 30 minuti prima).","Schiacciare l''aglio con un pizzico di sale fino a ridurlo in pasta, mescolarlo allo yogurt e distribuirlo su due piatti.","Portare a bollore un pentolino di acqua salata con l''aceto.","Creare un vortice nell''acqua, farvi scivolare un uovo e cuocerlo in camicia per 2-3 minuti finché l''albume non si rapprende ma il tuorlo resta morbido; ripetere con il secondo.","Nel frattempo scaldare l''olio d''oliva a fuoco medio-basso, aggiungere il pul biber, lasciarlo in infusione per circa 30 secondi e togliere dal fuoco.","Scolare le uova su carta da cucina, adagiarle sullo yogurt, irrorarle con l''olio al peperoncino, salare e cospargere di erbe.","Servire subito con il pane."]}}'::jsonb),
  ('352bee18-6d6b-43cb-a91e-e71ac786c563'::uuid, '{"fr":{"title":"Adjaruli Khachapuri","steps":["Placer une pierre à pizza au milieu du four et préchauffer à 260 °C (500 °F) ; huiler un grand saladier.","Mélanger la levure, le sucre, l''huile, environ 80 ml d''eau tiède, la farine et le sel au crochet pétrisseur : 2-3 minutes à vitesse lente, puis 3-4 minutes à vitesse moyenne-lente, jusqu''à obtenir une pâte lisse et légèrement humide.","Mettre la pâte dans le saladier huilé, couvrir et laisser dans un endroit tiède 50-60 minutes, jusqu''à ce qu''elle ait presque doublé de volume.","Mélanger la mozzarella et la feta ; casser l''œuf dans une petite tasse en gardant le jaune entier.","Façonner la pâte en boule, couvrir sans serrer et laisser reposer 15 minutes.","Sur du papier cuisson fariné, étaler la pâte en un disque de 25 cm d''environ 3 mm d''épaisseur, répartir la moitié du fromage en laissant une petite bordure, rouler deux côtés opposés vers l''intérieur puis pincer et torsader les extrémités pour former une barque ; garnir le centre avec le reste du fromage.","Laisser reposer à découvert 15 minutes pour qu''elle gonfle légèrement, badigeonner les bords d''huile et la faire glisser sur la pierre chaude.","Cuire 14-16 minutes jusqu''à ce qu''elle soit légèrement dorée et le fromage fondu, verser l''œuf au centre et cuire encore 3-4 minutes jusqu''à ce que le blanc soit tout juste pris.","Parsemer de noisettes de beurre et servir chaud, en mélangeant l''œuf et le beurre au fromage à table."]},"it":{"title":"Adjaruli Khachapuri","steps":["Mettere una pietra refrattaria al centro del forno e preriscaldare a 260 °C (500 °F); ungere d''olio una ciotola capiente.","Impastare lievito, zucchero, olio, circa 80 ml di acqua tiepida, farina e sale con il gancio: 2-3 minuti a velocità bassa, poi 3-4 minuti a velocità medio-bassa, finché l''impasto non è liscio e leggermente umido.","Mettere l''impasto nella ciotola unta, coprire e lasciar lievitare in un luogo tiepido per 50-60 minuti, finché non è quasi raddoppiato.","Mescolare la mozzarella e la feta; rompere l''uovo in una tazzina, mantenendo il tuorlo intero.","Formare una palla con l''impasto, coprirla senza stringere e lasciar riposare 15 minuti.","Su carta da forno infarinata, stendere l''impasto in un disco di 25 cm spesso circa 3 mm, distribuire metà del formaggio lasciando un piccolo bordo, arrotolare verso l''interno due lati opposti e pizzicare e attorcigliare le estremità formando una barchetta; riempire il centro con il formaggio rimasto.","Lasciare scoperto per 15 minuti perché si gonfi leggermente, spennellare i bordi con l''olio e farlo scivolare sulla pietra calda.","Cuocere 14-16 minuti finché non è leggermente dorato e il formaggio è fuso, versare l''uovo al centro e cuocere altri 3-4 minuti finché l''albume non si è appena rappreso.","Distribuire il burro a pezzetti e servire caldo, mescolando a tavola l''uovo e il burro al formaggio."]}}'::jsonb),
  ('b4a417db-84c5-4375-9e34-ed701092ccaa'::uuid, '{"fr":{"title":"Poutine canadienne","steps":["Préparer la sauce brune selon les instructions du sachet et la maintenir chaude à feu doux.","Faire frire les frites dans l''huile à 350 °F (175 °C) jusqu''à ce qu''elles soient dorées et croustillantes.","Égoutter les frites sur une plaque tapissée de papier absorbant.","Répartir les frites dans les assiettes, parsemer de fromage en grains et napper de sauce chaude à la louche.","Déguster aussitôt, pendant que le fromage commence tout juste à fondre."]},"it":{"title":"Poutine canadese","steps":["Preparare la salsa gravy secondo le istruzioni della confezione e tenerla calda a fuoco basso.","Friggere le patatine in olio a 350 °F (175 °C) finché sono dorate e croccanti.","Scolare le patatine su un vassoio foderato di carta assorbente.","Disporre le patatine nei piatti, distribuirvi sopra la cagliata di formaggio a pezzetti e versare con un mestolo la salsa calda.","Mangiare subito, mentre la cagliata inizia appena a sciogliersi."]}}'::jsonb),
  ('292f619c-527e-4bce-8623-235114ca29bf'::uuid, '{"en":{"title":"Homemade croque-monsieur","steps":["Melt the butter in a saucepan, add the flour, then gradually pour in the milk while whisking to make a smooth béchamel.","Let it thicken, season with salt, pepper and nutmeg, then take off the heat.","Melt half the Emmental into the hot béchamel.","Butter one side of each slice of bread; on the unbuttered side of half the slices, spread a little béchamel, add the ham and a little cheese, then close the sandwiches.","Brown the sandwiches in a frying pan for 3 to 4 min on each side.","Place them on a baking tray lined with baking paper, coat with the rest of the béchamel and sprinkle with the remaining cheese.","Put under the grill for about 5 min until the top is golden and bubbling, and serve immediately with a salad."]},"it":{"title":"Croque-monsieur fatto in casa","steps":["Sciogliere il burro in un pentolino, aggiungere la farina, poi versare il latte poco alla volta mescolando con la frusta per ottenere una besciamella liscia.","Lasciare addensare, condire con sale, pepe e noce moscata, poi togliere dal fuoco.","Far sciogliere metà dell''emmental nella besciamella calda.","Imburrare un lato di ogni fetta di pane; sul lato non imburrato di metà delle fette spalmare un po'' di besciamella, adagiare il prosciutto cotto e un po'' di formaggio, poi chiudere.","Dorare i toast in padella per 3-4 min per lato.","Disporli su una teglia rivestita di carta forno, nappare con la besciamella rimasta e cospargere con il formaggio restante.","Passare sotto il grill per circa 5 min finché la superficie è gratinata e servire subito con un''insalata."]}}'::jsonb),
  ('6ca01774-0338-4521-8c4e-9940cb329731'::uuid, '{"fr":{"title":"Fish and chips","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Couper les pommes de terre, avec la peau, en grosses frites.","Blanchir les frites 2 à 3 minutes, bien les égoutter et les laisser sécher en laissant s''échapper la vapeur.","Les mélanger avec l''huile végétale dans un plat à rôtir et les cuire au four 25 à 30 minutes, en les retournant une fois, jusqu''à ce qu''elles soient dorées.","Environ 15 minutes avant la fin de cuisson des frites, chauffer l''huile d''olive dans une grande poêle à fond épais et fariner le cabillaud.","Faire cuire le cabillaud côté peau 4 à 5 minutes, le retourner et poursuivre la cuisson 5 à 6 minutes, jusqu''à ce qu''il commence tout juste à s''effeuiller (terminer les morceaux très épais 5 minutes au four) ; le disposer sur des assiettes chaudes.","Dans la même poêle, faire grésiller les cornichons et les câpres 1 minute, ajouter le jus de citron et laisser bouillonner 30 secondes à feu vif, puis retirer du feu et incorporer les herbes.","Garnir chaque filet d''une cuillerée de mayonnaise et du mélange aux câpres, et servir avec les frites."]},"it":{"title":"Fish and chips","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Tagliare le patate, con la buccia, a bastoncini spessi.","Sbollentare le patate 2-3 minuti, scolarle bene e lasciarle asciugare al vapore.","Condirle con l''olio di semi in una teglia e arrostirle 25-30 minuti, girandole una volta, finché sono dorate.","Circa 15 minuti prima che le patate siano pronte, scaldare l''olio d''oliva in una padella grande dal fondo spesso e infarinare il merluzzo.","Cuocere il merluzzo dal lato della pelle per 4-5 minuti, girarlo e cuocere altri 5-6 minuti finché inizia appena a sfaldarsi (terminare i pezzi molto spessi in forno per 5 minuti); trasferirlo su piatti caldi.","Nella stessa padella far sfrigolare i cetriolini e i capperi per 1 minuto, aggiungere il succo di limone e far bollire 30 secondi a fuoco vivo, poi togliere dal fuoco e unire le erbe.","Completare ogni filetto con un cucchiaio di maionese e il composto di capperi e servire con le patate."]}}'::jsonb),
  ('8bd9287e-0b96-4c35-8e0b-c23f0212da32'::uuid, '{"fr":{"title":"Poulet frit coréen (Yangnyeom-tongdak)","steps":["Chauffer environ 5 cm d''huile dans une cocotte à fond épais sur feu moyen-vif pendant 10 à 12 minutes, jusqu''à 165-175 °C ; un morceau de poulet test doit grésiller immédiatement.","Dans un grand saladier, mélanger les ailes à la main avec le sel, le poivre, la fécule, la farine, le bicarbonate et les œufs jusqu''à ce qu''elles soient uniformément enrobées.","Plonger le poulet dans l''huile morceau par morceau (en plusieurs fois si nécessaire) et frire environ 12 minutes, en retournant, jusqu''à ce qu''il soit doré et croustillant.","Déposer les ailes dans une passoire grillagée posée sur un saladier pour les égoutter.","Pour la sauce, chauffer l''huile dans une grande poêle, faire revenir l''ail environ 30 secondes jusqu''à ce qu''il soit légèrement doré, incorporer le ketchup, le sirop de riz, le gochujang et le vinaigre, puis laisser mijoter à feu doux jusqu''à ce que la sauce bouillonne et retirer du feu.","Laisser l''huile de friture remonter en température (environ 2 minutes) et frire les ailes une seconde fois environ 12 minutes, jusqu''à ce qu''elles soient bien croustillantes.","Refaire bouillonner la sauce sur feu moyen-vif, ajouter les ailes chaudes et mélanger jusqu''à ce qu''elles soient bien laquées.","Parsemer de graines de sésame et servir, idéalement avec du radis mariné."]},"it":{"title":"Pollo fritto coreano (Yangnyeom-tongdak)","steps":["Scaldare circa 5 cm di olio in una pentola dal fondo spesso a fuoco medio-alto per 10-12 minuti, fino a 165-175 °C; un pezzetto di pollo di prova deve sfrigolare subito.","In una ciotola capiente mescolare con le mani le ali con sale, pepe, fecola, farina, bicarbonato e uova finché sono ricoperte in modo uniforme.","Immergere il pollo nell''olio un pezzo alla volta (a più riprese se necessario) e friggere circa 12 minuti, girando, finché è dorato e croccante.","Trasferire le ali in un colino a rete appoggiato su una ciotola per farle sgocciolare.","Per la salsa, scaldare l''olio in una padella grande, soffriggere l''aglio circa 30 secondi finché è leggermente dorato, unire ketchup, sciroppo di riso, gochujang e aceto, poi cuocere a fuoco basso finché sobbolle e togliere dal fuoco.","Riportare l''olio di frittura in temperatura (circa 2 minuti) e friggere le ali una seconda volta per circa 12 minuti finché sono croccantissime.","Riportare la salsa a bollore a fuoco medio-alto, aggiungere le ali calde e saltarle finché sono lucide.","Cospargere di semi di sesamo e servire, possibilmente con ravanello in salamoia."]}}'::jsonb),
  ('42b2a8e9-670f-4c85-8abe-400bc2463633'::uuid, '{"en":{"title":"Green lasagne Bolognese","steps":["Heat the oil and butter in a saucepan and brown the mince over low heat for about 10 minutes.","Turn up the heat, pour in the white wine and let it evaporate completely.","Add the sieved peeled tomatoes and the basil, then cook for about 1 and a half hours with the lid ajar.","Meanwhile, cook the spinach in a covered pan for 5 minutes without seasoning, drain, let cool and squeeze well in a tea towel.","Blend the spinach, add the two flours, the egg, the yolk and a pinch of salt and knead into a dough; wrap in cling film and let rest for 30 minutes.","For the béchamel, melt the butter, toast the flour into a golden roux, then pour in the hot milk a little at a time, stirring; season with salt and nutmeg.","Roll the pasta out very thin (about half a millimetre) and cut into rectangles.","Blanch the sheets for 30 seconds in salted water with a drizzle of oil, cool them in cold water and dry them on a tea towel.","In a buttered baking dish, alternate pasta sheets, béchamel, ragù and Parmesan for 5 layers, finishing with béchamel and Parmesan.","Bake in a preheated oven at 170 °C for 40 minutes."]},"fr":{"title":"Lasagnes vertes à la bolognaise","steps":["Chauffer l''huile et le beurre dans une casserole et faire revenir la viande hachée à feu doux pendant environ 10 minutes.","Augmenter le feu, déglacer au vin blanc et le laisser s''évaporer complètement.","Ajouter les tomates pelées passées et le basilic, puis cuire environ 1 heure et demie avec le couvercle posé en biais.","Pendant ce temps, cuire les épinards dans une casserole couverte 5 minutes sans assaisonnement, les égoutter, les laisser refroidir et bien les essorer dans un torchon.","Mixer les épinards, ajouter les deux farines, l''œuf, le jaune et une pincée de sel et pétrir ; envelopper de film alimentaire et laisser reposer 30 minutes.","Pour la béchamel, faire fondre le beurre, faire blondir la farine jusqu''à obtenir un roux doré, puis verser le lait chaud en plusieurs fois en remuant ; saler et parfumer à la muscade.","Abaisser la pâte très finement (environ un demi-millimètre) et la découper en rectangles.","Blanchir les feuilles 30 secondes dans de l''eau salée avec un filet d''huile, les rafraîchir dans l''eau froide et les sécher sur un torchon.","Dans un plat beurré, alterner pâte, béchamel, sauce bolognaise et parmesan sur 5 couches, en terminant par béchamel et parmesan.","Enfourner dans le four préchauffé à 170 °C pendant 40 minutes."]}}'::jsonb),
  ('0d73508c-6359-434b-bd0d-9ba7e7c3440d'::uuid, '{"en":{"title":"Skillet aubergine parmigiana","steps":["Wash the aubergines, remove the stalk and slice them.","Place them in a colander, sprinkle with salt and leave to drain for about 1 hour.","Meanwhile, heat a tablespoon of oil with the passata and a little water, season with salt and cook over low heat for 10 minutes; add the basil and turn off the heat.","Rinse the aubergines and gently squeeze them.","Grill them a few at a time on a lightly oiled nonstick griddle until soft and marked.","In a 24 cm nonstick frying pan, alternate layers of aubergine, sauce, Parmesan and mozzarella until the ingredients are used up.","Cover and cook over medium-low heat for 20-25 minutes until the mozzarella has melted."]},"fr":{"title":"Parmigiana d''aubergines à la poêle","steps":["Laver les aubergines, retirer le pédoncule et les couper en tranches.","Les disposer dans une passoire, les saupoudrer de sel et les laisser dégorger environ 1 heure.","Pendant ce temps, chauffer une cuillère à soupe d''huile avec le coulis de tomate et un peu d''eau, saler et cuire à feu doux 10 minutes ; ajouter le basilic et éteindre le feu.","Rincer les aubergines et les presser délicatement.","Les griller quelques-unes à la fois sur une poêle-gril antiadhésive légèrement huilée jusqu''à ce qu''elles soient tendres et marquées.","Dans une poêle antiadhésive de 24 cm, alterner des couches d''aubergines, de sauce, de parmesan et de mozzarella jusqu''à épuisement des ingrédients.","Couvrir et cuire à feu moyen-doux 20 à 25 minutes, jusqu''à ce que la mozzarella soit fondue."]}}'::jsonb),
  ('ebf5318c-01b3-4cdd-98d9-9e16ab0442f6'::uuid, '{"fr":{"title":"Okonomiyaki aux crevettes","steps":["Fouetter ensemble le ketchup, la sauce Worcestershire, la sauce d''huître et le sucre pour obtenir la sauce okonomiyaki.","Mélanger la farine, la levure chimique et le sel dans un grand saladier, incorporer le bouillon et les œufs en battant, puis ajouter délicatement le chou et la plus grande partie des oignons nouveaux.","Chauffer la moitié de l''huile dans une poêle antiadhésive munie d''un couvercle sur feu moyen et y verser à la cuillère la moitié de la pâte en un disque épais d''environ 15 cm de diamètre ; ne pas l''aplatir.","Enfoncer la moitié des crevettes sur le dessus, couvrir et cuire 3 à 5 minutes, jusqu''à ce que la galette soit prise et dorée en dessous.","Retourner, couvrir à nouveau et cuire encore 3 à 5 minutes, jusqu''à ce qu''elle soit dorée et cuite à cœur ; prolonger d''une minute de chaque côté si nécessaire.","Faire glisser sur une assiette, arroser de mayonnaise et de sauce, parsemer d''oignons nouveaux et servir avec le gingembre mariné.","Recommencer avec le reste d''huile, de pâte et de crevettes pour la deuxième galette."]},"it":{"title":"Okonomiyaki di gamberi","steps":["Mescolare con una frusta ketchup, salsa Worcestershire, salsa d''ostriche e zucchero per ottenere la salsa okonomiyaki.","Riunire farina, lievito e sale in una ciotola capiente, incorporare sbattendo il brodo e le uova, poi unire delicatamente il cavolo e gran parte dei cipollotti.","Scaldare metà dell''olio in una padella antiaderente con coperchio a fuoco medio e versarvi a cucchiaiate metà della pastella formando un disco spesso di circa 15 cm di diametro; non schiacciarlo.","Affondare metà dei gamberi sulla superficie, coprire e cuocere 3-5 minuti finché è rappreso e dorato sotto.","Girare, coprire di nuovo e cuocere altri 3-5 minuti finché è dorato e cotto all''interno; se necessario, prolungare di un minuto per lato.","Farlo scivolare su un piatto, condire con un filo di maionese e di salsa, cospargere di cipollotti e servire con lo zenzero marinato.","Ripetere con l''olio, la pastella e i gamberi rimasti per la seconda frittella."]}}'::jsonb),
  ('badc30ce-6a6a-450a-9bcf-5e4afcf32573'::uuid, '{"fr":{"title":"Rösti aux œufs au plat","steps":["Râper grossièrement les pommes de terre, crues ou cuites et refroidies.","Couper finement en dés la moitié de l''oignon et l''incorporer aux pommes de terre, en assaisonnant si on le souhaite.","Faire fondre du beurre dans une grande poêle à feu vif, ajouter le mélange de pommes de terre et remuer quelques minutes jusqu''à ce qu''il soit bien chaud.","Baisser à feu moyen-vif et presser le mélange en une galette ronde et plate d''environ 1 à 1,5 cm d''épaisseur.","Glisser un peu de beurre supplémentaire sur le pourtour et cuire 5 à 10 minutes, jusqu''à ce qu''une croûte se forme en dessous.","Pendant ce temps, couper en dés le reste de l''oignon et la carotte et les cuire à la vapeur avec les petits pois (ou les épinards) dans un peu d''eau, à couvert.","Retourner le rösti sur une assiette, le faire glisser de nouveau dans la poêle et le cuire à feu moyen-doux jusqu''à ce que la deuxième face soit croustillante.","Retirer le rösti, faire cuire les œufs au plat dans la même poêle et les servir dessus, avec les légumes à côté."]},"it":{"title":"Rösti con uova al tegamino","steps":["Grattugiare grossolanamente le patate, crude oppure lessate e raffreddate.","Tritare finemente metà della cipolla e unirla alle patate, condendo a piacere.","Sciogliere il burro in una padella grande a fuoco vivo, aggiungere il composto di patate e mescolare per qualche minuto finché è ben caldo.","Abbassare a fuoco medio-alto e pressare il composto in un disco piatto spesso circa 1-1,5 cm.","Far scivolare ancora un po'' di burro lungo il bordo e cuocere 5-10 minuti finché sotto si forma una crosticina.","Nel frattempo tagliare a dadini la cipolla rimasta e la carota e cuocerle al vapore con i piselli (o gli spinaci) in poca acqua con il coperchio.","Rovesciare il rösti su un piatto, farlo scivolare di nuovo nella padella e cuocere a fuoco medio-basso finché anche il secondo lato è croccante.","Togliere il rösti, cuocere le uova al tegamino nella stessa padella e servirle sopra, con le verdure a parte."]}}'::jsonb),
  ('72695646-987b-4eed-9407-29049d511fea'::uuid, '{"en":{"title":"Traditional tartiflette","steps":["Fry the sliced onion and chopped garlic in a drizzle of oil until translucent, then set aside.","Brown the lardons in the same pan, return the onion and garlic, then deglaze with the white wine.","Let the wine evaporate completely, transfer to a bowl and stir in the crème fraîche, salt, pepper and nutmeg.","Put the peeled potatoes in cold salted water and cook for about 15 min: they should stay slightly firm.","Cut the potatoes into thin slices.","Rub a buttered gratin dish with garlic, then alternate layers of potato and the lardon mixture.","Scrape the rind of the reblochon, cut it into pieces and lay them rind-side up on top.","Bake at 180 °C for 30 to 35 min, until the cheese is melted and golden, and serve piping hot."]},"it":{"title":"Tartiflette tradizionale","steps":["Soffriggere la cipolla affettata e l''aglio tritato in un filo d''olio finché diventano traslucidi, poi tenerli da parte.","Rosolare la pancetta nella stessa padella, rimettere cipolla e aglio, poi sfumare con il vino bianco.","Lasciare evaporare completamente il vino, versare in una ciotola e incorporare la panna, il sale, il pepe e la noce moscata.","Mettere le patate sbucciate in acqua fredda salata e cuocerle circa 15 min: devono rimanere un po'' sode.","Tagliare le patate a rondelle sottili.","Strofinare una pirofila imburrata con l''aglio, poi alternare strati di patate e di composto di pancetta.","Raschiare la crosta del reblochon, tagliarlo a pezzi e adagiarli sopra con la crosta rivolta verso l''alto.","Infornare a 180 °C per 30-35 min, finché il formaggio è fuso e dorato, e servire ben caldo."]}}'::jsonb),
  ('44f8d889-4d68-471f-a12e-050437c6f2d4'::uuid, '{"fr":{"title":"Poulet street food new-yorkais sur riz","steps":["Mélanger le poulet avec le cumin, la coriandre moulue, l''origan, la moitié du curcuma, 1 gousse d''ail, le jus d''un demi-citron, 1 c. à soupe d''huile, du sel et du poivre. Laisser reposer 10 min.","Rincer le riz. Le faire revenir 1 min dans un peu d''huile avec le reste du curcuma, ajouter le bouillon, couvrir et laisser mijoter 12 min ; laisser reposer 5 min hors du feu.","Pendant ce temps, cuire le poulet dans une poêle chaude avec un peu d''huile, 5 à 6 min de chaque côté, jusqu''à ce qu''il soit grillé et cuit à cœur. Laisser reposer, puis le couper en bouchées.","Mélanger le yaourt, la mayonnaise, le vinaigre, le reste de l''ail, un filet de citron, du sel et du poivre pour préparer la sauce blanche.","Servir le riz garni de poulet, de laitue et de tomate, arrosé de sauce blanche et de sauce piquante."]},"it":{"title":"Pollo street food newyorkese con riso","steps":["Condire il pollo con cumino, coriandolo in polvere, origano, metà della curcuma, 1 spicchio d''aglio, il succo di mezzo limone, 1 cucchiaio d''olio, sale e pepe. Lasciare riposare 10 min.","Sciacquare il riso. Tostarlo 1 min in un filo d''olio con la curcuma rimasta, aggiungere il brodo, coprire e cuocere a fuoco lento 12 min; lasciare riposare 5 min fuori dal fuoco.","Nel frattempo cuocere il pollo in una padella ben calda con un filo d''olio, 5-6 min per lato, finché è abbrustolito e cotto all''interno. Lasciarlo riposare, poi tagliarlo a bocconcini.","Mescolare lo yogurt, la maionese, l''aceto, l''aglio rimasto, una spruzzata di limone, sale e pepe per preparare la salsa bianca.","Servire il riso con sopra il pollo, la lattuga e il pomodoro, condito con la salsa bianca e la salsa piccante."]}}'::jsonb),
  ('83f42f74-df4c-4c45-be95-fa38674d1b1c'::uuid, '{"fr":{"title":"Bol de riz au saumon gochujang","steps":["Cuire le riz selon les instructions du paquet.","Mélanger le concombre avec le vinaigre de riz, une pincée de sel et une pincée de sucre ; réserver pour le faire mariner rapidement.","Mélanger le gochujang, la sauce soja, le miel et l''huile de sésame. Enrober le saumon avec la moitié du mélange.","Cuire les edamames 3 min dans l''eau bouillante, puis les égoutter.","Saisir le saumon dans une poêle chaude avec un peu d''huile 3 à 4 min en le retournant, puis ajouter le reste du glaçage et mélanger 30 s jusqu''à ce qu''il soit bien laqué.","Garnir les bols de riz, de saumon, de concombre, d''edamames et de carotte. Parsemer d''oignon nouveau et de graines de sésame."]},"it":{"title":"Ciotola di riso con salmone al gochujang","steps":["Cuocere il riso secondo le istruzioni della confezione.","Condire il cetriolo con l''aceto di riso, un pizzico di sale e un pizzico di zucchero; tenere da parte per una marinatura veloce.","Mescolare gochujang, salsa di soia, miele e olio di sesamo. Condire il salmone con metà della salsa.","Cuocere gli edamame in acqua bollente per 3 min, poi scolarli.","Scottare il salmone in una padella ben calda con un filo d''olio per 3-4 min, girandolo, poi aggiungere la glassa rimasta e saltare 30 s finché è ben laccato.","Riempire le ciotole con riso, salmone, cetriolo, edamame e carota. Completare con cipollotto e semi di sesamo."]}}'::jsonb),
  ('6f72d2b5-6a40-4b91-bf03-6c6a3cb4b4fb'::uuid, '{"fr":{"title":"Pasta e ceci","steps":["Faire revenir doucement l''oignon dans 2 c. à soupe d''huile d''olive pendant 5 min. Ajouter l''ail, le romarin et le piment pendant 1 min, puis incorporer le concentré de tomate.","Ajouter les pois chiches et le bouillon et laisser mijoter 10 min. Retirer le romarin et écraser ou mixer environ un tiers des pois chiches pour épaissir.","Ajouter les pâtes et les cuire dans la soupe, en remuant souvent, jusqu''à ce qu''elles soient al dente (ajouter un peu d''eau si cela devient trop épais).","Assaisonner, puis servir avec le parmesan, du poivre noir et un filet d''huile d''olive."]},"it":{"title":"Pasta e ceci","steps":["Soffriggere dolcemente la cipolla in 2 cucchiai d''olio d''oliva per 5 min. Aggiungere aglio, rosmarino e peperoncino per 1 min, poi incorporare il concentrato di pomodoro.","Unire i ceci e il brodo e cuocere a fuoco lento 10 min. Togliere il rosmarino e schiacciare o frullare circa un terzo dei ceci per addensare.","Aggiungere la pasta e cuocerla nella minestra, mescolando spesso, finché è al dente (aggiungere un goccio d''acqua se diventa troppo densa).","Regolare di sale, poi servire con il parmigiano, pepe nero e un filo d''olio d''oliva."]}}'::jsonb),
  ('921fc083-e3e0-43a0-a015-814ba0a3fa48'::uuid, '{"fr":{"title":"Poulet basquaise","steps":["Assaisonner le poulet et le faire dorer côté peau dans un peu d''huile dans une cocotte, 6 à 7 min, puis le retourner 2 min. Réserver.","Dans la même cocotte, faire revenir l''oignon, les poivrons et le jambon 8 min jusqu''à ce qu''ils soient tendres. Ajouter l''ail et le piment d''Espelette pendant 1 min.","Déglacer au vin, puis ajouter les tomates, le laurier et le thym. Remettre le poulet, peau vers le haut.","Couvrir et laisser mijoter doucement 25 min, puis découvrir pendant les 5 dernières minutes pour faire épaissir la sauce.","Pendant ce temps, cuire le riz. Servir le poulet et les poivrons sur le riz."]},"it":{"title":"Pollo alla basca","steps":["Salare e pepare il pollo e rosolarlo dal lato della pelle in un filo d''olio in una casseruola, 6-7 min, poi girarlo per 2 min. Tenere da parte.","Nella stessa casseruola cuocere la cipolla, i peperoni e il prosciutto per 8 min finché sono morbidi. Aggiungere l''aglio e il peperoncino di Espelette per 1 min.","Sfumare con il vino, poi aggiungere i pomodori, l''alloro e il timo. Rimettere il pollo con la pelle verso l''alto.","Coprire e cuocere a fuoco lento 25 min, poi scoprire negli ultimi 5 min per far addensare il sugo.","Nel frattempo cuocere il riso. Servire il pollo e i peperoni sul riso."]}}'::jsonb),
  ('7375c699-23ee-487c-9121-73adc3d46728'::uuid, '{"fr":{"title":"Shawarma de poulet au four","steps":["Préchauffer le four à 220 °C. Mélanger les épices, 2 gousses d''ail, le jus d''un demi-citron, 2 c. à soupe d''huile et du sel.","Enrober le poulet et les quartiers d''oignon de marinade et les étaler en une seule couche sur une plaque.","Rôtir 25 à 30 min, jusqu''à ce que le poulet soit grillé sur les bords. Laisser reposer 5 min, puis trancher.","Mélanger le yaourt avec le reste de l''ail, un filet de citron et du sel.","Mélanger la tomate, le concombre et le persil avec du jus de citron et de l''huile. Servir le poulet et les oignons avec les pains pita, le yaourt à l''ail et la salade."]},"it":{"title":"Shawarma di pollo in teglia","steps":["Scaldare il forno a 220 °C. Mescolare le spezie, 2 spicchi d''aglio, il succo di mezzo limone, 2 cucchiai d''olio e sale.","Condire il pollo e gli spicchi di cipolla con la marinata e distribuirli su una teglia in un solo strato.","Arrostire 25-30 min finché il pollo è abbrustolito ai bordi. Lasciare riposare 5 min, poi affettare.","Mescolare lo yogurt con l''aglio rimasto, una spruzzata di limone e sale.","Condire pomodoro, cetriolo e prezzemolo con succo di limone e olio. Servire il pollo e le cipolle con il pane pita, lo yogurt all''aglio e l''insalata."]}}'::jsonb),
  ('7ccb7672-07ff-4746-b7b9-165af1682c26'::uuid, '{"fr":{"title":"Tacos de dinde en feuilles de laitue","steps":["Faire revenir l''oignon dans 1 c. à café d''huile pendant 3 min. Ajouter la dinde et la faire dorer en l''émiettant, 5 à 6 min.","Incorporer l''ail, le chipotle, le cumin, le paprika et le concentré de tomate pendant 1 min, puis ajouter les haricots et un peu d''eau. Laisser mijoter 2 min jusqu''à obtenir une texture nappante.","Assaisonner de sel et du jus d''un demi-citron vert.","Répartir la garniture dans les feuilles de laitue et garnir de tomate, d''avocat, de yaourt, de coriandre et de quartiers de citron vert."]},"it":{"title":"Tacos di tacchino in foglie di lattuga","steps":["Soffriggere la cipolla in 1 cucchiaino d''olio per 3 min. Aggiungere il tacchino e rosolarlo sgranandolo, 5-6 min.","Unire aglio, chipotle, cumino, paprika e concentrato di pomodoro per 1 min, poi aggiungere i fagioli e un goccio d''acqua. Cuocere a fuoco lento 2 min finché si forma un sughetto.","Insaporire con sale e il succo di mezzo lime.","Distribuire il ripieno nelle foglie di lattuga e completare con pomodoro, avocado, yogurt, coriandolo e spicchi di lime."]}}'::jsonb),
  ('d31d3553-44c2-493a-ae47-a5ef771dfc03'::uuid, '{"fr":{"title":"Chana masala","steps":["Lancer la cuisson du riz selon les instructions du paquet.","Chauffer 2 c. à soupe d''huile et faire grésiller les graines de cumin 30 s. Ajouter l''oignon et cuire 8 min jusqu''à ce qu''il soit doré.","Ajouter l''ail, le gingembre et le piment pendant 1 min, puis les épices moulues pendant 30 s.","Ajouter les tomates et cuire 5 min jusqu''à ce que la sauce épaississe, puis les pois chiches et 150 ml d''eau. Laisser mijoter 10 min en écrasant légèrement quelques pois chiches.","Assaisonner de sel et de jus de citron, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Chana masala","steps":["Mettere a cuocere il riso secondo le istruzioni della confezione.","Scaldare 2 cucchiai d''olio e far sfrigolare i semi di cumino per 30 s. Aggiungere la cipolla e cuocere 8 min finché è dorata.","Aggiungere aglio, zenzero e peperoncino per 1 min, poi le spezie in polvere per 30 s.","Unire i pomodori e cuocere 5 min finché si addensano, poi i ceci e 150 ml d''acqua. Cuocere a fuoco lento 10 min, schiacciando leggermente una parte dei ceci.","Insaporire con sale e succo di limone, cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('bfa142e0-6a9e-458a-b320-536bf8aa8e76'::uuid, '{"fr":{"title":"Donburi de poulet teriyaki","steps":["Cuire le riz. Mélanger la sauce soja, le mirin, le saké et le sucre.","Cuire le brocoli à la vapeur ou à l''eau 3 à 4 min.","Cuire le poulet côté peau dans un peu d''huile à feu moyen 7 min jusqu''à ce qu''il soit croustillant, puis le retourner et poursuivre la cuisson 4 min.","Retirer l''excédent de graisse, verser la sauce et laisser mijoter 1 à 2 min en retournant le poulet jusqu''à ce qu''il soit bien laqué.","Trancher le poulet et le servir sur le riz avec le brocoli, un peu plus de sauce, l''oignon nouveau et le sésame."]},"it":{"title":"Donburi di pollo teriyaki","steps":["Cuocere il riso. Mescolare salsa di soia, mirin, sake e zucchero.","Cuocere i broccoli al vapore o lessarli per 3-4 min.","Cuocere il pollo dal lato della pelle in un filo d''olio a fuoco medio per 7 min finché è croccante, poi girarlo e cuocere altri 4 min.","Eliminare il grasso in eccesso, versare la salsa e cuocere a fuoco lento 1-2 min, girando il pollo finché è lucido.","Affettare il pollo e servirlo sul riso con i broccoli, altra salsa, il cipollotto e il sesamo."]}}'::jsonb),
  ('cf55fbb6-d6f4-4ed9-a1f1-b5675ef81fa4'::uuid, '{"fr":{"title":"Shakshuka à la feta","steps":["Faire revenir l''oignon et le poivron dans 2 c. à soupe d''huile d''olive pendant 8 min jusqu''à ce qu''ils soient tendres.","Ajouter l''ail et les épices pendant 1 min, puis les tomates. Laisser mijoter 6 à 8 min jusqu''à épaississement ; assaisonner.","Creuser 5 puits dans la sauce et y casser les œufs. Couvrir et cuire à feu doux 5 à 7 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer de feta et de persil et servir directement dans la poêle avec du pain."]},"it":{"title":"Shakshuka con feta","steps":["Cuocere la cipolla e il peperone in 2 cucchiai d''olio d''oliva per 8 min finché sono morbidi.","Aggiungere aglio e spezie per 1 min, poi i pomodori. Cuocere a fuoco lento 6-8 min finché il sugo si addensa; regolare di sale e pepe.","Formare 5 incavi nel sugo e rompervi dentro le uova. Coprire e cuocere a fuoco basso 5-7 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere di feta e prezzemolo e servire direttamente nella padella con il pane."]}}'::jsonb),
  ('22aa9226-5726-4893-ab82-6cb10720509d'::uuid, '{"fr":{"title":"Sauté de bœuf au brocoli","steps":["Cuire le riz. Mélanger le bœuf avec 1 c. à café de fécule de maïs et 1 c. à soupe de sauce soja.","Préparer la sauce : 2 c. à soupe de sauce soja, la sauce d''huître, le sucre, l''huile de sésame, 1 c. à café de fécule de maïs et 80 ml d''eau.","Chauffer un wok jusqu''à ce qu''il fume, ajouter 1 c. à soupe d''huile et saisir le bœuf en une seule couche, 1 à 2 min, sans trop le cuire. Le retirer.","Ajouter un peu d''huile, le brocoli et 2 c. à soupe d''eau ; faire sauter 3 min jusqu''à ce qu''il soit bien vert et juste tendre. Ajouter l''ail et le gingembre pendant 30 s.","Remettre le bœuf, verser la sauce et mélanger 1 min jusqu''à ce que ce soit bien brillant. Servir sur le riz."]},"it":{"title":"Manzo e broccoli saltati al wok","steps":["Cuocere il riso. Condire il manzo con 1 cucchiaino di amido di mais e 1 cucchiaio di salsa di soia.","Preparare la salsa: 2 cucchiai di salsa di soia, salsa d''ostriche, zucchero, olio di sesamo, 1 cucchiaino di amido di mais e 80 ml d''acqua.","Scaldare il wok finché fuma, aggiungere 1 cucchiaio d''olio e scottare il manzo in un solo strato, 1-2 min, senza cuocerlo troppo. Toglierlo.","Aggiungere un filo d''olio, i broccoli e 2 cucchiai d''acqua; saltare 3 min finché sono di un verde brillante e appena teneri. Aggiungere aglio e zenzero per 30 s.","Rimettere il manzo, versare la salsa e saltare 1 min finché è lucido. Servire sul riso."]}}'::jsonb),
  ('438ce1d6-39d6-46b8-b1b4-8358a3a7e801'::uuid, '{"fr":{"title":"Médaillons de porc à la normande, purée","steps":["Couper les pommes de terre en morceaux, les couvrir d''eau froide salée, porter à ébullition et cuire 20 min, jusqu''à ce que la pointe d''un couteau s''y enfonce facilement.","Pendant ce temps, saler et poivrer le porc. Chauffer l''huile et 10 g de beurre dans une grande poêle à feu moyen-vif et saisir les médaillons 3 min de chaque côté jusqu''à ce qu''ils soient dorés ; réserver sur une assiette.","Évider les pommes et couper chacune en 8 quartiers. Les cuire dans la même poêle avec 10 g de beurre 4 à 5 min en les retournant, jusqu''à ce que les bords dorent ; les ajouter au porc.","Faire fondre l''échalote 2 min dans la poêle, puis verser le cidre et décoller les sucs. Faire bouillir 3 min, jusqu''à réduction de moitié.","Incorporer la crème fraîche, la moutarde et les feuilles de thym et laisser frémir 1 min. Remettre le porc, les pommes et leur jus et mijoter doucement 3 à 4 min en retournant, jusqu''à ce que le porc soit juste cuit (à peine rosé à cœur).","Égoutter les pommes de terre et les écraser avec le reste du beurre et le lait chaud ; saler et poivrer.","Servir les médaillons et les pommes sur la purée, nappés de sauce au cidre."]},"it":{"title":"Medaglioni di maiale alla normanna con purè","steps":["Tagliare le patate a pezzi, coprirle con acqua fredda salata, portare a bollore e cuocere 20 min, finché la punta di un coltello entra facilmente.","Nel frattempo salare e pepare il maiale. Scaldare l''olio e 10 g di burro in una padella larga a fuoco medio-alto e rosolare i medaglioni 3 min per lato finché sono dorati; tenerli da parte su un piatto.","Togliere il torsolo alle mele e tagliare ciascuna in 8 spicchi. Cuocerli nella stessa padella con 10 g di burro per 4-5 min, girandoli, finché i bordi sono dorati; unirli al maiale.","Far appassire lo scalogno nella padella per 2 min, poi versare il sidro e staccare il fondo di cottura. Far bollire 3 min, finché si riduce della metà.","Incorporare la crème fraîche, la senape e le foglie di timo e sobbollire 1 min. Rimettere il maiale, le mele e il loro sugo e cuocere dolcemente 3-4 min, girando, finché il maiale è appena cotto (leggermente rosato al centro).","Scolare le patate e schiacciarle con il burro rimasto e il latte caldo; salare e pepare.","Servire i medaglioni e le mele sul purè, irrorati con la salsa al sidro."]}}'::jsonb),
  ('733a1520-f3d1-47af-9be0-d422b48b2c69'::uuid, '{"fr":{"title":"Salade tiède de lentilles, betterave et chèvre","steps":["Torréfier les noix à sec dans la casserole à feu moyen 2 à 3 min, jusqu''à ce qu''elles embaument ; les réserver.","Rincer les lentilles, les mettre dans la même casserole avec le laurier et le thym, couvrir de trois fois leur volume d''eau froide et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres mais encore entières. Saler en fin de cuisson.","Pendant ce temps, fouetter la moutarde, le vinaigre, le sel et le poivre, puis incorporer l''huile en fouettant et ajouter l''échalote.","Égoutter les lentilles, retirer les herbes et les mélanger encore tièdes avec les deux tiers de la vinaigrette. Laisser reposer 5 min pour qu''elles s''imprègnent.","Mélanger la betterave avec le reste de vinaigrette dans un autre bol pour qu''elle ne colore pas les lentilles.","Disposer la roquette dans les assiettes, ajouter les lentilles tièdes et la betterave, puis émietter le chèvre par-dessus et parsemer de noix et de persil. Servir tiède avec les tranches de baguette grillées."]},"it":{"title":"Insalata tiepida di lenticchie, barbabietola e caprino","steps":["Tostare le noci a secco nel pentolino a fuoco medio per 2-3 min, finché sono profumate; metterle da parte.","Sciacquare le lenticchie, metterle nello stesso pentolino con l''alloro e il timo, coprirle con tre volte il loro volume di acqua fredda e cuocere a fuoco lento 20-25 min, finché sono tenere ma ancora intere. Salare a fine cottura.","Nel frattempo sbattere la senape, l''aceto, il sale e il pepe, poi incorporare l''olio sbattendo e aggiungere lo scalogno.","Scolare le lenticchie, togliere le erbe e condirle ancora tiepide con due terzi della vinaigrette. Lasciarle riposare 5 min perché si insaporiscano.","Condire la barbabietola con il resto della vinaigrette in un''altra ciotola, così non colora le lenticchie.","Disporre la rucola nei piatti, aggiungere le lenticchie tiepide e la barbabietola, poi sbriciolare sopra il caprino e cospargere di noci e prezzemolo. Servire tiepido con le fette di baguette tostate."]}}'::jsonb),
  ('01e7604e-bc71-4e31-9a4f-180475fe8ddb'::uuid, '{"fr":{"title":"Truite poêlée, lentilles à la moutarde","steps":["Rincer les lentilles et les mettre dans une casserole avec la carotte, la moitié de l''échalote et le laurier. Couvrir de 3 cm d''eau froide et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres. Égoutter en gardant 3 c. à soupe d''eau de cuisson.","Remettre les lentilles dans la casserole à feu doux avec le reste de l''échalote, les deux moutardes, le vinaigre, la crème fraîche et l''eau réservée. Ajouter les épinards et remuer jusqu''à ce qu''ils tombent, environ 1 min ; assaisonner et garder au chaud.","Sécher la truite, inciser légèrement la peau et assaisonner des deux côtés.","Chauffer l''huile dans une poêle à feu moyen-vif. Poser les filets côté peau, les presser 10 s et cuire 3 à 4 min, jusqu''à ce que la peau soit croustillante et la chair opaque aux deux tiers.","Retourner les filets, ajouter le beurre et cuire encore 1 min en arrosant.","Répartir les lentilles dans les assiettes, poser la truite dessus et servir avec des quartiers de citron et de l''aneth."]},"it":{"title":"Trota in padella con lenticchie alla senape","steps":["Sciacquare le lenticchie e metterle in un pentolino con la carota, metà dello scalogno e l''alloro. Coprire con 3 cm di acqua fredda e cuocere a fuoco lento 20-25 min, finché sono tenere. Scolare tenendo da parte 3 cucchiai di acqua di cottura.","Rimettere le lenticchie nel pentolino a fuoco basso con il resto dello scalogno, le due senapi, l''aceto, la crème fraîche e l''acqua tenuta da parte. Aggiungere gli spinaci e mescolare finché appassiscono, circa 1 min; regolare di sale e pepe e tenere in caldo.","Asciugare la trota, incidere leggermente la pelle e condire da entrambi i lati.","Scaldare l''olio in una padella a fuoco medio-alto. Adagiare i filetti dal lato della pelle, premerli per 10 s e cuocere 3-4 min, finché la pelle è croccante e la carne è opaca per due terzi.","Girare i filetti, aggiungere il burro e cuocere ancora 1 min, irrorandoli.","Distribuire le lenticchie nei piatti, adagiarvi la trota e servire con spicchi di limone e aneto."]}}'::jsonb),
  ('a28a8bc9-457a-4379-b12a-e0367cc7a7cc'::uuid, '{"fr":{"title":"Poulet aux poireaux et champignons","steps":["Cuire le riz dans une casserole d''eau bouillante salée 12 min (ou selon le paquet), puis l''égoutter.","Saler et poivrer le poulet. Le faire dorer dans l''huile dans une grande sauteuse à feu moyen-vif 5 à 6 min, jusqu''à ce qu''il soit doré de tous côtés ; réserver.","Mettre le beurre et les champignons dans la sauteuse et cuire 4 à 5 min à feu vif, jusqu''à ce que leur eau soit évaporée et qu''ils colorent.","Ajouter les poireaux, l''ail, le thym et une pincée de sel et cuire à feu moyen 6 à 8 min, jusqu''à ce qu''ils soient fondants sans colorer.","Verser le vin et faire bouillir 1 min, puis ajouter le bouillon et le poulet. Couvrir et laisser mijoter 10 min, jusqu''à ce que le poulet soit cuit à cœur.","Incorporer la crème fraîche et la moutarde et laisser frémir 2 min à découvert, jusqu''à ce que la sauce nappe la cuillère. Rectifier l''assaisonnement.","Servir avec le riz, parsemé de persil."]},"it":{"title":"Pollo con porri e funghi","steps":["Cuocere il riso in una pentola di acqua bollente salata per 12 min (o secondo la confezione), poi scolarlo.","Salare e pepare il pollo. Rosolarlo nell''olio in una padella larga e alta a fuoco medio-alto per 5-6 min, finché è dorato su tutti i lati; tenerlo da parte.","Mettere nella padella il burro e i funghi e cuocere 4-5 min a fuoco vivo, finché la loro acqua è evaporata e prendono colore.","Aggiungere i porri, l''aglio, il timo e un pizzico di sale e cuocere a fuoco medio 6-8 min, finché sono morbidi ma non coloriti.","Versare il vino e far bollire 1 min, poi aggiungere il brodo e il pollo. Coprire e cuocere a fuoco lento 10 min, finché il pollo è cotto all''interno.","Incorporare la crème fraîche e la senape e sobbollire senza coperchio per 2 min, finché la salsa vela il cucchiaio. Regolare di sale e pepe.","Servire con il riso, cosparso di prezzemolo."]}}'::jsonb),
  ('37a05a33-7df2-470d-aa32-2ffa85f7c61c'::uuid, '{"fr":{"title":"Tarte feuilletée à la ratatouille, salade verte","steps":["Chauffer 2 c. à soupe d''huile dans une grande poêle et faire fondre l''oignon 5 min à feu moyen ; ajouter l''ail 1 min.","Ajouter l''aubergine et le poivron et cuire 8 min à feu moyen-vif en remuant souvent.","Ajouter la courgette, les tomates, les herbes de Provence et le sel et cuire à découvert 10 à 12 min, jusqu''à ce que tout soit tendre et que le jus se soit évaporé ; une ratatouille bien sèche garde la pâte croustillante. Laisser tiédir.","Préchauffer le four à 200 °C. Foncer un moule à tarte de 20 à 22 cm avec la pâte, piquer le fond à la fourchette et le badigeonner de moutarde.","Battre les œufs avec le lait, la moitié de l''emmental, du sel et du poivre.","Étaler la ratatouille sur le fond de tarte, verser l''appareil aux œufs et parsemer du reste de fromage.","Enfourner 30 à 35 min, jusqu''à ce que la pâte soit bien dorée et la garniture juste prise au centre. Laisser reposer 5 min.","Assaisonner la salade avec le vinaigre, le reste d''huile et une pincée de sel, et la servir avec la tarte parsemée de basilic déchiré."]},"it":{"title":"Torta di sfoglia alla ratatouille con insalata verde","steps":["Scaldare 2 cucchiai di olio in una padella larga e far appassire la cipolla per 5 min a fuoco medio; aggiungere l''aglio per 1 min.","Aggiungere la melanzana e il peperone e cuocere 8 min a fuoco medio-alto, mescolando spesso.","Aggiungere la zucchina, i pomodori, le erbe di Provenza e il sale e cuocere senza coperchio 10-12 min, finché tutto è tenero e il liquido è evaporato; una ratatouille asciutta mantiene croccante la sfoglia. Lasciare intiepidire.","Scaldare il forno a 200 °C. Foderare uno stampo da crostata di 20-22 cm con la sfoglia, bucherellare il fondo con una forchetta e spalmarlo di senape.","Sbattere le uova con il latte, metà dell''emmental, sale e pepe.","Distribuire la ratatouille nel guscio di pasta, versare il composto di uova e cospargere con il formaggio rimasto.","Cuocere in forno 30-35 min, finché la sfoglia è ben dorata e il ripieno è appena rappreso al centro. Lasciare riposare 5 min.","Condire l''insalata con l''aceto, l''olio rimasto e un pizzico di sale e servirla con la torta, completata con basilico spezzettato."]}}'::jsonb),
  ('912fa9d1-a5c7-4e51-9ba9-94e7b79e82ca'::uuid, '{"fr":{"title":"Truite aux amandes, haricots verts et pommes de terre","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau bouillante salée, en ajoutant les haricots verts pour les 6 dernières minutes. Égoutter, couper les pommes de terre en deux et garder le tout au chaud dans la casserole.","Saler et poivrer la truite et fariner les filets en tapotant pour ôter l''excédent.","Chauffer l''huile et 10 g de beurre dans une grande poêle à feu moyen-vif. Cuire les filets côté peau 3 min, jusqu''à ce qu''elle soit croustillante, puis les retourner et cuire encore 1 à 2 min. Les déposer dans des assiettes chaudes.","Essuyer la poêle, ajouter le reste du beurre à feu moyen et, quand il mousse, ajouter les amandes. Remuer 1 à 2 min, jusqu''à ce qu''elles soient blondes ; surveiller, elles brûlent vite.","Retirer la poêle du feu et ajouter le jus d''un demi-citron et le persil.","Napper la truite de beurre aux amandes et servir avec les pommes de terre, les haricots verts et le reste du citron en quartiers."]},"it":{"title":"Trota alle mandorle con fagiolini e patate","steps":["Lessare le patate in acqua salata per 15-18 min, aggiungendo i fagiolini negli ultimi 6 min. Scolare, tagliare a metà le patate e tenere tutto in caldo nella pentola.","Salare e pepare la trota e infarinare i filetti, scuotendo via l''eccesso.","Scaldare l''olio e 10 g di burro in una padella larga a fuoco medio-alto. Cuocere i filetti dal lato della pelle per 3 min, finché è croccante, poi girarli e cuocere ancora 1-2 min. Trasferirli su piatti caldi.","Pulire la padella, aggiungere il burro rimasto a fuoco medio e, quando fa la schiuma, unire le mandorle. Mescolare 1-2 min, finché sono appena dorate; controllare, bruciano in fretta.","Togliere la padella dal fuoco e aggiungere il succo di mezzo limone e il prezzemolo.","Versare il burro alle mandorle sulla trota e servire con le patate, i fagiolini e il resto del limone a spicchi."]}}'::jsonb),
  ('526726ea-ddcf-42ae-b3bc-d66740174c06'::uuid, '{"fr":{"title":"Courgettes farcies à la dinde","steps":["Préchauffer le four à 200 °C. Couper les courgettes en deux dans la longueur et les évider à la cuillère en laissant 1 cm de chair ; hacher la chair retirée. Poser les barquettes côté coupé vers le haut dans un plat huilé, les assaisonner et les précuire 12 min au four pendant la préparation de la farce.","Faire fondre l''oignon dans l''huile dans une poêle 4 min, puis ajouter l''ail et la chair de courgette hachée et cuire 5 min, jusqu''à ce que l''eau soit évaporée.","Ajouter la dinde en l''émiettant et cuire 5 min jusqu''à ce qu''elle ne soit plus rose. Ajouter les tomates, le concentré et les herbes et cuire encore 3 min.","Hors du feu, laisser tiédir quelques minutes, puis incorporer le persil, l''œuf, la moitié de la chapelure, du sel et du poivre.","Sortir le plat du four et garnir généreusement de farce les barquettes précuites.","Mélanger le reste de chapelure avec le parmesan, en parsemer le dessus et arroser d''un filet d''huile.","Enfourner 18 à 20 min, jusqu''à ce que les courgettes soient tendres sous la pointe d''un couteau et le dessus doré. Servir avec de la baguette."]},"it":{"title":"Zucchine ripiene di tacchino","steps":["Scaldare il forno a 200 °C. Tagliare le zucchine a metà nel senso della lunghezza e svuotarle con un cucchiaio lasciando 1 cm di polpa; tritare la polpa tolta. Sistemare le barchette con il taglio verso l''alto in una pirofila unta, condirle e precuocerle in forno per 12 min mentre si prepara il ripieno.","Far appassire la cipolla nell''olio in una padella per 4 min, poi aggiungere l''aglio e la polpa di zucchina tritata e cuocere 5 min, finché l''acqua è evaporata.","Aggiungere il tacchino sbriciolandolo e cuocere 5 min finché non è più rosa. Aggiungere i pomodori, il concentrato e le erbe e cuocere ancora 3 min.","Fuori dal fuoco lasciare intiepidire qualche minuto, poi incorporare il prezzemolo, l''uovo, metà del pangrattato, sale e pepe.","Togliere la pirofila dal forno e riempire abbondantemente con il ripieno le barchette precotte.","Mescolare il pangrattato rimasto con il parmigiano, cospargerlo sopra e irrorare con un filo d''olio.","Cuocere in forno 18-20 min, finché le zucchine sono tenere alla punta di un coltello e la superficie è dorata. Servire con la baguette."]}}'::jsonb),
  ('6fce5d8d-5b15-48e1-bbbc-a4f27311e708'::uuid, '{"fr":{"title":"Quiche au saumon fumé et aux poireaux","steps":["Préchauffer le four à 190 °C. Foncer un moule à tarte de 20 à 22 cm avec la pâte, piquer le fond et le réserver au frais pendant la préparation de la garniture.","Laver les poireaux et les faire suer dans le beurre avec une pincée de sel, à couvert, 10 min, jusqu''à ce qu''ils soient fondants ; découvrir les 2 dernières minutes pour les sécher. Laisser tiédir.","Battre les œufs avec la crème fraîche, le lait, la muscade et le poivre ; saler à peine, le saumon étant salé.","Étaler les poireaux sur la pâte, répartir le saumon, l''aneth et l''emmental, puis verser l''appareil.","Enfourner 30 à 35 min, jusqu''à ce que la quiche soit gonflée et dorée et que le centre tremble à peine.","Laisser reposer 10 min avant de découper, et servir avec une salade verte."]},"it":{"title":"Quiche al salmone affumicato e porri","steps":["Scaldare il forno a 190 °C. Foderare uno stampo da crostata di 20-22 cm con la sfoglia, bucherellare il fondo e tenerlo in frigorifero mentre si prepara il ripieno.","Lavare i porri e stufarli nel burro con un pizzico di sale, coperti, per 10 min, finché sono morbidi; scoprire negli ultimi 2 min per asciugarli. Lasciarli intiepidire.","Sbattere le uova con la crème fraîche, il latte, la noce moscata e il pepe; salare appena, perché il salmone è già salato.","Distribuire i porri sulla sfoglia, cospargere con il salmone, l''aneto e l''emmental, poi versare il composto di uova.","Cuocere in forno 30-35 min, finché la quiche è gonfia e dorata e il centro trema appena.","Lasciare riposare 10 min prima di tagliare e servire con un''insalata verde."]}}'::jsonb),
  ('3c54ff1d-21f9-40f7-ac17-447d4677f6e0'::uuid, '{"fr":{"title":"Galette complète","steps":["Fouetter la farine avec 1/2 c. à café de sel, puis incorporer peu à peu 220 ml d''eau froide en fouettant pour obtenir une pâte lisse, de la consistance d''une crème liquide. Couvrir et réserver au frais au moins 1 h (2 h, c''est mieux).","Fouetter à nouveau la pâte. Chauffer une grande poêle antiadhésive ou une crêpière (environ 28 cm) à feu moyen-vif et la graisser d''un peu de beurre.","Verser une petite louche de pâte (environ 70 ml) et l''étaler finement en inclinant la poêle. Cuire 1 min 30 à 2 min, jusqu''à ce que les bords se décollent et croustillent, puis retourner et cuire 30 s. Empiler et recommencer pour obtenir 4 galettes.","Remettre une galette dans la poêle beurrée à feu moyen. Parsemer un quart de l''emmental au centre, casser un œuf dessus et étaler doucement le blanc à la spatule sans crever le jaune.","Disposer une tranche de jambon autour du jaune et cuire 3 à 4 min, en couvrant 1 min, jusqu''à ce que le blanc soit pris et le dessous croustillant.","Replier les quatre bords pour former un carré en laissant le jaune apparent. Glisser sur une assiette, poivrer, parsemer de ciboulette et recommencer avec le reste."]},"it":{"title":"Galette complète bretone","steps":["Sbattere la farina con 1/2 cucchiaino di sale, poi incorporare poco a poco 220 ml di acqua fredda sbattendo, fino a ottenere una pastella liscia, della consistenza della panna liquida. Coprire e tenere in frigorifero almeno 1 ora (meglio 2).","Sbattere di nuovo la pastella. Scaldare una padella antiaderente larga o una crêpiera (circa 28 cm) a fuoco medio-alto e ungerla con poco burro.","Versare un piccolo mestolo di pastella (circa 70 ml) e stenderla sottile ruotando la padella. Cuocere 1,5-2 min, finché i bordi si staccano e diventano croccanti, poi girare e cuocere 30 s. Impilare e ripetere fino a ottenere 4 galette.","Rimettere una galette nella padella imburrata a fuoco medio. Distribuire un quarto dell''emmental al centro, rompervi sopra un uovo e allargare delicatamente l''albume con una spatola senza rompere il tuorlo.","Disporre una fetta di prosciutto intorno al tuorlo e cuocere 3-4 min, coprendo per 1 min, finché l''albume è rappreso e il fondo è croccante.","Ripiegare i quattro bordi formando un quadrato e lasciando visibile il tuorlo. Far scivolare su un piatto, pepare, cospargere di erba cipollina e ripetere con il resto."]}}'::jsonb),
  ('dc443c39-5da5-4243-8dd2-eb0da76ad765'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet rôtis, carottes et pommes de terre","steps":["Préchauffer le four à 200 °C.","Mélanger les pommes de terre, les carottes, l''oignon et l''ail dans un plat à rôtir avec 1,5 c. à soupe d''huile, le thym, du sel et du poivre, et les étaler en une seule couche.","Sécher les hauts de cuisse, les frotter avec le reste d''huile, bien les assaisonner et les poser côté peau vers le haut sur les légumes.","Verser le bouillon dans le plat autour des légumes, sans mouiller la peau du poulet.","Enfourner 45 min en arrosant les légumes une fois à mi-cuisson, jusqu''à ce que la peau soit croustillante, que le jus soit clair (75 °C près de l''os) et que les légumes soient tendres. Pour une peau encore plus croustillante, finir 3 min sous le gril.","Laisser reposer 5 min, presser l''ail fondant dans le jus de cuisson et servir parsemé de persil."]},"it":{"title":"Sovracosce di pollo arrosto con carote e patate","steps":["Scaldare il forno a 200 °C.","Mescolare le patate, le carote, la cipolla e l''aglio in una teglia con 1,5 cucchiai di olio, il timo, sale e pepe, e distribuirli in un solo strato.","Asciugare le sovracosce, massaggiarle con l''olio rimasto, condirle bene e adagiarle con la pelle verso l''alto sulle verdure.","Versare il brodo nella teglia intorno alle verdure, senza bagnare la pelle del pollo.","Arrostire 45 min, irrorando le verdure una volta a metà cottura, finché la pelle è croccante, il sugo esce chiaro (75 °C vicino all''osso) e le verdure sono tenere. Per una pelle ancora più croccante, finire 3 min sotto il grill.","Lasciare riposare 5 min, spremere l''aglio morbido nel fondo di cottura e servire cosparso di prezzemolo."]}}'::jsonb),
  ('32702abe-4094-459f-80a5-53f01914b4d3'::uuid, '{"fr":{"title":"Côtes de porc, haricots blancs à la moutarde","steps":["Sécher les côtes, inciser le gras du bord à deux ou trois endroits pour qu''elles restent à plat, et assaisonner.","Chauffer l''huile dans une grande poêle à feu moyen-vif. Cuire les côtes 4 à 5 min de chaque côté, jusqu''à ce qu''elles soient dorées et à 63 °C à cœur (encore légèrement rosées), en les tenant 1 min sur la tranche pour faire fondre le gras. Laisser reposer sous une feuille d''aluminium.","Baisser le feu, ajouter le beurre et faire fondre l''échalote 2 min, puis ajouter l''ail et le thym 30 s.","Verser le vin en décollant les sucs et réduire 1 min. Ajouter le bouillon et les haricots et laisser mijoter 4 min en écrasant quelques haricots pour épaissir la sauce.","Incorporer les deux moutardes et la crème fraîche, puis les épinards jusqu''à ce qu''ils tombent, environ 1 min. Ajouter le jus de repos des côtes et assaisonner.","Servir les côtes sur les haricots, parsemées de persil, avec de la baguette pour saucer."]},"it":{"title":"Braciole di maiale con fagioli bianchi alla senape","steps":["Asciugare le braciole, incidere il grasso del bordo in due o tre punti perché restino piatte, e condirle.","Scaldare l''olio in una padella larga a fuoco medio-alto. Cuocere le braciole 4-5 min per lato, finché sono dorate e a 63 °C al centro (ancora leggermente rosate), tenendole 1 min sul bordo grasso per farlo sciogliere. Lasciarle riposare coperte con un foglio di alluminio.","Abbassare il fuoco, aggiungere il burro e far appassire lo scalogno per 2 min, poi aggiungere l''aglio e il timo per 30 s.","Versare il vino staccando il fondo di cottura e ridurre 1 min. Aggiungere il brodo e i fagioli e sobbollire 4 min, schiacciando qualche fagiolo per addensare la salsa.","Incorporare le due senapi e la crème fraîche, poi gli spinaci finché appassiscono, circa 1 min. Aggiungere il sugo rilasciato dalle braciole e regolare di sale e pepe.","Servire le braciole sui fagioli, cosparse di prezzemolo, con la baguette per fare la scarpetta nella salsa."]}}'::jsonb),
  ('a1f1bf80-ba8c-445f-919f-eb1dfa24d82f'::uuid, '{"fr":{"title":"Steaks de céleri-rave rôtis, lentilles vertes","steps":["Préchauffer le four à 200 °C. Badigeonner les tranches de céleri de 1,5 c. à soupe d''huile, assaisonner, ajouter le thym et rôtir sur une plaque chemisée 40 à 45 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et tendres sous la pointe d''un couteau. Parsemer de beurre les 5 dernières minutes.","Pendant ce temps, faire revenir l''oignon, la carotte et le céleri branche dans 0,5 c. à soupe d''huile dans une casserole 5 min.","Ajouter les lentilles, le laurier, l''ail et 500 ml d''eau et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres, en ajoutant un peu d''eau si besoin. Saler en fin de cuisson.","Mélanger la crème fraîche avec 1 c. à café de moutarde, la moitié du persil, du sel et du poivre.","Égoutter les lentilles si nécessaire, retirer le laurier et incorporer le vinaigre, le reste de moutarde et d''huile et le reste du persil. Assaisonner.","Servir les lentilles surmontées des steaks de céleri, d''une cuillerée de crème fraîche à la moutarde et des noix."]},"it":{"title":"Bistecche di sedano rapa arrosto con lenticchie","steps":["Scaldare il forno a 200 °C. Spennellare le fette di sedano rapa con 1,5 cucchiai di olio, condirle, aggiungere il timo e arrostirle su una teglia foderata 40-45 min, girandole a metà, finché sono ben dorate e tenere alla punta di un coltello. Distribuire il burro a fiocchetti negli ultimi 5 min.","Nel frattempo far soffriggere la cipolla, la carota e il sedano in 0,5 cucchiai di olio in un pentolino per 5 min.","Aggiungere le lenticchie, l''alloro, l''aglio e 500 ml di acqua e cuocere a fuoco lento 20-25 min, finché sono tenere, aggiungendo un po'' d''acqua se serve. Salare a fine cottura.","Mescolare la crème fraîche con 1 cucchiaino di senape, metà del prezzemolo, sale e pepe.","Scolare le lenticchie se necessario, togliere l''alloro e incorporare l''aceto, la senape e l''olio rimasti e il resto del prezzemolo. Regolare di sale e pepe.","Servire le lenticchie con sopra le bistecche di sedano rapa, una cucchiaiata di crème fraîche alla senape e le noci."]}}'::jsonb),
  ('5486ba0e-eda7-4b34-9db4-c6ded42efe68'::uuid, '{"fr":{"title":"Bar poêlé, écrasé de pommes de terre, tomates et olives","steps":["Cuire les pommes de terre 15 à 20 min dans de l''eau bouillante salée, jusqu''à ce qu''elles soient tendres. Égoutter et laisser sécher 2 min à la vapeur.","Les écraser grossièrement à la fourchette dans la casserole avec 2 c. à soupe d''huile, le zeste du citron, du sel et du poivre ; garder des morceaux, sans faire de purée. Couvrir pour garder au chaud.","Chauffer 1 c. à soupe d''huile dans une poêle, ajouter l''ail 30 s, puis les tomates 3 à 4 min jusqu''à ce qu''elles commencent à éclater. Ajouter les olives, les câpres et un trait d''eau, assaisonner et verser dans un bol. Essuyer la poêle.","Sécher le poisson, inciser la peau et assaisonner. Chauffer le reste d''huile à feu moyen-vif et poser les filets côté peau en les pressant 10 s. Cuire 3 à 4 min, jusqu''à ce que la peau soit croustillante, puis retourner et cuire 1 min.","Servir le poisson sur l''écrasé avec les tomates et les olives, du basilic déchiré et un filet de jus de citron."]},"it":{"title":"Branzino con patate schiacciate, pomodorini e olive","steps":["Lessare le patate in acqua salata per 15-20 min, finché sono tenere. Scolarle e lasciarle asciugare al vapore per 2 min.","Schiacciarle grossolanamente con una forchetta nella pentola con 2 cucchiai di olio, la scorza del limone, sale e pepe; lasciarle a pezzetti, non a purè. Coprire per tenerle in caldo.","Scaldare 1 cucchiaio di olio in una padella, aggiungere l''aglio per 30 s, poi i pomodorini per 3-4 min finché iniziano ad aprirsi. Aggiungere le olive, i capperi e un goccio d''acqua, regolare di sale e pepe e versare in una ciotola. Pulire la padella.","Asciugare il pesce, incidere la pelle e condirlo. Scaldare l''olio rimasto a fuoco medio-alto e adagiare i filetti dal lato della pelle, premendoli per 10 s. Cuocere 3-4 min, finché la pelle è croccante, poi girarli e cuocere 1 min.","Servire il pesce sulle patate schiacciate con i pomodorini e le olive, basilico spezzettato e una spruzzata di limone."]}}'::jsonb),
  ('10bc39c8-9e08-45f4-8b8d-083d4485392e'::uuid, '{"fr":{"title":"Sole meunière, pommes vapeur et haricots verts","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau bouillante salée, en ajoutant les haricots verts pour les 6 dernières minutes. Égoutter et garder au chaud.","Sécher la sole, l''assaisonner des deux côtés et la passer dans la farine en tapotant pour ôter l''excédent.","Chauffer l''huile et 10 g de beurre dans une grande poêle à feu moyen-vif jusqu''à ce qu''ils moussent. Cuire les filets 2 min, les retourner délicatement et cuire encore 1 à 2 min, jusqu''à ce qu''ils soient dorés et opaques ; procéder en deux fois si besoin. Garder au chaud dans les assiettes.","Essuyer la poêle, ajouter le reste du beurre à feu moyen et le laisser mousser jusqu''à ce qu''il devienne noisette et sente la noisette, 2 à 3 min.","Retirer la poêle du feu et ajouter le jus d''un demi-citron (il va grésiller) et le persil.","Verser le beurre noisette sur le poisson et les pommes de terre et servir avec les haricots verts et des quartiers de citron."]},"it":{"title":"Sogliola alla mugnaia con patate e fagiolini","steps":["Lessare le patate in acqua salata per 15-18 min, aggiungendo i fagiolini negli ultimi 6 min. Scolare e tenere in caldo.","Asciugare la sogliola, condirla da entrambi i lati e passarla nella farina, scuotendo via l''eccesso.","Scaldare l''olio e 10 g di burro in una padella larga a fuoco medio-alto finché fanno la schiuma. Cuocere i filetti 2 min, girarli con delicatezza e cuocere ancora 1-2 min, finché sono dorati e opachi; procedere in due volte se serve. Tenerli in caldo nei piatti.","Pulire la padella, aggiungere il burro rimasto a fuoco medio e lasciarlo spumeggiare finché diventa color nocciola e profuma di nocciola, 2-3 min.","Togliere la padella dal fuoco e aggiungere il succo di mezzo limone (sfrigolerà) e il prezzemolo.","Versare il burro nocciola sul pesce e sulle patate e servire con i fagiolini e spicchi di limone."]}}'::jsonb),
  ('a50426c9-afb6-41ab-ae5c-a0c08d84695c'::uuid, '{"fr":{"title":"Salade niçoise au thon et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau bouillante salée. Au bout de 6 min, plonger les œufs ; 4 min plus tard, ajouter les haricots verts ; 5 min après, tout égoutter et refroidir sous l''eau froide (œufs 9 min, pommes de terre 15 min).","Écaler les œufs et les couper en quartiers, couper les pommes de terre en deux et les haricots en deux.","Fouetter la moutarde, le vinaigre, le sel et le poivre, puis incorporer l''huile en fouettant.","Saler légèrement les quartiers de tomate.","Disposer la salade sur un grand plat avec les pommes de terre, les haricots, les tomates et l''oignon nouveau. Émietter le thon par-dessus et garnir d''œufs, d''anchois, d''olives et de câpres.","Arroser de vinaigrette et parsemer de basilic juste avant de servir."]},"it":{"title":"Insalata nizzarda con tonno e fagiolini","steps":["Mettere le patate in una pentola di acqua bollente salata. Dopo 6 min immergere le uova; dopo altri 4 min aggiungere i fagiolini; 5 min più tardi scolare tutto e raffreddare sotto l''acqua fredda (uova 9 min, patate 15 min).","Sgusciare le uova e tagliarle in quarti, tagliare a metà le patate e i fagiolini.","Sbattere la senape, l''aceto, il sale e il pepe, poi incorporare l''olio sbattendo.","Salare leggermente gli spicchi di pomodoro.","Disporre l''insalata su un piatto grande con le patate, i fagiolini, i pomodori e il cipollotto. Sbriciolare sopra il tonno e completare con le uova, le acciughe, le olive e i capperi.","Condire con la vinaigrette e cospargere di basilico appena prima di servire."]}}'::jsonb),
  ('0a467eb7-d057-498a-8acc-597b35c741b4'::uuid, '{"fr":{"title":"Lapin à la moutarde","steps":["Saler et poivrer le lapin. Chauffer l''huile et le beurre dans une cocotte à feu moyen-vif et bien dorer les cuisses sur toutes les faces, environ 8 min ; réserver.","Baisser le feu et faire revenir les lardons, l''oignon et l''échalote 5 min, jusqu''à ce qu''ils soient fondants et légèrement dorés.","Remettre le lapin et l''enrober entièrement des deux moutardes. Verser le vin et faire bouillir 2 min, puis ajouter le bouillon et le bouquet garni.","Couvrir et laisser mijoter doucement 50 min en retournant les cuisses à mi-cuisson, jusqu''à ce que la viande se détache facilement de l''os.","En fin de cuisson, cuire les tagliatelles dans de l''eau bouillante salée selon le paquet et les égoutter.","Retirer le lapin et le bouquet garni. Incorporer la crème fraîche à la sauce et faire bouillir 3 à 4 min, jusqu''à ce qu''elle nappe la cuillère. Assaisonner et remettre le lapin pour le réchauffer.","Servir le lapin et sa sauce avec les tagliatelles, parsemés de persil."]},"it":{"title":"Coniglio alla senape","steps":["Salare e pepare il coniglio. Scaldare l''olio e il burro in una casseruola a fuoco medio-alto e rosolare bene le cosce su tutti i lati, circa 8 min; metterle da parte.","Abbassare il fuoco e far rosolare la pancetta, la cipolla e lo scalogno per 5 min, finché sono morbidi e leggermente dorati.","Rimettere il coniglio e ricoprirlo completamente con le due senapi. Versare il vino e far bollire 2 min, poi aggiungere il brodo e il mazzetto odoroso.","Coprire e cuocere a fuoco dolce per 50 min, girando le cosce a metà cottura, finché la carne si stacca facilmente dall''osso.","Verso la fine cuocere le tagliatelle in acqua bollente salata secondo la confezione e scolarle.","Togliere il coniglio e il mazzetto odoroso. Incorporare la crème fraîche nella salsa e far bollire 3-4 min, finché vela il cucchiaio. Regolare di sale e pepe e rimettere il coniglio a scaldare.","Servire il coniglio con la salsa e le tagliatelle, cosparso di prezzemolo."]}}'::jsonb),
  ('72030c48-cb4d-4400-8a24-e49c0be5316c'::uuid, '{"fr":{"title":"Hachis parmentier","steps":["Couvrir les pommes de terre d''eau froide salée, porter à ébullition et cuire 20 min, jusqu''à ce qu''elles soient très tendres.","Pendant ce temps, faire revenir l''oignon et la carotte dans l''huile dans une poêle 6 à 7 min, puis ajouter l''ail 1 min.","Monter le feu, ajouter le bœuf et le faire dorer 5 à 6 min en l''émiettant. Incorporer le concentré de tomate, les feuilles de thym et le bouillon et laisser mijoter 10 min, jusqu''à ce que le liquide soit presque absorbé mais la viande encore moelleuse. Ajouter le persil et assaisonner.","Préchauffer le four à 200 °C. Égoutter les pommes de terre et les écraser avec le beurre, le lait chaud, la muscade et du sel jusqu''à obtenir une purée lisse et souple.","Étaler la viande dans un plat à gratin beurré (environ 20 × 15 cm), recouvrir de purée, lisser et tracer des stries à la fourchette. Parsemer d''emmental.","Enfourner 20 à 25 min, jusqu''à ce que le dessus soit doré et que les bords bouillonnent. Laisser reposer 5 min avant de servir."]},"it":{"title":"Hachis parmentier (pasticcio di carne e purè)","steps":["Coprire le patate con acqua fredda salata, portare a bollore e cuocere 20 min, finché sono molto tenere.","Nel frattempo far soffriggere la cipolla e la carota nell''olio in una padella per 6-7 min, poi aggiungere l''aglio per 1 min.","Alzare il fuoco, aggiungere il manzo e rosolarlo 5-6 min sbriciolandolo. Incorporare il concentrato di pomodoro, le foglie di timo e il brodo e cuocere a fuoco lento 10 min, finché il liquido è quasi assorbito ma la carne è ancora morbida. Aggiungere il prezzemolo e regolare di sale e pepe.","Scaldare il forno a 200 °C. Scolare le patate e schiacciarle con il burro, il latte caldo, la noce moscata e il sale fino a ottenere un purè liscio e morbido.","Stendere la carne in una pirofila imburrata (circa 20 × 15 cm), ricoprire con il purè, livellare e tracciare delle righe con una forchetta. Cospargere di emmental.","Cuocere in forno 20-25 min, finché la superficie è dorata e i bordi sobbollono. Lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('d1469ff0-250b-44af-9740-b897725d64a9'::uuid, '{"fr":{"title":"Calamars à la provençale","steps":["Cuire le riz 12 min dans de l''eau bouillante salée, puis l''égoutter.","Pendant ce temps, bien sécher les calamars avec du papier absorbant et les assaisonner.","Faire fondre l''oignon dans 1,5 c. à soupe d''huile dans une grande poêle 5 min, puis ajouter les deux tiers de l''ail 1 min.","Ajouter les tomates, les herbes de Provence, le laurier et le vin et laisser réduire à bon frémissement 8 min, jusqu''à ce que la sauce épaississe. Assaisonner et verser la sauce dans un bol ; essuyer la poêle.","Chauffer le reste d''huile dans la poêle à feu vif jusqu''à ce qu''elle soit très chaude et saisir les calamars en une seule couche 1 min 30 à 2 min, juste jusqu''à ce qu''ils soient opaques ; au-delà, ils deviennent caoutchouteux.","Remettre la sauce dans la poêle et mélanger 1 min. Hors du feu, ajouter le persil mélangé au reste d''ail et le piment.","Servir aussitôt avec le riz."]},"it":{"title":"Calamari alla provenzale","steps":["Cuocere il riso in acqua bollente salata per 12 min, poi scolarlo.","Nel frattempo asciugare molto bene i calamari con carta da cucina e condirli.","Far appassire la cipolla in 1,5 cucchiai di olio in una padella larga per 5 min, poi aggiungere due terzi dell''aglio per 1 min.","Aggiungere i pomodori, le erbe di Provenza, l''alloro e il vino e cuocere a fuoco vivace per 8 min, finché la salsa si addensa. Regolare di sale e pepe e versare la salsa in una ciotola; pulire la padella.","Scaldare l''olio rimasto nella padella a fuoco vivo finché è molto caldo e saltare i calamari in un solo strato per 1,5-2 min, solo finché diventano opachi; oltre diventano gommosi.","Rimettere la salsa nella padella e mescolare per 1 min. Fuori dal fuoco aggiungere il prezzemolo mescolato con l''aglio rimasto e il peperoncino.","Servire subito con il riso."]}}'::jsonb),
  ('fc1f7890-aff1-46d1-a531-9eeb03b6ba6f'::uuid, '{"fr":{"title":"Bavette à l''échalote, pommes vapeur et haricots verts","steps":["Cuire les pommes de terre 15 min dans de l''eau bouillante salée, en ajoutant les haricots verts pour les 7 dernières minutes, jusqu''à ce qu''ils soient juste tendres. Égoutter et mélanger avec 5 g de beurre.","Pendant ce temps, sécher la viande et la saler. Chauffer l''huile dans une poêle épaisse à feu vif jusqu''à ce qu''elle fume et saisir la bavette 2 à 3 min de chaque côté pour une cuisson saignante à rosée ; au-delà d''à point, la bavette durcit.","Laisser reposer la viande 5 min sur une assiette chaude sous une feuille d''aluminium.","Baisser à feu moyen, mettre 15 g de beurre et les échalotes dans la poêle et cuire 4 à 5 min en remuant, jusqu''à ce qu''elles soient fondantes et dorées.","Ajouter le vinaigre et le vin, décoller les sucs et faire bouillir 1 à 2 min, jusqu''à consistance sirupeuse. Hors du feu, incorporer le reste du beurre, le persil, le jus de repos de la viande et du poivre en abondance.","Trancher finement la bavette dans le sens contraire des fibres, napper d''échalotes et servir avec les pommes de terre et les haricots verts."]},"it":{"title":"Bavette di manzo allo scalogno con patate e fagiolini","steps":["Lessare le patate in acqua salata per 15 min, aggiungendo i fagiolini negli ultimi 7 min, finché sono appena teneri. Scolare e condire con 5 g di burro.","Nel frattempo asciugare la carne e salarla. Scaldare l''olio in una padella dal fondo spesso a fuoco vivo finché fuma e scottare la bavette 2-3 min per lato per una cottura al sangue o media-al sangue; oltre la cottura media diventa dura.","Lasciare riposare la carne 5 min su un piatto caldo coperta con un foglio di alluminio.","Abbassare a fuoco medio, mettere nella padella 15 g di burro e gli scalogni e cuocere 4-5 min mescolando, finché sono morbidi e dorati.","Aggiungere l''aceto e il vino, staccare il fondo di cottura e far bollire 1-2 min, finché diventa sciropposo. Fuori dal fuoco incorporare il burro rimasto, il prezzemolo, il sugo rilasciato dalla carne e abbondante pepe.","Tagliare la carne a fettine sottili contro fibra, coprirla con gli scalogni e servire con le patate e i fagiolini."]}}'::jsonb),
  ('e6a9b053-18c1-4083-bff9-6dd9c29a9b25'::uuid, '{"fr":{"title":"Soupe au pistou aux haricots blancs","steps":["Chauffer 1 c. à soupe d''huile dans un grand faitout et faire fondre l''oignon et le poireau 5 min.","Ajouter la carotte, la pomme de terre, la tomate, le thym, 1,1 l d''eau et du sel. Porter à ébullition et laisser frémir 10 min.","Ajouter les haricots verts, la courgette, les haricots blancs et les pâtes et cuire 10 min en remuant de temps en temps, jusqu''à ce que les pâtes et les légumes soient tendres.","Vérifier la consistance : la soupe doit être épaisse, n''ajouter un peu d''eau chaude que si nécessaire, et rectifier le sel.","Pendant ce temps, préparer le pistou : écraser l''ail avec une pincée de gros sel jusqu''à obtenir une pâte (au mortier ou avec le plat d''un couteau), ajouter le basilic et piler ou hacher finement, puis incorporer le parmesan et les 3 c. à soupe d''huile.","Retirer le faitout du feu, ôter le thym et incorporer la moitié du pistou. Servir le reste à table."]},"it":{"title":"Zuppa al pistou con fagioli bianchi","steps":["Scaldare 1 cucchiaio di olio in una pentola capiente e far appassire la cipolla e il porro per 5 min.","Aggiungere la carota, la patata, il pomodoro, il timo, 1,1 l di acqua e il sale. Portare a bollore e cuocere a fuoco lento 10 min.","Aggiungere i fagiolini, la zucchina, i fagioli bianchi e la pasta e cuocere 10 min mescolando ogni tanto, finché pasta e verdure sono tenere.","Controllare la consistenza: la zuppa deve restare densa, quindi aggiungere un po'' d''acqua calda solo se serve, e regolare di sale.","Nel frattempo preparare il pistou: schiacciare l''aglio con un pizzico di sale grosso fino a ridurlo in crema (nel mortaio o con la lama piatta di un coltello), aggiungere il basilico e pestare o tritare finemente, poi incorporare il parmigiano e i 3 cucchiai di olio.","Togliere la pentola dal fuoco, eliminare il timo e incorporare metà del pistou. Servire il resto a tavola."]}}'::jsonb),
  ('cf3604f7-00c4-4439-ae7c-a23dd60cdc25'::uuid, '{"fr":{"title":"Pâtes au citron, petits pois et ricotta","steps":["Porter à ébullition une grande casserole d''eau salée et y cuire les pâtes 1 min de moins que le temps indiqué.","Pendant ce temps, écraser la ricotta dans un grand saladier avec le zeste de citron, la moitié du jus, l''ail, l''huile d''olive, la moitié du parmesan, du sel et beaucoup de poivre.","Ajouter les petits pois aux pâtes pendant les 3 dernières minutes de cuisson.","Prélever un bol d''eau de cuisson, puis égoutter les pâtes et les petits pois.","Les verser dans le saladier et mélanger avec la ricotta en ajoutant l''eau de cuisson petit à petit jusqu''à obtenir une sauce crémeuse qui enrobe les pâtes.","Goûter, ajouter le reste du jus de citron si on le souhaite et servir avec le reste du parmesan, le persil et une pincée de piment."]},"it":{"title":"Pasta al limone con piselli e ricotta","steps":["Portare a bollore una pentola di acqua salata e cuocere la pasta 1 min in meno del tempo indicato.","Nel frattempo schiacciare la ricotta in una ciotola capiente con la scorza di limone, metà del succo, l''aglio, l''olio, metà del parmigiano, sale e abbondante pepe.","Aggiungere i piselli alla pasta negli ultimi 3 min di cottura.","Tenere da parte una tazza di acqua di cottura, poi scolare pasta e piselli.","Versarli nella ciotola e mescolare con la ricotta, aggiungendo acqua di cottura poco alla volta finché la crema è morbida e avvolge la pasta.","Assaggiare, unire il resto del succo di limone a piacere e servire con il parmigiano rimasto, il prezzemolo e un pizzico di peperoncino."]}}'::jsonb),
  ('91e8fa61-df06-405b-a7c2-209948b7784f'::uuid, '{"fr":{"title":"Frittata aux champignons et épinards, pain","steps":["Préchauffer le four à 180 °C.","Chauffer l''huile dans une poêle de 24 cm allant au four, à feu moyen, et faire fondre l''oignon 5 min.","Ajouter les champignons, l''ail et le thym et cuire 6 à 8 min, jusqu''à ce que les champignons soient dorés et leur eau évaporée.","Ajouter les épinards par poignées et remuer jusqu''à ce qu''ils tombent et que la poêle soit sèche, environ 2 min ; assaisonner.","Battre les œufs avec le lait, le parmesan, du sel et du poivre.","Verser les œufs sur les légumes, bien répartir et cuire à feu doux 3 à 4 min, jusqu''à ce que les bords commencent à prendre.","Enfourner 10 à 12 min, jusqu''à ce que le centre soit juste pris et souple au toucher.","Laisser reposer 2 min, couper en parts et servir tiède avec le pain."]},"it":{"title":"Frittata di funghi e spinaci con pane","steps":["Scaldare il forno a 180 °C.","Scaldare l''olio in una padella da 24 cm adatta al forno, a fuoco medio, e appassire la cipolla per 5 min.","Aggiungere i funghi, l''aglio e il timo e cuocere 6-8 min, finché i funghi sono dorati e la loro acqua è evaporata.","Unire gli spinaci a manciate e mescolare finché sono appassiti e la padella è asciutta, circa 2 min; salare e pepare.","Sbattere le uova con il latte, il parmigiano, sale e pepe.","Versare le uova sulle verdure, distribuire bene e cuocere a fuoco basso 3-4 min, finché i bordi iniziano a rapprendersi.","Infornare per 10-12 min, finché il centro è appena rappreso ed elastico al tatto.","Lasciare riposare 2 min, tagliare a spicchi e servire tiepida con il pane."]}}'::jsonb),
  ('a22633f5-d714-4ccc-bc98-4d7d2c560bd9'::uuid, '{"fr":{"title":"Boulettes de dinde à la sauce tomate et polenta","steps":["Mélanger à la main la dinde, l''œuf, la chapelure, la moitié du parmesan, l''ail râpé, le persil, du sel et du poivre, sans trop travailler la farce.","Former 12 boulettes de la taille d''une noix.","Faire dorer les boulettes dans 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif 5 min en les retournant, puis les retirer.","Dans la même poêle, faire revenir l''oignon et l''ail émincé dans le reste d''huile 4 min, puis ajouter le coulis de tomate, du sel et un peu d''eau.","Remettre les boulettes, couvrir et laisser mijoter doucement 15 min, jusqu''à ce qu''elles soient cuites à cœur et la sauce épaissie ; ajouter le basilic déchiré.","Pendant ce temps, porter à ébullition 450 ml d''eau salée et le lait, verser la polenta en pluie en fouettant et cuire 5 à 8 min (voir le paquet) en remuant, jusqu''à ce qu''elle soit épaisse et lisse.","Incorporer le reste du parmesan à la polenta et la servir dans des bols, garnie des boulettes et de la sauce."]},"it":{"title":"Polpette di tacchino al sugo con polenta","steps":["Impastare con le mani il tacchino, l''uovo, il pangrattato, metà del parmigiano, l''aglio grattugiato, il prezzemolo, sale e pepe, senza lavorare troppo.","Formare 12 polpette grandi come una noce.","Rosolare le polpette in 1 cucchiaio d''olio in una padella larga a fuoco medio-alto per 5 min, girandole, poi toglierle.","Nella stessa padella appassire la cipolla e l''aglio a fettine nell''olio rimasto per 4 min, poi aggiungere la passata, sale e un goccio d''acqua.","Rimettere le polpette, coprire e cuocere a fuoco dolce 15 min, finché sono cotte all''interno e il sugo si è addensato; aggiungere il basilico spezzettato.","Nel frattempo portare a bollore 450 ml di acqua salata con il latte, versare la polenta a pioggia mescolando con la frusta e cuocere 5-8 min (vedi confezione), mescolando, finché è densa e liscia.","Mantecare la polenta con il parmigiano rimasto e servirla nei piatti fondi con le polpette e il sugo."]}}'::jsonb),
  ('966cf969-f9be-46cc-8715-4c5085874d48'::uuid, '{"fr":{"title":"Ragù de champignons, lentilles et noix","steps":["Faire revenir l''oignon, la carotte et le céleri dans l''huile dans une grande sauteuse à feu moyen 6 min.","Ajouter les champignons et les noix et cuire 6 min en remuant, jusqu''à ce que les champignons aient rendu leur eau et commencent à dorer.","Incorporer l''ail et le concentré de tomate 1 min, puis verser le vin et laisser réduire de moitié.","Ajouter les tomates, le bouillon, les lentilles, la sauce soja, le thym et le laurier, porter à frémissement, couvrir à moitié et cuire 18 à 20 min en remuant de temps en temps, jusqu''à ce que les lentilles soient fondantes et la sauce épaisse ; ajouter un peu d''eau si besoin.","Pendant ce temps, cuire les pâtes al dente dans de l''eau bouillante salée en gardant un bol d''eau de cuisson.","Retirer le thym et le laurier, assaisonner le ragù et le mélanger aux pâtes en détendant avec l''eau de cuisson ; servir avec le basilic."]},"it":{"title":"Ragù di funghi, lenticchie e noci","steps":["Appassire cipolla, carota e sedano nell''olio in una padella larga a fuoco medio per 6 min.","Aggiungere i funghi e le noci e cuocere 6 min mescolando, finché i funghi hanno perso l''acqua e iniziano a dorare.","Unire l''aglio e il concentrato per 1 min, poi sfumare con il vino e lasciarlo ridurre della metà.","Aggiungere i pomodori, il brodo, le lenticchie, la salsa di soia, il timo e l''alloro, portare a bollore leggero, coprire a metà e cuocere 18-20 min mescolando ogni tanto, finché le lenticchie sono morbide e il sugo è denso; aggiungere un goccio d''acqua se si asciuga troppo.","Nel frattempo cuocere la pasta al dente in acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Togliere timo e alloro, regolare di sale e pepe e saltare il ragù con la pasta, allungando con l''acqua di cottura; servire con il basilico."]}}'::jsonb),
  ('ef9af9e4-429a-41fc-a675-41c9b617379a'::uuid, '{"fr":{"title":"Ribollita","steps":["Chauffer 2 c. à soupe d''huile dans une grande cocotte à feu doux et faire suer l''oignon, la carotte, le céleri, l''ail et le thym 10 min, sans coloration.","Ajouter la pomme de terre, le chou noir et le chou frisé, saler, poivrer et remuer 3 à 4 min jusqu''à ce que les feuilles tombent.","Ajouter les tomates, le concentré et le bouillon, porter à frémissement et cuire à couvert partiel 40 min.","Écraser la moitié des haricots en purée grossière à la fourchette ou au presse-purée avec une louche de soupe.","Incorporer la purée et les haricots entiers dans la cocotte et laisser mijoter encore 15 min.","Enfoncer le pain dans la soupe et cuire 10 min en remuant, jusqu''à ce qu''il se défasse et que la soupe soit épaisse ; ajouter un peu d''eau si besoin.","Rectifier l''assaisonnement et servir avec un filet d''huile d''olive crue, du poivre et du parmesan. Elle est encore meilleure réchauffée le lendemain."]},"it":{"title":"Ribollita","steps":["Scaldare 2 cucchiai d''olio in una pentola capiente a fuoco basso e stufare cipolla, carota, sedano, aglio e timo per 10 min, senza farli colorire.","Aggiungere la patata, il cavolo nero e la verza, salare, pepare e mescolare 3-4 min finché le foglie appassiscono.","Unire i pomodori, il concentrato e il brodo, portare a bollore leggero e cuocere semicoperto per 40 min.","Schiacciare metà dei fagioli con una forchetta o uno schiacciapatate insieme a un mestolo di zuppa, fino a una purea grossolana.","Unire la purea e i fagioli interi nella pentola e cuocere ancora 15 min.","Immergere il pane nella zuppa e cuocere 10 min mescolando, finché si sfalda e la zuppa è densa; aggiungere un po'' d''acqua se serve.","Regolare di sale e servire con un filo d''olio a crudo, pepe e parmigiano. Il giorno dopo, ribollita, è ancora più buona."]}}'::jsonb),
  ('8ffa559e-9ee1-4db0-b46c-a4956b1290be'::uuid, '{"fr":{"title":"Gnocchis aux poivrons rôtis et mozzarella","steps":["Préchauffer le four à 220 °C.","Mélanger les poivrons, l''oignon, les tomates cerises, l''ail et le thym avec 2 c. à soupe d''huile, du sel et du poivre dans un grand plat à rôtir.","Rôtir 15 min, jusqu''à ce que les poivrons soient fondants et cloqués et les tomates éclatées.","Écraser l''ail et les tomates à la fourchette pour obtenir une sauce rustique et retirer les tiges de thym.","Ajouter les gnocchis directement du paquet avec le reste d''huile et un peu d''eau, bien mélanger et rôtir 10 min, jusqu''à ce que les gnocchis soient tendres.","Parsemer de mozzarella et de parmesan et enfourner encore 5 min, jusqu''à ce que le fromage soit fondu et doré par endroits.","Servir parsemé de basilic."]},"it":{"title":"Gnocchi al forno con peperoni arrosto e mozzarella","steps":["Scaldare il forno a 220 °C.","Condire peperoni, cipolla, pomodorini, aglio e timo con 2 cucchiai d''olio, sale e pepe in una teglia grande.","Arrostire per 15 min, finché i peperoni sono morbidi e abbrustoliti e i pomodorini scoppiati.","Schiacciare l''aglio e i pomodorini con una forchetta per ottenere un sugo rustico ed eliminare i rametti di timo.","Aggiungere gli gnocchi direttamente dalla confezione con l''olio rimasto e un goccio d''acqua, mescolare bene e arrostire 10 min, finché gli gnocchi sono morbidi.","Distribuire la mozzarella e il parmigiano e infornare ancora 5 min, finché il formaggio è fuso e dorato qua e là.","Servire con il basilico."]}}'::jsonb),
  ('44542c57-7489-4eeb-ba0c-2a8923c197a8'::uuid, '{"fr":{"title":"Orzotto aux champignons","steps":["Porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire sauter les champignons dans l''huile avec l''ail et le romarin à feu vif 6 à 8 min, jusqu''à ce qu''ils soient dorés ; assaisonner, réserver un tiers pour le dessus et retirer l''ail et le romarin.","Ajouter la moitié du beurre et l''échalote dans la sauteuse et faire fondre à feu moyen 3 min.","Ajouter l''orge et la nacrer 2 min en remuant, puis verser le vin et le laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant souvent et en attendant qu''il soit presque absorbé, pendant 30 à 35 min, jusqu''à ce que l''orge soit tendre mais encore légèrement ferme.","Hors du feu, incorporer le reste du beurre et le parmesan et laisser reposer 1 min ; l''orzotto doit être crémeux et souple.","Servir garni des champignons réservés, de persil et de poivre."]},"it":{"title":"Orzotto ai funghi","steps":["Portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga saltare i funghi nell''olio con l''aglio e il rosmarino a fuoco vivo per 6-8 min, finché sono dorati; salare, tenerne da parte un terzo per guarnire ed eliminare aglio e rosmarino.","Aggiungere metà del burro e lo scalogno nella padella e appassire a fuoco medio per 3 min.","Unire l''orzo e tostarlo 2 min mescolando, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando spesso e aspettando che sia quasi assorbito, per 30-35 min, finché l''orzo è tenero ma ancora leggermente al dente.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano e lasciare riposare 1 min; deve risultare cremoso e morbido.","Servire con i funghi tenuti da parte, il prezzemolo e pepe nero."]}}'::jsonb),
  ('4ac67db3-15f0-4505-a682-a9989c256c89'::uuid, '{"fr":{"title":"Linguine aux crevettes, courgette et citron","steps":["Cuire les linguine al dente dans une grande casserole d''eau bouillante salée en gardant un bol d''eau de cuisson.","Pendant ce temps, chauffer 2 c. à soupe d''huile dans une grande poêle à feu vif et faire dorer la courgette 4 à 5 min ; assaisonner et réserver.","Ajouter le reste d''huile, l''ail et une pincée de piment dans la poêle 30 s, puis ajouter les crevettes et cuire 2 à 3 min en les retournant une fois, jusqu''à ce qu''elles soient roses.","Remettre la courgette et ajouter le zeste et la moitié du jus de citron.","Ajouter les linguine égouttées avec un peu d''eau de cuisson et mélanger sur le feu 1 min, jusqu''à ce qu''elles soient brillantes.","Ajouter le persil, du jus de citron selon le goût, du sel et du poivre, et servir aussitôt."]},"it":{"title":"Linguine con gamberi, zucchine e limone","steps":["Cuocere le linguine al dente in abbondante acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Nel frattempo scaldare 2 cucchiai d''olio in una padella grande a fuoco vivo e dorare la zucchina per 4-5 min; salare e mettere da parte.","Aggiungere nella padella l''olio rimasto, l''aglio e un pizzico di peperoncino per 30 s, poi i gamberi e cuocerli 2-3 min girandoli una volta, finché sono rosa.","Rimettere la zucchina e aggiungere la scorza e metà del succo di limone.","Unire le linguine scolate con un po'' di acqua di cottura e saltare sul fuoco 1 min, finché sono lucide.","Aggiungere il prezzemolo, altro succo di limone a piacere, sale e pepe, e servire subito."]}}'::jsonb),
  ('4172c8f0-f681-446f-be3b-0a1848a9606c'::uuid, '{"fr":{"title":"Lasagnes aux épinards et champignons","steps":["Préchauffer le four à 200 °C.","Préparer la béchamel : faire fondre le beurre dans une casserole, ajouter la farine et remuer 1 min, puis verser le lait petit à petit en fouettant et laisser épaissir 5 min en remuant. Saler, poivrer, muscader et incorporer les deux tiers du parmesan.","Faire sauter les champignons avec l''ail dans l''huile dans une grande poêle à feu vif 8 min, jusqu''à ce qu''ils soient dorés ; ajouter le vin, le laisser s''évaporer, puis assaisonner.","Ajouter les épinards dans la poêle et remuer jusqu''à ce qu''ils tombent ; jeter le liquide éventuel.","Étaler une fine couche de béchamel dans un plat de 20 × 20 cm, puis alterner feuilles de lasagne, un tiers des champignons et épinards et un quart de la béchamel ; répéter deux fois.","Terminer par une couche de feuilles recouverte du reste de béchamel et de parmesan.","Enfourner 30 à 35 min, jusqu''à ce que le dessus soit doré et bouillonnant et qu''un couteau traverse facilement les pâtes.","Laisser reposer 10 min avant de découper."]},"it":{"title":"Lasagne con spinaci e funghi","steps":["Scaldare il forno a 200 °C.","Preparare la besciamella: sciogliere il burro in un pentolino, unire la farina e mescolare 1 min, poi aggiungere il latte poco alla volta con la frusta e cuocere 5 min mescolando, finché si addensa. Regolare di sale, pepe e noce moscata e incorporare due terzi del parmigiano.","Saltare i funghi con l''aglio nell''olio in una padella grande a fuoco vivo per 8 min, finché sono dorati; sfumare con il vino, lasciarlo evaporare e salare.","Aggiungere gli spinaci nella padella e mescolare finché sono appena appassiti; eliminare l''eventuale liquido.","Stendere un velo di besciamella in una pirofila da 20 × 20 cm, poi alternare sfoglie di lasagna, un terzo di funghi e spinaci e un quarto della besciamella; ripetere altre due volte.","Chiudere con un ultimo strato di sfoglie coperto con la besciamella e il parmigiano rimasti.","Infornare per 30-35 min, finché la superficie è dorata e bollente e un coltello affonda facilmente nella pasta.","Lasciare riposare 10 min prima di tagliare."]}}'::jsonb),
  ('a5aace29-d33e-4a90-9a9a-5ec39bbd6f9b'::uuid, '{"fr":{"title":"Pizzas sur pain plat, tomate et mozzarella","steps":["Préchauffer le four à 220 °C avec une plaque à l''intérieur.","Éponger les rondelles de tomate et la mozzarella déchirée avec du papier absorbant.","Mélanger le coulis de tomate avec l''ail, une pincée d''origan et du sel, puis l''étaler finement sur les pains en laissant une petite bordure.","Parsemer de mozzarella râpée, puis des rondelles de tomate et de la mozzarella déchirée ; assaisonner et arroser d''huile.","Glisser sur la plaque chaude et cuire 10 à 12 min, jusqu''à ce que la base soit croustillante et le fromage bouillonnant et doré par endroits.","Garnir de basilic frais et d''une pincée de piment, puis couper en parts."]},"it":{"title":"Pizzette su piadina con pomodoro e mozzarella","steps":["Scaldare il forno a 220 °C con una teglia all''interno.","Tamponare le fette di pomodoro e la mozzarella spezzettata con carta da cucina.","Mescolare la passata con l''aglio, un pizzico di origano e sale e stenderla sottile sulle focacce, lasciando un piccolo bordo.","Distribuire la mozzarella grattugiata, poi le fette di pomodoro e la mozzarella spezzettata; salare, pepare e irrorare con l''olio.","Trasferire sulla teglia calda e cuocere 10-12 min, finché la base è croccante e il formaggio è bollente e dorato qua e là.","Completare con basilico fresco e un pizzico di peperoncino e tagliare a spicchi."]}}'::jsonb),
  ('05fd4eac-be99-4274-a403-ad8b8821f794'::uuid, '{"fr":{"title":"Risotto au potiron, saucisse et sauge","steps":["Préchauffer le four à 200 °C. Mélanger le potiron avec l''huile, la moitié de la sauge, du sel et du poivre sur une plaque et rôtir 25 min, jusqu''à ce qu''il soit fondant et caramélisé sur les bords.","Pendant ce temps, porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, émietter la chair à saucisse et la faire dorer à feu moyen 5 min ; la retirer en laissant la graisse.","Ajouter la moitié du beurre, l''oignon et le reste de la sauge et faire fondre 5 min.","Ajouter le riz et le nacrer 2 min, puis verser le vin et le laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant et en le laissant absorber, pendant 16 à 18 min, jusqu''à ce que le riz soit crémeux et al dente ; incorporer la saucisse et la moitié du potiron écrasé à mi-cuisson.","Hors du feu, incorporer le reste du beurre et le parmesan, couvrir et laisser reposer 2 min.","Servir garni du reste du potiron rôti et des feuilles de sauge croustillantes."]},"it":{"title":"Risotto con zucca, salsiccia e salvia","steps":["Scaldare il forno a 200 °C. Condire la zucca con l''olio, metà della salvia, sale e pepe su una teglia e arrostire 25 min, finché è morbida e caramellata ai bordi.","Nel frattempo portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga sbriciolare la salsiccia e rosolarla a fuoco medio per 5 min; toglierla lasciando il grasso.","Aggiungere metà del burro, la cipolla e il resto della salvia e appassire per 5 min.","Unire il riso e tostarlo 2 min, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando e lasciandolo assorbire, per 16-18 min, finché il riso è cremoso e al dente; a metà cottura unire la salsiccia e metà della zucca schiacciata.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano, coprire e lasciare riposare 2 min.","Servire con il resto della zucca arrosto e le foglie di salvia croccanti."]}}'::jsonb),
  ('4f5355b3-f2fd-4dbd-921a-d50d37544580'::uuid, '{"fr":{"title":"Gratin de pâtes au thon, tomate et épinards","steps":["Préchauffer le four à 180 °C.","Cuire les pâtes dans de l''eau bouillante salée 2 min de moins que le temps indiqué, puis les égoutter.","Pendant ce temps, faire revenir l''oignon et l''ail dans l''huile dans une poêle allant au four à feu moyen 4 min.","Ajouter les tomates, l''origan, du sel, du poivre et un peu d''eau et laisser mijoter 5 à 8 min, jusqu''à ce que la sauce épaississe légèrement.","Incorporer les épinards dans la sauce jusqu''à ce qu''ils tombent, puis retirer du feu et ajouter les pâtes.","Incorporer délicatement le thon en gros morceaux et parsemer de mozzarella.","Enfourner 15 à 20 min, jusqu''à ce que le fromage soit doré et la sauce bouillonnante sur les bords ; laisser reposer 3 min avant de servir."]},"it":{"title":"Pasta al forno con tonno, pomodoro e spinaci","steps":["Scaldare il forno a 180 °C.","Cuocere la pasta in acqua bollente salata 2 min in meno del tempo indicato, poi scolarla.","Nel frattempo appassire cipolla e aglio nell''olio in una padella adatta al forno a fuoco medio per 4 min.","Aggiungere i pomodori, l''origano, sale, pepe e un goccio d''acqua e cuocere 5-8 min, finché il sugo si addensa leggermente.","Unire gli spinaci al sugo e farli appassire, poi togliere dal fuoco e mescolare con la pasta.","Incorporare delicatamente il tonno a pezzi grossi e distribuire la mozzarella in superficie.","Infornare per 15-20 min, finché il formaggio è dorato e il sugo bolle ai bordi; lasciare riposare 3 min prima di servire."]}}'::jsonb),
  ('24abeaf1-16d2-4545-92bb-0c275f122522'::uuid, '{"fr":{"title":"Conchiglioni farcis aux épinards et à la ricotta","steps":["Préchauffer le four à 200 °C.","Faire tomber les épinards dans une grande casserole avec un peu d''eau 2 à 3 min, les égoutter, les laisser refroidir, les presser et les hacher finement.","Mélanger les épinards avec la ricotta, l''œuf, les deux tiers du parmesan, un peu de muscade, du sel et du poivre.","Remplir à nouveau la casserole d''eau salée et cuire les conchiglioni la moitié du temps indiqué (environ 6 min) ; les égoutter, les passer sous l''eau froide et les huiler légèrement.","Mélanger le coulis de tomate avec l''ail, le reste de l''huile, du sel et le basilic et l''étaler au fond d''un plat à gratin.","Garnir chaque coquille d''une bonne cuillerée de farce et les disposer côte à côte dans la sauce.","Parsemer du reste de parmesan, enfourner 20 min, jusqu''à ce que le dessus soit doré et la sauce bouillonnante."]},"it":{"title":"Conchiglioni ripieni di ricotta e spinaci","steps":["Scaldare il forno a 200 °C.","Far appassire gli spinaci in una pentola capiente con un goccio d''acqua per 2-3 min, scolarli, lasciarli raffreddare, strizzarli e tritarli finemente.","Mescolare gli spinaci con la ricotta, l''uovo, due terzi del parmigiano, una grattata di noce moscata, sale e pepe.","Riempire di nuovo la pentola con acqua salata e cuocere i conchiglioni per metà del tempo indicato (circa 6 min); scolarli, passarli sotto l''acqua fredda e ungerli con un filo d''olio.","Mescolare la passata con l''aglio, l''olio rimasto, sale e il basilico e stenderla sul fondo di una pirofila.","Farcire ogni conchiglione con una cucchiaiata abbondante di ripieno e sistemarli vicini nel sugo.","Cospargere con il parmigiano rimasto, infornare per 20 min, finché la superficie è dorata e il sugo bolle."]}}'::jsonb),
  ('55823f6d-25c8-4972-b71a-6303a4330168'::uuid, '{"fr":{"title":"Spaghetti aux sardines, citron et chapelure","steps":["Cuire les spaghetti al dente dans une grande casserole d''eau bouillante salée en gardant un bol d''eau de cuisson.","Pendant ce temps, faire griller la chapelure dans 1 c. à soupe d''huile dans une grande poêle à feu moyen 3 à 4 min en remuant, jusqu''à ce qu''elle soit dorée et croustillante ; y mélanger le zeste de citron et une pincée de sel, puis la verser dans un bol.","Essuyer la poêle, ajouter le reste d''huile, l''ail, les câpres et une pincée de piment et cuire doucement 1 à 2 min sans colorer l''ail.","Ajouter les sardines et les briser en morceaux à la cuillère ; réchauffer 1 min.","Ajouter les spaghetti égouttés avec un peu d''eau de cuisson, le jus de citron et la majeure partie du persil, et mélanger jusqu''à ce qu''ils soient brillants.","Servir parsemé de chapelure croustillante, du reste de persil et de poivre."]},"it":{"title":"Spaghetti con sarde, limone e pangrattato","steps":["Cuocere gli spaghetti al dente in abbondante acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Nel frattempo tostare il pangrattato in 1 cucchiaio d''olio in una padella grande a fuoco medio per 3-4 min, mescolando, finché è dorato e croccante; unire la scorza di limone e un pizzico di sale e versarlo in una ciotola.","Pulire la padella, aggiungere l''olio rimasto, l''aglio, i capperi e un pizzico di peperoncino e cuocere dolcemente 1-2 min senza far colorire l''aglio.","Aggiungere le sarde e spezzettarle con un cucchiaio; scaldarle 1 min.","Unire gli spaghetti scolati con un po'' di acqua di cottura, il succo di limone e quasi tutto il prezzemolo e saltare finché sono lucidi.","Servire con il pangrattato croccante, il prezzemolo rimasto e pepe nero."]}}'::jsonb),
  ('d05206b1-877d-46fa-bc31-639b46637ae4'::uuid, '{"fr":{"title":"Tagliatelle à la bolognaise de dinde","steps":["Faire revenir la carotte, l''oignon et le céleri dans l''huile dans une sauteuse à fond épais à feu moyen 8 min.","Ajouter la dinde et l''ail, monter le feu et cuire 6 à 8 min en l''émiettant, jusqu''à ce qu''elle ne soit plus rose et commence à dorer.","Incorporer le concentré de tomate 1 min, puis verser le vin et le laisser réduire presque entièrement.","Ajouter les tomates, le lait, le laurier, un peu de muscade, du sel et du poivre, porter à frémissement et cuire doucement à couvert partiel 15 min, jusqu''à ce que la sauce soit épaisse ; ajouter un peu d''eau si elle attache.","Pendant ce temps, cuire les tagliatelle al dente dans de l''eau bouillante salée en gardant un peu d''eau de cuisson.","Retirer le laurier, mélanger les pâtes avec la sauce et un peu d''eau de cuisson, et servir avec du parmesan."]},"it":{"title":"Tagliatelle al ragù di tacchino","steps":["Appassire carota, cipolla e sedano nell''olio in un tegame dal fondo spesso a fuoco medio per 8 min.","Aggiungere il tacchino e l''aglio, alzare la fiamma e cuocere 6-8 min sgranandolo, finché non è più rosa e inizia a rosolare.","Unire il concentrato per 1 min, poi sfumare con il vino e lasciarlo evaporare quasi del tutto.","Aggiungere i pomodori, il latte, l''alloro, una grattata di noce moscata, sale e pepe, portare a bollore leggero e cuocere dolcemente semicoperto per 15 min, finché il ragù è denso; aggiungere un goccio d''acqua se attacca.","Nel frattempo cuocere le tagliatelle al dente in acqua bollente salata, tenendo da parte un po'' di acqua di cottura.","Togliere l''alloro, condire la pasta con il ragù e un goccio di acqua di cottura e servire con il parmigiano."]}}'::jsonb),
  ('b52abd15-1267-4830-a431-c33e87f52e3d'::uuid, '{"fr":{"title":"Risotto aux crevettes, petits pois et citron","steps":["Porter le fumet à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire fondre l''échalote et l''ail dans le beurre et 1 c. à soupe d''huile à feu moyen 4 min.","Ajouter le riz et remuer 2 min, jusqu''à ce que les grains deviennent translucides sur les bords, puis verser le vin et le laisser s''évaporer.","Ajouter le fumet chaud louche par louche en remuant et en le laissant absorber avant la suivante, pendant environ 12 min.","Incorporer les petits pois et les crevettes et continuer à ajouter du fumet 5 à 6 min, jusqu''à ce que les crevettes soient roses et le riz crémeux et al dente.","Hors du feu, incorporer le jus de citron, le reste d''huile, la majeure partie du persil et une pincée de piment ; assaisonner, couvrir et laisser reposer 1 min.","Servir parsemé du zeste de citron et du reste de persil."]},"it":{"title":"Risotto con gamberi, piselli e limone","steps":["Portare il fumetto a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga appassire lo scalogno e l''aglio nel burro e in 1 cucchiaio d''olio a fuoco medio per 4 min.","Unire il riso e tostarlo 2 min, finché i chicchi diventano traslucidi ai bordi, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il fumetto caldo un mestolo alla volta, mescolando e lasciandolo assorbire prima del successivo, per circa 12 min.","Unire i piselli e i gamberi e continuare ad aggiungere fumetto per altri 5-6 min, finché i gamberi sono rosa e il riso è cremoso e al dente.","Fuori dal fuoco mantecare con il succo di limone, l''olio rimasto, quasi tutto il prezzemolo e un pizzico di peperoncino; regolare di sale, coprire e lasciare riposare 1 min.","Servire con la scorza di limone e il prezzemolo rimasto."]}}'::jsonb),
  ('4c97e702-12b8-4dc5-a739-715df1150d37'::uuid, '{"fr":{"title":"Risotto au citron, petits pois et asperges","steps":["Couper les pointes d''asperges et les réserver ; tailler les tiges en tronçons de 2 cm.","Porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire fondre l''échalote dans la moitié du beurre et l''huile à feu moyen 4 min.","Ajouter le riz et le nacrer 2 min, puis verser le vin avec la moitié du jus de citron et laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant et en le laissant absorber, pendant environ 10 min ; ajouter alors les tiges d''asperges.","Après 4 min, ajouter les pointes et les petits pois et continuer à mouiller 4 à 5 min, jusqu''à ce que le riz soit crémeux et al dente et les asperges juste tendres.","Hors du feu, incorporer le reste du beurre, le parmesan, le jaune d''œuf, le zeste et le reste du jus de citron ; assaisonner, couvrir et laisser reposer 1 min.","Servir parsemé de menthe."]},"it":{"title":"Risotto al limone con piselli e asparagi","steps":["Tagliare le punte degli asparagi e tenerle da parte; tagliare i gambi a tocchetti di 2 cm.","Portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga appassire lo scalogno in metà del burro e nell''olio a fuoco medio per 4 min.","Unire il riso e tostarlo 2 min, poi sfumare con il vino e metà del succo di limone e lasciare evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando e lasciandolo assorbire, per circa 10 min; poi unire i gambi degli asparagi.","Dopo altri 4 min aggiungere le punte e i piselli e continuare a bagnare per 4-5 min, finché il riso è cremoso e al dente e gli asparagi appena teneri.","Fuori dal fuoco mantecare con il burro rimasto, il parmigiano, il tuorlo, la scorza e il resto del succo di limone; regolare di sale, coprire e lasciare riposare 1 min.","Servire con la menta."]}}'::jsonb),
  ('4427b42a-5623-490b-af00-1004887dfb98'::uuid, '{"fr":{"title":"Bar, salade de fenouil et d''orange","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres ; les égoutter et les mélanger avec 1 c. à soupe d''huile, le persil et du sel.","Pendant ce temps, peler à vif 1,5 orange et la couper en rondelles ; presser la demi-orange restante.","Mélanger le fenouil, les rondelles d''orange, l''oignon rouge et les olives avec le jus d''orange, la moitié du jus de citron, 2 c. à soupe d''huile, du sel et du poivre ; laisser reposer 10 min.","Sécher le poisson, inciser la peau à quelques endroits et assaisonner des deux côtés.","Chauffer le reste d''huile dans une poêle à feu moyen-vif et cuire les filets côté peau 3 à 4 min, en les pressant au début, jusqu''à ce que la peau soit croustillante.","Retourner et cuire encore 1 à 2 min, jusqu''à ce que la chair soit juste nacrée ; arroser du reste de jus de citron.","Servir le poisson sur la salade, parsemé de pluches de fenouil, avec les pommes de terre à côté."]},"it":{"title":"Branzino con insalata di finocchi e arance","steps":["Lessare le patate in acqua salata per 15-18 min, finché sono tenere; scolarle e condirle con 1 cucchiaio d''olio, il prezzemolo e sale.","Nel frattempo pelare a vivo 1 arancia e mezza e tagliarla a fette; spremere la mezza arancia rimasta.","Condire finocchio, fette d''arancia, cipolla rossa e olive con il succo d''arancia, metà del succo di limone, 2 cucchiai d''olio, sale e pepe; lasciare insaporire 10 min.","Asciugare il pesce, incidere la pelle in qualche punto e salare e pepare da entrambi i lati.","Scaldare l''olio rimasto in una padella a fuoco medio-alto e cuocere i filetti dal lato della pelle per 3-4 min, premendoli all''inizio, finché la pelle è croccante.","Girarli e cuocere ancora 1-2 min, finché la carne è appena opaca; irrorare con il resto del succo di limone.","Servire il pesce sull''insalata, con le barbe del finocchio, e le patate a parte."]}}'::jsonb),
  ('7f8f28eb-fb9c-48ec-9d27-6298066de40a'::uuid, '{"fr":{"title":"Gnocchis gratinés au potiron et gorgonzola","steps":["Préchauffer le four à 220 °C et porter à ébullition une casserole d''eau salée.","Cuire le potiron avec l''huile et la sauge dans une grande poêle allant au four à feu moyen 12 à 15 min, à couvert les 5 premières minutes, jusqu''à ce qu''il soit tendre ; assaisonner et en écraser environ la moitié à la fourchette.","Pousser le potiron sur le côté, faire fondre le beurre dans la poêle, ajouter la farine et remuer 1 min, puis verser le lait en fouettant et laisser épaissir légèrement 3 min.","Ajouter le gorgonzola et remuer à feu doux jusqu''à ce qu''il soit fondu et mêlé au potiron ; poivrer et muscader légèrement.","Cuire les gnocchis dans l''eau bouillante jusqu''à ce qu''ils remontent à la surface, 2 à 3 min, puis les égoutter et les incorporer dans la poêle.","Parsemer de parmesan et de noix et enfourner 10 min, jusqu''à ce que le gratin bouillonne et soit doré ; laisser reposer 3 min avant de servir."]},"it":{"title":"Gnocchi gratinati con zucca e gorgonzola","steps":["Scaldare il forno a 220 °C e portare a bollore una pentola di acqua salata.","Cuocere la zucca con l''olio e la salvia in una padella grande adatta al forno a fuoco medio per 12-15 min, coperta per i primi 5 min, finché è tenera; salare, pepare e schiacciarne circa metà con una forchetta.","Spostare la zucca da un lato, sciogliere il burro nella padella, unire la farina e mescolare 1 min, poi aggiungere il latte con la frusta e cuocere 3 min finché si addensa leggermente.","Aggiungere il gorgonzola e mescolare a fuoco basso finché è fuso e amalgamato alla zucca; pepare e profumare con poca noce moscata.","Lessare gli gnocchi nell''acqua bollente finché salgono a galla, 2-3 min, poi scolarli e unirli nella padella.","Cospargere con il parmigiano e le noci e infornare per 10 min, finché bolle e si forma una crosticina dorata; lasciare riposare 3 min prima di servire."]}}'::jsonb),
  ('2fd32898-57b1-45e1-83f9-89850157adf0'::uuid, '{"fr":{"title":"Spaghetti au saumon fumé et petits pois","steps":["Cuire les spaghetti dans une grande casserole d''eau bouillante salée en ajoutant les petits pois pendant les 3 dernières minutes.","Pendant ce temps, fouetter le yaourt, la crème, le jaune d''œuf, le parmesan, le zeste de citron, du sel et beaucoup de poivre dans un bol.","Garder un bol d''eau de cuisson, puis égoutter les pâtes et les petits pois et les remettre dans la casserole hors du feu avec 3 c. à soupe d''eau.","Verser la sauce et mélanger sur feu très doux 1 à 2 min, jusqu''à ce qu''elle soit crémeuse et enrobe les pâtes ; ne pas laisser bouillir pour que l''œuf ne coagule pas.","Incorporer le saumon fumé et la majeure partie de la ciboulette, ajouter un filet de citron et détendre avec un peu d''eau de cuisson si besoin.","Servir aussitôt avec le reste de la ciboulette et du poivre."]},"it":{"title":"Spaghetti con salmone affumicato e piselli","steps":["Cuocere gli spaghetti in abbondante acqua bollente salata, aggiungendo i piselli negli ultimi 3 min.","Nel frattempo sbattere in una ciotola lo yogurt, la panna, il tuorlo, il parmigiano, la scorza di limone, sale e abbondante pepe.","Tenere da parte una tazza di acqua di cottura, poi scolare pasta e piselli e rimetterli nella pentola fuori dal fuoco con 3 cucchiai d''acqua.","Versare la salsa e mescolare a fuoco bassissimo per 1-2 min, finché è cremosa e avvolge la pasta; non farla bollire o l''uovo si rapprende.","Unire il salmone affumicato e quasi tutta l''erba cipollina, aggiungere una spruzzata di limone e allungare con altra acqua di cottura se serve.","Servire subito con l''erba cipollina rimasta e pepe nero."]}}'::jsonb),
  ('6c246a38-571f-4eb9-b95c-baad65375613'::uuid, '{"fr":{"title":"Poulet au pesto et tomates cerises au four","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Mélanger les pommes de terre coupées en quatre avec l''huile, du sel et du poivre sur une grande plaque et rôtir 12 min.","Pendant ce temps, enrober les hauts de cuisse de poulet de 2 c. à soupe de pesto, d''un peu de sel et de poivre.","Pousser les pommes de terre sur le côté, ajouter le poulet et les quartiers d''oignon sur la plaque et rôtir 12 min.","Ajouter les tomates cerises et rôtir encore 6 à 8 min, jusqu''à ce que les tomates éclatent et que le poulet soit cuit à cœur, avec un jus clair.","Détendre le reste du pesto avec le jus de citron et le verser sur le poulet. Parsemer de basilic et servir sur la plaque."]},"it":{"title":"Teglia di pollo al pesto e pomodorini","steps":["Scaldare il forno a 220 °C (200 °C ventilato). Condire le patate tagliate in quattro con l''olio, sale e pepe su una grande teglia e arrostire 12 min.","Nel frattempo, ricoprire le sovracosce di pollo con 2 cucchiai di pesto, un po'' di sale e pepe.","Spostare le patate di lato, aggiungere il pollo e gli spicchi di cipolla nella teglia e arrostire 12 min.","Aggiungere i pomodorini e arrostire altri 6-8 min, finché i pomodorini si spaccano e il pollo è cotto all''interno, con succhi chiari.","Allungare il pesto rimasto con il succo di limone e versarlo sul pollo. Completare con il basilico e servire nella teglia."]}}'::jsonb),
  ('67056eba-a09c-484e-98ec-cf1f2b086b9e'::uuid, '{"fr":{"title":"Calzones aux champignons et mozzarella","steps":["Mélanger la farine, la levure et le sel, ajouter 160 ml d''eau tiède et 1 c. à soupe d''huile, et pétrir 8 à 10 min jusqu''à obtenir une pâte lisse et élastique. Couvrir et laisser lever environ 1 h, jusqu''à ce qu''elle double de volume.","Faire sauter les champignons dans le reste d''huile à feu vif 5 à 6 min, jusqu''à ce qu''ils soient dorés et secs ; ajouter l''ail et le thym la dernière minute.","Ajouter les épinards et remuer 1 à 2 min jusqu''à ce qu''ils tombent et que la poêle soit sèche. Saler, poivrer et laisser refroidir.","Préchauffer le four à 230 °C avec une plaque à l''intérieur. Mélanger la ricotta avec le parmesan et un peu de poivre.","Diviser la pâte en deux et étirer ou abaisser chaque pâton en un disque de 25 cm sur un plan fariné.","Étaler le coulis de tomate sur une moitié de chaque disque en laissant un bord de 2 cm, puis ajouter la ricotta, les champignons et la mozzarella.","Replier la pâte, presser et pincer fermement les bords, faire une petite cheminée et badigeonner le dessus d''un peu d''huile.","Glisser les calzones sur la plaque chaude et cuire 15 à 18 min, jusqu''à ce qu''ils soient gonflés et bien dorés. Laisser reposer 5 min avant de couper."]},"it":{"title":"Calzoni ai funghi e mozzarella","steps":["Mescolare la farina, il lievito e il sale, aggiungere 160 ml di acqua tiepida e 1 cucchiaio d''olio e impastare 8-10 min fino a ottenere un impasto liscio ed elastico. Coprire e lasciare lievitare circa 1 ora, finché raddoppia.","Saltare i funghi nell''olio rimasto a fuoco vivo per 5-6 min, finché sono dorati e asciutti; aggiungere l''aglio e il timo nell''ultimo minuto.","Aggiungere gli spinaci e mescolare 1-2 min finché appassiscono e la padella è asciutta. Salare, pepare e lasciare raffreddare.","Scaldare il forno a 230 °C con una teglia all''interno. Mescolare la ricotta con il parmigiano e un po'' di pepe.","Dividere l''impasto in due e stendere ogni pezzo in un disco di 25 cm su un piano infarinato.","Spalmare la passata su metà di ogni disco lasciando un bordo di 2 cm, poi aggiungere la ricotta, i funghi e la mozzarella.","Ripiegare l''impasto, premere e pizzicare bene i bordi, praticare un piccolo foro per il vapore e spennellare la superficie con un filo d''olio.","Far scivolare i calzoni sulla teglia calda e cuocere 15-18 min, finché sono gonfi e ben dorati. Lasciare riposare 5 min prima di tagliarli."]}}'::jsonb),
  ('f8703f9d-af88-479d-bf23-0d5a062540bc'::uuid, '{"fr":{"title":"Raviolis ricotta-citron aux petits pois","steps":["Disposer la farine en fontaine, casser les œufs au centre et mélanger à la fourchette, puis pétrir 8 à 10 min jusqu''à obtenir une pâte lisse et élastique. Filmer et laisser reposer 30 min.","Mélanger la ricotta, le parmesan, le zeste de citron, la muscade, du sel et beaucoup de poivre pour obtenir une farce ferme.","Abaisser la pâte très finement (environ 1 mm, presque transparente) au rouleau ou au laminoir, et la couper en deux longues bandes.","Déposer des cuillerées à café de farce espacées de 4 cm sur une bande, humidifier autour à l''eau, couvrir avec la seconde bande et chasser l''air autour de chaque tas de farce.","Découper les raviolis, bien presser les bords pour les souder et les poser sur un plateau fariné.","Cuire les raviolis dans une grande casserole d''eau salée à petite ébullition 3 à 4 min, en ajoutant les petits pois les 2 dernières minutes.","Pendant ce temps, faire fondre le beurre à feu doux dans une grande poêle avec un filet de jus de citron.","Transférer les raviolis et les petits pois dans la poêle à l''écumoire, ajouter une petite louche d''eau de cuisson et mélanger délicatement 1 min jusqu''à ce que ce soit brillant. Servir avec la menthe, du poivre et du parmesan."]},"it":{"title":"Ravioli ricotta e limone con piselli","steps":["Disporre la farina a fontana, rompere le uova al centro e sbattere con una forchetta, poi impastare 8-10 min fino a ottenere un impasto liscio ed elastico. Avvolgere nella pellicola e lasciare riposare 30 min.","Mescolare la ricotta, il parmigiano, la scorza di limone, la noce moscata, sale e abbondante pepe per ottenere un ripieno sodo.","Stendere la pasta molto sottile (circa 1 mm, quasi trasparente) con il mattarello o la macchina per la pasta e tagliarla in due lunghe sfoglie.","Disporre cucchiaini di ripieno a 4 cm di distanza su una sfoglia, spennellare intorno con acqua, coprire con la seconda sfoglia e premere per far uscire l''aria intorno a ogni mucchietto.","Ritagliare i ravioli, premere bene i bordi per sigillarli e disporli su un vassoio infarinato.","Cuocere i ravioli in una pentola grande di acqua salata a leggero bollore per 3-4 min, aggiungendo i piselli negli ultimi 2 min.","Nel frattempo, sciogliere il burro a fuoco basso in una padella grande con una spruzzata di succo di limone.","Trasferire ravioli e piselli nella padella con una schiumarola, aggiungere un mestolino di acqua di cottura e saltare delicatamente 1 min finché è lucido. Servire con la menta, pepe e altro parmigiano."]}}'::jsonb),
  ('3ee4b676-aad6-4e46-8795-8605729489d0'::uuid, '{"fr":{"title":"Orecchiette au brocoli et à la saucisse","steps":["Porter à ébullition une grande casserole d''eau salée et y cuire les fleurettes de brocoli à couvert 6 à 7 min, jusqu''à ce qu''elles soient tendres. Les retirer à l''écumoire et garder l''eau.","Pendant ce temps, chauffer l''huile dans une grande poêle avec l''ail, puis ajouter la chair à saucisse émiettée, le romarin, le thym et le piment et cuire à feu moyen-vif 6 à 7 min jusqu''à ce qu''elle soit dorée.","Verser le vin et laisser bouillonner 1 min jusqu''à ce qu''il ait presque disparu.","Ajouter le brocoli et cuire 3 à 4 min en écrasant une partie des fleurettes à la cuillère. Retirer l''ail et poivrer.","Remettre l''eau du brocoli à ébullition et y cuire les orecchiette juste al dente.","Transférer les pâtes dans la poêle à l''écumoire, ajouter une louche d''eau de cuisson et mélanger sur le feu 2 min jusqu''à ce que ce soit crémeux. Servir avec le parmesan."]},"it":{"title":"Orecchiette con broccoli e salsiccia","steps":["Portare a bollore una pentola grande di acqua salata e cuocere le cimette di broccoli, coperte, per 6-7 min finché sono tenere. Scolarle con una schiumarola e tenere l''acqua.","Nel frattempo, scaldare l''olio in una padella grande con l''aglio, poi aggiungere la salsiccia sbriciolata, il rosmarino, il timo e il peperoncino e rosolare a fuoco medio-alto 6-7 min finché è dorata.","Sfumare con il vino e lasciarlo evaporare per 1 min.","Aggiungere i broccoli e cuocere 3-4 min, schiacciando parte delle cimette con il cucchiaio. Togliere l''aglio e pepare.","Riportare a bollore l''acqua dei broccoli e cuocere le orecchiette al dente.","Trasferire la pasta nella padella con una schiumarola, aggiungere un mestolo di acqua di cottura e saltare sul fuoco per 2 min finché è cremosa. Servire con il parmigiano."]}}'::jsonb),
  ('25acb8ff-311c-4665-944e-84f483b0e912'::uuid, '{"fr":{"title":"Épinards aux pois chiches à la sévillane","steps":["Plonger les œufs dans l''eau bouillante et les cuire 9 min, puis les refroidir dans l''eau froide et les écaler.","Faire tomber les épinards dans une grande poêle avec un peu d''eau à feu moyen 2 à 3 min, puis les égoutter, les presser et les hacher finement.","Essuyer la poêle, chauffer l''huile et y faire dorer les gousses d''ail entières et le pain à feu moyen 2 à 3 min. Les retirer en gardant l''huile dans la poêle.","Piler l''ail et le pain au mortier avec le cumin, le paprika, le piment et une pincée de sel, puis incorporer le vinaigre, le coulis de tomate et 3 c. à soupe d''eau pour obtenir une pâte lisse.","Réchauffer l''huile, ajouter les épinards et remuer 2 min, puis incorporer la pâte et cuire encore 2 min.","Ajouter les pois chiches et environ 100 ml d''eau et laisser mijoter 5 min en remuant, jusqu''à obtenir une sauce épaisse. Rectifier l''assaisonnement.","Servir dans des assiettes creuses, garni des œufs coupés en deux et d''un peu de poivre, avec le pain pour saucer."]},"it":{"title":"Spinaci con ceci alla sivigliana","steps":["Immergere le uova in acqua bollente e cuocerle 9 min, poi raffreddarle in acqua fredda e sgusciarle.","Far appassire gli spinaci in una padella grande con un goccio d''acqua a fuoco medio per 2-3 min, poi scolarli, strizzarli e tritarli finemente.","Asciugare la padella, scaldare l''olio e dorare gli spicchi d''aglio interi e il pane a fuoco medio per 2-3 min. Toglierli, lasciando l''olio nella padella.","Pestare l''aglio e il pane nel mortaio con il cumino, la paprika, il peperoncino e un pizzico di sale, poi incorporare l''aceto, la passata e 3 cucchiai d''acqua fino a ottenere una pasta liscia.","Riscaldare l''olio, aggiungere gli spinaci e mescolare 2 min, poi unire la pasta e cuocere altri 2 min.","Aggiungere i ceci e circa 100 ml d''acqua e cuocere a fuoco lento 5 min, mescolando, finché è denso e cremoso. Regolare di sale.","Servire in piatti fondi con le uova tagliate a metà e un po'' di pepe, con il pane per raccogliere il sugo."]}}'::jsonb),
  ('6307f25f-d0c5-41b7-9da7-b1c9edcf87e7'::uuid, '{"fr":{"title":"Cabillaud poché à la tomate et aux haricots blancs","steps":["Faire revenir l''oignon et le poivron dans l''huile dans une sauteuse à feu moyen 8 min.","Ajouter l''ail et le paprika et remuer 30 s, puis verser le vin et laisser bouillonner 1 min.","Ajouter les tomates et le laurier, saler, poivrer et laisser mijoter 10 min jusqu''à ce que la sauce épaississe.","Incorporer les haricots et laisser mijoter 3 min.","Assaisonner le cabillaud, le déposer dans la sauce, couvrir et pocher à feu doux 7 à 8 min, jusqu''à ce que le poisson soit nacré et s''effeuille facilement.","Parsemer de persil et servir directement dans la sauteuse, avec du pain pour la sauce."]},"it":{"title":"Merluzzo in umido al pomodoro con fagioli bianchi","steps":["Far appassire la cipolla e il peperone nell''olio in una padella larga a fuoco medio per 8 min.","Aggiungere l''aglio e la paprika e mescolare 30 s, poi versare il vino e lasciarlo sobbollire 1 min.","Aggiungere i pomodori e l''alloro, regolare di sale e pepe e cuocere a fuoco lento 10 min finché il sugo si addensa.","Unire i fagioli e cuocere 3 min.","Condire il merluzzo, adagiarlo nel sugo, coprire e cuocere a fuoco basso 7-8 min, finché il pesce è opaco e si sfalda facilmente.","Completare con il prezzemolo e servire direttamente nella padella, con pane per il sugo."]}}'::jsonb),
  ('3c4bc8c3-19f4-40b7-b916-4f9a3660a44f'::uuid, '{"fr":{"title":"Tortilla de patatas et salade de tomates","steps":["Couper les pommes de terre en rondelles de 2 à 3 mm. Couvrir le fond d''une poêle antiadhésive de 20 cm d''1 cm d''huile d''olive et chauffer à feu moyen.","Ajouter les pommes de terre et l''oignon avec une pincée de sel et cuire doucement 15 à 20 min en remuant de temps en temps, jusqu''à ce qu''ils soient tendres mais à peine colorés.","Égoutter les pommes de terre dans une passoire au-dessus d''un bol, en gardant l''huile pour une autre fois.","Battre les œufs avec du sel, y incorporer les pommes de terre tièdes et laisser reposer 5 min.","Chauffer 1 c. à soupe de l''huile dans la poêle à feu moyen-vif, verser le mélange et cuire 3 à 4 min en secouant la poêle, jusqu''à ce que les bords soient pris.","Couvrir la poêle d''une assiette, retourner la tortilla dessus et la faire glisser à nouveau dans la poêle. Cuire encore 2 à 3 min en gardant le centre légèrement baveux.","Trancher les tomates sur une assiette, ajouter l''oignon rouge et assaisonner avec 1 c. à soupe d''huile, le vinaigre, du sel et l''origan. Servir avec la tortilla, tiède ou à température ambiante, et du pain."]},"it":{"title":"Tortilla de patatas con insalata di pomodori","steps":["Tagliare le patate a fette di 2-3 mm. Coprire il fondo di una padella antiaderente da 20 cm con 1 cm di olio d''oliva e scaldare a fuoco medio.","Aggiungere le patate e la cipolla con un pizzico di sale e cuocere dolcemente 15-20 min, girando ogni tanto, finché sono morbide ma poco colorite.","Scolare le patate in un colino sopra una ciotola, tenendo l''olio per un altro uso.","Sbattere le uova con il sale, unire le patate tiepide e lasciare riposare 5 min.","Scaldare 1 cucchiaio dell''olio nella padella a fuoco medio-alto, versare il composto e cuocere 3-4 min, scuotendo la padella, finché i bordi si rapprendono.","Coprire la padella con un piatto, capovolgere la tortilla sul piatto e farla scivolare di nuovo nella padella. Cuocere altri 2-3 min, lasciando il centro leggermente morbido.","Affettare i pomodori su un piatto, aggiungere la cipolla rossa e condire con 1 cucchiaio d''olio, l''aceto, sale e origano. Servire con la tortilla, tiepida o a temperatura ambiente, e pane."]}}'::jsonb),
  ('c47e6281-33c2-439b-ae58-28c4ee81253b'::uuid, '{"fr":{"title":"Merlu au paprika, poivrons et pommes de terre","steps":["Préchauffer le four à 220 °C. Mélanger les pommes de terre, les poivrons et l''oignon avec 2 c. à soupe d''huile, du sel et du poivre dans un plat à rôtir.","Rôtir 20 min en remuant une fois, jusqu''à ce que les pommes de terre soient tendres et commencent à dorer.","Assaisonner le merlu, le poser sur les légumes côté peau dessous et rôtir 8 à 10 min, jusqu''à ce que la chair soit nacrée et s''effeuille tout juste.","Pendant ce temps, faire revenir l''ail dans les 2 c. à soupe d''huile restantes dans une petite poêle à feu moyen-doux 2 à 3 min, jusqu''à ce qu''il soit blond.","Retirer la poêle du feu, incorporer le paprika puis le vinaigre.","Napper le poisson de l''huile chaude au paprika, parsemer de persil et servir."]},"it":{"title":"Nasello alla paprika con peperoni e patate","steps":["Scaldare il forno a 220 °C. Condire le patate, i peperoni e la cipolla con 2 cucchiai d''olio, sale e pepe in una pirofila.","Arrostire 20 min, mescolando una volta, finché le patate sono tenere e iniziano a colorire.","Condire il nasello, adagiarlo sulle verdure con la pelle in basso e arrostire 8-10 min, finché la polpa è opaca e si sfalda appena.","Nel frattempo, soffriggere l''aglio nei 2 cucchiai d''olio rimasti in un padellino a fuoco medio-basso per 2-3 min, finché è appena dorato.","Togliere il padellino dal fuoco, unire la paprika e poi l''aceto.","Versare l''olio caldo alla paprika sul pesce, completare con il prezzemolo e servire."]}}'::jsonb),
  ('0dce17d0-cb2a-43f8-9113-4566cf6ea46b'::uuid, '{"fr":{"title":"Gambas al ajillo aux haricots blancs","steps":["Griller les tranches de pain dans une poêle sèche 1 à 2 min de chaque côté, puis réserver.","Sécher les crevettes et les saler légèrement.","Chauffer l''huile, l''ail et le piment dans la poêle à feu moyen 2 à 3 min, jusqu''à ce que l''ail commence à blondir.","Monter le feu, ajouter les crevettes et cuire 1 min de chaque côté jusqu''à ce qu''elles rosissent.","Verser le xérès, saupoudrer de paprika et laisser bouillonner 30 s.","Ajouter les haricots et mélanger 2 à 3 min jusqu''à ce qu''ils soient chauds et enrobés d''huile à l''ail. Finir avec un filet de citron et le persil et servir avec le pain grillé pour saucer."]},"it":{"title":"Gamberi all''aglio con fagioli bianchi","steps":["Tostare le fette di pane in una padella asciutta 1-2 min per lato, poi tenerle da parte.","Asciugare i gamberi e salarli leggermente.","Scaldare l''olio, l''aglio e il peperoncino nella padella a fuoco medio per 2-3 min, finché l''aglio inizia a dorare.","Alzare la fiamma, aggiungere i gamberi e cuocere 1 min per lato finché diventano rosa.","Versare lo sherry, cospargere di paprika e lasciar sobbollire 30 s.","Aggiungere i fagioli e saltare 2-3 min finché sono caldi e ricoperti d''olio all''aglio. Completare con una spruzzata di limone e il prezzemolo e servire con il pane tostato per fare la scarpetta."]}}'::jsonb),
  ('f42e4280-fed9-47cc-9ccd-5bb37ad400ea'::uuid, '{"fr":{"title":"Gaspacho aux œufs et jambon serrano","steps":["Mettre les tomates, le poivron, le concombre, l''ail et le pain dans un blender avec le vinaigre, 100 ml d''eau froide et 1 c. à café de sel et mixer 2 min jusqu''à ce que ce soit parfaitement lisse.","Moteur en marche, verser l''huile jusqu''à ce que la soupe devienne crémeuse. Goûter et rectifier le sel et le vinaigre.","Passer au tamis pour une texture soyeuse si on le souhaite, puis réfrigérer au moins 2 h.","Plonger les œufs dans l''eau bouillante, les cuire 10 min, les refroidir dans l''eau froide, les écaler et les hacher.","Faire croustiller les dés de jambon dans une poêle sèche à feu moyen 3 à 4 min, puis griller les cubes de pain dans la même poêle 2 à 3 min.","Verser le gaspacho froid dans des bols et garnir d''œuf, de jambon et de croûtons."]},"it":{"title":"Gazpacho con uova e jamón","steps":["Mettere i pomodori, il peperone, il cetriolo, l''aglio e il pane nel frullatore con l''aceto, 100 ml di acqua fredda e 1 cucchiaino di sale e frullare 2 min fino a ottenere un composto perfettamente liscio.","Con il frullatore in funzione, versare l''olio finché la zuppa diventa cremosa. Assaggiare e regolare di sale e aceto.","Passare al setaccio per una consistenza vellutata, se si desidera, poi mettere in frigorifero almeno 2 ore.","Immergere le uova in acqua bollente, cuocerle 10 min, raffreddarle in acqua fredda, sgusciarle e tritarle.","Rendere croccante il jamón a dadini in una padella asciutta a fuoco medio per 3-4 min, poi tostare i cubetti di pane nella stessa padella per 2-3 min.","Versare il gazpacho freddo nelle ciotole e completare con l''uovo, il jamón e i crostini."]}}'::jsonb),
  ('5ad1bda9-8aca-4746-92bc-c6ea865e640e'::uuid, '{"fr":{"title":"Cabillaud, pois chiches croustillants et épinards","steps":["Préchauffer le four à 220 °C. Mélanger les pois chiches bien séchés avec 2 c. à soupe d''huile, le paprika, le cumin et du sel sur une plaque recouverte de papier cuisson.","Rôtir les pois chiches 15 min en secouant la plaque une fois, jusqu''à ce qu''ils commencent à croustiller.","Les pousser sur un côté, ajouter le cabillaud assaisonné, l''arroser d''un filet d''huile et rôtir 10 à 12 min, jusqu''à ce que le poisson s''effeuille facilement et que les pois chiches soient croquants.","Pendant ce temps, faire revenir l''ail dans le reste d''huile dans une grande poêle à feu moyen 1 min, ajouter les épinards et remuer 2 à 3 min jusqu''à ce qu''ils tombent. Assaisonner et ajouter un filet de citron.","Servir le cabillaud sur les épinards, parsemer de pois chiches croustillants et accompagner de quartiers de citron et de pain."]},"it":{"title":"Merluzzo con ceci croccanti e spinaci","steps":["Scaldare il forno a 220 °C. Condire i ceci ben asciugati con 2 cucchiai d''olio, la paprika, il cumino e il sale su una teglia rivestita di carta forno.","Arrostire i ceci 15 min, scuotendo la teglia una volta, finché iniziano a diventare croccanti.","Spostarli da un lato, aggiungere il merluzzo condito, irrorarlo con un filo d''olio e arrostire 10-12 min, finché il pesce si sfalda facilmente e i ceci sono croccanti.","Nel frattempo, soffriggere l''aglio nell''olio rimasto in una padella grande a fuoco medio per 1 min, aggiungere gli spinaci e mescolare 2-3 min finché appassiscono. Regolare di sale e aggiungere una spruzzata di limone.","Servire il merluzzo sugli spinaci, cospargere con i ceci croccanti e accompagnare con spicchi di limone e pane."]}}'::jsonb),
  ('4c174849-6e53-4371-be0e-fa0e67e4d60f'::uuid, '{"fr":{"title":"Riz aux crevettes à l''espagnole","steps":["Chauffer le fumet avec le safran dans une petite casserole et le garder chaud.","Chauffer l''huile dans une grande poêle ou une poêle à paella à feu vif, saisir les crevettes 1 min et les réserver.","Baisser à feu moyen et cuire ensemble l''oignon, l''ail, le poivron et le laurier 7 min jusqu''à ce qu''ils soient tendres.","Ajouter la tomate râpée et cuire 4 min à feu moyen-vif jusqu''à ce qu''elle fonce et que la poêle soit presque sèche.","Incorporer le paprika quelques secondes, puis le riz 1 min pour bien l''enrober du sofrito.","Verser le fumet chaud, saler, répartir le riz uniformément et laisser frémir à feu moyen 10 min sans remuer.","Baisser le feu et cuire encore 7 à 8 min ; déposer les crevettes dessus les 3 dernières minutes, jusqu''à ce que le riz soit tendre et le fumet absorbé.","Retirer du feu, couvrir d''un torchon propre et laisser reposer 5 min. Servir avec le persil et le citron."]},"it":{"title":"Riso con gamberi alla spagnola","steps":["Scaldare il fumetto con lo zafferano in un pentolino e tenerlo caldo.","Scaldare l''olio in una padella larga o una paellera a fuoco vivo, scottare i gamberi 1 min e tenerli da parte.","Abbassare a fuoco medio e cuocere insieme la cipolla, l''aglio, il peperone e l''alloro per 7 min finché sono morbidi.","Aggiungere il pomodoro grattugiato e cuocere 4 min a fuoco medio-alto finché scurisce e la padella è quasi asciutta.","Unire la paprika per pochi secondi, poi il riso per 1 min per insaporirlo nel soffritto.","Versare il fumetto caldo, salare, distribuire il riso in modo uniforme e cuocere a fuoco medio 10 min senza mescolare.","Abbassare la fiamma e cuocere altri 7-8 min; adagiare i gamberi sopra negli ultimi 3 min, finché il riso è tenero e il fumetto assorbito.","Togliere dal fuoco, coprire con un canovaccio pulito e lasciare riposare 5 min. Servire con prezzemolo e limone."]}}'::jsonb),
  ('a5894a47-22ee-42d7-9927-2b4caead1eef'::uuid, '{"fr":{"title":"Riz au poulet et chorizo","steps":["Assaisonner le poulet et le faire dorer dans l''huile dans une sauteuse profonde à feu moyen-vif 5 min. Réserver.","Ajouter le chorizo, l''oignon et le poivron et cuire à feu moyen 6 min, jusqu''à ce que le chorizo rende son huile rouge et que les légumes soient tendres.","Incorporer l''ail, le paprika et la tomate râpée et cuire 2 min.","Ajouter le riz et remuer 1 min pour bien l''enrober.","Verser le bouillon, émietter le safran, ajouter le laurier et le poulet, assaisonner et porter à ébullition.","Couvrir et laisser mijoter à feu doux 16 min ; parsemer les petits pois les 5 dernières minutes, jusqu''à ce que le riz soit tendre et encore un peu moelleux.","Laisser reposer 5 min hors du feu, puis servir avec le persil."]},"it":{"title":"Riso con pollo e chorizo","steps":["Condire il pollo e rosolarlo nell''olio in una padella larga e profonda a fuoco medio-alto per 5 min. Tenerlo da parte.","Aggiungere il chorizo, la cipolla e il peperone e cuocere a fuoco medio 6 min, finché il chorizo rilascia il suo olio rosso e le verdure si ammorbidiscono.","Unire l''aglio, la paprika e il pomodoro grattugiato e cuocere 2 min.","Aggiungere il riso e mescolare 1 min per insaporirlo.","Versare il brodo, sbriciolare lo zafferano, aggiungere l''alloro e il pollo, regolare di sale e pepe e portare a bollore.","Coprire e cuocere a fuoco basso 16 min; aggiungere i piselli negli ultimi 5 min, finché il riso è tenero e ancora un po'' umido.","Lasciare riposare 5 min fuori dal fuoco, poi servire con il prezzemolo."]}}'::jsonb),
  ('b44c86ec-e86c-4a74-94e1-d8ec335c05f4'::uuid, '{"fr":{"title":"Poulet à l''ail à l''espagnole","steps":["Préchauffer le four à 220 °C. Mélanger les dés de pomme de terre avec 1 c. à soupe d''huile et du sel sur une plaque et rôtir 25 à 30 min en les retournant une fois, jusqu''à ce qu''ils soient dorés (à la place des frites traditionnelles).","Faire revenir les gousses d''ail dans le reste d''huile dans une grande poêle à feu moyen 3 à 4 min jusqu''à ce que la peau soit grillée. Les retirer.","Assaisonner le poulet, le fariner légèrement et le faire dorer dans l''huile à l''ail à feu vif 8 min en le retournant, jusqu''à ce qu''il soit doré de tous côtés.","Retirer l''excès d''huile, presser le citron dessus et remettre l''ail. Ajouter le xérès et le laurier et laisser bouillonner 2 min.","Ajouter le bouillon et laisser frémir vivement 10 à 12 min en retournant le poulet, jusqu''à ce qu''il soit cuit à cœur et que la sauce ait réduit et le nappe.","Gratter le fond de la poêle, parsemer de persil et servir avec les pommes de terre."]},"it":{"title":"Pollo all''aglio alla spagnola","steps":["Scaldare il forno a 220 °C. Condire i cubetti di patate con 1 cucchiaio d''olio e il sale su una teglia e arrostire 25-30 min, girandoli una volta, finché sono dorati (al posto delle patate fritte tradizionali).","Soffriggere gli spicchi d''aglio nell''olio rimasto in una padella grande a fuoco medio per 3-4 min finché la buccia è tostata. Toglierli.","Condire il pollo, infarinarlo leggermente e rosolarlo nell''olio all''aglio a fuoco vivo per 8 min, girandolo, finché è dorato da tutti i lati.","Eliminare l''olio in eccesso, spremere sopra il limone e rimettere l''aglio. Aggiungere lo sherry e l''alloro e lasciar sobbollire 2 min.","Aggiungere il brodo e cuocere a fuoco vivace 10-12 min, girando il pollo, finché è cotto all''interno e il sugo si è ridotto e lo vela.","Raschiare il fondo della padella, completare con il prezzemolo e servire con le patate."]}}'::jsonb),
  ('a914da25-8a4d-40fd-b3ae-1857d48c52a8'::uuid, '{"fr":{"title":"Lentilles au chorizo à l''espagnole","steps":["Rincer les lentilles.","Faire revenir l''oignon, le poivron et la carotte dans l''huile dans une grande cocotte à feu moyen 8 min.","Ajouter l''ail, le paprika et la tomate râpée et cuire 3 min.","Ajouter les lentilles, la pomme de terre, le laurier, 900 ml d''eau et un peu de sel. Porter à ébullition, puis couvrir et laisser mijoter doucement 40 min en remuant de temps en temps.","Ajouter le chorizo et laisser mijoter à découvert encore 15 min, jusqu''à ce que les lentilles soient tendres et le bouillon épais et rouge. Ajouter un peu d''eau si c''est trop sec.","Rectifier le sel et laisser reposer 5 min avant de servir."]},"it":{"title":"Lenticchie con chorizo alla spagnola","steps":["Sciacquare le lenticchie.","Far appassire la cipolla, il peperone e la carota nell''olio in una pentola grande a fuoco medio per 8 min.","Aggiungere l''aglio, la paprika e il pomodoro grattugiato e cuocere 3 min.","Aggiungere le lenticchie, la patata, l''alloro, 900 ml d''acqua e un po'' di sale. Portare a bollore, poi coprire e cuocere a fuoco dolce 40 min, mescolando ogni tanto.","Aggiungere il chorizo e cuocere scoperto altri 15 min, finché le lenticchie sono tenere e il brodo è denso e rosso. Aggiungere un goccio d''acqua se si asciuga troppo.","Regolare di sale e lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('6fa70574-b4d3-46d1-83db-4e22739a81cf'::uuid, '{"fr":{"title":"Bacalhau à Brás (morue aux œufs et pommes paille)","steps":["Dessaler la morue dans beaucoup d''eau froide au réfrigérateur 24 à 36 h, en changeant l''eau toutes les 6 à 8 h.","Préchauffer le four à 220 °C. Rincer et bien sécher les allumettes de pomme de terre, les mélanger avec 1,5 c. à soupe d''huile et une pincée de sel et les étaler sur une plaque recouverte de papier cuisson.","Cuire 20 à 25 min en les retournant deux fois, jusqu''à ce qu''elles soient dorées et croustillantes (à la place des pommes paille frites traditionnelles).","Pendant ce temps, retirer la peau et les arêtes de la morue et l''effilocher finement à la main.","Pendant la cuisson des pommes de terre, faire revenir l''oignon et l''ail dans le reste d''huile dans une grande poêle à feu moyen-doux 10 min jusqu''à ce qu''ils soient tendres et dorés.","Ajouter la morue et cuire 3 à 4 min en remuant, jusqu''à ce qu''elle absorbe l''huile. Incorporer les pommes de terre.","Battre les œufs avec du poivre, les verser à feu doux et remuer 1 à 2 min ; retirer du feu tant que c''est encore crémeux, avant qu''ils ne prennent.","Servir aussitôt, garni de persil et d''olives noires."]},"it":{"title":"Bacalhau à Brás (baccalà con uova e patate)","steps":["Dissalare il baccalà in abbondante acqua fredda in frigorifero per 24-36 ore, cambiando l''acqua ogni 6-8 ore.","Scaldare il forno a 220 °C. Sciacquare e asciugare bene i fiammiferi di patate, condirli con 1,5 cucchiai d''olio e un pizzico di sale e stenderli su una teglia rivestita di carta forno.","Cuocere 20-25 min, girandoli due volte, finché sono dorati e croccanti (al posto delle patate a fiammifero fritte tradizionali).","Nel frattempo, togliere la pelle e le spine dal baccalà e sfilacciarlo finemente con le mani.","Mentre le patate cuociono, cuocere la cipolla e l''aglio nell''olio rimasto in una padella grande a fuoco medio-basso per 10 min finché sono morbidi e dorati.","Aggiungere il baccalà e cuocere 3-4 min, mescolando, finché assorbe l''olio. Unire le patate.","Sbattere le uova con il pepe, versarle a fuoco basso e mescolare 1-2 min; togliere dal fuoco quando sono ancora cremose, prima che si rapprendano.","Servire subito con prezzemolo e olive nere."]}}'::jsonb),
  ('a6c31957-1d9a-4114-b952-8037f62d3528'::uuid, '{"fr":{"title":"Pisto manchego aux œufs","steps":["Couper les tomates en deux et les râper sur une râpe, en jetant la peau.","Faire revenir l''oignon et l''ail dans 3 c. à soupe d''huile dans une sauteuse à feu doux 12 min jusqu''à ce qu''ils soient tendres.","Ajouter les poivrons et cuire encore 15 min en remuant de temps en temps, jusqu''à ce qu''ils soient très tendres.","Ajouter la courgette et cuire 8 min.","Incorporer la tomate râpée, le sucre, du sel et du poivre et cuire à feu moyen-doux 20 à 25 min à découvert, jusqu''à ce que ce soit épais, confit et sans eau.","Creuser 4 puits dans le pisto, casser un œuf dans chacun, couvrir et cuire à feu doux 5 à 6 min jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Servir directement dans la sauteuse avec beaucoup de pain."]},"it":{"title":"Pisto manchego con uova","steps":["Tagliare i pomodori a metà e grattugiarli con una grattugia, eliminando la buccia.","Cuocere la cipolla e l''aglio in 3 cucchiai d''olio in una padella larga a fuoco basso per 12 min finché sono morbidi.","Aggiungere i peperoni e cuocere altri 15 min, mescolando ogni tanto, finché sono molto teneri.","Aggiungere la zucchina e cuocere 8 min.","Unire il pomodoro grattugiato, lo zucchero, sale e pepe e cuocere a fuoco medio-basso 20-25 min, scoperto, finché è denso, morbido e senza acqua.","Fare 4 conche nel pisto, rompere un uovo in ciascuna, coprire e cuocere a fuoco basso 5-6 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Servire direttamente nella padella con abbondante pane."]}}'::jsonb),
  ('65b65923-4205-4160-98a0-f2a6c4e1c9d7'::uuid, '{"fr":{"title":"Moules à la marinera (à l''espagnole)","steps":["Gratter les moules et retirer les barbes ; jeter celles qui sont cassées ou restent ouvertes quand on les tapote.","Les mettre dans une grande cocotte avec les feuilles de laurier et 100 ml d''eau, couvrir et cuire à feu vif 3 à 4 min en secouant la cocotte, jusqu''à ce qu''elles s''ouvrent. Jeter celles qui restent fermées.","Retirer les moules, filtrer le jus de cuisson dans une passoire fine et en garder 200 ml.","Dans la cocotte essuyée, faire revenir l''oignon et l''ail dans l''huile à feu moyen 8 min jusqu''à ce qu''ils soient dorés.","Incorporer la farine 1 min, puis retirer du feu et ajouter le paprika et le piment.","Verser le vin et le jus des moules réservé et laisser mijoter 5 min en remuant, jusqu''à ce que la sauce épaississe légèrement.","Remettre les moules, ajouter presque tout le persil et mélanger 1 à 2 min jusqu''à ce qu''elles soient chaudes et nappées. Servir avec le reste du persil et du pain pour la sauce."]},"it":{"title":"Cozze alla marinera spagnola","steps":["Raschiare le cozze ed eliminare il bisso; scartare quelle rotte o che restano aperte se battute.","Metterle in una pentola grande con le foglie di alloro e 100 ml d''acqua, coprire e cuocere a fuoco vivo 3-4 min, scuotendo la pentola, finché si aprono. Scartare quelle rimaste chiuse.","Togliere le cozze, filtrare il liquido di cottura con un colino fine e tenerne 200 ml.","Nella pentola asciugata, cuocere la cipolla e l''aglio nell''olio a fuoco medio per 8 min finché sono dorati.","Unire la farina e mescolare 1 min, poi togliere dal fuoco e aggiungere la paprika e il peperoncino.","Versare il vino e il liquido delle cozze tenuto da parte e cuocere a fuoco lento 5 min, mescolando, finché si addensa leggermente.","Rimettere le cozze, aggiungere quasi tutto il prezzemolo e saltare 1-2 min finché sono calde e ben condite. Servire con il prezzemolo rimasto e pane per il sugo."]}}'::jsonb),
  ('b3a53206-d2e6-46c6-8914-d174f6f6000d'::uuid, '{"fr":{"title":"Falafels au four en pain pita","steps":["Faire tremper les pois chiches secs une nuit dans beaucoup d''eau froide (pas de pois chiches en boîte, le mélange serait trop humide), puis les égoutter et bien les sécher.","Mixer les pois chiches par à-coups au robot avec l''oignon, 1 gousse d''ail, le persil, le cumin, la coriandre, le paprika, la farine, 1 c. à soupe d''huile et 1 c. à café de sel, jusqu''à ce qu''ils soient finement hachés et se tiennent quand on les presse.","Réfrigérer le mélange au moins 1 h.","Préchauffer le four à 200 °C et huiler une plaque avec la moitié de l''huile restante.","Former des galettes de la taille d''une noix, les poser sur la plaque et badigeonner le dessus du reste d''huile.","Cuire 25 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et croustillantes.","Pendant ce temps, fouetter le tahini avec le jus de citron, le reste de l''ail râpé, une pincée de sel et 3 à 4 c. à soupe d''eau froide jusqu''à obtenir une sauce lisse et fluide.","Réchauffer les pains pita, les couper en deux, ouvrir les poches et les garnir de salade, de tomate, de concombre, de falafels et de beaucoup de sauce tahini."]},"it":{"title":"Falafel al forno nella pita","steps":["Mettere in ammollo i ceci secchi per una notte in abbondante acqua fredda (non usare ceci in scatola, il composto sarebbe troppo umido), poi scolarli e asciugarli bene.","Tritare i ceci a impulsi nel mixer con la cipolla, 1 spicchio d''aglio, il prezzemolo, il cumino, il coriandolo, la paprika, la farina, 1 cucchiaio d''olio e 1 cucchiaino di sale, finché sono tritati finemente e restano compatti se pressati.","Far riposare il composto in frigorifero almeno 1 ora.","Scaldare il forno a 200 °C e ungere una teglia con metà dell''olio rimasto.","Formare delle polpettine della grandezza di una noce, disporle sulla teglia e spennellarle sopra con l''olio rimasto.","Cuocere 25 min, girandole a metà cottura, finché sono dorate e croccanti fuori.","Nel frattempo, sbattere la tahina con il succo di limone, l''aglio rimasto grattugiato, un pizzico di sale e 3-4 cucchiai di acqua fredda fino a ottenere una salsa liscia e fluida.","Scaldare le pite, tagliarle a metà, aprire le tasche e farcirle con lattuga, pomodoro, cetriolo, i falafel e abbondante salsa di tahina."]}}'::jsonb),
  ('e7f345b6-ff62-406f-9461-f8f36fd5b1b1'::uuid, '{"fr":{"title":"Assiette de kefta de dinde et pain pita","steps":["Mélanger à la main la dinde, l''oignon, le persil, presque toute la menthe, le paprika, le cumin, la cannelle, le piment de la Jamaïque, la chapelure, 0,5 c. à café de sel et du poivre jusqu''à ce que ce soit homogène.","Former 6 keftas ovales, autour de brochettes si on en a, et les réfrigérer 10 min pendant la préparation du reste.","Mélanger le yaourt avec le zeste et le jus de citron, l''ail, le reste de la menthe et une pincée de sel.","Mélanger les tomates, le concombre et l''oignon rouge avec un peu de sel.","Chauffer une poêle-gril ou une poêle à feu moyen-vif, badigeonner les keftas d''huile et les cuire 10 à 12 min en les retournant toutes les quelques minutes, jusqu''à ce qu''elles soient dorées et cuites à cœur (74 °C au centre).","Réchauffer les pains pita dans la poêle 30 s de chaque côté et les couper en lanières.","Disposer les keftas, le pain pita, la salade et le yaourt à l''ail sur un plat et servir."]},"it":{"title":"Piatto di kofta di tacchino con pita","steps":["Impastare con le mani il tacchino, la cipolla, il prezzemolo, quasi tutta la menta, la paprika, il cumino, la cannella, il pimento, il pangrattato, mezzo cucchiaino di sale e il pepe finché è ben amalgamato.","Formare 6 kofta ovali, attorno a degli spiedini se si hanno, e metterle in frigorifero 10 min mentre si prepara il resto.","Mescolare lo yogurt con la scorza e il succo di limone, l''aglio, la menta rimasta e un pizzico di sale.","Condire i pomodorini, il cetriolo e la cipolla rossa con un po'' di sale.","Scaldare una bistecchiera o una padella a fuoco medio-alto, spennellare le kofta con l''olio e cuocerle 10-12 min, girandole ogni pochi minuti, finché sono dorate e cotte all''interno (74 °C al centro).","Scaldare le pite nella padella 30 s per lato e tagliarle a strisce.","Disporre le kofta, la pita, l''insalata e lo yogurt all''aglio su un piatto da portata e servire."]}}'::jsonb),
  ('b75b8190-ec3f-49c7-86f1-ccd3ae433c1e'::uuid, '{"fr":{"title":"Pitas au souvlaki de porc","steps":["Mélanger le jus d''un demi-citron, l''ail écrasé, le vinaigre, le miel, 1 c. à café d''origan, le paprika, le cumin, 2 c. à soupe d''huile, du sel et du poivre. Y enrober le porc, couvrir et réfrigérer au moins 1 h (jusqu''à une nuit).","Râper la moitié du concombre, bien l''essorer et l''incorporer au yaourt avec la gousse d''ail restante, l''aneth, un filet de citron, du sel et un trait d''huile.","Couper le reste du concombre en dés et le mélanger avec la tomate, l''oignon rouge, le reste de l''origan, un peu d''huile et du sel.","Enfiler le porc sur 4 brochettes. Faire chauffer une poêle-gril à feu vif jusqu''à ce qu''elle fume.","Griller les brochettes 8 à 10 min en les tournant toutes les 2 min, jusqu''à ce qu''elles soient grillées dehors et juste cuites, à peine rosées au centre. Laisser reposer 3 min.","Réchauffer les pitas 30 s de chaque côté dans la poêle chaude.","Garnir chaque pita de tzatziki, de porc, de salade de tomates et d''un filet de citron ; replier et servir."]},"it":{"title":"Pita con souvlaki di maiale","steps":["Mescolare il succo di mezzo limone, l''aglio schiacciato, l''aceto, il miele, 1 cucchiaino di origano, la paprika, il cumino, 2 cucchiai d''olio, sale e pepe. Condire il maiale, coprire e lasciare in frigo almeno 1 h (fino a una notte).","Grattugiare metà del cetriolo, strizzarlo bene e unirlo allo yogurt con lo spicchio d''aglio rimasto, l''aneto, una spruzzata di limone, sale e un filo d''olio.","Tagliare a dadini il resto del cetriolo e condirlo con il pomodoro, la cipolla rossa, l''origano rimasto, un filo d''olio e sale.","Infilzare il maiale su 4 spiedini. Scaldare una bistecchiera a fuoco vivo finché fuma.","Grigliare gli spiedini 8-10 min, girandoli ogni 2 min, finché sono abbrustoliti fuori e appena cotti, solo leggermente rosati al centro. Lasciare riposare 3 min.","Scaldare le pita 30 s per lato nella bistecchiera calda.","Farcire ogni pita con tzatziki, maiale, insalata di pomodori e una spruzzata di limone; richiudere e servire."]}}'::jsonb),
  ('f8d5e8fc-4632-4270-9051-27105174a375'::uuid, '{"fr":{"title":"Gemista à la viande","steps":["Préchauffer le four à 180 °C. Couper le chapeau des poivrons et des tomates et les garder comme couvercles. Épépiner les poivrons ; évider les tomates dans un bol et hacher finement la chair en gardant le jus.","Saler l''intérieur des légumes, ajouter une pincée de sucre et les placer debout dans un plat à four.","Faire suer l''oignon dans 2 c. à soupe d''huile à feu moyen, 5 min. Ajouter le bœuf et le faire dorer 5 min en l''émiettant, puis incorporer l''ail.","Ajouter le riz et remuer 1 min, puis le concentré de tomate, la moitié de la chair de tomate hachée et 100 ml d''eau. Laisser mijoter 5 min jusqu''à ce que le riz soit à moitié cuit ; hors du feu, ajouter le persil, la menthe, du sel et du poivre.","Remplir les légumes aux trois quarts (le riz gonfle), répartir le reste de chair de tomate dessus et remettre les chapeaux.","Glisser les quartiers de pomme de terre entre les légumes, assaisonner, arroser le tout de 2 c. à soupe d''huile et verser 200 ml d''eau dans le plat.","Couvrir de papier aluminium et cuire 50 min, puis découvrir et cuire encore 25 à 30 min en arrosant une fois, jusqu''à ce que le riz soit tendre et le dessus bien coloré. Ajouter un peu d''eau si le plat se dessèche.","Laisser reposer 10 min et servir tiède avec la feta."]},"it":{"title":"Gemista con carne","steps":["Scaldare il forno a 180 °C. Tagliare la calotta di peperoni e pomodori e tenerla come coperchio. Svuotare i peperoni dai semi; scavare la polpa dei pomodori in una ciotola e tritarla finemente, tenendo il succo.","Salare l''interno degli ortaggi, aggiungere un pizzico di zucchero e sistemarli in piedi in una pirofila.","Appassire la cipolla in 2 cucchiai d''olio a fuoco medio, 5 min. Aggiungere il manzo e rosolarlo 5 min sgranandolo, poi unire l''aglio.","Aggiungere il riso e mescolare 1 min, poi il concentrato, metà della polpa di pomodoro e 100 ml d''acqua. Cuocere 5 min finché il riso è a metà cottura; fuori dal fuoco unire prezzemolo, menta, sale e pepe.","Riempire gli ortaggi per tre quarti (il riso si gonfia), distribuire sopra il resto della polpa di pomodoro e rimettere le calotte.","Sistemare gli spicchi di patata tra gli ortaggi, condire, irrorare tutto con 2 cucchiai d''olio e versare 200 ml d''acqua nella pirofila.","Coprire con alluminio e cuocere 50 min, poi scoprire e cuocere altri 25-30 min, bagnando una volta, finché il riso è tenero e la superficie abbrustolita. Aggiungere un goccio d''acqua se si asciuga troppo.","Lasciare riposare 10 min e servire tiepido con la feta."]}}'::jsonb),
  ('b635672f-00b1-4632-b8a6-4c0172b0cc29'::uuid, '{"fr":{"title":"Köfte de bœuf, boulgour à la tomate","steps":["Essorer l''oignon râpé, puis le pétrir avec le bœuf, l''ail, le persil, le cumin, le paprika, le piment, du sel et du poivre pendant 2 min jusqu''à ce que la farce colle.","Diviser en 6 et presser chaque portion autour d''une brochette en boudin de 12 cm. Réfrigérer pendant la préparation du boulgour.","Faire suer l''oignon haché dans le beurre et 1 c. à soupe d''huile à feu moyen, 5 min. Ajouter le concentré de tomate 1 min, puis la tomate râpée 2 min.","Ajouter le boulgour, le bouillon et une pincée de sel. Porter à ébullition, couvrir et cuire à feu très doux 12 min, jusqu''à absorption du liquide.","Retirer du feu, glisser un torchon propre sous le couvercle et laisser gonfler 10 min.","Pendant ce temps, badigeonner les köfte d''huile et les cuire dans une poêle-gril très chaude 8 à 10 min en les tournant toutes les 2 min, jusqu''à ce qu''elles soient dorées et cuites à cœur.","Égrener le boulgour et servir avec les köfte, le yaourt et des quartiers de citron."]},"it":{"title":"Kofta di manzo con bulgur al pomodoro","steps":["Strizzare la cipolla grattugiata, poi impastarla con il manzo, l''aglio, il prezzemolo, il cumino, la paprika, il peperoncino, sale e pepe per 2 min finché l''impasto è compatto.","Dividere in 6 e modellare ogni porzione attorno a uno spiedino in un salsicciotto di 12 cm. Mettere in frigo mentre si prepara il bulgur.","Appassire la cipolla tritata nel burro e 1 cucchiaio d''olio a fuoco medio, 5 min. Unire il concentrato per 1 min, poi il pomodoro grattugiato per 2 min.","Aggiungere il bulgur, il brodo e un pizzico di sale. Portare a bollore, coprire e cuocere a fuoco minimo 12 min, finché il liquido è assorbito.","Togliere dal fuoco, mettere un canovaccio pulito sotto il coperchio e lasciare riposare 10 min.","Nel frattempo spennellare le kofta d''olio e cuocerle in una bistecchiera rovente 8-10 min, girandole ogni 2 min, finché sono dorate e cotte all''interno.","Sgranare il bulgur e servire con le kofta, lo yogurt e spicchi di limone."]}}'::jsonb),
  ('f3ca2b5c-b4ad-4f57-869b-798303f6f839'::uuid, '{"fr":{"title":"Moussaka aux lentilles et aubergines","steps":["Préchauffer le four à 200 °C. Badigeonner les tranches d''aubergine et de pomme de terre de 3 c. à soupe d''huile, assaisonner et rôtir sur une plaque chemisée 25 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient tendres et dorées.","Pendant ce temps, faire suer l''oignon dans 1 c. à soupe d''huile dans une casserole, 6 min. Ajouter l''ail, l''origan et la cannelle 1 min.","Ajouter les lentilles rincées, le coulis, le concentré de tomate et 300 ml d''eau. Laisser mijoter à demi couvert 30 min, jusqu''à ce que les lentilles soient tendres et la sauce épaisse. Assaisonner et répartir dans un petit plat à four (environ 20 x 15 cm) en alternant avec les légumes : sauce, légumes, sauce, légumes.","Rincer la casserole. Faire fondre le beurre, ajouter la farine et remuer 1 min, puis incorporer le lait petit à petit au fouet et laisser épaissir 3 à 4 min en fouettant. Saler, poivrer et ajouter de la muscade.","Hors du feu, incorporer l''œuf et la moitié du parmesan au fouet.","Verser la béchamel sur les légumes, parsemer du reste de parmesan et cuire à 180 °C pendant 35 min, jusqu''à ce que le dessus soit doré et bouillonnant.","Laisser reposer 10 min avant de découper, pour que les couches se tiennent."]},"it":{"title":"Moussaka di lenticchie e melanzane","steps":["Scaldare il forno a 200 °C. Spennellare le fette di melanzana e di patata con 3 cucchiai d''olio, condire e arrostire su una teglia foderata 25 min, girandole a metà, finché sono morbide e dorate.","Nel frattempo appassire la cipolla in 1 cucchiaio d''olio in una casseruola, 6 min. Unire aglio, origano e cannella per 1 min.","Aggiungere le lenticchie sciacquate, la passata, il concentrato e 300 ml d''acqua. Cuocere semicoperto 30 min, finché le lenticchie sono tenere e il sugo denso. Regolare di sale e distribuire in una piccola pirofila (circa 20 x 15 cm) alternando con le verdure: sugo, verdure, sugo, verdure.","Sciacquare la casseruola. Sciogliere il burro, unire la farina e mescolare 1 min, poi aggiungere il latte poco alla volta con la frusta e cuocere 3-4 min mescolando, finché si addensa. Condire con sale, pepe e noce moscata.","Fuori dal fuoco, incorporare l''uovo e metà del parmigiano con la frusta.","Versare la besciamella sulle verdure, cospargere con il resto del parmigiano e cuocere a 180 °C per 35 min, finché è dorata e sobbolle.","Lasciare riposare 10 min prima di tagliare, così gli strati restano compatti."]}}'::jsonb),
  ('a72b6524-b539-48e5-9e9c-77744a5cb4dc'::uuid, '{"fr":{"title":"Gigantes plaki (haricots géants à la tomate)","steps":["Dans une grande sauteuse, faire revenir doucement l''oignon, la carotte et le céleri dans 4 c. à soupe d''huile avec une pincée de sel 8 min, jusqu''à ce qu''ils soient tendres sans colorer.","Ajouter l''ail et le piment 30 s, puis le concentré de tomate 1 min.","Ajouter les tomates concassées, le bouillon, le laurier, le sucre et la moitié de l''aneth. Porter à frémissement, assaisonner, puis incorporer les haricots.","Couvrir et laisser mijoter doucement 20 min en remuant de temps en temps, jusqu''à ce que les haricots soient très tendres et la sauce épaisse et confite. Ajouter un peu d''eau si cela attache.","Retirer le laurier, ajouter le reste de l''aneth et laisser reposer 5 min hors du feu (c''est meilleur tiède que brûlant).","Servir avec la feta émiettée, un filet d''huile, le persil et le pain."]},"it":{"title":"Gigantes plaki (fagioloni al pomodoro)","steps":["In una padella larga e profonda, cuocere dolcemente cipolla, carota e sedano in 4 cucchiai d''olio con un pizzico di sale per 8 min, finché sono morbidi ma non coloriti.","Aggiungere l''aglio e il peperoncino per 30 s, poi il concentrato per 1 min.","Unire i pomodori pelati, il brodo, l''alloro, lo zucchero e metà dell''aneto. Portare a sobbollire, regolare di sale, poi incorporare i fagioli.","Coprire e cuocere dolcemente 20 min, mescolando ogni tanto, finché i fagioli sono molto teneri e il sugo denso. Aggiungere un goccio d''acqua se attacca.","Togliere l''alloro, unire il resto dell''aneto e lasciare riposare 5 min fuori dal fuoco (è più buono tiepido che bollente).","Servire con la feta sbriciolata, un filo d''olio, il prezzemolo e il pane."]}}'::jsonb),
  ('d03d756a-f782-4067-8ef2-a6c2887809d7'::uuid, '{"fr":{"title":"Arni me melitzanes (agneau aux aubergines)","steps":["Préchauffer le four à 180 °C. Saler et poivrer l''agneau.","Dans une cocotte allant au four, dorer les tranches d''aubergine dans 2 c. à soupe d''huile à feu moyen-vif, 2 à 3 min par face, en ajoutant un peu d''huile seulement si la cocotte est sèche. Réserver.","Dorer l''agneau dans 1 c. à soupe d''huile dans la même cocotte, 6 à 8 min en le retournant, jusqu''à ce qu''il soit coloré de partout. Verser le vin et laisser bouillonner 1 min.","Pousser l''agneau sur le côté et faire suer l''oignon et le céleri 5 min, puis ajouter l''ail, l''origan, le paprika et le cumin 1 min.","Ajouter les tomates, 100 ml d''eau et le romarin, assaisonner et porter à frémissement. Disposer l''aubergine par-dessus.","Couvrir et cuire au four 1 h 45, jusqu''à ce que l''agneau soit très tendre. Découvrir, mélanger pour que de l''agneau se retrouve sur le dessus et cuire encore 15 min pour colorer.","Pendant ce temps, environ 20 min avant la fin, cuire le riz : le laisser mijoter à couvert dans 200 ml d''eau salée 12 min, puis reposer 5 min.","Servir le ragoût sur le riz avec une cuillerée de yaourt."]},"it":{"title":"Arni me melitzanes (agnello con melanzane)","steps":["Scaldare il forno a 180 °C. Salare e pepare l''agnello.","In una casseruola adatta al forno, rosolare le fette di melanzana in 2 cucchiai d''olio a fuoco medio-alto, 2-3 min per lato, aggiungendo olio solo se la pentola è asciutta. Mettere da parte.","Rosolare l''agnello in 1 cucchiaio d''olio nella stessa casseruola, 6-8 min, girandolo, finché è colorito ovunque. Versare il vino e lasciarlo sfumare 1 min.","Spostare l''agnello di lato e appassire cipolla e sedano 5 min, poi aggiungere aglio, origano, paprika e cumino per 1 min.","Unire i pomodori, 100 ml d''acqua e il rosmarino, regolare di sale e portare a sobbollire. Adagiare sopra le melanzane.","Coprire e cuocere in forno 1 h 45 min, finché l''agnello è molto tenero. Scoprire, mescolare in modo che un po'' di agnello resti in superficie e cuocere altri 15 min per colorire.","Nel frattempo, circa 20 min prima della fine, cuocere il riso: sobbollire coperto in 200 ml d''acqua salata 12 min, poi riposare 5 min.","Servire lo spezzatino sul riso con un cucchiaio di yogurt."]}}'::jsonb),
  ('d79d51a5-0384-4a66-b807-ef9f7af3a3ef'::uuid, '{"fr":{"title":"Mercimek çorbası (soupe turque aux lentilles)","steps":["Faire suer l''oignon dans 2 c. à soupe d''huile avec une pincée de sel à feu moyen-doux, 6 à 8 min.","Ajouter l''ail, le cumin et le concentré de tomate et faire revenir 3 min en remuant, jusqu''à ce que le concentré fonce.","Ajouter les lentilles, la carotte, la pomme de terre et le bouillon. Porter à ébullition, écumer, puis couvrir et laisser mijoter doucement 18 à 20 min, jusqu''à ce que tout soit très tendre.","Mixer au mixeur plongeant jusqu''à obtenir un velouté lisse ; détendre avec un peu d''eau chaude si c''est trop épais, saler et poivrer.","Dans une petite poêle, faire fondre le beurre avec 1 c. à soupe d''huile, ajouter le piment d''Alep et remuer 1 min à feu doux, jusqu''à ce que le gras devienne rouge.","Servir la soupe dans des bols, arroser de beurre rouge, parsemer de persil et servir avec du citron à presser et le pain."]},"it":{"title":"Mercimek çorbası (zuppa turca di lenticchie)","steps":["Appassire la cipolla in 2 cucchiai d''olio con un pizzico di sale a fuoco medio-basso, 6-8 min.","Aggiungere aglio, cumino e concentrato e soffriggere 3 min mescolando, finché il concentrato si scurisce.","Unire le lenticchie, la carota, la patata e il brodo. Portare a bollore, schiumare, poi coprire e cuocere dolcemente 18-20 min, finché tutto è molto morbido.","Frullare con il frullatore a immersione fino a ottenere una crema liscia; allungare con poca acqua calda se è troppo densa e regolare di sale e pepe.","In un pentolino sciogliere il burro con 1 cucchiaio d''olio, aggiungere il pepe di Aleppo e mescolare 1 min a fuoco basso finché il grasso diventa rosso.","Versare la zuppa nelle ciotole, irrorare con il burro rosso, cospargere di prezzemolo e servire con limone da spremere e il pane."]}}'::jsonb),
  ('10663b06-3c7d-4f2f-a1f9-e2aded01352b'::uuid, '{"fr":{"title":"Sabich","steps":["Préchauffer le four à 220 °C. Badigeonner généreusement d''huile les deux faces des tranches d''aubergine, assaisonner et rôtir sur une plaque chemisée 25 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et fondantes.","Pendant ce temps, plonger les œufs dans l''eau frémissante et les cuire 9 min, puis les refroidir sous l''eau froide, les écaler et les trancher.","Fouetter le tahini avec 1 gousse d''ail écrasée, le jus d''un demi-citron, une pincée de sel et 3 à 4 c. à soupe d''eau froide jusqu''à ce que la sauce soit lisse et coulante.","Écraser grossièrement les pois chiches à la fourchette avec l''autre gousse d''ail, le cumin, 1 c. à soupe d''huile, un filet de citron et du sel.","Mélanger la tomate, le concombre, l''oignon et la moitié du persil avec un filet de citron, un trait d''huile et du sel.","Réchauffer les pitas 2 min au four, puis les ouvrir en poche.","Tartiner l''intérieur de pois chiches, puis superposer aubergine, œuf et salade en arrosant de tahini entre les couches. Finir avec du tahini, un filet d''amba et du persil, et manger aussitôt."]},"it":{"title":"Sabich","steps":["Scaldare il forno a 220 °C. Spennellare abbondantemente d''olio le fette di melanzana su entrambi i lati, condire e arrostire su una teglia foderata 25 min, girandole a metà, finché sono ben dorate e cremose.","Nel frattempo calare le uova in acqua che sobbolle e cuocerle 9 min, poi raffreddarle sotto l''acqua fredda, sgusciarle e affettarle.","Sbattere la tahina con 1 spicchio d''aglio schiacciato, il succo di mezzo limone, un pizzico di sale e 3-4 cucchiai d''acqua fredda fino a ottenere una salsa liscia e fluida.","Schiacciare grossolanamente i ceci con una forchetta insieme all''altro spicchio d''aglio, al cumino, a 1 cucchiaio d''olio, a una spruzzata di limone e al sale.","Mescolare pomodoro, cetriolo, cipolla e metà del prezzemolo con una spruzzata di limone, un filo d''olio e sale.","Scaldare le pita in forno 2 min, poi aprirle a tasca.","Spalmare i ceci all''interno, poi alternare melanzana, uovo e insalata, versando la tahina tra gli strati. Finire con tahina, un filo di amba e prezzemolo e mangiare subito."]}}'::jsonb),
  ('7ff53ecb-a890-45d5-b340-46719ce3ae64'::uuid, '{"fr":{"title":"Plateau shawarma de chou-fleur et pois chiches","steps":["Préchauffer le four à 220 °C et chemiser une grande plaque.","Fouetter 3 c. à soupe d''huile avec le jus d''un demi-citron, 2 gousses d''ail, le cumin, la coriandre moulue, le paprika, le curcuma, la cannelle, le piment en poudre et 1 c. à café de sel.","Enrober le chou-fleur, les pois chiches et l''oignon de cette huile épicée et les étaler en une seule couche sur la plaque.","Rôtir 30 min en secouant la plaque à mi-cuisson, jusqu''à ce que le chou-fleur soit tendre et grillé sur les bords et les pois chiches croustillants. Réchauffer les pitas sur la grille du four les 2 dernières minutes.","Pendant ce temps, fouetter le tahini, le yaourt, le miel, le reste de l''ail, le zeste et le jus de l''autre moitié de citron, une pincée de sel et assez d''eau pour obtenir une sauce coulante.","Disposer les légumes sur un plat, arroser de sauce au tahini et parsemer de persil. Servir avec les pitas déchirées et des cornichons."]},"it":{"title":"Piatto shawarma di cavolfiore e ceci","steps":["Scaldare il forno a 220 °C e foderare una teglia grande.","Sbattere 3 cucchiai d''olio con il succo di mezzo limone, 2 spicchi d''aglio, il cumino, il coriandolo in polvere, la paprika, la curcuma, la cannella, il peperoncino in polvere e 1 cucchiaino di sale.","Condire il cavolfiore, i ceci e la cipolla con l''olio speziato e distribuirli in un solo strato sulla teglia.","Arrostire 30 min, scuotendo la teglia a metà, finché il cavolfiore è tenero e abbrustolito ai bordi e i ceci croccanti. Scaldare le pita sulla griglia del forno negli ultimi 2 min.","Nel frattempo sbattere tahina, yogurt, miele, l''aglio rimasto, la scorza e il succo dell''altra metà del limone, un pizzico di sale e acqua quanto basta per una salsa fluida.","Disporre le verdure su un piatto da portata, irrorare con la salsa alla tahina e cospargere di prezzemolo. Servire con le pita spezzettate e i cetriolini."]}}'::jsonb),
  ('92e6216c-d5d6-4d6c-9483-31a0b88ceac4'::uuid, '{"fr":{"title":"Salade de semoule au halloumi et aux pêches","steps":["Mettre la semoule dans un bol avec 1 c. à café d''huile et une pincée de sel, verser le bouillon bouillant, couvrir et laisser gonfler 5 min.","Fouetter 2 c. à soupe d''huile, le jus du citron, le miel, la moutarde, le piment, du sel et du poivre.","Égrener la semoule à la fourchette et la mélanger avec la moitié de la vinaigrette et l''oignon rouge ; laisser tiédir.","Faire chauffer une poêle-gril ou une poêle antiadhésive à feu moyen-vif. Badigeonner les quartiers de pêche d''un peu d''huile et les cuire 1 à 2 min par face, jusqu''à ce qu''ils soient marqués. Réserver.","Sécher le halloumi et le cuire dans la même poêle 2 min par face, jusqu''à ce qu''il soit doré.","Mélanger la semoule avec la roquette et la menthe, garnir des pêches et du halloumi chaud, arroser du reste de vinaigrette et parsemer de pistaches."]},"it":{"title":"Insalata di cous cous con halloumi e pesche","steps":["Mettere il cous cous in una ciotola con 1 cucchiaino d''olio e un pizzico di sale, versare il brodo bollente, coprire e lasciare riposare 5 min.","Sbattere 2 cucchiai d''olio, il succo del limone, il miele, la senape, il peperoncino, sale e pepe.","Sgranare il cous cous con una forchetta e condirlo con metà del condimento e la cipolla rossa; lasciare intiepidire.","Scaldare una bistecchiera o una padella antiaderente a fuoco medio-alto. Spennellare gli spicchi di pesca con poco olio e cuocerli 1-2 min per lato finché sono segnati. Mettere da parte.","Asciugare l''halloumi e cuocerlo nella stessa padella 2 min per lato, finché è dorato.","Mescolare il cous cous con la rucola e la menta, completare con le pesche e l''halloumi caldo, condire con il resto del condimento e cospargere di pistacchi."]}}'::jsonb),
  ('69d6a6a6-0d99-43e5-b62f-57968b7e02c9'::uuid, '{"fr":{"title":"Burgers d''agneau à la feta, salade de tomates","steps":["Presser la tomate râpée dans la main pour l''égoutter, puis la mélanger à l''agneau avec l''ail, la moitié de l''origan, la menthe, le persil, du sel et du poivre. Former 2 steaks de 2 cm d''épaisseur et réfrigérer 15 min.","Écraser la feta dans le yaourt avec un peu de poivre pour obtenir une sauce épaisse.","Mélanger les quartiers de tomate, le concombre, l''oignon rouge et les olives avec le vinaigre, 1 c. à soupe d''huile, le reste de l''origan et du sel.","Faire chauffer une poêle-gril à feu moyen-vif et cuire les burgers 4 à 5 min par face, jusqu''à ce qu''ils soient bien dorés et cuits à cœur. Laisser reposer 2 min.","Toaster la face coupée des pains dans la poêle, 1 min.","Tartiner les pains de sauce à la feta, ajouter les steaks et servir la salade de tomates à côté."]},"it":{"title":"Burger di agnello con feta e insalata di pomodori","steps":["Strizzare con la mano il pomodoro grattugiato per scolarlo, poi unirlo all''agnello con l''aglio, metà dell''origano, la menta, il prezzemolo, sale e pepe. Formare 2 hamburger spessi 2 cm e metterli in frigo 15 min.","Schiacciare la feta nello yogurt con un po'' di pepe per ottenere una salsa densa.","Condire gli spicchi di pomodoro, il cetriolo, la cipolla rossa e le olive con l''aceto, 1 cucchiaio d''olio, l''origano rimasto e sale.","Scaldare una bistecchiera a fuoco medio-alto e cuocere gli hamburger 4-5 min per lato, finché sono ben rosolati e cotti all''interno. Lasciare riposare 2 min.","Tostare il lato tagliato dei panini nella bistecchiera, 1 min.","Spalmare i panini con la salsa alla feta, aggiungere gli hamburger e servire l''insalata di pomodori a parte."]}}'::jsonb),
  ('a8b8e77d-d4d8-4caa-9ef0-913a096603a2'::uuid, '{"fr":{"title":"Kleftiko d''agneau","steps":["Mélanger le jus du citron, le vin, 3 c. à soupe d''huile, 1 gousse d''ail hachée, l''origan, 1 c. à café de sel et du poivre. En frotter l''agneau, couvrir et réfrigérer 2 h (ou une nuit). Le sortir 30 min avant la cuisson.","Préchauffer le four à 160 °C. Poser deux longues feuilles de papier cuisson en croix dans un plat à rôtir.","Entasser au centre les pommes de terre, l''oignon, le poivron et les tomates, assaisonner, puis poser l''agneau dessus avec sa marinade, les gousses d''ail restantes coupées en deux et le romarin.","Rabattre le papier sur le tout et le plier ou le ficeler pour former une papillote bien fermée ; couvrir aussi le plat de papier aluminium.","Cuire 2 h 30, jusqu''à ce que l''agneau s''effiloche à la fourchette. S''il résiste, refermer et cuire encore 20 min.","Réserver l''agneau sur une assiette, couvert. Monter le four à 200 °C, ouvrir la papillote, parsemer les légumes de feta et rôtir 20 min, jusqu''à ce que les pommes de terre dorent sur les bords.","Servir l''agneau avec les pommes de terre, nappé du jus de cuisson."]},"it":{"title":"Kleftiko di agnello","steps":["Mescolare il succo del limone, il vino, 3 cucchiai d''olio, 1 spicchio d''aglio tritato, l''origano, 1 cucchiaino di sale e pepe. Massaggiare l''agnello con il composto, coprire e lasciare in frigo 2 h (o una notte). Toglierlo dal frigo 30 min prima della cottura.","Scaldare il forno a 160 °C. Stendere due lunghi fogli di carta forno incrociati in una teglia.","Ammucchiare al centro patate, cipolla, peperone e pomodorini, condire, poi adagiare sopra l''agnello con la marinata, gli spicchi d''aglio rimasti tagliati a metà e il rosmarino.","Ripiegare la carta su tutto e chiuderla o legarla bene a cartoccio; coprire anche la teglia con alluminio.","Cuocere 2 h 30 min, finché l''agnello si sfilaccia con una forchetta. Se resiste, richiudere e cuocere altri 20 min.","Spostare l''agnello su un piatto e coprirlo. Alzare il forno a 200 °C, aprire il cartoccio, cospargere le verdure di feta e arrostire 20 min, finché le patate si dorano ai bordi.","Servire l''agnello con le patate, irrorato con il fondo di cottura."]}}'::jsonb),
  ('2f2c73a4-dbc5-4175-9822-235754fff440'::uuid, '{"fr":{"title":"Stifado de bœuf","steps":["Préchauffer le four à 170 °C. Assaisonner le bœuf et le dorer en plusieurs fois dans 2 c. à soupe d''huile dans une cocotte allant au four, à feu moyen-vif, 2 à 3 min par face. Réserver.","Baisser à feu moyen et dorer les oignons grelots dans la même cocotte 5 min en secouant, puis ajouter l''ail et le concentré de tomate 1 min.","Verser le vin et le vinaigre et laisser bouillonner 2 min en grattant les sucs.","Ajouter les tomates, le bouillon, la cannelle, les clous de girofle, le piment de la Jamaïque et le laurier, remettre le bœuf avec son jus et porter à frémissement.","Couvrir et cuire au four 2 h, jusqu''à ce que le bœuf soit fondant et les oignons grelots tendres mais entiers.","Environ 25 min avant la fin, cuire les pommes de terre 20 min à l''eau salée, les égoutter et les écraser grossièrement avec 2 c. à soupe d''huile, du sel et du poivre.","Si la sauce est trop liquide, laisser mijoter le ragoût à découvert sur le feu 10 min. Retirer la cannelle, les clous et le laurier, rectifier l''assaisonnement et servir sur les pommes de terre avec du persil."]},"it":{"title":"Stifado di manzo","steps":["Scaldare il forno a 170 °C. Salare e pepare il manzo e rosolarlo a più riprese in 2 cucchiai d''olio in una casseruola adatta al forno, a fuoco medio-alto, 2-3 min per lato. Mettere da parte.","Abbassare a fuoco medio e rosolare le cipolline nella stessa pentola 5 min scuotendola, poi aggiungere l''aglio e il concentrato per 1 min.","Versare il vino e l''aceto e far bollire 2 min, staccando il fondo.","Unire i pomodori, il brodo, la cannella, i chiodi di garofano, il pimento e l''alloro, rimettere il manzo con il suo sugo e portare a sobbollire.","Coprire e cuocere in forno 2 h, finché il manzo è tenerissimo e le cipolline morbide ma intere.","Circa 25 min prima della fine, lessare le patate in acqua salata 20 min finché sono tenere, scolarle e schiacciarle grossolanamente con 2 cucchiai d''olio, sale e pepe.","Se il sugo è liquido, far sobbollire lo stufato scoperto sul fuoco 10 min. Togliere cannella, chiodi di garofano e alloro, regolare di sale e servire sulle patate con il prezzemolo."]}}'::jsonb),
  ('1f05ce54-f8c8-49bf-a3d4-5cba3cdbdbc8'::uuid, '{"fr":{"title":"Youvetsi (bœuf et orzo au four)","steps":["Assaisonner le bœuf et le dorer dans 2 c. à soupe d''huile dans une cocotte allant au four, à feu moyen-vif, 2 à 3 min par face. Réserver.","Baisser le feu et faire suer l''oignon et la carotte 4 min, puis ajouter l''ail 1 min et le concentré de tomate 1 min.","Verser le vin et laisser bouillonner 1 min, puis ajouter les tomates, la cannelle, le laurier, 350 ml de bouillon et le bœuf avec son jus.","Couvrir et laisser mijoter doucement 1 h 30 en remuant de temps en temps, jusqu''à ce que le bœuf soit très tendre. Préchauffer le four à 180 °C vers la fin.","Porter à ébullition les 400 ml de bouillon restants. Incorporer l''orzo et le bouillon chaud dans la cocotte, assaisonner et reporter à frémissement.","Cuire au four à découvert 25 à 30 min en remuant une fois à mi-cuisson, jusqu''à ce que l''orzo soit tendre et ait absorbé presque toute la sauce.","Laisser reposer 10 min (cela épaissit en reposant), retirer la cannelle et le laurier et servir avec le kefalotyri."]},"it":{"title":"Giouvetsi (manzo e orzo al forno)","steps":["Salare e pepare il manzo e rosolarlo in 2 cucchiai d''olio in una casseruola adatta al forno, a fuoco medio-alto, 2-3 min per lato. Mettere da parte.","Abbassare il fuoco e appassire cipolla e carota 4 min, poi aggiungere l''aglio per 1 min e il concentrato per 1 min.","Versare il vino e lasciarlo sfumare 1 min, poi unire i pomodori, la cannella, l''alloro, 350 ml di brodo e il manzo con il suo sugo.","Coprire e cuocere dolcemente 1 h 30 min, mescolando ogni tanto, finché il manzo è molto tenero. Verso la fine scaldare il forno a 180 °C.","Portare a bollore i 400 ml di brodo rimasti. Unire l''orzo e il brodo caldo nella casseruola, regolare di sale e riportare a sobbollire.","Cuocere in forno scoperto 25-30 min, mescolando una volta a metà, finché l''orzo è tenero e ha assorbito quasi tutto il sugo.","Lasciare riposare 10 min (si addensa riposando), togliere cannella e alloro e servire con il kefalotyri."]}}'::jsonb),
  ('91ce129b-6f6d-476b-8e00-f0497a49ac72'::uuid, '{"fr":{"title":"Karnıyarık (aubergines farcies)","steps":["Préchauffer le four à 220 °C. Quadriller profondément la face coupée de chaque demi-aubergine sans percer la peau, saler et laisser 10 min, puis éponger.","Badigeonner les aubergines de 3 c. à soupe d''huile et les rôtir face coupée en dessous dans un plat à four 20 min, jusqu''à ce qu''elles soient tendres et dorées.","Pendant ce temps, faire suer l''oignon et le poivron dans 1 c. à soupe d''huile à feu moyen, 6 min. Ajouter le bœuf et cuire 5 min en l''émiettant, jusqu''à ce que son jus se soit évaporé.","Ajouter l''ail, le concentré de tomate et le piment d''Alep 1 min, puis la moitié de la tomate en dés. Laisser mijoter 3 min, assaisonner et ajouter presque tout le persil.","Retourner les aubergines face coupée vers le haut et ouvrir la chair à la cuillère pour former une fente profonde. Garnir de viande, couvrir du reste de tomate et verser 100 ml d''eau dans le plat.","Remettre le plat au four à 220 °C, sans couvrir, 10 min, jusqu''à ce que la farce bouillonne et que le dessus soit doré.","Réchauffer le pain sur la grille du four les 3 dernières minutes.","Servir les aubergines avec leur jus, le pain, le yaourt et le reste du persil."]},"it":{"title":"Karnıyarık (melanzane ripiene)","steps":["Scaldare il forno a 220 °C. Incidere a griglia in profondità il lato tagliato di ogni mezza melanzana senza bucare la buccia, salare e lasciare 10 min, poi asciugare.","Spennellare le melanzane con 3 cucchiai d''olio e arrostirle con il lato tagliato verso il basso in una pirofila 20 min, finché sono morbide e dorate.","Nel frattempo appassire cipolla e peperone in 1 cucchiaio d''olio a fuoco medio, 6 min. Aggiungere il manzo e cuocere 5 min sgranandolo, finché il liquido è evaporato.","Unire aglio, concentrato e pepe di Aleppo per 1 min, poi metà del pomodoro a dadini. Cuocere 3 min, regolare di sale e aggiungere quasi tutto il prezzemolo.","Girare le melanzane con il lato tagliato verso l''alto e aprire la polpa con un cucchiaio formando un taglio profondo. Farcire con la carne, coprire con il pomodoro rimasto e versare 100 ml d''acqua nella pirofila.","Rimettere la pirofila in forno a 220 °C, scoperta, per 10 min, finché il ripieno sobbolle e la superficie è dorata.","Scaldare il pane sulla griglia del forno negli ultimi 3 min.","Servire le melanzane con il loro sugo, il pane, lo yogurt e il prezzemolo rimasto."]}}'::jsonb),
  ('ba157b8e-c181-409e-b432-61f3f90fc64e'::uuid, '{"fr":{"title":"Menemen","steps":["Faire chauffer le beurre et 1 c. à soupe d''huile dans une grande poêle à feu moyen. Ajouter le poivron (et l''oignon, si on en met) avec une pincée de sel et cuire 5 min jusqu''à ce qu''il soit tendre.","Ajouter les tomates et le piment d''Alep, couvrir et cuire 5 à 6 min en remuant une fois, jusqu''à ce que les tomates fondent en une sauce épaisse.","Battre légèrement les œufs avec du sel et du poivre.","Baisser le feu, verser les œufs et remuer lentement à la spatule 2 à 3 min en les mêlant à la sauce, jusqu''à ce qu''ils soient juste pris et encore moelleux.","Parsemer de feta et de persil et servir directement dans la poêle avec le pain."]},"it":{"title":"Menemen","steps":["Scaldare il burro e 1 cucchiaio d''olio in una padella larga a fuoco medio. Aggiungere il peperone (e la cipolla, se si usa) con un pizzico di sale e cuocere 5 min finché è morbido.","Unire i pomodori e il pepe di Aleppo, coprire e cuocere 5-6 min, mescolando una volta, finché i pomodori si disfano in un sugo denso.","Sbattere leggermente le uova con sale e pepe.","Abbassare il fuoco, versare le uova e mescolare lentamente con una spatola per 2-3 min, amalgamandole al sugo, finché sono appena rapprese e ancora morbide.","Cospargere di feta e prezzemolo e servire direttamente in padella con il pane."]}}'::jsonb),
  ('6b1436ee-7841-465f-b752-b7b18bd352ba'::uuid, '{"fr":{"title":"Fattouche au poulet grillé","steps":["Frotter le poulet avec 1 c. à soupe d''huile, 2 gousses d''ail, 1 c. à café de sumac, le paprika, le jus d''un demi-citron et du sel. Laisser reposer 20 min.","Préchauffer le four à 200 °C. Ouvrir les pitas, les déchirer en morceaux, les mélanger avec 1 c. à soupe d''huile et une pincée de sel et les cuire 8 à 10 min jusqu''à ce qu''ils soient croustillants et dorés.","Fouetter 3 c. à soupe d''huile avec le jus d''un citron, le vinaigre, le reste de l''ail et du sumac, du sel et du poivre.","Faire chauffer une poêle-gril à feu moyen-vif et cuire le poulet 5 à 6 min par face, jusqu''à ce qu''il soit grillé et cuit à cœur (plus rose au centre). Laisser reposer 5 min, puis trancher.","Mélanger la laitue, la tomate, le concombre, les radis, l''oignon nouveau, le persil et la menthe avec la vinaigrette.","Incorporer les chips de pita juste avant de servir, garnir de poulet et presser le dernier demi-citron par-dessus."]},"it":{"title":"Fattoush con pollo alla griglia","steps":["Massaggiare il pollo con 1 cucchiaio d''olio, 2 spicchi d''aglio, 1 cucchiaino di sumac, la paprika, il succo di mezzo limone e sale. Lasciare riposare 20 min.","Scaldare il forno a 200 °C. Aprire le pita, spezzettarle, condirle con 1 cucchiaio d''olio e un pizzico di sale e cuocerle 8-10 min finché sono croccanti e dorate.","Sbattere 3 cucchiai d''olio con il succo di 1 limone, l''aceto, l''aglio e il sumac rimasti, sale e pepe.","Scaldare una bistecchiera a fuoco medio-alto e cuocere il pollo 5-6 min per lato, finché è abbrustolito e cotto all''interno (non più rosa al centro). Lasciare riposare 5 min, poi affettare.","Condire la lattuga, il pomodoro, il cetriolo, i ravanelli, il cipollotto, il prezzemolo e la menta con la salsa.","Unire le chips di pita appena prima di servire, completare con il pollo e spremere sopra l''ultima metà di limone."]}}'::jsonb),
  ('2a07c7e1-2a5b-461d-b203-27a73373f305'::uuid, '{"fr":{"title":"Shish taouk, sauce à l''ail","steps":["Fouetter le yaourt nature, le jus d''un citron, 1 c. à soupe d''huile, le concentré de tomate, la moutarde, 3 gousses d''ail, le paprika, le sumac, la cannelle, 1 c. à café de sel et du poivre. Y enrober le poulet, couvrir et réfrigérer au moins 2 h (jusqu''à une nuit).","Pour la sauce à l''ail, écraser la dernière gousse avec une pincée de sel en purée, puis l''incorporer au fouet au yaourt grec avec 1 c. à soupe d''huile et un filet de citron. Réfrigérer.","Enfiler le poulet sur des brochettes, en alternant avec le poivron et l''oignon si on en met.","Faire chauffer une poêle-gril à feu moyen-vif, la huiler et cuire les brochettes 10 à 12 min en les tournant toutes les 3 min, jusqu''à ce qu''elles soient grillées sur les bords et cuites à cœur.","Laisser reposer 5 min sous une feuille d''aluminium pendant que les pitas chauffent dans la poêle.","Servir les brochettes avec les pitas, la sauce à l''ail, la tomate, les cornichons et le reste du citron en quartiers."]},"it":{"title":"Shish tawook con salsa all''aglio","steps":["Sbattere lo yogurt bianco, il succo di 1 limone, 1 cucchiaio d''olio, il concentrato, la senape, 3 spicchi d''aglio, paprika, sumac, cannella, 1 cucchiaino di sale e pepe. Condire il pollo, coprire e lasciare in frigo almeno 2 h (fino a una notte).","Per la salsa all''aglio, schiacciare l''ultimo spicchio con un pizzico di sale fino a ridurlo in crema, poi unirlo con la frusta allo yogurt greco con 1 cucchiaio d''olio e una spruzzata di limone. Mettere in frigo.","Infilzare il pollo sugli spiedini, alternandolo con peperone e cipolla se si usano.","Scaldare una bistecchiera a fuoco medio-alto, ungerla e cuocere gli spiedini 10-12 min, girandoli ogni 3 min, finché sono abbrustoliti ai bordi e cotti all''interno.","Lasciare riposare 5 min sotto un foglio di alluminio mentre si scaldano le pita nella bistecchiera.","Servire gli spiedini con le pita, la salsa all''aglio, il pomodoro, i cetriolini e il resto del limone a spicchi."]}}'::jsonb),
  ('0c76e1d2-3d8c-460e-b515-bb545d5fa83f'::uuid, '{"fr":{"title":"Moujadara au halloumi","steps":["Couvrir les lentilles de 500 ml d''eau dans une casserole, porter à ébullition et cuire 15 min, jusqu''à ce qu''elles soient juste tendres mais encore entières. Égoutter en gardant le liquide.","En même temps, cuire les oignons dans 4 c. à soupe d''huile avec une pincée de sel dans une grande poêle à feu moyen, en remuant souvent, 25 à 30 min, jusqu''à ce qu''ils soient bien bruns ; monter le feu les 3 dernières minutes pour qu''une partie croustille.","Remettre les lentilles dans la casserole avec le riz, le cumin, le piment de la Jamaïque, 1 c. à café de sel, du poivre et 280 ml du liquide des lentilles (compléter avec de l''eau). Porter à ébullition, couvrir et cuire à feu très doux 15 min.","Hors du feu, incorporer à la fourchette les deux tiers des oignons avec leur huile, couvrir et laisser reposer 10 min. Garder le reste des oignons sur une assiette.","Pendant ce temps, essuyer la poêle et cuire le halloumi à feu moyen-vif 2 min par face, jusqu''à ce qu''il soit doré.","Garnir la moujadara des oignons croustillants et du halloumi et servir avec du yaourt et une salade de tomate, concombre et persil hachés."]},"it":{"title":"Mujaddara con halloumi","steps":["Coprire le lenticchie con 500 ml d''acqua in una casseruola, portare a bollore e cuocere 15 min, finché sono appena tenere ma intere. Scolarle tenendo il liquido.","Nello stesso tempo cuocere le cipolle in 4 cucchiai d''olio con un pizzico di sale in una padella larga a fuoco medio, mescolando spesso, 25-30 min, finché sono ben brunite; alzare il fuoco negli ultimi 3 min perché una parte diventi croccante.","Rimettere le lenticchie nella casseruola con il riso, il cumino, il pimento, 1 cucchiaino di sale, pepe e 280 ml del liquido delle lenticchie (completare con acqua). Portare a bollore, coprire e cuocere a fuoco minimo 15 min.","Fuori dal fuoco unire con una forchetta due terzi delle cipolle con il loro olio, coprire e lasciare riposare 10 min. Tenere il resto delle cipolle su un piatto.","Nel frattempo pulire la padella e cuocere l''halloumi a fuoco medio-alto 2 min per lato, finché è dorato.","Completare la mujaddara con le cipolle croccanti e l''halloumi e servire con yogurt e un''insalata di pomodoro, cetriolo e prezzemolo tritati."]}}'::jsonb),
  ('6ed4612b-73f6-4d13-bbe9-4b00aaa15141'::uuid, '{"fr":{"title":"Tajine de pois chiches aux abricots et semoule","steps":["Faire revenir l''oignon dans 2 c. à soupe d''huile avec une pincée de sel dans une grande sauteuse à feu moyen, à couvert, 8 min jusqu''à ce qu''il soit tendre et brillant.","Ajouter l''ail, le gingembre et le ras el hanout et remuer 1 min jusqu''à ce que les épices embaument.","Ajouter la carotte et la patate douce et bien les enrober, puis les pois chiches, les tomates, le bouillon et les abricots. Porter à ébullition, couvrir et laisser mijoter 20 min, jusqu''à ce que les légumes soient tendres et la sauce épaissie.","Pendant ce temps, mettre la semoule dans un bol avec le zeste râpé du citron, 1 c. à café d''huile et une pincée de sel, verser 130 ml d''eau bouillante, couvrir et laisser gonfler 5 min, puis égrener à la fourchette.","Faire griller les amandes à sec dans une poêle 2 min jusqu''à ce qu''elles soient dorées, en surveillant.","Assaisonner le tajine de sel, de poivre et d''un filet de citron. Servir sur la semoule, garni d''amandes, d''une cuillerée de yaourt et de coriandre."]},"it":{"title":"Tajine di ceci e albicocche con cous cous","steps":["Cuocere la cipolla in 2 cucchiai d''olio con un pizzico di sale in una pentola larga a fuoco medio, coperta, 8 min finché è morbida e lucida.","Aggiungere aglio, zenzero e ras el hanout e mescolare 1 min finché profumano.","Unire la carota e la patata dolce mescolando bene, poi i ceci, i pomodori, il brodo e le albicocche. Portare a bollore, coprire e cuocere 20 min, finché le verdure sono tenere e il sugo si è addensato.","Nel frattempo mettere il cous cous in una ciotola con la scorza grattugiata del limone, 1 cucchiaino d''olio e un pizzico di sale, versare 130 ml d''acqua bollente, coprire e lasciare 5 min, poi sgranare con una forchetta.","Tostare le mandorle in una padella asciutta per 2 min finché sono dorate, sorvegliandole.","Regolare il tajine di sale, pepe e una spruzzata di limone. Servire sul cous cous, con le mandorle, un cucchiaio di yogurt e il coriandolo."]}}'::jsonb),
  ('c24af535-ff47-498a-a075-d6f86716f8c9'::uuid, '{"fr":{"title":"Boulettes d''agneau aux pois chiches et tomate","steps":["Mélanger l''agneau avec l''oignon râpé, 1 gousse d''ail, la majeure partie du persil, 1 c. à café de cumin, 1 c. à café de paprika, la cannelle, du sel et du poivre. Former 14 à 16 boulettes de la taille d''une noix.","Faire dorer les boulettes dans 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif, 6 à 8 min en les retournant, puis les réserver sur une assiette.","Faire fondre l''oignon haché dans la même poêle à feu moyen 6 min, puis ajouter le reste de l''ail, du cumin et du paprika ainsi que la harissa et remuer 1 min.","Ajouter les tomates, les pois chiches et 100 ml d''eau, assaisonner et porter à frémissement.","Remettre les boulettes, couvrir et laisser mijoter doucement 15 min, jusqu''à ce qu''elles soient cuites à cœur et la sauce épaissie.","Parsemer du reste de persil et servir avec du pain plat chaud."]},"it":{"title":"Polpette d''agnello con ceci al pomodoro","steps":["Mescolare l''agnello con la cipolla grattugiata, 1 spicchio d''aglio, quasi tutto il prezzemolo, 1 cucchiaino di cumino, 1 cucchiaino di paprika, la cannella, sale e pepe. Formare 14-16 polpette grandi come una noce.","Rosolare le polpette in 1 cucchiaio d''olio in una padella larga a fuoco medio-alto, 6-8 min girandole, poi metterle da parte su un piatto.","Appassire la cipolla tritata nella stessa padella a fuoco medio per 6 min, poi aggiungere l''aglio, il cumino e la paprika rimasti e la harissa e mescolare 1 min.","Aggiungere i pomodori, i ceci e 100 ml d''acqua, salare e portare a sobbollire.","Rimettere le polpette, coprire e cuocere a fuoco dolce 15 min, finché sono cotte all''interno e il sugo si è addensato.","Cospargere con il prezzemolo rimasto e servire con pane piatto caldo."]}}'::jsonb),
  ('3d018581-d136-4665-a2dc-1caf7eef3fbd'::uuid, '{"fr":{"title":"Couscous royal","steps":["Faire dorer l''agneau dans 1 c. à soupe d''huile dans un grand faitout à feu moyen-vif, 5 min. Ajouter l''oignon et cuire 3 min.","Incorporer le concentré de tomate, 1,5 c. à café de ras el hanout, le paprika, du sel et du poivre, verser le bouillon et laisser frémir à couvert à moitié 30 min.","Ajouter les carottes et le navet et laisser frémir 15 min.","Pendant ce temps, faire dorer les hauts de cuisse dans une poêle avec un peu d''huile, 4 min de chaque côté, puis les ajouter au faitout avec les courgettes, les pois chiches et le safran ; laisser frémir encore 25 min, jusqu''à ce que l''agneau soit tendre.","Cuire les merguez dans la poêle à feu moyen, 8 à 10 min en les retournant, jusqu''à ce qu''elles soient dorées et cuites.","Mettre la semoule dans un saladier avec le reste du ras el hanout, une pincée de sel et un filet d''huile ; verser 180 ml de bouillon chaud, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette en y incorporant le beurre.","Servir la semoule garnie des viandes et des légumes, avec un bol de bouillon à part, relevé d''un peu de harissa pour ceux qui aiment le piquant."]},"it":{"title":"Cuscus royal","steps":["Rosolare l''agnello in 1 cucchiaio d''olio in una pentola capiente a fuoco medio-alto, 5 min. Aggiungere la cipolla e cuocere 3 min.","Unire il concentrato di pomodoro, 1,5 cucchiaini di ras el hanout, la paprika, sale e pepe, versare il brodo e cuocere a fuoco dolce, semicoperto, 30 min.","Aggiungere le carote e la rapa e cuocere 15 min.","Nel frattempo rosolare le sovracosce in una padella con un filo d''olio, 4 min per lato, poi unirle alla pentola con le zucchine, i ceci e lo zafferano; cuocere ancora 25 min, finché l''agnello è tenero.","Cuocere le merguez nella padella a fuoco medio, 8-10 min girandole, finché sono dorate e cotte.","Mettere il cuscus in una ciotola con il ras el hanout rimasto, un pizzico di sale e un filo d''olio; versare 180 ml di brodo caldo, coprire e lasciare riposare 5 min.","Sgranare il cuscus con una forchetta incorporando il burro.","Servire il cuscus con sopra le carni e le verdure, con una ciotola di brodo a parte e un po'' di harissa sciolta dentro per chi ama il piccante."]}}'::jsonb),
  ('9a6ee5cf-200e-4579-9433-3f98f473c9de'::uuid, '{"fr":{"title":"Tajine d''agneau aux pruneaux","steps":["Faire fondre l''oignon dans 1 c. à soupe d''huile dans une cocotte à feu moyen, 3 à 4 min.","Ajouter l''agneau, le bâton de cannelle, le curcuma, le gingembre, beaucoup de poivre et un peu de sel ; bien enrober, puis verser 300 ml d''eau.","Porter à ébullition, couvrir et laisser mijoter très doucement 1 h 15, jusqu''à ce que l''agneau soit presque tendre ; ajouter un peu d''eau si cela attache.","Ajouter les pruneaux et cuire encore 20 min à couvert.","Mélanger le miel et la cannelle moulue à la sauce et laisser mijoter 15 min à découvert, jusqu''à ce qu''elle soit épaisse et brillante.","Pendant ce temps, faire griller les amandes à sec dans une poêle à feu moyen, 3 à 4 min en remuant, jusqu''à ce qu''elles soient dorées.","Servir le tajine parsemé d''amandes et de graines de sésame, avec du pain pour saucer."]},"it":{"title":"Tajine d''agnello alle prugne","steps":["Appassire la cipolla in 1 cucchiaio d''olio in una pentola dal fondo spesso a fuoco medio, 3-4 min.","Aggiungere l''agnello, la stecca di cannella, la curcuma, lo zenzero, abbondante pepe e un po'' di sale; mescolare bene, poi versare 300 ml d''acqua.","Portare a bollore, coprire e cuocere a fuoco dolcissimo 1 h 15, finché l''agnello è quasi tenero; aggiungere un goccio d''acqua se si asciuga.","Aggiungere le prugne e cuocere ancora 20 min, coperto.","Mescolare il miele e la cannella in polvere nel sugo e cuocere scoperto 15 min, finché è denso e lucido.","Nel frattempo tostare le mandorle in una padella asciutta a fuoco medio, 3-4 min scuotendo, finché sono dorate.","Servire il tajine cosparso di mandorle e semi di sesamo, con pane per fare la scarpetta."]}}'::jsonb),
  ('5f6175e0-2fa4-486d-a240-ed5a45569174'::uuid, '{"fr":{"title":"Tajine de kefta aux œufs","steps":["Mélanger le bœuf avec l''oignon râpé, la moitié du persil, 1 c. à café de cumin, 1 c. à café de paprika, la cannelle, du sel et du poivre. Former de petites boulettes d''environ 3 cm.","Faire fondre l''oignon haché et l''ail dans 1 c. à soupe d''huile dans une grande sauteuse avec couvercle (ou un tajine) à feu moyen, 4 min.","Ajouter le reste du cumin et du paprika, le curcuma et le piment, puis les tomates et 100 ml d''eau ; assaisonner et laisser mijoter 8 min, jusqu''à ce que la sauce épaississe légèrement.","Déposer les boulettes dans la sauce, couvrir et laisser mijoter doucement 12 min en les retournant une fois.","Creuser 3 puits entre les boulettes et y casser un œuf. Couvrir et cuire 5 à 6 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer du reste de persil et de coriandre et servir directement dans le plat avec du pain."]},"it":{"title":"Tajine di kefta con uova","steps":["Mescolare il manzo con la cipolla grattugiata, metà del prezzemolo, 1 cucchiaino di cumino, 1 cucchiaino di paprika, la cannella, sale e pepe. Formare piccole polpette di circa 3 cm.","Appassire la cipolla tritata e l''aglio in 1 cucchiaio d''olio in una padella larga con coperchio (o un tajine) a fuoco medio, 4 min.","Aggiungere il cumino e la paprika rimasti, la curcuma e il peperoncino, poi i pomodori e 100 ml d''acqua; salare e cuocere 8 min, finché il sugo si addensa leggermente.","Adagiare le polpette nel sugo, coprire e cuocere a fuoco dolce 12 min, girandole una volta.","Formare 3 incavi tra le polpette e rompervi un uovo ciascuno. Coprire e cuocere 5-6 min, finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere con il prezzemolo rimasto e il coriandolo e servire direttamente dalla padella con il pane."]}}'::jsonb),
  ('8f203224-5bb8-48d2-8fcc-dfa1e8e3c43b'::uuid, '{"fr":{"title":"Harira","steps":["Faire dorer l''agneau dans 1 c. à soupe d''huile dans un grand faitout à feu moyen-vif, 5 min.","Ajouter l''oignon, le céleri et la majeure partie du persil et cuire 5 min, puis incorporer le gingembre, le curcuma, la cannelle, 0,5 c. à café de poivre et le concentré de tomate 1 min.","Ajouter les tomates, les lentilles et le bouillon, porter à ébullition, puis couvrir et laisser mijoter doucement 40 min, jusqu''à ce que l''agneau et les lentilles soient tendres.","Ajouter les pois chiches et les vermicelles et laisser frémir 8 min.","Délayer la farine dans 100 ml d''eau froide, la verser en filet dans la soupe en remuant et laisser frémir 3 à 4 min, jusqu''à ce qu''elle devienne veloutée.","Battre l''œuf, puis le verser en filet dans la soupe frémissante en remuant pour qu''il prenne en fins filaments ; saler.","Servir avec le reste du persil, la coriandre et des quartiers de citron à presser."]},"it":{"title":"Harira","steps":["Rosolare l''agnello in 1 cucchiaio d''olio in una pentola capiente a fuoco medio-alto, 5 min.","Aggiungere la cipolla, il sedano e quasi tutto il prezzemolo e cuocere 5 min, poi unire lo zenzero, la curcuma, la cannella, 0,5 cucchiaini di pepe e il concentrato di pomodoro per 1 min.","Aggiungere i pomodori, le lenticchie e il brodo, portare a bollore, poi coprire e cuocere a fuoco dolce 40 min, finché l''agnello e le lenticchie sono teneri.","Aggiungere i ceci e i vermicelli e cuocere 8 min.","Stemperare la farina in 100 ml d''acqua fredda, versarla a filo nella zuppa mescolando e cuocere 3-4 min, finché diventa vellutata.","Sbattere l''uovo, poi versarlo a filo nella zuppa che sobbolle mescolando, perché si rapprenda in fili sottili; salare.","Servire con il prezzemolo rimasto, il coriandolo e spicchi di limone da spremere."]}}'::jsonb),
  ('5d13af89-d872-4a64-91e2-ab41f15ff8a1'::uuid, '{"fr":{"title":"Tajine de poisson au cabillaud","steps":["Préparer la chermoula : mélanger le persil, la coriandre, l''ail, le cumin, le paprika, le piment, le jus du demi-citron, 2 c. à soupe d''huile et une bonne pincée de sel.","Enrober le cabillaud de la moitié de la chermoula et le laisser au réfrigérateur pendant la préparation des légumes.","Étaler l''oignon au fond d''une grande sauteuse avec couvercle (ou d''un tajine) avec la dernière c. à soupe d''huile. Disposer la carotte, puis les pommes de terre, et assaisonner de curcuma, de gingembre, de sel et de poivre.","Disposer la tomate et le poivron par-dessus, napper du reste de chermoula et ajouter 120 ml d''eau.","Couvrir et cuire à feu moyen 18 à 20 min, jusqu''à ce que les pommes de terre soient presque tendres sous la pointe d''un couteau.","Poser le cabillaud dessus avec les olives et l''écorce de citron confit, couvrir et cuire 8 à 10 min, jusqu''à ce que le poisson s''effeuille facilement et que le liquide ait réduit en sauce.","Servir directement dans le plat."]},"it":{"title":"Tajine di pesce con merluzzo","steps":["Preparare la chermoula: mescolare prezzemolo, coriandolo, aglio, cumino, paprika, peperoncino, il succo del mezzo limone, 2 cucchiai d''olio e un buon pizzico di sale.","Condire il merluzzo con metà della chermoula e lasciarlo in frigorifero mentre si preparano le verdure.","Distribuire la cipolla sul fondo di una padella larga con coperchio (o di un tajine) con l''ultimo cucchiaio d''olio. Disporre a strati la carota, poi le patate, e condire con curcuma, zenzero, sale e pepe.","Adagiare sopra il pomodoro e il peperone, distribuire la chermoula rimasta e aggiungere 120 ml d''acqua.","Coprire e cuocere a fuoco medio 18-20 min, finché le patate sono quasi tenere alla prova del coltello.","Adagiare sopra il merluzzo con le olive e la scorza del limone sotto sale, coprire e cuocere 8-10 min, finché il pesce si sfalda facilmente e il liquido si è ridotto in salsa.","Servire direttamente dalla padella."]}}'::jsonb),
  ('bbf7ab1c-0133-41c4-be33-4ff4253271c4'::uuid, '{"fr":{"title":"Couscous merguez et légumes rôtis","steps":["Préchauffer le four à 220 °C. Mélanger l''aubergine, la courgette, le poivron et l''oignon sur une grande plaque avec 3 c. à soupe d''huile, le ras el hanout, du sel et du poivre, et les étaler en une seule couche.","Rôtir 12 min, puis remuer et poser les merguez dessus.","Rôtir encore 15 min en retournant les merguez une fois, jusqu''à ce qu''elles soient dorées et les légumes fondants et caramélisés sur les bords.","Pendant ce temps, porter le bouillon à ébullition, le verser sur la semoule dans un saladier avec 1 c. à café d''huile, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette et y mélanger les légumes rôtis avec le jus de cuisson et le jus de citron.","Servir garni des merguez, de menthe et d''un peu de harissa."]},"it":{"title":"Cuscus con merguez e verdure arrosto","steps":["Scaldare il forno a 220 °C. Condire melanzana, zucchina, peperone e cipolla su una teglia grande con 3 cucchiai d''olio, il ras el hanout, sale e pepe, e distribuirli in un solo strato.","Arrostire 12 min, poi mescolare e adagiare sopra le merguez.","Arrostire ancora 15 min girando le merguez una volta, finché sono dorate e le verdure morbide e caramellate ai bordi.","Nel frattempo portare a bollore il brodo, versarlo sul cuscus in una ciotola con 1 cucchiaino d''olio, coprire e lasciare riposare 5 min.","Sgranare il cuscus con una forchetta e unire le verdure arrosto con il fondo di cottura e il succo di limone.","Servire con sopra le merguez, la menta e un po'' di harissa."]}}'::jsonb),
  ('ea0abd75-bf32-4718-9c3a-4ccfd8fc9917'::uuid, '{"fr":{"title":"Crevettes à la chermoula et semoule","steps":["Mélanger la coriandre, le persil, l''ail, le cumin, le paprika, le piment, le zeste et le jus d''un demi-citron, 2 c. à soupe d''huile et une pincée de sel pour obtenir une chermoula fluide.","Enrober les crevettes de la moitié de la chermoula et laisser reposer 5 min.","Porter le bouillon à ébullition, le verser sur la semoule dans un saladier avec 1 c. à café d''huile, couvrir et laisser gonfler 5 min, puis égrener à la fourchette et incorporer la carotte râpée.","Cuire les crevettes dans une poêle bien chaude avec le reste de l''huile à feu moyen-vif, 3 à 4 min en les retournant une fois, jusqu''à ce qu''elles soient roses et juste cuites.","Déposer les crevettes sur la semoule, arroser du reste de chermoula et servir avec l''autre demi-citron en quartiers."]},"it":{"title":"Gamberi alla chermoula con cuscus","steps":["Mescolare coriandolo, prezzemolo, aglio, cumino, paprika, peperoncino, la scorza e il succo di mezzo limone, 2 cucchiai d''olio e un pizzico di sale per ottenere una chermoula fluida.","Condire i gamberi con metà della chermoula e lasciare riposare 5 min.","Portare a bollore il brodo, versarlo sul cuscus in una ciotola con 1 cucchiaino d''olio, coprire e lasciare riposare 5 min, poi sgranare con una forchetta e unire la carota grattugiata.","Cuocere i gamberi in una padella ben calda con l''olio rimasto a fuoco medio-alto, 3-4 min girandoli una volta, finché sono rosa e appena cotti.","Disporre i gamberi sul cuscus, condire con la chermoula rimasta e servire con l''altra metà del limone a spicchi."]}}'::jsonb),
  ('c4a8b76a-90e0-4bbd-9679-d04cd71870d9'::uuid, '{"fr":{"title":"Dal de lentilles corail au lait de coco et riz","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; le laisser gonfler 5 min hors du feu.","Pendant ce temps, faire fondre l''oignon dans 1 c. à soupe d''huile dans une casserole à feu moyen, 5 min.","Ajouter l''ail, le gingembre et le piment et cuire 1 min, puis le cumin, la coriandre moulue, le curcuma et la cannelle 30 s.","Ajouter les lentilles, la tomate, le lait de coco et 450 ml d''eau. Porter à ébullition, puis laisser mijoter à couvert à moitié 20 min en remuant souvent, jusqu''à ce que les lentilles se défassent en une purée épaisse ; ajouter de l''eau si besoin.","Assaisonner de sel et de jus de citron.","Chauffer 1 c. à soupe d''huile dans une petite poêle, ajouter les graines de moutarde et les laisser éclater 30 s, puis verser sur le dal. Servir avec le riz et la coriandre."]},"it":{"title":"Dal di lenticchie rosse al cocco con riso","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo appassire la cipolla in 1 cucchiaio d''olio in una casseruola a fuoco medio, 5 min.","Aggiungere aglio, zenzero e peperoncino e cuocere 1 min, poi cumino, coriandolo in polvere, curcuma e cannella per 30 s.","Aggiungere le lenticchie, il pomodoro, il latte di cocco e 450 ml d''acqua. Portare a bollore, poi cuocere semicoperto 20 min mescolando spesso, finché le lenticchie si sfaldano in una purea densa; aggiungere acqua se serve.","Regolare di sale e aggiungere il succo di limone.","Scaldare 1 cucchiaio d''olio in un padellino, aggiungere i semi di senape e lasciarli scoppiettare 30 s, poi versarli sul dal. Servire con il riso e il coriandolo."]}}'::jsonb),
  ('da808dc3-7d41-43cd-9e70-cb82f2e4f7bd'::uuid, '{"fr":{"title":"Curry de poulet du Kerala","steps":["Mélanger le poulet avec la moitié du curcuma, la moitié du garam masala, le poivre, une pincée de piment en poudre et 0,5 c. à café de sel ; laisser reposer pendant la préparation du reste.","Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Faire revenir l''oignon dans 2 c. à soupe d''huile dans une sauteuse à fond épais à feu moyen, 8 min, jusqu''à ce qu''il soit doré. Ajouter le gingembre et l''ail et cuire 1 min.","Ajouter la tomate et cuire 3 min jusqu''à ce qu''elle soit fondue, puis incorporer la coriandre moulue, le reste du piment, du curcuma et du garam masala avec 3 c. à soupe d''eau et cuire 1 min.","Ajouter le poulet et remuer à feu moyen-vif 3 à 4 min jusqu''à ce qu''il devienne opaque. Verser 100 ml d''eau, couvrir et cuire à feu doux 12 min, jusqu''à ce qu''il soit tendre.","Incorporer le lait de coco et laisser frémir 4 min à découvert, jusqu''à ce que la sauce épaississe légèrement ; rectifier le sel.","Dans une petite poêle, faire dorer l''échalote dans 1 c. à soupe d''huile, ajouter les feuilles de curry et le piment 30 s, jusqu''à ce que les feuilles soient croustillantes, puis verser sur le curry. Servir avec le riz."]},"it":{"title":"Curry di pollo del Kerala","steps":["Condire il pollo con metà della curcuma, metà del garam masala, il pepe, un pizzico di peperoncino in polvere e 0,5 cucchiaini di sale; lasciarlo riposare mentre si prepara il resto.","Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Soffriggere la cipolla in 2 cucchiai d''olio in una padella dal fondo spesso a fuoco medio, 8 min, finché è dorata. Aggiungere zenzero e aglio e cuocere 1 min.","Aggiungere il pomodoro e cuocere 3 min finché si disfa, poi unire il coriandolo in polvere, il resto del peperoncino, della curcuma e del garam masala con 3 cucchiai d''acqua e cuocere 1 min.","Aggiungere il pollo e mescolare a fuoco medio-alto 3-4 min finché diventa opaco. Versare 100 ml d''acqua, coprire e cuocere a fuoco basso 12 min, finché è tenero.","Unire il latte di cocco e cuocere scoperto 4 min, finché il sugo si addensa leggermente; regolare di sale.","In un padellino dorare lo scalogno in 1 cucchiaio d''olio, aggiungere le foglie di curry e il peperoncino per 30 s, finché le foglie sono croccanti, poi versare sul curry. Servire con il riso."]}}'::jsonb),
  ('f47d0b89-d4b8-425b-8d63-dc0b9302e262'::uuid, '{"fr":{"title":"Aloo chana chaat (pommes de terre et pois chiches)","steps":["Préchauffer le four à 220 °C. Mélanger les pommes de terre et les pois chiches sur une grande plaque avec 2 c. à soupe d''huile, 1 c. à café de cumin, le piment en poudre et du sel.","Rôtir 30 min en retournant à mi-cuisson, jusqu''à ce que les pommes de terre soient dorées et les pois chiches croustillants.","Pendant ce temps, hacher finement la menthe, la majeure partie de la coriandre et le piment et les mélanger à 3 c. à soupe de yaourt avec la moitié du jus de citron vert et une pincée de sel pour obtenir un chutney vert.","Délayer la pâte de tamarin avec le sucre, le reste du cumin et 3 c. à soupe d''eau chaude pour obtenir un chutney aigre-doux fluide. Fouetter le reste du yaourt avec une pincée de sel.","Dresser les pommes de terre et pois chiches chauds dans les assiettes, napper de yaourt et des deux chutneys et saupoudrer de chaat masala.","Parsemer d''oignon, de tomate, de sev et du reste de coriandre, presser le reste du citron vert par-dessus et servir aussitôt, avant que le sev ramollisse."]},"it":{"title":"Aloo chana chaat (patate e ceci)","steps":["Scaldare il forno a 220 °C. Condire patate e ceci su una teglia grande con 2 cucchiai d''olio, 1 cucchiaino di cumino, il peperoncino in polvere e sale.","Arrostire 30 min girando a metà cottura, finché le patate sono dorate e i ceci croccanti.","Nel frattempo tritare finemente la menta, quasi tutto il coriandolo e il peperoncino e mescolarli a 3 cucchiai di yogurt con metà del succo di lime e un pizzico di sale per ottenere un chutney verde.","Stemperare la pasta di tamarindo con lo zucchero, il cumino rimasto e 3 cucchiai d''acqua calda per ottenere un chutney agrodolce fluido. Sbattere lo yogurt rimasto con un pizzico di sale.","Disporre patate e ceci caldi nei piatti, condire con lo yogurt e i due chutney e cospargere di chaat masala.","Cospargere di cipolla, pomodoro, sev e coriandolo rimasto, spremere sopra il resto del lime e servire subito, prima che il sev si ammorbidisca."]}}'::jsonb),
  ('5b716b9c-544f-4b6e-89b1-5787ec0d5d4d'::uuid, '{"fr":{"title":"Biryani de chou-fleur et petits pois","steps":["Rincer le riz jusqu''à ce que l''eau soit claire et le faire tremper 20 min dans de l''eau froide, puis l''égoutter.","Chauffer 2 c. à soupe d''huile dans une cocotte à feu moyen, ajouter le laurier, la cannelle, l''anis étoilé, les clous de girofle et les noix de cajou et faire revenir 1 min, puis ajouter l''oignon et cuire 8 à 10 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis la moitié de la menthe, le piment et la tomate, et cuire 3 min jusqu''à ce qu''elle soit fondue.","Ajouter le chou-fleur, les petits pois, la cardamome, le cumin, le curcuma, le piment, le garam masala, la coriandre moulue et 1 c. à café de sel et remuer 2 min pour bien enrober.","Incorporer 50 g de yaourt, puis le riz égoutté et 300 ml d''eau bouillante. Porter à ébullition, couvrir hermétiquement et cuire à feu très doux 15 min.","Laisser reposer 10 min à couvert hors du feu, puis égrener délicatement à la fourchette.","Mélanger le reste du yaourt avec le concombre, le reste de la menthe et une pincée de sel pour faire un raïta et le servir avec le biryani."]},"it":{"title":"Biryani di cavolfiore e piselli","steps":["Sciacquare il riso finché l''acqua è limpida e lasciarlo in ammollo in acqua fredda 20 min, poi scolarlo.","Scaldare 2 cucchiai d''olio in una pentola dal fondo spesso con coperchio a fuoco medio, aggiungere alloro, cannella, anice stellato, chiodi di garofano e anacardi e soffriggere 1 min, poi aggiungere la cipolla e cuocere 8-10 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi metà della menta, il peperoncino e il pomodoro, e cuocere 3 min finché si ammorbidisce.","Aggiungere cavolfiore, piselli, cardamomo, cumino, curcuma, peperoncino, garam masala, coriandolo in polvere e 1 cucchiaino di sale e mescolare 2 min per insaporire.","Unire 50 g di yogurt, poi il riso scolato e 300 ml d''acqua bollente. Portare a bollore, coprire bene e cuocere a fuoco minimo 15 min.","Lasciare riposare coperto 10 min fuori dal fuoco, poi sgranare delicatamente con una forchetta.","Mescolare lo yogurt rimasto con il cetriolo, la menta rimasta e un pizzico di sale per preparare la raita e servirla con il biryani."]}}'::jsonb),
  ('6bc1c089-e3e1-4387-b021-e752bd4966a1'::uuid, '{"fr":{"title":"Curry de pois chiches et potiron au lait de coco","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Chauffer 2 c. à soupe d''huile dans une grande sauteuse à feu moyen, ajouter les graines de moutarde et le cumin et les laisser grésiller et éclater 30 s.","Ajouter l''oignon, l''ail, le gingembre et les feuilles de curry et cuire 5 min jusqu''à ce que l''oignon soit tendre, puis la tomate, la coriandre moulue, le curcuma, le piment et du sel, et cuire 3 min jusqu''à ce que la tomate se défasse.","Ajouter le potiron, les pois chiches et 250 ml d''eau, couvrir et laisser mijoter 15 min, jusqu''à ce que le potiron soit tendre.","Incorporer le lait de coco et le garam masala et laisser frémir 3 min à découvert, jusqu''à ce que la sauce épaississe légèrement.","Finir avec le jus de citron vert et la coriandre et servir avec le riz."]},"it":{"title":"Curry di ceci e zucca al cocco","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare 2 cucchiai d''olio in una padella larga a fuoco medio, aggiungere i semi di senape e il cumino e lasciarli sfrigolare e scoppiettare 30 s.","Aggiungere cipolla, aglio, zenzero e foglie di curry e cuocere 5 min finché la cipolla è morbida, poi il pomodoro, il coriandolo in polvere, la curcuma, il peperoncino e il sale, e cuocere 3 min finché il pomodoro si disfa.","Aggiungere la zucca, i ceci e 250 ml d''acqua, coprire e cuocere 15 min, finché la zucca è tenera.","Unire il latte di cocco e il garam masala e cuocere scoperto 3 min, finché il sugo si addensa leggermente.","Completare con il succo di lime e il coriandolo e servire con il riso."]}}'::jsonb),
  ('fef780b4-874f-4404-af16-299d19f45262'::uuid, '{"fr":{"title":"Curry de crevettes de Goa au coco et haricots verts","steps":["Mélanger les crevettes avec 0,25 c. à café de curcuma et une pincée de sel.","Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Chauffer 2 c. à soupe d''huile dans une grande sauteuse à feu moyen et y faire grésiller les feuilles de curry et le piment 30 s. Ajouter l''oignon et cuire 6 à 7 min, jusqu''à ce qu''il soit tendre et légèrement doré, puis l''ail et le gingembre 1 min.","Incorporer le paprika, le piment, la coriandre moulue, le cumin et le reste du curcuma avec 3 c. à soupe d''eau et faire revenir 2 min, jusqu''à ce que l''huile commence à se séparer.","Verser le lait de coco et 150 ml d''eau, ajouter les haricots verts et laisser frémir 6 min, jusqu''à ce qu''ils soient juste tendres.","Ajouter les crevettes et laisser frémir 3 à 4 min, jusqu''à ce qu''elles soient roses et cuites.","Incorporer la pâte de tamarin, le sucre et du sel à goût ; la sauce doit être acidulée. Servir avec le riz, la coriandre et des quartiers de citron vert."]},"it":{"title":"Curry di gamberi di Goa al cocco con fagiolini","steps":["Condire i gamberi con 0,25 cucchiaini di curcuma e un pizzico di sale.","Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare 2 cucchiai d''olio in una padella larga a fuoco medio e farvi sfrigolare le foglie di curry e il peperoncino 30 s. Aggiungere la cipolla e cuocere 6-7 min, finché è morbida e leggermente dorata, poi aglio e zenzero per 1 min.","Unire paprika, peperoncino, coriandolo in polvere, cumino e la curcuma rimasta con 3 cucchiai d''acqua e soffriggere 2 min, finché l''olio comincia a separarsi.","Versare il latte di cocco e 150 ml d''acqua, aggiungere i fagiolini e cuocere 6 min, finché sono appena teneri.","Aggiungere i gamberi e cuocere 3-4 min, finché sono rosa e cotti.","Unire la pasta di tamarindo, lo zucchero e sale a piacere; deve risultare acidulo. Servire con il riso, il coriandolo e spicchi di lime."]}}'::jsonb),
  ('a3ae4eef-b13b-417a-ab48-06aa0416f834'::uuid, '{"fr":{"title":"Palak paneer et riz","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Faire tomber les épinards avec le piment et les noix de cajou dans 1 c. à soupe d''huile dans une grande poêle à feu moyen, 3 min, juste le temps qu''ils réduisent. Laisser tiédir, puis mixer avec 4 c. à soupe d''eau en une purée lisse.","Faire fondre le beurre dans la même poêle, ajouter les graines de cumin 30 s, puis l''oignon et faire revenir 8 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates et une pincée de sel et cuire 5 min jusqu''à ce qu''elles soient fondantes.","Incorporer le garam masala et la coriandre moulue 1 min, ajouter 150 ml d''eau, couvrir et cuire 5 min, puis ajouter les feuilles de fenugrec émiettées entre les doigts.","Baisser le feu, incorporer la purée d''épinards et porter juste à frémissement, 2 à 3 min ; ne pas faire bouillir fort pour qu''elle reste bien verte.","Ajouter délicatement le paneer et chauffer 2 min, puis incorporer la crème. Servir avec le riz."]},"it":{"title":"Palak paneer con riso","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Far appassire gli spinaci con il peperoncino e gli anacardi in 1 cucchiaio d''olio in una padella grande a fuoco medio, 3 min, solo finché si afflosciano. Far intiepidire, poi frullare con 4 cucchiai d''acqua fino a ottenere una purea liscia.","Sciogliere il burro nella stessa padella, aggiungere i semi di cumino per 30 s, poi la cipolla e soffriggere 8 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori e un pizzico di sale e cuocere 5 min finché sono morbidi e densi.","Unire garam masala e coriandolo in polvere per 1 min, aggiungere 150 ml d''acqua, coprire e cuocere 5 min, poi unire le foglie di fieno greco sbriciolate tra le dita.","Abbassare il fuoco, unire la purea di spinaci e portare appena a bollore, 2-3 min; non far bollire forte o perderà il colore.","Aggiungere delicatamente il paneer e scaldare 2 min, poi incorporare la panna. Servire con il riso."]}}'::jsonb),
  ('4c3bafea-b644-4721-b329-1da8f0824459'::uuid, '{"fr":{"title":"Keema aloo (bœuf haché et pommes de terre)","steps":["Chauffer 2 c. à soupe d''huile dans une sauteuse à fond épais avec couvercle à feu moyen, ajouter les graines de cumin, le laurier, la cannelle et les clous de girofle et faire revenir 1 min, jusqu''à ce qu''ils embaument.","Ajouter l''oignon et cuire 5 min jusqu''à ce qu''il soit doré, puis l''ail et le gingembre 1 min.","Ajouter le bœuf et cuire à feu moyen-vif 5 à 6 min en l''émiettant, jusqu''à ce qu''il soit doré et que son jus se soit évaporé.","Incorporer la coriandre moulue, le cumin moulu, le curcuma, le piment et 1 c. à café de sel 2 min, puis ajouter les tomates et les pommes de terre.","Verser 200 ml d''eau, couvrir et laisser mijoter à feu doux 15 min en remuant de temps en temps, jusqu''à ce que les pommes de terre soient tendres et que l''huile remonte en surface.","Ajouter les petits pois et le garam masala et cuire encore 3 min à découvert, jusqu''à ce que la sauce nappe la viande.","Finir avec le jus de citron, la coriandre et le piment vert et servir avec du pain plat chaud."]},"it":{"title":"Keema aloo (macinato di manzo e patate)","steps":["Scaldare 2 cucchiai d''olio in una padella dal fondo spesso con coperchio a fuoco medio, aggiungere i semi di cumino, l''alloro, la cannella e i chiodi di garofano e soffriggere 1 min, finché profumano.","Aggiungere la cipolla e cuocere 5 min finché è dorata, poi aglio e zenzero per 1 min.","Aggiungere il manzo e cuocere a fuoco medio-alto 5-6 min sgranandolo, finché è rosolato e il liquido è evaporato.","Unire coriandolo in polvere, cumino in polvere, curcuma, peperoncino e 1 cucchiaino di sale per 2 min, poi aggiungere i pomodori e le patate.","Versare 200 ml d''acqua, coprire e cuocere a fuoco basso 15 min mescolando ogni tanto, finché le patate sono tenere e l''olio affiora in superficie.","Aggiungere i piselli e il garam masala e cuocere ancora 3 min scoperto, finché il sugo avvolge la carne.","Completare con il succo di limone, il coriandolo e il peperoncino verde e servire con pane piatto caldo."]}}'::jsonb),
  ('8213da9d-3b1b-46a3-b4b2-70bfcbbfc392'::uuid, '{"fr":{"title":"Saag gosht (agneau aux épinards) et riz basmati","steps":["Faire dorer l''agneau dans 1 c. à soupe d''huile dans une cocotte à feu moyen-vif, en deux fois, 5 min, puis le réserver.","Mettre le beurre, les graines de cumin et le laurier dans la cocotte 30 s, puis l''oignon, et cuire 8 à 10 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates, le curcuma, la coriandre moulue, le cumin moulu et le piment, et cuire 8 min jusqu''à ce que le mélange épaississe et que la matière grasse se sépare ; ajouter un peu d''eau si cela attache.","Remettre l''agneau avec 300 ml d''eau et 1 c. à café de sel, couvrir et laisser mijoter doucement 50 min.","Fouetter le yaourt et l''incorporer hors ébullition, puis ajouter les épinards par poignées et les laisser tomber. Couvrir et laisser mijoter encore 15 min, jusqu''à ce que l''agneau soit tendre et la sauce épaisse et verte.","Pendant ce temps, rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Incorporer au curry le garam masala et les feuilles de fenugrec émiettées entre les paumes, rectifier le sel et servir avec le riz."]},"it":{"title":"Saag gosht (agnello agli spinaci) con riso basmati","steps":["Rosolare l''agnello in 1 cucchiaio d''olio in una pentola dal fondo spesso con coperchio a fuoco medio-alto, in due volte, 5 min, poi metterlo da parte.","Mettere nella pentola il burro, i semi di cumino e l''alloro per 30 s, poi la cipolla, e cuocere 8-10 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori, la curcuma, il coriandolo in polvere, il cumino in polvere e il peperoncino, e cuocere 8 min finché il fondo è denso e il grasso si separa; aggiungere un goccio d''acqua se attacca.","Rimettere l''agnello con 300 ml d''acqua e 1 cucchiaino di sale, coprire e cuocere a fuoco dolce 50 min.","Sbattere lo yogurt e incorporarlo a fuoco spento, poi aggiungere gli spinaci una manciata alla volta e lasciarli appassire. Coprire e cuocere ancora 15 min, finché l''agnello è tenero e il sugo denso e verde.","Nel frattempo sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Unire al curry il garam masala e le foglie di fieno greco sbriciolate tra i palmi, regolare di sale e servire con il riso."]}}'::jsonb),
  ('3ce76142-b963-43c3-be17-260ca39b916d'::uuid, '{"fr":{"title":"Brochettes de paneer tikka et riz au concombre","steps":["Mélanger le yaourt avec l''ail, le gingembre, le garam masala, le piment, le paprika, le cumin, le curcuma, le jus d''un demi-citron, 1 c. à soupe d''huile et 0,5 c. à café de sel. Y enrober le paneer, le poivron et l''oignon et laisser 30 min au réfrigérateur.","Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu, puis l''étaler pour qu''il tiédisse.","Allumer le gril du four à puissance maximale (ou le four à 230 °C). Enfiler le paneer, le poivron et l''oignon sur des brochettes et les poser sur une plaque huilée.","Griller 12 à 15 min en retournant une fois, jusqu''à ce que le paneer soit grillé sur les bords et les légumes tendres.","Incorporer le concombre, la menthe, un filet de citron et une pincée de sel au riz tiède.","Servir les brochettes sur le riz au concombre avec le reste du citron en quartiers."]},"it":{"title":"Spiedini di paneer tikka con riso al cetriolo","steps":["Mescolare lo yogurt con aglio, zenzero, garam masala, peperoncino, paprika, cumino, curcuma, il succo di mezzo limone, 1 cucchiaio d''olio e 0,5 cucchiaini di sale. Unire paneer, peperone e cipolla e lasciare in frigorifero 30 min.","Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco, poi allargarlo perché intiepidisca.","Accendere il grill del forno al massimo (o il forno a 230 °C). Infilare paneer, peperone e cipolla negli spiedini e disporli su una teglia unta.","Grigliare 12-15 min girando una volta, finché il paneer è abbrustolito ai bordi e le verdure tenere.","Unire al riso tiepido il cetriolo, la menta, una spruzzata di limone e un pizzico di sale.","Servire gli spiedini sul riso al cetriolo con il resto del limone a spicchi."]}}'::jsonb),
  ('0f1721fb-aa3a-4130-b668-700a02491983'::uuid, '{"fr":{"title":"Rajma chawal (curry de haricots rouges et riz)","steps":["Chauffer le beurre avec 1 c. à soupe d''huile dans une casserole à feu moyen, ajouter les graines de cumin et le laurier 30 s, puis l''oignon et le piment, et cuire 5 à 6 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates, et cuire 3 à 4 min jusqu''à ce que l''odeur de cru disparaisse.","Incorporer le piment, la coriandre moulue, le cumin moulu, le curcuma, la moitié du garam masala et 1 c. à café de sel et cuire 3 min jusqu''à ce que la base épaississe et brille d''huile.","Ajouter les haricots et 300 ml d''eau chaude et laisser mijoter 15 min, en écrasant quelques haricots contre la paroi pour épaissir la sauce.","Pendant ce temps, rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Incorporer au rajma le reste du garam masala, les feuilles de fenugrec émiettées et le jus de citron, parsemer de coriandre et servir sur le riz avec le yaourt à côté."]},"it":{"title":"Rajma chawal (curry di fagioli rossi con riso)","steps":["Scaldare il burro con 1 cucchiaio d''olio in una casseruola a fuoco medio, aggiungere i semi di cumino e l''alloro per 30 s, poi la cipolla e il peperoncino, e cuocere 5-6 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori, e cuocere 3-4 min finché sparisce l''odore di crudo.","Unire peperoncino, coriandolo in polvere, cumino in polvere, curcuma, metà del garam masala e 1 cucchiaino di sale e cuocere 3 min finché il fondo si addensa e diventa lucido d''olio.","Aggiungere i fagioli e 300 ml d''acqua calda e cuocere 15 min, schiacciando qualche fagiolo contro la parete per addensare il sugo.","Nel frattempo sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Unire al rajma il garam masala rimasto, le foglie di fieno greco sbriciolate e il succo di limone, cospargere di coriandolo e servire sul riso con lo yogurt a parte."]}}'::jsonb),
  ('db823cde-4d7a-4643-83ef-da6dc18ff628'::uuid, '{"fr":{"title":"Poulet jalfrezi","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; le laisser reposer hors du feu jusqu''au service.","Mélanger le poulet avec le jus de citron, une pincée de piment en poudre et du sel.","Faire sauter les poivrons, les morceaux d''oignon et le piment dans 1 c. à soupe d''huile dans une grande poêle à feu vif, 3 min, jusqu''à ce qu''ils soient grillés sur les bords mais encore croquants ; les réserver sur une assiette.","Ajouter 1 c. à soupe d''huile et l''oignon haché dans la poêle et faire revenir à feu moyen-vif 4 min, puis ajouter l''ail et le gingembre 1 min.","Ajouter le poulet et le faire sauter 3 min jusqu''à ce qu''il blanchisse, puis le reste du piment en poudre, le garam masala, la coriandre moulue, le cumin et le curcuma 30 s.","Verser les tomates avec 3 c. à soupe d''eau et cuire 5 à 6 min en remuant, jusqu''à ce que le poulet soit cuit et la sauce épaisse et nappante.","Remettre les poivrons et l''oignon avec les feuilles de fenugrec émiettées, faire sauter 1 min pour les réchauffer, rectifier le sel et servir avec le riz et la coriandre."]},"it":{"title":"Pollo jalfrezi","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare fuori dal fuoco fino al momento di servire.","Condire il pollo con il succo di limone, un pizzico di peperoncino in polvere e sale.","Saltare i peperoni, i pezzi di cipolla e il peperoncino in 1 cucchiaio d''olio in una padella grande a fuoco vivo, 3 min, finché sono abbrustoliti ai bordi ma ancora croccanti; metterli da parte su un piatto.","Aggiungere 1 cucchiaio d''olio e la cipolla tritata nella padella e soffriggere a fuoco medio-alto 4 min, poi aggiungere aglio e zenzero per 1 min.","Aggiungere il pollo e saltarlo 3 min finché diventa chiaro, poi il resto del peperoncino in polvere, il garam masala, il coriandolo in polvere, il cumino e la curcuma per 30 s.","Versare i pomodori con 3 cucchiai d''acqua e cuocere 5-6 min mescolando, finché il pollo è cotto e il sugo denso e avvolgente.","Rimettere i peperoni e la cipolla con le foglie di fieno greco sbriciolate, saltare 1 min per scaldarli, regolare di sale e servire con il riso e il coriandolo."]}}'::jsonb),
  ('442ff452-d938-4eab-96a9-6d100a2a00df'::uuid, '{"fr":{"title":"Anda curry (curry d''œufs)","steps":["Cuire les œufs 9 min dans l''eau frémissante, les refroidir dans l''eau froide et les écaler. Piquer chaque œuf 3 ou 4 fois avec une fourchette.","Rincer le riz, le mettre dans la même casserole avec 300 ml d''eau salée, couvrir et cuire 12 min à feu doux ; laisser reposer 5 min hors du feu.","Pendant ce temps, faire dorer les œufs dans le beurre avec une pincée de curcuma dans une sauteuse, 2 à 3 min, en les roulant jusqu''à ce qu''ils soient dorés et cloqués. Réserver.","Chauffer l''huile dans la même sauteuse, ajouter le laurier, la cannelle et la cardamome 30 s, puis les oignons ; cuire 8 min à feu moyen jusqu''à ce qu''ils soient dorés.","Ajouter l''ail et le gingembre 1 min, puis les tomates ; cuire 5 min jusqu''à obtenir une sauce épaisse.","Incorporer le piment en poudre, la coriandre en poudre, le garam masala, le reste du curcuma et du sel ; cuire 2 min jusqu''à ce que l''huile se sépare.","Verser 250 ml d''eau, couvrir et laisser mijoter 6 min jusqu''à ce que la sauce épaississe.","Ajouter les œufs et laisser mijoter 3 à 4 min pour qu''ils prennent le goût de la sauce ; émietter les feuilles de fenugrec, incorporer la crème, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Anda curry (curry di uova)","steps":["Cuocere le uova 9 min in acqua che sobbolle, raffreddarle in acqua fredda e sgusciarle. Bucherellare ogni uovo 3-4 volte con una forchetta.","Sciacquare il riso, metterlo nella stessa pentola con 300 ml di acqua salata, coprire e cuocere 12 min a fuoco basso; lasciare riposare 5 min fuori dal fuoco.","Nel frattempo, rosolare le uova nel burro con un pizzico di curcuma in una padella larga, 2-3 min, girandole finché sono dorate e con qualche bolla. Tenere da parte.","Scaldare l''olio nella stessa padella, aggiungere alloro, cannella e cardamomo per 30 s, poi le cipolle; cuocere 8 min a fuoco medio finché sono dorate.","Aggiungere aglio e zenzero per 1 min, poi i pomodori; cuocere 5 min finché il sugo è denso.","Unire il peperoncino in polvere, il coriandolo macinato, il garam masala, il resto della curcuma e il sale; cuocere 2 min finché l''olio si separa.","Versare 250 ml di acqua, coprire e cuocere a fuoco lento 6 min finché il sugo si addensa.","Aggiungere le uova e cuocere 3-4 min perché prendano il sapore del sugo; sbriciolare il fieno greco, unire la panna, cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('1ab9739c-acbe-4eba-9ade-d3384a505962'::uuid, '{"fr":{"title":"Rogan josh (agneau braisé du Cachemire)","steps":["Faire dorer l''oignon dans 1 c. à soupe d''huile dans une cocotte à fond épais, à feu moyen, 8 à 10 min. Le retirer sur une assiette.","Ajouter le reste de l''huile, puis le laurier, la cardamome, les clous de girofle et la cannelle ; laisser grésiller 30 s.","Ajouter l''agneau, le saisir 2 min à feu vif, puis le cuire 5 min à feu moyen jusqu''à ce qu''il soit légèrement doré.","Fouetter le yaourt avec le piment du Cachemire, le fenouil moulu, le gingembre et le sel. Retirer la cocotte du feu et incorporer le yaourt cuillerée par cuillerée pour qu''il ne tranche pas.","Remettre à feu moyen, couvrir et cuire 4 min, puis ajouter 250 ml d''eau chaude. Couvrir et laisser mijoter à feu doux 1 h 30 à 1 h 45, en remuant toutes les 15 min et en ajoutant un peu d''eau chaude si nécessaire, jusqu''à ce que l''agneau soit très tendre.","Pendant les 20 dernières minutes, incorporer l''oignon frit et le garam masala.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Quand la sauce est épaisse et qu''une huile rouge apparaît en surface, rectifier le sel et servir avec le riz."]},"it":{"title":"Rogan josh (agnello brasato del Kashmir)","steps":["Rosolare la cipolla in 1 cucchiaio d''olio in una pentola dal fondo spesso a fuoco medio, 8-10 min, finché è ben dorata. Toglierla e metterla su un piatto.","Aggiungere il resto dell''olio, poi alloro, cardamomo, chiodi di garofano e cannella; lasciarli sfrigolare 30 s.","Aggiungere l''agnello, scottarlo 2 min a fuoco vivo, poi cuocerlo 5 min a fuoco medio finché è leggermente dorato.","Sbattere lo yogurt con peperoncino del Kashmir, finocchio macinato, zenzero e sale. Togliere la pentola dal fuoco e incorporare lo yogurt un cucchiaio alla volta perché non impazzisca.","Rimettere a fuoco medio, coprire e cuocere 4 min, poi aggiungere 250 ml di acqua calda. Coprire e cuocere a fuoco basso 1 h 30-1 h 45, mescolando ogni 15 min e aggiungendo un goccio di acqua calda se si asciuga, finché l''agnello è molto tenero.","Negli ultimi 20 min, unire la cipolla rosolata e il garam masala.","Nel frattempo, sciacquare il riso e cuocerlo coperto in 300 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Quando il sugo è denso e in superficie compare un olio rosso, regolare di sale e servire con il riso."]}}'::jsonb),
  ('aff85e70-95e3-4537-a252-0b668f27c213'::uuid, '{"fr":{"title":"Biryani au poulet","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, le couvrir d''eau et le laisser tremper 30 min ; égoutter.","Pendant ce temps, faire frire les oignons dans l''huile dans une cocotte à fond épais à feu moyen, 12 à 15 min, jusqu''à ce qu''ils soient bien dorés. En réserver un tiers pour le dessus.","Ajouter le laurier, la cannelle, la cardamome et les clous de girofle 30 s, puis l''ail et le gingembre 1 min.","Ajouter le poulet et le cuire 3 min jusqu''à ce qu''il blanchisse, puis assaisonner de sel, garam masala, piment en poudre et curcuma et faire revenir encore 3 min.","Incorporer le yaourt, couvrir et cuire 15 à 20 min à feu moyen-doux jusqu''à ce que le poulet soit tendre et la sauce épaisse, pas liquide.","Pendant ce temps, porter à ébullition 2 l d''eau salée avec le carvi, ajouter le riz et le cuire 5 à 6 min jusqu''à ce qu''il soit cuit à 90 %, encore ferme au centre ; égoutter. Faire infuser le safran dans le lait tiède.","Parsemer le poulet de menthe et de coriandre, étaler le riz par-dessus, puis ajouter les oignons réservés, le lait au safran et le beurre fondu.","Fermer hermétiquement la cocotte avec du papier aluminium et le couvercle et cuire 15 min sur le feu le plus doux. Laisser reposer 10 min hors du feu avant d''ouvrir, puis mélanger délicatement et servir."]},"it":{"title":"Biryani di pollo","steps":["Sciacquare il riso finché l''acqua è limpida, coprirlo d''acqua e lasciarlo in ammollo 30 min; scolare.","Nel frattempo, friggere le cipolle nell''olio in una pentola dal fondo spesso a fuoco medio, 12-15 min, finché sono ben dorate. Tenerne da parte un terzo per la copertura.","Aggiungere alloro, cannella, cardamomo e chiodi di garofano per 30 s, poi aglio e zenzero per 1 min.","Aggiungere il pollo e cuocerlo 3 min finché diventa chiaro, poi condire con sale, garam masala, peperoncino in polvere e curcuma e rosolare altri 3 min.","Unire lo yogurt, coprire e cuocere 15-20 min a fuoco medio-basso finché il pollo è tenero e il sugo denso, non acquoso.","Nel frattempo, portare a ebollizione 2 l di acqua salata con il cumino dei prati, aggiungere il riso e bollirlo 5-6 min finché è cotto al 90%, ancora sodo al centro; scolare. Mettere in infusione lo zafferano nel latte tiepido.","Cospargere il pollo di menta e coriandolo, stendere sopra il riso, poi aggiungere le cipolle tenute da parte, il latte allo zafferano e il burro fuso.","Sigillare la pentola con carta stagnola e coperchio e cuocere 15 min sul fuoco più basso. Lasciare riposare 10 min fuori dal fuoco prima di aprire, poi mescolare delicatamente e servire."]}}'::jsonb),
  ('8cf5200c-38b4-4aa5-aa57-44228ae164ec'::uuid, '{"fr":{"title":"Matar paneer (paneer aux petits pois)","steps":["Rincer le riz et le cuire à couvert dans 250 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Faire dorer le paneer dans la moitié du beurre dans une poêle, 1 à 2 min de chaque côté. Réserver.","Ajouter l''huile et le reste du beurre, le cumin 30 s, puis l''oignon ; cuire 5 min jusqu''à ce qu''il soit légèrement doré.","Ajouter l''ail et le gingembre 1 min, puis le curcuma, le piment en poudre et la coriandre en poudre 30 s.","Verser le coulis de tomate avec un peu de sel et cuire 4 min en remuant, jusqu''à ce qu''il épaississe et que l''huile se sépare.","Ajouter les petits pois et 150 ml d''eau et laisser mijoter 5 min.","Émietter les feuilles de fenugrec, ajouter le paneer et le garam masala et laisser mijoter 2 min. Incorporer la crème, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Matar paneer (paneer con piselli)","steps":["Sciacquare il riso e cuocerlo coperto in 250 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Dorare il paneer in metà del burro in una padella, 1-2 min per lato. Tenere da parte.","Aggiungere l''olio e il resto del burro, il cumino per 30 s, poi la cipolla; cuocere 5 min finché è leggermente dorata.","Aggiungere aglio e zenzero per 1 min, poi curcuma, peperoncino in polvere e coriandolo macinato per 30 s.","Versare la passata con un po'' di sale e cuocere 4 min mescolando, finché si addensa e l''olio si separa.","Aggiungere i piselli e 150 ml di acqua e cuocere a fuoco lento 5 min.","Sbriciolare il fieno greco, aggiungere il paneer e il garam masala e cuocere 2 min. Unire la panna, cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('aba8ad6d-ca4c-4d94-a688-3adb95587555'::uuid, '{"fr":{"title":"Crevettes masala","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Mélanger les crevettes avec une pincée de curcuma, de piment du Cachemire et de sel et les laisser reposer pendant que vous commencez la sauce.","Chauffer l''huile dans une sauteuse, ajouter le cumin et les feuilles de curry 30 s, puis l''oignon ; cuire 6 à 7 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates et un peu de sel ; cuire 6 min jusqu''à ce qu''elles soient fondues et épaisses.","Incorporer le reste du curcuma et du piment du Cachemire, la coriandre en poudre et le garam masala ; cuire 1 à 2 min jusqu''à ce que l''huile se sépare.","Ajouter le lait de coco et 100 ml d''eau et laisser mijoter 4 à 5 min pour obtenir une sauce épaisse mais nappante.","Baisser le feu, ajouter les crevettes et cuire 3 à 4 min, juste jusqu''à ce qu''elles soient roses et recourbées en C. Ajouter un filet de citron et la coriandre et servir avec le riz."]},"it":{"title":"Gamberi masala","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare i gamberi con un pizzico di curcuma, peperoncino del Kashmir e sale e lasciarli riposare mentre si prepara il sugo.","Scaldare l''olio in una padella, aggiungere il cumino e le foglie di curry per 30 s, poi la cipolla; cuocere 6-7 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori e un po'' di sale; cuocere 6 min finché sono disfatti e densi.","Unire il resto della curcuma e del peperoncino del Kashmir, coriandolo macinato e garam masala; cuocere 1-2 min finché l''olio si separa.","Aggiungere il latte di cocco e 100 ml di acqua e cuocere a fuoco lento 4-5 min fino a ottenere un sugo denso ma fluido.","Abbassare il fuoco, aggiungere i gamberi e cuocere 3-4 min, finché diventano rosa e si piegano a C. Aggiungere una spruzzata di limone e il coriandolo e servire con il riso."]}}'::jsonb),
  ('24505ac8-cfec-4400-bede-ce4bae130d8a'::uuid, '{"fr":{"title":"Sauté de porc au chou et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Mélanger le porc avec le vin de Shaoxing, 1 c. à café de sauce soja foncée, un peu de gingembre et 1 c. à café de fécule ; laisser reposer 10 min.","Mélanger la sauce soja avec le reste de la sauce soja foncée et le sucre. Délayer le reste de la fécule dans 1 c. à soupe d''eau.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif, étaler le porc en une couche, laisser 1 min, puis faire sauter encore 1 min jusqu''à ce qu''il soit juste cuit. Réserver.","Ajouter le reste de l''huile, l''ail et le gingembre et remuer 20 s jusqu''à ce qu''ils embaument.","Ajouter le chou et le faire sauter 3 à 4 min jusqu''à ce qu''il soit à peine tendre mais encore croquant.","Verser la sauce, remettre le porc, ajouter la fécule délayée et remuer 1 min jusqu''à ce que ce soit brillant. Assaisonner de sel et de piment et servir sur le riz."]},"it":{"title":"Maiale saltato con cavolo e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare il maiale con il vino di Shaoxing, 1 cucchiaino di salsa di soia scura, un po'' di zenzero e 1 cucchiaino di amido; lasciare riposare 10 min.","Mescolare la salsa di soia con il resto della salsa di soia scura e lo zucchero. Stemperare l''amido rimasto in 1 cucchiaio di acqua.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo, stendere il maiale in un solo strato, lasciarlo 1 min, poi saltarlo ancora 1 min finché è appena cotto. Tenere da parte.","Aggiungere il resto dell''olio, aglio e zenzero e mescolare 20 s finché profumano.","Aggiungere il cavolo e saltarlo 3-4 min finché è appena tenero ma ancora croccante.","Versare la salsa, rimettere il maiale, aggiungere l''amido stemperato e mescolare 1 min finché è lucido. Condire con sale e peperoncino e servire sul riso."]}}'::jsonb),
  ('8374c9b3-57b9-4cc7-be98-c4ae66518e2a'::uuid, '{"fr":{"title":"Bouchées de laitue au bœuf gingembre et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Chauffer l''huile dans une grande poêle à feu vif et faire dorer le bœuf en l''émiettant, 5 à 6 min, jusqu''à ce qu''il soit bien caramélisé. Réserver.","Dans la même poêle, faire revenir l''oignon, le poivron, la carotte, l''ail et le gingembre 3 à 4 min jusqu''à ce qu''ils soient tendres.","Remettre le bœuf, ajouter la sauce d''huître, la sauce hoisin, la sauce soja, le bouillon et les châtaignes d''eau et faire sauter 3 à 4 min jusqu''à ce que le liquide soit absorbé et la viande sèche et laquée.","Incorporer l''huile de sésame et retirer du feu.","Garnir les feuilles de laitue de bœuf, parsemer d''oignon nouveau, de cacahuètes et de piment et servir avec le riz."]},"it":{"title":"Coppette di lattuga con manzo allo zenzero e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Scaldare l''olio in una padella grande a fuoco vivo e rosolare il manzo sbriciolandolo, 5-6 min, finché è ben caramellato ai bordi. Tenere da parte.","Nella stessa padella, cuocere cipolla, peperone, carota, aglio e zenzero 3-4 min finché si ammorbidiscono.","Rimettere il manzo, aggiungere salsa di ostriche, salsa hoisin, salsa di soia, brodo e castagne d''acqua e saltare 3-4 min finché il liquido è evaporato e la carne è asciutta e glassata.","Unire l''olio di sesamo e togliere dal fuoco.","Distribuire il manzo nelle foglie di lattuga, completare con cipollotto, arachidi e peperoncino e servire con il riso."]}}'::jsonb),
  ('feea91a4-24a0-4ece-adb4-46b6944cafcc'::uuid, '{"fr":{"title":"Riz sauté au poulet et aux légumes","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux. L''étaler sur un plateau et le laisser refroidir complètement, au moins 30 min (ou le cuire la veille et le réfrigérer).","Mélanger le poulet avec 1 c. à café de sauce soja, la fécule et l''huile de sésame. Mélanger le reste de la sauce soja avec la sauce soja foncée, le sucre, une pincée de sel, du poivre et 1 c. à soupe d''eau chaude.","Chauffer 1 c. à soupe d''huile dans un wok à feu moyen-vif, brouiller les œufs jusqu''à ce qu''ils soient juste pris et les retirer.","Ajouter 1 c. à soupe d''huile, saisir le poulet en une couche à feu vif et le faire sauter 3 à 4 min jusqu''à ce qu''il soit cuit. Réserver.","Ajouter le reste de l''huile, faire sauter l''oignon et la carotte 3 min, puis les petits pois 1 min.","Ajouter le riz froid en défaisant les grumeaux et faire sauter 4 à 5 min jusqu''à ce qu''il soit chaud et les grains bien séparés.","Verser la sauce et mélanger jusqu''à coloration uniforme, puis ajouter le poulet, les œufs, les germes de soja et l''oignon nouveau et faire sauter 1 min.","Verser le vin de Shaoxing en filet sur les bords chauds du wok, mélanger 20 s et servir."]},"it":{"title":"Riso saltato con pollo e verdure","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso. Stenderlo su un vassoio e lasciarlo raffreddare completamente, almeno 30 min (oppure cuocerlo il giorno prima e metterlo in frigo).","Mescolare il pollo con 1 cucchiaino di salsa di soia, l''amido e l''olio di sesamo. Mescolare il resto della salsa di soia con la salsa di soia scura, lo zucchero, un pizzico di sale, pepe e 1 cucchiaio di acqua calda.","Scaldare 1 cucchiaio d''olio in un wok a fuoco medio-alto, strapazzare le uova finché sono appena rapprese e toglierle.","Aggiungere 1 cucchiaio d''olio, scottare il pollo in un solo strato a fuoco vivo e saltarlo 3-4 min finché è cotto. Tenere da parte.","Aggiungere il resto dell''olio, saltare cipolla e carota 3 min, poi i piselli 1 min.","Aggiungere il riso freddo sgranando i grumi e saltarlo 4-5 min finché è caldo e i chicchi sono separati.","Versare la salsa e mescolare finché il colore è uniforme, poi aggiungere pollo, uova, germogli di soia e cipollotto e saltare 1 min.","Versare il vino di Shaoxing lungo i bordi caldi del wok, mescolare 20 s e servire."]}}'::jsonb),
  ('aa00c4b7-db7b-4b8a-8ea5-5637a1fb4bdf'::uuid, '{"fr":{"title":"Boulettes de porc, bouillon au gingembre et nouilles","steps":["Porter le bouillon à ébullition avec les bâtonnets de gingembre et l''ail écrasé, puis laisser frémir 10 min.","Pendant ce temps, mélanger le porc avec le blanc des oignons nouveaux, le gingembre râpé, l''ail râpé, 1 c. à soupe de sauce soja, le vin de Shaoxing, l''huile de sésame, la fécule, 2 c. à soupe d''eau et du poivre. Travailler 1 min jusqu''à ce que la farce soit collante.","Avec les mains mouillées, former environ 14 boulettes de la taille d''une noix.","Plonger les boulettes et la carotte dans le bouillon frémissant et les pocher 8 min sans faire bouillir fort.","Pendant ce temps, cuire les nouilles dans l''eau bouillante selon le paquet, les égoutter et les répartir dans deux bols.","Ajouter le pak-choï au bouillon et laisser frémir 3 à 4 min jusqu''à ce qu''il soit tendre et que les boulettes soient cuites à cœur, sans rose à l''intérieur.","Assaisonner le bouillon avec le reste de la sauce soja, le vinaigre et le sucre, le verser sur les nouilles et parsemer du vert des oignons nouveaux et de piment."]},"it":{"title":"Polpette di maiale in brodo allo zenzero con noodles","steps":["Portare a ebollizione il brodo con i bastoncini di zenzero e l''aglio schiacciato, poi far sobbollire 10 min.","Nel frattempo, mescolare il maiale con la parte bianca dei cipollotti, lo zenzero grattugiato, l''aglio grattugiato, 1 cucchiaio di salsa di soia, il vino di Shaoxing, l''olio di sesamo, l''amido, 2 cucchiai di acqua e pepe. Lavorare 1 min finché l''impasto è appiccicoso.","Con le mani bagnate, formare circa 14 polpette grandi come una noce.","Immergere le polpette e la carota nel brodo che sobbolle e cuocerle 8 min senza far bollire forte.","Nel frattempo, cuocere i noodles in acqua bollente come indicato sulla confezione, scolarli e dividerli in due ciotole.","Aggiungere il pak choi al brodo e cuocere 3-4 min finché è tenero e le polpette sono cotte all''interno, senza parti rosa.","Condire il brodo con il resto della salsa di soia, l''aceto e lo zucchero, versarlo sui noodles e completare con la parte verde dei cipollotti e il peperoncino."]}}'::jsonb),
  ('03b4b489-6e9f-4433-8687-bbb43c7193ee'::uuid, '{"fr":{"title":"Raviolis grillés aux champignons et au chou","steps":["Mélanger la farine et le sel avec 120 ml d''eau tiède, pétrir 5 min jusqu''à obtenir une pâte lisse, couvrir et laisser reposer 30 min.","Mélanger le chou avec 0,5 c. à café de sel, laisser 10 min, puis le presser pour en extraire le plus d''eau possible.","Faire revenir les champignons et la carotte dans 1 c. à soupe d''huile 5 à 6 min jusqu''à ce qu''ils soient secs, ajouter l''ail et le gingembre 1 min et laisser refroidir.","Mélanger le tofu, le chou, les champignons, l''oignon nouveau, 1 c. à soupe de sauce soja, l''huile de sésame et la fécule pour obtenir une farce ferme.","Couper la pâte en 24 morceaux, abaisser chacun en un disque fin de 8 cm et le fariner de fécule.","Déposer une bonne cuillerée à soupe de farce au centre de chaque disque, plier en deux et plisser les bords pour souder.","Cuire en trois fois : chauffer 1 c. à soupe d''huile dans une poêle antiadhésive avec couvercle, faire dorer les raviolis 3 à 4 min, ajouter 60 ml d''eau, couvrir et cuire à la vapeur 5 à 6 min jusqu''à évaporation, puis découvrir et laisser croustiller 1 min.","Mélanger le reste de la sauce soja avec le vinaigre noir et le piment et servir comme sauce."]},"it":{"title":"Ravioli cinesi alla piastra con funghi e cavolo","steps":["Mescolare farina e sale con 120 ml di acqua tiepida, impastare 5 min fino a ottenere un impasto liscio, coprire e lasciare riposare 30 min.","Mescolare il cavolo con mezzo cucchiaino di sale, lasciare 10 min, poi strizzarlo per eliminare più acqua possibile.","Rosolare funghi e carota in 1 cucchiaio d''olio 5-6 min finché sono asciutti, aggiungere aglio e zenzero per 1 min e lasciare raffreddare.","Mescolare tofu, cavolo, funghi, cipollotto, 1 cucchiaio di salsa di soia, olio di sesamo e amido fino a ottenere un ripieno compatto.","Dividere l''impasto in 24 pezzi, stendere ciascuno in un disco sottile di 8 cm e spolverarlo di amido.","Mettere un cucchiaio abbondante di ripieno al centro di ogni disco, piegarlo a metà e pieghettare i bordi per sigillarlo.","Cuocere in tre volte: scaldare 1 cucchiaio d''olio in una padella antiaderente con coperchio, rosolare i ravioli 3-4 min finché la base è dorata, aggiungere 60 ml di acqua, coprire e cuocere al vapore 5-6 min finché l''acqua è evaporata, poi scoprire e far croccare 1 min.","Mescolare il resto della salsa di soia con l''aceto nero e il peperoncino e servire come salsa per intingere."]}}'::jsonb),
  ('97b513b6-d70b-4491-a7ad-f9277ee94a14'::uuid, '{"fr":{"title":"Soupe de nouilles au poulet et aux champignons","steps":["Faire dorer les champignons dans l''huile dans une grande casserole à feu vif, 5 à 6 min. Les retirer.","Verser le bouillon dans la casserole avec le gingembre, l''ail, la sauce soja et le vin de Shaoxing et porter à ébullition.","Ajouter le poulet, baisser le feu et le pocher à petits frémissements 15 à 18 min jusqu''à ce qu''il soit cuit à cœur, sans rose dans la partie la plus épaisse.","Retirer le poulet, le laisser reposer 5 min et l''effilocher avec deux fourchettes.","Pendant ce temps, cuire les nouilles dans le bouillon le temps indiqué sur le paquet, en ajoutant le pak-choï pour les 3 dernières minutes.","Répartir les nouilles, le pak-choï et le bouillon dans les bols, garnir de poulet et de champignons et finir avec l''huile de sésame, l''oignon nouveau et le piment."]},"it":{"title":"Zuppa di noodles con pollo e funghi","steps":["Rosolare i funghi nell''olio in una pentola grande a fuoco vivo, 5-6 min finché sono dorati. Toglierli.","Versare il brodo nella pentola con zenzero, aglio, salsa di soia e vino di Shaoxing e portare a ebollizione.","Aggiungere il pollo, abbassare il fuoco e cuocerlo a leggero sobbollore 15-18 min finché è cotto all''interno, senza parti rosa nel punto più spesso.","Togliere il pollo, lasciarlo riposare 5 min e sfilacciarlo con due forchette.","Nel frattempo, cuocere i noodles nel brodo per il tempo indicato sulla confezione, aggiungendo il pak choi negli ultimi 3 min.","Dividere noodles, pak choi e brodo nelle ciotole, completare con pollo e funghi e finire con olio di sesamo, cipollotto e peperoncino."]}}'::jsonb),
  ('d7790ac8-391f-4ae9-92b6-2274a94cb910'::uuid, '{"fr":{"title":"Nouilles sautées au porc hoisin et brocoli","steps":["Mélanger le porc avec 1 c. à soupe de sauce soja et la fécule ; laisser reposer 10 min.","Mélanger la sauce hoisin avec le reste de la sauce soja, le miel, le vinaigre, l''huile de sésame et le piment.","Cuire les nouilles dans l''eau bouillante selon le paquet, en ajoutant le brocoli pour les 2 dernières minutes. Garder 60 ml d''eau de cuisson, puis égoutter.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif et saisir le porc en une couche 2 à 3 min, en le retournant une fois, jusqu''à ce qu''il soit doré et juste cuit. Réserver.","Ajouter le reste de l''huile, l''ail, le gingembre et la carotte et faire sauter 1 min.","Ajouter les nouilles, le brocoli, le porc, la sauce et un peu d''eau de cuisson et mélanger 1 à 2 min jusqu''à ce que ce soit brillant et chaud.","Servir parsemé de cacahuètes et d''oignon nouveau."]},"it":{"title":"Noodles saltati con maiale hoisin e broccoli","steps":["Mescolare il maiale con 1 cucchiaio di salsa di soia e l''amido; lasciare riposare 10 min.","Mescolare la salsa hoisin con il resto della salsa di soia, il miele, l''aceto, l''olio di sesamo e il peperoncino.","Cuocere i noodles in acqua bollente come indicato sulla confezione, aggiungendo i broccoli negli ultimi 2 min. Tenere da parte 60 ml di acqua di cottura, poi scolare.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo e scottare il maiale in un solo strato 2-3 min, girandolo una volta, finché è dorato e appena cotto. Tenere da parte.","Aggiungere il resto dell''olio, aglio, zenzero e carota e saltare 1 min.","Aggiungere noodles, broccoli, maiale, salsa e un goccio di acqua di cottura e saltare 1-2 min finché è tutto lucido e caldo.","Servire con arachidi e cipollotto."]}}'::jsonb),
  ('261d4acf-50fc-4e1b-be3f-9558751ad743'::uuid, '{"fr":{"title":"Saumon au gingembre, pak-choï et nouilles","steps":["Mélanger la sauce soja, le gingembre, l''ail, le miel, l''huile de sésame et la sriracha. En verser les deux tiers sur le saumon et laisser 30 min au réfrigérateur.","Préchauffer le four à 220 °C (200 °C chaleur tournante).","Cuire le saumon sur une plaque recouverte de papier cuisson 12 à 14 min, jusqu''à ce qu''il s''effeuille facilement.","Pendant ce temps, cuire les nouilles selon le paquet en ajoutant le pak-choï pour les 2 dernières minutes, puis égoutter.","Chauffer l''huile dans la casserole vide, ajouter l''oignon nouveau, le reste de la marinade et le vinaigre et laisser bouillonner 1 min, puis ajouter les nouilles et le pak-choï et mélanger.","Servir le saumon sur les nouilles et parsemer de graines de sésame."]},"it":{"title":"Salmone allo zenzero con pak choi e noodles","steps":["Mescolare salsa di soia, zenzero, aglio, miele, olio di sesamo e sriracha. Versarne due terzi sul salmone e lasciarlo 30 min in frigo.","Preriscaldare il forno a 220 °C (200 °C ventilato).","Cuocere il salmone su una teglia foderata 12-14 min, finché si sfalda facilmente.","Nel frattempo, cuocere i noodles come indicato sulla confezione aggiungendo il pak choi negli ultimi 2 min, poi scolare.","Scaldare l''olio nella pentola vuota, aggiungere il cipollotto, il resto della marinata e l''aceto e far bollire 1 min, poi unire noodles e pak choi e mescolare.","Servire il salmone sui noodles e cospargere di semi di sesamo."]}}'::jsonb),
  ('a0cb6512-daf4-4ea6-b97d-8730541d8c4f'::uuid, '{"fr":{"title":"Tofu croustillant sauce orange-gingembre et riz","steps":["Envelopper le tofu dans un torchon propre, poser une casserole lourde dessus et presser 20 min.","Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Couper le tofu en cubes de 2,5 cm, le mélanger avec 1 c. à soupe de sauce soja, puis avec 2 c. à soupe de fécule pour bien l''enrober.","Faire dorer le tofu dans l''huile à feu moyen-vif 8 à 10 min, en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces. Réserver sur une grille.","Fouetter le jus et le zeste d''orange, le reste de la sauce soja, le vinaigre, le sucre, le piment et 3 c. à café de fécule.","Dans la même poêle, faire revenir le gingembre et l''ail 30 s, verser la sauce et laisser frémir 2 à 3 min en remuant, jusqu''à ce qu''elle soit épaisse et brillante.","Hors du feu, enrober le tofu de sauce et servir sur le riz avec l''oignon nouveau et les graines de sésame."]},"it":{"title":"Tofu croccante con salsa all''arancia e zenzero e riso","steps":["Avvolgere il tofu in un canovaccio pulito, appoggiarci sopra una pentola pesante e pressarlo 20 min.","Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Tagliare il tofu a cubetti di 2,5 cm, mescolarlo con 1 cucchiaio di salsa di soia, poi con 2 cucchiai di amido finché è ben rivestito.","Rosolare il tofu nell''olio a fuoco medio-alto 8-10 min, girandolo, finché è croccante e dorato su tutti i lati. Tenerlo da parte su una griglia.","Sbattere succo e scorza d''arancia, il resto della salsa di soia, aceto, zucchero, peperoncino e 3 cucchiaini di amido.","Nella stessa padella, cuocere zenzero e aglio 30 s, versare la salsa e cuocere 2-3 min mescolando, finché è densa e lucida.","Fuori dal fuoco, ripassare il tofu nella salsa e servirlo sul riso con cipollotto e semi di sesamo."]}}'::jsonb),
  ('cf5613cb-4635-4714-bf7b-da5b7ac6a5d9'::uuid, '{"fr":{"title":"Mapo tofu","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Torréfier le poivre du Sichuan à sec dans le wok 2 min jusqu''à ce qu''il embaume, le moudre finement et réserver.","Porter 600 ml d''eau salée additionnée de sauce soja foncée à frémissement dans le wok, y glisser le tofu 3 min, puis le retirer délicatement et vider le wok.","Chauffer 1 c. à soupe d''huile à feu vif et faire revenir le bœuf 4 à 5 min jusqu''à ce qu''il soit doré et un peu croustillant ; ajouter 1 c. à café de sauce soja et réserver.","Baisser le feu, ajouter le reste de l''huile, l''ail et le gingembre 1 min 30, puis les haricots noirs fermentés et le doubanjiang 2 à 3 min en remuant sans cesse, et le piment en poudre et le paprika 30 s, jusqu''à ce que l''huile devienne rouge.","Verser le bouillon et le reste de la sauce soja, porter à frémissement et y glisser le tofu. Laisser mijoter 8 à 10 min en poussant le tofu avec le dos d''une spatule plutôt que de remuer.","Ajouter le bœuf, le sucre et la moitié du poivre du Sichuan. Verser la fécule délayée dans 3 c. à soupe d''eau en surface et remuer délicatement jusqu''à ce que la sauce soit brillante et épaisse.","Incorporer l''oignon nouveau et l''huile de sésame, saupoudrer du reste de poivre du Sichuan et servir sur le riz."]},"it":{"title":"Mapo tofu","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Tostare il pepe di Sichuan nel wok asciutto 2 min finché profuma, macinarlo finemente e tenerlo da parte.","Portare a sobbollore 600 ml di acqua salata con la salsa di soia scura nel wok, immergere il tofu per 3 min, poi toglierlo delicatamente e svuotare il wok.","Scaldare 1 cucchiaio d''olio a fuoco vivo e rosolare il manzo 4-5 min finché è dorato e un po'' croccante; aggiungere 1 cucchiaino di salsa di soia e tenerlo da parte.","Abbassare il fuoco, aggiungere il resto dell''olio, aglio e zenzero per 90 s, poi i fagioli neri fermentati e il doubanjiang per 2-3 min mescolando di continuo, e peperoncino in polvere e paprika per 30 s, finché l''olio diventa rosso.","Versare il brodo e il resto della salsa di soia, portare a bollore e unire il tofu. Cuocere 8-10 min spingendo il tofu con il dorso di una spatola invece di mescolare.","Aggiungere il manzo, lo zucchero e metà del pepe di Sichuan. Versare sopra l''amido stemperato in 3 cucchiai di acqua e mescolare delicatamente finché la salsa è lucida e densa.","Unire cipollotto e olio di sesamo, cospargere con il resto del pepe di Sichuan e servire sul riso."]}}'::jsonb),
  ('c27f8d79-6a7d-40f6-b374-34634d94bd69'::uuid, '{"fr":{"title":"Hong shao rou (porc braisé rouge)","steps":["Cuire les œufs 8 min dans l''eau bouillante, les refroidir dans l''eau froide et les écaler.","Mettre le porc dans une cocotte à fond épais, couvrir d''eau froide, porter à ébullition et faire bouillir 2 min. Égoutter, rincer et essuyer la cocotte.","Faire fondre le sucre dans l''huile à feu doux 3 à 4 min jusqu''à obtenir un caramel ambré clair.","Ajouter le porc, passer à feu moyen et remuer 3 à 4 min jusqu''à ce qu''il soit enrobé et légèrement doré.","Ajouter le gingembre, l''oignon nouveau et l''anis étoilé, verser le vin de Shaoxing et cuire 1 min, puis ajouter les deux sauces soja et environ 400 ml d''eau chaude, de quoi presque couvrir.","Couvrir et laisser mijoter doucement 60 à 75 min, en remuant toutes les 10 à 15 min et en ajoutant de l''eau si nécessaire ; ajouter les œufs au bout de 30 min.","Pendant les 20 dernières minutes, rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Quand le porc est tendre à la fourchette, poser le pak-choï dessus, couvrir 4 min et le retirer. Découvrir, monter le feu et faire bouillir 5 à 8 min en remuant, jusqu''à ce que la sauce soit laquée et collante. Servir avec le riz et les légumes."]},"it":{"title":"Hong shao rou (maiale brasato rosso)","steps":["Cuocere le uova 8 min in acqua bollente, raffreddarle in acqua fredda e sgusciarle.","Mettere il maiale in una pentola dal fondo spesso, coprirlo con acqua fredda, portare a ebollizione e bollire 2 min. Scolare, sciacquare e asciugare la pentola.","Sciogliere lo zucchero nell''olio a fuoco basso 3-4 min fino a ottenere un caramello ambrato chiaro.","Aggiungere il maiale, alzare a fuoco medio e mescolare 3-4 min finché è ricoperto e leggermente dorato.","Aggiungere zenzero, cipollotto e anice stellato, versare il vino di Shaoxing e cuocere 1 min, poi aggiungere le due salse di soia e circa 400 ml di acqua calda, quanto basta per coprire quasi del tutto.","Coprire e cuocere a fuoco dolce 60-75 min, mescolando ogni 10-15 min e aggiungendo acqua se si asciuga; aggiungere le uova dopo 30 min.","Negli ultimi 20 min, sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Quando il maiale è tenero alla forchetta, adagiarvi sopra il pak choi, coprire 4 min e toglierlo. Scoprire, alzare il fuoco e far bollire 5-8 min mescolando, finché la salsa diventa una glassa appiccicosa. Servire con il riso e le verdure."]}}'::jsonb),
  ('2e88837a-8303-4192-b86e-937e56874383'::uuid, '{"fr":{"title":"Œufs brouillés sautés à la tomate","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Battre les œufs avec le vin de Shaoxing, une pincée de sel et du poivre.","Mélanger le concentré de tomate, la fécule et le sucre avec 3 c. à soupe d''eau.","Chauffer 2 c. à soupe d''huile dans un wok à feu moyen-vif et brouiller les œufs 1 à 2 min jusqu''à ce qu''ils soient juste pris mais encore brillants. Les verser dans un bol.","Ajouter le reste de l''huile, les tomates et le blanc des oignons nouveaux avec une pincée de sel et cuire 3 min jusqu''à ce qu''elles soient tendres et juteuses mais encore entières.","Incorporer le mélange au concentré de tomate jusqu''à ce qu''il épaississe, remettre les œufs et mélanger délicatement 30 s.","Éteindre le feu, arroser d''huile de sésame, parsemer du vert des oignons nouveaux et servir sur le riz."]},"it":{"title":"Uova strapazzate saltate al pomodoro","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Sbattere le uova con il vino di Shaoxing, un pizzico di sale e pepe.","Mescolare concentrato di pomodoro, amido e zucchero con 3 cucchiai di acqua.","Scaldare 2 cucchiai d''olio in un wok a fuoco medio-alto e strapazzare le uova 1-2 min finché sono appena rapprese ma ancora lucide. Versarle in una ciotola.","Aggiungere il resto dell''olio, i pomodori e la parte bianca dei cipollotti con un pizzico di sale e cuocere 3 min finché sono morbidi e succosi ma ancora interi.","Unire il composto al concentrato finché si addensa, rimettere le uova e mescolare delicatamente 30 s.","Spegnere il fuoco, condire con olio di sesamo, cospargere con la parte verde dei cipollotti e servire sul riso."]}}'::jsonb),
  ('b43b0cd3-cfe4-4513-9b78-fc0e2c6d9a22'::uuid, '{"fr":{"title":"Porc char siu et légumes verts","steps":["Mélanger la sauce hoisin, 1 c. à soupe de sauce soja, le miel, le sucre, 0,5 c. à soupe de sauce d''huître, le vin de Shaoxing, le cinq-épices, l''huile de sésame et l''ail. En enrober le porc, réserver 2 c. à soupe de marinade et laisser au réfrigérateur au moins 4 h, ou toute une nuit.","Préchauffer le four à 220 °C. Poser le porc sur une grille au-dessus d''une plaque recouverte de papier aluminium.","Rôtir 20 à 25 min en le retournant et en le badigeonnant de marinade réservée toutes les 10 min, jusqu''à 63 °C à cœur.","Passer en position gril les 2 dernières minutes pour caraméliser les bords, puis laisser reposer 10 min.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; poser le pak-choï dessus pour les 4 dernières minutes afin qu''il cuise à la vapeur, puis laisser reposer 5 min.","Mélanger 1 c. à soupe de sauce d''huître avec le reste de la sauce soja et 1 c. à soupe d''eau chaude et en napper les légumes.","Trancher le porc dans le sens contraire des fibres et servir avec le riz et les légumes, parsemé de graines de sésame et d''oignon nouveau."]},"it":{"title":"Maiale char siu con verdure","steps":["Mescolare salsa hoisin, 1 cucchiaio di salsa di soia, miele, zucchero, mezzo cucchiaio di salsa di ostriche, vino di Shaoxing, cinque spezie, olio di sesamo e aglio. Ricoprire il maiale, tenere da parte 2 cucchiai di marinata e lasciare in frigo almeno 4 h, o tutta la notte.","Preriscaldare il forno a 220 °C. Mettere il maiale su una griglia sopra una teglia foderata di carta stagnola.","Arrostire 20-25 min girandolo e spennellandolo con la marinata tenuta da parte ogni 10 min, finché raggiunge 63 °C al cuore.","Passare al grill negli ultimi 2 min per caramellare i bordi, poi lasciare riposare 10 min.","Nel frattempo, sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; adagiarvi sopra il pak choi negli ultimi 4 min perché cuocia al vapore, poi lasciare riposare 5 min.","Mescolare 1 cucchiaio di salsa di ostriche con il resto della salsa di soia e 1 cucchiaio di acqua calda e versarlo sulle verdure.","Affettare il maiale contro fibra e servirlo con il riso e le verdure, cosparso di semi di sesamo e cipollotto."]}}'::jsonb),
  ('beeb1367-a9d8-4d08-aac1-88fd80b58e0a'::uuid, '{"fr":{"title":"Agneau sauté au cumin","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Mélanger l''agneau avec la sauce soja, le vin de Shaoxing, une pincée de sel, le bicarbonate et la fécule ; laisser reposer 10 min.","Mélanger le cumin, le poivre du Sichuan et le sucre.","Chauffer 1,5 c. à soupe d''huile dans un wok à feu vif et cuire l''agneau en deux fois : l''étaler, laisser 30 s, puis remuer 1 min jusqu''à ce qu''il soit doré. Réserver.","Ajouter le reste de l''huile, le piment, le gingembre et l''ail 10 s, puis l''oignon ; faire sauter 2 min jusqu''à ce qu''il commence à s''attendrir.","Remettre l''agneau, saupoudrer du mélange d''épices et remuer 1 min pour bien enrober.","Ajouter la coriandre et les graines de sésame et servir aussitôt sur le riz."]},"it":{"title":"Agnello saltato al cumino","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare l''agnello con salsa di soia, vino di Shaoxing, un pizzico di sale, bicarbonato e amido; lasciare riposare 10 min.","Mescolare cumino, pepe di Sichuan e zucchero.","Scaldare 1,5 cucchiai d''olio in un wok a fuoco vivo e cuocere l''agnello in due volte: stenderlo, lasciarlo 30 s, poi saltarlo 1 min finché è dorato. Tenere da parte.","Aggiungere il resto dell''olio, peperoncino, zenzero e aglio per 10 s, poi la cipolla; saltare 2 min finché inizia ad ammorbidirsi.","Rimettere l''agnello, cospargere con il mix di spezie e saltare 1 min finché è ben condito.","Unire coriandolo e semi di sesamo e servire subito sul riso."]}}'::jsonb),
  ('1894de61-71cb-45f7-aba5-7cdf36e2e69e'::uuid, '{"fr":{"title":"Nasu dengaku au tofu et nouilles soba","steps":["Préchauffer le four à 220 °C. Couper les aubergines en deux dans la longueur, quadriller la chair profondément sans percer la peau et badigeonner les faces coupées avec presque toute l''huile.","Éponger le tofu et le badigeonner du reste de l''huile.","Rôtir les aubergines côté chair vers le haut et le tofu sur une même plaque recouverte de papier cuisson 20 à 25 min, en retournant le tofu une fois, jusqu''à ce que la chair des aubergines soit fondante à cœur et dorée.","Fouetter le miso, le mirin, le saké et le sucre pour obtenir un glaçage lisse.","Passer le four en position gril à puissance maximale, napper les aubergines et le tofu de glaçage et passer sous le gril 3 à 4 min jusqu''à ce qu''il bouillonne et caramélise par endroits ; surveiller, car il brûle vite.","Pendant ce temps, cuire les soba selon le paquet, les rincer à l''eau froide et les mélanger avec la sauce soja, l''huile de sésame et l''oignon nouveau.","Servir les aubergines et le tofu parsemés de graines de sésame, avec les soba à côté."]},"it":{"title":"Nasu dengaku con tofu e soba","steps":["Preriscaldare il forno a 220 °C. Tagliare le melanzane a metà per il lungo, incidere la polpa a griglia in profondità senza tagliare la buccia e spennellare i lati tagliati con quasi tutto l''olio.","Asciugare il tofu e spennellarlo con il resto dell''olio.","Arrostire le melanzane con il lato tagliato verso l''alto e il tofu su un''unica teglia foderata 20-25 min, girando il tofu una volta, finché la polpa delle melanzane è morbida e dorata.","Sbattere miso, mirin, sake e zucchero fino a ottenere una glassa liscia.","Passare il forno al grill al massimo, stendere la glassa su melanzane e tofu e grigliare 3-4 min finché bolle e si colora qua e là; controllare perché brucia in fretta.","Nel frattempo, cuocere le soba come indicato sulla confezione, sciacquarle in acqua fredda e condirle con salsa di soia, olio di sesamo e cipollotto.","Servire melanzane e tofu cosparsi di semi di sesamo, con le soba a parte."]}}'::jsonb),
  ('52915883-18c7-40b1-9500-09f4efc12426'::uuid, '{"fr":{"title":"Tofu teriyaki, brocoli et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Bien sécher le tofu dans un torchon propre et enrober les cubes de 1 c. à soupe de fécule et d''une pincée de sel.","Fouetter la sauce soja, le miel, le vinaigre, l''ail, le gingembre, 80 ml d''eau et les 2 c. à café de fécule pour obtenir une sauce teriyaki lisse.","Faire dorer le tofu dans 1,5 c. à soupe d''huile dans une grande poêle antiadhésive à feu moyen-vif, en le retournant, 10 à 12 min. Le réserver.","Ajouter le reste de l''huile, le brocoli et 2 c. à soupe d''eau, et faire sauter 4 à 5 min jusqu''à ce qu''il soit vert vif et encore croquant.","Baisser le feu, verser la sauce et remuer environ 30 s jusqu''à ce qu''elle bouillonne et épaississe, puis remettre le tofu et mélanger pour le laquer.","Servir sur le riz, parsemé de sésame et d''oignon nouveau."]},"it":{"title":"Tofu teriyaki con broccoli e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Asciugare bene il tofu con un canovaccio pulito e passare i cubetti in 1 cucchiaio di amido con un pizzico di sale.","Sbattere la salsa di soia, il miele, l''aceto, l''aglio, lo zenzero, 80 ml d''acqua e i 2 cucchiaini di amido fino a ottenere una salsa teriyaki liscia.","Rosolare il tofu in 1,5 cucchiai d''olio in una padella antiaderente a fuoco medio-alto, girandolo, per 10-12 min finché è dorato su tutti i lati. Toglierlo.","Aggiungere l''olio rimasto, i broccoli e 2 cucchiai d''acqua e saltare 4-5 min finché sono verde brillante e ancora croccanti.","Abbassare il fuoco, versare la salsa e mescolare circa 30 s finché bolle e si addensa, poi rimettere il tofu e mescolare per glassarlo.","Servire sul riso, cosparso di sesamo e cipollotto."]}}'::jsonb),
  ('62893e4f-bac6-47e6-9a16-28e32690738a'::uuid, '{"fr":{"title":"Soupe udon au miso, champignons, tofu et œuf","steps":["Plonger les œufs dans l''eau bouillante et les cuire 6 min 30 pour un jaune fondant ; les refroidir à l''eau froide et les écaler. Vider la casserole.","Dans la même casserole, porter 800 ml d''eau et le dashi à frémissement avec le gingembre et l''ail.","Ajouter les champignons et la sauce soja et laisser frémir 5 min jusqu''à ce que les champignons soient tendres.","Ajouter les udon, le tofu et le pak-choï et laisser frémir 2 à 3 min, jusqu''à ce que les nouilles se détachent et que le pak-choï soit tombé.","Retirer du feu. Délayer le miso dans une louche de bouillon et le remettre dans la casserole ; ne plus faire bouillir.","Répartir dans des bols, garnir des œufs coupés en deux et d''oignon nouveau, puis finir avec l''huile de sésame, le sésame et le piment."]},"it":{"title":"Zuppa di udon al miso con funghi, tofu e uovo","steps":["Immergere le uova in acqua bollente e cuocerle 6 min e mezzo per un tuorlo cremoso; raffreddarle in acqua fredda e sgusciarle. Svuotare la pentola.","Nella stessa pentola portare a sobbollire 800 ml d''acqua con il dashi, lo zenzero e l''aglio.","Aggiungere i funghi e la salsa di soia e cuocere a fuoco lento 5 min finché i funghi sono teneri.","Aggiungere gli udon, il tofu e il pak choi e cuocere 2-3 min, finché i noodles si separano e il pak choi appassisce.","Togliere dal fuoco. Sciogliere il miso in un mestolo di brodo e rimetterlo nella pentola; non farlo più bollire.","Distribuire nelle ciotole, completare con le uova tagliate a metà e il cipollotto, poi finire con olio di sesamo, sesamo e peperoncino."]}}'::jsonb),
  ('9b05494a-6b38-47d3-a478-7965c5cf3c64'::uuid, '{"fr":{"title":"Thon snacké, épinards au sésame et riz","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert dans 180 ml d''eau à feu doux 12 min et le laisser reposer 10 min hors du feu.","Tiédir le vinaigre avec 1 c. à café de sucre et ½ c. à café de sel jusqu''à dissolution et l''incorporer délicatement au riz chaud.","Torréfier 2 c. à soupe de sésame à sec dans une poêle 2 min jusqu''à ce qu''il dore, puis l''écraser grossièrement et le mélanger avec 1 c. à soupe de sauce soja et le reste du sucre.","Faire tomber les épinards dans la même poêle avec un peu d''eau, environ 2 min ; les presser, les hacher et les mélanger à la sauce au sésame. Essuyer la poêle.","Sécher le thon, le badigeonner d''huile de sésame, le saler légèrement et presser le reste du sésame sur les deux faces.","Chauffer l''huile végétale dans la poêle à feu vif et saisir le thon 1 min par face pour un cœur rosé (2 min pour à point). Laisser reposer 2 min.","Trancher le thon contre le fil et servir sur le riz avec les épinards, le gingembre mariné, l''oignon nouveau et le reste de la sauce soja."]},"it":{"title":"Tonno scottato con spinaci al sesamo e riso","steps":["Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto in 180 ml d''acqua a fuoco basso per 12 min e lasciarlo riposare 10 min fuori dal fuoco.","Scaldare l''aceto con 1 cucchiaino di zucchero e mezzo cucchiaino di sale finché si sciolgono e incorporarlo delicatamente al riso caldo.","Tostare 2 cucchiai di sesamo in una padella asciutta per 2 min finché è dorato, poi pestarlo grossolanamente e mescolarlo con 1 cucchiaio di salsa di soia e lo zucchero rimasto.","Far appassire gli spinaci nella stessa padella con un goccio d''acqua, circa 2 min; strizzarli, tritarli e condirli con la salsa al sesamo. Pulire la padella.","Asciugare il tonno, spennellarlo con l''olio di sesamo, salarlo leggermente e premere il sesamo rimasto su entrambi i lati.","Scaldare l''olio di semi nella padella a fuoco vivo e scottare il tonno 1 min per lato per un cuore al sangue (2 min per una cottura media). Lasciarlo riposare 2 min.","Tagliare il tonno contro fibra e servirlo sul riso con gli spinaci, lo zenzero marinato, il cipollotto e il resto della salsa di soia."]}}'::jsonb),
  ('ff1bfc7c-f6d4-4c1e-a75e-45eb3b87e0dc'::uuid, '{"fr":{"title":"Katsu de poulet au four, riz et chou","steps":["Préchauffer le four à 200 °C. Mélanger le panko avec 1,5 c. à soupe d''huile sur la plaque du four et le faire dorer au four 4 à 5 min en remuant une fois ; le verser dans une assiette pour qu''il refroidisse.","Ouvrir chaque filet en portefeuille et l''aplatir à une épaisseur régulière de 1 à 1,5 cm ; saler et poivrer.","Battre l''œuf avec le reste de l''huile. Passer chaque escalope dans la farine, puis dans l''œuf, puis la presser fermement dans le panko doré.","Poser les escalopes sur une grille au-dessus de la même plaque et cuire 20 à 25 min, jusqu''à ce que le jus soit clair (74 °C à cœur).","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Mélanger le ketchup, la sauce Worcestershire, la sauce soja et le sucre pour une sauce tonkatsu express. Plonger le chou 5 min dans de l''eau glacée et bien l''égoutter.","Laisser reposer le katsu 2 min, le couper en lanières et servir avec le riz, le chou, le citron et la sauce en filet."]},"it":{"title":"Katsu di pollo al forno con riso e cavolo","steps":["Scaldare il forno a 200 °C. Mescolare il panko con 1,5 cucchiai d''olio sulla teglia e tostarlo in forno 4-5 min, mescolando una volta, finché è dorato; versarlo in un piatto a raffreddare.","Aprire ogni petto a libro e batterlo a uno spessore uniforme di 1-1,5 cm; salare e pepare.","Sbattere l''uovo con l''olio rimasto. Passare ogni cotoletta nella farina, poi nell''uovo, poi premerla bene nel panko tostato.","Disporre le cotolette su una griglia sopra la stessa teglia e cuocere 20-25 min, finché i succhi sono chiari (74 °C al cuore).","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mescolare il ketchup, la salsa Worcestershire, la salsa di soia e lo zucchero per una salsa tonkatsu veloce. Immergere il cavolo 5 min in acqua ghiacciata e scolarlo bene.","Lasciare riposare il katsu 2 min, tagliarlo a strisce e servirlo con il riso, il cavolo, il limone e la salsa a filo."]}}'::jsonb),
  ('3d4d6f57-5e42-4208-af77-afff5162cee1'::uuid, '{"fr":{"title":"Salade de riz à sushi, tofu et edamame","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, le cuire à couvert dans 180 ml d''eau à feu doux 12 min et le laisser reposer 10 min hors du feu.","Dissoudre 2 c. à soupe de vinaigre, le sucre et ½ c. à café de sel, les incorporer au riz, l''étaler sur une assiette et laisser refroidir 15 min.","Cuire les edamame 3 min dans une poêle avec un peu d''eau, puis les égoutter et les laisser refroidir.","Sécher le tofu et le faire dorer dans l''huile dans la même poêle à feu moyen-vif, 8 min ; ajouter 1 c. à soupe de sauce soja et mélanger jusqu''à absorption.","Fouetter le reste de sauce soja et de vinaigre avec l''huile de sésame pour la sauce.","Répartir le riz dans deux bols et garnir de tofu, d''edamame, de concombre, de carotte et d''avocat.","Arroser de sauce et finir avec le gingembre mariné, le sésame et l''oignon nouveau."]},"it":{"title":"Insalata di riso da sushi con tofu ed edamame","steps":["Sciacquare il riso finché l''acqua è limpida, cuocerlo coperto in 180 ml d''acqua a fuoco basso per 12 min e lasciarlo riposare 10 min fuori dal fuoco.","Sciogliere 2 cucchiai di aceto, lo zucchero e mezzo cucchiaino di sale, incorporarli al riso, stenderlo su un piatto e lasciarlo raffreddare 15 min.","Cuocere gli edamame 3 min in padella con un goccio d''acqua, poi scolarli e lasciarli raffreddare.","Asciugare il tofu e rosolarlo nell''olio nella stessa padella a fuoco medio-alto, 8 min, finché è dorato; aggiungere 1 cucchiaio di salsa di soia e mescolare finché si assorbe.","Sbattere la salsa di soia e l''aceto rimasti con l''olio di sesamo per il condimento.","Dividere il riso in due ciotole e completare con tofu, edamame, cetriolo, carota e avocado.","Condire con la salsa e finire con zenzero marinato, sesamo e cipollotto."]}}'::jsonb),
  ('85118fd3-d36c-4fb3-83b3-c39289e6bc96'::uuid, '{"fr":{"title":"Donburi de tsukune","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Pétrir à la main le poulet haché, presque tout l''oignon nouveau, le gingembre, l''œuf, la fécule et une pincée de sel 1 à 2 min, jusqu''à ce que le mélange colle.","Les mains mouillées, former 10 à 12 petites boulettes aplaties.","Cuire le brocoli dans une poêle avec 3 c. à soupe d''eau, à couvert, 3 à 4 min jusqu''à ce qu''il soit juste tendre ; réserver.","Chauffer l''huile dans la poêle à feu moyen et cuire les tsukune 3 à 4 min par face, jusqu''à ce qu''ils soient dorés et cuits à cœur.","Mélanger la sauce soja, le mirin, le saké et le sucre, verser dans la poêle et laisser bouillonner 1 à 2 min en retournant les boulettes jusqu''à ce qu''elles soient brillantes et laquées.","Servir les tsukune et le brocoli sur le riz avec la sauce de la poêle, un jaune d''œuf cru par-dessus si on le souhaite, le sésame, le piment et le reste de l''oignon nouveau."]},"it":{"title":"Donburi di tsukune","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Impastare a mano il pollo macinato, quasi tutto il cipollotto, lo zenzero, l''uovo, l''amido e un pizzico di sale per 1-2 min finché il composto è appiccicoso.","Con le mani bagnate formare 10-12 piccole polpette appiattite.","Cuocere i broccoli in padella con 3 cucchiai d''acqua, coperti, 3-4 min finché sono appena teneri; tenerli da parte.","Scaldare l''olio nella padella a fuoco medio e cuocere gli tsukune 3-4 min per lato finché sono dorati e cotti all''interno.","Mescolare la salsa di soia, il mirin, il sake e lo zucchero, versare nella padella e far sobbollire 1-2 min girando le polpette finché sono lucide e glassate.","Servire gli tsukune e i broccoli sul riso con la glassa della padella, un tuorlo crudo sopra a piacere, sesamo, peperoncino e il cipollotto rimasto."]}}'::jsonb),
  ('f2f27077-f5bc-493c-9769-5f62aefa34eb'::uuid, '{"fr":{"title":"Butaniku shōgayaki (porc au gingembre)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Mélanger le gingembre, l''ail, la sauce soja, le mirin, le saké et le sucre pour la sauce. Saler et poivrer légèrement le porc.","Chauffer l''huile dans une grande poêle à feu moyen-vif et faire revenir l''oignon 2 min.","Étaler les tranches de porc dans la poêle et les cuire 1 à 2 min par face jusqu''à ce qu''elles soient dorées.","Verser la sauce et laisser bouillonner 1 à 2 min en retournant le porc, jusqu''à ce qu''elle réduise et nappe la viande.","Servir le porc et sa sauce avec un dôme de chou cru émincé et le riz, parsemé d''oignon nouveau."]},"it":{"title":"Butaniku shōgayaki (maiale allo zenzero)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mescolare zenzero, aglio, salsa di soia, mirin, sake e zucchero per la salsa. Salare e pepare leggermente il maiale.","Scaldare l''olio in una padella grande a fuoco medio-alto e soffriggere la cipolla 2 min.","Distendere le fette di maiale nella padella e cuocerle 1-2 min per lato finché sono dorate.","Versare la salsa e farla sobbollire 1-2 min girando il maiale, finché si riduce e avvolge la carne.","Servire il maiale con la sua salsa insieme a un mucchietto di cavolo crudo affettato e al riso, con cipollotto sopra."]}}'::jsonb),
  ('a6face1b-b335-4aae-b9cd-603f4dd6b7c1'::uuid, '{"fr":{"title":"Nikujaga (bœuf et pommes de terre mijotés)","steps":["Éplucher les pommes de terre, les couper en gros morceaux, arrondir les arêtes pour qu''elles se tiennent et les faire tremper 10 min dans l''eau froide.","Chauffer l''huile dans une cocotte à feu moyen et faire revenir l''oignon, la carotte et les pommes de terre égouttées 3 min, jusqu''à ce que les bords des pommes de terre deviennent translucides.","Ajouter le bœuf et remuer jusqu''à ce qu''il ne soit plus rose.","Verser 300 ml d''eau et le dashi, porter à ébullition et écumer. Ajouter d''abord le saké, le mirin et le sucre, couvrir d''une feuille de papier cuisson posée à la surface et laisser mijoter 12 min.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Ajouter la sauce soja au ragoût et laisser mijoter encore 10 min sans remuer, en arrosant avec le bouillon, jusqu''à ce que les pommes de terre soient tendres et le liquide réduit de moitié environ.","Ajouter les haricots verts pour les 3 dernières minutes. Servir en bols avec un peu de bouillon, le riz à côté."]},"it":{"title":"Nikujaga (manzo e patate in umido)","steps":["Sbucciare le patate, tagliarle a pezzi grossi, smussare gli spigoli perché restino intere e lasciarle 10 min in acqua fredda.","Scaldare l''olio in una pentola a fuoco medio e rosolare cipolla, carota e patate scolate per 3 min, finché i bordi delle patate diventano traslucidi.","Aggiungere il manzo e mescolare finché non è più rosa.","Versare 300 ml d''acqua con il dashi, portare a bollore e schiumare. Aggiungere prima sake, mirin e zucchero, coprire con un foglio di carta forno appoggiato sulla superficie e cuocere a fuoco lento 12 min.","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Aggiungere la salsa di soia allo stufato e cuocere ancora 10 min senza mescolare, irrorando con il brodo, finché le patate sono tenere e il liquido si è ridotto di circa metà.","Aggiungere i fagiolini negli ultimi 3 min. Servire in ciotole con un po'' di brodo, con il riso a parte."]}}'::jsonb),
  ('96bd3c95-432e-4410-b43d-d745112aa97b'::uuid, '{"fr":{"title":"Saba shioyaki (maquereau grillé au sel)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Saler généreusement le maquereau des deux côtés et le laisser 10 min pendant la cuisson du riz ; puis éponger l''humidité qui en sort.","Mélanger le concombre avec une pincée de sel, attendre 5 min, le presser puis l''assaisonner avec le vinaigre et le sucre.","Tapisser une poêle de papier aluminium, le badigeonner d''huile et chauffer à feu moyen.","Cuire le maquereau côté peau 4 à 5 min jusqu''à ce qu''elle soit croustillante et dorée, puis le retourner et cuire encore 3 à 4 min jusqu''à ce qu''il soit opaque à cœur.","Servir le poisson avec le riz, la salade de concombre parsemée de sésame, les quartiers de citron et le daikon râpé arrosé d''une goutte de sauce soja."]},"it":{"title":"Saba shioyaki (sgombro alla griglia con sale)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Salare abbondantemente lo sgombro su entrambi i lati e lasciarlo 10 min mentre cuoce il riso; poi tamponare l''umidità che rilascia.","Mescolare il cetriolo con un pizzico di sale, attendere 5 min, strizzarlo e condirlo con l''aceto e lo zucchero.","Foderare una padella con carta stagnola, spennellarla d''olio e scaldarla a fuoco medio.","Cuocere lo sgombro dal lato della pelle 4-5 min finché è croccante e dorata, poi girarlo e cuocere altri 3-4 min finché è opaco all''interno.","Servire il pesce con il riso, l''insalata di cetriolo cosparsa di sesamo, spicchi di limone e il daikon grattugiato con una goccia di salsa di soia."]}}'::jsonb),
  ('179efe64-fe23-4da3-97b2-836e0e98e0cf'::uuid, '{"fr":{"title":"Curry japonais au poulet","steps":["Saler et poivrer le poulet et le faire dorer dans l''huile dans une cocotte à feu moyen-vif, environ 5 min. Le réserver.","Baisser le feu, ajouter l''oignon, l''ail et le gingembre et cuire en remuant 6 à 7 min jusqu''à ce qu''ils soient fondants et dorés.","Ajouter le beurre, puis incorporer la farine et le curry et cuire 2 min jusqu''à ce que le roux sente le grillé.","Verser le bouillon petit à petit en fouettant, puis ajouter le poulet, les carottes, la pomme de terre, la pomme, la sauce Worcestershire, le ketchup et le laurier. Couvrir et laisser mijoter 15 min en remuant de temps en temps, jusqu''à ce que les légumes soient tendres et la sauce épaisse.","Pendant ce temps, rincer le riz et le cuire à couvert dans 280 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Ajouter les petits pois, laisser frémir 2 min, puis rectifier le sel. Servir à côté du riz."]},"it":{"title":"Curry giapponese di pollo","steps":["Salare e pepare il pollo e rosolarlo nell''olio in una pentola dal fondo spesso a fuoco medio-alto, circa 5 min. Toglierlo.","Abbassare il fuoco, aggiungere cipolla, aglio e zenzero e cuocere mescolando per 6-7 min finché sono morbidi e dorati.","Aggiungere il burro, poi incorporare la farina e il curry e cuocere 2 min finché il roux profuma di tostato.","Unire il brodo poco alla volta mescolando con la frusta, poi aggiungere il pollo, le carote, la patata, la mela, la salsa Worcestershire, il ketchup e l''alloro. Coprire e cuocere a fuoco lento 15 min, mescolando ogni tanto, finché le verdure sono tenere e la salsa è densa.","Nel frattempo sciacquare il riso e cuocerlo coperto in 280 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Unire i piselli, cuocere 2 min, poi regolare di sale. Servire accanto al riso."]}}'::jsonb),
  ('090b603f-91ab-4c37-8c40-93b84e835d51'::uuid, '{"fr":{"title":"Soba froides au tofu et edamame","steps":["Porter 240 ml d''eau, le dashi, la sauce soja, le saké et le sucre à ébullition dans une casserole et laisser bouillir 1 min. Verser dans un bol et le mettre au frais (quelques glaçons accélèrent le refroidissement).","Sécher le tofu et le faire dorer dans l''huile dans une poêle à feu moyen-vif, 3 min par face. Le couper en lanières.","Porter une grande casserole d''eau à gros bouillons, ajouter les edamame et les soba, remuer et cuire le temps indiqué sur le paquet de soba (souvent 4 à 5 min).","Égoutter et rincer sous l''eau froide en frottant les nouilles pour enlever l''amidon, puis les plonger un instant dans de l''eau glacée et bien égoutter.","Dresser les soba et les edamame sur des assiettes avec le tofu et le concombre.","Servir la sauce froide dans de petits bols avec l''oignon nouveau et le daikon râpé à y ajouter, et le sésame à parsemer."]},"it":{"title":"Soba freddi con tofu ed edamame","steps":["Portare a bollore 240 ml d''acqua, dashi, salsa di soia, sake e zucchero in una pentola e bollire 1 min. Versare in una ciotola e farla raffreddare (qualche cubetto di ghiaccio aiuta).","Asciugare il tofu e rosolarlo nell''olio in una padella a fuoco medio-alto, 3 min per lato, finché è dorato. Tagliarlo a strisce.","Portare a bollore una pentola grande d''acqua, aggiungere edamame e soba, mescolare e cuocere per il tempo indicato sulla confezione dei soba (di solito 4-5 min).","Scolare e sciacquare sotto l''acqua fredda strofinando i noodles per eliminare l''amido, poi immergerli un attimo in acqua ghiacciata e scolarli bene.","Disporre soba ed edamame nei piatti con il tofu e il cetriolo.","Servire la salsa fredda in ciotoline con il cipollotto e il daikon grattugiato da aggiungere, e il sesamo da cospargere."]}}'::jsonb),
  ('2f9185f2-8f3c-45a9-809f-8577f36a66dc'::uuid, '{"fr":{"title":"Bánh mì au tofu croustillant","steps":["Mélanger la carotte et le daikon avec le vinaigre, 1 c. à soupe de sucre et ½ c. à café de sel ; laisser mariner au moins 20 min en remuant de temps en temps.","Préchauffer le four à 200 °C. Sécher le tofu et passer les tranches dans la fécule en secouant l''excédent.","Faire frire le tofu dans l''huile végétale dans une poêle antiadhésive à feu moyen-vif, 4 à 5 min par face, jusqu''à ce qu''il soit croustillant et doré. Le réserver.","Baisser le feu, faire revenir l''ail dans l''huile de sésame 1 min, puis ajouter la sauce soja, le reste du sucre et 3 c. à soupe d''eau. Remettre le tofu avec le zeste du citron vert et mélanger 1 à 2 min jusqu''à ce qu''il soit laqué.","Réchauffer les morceaux de baguette directement sur la grille du four 5 à 6 min jusqu''à ce qu''ils soient croustillants.","Mélanger la mayonnaise, la sriracha et 1 c. à soupe de jus de citron vert.","Ouvrir le pain, le tartiner de mayonnaise à la sriracha et le garnir de tofu, de pickles égouttés, de concombre, de coriandre et de piment."]},"it":{"title":"Bánh mì con tofu croccante","steps":["Mescolare carota e daikon con l''aceto, 1 cucchiaio di zucchero e mezzo cucchiaino di sale; lasciar marinare almeno 20 min mescolando ogni tanto.","Scaldare il forno a 200 °C. Asciugare il tofu e passare le fette nell''amido, scuotendo l''eccesso.","Friggere il tofu nell''olio di semi in una padella antiaderente a fuoco medio-alto, 4-5 min per lato, finché è croccante e dorato. Toglierlo.","Abbassare il fuoco, soffriggere l''aglio nell''olio di sesamo 1 min, poi aggiungere la salsa di soia, lo zucchero rimasto e 3 cucchiai d''acqua. Rimettere il tofu con la scorza del lime e mescolare 1-2 min finché è glassato.","Scaldare i pezzi di baguette direttamente sulla griglia del forno per 5-6 min finché sono croccanti.","Mescolare la maionese, la sriracha e 1 cucchiaio di succo di lime.","Aprire il pane, spalmarlo con la maionese alla sriracha e farcirlo con tofu, verdure sottaceto scolate, cetriolo, coriandolo e peperoncino."]}}'::jsonb),
  ('bd6e4d1a-f6e3-4a40-b674-40721b9a6a01'::uuid, '{"fr":{"title":"Pad thaï aux crevettes","steps":["Faire tremper les nouilles 15 à 20 min dans l''eau tiède jusqu''à ce qu''elles soient souples mais encore fermes ; égoutter.","Faire fondre le sucre avec 2 c. à soupe d''eau, puis incorporer la pâte de tamarin et la sauce de poisson.","Faire sauter le tofu et les crevettes dans 1 c. à soupe d''huile dans un wok à feu vif, 2 à 3 min jusqu''à ce que les crevettes soient roses. Réserver.","Ajouter le reste de l''huile et faire revenir l''ail et l''échalote 30 s jusqu''à ce qu''ils embaument.","Ajouter les nouilles et la sauce et faire sauter à feu vif 1 à 2 min jusqu''à ce que les nouilles soient tendres et aient absorbé la sauce.","Pousser les nouilles sur le côté, casser les œufs, les laisser prendre 30 s, puis remettre les crevettes et le tofu et mélanger le tout.","Ajouter les germes de soja et l''oignon nouveau, faire sauter 30 s et servir avec les cacahuètes, le citron vert en quartiers et le piment."]},"it":{"title":"Pad thai con gamberi","steps":["Ammollare i noodles in acqua tiepida per 15-20 min finché sono flessibili ma ancora sodi; scolarli.","Sciogliere lo zucchero con 2 cucchiai d''acqua, poi unire la pasta di tamarindo e la salsa di pesce.","Saltare tofu e gamberi in 1 cucchiaio d''olio nel wok a fuoco vivo per 2-3 min finché i gamberi diventano rosa. Tenerli da parte.","Aggiungere l''olio rimasto e soffriggere aglio e scalogno per 30 s finché profumano.","Aggiungere i noodles e la salsa e saltare a fuoco vivo 1-2 min finché i noodles si ammorbidiscono e assorbono la salsa.","Spostare i noodles di lato, rompere le uova, lasciarle rapprendere 30 s, poi rimettere gamberi e tofu e mescolare tutto.","Aggiungere germogli di soia e cipollotto, saltare 30 s e servire con le arachidi, il lime a spicchi e il peperoncino."]}}'::jsonb),
  ('bb6e3cf8-439f-4f5b-93df-b86fb163c981'::uuid, '{"fr":{"title":"Curry vert aubergine et tofu","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Sécher le tofu et le faire dorer dans l''huile dans un wok ou une sauteuse à feu moyen-vif, 6 à 8 min. Le réserver.","Faire revenir la pâte de curry dans la sauteuse avec 3 c. à soupe de la partie la plus épaisse du lait de coco 2 min, jusqu''à ce qu''elle embaume et que l''huile se sépare.","Ajouter le reste du lait de coco et 100 ml d''eau, puis l''aubergine, et laisser mijoter 8 à 10 min jusqu''à ce qu''elle soit fondante.","Ajouter les haricots verts et le tofu et laisser mijoter encore 4 min, jusqu''à ce que les haricots soient juste tendres.","Assaisonner avec la sauce soja, le sucre et le jus de citron vert, goûter, puis ajouter le basilic thaï hors du feu. Servir avec le riz et le piment."]},"it":{"title":"Curry verde di melanzane e tofu","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Asciugare il tofu e rosolarlo nell''olio in un wok o in una padella larga a fuoco medio-alto, 6-8 min, finché è dorato. Toglierlo.","Soffriggere la pasta di curry nella padella con 3 cucchiai della parte più densa del latte di cocco per 2 min, finché profuma e l''olio si separa.","Unire il resto del latte di cocco e 100 ml d''acqua, aggiungere la melanzana e cuocere a fuoco lento 8-10 min finché è morbida.","Aggiungere fagiolini e tofu e cuocere altri 4 min, finché i fagiolini sono appena teneri.","Condire con salsa di soia, zucchero e succo di lime, assaggiare, poi unire il basilico thai fuori dal fuoco. Servire con il riso e il peperoncino."]}}'::jsonb),
  ('b5647c45-2692-45ca-8ee6-c01a1edcf529'::uuid, '{"fr":{"title":"Rouleaux de printemps crevettes et avocat","steps":["Cuire les vermicelles 3 à 4 min dans l''eau bouillante (ou selon le paquet), les rincer à l''eau froide et bien les égoutter.","Fouetter le beurre de cacahuète, la sauce soja, le miel, le jus d''un demi-citron vert, le piment et 3 à 4 c. à soupe d''eau tiède pour une sauce lisse.","Arroser l''avocat du reste du citron vert pour qu''il ne noircisse pas.","Tremper une feuille de riz 10 à 15 s dans l''eau tiède jusqu''à ce qu''elle soit juste souple et la poser sur un torchon humide.","Disposer une rangée de demi-crevettes, côté coupé vers le haut, au centre, puis la salade, les vermicelles, la carotte, l''avocat et les herbes par-dessus.","Rabattre le bas sur la garniture, replier les côtés et rouler bien serré. Recommencer pour faire 8 rouleaux.","Servir aussitôt avec la sauce aux cacahuètes pour tremper."]},"it":{"title":"Involtini di carta di riso con gamberi e avocado","steps":["Cuocere i vermicelli in acqua bollente per 3-4 min (o secondo la confezione), sciacquarli in acqua fredda e scolarli bene.","Sbattere burro di arachidi, salsa di soia, miele, succo di mezzo lime, peperoncino e 3-4 cucchiai d''acqua tiepida fino a ottenere una salsa liscia.","Irrorare l''avocado con il resto del lime perché non annerisca.","Immergere un foglio di carta di riso in acqua tiepida per 10-15 s finché è appena morbido e stenderlo su un canovaccio umido.","Disporre al centro una fila di mezzi gamberi con il lato tagliato verso l''alto, poi sopra lattuga, vermicelli, carota, avocado ed erbe.","Ripiegare il lembo inferiore sul ripieno, chiudere i lati e arrotolare stretto. Ripetere per ottenere 8 involtini.","Servire subito con la salsa di arachidi per intingere."]}}'::jsonb),
  ('788cd98a-23e9-42b2-94d2-c323fbb2ec0b'::uuid, '{"fr":{"title":"Curry massaman au bœuf","steps":["Préchauffer le four à 160 °C. Faire dorer le bœuf dans l''huile dans une cocotte allant au four à feu vif, 5 min.","Ajouter l''oignon, l''ail et la pâte de curry et remuer 2 min jusqu''à ce qu''ils embaument.","Ajouter la cannelle, la cardamome, le bouillon et la moitié du lait de coco, porter à frémissement, couvrir et cuire au four 1 h 15.","Ajouter les pommes de terre, les cacahuètes, le reste du lait de coco, la sauce de poisson et le sucre, et remettre au four sans couvercle 50 à 60 min, jusqu''à ce que le bœuf soit tendre et les pommes de terre cuites.","Environ 20 min avant la fin, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Assaisonner le curry avec le jus d''un demi-citron vert, et un peu de sauce de poisson ou de sucre pour équilibrer le sucré, le salé et l''acide.","Servir avec le riz, la coriandre et le reste du citron vert en quartiers."]},"it":{"title":"Curry massaman di manzo","steps":["Scaldare il forno a 160 °C. Rosolare il manzo nell''olio in una casseruola adatta al forno a fuoco vivo, 5 min.","Aggiungere cipolla, aglio e pasta di curry e mescolare 2 min finché profumano.","Aggiungere cannella, cardamomo, brodo e metà del latte di cocco, portare a sobbollire, coprire e brasare in forno per 1 h 15 min.","Unire patate, arachidi, il resto del latte di cocco, la salsa di pesce e lo zucchero e rimettere in forno scoperto per 50-60 min, finché il manzo è tenero e le patate cotte.","Circa 20 min prima della fine sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Condire il curry con il succo di mezzo lime e altra salsa di pesce o zucchero per bilanciare dolce, salato e acido.","Servire con il riso, il coriandolo e il resto del lime a spicchi."]}}'::jsonb),
  ('6ea6bed6-f994-4c4e-b9dc-7e3c29d833b6'::uuid, '{"fr":{"title":"Curry rouge thaï au butternut et poulet","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Faire revenir doucement la pâte de curry dans l''huile dans un wok 1 à 2 min, jusqu''à ce qu''elle grésille et embaume.","Ajouter le lait de coco et 100 ml d''eau, porter à frémissement, ajouter la courge et laisser mijoter 10 min jusqu''à ce qu''elle soit presque tendre.","Ajouter le poulet et laisser mijoter 6 à 8 min jusqu''à ce qu''il soit cuit à cœur.","Ajouter les tomates et cuire 2 min jusqu''à ce qu''elles commencent à éclater.","Assaisonner avec la sauce de poisson petit à petit et le jus d''un demi-citron vert, puis parsemer de basilic thaï. Servir avec le riz et le reste du citron vert."]},"it":{"title":"Curry rosso thai con zucca butternut e pollo","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Soffriggere dolcemente la pasta di curry nell''olio in un wok per 1-2 min finché sfrigola e profuma.","Unire il latte di cocco e 100 ml d''acqua, portare a sobbollire, aggiungere la zucca e cuocere 10 min finché è quasi tenera.","Aggiungere il pollo e cuocere 6-8 min finché è cotto all''interno.","Aggiungere i pomodorini e cuocere 2 min finché iniziano a spaccarsi.","Condire con la salsa di pesce poco alla volta e il succo di mezzo lime, poi cospargere di basilico thai. Servire con il riso e il resto del lime."]}}'::jsonb),
  ('3f39c7bd-f6c1-4ad1-86e9-0d865aaf83f2'::uuid, '{"fr":{"title":"Gai yang (poulet grillé thaï) et salade de concombre","steps":["Râper très finement la citronnelle et l''ail (ou les mixer au mixeur plongeant) et les mélanger avec les tiges de coriandre hachées, 1,5 c. à soupe de sauce de poisson, les deux sauces soja, 1,5 c. à soupe de sucre, l''huile et beaucoup de poivre noir.","Enrober le poulet de marinade, couvrir et réfrigérer au moins 3 h (idéalement une nuit).","Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Chauffer une poêle-gril ou une poêle antiadhésive (ou un barbecue), ajouter le poulet et baisser à feu moyen ; cuire 5 à 6 min par face jusqu''à ce qu''il soit caramélisé sur les bords et cuit à cœur. Laisser reposer 3 min.","Pendant ce temps, mélanger le concombre et l''échalote avec le jus du citron vert, le reste de la sauce de poisson et du sucre, et du piment selon le goût.","Trancher le poulet et servir avec le riz et la salade de concombre, parsemé de cacahuètes et de feuilles de coriandre."]},"it":{"title":"Gai yang (pollo alla griglia thai) con insalata di cetrioli","steps":["Grattugiare finissimi citronella e aglio (o frullarli con il minipimer) e mescolarli con i gambi di coriandolo tritati, 1,5 cucchiai di salsa di pesce, le due salse di soia, 1,5 cucchiai di zucchero, l''olio e molto pepe nero.","Ricoprire il pollo con la marinata, coprire e lasciare in frigo almeno 3 h (meglio tutta la notte).","Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare bene una bistecchiera o una padella antiaderente (o il barbecue), aggiungere il pollo e abbassare a fuoco medio; cuocere 5-6 min per lato finché è abbrustolito ai bordi e cotto all''interno. Lasciarlo riposare 3 min.","Nel frattempo condire cetriolo e scalogno con il succo del lime, la salsa di pesce e lo zucchero rimasti e peperoncino a piacere.","Affettare il pollo e servirlo con il riso e l''insalata di cetrioli, cosparso di arachidi e foglie di coriandolo."]}}'::jsonb),
  ('6b6848a2-12e1-4dde-a6cb-7291243dbc57'::uuid, '{"fr":{"title":"Bún chả (porc grillé et vermicelles de Hanoï)","steps":["Mélanger l''échalote, 3 gousses d''ail, la citronnelle, la sauce d''huître, 1,5 c. à soupe de sauce de poisson, 1 c. à soupe de sucre et beaucoup de poivre. En mélanger la moitié au porc haché et l''autre aux tranches de porc ; laisser mariner 30 min.","Mélanger la papaye verte et la carotte avec une pincée de sel, 1 c. à café de sucre et le vinaigre pour un pickle express.","Préparer le bouillon à tremper : dissoudre le reste du sucre dans 200 ml d''eau chaude, puis ajouter le reste de la sauce de poisson, le jus d''un citron vert, la dernière gousse d''ail et le piment.","Préchauffer le gril du four au maximum. Les mains huilées, façonner le porc haché en 10 petites galettes et les poser avec les tranches de porc sur une grille huilée au-dessus d''une plaque.","Faire griller 10 à 12 min en retournant une fois, jusqu''à ce que la viande soit caramélisée sur les bords et cuite à cœur.","Pendant ce temps, cuire les vermicelles 3 à 4 min dans l''eau bouillante (ou selon le paquet), les rincer à l''eau froide et les égoutter.","Mettre le porc grillé et la papaye et la carotte marinées dans des bols de bouillon tiède et servir avec les vermicelles, la salade, les herbes et le demi-citron vert restant ; tremper le tout dans le bouillon en mangeant."]},"it":{"title":"Bún chả (maiale grigliato e vermicelli di Hanoi)","steps":["Mescolare scalogno, 3 spicchi d''aglio, citronella, salsa d''ostrica, 1,5 cucchiai di salsa di pesce, 1 cucchiaio di zucchero e molto pepe. Unirne metà al maiale macinato e metà alle fette di maiale; marinare 30 min.","Mescolare la papaya verde e la carota con un pizzico di sale, 1 cucchiaino di zucchero e l''aceto per un sottaceto veloce.","Preparare il brodo per intingere: sciogliere lo zucchero rimasto in 200 ml d''acqua calda, poi aggiungere la salsa di pesce rimasta, il succo di 1 lime, l''ultimo spicchio d''aglio e il peperoncino.","Scaldare il grill del forno al massimo. Con le mani unte formare con il maiale macinato 10 piccole polpette piatte e disporle con le fette di maiale su una griglia unta sopra una teglia.","Grigliare 10-12 min girando una volta, finché la carne è abbrustolita ai bordi e cotta all''interno.","Nel frattempo cuocere i vermicelli in acqua bollente 3-4 min (o secondo la confezione), sciacquarli in acqua fredda e scolarli.","Mettere il maiale grigliato e la papaya e la carota sottaceto in ciotole di brodo tiepido e servire con vermicelli, lattuga, erbe e il mezzo lime rimasto; intingere tutto nel brodo mangiando."]}}'::jsonb),
  ('b5fa3fe8-d226-4eda-88a3-7ea404bc6380'::uuid, '{"fr":{"title":"Bò lúc lắc (bœuf sauté vietnamien)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Pendant la cuisson du riz, mélanger le bœuf avec l''ail, la sauce d''huître, les deux sauces soja, la sauce de poisson, le sucre, la fécule et ½ c. à café de poivre noir ; laisser reposer 15 min.","Disposer la salade, les tomates et l''oignon rouge émincé sur deux assiettes. Mélanger le jus du citron vert avec une bonne pincée de sel et de poivre pour la sauce.","Chauffer l''huile dans un wok à feu vif jusqu''à ce qu''elle fume. Ajouter le bœuf en une couche, laisser dorer 1 min, puis secouer et faire sauter 2 à 3 min jusqu''à ce qu''il soit saisi de tous côtés.","Ajouter le beurre, les carrés d''oignon et l''oignon nouveau et faire sauter encore 1 à 2 min, jusqu''à ce que l''oignon soit juste attendri et le bœuf encore rosé à cœur.","Déposer le bœuf sur la salade et servir avec le riz et la sauce citron vert-poivre."]},"it":{"title":"Bò lúc lắc (manzo saltato vietnamita)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mentre cuoce il riso, mescolare il manzo con aglio, salsa d''ostrica, le due salse di soia, salsa di pesce, zucchero, amido e mezzo cucchiaino di pepe nero; lasciar riposare 15 min.","Disporre lattuga, pomodorini e cipolla rossa affettata su due piatti. Mescolare il succo del lime con un buon pizzico di sale e di pepe per la salsina.","Scaldare l''olio nel wok a fuoco vivo finché fuma. Aggiungere il manzo in un solo strato, lasciarlo rosolare 1 min, poi scuotere e saltare 2-3 min finché è scottato su tutti i lati.","Aggiungere il burro, i quadrati di cipolla e il cipollotto e saltare ancora 1-2 min, finché la cipolla è appena morbida e il manzo ancora rosa all''interno.","Disporre il manzo sull''insalata e servire con il riso e la salsina di lime e pepe."]}}'::jsonb),
  ('09155c6a-9a2d-49d0-beb9-32ed4b7d3e9e'::uuid, '{"fr":{"title":"Gado-gado aux œufs et au tofu","steps":["Mettre les pommes de terre et les œufs dans une casserole d''eau froide salée, porter à ébullition et cuire 9 min. Sortir les œufs et les plonger dans l''eau froide.","Ajouter les haricots verts aux pommes de terre et cuire encore 4 min, jusqu''à ce que tout soit juste tendre. Les sortir à l''écumoire.","Plonger le chou et les germes de soja 1 min dans la même eau, puis égoutter et presser pour retirer l''excès d''eau.","Chauffer l''huile dans une poêle et faire dorer le tofu 2 à 3 min de chaque côté à feu moyen-vif. L''égoutter sur du papier absorbant.","Essuyer la poêle, puis faire mijoter le beurre de cacahuète, le lait de coco, 80 ml d''eau, l''ail, la pâte de curry, le kecap manis et le sel 4 à 5 min en remuant, jusqu''à ce que la sauce nappe la cuillère. Ajouter le jus d''un demi-citron vert et le piment, et détendre avec un peu d''eau si besoin.","Écaler les œufs et les couper en deux. Disposer pommes de terre, haricots, chou, germes, concombre, tofu et œufs sur deux assiettes.","Napper de sauce aux cacahuètes tiède, parsemer de cacahuètes et servir avec le reste du citron vert en quartiers."]},"it":{"title":"Gado-gado con uova e tofu","steps":["Mettere le patate e le uova in una pentola di acqua fredda salata, portare a bollore e cuocere 9 min. Trasferire le uova in acqua fredda.","Aggiungere i fagiolini alle patate e cuocere altri 4 min, finché sono appena teneri. Scolarli con una schiumarola.","Tuffare il cavolo e i germogli di soia nella stessa acqua per 1 min, poi scolarli e strizzarli.","Scaldare l''olio in una padella e rosolare il tofu 2-3 min per lato a fuoco medio-alto finché è dorato. Scolarlo su carta assorbente.","Pulire la padella e cuocere a fuoco basso il burro di arachidi, il latte di cocco, 80 ml d''acqua, l''aglio, la pasta di curry, il kecap manis e il sale per 4-5 min mescolando, finché vela il cucchiaio. Aggiungere il succo di mezzo lime e il peperoncino, e allungare con acqua se serve.","Sgusciare le uova e tagliarle a metà. Disporre patate, fagiolini, cavolo, germogli, cetriolo, tofu e uova su due piatti.","Condire con la salsa di arachidi tiepida, cospargere di arachidi e servire con il resto del lime a spicchi."]}}'::jsonb),
  ('24a6e5dd-6a48-4027-bef7-93b4fbe4694a'::uuid, '{"fr":{"title":"Nouilles de Singapour","steps":["Faire tremper les vermicelles de riz 3 à 4 min dans de l''eau tout juste bouillante (ou selon le paquet), égoutter et rincer à l''eau froide.","Mélanger la sauce soja, le vin de Shaoxing, le curry, le sucre et une bonne pincée de poivre dans un bol.","Chauffer 1 c. à café d''huile dans un wok à feu moyen-vif, verser les œufs et faire une omelette fine. Une fois prise, la rouler, la couper en lanières et réserver.","Ajouter 1 c. à soupe d''huile et faire sauter les crevettes 1 à 2 min jusqu''à ce qu''elles soient juste roses. Réserver avec l''omelette.","Ajouter le reste de l''huile et faire sauter l''oignon, l''ail et le gingembre 1 à 2 min, puis le poivron 1 min.","Ajouter les nouilles et la sauce et mélanger à la pince 1 à 2 min jusqu''à ce qu''elles soient uniformément jaunes.","Ajouter le char siu avec les crevettes et l''omelette avec les germes de soja et l''oignon nouveau, faire sauter 1 min et servir aussitôt."]},"it":{"title":"Noodles di Singapore","steps":["Ammollare i vermicelli di riso 3-4 min in acqua appena bollita (o come indicato sulla confezione), scolarli e sciacquarli sotto l''acqua fredda.","Mescolare la salsa di soia, il vino Shaoxing, il curry, lo zucchero e un buon pizzico di pepe in una ciotolina.","Scaldare 1 cucchiaino d''olio nel wok a fuoco medio-alto, versare le uova e farne una frittatina sottile. Quando è rappresa, arrotolarla, tagliarla a striscioline e tenerla da parte.","Aggiungere 1 cucchiaio d''olio e saltare i gamberi 1-2 min finché diventano appena rosa. Tenere da parte con la frittatina.","Aggiungere l''olio rimasto e saltare cipolla, aglio e zenzero 1-2 min, poi il peperone 1 min.","Aggiungere i noodles e la salsa e mescolare con le pinze 1-2 min finché sono uniformemente gialli.","Aggiungere il char siu con gamberi e frittatina con i germogli di soia e il cipollotto, saltare 1 min e servire subito."]}}'::jsonb),
  ('903e26bc-8498-48e9-9a80-8ea3175bd84c'::uuid, '{"fr":{"title":"Tofu au gochujang, riz au sésame et concombre","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert avec 200 ml d''eau et une pincée de sel 15 min à feu doux ; laisser reposer 10 min hors du feu.","Couper le concombre en deux dans la longueur et l''émincer finement. Le mélanger avec 1 c. à soupe de vinaigre, le sucre et une pincée de sel et laisser mariner.","Fouetter le gochujang, la sauce soja, le miel, la c. à soupe de vinaigre restante, 2 c. à café d''huile de sésame, l''ail, le gingembre et 2 c. à soupe d''eau.","Sécher le tofu et l''enrober de fécule. Le faire dorer dans l''huile végétale à feu moyen-vif 8 à 10 min en le retournant, jusqu''à ce qu''il soit croustillant de tous côtés.","Baisser le feu, verser la sauce et mélanger 1 à 2 min jusqu''à ce qu''elle bouillonne et enrobe le tofu d''un glaçage collant.","Mélanger à la fourchette le reste d''huile de sésame et les graines de sésame dans le riz.","Servir le riz garni de tofu et de concombre égoutté, parsemé d''oignon nouveau."]},"it":{"title":"Tofu al gochujang con riso al sesamo e cetriolo","steps":["Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto con 200 ml d''acqua e un pizzico di sale per 15 min a fuoco basso; lasciarlo riposare 10 min fuori dal fuoco.","Tagliare il cetriolo a metà per il lungo e affettarlo sottile. Condirlo con 1 cucchiaio di aceto, lo zucchero e un pizzico di sale e lasciarlo marinare.","Sbattere il gochujang, la salsa di soia, il miele, il cucchiaio di aceto rimasto, 2 cucchiaini di olio di sesamo, l''aglio, lo zenzero e 2 cucchiai d''acqua.","Asciugare il tofu e passarlo nell''amido. Rosolarlo nell''olio di semi a fuoco medio-alto per 8-10 min, girandolo, finché è croccante e dorato su tutti i lati.","Abbassare il fuoco, versare la salsa e mescolare 1-2 min finché sobbolle e avvolge il tofu in una glassa appiccicosa.","Incorporare con una forchetta l''olio di sesamo rimasto e i semi di sesamo nel riso.","Servire il riso con sopra il tofu e il cetriolo scolato, cosparso di cipollotto."]}}'::jsonb),
  ('e4fbec5b-2877-472e-b90f-9cce17e906d4'::uuid, '{"fr":{"title":"Riz sauté au kimchi, thon, champignons et œuf","steps":["Cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux. L''étaler sur une assiette pour qu''il refroidisse et sèche un peu (le riz de la veille est encore mieux).","Chauffer 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif et faire revenir l''oignon et les champignons 4 à 5 min jusqu''à ce que les champignons soient dorés.","Ajouter le kimchi, le gochugaru, le gochujang et le sucre et faire sauter 3 min jusqu''à ce que le kimchi ramollisse et sente le grillé.","Ajouter le riz et le jus de kimchi et faire sauter 3 à 4 min en pressant le riz contre la poêle pour qu''il colore.","Incorporer le thon, la moitié de l''oignon nouveau et l''huile de sésame et réchauffer 1 min. Répartir dans deux bols.","Cuire les œufs au plat dans le reste de l''huile 2 à 3 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Garnir chaque bol d''un œuf au plat, du reste d''oignon nouveau et des graines de sésame."]},"it":{"title":"Riso saltato al kimchi con tonno, funghi e uovo","steps":["Cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso. Stenderlo su un piatto perché si raffreddi e si asciughi un po'' (il riso del giorno prima è ancora meglio).","Scaldare 1 cucchiaio d''olio in una padella larga a fuoco medio-alto e rosolare la cipolla e i funghi 4-5 min finché i funghi sono dorati.","Aggiungere il kimchi, il gochugaru, il gochujang e lo zucchero e saltare 3 min finché il kimchi si ammorbidisce e profuma di tostato.","Aggiungere il riso e il succo del kimchi e saltare 3-4 min, premendo il riso contro la padella perché prenda colore.","Incorporare il tonno, metà del cipollotto e l''olio di sesamo e scaldare 1 min. Dividere in due ciotole.","Friggere le uova nell''olio rimasto 2-3 min, finché l''albume è rappreso ma il tuorlo ancora morbido.","Completare ogni ciotola con un uovo, il resto del cipollotto e i semi di sesamo."]}}'::jsonb),
  ('18d7da88-e0e2-45d7-9951-6b9728624038'::uuid, '{"fr":{"title":"Japchae","steps":["Mélanger la sauce soja, le sucre, l''huile de sésame, l''ail et beaucoup de poivre. Enrober le bœuf de 1,5 c. à soupe de cette sauce, puis de fécule, et laisser reposer pendant la préparation.","Cuire les nouilles 6 à 7 min dans l''eau bouillante (ou selon le paquet) jusqu''à ce qu''elles soient souples et élastiques. Égoutter, rincer à l''eau froide et les raccourcir aux ciseaux.","Battre les œufs avec une pincée de sel et les cuire en omelette fine dans le wok légèrement huilé à feu moyen, 1 min de chaque côté. La rouler et la couper en fines lanières.","Chauffer 1 c. à café d''huile dans le wok à feu vif et saisir le bœuf en une seule couche, 1 à 2 min de chaque côté, jusqu''à ce qu''il soit doré. Le mettre dans un grand saladier.","Ajouter 1 c. à soupe d''huile et faire revenir les champignons 4 min jusqu''à ce qu''ils soient dorés et secs ; les ajouter au saladier.","Ajouter le reste de l''huile et faire sauter la carotte, l''oignon et l''oignon nouveau avec une pincée de sel 3 min, jusqu''à ce qu''ils soient juste tendres ; les ajouter au saladier.","Faire tomber les épinards 1 min dans le wok chaud, puis les ajouter au saladier avec les nouilles.","Verser le reste de la sauce, ajouter les lanières d''omelette et le sésame et mélanger à la main ou à la pince jusqu''à ce que les nouilles soient brillantes. Servir tiède."]},"it":{"title":"Japchae","steps":["Mescolare la salsa di soia, lo zucchero, l''olio di sesamo, l''aglio e abbondante pepe. Condire il manzo con 1,5 cucchiai di questa salsa, poi con l''amido, e lasciarlo riposare durante la preparazione.","Cuocere i noodles in acqua bollente per 6-7 min (o come indicato sulla confezione) finché sono morbidi ed elastici. Scolarli, sciacquarli in acqua fredda e accorciarli con le forbici.","Sbattere le uova con un pizzico di sale e cuocerle in una frittatina sottile nel wok leggermente unto a fuoco medio, 1 min per lato. Arrotolarla e tagliarla a striscioline.","Scaldare 1 cucchiaino d''olio nel wok a fuoco alto e scottare il manzo in un solo strato, 1-2 min per lato, finché è rosolato. Trasferirlo in una ciotola grande.","Aggiungere 1 cucchiaio d''olio e rosolare i funghi 4 min finché sono dorati e asciutti; unirli alla ciotola.","Aggiungere l''olio rimasto e saltare carota, cipolla e cipollotto con un pizzico di sale per 3 min, finché sono appena teneri; unirli alla ciotola.","Far appassire gli spinaci nel wok caldo per 1 min, poi unirli alla ciotola con i noodles.","Versare la salsa rimasta, aggiungere le striscioline di frittata e il sesamo e mescolare con le mani o le pinze finché i noodles sono lucidi. Servire tiepido."]}}'::jsonb),
  ('a5433dcb-2462-4141-a7c2-64971329e1d1'::uuid, '{"fr":{"title":"Kimchi jjigae","steps":["Cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux, puis le laisser reposer hors du feu.","Mettre la poitrine de porc dans une cocotte à feu moyen et la faire revenir 4 à 5 min en remuant, jusqu''à ce qu''elle rende un peu de gras et dore sur les bords.","Ajouter l''oignon, l''ail, le gingembre et le kimchi et faire sauter 4 min jusqu''à ce que le kimchi soit tendre et parfumé.","Incorporer le gochugaru, le gochujang, le sucre, la sauce soja, le jus de kimchi et 500 ml d''eau. Porter à ébullition, puis laisser mijoter 15 min à couvert partiel.","Poser le tofu dessus, l''arroser d''un peu de bouillon et mijoter encore 5 min, jusqu''à ce que le porc soit tendre et le tofu bien chaud. Goûter et rectifier en sel ou en gochugaru.","Parsemer d''oignon nouveau, arroser d''huile de sésame et servir bouillonnant dans la cocotte, avec le riz."]},"it":{"title":"Kimchi jjigae","steps":["Cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Mettere la pancia di maiale in una pentola dal fondo spesso a fuoco medio e rosolarla 4-5 min mescolando, finché rilascia un po'' di grasso e si colora ai bordi.","Aggiungere cipolla, aglio, zenzero e kimchi e saltare 4 min finché il kimchi è morbido e profumato.","Unire il gochugaru, il gochujang, lo zucchero, la salsa di soia, il succo del kimchi e 500 ml d''acqua. Portare a bollore, poi cuocere a fuoco basso 15 min con il coperchio socchiuso.","Adagiare sopra il tofu, bagnarlo con un po'' di brodo e cuocere altri 5 min, finché il maiale è tenero e il tofu ben caldo. Assaggiare e regolare di sale o gochugaru.","Cospargere di cipollotto, irrorare con l''olio di sesamo e servire fumante nella pentola, con il riso."]}}'::jsonb),
  ('b5aa2a92-5715-4729-9059-11df4a1ed144'::uuid, '{"fr":{"title":"Jeyuk bokkeum","steps":["Mélanger le gochujang, le gochugaru, la sauce soja, le vinaigre, le sucre, le miel, l''huile de sésame, l''ail et le gingembre jusqu''à ce que le sucre soit dissous.","Mélanger le porc, l''oignon et l''oignon nouveau avec la marinade en massant bien. Couvrir et réserver 30 min au frais (jusqu''à quelques heures).","Pendant ce temps, cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux, puis le laisser reposer hors du feu.","Chauffer l''huile dans une grande poêle ou un wok à feu vif jusqu''à ce qu''elle frémisse.","Faire sauter le porc en deux fois, 3 à 4 min chaque fois, jusqu''à ce qu''il soit cuit et caramélisé sur les bords ; ne pas surcharger la poêle sinon il bout.","Parsemer de sésame et servir avec le riz et des feuilles de laitue pour faire des wraps."]},"it":{"title":"Jeyuk bokkeum","steps":["Mescolare il gochujang, il gochugaru, la salsa di soia, l''aceto, lo zucchero, il miele, l''olio di sesamo, l''aglio e lo zenzero finché lo zucchero si scioglie.","Condire il maiale, la cipolla e il cipollotto con la marinata, massaggiando bene. Coprire e lasciare in frigo 30 min (fino a qualche ora).","Nel frattempo cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Scaldare l''olio in una padella larga o nel wok a fuoco alto finché è ben caldo.","Saltare il maiale in due volte, 3-4 min ciascuna, finché è cotto e caramellato ai bordi; non riempire troppo la padella o il maiale lessa.","Cospargere di sesamo e servire con il riso e foglie di lattuga per avvolgere."]}}'::jsonb),
  ('bb35f3c2-7532-45fa-a110-e430a3f4f1c5'::uuid, '{"fr":{"title":"Andong jjimdak","steps":["Faire tremper les nouilles de patate douce environ 30 min dans de l''eau tiède, pendant la préparation et la cuisson, jusqu''à ce qu''elles soient souples.","Mélanger la sauce soja, le sucre, la sauce d''huître, l''huile de sésame, l''ail et le gingembre dans un bol.","Chauffer l''huile dans une sauteuse à feu moyen-vif et faire dorer le poulet 5 min en le retournant.","Verser la sauce, 450 ml d''eau et le piment, porter à ébullition et cuire 8 min à bon frémissement.","Ajouter la pomme de terre, la carotte et l''oignon et laisser mijoter 12 min en remuant de temps en temps, jusqu''à ce que la pomme de terre soit tendre et la sauce réduite d''environ un tiers.","Égoutter les nouilles et les ajouter avec l''oignon nouveau. Cuire 4 à 5 min jusqu''à ce que les nouilles soient brillantes, translucides et aient absorbé un peu de sauce.","Parsemer de sésame et servir aussitôt."]},"it":{"title":"Andong jjimdak","steps":["Ammollare i noodles di patata dolce in acqua tiepida per circa 30 min, durante la preparazione e la cottura, finché sono morbidi.","Mescolare la salsa di soia, lo zucchero, la salsa di ostriche, l''olio di sesamo, l''aglio e lo zenzero in una ciotola.","Scaldare l''olio in una pentola larga a fuoco medio-alto e rosolare il pollo 5 min, girandolo.","Versare la salsa, 450 ml d''acqua e il peperoncino, portare a bollore e cuocere 8 min a sobbollore vivace.","Aggiungere la patata, la carota e la cipolla e cuocere 12 min mescolando ogni tanto, finché la patata è tenera e la salsa si è ridotta di circa un terzo.","Scolare i noodles e unirli con il cipollotto. Cuocere 4-5 min finché i noodles sono lucidi, trasparenti e hanno assorbito un po'' di salsa.","Cospargere di sesamo e servire subito."]}}'::jsonb),
  ('6bc515fb-1db9-4a26-a278-d6dea10855c3'::uuid, '{"fr":{"title":"Fajitas au poulet et aux poivrons","steps":["Mélanger 2 c. à café d''huile avec l''ail, le zeste de citron vert, la moitié du jus, le cumin, l''origan, le piment en poudre, le paprika fumé et 1/2 c. à café de sel. Enrober le poulet et laisser mariner 30 min (ou jusqu''à un jour au frais).","Chauffer le reste de l''huile dans une grande poêle épaisse à feu moyen-vif. Ajouter les poivrons, l''oignon, le sucre et une pincée de sel et cuire 6 à 8 min en remuant, jusqu''à ce qu''ils soient tendres et grillés par endroits.","Verser 3 c. à soupe d''eau pour décoller les sucs, laisser évaporer, puis réserver les légumes sur une assiette.","Cuire le poulet dans la même poêle bien chaude 3 à 4 min de chaque côté, jusqu''à ce qu''il soit bien doré et cuit à cœur. Laisser reposer 3 min, l''émincer et arroser du reste de jus de citron vert.","Réchauffer les tortillas 20 secondes de chaque côté dans une poêle sèche, ou emballées dans du papier aluminium au four doux.","Remettre les poivrons dans la poêle avec le poulet 1 min pour les réchauffer et servir avec les tortillas, le yaourt, l''avocat et la coriandre."]},"it":{"title":"Fajitas di pollo e peperoni","steps":["Mescolare 2 cucchiaini d''olio con l''aglio, la scorza di lime, metà del succo, il cumino, l''origano, il peperoncino in polvere, la paprika affumicata e 1/2 cucchiaino di sale. Condire il pollo e lasciarlo marinare 30 min (o fino a un giorno in frigo).","Scaldare l''olio rimasto in una padella larga dal fondo spesso a fuoco medio-alto. Aggiungere i peperoni, la cipolla, lo zucchero e un pizzico di sale e cuocere 6-8 min mescolando, finché sono morbidi e abbrustoliti qua e là.","Versare 3 cucchiai d''acqua per staccare il fondo, lasciarla evaporare, poi trasferire le verdure su un piatto.","Cuocere il pollo nella stessa padella ben calda 3-4 min per lato finché è ben rosolato e cotto all''interno. Lasciarlo riposare 3 min, tagliarlo a strisce e irrorarlo con il succo di lime rimasto.","Scaldare le tortillas in una padella asciutta 20 secondi per lato, oppure avvolte nell''alluminio in forno basso.","Rimettere i peperoni nella padella con il pollo per 1 min e servire con le tortillas, lo yogurt, l''avocado e il coriandolo."]}}'::jsonb),
  ('2484fa78-780d-4b2b-9a12-2d64bc9f6410'::uuid, '{"fr":{"title":"Chili aux haricots noirs et patate douce","steps":["Chauffer l''huile dans une grande cocotte à feu moyen et faire fondre l''oignon 6 à 7 min.","Ajouter la patate douce, l''ail, le piment en poudre, le cumin, le paprika fumé et l''origan et remuer 2 min jusqu''à ce que les épices sentent le grillé.","Ajouter les haricots noirs, les tomates et le bouillon et porter à ébullition.","Couvrir, baisser le feu et laisser mijoter 18 à 20 min en remuant de temps en temps, jusqu''à ce que la patate douce soit tendre. Découvrir les 5 dernières minutes pour un chili plus épais.","Saler et ajouter le jus d''un demi-citron vert ; écraser quelques haricots contre la paroi pour épaissir.","Servir garni de yaourt, d''avocat, de coriandre et du reste du citron vert en quartiers."]},"it":{"title":"Chili di fagioli neri e patate dolci","steps":["Scaldare l''olio in una pentola capiente a fuoco medio e far appassire la cipolla 6-7 min.","Aggiungere la patata dolce, l''aglio, il peperoncino in polvere, il cumino, la paprika affumicata e l''origano e mescolare 2 min finché le spezie profumano di tostato.","Aggiungere i fagioli neri, i pomodori e il brodo e portare a bollore.","Coprire, abbassare il fuoco e cuocere 18-20 min mescolando ogni tanto, finché la patata dolce è tenera. Scoprire negli ultimi 5 min per un chili più denso.","Salare e aggiungere il succo di mezzo lime; schiacciare qualche fagiolo contro la pentola per addensare.","Servire con lo yogurt, l''avocado, il coriandolo e il resto del lime a spicchi."]}}'::jsonb),
  ('dbb3e9ce-6c2a-4fd6-855e-868e35eb2ecb'::uuid, '{"fr":{"title":"Quesadillas aux haricots noirs et poivron","steps":["Chauffer l''huile dans une grande poêle à feu moyen et cuire le poivron et l''oignon 5 min jusqu''à ce qu''ils soient tendres.","Ajouter les haricots, le maïs, le cumin et le piment et cuire 3 min en écrasant légèrement un tiers des haricots, jusqu''à ce que le liquide soit évaporé. Assaisonner et ajouter l''oignon nouveau. Verser dans un bol et essuyer la poêle.","Mélanger la tomate avec un filet de citron vert, une pincée de sel et la coriandre pour une salsa rapide.","Parsemer un quart du fromage sur une moitié de chaque tortilla, répartir la garniture aux haricots et finir avec le reste du fromage. Replier et presser légèrement.","Cuire les quesadillas deux par deux dans la poêle sèche à feu moyen-doux, 2 à 3 min de chaque côté, jusqu''à ce qu''elles soient dorées et le fromage fondu.","Couper en parts et servir avec la salsa, le yaourt et des quartiers de citron vert."]},"it":{"title":"Quesadillas di fagioli neri e peperoni","steps":["Scaldare l''olio in una padella larga a fuoco medio e cuocere il peperone e la cipolla 5 min finché sono morbidi.","Aggiungere i fagioli, il mais, il cumino e il peperoncino e cuocere 3 min schiacciando leggermente un terzo dei fagioli, finché l''umidità è evaporata. Regolare di sale e unire il cipollotto. Trasferire in una ciotola e pulire la padella.","Mescolare il pomodoro con un po'' di succo di lime, un pizzico di sale e il coriandolo per una salsa veloce.","Distribuire un quarto del formaggio su metà di ogni tortilla, aggiungere il ripieno di fagioli e finire con il formaggio rimasto. Ripiegare e premere leggermente.","Cuocere le quesadillas due alla volta nella padella asciutta a fuoco medio-basso, 2-3 min per lato, finché sono dorate e il formaggio è fuso.","Tagliare a spicchi e servire con la salsa, lo yogurt e spicchi di lime."]}}'::jsonb),
  ('e65fe071-853c-4a03-a5e5-5f8a90979328'::uuid, '{"fr":{"title":"Tacos de crevettes fumés, chou et avocat","steps":["Mélanger les crevettes avec le paprika fumé, le cumin, le piment en poudre, l''origan, l''ail, la moitié de l''huile et une pincée de sel.","Mélanger le chou avec le jus d''un citron vert et une pincée de sel juste avant de garnir, pour qu''il reste croquant.","Mélanger le yaourt avec la sauce piquante et un filet de citron vert.","Réchauffer les tortillas dans une poêle sèche, 20 secondes de chaque côté, et les garder enveloppées dans un torchon.","Chauffer le reste de l''huile dans la poêle à feu vif et cuire les crevettes 1 à 2 min de chaque côté, jusqu''à ce qu''elles soient roses et légèrement grillées.","Garnir les tortillas de chou, de crevettes et d''avocat, napper de yaourt fumé et finir avec la coriandre et des quartiers de citron vert."]},"it":{"title":"Tacos di gamberi affumicati con cavolo e avocado","steps":["Condire i gamberi con la paprika affumicata, il cumino, il peperoncino in polvere, l''origano, l''aglio, metà dell''olio e un pizzico di sale.","Condire il cavolo con il succo di un lime e un pizzico di sale appena prima di farcire, perché resti croccante.","Mescolare lo yogurt con la salsa piccante e un po'' di succo di lime.","Scaldare le tortillas in una padella asciutta, 20 secondi per lato, e tenerle avvolte in un canovaccio.","Scaldare l''olio rimasto nella padella a fuoco alto e cuocere i gamberi 1-2 min per lato finché sono rosa e leggermente abbrustoliti.","Farcire le tortillas con cavolo, gamberi e avocado, condire con lo yogurt affumicato e finire con coriandolo e spicchi di lime."]}}'::jsonb),
  ('d2793b68-f90b-4f5f-9649-da6b652d910a'::uuid, '{"fr":{"title":"Burgers de patate douce et haricots noirs","steps":["Préchauffer le four à 200 °C. Piquer la patate douce de tous côtés et la cuire au micro-ondes à puissance maximale 7 à 8 min en la retournant une fois, jusqu''à ce qu''elle soit très tendre (une patate douce cuite la veille convient aussi).","Pendant ce temps, cuire le quinoa dans 100 ml d''eau à couvert 15 min, jusqu''à absorption ; laisser refroidir.","Récupérer la chair de la patate douce dans un saladier et l''écraser. Ajouter les haricots et en écraser la moitié à la fourchette.","Incorporer le quinoa, l''œuf, la chapelure, l''oignon nouveau, le cumin, le paprika fumé, le sel et le poivre. Le mélange doit se tenir ; ajouter un peu de chapelure s''il est trop humide.","Former 2 grands ou 4 petits steaks d''environ 2 cm d''épaisseur sur une plaque chemisée et huilée et badigeonner le dessus d''huile.","Cuire 20 min en les retournant délicatement une fois après 12 min, jusqu''à ce qu''ils soient fermes et dorés. Laisser reposer 5 min pour qu''ils se raffermissent.","Mélanger le yaourt avec un filet de citron vert et une pincée de sel.","Garnir les pains grillés de salade, des steaks, de tomate, d''avocat et du yaourt au citron vert."]},"it":{"title":"Burger di patate dolci e fagioli neri","steps":["Scaldare il forno a 200 °C. Bucherellare la patata dolce e cuocerla nel microonde alla massima potenza per 7-8 min, girandola una volta, finché è morbidissima (va bene anche una patata dolce avanzata già cotta).","Nel frattempo cuocere la quinoa in 100 ml d''acqua, coperta, per 15 min finché l''acqua è assorbita; lasciarla raffreddare.","Raccogliere la polpa della patata dolce in una ciotola e schiacciarla. Aggiungere i fagioli e schiacciarne metà con una forchetta.","Incorporare la quinoa, l''uovo, il pangrattato, il cipollotto, il cumino, la paprika affumicata, sale e pepe. L''impasto deve stare insieme; aggiungere un po'' di pangrattato se è troppo umido.","Formare 2 burger grandi o 4 piccoli spessi circa 2 cm su una teglia foderata e unta e spennellarli d''olio.","Cuocere 20 min girandoli con delicatezza una volta dopo 12 min, finché sono sodi e dorati. Lasciarli riposare 5 min perché si rassodino.","Mescolare lo yogurt con un po'' di succo di lime e un pizzico di sale.","Farcire i panini tostati con lattuga, burger, pomodoro, avocado e yogurt al lime."]}}'::jsonb),
  ('1ce30af4-0557-44c0-90a7-943b7db38432'::uuid, '{"fr":{"title":"Enchiladas au poulet et poivrons rôtis","steps":["Préchauffer le four à 200 °C. Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire l''oignon 3 min jusqu''à ce qu''il commence à fondre.","Ajouter le poulet avec une pincée de sel et cuire 5 à 6 min en remuant, jusqu''à ce qu''il soit légèrement doré et cuit à cœur. Incorporer les poivrons grillés et verser le tout dans un saladier.","Dans la même poêle, faire revenir l''ail, le cumin, le piment et l''origan 1 min. Ajouter les tomates et le bouillon et laisser mijoter 8 min jusqu''à ce que la sauce épaississe un peu ; assaisonner.","Mélanger 4 c. à soupe de sauce avec le poulet et les poivrons.","Étaler quelques cuillerées de sauce dans un plat à gratin. Garnir chaque tortilla du mélange au poulet, la rouler serré et la poser jointure en dessous dans le plat.","Verser le reste de la sauce et parsemer de cheddar.","Enfourner 12 à 15 min jusqu''à ce que le fromage soit fondu et la sauce bouillonne sur les bords. Servir avec l''oignon nouveau et le yaourt ou la crème aigre."]},"it":{"title":"Enchiladas di pollo e peperoni arrosto","steps":["Scaldare il forno a 200 °C. Scaldare l''olio in una padella larga a fuoco medio-alto e cuocere la cipolla 3 min finché inizia ad ammorbidirsi.","Aggiungere il pollo con un pizzico di sale e cuocerlo 5-6 min mescolando, finché è leggermente rosolato e cotto. Unire i peperoni arrosto e trasferire tutto in una ciotola.","Nella stessa padella soffriggere l''aglio, il cumino, il peperoncino e l''origano 1 min. Aggiungere i pomodori e il brodo e cuocere 8 min finché la salsa si addensa un po''; regolare di sale.","Mescolare 4 cucchiai di salsa con il pollo e i peperoni.","Stendere qualche cucchiaio di salsa in una pirofila. Farcire ogni tortilla con il pollo, arrotolarla stretta e disporla in pirofila con la chiusura sotto.","Versare sopra la salsa rimasta e cospargere di cheddar.","Infornare 12-15 min finché il formaggio è fuso e la salsa sobbolle ai bordi. Servire con cipollotto e yogurt o panna acida."]}}'::jsonb),
  ('458a777c-279e-44f9-b835-9a4c4c9a99a5'::uuid, '{"fr":{"title":"Burritos à la courge rôtie et aux haricots noirs","steps":["Préchauffer le four à 200 °C. Mélanger la courge et l''oignon rouge avec 1 c. à soupe d''huile, la moitié du cumin, le paprika fumé, le piment et du sel et les rôtir sur une plaque 20 min.","Pendant ce temps, cuire le riz dans 160 ml d''eau salée à couvert 12 min ; laisser reposer 5 min puis l''égrener avec un filet de citron vert et la coriandre.","Mélanger les haricots avec l''ail, le reste du cumin et de l''huile, les ajouter sur la plaque et rôtir encore 8 à 10 min, jusqu''à ce que la courge soit tendre et caramélisée. Écraser légèrement les haricots à la fourchette et arroser d''un peu de citron vert.","Réchauffer les tortillas enveloppées de papier aluminium dans le four les 3 dernières minutes.","Au centre de chaque tortilla, superposer riz, haricots, courge, épinards, feta et une cuillerée de yaourt.","Rabattre les côtés et rouler serré. Couper en deux et servir avec le reste du yaourt."]},"it":{"title":"Burritos di zucca arrosto e fagioli neri","steps":["Scaldare il forno a 200 °C. Condire la zucca e la cipolla rossa con 1 cucchiaio d''olio, metà del cumino, la paprika affumicata, il peperoncino e sale e arrostirle su una teglia per 20 min.","Nel frattempo cuocere il riso in 160 ml d''acqua salata, coperto, per 12 min; lasciarlo riposare 5 min, poi sgranarlo con un po'' di succo di lime e il coriandolo.","Condire i fagioli con l''aglio, il resto del cumino e dell''olio, unirli sulla teglia e arrostire altri 8-10 min, finché la zucca è tenera e caramellata. Schiacciare leggermente i fagioli con una forchetta e irrorarli con un po'' di lime.","Scaldare le tortillas avvolte nell''alluminio in forno negli ultimi 3 min.","Al centro di ogni tortilla stendere riso, fagioli, zucca, spinaci, feta e un cucchiaio di yogurt.","Ripiegare i lati e arrotolare stretto. Tagliare a metà e servire con lo yogurt rimasto."]}}'::jsonb),
  ('8af92bc9-e7f4-4b51-b5c5-f3e158947f63'::uuid, '{"fr":{"title":"Bowls burrito au bœuf et aux haricots noirs","steps":["Cuire le riz dans 280 ml d''eau salée à couvert 12 min ; laisser reposer 5 min, puis l''égrener à la fourchette avec le jus d''un citron vert et la moitié de la coriandre.","Pendant ce temps, chauffer l''huile dans une poêle à feu moyen et faire fondre l''oignon 4 min.","Monter le feu, ajouter le bœuf et le faire dorer 5 à 6 min en l''émiettant, jusqu''à ce qu''il ne soit plus rose.","Ajouter l''ail, les épices et le concentré de tomate 1 min, puis 60 ml d''eau et laisser mijoter 2 à 3 min jusqu''à obtenir une viande nappée. Assaisonner.","Mélanger les haricots, le maïs et la tomate avec le jus d''un demi-citron vert et une pincée de sel.","Répartir le riz dans deux bols et garnir de bœuf, de salsa aux haricots, de salade et d''avocat.","Finir avec le cheddar, une cuillerée de yaourt, le reste de la coriandre et des quartiers de citron vert."]},"it":{"title":"Burrito bowl di manzo e fagioli neri","steps":["Cuocere il riso in 280 ml d''acqua salata, coperto, per 12 min; lasciarlo riposare 5 min, poi sgranarlo con il succo di un lime e metà del coriandolo.","Nel frattempo scaldare l''olio in una padella a fuoco medio e far appassire la cipolla 4 min.","Alzare il fuoco, aggiungere il manzo e rosolarlo 5-6 min sgranandolo, finché non è più rosa.","Unire l''aglio, le spezie e il concentrato di pomodoro per 1 min, poi 60 ml d''acqua e cuocere 2-3 min finché è ben condito. Regolare di sale.","Mescolare i fagioli, il mais e il pomodoro con il succo di mezzo lime e un pizzico di sale.","Dividere il riso in due ciotole e completare con il manzo, la salsa di fagioli, la lattuga e l''avocado.","Finire con il cheddar, un cucchiaio di yogurt, il coriandolo rimasto e spicchi di lime."]}}'::jsonb),
  ('1c8911ac-cb21-4de7-afe8-c3501009222f'::uuid, '{"fr":{"title":"Lomo saltado","steps":["Cuire les frites au air fryer à 200 °C 15 à 18 min en les secouant à mi-cuisson, jusqu''à ce qu''elles soient croustillantes.","Pendant ce temps, cuire le riz dans 240 ml d''eau salée à couvert 12 min, puis le laisser reposer hors du feu.","Mélanger le bœuf avec le cumin, la moitié du vinaigre, la moitié de la sauce soja, du poivre et une pincée de sel ; laisser 10 min.","Chauffer 1 c. à soupe d''huile dans un wok à feu très vif. Égoutter le bœuf et le saisir en deux fois, 2 min par fournée, jusqu''à ce qu''il soit doré dehors et rosé dedans. Réserver.","Ajouter le reste de l''huile et faire sauter l''oignon, l''ail et la pâte d''ají amarillo 1 min, en gardant l''oignon croquant.","Ajouter les tomates, le reste du vinaigre et de la sauce soja et le bouillon et faire sauter 30 secondes, juste jusqu''à ce que les tomates commencent à ramollir.","Remettre le bœuf avec son jus, ajouter les frites et mélanger 15 secondes. Parsemer de persil et servir aussitôt avec le riz."]},"it":{"title":"Lomo saltado","steps":["Cuocere le patatine nella friggitrice ad aria a 200 °C per 15-18 min, scuotendole a metà, finché sono croccanti.","Nel frattempo cuocere il riso in 240 ml d''acqua salata, coperto, per 12 min, poi lasciarlo riposare fuori dal fuoco.","Condire il manzo con il cumino, metà dell''aceto, metà della salsa di soia, pepe e un pizzico di sale; lasciarlo 10 min.","Scaldare 1 cucchiaio d''olio nel wok a fuoco vivissimo. Scolare il manzo dalla marinata e scottarlo in due volte, 2 min per volta, finché è rosolato fuori e rosato dentro. Tenerlo da parte.","Aggiungere l''olio rimasto e saltare cipolla, aglio e pasta di ají amarillo 1 min, lasciando la cipolla croccante.","Aggiungere i pomodori, il resto dell''aceto e della salsa di soia e il brodo e saltare 30 secondi, finché i pomodori iniziano appena ad ammorbidirsi.","Rimettere il manzo con il suo sugo, aggiungere le patatine e mescolare 15 secondi. Cospargere di prezzemolo e servire subito con il riso."]}}'::jsonb),
  ('40812162-f84f-4848-8ce1-d2dcbc36e3ee'::uuid, '{"fr":{"title":"Ropa vieja","steps":["Saler et poivrer le bœuf.","Chauffer l''huile dans une cocotte à feu moyen et faire fondre l''oignon et les poivrons 4 min. Réserver un tiers des poivrons pour la fin.","Ajouter l''ail, l''origan, le cumin, le paprika et le laurier 1 min, puis verser le vin et laisser bouillonner 1 min.","Ajouter le coulis de tomate et le bouillon, enfoncer le bœuf pour qu''il soit couvert et porter à frémissement.","Couvrir en laissant le couvercle entrouvert et laisser mijoter très doucement 2 heures, en ajoutant un peu d''eau si besoin, jusqu''à ce que le bœuf s''effiloche facilement.","Sortir le bœuf, retirer le laurier et effilocher la viande en fins filaments avec deux fourchettes.","Remettre le bœuf dans la cocotte avec les poivrons réservés, les olives et le vinaigre et laisser mijoter 15 min à découvert jusqu''à ce que la sauce enrobe la viande. Rectifier l''assaisonnement.","Environ 20 min avant la fin, cuire le riz dans 280 ml d''eau salée à couvert 12 min, laisser reposer 5 min et servir avec la ropa vieja."]},"it":{"title":"Ropa vieja","steps":["Salare e pepare il manzo.","Scaldare l''olio in una pentola dal fondo spesso a fuoco medio e far appassire la cipolla e i peperoni 4 min. Tenere da parte un terzo dei peperoni per la fine.","Unire l''aglio, l''origano, il cumino, la paprika e l''alloro per 1 min, poi versare il vino e farlo sobbollire 1 min.","Aggiungere la passata e il brodo, immergere il manzo in modo che sia coperto e portare a sobbollore.","Coprire lasciando il coperchio socchiuso e cuocere a fuoco dolcissimo per 2 ore, aggiungendo un goccio d''acqua se serve, finché il manzo si sfilaccia facilmente.","Togliere il manzo, eliminare l''alloro e sfilacciare la carne a fili sottili con due forchette.","Rimettere il manzo nella pentola con i peperoni tenuti da parte, le olive e l''aceto e cuocere scoperto 15 min finché la salsa avvolge la carne. Regolare di sale e pepe.","Circa 20 min prima della fine, cuocere il riso in 280 ml d''acqua salata, coperto, per 12 min, lasciarlo riposare 5 min e servirlo con la ropa vieja."]}}'::jsonb),
  ('0d15fc3d-576a-46cd-a6a3-ff2552e7beea'::uuid, '{"fr":{"title":"Tacos de carnitas","steps":["Préchauffer le four à 150 °C. Retirer le gras épais du porc en laissant une fine couche.","Mettre le porc dans une cocotte allant au four avec le zeste et le jus d''orange, le jus d''un citron vert, le laurier, le cumin, l''origan, l''ail, les morceaux d''oignon, 1 c. à café de sel, du poivre et 400 ml d''eau.","Porter à frémissement sur le feu, couvrir et braiser au four 2 heures jusqu''à ce que le porc soit très tendre.","Sortir le porc sur une plaque chemisée. Faire bouillir le jus de cuisson à découvert 8 à 10 min jusqu''à ce qu''il soit réduit à quelques cuillerées sirupeuses.","Effilocher le porc en gros morceaux, le mélanger avec le jus réduit et l''étaler sur la plaque.","Passer le four en position gril et griller le porc à 10-15 cm de la résistance 5 à 8 min en le retournant une fois, jusqu''à ce qu''il soit croustillant sur les bords. Surveiller de près.","Réchauffer les tortillas dans une poêle sèche et les garnir de carnitas, d''oignon haché, d''avocat et de coriandre. Servir avec des quartiers de citron vert et de la sauce piquante."]},"it":{"title":"Tacos di carnitas","steps":["Scaldare il forno a 150 °C. Eliminare il grasso spesso dal maiale lasciandone uno strato sottile.","Mettere il maiale in una pentola con coperchio adatta al forno con la scorza e il succo d''arancia, il succo di un lime, l''alloro, il cumino, l''origano, l''aglio, i pezzi di cipolla, 1 cucchiaino di sale, pepe e 400 ml d''acqua.","Portare a sobbollore sul fuoco, coprire e brasare in forno per 2 ore finché il maiale è tenerissimo.","Trasferire il maiale su una teglia foderata. Far bollire vivacemente il liquido di cottura, scoperto, per 8-10 min finché si riduce a pochi cucchiai sciropposi.","Sfilacciare il maiale a pezzi grossi, condirlo con il liquido ridotto e stenderlo sulla teglia.","Passare il forno in modalità grill e grigliare il maiale a 10-15 cm dalla resistenza per 5-8 min, girandolo una volta, finché è croccante ai bordi. Sorvegliarlo da vicino.","Scaldare le tortillas in una padella asciutta e farcirle con le carnitas, la cipolla tritata, l''avocado e il coriandolo. Servire con spicchi di lime e salsa piccante."]}}'::jsonb),
  ('96b56819-e22c-40cb-a356-bfd932ee56c1'::uuid, '{"fr":{"title":"Sopa de tortilla au poulet","steps":["Griller les piments guajillo dans une grande casserole sèche à feu moyen, 30 à 60 secondes de chaque côté, jusqu''à ce qu''ils embaument sans brûler. Les mettre dans un bol, les couvrir de 250 ml d''eau tout juste bouillante et les laisser tremper 10 min jusqu''à ce qu''ils soient souples.","Pendant ce temps, préchauffer le four à 200 °C. Mélanger les lanières de tortilla avec un peu d''huile et une pincée de sel et les cuire sur une plaque 8 à 10 min en les remuant une fois, jusqu''à ce qu''elles soient dorées et croustillantes ; ajouter les lanières de pasilla les 1 à 2 dernières minutes.","Mixer les guajillos avec leur eau de trempage, les tomates, l''oignon, l''ail et une pincée de sel jusqu''à obtenir une purée bien lisse.","Chauffer l''huile dans la casserole à feu moyen-vif, verser la purée (elle éclabousse) et cuire 8 min en remuant, jusqu''à ce qu''elle soit épaisse et plus foncée.","Ajouter le bouillon et le brin de persil, porter à frémissement, ajouter le poulet et le pocher doucement 15 min jusqu''à cuisson complète.","Sortir le poulet, l''effilocher et le remettre dans la soupe. Retirer le persil et assaisonner avec du sel et un filet de citron vert.","Mettre les lanières de tortilla dans les bols, verser la soupe et garnir d''avocat, de queso fresco, de crème fraîche, de lanières de pasilla, de coriandre et de quartiers de citron vert."]},"it":{"title":"Sopa de tortilla con pollo","steps":["Tostare i peperoncini guajillo in una pentola capiente asciutta a fuoco medio, 30-60 secondi per lato, finché profumano senza bruciare. Metterli in una ciotola, coprirli con 250 ml d''acqua appena bollita e lasciarli in ammollo 10 min finché sono morbidi.","Nel frattempo scaldare il forno a 200 °C. Condire le strisce di tortilla con un filo d''olio e un pizzico di sale e cuocerle su una teglia 8-10 min, scuotendole una volta, finché sono dorate e croccanti; aggiungere le strisce di pasilla negli ultimi 1-2 min.","Frullare i guajillo con l''acqua dell''ammollo, i pomodori, la cipolla, l''aglio e un pizzico di sale fino a ottenere una purea liscia.","Scaldare l''olio nella pentola a fuoco medio-alto, versare la purea (schizza) e cuocerla 8 min mescolando, finché è densa e più scura.","Aggiungere il brodo e il rametto di prezzemolo, portare a sobbollore, unire il pollo e cuocerlo dolcemente 15 min finché è cotto.","Togliere il pollo, sfilacciarlo e rimetterlo nella zuppa. Eliminare il prezzemolo e regolare con sale e un po'' di succo di lime.","Mettere le strisce di tortilla nelle ciotole, versare la zuppa e completare con avocado, queso fresco, crème fraîche, strisce di pasilla, coriandolo e spicchi di lime."]}}'::jsonb),
  ('117b8579-55c5-4e44-8073-d822afcd3fca'::uuid, '{"fr":{"title":"Ceviche à la patate douce","steps":["Cuire les rondelles de patate douce 12 à 15 min dans de l''eau salée, juste tendres. Égoutter et laisser refroidir complètement au frais.","Faire tremper l''oignon émincé 10 min dans de l''eau glacée, puis bien égoutter.","Préparer le leche de tigre : râper l''ail et le gingembre, hacher finement le céleri et les tiges de coriandre, et les mélanger au jus de citron vert avec 1 c. à café de sel et 2 c. à soupe d''eau froide. Laisser 5 min, puis filtrer.","Couper le poisson en cubes de 2 cm et le mettre dans un saladier froid. Saler légèrement et ajouter la pâte d''ají amarillo.","Verser le leche de tigre sur le poisson et mélanger. Laisser 3 à 5 min, jusqu''à ce que l''extérieur des cubes devienne opaque.","Incorporer l''oignon et les feuilles de coriandre. Goûter et rectifier en sel ou en citron vert.","Servir aussitôt avec le jus, la patate douce froide et le maïs à côté."]},"it":{"title":"Ceviche con patata dolce","steps":["Lessare le rondelle di patata dolce in acqua salata per 12-15 min, finché sono appena tenere. Scolarle e farle raffreddare completamente in frigo.","Mettere in ammollo la cipolla affettata in acqua ghiacciata per 10 min, poi scolarla bene.","Preparare la leche de tigre: grattugiare l''aglio e lo zenzero, tritare finemente il sedano e i gambi di coriandolo e mescolarli al succo di lime con 1 cucchiaino di sale e 2 cucchiai di acqua fredda. Lasciare 5 min, poi filtrare.","Tagliare il pesce a cubetti di 2 cm e metterlo in una ciotola fredda. Salare leggermente e unire la pasta di ají amarillo.","Versare la leche de tigre sul pesce e mescolare. Lasciare 3-5 min, finché l''esterno dei cubetti diventa opaco.","Unire la cipolla e le foglie di coriandolo. Assaggiare e regolare di sale o lime.","Servire subito con il suo succo, la patata dolce fredda e il mais a parte."]}}'::jsonb),
  ('674abcb4-f1db-4f7d-b760-966a0e335502'::uuid, '{"fr":{"title":"Steak au chimichurri et pommes de terre","steps":["Préparer le chimichurri : mélanger le persil haché au couteau, l''ail, l''origan, le piment, 1,5 c. à soupe de vinaigre et 3 c. à soupe d''huile avec sel et poivre. Laisser reposer au moins 20 min.","Sortir le steak du réfrigérateur 30 min avant la cuisson, l''éponger et bien le saler.","Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres. Égoutter et laisser sécher à la vapeur.","Faire dorer les pommes de terre dans une poêle avec 1 c. à soupe d''huile à feu moyen-vif, 8 min, en les retournant. Garder au chaud.","Essuyer la poêle et la chauffer jusqu''à ce qu''elle fume. Saisir le steak 3 à 4 min de chaque côté pour une cuisson saignante (52-55 °C à cœur). Laisser reposer 5 à 10 min.","Trancher les tomates et l''oignon, assaisonner avec du sel, le reste du vinaigre et un filet d''huile.","Trancher le steak contre le fil, napper de chimichurri et servir avec les pommes de terre et la salade de tomates."]},"it":{"title":"Bistecca al chimichurri con patate","steps":["Preparare il chimichurri: mescolare il prezzemolo tritato a coltello, l''aglio, l''origano, il peperoncino, 1,5 cucchiai di aceto e 3 cucchiai d''olio con sale e pepe. Lasciare riposare almeno 20 min.","Togliere la bistecca dal frigo 30 min prima della cottura, asciugarla e salarla bene.","Lessare le patate in acqua salata per 15 min, finché sono tenere. Scolarle e lasciarle asciugare.","Rosolare le patate in padella con 1 cucchiaio d''olio a fuoco medio-alto per 8 min, girandole. Tenerle in caldo.","Pulire la padella e scaldarla finché fuma. Scottare la bistecca 3-4 min per lato per una cottura al sangue (52-55 °C al cuore). Lasciarla riposare 5-10 min.","Affettare i pomodori e la cipolla e condirli con sale, il resto dell''aceto e un filo d''olio.","Tagliare la bistecca contro fibra, condirla con il chimichurri e servirla con le patate e l''insalata di pomodori."]}}'::jsonb),
  ('8660ca5e-d5ae-4f8c-8013-fc19defba212'::uuid, '{"fr":{"title":"Picadillo cubain et riz","steps":["Rincer le riz, le mettre dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min. Laisser reposer 5 min hors du feu.","Pendant ce temps, faire revenir l''oignon et le poivron dans 1 c. à soupe d''huile à feu moyen 5 min. Ajouter l''ail 1 min.","Ajouter le bœuf et l''émietter. Cuire 5 min jusqu''à ce qu''il ne soit plus rosé.","Ajouter le cumin, l''origan et le laurier, verser le vin et laisser bouillonner 1 min.","Ajouter le coulis de tomate et les raisins secs et laisser mijoter 10 min à découvert, en remuant de temps en temps, jusqu''à ce que ce soit épais.","Incorporer les olives, les câpres et le vinaigre, puis saler et poivrer.","Servir le picadillo sur le riz."]},"it":{"title":"Picadillo cubano con riso","steps":["Sciacquare il riso, metterlo in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min. Lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo, appassire la cipolla e il peperone in 1 cucchiaio d''olio a fuoco medio per 5 min. Aggiungere l''aglio per 1 min.","Aggiungere la carne e sgranarla. Cuocere 5 min finché non è più rosa.","Unire il cumino, l''origano e l''alloro, versare il vino e lasciarlo sfumare 1 min.","Aggiungere la passata e l''uvetta e cuocere scoperto 10 min, mescolando ogni tanto, finché si addensa.","Unire le olive, i capperi e l''aceto, e regolare di sale e pepe.","Servire il picadillo sul riso."]}}'::jsonb),
  ('a3d15426-1a21-4284-8cf5-5d39c27353d5'::uuid, '{"fr":{"title":"Chowder de haddock fumé et maïs","steps":["Faire fondre le beurre dans une casserole et faire suer l''oignon, le céleri et la pomme de terre à feu doux 10 min, sans coloration.","Verser le bouillon et le lait et porter à petits frémissements. Cuire 15 min, jusqu''à ce que la pomme de terre soit tendre, sans faire bouillir fort.","Écraser quelques morceaux de pomme de terre contre la paroi pour épaissir la soupe.","Ajouter le maïs, poser le haddock dessus et le pocher très doucement 5 min, jusqu''à ce qu''il s''effeuille.","Défaire le poisson en gros morceaux et poivrer. Goûter avant de saler, le poisson fumé est déjà salé.","Servir dans des bols, parsemé de persil, avec du pain croustillant à côté."]},"it":{"title":"Chowder di eglefino affumicato e mais","steps":["Sciogliere il burro in una pentola e stufare cipolla, sedano e patata a fuoco basso per 10 min senza farli colorire.","Versare il brodo e il latte e portare a un leggero bollore. Cuocere 15 min finché la patata è tenera, senza far bollire forte.","Schiacciare qualche pezzo di patata contro la parete della pentola per addensare la zuppa.","Aggiungere il mais, adagiare sopra l''eglefino e farlo cuocere molto dolcemente per 5 min, finché si sfalda.","Spezzare il pesce in grosse scaglie e pepare. Assaggiare prima di salare, perché il pesce affumicato è già sapido.","Servire nelle ciotole con il prezzemolo e pane croccante a parte."]}}'::jsonb),
  ('f9ed364b-8350-45b8-ac5b-aca582be6f94'::uuid, '{"fr":{"title":"Croquettes de saumon, petits pois et yaourt citronné","steps":["Cuire les pommes de terre 12 à 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres. Égoutter, laisser sécher 2 min, puis écraser grossièrement.","Pendant ce temps, pocher le saumon dans une poêle d''eau à peine frémissante 6 à 8 min, juste cuit. Égoutter et effeuiller.","Mélanger la purée, le saumon, le zeste de citron, les oignons nouveaux, la moitié de l''aneth, sel et poivre. Former 4 galettes d''environ 3 cm d''épaisseur et les réfrigérer 15 min.","Fariner les galettes, les tremper dans l''œuf, puis les enrober de chapelure.","Essuyer la poêle, chauffer l''huile à feu moyen et cuire les croquettes 4 min de chaque côté, jusqu''à ce qu''elles soient dorées et chaudes à cœur.","Cuire les petits pois 3 min dans de l''eau bouillante, égoutter et assaisonner.","Mélanger le yaourt avec 1 c. à soupe de jus de citron, le reste de l''aneth et une pincée de sel.","Servir les croquettes avec les petits pois, le yaourt citronné et des quartiers de citron."]},"it":{"title":"Polpette di salmone con piselli e yogurt al limone","steps":["Lessare le patate in acqua salata per 12-15 min finché sono tenere. Scolarle, lasciarle asciugare 2 min e schiacciarle grossolanamente.","Nel frattempo cuocere il salmone in una padella d''acqua appena sobbollente per 6-8 min, finché è appena cotto. Scolarlo e sfaldarlo.","Mescolare le patate, il salmone, la scorza di limone, i cipollotti, metà dell''aneto, sale e pepe. Formare 4 tortini spessi circa 3 cm e farli riposare in frigo 15 min.","Infarinare i tortini, passarli nell''uovo e poi nel pangrattato.","Pulire la padella, scaldare l''olio a fuoco medio e cuocere i tortini 4 min per lato, finché sono dorati e caldi all''interno.","Cuocere i piselli in acqua bollente per 3 min, scolarli e condirli.","Mescolare lo yogurt con 1 cucchiaio di succo di limone, il resto dell''aneto e un pizzico di sale.","Servire i tortini con i piselli, lo yogurt al limone e spicchi di limone."]}}'::jsonb),
  ('b76ef299-3036-48ea-94ff-e8d5f575d475'::uuid, '{"fr":{"title":"Saucisses et légumes racines rôtis à la plaque","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante) avec une grande plaque à l''intérieur.","Mélanger les panais, les carottes, les pommes de terre et l''oignon avec l''huile, le thym, le sel et le poivre.","Les étaler sur la plaque chaude en une seule couche, glisser les saucisses entre eux et rôtir 15 min.","Tout retourner et rôtir encore 10 min.","Mélanger le miel et la moutarde, en enrober les saucisses et les panais et rôtir encore 5 min, jusqu''à ce que ce soit caramélisé et que les saucisses soient cuites à cœur."]},"it":{"title":"Salsicce e ortaggi a radice in teglia","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato) con una grande teglia all''interno.","Condire pastinache, carote, patate e cipolla con l''olio, il timo, sale e pepe.","Stenderle sulla teglia calda in un solo strato, sistemare le salsicce in mezzo e arrostire 15 min.","Girare tutto e arrostire altri 10 min.","Mescolare il miele e la senape, versarli sulle salsicce e sulle pastinache e arrostire altri 5 min, finché sono glassate e le salsicce cotte all''interno."]}}'::jsonb),
  ('080fcab4-3b09-4071-8cc8-d2871c61b0c3'::uuid, '{"fr":{"title":"Fish pie au cabillaud et pommes de terre","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante). Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres.","Pendant ce temps, mettre le cabillaud et le haddock dans une casserole avec 350 ml de lait et le laurier. Porter juste à frémissement et pocher 4 min. Retirer le poisson et verser le lait dans un pichet.","Faire fondre 20 g de beurre dans la même casserole, ajouter la farine 1 min, puis incorporer peu à peu le lait de pochage au fouet. Laisser épaissir 3 à 4 min à feu doux ; ajouter la moutarde, le persil et du poivre.","Effeuiller le poisson en gros morceaux dans un plat à four, répartir les crevettes et napper de sauce.","Égoutter les pommes de terre et les écraser en purée avec le reste du beurre et du lait. Assaisonner.","Étaler la purée sur la garniture, la strier à la fourchette et parsemer de cheddar.","Enfourner 25 à 30 min, jusqu''à ce que ce soit doré et que ça bouillonne sur les bords."]},"it":{"title":"Fish pie di merluzzo e patate","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato). Lessare le patate in acqua salata per 15 min finché sono tenere.","Nel frattempo mettere il merluzzo e l''eglefino in una pentola con 350 ml di latte e l''alloro. Portare appena a bollore e cuocere 4 min. Togliere il pesce e versare il latte in una caraffa.","Sciogliere 20 g di burro nella stessa pentola, unire la farina per 1 min, poi aggiungere il latte poco alla volta mescolando con la frusta. Cuocere 3-4 min finché si addensa; aggiungere la senape, il prezzemolo e il pepe.","Sfaldare il pesce a grossi pezzi in una pirofila, distribuire i gamberi e versare sopra la salsa.","Scolare le patate e schiacciarle con il burro e il latte rimasti. Regolare di sale.","Stendere il purè sul ripieno, rigarlo con una forchetta e cospargere di cheddar.","Infornare 25-30 min, finché è dorato e bolle ai bordi."]}}'::jsonb),
  ('7e540a97-e2de-41ac-a97e-3781fce9f828'::uuid, '{"fr":{"title":"Tourte feuilletée à la dinde et aux poireaux","steps":["Faire dorer la dinde dans l''huile dans une sauteuse à feu vif 4 min. La réserver sur une assiette.","Faire fondre le beurre dans la même sauteuse et cuire les poireaux à feu moyen-doux 8 min, jusqu''à ce qu''ils soient fondants.","Ajouter la farine 1 min, puis verser le bouillon petit à petit et laisser épaissir 3 min. Incorporer la crème fraîche, la moutarde, le thym et la dinde ; assaisonner. Laisser tiédir 10 min.","Préchauffer le four à 200 °C (180 °C chaleur tournante).","Verser la garniture dans un petit plat à tourte, couvrir de pâte, souder les bords et percer une petite cheminée. Badigeonner d''œuf.","Enfourner 25 min, jusqu''à ce que la pâte soit gonflée et bien dorée. Laisser reposer 5 min avant de servir."]},"it":{"title":"Torta salata di sfoglia con tacchino e porri","steps":["Rosolare il tacchino nell''olio in una padella larga a fuoco alto per 4 min. Toglierlo e tenerlo da parte.","Sciogliere il burro nella stessa padella e cuocere i porri a fuoco medio-basso per 8 min finché sono morbidi.","Unire la farina per 1 min, poi aggiungere il brodo poco alla volta e cuocere 3 min finché si addensa. Unire la crème fraîche, la senape, il timo e il tacchino; regolare di sale e pepe. Lasciare intiepidire 10 min.","Preriscaldare il forno a 200 °C (180 °C ventilato).","Versare il ripieno in una piccola teglia, coprire con la sfoglia, sigillare i bordi e praticare un piccolo foro. Spennellare con l''uovo.","Infornare 25 min, finché la sfoglia è gonfia e ben dorata. Lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('f2838b36-f8a4-4800-b348-062ecb0ab0b0'::uuid, '{"fr":{"title":"Macaroni aux quatre fromages et brocoli au four","steps":["Cuire les macaroni dans de l''eau bouillante salée 1 min de moins que l''indication du paquet, en ajoutant le brocoli les 3 dernières minutes. Égoutter et allumer le gril du four à puissance maximale.","Faire fondre le beurre dans la même casserole, ajouter la farine 1 min, puis incorporer le lait peu à peu au fouet. Cuire 5 min en remuant, jusqu''à ce que la sauce nappe la cuillère.","Hors du feu, incorporer le cheddar, l''emmental, la moitié du parmesan, la moutarde et la muscade. Assaisonner.","Remettre les pâtes et le brocoli dans la casserole, bien mélanger, verser dans un plat à four et parsemer de mozzarella.","Mélanger la chapelure avec le reste du parmesan, en parsemer le plat et passer 5 à 6 min sous le gril, jusqu''à ce que ce soit doré et bouillonnant."]},"it":{"title":"Maccheroni ai quattro formaggi e broccoli al forno","steps":["Cuocere i maccheroni in acqua bollente salata 1 min meno di quanto indicato sulla confezione, aggiungendo i broccoli negli ultimi 3 min. Scolare e accendere il grill del forno al massimo.","Sciogliere il burro nella stessa pentola, unire la farina per 1 min, poi aggiungere il latte poco alla volta mescolando con la frusta. Cuocere 5 min, mescolando, finché vela il cucchiaio.","Fuori dal fuoco, unire il cheddar, l''emmental, metà del parmigiano, la senape e la noce moscata. Regolare di sale e pepe.","Rimettere la pasta e i broccoli nella pentola, mescolare bene, versare in una pirofila e distribuire la mozzarella.","Mescolare il pangrattato con il parmigiano rimasto, cospargerlo sopra e gratinare sotto il grill 5-6 min, finché è dorato e bolle."]}}'::jsonb),
  ('0932be9e-079a-4987-8170-c331087fb0a7'::uuid, '{"fr":{"title":"Merlu poêlé, écrasé de petits pois à la menthe","steps":["Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les petits pois les 3 dernières minutes.","Égoutter, puis écraser avec le beurre, le lait chaud, la menthe, sel et poivre, en gardant un peu de texture. Garder au chaud.","Éponger le merlu, inciser légèrement la peau et assaisonner des deux côtés.","Chauffer l''huile dans une poêle à feu moyen-vif. Cuire le merlu côté peau 4 min, jusqu''à ce qu''elle soit croustillante, puis le retourner et cuire 2 à 3 min, juste nacré à cœur.","Servir le poisson sur l''écrasé avec un filet de citron."]},"it":{"title":"Nasello in padella con purè di piselli e menta","steps":["Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo i piselli negli ultimi 3 min.","Scolare, poi schiacciare con il burro, il latte caldo, la menta, sale e pepe, lasciando un po'' di consistenza. Tenere in caldo.","Asciugare il nasello, incidere leggermente la pelle e condire da entrambi i lati.","Scaldare l''olio in padella a fuoco medio-alto. Cuocere il nasello dalla parte della pelle per 4 min finché è croccante, poi girarlo e cuocere 2-3 min, finché è appena opaco al centro.","Servire il pesce sul purè con una spruzzata di limone."]}}'::jsonb),
  ('052505d0-dfea-4d39-abe9-1eb80426e276'::uuid, '{"fr":{"title":"Pommes de terre en robe des champs au thon et maïs","steps":["Piquer les pommes de terre de partout, les frotter d''un peu d''huile et de sel et les cuire au micro-ondes à puissance maximale 6 min. Les retourner et cuire encore 5 à 7 min, jusqu''à ce qu''un couteau s''enfonce facilement.","Pendant ce temps, allumer le gril du four à puissance maximale et mélanger le thon, le maïs, le yaourt, la mayonnaise, les oignons nouveaux, le jus de citron et du poivre.","Passer les pommes de terre 5 min sous le gril pour rendre la peau croustillante.","Les fendre, aérer la chair à la fourchette et garnir du mélange au thon.","Parsemer de cheddar et passer 2 min sous le gril pour le faire fondre. Servir avec de la salade."]},"it":{"title":"Patate al cartoccio con tonno e mais","steps":["Bucherellare le patate, strofinarle con un filo d''olio e sale e cuocerle al microonde alla massima potenza per 6 min. Girarle e cuocere altri 5-7 min, finché un coltello entra facilmente.","Nel frattempo accendere il grill del forno al massimo e mescolare il tonno, il mais, lo yogurt, la maionese, i cipollotti, il succo di limone e il pepe.","Mettere le patate sotto il grill per 5 min per rendere la buccia croccante.","Aprirle, smuovere la polpa con una forchetta e farcirle con il composto di tonno.","Cospargere di cheddar e passare 2 min sotto il grill finché fonde. Servire con insalata."]}}'::jsonb),
  ('86ac5a18-9832-4b71-b7a5-72f531f53ddf'::uuid, '{"fr":{"title":"Côtelettes d''agneau, écrasé de petits pois et pommes de terre","steps":["Frotter les côtelettes avec l''ail, le romarin, 1 c. à soupe d''huile et du poivre. Laisser 20 min à température ambiante.","Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les petits pois les 3 dernières minutes.","Égoutter, puis écraser grossièrement pommes de terre et petits pois avec le beurre, 1 c. à soupe d''huile, la menthe, le zeste de citron et du sel. Garder au chaud.","Saler les côtelettes. Chauffer une poêle à feu vif et poser les côtelettes debout sur leur gras 2 min pour le faire fondre.","Les coucher et cuire 3 min de chaque côté pour une viande rosée. Laisser reposer 5 min.","Servir les côtelettes sur l''écrasé avec des quartiers de citron."]},"it":{"title":"Costolette d''agnello con piselli e patate schiacciati","steps":["Massaggiare le costolette con l''aglio, il rosmarino, 1 cucchiaio d''olio e il pepe. Lasciarle 20 min a temperatura ambiente.","Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo i piselli negli ultimi 3 min.","Scolare, poi schiacciare grossolanamente patate e piselli con il burro, 1 cucchiaio d''olio, la menta, la scorza di limone e il sale. Tenere in caldo.","Salare le costolette. Scaldare una padella a fuoco alto e appoggiare le costolette sul lato del grasso per 2 min per farlo sciogliere.","Adagiarle di piatto e cuocere 3 min per lato per una carne rosata. Lasciarle riposare 5 min.","Servire le costolette sui piselli e patate schiacciati con spicchi di limone."]}}'::jsonb),
  ('5d85fa6b-aadc-4188-ac08-ae090e153778'::uuid, '{"fr":{"title":"Tourte aux champignons et aux châtaignes","steps":["Faire tremper les cèpes séchés dans 250 ml d''eau chaude 15 min.","Pendant ce temps, faire fondre l''oignon dans l''huile dans une sauteuse à feu moyen 10 min.","Monter le feu, ajouter les champignons frais et les faire sauter 4 à 5 min, jusqu''à ce qu''ils soient dorés.","Égoutter les cèpes en gardant leur eau, et les ajouter dans la sauteuse avec les châtaignes et le thym. Bien assaisonner.","Verser le cidre et 150 ml de l''eau des cèpes, porter à ébullition et laisser mijoter doucement 15 min, jusqu''à ce que ça réduise. Incorporer la crème, retirer du feu et laisser tiédir 15 min.","Préchauffer le four à 200 °C (180 °C chaleur tournante). Répartir la garniture dans 2 petits plats à tourte, badigeonner les bords de jaune d''œuf, poser la pâte dessus et souder. Dorer au jaune et réfrigérer 5 min.","Enfourner 15 à 20 min, jusqu''à ce que la pâte soit gonflée et dorée."]},"it":{"title":"Pasticcio di funghi e castagne in sfoglia","steps":["Mettere in ammollo i porcini secchi in 250 ml di acqua calda per 15 min.","Nel frattempo appassire la cipolla nell''olio in una padella larga a fuoco medio per 10 min.","Alzare la fiamma, aggiungere i funghi freschi e saltarli 4-5 min finché sono dorati.","Scolare i porcini conservando l''acqua e aggiungerli in padella con le castagne e il timo. Regolare bene di sale e pepe.","Versare il sidro e 150 ml dell''acqua dei porcini, portare a bollore e cuocere dolcemente 15 min finché si riduce. Unire la panna, togliere dal fuoco e lasciare intiepidire 15 min.","Preriscaldare il forno a 200 °C (180 °C ventilato). Distribuire il ripieno in 2 piccole teglie, spennellare i bordi con il tuorlo, coprire con la sfoglia e sigillare. Spennellare con il tuorlo e far riposare in frigo 5 min.","Infornare 15-20 min, finché la sfoglia è gonfia e dorata."]}}'::jsonb),
  ('c6232350-6113-4114-8a14-4cdec962f675'::uuid, '{"fr":{"title":"Gratin de chou-fleur au fromage, croûte de pommes de terre","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Cuire ensemble le chou-fleur et les rondelles de pomme de terre 5 min dans de l''eau bouillante salée. Bien égoutter, mettre le chou-fleur dans un plat à four et réserver les pommes de terre.","Faire fondre le beurre dans la même casserole, ajouter la farine 1 min, puis incorporer le lait peu à peu au fouet. Cuire 4 min en remuant, jusqu''à ce que la sauce épaississe.","Hors du feu, incorporer les trois quarts du cheddar, la moutarde et la muscade. Assaisonner.","Napper le chou-fleur de sauce.","Disposer les rondelles de pomme de terre en les faisant se chevaucher, les badigeonner d''huile, assaisonner et parsemer du reste du cheddar et du parmesan.","Enfourner 20 min, jusqu''à ce que les pommes de terre soient croustillantes et dorées sur les bords. Laisser reposer 5 min avant de servir."]},"it":{"title":"Cavolfiore gratinato al formaggio con crosta di patate","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Lessare insieme il cavolfiore e le fette di patata in acqua salata per 5 min. Scolare bene, mettere il cavolfiore in una pirofila e tenere da parte le patate.","Sciogliere il burro nella stessa pentola, unire la farina per 1 min, poi aggiungere il latte poco alla volta mescolando con la frusta. Cuocere 4 min, mescolando, finché si addensa.","Fuori dal fuoco, unire tre quarti del cheddar, la senape e la noce moscata. Regolare di sale e pepe.","Versare la salsa sul cavolfiore.","Disporre sopra le fette di patata sovrapponendole, spennellarle d''olio, condire e cospargere con il cheddar rimasto e il parmigiano.","Infornare 20 min, finché le patate sono croccanti e dorate ai bordi. Lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('f445cd76-b382-4065-8f94-eb2d927749e5'::uuid, '{"fr":{"title":"Sandwichs aux boulettes de bœuf et mozzarella","steps":["Mélanger le bœuf, la chapelure, l''œuf, le parmesan, 1 gousse d''ail, l''origan, sel et poivre. Former 10 boulettes.","Faire dorer les boulettes dans l''huile dans une poêle antiadhésive à feu moyen-vif 5 min, en les retournant.","Ajouter le coulis de tomate, le reste de l''ail et le sucre. Couvrir et laisser mijoter 12 min, jusqu''à ce que les boulettes soient cuites à cœur.","Allumer le gril du four à puissance maximale. Ouvrir les pains et les griller 2 min, face coupée vers le haut.","Garnir les pains de boulettes et d''un peu de sauce, puis couvrir de mozzarella.","Passer 3 à 4 min sous le gril, jusqu''à ce que le fromage fonde et dore. Parsemer de basilic et servir avec le reste de sauce."]},"it":{"title":"Panini con polpette di manzo e mozzarella","steps":["Mescolare la carne, il pangrattato, l''uovo, il parmigiano, 1 spicchio d''aglio, l''origano, sale e pepe. Formare 10 polpette.","Rosolare le polpette nell''olio in una padella antiaderente a fuoco medio-alto per 5 min, girandole.","Aggiungere la passata, l''aglio rimasto e lo zucchero. Coprire e cuocere a fuoco lento 12 min, finché le polpette sono cotte all''interno.","Accendere il grill del forno al massimo. Aprire i panini e tostarli 2 min con il lato tagliato verso l''alto.","Farcire i panini con le polpette e un po'' di sugo e coprire con la mozzarella.","Gratinare 3-4 min finché il formaggio fonde e si dora. Completare con il basilico e servire con il sugo rimasto."]}}'::jsonb),
  ('579eee8b-5bb0-4a2d-a485-40c468fcf68e'::uuid, '{"fr":{"title":"Hachis parmentier d''agneau aux lentilles","steps":["Cuire les lentilles 15 min dans de l''eau frémissante, à mi-cuisson. Égoutter.","Faire dorer l''agneau dans une sauteuse sans matière grasse à feu vif 6 min, puis retirer l''essentiel du gras. Ajouter l''oignon et la carotte et cuire 6 min.","Ajouter l''ail, la farine et le concentré de tomate 1 min. Verser le bouillon, la sauce Worcestershire, le thym, le romarin et les lentilles, couvrir et laisser mijoter 25 min, jusqu''à ce que les lentilles soient tendres et la sauce épaisse. Assaisonner.","Pendant ce temps, cuire les pommes de terre 15 min dans de l''eau salée. Égoutter et les écraser en purée avec le beurre et le lait chaud ; assaisonner.","Préchauffer le four à 200 °C (180 °C chaleur tournante). Verser la garniture dans un plat à four, couvrir de purée et strier le dessus à la fourchette.","Enfourner 25 min, jusqu''à ce que le dessus soit doré et que ça bouillonne sur les bords."]},"it":{"title":"Shepherd''s pie di agnello e lenticchie","steps":["Cuocere le lenticchie in acqua sobbollente per 15 min, a metà cottura. Scolarle.","Rosolare l''agnello in una padella senza grassi a fuoco alto per 6 min, poi eliminare gran parte del grasso. Aggiungere la cipolla e la carota e cuocere 6 min.","Unire l''aglio, la farina e il concentrato di pomodoro per 1 min. Aggiungere il brodo, la salsa Worcestershire, il timo, il rosmarino e le lenticchie, coprire e cuocere a fuoco lento 25 min, finché le lenticchie sono tenere e il sugo denso. Regolare di sale e pepe.","Nel frattempo lessare le patate in acqua salata per 15 min. Scolarle e schiacciarle con il burro e il latte caldo; regolare di sale.","Preriscaldare il forno a 200 °C (180 °C ventilato). Versare il ripieno in una pirofila, coprire con il purè e rigare la superficie con una forchetta.","Infornare 25 min, finché la superficie è dorata e bolle ai bordi."]}}'::jsonb),
  ('547accca-910e-44d6-8b35-b5f9621f0bd1'::uuid, '{"fr":{"title":"Wraps au poulet façon César","steps":["Aplatir le poulet sur 1,5 cm d''épaisseur régulière et l''assaisonner avec l''huile, le zeste de citron, du sel et du poivre.","Le cuire dans une poêle chaude 4 à 5 min de chaque côté, jusqu''à ce qu''il soit cuit à cœur. Laisser reposer 3 min, puis trancher.","Fouetter le yaourt, la mayonnaise, l''ail, les anchois, la moutarde, la sauce Worcestershire, le jus de citron, la moitié du parmesan et beaucoup de poivre pour la sauce.","Essuyer la poêle et y réchauffer les tortillas 20 s de chaque côté.","Mélanger la salade avec presque toute la sauce. Garnir chaque tortilla de salade, de poulet, du reste de la sauce et du parmesan, rouler serré et couper en deux."]},"it":{"title":"Wrap di pollo stile Caesar","steps":["Appiattire il pollo a uno spessore uniforme di 1,5 cm e condirlo con l''olio, la scorza di limone, sale e pepe.","Cuocerlo in una padella calda per 4-5 min per lato, finché è cotto all''interno. Lasciarlo riposare 3 min, poi affettarlo.","Sbattere lo yogurt, la maionese, l''aglio, le acciughe, la senape, la salsa Worcestershire, il succo di limone, metà del parmigiano e abbondante pepe per la salsa.","Pulire la padella e scaldarvi le tortillas 20 s per lato.","Condire la lattuga con quasi tutta la salsa. Farcire ogni tortilla con lattuga, pollo, la salsa e il parmigiano rimasti, arrotolare stretto e tagliare a metà."]}}'::jsonb),
  ('18c1a899-e68c-4b75-8eb3-38adbd2e2aae'::uuid, '{"fr":{"title":"Salade de maquereau fumé, betterave et pommes de terre","steps":["Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les œufs les 8 dernières minutes. Refroidir les œufs dans de l''eau froide, puis les écaler et les couper en deux.","Mélanger la crème fraîche, le raifort, la moutarde, le jus de citron, la moitié de l''aneth, sel et poivre.","Mélanger l''oignon émincé avec le vinaigre et une pincée de sel et laisser 10 min.","Mélanger les pommes de terre tièdes avec l''oignon, son vinaigre et la moitié de la sauce.","Répartir les pommes de terre, la betterave, le maquereau et la roquette dans les assiettes, ajouter les œufs et le reste de la sauce, et parsemer du reste d''aneth."]},"it":{"title":"Insalata di sgombro affumicato, barbabietola e patate","steps":["Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo le uova negli ultimi 8 min. Raffreddare le uova in acqua fredda, poi sgusciarle e tagliarle a metà.","Mescolare la crème fraîche, il rafano, la senape, il succo di limone, metà dell''aneto, sale e pepe.","Condire la cipolla affettata con l''aceto e un pizzico di sale e lasciarla 10 min.","Condire le patate tiepide con la cipolla, il suo aceto e metà della salsa.","Disporre nei piatti le patate, la barbabietola, lo sgombro e la rucola, aggiungere le uova e il resto della salsa e completare con l''aneto rimasto."]}}'::jsonb),
  ('159dedbb-14c3-4d5a-9b03-6d4f1f6f6f3f'::uuid, '{"fr":{"title":"Escalope de poulet panée, coleslaw et potatoes","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Couper les pommes de terre en quartiers fins d''environ 1,5 cm, les mélanger avec 1 c. à soupe d''huile d''olive, le paprika et du sel sur une plaque et rôtir 30 min, en retournant une fois, jusqu''à ce qu''elles soient croustillantes.","Mélanger le chou et la carotte avec le yaourt, la mayonnaise, la moutarde, le vinaigre et du sel. Laisser ramollir.","Couper chaque blanc de poulet en deux dans l''épaisseur, puis aplatir les morceaux entre deux films à 5 mm d''épaisseur. Assaisonner.","Passer chaque morceau dans la farine, puis dans l''œuf battu, puis dans la chapelure, en l''enrobant légèrement sans appuyer.","Chauffer l''huile végétale dans une grande poêle jusqu''à ce qu''une miette grésille aussitôt (environ 170 °C). Cuire les escalopes 2 à 3 min de chaque côté, en faisant doucement tourner la poêle pour que la panure gonfle, jusqu''à ce qu''elles soient bien dorées.","Égoutter sur du papier absorbant, saler légèrement et servir avec des quartiers de citron, le coleslaw et les potatoes."]},"it":{"title":"Cotoletta di pollo con insalata di cavolo e patate a spicchi","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Tagliare le patate a spicchi sottili di circa 1,5 cm, condirle con 1 cucchiaio d''olio d''oliva, la paprika e il sale su una teglia e arrostirle 30 min, girandole una volta, finché sono croccanti.","Mescolare il cavolo e la carota con lo yogurt, la maionese, la senape, l''aceto e il sale. Lasciare ammorbidire.","Tagliare a metà ogni petto di pollo nello spessore, poi battere i pezzi tra due fogli di pellicola fino a 5 mm. Condire.","Passare ogni pezzo nella farina, poi nell''uovo sbattuto, poi nel pangrattato, ricoprendolo leggermente senza premere.","Scaldare l''olio di semi in una padella grande finché una briciola sfrigola subito (circa 170 °C). Friggere le cotolette 2-3 min per lato, muovendo delicatamente la padella perché la panatura si gonfi, finché sono ben dorate.","Scolarle su carta assorbente, salarle leggermente e servirle con spicchi di limone, l''insalata di cavolo e le patate."]}}'::jsonb),
  ('0fed55e8-6259-459c-8b4c-b64a8add53da'::uuid, '{"fr":{"title":"Saucisses au chou braisé et purée","steps":["Mettre les pommes de terre à cuire dans de l''eau salée ; il leur faut 15 à 20 min pour être tendres.","Pendant ce temps, faire dorer les saucisses dans l''huile dans une grande cocotte à feu moyen 8 min, en les retournant. Les réserver.","Mettre l''oignon dans la cocotte et le cuire 4 min jusqu''à ce qu''il soit tendre, puis ajouter le chou, le carvi et le laurier et remuer 3 min, jusqu''à ce que le chou tombe.","Verser le vin, le bouillon et le vinaigre, assaisonner et remettre les saucisses dessus. Couvrir et braiser à feu moyen-doux 12 à 15 min, jusqu''à ce que le chou soit tendre et les saucisses cuites à cœur.","Égoutter les pommes de terre et les écraser en purée avec le beurre, le lait chaud et la muscade.","Servir les saucisses et le chou avec la purée et de la moutarde."]},"it":{"title":"Salsicce con cavolo brasato e purè","steps":["Mettere a lessare le patate in acqua salata; servono 15-20 min perché siano tenere.","Nel frattempo rosolare le salsicce nell''olio in una casseruola grande a fuoco medio per 8 min, girandole. Toglierle e tenerle da parte.","Mettere la cipolla nella casseruola e cuocerla 4 min finché è morbida, poi aggiungere il cavolo, il cumino dei prati e l''alloro e mescolare 3 min finché il cavolo appassisce.","Versare il vino, il brodo e l''aceto, regolare di sale e rimettere sopra le salsicce. Coprire e brasare a fuoco medio-basso per 12-15 min, finché il cavolo è tenero e le salsicce cotte all''interno.","Scolare le patate e schiacciarle con il burro, il latte caldo e la noce moscata.","Servire le salsicce e il cavolo con il purè e la senape."]}}'::jsonb),
  ('a789c5f2-85b3-4e2d-816d-a159b7989c55'::uuid, '{"fr":{"title":"Ragoût de patate douce aux cacahuètes","steps":["Lancer le riz : le cuire à couvert à petit feu dans 1,5 fois son volume d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Pendant ce temps, faire fondre l''oignon dans l''huile dans une cocotte à feu moyen-doux 6 à 8 min.","Ajouter l''ail, le gingembre, le cumin, la coriandre moulue et le piment de Cayenne et remuer 1 min jusqu''à ce que ça embaume.","Ajouter les tomates, le bouillon, la patate douce et les pois chiches avec sel et poivre. Porter à ébullition puis laisser mijoter à découvert 12 à 15 min, jusqu''à ce que la patate douce soit tendre.","Délayer le beurre de cacahuète avec une louche de liquide chaud jusqu''à ce qu''il soit lisse, l''incorporer dans la cocotte et laisser mijoter 2 à 3 min jusqu''à ce que la sauce épaississe.","Ajouter les épinards et remuer jusqu''à ce qu''ils tombent, environ 1 min, puis rectifier le sel.","Servir sur le riz, parsemé de cacahuètes concassées et de coriandre."]},"it":{"title":"Stufato di patate dolci e arachidi","steps":["Avviare il riso: cuocerlo coperto a fuoco basso in 1,5 volte il suo volume di acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo, appassire la cipolla nell''olio in una pentola a fuoco medio-basso per 6-8 min.","Aggiungere l''aglio, lo zenzero, il cumino, il coriandolo in polvere e il pepe di Cayenna e mescolare 1 min finché profumano.","Aggiungere i pomodori, il brodo, la patata dolce e i ceci con sale e pepe. Portare a bollore, poi cuocere scoperto a fuoco lento 12-15 min, finché la patata dolce è tenera.","Stemperare il burro di arachidi con un mestolo di liquido caldo finché è liscio, versarlo nella pentola e cuocere 2-3 min finché la salsa si addensa.","Unire gli spinaci e mescolare finché appassiscono, circa 1 min, poi regolare di sale.","Servire sul riso, con arachidi tritate e coriandolo."]}}'::jsonb),
  ('8bb592e0-9ca3-454e-92f6-15e3a6d0d82d'::uuid, '{"fr":{"title":"Bœuf Stroganoff aux tagliatelles","steps":["Mettre à bouillir une casserole d''eau salée pour les tagliatelles.","Faire dorer les champignons dans la moitié de l''huile dans une grande poêle à feu vif 5 à 6 min, saler et les réserver dans un bol.","Ajouter le reste de l''huile et saisir les lanières de bœuf en une seule couche 1 à 2 min de chaque côté, juste dorées mais encore rosées à cœur. Saler, poivrer et les ajouter aux champignons.","Baisser à feu moyen, faire fondre le beurre et cuire l''oignon avec le concentré de tomate et le paprika 5 à 6 min, jusqu''à ce qu''il soit tendre et légèrement doré.","Incorporer la farine 30 s, puis verser le bouillon et le vin en fouettant et en grattant la poêle. Laisser mijoter 2 à 3 min jusqu''à ce que la sauce nappe la cuillère.","Pendant ce temps, cuire les tagliatelles selon le paquet, en général 8 à 10 min, et les égoutter.","Retirer la poêle du feu, incorporer la moutarde et la crème fraîche, puis remettre le bœuf, les champignons et leur jus et réchauffer 1 min sans faire bouillir.","Servir le Stroganoff sur les tagliatelles, parsemé de persil."]},"it":{"title":"Manzo alla Stroganoff con tagliatelle","steps":["Mettere a bollire una pentola d''acqua salata per le tagliatelle.","Rosolare i funghi in metà dell''olio in una padella grande a fuoco vivo per 5-6 min, salarli e metterli da parte in una ciotola.","Aggiungere il resto dell''olio e scottare le strisce di manzo in un solo strato 1-2 min per lato, appena rosolate ma ancora rosate dentro. Salare, pepare e unirle ai funghi.","Abbassare a fuoco medio, sciogliere il burro e cuocere la cipolla con il concentrato di pomodoro e la paprika per 5-6 min, finché è morbida e appena dorata.","Incorporare la farina per 30 s, poi versare il brodo e il vino mescolando con la frusta e raschiando la padella. Cuocere 2-3 min finché la salsa vela il cucchiaio.","Nel frattempo, cuocere le tagliatelle secondo la confezione, di solito 8-10 min, e scolarle.","Togliere la padella dal fuoco, unire la senape e la crème fraîche, poi rimettere il manzo, i funghi e il loro sugo e scaldare 1 min senza far bollire.","Servire lo Stroganoff sulle tagliatelle con il prezzemolo."]}}'::jsonb),
  ('54c25855-82be-4d48-9e67-689d4b21866c'::uuid, '{"fr":{"title":"Truite au four, pommes de terre à l''aneth et concombre","steps":["Préchauffer le four à 200 °C. Mettre les pommes de terre dans une casserole d''eau froide salée avec les tiges d''aneth, porter à ébullition et cuire 15 à 20 min jusqu''à ce qu''elles soient tendres.","Pour le pressgurka, mélanger le vinaigre, le sucre, 2 c. à soupe d''eau et une pincée de sel jusqu''à dissolution, ajouter le concombre et un peu d''aneth et laisser mariner pendant la cuisson.","Poser la truite côté peau dans un plat huilé, saler, poivrer, parsemer de la moitié du beurre et ajouter quelques rondelles de citron.","Enfourner 10 à 12 min, jusqu''à ce que la chair soit opaque et se détache facilement.","Mélanger la crème fraîche avec la moutarde, un filet de citron, la moitié de l''aneth restant, du sel et du poivre.","Égoutter les pommes de terre et les enrober du reste du beurre et de l''aneth.","Servir la truite avec les pommes de terre à l''aneth, le concombre égoutté et la sauce à l''aneth."]},"it":{"title":"Trota al forno con patate all''aneto e cetrioli","steps":["Scaldare il forno a 200 °C. Mettere le patate in una pentola di acqua fredda salata con i gambi di aneto, portare a bollore e cuocere 15-20 min finché sono tenere.","Per il pressgurka, mescolare l''aceto, lo zucchero, 2 cucchiai d''acqua e un pizzico di sale finché si sciolgono, aggiungere il cetriolo e un po'' di aneto e lasciare marinare durante la cottura.","Disporre la trota con la pelle verso il basso in una pirofila unta, salare, pepare, distribuire metà del burro e qualche fetta di limone.","Infornare 10-12 min, finché la polpa è opaca e si sfalda facilmente.","Mescolare la crème fraîche con la senape, una spruzzata di limone, metà dell''aneto rimasto, sale e pepe.","Scolare le patate e condirle con il resto del burro e dell''aneto.","Servire la trota con le patate all''aneto, il cetriolo scolato e la salsa all''aneto."]}}'::jsonb),
  ('f494248a-e37a-4325-a232-ee05373d514e'::uuid, '{"fr":{"title":"Gołąbki aux champignons, épinards et riz","steps":["Faire tremper les cèpes séchés 20 min dans 200 ml d''eau chaude, puis les égoutter, les hacher et garder l''eau de trempage.","Retirer le trognon du chou et cuire le chou entier 8 à 10 min dans un grand faitout d''eau salée frémissante, en détachant 8 feuilles à mesure qu''elles ramollissent. Amincir la grosse nervure de chaque feuille.","Vider le faitout et y cuire le riz dans l''eau des cèpes filtrée, complétée d''eau jusqu''à 300 ml, 8 à 10 min, jusqu''à ce qu''il soit à moitié cuit et ait absorbé le liquide.","Pendant ce temps, faire dorer l''oignon dans l''huile et le beurre 8 min, ajouter les champignons frais et réhydratés, l''ail et le thym et cuire 6 à 8 min jusqu''à évaporation, puis ajouter les épinards et les laisser tomber.","Préchauffer le four à 180 °C. Mélanger le riz et la poêlée de champignons, et bien assaisonner.","Déposer une bonne cuillerée de farce à la base de chaque feuille, rabattre les côtés et rouler. Ranger les rouleaux, fermeture dessous, dans un plat tapissé de quelques feuilles restantes.","Assaisonner le coulis de tomate, le détendre avec 100 ml d''eau et le verser sur les rouleaux. Couvrir d''un couvercle ou de papier aluminium.","Enfourner 50 min, jusqu''à ce que le chou soit bien tendre. Servir avec une cuillerée de crème fraîche et de l''aneth."]},"it":{"title":"Gołąbki con funghi, spinaci e riso","steps":["Mettere in ammollo i porcini secchi in 200 ml di acqua calda per 20 min, poi scolarli, tritarli e tenere l''acqua dell''ammollo.","Eliminare il torsolo del cavolo e sbollentare il cavolo intero in una pentola grande di acqua salata per 8-10 min, staccando 8 foglie man mano che si ammorbidiscono. Assottigliare la costa spessa di ogni foglia.","Svuotare la pentola e cuocervi il riso nell''acqua dei porcini filtrata, allungata con acqua fino a 300 ml, per 8-10 min, finché è a metà cottura e ha assorbito il liquido.","Nel frattempo, dorare la cipolla nell''olio e nel burro per 8 min, aggiungere i funghi freschi e quelli ammollati, l''aglio e il timo e cuocere 6-8 min finché sono asciutti, poi unire gli spinaci e farli appassire.","Scaldare il forno a 180 °C. Mescolare il riso e i funghi e condire bene.","Mettere una cucchiaiata abbondante di ripieno alla base di ogni foglia, ripiegare i lati e arrotolare. Disporre gli involtini con la chiusura verso il basso in una pirofila foderata con qualche foglia avanzata.","Condire la passata, allungarla con 100 ml d''acqua e versarla sugli involtini. Coprire con un coperchio o con alluminio.","Infornare 50 min, finché il cavolo è molto tenero. Servire con una cucchiaiata di crème fraîche e aneto."]}}'::jsonb),
  ('3386f80c-25ff-468e-bd8a-ec26b70c7749'::uuid, '{"fr":{"title":"Joojeh kabab et riz au safran","steps":["Piler le safran avec une pincée de sucre ou de sel et le faire infuser 10 min dans 3 c. à soupe d''eau chaude.","Mélanger l''oignon râpé, le jus du citron, le yaourt, l''huile, le curcuma, les deux tiers de l''eau safranée, du sel et du poivre. Y enrober le poulet, couvrir et réfrigérer au moins 4 h, idéalement une nuit.","Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert à petit feu dans 250 ml d''eau salée avec le beurre 12 min et le laisser reposer 5 min hors du feu.","Mélanger quelques cuillerées de riz avec le reste de l''eau safranée et réserver pour les incorporer au service.","Enfiler le poulet sur des brochettes en égouttant l''excès de marinade. Faire chauffer très fort une poêle-gril ou un barbecue.","Griller les brochettes 10 à 12 min en les retournant toutes les quelques minutes, jusqu''à ce qu''elles soient grillées sur les bords et cuites à cœur. Griller les demi-tomates à côté 5 à 6 min.","Égrener le riz blanc, le garnir du riz safrané et servir avec les brochettes, les tomates grillées et un filet de citron."]},"it":{"title":"Joojeh kabab con riso allo zafferano","steps":["Pestare lo zafferano con un pizzico di zucchero o sale e lasciarlo in infusione 10 min in 3 cucchiai di acqua calda.","Mescolare la cipolla grattugiata, il succo del limone, lo yogurt, l''olio, la curcuma, due terzi dell''acqua allo zafferano, sale e pepe. Ricoprirvi il pollo, coprire e mettere in frigo almeno 4 h, meglio tutta la notte.","Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto a fuoco basso in 250 ml di acqua salata con il burro per 12 min e lasciarlo riposare 5 min fuori dal fuoco.","Mescolare qualche cucchiaiata di riso con il resto dell''acqua allo zafferano e tenerla da parte da unire al momento di servire.","Infilare il pollo negli spiedini, scolando la marinata in eccesso. Scaldare bene una bistecchiera o il barbecue.","Grigliare gli spiedini 10-12 min, girandoli ogni pochi minuti, finché sono abbrustoliti ai bordi e cotti all''interno. Grigliare accanto i mezzi pomodori per 5-6 min.","Sgranare il riso bianco, coprirlo con il riso allo zafferano e servire con gli spiedini, i pomodori grigliati e una spruzzata di limone."]}}'::jsonb),
  ('f96f71e7-3799-457e-bcee-84a98bd7bcad'::uuid, '{"fr":{"title":"Kuku sabzi (omelette persane aux herbes)","steps":["Laver les herbes et les oignons nouveaux et les sécher très soigneusement, puis les hacher finement avec l''ail au robot par petites impulsions (ou au couteau).","Battre les œufs avec le curcuma, la levure chimique, du sel et du poivre, puis incorporer les herbes et les noix. Le mélange doit être plus vert que jaune.","Faire chauffer l''huile dans une poêle antiadhésive de 22 à 24 cm à feu moyen-doux, verser le mélange et l''égaliser.","Couvrir et cuire 8 à 10 min, jusqu''à ce que les bords soient pris et le dessous bien doré.","Couper en quatre, retourner chaque quart et cuire encore 4 à 5 min à découvert, jusqu''à ce que le centre soit pris.","Servir chaud ou tiède avec le yaourt et le pain plat chaud."]},"it":{"title":"Kuku sabzi (frittata persiana alle erbe)","steps":["Lavare le erbe e i cipollotti e asciugarli molto bene, poi tritarli finemente con l''aglio nel robot a brevi impulsi (o a coltello).","Sbattere le uova con la curcuma, il lievito, sale e pepe, poi incorporare le erbe e le noci. Il composto deve essere più verde che giallo.","Scaldare l''olio in una padella antiaderente da 22-24 cm a fuoco medio-basso, versare il composto e livellarlo.","Coprire e cuocere 8-10 min, finché i bordi sono rappresi e il fondo è ben dorato.","Tagliare in quattro, girare ogni spicchio e cuocere scoperto altri 4-5 min, finché è rappreso al centro.","Servire calda o tiepida con lo yogurt e il pane piatto caldo."]}}'::jsonb),
  ('27951550-45d9-4434-95ac-acb66e9a2444'::uuid, '{"fr":{"title":"Riz jollof au poulet","steps":["Préchauffer le four à 220 °C. Frotter le poulet avec la moitié du curry, le paprika, la moitié du thym, un peu d''huile, du sel et du poivre. Le rôtir côté peau vers le haut sur une plaque 22 à 25 min, jusqu''à ce qu''il soit doré et cuit à cœur.","Pendant ce temps, mixer la tomate, le poivron, la moitié de l''oignon, l''ail, le gingembre et le piment en purée lisse.","Émincer le reste de l''oignon et le faire revenir dans l''huile dans une cocotte à feu moyen-vif 3 min.","Ajouter la purée et cuire en remuant 6 à 7 min, jusqu''à ce qu''elle épaississe et que l''huile se sépare. Incorporer le concentré de tomate, le reste du curry et du thym et faire revenir 2 min.","Ajouter le bouillon, le laurier, le beurre et du sel, porter à ébullition, puis incorporer le riz.","Couvrir hermétiquement et cuire à feu doux 18 à 20 min sans remuer, jusqu''à ce que le riz soit tendre et ait absorbé le liquide. Ajouter un peu d''eau s''il sèche avant d''être cuit.","Laisser reposer 5 min hors du feu, égrener à la fourchette et servir avec le poulet rôti."]},"it":{"title":"Riso jollof con pollo","steps":["Scaldare il forno a 220 °C. Massaggiare il pollo con metà del curry, la paprika, metà del timo, un filo d''olio, sale e pepe. Arrostirlo con la pelle verso l''alto su una teglia per 22-25 min, finché è dorato e cotto all''interno.","Nel frattempo, frullare il pomodoro, il peperone, metà della cipolla, l''aglio, lo zenzero e il peperoncino fino a ottenere una purea liscia.","Tritare il resto della cipolla e soffriggerla nell''olio in una pentola dal fondo spesso a fuoco medio-alto per 3 min.","Aggiungere la purea e cuocere mescolando 6-7 min, finché si addensa e l''olio comincia a separarsi. Unire il concentrato di pomodoro, il curry e il timo rimasti e soffriggere 2 min.","Aggiungere il brodo, l''alloro, il burro e il sale, portare a bollore, poi unire il riso.","Coprire bene e cuocere a fuoco basso 18-20 min senza mescolare, finché il riso è tenero e ha assorbito il liquido. Aggiungere un goccio d''acqua se si asciuga prima che il riso sia cotto.","Lasciare riposare 5 min fuori dal fuoco, sgranare con una forchetta e servire con il pollo arrosto."]}}'::jsonb),
  ('9859e619-b04e-460a-b38f-d101ff535774'::uuid, '{"fr":{"title":"Poulet yassa","steps":["Mélanger les oignons, le jus des citrons, la moutarde, l''ail, le piment, 1 c. à soupe d''huile, du sel et du poivre. Y retourner le poulet, couvrir et réfrigérer au moins 2 h, ou une nuit.","Sortir le poulet de la marinade et le sécher. Le faire dorer dans le reste de l''huile dans une cocotte à feu moyen-vif 3 min de chaque côté, puis réserver.","Égoutter les oignons de la marinade en gardant le liquide. Les cuire dans la même cocotte à feu moyen 12 min en remuant souvent, jusqu''à ce qu''ils soient fondants et dorés.","Ajouter le liquide de marinade, le bouillon et le laurier, puis remettre le poulet. Couvrir et laisser mijoter doucement 12 min jusqu''à ce que le poulet soit cuit à cœur, en ajoutant les olives les 5 dernières minutes.","Pendant ce temps, cuire le riz à couvert dans 1,5 fois son volume d''eau salée 12 min et le laisser reposer 5 min.","Goûter la sauce : elle doit être acidulée mais ronde ; ajouter un peu de moutarde ou une pincée de sucre si elle est trop vive. Servir sur le riz."]},"it":{"title":"Pollo yassa","steps":["Mescolare le cipolle, il succo dei limoni, la senape, l''aglio, il peperoncino, 1 cucchiaio d''olio, sale e pepe. Girarvi il pollo, coprire e mettere in frigo almeno 2 h, o tutta la notte.","Togliere il pollo dalla marinata e asciugarlo. Rosolarlo nel resto dell''olio in una casseruola a fuoco medio-alto 3 min per lato, poi tenerlo da parte.","Scolare le cipolle dalla marinata tenendo il liquido. Cuocerle nella stessa casseruola a fuoco medio per 12 min, mescolando spesso, finché sono morbide e dorate.","Aggiungere il liquido della marinata, il brodo e l''alloro, poi rimettere il pollo. Coprire e cuocere a fuoco dolce 12 min finché il pollo è cotto, unendo le olive negli ultimi 5 min.","Nel frattempo, cuocere il riso coperto in 1,5 volte il suo volume di acqua salata per 12 min e lasciarlo riposare 5 min.","Assaggiare la salsa: deve essere acidula ma rotonda; aggiungere un po'' di senape o un pizzico di zucchero se è troppo aspra. Servire sul riso."]}}'::jsonb),
  ('cc15f857-8ba8-43a4-b185-6b48713f7f16'::uuid, '{"fr":{"title":"Poulet brown stew, riz aux haricots rouges","steps":["Mélanger le poulet avec l''oignon, le poivron, la carotte, l''ail, le gingembre, les oignons nouveaux, le piment de la Jamaïque, le paprika, le piment, le thym, la sauce soja, du sel et du poivre. Couvrir et réfrigérer au moins 2 h, ou une nuit.","Faire chauffer l''huile et le sucre dans une cocotte à fond épais à feu moyen jusqu''à ce que le sucre devienne brun foncé et commence à fumer, 2 à 3 min, en surveillant bien.","Sortir le poulet des légumes et le faire dorer dans le caramel 3 min de chaque côté, jusqu''à ce qu''il soit bien brun.","Ajouter les légumes marinés et les faire revenir 3 min, puis incorporer le ketchup et le bouillon. Couvrir et laisser mijoter doucement 12 min.","Pendant ce temps, pour le riz, mettre le riz, les haricots, le lait de coco, 150 ml d''eau, une branche de thym et du sel dans une casserole, porter à ébullition, couvrir et cuire à feu doux 15 min, puis laisser reposer 5 min.","Découvrir le poulet et laisser mijoter encore 6 à 8 min, jusqu''à ce que la viande soit cuite et la sauce épaisse et brillante.","Servir le poulet et sa sauce avec le riz aux haricots rouges."]},"it":{"title":"Pollo brown stew con riso e fagioli","steps":["Mescolare il pollo con la cipolla, il peperone, la carota, l''aglio, lo zenzero, i cipollotti, il pimento, la paprika, il peperoncino, il timo, la salsa di soia, sale e pepe. Coprire e mettere in frigo almeno 2 h, o tutta la notte.","Scaldare l''olio e lo zucchero in una pentola dal fondo spesso a fuoco medio finché lo zucchero diventa bruno scuro e comincia a fumare, 2-3 min, controllando bene.","Togliere il pollo dalle verdure e rosolarlo nel caramello 3 min per lato, finché è ben scuro.","Aggiungere le verdure marinate e soffriggere 3 min, poi unire il ketchup e il brodo. Coprire e cuocere a fuoco dolce 12 min.","Nel frattempo, per il riso, mettere in una pentola il riso, i fagioli, il latte di cocco, 150 ml d''acqua, un rametto di timo e il sale, portare a bollore, coprire e cuocere a fuoco basso 15 min, poi lasciare riposare 5 min.","Scoprire il pollo e cuocere altri 6-8 min, finché la carne è cotta e il sugo denso e lucido.","Servire il pollo con il sugo e il riso con i fagioli."]}}'::jsonb),
  ('5e6779a0-957a-4af7-9775-d03c9b70b678'::uuid, '{"fr":{"title":"Goulash hongrois (gulyás)","steps":["Faire fondre le beurre dans une cocotte à fond épais à feu moyen et cuire les oignons 8 à 10 min jusqu''à ce qu''ils soient dorés.","Ajouter le bœuf et le faire dorer sur toutes les faces 8 min.","Ajouter le poivron, la tomate et l''ail et cuire 5 min.","Retirer la cocotte du feu et incorporer le paprika et le carvi pour que le paprika ne brûle pas.","Verser le bouillon, ajouter le laurier et du sel, porter à ébullition, puis couvrir et laisser mijoter doucement 1 h.","Ajouter les carottes et les pommes de terre et laisser mijoter à couvert encore 30 à 40 min, jusqu''à ce que le bœuf soit très tendre et les pommes de terre cuites.","Retirer le laurier, rectifier l''assaisonnement et servir dans des assiettes creuses avec une cuillerée de crème fraîche et du pain."]},"it":{"title":"Gulasch ungherese (gulyás)","steps":["Sciogliere il burro in una pentola dal fondo spesso a fuoco medio e cuocere le cipolle 8-10 min finché sono dorate.","Aggiungere il manzo e rosolarlo su tutti i lati per 8 min.","Aggiungere il peperone, il pomodoro e l''aglio e cuocere 5 min.","Togliere la pentola dal fuoco e incorporare la paprika e il cumino dei prati, così la paprika non brucia.","Versare il brodo, aggiungere l''alloro e il sale, portare a bollore, poi coprire e cuocere a fuoco dolce per 1 h.","Aggiungere le carote e le patate e cuocere coperto altri 30-40 min, finché il manzo è molto tenero e le patate sono cotte.","Togliere l''alloro, regolare di sale e servire in piatti fondi con una cucchiaiata di crème fraîche e pane."]}}'::jsonb),
  ('109d6d4a-1ff5-4003-9980-ec0e6c98e33c'::uuid, '{"fr":{"title":"Bigos (choucroute polonaise du chasseur)","steps":["Faire tremper les cèpes séchés 20 min dans 250 ml d''eau chaude, puis les hacher et filtrer le liquide.","Faire revenir les lardons dans l''huile dans un grand faitout à fond épais à feu moyen jusqu''à ce qu''ils rendent leur gras, puis ajouter le porc et le faire dorer sur toutes les faces 8 min. Ajouter la saucisse les 2 dernières minutes.","Ajouter l''oignon et les champignons frais et cuire 6 à 8 min jusqu''à ce qu''ils soient tendres.","Incorporer le concentré de tomate 1 min, puis ajouter la choucroute, le chou, les cèpes et leur eau, les pruneaux, le vin, le laurier, le piment de la Jamaïque, le carvi et du poivre.","Porter à frémissement, couvrir et cuire à très feu doux 2 h, en remuant de temps en temps et en ajoutant un peu d''eau si ça accroche.","Découvrir les 15 dernières minutes pour faire épaissir. Rectifier l''assaisonnement et servir avec du pain de seigle. C''est encore meilleur réchauffé le lendemain."]},"it":{"title":"Bigos (stufato polacco del cacciatore)","steps":["Mettere in ammollo i porcini secchi in 250 ml di acqua calda per 20 min, poi tritarli e filtrare il liquido.","Rosolare la pancetta nell''olio in una pentola grande dal fondo spesso a fuoco medio finché rilascia il grasso, poi aggiungere il maiale e rosolarlo su tutti i lati per 8 min. Unire la salsiccia negli ultimi 2 min.","Aggiungere la cipolla e i funghi freschi e cuocere 6-8 min finché sono morbidi.","Incorporare il concentrato di pomodoro per 1 min, poi aggiungere i crauti, il cavolo, i porcini con il loro liquido, le prugne, il vino, l''alloro, il pimento, il cumino dei prati e il pepe.","Portare a sobbollire, coprire e cuocere a fuoco bassissimo per 2 h, mescolando ogni tanto e aggiungendo un goccio d''acqua se attacca.","Scoprire negli ultimi 15 min per far addensare. Regolare di sale e servire con pane di segale. Riscaldato il giorno dopo è ancora più buono."]}}'::jsonb),
  ('263af3c6-ef74-4605-91cb-056837b47a7c'::uuid, '{"fr":{"title":"Chkmeruli (poulet géorgien à l''ail)","steps":["Saler et poivrer le poulet. Le poser côté peau dans une grande poêle avec l''huile à feu moyen-vif et l''aplatir avec une casserole lourde ou une assiette.","Cuire 8 à 10 min jusqu''à ce que la peau soit bien dorée et croustillante, puis retourner et cuire encore 4 à 5 min jusqu''à cuisson à cœur. Retirer l''essentiel du gras.","Baisser le feu, ajouter la pâte d''ail autour du poulet et la remuer dans le gras 30 à 60 s sans la laisser colorer.","Verser le lait et la crème, ajouter la coriandre moulue et le piment et laisser mijoter 4 à 5 min en arrosant le poulet de sauce, jusqu''à ce qu''elle épaississe légèrement.","Incorporer le persil, parsemer de coriandre et servir directement dans la poêle avec du pain pour saucer."]},"it":{"title":"Chkmeruli (pollo georgiano all''aglio)","steps":["Salare e pepare il pollo. Disporlo con la pelle verso il basso in una padella grande con l''olio a fuoco medio-alto e schiacciarlo con una pentola pesante o un piatto.","Cuocere 8-10 min finché la pelle è ben dorata e croccante, poi girare e cuocere altri 4-5 min finché è cotto all''interno. Eliminare quasi tutto il grasso.","Abbassare il fuoco, aggiungere la pasta d''aglio intorno al pollo e mescolarla nel grasso per 30-60 s senza farla colorire.","Versare il latte e la panna, aggiungere il coriandolo in polvere e il peperoncino e cuocere 4-5 min, irrorando il pollo con la salsa, finché si addensa leggermente.","Unire il prezzemolo, cospargere di coriandolo e servire direttamente nella padella con pane per fare la scarpetta."]}}'::jsonb),
  ('6c4dd985-1d88-4985-a862-18e27c911a1d'::uuid, '{"fr":{"title":"Carbonnade flamande","steps":["Faire fondre la moitié du beurre dans une cocotte à feu moyen-doux et cuire les oignons à couvert 12 à 15 min jusqu''à ce qu''ils soient fondants et dorés. Ajouter les lardons les 3 dernières minutes, puis tout retirer.","Monter le feu, ajouter le reste du beurre et saisir le bœuf en plusieurs fois, 6 à 8 min en tout, jusqu''à ce qu''il soit bien coloré. Saler et poivrer.","Saupoudrer le bœuf de farine et de cassonade et remuer 1 à 2 min jusqu''à ce que le sucre caramélise.","Remettre les oignons et les lardons, verser la bière, ajouter le bouquet garni et gratter le fond de la cocotte.","Tartiner les tranches de pain d''épices de moutarde et les poser sur le dessus, côté moutarde dessous, sans mélanger.","Couvrir et laisser mijoter à très feu doux 2 h 30 à 3 h, jusqu''à ce que le bœuf soit très tendre et que le pain d''épices ait fondu en une sauce épaisse. Découvrir les 15 dernières minutes si la sauce est trop liquide.","Environ 25 min avant la fin, cuire les pommes de terre 20 min dans de l''eau salée jusqu''à ce qu''elles soient tendres et les égoutter.","Retirer le bouquet garni, ajouter le vinaigre, rectifier l''assaisonnement et servir avec les pommes de terre et le persil."]},"it":{"title":"Carbonade fiamminga (manzo alla birra)","steps":["Sciogliere metà del burro in una casseruola a fuoco medio-basso e cuocere le cipolle coperte per 12-15 min, finché sono morbide e dorate. Unire la pancetta negli ultimi 3 min, poi togliere tutto.","Alzare il fuoco, aggiungere il resto del burro e rosolare il manzo un po'' alla volta, 6-8 min in tutto, finché è ben colorito. Salare e pepare.","Cospargere il manzo con la farina e lo zucchero e mescolare 1-2 min finché lo zucchero caramella.","Rimettere le cipolle e la pancetta, versare la birra, aggiungere il mazzetto aromatico e raschiare il fondo della casseruola.","Spalmare le fette di pan di spezie con la senape e adagiarle sopra, con la senape verso il basso, senza mescolare.","Coprire e cuocere a fuoco bassissimo per 2 h 30 - 3 h, finché il manzo è molto tenero e il pan di spezie si è sciolto in una salsa densa. Scoprire negli ultimi 15 min se la salsa è troppo liquida.","Circa 25 min prima della fine, lessare le patate in acqua salata per 20 min finché sono tenere e scolarle.","Togliere il mazzetto aromatico, unire l''aceto, regolare di sale e servire con le patate e il prezzemolo."]}}'::jsonb),
  ('21256741-4c74-4be1-afeb-973446df94e4'::uuid, '{"fr":{"title":"Waterzooi de poulet","steps":["Faire fondre le beurre dans un grand faitout à feu moyen-doux et faire suer le poireau, les carottes, le céleri et l''oignon 5 min sans coloration.","Ajouter le bouillon et le bouquet garni, porter à frémissement, puis ajouter les morceaux de poulet et les pommes de terre.","Pocher doucement, à demi couvert, 15 min jusqu''à ce que le poulet soit cuit à cœur et les pommes de terre tendres.","Retirer le bouquet garni et vérifier que le poulet et les pommes de terre sont cuits à cœur.","Fouetter la crème, le jaune d''œuf et la fécule dans un bol, puis y incorporer une louche de bouillon chaud en fouettant.","Hors ébullition, verser la liaison dans le faitout et chauffer doucement 2 à 3 min en remuant, jusqu''à ce que le bouillon épaississe légèrement. Ne pas faire bouillir.","Assaisonner de sel, de poivre et d''un filet de citron, et servir dans des assiettes creuses avec le persil et la ciboulette."]},"it":{"title":"Waterzooi di pollo","steps":["Sciogliere il burro in una pentola grande a fuoco medio-basso e stufare il porro, le carote, il sedano e la cipolla per 5 min senza farli colorire.","Aggiungere il brodo e il mazzetto aromatico, portare a sobbollire, poi aggiungere i pezzi di pollo e le patate.","Cuocere dolcemente, semicoperto, per 15 min, finché il pollo è cotto all''interno e le patate sono tenere.","Eliminare il mazzetto aromatico e controllare che pollo e patate siano cotti.","Sbattere la panna, il tuorlo e l''amido di mais in una ciotola, poi incorporare un mestolo di brodo caldo.","Fuori dal bollore, versare il composto nella pentola e scaldare dolcemente 2-3 min mescolando, finché il brodo si addensa leggermente. Non far bollire.","Condire con sale, pepe e una spruzzata di limone, e servire in piatti fondi con prezzemolo ed erba cipollina."]}}'::jsonb),
  ('5cad9345-d8b4-438f-a6b8-4f4a657d32ac'::uuid, '{"fr":{"title":"Jambalaya","steps":["Assaisonner le poulet avec la moitié des épices créoles. Le faire dorer dans l''huile dans une cocotte à fond épais à feu moyen-vif 4 min, puis réserver.","Faire dorer la saucisse dans la même cocotte 2 min et la réserver avec le poulet.","Cuire l''oignon, le céleri et le poivron dans le gras 5 min jusqu''à ce qu''ils soient tendres, ajouter l''ail 30 s, puis incorporer le concentré de tomate 1 min.","Ajouter les tomates, le bouillon, le reste des épices, le thym et le laurier, gratter le fond et remettre le poulet et la saucisse.","Porter à ébullition, incorporer le riz, puis couvrir et cuire à feu doux 15 min sans remuer.","Répartir les crevettes sur le riz, couvrir à nouveau et cuire 4 à 5 min, jusqu''à ce qu''elles soient roses et le riz tendre.","Laisser reposer 5 min hors du feu, égrener, rectifier l''assaisonnement et servir avec les oignons nouveaux."]},"it":{"title":"Jambalaya","steps":["Condire il pollo con metà delle spezie creole. Rosolarlo nell''olio in una pentola dal fondo spesso a fuoco medio-alto per 4 min, poi tenerlo da parte.","Rosolare la salsiccia nella stessa pentola per 2 min e metterla da parte con il pollo.","Cuocere la cipolla, il sedano e il peperone nel grasso per 5 min finché sono morbidi, aggiungere l''aglio per 30 s, poi unire il concentrato di pomodoro per 1 min.","Aggiungere i pomodori, il brodo, il resto delle spezie, il timo e l''alloro, raschiare il fondo e rimettere il pollo e la salsiccia.","Portare a bollore, unire il riso, poi coprire e cuocere a fuoco basso 15 min senza mescolare.","Distribuire i gamberi sul riso, coprire di nuovo e cuocere 4-5 min, finché diventano rosa e il riso è tenero.","Lasciare riposare 5 min fuori dal fuoco, sgranare, regolare di sale e servire con i cipollotti."]}}'::jsonb),
  ('751145c3-7b69-4ccb-a0f5-a608ed92d0d8'::uuid, '{"fr":{"title":"Frikadeller, pommes de terre et salade de concombre","steps":["Mettre les pommes de terre dans de l''eau froide salée, porter à ébullition et cuire 15 à 20 min jusqu''à ce qu''elles soient tendres.","Mélanger le vinaigre, le sucre, 1 c. à soupe d''eau et une pincée de sel jusqu''à dissolution et y ajouter le concombre ; laisser mariner.","Mélanger le porc, le veau, l''oignon, l''œuf, la farine, le lait, la muscade, 1 c. à café de sel et du poivre jusqu''à obtenir une farce lisse et collante. Faire cuire une cuillerée pour goûter l''assaisonnement.","Façonner 8 boulettes ovales à l''aide d''une cuillère ou des mains mouillées.","Les faire cuire dans le beurre et l''huile dans une poêle à feu moyen 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et cuites à cœur.","Égoutter les pommes de terre et les enrober d''un peu du beurre de cuisson et de persil. Servir avec les frikadeller et le concombre égoutté parsemé d''aneth."]},"it":{"title":"Frikadeller con patate e insalata di cetrioli","steps":["Mettere le patate in acqua fredda salata, portare a bollore e cuocere 15-20 min finché sono tenere.","Mescolare l''aceto, lo zucchero, 1 cucchiaio d''acqua e un pizzico di sale finché si sciolgono e unire il cetriolo; lasciare marinare.","Impastare il maiale, il vitello, la cipolla, l''uovo, la farina, il latte, la noce moscata, 1 cucchiaino di sale e il pepe finché l''impasto è liscio e appiccicoso. Cuocerne un cucchiaino per assaggiare il sale.","Formare 8 polpette ovali con un cucchiaio o con le mani bagnate.","Cuocerle nel burro e nell''olio in una padella a fuoco medio per 10-12 min, girandole a metà, finché sono ben dorate e cotte all''interno.","Scolare le patate e condirle con un po'' del burro di cottura e il prezzemolo. Servire con le frikadeller e il cetriolo scolato cosparso di aneto."]}}'::jsonb),
  ('86344908-27c8-4c77-90f7-299d2972fb69'::uuid, '{"fr":{"title":"Saumon au citron, pommes de terre et haricots verts au four","steps":["Préchauffer le four à 220 °C. Mélanger les pommes de terre coupées en quartiers avec 1 c. à soupe d''huile, du sel et du poivre sur une grande plaque et rôtir 18 min.","Mélanger le reste de l''huile avec l''ail, le zeste du citron et la moitié de son jus, la moitié de l''aneth, du sel et du poivre.","Pousser les pommes de terre sur les côtés, ajouter les haricots verts enrobés d''un peu d''huile citronnée et poser le saumon au centre, côté peau dessous.","Napper le saumon du reste de l''huile citronnée et ajouter quelques rondelles de citron.","Rôtir 10 à 12 min, jusqu''à ce que le saumon s''effeuille facilement et que les haricots soient tendres mais encore bien verts.","Parsemer du reste de l''aneth et servir avec des quartiers de citron."]},"it":{"title":"Salmone al limone in teglia con patate e fagiolini","steps":["Scaldare il forno a 220 °C. Condire le patate tagliate in quarti con 1 cucchiaio d''olio, sale e pepe su una teglia grande e arrostirle 18 min.","Mescolare il resto dell''olio con l''aglio, la scorza del limone e metà del suo succo, metà dell''aneto, sale e pepe.","Spostare le patate ai lati, aggiungere i fagiolini conditi con un po'' dell''olio al limone e mettere il salmone al centro, con la pelle verso il basso.","Versare il resto dell''olio al limone sul salmone e aggiungere qualche fetta di limone.","Arrostire 10-12 min, finché il salmone si sfalda facilmente e i fagiolini sono teneri ma ancora verdi brillanti.","Cospargere con il resto dell''aneto e servire con spicchi di limone."]}}'::jsonb),
  ('d473cbb0-83df-4bdb-bd0c-3fac1f8b2c83'::uuid, '{"fr":{"title":"Omelette aux petits pois, menthe et pommes de terre","steps":["Faire chauffer l''huile dans une poêle antiadhésive de 24 cm allant au four, à feu moyen. Ajouter les rondelles de pomme de terre avec une pincée de sel, couvrir et cuire 10 à 12 min en remuant de temps en temps, jusqu''à ce qu''elles soient tendres et dorées par endroits.","Ajouter les oignons nouveaux et les petits pois surgelés et cuire 2 min à découvert jusqu''à ce que les petits pois soient décongelés.","Allumer le gril du four. Battre les œufs avec la plus grande partie de la menthe, du sel et du poivre.","Verser les œufs dans la poêle, parsemer de feta et cuire à feu moyen-doux 4 à 5 min, en ramenant les bords vers le centre une ou deux fois, jusqu''à ce que le dessous soit pris et doré.","Glisser la poêle sous le gril 2 à 3 min, jusqu''à ce que le dessus soit gonflé et juste pris.","Parsemer du reste de menthe, couper en parts et servir."]},"it":{"title":"Frittata di piselli, menta e patate","steps":["Scaldare l''olio in una padella antiaderente da 24 cm adatta al forno, a fuoco medio. Aggiungere le fette di patata con un pizzico di sale, coprire e cuocere 10-12 min, girandole ogni tanto, finché sono tenere e dorate qua e là.","Aggiungere i cipollotti e i piselli surgelati e cuocere scoperto 2 min finché i piselli sono scongelati.","Accendere il grill del forno. Sbattere le uova con gran parte della menta, sale e pepe.","Versare le uova nella padella, cospargere di feta e cuocere a fuoco medio-basso 4-5 min, riportando i bordi verso il centro una o due volte, finché il fondo è rappreso e dorato.","Passare la padella sotto il grill per 2-3 min, finché la superficie è gonfia e appena rappresa.","Cospargere con la menta rimasta, tagliare a spicchi e servire."]}}'::jsonb),
  ('946f92ac-6411-45df-8501-3e4e1c32c64b'::uuid, '{"fr":{"title":"Burgers de dinde, poivrons rôtis et feta","steps":["Préchauffer le four à 220 °C. Mélanger les lanières de poivron avec 1 c. à soupe d''huile et du sel sur une plaque et rôtir 20 à 25 min, jusqu''à ce qu''elles soient tendres et grillées sur les bords.","Mélanger la dinde avec l''origan, la moitié de l''ail, la chapelure, du sel et du poivre, et façonner 2 steaks d''environ 2 cm d''épaisseur.","Mélanger le yaourt avec le reste de l''ail, un filet de citron et une pincée de sel.","Cuire les steaks dans le reste de l''huile dans une poêle à feu moyen 5 à 6 min de chaque côté, jusqu''à cuisson complète (74 °C à cœur, plus de rose).","Garnir les steaks de feta la dernière minute et couvrir la poêle pour qu''elle ramollisse. Toaster les pains côté mie dans la poêle ou au four.","Garnir les pains de salade, des steaks, des poivrons rôtis et d''une cuillerée de sauce au yaourt."]},"it":{"title":"Burger di tacchino con peperoni arrosto e feta","steps":["Scaldare il forno a 220 °C. Condire le strisce di peperone con 1 cucchiaio d''olio e sale su una teglia e arrostirle 20-25 min, finché sono morbide e abbrustolite ai bordi.","Mescolare il tacchino con l''origano, metà dell''aglio, il pangrattato, sale e pepe, e formare 2 hamburger spessi circa 2 cm.","Mescolare lo yogurt con il resto dell''aglio, una spruzzata di limone e un pizzico di sale.","Cuocere gli hamburger nel resto dell''olio in una padella a fuoco medio 5-6 min per lato, finché sono cotti (74 °C al centro, niente rosa).","Coprire gli hamburger con la feta nell''ultimo minuto e mettere il coperchio perché si ammorbidisca. Tostare i panini dal lato tagliato in padella o in forno.","Farcire i panini con lattuga, hamburger, peperoni arrosto e una cucchiaiata di salsa allo yogurt."]}}'::jsonb),
  ('57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, '{"fr":{"title":"Poêlée de patate douce, feta et œufs","steps":["Faire chauffer l''huile dans une grande poêle avec couvercle à feu moyen-vif. Ajouter la patate douce et l''oignon avec du sel, couvrir et cuire 8 min en remuant deux fois.","Découvrir et cuire encore 4 à 5 min en remuant de temps en temps, jusqu''à ce que la patate douce soit tendre et dorée sur les bords.","Incorporer l''ail, le paprika et le cumin 1 min, puis ajouter les épinards et un filet de citron et remuer jusqu''à ce qu''ils tombent.","Creuser 4 puits dans la poêlée, casser un œuf dans chacun, assaisonner et répartir la feta autour.","Couvrir et cuire à feu moyen-doux 4 à 5 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants. Servir avec du piment."]},"it":{"title":"Padellata di patate dolci, feta e uova","steps":["Scaldare l''olio in una padella grande con coperchio a fuoco medio-alto. Aggiungere la patata dolce e la cipolla con il sale, coprire e cuocere 8 min, mescolando due volte.","Scoprire e cuocere altri 4-5 min mescolando ogni tanto, finché la patata dolce è tenera e dorata ai bordi.","Unire l''aglio, la paprika e il cumino per 1 min, poi aggiungere gli spinaci e una spruzzata di limone e mescolare finché appassiscono.","Formare 4 incavi nella padellata, rompere un uovo in ognuno, condire e distribuire la feta intorno.","Coprire e cuocere a fuoco medio-basso 4-5 min, finché gli albumi sono rappresi e i tuorli ancora morbidi. Servire con peperoncino."]}}'::jsonb),
  ('7c747998-0a21-4b64-913d-489d9d25bb52'::uuid, '{"fr":{"title":"Pot-au-feu","steps":["Mettre le bœuf dans une grande marmite, couvrir de 2,5 l d''eau froide et porter doucement à ébullition à feu moyen (environ 20 min) en écumant la mousse grise qui remonte.","Ajouter l''oignon piqué de clous de girofle, le bouquet garni, les grains de poivre et 1 c. à soupe de gros sel, baisser à petit frémissement et cuire 2 h à couvert partiel, en écumant de temps en temps.","Ajouter les carottes, les navets, les poireaux et le céleri et laisser frémir encore 1 h, jusqu''à ce que la viande se coupe à la cuillère et que les légumes soient fondants.","Une demi-heure avant la fin, cuire les pommes de terre 20 à 25 min dans de l''eau salée (ou une louche de bouillon complétée d''eau), jusqu''à ce que la lame d''un couteau s''y enfonce facilement.","Sortir la viande et les légumes, trancher la viande dans le sens contraire des fibres et garder le tout au chaud dans un peu de bouillon.","Filtrer le bouillon et le dégraisser à la cuillère ; rectifier l''assaisonnement.","Servir d''abord une tasse de bouillon, puis la viande, les légumes et les pommes de terre avec du gros sel, de la moutarde de Dijon et des cornichons."]},"it":{"title":"Pot-au-feu (bollito alla francese)","steps":["Mettere il manzo in una pentola capiente, coprire con 2,5 l di acqua fredda e portare lentamente a bollore a fuoco medio (circa 20 min), schiumando la schiuma grigia che sale.","Aggiungere la cipolla steccata con i chiodi di garofano, il bouquet garni, i grani di pepe e 1 cucchiaio di sale grosso, abbassare a un leggero sobbollire e cuocere 2 h semicoperto, schiumando ogni tanto.","Aggiungere carote, rape, porri e sedano e cuocere ancora 1 h, finché la carne si taglia con un cucchiaio e le verdure sono morbide.","Mezz''ora prima della fine, lessare le patate in acqua salata (o in un mestolo di brodo allungato con acqua) per 20-25 min, finché un coltello entra facilmente.","Togliere carne e verdure, affettare la carne contro fibra e tenere tutto in caldo con un po'' di brodo.","Filtrare il brodo e sgrassarlo con un cucchiaio; regolare di sale.","Servire prima una tazza di brodo, poi carne, verdure e patate con sale grosso, senape di Digione e cetriolini."]}}'::jsonb),
  ('0cf3abed-cbf5-41be-a48b-9b9513390ce2'::uuid, '{"fr":{"title":"Endives au jambon","steps":["Parer la base des endives et retirer le petit cône amer au pied.","Mettre les endives dans une sauteuse avec 10 g de beurre, le jus de citron, le sucre, une pincée de sel et 3 c. à soupe d''eau ; couvrir et cuire 20 min à feu doux en les retournant une fois, jusqu''à ce que la pointe d''un couteau les traverse facilement.","Égoutter les endives dans une passoire en les pressant doucement pour en extraire le jus, et préchauffer le four à 200 °C.","Faire fondre 20 g de beurre dans une casserole, ajouter la farine et cuire 1 à 2 min ; verser le lait froid petit à petit en fouettant et laisser frémir 5 min en remuant, jusqu''à ce que la sauce nappe la cuillère. Saler, poivrer, muscader et incorporer la moitié du fromage.","Enrouler chaque endive dans une tranche de jambon et les ranger, jointure dessous, dans un plat à gratin beurré avec le reste du beurre.","Napper de béchamel et parsemer du reste de fromage.","Enfourner 20 à 25 min, jusqu''à ce que ce soit bouillonnant et doré, et laisser reposer 5 min avant de servir."]},"it":{"title":"Indivia belga al prosciutto gratinata","steps":["Rifilare la base delle indivie ed eliminare il piccolo cono amaro alla radice.","Mettere le indivie in una padella con coperchio con 10 g di burro, il succo di limone, lo zucchero, un pizzico di sale e 3 cucchiai d''acqua; coprire e cuocere a fuoco basso 20 min, girandole una volta, finché la punta di un coltello le attraversa facilmente.","Scolare le indivie in un colino premendole delicatamente per eliminare il liquido, e scaldare il forno a 200°C.","Sciogliere 20 g di burro in un pentolino, unire la farina e cuocere 1-2 min; aggiungere il latte freddo poco alla volta sbattendo e sobbollire 5 min mescolando, finché vela il cucchiaio. Regolare di sale, pepe e noce moscata e unire metà del formaggio.","Avvolgere ogni indivia in una fetta di prosciutto cotto e disporle, chiusura sotto, in una pirofila imburrata con il burro rimasto.","Versare sopra la besciamella e cospargere con il resto del formaggio.","Cuocere in forno 20-25 min, finché bolle ed è dorato, e far riposare 5 min prima di servire."]}}'::jsonb),
  ('e212f673-d1cc-44d6-b9a0-9ce0ec956d75'::uuid, '{"fr":{"title":"Asperges, œufs mollets et jambon","steps":["Cuire les pommes de terre dans de l''eau salée ; au bout de 10 min, y plonger les œufs et cuire encore 6 min, jusqu''à ce qu''un couteau s''enfonce facilement dans les pommes de terre. Refroidir les œufs 2 min dans de l''eau glacée et les écaler délicatement ; égoutter les pommes de terre et les garder au chaud.","Casser la base ligneuse des asperges ; éplucher les asperges blanches de la pointe jusqu''en bas, les vertes seulement sur le tiers inférieur.","Cuire les asperges dans une grande sauteuse d''eau bouillante salée jusqu''à ce que la pointe d''un couteau s''y enfonce facilement (vertes 4 à 6 min, blanches 10 à 15 min), puis les égoutter sur un torchon propre.","Fouetter la moutarde et le vinaigre avec du sel et du poivre, incorporer l''huile en fouettant, puis ajouter l''échalote et la ciboulette.","Disposer les asperges, les pommes de terre et les deux jambons dans les assiettes, poser les œufs dessus, les ouvrir et napper de vinaigrette."]},"it":{"title":"Asparagi con uova bazzotte e prosciutto","steps":["Lessare le patate in acqua salata; dopo 10 min calare anche le uova e cuocere altri 6 min, finché un coltello entra facilmente nelle patate. Raffreddare le uova 2 min in acqua ghiacciata e sgusciarle con delicatezza; scolare le patate e tenerle in caldo.","Spezzare la parte legnosa degli asparagi; pelare gli asparagi bianchi da sotto la punta fino in fondo, quelli verdi solo nel terzo inferiore.","Cuocere gli asparagi in una padella larga di acqua bollente salata finché la punta di un coltello entra facilmente (verdi 4-6 min, bianchi 10-15 min), poi scolarli su un canovaccio pulito.","Sbattere la senape e l''aceto con sale e pepe, incorporare l''olio sbattendo, poi unire lo scalogno e l''erba cipollina.","Disporre nei piatti asparagi, patate ed entrambi i prosciutti, appoggiare sopra le uova, aprirle e condire con la vinaigrette."]}}'::jsonb),
  ('ae0c6d16-3076-4f9e-be47-67c892c439c3'::uuid, '{"fr":{"title":"Petits pois à la française et hauts de cuisse de poulet rôtis","steps":["Préchauffer le four à 220 °C. Mélanger les pommes de terre sur une plaque avec la moitié de l''huile et une pincée de sel ; sécher les hauts de cuisse, les frotter du reste d''huile, de sel, de poivre et de thym et les poser peau dessus entre les pommes de terre.","Rôtir 25 à 30 min, jusqu''à ce que la peau du poulet soit croustillante, que le jus soit clair et que les pommes de terre soient dorées et tendres.","Pendant ce temps, faire fondre la moitié du beurre dans une sauteuse à feu moyen-doux (faire d''abord revenir les lardons si on en met) et faire fondre les oignons nouveaux 5 min sans coloration.","Ajouter les petits pois, la laitue, le sucre, le bouillon et une pincée de sel, couvrir et laisser mijoter doucement 10 min (15 à 20 min pour des pois frais), jusqu''à ce que les pois soient tendres et la laitue fondue.","Découvrir et laisser bouillonner 2 à 3 min jusqu''à ce qu''il ne reste que quelques cuillerées de liquide, puis incorporer le reste du beurre hors du feu.","Laisser reposer le poulet 5 min, ajouter une cuillerée de son jus de cuisson aux petits pois et servir avec les pommes de terre."]},"it":{"title":"Piselli alla francese con sovracosce di pollo arrosto","steps":["Scaldare il forno a 220°C. Condire le patate in una teglia con metà dell''olio e un pizzico di sale; asciugare le sovracosce, strofinarle con il resto dell''olio, sale, pepe e timo e disporle con la pelle verso l''alto tra le patate.","Arrostire 25-30 min, finché la pelle del pollo è croccante, i succhi sono chiari e le patate dorate e tenere.","Nel frattempo sciogliere metà del burro in una padella larga a fuoco medio-basso (rosolare prima la pancetta, se si usa) e appassire i cipollotti per 5 min senza farli colorire.","Aggiungere piselli, lattuga, zucchero, brodo e un pizzico di sale, coprire e cuocere dolcemente 10 min (15-20 min per piselli freschi), finché i piselli sono teneri e la lattuga si è sciolta.","Scoprire e far bollire 2-3 min finché restano solo pochi cucchiai di liquido, poi incorporare il burro rimasto fuori dal fuoco.","Far riposare il pollo 5 min, unire ai piselli un cucchiaio del suo fondo di cottura e servire con le patate."]}}'::jsonb),
  ('f009535a-d269-4003-bba7-327628ed59c1'::uuid, '{"fr":{"title":"Risotto au potiron et à la sauge","steps":["Porter le bouillon à frémissement dans une casserole et le garder chaud.","Faire fondre l''échalote dans l''huile et 10 g de beurre dans une sauteuse à feu moyen-doux pendant 4 min, puis ajouter la moitié du potiron et 3 feuilles de sauge hachées et cuire 5 min.","Ajouter le riz et le nacrer 2 min en remuant, jusqu''à ce que les bords deviennent translucides ; verser le vin et remuer jusqu''à évaporation.","Ajouter le bouillon louche par louche, en remuant souvent et en n''ajoutant la suivante que lorsque la précédente est presque absorbée ; au bout de 8 min, ajouter le reste du potiron. Cuire 17 à 18 min en tout, jusqu''à ce que le riz soit al dente et que le premier potiron ait fondu.","Pendant ce temps, faire frire les feuilles de sauge entières restantes dans 10 g de beurre dans une petite poêle environ 1 min, jusqu''à ce qu''elles soient croustillantes.","Hors du feu, incorporer vivement le reste du beurre et le parmesan avec un trait de bouillon pour que le risotto soit coulant (all''onda) ; assaisonner, couvrir et laisser reposer 2 min.","Servir parsemé de sauge croustillante et de poivre noir."]},"it":{"title":"Risotto zucca e salvia","steps":["Portare il brodo a sobbollire in una casseruola e tenerlo caldo.","Appassire lo scalogno nell''olio e 10 g di burro in una casseruola larga a fuoco medio-basso per 4 min, poi aggiungere metà della zucca e 3 foglie di salvia tritate e cuocere 5 min.","Aggiungere il riso e tostarlo 2 min mescolando, finché i bordi diventano traslucidi; sfumare con il vino e mescolare finché evapora.","Aggiungere il brodo un mestolo alla volta, mescolando spesso e versando il successivo solo quando il precedente è quasi assorbito; dopo 8 min unire il resto della zucca. Cuocere 17-18 min in tutto, finché il riso è al dente e la prima zucca si è sciolta.","Nel frattempo friggere le foglie di salvia intere rimaste in 10 g di burro in un padellino per circa 1 min, finché croccanti.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano e un goccio di brodo, perché il risotto sia all''onda; regolare di sale, coprire e far riposare 2 min.","Servire con la salvia croccante e pepe nero."]}}'::jsonb),
  ('0969a7fb-e600-4b76-83a3-93d7652f0ba9'::uuid, '{"fr":{"title":"Vignarola et œufs pochés","steps":["Préparer les artichauts : retirer les feuilles extérieures dures jusqu''aux feuilles pâles, couper le tiers supérieur, éplucher les tiges, couper en quartiers, retirer le foin éventuel et plonger dans de l''eau citronnée.","Si les fèves sont plus grosses qu''un ongle de pouce, les blanchir 1 min, les refroidir et retirer leur peau.","Faire fondre le guanciale dans la moitié de l''huile dans une sauteuse à feu moyen 4 min, ajouter les oignons nouveaux et cuire 3 min jusqu''à ce qu''ils soient tendres.","Ajouter les artichauts égouttés, remuer 2 min, verser le vin et laisser bouillonner 1 min ; ajouter le bouillon, couvrir et laisser mijoter 12 à 15 min, jusqu''à ce qu''un couteau s''enfonce facilement dans le fond des artichauts.","Ajouter les fèves et les petits pois, couvrir et cuire 5 min ; incorporer la laitue et la menthe et cuire encore 2 min jusqu''à ce qu''elles tombent. Assaisonner ; les légumes doivent baigner dans un peu de jus brillant.","Pendant ce temps, porter une casserole d''eau à petit frémissement avec le vinaigre, y glisser les œufs un par un depuis une tasse et pocher 3 min, puis les sortir à l''écumoire.","Répartir la vignarola dans des assiettes creuses, poser 2 œufs sur chaque portion, arroser du reste d''huile et ajouter poivre et pecorino selon l''envie ; servir avec du pain."]},"it":{"title":"Vignarola con uova in camicia","steps":["Pulire i carciofi: eliminare le foglie esterne dure fino a quelle chiare, tagliare il terzo superiore, pelare i gambi, tagliare in quarti, togliere l''eventuale barba e metterli in acqua acidulata con il succo di limone.","Se le fave sono più grandi di un''unghia del pollice, sbollentarle 1 min, raffreddarle e togliere la pellicina.","Rosolare il guanciale in metà dell''olio in una padella larga a fuoco medio per 4 min, aggiungere i cipollotti e cuocere 3 min finché morbidi.","Aggiungere i carciofi scolati, saltare 2 min, sfumare con il vino e far bollire 1 min; aggiungere il brodo, coprire e cuocere 12-15 min, finché un coltello entra facilmente nel fondo dei carciofi.","Unire fave e piselli, coprire e cuocere 5 min; aggiungere lattuga e menta e cuocere ancora 2 min finché appassiscono. Regolare di sale; le verdure devono restare in un po'' di fondo lucido.","Nel frattempo portare una pentola d''acqua a leggero sobbollire con l''aceto, farvi scivolare le uova una alla volta da una tazza e cuocerle in camicia 3 min, poi toglierle con una schiumarola.","Distribuire la vignarola in piatti fondi, adagiare 2 uova su ogni porzione, condire con l''olio rimasto e aggiungere pepe e pecorino a piacere; servire con il pane."]}}'::jsonb),
  ('d4edda52-05e2-4715-a6cf-c38c88a78de8'::uuid, '{"fr":{"title":"Gnudi épinards-ricotta, sauce tomate","steps":["Égoutter la ricotta 15 min dans une passoire.","Faire tomber les épinards 2 min dans une poêle sèche, les laisser refroidir, puis les presser très fort dans un torchon propre et les hacher finement.","Mélanger la ricotta, les épinards, l''œuf, 50 g de parmesan, un peu de muscade râpée, du sel, du poivre et 40 g de farine pour obtenir une pâte souple qui se tient tout juste.","Les mains farinées, former des boules de la taille d''une noix (16 à 18), les rouler dans le reste de farine, les poser sur un plateau fariné et réfrigérer 30 min.","Pour la sauce, chauffer l''huile avec l''ail à feu doux 1 min, ajouter le coulis de tomate et une pincée de sel et laisser mijoter 15 min ; incorporer le beurre et le basilic.","Cuire les gnudi en plusieurs fois dans une grande casserole d''eau salée à petit frémissement : ils remontent au bout de 2 min environ ; compter 1 min de plus et les sortir à l''écumoire. En tester un d''abord et ajouter une cuillerée de farine à la pâte s''il se défait.","Servir les gnudi dans la sauce avec le reste du parmesan."]},"it":{"title":"Gnudi di ricotta e spinaci al pomodoro","steps":["Scolare la ricotta in un colino per 15 min.","Appassire gli spinaci in una padella asciutta per 2 min, lasciarli raffreddare, poi strizzarli benissimo in un canovaccio pulito e tritarli finemente.","Mescolare ricotta, spinaci, uovo, 50 g di parmigiano, una grattata di noce moscata, sale, pepe e 40 g di farina fino a un impasto morbido che stia appena in forma.","Con le mani infarinate formare palline grandi come una noce (16-18), passarle nella farina rimasta, disporle su un vassoio infarinato e far riposare in frigo 30 min.","Per il sugo, scaldare l''olio con l''aglio a fuoco basso per 1 min, aggiungere la passata e un pizzico di sale e cuocere 15 min; unire il burro e il basilico.","Cuocere gli gnudi a gruppi in una pentola larga di acqua salata che sobbolle appena: salgono a galla dopo circa 2 min; lasciarli 1 min ancora e toglierli con una schiumarola. Provarne uno prima e, se si sfalda, aggiungere un cucchiaio di farina all''impasto.","Servire gli gnudi nel sugo con il parmigiano rimasto."]}}'::jsonb),
  ('95646b15-2042-4f16-9635-9e0c9dc5fe63'::uuid, '{"fr":{"title":"Fèves au jambon (habas con jamón)","steps":["Faire revenir doucement l''oignon dans 1,5 c. à soupe d''huile dans une sauteuse couverte à feu moyen-doux 8 min, jusqu''à ce qu''il soit tendre ; ajouter l''ail 1 min.","Ajouter le jambon et remuer 1 à 2 min, sans le laisser croustiller.","Ajouter les fèves et le vin, laisser bouillonner 1 min, puis ajouter 100 ml d''eau, couvrir et cuire à feu doux 10 à 15 min (environ 8 min pour des fèves surgelées), jusqu''à ce qu''elles soient tendres ; ajouter un peu d''eau si cela attache. Poivrer et saler très peu.","Faire frire les œufs dans le reste d''huile dans une petite poêle environ 3 min, jusqu''à ce que les bords soient croustillants et le jaune encore coulant.","Servir les fèves surmontées des œufs au plat et de quelques feuilles de menthe, avec du pain."]},"it":{"title":"Fave con jamón","steps":["Cuocere dolcemente la cipolla in 1,5 cucchiai d''olio in una padella con coperchio a fuoco medio-basso per 8 min, finché morbida; aggiungere l''aglio per 1 min.","Unire il prosciutto e mescolare 1-2 min, senza farlo diventare croccante.","Aggiungere le fave e il vino, far bollire 1 min, poi aggiungere 100 ml d''acqua, coprire e cuocere a fuoco basso 10-15 min (circa 8 min per le fave surgelate), finché tenere; aggiungere un goccio d''acqua se asciuga. Pepare e salare pochissimo.","Friggere le uova nell''olio rimasto in un padellino per circa 3 min, finché i bordi sono croccanti e il tuorlo ancora morbido.","Servire le fave con sopra le uova fritte e qualche foglia di menta, con il pane."]}}'::jsonb),
  ('a86e96e9-62db-412d-b135-71e84c0cbfef'::uuid, '{"fr":{"title":"Lahmacun","steps":["Mélanger la farine, la levure et le sel, ajouter 160 ml d''eau tiède et l''huile et pétrir 8 min jusqu''à obtenir une pâte lisse ; couvrir et laisser lever 1 h, jusqu''à ce qu''elle double de volume.","Presser dans les mains l''oignon, la tomate, le poivron et le piment hachés pour en retirer l''excès de jus, puis les mélanger avec l''agneau, l''ail, le persil, le concentré de tomate, le piment d''Alep, le paprika, le cumin, une pincée de sel et du poivre pour obtenir une farce facile à étaler.","Préchauffer le four à sa température maximale (250 °C) avec une plaque à l''intérieur, au moins 20 min.","Diviser la pâte en 4 et abaisser chaque morceau très finement sur un plan fariné en un ovale d''environ 25 à 30 cm.","Étaler finement un quart de la viande sur chacun, jusqu''à 1 cm du bord, en la pressant dans la pâte.","Glisser un ou deux lahmacun à la fois sur du papier cuisson sur la plaque chaude et cuire 7 à 9 min, jusqu''à ce que les bords soient croustillants et la viande cuite.","Mélanger l''oignon rouge émincé avec le sumac et le persil ; servir les lahmacun chauds avec cette salade d''oignon et du citron à presser, roulés pour les manger."]},"it":{"title":"Lahmacun","steps":["Mescolare farina, lievito e sale, aggiungere 160 ml di acqua tiepida e l''olio e impastare 8 min fino a un impasto liscio; coprire e far lievitare 1 h, finché raddoppia.","Strizzare con le mani cipolla, pomodoro, peperone e peperoncino tritati per eliminare il liquido in eccesso, poi mescolarli con l''agnello, l''aglio, il prezzemolo, il concentrato di pomodoro, il pepe di Aleppo, la paprika, il cumino, un pizzico di sale e pepe fino a una pasta spalmabile.","Scaldare il forno al massimo (250°C) con una teglia dentro, per almeno 20 min.","Dividere l''impasto in 4 e stendere ogni pezzo molto sottile, in un ovale di circa 25-30 cm, su un piano infarinato.","Spalmare sottilmente un quarto della carne su ciascuno, fino a 1 cm dal bordo, premendola nell''impasto.","Far scivolare uno o due lahmacun alla volta su carta forno sulla teglia calda e cuocere 7-9 min, finché i bordi sono croccanti e la carne è cotta.","Condire la cipolla rossa affettata con sumac e prezzemolo; servire i lahmacun caldi con l''insalata di cipolla e limone da spremere, arrotolati per mangiarli."]}}'::jsonb),
  ('73fdf41a-9d25-4cb3-bfb6-6e7c3c74026a'::uuid, '{"fr":{"title":"Hünkar beğendi (agneau sur purée d''aubergines)","steps":["Faire dorer l''agneau dans l''huile dans une cocotte à feu vif environ 5 min, en deux fois.","Ajouter l''oignon et cuire 5 min, puis l''ail et le poivron vert 2 min et le concentré de tomate 1 min. Ajouter les tomates, 300 ml d''eau chaude, du sel et du poivre, couvrir et laisser mijoter doucement 75 à 90 min, jusqu''à ce que l''agneau soit tendre et la sauce épaisse ; ajouter un peu d''eau si besoin.","Pendant ce temps, piquer les aubergines et les griller directement sur la flamme du gaz 10 à 15 min, ou sous le gril du four à 240 °C 25 à 30 min, en les retournant, jusqu''à ce qu''elles s''affaissent et noircissent.","Récupérer la chair, la laisser 5 min dans de l''eau citronnée, la presser et la hacher très finement.","Faire fondre le beurre dans une casserole, ajouter la farine et cuire 1 à 2 min, puis verser le lait petit à petit en fouettant et cuire 4 à 5 min jusqu''à épaississement.","Incorporer l''aubergine et cuire 3 à 4 min, puis ajouter le fromage, un peu de muscade et du sel et battre jusqu''à ce que ce soit lisse et crémeux.","Étaler le beğendi dans les assiettes, déposer l''agneau et sa sauce au centre et saupoudrer de piment d''Alep."]},"it":{"title":"Hünkar beğendi (agnello su crema di melanzane)","steps":["Rosolare l''agnello nell''olio in una casseruola pesante a fuoco vivo per circa 5 min, in due volte.","Aggiungere la cipolla e cuocere 5 min, poi l''aglio e il peperone verde per 2 min e il concentrato per 1 min. Unire i pomodori, 300 ml di acqua calda, sale e pepe, coprire e cuocere dolcemente 75-90 min, finché l''agnello è tenero e il sugo denso; aggiungere un goccio d''acqua se serve.","Nel frattempo bucherellare le melanzane e abbrustolirle direttamente sulla fiamma del gas per 10-15 min, o sotto il grill a 240°C per 25-30 min, girandole, finché sono afflosciate e annerite.","Prelevare la polpa, lasciarla 5 min in acqua e succo di limone, strizzarla e tritarla finissima.","Sciogliere il burro in un pentolino, unire la farina per 1-2 min, poi aggiungere il latte poco alla volta sbattendo e cuocere 4-5 min, finché si addensa.","Incorporare la melanzana e cuocere 3-4 min, poi aggiungere il formaggio, un po'' di noce moscata e sale e sbattere fino a una crema liscia.","Stendere il beğendi nei piatti, mettere al centro l''agnello con il suo sugo e cospargere di pepe di Aleppo."]}}'::jsonb),
  ('ee925082-69bb-44b0-940b-cb647bfd021f'::uuid, '{"fr":{"title":"Kebbé au four (kibbeh bil sayniyeh)","steps":["Rincer le boulgour, le couvrir d''eau froide et le laisser tremper 15 min, puis l''égoutter et le presser très fort dans les mains.","Pour la farce, faire fondre l''oignon haché dans la moitié de l''huile à feu moyen 8 min ; ajouter les 120 g d''agneau et faire dorer 6 à 8 min en l''émiettant. Assaisonner avec 0,5 c. à café de piment de la Jamaïque, 0,5 c. à café de cannelle, du sel et du poivre. Faire griller les pignons à sec dans une poêle 2 à 3 min et les incorporer.","Pour la pâte, mixer le boulgour avec les 200 g d''agneau, l''oignon râpé, le reste du piment de la Jamaïque et de la cannelle, le cumin, du sel et 2 à 3 c. à soupe d''eau glacée environ 2 min (ou pétrir 5 min à la main) jusqu''à obtenir une pâte lisse.","Préchauffer le four à 190 °C et huiler un plat de 20 cm. Les mains mouillées, étaler la moitié de la pâte en une couche régulière d''environ 1 cm au fond du plat.","Répartir la farce dessus, couvrir avec le reste de la pâte en morceaux aplatis et lisser le dessus avec les mains mouillées.","Quadriller le dessus en losanges jusqu''au fond, passer un couteau le long du bord et arroser du beurre fondu et du reste d''huile.","Cuire 35 à 40 min, jusqu''à ce que ce soit bien doré avec des bords croustillants ; laisser reposer 10 min et servir avec le yaourt."]},"it":{"title":"Kibbeh al forno (kibbeh bil sayniyeh)","steps":["Sciacquare il bulgur, coprirlo con acqua fredda e lasciarlo in ammollo 15 min, poi scolarlo e strizzarlo benissimo con le mani.","Per il ripieno, appassire la cipolla tritata in metà dell''olio a fuoco medio per 8 min; aggiungere i 120 g di agnello e rosolare 6-8 min sgranandolo. Condire con 0,5 cucchiaino di pimento, 0,5 cucchiaino di cannella, sale e pepe. Tostare i pinoli in una padella asciutta 2-3 min e unirli.","Per il guscio, frullare il bulgur con i 200 g di agnello, la cipolla grattugiata, il resto del pimento e della cannella, il cumino, sale e 2-3 cucchiai di acqua ghiacciata per circa 2 min (o impastare 5 min a mano) fino a una pasta liscia.","Scaldare il forno a 190°C e ungere una pirofila da 20 cm. Con le mani bagnate, stendere metà del guscio sul fondo in uno strato uniforme di circa 1 cm.","Distribuire sopra il ripieno, coprire con il resto del guscio a pezzi appiattiti e lisciare la superficie con le mani bagnate.","Incidere la superficie a rombi fino al fondo, passare un coltello lungo il bordo e versare sopra il burro fuso e l''olio rimasto.","Cuocere 35-40 min, finché ben dorato con i bordi croccanti; far riposare 10 min e servire con lo yogurt."]}}'::jsonb),
  ('b7df0ef0-eeb6-4a50-95f6-c661bca1e47d'::uuid, '{"fr":{"title":"Poulet aux petits pois à la grecque (kotopoulo me araka)","steps":["Saler et poivrer le poulet et le faire dorer dans l''huile dans une grande cocotte à feu moyen-vif, environ 4 min par face ; réserver.","Faire fondre l''oignon et les oignons nouveaux dans la même cocotte 5 min, puis ajouter l''ail 1 min et le concentré de tomate 1 min.","Ajouter les tomates et 250 ml d''eau, remettre le poulet, couvrir et laisser mijoter 20 min.","Ajouter les pommes de terre et les carottes avec assez d''eau pour presque les couvrir, assaisonner et laisser mijoter 15 min à couvert.","Ajouter les petits pois et la plus grande partie de l''aneth et laisser mijoter 15 min à découvert, jusqu''à ce que les pois soient fondants, les pommes de terre tendres et la sauce réduite et brillante d''huile.","Laisser reposer 10 min hors du feu, parsemer du reste d''aneth et servir tiède, avec de la feta si on le souhaite."]},"it":{"title":"Pollo con piselli alla greca (kotopoulo me araka)","steps":["Salare e pepare il pollo e rosolarlo nell''olio in una pentola larga a fuoco medio-alto, circa 4 min per lato; mettere da parte.","Appassire la cipolla e i cipollotti nella stessa pentola per 5 min, poi aggiungere l''aglio per 1 min e il concentrato per 1 min.","Unire i pomodori e 250 ml d''acqua, rimettere il pollo, coprire e cuocere 20 min.","Aggiungere patate e carote con acqua sufficiente quasi a coprirle, salare e cuocere coperto 15 min.","Unire i piselli e quasi tutto l''aneto e cuocere scoperto 15 min, finché i piselli sono morbidi, le patate tenere e il sugo ristretto e lucido d''olio.","Far riposare 10 min fuori dal fuoco, cospargere con l''aneto rimasto e servire tiepido, con la feta se piace."]}}'::jsonb),
  ('10a782bb-b319-44ce-9ab0-8507659369f8'::uuid, '{"fr":{"title":"Œufs aux épinards à la turque (ıspanaklı yumurta)","steps":["Mélanger le yaourt avec l''ail et une pincée de sel et réserver.","Faire fondre l''oignon dans l''huile et la moitié du beurre dans une grande sauteuse avec couvercle à feu moyen 5 min ; ajouter le concentré de tomate, le cumin et la moitié du piment d''Alep 1 min, puis la tomate râpée 2 min.","Ajouter les épinards par poignées et remuer jusqu''à ce qu''ils tombent, 2 à 3 min ; assaisonner et faire évaporer la plus grande partie du liquide 1 à 2 min.","Former 4 creux, casser un œuf dans chacun, assaisonner, couvrir et cuire à feu doux 5 à 7 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Faire fondre le reste du beurre dans une petite poêle avec le reste du piment d''Alep jusqu''à ce qu''il grésille, environ 30 s.","Servir le yaourt à l''ail à côté, arroser les œufs de beurre pimenté et accompagner de pain."]},"it":{"title":"Uova con spinaci alla turca (ıspanaklı yumurta)","steps":["Mescolare lo yogurt con l''aglio e un pizzico di sale e mettere da parte.","Appassire la cipolla nell''olio e metà del burro in una padella larga con coperchio a fuoco medio per 5 min; aggiungere il concentrato, il cumino e metà del pepe di Aleppo per 1 min, poi il pomodoro grattugiato per 2 min.","Aggiungere gli spinaci a manciate e mescolare finché appassiscono, 2-3 min; regolare di sale e far evaporare quasi tutto il liquido per 1-2 min.","Formare 4 incavi, rompere un uovo in ciascuno, salare, coprire e cuocere a fuoco basso 5-7 min, finché gli albumi sono rappresi e i tuorli ancora morbidi.","Sciogliere il burro rimasto in un padellino con il resto del pepe di Aleppo finché sfrigola, circa 30 s.","Servire lo yogurt all''aglio a parte, versare il burro piccante sulle uova e accompagnare con il pane."]}}'::jsonb),
  ('66f1f64b-259c-441a-8fe9-bef4680372ca'::uuid, '{"fr":{"title":"Épaule d''agneau façon méchoui","steps":["Préchauffer le four à 160 °C. Inciser légèrement le gras de l''agneau et le frotter entièrement avec le beurre écrasé avec l''ail, 2 c. à café de cumin, le paprika, la coriandre et 1 c. à café de sel.","Poser l''agneau dans un plat juste à sa taille avec 150 ml d''eau, couvrir hermétiquement de papier aluminium et rôtir 3 h en arrosant de jus toutes les heures.","Découvrir, monter le four à 210 °C et rôtir encore 25 à 30 min en arrosant deux fois, jusqu''à ce que la viande soit bien brune et se détache facilement de l''os.","Laisser reposer 10 min sous une feuille d''aluminium posée sans serrer.","Pendant ce temps, mélanger 1 c. à café de cumin et 1 c. à café de sel pour tremper la viande, et mélanger la tomate, l''oignon et le persil avec l''huile et une pincée de sel si on fait la salade.","Effilocher la viande avec deux fourchettes, l''arroser du jus de cuisson et servir avec le sel au cumin, le pain et la salade."]},"it":{"title":"Spalla d''agnello al forno in stile méchoui","steps":["Scaldare il forno a 160°C. Incidere leggermente il grasso dell''agnello e massaggiarlo ovunque con il burro schiacciato con l''aglio, 2 cucchiaini di cumino, la paprika, il coriandolo e 1 cucchiaino di sale.","Mettere l''agnello in una teglia della sua misura con 150 ml d''acqua, coprire bene con alluminio e arrostire 3 h, irrorando con il fondo ogni ora.","Scoprire, alzare il forno a 210°C e arrostire ancora 25-30 min irrorando due volte, finché è ben bruno e la carne si stacca facilmente dall''osso.","Far riposare 10 min sotto un foglio di alluminio appoggiato.","Nel frattempo mescolare 1 cucchiaino di cumino con 1 cucchiaino di sale per intingere, e condire pomodoro, cipolla e prezzemolo con l''olio e un pizzico di sale se si fa l''insalata.","Sfilacciare la carne con due forchette, bagnarla con il fondo di cottura e servire con il sale al cumino, il pane e l''insalata."]}}'::jsonb),
  ('c51f2da3-e80a-4036-a893-3720852ff2cb'::uuid, '{"fr":{"title":"Lablabi (soupe tunisienne de pois chiches)","steps":["Écraser l''ail avec 1 c. à café de sel et 1,5 c. à café de cumin pour obtenir une pâte.","Chauffer 1 c. à soupe d''huile dans une casserole, faire revenir la pâte d''ail 1 min, puis ajouter les pois chiches, le bouillon et la harissa et laisser frémir 15 min ; écraser quelques pois chiches contre la paroi pour épaissir un peu le bouillon.","Pendant ce temps, plonger les œufs 6 min dans l''eau bouillante, les refroidir à l''eau froide et les écaler.","Répartir le pain déchiré dans 2 bols creux.","Verser les pois chiches et le bouillon à la louche sur le pain et laisser imbiber 1 min.","Garnir chaque bol d''un œuf ouvert, des câpres, du thon et du persil si on en met, du reste de cumin, d''un filet de citron et du reste d''huile, avec de la harissa en plus à mélanger."]},"it":{"title":"Lablabi (zuppa tunisina di ceci)","steps":["Pestare l''aglio con 1 cucchiaino di sale e 1,5 cucchiaini di cumino fino a ottenere una pasta.","Scaldare 1 cucchiaio d''olio in una pentola, soffriggere la pasta d''aglio 1 min, poi aggiungere ceci, brodo e harissa e cuocere 15 min; schiacciare qualche cece contro la parete per addensare un po'' il brodo.","Nel frattempo calare le uova in acqua bollente per 6 min, raffreddarle in acqua fredda e sgusciarle.","Mettere il pane spezzettato in 2 ciotole fonde.","Versare con il mestolo ceci e brodo sul pane e lasciarlo inzuppare 1 min.","Completare ogni ciotola con un uovo aperto, i capperi, il tonno e il prezzemolo se si usano, il cumino rimasto, una spruzzata di limone e il resto dell''olio, con altra harissa da mescolare."]}}'::jsonb),
  ('4ee738a3-579e-4c06-8cfa-0037f8174975'::uuid, '{"fr":{"title":"Loubia à l''agneau","steps":["Faire dorer l''agneau dans l''huile dans une cocotte à feu moyen-vif 5 min, puis ajouter l''oignon et cuire encore 5 min.","Incorporer l''ail, le concentré de tomate, le paprika, le cumin et le piment en poudre 1 min.","Ajouter les tomates, le laurier, 700 ml d''eau, du sel et du poivre ; couvrir et laisser mijoter doucement 75 min, jusqu''à ce que l''agneau soit tendre. (Avec des haricots secs trempés, les ajouter maintenant et compter 1 h 30.)","Ajouter les haricots en conserve et laisser mijoter 20 min à découvert, jusqu''à ce que la sauce soit épaisse et les haricots crémeux.","Laisser reposer 5 min, parsemer de coriandre et servir avec du pain."]},"it":{"title":"Loubia con agnello","steps":["Rosolare l''agnello nell''olio in una casseruola pesante a fuoco medio-alto per 5 min, poi aggiungere la cipolla e cuocere altri 5 min.","Unire aglio, concentrato, paprika, cumino e peperoncino in polvere per 1 min.","Aggiungere i pomodori, l''alloro, 700 ml d''acqua, sale e pepe; coprire e cuocere dolcemente 75 min, finché l''agnello è tenero. (Con fagioli secchi ammollati, aggiungerli ora e calcolare 1 h 30.)","Unire i fagioli in scatola e cuocere scoperto 20 min, finché il sugo è denso e i fagioli cremosi.","Far riposare 5 min, cospargere di coriandolo e servire con il pane."]}}'::jsonb),
  ('01b1b8cb-5f7b-49dc-abb6-34d82d55a942'::uuid, '{"fr":{"title":"Korma de poulet","steps":["Mélanger le poulet avec la moitié du yaourt, l''ail, le gingembre et 0,5 c. à café de sel et laisser mariner 30 min.","Faire tremper les noix de cajou 15 min dans de l''eau chaude. Faire frire les oignons dans l''huile et le beurre dans une sauteuse à fond épais à feu moyen 12 à 15 min en remuant, jusqu''à ce qu''ils soient bien dorés ; en retirer la moitié.","Mixer les oignons retirés avec les noix de cajou égouttées, le reste du yaourt et 4 c. à soupe d''eau pour obtenir une pâte lisse.","Faire revenir la cardamome, les clous de girofle, la cannelle et le laurier avec le reste des oignons 30 s, ajouter le poulet et cuire 5 min jusqu''à ce qu''il soit blanc à l''extérieur, puis ajouter la coriandre en poudre et le piment 1 min.","Ajouter la pâte oignon-cajou et 150 ml d''eau et laisser mijoter à couvert à feu doux 20 à 25 min en remuant de temps en temps, jusqu''à ce que le poulet soit tendre et la sauce épaisse et luisante d''huile ; ne pas laisser bouillir fort pour que le yaourt ne tranche pas.","Pendant ce temps, rincer le riz, le cuire à couvert dans 1,5 fois son volume d''eau salée 12 min et le laisser reposer 5 min hors du feu.","Incorporer le garam masala et la crème (si on en met) au korma, rectifier l''assaisonnement et servir avec le riz et la coriandre."]},"it":{"title":"Korma di pollo","steps":["Mescolare il pollo con metà dello yogurt, l''aglio, lo zenzero e 0,5 cucchiaino di sale e lasciar marinare 30 min.","Mettere in ammollo gli anacardi in acqua calda per 15 min. Friggere le cipolle nell''olio e nel burro in una padella dal fondo spesso a fuoco medio per 12-15 min mescolando, finché ben dorate; toglierne metà.","Frullare le cipolle tolte con gli anacardi scolati, il resto dello yogurt e 4 cucchiai d''acqua fino a una crema liscia.","Soffriggere cardamomo, chiodi di garofano, cannella e alloro con le cipolle rimaste per 30 s, aggiungere il pollo e cuocere 5 min finché è opaco fuori, poi unire il coriandolo in polvere e il peperoncino per 1 min.","Aggiungere la crema di cipolla e anacardi e 150 ml d''acqua e cuocere coperto a fuoco basso 20-25 min mescolando ogni tanto, finché il pollo è tenero e il sugo denso e lucido d''olio; non farlo bollire forte perché lo yogurt non impazzisca.","Nel frattempo sciacquare il riso, cuocerlo coperto in 1,5 volte il suo volume di acqua salata per 12 min e farlo riposare 5 min fuori dal fuoco.","Unire al korma il garam masala e la panna (se si usa), regolare di sale e servire con il riso e il coriandolo."]}}'::jsonb),
  ('e99891d7-dc00-4d5a-a242-8694b13603cd'::uuid, '{"fr":{"title":"Tikka de poisson","steps":["Sécher le poisson, l''arroser du jus d''un demi-citron, saler légèrement et laisser reposer 10 min.","Faire griller la farine de pois chiche à sec dans une poêle 1 à 2 min jusqu''à ce qu''elle sente la noisette, la laisser refroidir, puis la mélanger avec le yaourt grec, le gingembre, l''ail, le piment, le garam masala, le curcuma, l''ajwain, la moitié de l''huile et 0,5 c. à café de sel.","Enrober délicatement le poisson de marinade et laisser 30 min au réfrigérateur (pas plus d''1 h).","Préchauffer le four à 230 °C en position gril. Enfiler le poisson sur des brochettes, ou l''espacer sur une grille huilée posée sur une plaque tapissée d''aluminium.","Cuire 8 à 10 min, badigeonner du reste d''huile, puis passer encore 2 à 3 min sous le gril, jusqu''à ce que les bords soient grillés et que le poisson s''effeuille.","Pendant ce temps, mixer la menthe, la majeure partie de la coriandre, le piment, le yaourt nature et une pincée de sel en chutney, et mélanger la tomate, le concombre et l''oignon avec le reste du jus de citron, la coriandre restante et du sel.","Saupoudrer le tikka de chaat masala et servir avec le chutney, la salade et le pain chaud."]},"it":{"title":"Tikka di pesce","steps":["Asciugare il pesce, condirlo con il succo di mezzo limone e un pizzico di sale e lasciarlo 10 min.","Tostare la farina di ceci in una padella asciutta 1-2 min finché profuma di nocciola, lasciarla raffreddare, poi mescolarla con lo yogurt greco, lo zenzero, l''aglio, il peperoncino, il garam masala, la curcuma, l''ajwain, metà dell''olio e 0,5 cucchiaino di sale.","Avvolgere delicatamente il pesce nella marinata e lasciarlo in frigo 30 min (non più di 1 h).","Scaldare il forno a 230°C con il grill acceso. Infilare il pesce sugli spiedini, o distanziarlo su una griglia unta appoggiata su una teglia foderata di alluminio.","Cuocere 8-10 min, spennellare con l''olio rimasto, poi grigliare ancora 2-3 min, finché i bordi sono abbrustoliti e il pesce si sfalda.","Nel frattempo frullare menta, quasi tutto il coriandolo, peperoncino, yogurt bianco e un pizzico di sale in un chutney, e condire pomodoro, cetriolo e cipolla con il succo di limone rimasto, il coriandolo restante e sale.","Cospargere il tikka di chaat masala e servire con il chutney, l''insalata e il pane caldo."]}}'::jsonb),
  ('d74e1f57-ab1d-49a7-8beb-1c44ff52a3ed'::uuid, '{"fr":{"title":"Khichdi de moong dal aux œufs au plat","steps":["Rincer ensemble le dal et le riz dans plusieurs eaux jusqu''à ce que l''eau soit claire, puis égoutter.","Chauffer 20 g de ghee dans une casserole à fond épais à feu moyen, ajouter le cumin et le laisser grésiller 30 s, puis ajouter le gingembre et le piment 30 s et la tomate 2 min ; incorporer le curcuma.","Ajouter le dal et le riz et remuer 1 min, puis verser 900 ml d''eau avec 1 c. à café de sel. Porter à ébullition, couvrir et laisser mijoter à feu doux 20 à 25 min en remuant de temps en temps, jusqu''à ce que tout soit tendre et que le khichdi ait la texture d''un porridge épais ; ajouter de l''eau chaude pour le détendre.","Faire frire les œufs dans le reste de ghee dans une poêle environ 3 min, jusqu''à ce que les bords soient croustillants, et saupoudrer de piment et d''une pincée de sel.","Servir le khichdi surmonté des œufs, avec du yaourt et de la coriandre."]},"it":{"title":"Khichdi di moong dal con uova fritte","steps":["Sciacquare insieme dal e riso in più acque finché l''acqua è limpida, poi scolare.","Scaldare 20 g di ghee in una pentola dal fondo spesso a fuoco medio, aggiungere il cumino e farlo sfrigolare 30 s, poi unire zenzero e peperoncino per 30 s e il pomodoro per 2 min; aggiungere la curcuma.","Unire dal e riso e mescolare 1 min, poi versare 900 ml d''acqua con 1 cucchiaino di sale. Portare a bollore, coprire e cuocere a fuoco basso 20-25 min mescolando ogni tanto, finché tutto è morbido e il khichdi ha la consistenza di un porridge denso; aggiungere acqua calda per renderlo più morbido.","Friggere le uova nel ghee rimasto in una padella per circa 3 min, finché i bordi sono croccanti, e cospargerle di peperoncino e un pizzico di sale.","Servire il khichdi con sopra le uova, con yogurt e coriandolo."]}}'::jsonb),
  ('0a6c1c2e-111e-451b-8264-41a7301d11c7'::uuid, '{"fr":{"title":"Saumon, asperges et pommes de terre nouvelles au four","steps":["Préchauffer le four à 220 °C. Cuire les pommes de terre 8 min dans de l''eau salée, les égoutter et les laisser sécher 2 min.","Mélanger les pommes de terre sur une grande plaque avec 1 c. à soupe d''huile, du sel et du poivre et rôtir 10 min.","Casser la base ligneuse des asperges et les mélanger avec 1 c. à soupe d''huile, l''ail et une pincée de sel.","Repousser les pommes de terre sur les côtés, ajouter les asperges et poser le saumon dessus, peau dessous ; assaisonner et couvrir des rondelles de citron.","Rôtir 12 à 15 min, jusqu''à ce que le saumon soit opaque et s''effeuille tout juste et que les asperges soient tendres.","Mélanger l''aneth, le jus de citron, la moutarde et le reste d''huile avec une pincée de sel.","Napper le saumon et les légumes de cette sauce et servir directement sur la plaque."]},"it":{"title":"Teglia di salmone, asparagi e patate novelle","steps":["Scaldare il forno a 220°C. Lessare le patate in acqua salata per 8 min, scolarle e lasciarle asciugare 2 min.","Condire le patate su una teglia grande con 1 cucchiaio d''olio, sale e pepe e arrostire 10 min.","Spezzare la parte legnosa degli asparagi e condirli con 1 cucchiaio d''olio, l''aglio e un pizzico di sale.","Spostare le patate ai lati, aggiungere gli asparagi e adagiarvi il salmone con la pelle sotto; salare e coprire con le fette di limone.","Arrostire 12-15 min, finché il salmone è opaco e si sfalda appena e gli asparagi sono teneri.","Mescolare aneto, succo di limone, senape e olio rimasto con un pizzico di sale.","Versare il condimento su salmone e verdure e servire direttamente dalla teglia."]}}'::jsonb),
  ('dfafcd91-634f-43f4-8416-3ef33e412692'::uuid, '{"fr":{"title":"Soupe aigre-piquante au porc et au tofu","steps":["Faire tremper les champignons noirs 20 min dans de l''eau chaude, puis les égoutter, retirer les parties dures et les émincer finement.","Lancer le riz : le cuire à couvert dans 1,5 fois son volume d''eau 12 min, puis le laisser reposer 5 min hors du feu. Mélanger le porc avec 1 c. à café de sauce soja et 1 c. à café de fécule et laisser reposer pendant la découpe du reste.","Porter le bouillon à ébullition dans une casserole, ajouter les champignons noirs, les shiitakés et les pousses de bambou et laisser frémir 3 min.","Ajouter le porc en remuant pour séparer les lanières et cuire 2 min jusqu''à ce qu''il pâlisse ; ajouter le tofu, le reste de sauce soja, la sauce soja noire et le sucre.","Délayer le reste de fécule dans 4 c. à soupe d''eau froide, l''incorporer à la soupe frémissante et cuire 1 min jusqu''à ce qu''elle épaississe légèrement et devienne brillante.","Baisser le feu et verser les œufs battus en filet en remuant lentement dans un seul sens pour former des rubans ; attendre 30 secondes.","Hors du feu, ajouter le vinaigre noir, le poivre blanc et l''huile de sésame. Goûter et rectifier en sel, vinaigre ou poivre : la soupe doit être nettement acidulée et poivrée.","Servir dans des bols, parsemer d''oignon nouveau et accompagner du riz."]},"it":{"title":"Zuppa agropiccante con maiale e tofu","steps":["Ammollare i funghi orecchio di Giuda in acqua calda per 20 min, poi scolarli, eliminare le parti dure e affettarli finemente.","Avviare il riso: cuocerlo coperto in 1,5 volte il suo volume d''acqua per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco. Condire il maiale con 1 cucchiaino di salsa di soia e 1 cucchiaino di amido e lasciarlo riposare mentre si taglia il resto.","Portare a bollore il brodo in una pentola, aggiungere i funghi orecchio di Giuda, gli shiitake e i germogli di bambù e cuocere a fuoco lento 3 min.","Aggiungere il maiale mescolando per separare le listarelle e cuocere 2 min finché diventa chiaro; unire il tofu, il resto della salsa di soia, la salsa di soia scura e lo zucchero.","Stemperare il resto dell''amido in 4 cucchiai d''acqua fredda, versarlo nella zuppa che sobbolle e cuocere 1 min finché si addensa leggermente e diventa lucida.","Abbassare il fuoco e versare le uova sbattute a filo mescolando lentamente in un solo senso, così si rapprendono a nastri; attendere 30 secondi.","Fuori dal fuoco, unire l''aceto nero, il pepe bianco e l''olio di sesamo. Assaggiare e regolare di sale, aceto o pepe: deve essere decisamente acida e pepata.","Servire nelle ciotole, cospargere di cipollotto e accompagnare con il riso."]}}'::jsonb),
  ('37907ecd-1bda-4dbd-9ff7-457883f41468'::uuid, '{"fr":{"title":"Boulettes tête de lion au chou chinois","steps":["Mélanger le porc avec le gingembre, les deux tiers de l''oignon nouveau, le vin de riz, 1 c. à soupe de sauce soja, le sucre, l''œuf, 1 c. à soupe de fécule, le poivre blanc et 0,5 c. à café de sel. Remuer vigoureusement dans un seul sens 3 à 4 min jusqu''à obtenir une farce collante et élastique.","Les mains mouillées, former 4 grosses boulettes d''environ 90 g.","Chauffer l''huile dans une cocotte à feu moyen et dorer doucement les boulettes sur toutes les faces, 6 à 8 min ; les retirer.","Faire revenir les grosses côtes de chou 2 min dans la même matière grasse, poser les boulettes dessus et les recouvrir des feuilles.","Verser le bouillon, le reste de sauce soja et la sauce soja noire. Porter à ébullition, couvrir et laisser mijoter à feu doux 35 à 40 min, jusqu''à ce que les boulettes soient tendres et le chou fondant.","Pendant ce temps, rincer le riz et le cuire à couvert dans 1,5 fois son volume d''eau 12 min, puis le laisser reposer 5 min hors du feu.","Répartir les boulettes et le chou dans des bols. Lier le bouillon avec le reste de fécule délayé dans 2 c. à soupe d''eau, faire bouillir 1 min, puis ajouter l''huile de sésame.","Napper de sauce, parsemer du reste d''oignon nouveau et servir avec le riz."]},"it":{"title":"Polpette testa di leone con cavolo cinese","steps":["Mescolare il maiale con lo zenzero, due terzi del cipollotto, il vino di riso, 1 cucchiaio di salsa di soia, lo zucchero, l''uovo, 1 cucchiaio di amido, il pepe bianco e 0,5 cucchiaino di sale. Lavorare energicamente in un solo senso per 3-4 min finché l''impasto è appiccicoso ed elastico.","Con le mani bagnate formare 4 grandi polpette da circa 90 g.","Scaldare l''olio in una casseruola a fuoco medio e rosolare delicatamente le polpette su tutti i lati, 6-8 min; toglierle.","Saltare le coste spesse del cavolo nello stesso grasso per 2 min, adagiarvi sopra le polpette e coprirle con le foglie.","Versare il brodo, il resto della salsa di soia e la salsa di soia scura. Portare a bollore, coprire e cuocere a fuoco basso 35-40 min, finché le polpette sono tenere e il cavolo morbido.","Nel frattempo sciacquare il riso e cuocerlo coperto in 1,5 volte il suo volume d''acqua per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Disporre polpette e cavolo nelle ciotole. Addensare il brodo con il resto dell''amido sciolto in 2 cucchiai d''acqua, far bollire 1 min, poi aggiungere l''olio di sesamo.","Versare la salsa sopra, cospargere con il cipollotto rimasto e servire con il riso."]}}'::jsonb),
  ('55043b76-d1aa-4e87-ad98-d03ada43f562'::uuid, '{"fr":{"title":"Crevettes sautées aux asperges","steps":["Lancer le riz : le cuire à couvert dans 1,5 fois son volume d''eau 12 min, puis le laisser reposer 5 min hors du feu.","Mélanger les crevettes avec une pincée de sel, 1 c. à café de fécule et la moitié du vin de riz. Mélanger dans un bol la sauce d''huître, la sauce soja, le sucre, le poivre blanc, le reste de fécule et 4 c. à soupe d''eau.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif jusqu''à ce qu''elle fume et saisir les crevettes environ 1 min par face, jusqu''à ce qu''elles soient juste roses ; les réserver sur une assiette.","Ajouter le reste d''huile, puis l''ail et le gingembre 15 secondes, puis les asperges avec une pincée de sel. Faire sauter 2 min, ajouter 2 c. à soupe d''eau et poursuivre 1 min jusqu''à ce qu''elles soient vert vif et encore croquantes.","Remettre les crevettes, verser le reste de vin de riz sur le bord chaud du wok, ajouter la sauce et faire sauter 30 à 60 secondes jusqu''à ce que ce soit brillant.","Hors du feu, arroser d''huile de sésame et servir avec le riz."]},"it":{"title":"Gamberi saltati con asparagi","steps":["Avviare il riso: cuocerlo coperto in 1,5 volte il suo volume d''acqua per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Condire i gamberi con un pizzico di sale, 1 cucchiaino di amido e metà del vino di riso. In una ciotola mescolare la salsa d''ostriche, la salsa di soia, lo zucchero, il pepe bianco, il resto dell''amido e 4 cucchiai d''acqua.","Scaldare 1 cucchiaio d''olio nel wok a fuoco vivo finché fuma e scottare i gamberi circa 1 min per lato, finché sono appena rosa; metterli da parte su un piatto.","Aggiungere il resto dell''olio, poi aglio e zenzero per 15 secondi, poi gli asparagi con un pizzico di sale. Saltare 2 min, aggiungere 2 cucchiai d''acqua e saltare ancora 1 min finché sono verde brillante e croccanti.","Rimettere i gamberi, versare il resto del vino di riso sul bordo caldo del wok, unire la salsa e saltare 30-60 secondi finché tutto è lucido.","Fuori dal fuoco condire con l''olio di sesamo e servire con il riso."]}}'::jsonb),
  ('ee587622-6ee2-467e-8fda-bb22df3a49a0'::uuid, '{"fr":{"title":"Yakisoba au porc","steps":["Mélanger dans un bol la sauce Worcestershire, la sauce d''huître, le ketchup, la sauce soja et le sucre.","Cuire les nouilles sèches à l''eau bouillante 1 min de moins que l''indication du paquet, les égoutter, les rincer à l''eau froide et les mélanger avec quelques gouttes d''huile. Les nouilles yakisoba fraîches se détachent simplement sous l''eau chaude.","Chauffer l''huile dans une grande poêle ou un wok à feu moyen-vif et faire dorer la poitrine de porc 3 à 4 min jusqu''à ce que les bords soient croustillants ; poivrer.","Ajouter l''oignon et la carotte et faire sauter 2 min, puis le chou 2 min jusqu''à ce qu''il commence à tomber.","Ajouter les nouilles, les germes de soja et 2 c. à soupe d''eau et mélanger 2 min pour réchauffer.","Verser la sauce, ajouter l''oignon nouveau et faire sauter à feu vif 1 à 2 min jusqu''à ce que les nouilles soient uniformément colorées et accrochent légèrement.","Servir garni de gingembre mariné rouge."]},"it":{"title":"Yakisoba con maiale","steps":["Mescolare in una ciotolina la salsa Worcestershire, la salsa d''ostriche, il ketchup, la salsa di soia e lo zucchero.","Cuocere i noodles secchi in acqua bollente 1 min meno di quanto indicato sulla confezione, scolarli, sciacquarli sotto l''acqua fredda e condirli con qualche goccia d''olio. Gli yakisoba freschi vanno solo sciolti sotto l''acqua calda.","Scaldare l''olio in una padella grande o nel wok a fuoco medio-alto e rosolare la pancia di maiale 3-4 min finché è dorata e croccante ai bordi; pepare.","Aggiungere cipolla e carota e saltare 2 min, poi il cavolo per 2 min finché appassisce appena.","Unire i noodles, i germogli di soia e 2 cucchiai d''acqua e saltare 2 min per scaldare.","Versare la salsa, aggiungere il cipollotto e saltare a fuoco vivo 1-2 min finché i noodles sono uniformemente bruniti e si attaccano leggermente alla padella.","Servire con lo zenzero rosso sottaceto sopra."]}}'::jsonb),
  ('ab67d2ee-23c9-4012-ba25-0beea79e587c'::uuid, '{"fr":{"title":"Hambāgu (steak haché à la japonaise)","steps":["Faire revenir l''oignon dans 1 c. à café d''huile à feu moyen 6 à 8 min jusqu''à ce qu''il soit tendre et blond, puis le laisser refroidir. Faire tremper le panko dans le lait.","Lancer le riz : le cuire à couvert dans 1,5 fois son volume d''eau 12 min, puis le laisser reposer 5 min hors du feu.","Mettre dans un saladier le bœuf, le porc, l''oignon refroidi, le panko trempé, l''œuf, la muscade, 0,5 c. à café de sel et du poivre, et pétrir 1 à 2 min jusqu''à ce que la farce soit collante.","Diviser en deux. Passer chaque moitié d''une main à l''autre pour chasser l''air, former un ovale d''environ 2 cm d''épaisseur et creuser légèrement le centre.","Essuyer la poêle des oignons, y chauffer le reste d''huile à feu moyen-vif et dorer les steaks 3 min. Les retourner, verser le vin, couvrir et cuire à feu doux 8 min, jusqu''à ce que le jus soit clair quand on appuie.","Pendant ce temps, cuire le brocoli avec le riz : le poser sur le riz pour les 5 dernières minutes de cuisson, à couvert, afin qu''il cuise à la vapeur.","Déposer les steaks dans les assiettes. Ajouter le ketchup, la sauce Worcestershire et le beurre au jus de cuisson et laisser frémir 1 min jusqu''à ce que la sauce soit brillante.","Napper les steaks de sauce et servir avec le riz et le brocoli."]},"it":{"title":"Hambāgu (hamburger giapponese)","steps":["Cuocere la cipolla in 1 cucchiaino d''olio a fuoco medio per 6-8 min finché è morbida e leggermente dorata, poi lasciarla raffreddare. Ammollare il panko nel latte.","Avviare il riso: cuocerlo coperto in 1,5 volte il suo volume d''acqua per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Mettere in una ciotola manzo, maiale, cipolla raffreddata, panko ammollato, uovo, noce moscata, 0,5 cucchiaino di sale e pepe e impastare 1-2 min finché è appiccicoso.","Dividere in due. Lanciare ogni metà da una mano all''altra per far uscire l''aria, formare un ovale spesso circa 2 cm e premere un incavo al centro.","Pulire la padella della cipolla, scaldarvi il resto dell''olio a fuoco medio-alto e rosolare gli hamburger 3 min. Girarli, versare il vino, coprire e cuocere a fuoco basso 8 min, finché premendo esce un succo chiaro.","Nel frattempo cuocere i broccoli con il riso: adagiarli sul riso negli ultimi 5 min di cottura, coperti, perché cuociano al vapore.","Trasferire gli hamburger nei piatti. Aggiungere ketchup, salsa Worcestershire e burro al fondo di cottura e cuocere 1 min finché la salsa è lucida.","Versare la salsa sugli hamburger e servire con riso e broccoli."]}}'::jsonb),
  ('1730bc57-55bd-4af6-a13e-c743c60afdbd'::uuid, '{"fr":{"title":"Asperges roulées au porc (butabara maki) et riz","steps":["Lancer le riz : le cuire à couvert dans 1,5 fois son volume d''eau 12 min, puis le laisser reposer 5 min hors du feu.","Éplucher le tiers inférieur des asperges si elles sont épaisses. Les blanchir 1 min dans de l''eau bouillante salée dans la poêle, les égoutter, les refroidir sous l''eau froide et bien les sécher ; essuyer la poêle.","Mélanger dans un bol la sauce soja, le mirin, le saké et le sucre.","Enrouler chaque asperge en spirale dans une tranche de poitrine de porc, en la faisant légèrement chevaucher. Saler et poivrer légèrement, puis saupoudrer de fécule.","Chauffer l''huile dans la poêle à feu moyen et y poser les rouleaux côté jointure dessous. Cuire 2 min pour sceller la jointure, puis les tourner et cuire encore 5 à 6 min jusqu''à ce qu''ils soient dorés de tous côtés.","Éponger l''essentiel de la graisse avec du papier absorbant, verser la sauce et laisser bouillonner 1 à 2 min en roulant les asperges pour les napper d''un glaçage collant.","Couper chaque rouleau en deux et servir sur le riz avec le glaçage et les graines de sésame."]},"it":{"title":"Asparagi avvolti nella pancetta di maiale (butabara maki) con riso","steps":["Avviare il riso: cuocerlo coperto in 1,5 volte il suo volume d''acqua per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Pelare il terzo inferiore degli asparagi se sono spessi. Sbollentarli 1 min in acqua bollente salata nella padella, scolarli, raffreddarli sotto l''acqua fredda e asciugarli bene; asciugare la padella.","Mescolare in una ciotolina salsa di soia, mirin, sake e zucchero.","Avvolgere ogni asparago a spirale in una fetta di pancia di maiale, sovrapponendola leggermente. Salare e pepare appena e spolverare con l''amido.","Scaldare l''olio nella padella a fuoco medio e adagiare gli involtini con la chiusura in basso. Cuocere 2 min finché la chiusura si fissa, poi girarli e cuocere altri 5-6 min finché sono dorati su tutti i lati.","Tamponare quasi tutto il grasso con carta da cucina, versare la salsa e far sobbollire 1-2 min, rigirando gli involtini finché sono ricoperti da una glassa appiccicosa.","Tagliare ogni involtino a metà e servire sul riso con la glassa e i semi di sesamo."]}}'::jsonb),
  ('d9057435-15c8-4de0-902f-aa8741ca003f'::uuid, '{"fr":{"title":"Phở bò","steps":["Noircir les moitiés d''oignon et le gingembre côté coupé dans une poêle épaisse sèche à feu vif 8 à 10 min, jusqu''à ce qu''ils soient brûlés par endroits ; rincer la peau carbonisée qui se détache.","Mettre la poitrine de bœuf dans une marmite, couvrir d''eau froide, faire bouillir 3 min, puis égoutter et rincer la viande et la marmite : le bouillon restera limpide.","Remettre la viande dans la marmite avec le bouillon, 1 l d''eau, l''oignon et le gingembre grillés, 1 c. à soupe de sauce de poisson et le sucre. Porter à petits frémissements et cuire à découvert 2 h à 2 h 30 en écumant de temps en temps, jusqu''à ce que la viande soit tendre.","Pour les 45 dernières minutes, torréfier l''anis étoilé, la cannelle, les clous de girofle, les graines de coriandre et la cardamome 2 min à sec dans la poêle jusqu''à ce qu''ils embaument, puis les ajouter au bouillon dans une boule à thé ou une mousseline.","Retirer la viande et la trancher finement. Filtrer le bouillon et l''assaisonner avec le reste de sauce de poisson et du sel ; il faut environ 1,2 l de bouillon limpide et bien relevé.","Faire tremper ou cuire les nouilles de riz selon le paquet, les égoutter et les répartir dans deux grands bols.","Garnir les nouilles de poitrine tranchée, des tranches de bœuf cru et de l''oignon émincé. Porter de nouveau le bouillon à gros bouillons et le verser dessus, pour cuire le bœuf cru à rosé.","Parsemer d''oignon nouveau et de coriandre et servir avec les germes de soja, le basilic thaï, le citron vert, le piment, la sauce hoisin et la sriracha à part."]},"it":{"title":"Phở bò","steps":["Abbrustolire le metà di cipolla e lo zenzero dal lato tagliato in una padella spessa asciutta a fuoco vivo per 8-10 min, finché sono anneriti qua e là; sciacquare via la pelle bruciata che si stacca.","Mettere il petto di manzo in una pentola, coprire con acqua fredda, far bollire 3 min, poi scolare e sciacquare la carne e la pentola: così il brodo resta limpido.","Rimettere la carne nella pentola con il brodo, 1 l d''acqua, cipolla e zenzero abbrustoliti, 1 cucchiaio di salsa di pesce e lo zucchero. Portare a un sobbollire appena accennato e cuocere scoperto 2-2,5 h, schiumando ogni tanto, finché la carne è tenera.","Per gli ultimi 45 min, tostare anice stellato, cannella, chiodi di garofano, semi di coriandolo e cardamomo nella padella asciutta per 2 min finché profumano e aggiungerli al brodo in un infusore da tè o in una garza.","Togliere la carne e affettarla sottile. Filtrare il brodo e regolarlo con il resto della salsa di pesce e sale; servono circa 1,2 l di brodo limpido e saporito.","Ammollare o cuocere i noodles di riso come indicato sulla confezione, scolarli e dividerli in due ciotole grandi.","Disporre sui noodles il petto affettato, le fettine di manzo crudo e la cipolla affettata. Riportare il brodo a bollore vivace e versarlo sopra, così cuoce il manzo crudo lasciandolo rosa.","Cospargere di cipollotto e coriandolo e servire a parte con germogli di soia, basilico thai, lime, peperoncino, salsa hoisin e sriracha."]}}'::jsonb),
  ('21c5d365-a70b-47b4-86f0-da46e6a9f976'::uuid, '{"fr":{"title":"Cà ri gà (curry de poulet vietnamien)","steps":["Mélanger le poulet avec 1 c. à soupe de curry, 1 c. à soupe de sauce de poisson, le sucre et un tiers de l''ail et laisser mariner 30 min.","Chauffer l''huile dans une cocotte à feu moyen et faire revenir l''échalote, le reste de l''ail, le gingembre et la citronnelle 2 min, puis ajouter le reste du curry 30 secondes.","Ajouter le poulet et le dorer 5 min en le retournant.","Verser le bouillon et le lait de coco, ajouter la carotte et la patate douce et porter à frémissement.","Laisser mijoter à découvert 20 min, jusqu''à ce que le poulet soit cuit à cœur, les légumes tendres et la sauce un peu épaissie.","Assaisonner avec le reste de sauce de poisson et du sel, puis retirer la citronnelle.","Servir dans des bols, garni d''oignon nouveau et de coriandre, avec la baguette pour saucer."]},"it":{"title":"Cà ri gà (curry di pollo vietnamita)","steps":["Condire il pollo con 1 cucchiaio di curry, 1 cucchiaio di salsa di pesce, lo zucchero e un terzo dell''aglio e lasciare marinare 30 min.","Scaldare l''olio in una pentola a fuoco medio e soffriggere scalogno, il resto dell''aglio, zenzero e citronella per 2 min, poi unire il resto del curry per 30 secondi.","Aggiungere il pollo e rosolarlo 5 min, girandolo.","Versare il brodo e il latte di cocco, aggiungere carota e patata dolce e portare a sobbollire.","Cuocere scoperto 20 min, finché il pollo è cotto, le verdure sono tenere e la salsa si è un po'' addensata.","Regolare con il resto della salsa di pesce e sale ed eliminare la citronella.","Servire nelle ciotole con cipollotto e coriandolo, accompagnando con la baguette per la scarpetta."]}}'::jsonb),
  ('f32ce680-abc9-44ed-b155-d09e4329c413'::uuid, '{"fr":{"title":"Ayam kecap (poulet indonésien à la sauce soja sucrée)","steps":["Mélanger le poulet avec le jus d''un demi-citron vert et 0,5 c. à café de sel et laisser reposer 10 min.","Lancer le riz : le cuire à couvert dans 1,5 fois son volume d''eau 12 min, puis le laisser reposer 5 min hors du feu.","Chauffer l''huile dans un wok ou une grande poêle à feu moyen-vif et faire dorer le poulet en une seule couche 6 à 8 min en le retournant ; le retirer.","Dans l''huile restante, faire dorer les échalotes 3 à 4 min, puis ajouter l''ail, le gingembre et le piment 1 min.","Remettre le poulet, ajouter le kecap manis, la sauce soja, la muscade, du poivre et 150 ml d''eau. Laisser mijoter à découvert 12 à 15 min en retournant les morceaux, jusqu''à ce que la sauce réduise en un glaçage collant et que le poulet soit cuit à cœur.","Ajouter la tomate et l''oignon nouveau les 2 dernières minutes, juste pour les attendrir.","Servir avec le riz et les quartiers de citron vert."]},"it":{"title":"Ayam kecap (pollo indonesiano alla soia dolce)","steps":["Condire il pollo con il succo di mezzo lime e 0,5 cucchiaino di sale e lasciare riposare 10 min.","Avviare il riso: cuocerlo coperto in 1,5 volte il suo volume d''acqua per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare l''olio nel wok o in una padella grande a fuoco medio-alto e rosolare il pollo in un solo strato per 6-8 min, girandolo, finché è dorato; toglierlo.","Nell''olio rimasto dorare gli scalogni 3-4 min, poi aggiungere aglio, zenzero e peperoncino per 1 min.","Rimettere il pollo, aggiungere kecap manis, salsa di soia, noce moscata, pepe e 150 ml d''acqua. Cuocere scoperto 12-15 min girando i pezzi, finché la salsa si riduce a una glassa appiccicosa e il pollo è cotto.","Aggiungere pomodoro e cipollotto negli ultimi 2 min, giusto per ammorbidirli.","Servire con il riso e gli spicchi di lime."]}}'::jsonb),
  ('9a075ad1-e1c7-489b-ba5a-1a94b5f9a182'::uuid, '{"fr":{"title":"Haemul pajeon (galette coréenne aux fruits de mer)","steps":["Préparer la sauce : mélanger la sauce soja, le vinaigre, 1 c. à soupe d''eau, le gochugaru et les graines de sésame.","Fouetter la farine, la fécule et le sel avec 180 ml d''eau glacée juste jusqu''à ce que la pâte soit lisse ; elle doit être aussi fluide qu''une crème liquide.","Chauffer 1,5 c. à soupe d''huile dans une poêle de 24-26 cm à feu moyen-vif. Y coucher la moitié des oignons nouveaux côte à côte, parsemer de la moitié des crevettes, du calmar et du piment, puis verser la moitié de la pâte uniformément pour lier le tout.","Arroser de la moitié de l''œuf battu et cuire 3 à 4 min jusqu''à ce que le dessous soit croustillant et doré.","Retourner la galette, ajouter un peu d''huile sur le pourtour, l''aplatir et cuire 3 min jusqu''à ce que les fruits de mer soient cuits et la deuxième face croustillante.","La faire glisser hors de la poêle et préparer la deuxième galette de la même façon.","Couper en carrés et servir aussitôt avec la sauce."]},"it":{"title":"Haemul pajeon (frittella coreana ai frutti di mare)","steps":["Preparare la salsa: mescolare salsa di soia, aceto, 1 cucchiaio d''acqua, gochugaru e semi di sesamo.","Sbattere farina, amido e sale con 180 ml d''acqua ghiacciata giusto finché la pastella è liscia; deve essere fluida come panna da cucina.","Scaldare 1,5 cucchiai d''olio in una padella da 24-26 cm a fuoco medio-alto. Disporre metà dei cipollotti affiancati, distribuire metà di gamberi, calamari e peperoncino e versare metà della pastella in modo uniforme per legare il tutto.","Versare a filo metà dell''uovo sbattuto sopra e cuocere 3-4 min finché il fondo è croccante e dorato.","Girare la frittella, aggiungere un po'' d''olio lungo il bordo, premerla e cuocere 3 min finché i frutti di mare sono cotti e il secondo lato è croccante.","Farla scivolare fuori dalla padella e preparare la seconda frittella allo stesso modo.","Tagliare a quadrotti e servire subito con la salsa."]}}'::jsonb),
  ('77e695ba-765c-416d-879e-ee52967eb6a7'::uuid, '{"fr":{"title":"Bossam (porc bouilli coréen en feuilles de chou)","steps":["Dans une marmite, porter à ébullition environ 2 l d''eau avec l''oignon, le blanc de 3 oignons nouveaux, 6 gousses d''ail, le gingembre, le doenjang, le vin de riz, les grains de poivre et le laurier, et faire bouillir 5 min.","Ajouter le porc de façon qu''il soit entièrement immergé, reporter à ébullition, puis couvrir et laisser frémir à feu moyen-doux 50 à 60 min, jusqu''à ce qu''une baguette traverse facilement la partie la plus épaisse.","Pendant ce temps, mélanger le daikon avec 0,5 c. à café de sel, laisser 10 min et l''essorer légèrement. Le mélanger d''abord avec le gochugaru pour le colorer, puis avec la sauce de poisson, le sucre, le vinaigre, 1 gousse d''ail râpée, les oignons nouveaux restants hachés et les graines de sésame.","Rincer et sécher les feuilles de chou. Émincer finement l''ail restant et le mettre dans de petites coupelles avec le kimchi et le ssamjang.","Sortir le porc de la marmite, le laisser reposer 5 min et le trancher en tranches de 5 mm.","Pour manger, envelopper une tranche de porc dans une feuille de chou avec un peu de salade de radis, du kimchi, une lamelle d''ail et un peu de ssamjang."]},"it":{"title":"Bossam (maiale bollito coreano in foglie di cavolo)","steps":["In una pentola portare a bollore circa 2 l d''acqua con la cipolla, la parte bianca di 3 cipollotti, 6 spicchi d''aglio, lo zenzero, il doenjang, il vino di riso, il pepe in grani e l''alloro, e far bollire 5 min.","Aggiungere il maiale in modo che sia completamente coperto, riportare a bollore, poi coprire e cuocere a fuoco medio-basso 50-60 min, finché una bacchetta attraversa facilmente la parte più spessa.","Nel frattempo condire il daikon con 0,5 cucchiaino di sale, lasciarlo 10 min e strizzarlo leggermente. Mescolarlo prima con il gochugaru per colorarlo, poi con salsa di pesce, zucchero, aceto, 1 spicchio d''aglio grattugiato, i cipollotti rimasti tritati e i semi di sesamo.","Sciacquare e asciugare le foglie di cavolo. Affettare sottile l''aglio rimasto e metterlo in ciotoline con il kimchi e il ssamjang.","Togliere il maiale dalla pentola, lasciarlo riposare 5 min e tagliarlo a fette di 5 mm.","Per mangiare, avvolgere una fetta di maiale in una foglia di cavolo con un po'' di insalata di ravanello, kimchi, una fettina d''aglio e un po'' di ssamjang."]}}'::jsonb),
  ('7202212f-7f30-4815-9536-2eeff0208cb9'::uuid, '{"fr":{"title":"Feijoada","steps":["Chauffer l''huile dans une cocotte en fonte à feu moyen-vif et faire revenir les lardons 4 min jusqu''à ce qu''ils rendent leur graisse. Ajouter le porc et le dorer 6 à 8 min, puis la saucisse 2 min.","Ajouter l''oignon et les deux tiers de l''ail et cuire 5 min jusqu''à ce qu''ils soient tendres.","Ajouter le laurier, 600 ml d''eau et du poivre, porter à ébullition, couvrir et laisser mijoter à feu doux 1 h, jusqu''à ce que le porc soit presque tendre.","Ajouter les haricots et laisser mijoter à découvert 40 min en remuant de temps en temps. Écraser une louche de haricots contre la paroi pour que le ragoût devienne sombre et crémeux ; saler (les lardons et la saucisse le sont déjà).","Pendant ce temps, cuire le riz à couvert dans 1,5 fois son volume d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Juste avant de servir, faire revenir le reste de l''ail dans un peu d''huile dans une poêle 30 secondes, ajouter le chou kale avec une pincée de sel et faire sauter 2 à 3 min jusqu''à ce qu''il soit vert vif et juste tombé.","Servir la feijoada avec le riz, le chou, les rondelles d''orange et la sauce piquante."]},"it":{"title":"Feijoada","steps":["Scaldare l''olio in una casseruola pesante a fuoco medio-alto e rosolare la pancetta 4 min finché rilascia il grasso. Aggiungere il maiale e rosolarlo 6-8 min, poi la salsiccia per 2 min.","Aggiungere la cipolla e due terzi dell''aglio e cuocere 5 min finché sono morbidi.","Unire l''alloro, 600 ml d''acqua e pepe, portare a bollore, coprire e cuocere a fuoco basso 1 h, finché il maiale è quasi tenero.","Aggiungere i fagioli e cuocere scoperto 40 min, mescolando ogni tanto. Schiacciare un mestolo di fagioli contro la parete della pentola perché lo stufato diventi scuro e cremoso; salare (pancetta e salsiccia sono già sapide).","Nel frattempo cuocere il riso coperto in 1,5 volte il suo volume d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Poco prima di servire, soffriggere il resto dell''aglio in un filo d''olio in padella per 30 secondi, aggiungere il cavolo riccio con un pizzico di sale e saltarlo 2-3 min finché è verde brillante e appena appassito.","Servire la feijoada con riso, cavolo, fette d''arancia e salsa piccante."]}}'::jsonb),
  ('606c2941-260f-444a-9ee9-55904482bfef'::uuid, '{"fr":{"title":"Huevos rancheros","steps":["Mixer les tomates, le morceau d''oignon, l''ail, le piment et une pincée de sel jusqu''à obtenir une sauce lisse.","Chauffer 1 c. à café d''huile dans une casserole, verser la sauce (elle éclabousse) et laisser mijoter 8 à 10 min jusqu''à ce qu''elle épaississe légèrement ; assaisonner.","Pendant ce temps, chauffer 1 c. à café d''huile dans une poêle et faire revenir l''oignon haché 3 min. Ajouter les haricots et 3 c. à soupe d''eau et les écraser à la fourchette en purée grossière sur le feu pendant 3 min ; assaisonner et verser dans un bol.","Essuyer la poêle et y réchauffer les tortillas à sec, 30 secondes par face, jusqu''à ce qu''elles soient souples et légèrement grillées ; les envelopper dans un torchon.","Chauffer le reste d''huile dans la poêle et cuire les œufs au plat à feu moyen environ 3 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Poser 2 tortillas par assiette, les tartiner de haricots, poser un œuf sur chacune et napper de sauce chaude autour. Finir avec le queso fresco, l''avocat et la coriandre."]},"it":{"title":"Huevos rancheros","steps":["Frullare i pomodori, il pezzo di cipolla, l''aglio, il peperoncino e un pizzico di sale fino a ottenere una salsa liscia.","Scaldare 1 cucchiaino d''olio in un pentolino, versare la salsa (schizza) e cuocere 8-10 min finché si addensa leggermente; regolare di sale.","Nel frattempo scaldare 1 cucchiaino d''olio in padella e soffriggere la cipolla tritata 3 min. Aggiungere i fagioli e 3 cucchiai d''acqua e schiacciarli con una forchetta in una purea grossolana sul fuoco per 3 min; salare e trasferire in una ciotola.","Pulire la padella e scaldarvi le tortillas a secco, 30 secondi per lato, finché sono morbide e leggermente tostate; avvolgerle in un canovaccio.","Scaldare il resto dell''olio nella padella e cuocere le uova all''occhio di bue a fuoco medio circa 3 min, finché l''albume è rappreso e il tuorlo ancora morbido.","Mettere 2 tortillas per piatto, spalmarle di fagioli, adagiare un uovo su ciascuna e versare la salsa calda intorno. Completare con queso fresco, avocado e coriandolo."]}}'::jsonb),
  ('065cf384-d091-4686-9e88-f46b9f905af0'::uuid, '{"fr":{"title":"Empanadas de carne (argentines)","steps":["Préparer la pâte : mélanger la farine et le sel, ajouter le beurre fondu et environ 100 ml d''eau tiède petit à petit, et pétrir 5 min jusqu''à obtenir une pâte lisse et souple. L''envelopper et la laisser reposer 30 min.","Cuire 2 des œufs 10 min à l''eau bouillante, les refroidir dans l''eau froide, les écaler et les hacher.","Chauffer l''huile dans une poêle et faire revenir l''oignon et le blanc des oignons nouveaux à feu moyen 8 min jusqu''à ce qu''ils soient tendres. Ajouter le bœuf, l''émietter et cuire 5 min jusqu''à ce qu''il ne soit plus rosé. Assaisonner de paprika, cumin, piment, origan, sel et poivre, ajouter le vert des oignons nouveaux et laisser refroidir complètement, au moins 30 min au réfrigérateur.","Préchauffer le four à 200 °C. Abaisser la pâte sur 2-3 mm d''épaisseur et découper des disques de 12 cm, en rassemblant les chutes ; on doit en obtenir 8 à 10.","Déposer une bonne cuillerée de farce au centre de chaque disque avec un peu d''œuf haché, d''olives et de raisins secs. Humidifier le bord, replier en demi-lune, presser pour souder et rouler le bord sur lui-même pour le festonner.","Poser les empanadas sur une plaque recouverte de papier cuisson, les badigeonner avec le dernier œuf battu et les piquer une fois à la fourchette.","Cuire 18 à 20 min jusqu''à ce qu''elles soient bien dorées. Laisser reposer 5 min avant de déguster."]},"it":{"title":"Empanadas de carne (argentine)","steps":["Preparare l''impasto: mescolare farina e sale, aggiungere il burro fuso e circa 100 ml d''acqua tiepida poco alla volta e impastare 5 min fino a ottenere un panetto liscio e morbido. Avvolgerlo e lasciarlo riposare 30 min.","Rassodare 2 delle uova in acqua bollente per 10 min, raffreddarle in acqua fredda, sgusciarle e tritarle.","Scaldare l''olio in padella e cuocere la cipolla e la parte bianca dei cipollotti a fuoco medio per 8 min finché sono morbide. Aggiungere il manzo, sgranarlo e cuocere 5 min finché non è più rosa. Condire con paprika, cumino, peperoncino, origano, sale e pepe, unire la parte verde dei cipollotti e lasciare raffreddare completamente, almeno 30 min in frigorifero.","Scaldare il forno a 200 °C. Stendere l''impasto a 2-3 mm di spessore e ritagliare dischi da 12 cm, reimpastando i ritagli; se ne ottengono 8-10.","Mettere una cucchiaiata abbondante di ripieno al centro di ogni disco con un po'' di uovo tritato, olive e uvetta. Inumidire il bordo, chiudere a mezzaluna, premere per sigillare e arrotolare il bordo su se stesso per formare il cordoncino.","Disporre le empanadas su una teglia foderata, spennellarle con l''ultimo uovo sbattuto e bucarle una volta con una forchetta.","Cuocere 18-20 min finché sono ben dorate. Lasciare riposare 5 min prima di mangiare."]}}'::jsonb),
  ('bd00c98e-1568-44a4-89e9-94a79fa0d62f'::uuid, '{"fr":{"title":"Fesenjan (poulet aux noix et à la grenade)","steps":["Torréfier les noix dans une cocotte épaisse sèche à feu moyen 4 à 5 min jusqu''à ce qu''elles embaument, les laisser refroidir, puis les mixer au robot en une poudre fine et humide.","Chauffer l''huile dans la même cocotte et faire dorer l''oignon 8 min. Ajouter le curcuma, puis le poulet et le dorer 5 min ; retirer le poulet.","Ajouter les noix moulues et le bouillon dans la cocotte, porter à frémissement, couvrir et cuire à feu doux 30 min en remuant souvent pour que rien n''attache, jusqu''à ce que la sauce fonce et qu''un peu d''huile remonte.","Incorporer la mélasse de grenade, la cannelle, le sucre, du sel et du poivre, remettre le poulet et laisser mijoter à couvert 30 à 40 min, jusqu''à ce que le poulet soit tendre et la sauce épaisse et brun foncé. Goûter et équilibrer l''acidité et le sucre avec un peu plus de mélasse ou de sucre.","Pendant ce temps, rincer le riz et le cuire à couvert dans 1,5 fois son volume d''eau salée avec le safran 12 min ; le laisser reposer 5 min hors du feu.","Servir le fesenjan sur le riz, parsemé de persil."]},"it":{"title":"Fesenjan (pollo con noci e melograno)","steps":["Tostare le noci in una pentola pesante asciutta a fuoco medio per 4-5 min finché profumano, lasciarle raffreddare, poi tritarle nel robot fino a ottenere una farina fine e umida.","Scaldare l''olio nella stessa pentola e dorare la cipolla 8 min. Unire la curcuma, poi il pollo e rosolarlo 5 min; togliere il pollo.","Aggiungere le noci tritate e il brodo, portare a sobbollire, coprire e cuocere a fuoco basso 30 min, mescolando spesso perché non attacchi, finché la salsa si scurisce e affiora un po'' d''olio.","Unire la melassa di melograno, la cannella, lo zucchero, sale e pepe, rimettere il pollo e cuocere coperto 30-40 min, finché il pollo è tenero e la salsa densa e marrone scuro. Assaggiare e bilanciare acido e dolce con altra melassa o zucchero.","Nel frattempo sciacquare il riso e cuocerlo coperto in 1,5 volte il suo volume d''acqua salata con lo zafferano per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Servire il fesenjan sul riso, cosparso di prezzemolo."]}}'::jsonb),
  ('8b20d202-eae1-49a5-aa90-14874c2a0c0e'::uuid, '{"fr":{"title":"Thiéboudienne","steps":["Préparer le rof : piler ou hacher le persil, l''ail, les oignons nouveaux, une pincée de piment, 0,5 c. à café de sel et du poivre en une pâte grossière. Inciser profondément chaque darne de poisson à deux endroits et farcir les entailles avec la moitié du rof.","Chauffer l''huile dans une grande cocotte à feu moyen et dorer le poisson 2 min par face ; le retirer.","Faire revenir l''oignon dans la même huile 6 à 8 min jusqu''à ce qu''il soit tendre. Ajouter le concentré de tomate délayé dans 100 ml d''eau et le faire frire 5 à 8 min en remuant, jusqu''à ce qu''il prenne une couleur rouge brique et que l''huile se sépare.","Ajouter le fumet, le laurier, le piment entier et le reste du rof et porter à ébullition. Ajouter les carottes, le navet, le manioc et le chou et laisser mijoter 15 min, puis l''aubergine et le poisson encore 10 à 15 min, jusqu''à ce que le poisson s''effeuille et que les légumes soient tendres.","Retirer le poisson et les légumes sur un plat, couvrir de papier aluminium et garder au chaud ; retirer le piment. Laisser environ 450 ml de bouillon dans la cocotte et réserver le reste.","Rincer le riz, le verser dans le bouillon, couvrir hermétiquement et cuire à feu doux 20 à 25 min jusqu''à ce qu''il ait absorbé le liquide et soit tendre, en ajoutant un peu de bouillon réservé s''il se dessèche. Monter le feu les 2 dernières minutes pour que le fond accroche et croustille.","Étaler le riz sur un grand plat, disposer le poisson et les légumes dessus, arroser d''un peu de bouillon réservé et servir avec des quartiers de citron vert."]},"it":{"title":"Thieboudienne","steps":["Preparare il rof: pestare o tritare prezzemolo, aglio, cipollotti, un pizzico di peperoncino, 0,5 cucchiaino di sale e pepe fino a una pasta grossolana. Praticare 2 tagli profondi in ogni trancio di pesce e farcirli con metà del rof.","Scaldare l''olio in una pentola larga a fuoco medio e rosolare il pesce 2 min per lato; toglierlo.","Cuocere la cipolla nello stesso olio 6-8 min finché è morbida. Aggiungere il concentrato di pomodoro sciolto in 100 ml d''acqua e friggerlo 5-8 min mescolando, finché diventa rosso mattone e l''olio si separa.","Aggiungere il fumetto, l''alloro, il peperoncino intero e il resto del rof e portare a bollore. Unire carote, rapa, manioca e cavolo e cuocere 15 min, poi melanzana e pesce per altri 10-15 min, finché il pesce si sfalda e le verdure sono tenere.","Trasferire pesce e verdure su un piatto, coprire con alluminio e tenere in caldo; eliminare il peperoncino. Lasciare circa 450 ml di brodo nella pentola e tenere da parte il resto.","Sciacquare il riso, versarlo nel brodo, coprire bene e cuocere a fuoco basso 20-25 min finché ha assorbito il liquido ed è tenero, aggiungendo un po'' di brodo tenuto da parte se si asciuga. Alzare il fuoco negli ultimi 2 min perché il fondo diventi croccante.","Stendere il riso su un grande piatto da portata, disporre sopra pesce e verdure, irrorare con un po'' di brodo tenuto da parte e servire con spicchi di lime."]}}'::jsonb),
  ('2967ec22-b774-49f7-b93c-f359f1cb02ed'::uuid, '{"fr":{"title":"Käsespätzle (spätzle au fromage)","steps":["Battre la farine, les œufs, le lait, le sel et la muscade à la cuillère en bois 3 à 4 min jusqu''à obtenir une pâte lisse, épaisse et pleine de bulles, qui tombe de la cuillère en rubans lents. La laisser reposer 15 min.","Faire fondre 20 g de beurre dans une poêle à feu moyen-doux et cuire les oignons 15 à 20 min en remuant de temps en temps, jusqu''à ce qu''ils soient bien dorés ; monter le feu les 2 dernières minutes pour les rendre croustillants.","Préchauffer le four à 180 °C et beurrer un plat allant au four avec le reste du beurre.","Porter à ébullition une grande casserole d''eau salée. En 3 fois, presser la pâte à travers une presse à spätzle ou une passoire à gros trous, ou raser de fines lanières de pâte d''une planche mouillée directement dans l''eau. Quand ils remontent à la surface, après 1 à 2 min, les retirer à l''écumoire.","Disposer les spätzle chauds en couches dans le plat avec le fromage et du poivre, en finissant par du fromage.","Enfourner 10 min jusqu''à ce que le fromage ait fondu, puis garnir des oignons croustillants et de ciboulette et servir avec une salade verte."]},"it":{"title":"Käsespätzle (spätzle al formaggio)","steps":["Sbattere farina, uova, latte, sale e noce moscata con un cucchiaio di legno per 3-4 min fino a ottenere una pastella liscia, densa e piena di bolle, che cade dal cucchiaio a nastri lenti. Lasciarla riposare 15 min.","Sciogliere 20 g di burro in padella a fuoco medio-basso e cuocere le cipolle 15-20 min, mescolando ogni tanto, finché sono ben dorate; alzare il fuoco negli ultimi 2 min per renderle croccanti.","Scaldare il forno a 180 °C e imburrare una pirofila con il resto del burro.","Portare a bollore una pentola grande d''acqua salata. In 3 riprese, passare la pastella nell''apposito attrezzo per spätzle o in uno scolapasta a fori larghi, oppure raschiare strisce sottili da un tagliere bagnato direttamente nell''acqua. Quando vengono a galla, dopo 1-2 min, scolarli con una schiumarola.","Disporre gli spätzle caldi a strati nella pirofila con il formaggio e pepe, finendo con il formaggio.","Infornare 10 min finché il formaggio è fuso, poi completare con le cipolle croccanti e l''erba cipollina e servire con un''insalata verde."]}}'::jsonb),
  ('518315a0-7551-4a2c-a8bb-e97d40a780b6'::uuid, '{"fr":{"title":"Bortsch au bœuf","steps":["Mettre le bœuf dans une grande marmite avec 1,5 l d''eau froide, porter à ébullition et écumer. Ajouter le laurier, les grains de poivre et 1 c. à café de sel et laisser frémir à demi couvert 1 h 30, jusqu''à ce que le bœuf soit tendre.","Retirer le bœuf, le couper en bouchées et le remettre dans le bouillon.","Pendant ce temps, chauffer l''huile dans une poêle et faire revenir l''oignon et la carotte 5 min. Ajouter la betterave, le concentré de tomate, 1 c. à soupe de vinaigre, le sucre et une louche de bouillon, couvrir et laisser étuver 15 min en remuant de temps en temps (le vinaigre garde la couleur vive).","Ajouter les pommes de terre dans le bouillon et cuire 10 min.","Ajouter le chou et cuire 5 min.","Incorporer la préparation à la betterave et l''ail et laisser frémir 5 min. Assaisonner de sel et du reste de vinaigre pour un goût aigre-doux, ajouter la moitié de l''aneth et, si possible, laisser reposer la soupe 10 min hors du feu.","Servir avec une cuillerée de crème fraîche, le reste d''aneth et du pain de seigle."]},"it":{"title":"Boršč con manzo","steps":["Mettere il manzo in una pentola grande con 1,5 l d''acqua fredda, portare a bollore e schiumare. Aggiungere alloro, pepe in grani e 1 cucchiaino di sale e cuocere semicoperto 1,5 h, finché il manzo è tenero.","Togliere il manzo, tagliarlo a bocconi e rimetterlo nel brodo.","Nel frattempo scaldare l''olio in padella e cuocere cipolla e carota 5 min. Aggiungere la barbabietola, il concentrato di pomodoro, 1 cucchiaio di aceto, lo zucchero e un mestolo di brodo, coprire e stufare 15 min mescolando ogni tanto (l''aceto mantiene il colore vivo).","Aggiungere le patate al brodo e cuocere 10 min.","Aggiungere il cavolo e cuocere 5 min.","Unire la barbabietola stufata e l''aglio e cuocere 5 min. Regolare di sale e con il resto dell''aceto fino a un gusto agrodolce, aggiungere metà dell''aneto e, se possibile, far riposare la zuppa 10 min fuori dal fuoco.","Servire con un cucchiaio di crème fraîche, il resto dell''aneto e pane di segale."]}}'::jsonb),
  ('9244b1f2-c079-4d75-9219-3455d670a6ae'::uuid, '{"fr":{"title":"Misir wot aux œufs (lentilles éthiopiennes)","steps":["Cuire les oignons dans une cocotte à sec à feu moyen-doux 8 à 10 min en remuant, jusqu''à ce qu''ils soient tendres et commencent à peine à colorer.","Ajouter 30 g de beurre, la cardamome, l''ail et le gingembre et cuire 3 min.","Incorporer 1,5 c. à soupe de berbéré et le concentré de tomate avec un trait d''eau et faire revenir 2 min, jusqu''à ce que ce soit rouge sombre et parfumé ; ajouter de l''eau si les épices commencent à attacher.","Ajouter les lentilles et 800 ml d''eau chaude, porter à ébullition et laisser mijoter à demi couvert 30 à 35 min en remuant souvent et en ajoutant de l''eau si besoin, jusqu''à ce que les lentilles se défassent en un ragoût épais.","Pendant ce temps, cuire les œufs 9 min à l''eau bouillante, les refroidir dans l''eau froide, les écaler et entailler légèrement leur surface au couteau.","Incorporer le reste du beurre et du berbéré au wot et saler. Ajouter les œufs et laisser mijoter 5 min pour qu''ils prennent la couleur.","Servir sur l''injera, avec les œufs coupés en deux par-dessus."]},"it":{"title":"Misir wot con uova (lenticchie etiopi)","steps":["Cuocere le cipolle in una pentola asciutta a fuoco medio-basso per 8-10 min, mescolando, finché sono morbide e iniziano appena a colorirsi.","Aggiungere 30 g di burro, il cardamomo, l''aglio e lo zenzero e cuocere 3 min.","Unire 1,5 cucchiai di berbere e il concentrato di pomodoro con un goccio d''acqua e soffriggere 2 min, finché il tutto è rosso scuro e profumato; aggiungere acqua se le spezie iniziano ad attaccare.","Aggiungere le lenticchie e 800 ml d''acqua calda, portare a bollore e cuocere semicoperto 30-35 min, mescolando spesso e aggiungendo acqua se serve, finché le lenticchie si sfaldano in uno stufato denso.","Nel frattempo rassodare le uova per 9 min, raffreddarle in acqua fredda, sgusciarle e incidere leggermente la superficie con un coltello.","Unire al wot il resto del burro e del berbere e salare. Aggiungere le uova e cuocere 5 min perché prendano colore.","Servire sull''injera, con le uova tagliate a metà sopra."]}}'::jsonb),
  ('1a70bffe-f24f-41c8-871e-d950aaa404e7'::uuid, '{"fr":{"title":"Salade de pommes de terre nouvelles, radis, œufs et truite fumée","steps":["Cuire les pommes de terre à l''eau salée 15 à 18 min jusqu''à ce qu''elles soient tendres, en ajoutant les œufs pour les 8 dernières minutes.","Égoutter, refroidir les œufs dans l''eau froide, puis les écaler et les couper en quartiers. Couper les pommes de terre en deux encore tièdes.","Mélanger la crème fraîche, la moutarde, le jus de citron, la moitié de l''aneth, du sel et du poivre pour la sauce.","Mélanger les pommes de terre tièdes avec l''échalote et la moitié de la sauce.","Ajouter les radis, le concombre et la roquette, puis disposer les œufs et la truite émiettée par-dessus.","Napper du reste de sauce et finir avec le reste d''aneth et la ciboulette."]},"it":{"title":"Insalata di patate novelle, ravanelli, uova e trota affumicata","steps":["Lessare le patate in acqua salata 15-18 min finché sono tenere, aggiungendo le uova negli ultimi 8 min.","Scolare, raffreddare le uova in acqua fredda, poi sgusciarle e tagliarle in quarti. Tagliare a metà le patate ancora tiepide.","Mescolare crème fraîche, senape, succo di limone, metà dell''aneto, sale e pepe per il condimento.","Condire le patate tiepide con lo scalogno e metà del condimento.","Aggiungere ravanelli, cetriolo e rucola, poi disporre sopra le uova e la trota sbriciolata.","Versare il resto del condimento e completare con l''aneto rimasto e l''erba cipollina."]}}'::jsonb),
  ('d57419c4-5bac-533f-a864-773905989892'::uuid, '{"fr":{"title":"Poulet au citron au air fryer, boulgour aux herbes, petits pois et yaourt citronné","steps":["Frotter le poulet avec l''huile d''olive, la moitié du zeste de citron, l''origan, la moitié de l''ail, du sel et du poivre.","Cuire le poulet au air fryer à 200 °C pendant 12 à 15 min en le retournant à mi-cuisson, jusqu''à 75 °C à cœur ; le laisser reposer 3 min.","Pendant ce temps, porter le boulgour et le bouillon à ébullition dans une casserole, couvrir et laisser frémir 10 min.","Ajouter les petits pois, couvrir et cuire encore 3 min, puis incorporer les épinards hors du feu jusqu''à ce qu''ils tombent.","Mélanger le yaourt avec la moitié du jus de citron, le reste de l''ail, la moitié de la menthe et du persil et une pincée de sel.","Mélanger à la fourchette le reste du jus, du zeste et des herbes dans le boulgour, trancher le poulet et le servir dessus avec le yaourt."]},"it":{"title":"Pollo al limone in friggitrice ad aria con bulgur alle erbe, piselli e yogurt al limone","steps":["Massaggiare il pollo con l''olio d''oliva, metà della scorza di limone, l''origano, metà dell''aglio, sale e pepe.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–15 min, girandolo a metà, finché raggiunge 75 °C al cuore; farlo riposare 3 min.","Nel frattempo portare a bollore il bulgur con il brodo in una pentola, coprire e cuocere a fuoco dolce 10 min.","Unire i piselli, coprire e cuocere altri 3 min, poi incorporare gli spinaci fuori dal fuoco finché appassiscono.","Mescolare lo yogurt con metà del succo di limone, il resto dell''aglio, metà della menta e del prezzemolo e un pizzico di sale.","Sgranare il bulgur con la forchetta unendo il resto di succo, scorza ed erbe, affettare il pollo e servirlo sopra con lo yogurt."]}}'::jsonb),
  ('64156951-1c4e-5eff-aae3-b139edfc8c3c'::uuid, '{"fr":{"title":"Nouilles au poulet, sauce cacahuète-citron vert, carotte et poivron","steps":["Cuire les nouilles de riz dans une casserole d''eau bouillante selon le paquet (4 à 6 min en général), égoutter et rincer à l''eau froide.","Fouetter le beurre de cacahuète, la sauce soja, le zeste et le jus de citron vert, le miel, la sriracha, l''ail et le gingembre avec 3 à 4 c. à soupe d''eau chaude jusqu''à obtenir une sauce lisse et fluide.","Chauffer l''huile dans un wok ou une grande poêle à feu vif et faire sauter le poulet 4 à 5 min jusqu''à ce qu''il soit doré et cuit.","Ajouter le poivron et la carotte et faire sauter 2 min pour qu''ils restent croquants.","Ajouter les nouilles et la sauce et mélanger sur le feu 1 min pour bien enrober ; détendre avec un peu d''eau si besoin.","Servir parsemé d''oignon nouveau, de coriandre et de cacahuètes concassées."]},"it":{"title":"Noodles di pollo al burro di arachidi e lime con carota e peperone","steps":["Cuocere i noodles di riso in una pentola d''acqua bollente come indicato sulla confezione (di solito 4–6 min), scolarli e sciacquarli in acqua fredda.","Sbattere il burro di arachidi, la salsa di soia, scorza e succo di lime, il miele, la sriracha, l''aglio e lo zenzero con 3–4 cucchiai d''acqua calda fino a ottenere una salsa liscia e fluida.","Scaldare l''olio in un wok o in una padella grande a fuoco vivo e saltare il pollo 4–5 min finché è dorato e cotto.","Aggiungere il peperone e la carota e saltare 2 min perché restino croccanti.","Unire i noodles e la salsa e mescolare sul fuoco 1 min finché tutto è ben condito; allungare con un goccio d''acqua se serve.","Servire con cipollotto, coriandolo e arachidi tritate."]}}'::jsonb),
  ('43b6a6ab-8a49-504d-a5d0-0bdff76e2627'::uuid, '{"fr":{"title":"Poulet au pesto au air fryer, pommes de terre nouvelles écrasées et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min à frémissement.","Saler et poivrer le poulet et le badigeonner de 2 c. à soupe de pesto.","Cuire le poulet au air fryer à 200 °C pendant 12 à 14 min, jusqu''à 75 °C à cœur ; le laisser reposer 3 min.","Ajouter les haricots verts aux pommes de terre pour les 4 dernières minutes, puis bien égoutter le tout.","Retirer les haricots, puis écraser grossièrement les pommes de terre dans la casserole avec l''huile d''olive, le reste du pesto, un filet de citron, du sel et du poivre.","Trancher le poulet et le servir avec les pommes de terre et les haricots, parsemé de parmesan."]},"it":{"title":"Pollo al pesto in friggitrice ad aria con patate novelle schiacciate e fagiolini","steps":["Mettere le patate in una pentola d''acqua fredda salata, portare a bollore e cuocere 15 min a fuoco medio.","Salare e pepare il pollo e spalmarlo con 2 cucchiai di pesto.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–14 min, finché raggiunge 75 °C al cuore; farlo riposare 3 min.","Aggiungere i fagiolini alle patate negli ultimi 4 min, poi scolare bene tutto.","Togliere i fagiolini, poi schiacciare grossolanamente le patate nella pentola con l''olio, il resto del pesto, una spruzzata di limone, sale e pepe.","Affettare il pollo e servirlo con le patate e i fagiolini, con il parmigiano sopra."]}}'::jsonb),
  ('2ad7bb6d-b208-58bf-b258-1f95e64ea400'::uuid, '{"fr":{"title":"Poulet à la harissa au air fryer, couscous aux poivrons et pois chiches","steps":["Mélanger la harissa avec 1 c. à soupe d''huile, la moitié du jus de citron et une pincée de sel, et en enrober le poulet ; le laisser mariner pendant la préparation du reste.","Cuire le poulet au air fryer à 200 °C pendant 12 à 15 min en le retournant à mi-cuisson, jusqu''à 75 °C à cœur ; le laisser reposer 3 min.","Pendant ce temps, chauffer le reste de l''huile dans une sauteuse et faire revenir le poivron et l''oignon 6 min à feu moyen.","Ajouter les pois chiches et le cumin et cuire 1 min, puis incorporer la semoule et verser le bouillon bouillant.","Retirer du feu, couvrir et laisser gonfler 5 min, puis égrener à la fourchette avec le reste du jus de citron et la moitié de la menthe.","Trancher le poulet et le servir sur la semoule avec le yaourt et le reste de la menthe."]},"it":{"title":"Pollo all''harissa in friggitrice ad aria con cous cous di peperoni e ceci","steps":["Mescolare l''harissa con 1 cucchiaio d''olio, metà del succo di limone e un pizzico di sale e ricoprirne il pollo; lasciarlo insaporire mentre si prepara il resto.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–15 min, girandolo a metà, finché raggiunge 75 °C al cuore; farlo riposare 3 min.","Nel frattempo scaldare il resto dell''olio in una padella fonda e far appassire peperone e cipolla per 6 min a fuoco medio.","Aggiungere i ceci e il cumino e cuocere 1 min, poi unire il cous cous e versare il brodo bollente.","Togliere dal fuoco, coprire e lasciar riposare 5 min, poi sgranare con la forchetta con il resto del succo di limone e metà della menta.","Affettare il pollo e servirlo sul cous cous con lo yogurt e il resto della menta."]}}'::jsonb),
  ('733ec69d-3777-5784-86c3-674f2fc480d3'::uuid, '{"fr":{"title":"Poulet miso-gingembre, nouilles soba et brocoli","steps":["Fouetter le miso, la sauce soja, le mirin, le miel, le gingembre, l''ail, le vinaigre de riz et l''huile de sésame avec 3 c. à soupe d''eau.","Cuire les soba 4 à 5 min dans une casserole d''eau bouillante en ajoutant le brocoli pour les 2 dernières minutes ; égoutter et rincer rapidement à l''eau froide.","Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire le poulet 5 à 6 min jusqu''à ce qu''il soit doré et cuit.","Verser la sauce au miso et laisser bouillonner 1 min jusqu''à ce qu''elle nappe le poulet.","Ajouter les nouilles et le brocoli et mélanger 1 min pour réchauffer et enrober.","Servir parsemé de graines de sésame et d''oignon nouveau."]},"it":{"title":"Pollo al miso e zenzero con soba e broccoli","steps":["Sbattere il miso, la salsa di soia, il mirin, il miele, lo zenzero, l''aglio, l''aceto di riso e l''olio di sesamo con 3 cucchiai d''acqua.","Cuocere la soba in una pentola d''acqua bollente per 4–5 min, aggiungendo i broccoli negli ultimi 2 min; scolare e sciacquare velocemente in acqua fredda.","Scaldare l''olio in una padella grande a fuoco medio-alto e cuocere il pollo 5–6 min finché è dorato e cotto.","Versare la salsa al miso e lasciar sobbollire 1 min finché glassa il pollo.","Unire la soba e i broccoli e mescolare 1 min per scaldare e condire.","Servire con semi di sesamo e cipollotto."]}}'::jsonb),
  ('4624f1fb-2e42-5728-bc55-0198cd2918ca'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet miel-gochujang au air fryer, riz et concombre","steps":["Rincer le riz et le cuire dans une casserole avec 300 ml d''eau : porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer 5 min hors du feu.","Mélanger le gochujang, le miel, la sauce soja, l''huile de sésame et l''ail pour faire un glaçage ; en enrober le poulet avec un tiers.","Cuire le poulet au air fryer à 200 °C pendant 8 min, puis le retourner, le badigeonner du reste du glaçage et cuire encore 4 à 6 min jusqu''à ce qu''il soit laqué et à 75 °C à cœur.","Pendant ce temps, écraser légèrement le concombre avec un rouleau ou le plat d''un couteau et le casser en bouchées.","Mélanger le concombre avec le vinaigre de riz, le sucre, une pincée de sel et la moitié des graines de sésame.","Trancher le poulet et le servir sur le riz avec le concombre, le reste des graines de sésame et l''oignon nouveau."]},"it":{"title":"Sovracosce di pollo al miele e gochujang in friggitrice ad aria con riso e cetriolo","steps":["Sciacquare il riso e cuocerlo in una pentola con 300 ml d''acqua: portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Mescolare gochujang, miele, salsa di soia, olio di sesamo e aglio per ottenere una glassa; condire il pollo con un terzo.","Cuocere il pollo in friggitrice ad aria a 200 °C per 8 min, poi girarlo, spennellarlo con il resto della glassa e cuocere altri 4–6 min finché è laccato e a 75 °C al cuore.","Nel frattempo schiacciare leggermente il cetriolo con un mattarello o con la lama piatta di un coltello e spezzarlo a bocconi.","Condire il cetriolo con l''aceto di riso, lo zucchero, un pizzico di sale e metà dei semi di sesamo.","Affettare il pollo e servirlo sul riso con il cetriolo, il resto dei semi di sesamo e il cipollotto."]}}'::jsonb),
  ('079ff286-d35c-5eda-b67b-aee1962e87e9'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet au air fryer, sauce tahini-citron, quinoa et chou kale","steps":["Cuire le quinoa à couvert dans une casserole avec 280 ml d''eau salée pendant 15 min, jusqu''à absorption ; laisser reposer 5 min.","Frotter le poulet avec le cumin, le paprika, la moitié de l''huile, du sel et du poivre.","Cuire le poulet au air fryer à 200 °C pendant 12 à 14 min en le retournant à mi-cuisson, jusqu''à ce qu''il soit doré et à 75 °C à cœur.","Fouetter le tahini avec la moitié du jus de citron, 1 gousse d''ail râpée, une pincée de sel et 4 à 5 c. à soupe d''eau froide jusqu''à obtenir une sauce lisse et fluide.","Chauffer le reste de l''huile dans une poêle, ajouter la seconde gousse d''ail émincée et le chou kale avec un peu d''eau et cuire 3 à 4 min jusqu''à ce qu''il soit tendre.","Incorporer le chou kale et le reste du jus de citron au quinoa, garnir du poulet tranché, de la sauce tahini et du persil."]},"it":{"title":"Sovracosce di pollo in friggitrice ad aria con salsa tahina e limone, quinoa e cavolo riccio","steps":["Cuocere la quinoa coperta in una pentola con 280 ml d''acqua salata per 15 min, finché l''acqua è assorbita; lasciarla riposare 5 min.","Massaggiare il pollo con cumino, paprika, metà dell''olio, sale e pepe.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–14 min, girandolo a metà, finché è dorato e a 75 °C al cuore.","Sbattere la tahina con metà del succo di limone, 1 spicchio d''aglio grattugiato, un pizzico di sale e 4–5 cucchiai d''acqua fredda fino a ottenere una salsa liscia e fluida.","Scaldare il resto dell''olio in una padella, aggiungere il secondo spicchio d''aglio a fettine e il cavolo con un goccio d''acqua e cuocere 3–4 min finché è tenero.","Unire il cavolo e il resto del succo di limone alla quinoa, completare con il pollo affettato, la salsa tahina e il prezzemolo."]}}'::jsonb),
  ('f006e547-e528-5078-be45-4fe999de4982'::uuid, '{"fr":{"title":"Wraps au poulet cajun et salsa de maïs","steps":["Mélanger le poulet avec les épices cajun et une pincée de sel.","Mélanger le maïs, la tomate, l''oignon rouge, la coriandre et le jus d''un demi-citron vert pour la salsa ; saler.","Incorporer le zeste et le reste du jus de citron vert au yaourt.","Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire le poulet et le poivron 8 à 10 min en remuant, jusqu''à ce que le poulet soit grillé sur les bords et cuit.","Essuyer la poêle et y réchauffer les tortillas 20 secondes de chaque côté.","Tartiner chaque tortilla de yaourt au citron vert, ajouter la salade, le poulet et le poivron et une cuillerée de salsa, puis rouler."]},"it":{"title":"Wrap di pollo cajun con salsa di mais","steps":["Condire il pollo con le spezie cajun e un pizzico di sale.","Mescolare mais, pomodoro, cipolla rossa, coriandolo e il succo di mezzo lime per la salsa; salare.","Unire allo yogurt la scorza e il resto del succo di lime.","Scaldare l''olio in una padella grande a fuoco medio-alto e cuocere pollo e peperone per 8–10 min, mescolando, finché il pollo è abbrustolito ai bordi e cotto.","Pulire la padella e scaldarvi le tortillas 20 secondi per lato.","Spalmare ogni tortilla con lo yogurt al lime, aggiungere insalata, pollo e peperone e un cucchiaio di salsa, poi arrotolare."]}}'::jsonb),
  ('7279a898-d04d-57eb-b82b-e31b57e6571a'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet chili doux-citron vert au air fryer, salade de nouilles de riz","steps":["Mélanger 2 c. à soupe de sauce chili douce avec la sauce soja, le zeste d''un citron vert, l''ail et le gingembre ; en enrober le poulet et laisser mariner 15 min.","Cuire le poulet au air fryer à 200 °C pendant 12 à 14 min, en le retournant à mi-cuisson et en le badigeonnant d''1 c. à soupe de sauce chili douce pour les 3 dernières minutes, jusqu''à ce qu''il soit laqué et à 75 °C à cœur.","Pendant ce temps, cuire les vermicelles dans une casserole d''eau bouillante selon le paquet (3 à 4 min en général), puis égoutter et rincer à l''eau froide.","Fouetter le reste de sauce chili douce avec la sauce de poisson, le jus des deux citrons verts et 1 c. à soupe d''eau.","Mélanger les nouilles avec la carotte, le concombre, les herbes et presque toute la sauce.","Trancher le poulet, le poser sur les nouilles, arroser du reste de sauce et parsemer de cacahuètes."]},"it":{"title":"Sovracosce di pollo chili dolce e lime in friggitrice ad aria con insalata di noodles di riso","steps":["Mescolare 2 cucchiai di salsa chili dolce con la salsa di soia, la scorza di 1 lime, l''aglio e lo zenzero; ricoprirne il pollo e lasciar marinare 15 min.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12–14 min, girandolo a metà e spennellandolo con 1 cucchiaio di salsa chili dolce negli ultimi 3 min, finché è laccato e a 75 °C al cuore.","Nel frattempo cuocere i vermicelli in una pentola d''acqua bollente come indicato sulla confezione (di solito 3–4 min), poi scolarli e sciacquarli in acqua fredda.","Sbattere il resto della salsa chili dolce con la salsa di pesce, il succo dei due lime e 1 cucchiaio d''acqua.","Condire i noodles con carota, cetriolo, erbe e quasi tutto il condimento.","Affettare il pollo, adagiarlo sui noodles, irrorare con il resto del condimento e cospargere di arachidi."]}}'::jsonb),
  ('0cabb57a-3d4c-5c88-9932-e0c5a59cac95'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet, salsa verde, pommes de terre nouvelles et asperges","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 à 18 min jusqu''à ce qu''elles soient tendres.","Saler et poivrer le poulet et le cuire dans 1 c. à soupe d''huile dans une poêle à feu moyen-vif, 6 à 7 min de chaque côté, jusqu''à ce qu''il soit bien doré et à 75 °C à cœur ; laisser reposer 3 min.","Pendant ce temps, mélanger le persil, le basilic, les câpres, les anchois, l''ail, la moutarde et le vinaigre, puis incorporer les 3 c. à soupe d''huile d''olive et poivrer.","Ajouter les asperges aux pommes de terre pour les 3 dernières minutes, puis égoutter.","Mélanger les pommes de terre et les asperges avec une cuillerée de salsa verde.","Trancher le poulet et le servir avec les légumes, nappé du reste de salsa verde."]},"it":{"title":"Sovracosce di pollo con salsa verde, patate novelle e asparagi","steps":["Mettere le patate in una pentola d''acqua fredda salata, portare a bollore e cuocere 15–18 min finché sono tenere.","Salare e pepare il pollo e cuocerlo con 1 cucchiaio d''olio in una padella a fuoco medio-alto, 6–7 min per lato, finché è ben dorato e a 75 °C al cuore; farlo riposare 3 min.","Nel frattempo mescolare prezzemolo, basilico, capperi, acciughe, aglio, senape e aceto, poi unire i 3 cucchiai d''olio e pepare.","Aggiungere gli asparagi alle patate negli ultimi 3 min, poi scolare.","Condire patate e asparagi con un cucchiaio di salsa verde.","Affettare il pollo e servirlo con le verdure e il resto della salsa verde sopra."]}}'::jsonb),
  ('ee06f3e4-ef46-5b0a-b781-30f1a1934e5c'::uuid, '{"fr":{"title":"Escalopes de dinde au chimichurri, potatoes au air fryer et salade de tomates","steps":["Mélanger les quartiers de pommes de terre avec 1 c. à soupe d''huile d''olive, le paprika et du sel, et les cuire au air fryer à 200 °C pendant 20 à 22 min en secouant deux fois, jusqu''à ce qu''ils soient croustillants et dorés.","Pour le chimichurri, mélanger le persil, l''ail, l''origan, le piment et le vinaigre avec une pincée de sel, puis incorporer les 3 c. à soupe d''huile d''olive ; laisser reposer.","Mélanger les tomates et l''oignon rouge avec une pincée de sel et une cuillerée de chimichurri.","Quand il reste 6 min aux pommes de terre, saler et poivrer la dinde et la cuire dans l''huile végétale dans une poêle chaude 2 à 3 min de chaque côté, jusqu''à ce qu''elle soit dorée et juste cuite (74 °C).","Laisser reposer la dinde 2 min, puis la trancher.","Servir la dinde avec les pommes de terre et la salade de tomates, nappée de chimichurri."]},"it":{"title":"Fettine di tacchino al chimichurri con spicchi di patate in friggitrice ad aria e insalata di pomodori","steps":["Condire gli spicchi di patate con 1 cucchiaio d''olio, la paprika e sale e cuocerli in friggitrice ad aria a 200 °C per 20–22 min, scuotendo due volte, finché sono croccanti e dorati.","Per il chimichurri mescolare prezzemolo, aglio, origano, peperoncino e aceto con un pizzico di sale, poi unire i 3 cucchiai d''olio; lasciar riposare.","Condire pomodorini e cipolla rossa con un pizzico di sale e un cucchiaio di chimichurri.","Quando alle patate mancano 6 min, salare e pepare il tacchino e cuocerlo con l''olio di semi in una padella calda 2–3 min per lato, finché è dorato e appena cotto (74 °C).","Far riposare il tacchino 2 min, poi affettarlo.","Servire il tacchino con le patate e l''insalata di pomodori, con il chimichurri sopra."]}}'::jsonb),
  ('6964efee-3927-5498-af12-87b83d2534ae'::uuid, '{"fr":{"title":"Pains plats au shawarma de dinde au air fryer, sauce tahini","steps":["Mélanger les épices, 1 gousse d''ail, la moitié du jus de citron, l''huile d''olive et une bonne pincée de sel, et y enrober la dinde ; laisser mariner 20 min (ou jusqu''à un jour au réfrigérateur).","Fouetter le tahini, le yaourt, le reste de l''ail et un filet de citron avec 1 à 2 c. à soupe d''eau et une pincée de sel.","Mélanger le chou avec le reste du jus de citron et une pincée de sel.","Étaler la dinde dans le panier du air fryer et cuire à 200 °C pendant 8 à 10 min en secouant à mi-cuisson, jusqu''à ce qu''elle soit grillée sur les bords et cuite.","Réchauffer les pitas dans une poêle sèche 30 secondes de chaque côté.","Tartiner les pitas de sauce tahini et garnir de chou, de tomate, de dinde, de cornichons et de persil."]},"it":{"title":"Piadine di shawarma di tacchino in friggitrice ad aria con salsa tahina","steps":["Mescolare le spezie, 1 spicchio d''aglio, metà del succo di limone, l''olio e un bel pizzico di sale e condirvi il tacchino; lasciar marinare 20 min (o fino a un giorno in frigo).","Sbattere la tahina, lo yogurt, il resto dell''aglio e una spruzzata di limone con 1–2 cucchiai d''acqua e un pizzico di sale.","Condire il cavolo con il resto del succo di limone e un pizzico di sale.","Distribuire il tacchino nel cestello della friggitrice e cuocere a 200 °C per 8–10 min, scuotendo a metà, finché è abbrustolito ai bordi e cotto.","Scaldare le pite in una padella asciutta 30 secondi per lato.","Spalmare le pite con la salsa tahina e farcire con cavolo, pomodoro, tacchino, cetriolini e prezzemolo."]}}'::jsonb),
  ('b91c4fb8-73a7-5b7f-87e3-3b902ea315a9'::uuid, '{"fr":{"title":"Tikka de dinde au air fryer, riz pilaf aux épinards","steps":["Mélanger le yaourt, le garam masala, le paprika, le piment, le curcuma, la moitié du cumin, l''ail, le gingembre, le jus d''un demi-citron, le fenugrec et une bonne pincée de sel ; en enrober la dinde et laisser mariner au moins 20 min.","Chauffer l''huile dans une casserole, faire revenir l''oignon avec le laurier et le reste du cumin 4 min, puis ajouter le riz en remuant.","Ajouter 300 ml d''eau et une pincée de sel, porter à ébullition, couvrir et cuire 12 min à feu doux.","Pendant ce temps, cuire la dinde au air fryer à 200 °C pendant 10 à 12 min en la retournant à mi-cuisson, jusqu''à ce qu''elle soit grillée sur les bords et à 74 °C à cœur.","Déposer les épinards sur le riz, recouvrir et laisser 5 min hors du feu, puis les mélanger au riz.","Servir la dinde sur le riz avec la coriandre et le reste du citron en quartiers."]},"it":{"title":"Tikka di tacchino in friggitrice ad aria con riso pilaf agli spinaci","steps":["Mescolare yogurt, garam masala, paprika, peperoncino in polvere, curcuma, metà del cumino, aglio, zenzero, il succo di mezzo limone, il fieno greco e un bel pizzico di sale; ricoprirne il tacchino e lasciar marinare almeno 20 min.","Scaldare l''olio in una pentola, far appassire la cipolla con l''alloro e il resto del cumino per 4 min, poi unire il riso mescolando.","Aggiungere 300 ml d''acqua e un pizzico di sale, portare a bollore, coprire e cuocere 12 min a fuoco basso.","Nel frattempo cuocere il tacchino in friggitrice ad aria a 200 °C per 10–12 min, girandolo a metà, finché è abbrustolito ai bordi e a 74 °C al cuore.","Adagiare gli spinaci sul riso, coprire di nuovo e lasciare 5 min fuori dal fuoco, poi mescolarli al riso.","Servire il tacchino sul riso con il coriandolo e il resto del limone a spicchi."]}}'::jsonb),
  ('71449b68-635a-5e6a-9e94-d662693b30d1'::uuid, '{"fr":{"title":"Escalopes de dinde, poireaux au miel et à la moutarde, pommes de terre","steps":["Cuire les pommes de terre 15 à 18 min à l''eau salée jusqu''à ce qu''elles soient tendres, puis égoutter.","Saler et poivrer les escalopes et les fariner légèrement.","Chauffer l''huile dans une grande poêle à feu moyen-vif et cuire la dinde 3 min de chaque côté jusqu''à ce qu''elle soit dorée et juste cuite ; réserver sur une assiette.","Baisser le feu, ajouter le beurre, les poireaux, le thym et une pincée de sel et cuire 6 à 8 min jusqu''à ce qu''ils soient fondants.","Ajouter le bouillon, les deux moutardes et le miel et laisser bouillonner 2 min, puis incorporer la crème fraîche.","Remettre la dinde et son jus dans la poêle 1 à 2 min pour la réchauffer, et servir avec les pommes de terre et le persil."]},"it":{"title":"Scaloppine di tacchino con porri al miele e senape e patate","steps":["Lessare le patate in acqua salata per 15–18 min finché sono tenere, poi scolarle.","Salare e pepare le scaloppine e infarinarle leggermente.","Scaldare l''olio in una padella grande a fuoco medio-alto e cuocere il tacchino 3 min per lato finché è dorato e appena cotto; tenerlo da parte su un piatto.","Abbassare il fuoco, aggiungere burro, porri, timo e un pizzico di sale e cuocere 6–8 min finché sono morbidi.","Unire il brodo, le due senapi e il miele e far sobbollire 2 min, poi incorporare la crème fraîche.","Rimettere il tacchino con il suo sugo nella padella per 1–2 min per scaldarlo e servire con le patate e il prezzemolo."]}}'::jsonb),
  ('91ff547e-b20b-5179-815e-98b0e7f66a74'::uuid, '{"fr":{"title":"Souvlaki de dinde au air fryer, boulgour, salade de tomates et tzatziki","steps":["Mélanger la dinde avec l''huile d''olive, le zeste et la moitié du jus de citron, l''origan, 1 gousse d''ail, du sel et du poivre ; laisser mariner 15 min et l''enfiler sur des brochettes si on le souhaite.","Porter le boulgour et le bouillon à ébullition dans une casserole, couvrir et cuire à feu doux 10 à 12 min, puis laisser reposer hors du feu.","Pour le tzatziki, râper grossièrement la moitié du concombre, l''essorer et le mélanger avec le yaourt, le reste de l''ail, l''aneth et une pincée de sel.","Cuire la dinde au air fryer à 200 °C pendant 10 à 12 min en la retournant à mi-cuisson, jusqu''à ce qu''elle soit dorée sur les bords et à 74 °C à cœur.","Couper le reste du concombre en dés et le mélanger avec les tomates, l''oignon rouge, la feta et le reste du jus de citron.","Égrener le boulgour et le servir avec la dinde, la salade et le tzatziki."]},"it":{"title":"Souvlaki di tacchino in friggitrice ad aria con bulgur, insalata di pomodori e tzatziki","steps":["Condire il tacchino con l''olio, la scorza e metà del succo di limone, l''origano, 1 spicchio d''aglio, sale e pepe; lasciar marinare 15 min e infilarlo su spiedini se si vuole.","Portare a bollore il bulgur con il brodo in una pentola, coprire e cuocere a fuoco dolce 10–12 min, poi lasciar riposare fuori dal fuoco.","Per lo tzatziki grattugiare grossolanamente metà del cetriolo, strizzarlo e mescolarlo con lo yogurt, il resto dell''aglio, l''aneto e un pizzico di sale.","Cuocere il tacchino in friggitrice ad aria a 200 °C per 10–12 min, girandolo a metà, finché è dorato ai bordi e a 74 °C al cuore.","Tagliare a dadini il resto del cetriolo e condirlo con pomodori, cipolla rossa, feta e il resto del succo di limone.","Sgranare il bulgur e servirlo con il tacchino, l''insalata e lo tzatziki."]}}'::jsonb),
  ('324e881a-69b4-581b-90e6-1056bc56fe28'::uuid, '{"fr":{"title":"Steak sauce romesco, pommes de terre au air fryer et brocoli","steps":["Mélanger les pommes de terre avec 1 c. à soupe d''huile d''olive, 1 c. à café de paprika fumé et du sel, et les cuire au air fryer à 200 °C pendant 20 à 22 min en secouant deux fois, jusqu''à ce qu''elles soient croustillantes.","Mixer les poivrons grillés, les amandes, l''ail, le concentré de tomate, le vinaigre, le reste du paprika et les 2 c. à soupe d''huile d''olive pour obtenir une sauce épaisse et un peu rustique ; saler.","Sortir les steaks du réfrigérateur 10 min avant la cuisson, les sécher et bien les assaisonner.","Cuire le brocoli 3 à 4 min dans une casserole d''eau salée bouillante jusqu''à ce qu''il soit juste tendre, puis égoutter.","Saisir les steaks dans l''huile végétale dans une poêle très chaude 2 à 3 min de chaque côté pour une cuisson à point-saignant, puis les laisser reposer 5 min.","Trancher les steaks et servir avec les pommes de terre, le brocoli et une belle cuillerée de romesco."]},"it":{"title":"Bistecca con salsa romesco, patate in friggitrice ad aria e broccoli","steps":["Condire le patate con 1 cucchiaio d''olio, 1 cucchiaino di paprika affumicata e sale e cuocerle in friggitrice ad aria a 200 °C per 20–22 min, scuotendo due volte, finché sono croccanti.","Frullare i peperoni arrostiti, le mandorle, l''aglio, il concentrato, l''aceto, il resto della paprika e i 2 cucchiai d''olio fino a ottenere una salsa densa e un po'' rustica; salare.","Togliere le bistecche dal frigo 10 min prima di cuocerle, asciugarle e condirle bene.","Lessare i broccoli in una pentola d''acqua salata bollente per 3–4 min finché sono appena teneri, poi scolarli.","Scottare le bistecche con l''olio di semi in una padella molto calda per 2–3 min per lato per una cottura al sangue-media, poi farle riposare 5 min.","Affettare le bistecche e servire con patate, broccoli e un''abbondante cucchiaiata di romesco."]}}'::jsonb),
  ('ab56082b-eb3f-5fe6-9fb7-ef4cf68508ad'::uuid, '{"fr":{"title":"Boulettes de bœuf teriyaki au air fryer, riz et haricots verts","steps":["Rincer le riz et le mettre dans une casserole avec 300 ml d''eau ; porter à ébullition, couvrir et cuire 12 min à feu doux.","Mélanger le bœuf, le panko, l''œuf, la moitié de l''oignon nouveau, l''ail, le gingembre et une pincée de sel, et former 12 boulettes.","Cuire les boulettes au air fryer à 200 °C pendant 10 à 12 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient dorées et cuites.","Déposer les haricots verts sur le riz pour les 6 dernières minutes, recouvrir, puis laisser reposer le tout 5 min hors du feu.","Pour le teriyaki, porter à frémissement la sauce soja, le mirin, le miel et 3 c. à soupe d''eau dans une petite casserole, ajouter la fécule délayée dans 1 c. à soupe d''eau froide et laisser bouillonner 1 min jusqu''à ce que la sauce soit brillante.","Enrober les boulettes de sauce et servir sur le riz avec les haricots, les graines de sésame et le reste de l''oignon nouveau."]},"it":{"title":"Polpette di manzo teriyaki in friggitrice ad aria con riso e fagiolini","steps":["Sciacquare il riso e metterlo in una pentola con 300 ml d''acqua; portare a bollore, coprire e cuocere 12 min a fuoco basso.","Mescolare manzo, panko, uovo, metà del cipollotto, aglio, zenzero e un pizzico di sale e formare 12 polpette.","Cuocere le polpette in friggitrice ad aria a 200 °C per 10–12 min, scuotendo a metà, finché sono dorate e cotte.","Adagiare i fagiolini sul riso negli ultimi 6 min, coprire di nuovo, poi lasciar riposare tutto 5 min fuori dal fuoco.","Per il teriyaki portare a sobbollire salsa di soia, mirin, miele e 3 cucchiai d''acqua in un pentolino, unire l''amido sciolto in 1 cucchiaio d''acqua fredda e cuocere 1 min finché è lucida.","Ripassare le polpette nella salsa e servirle sul riso con i fagiolini, i semi di sesamo e il resto del cipollotto."]}}'::jsonb),
  ('68a03d91-944b-5da3-954a-1d168df79923'::uuid, '{"fr":{"title":"Bœuf haché à la harissa, courge rôtie et semoule","steps":["Préchauffer le four à 220 °C. Mélanger la courge avec 1 c. à soupe d''huile, la moitié du cumin et du sel sur une plaque et rôtir 25 min en retournant une fois, jusqu''à ce qu''elle soit tendre et caramélisée.","Chauffer la cuillère à café d''huile dans une poêle et faire revenir l''oignon 5 min.","Ajouter le bœuf et l''ail et cuire à feu vif 5 à 6 min en émiettant, jusqu''à ce qu''il soit bien doré.","Ajouter la harissa, le concentré de tomate, le reste du cumin et 100 ml d''eau et laisser mijoter 5 min jusqu''à obtenir une sauce ; saler.","Pendant ce temps, verser le bouillon bouillant sur la semoule dans un saladier, couvrir et laisser gonfler 5 min, puis égrener à la fourchette.","Servir la semoule garnie du bœuf et de la courge, d''une cuillerée de yaourt et de menthe."]},"it":{"title":"Manzo macinato all''harissa con zucca arrosto e cous cous","steps":["Scaldare il forno a 220 °C. Condire la zucca con 1 cucchiaio d''olio, metà del cumino e sale su una teglia e arrostirla 25 min, girandola una volta, finché è morbida e caramellata.","Scaldare il cucchiaino d''olio in una padella e far appassire la cipolla per 5 min.","Aggiungere il manzo e l''aglio e cuocere a fuoco vivo 5–6 min, sgranandolo, finché è ben rosolato.","Unire harissa, concentrato, il resto del cumino e 100 ml d''acqua e cuocere 5 min finché si forma un sugo; salare.","Nel frattempo versare il brodo bollente sul cous cous in una ciotola, coprire e lasciar riposare 5 min, poi sgranare con la forchetta.","Servire il cous cous con il manzo e la zucca sopra, un cucchiaio di yogurt e la menta."]}}'::jsonb),
  ('eb23031d-172b-5243-816a-c74788837fc3'::uuid, '{"fr":{"title":"Nouilles au bœuf miel-gochujang et épinards","steps":["Mélanger le bœuf avec la fécule et 1 c. à café de sauce soja.","Fouetter le gochujang, le miel, 1 c. à soupe de sauce soja, le vinaigre de riz, l''ail et l''huile de sésame avec 2 c. à soupe d''eau.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet (4 min en général), puis égoutter.","Chauffer l''huile dans un wok à feu vif et faire sauter le bœuf 2 min jusqu''à ce qu''il soit saisi ; le retirer.","Faire sauter l''oignon et l''oignon nouveau 2 min, puis ajouter les épinards et remuer 1 min jusqu''à ce qu''ils tombent à peine.","Remettre le bœuf avec les nouilles et la sauce et mélanger 1 min jusqu''à ce que tout soit bien laqué ; servir avec les graines de sésame."]},"it":{"title":"Noodles di manzo al miele e gochujang con spinaci","steps":["Condire il manzo con l''amido e 1 cucchiaino di salsa di soia.","Sbattere gochujang, miele, 1 cucchiaio di salsa di soia, aceto di riso, aglio e olio di sesamo con 2 cucchiai d''acqua.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione (di solito 4 min), poi scolarli.","Scaldare l''olio in un wok a fuoco vivo e saltare il manzo 2 min finché è rosolato; toglierlo.","Saltare cipolla e cipollotto per 2 min, poi aggiungere gli spinaci e mescolare 1 min finché appassiscono appena.","Rimettere il manzo con i noodles e la salsa e saltare 1 min finché tutto è ben laccato; servire con i semi di sesamo."]}}'::jsonb),
  ('c6ba679c-0cf6-522d-a8e9-237a8b75c15d'::uuid, '{"fr":{"title":"Udon au bœuf et au poivre noir, chou sauté","steps":["Mélanger le bœuf avec la fécule et 1 c. à café de sauce soja ; mélanger les 2 c. à soupe de sauce soja, la sauce d''huître, le sucre, le poivre et 4 c. à soupe d''eau pour la sauce.","Mettre les udon dans un saladier, les couvrir d''eau bouillante 1 min pour les détacher, puis égoutter.","Chauffer l''huile dans un wok à feu vif et faire sauter le bœuf 2 min jusqu''à ce qu''il soit saisi ; le retirer.","Faire sauter l''oignon, l''ail et le chou 3 à 4 min jusqu''à ce que le chou soit tombé mais encore croquant.","Ajouter les udon, le bœuf et la sauce et mélanger 2 min jusqu''à ce que les nouilles soient chaudes et enrobées de sauce poivrée.","Servir aussitôt avec l''oignon nouveau."]},"it":{"title":"Udon al manzo e pepe nero con cavolo","steps":["Condire il manzo con l''amido e 1 cucchiaino di salsa di soia; mescolare i 2 cucchiai di salsa di soia, la salsa d''ostrica, lo zucchero, il pepe e 4 cucchiai d''acqua per la salsa.","Mettere gli udon in una ciotola, coprirli con acqua bollente per 1 min per separarli, poi scolarli.","Scaldare l''olio in un wok a fuoco vivo e saltare il manzo 2 min finché è rosolato; toglierlo.","Saltare cipolla, aglio e cavolo per 3–4 min finché il cavolo è appassito ma ancora croccante.","Unire gli udon, il manzo e la salsa e saltare 2 min finché i noodles sono caldi e avvolti dalla salsa pepata.","Servire subito con il cipollotto."]}}'::jsonb),
  ('be62c0b2-60d2-547b-84c7-e6d0a13b3c07'::uuid, '{"fr":{"title":"Côtes de porc miel-moutarde au air fryer, pommes de terre et choux de Bruxelles","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min à frémissement.","Mélanger les deux moutardes, le miel, l''huile d''olive et l''ail ; saler et poivrer les côtes et les badigeonner de la moitié du mélange.","Cuire les côtes au air fryer à 200 °C pendant 10 à 12 min en les retournant à mi-cuisson, jusqu''à 63 °C à cœur ; les laisser reposer 5 min.","Ajouter les choux de Bruxelles aux pommes de terre pour les 6 dernières minutes, puis égoutter et mélanger avec le beurre, du sel et du poivre.","Porter à ébullition le reste du mélange miel-moutarde avec le bouillon dans une petite casserole et laisser réduire 1 à 2 min jusqu''à ce qu''il épaississe légèrement.","Servir les côtes avec les pommes de terre et les choux de Bruxelles, nappées de sauce."]},"it":{"title":"Braciole di maiale al miele e senape in friggitrice ad aria con patate e cavolini di Bruxelles","steps":["Mettere le patate in una pentola d''acqua fredda salata, portare a bollore e cuocere 15 min a fuoco medio.","Mescolare le due senapi, il miele, l''olio e l''aglio; salare e pepare le braciole e spennellarle con metà del composto.","Cuocere le braciole in friggitrice ad aria a 200 °C per 10–12 min, girandole a metà, finché raggiungono 63 °C al cuore; farle riposare 5 min.","Aggiungere i cavolini alle patate negli ultimi 6 min, poi scolare e condire con il burro, sale e pepe.","Portare a bollore il resto del composto al miele e senape con il brodo in un pentolino e far ridurre 1–2 min finché si addensa leggermente.","Servire le braciole con patate e cavolini, con la salsa versata sopra."]}}'::jsonb),
  ('05a8e01f-949a-5a2e-bf71-1b877f338bc1'::uuid, '{"fr":{"title":"Filet mignon de porc jerk au air fryer, riz aux haricots rouges et coleslaw","steps":["Frotter le porc avec l''assaisonnement jerk, l''huile et le jus d''un demi-citron vert ; laisser mariner 15 min (ou jusqu''à un jour au réfrigérateur).","Mettre le riz, le lait de coco, 150 ml d''eau, les haricots, la moitié de l''oignon nouveau, l''ail, le thym, le piment de la Jamaïque et une pincée de sel dans une casserole ; porter à ébullition, couvrir et cuire 15 min à feu doux, puis laisser reposer 5 min.","Couper le filet mignon en deux morceaux plus courts et le cuire au air fryer à 200 °C pendant 16 à 18 min en le retournant à mi-cuisson, jusqu''à 63 °C à cœur.","Laisser reposer le porc 5 min pendant que l''on mélange le chou et la carotte avec le jus d''un citron vert et une pincée de sel.","Retirer le thym du riz et l''égrener à la fourchette.","Trancher le porc et servir avec le riz, le coleslaw, le reste de l''oignon nouveau et des quartiers de citron vert."]},"it":{"title":"Filetto di maiale jerk in friggitrice ad aria con riso e fagioli e insalata di cavolo","steps":["Massaggiare il maiale con le spezie jerk, l''olio e il succo di mezzo lime; lasciar marinare 15 min (o fino a un giorno in frigo).","Mettere in una pentola riso, latte di cocco, 150 ml d''acqua, fagioli, metà del cipollotto, aglio, timo, pimento e un pizzico di sale; portare a bollore, coprire e cuocere 15 min a fuoco basso, poi lasciar riposare 5 min.","Tagliare il filetto in due pezzi più corti e cuocerlo in friggitrice ad aria a 200 °C per 16–18 min, girandolo a metà, finché raggiunge 63 °C al cuore.","Far riposare il maiale 5 min mentre si condiscono cavolo e carota con il succo di 1 lime e un pizzico di sale.","Togliere il timo dal riso e sgranarlo con la forchetta.","Affettare il maiale e servirlo con riso e fagioli, l''insalata di cavolo, il resto del cipollotto e spicchi di lime."]}}'::jsonb),
  ('b0dcc451-b61c-5159-81e5-e140eb635520'::uuid, '{"fr":{"title":"Porc haché sauté aux haricots verts, sauce ail-piment et riz","steps":["Cuire le riz dans une casserole avec 300 ml d''eau : porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer 5 min.","Mélanger la sriracha, la sauce soja, la sauce d''huître, le sucre, le vinaigre de riz et l''huile de sésame avec 2 c. à soupe d''eau.","Chauffer l''huile dans un wok à feu vif et faire sauter les haricots verts 4 à 5 min jusqu''à ce qu''ils soient cloqués et juste tendres ; les pousser sur le côté.","Ajouter le porc et cuire 4 à 5 min en l''émiettant, jusqu''à ce qu''il soit doré et un peu croustillant.","Ajouter l''ail, le gingembre et le piment et faire sauter 1 min jusqu''à ce qu''ils embaument.","Verser la sauce et mélanger 1 min pour tout enrober ; servir sur le riz avec l''oignon nouveau."]},"it":{"title":"Maiale macinato saltato con fagiolini, salsa aglio e peperoncino e riso","steps":["Cuocere il riso in una pentola con 300 ml d''acqua: portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare 5 min.","Mescolare sriracha, salsa di soia, salsa d''ostrica, zucchero, aceto di riso e olio di sesamo con 2 cucchiai d''acqua.","Scaldare l''olio in un wok a fuoco vivo e saltare i fagiolini per 4–5 min finché sono abbrustoliti e appena teneri; spingerli di lato.","Aggiungere il maiale e cuocere 4–5 min, sgranandolo, finché è rosolato e un po'' croccante.","Aggiungere aglio, zenzero e peperoncino e saltare 1 min finché sprigionano il profumo.","Versare la salsa e saltare 1 min finché avvolge tutto; servire sul riso con il cipollotto."]}}'::jsonb),
  ('a043608c-b12a-5954-9def-cfb521936032'::uuid, '{"fr":{"title":"Satay de porc au air fryer, riz et pickles minute de concombre","steps":["Mélanger la sauce soja, la coriandre, le curcuma, le sucre, l''huile et l''ail, y enrober le porc et laisser mariner 20 min ; l''enfiler sur des brochettes adaptées au air fryer.","Cuire le riz dans une casserole avec 300 ml d''eau : porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer 5 min.","Mélanger le concombre et l''oignon rouge avec le vinaigre de riz, le sucre du pickle et une pincée de sel.","Cuire les brochettes au air fryer à 200 °C pendant 8 à 10 min en les retournant une fois, jusqu''à ce qu''elles soient grillées sur les bords et cuites.","Pendant ce temps, chauffer le beurre de cacahuète, le lait de coco, la sauce soja, le miel et la sriracha dans une petite casserole 2 à 3 min en remuant, jusqu''à obtenir une sauce lisse et épaisse ; ajouter du jus de citron vert selon le goût.","Servir les brochettes sur le riz avec la sauce satay et les pickles de concombre."]},"it":{"title":"Satay di maiale in friggitrice ad aria con riso e cetriolo marinato","steps":["Mescolare salsa di soia, coriandolo, curcuma, zucchero, olio e aglio, condirvi il maiale e lasciar marinare 20 min; infilarlo su spiedini adatti alla friggitrice.","Cuocere il riso in una pentola con 300 ml d''acqua: portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare 5 min.","Condire cetriolo e cipolla rossa con l''aceto di riso, lo zucchero per il marinato e un pizzico di sale.","Cuocere gli spiedini in friggitrice ad aria a 200 °C per 8–10 min, girandoli una volta, finché sono abbrustoliti ai bordi e cotti.","Nel frattempo scaldare burro di arachidi, latte di cocco, salsa di soia, miele e sriracha in un pentolino per 2–3 min, mescolando, finché la salsa è liscia e densa; aggiungere succo di lime a piacere.","Servire gli spiedini sul riso con la salsa satay e il cetriolo marinato."]}}'::jsonb),
  ('8ff6285f-bed7-538b-b68f-bc3d0973f4a8'::uuid, '{"fr":{"title":"Médaillons de porc, salsa verde et semoule aux courgettes","steps":["Pour la salsa verde, mélanger le persil, le basilic, la menthe, les câpres, l''ail, la moutarde et le vinaigre, puis incorporer les 3 c. à soupe d''huile d''olive et poivrer.","Chauffer la moitié de l''huile dans une grande poêle à feu vif et faire dorer les courgettes 5 à 6 min ; saler et les verser dans un saladier.","Ajouter la semoule et le bouillon bouillant dans le saladier, couvrir et laisser gonfler 5 min.","Aplatir légèrement les médaillons, les assaisonner et les cuire dans le reste de l''huile dans la même poêle 3 min de chaque côté jusqu''à ce qu''ils soient dorés et juste cuits (63 °C).","Égrener la semoule avec le zeste et le jus de citron et une cuillerée de salsa verde.","Servir le porc sur la semoule, nappé du reste de salsa verde."]},"it":{"title":"Medaglioni di maiale con salsa verde e cous cous alle zucchine","steps":["Per la salsa verde mescolare prezzemolo, basilico, menta, capperi, aglio, senape e aceto, poi unire i 3 cucchiai d''olio e pepare.","Scaldare metà dell''olio in una padella grande a fuoco vivo e rosolare le zucchine per 5–6 min finché sono dorate; salarle e trasferirle in una ciotola.","Aggiungere nella ciotola il cous cous e il brodo bollente, coprire e lasciar riposare 5 min.","Schiacciare leggermente i medaglioni, condirli e cuocerli con il resto dell''olio nella stessa padella per 3 min per lato finché sono dorati e appena cotti (63 °C).","Sgranare il cous cous con scorza e succo di limone e un cucchiaio di salsa verde.","Servire il maiale sul cous cous con il resto della salsa verde sopra."]}}'::jsonb),
  ('4afb5fe7-2ef2-452e-86a5-81da6eebe426'::uuid, '{"fr":{"title":"Saumon teriyaki au air fryer, riz et brocoli","steps":["Mélanger la sauce soja, le mirin, le miel, l''ail et le gingembre. En verser un tiers sur le saumon dans un plat et laisser 15 min pendant que le riz démarre.","Rincer le riz et le cuire à couvert dans 225 ml d''eau 12 min à feu doux.","Répartir le brocoli sur le riz, remettre le couvercle et cuire à la vapeur 5 min de plus, puis laisser reposer 5 min hors du feu.","Préchauffer le air fryer à 200 °C. Poser le saumon côté peau dans le panier et cuire 8 à 9 min, jusqu''à ce qu''il s''effeuille tout en restant juste rosé à cœur.","Pendant ce temps, faire frémir le reste de sauce dans une petite casserole avec la fécule délayée dans 2 c. à soupe d''eau, 1 à 2 min, jusqu''à ce qu''elle soit brillante et nappante.","Mélanger le brocoli avec l''huile de sésame et une pincée de sel.","Servir le saumon sur le riz avec le brocoli, napper de sauce teriyaki et finir avec les graines de sésame et l''oignon nouveau."]},"it":{"title":"Salmone teriyaki in friggitrice ad aria con riso e broccoli","steps":["Mescolare salsa di soia, mirin, miele, aglio e zenzero. Versarne un terzo sul salmone in un piatto e lasciarlo 15 min mentre si avvia il riso.","Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua per 12 min a fuoco basso.","Distribuire i broccoli sul riso, rimettere il coperchio e cuocere a vapore altri 5 min, poi lasciar riposare 5 min fuori dal fuoco.","Scaldare la friggitrice ad aria a 200 °C. Disporre il salmone con la pelle in basso nel cestello e cuocere 8-9 min, finché si sfalda ma resta appena rosato al centro.","Intanto far sobbollire il resto della salsa in un pentolino con l''amido stemperato in 2 cucchiai d''acqua, 1-2 min, finché è lucida e vela il cucchiaio.","Condire i broccoli con l''olio di sesamo e un pizzico di sale.","Servire il salmone sul riso con i broccoli, nappare con la salsa teriyaki e finire con sesamo e cipollotto."]}}'::jsonb),
  ('38b6fe91-83fe-46ac-8292-00b83183c374'::uuid, '{"fr":{"title":"Pâtes au saumon et au pesto, petits pois et épinards","steps":["Porter une grande casserole d''eau salée à ébullition et cuire les pâtes le temps indiqué sur le paquet.","Pendant ce temps, saler et poivrer le saumon et le saisir dans l''huile dans une poêle antiadhésive à feu moyen-vif, 4 min sur la première face et 2 à 3 min sur la seconde, jusqu''à ce qu''il soit juste cuit. Le retirer et l''effeuiller en gros morceaux.","Ajouter les petits pois aux pâtes pour leurs 2 dernières minutes de cuisson.","Prélever une tasse d''eau de cuisson, puis égoutter les pâtes et les petits pois et les verser dans la poêle du saumon, hors du feu.","Incorporer les épinards, le pesto, le zeste et le jus de citron et 3 à 4 c. à soupe d''eau de cuisson, en mélangeant jusqu''à ce que les épinards tombent et que la sauce soit brillante ; ajouter un peu d''eau si elle est épaisse.","Incorporer délicatement le saumon, poivrer et servir avec le parmesan."]},"it":{"title":"Pasta al pesto con salmone, piselli e spinaci","steps":["Portare a bollore una pentola capiente di acqua salata e cuocere la pasta per il tempo indicato sulla confezione.","Intanto salare il salmone e rosolarlo nell''olio in una padella antiaderente a fuoco medio-alto, 4 min sul primo lato e 2-3 min sul secondo, finché è appena cotto. Toglierlo e spezzarlo in grosse scaglie.","Aggiungere i piselli alla pasta negli ultimi 2 min di cottura.","Prelevare una tazza di acqua di cottura, poi scolare pasta e piselli e versarli nella padella del salmone, fuori dal fuoco.","Unire gli spinaci, il pesto, la scorza e il succo di limone e 3-4 cucchiai di acqua di cottura, mescolando finché gli spinaci appassiscono e il condimento diventa lucido; aggiungere un po'' d''acqua se è denso.","Incorporare delicatamente il salmone, pepare e servire con il parmigiano."]}}'::jsonb),
  ('a5a62f16-c919-45cc-a99b-d43250a82878'::uuid, '{"fr":{"title":"Saumon miel-moutarde au air fryer, pommes de terre nouvelles et poireaux","steps":["Couvrir les pommes de terre d''eau froide salée dans une casserole, porter à ébullition et cuire 15 à 18 min, jusqu''à ce qu''un couteau s''enfonce facilement. Égoutter.","Pendant ce temps, faire fondre le beurre dans une poêle, ajouter les poireaux avec une pincée de sel et 2 c. à soupe d''eau et cuire doucement 10 à 12 min en remuant de temps en temps, jusqu''à ce qu''ils soient fondants.","Mélanger les deux moutardes avec le miel, l''huile, un peu de sel et de poivre.","Préchauffer le air fryer à 200 °C. Badigeonner généreusement le saumon de ce glaçage et le cuire côté peau 8 à 9 min, jusqu''à ce que le dessus soit caramélisé et que le poisson s''effeuille.","Arroser les poireaux de jus de citron, puis ajouter les pommes de terre et les écraser grossièrement à la fourchette.","Servir le saumon sur les pommes de terre et les poireaux, parsemé de persil."]},"it":{"title":"Salmone al miele e senape in friggitrice ad aria con patate novelle e porri","steps":["Coprire le patate con acqua fredda salata in una pentola, portare a bollore e cuocere 15-18 min, finché un coltello entra facilmente. Scolare.","Intanto sciogliere il burro in una padella, aggiungere i porri con un pizzico di sale e 2 cucchiai d''acqua e cuocere dolcemente 10-12 min, mescolando ogni tanto, finché sono morbidi e dolci.","Mescolare le due senapi con il miele, l''olio, un pizzico di sale e pepe.","Scaldare la friggitrice ad aria a 200 °C. Spennellare abbondantemente il salmone con la glassa e cuocerlo con la pelle in basso 8-9 min, finché la superficie è caramellata e il pesce si sfalda.","Spremere il limone sui porri, poi unire le patate e schiacciarle leggermente con una forchetta.","Servire il salmone sulle patate e i porri, cosparso di prezzemolo."]}}'::jsonb),
  ('a4e50e5b-ed5a-49de-84e0-dca7c097cc76'::uuid, '{"fr":{"title":"Saumon et nouilles cacahuète-citron vert aux légumes croquants","steps":["Faire tremper ou cuire les nouilles de riz selon le paquet, puis les égoutter et les rincer à l''eau froide pour qu''elles ne collent pas.","Fouetter le beurre de cacahuète avec la sauce soja, le jus de citron vert, le miel, l''ail, le gingembre, la sriracha et 3 à 4 c. à soupe d''eau tiède pour obtenir une sauce fluide.","Saler le saumon et le saisir dans l''huile dans une poêle antiadhésive à feu moyen-vif, 3 à 4 min par face, jusqu''à ce qu''il soit doré et juste cuit.","Mélanger les nouilles avec la carotte, le concombre et la plus grande partie de la sauce.","Répartir les nouilles dans des bols, effeuiller le saumon par-dessus en gros morceaux et napper du reste de sauce.","Finir avec les cacahuètes et la coriandre."]},"it":{"title":"Salmone con noodles arachidi e lime e verdure croccanti","steps":["Ammollare o lessare i noodles di riso come indicato sulla confezione, poi scolarli e sciacquarli sotto l''acqua fredda perché non si attacchino.","Sbattere il burro di arachidi con salsa di soia, succo di lime, miele, aglio, zenzero, sriracha e 3-4 cucchiai d''acqua tiepida fino a ottenere una salsa fluida.","Salare il salmone e rosolarlo nell''olio in una padella antiaderente a fuoco medio-alto, 3-4 min per lato, finché è dorato e appena cotto.","Condire i noodles con carota, cetriolo e gran parte della salsa.","Dividere i noodles nelle ciotole, spezzare sopra il salmone in grosse scaglie e versare il resto della salsa.","Finire con arachidi e coriandolo."]}}'::jsonb),
  ('299a87a7-23bf-411f-87b5-7eaaa7301c7c'::uuid, '{"fr":{"title":"Pitas au saumon au air fryer et tzatziki","steps":["Mélanger le saumon avec l''huile, l''origan, le paprika, le zeste de citron, du sel et du poivre.","Pour le tzatziki, mélanger le yaourt avec le concombre, l''ail, l''aneth, un filet de citron et une pincée de sel.","Préchauffer le air fryer à 200 °C. Étaler les cubes de saumon en une seule couche dans le panier et cuire 6 à 7 min, jusqu''à ce qu''ils soient légèrement grillés sur les bords et juste cuits.","Pendant ce temps, réchauffer les pitas dans une poêle sèche, 1 min par face.","Rincer l''oignon rouge à l''eau froide et l''arroser d''un filet de citron.","Tartiner les pitas de tzatziki, les garnir de salade, de tomate, d''oignon et de saumon, et ajouter une dernière cuillerée de tzatziki."]},"it":{"title":"Pita con salmone in friggitrice ad aria e tzatziki","steps":["Condire il salmone con olio, origano, paprika, scorza di limone, sale e pepe.","Per lo tzatziki, mescolare lo yogurt con cetriolo, aglio, aneto, un po'' di succo di limone e un pizzico di sale.","Scaldare la friggitrice ad aria a 200 °C. Disporre i cubetti di salmone in un solo strato nel cestello e cuocere 6-7 min, finché sono leggermente abbrustoliti ai bordi e appena cotti.","Intanto scaldare le pita in una padella asciutta, 1 min per lato.","Sciacquare la cipolla rossa sotto l''acqua fredda e condirla con un po'' di limone.","Spalmare le pita di tzatziki, farcirle con lattuga, pomodoro, cipolla e salmone e aggiungere un''ultima cucchiaiata di tzatziki."]}}'::jsonb),
  ('8e9b0f20-5586-444c-8b0a-15a882664811'::uuid, '{"fr":{"title":"Cabillaud sauce romesco, pommes de terre et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min ; ajouter les haricots verts pour les 5 dernières minutes. Égoutter.","Pendant ce temps, mixer les poivrons, les amandes, l''ail, le paprika, le vinaigre, 1 c. à soupe d''huile et une pincée de sel en une sauce romesco épaisse et un peu rustique.","Sécher le cabillaud, le saler, le poivrer et le fariner légèrement.","Chauffer le reste d''huile dans une poêle antiadhésive à feu moyen-vif et saisir le cabillaud 4 min sans le bouger, jusqu''à ce qu''il soit doré dessous ; le retourner et cuire 2 à 3 min de plus, jusqu''à ce qu''il s''effeuille.","Mélanger les pommes de terre et les haricots avec une pincée de sel et l''huile restée dans la poêle.","Étaler une bonne cuillerée de romesco dans chaque assiette, poser le cabillaud dessus et servir avec les pommes de terre, les haricots et le persil."]},"it":{"title":"Merluzzo con salsa romesco, patate e fagiolini","steps":["Mettere le patate in una pentola di acqua fredda salata, portare a bollore e cuocere 15 min; aggiungere i fagiolini negli ultimi 5 min. Scolare.","Intanto frullare peperoni, mandorle, aglio, paprika, aceto, 1 cucchiaio d''olio e un pizzico di sale fino a ottenere una romesco densa e un po'' rustica.","Asciugare il merluzzo, salarlo, peparlo e infarinarlo leggermente.","Scaldare il resto dell''olio in una padella antiaderente a fuoco medio-alto e rosolare il merluzzo 4 min senza muoverlo, finché è dorato sotto; girarlo e cuocere altri 2-3 min, finché si sfalda.","Condire patate e fagiolini con un pizzico di sale e l''olio rimasto in padella.","Stendere una bella cucchiaiata di romesco in ogni piatto, adagiarvi il merluzzo e servire con patate, fagiolini e prezzemolo."]}}'::jsonb),
  ('359db6c0-fa7c-4415-808c-1678f959a128'::uuid, '{"fr":{"title":"Merlu à la harissa au air fryer, semoule et courgettes","steps":["Mélanger la harissa avec 1 c. à café d''huile et le zeste de citron et en badigeonner le merlu.","Préchauffer le air fryer à 200 °C et cuire le merlu 9 à 10 min, jusqu''à ce qu''il soit nacré et s''effeuille facilement.","Pendant ce temps, verser le bouillon chaud sur la semoule dans un saladier, couvrir et laisser gonfler 5 min.","Faire sauter les courgettes dans le reste d''huile dans une poêle à feu vif avec le cumin et une pincée de sel, 5 à 6 min, jusqu''à ce qu''elles soient dorées par endroits mais encore fermes.","Égrener la semoule à la fourchette et y mélanger les courgettes, la moitié du jus de citron, la menthe et le persil.","Assaisonner le yaourt d''un peu de jus de citron et de sel et le servir avec le merlu sur la semoule."]},"it":{"title":"Nasello all''harissa in friggitrice ad aria con cous cous e zucchine","steps":["Mescolare l''harissa con 1 cucchiaino d''olio e la scorza di limone e spalmarla sul nasello.","Scaldare la friggitrice ad aria a 200 °C e cuocere il nasello 9-10 min, finché è opaco e si sfalda facilmente.","Intanto versare il brodo caldo sul cous cous in una ciotola, coprire e lasciare 5 min.","Saltare le zucchine nel resto dell''olio in una padella a fuoco vivo con il cumino e un pizzico di sale, 5-6 min, finché sono dorate qua e là ma ancora sode.","Sgranare il cous cous con una forchetta e unire le zucchine, metà del succo di limone, la menta e il prezzemolo.","Condire lo yogurt con un po'' di succo di limone e sale e servirlo con il nasello sul cous cous."]}}'::jsonb),
  ('a8d2ed16-8c58-4da3-bbbe-2a4bbc59e8cb'::uuid, '{"fr":{"title":"Cabillaud miso-gingembre au air fryer, riz et pak choï","steps":["Mélanger le miso, le mirin, le miel, la sauce soja et les deux tiers du gingembre. En enrober le cabillaud et le laisser 20 à 30 min au réfrigérateur.","Rincer le riz et le cuire à couvert dans 240 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Préchauffer le air fryer à 200 °C. Retirer les gros amas de marinade, poser le cabillaud sur une feuille de papier cuisson dans le panier et cuire 9 à 10 min, jusqu''à ce que le dessus soit caramélisé et que le poisson s''effeuille.","Pendant ce temps, chauffer l''huile dans une poêle, ajouter l''ail et le reste du gingembre, puis le pak choï côté coupé en bas. Cuire 2 min, ajouter 2 c. à soupe d''eau, couvrir et cuire à la vapeur 2 min jusqu''à ce que les tiges soient juste tendres.","Arroser le pak choï d''huile de sésame.","Servir le cabillaud sur le riz avec le pak choï, parsemé de sésame et d''oignon nouveau."]},"it":{"title":"Merluzzo al miso e zenzero in friggitrice ad aria con riso e pak choi","steps":["Mescolare miso, mirin, miele, salsa di soia e due terzi dello zenzero. Ricoprirne il merluzzo e lasciarlo in frigo 20-30 min.","Sciacquare il riso e cuocerlo coperto in 240 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare la friggitrice ad aria a 200 °C. Togliere i grumi spessi di marinata, adagiare il merluzzo su un foglio di carta forno nel cestello e cuocere 9-10 min, finché la superficie è caramellata e il pesce si sfalda.","Intanto scaldare l''olio in una padella, aggiungere l''aglio e il resto dello zenzero, poi il pak choi con il lato tagliato in basso. Cuocere 2 min, aggiungere 2 cucchiai d''acqua, coprire e cuocere a vapore 2 min finché i gambi sono appena teneri.","Condire il pak choi con l''olio di sesamo.","Servire il merluzzo sul riso con il pak choi, cosparso di sesamo e cipollotto."]}}'::jsonb),
  ('75d1230d-4daf-4a3c-89e3-592b242ea24b'::uuid, '{"fr":{"title":"Tacos de cabillaud cajun au air fryer, salade de chou au citron vert","steps":["Mélanger délicatement le cabillaud avec l''huile et l''assaisonnement cajun.","Pour la salade de chou, mélanger la mayonnaise, le yaourt, le zeste de citron vert, la moitié du jus et une pincée de sel, puis y mêler le chou, la carotte et la coriandre.","Préchauffer le air fryer à 200 °C. Disposer le cabillaud en une seule couche dans le panier et cuire 8 à 9 min sans le retourner, jusqu''à ce qu''il s''effeuille.","Réchauffer les tortillas dans une poêle sèche, 30 secondes par face.","Garnir les tortillas de salade de chou et de cabillaud, arroser du reste de citron vert et ajouter le piment."]},"it":{"title":"Tacos di merluzzo cajun in friggitrice ad aria con insalata di cavolo al lime","steps":["Condire delicatamente il merluzzo con l''olio e le spezie cajun.","Per l''insalata di cavolo, mescolare maionese, yogurt, scorza di lime, metà del succo e un pizzico di sale, poi unire cavolo, carota e coriandolo.","Scaldare la friggitrice ad aria a 200 °C. Disporre il merluzzo in un solo strato nel cestello e cuocere 8-9 min senza girarlo, finché si sfalda.","Scaldare le tortillas in una padella asciutta, 30 secondi per lato.","Farcire le tortillas con insalata e merluzzo, spremere sopra il resto del lime e aggiungere il peperoncino."]}}'::jsonb),
  ('8d8e85d0-95ef-45dc-b599-bcb0846aed0a'::uuid, '{"fr":{"title":"Merlu sauce verte, pommes de terre nouvelles et asperges","steps":["Couvrir les pommes de terre d''eau froide salée dans une casserole, porter à ébullition et cuire 15 min ; ajouter les asperges pour les 3 dernières minutes. Égoutter.","Pour la sauce verte, mélanger le persil, la menthe, les câpres, les anchois, la moutarde, le vinaigre et 2 c. à soupe d''huile avec un peu de poivre ; détendre d''une cuillerée d''eau si besoin.","Sécher le merlu et l''assaisonner. Chauffer le reste d''huile dans une poêle antiadhésive à feu moyen-vif et cuire le merlu côté peau 4 min en l''aplatissant les premières secondes, jusqu''à ce que la peau soit croustillante.","Retourner le poisson et cuire 1 à 2 min de plus, jusqu''à ce qu''il s''effeuille tout juste ; arroser de jus de citron.","Mélanger les pommes de terre et les asperges avec une cuillerée de sauce verte.","Servir le merlu sur les pommes de terre et les asperges, nappé du reste de sauce verte."]},"it":{"title":"Nasello con salsa verde, patate novelle e asparagi","steps":["Coprire le patate con acqua fredda salata in una pentola, portare a bollore e cuocere 15 min; aggiungere gli asparagi negli ultimi 3 min. Scolare.","Per la salsa verde, mescolare prezzemolo, menta, capperi, acciughe, senape, aceto e 2 cucchiai d''olio con un po'' di pepe; allungare con un cucchiaio d''acqua se serve.","Asciugare il nasello e condirlo. Scaldare il resto dell''olio in una padella antiaderente a fuoco medio-alto e cuocere il nasello dal lato della pelle per 4 min, premendolo i primi secondi, finché la pelle è croccante.","Girare il pesce e cuocere ancora 1-2 min, finché si sfalda appena; spremere sopra il limone.","Condire patate e asparagi con una cucchiaiata di salsa verde.","Servire il nasello su patate e asparagi con il resto della salsa verde sopra."]}}'::jsonb),
  ('c3065a27-e6d3-4d46-8179-c8d9990ea1b8'::uuid, '{"fr":{"title":"Crevettes miel-gochujang au air fryer, riz et concombre","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau 12 min à feu doux ; poser les edamames dessus pour les 4 dernières minutes, puis laisser reposer 5 min hors du feu.","Mélanger le concombre avec le vinaigre de riz, le sucre et une pincée de sel et le laisser mariner légèrement.","Mélanger le gochujang, le miel, la sauce soja, l''ail et l''huile de sésame dans une petite casserole.","Préchauffer le air fryer à 200 °C. Sécher les crevettes, les mélanger avec l''huile et une pincée de sel et les cuire 6 à 7 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient roses et recourbées.","Chauffer la sauce 1 min jusqu''à ce qu''elle bouillonne, puis y enrober les crevettes chaudes.","Servir les crevettes sur le riz et les edamames avec le concombre, parsemées de sésame et d''oignon nouveau."]},"it":{"title":"Gamberi al miele e gochujang in friggitrice ad aria con riso e cetriolo","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua per 12 min a fuoco basso; aggiungere sopra gli edamame negli ultimi 4 min, poi lasciar riposare 5 min fuori dal fuoco.","Condire il cetriolo con aceto di riso, zucchero e un pizzico di sale e lasciarlo marinare leggermente.","Mescolare gochujang, miele, salsa di soia, aglio e olio di sesamo in un pentolino.","Scaldare la friggitrice ad aria a 200 °C. Asciugare i gamberi, condirli con l''olio e un pizzico di sale e cuocerli 6-7 min, scuotendo a metà, finché sono rosa e arricciati.","Scaldare la salsa 1 min finché bolle, poi saltarvi i gamberi caldi.","Servire i gamberi sul riso con edamame e cetriolo, cosparsi di sesamo e cipollotto."]}}'::jsonb),
  ('a41c4225-ba5e-410f-83b8-44767b52d719'::uuid, '{"fr":{"title":"Nouilles sautées aux crevettes et au poivre noir, pois gourmands","steps":["Cuire les nouilles dans l''eau bouillante selon le paquet, les égoutter et les rincer rapidement pour qu''elles ne collent pas.","Mélanger la sauce d''huître, la sauce soja, le sucre, le poivre noir et la fécule avec 4 c. à soupe d''eau.","Chauffer l''huile dans un wok à feu vif et faire sauter les crevettes 2 min, jusqu''à ce qu''elles soient roses des deux côtés ; les retirer.","Ajouter le beurre, l''ail, le gingembre et le blanc des oignons nouveaux et remuer 30 secondes jusqu''à ce que ça embaume.","Ajouter les pois gourmands et le poivron et faire sauter 2 min, jusqu''à ce qu''ils soient bien verts mais encore croquants.","Remettre les crevettes avec les nouilles et la sauce et mélanger 1 à 2 min, jusqu''à ce que tout soit brillant et les crevettes cuites.","Ajouter le vert des oignons nouveaux et servir aussitôt."]},"it":{"title":"Noodles saltati con gamberi al pepe nero e taccole","steps":["Cuocere i noodles in acqua bollente come indicato sulla confezione, scolarli e sciacquarli brevemente perché non si attacchino.","Mescolare salsa d''ostriche, salsa di soia, zucchero, pepe nero e amido con 4 cucchiai d''acqua.","Scaldare l''olio in un wok a fuoco vivo e saltare i gamberi 2 min, finché sono rosa su entrambi i lati; toglierli.","Aggiungere il burro, l''aglio, lo zenzero e la parte bianca dei cipollotti e mescolare 30 secondi finché profumano.","Aggiungere taccole e peperone e saltare 2 min, finché sono brillanti ma ancora croccanti.","Rimettere i gamberi con i noodles e la salsa e saltare 1-2 min, finché tutto è lucido e i gamberi sono cotti.","Unire la parte verde dei cipollotti e servire subito."]}}'::jsonb),
  ('e734e3d4-55e6-4745-a4e1-23a64efe8e9e'::uuid, '{"fr":{"title":"Nouilles sautées aux crevettes sauce satay et pak choï","steps":["Faire tremper ou cuire les nouilles de riz selon le paquet, puis les égoutter.","Fouetter le beurre de cacahuète, le lait de coco, la sauce soja, le jus de citron vert, le miel et le curry en une sauce lisse.","Chauffer l''huile dans un wok à feu vif, ajouter l''ail, le gingembre, la carotte et les tiges de pak choï et faire sauter 2 min.","Ajouter les crevettes et faire sauter 2 à 3 min, jusqu''à ce qu''elles deviennent roses.","Verser la sauce et les feuilles de pak choï et laisser bouillonner 1 min, jusqu''à ce que les feuilles tombent ; détendre d''un peu d''eau si c''est épais.","Ajouter les nouilles et mélanger jusqu''à ce qu''elles soient enrobées et chaudes, puis servir avec le piment et la coriandre."]},"it":{"title":"Noodles con gamberi in salsa satay e pak choi","steps":["Ammollare o lessare i noodles di riso come indicato sulla confezione, poi scolarli.","Sbattere burro di arachidi, latte di cocco, salsa di soia, succo di lime, miele e curry fino a ottenere una salsa liscia.","Scaldare l''olio in un wok a fuoco vivo, aggiungere aglio, zenzero, carota e gambi di pak choi e saltare 2 min.","Aggiungere i gamberi e saltare 2-3 min, finché diventano rosa.","Versare la salsa e le foglie di pak choi e far bollire 1 min, finché le foglie appassiscono; allungare con un goccio d''acqua se è densa.","Unire i noodles e mescolare finché sono ben conditi e caldi, poi servire con peperoncino e coriandolo."]}}'::jsonb),
  ('b5b1cd3f-52f7-47b0-8e3c-b0f1cf3c75cb'::uuid, '{"fr":{"title":"Wraps de crevettes tikka au air fryer, yaourt à la menthe","steps":["Mélanger 3 c. à soupe de yaourt avec le garam masala, le paprika, le cumin, le curcuma, le piment en poudre, l''ail, le gingembre, la moitié du jus de citron, l''huile et une pincée de sel. Y enrober les crevettes et laisser 15 à 20 min.","Incorporer la menthe, le concombre, un filet de citron et une pincée de sel au reste du yaourt.","Mélanger l''oignon rouge avec le reste du jus de citron.","Préchauffer le air fryer à 200 °C. Étaler les crevettes en une seule couche dans le panier et les cuire 6 à 7 min en les retournant une fois, jusqu''à ce qu''elles soient roses et grillées par endroits.","Réchauffer les wraps dans une poêle sèche, 30 secondes par face.","Garnir chaque wrap de salade, de crevettes, d''oignon et d''une bonne cuillerée de yaourt à la menthe, puis rouler."]},"it":{"title":"Wrap di gamberi tikka in friggitrice ad aria con yogurt alla menta","steps":["Mescolare 3 cucchiai di yogurt con garam masala, paprika, cumino, curcuma, peperoncino in polvere, aglio, zenzero, metà del succo di limone, l''olio e un pizzico di sale. Ricoprirne i gamberi e lasciarli 15-20 min.","Unire menta, cetriolo, un po'' di limone e un pizzico di sale al resto dello yogurt.","Condire la cipolla rossa con il resto del succo di limone.","Scaldare la friggitrice ad aria a 200 °C. Disporre i gamberi in un solo strato nel cestello e cuocerli 6-7 min, girandoli una volta, finché sono rosa e abbrustoliti qua e là.","Scaldare i wrap in una padella asciutta, 30 secondi per lato.","Farcire ogni wrap con lattuga, gamberi, cipolla e una bella cucchiaiata di yogurt alla menta, poi arrotolare."]}}'::jsonb),
  ('864233ec-efae-4266-b3c1-855a9a78f606'::uuid, '{"fr":{"title":"Bols de quinoa aux crevettes chimichurri au air fryer","steps":["Cuire le quinoa à couvert dans 280 ml d''eau salée 12 à 15 min, jusqu''à absorption ; le laisser reposer 5 min puis l''égrener.","Pour le chimichurri, mélanger le persil, l''ail, l''origan, le piment, le vinaigre, 2 c. à soupe d''huile et une bonne pincée de sel.","Mélanger les crevettes avec 1 c. à soupe de chimichurri. Préchauffer le air fryer à 200 °C et les cuire 6 à 7 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient roses et recourbées.","Pendant ce temps, faire sauter le poivron et le maïs dans le reste d''huile dans une poêle à feu vif, 4 à 5 min, jusqu''à ce qu''ils soient grillés par endroits.","Mélanger le poivron, le maïs, les tomates et le jus de citron vert au quinoa.","Répartir dans des bols, garnir de crevettes et napper du reste de chimichurri."]},"it":{"title":"Ciotole di quinoa con gamberi al chimichurri in friggitrice ad aria","steps":["Cuocere la quinoa coperta in 280 ml d''acqua salata per 12-15 min, finché l''acqua è assorbita; lasciarla riposare 5 min, poi sgranarla.","Per il chimichurri, mescolare prezzemolo, aglio, origano, peperoncino, aceto, 2 cucchiai d''olio e un buon pizzico di sale.","Condire i gamberi con 1 cucchiaio di chimichurri. Scaldare la friggitrice ad aria a 200 °C e cuocerli 6-7 min, scuotendo a metà, finché sono rosa e arricciati.","Intanto saltare peperone e mais nel resto dell''olio in una padella a fuoco vivo, 4-5 min, finché sono abbrustoliti qua e là.","Unire alla quinoa peperone, mais, pomodorini e succo di lime.","Dividere nelle ciotole, completare con i gamberi e versare sopra il resto del chimichurri."]}}'::jsonb),
  ('ee123b44-5c1b-473b-ac0c-bd5f9c59c493'::uuid, '{"fr":{"title":"Tofu sauce chili douce au air fryer, nouilles et poivrons","steps":["Sécher le tofu, le mélanger avec 1 c. à café d''huile et une pincée de sel, puis avec la fécule jusqu''à ce qu''il soit enrobé.","Préchauffer le air fryer à 200 °C et cuire le tofu 15 min en secouant deux fois, jusqu''à ce qu''il soit doré et croustillant.","Pendant ce temps, cuire les nouilles selon le paquet, les égoutter et les rincer rapidement.","Mélanger la sauce chili douce, la sauce soja, le jus de citron vert et l''ail.","Chauffer le reste d''huile dans un wok à feu vif et faire sauter les poivrons et le blanc des oignons nouveaux 3 min, jusqu''à ce qu''ils soient juste tendres.","Ajouter les nouilles et la moitié de la sauce et mélanger 1 min ; enrober le tofu chaud du reste de sauce.","Servir les nouilles garnies de tofu, de vert d''oignon nouveau, de sésame et de coriandre."]},"it":{"title":"Tofu alla salsa chili dolce in friggitrice ad aria con noodles e peperoni","steps":["Asciugare il tofu, condirlo con 1 cucchiaino d''olio e un pizzico di sale, poi con l''amido finché è ricoperto.","Scaldare la friggitrice ad aria a 200 °C e cuocere il tofu 15 min, scuotendo due volte, finché è dorato e croccante.","Intanto cuocere i noodles come indicato sulla confezione, scolarli e sciacquarli brevemente.","Mescolare salsa chili dolce, salsa di soia, succo di lime e aglio.","Scaldare il resto dell''olio in un wok a fuoco vivo e saltare i peperoni e la parte bianca dei cipollotti 3 min, finché sono appena teneri.","Aggiungere i noodles e metà della salsa e saltare 1 min; condire il tofu caldo con il resto della salsa.","Servire i noodles con sopra il tofu, la parte verde dei cipollotti, sesamo e coriandolo."]}}'::jsonb),
  ('b9133b27-97e0-4c11-9752-f03233863717'::uuid, '{"fr":{"title":"Tofu katsu au air fryer, sauce curry japonaise et riz","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Pour la sauce curry, faire fondre l''oignon et la carotte dans 1 c. à café d''huile dans une casserole à feu moyen, 6 à 7 min. Ajouter l''ail, 1 c. à soupe de farine et le curry et remuer 1 min.","Incorporer le bouillon petit à petit en fouettant, puis la sauce soja et le sirop d''érable, et laisser mijoter 10 à 12 min en remuant souvent, jusqu''à ce que la sauce nappe la cuillère. Mixer si on la veut lisse.","Pendant ce temps, fouetter le reste de farine avec environ 60 ml d''eau et une pincée de sel en une pâte épaisse. Y tremper chaque tranche de tofu, puis la presser dans le panko des deux côtés.","Préchauffer le air fryer à 200 °C. Badigeonner ou vaporiser le tofu du reste d''huile et le cuire 12 à 14 min en le retournant une fois, jusqu''à ce qu''il soit bien doré et croustillant.","Trancher le katsu et le servir sur le riz avec le chou émincé, la sauce curry versée à côté."]},"it":{"title":"Tofu katsu in friggitrice ad aria con curry giapponese e riso","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Per la salsa al curry, appassire cipolla e carota in 1 cucchiaino d''olio in una casseruola a fuoco medio, 6-7 min. Aggiungere aglio, 1 cucchiaio di farina e curry e mescolare 1 min.","Incorporare il brodo poco alla volta con la frusta, poi salsa di soia e sciroppo d''acero, e cuocere a fuoco lento 10-12 min mescolando spesso, finché vela il cucchiaio. Frullare se la si vuole liscia.","Intanto sbattere il resto della farina con circa 60 ml d''acqua e un pizzico di sale fino a ottenere una pastella densa. Immergervi ogni fetta di tofu, poi premerla nel panko su entrambi i lati.","Scaldare la friggitrice ad aria a 200 °C. Spennellare o spruzzare il tofu con il resto dell''olio e cuocerlo 12-14 min, girandolo una volta, finché è ben dorato e croccante.","Affettare il katsu e servirlo sul riso con il cavolo a julienne e la salsa al curry accanto."]}}'::jsonb),
  ('097a3158-2f72-4ef2-9407-d7bc62b5421b'::uuid, '{"fr":{"title":"Tofu au poivre noir, riz et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Enrober le tofu de fécule. Chauffer l''huile dans une grande poêle antiadhésive à feu moyen-vif et faire dorer le tofu 8 à 10 min en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces. Le poser sur du papier absorbant.","Ne garder qu''un film d''huile, ajouter le beurre, les échalotes, le piment, l''ail et le gingembre et cuire à feu moyen 6 à 8 min en remuant, jusqu''à ce qu''ils soient fondants et brillants.","Ajouter les haricots verts et 3 c. à soupe d''eau, couvrir et cuire 3 à 4 min jusqu''à ce qu''ils soient juste tendres.","Incorporer le poivre noir, la sauce soja et le sucre, puis remettre le tofu et mélanger 1 min pour l''enrober et le réchauffer.","Ajouter les oignons nouveaux et servir avec le riz."]},"it":{"title":"Tofu al pepe nero con riso e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Passare il tofu nell''amido. Scaldare l''olio in una grande padella antiaderente a fuoco medio-alto e rosolare il tofu 8-10 min, girandolo, finché è croccante e dorato su tutti i lati. Metterlo su carta assorbente.","Eliminare l''olio lasciandone solo un velo, aggiungere burro, scalogni, peperoncino, aglio e zenzero e cuocere a fuoco medio 6-8 min mescolando, finché sono morbidi e lucidi.","Aggiungere i fagiolini e 3 cucchiai d''acqua, coprire e cuocere 3-4 min finché sono appena teneri.","Unire pepe nero, salsa di soia e zucchero, poi rimettere il tofu e saltare 1 min per condirlo e scaldarlo.","Aggiungere i cipollotti e servire con il riso."]}}'::jsonb),
  ('ee18cbd5-03f1-4c48-b68e-1c26e8c8e29e'::uuid, '{"fr":{"title":"Tofu à la harissa au air fryer, boulgour et carottes","steps":["Porter le bouillon à ébullition dans une casserole, ajouter le boulgour, couvrir et cuire à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Mélanger le tofu avec 1 c. à café d''huile, une pincée de sel et la fécule. Préchauffer le air fryer à 200 °C et le cuire 12 min en secouant à mi-cuisson.","Pendant ce temps, faire revenir les carottes dans 1 c. à soupe d''huile dans une poêle à feu moyen-vif avec le cumin et une pincée de sel, 10 à 12 min en remuant, jusqu''à ce qu''elles soient tendres et dorées sur les bords.","Mélanger la harissa avec le sirop d''érable, y enrober le tofu et cuire encore 2 à 3 min, jusqu''à ce qu''il soit laqué et grillé sur les bords.","Égrener le boulgour et y mélanger les carottes, le jus de citron, le reste d''huile, le persil et la menthe.","Servir le tofu à la harissa sur le boulgour."]},"it":{"title":"Tofu all''harissa in friggitrice ad aria con bulgur e carote","steps":["Portare a bollore il brodo in una casseruola, versare il bulgur, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare 5 min fuori dal fuoco.","Condire il tofu con 1 cucchiaino d''olio, un pizzico di sale e l''amido. Scaldare la friggitrice ad aria a 200 °C e cuocerlo 12 min, scuotendo a metà.","Intanto rosolare le carote in 1 cucchiaio d''olio in una padella a fuoco medio-alto con il cumino e un pizzico di sale, 10-12 min mescolando, finché sono tenere e dorate ai bordi.","Mescolare l''harissa con lo sciroppo d''acero, condirvi il tofu e cuocerlo altri 2-3 min, finché è laccato e abbrustolito ai bordi.","Sgranare il bulgur e unire carote, succo di limone, il resto dell''olio, prezzemolo e menta.","Servire il tofu all''harissa sul bulgur."]}}'::jsonb),
  ('5eed3550-e582-4410-9023-f70fde4cac4f'::uuid, '{"fr":{"title":"Tofu sauce tahini-citron, courge rôtie et quinoa","steps":["Préchauffer le four à 220 °C. Mélanger la courge avec 2 c. à café d''huile, la moitié du cumin et du paprika et une pincée de sel, l''étaler sur une grande plaque et rôtir 10 min.","Mélanger le tofu avec le reste d''huile et d''épices et une pincée de sel, l''ajouter sur la plaque et rôtir encore 15 à 18 min en retournant une fois, jusqu''à ce que la courge soit tendre et dorée et le tofu bien doré.","Pendant ce temps, cuire le quinoa à couvert dans 280 ml d''eau salée 12 à 15 min, jusqu''à absorption ; le laisser reposer 5 min.","Fouetter le tahini avec le jus de citron, l''ail, le sirop d''érable, une pincée de sel et 2 à 3 c. à soupe d''eau en une sauce fluide.","Incorporer les épinards au quinoa chaud pour qu''ils tombent, puis le persil.","Servir le quinoa garni de courge et de tofu, arrosé de sauce tahini-citron."]},"it":{"title":"Tofu con salsa tahina e limone, zucca arrosto e quinoa","steps":["Scaldare il forno a 220 °C. Condire la zucca con 2 cucchiaini d''olio, metà del cumino e della paprika e un pizzico di sale, stenderla su una grande teglia e arrostire 10 min.","Condire il tofu con il resto dell''olio e delle spezie e un pizzico di sale, aggiungerlo alla teglia e arrostire altri 15-18 min, girando una volta, finché la zucca è morbida e dorata e il tofu ben dorato.","Intanto cuocere la quinoa coperta in 280 ml d''acqua salata per 12-15 min, finché l''acqua è assorbita; lasciarla riposare 5 min.","Sbattere la tahina con succo di limone, aglio, sciroppo d''acero, un pizzico di sale e 2-3 cucchiai d''acqua fino a ottenere una salsa fluida.","Unire gli spinaci alla quinoa calda perché appassiscano, poi il prezzemolo.","Servire la quinoa con sopra zucca e tofu e la salsa tahina e limone."]}}'::jsonb),
  ('cdbeba47-7c9a-4b38-b153-1ef98c28b768'::uuid, '{"fr":{"title":"Halloumi au air fryer, semoule aux pois chiches et sauce tahini-citron","steps":["Préchauffer le air fryer à 200 °C. Mélanger les pois chiches et le poivron avec 2 c. à café d''huile, le cumin, le paprika et une pincée de sel et cuire 8 min en secouant à mi-cuisson.","Poser les tranches d''halloumi dessus et cuire encore 6 à 7 min, jusqu''à ce que l''halloumi soit doré sur les bords et les pois chiches croustillants.","Pendant ce temps, porter le bouillon à ébullition dans une casserole, ajouter la semoule et le zeste de citron, couvrir hors du feu et laisser gonfler 5 min.","Fouetter le tahini avec la moitié du jus de citron, l''ail, une pincée de sel et 2 à 3 c. à soupe d''eau en une sauce fluide.","Égrener la semoule à la fourchette et y mélanger le concombre, les herbes, le reste du jus de citron et d''huile, puis les pois chiches et le poivron.","Servir la semoule garnie d''halloumi et arrosée de sauce tahini-citron."]},"it":{"title":"Halloumi in friggitrice ad aria con cous cous ai ceci e salsa tahina e limone","steps":["Scaldare la friggitrice ad aria a 200 °C. Condire ceci e peperone con 2 cucchiaini d''olio, cumino, paprika e un pizzico di sale e cuocere 8 min, scuotendo a metà.","Adagiare sopra le fette di halloumi e cuocere altri 6-7 min, finché l''halloumi è dorato ai bordi e i ceci croccanti.","Intanto portare a bollore il brodo in una casseruola, versare il cous cous e la scorza di limone, coprire fuori dal fuoco e lasciare 5 min.","Sbattere la tahina con metà del succo di limone, l''aglio, un pizzico di sale e 2-3 cucchiai d''acqua fino a ottenere una salsa fluida.","Sgranare il cous cous con una forchetta e unire cetriolo, erbe, il resto del succo di limone e dell''olio, poi ceci e peperone.","Servire il cous cous con sopra l''halloumi e la salsa tahina e limone."]}}'::jsonb),
  ('22ac2fdb-6c42-4e22-8be1-8969ffeeae90'::uuid, '{"fr":{"title":"Kathi rolls au paneer au air fryer","steps":["Mélanger 3 c. à soupe de yaourt avec le garam masala, le paprika, le curcuma, le piment en poudre, l''ail, le gingembre, l''huile, un filet de citron et une pincée de sel. Y enrober le paneer et laisser 15 à 20 min.","Mixer ou hacher très finement la coriandre, la menthe et le piment vert et les incorporer au reste du yaourt avec un filet de citron et une pincée de sel.","Couper la moitié de l''oignon en quartiers et émincer finement l''autre moitié ; mélanger les lamelles avec un peu de jus de citron et de sel.","Préchauffer le air fryer à 200 °C. Mettre le paneer, le poivron et les quartiers d''oignon en une seule couche et cuire 10 à 12 min en secouant à mi-cuisson, jusqu''à ce que le paneer soit grillé sur les bords.","Réchauffer les wraps dans une poêle sèche, 30 secondes par face.","Tartiner chaque wrap de yaourt au chutney vert, ajouter le paneer, les légumes et l''oignon émincé, rouler bien serré et servir."]},"it":{"title":"Kathi roll al paneer in friggitrice ad aria","steps":["Mescolare 3 cucchiai di yogurt con garam masala, paprika, curcuma, peperoncino in polvere, aglio, zenzero, l''olio, un po'' di limone e un pizzico di sale. Condirvi il paneer e lasciarlo 15-20 min.","Frullare o tritare finissimi coriandolo, menta e peperoncino verde e unirli al resto dello yogurt con un po'' di limone e un pizzico di sale.","Tagliare metà cipolla a spicchi e affettare sottile l''altra metà; condire le fettine con un po'' di succo di limone e sale.","Scaldare la friggitrice ad aria a 200 °C. Disporre paneer, peperone e spicchi di cipolla in un solo strato e cuocere 10-12 min, scuotendo a metà, finché il paneer è abbrustolito ai bordi.","Scaldare i wrap in una padella asciutta, 30 secondi per lato.","Spalmare ogni wrap con lo yogurt al chutney verde, aggiungere paneer, verdure e cipolla affettata, arrotolare stretto e servire."]}}'::jsonb),
  ('27449cd5-b106-4b6d-88e8-622045c10586'::uuid, '{"fr":{"title":"Riz sauté aux œufs, edamames et gochujang","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau 12 min, puis l''étaler sur une grande assiette pour qu''il sèche et refroidisse 5 à 10 min.","Mélanger le gochujang, le miel, la sauce soja et l''huile de sésame.","Chauffer 1 c. à café d''huile dans un wok ou une grande poêle à feu moyen, verser 4 œufs battus avec une pincée de sel et les brouiller en gros grumeaux moelleux, environ 1 min. Les réserver.","Ajouter le reste d''huile et monter le feu. Faire sauter la carotte, les edamames, l''ail et le blanc des oignons nouveaux 2 à 3 min.","Ajouter le riz et faire sauter 3 à 4 min en l''écrasant contre la poêle, jusqu''à ce qu''il soit chaud et légèrement grillé. Incorporer la sauce jusqu''à ce que chaque grain soit enrobé, puis remettre les œufs brouillés.","Pendant ce temps, cuire les 2 œufs restants au plat dans un peu d''huile dans une poêle, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Servir le riz sauté surmonté d''un œuf au plat, du vert des oignons nouveaux et de sésame."]},"it":{"title":"Riso saltato con uova, edamame e gochujang","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua per 12 min, poi stenderlo su un grande piatto perché asciughi e si raffreddi 5-10 min.","Mescolare gochujang, miele, salsa di soia e olio di sesamo.","Scaldare 1 cucchiaino d''olio in un wok o in una grande padella a fuoco medio, versare 4 uova sbattute con un pizzico di sale e strapazzarle in grossi fiocchi morbidi, circa 1 min. Toglierle.","Aggiungere il resto dell''olio e alzare il fuoco. Saltare carota, edamame, aglio e parte bianca dei cipollotti 2-3 min.","Aggiungere il riso e saltare 3-4 min, premendolo contro la padella, finché è caldo e leggermente tostato. Unire la salsa finché ogni chicco è condito, poi rimettere le uova strapazzate.","Intanto friggere le 2 uova rimaste in poco olio in una padella, finché gli albumi sono rappresi e i tuorli ancora morbidi.","Servire il riso saltato con sopra un uovo all''occhio di bue, la parte verde dei cipollotti e il sesamo."]}}'::jsonb),
  ('8c6694d6-a78f-4a4e-b68a-0aa18ebd4294'::uuid, '{"fr":{"title":"Burritos aux haricots noirs et aux œufs, salsa de tomates","steps":["Pour la salsa, mélanger les tomates, l''oignon rouge, la moitié de la coriandre, le piment, la moitié du jus de citron vert et une pincée de sel.","Réchauffer les tortillas une à une dans une poêle sèche, 30 secondes par face, et les garder enveloppées dans un torchon propre.","Chauffer 1 c. à café d''huile dans la même poêle à feu moyen et faire fondre l''oignon 4 min. Ajouter l''ail, le cumin et le paprika 30 secondes, puis les haricots et 3 c. à soupe d''eau.","Cuire les haricots 3 min en en écrasant environ la moitié à la fourchette, jusqu''à ce qu''ils épaississent ; saler, ajouter le reste du jus de citron vert et les répartir sur les tortillas.","Essuyer la poêle, ajouter le reste d''huile et brouiller les œufs battus avec sel et poivre à feu doux, 2 min, jusqu''à ce qu''ils soient juste pris et moelleux.","Garnir les haricots d''œufs, de cheddar, de salsa et du reste de coriandre, rabattre les côtés et rouler bien serré."]},"it":{"title":"Burritos con fagioli neri e uova e salsa di pomodoro","steps":["Per la salsa, mescolare pomodori, cipolla rossa, metà del coriandolo, il peperoncino, metà del succo di lime e un pizzico di sale.","Scaldare le tortillas una alla volta in una padella asciutta, 30 secondi per lato, e tenerle avvolte in un canovaccio pulito.","Scaldare 1 cucchiaino d''olio nella stessa padella a fuoco medio e appassire la cipolla 4 min. Aggiungere aglio, cumino e paprika per 30 secondi, poi i fagioli e 3 cucchiai d''acqua.","Cuocere i fagioli 3 min schiacciandone circa metà con una forchetta, finché si addensano; salare, unire il resto del succo di lime e distribuirli sulle tortillas.","Pulire la padella, aggiungere il resto dell''olio e strapazzare le uova sbattute con sale e pepe a fuoco basso, 2 min, finché sono appena rapprese e morbide.","Completare i fagioli con uova, cheddar, salsa e il resto del coriandolo, ripiegare i lati e arrotolare stretto."]}}'::jsonb),
  ('6ccd0cfe-4e21-4d8d-9693-dff751a4886b'::uuid, '{"fr":{"title":"Lentilles du Puy sauce verte, œufs mollets et pommes de terre nouvelles","steps":["Couvrir les lentilles d''une grande quantité d''eau froide dans une casserole, ajouter le laurier et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres mais encore entières. Ne les saler qu''à la fin, puis égoutter.","Pendant ce temps, mettre les pommes de terre dans une seconde casserole d''eau froide salée, porter à ébullition et cuire 15 à 18 min, jusqu''à ce qu''elles soient tendres.","Plonger les œufs dans l''eau des pommes de terre pour les 6 min 30 dernières, puis les passer dans l''eau froide, les écaler et les couper en deux.","Pour la sauce verte, mélanger le persil, le basilic, les câpres, l''ail, la moutarde, 1 c. à soupe de vinaigre et 2 c. à soupe d''huile avec une pincée de sel et de poivre.","Mélanger les lentilles tièdes avec l''échalote, le reste du vinaigre et de l''huile et la moitié de la sauce verte. Égoutter les pommes de terre.","Servir les lentilles avec les pommes de terre et la roquette, garnies des œufs mollets et du reste de sauce verte."]},"it":{"title":"Lenticchie verdi con salsa verde, uova morbide e patate novelle","steps":["Coprire le lenticchie con abbondante acqua fredda in una pentola, aggiungere l''alloro e cuocere a fuoco lento 20-25 min, finché sono tenere ma ancora intere. Salarle solo alla fine, poi scolarle.","Intanto mettere le patate in una seconda pentola di acqua fredda salata, portare a bollore e cuocere 15-18 min, finché sono tenere.","Calare le uova nell''acqua delle patate negli ultimi 6 min e mezzo, poi passarle in acqua fredda, sgusciarle e tagliarle a metà.","Per la salsa verde, mescolare prezzemolo, basilico, capperi, aglio, senape, 1 cucchiaio di aceto e 2 cucchiai d''olio con un pizzico di sale e pepe.","Condire le lenticchie tiepide con lo scalogno, il resto dell''aceto e dell''olio e metà della salsa verde. Scolare le patate.","Servire le lenticchie con le patate e la rucola, con sopra le uova morbide e il resto della salsa verde."]}}'::jsonb),
  ('63e8ac66-626b-56dc-ad74-a1f52919bee4'::uuid, '{"fr":{"title":"Bols de riz au poulet yakitori à l''air fryer et haricots verts","steps":["Rincer le riz, le mettre dans une casserole avec 210 ml d''eau, porter à ébullition, couvrir et cuire 12 min à feu doux, puis laisser reposer hors du feu à couvert.","Cuire les haricots verts 4 min dans une petite casserole d''eau salée bouillante, égoutter et réserver au chaud.","Dans la même petite casserole, faire frémir la sauce soja, le mirin, le saké et le sucre 3 à 4 min jusqu''à consistance sirupeuse : c''est la sauce tare.","Enfiler le poulet et l''oignon nouveau en alternance sur de petites brochettes adaptées au panier et les badigeonner d''huile.","Cuire à l''air fryer à 190 °C pendant 6 min, badigeonner de tare, retourner, badigeonner à nouveau et cuire encore 5 à 6 min, jusqu''à ce que ce soit laqué et à 75 °C à cœur.","Répartir le riz dans des bols, ajouter les haricots et les brochettes, arroser du reste de tare et finir avec les graines de sésame et le piment."]},"it":{"title":"Ciotole di riso con pollo yakitori in friggitrice ad aria e fagiolini","steps":["Sciacquare il riso, metterlo in una pentola con 210 ml d''acqua, portare a bollore, coprire e cuocere 12 min a fuoco basso, poi lasciarlo riposare coperto fuori dal fuoco.","Lessare i fagiolini 4 min in un pentolino d''acqua salata, scolarli e tenerli al caldo.","Nello stesso pentolino far sobbollire salsa di soia, mirin, sake e zucchero per 3–4 min finché diventa sciropposa: è la salsa tare.","Infilare pollo e cipollotto alternati su spiedini corti adatti al cestello e spennellarli con l''olio.","Cuocere in friggitrice ad aria a 190 °C per 6 min, spennellare con la tare, girare, spennellare di nuovo e cuocere altri 5–6 min, finché sono lucidi e a 75 °C al cuore.","Distribuire il riso nelle ciotole, aggiungere fagiolini e spiedini, irrorare con il resto della tare e finire con sesamo e peperoncino."]}}'::jsonb),
  ('be8267a1-d52e-53ab-85e6-83aef1458b18'::uuid, '{"fr":{"title":"Nouilles au poulet et brocoli, sauce huître","steps":["Mélanger le poulet avec la sauce soja et 1 c. à café de fécule. Fouetter la sauce huître, le vin de Shaoxing, le sucre, le bouillon et le reste de fécule dans un bol.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet en ajoutant le brocoli et la carotte les 2 dernières minutes ; égoutter.","Chauffer l''huile dans un wok à feu vif et faire sauter le poulet 3 à 4 min jusqu''à ce qu''il soit doré et cuit.","Ajouter l''ail et le gingembre et faire sauter 30 secondes jusqu''à ce qu''ils embaument.","Verser la sauce et laisser bouillonner 1 min jusqu''à ce qu''elle épaississe et devienne brillante.","Ajouter les nouilles et les légumes et mélanger 1 à 2 min jusqu''à ce qu''ils soient enrobés et chauds, puis ajouter l''huile de sésame et l''oignon nouveau et servir."]},"it":{"title":"Noodles con pollo e broccoli in salsa d''ostrica","steps":["Mescolare il pollo con la salsa di soia e 1 cucchiaino di amido. In una caraffa sbattere salsa d''ostrica, vino Shaoxing, zucchero, brodo e il resto dell''amido.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione, aggiungendo broccoli e carota negli ultimi 2 min; scolare.","Scaldare l''olio in un wok a fuoco vivo e saltare il pollo per 3–4 min finché è dorato e cotto.","Unire aglio e zenzero e saltare 30 secondi finché profumano.","Versare la salsa e farla bollire 1 min finché si addensa e diventa lucida.","Unire noodles e verdure e saltare 1–2 min finché sono ben conditi e caldi, poi aggiungere olio di sesamo e cipollotto e servire."]}}'::jsonb),
  ('43a904db-41c6-56c6-9efe-ee6b7ae30125'::uuid, '{"fr":{"title":"Poulet à la chermoula à l''air fryer, semoule à la tomate et au concombre","steps":["Préparer la chermoula : mélanger le persil, la coriandre, l''ail, le cumin, le paprika, le piment, le zeste de citron, la moitié du jus, 1 c. à soupe d''huile d''olive et une pincée de sel.","Couper les filets de poulet en deux dans l''épaisseur et les frotter avec les deux tiers de la chermoula.","Cuire à l''air fryer à 200 °C pendant 12 à 15 min en retournant à mi-cuisson, jusqu''à ce que les bords soient grillés et à 75 °C au plus épais.","Pendant ce temps, verser le bouillon chaud sur la semoule dans une casserole hors du feu, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette et incorporer la tomate, le concombre, l''oignon rouge, le reste du jus de citron et de l''huile.","Mélanger le reste de chermoula avec le yaourt.","Trancher le poulet et le servir sur la semoule avec le yaourt à la chermoula."]},"it":{"title":"Pollo alla chermoula in friggitrice ad aria con cous cous di pomodoro e cetriolo","steps":["Preparare la chermoula: mescolare prezzemolo, coriandolo, aglio, cumino, paprica, peperoncino, scorza di limone, metà del succo, 1 cucchiaio d''olio d''oliva e un pizzico di sale.","Tagliare i filetti di pollo a metà nello spessore e massaggiarli con due terzi della chermoula.","Cuocere in friggitrice ad aria a 200 °C per 12–15 min, girando a metà, finché i bordi sono abbrustoliti e il cuore è a 75 °C.","Nel frattempo versare il brodo caldo sul cous cous in una pentola fuori dal fuoco, coprire e lasciar riposare 5 min.","Sgranare il cous cous con la forchetta e unire pomodoro, cetriolo, cipolla rossa, il resto del succo di limone e dell''olio.","Mescolare la chermoula rimasta con lo yogurt.","Affettare il pollo e servirlo sul cous cous con lo yogurt alla chermoula."]}}'::jsonb),
  ('c7c319b4-d176-59d8-9705-957d1456be40'::uuid, '{"fr":{"title":"Penne all''arrabbiata au poulet et à la courgette","steps":["Porter à ébullition une grande casserole d''eau salée pour les penne.","Chauffer l''huile dans une grande poêle à feu moyen-vif, assaisonner le poulet et le dorer 4 à 5 min ; le retirer.","Mettre la courgette dans la poêle et cuire 3 min, puis ajouter l''ail et le piment 1 min sans laisser l''ail colorer.","Ajouter les tomates et le concentré, remettre le poulet et laisser mijoter 10 min jusqu''à ce que la sauce épaississe.","Pendant ce temps, cuire les penne al dente, 10 à 11 min environ, et garder une tasse d''eau de cuisson.","Égoutter les penne et les mélanger à la sauce avec un peu d''eau de cuisson jusqu''à ce qu''elles soient nappées ; servir avec le basilic et un peu de parmesan."]},"it":{"title":"Penne all''arrabbiata con pollo e zucchina","steps":["Portare a bollore una pentola capiente d''acqua salata per le penne.","Scaldare l''olio in una padella grande a fuoco medio-alto, condire il pollo e rosolarlo per 4–5 min finché è dorato; toglierlo.","Mettere la zucchina nella padella e cuocere 3 min, poi unire aglio e peperoncino per 1 min senza far scurire l''aglio.","Unire i pomodori e il concentrato, rimettere il pollo e cuocere a fuoco dolce 10 min finché il sugo si addensa.","Nel frattempo cuocere le penne al dente, circa 10–11 min, e tenere da parte una tazza d''acqua di cottura.","Scolare le penne e saltarle nel sugo con un goccio d''acqua di cottura finché sono lucide; servire con basilico e poco parmigiano."]}}'::jsonb),
  ('8ab64d4f-2865-591c-a2ca-1d6d643e0ad1'::uuid, '{"fr":{"title":"Tacos au poulet chipotle à l''air fryer, maïs grillé et salade de chou","steps":["Mélanger la pâte de chipotle, l''ail, le cumin, l''origan, le jus d''un demi-citron vert, l''huile et une pincée de sel ; y enrober le poulet.","Cuire le poulet à l''air fryer à 200 °C pendant 10 à 12 min en secouant à mi-cuisson, jusqu''à ce qu''il soit légèrement grillé et cuit.","Pendant ce temps, mélanger le chou et l''oignon rouge avec le jus d''un citron vert et une pincée de sel.","Faire griller le maïs dans une poêle sèche à feu vif 4 à 5 min en remuant de temps en temps ; le réserver.","Réchauffer les tortillas dans la même poêle 20 à 30 secondes de chaque côté.","Garnir les tortillas de salade de chou, de poulet et de maïs, ajouter une cuillerée de yaourt, la coriandre et le dernier citron vert en quartiers."]},"it":{"title":"Tacos di pollo al chipotle in friggitrice ad aria con mais abbrustolito e insalata di cavolo","steps":["Mescolare pasta di chipotle, aglio, cumino, origano, il succo di mezzo lime, l''olio e un pizzico di sale; condire il pollo.","Cuocere il pollo in friggitrice ad aria a 200 °C per 10–12 min, scuotendo a metà, finché è leggermente abbrustolito e cotto.","Nel frattempo condire cavolo e cipolla rossa con il succo di un lime e un pizzico di sale.","Abbrustolire il mais in una padella asciutta a fuoco vivo per 4–5 min, mescolando ogni tanto; tenerlo da parte.","Scaldare le tortillas nella stessa padella per 20–30 secondi per lato.","Farcire le tortillas con insalata di cavolo, pollo e mais, aggiungere un cucchiaio di yogurt, coriandolo e l''ultimo lime a spicchi."]}}'::jsonb),
  ('149d32ed-4e91-5b66-b0fe-145e8bd1f1f5'::uuid, '{"fr":{"title":"Pinchos morunos de poulet à l''air fryer, pommes de terre nouvelles et salade de poivrons","steps":["Cuire les pommes de terre 15 à 18 min dans une casserole d''eau salée bouillante jusqu''à ce qu''elles soient tendres ; égoutter.","Pendant ce temps, mélanger le cumin, le paprika fumé, la coriandre, le thym, l''ail, la moitié du jus de citron, 1 c. à soupe d''huile et une bonne pincée de sel ; y enrober le poulet.","Enfiler le poulet sur de petites brochettes adaptées au panier.","Cuire à l''air fryer à 190 °C pendant 12 à 14 min en retournant à mi-cuisson, jusqu''à ce qu''ils soient dorés et cuits.","Pour la salade, mélanger le poivron, la tomate et l''oignon rouge avec le vinaigre, le reste de l''huile et une pincée de sel.","Mélanger les pommes de terre chaudes avec le persil et le reste du jus de citron, et servir avec les brochettes et la salade."]},"it":{"title":"Pinchos morunos di pollo in friggitrice ad aria con patate novelle e insalata di peperoni","steps":["Lessare le patate in una pentola d''acqua salata per 15–18 min finché sono tenere; scolarle.","Nel frattempo mescolare cumino, paprica affumicata, coriandolo, timo, aglio, metà del succo di limone, 1 cucchiaio d''olio e un buon pizzico di sale; condire il pollo.","Infilare il pollo su spiedini corti adatti al cestello.","Cuocere in friggitrice ad aria a 190 °C per 12–14 min, girando a metà, finché sono dorati e cotti.","Per l''insalata condire peperone, pomodoro e cipolla rossa con l''aceto, il resto dell''olio e un pizzico di sale.","Condire le patate calde con prezzemolo e il resto del succo di limone e servirle con gli spiedini e l''insalata."]}}'::jsonb),
  ('c18003ce-3b5d-56be-acc1-86393d87785b'::uuid, '{"fr":{"title":"Pad prik khing au poulet, haricots verts et riz jasmin","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis laisser reposer 5 min à couvert.","Chauffer l''huile dans un wok à feu moyen et faire revenir la pâte de curry 1 min en remuant jusqu''à ce qu''elle embaume.","Monter le feu, ajouter le poulet et le faire sauter 3 min jusqu''à ce qu''il soit blanc partout.","Ajouter les haricots verts et 3 c. à soupe d''eau et faire sauter 4 à 5 min jusqu''à ce que les haricots soient tendres mais croquants et le poulet cuit.","Assaisonner avec la sauce poisson et le sucre, ajouter les feuilles de combava et cuire encore 30 secondes.","Servir sur le riz jasmin avec le piment émincé pour plus de piquant."]},"it":{"title":"Pad prik khing con pollo, fagiolini e riso jasmine","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min coperto.","Scaldare l''olio in un wok a fuoco medio e soffriggere la pasta di curry per 1 min, mescolando, finché profuma.","Alzare la fiamma, unire il pollo e saltarlo 3 min finché è bianco ovunque.","Unire i fagiolini e 3 cucchiai d''acqua e saltare 4–5 min finché i fagiolini sono teneri ma croccanti e il pollo è cotto.","Condire con salsa di pesce e zucchero, unire le foglie di lime kaffir e cuocere ancora 30 secondi.","Servire sul riso jasmine con il peperoncino a fettine per chi lo vuole più piccante."]}}'::jsonb),
  ('03cda661-245c-51fc-9d5e-8eb63aae54ee'::uuid, '{"fr":{"title":"Poulet achari à l''air fryer, naan et kachumber","steps":["Torréfier les graines de moutarde, de fenouil et de nigelle 1 min à sec dans une petite poêle jusqu''à ce qu''elles crépitent, puis les concasser grossièrement.","Mélanger les graines concassées avec le cumin, le piment en poudre, le curcuma, l''ail, le gingembre, le yaourt, la moitié du jus de citron et une bonne pincée de sel.","Enrober le poulet du yaourt achari et l''étaler en une seule couche dans le panier de l''air fryer.","Cuire à l''air fryer à 200 °C pendant 12 à 14 min en secouant à mi-cuisson, jusqu''à ce que les bords soient grillés et la viande cuite.","Pendant ce temps, préparer le kachumber : mélanger le concombre, la tomate, l''oignon rouge, la coriandre et la menthe avec le reste du jus de citron et une pincée de sel.","Réchauffer les naans dans l''air fryer les 2 dernières minutes, puis servir avec le poulet et le kachumber."]},"it":{"title":"Pollo achari in friggitrice ad aria con naan e kachumber","steps":["Tostare i semi di senape, finocchio e nigella in un padellino asciutto per 1 min finché scoppiettano, poi pestarli grossolanamente.","Mescolare i semi pestati con cumino, peperoncino in polvere, curcuma, aglio, zenzero, yogurt, metà del succo di limone e un buon pizzico di sale.","Ricoprire il pollo con lo yogurt achari e disporlo in un solo strato nel cestello della friggitrice ad aria.","Cuocere in friggitrice ad aria a 200 °C per 12–14 min, scuotendo a metà, finché i bordi sono abbrustoliti e la carne è cotta.","Nel frattempo preparare il kachumber: condire cetriolo, pomodoro, cipolla rossa, coriandolo e menta con il resto del succo di limone e un pizzico di sale.","Scaldare i naan nella friggitrice ad aria negli ultimi 2 min, poi servirli con il pollo e il kachumber."]}}'::jsonb),
  ('a14ad196-a3cd-54f6-9528-638660d11e5d'::uuid, '{"fr":{"title":"Poulet coréen soja-ail à l''air fryer, riz et namul d''épinards","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis laisser reposer hors du feu.","Mélanger le poulet avec la fécule et une pincée de sel et le cuire à l''air fryer à 200 °C pendant 16 à 18 min en secouant deux fois, jusqu''à ce qu''il soit croustillant et cuit.","Pendant ce temps, faire tomber les épinards 1 à 2 min dans une poêle avec un peu d''eau, égoutter, presser pour retirer l''eau et assaisonner avec l''huile de sésame, un peu d''ail et une pincée de sel.","Essuyer la poêle et faire frémir la sauce soja, le miel, le reste de l''ail, le gingembre, le vinaigre et 2 c. à soupe d''eau 2 à 3 min jusqu''à ce que la sauce soit collante.","Enrober le poulet chaud de laque.","Servir sur le riz avec le namul d''épinards, l''oignon nouveau et les graines de sésame."]},"it":{"title":"Pollo coreano soia e aglio in friggitrice ad aria con riso e namul di spinaci","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare fuori dal fuoco.","Condire il pollo con l''amido e un pizzico di sale e cuocerlo in friggitrice ad aria a 200 °C per 16–18 min, scuotendo due volte, finché è croccante e cotto.","Nel frattempo far appassire gli spinaci in una padella con un goccio d''acqua per 1–2 min, scolarli, strizzarli e condirli con olio di sesamo, un po'' d''aglio e un pizzico di sale.","Pulire la padella e far sobbollire salsa di soia, miele, il resto dell''aglio, zenzero, aceto e 2 cucchiai d''acqua per 2–3 min finché diventa appiccicosa.","Saltare il pollo caldo nella glassa finché è ben ricoperto.","Servire sul riso con il namul di spinaci, cipollotto e semi di sesamo."]}}'::jsonb),
  ('a11d46fd-8dc9-521a-bcc0-ae7cb3f950f9'::uuid, '{"fr":{"title":"Orzo au poulet et au citron à la grecque, épinards et tomates cerises","steps":["Assaisonner le poulet de sel, de poivre et de la moitié de l''origan et le dorer 5 min dans l''huile, dans une sauteuse avec couvercle à feu moyen-vif.","Ajouter l''oignon et cuire 3 min, puis l''ail et le reste de l''origan 30 secondes.","Ajouter l''orzo, le bouillon et le zeste de citron et porter à ébullition.","Couvrir et laisser mijoter 10 à 12 min en remuant de temps en temps, jusqu''à ce que l''orzo soit tendre et ait absorbé presque tout le bouillon.","Incorporer les tomates cerises et les épinards et cuire 2 min jusqu''à ce que les épinards tombent.","Ajouter le jus de citron, rectifier l''assaisonnement et servir parsemé de feta et d''aneth."]},"it":{"title":"Orzo greco al pollo e limone con spinaci e pomodorini","steps":["Condire il pollo con sale, pepe e metà dell''origano e rosolarlo nell''olio per 5 min in un tegame largo con coperchio a fuoco medio-alto.","Unire la cipolla e cuocere 3 min, poi aglio e il resto dell''origano per 30 secondi.","Unire l''orzo, il brodo e la scorza di limone e portare a bollore.","Coprire e cuocere a fuoco dolce 10–12 min, mescolando ogni tanto, finché l''orzo è tenero e ha assorbito quasi tutto il brodo.","Unire pomodorini e spinaci e cuocere 2 min finché gli spinaci appassiscono.","Aggiungere il succo di limone, regolare di sale e servire con feta e aneto sopra."]}}'::jsonb),
  ('bf976172-3ded-5855-82f6-e6f0db648843'::uuid, '{"fr":{"title":"Poulet sauce aux haricots noirs, poivrons et nouilles","steps":["Mélanger le poulet avec le vin de Shaoxing, 1 c. à café de fécule et 1 c. à café de sauce soja. Mélanger le reste de sauce soja, le sucre, le bouillon et le reste de fécule.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet, égoutter et rincer brièvement.","Chauffer l''huile dans un wok à feu vif et faire sauter le poulet 3 à 4 min jusqu''à ce qu''il soit doré ; le retirer.","Faire sauter l''oignon et les poivrons 2 min, puis ajouter les haricots noirs, l''ail et le gingembre 30 secondes.","Remettre le poulet, verser la sauce et mélanger 1 à 2 min jusqu''à ce qu''elle soit épaisse et brillante.","Servir sur les nouilles, avec du piment émincé si on aime."]},"it":{"title":"Pollo in salsa di fagioli neri con peperoni e noodles","steps":["Condire il pollo con vino Shaoxing, 1 cucchiaino di amido e 1 cucchiaino di salsa di soia. Mescolare il resto della soia, zucchero, brodo e l''amido rimasto.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione, scolarli e sciacquarli brevemente.","Scaldare l''olio in un wok a fuoco vivo e saltare il pollo per 3–4 min finché è dorato; toglierlo.","Saltare cipolla e peperoni per 2 min, poi unire fagioli neri, aglio e zenzero per 30 secondi.","Rimettere il pollo, versare la salsa e saltare 1–2 min finché è densa e lucida.","Servire sui noodles, con peperoncino a fettine a piacere."]}}'::jsonb),
  ('d7abf651-5d99-580a-8c8f-3a5ce00d0f20'::uuid, '{"fr":{"title":"Pollo saltado, pommes de terre à l''air fryer et riz","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau salée 12 min à feu doux, puis laisser reposer à couvert.","Mélanger les frites avec 1 c. à café d''huile et une pincée de sel et les cuire à l''air fryer à 200 °C pendant 18 à 20 min en secouant deux fois, jusqu''à ce qu''elles soient dorées et croustillantes.","Assaisonner le poulet avec le cumin, du sel et du poivre.","Quand il reste 8 min aux frites, chauffer le reste de l''huile dans un wok à feu très vif et saisir le poulet 4 à 5 min jusqu''à ce qu''il soit doré et cuit.","Ajouter l''ail et la pâte d''ají amarillo, puis l''oignon, et faire sauter 1 min pour que l''oignon reste croquant.","Ajouter la tomate, puis verser la sauce soja et le vinaigre sur les bords du wok chaud et faire sauter 30 secondes, jusqu''à ce qu''ils grésillent en une sauce légère.","Ajouter les frites et la coriandre et servir aussitôt avec le riz."]},"it":{"title":"Pollo saltado con patate in friggitrice ad aria e riso","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto.","Condire i bastoncini di patata con 1 cucchiaino d''olio e un pizzico di sale e cuocerli in friggitrice ad aria a 200 °C per 18–20 min, scuotendo due volte, finché sono dorati e croccanti.","Condire il pollo con cumino, sale e pepe.","Quando alle patate mancano 8 min, scaldare il resto dell''olio in un wok a fuoco vivissimo e scottare il pollo per 4–5 min finché è dorato e cotto.","Unire aglio e pasta di ají amarillo, poi la cipolla, e saltare 1 min perché la cipolla resti croccante.","Aggiungere il pomodoro, poi versare salsa di soia e aceto lungo i bordi del wok caldo e saltare 30 secondi finché sfrigolano in un sughetto leggero.","Unire le patate e il coriandolo e servire subito con il riso."]}}'::jsonb),
  ('8abe1f0a-a0f1-5620-b8e9-123b6e298553'::uuid, '{"fr":{"title":"Gà kho gừng (poulet vietnamien au gingembre), riz et pak choï","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux.","Mélanger le poulet avec 1 c. à soupe de sauce poisson et beaucoup de poivre noir.","Faire fondre le sucre avec 1 c. à soupe d''eau dans une poêle avec couvercle à feu moyen, sans remuer, 3 à 4 min jusqu''à obtenir un caramel ambré foncé.","Ajouter l''huile, l''échalote, l''ail et le gingembre et remuer 30 secondes, puis ajouter le poulet et l''enrober de caramel 2 min.","Verser le reste de sauce poisson et 100 ml d''eau, couvrir et laisser mijoter 10 min, puis découvrir et faire réduire 3 min jusqu''à ce que la sauce soit foncée et collante.","Pendant ce temps, poser le pak choï sur le riz pour ses 4 dernières minutes, remettre le couvercle et laisser cuire à la vapeur.","Servir le poulet et sa sauce avec le riz et le pak choï, parsemés d''oignon nouveau."]},"it":{"title":"Gà kho gừng (pollo vietnamita allo zenzero) con riso e pak choi","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min.","Condire il pollo con 1 cucchiaio di salsa di pesce e abbondante pepe nero.","Sciogliere lo zucchero con 1 cucchiaio d''acqua in una padella con coperchio a fuoco medio, senza mescolare, per 3–4 min finché diventa un caramello ambrato scuro.","Unire olio, scalogno, aglio e zenzero e mescolare 30 secondi, poi aggiungere il pollo e girarlo nel caramello per 2 min.","Versare il resto della salsa di pesce e 100 ml d''acqua, coprire e cuocere a fuoco dolce 10 min, poi scoprire e far ridurre 3 min finché la salsa è scura e appiccicosa.","Nel frattempo adagiare il pak choi sul riso negli ultimi 4 min, rimettere il coperchio e lasciarlo cuocere a vapore.","Servire il pollo con la sua salsa insieme a riso e pak choi, con cipollotto sopra."]}}'::jsonb),
  ('020a9392-2512-55f1-9700-d31508a57a3e'::uuid, '{"fr":{"title":"Poulet mojo à l''air fryer, riz et haricots noirs","steps":["Fouetter les jus d''orange et de citron vert avec l''ail, la moitié du cumin, l''origan, l''huile, du sel et du poivre : c''est le mojo.","Enrober le poulet d''un tiers du mojo et le cuire à l''air fryer à 200 °C pendant 16 à 18 min en le retournant à mi-cuisson, jusqu''à ce qu''il soit doré et à 75 °C à cœur.","Pendant ce temps, rincer le riz et le cuire à couvert dans 180 ml d''eau salée 12 min à feu doux.","Dans une seconde casserole, faire revenir l''oignon et le poivron vert dans 2 c. à soupe de mojo 5 min, puis ajouter les haricots noirs, le laurier, le reste du cumin et 4 c. à soupe d''eau et laisser mijoter 8 min.","Trancher le poulet et l''arroser du reste de mojo.","Servir avec le riz et les haricots noirs, parsemés de coriandre."]},"it":{"title":"Pollo al mojo in friggitrice ad aria con riso e fagioli neri","steps":["Sbattere i succhi d''arancia e lime con aglio, metà del cumino, origano, olio, sale e pepe: è il mojo.","Condire il pollo con un terzo del mojo e cuocerlo in friggitrice ad aria a 200 °C per 16–18 min, girandolo a metà, finché è dorato e a 75 °C al cuore.","Nel frattempo sciacquare il riso e cuocerlo coperto in 180 ml d''acqua salata a fuoco basso per 12 min.","In un secondo tegame stufare cipolla e peperone verde in 2 cucchiai di mojo per 5 min, poi unire fagioli neri, alloro, il resto del cumino e 4 cucchiai d''acqua e cuocere 8 min.","Affettare il pollo e irrorarlo con il resto del mojo.","Servire con riso e fagioli neri, con coriandolo sopra."]}}'::jsonb),
  ('6ade88fa-f405-5314-bbfb-0c109e97ec93'::uuid, '{"fr":{"title":"Keema matar à la dinde et chapatis","steps":["Chauffer l''huile dans une grande poêle à feu moyen et faire grésiller les graines de cumin 30 secondes.","Ajouter l''oignon et cuire 5 à 6 min jusqu''à ce qu''il soit doré, puis ajouter l''ail, le gingembre et le piment vert 1 min.","Ajouter la dinde et cuire 5 min à feu vif en l''émiettant à la cuillère, jusqu''à ce qu''elle ne soit plus rosée.","Ajouter la coriandre moulue, le curcuma, le piment en poudre et la tomate avec une pincée de sel et cuire 4 min jusqu''à ce que la tomate se défasse.","Ajouter les petits pois et 4 c. à soupe d''eau et laisser mijoter 4 min, jusqu''à ce que les pois soient tendres et le keema moelleux sans être liquide.","Incorporer le garam masala et le jus de citron.","Réchauffer les chapatis 20 secondes de chaque côté dans une poêle sèche et servir avec le keema et la coriandre."]},"it":{"title":"Keema matar di tacchino con chapati","steps":["Scaldare l''olio in una padella grande a fuoco medio e far sfrigolare i semi di cumino per 30 secondi.","Unire la cipolla e cuocere 5–6 min finché è dorata, poi aggiungere aglio, zenzero e peperoncino verde per 1 min.","Unire il tacchino e cuocere 5 min a fuoco vivo, sbriciolandolo con un cucchiaio, finché non è più rosa.","Unire coriandolo macinato, curcuma, peperoncino in polvere e pomodoro con un pizzico di sale e cuocere 4 min finché il pomodoro si disfa.","Unire i piselli e 4 cucchiai d''acqua e cuocere 4 min finché i piselli sono teneri e il keema è umido ma non brodoso.","Incorporare il garam masala e il succo di limone.","Scaldare i chapati in una padella asciutta per 20 secondi per lato e servirli con il keema e il coriandolo."]}}'::jsonb),
  ('7cda71ea-f66d-5583-9dd7-ec507c77a788'::uuid, '{"fr":{"title":"Nouilles dan dan à la dinde et pak choï","steps":["Fouetter la purée de sésame, 1,5 c. à soupe de sauce soja, le vinaigre noir, l''huile pimentée, le poivre du Sichuan, le sucre et la moitié de l''ail dans les bols de service.","Chauffer l''huile dans une poêle à feu vif et faire revenir la dinde 5 à 6 min en l''émiettant, jusqu''à ce qu''elle soit dorée et un peu croustillante.","Ajouter le reste de l''ail, le gingembre, le vin de Shaoxing, le hoisin, les cinq-épices et le reste de sauce soja et cuire 1 min jusqu''à ce que la poêle soit presque sèche.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet, en ajoutant le pak choï les 2 dernières minutes.","Délayer la sauce de chaque bol avec 3 c. à soupe d''eau de cuisson, puis égoutter les nouilles et le pak choï et les répartir dans les bols.","Garnir de dinde, d''oignon nouveau et de cacahuètes et tout mélanger à table."]},"it":{"title":"Noodles dan dan con tacchino e pak choi","steps":["Sbattere nelle ciotole da portata tahina, 1,5 cucchiai di salsa di soia, aceto nero, olio al peperoncino, pepe di Sichuan, zucchero e metà dell''aglio.","Scaldare l''olio in una padella a fuoco vivo e rosolare il tacchino per 5–6 min, sbriciolandolo, finché è dorato e un po'' croccante.","Unire il resto dell''aglio, zenzero, vino Shaoxing, hoisin, cinque spezie e la soia rimasta e cuocere 1 min finché la padella è quasi asciutta.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione, aggiungendo il pak choi negli ultimi 2 min.","Stemperare la salsa in ogni ciotola con 3 cucchiai d''acqua di cottura, poi scolare noodles e pak choi e dividerli nelle ciotole.","Completare con tacchino, cipollotto e arachidi e mescolare tutto a tavola."]}}'::jsonb),
  ('7796bb98-ab0a-5372-8642-dff105dc2ccd'::uuid, '{"fr":{"title":"Dinde piri-piri à l''air fryer et riz épicé","steps":["Écraser ou mixer les piments, l''ail, le paprika fumé, l''origan, le jus de citron, le vinaigre, l''huile d''olive et une bonne pincée de sel pour obtenir une sauce piri-piri fluide.","Faire revenir l''oignon et le poivron 4 min dans 1 c. à soupe de sauce, dans une casserole avec couvercle.","Ajouter le riz rincé et le curcuma, verser le bouillon, porter à ébullition, couvrir et cuire 12 min à feu doux.","Pendant ce temps, badigeonner les escalopes de dinde avec la moitié de la sauce restante.","Cuire à l''air fryer à 200 °C pendant 10 à 12 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient légèrement grillées et à 75 °C à cœur ; laisser reposer 3 min.","Répartir les petits pois et le maïs sur le riz, couvrir et cuire encore 3 min, puis égrener à la fourchette.","Trancher la dinde et la servir sur le riz avec le reste de sauce piri-piri."]},"it":{"title":"Tacchino piri-piri in friggitrice ad aria con riso piccante","steps":["Pestare o frullare peperoncini, aglio, paprica affumicata, origano, succo di limone, aceto, olio d''oliva e un buon pizzico di sale in una salsa piri-piri fluida.","Soffriggere cipolla e peperone in 1 cucchiaio di salsa in un tegame con coperchio per 4 min.","Unire il riso sciacquato e la curcuma, versare il brodo, portare a bollore, coprire e cuocere a fuoco basso per 12 min.","Nel frattempo spennellare le fette di tacchino con metà della salsa rimasta.","Cuocere in friggitrice ad aria a 200 °C per 10–12 min, girando a metà, finché sono leggermente abbrustolite e a 75 °C al cuore; far riposare 3 min.","Distribuire piselli e mais sul riso, coprire e cuocere altri 3 min, poi sgranare con la forchetta.","Affettare il tacchino e servirlo sul riso con il resto della salsa piri-piri."]}}'::jsonb),
  ('3bf77e79-a503-567b-86b2-d41c2d351516'::uuid, '{"fr":{"title":"Soboro don à la dinde, œufs brouillés et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux.","Poser les haricots verts sur le riz pour les 4 dernières minutes, remettre le couvercle et laisser cuire à la vapeur ; puis laisser reposer hors du feu.","Battre les œufs avec 1 c. à café de sucre et une pincée de sel et les cuire dans une poêle antiadhésive à feu moyen-doux en remuant sans cesse avec des baguettes, 2 min, en fines miettes moelleuses ; réserver.","Mettre la dinde, le gingembre, la sauce soja, le mirin, le saké et le reste du sucre dans la même poêle froide et bien mélanger pour séparer la viande.","Cuire à feu moyen 6 à 7 min en remuant sans cesse avec des baguettes, jusqu''à ce que la viande soit en fines miettes et le liquide presque évaporé.","Remplir les bols de riz et disposer dessus la dinde, l''œuf et les haricots verts en trois parts ; ajouter le gingembre mariné."]},"it":{"title":"Soboro don di tacchino con uova e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min.","Adagiare i fagiolini sul riso negli ultimi 4 min, rimettere il coperchio e lasciarli cuocere a vapore; poi far riposare fuori dal fuoco.","Sbattere le uova con 1 cucchiaino di zucchero e un pizzico di sale e cuocerle in una padella antiaderente a fuoco medio-basso mescolando di continuo con le bacchette, per 2 min, in briciole fini e morbide; tenerle da parte.","Mettere nella stessa padella fredda tacchino, zenzero, salsa di soia, mirin, sake e il resto dello zucchero e mescolare bene per sgranare la carne.","Cuocere a fuoco medio per 6–7 min mescolando sempre con le bacchette, finché la carne è in briciole fini e il liquido è quasi evaporato.","Riempire le ciotole di riso e disporvi sopra tacchino, uovo e fagiolini in tre settori; aggiungere lo zenzero marinato."]}}'::jsonb),
  ('a7902387-e1b1-5e72-8f75-c3b7264fddfc'::uuid, '{"fr":{"title":"Escalopes de dinde à l''air fryer, sauce vierge et pommes de terre écrasées","steps":["Cuire les pommes de terre 15 à 18 min dans une casserole d''eau salée bouillante jusqu''à ce qu''elles soient tendres, en ajoutant les haricots verts les 5 dernières minutes.","Pendant ce temps, préparer la sauce vierge : mélanger la tomate, l''échalote, le jus de citron, le basilic, les olives, 1,5 c. à soupe d''huile d''olive, du sel et du poivre et laisser reposer.","Frotter les escalopes avec 1 c. à café d''huile d''olive, les herbes de Provence, du sel et du poivre.","Cuire à l''air fryer à 200 °C pendant 8 à 10 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et plus rosées à cœur.","Égoutter les pommes de terre et les haricots, écraser grossièrement les pommes de terre à la fourchette avec le reste de l''huile et assaisonner.","Servir la dinde sur les pommes de terre écrasées avec les haricots verts et napper de sauce vierge."]},"it":{"title":"Scaloppine di tacchino in friggitrice ad aria con salsa vergine e patate schiacciate","steps":["Lessare le patate in una pentola d''acqua salata per 15–18 min finché sono tenere, aggiungendo i fagiolini negli ultimi 5 min.","Nel frattempo preparare la salsa vergine: mescolare pomodoro, scalogno, succo di limone, basilico, olive, 1,5 cucchiai d''olio d''oliva, sale e pepe e lasciarla riposare.","Massaggiare le scaloppine con 1 cucchiaino d''olio d''oliva, le erbe di Provenza, sale e pepe.","Cuocere in friggitrice ad aria a 200 °C per 8–10 min, girando a metà, finché sono dorate e non più rosa all''interno.","Scolare patate e fagiolini, schiacciare grossolanamente le patate con la forchetta e il resto dell''olio e regolare di sale.","Servire il tacchino sulle patate schiacciate con i fagiolini e versarci sopra la salsa vergine."]}}'::jsonb),
  ('8e59d959-5ac0-5c4a-a475-c526e235adf0'::uuid, '{"fr":{"title":"Albóndigas de dinde à l''air fryer, pommes de terre en sauce tomate","steps":["Chauffer l''huile dans une sauteuse avec couvercle et faire revenir l''oignon et la carotte 4 min, puis ajouter l''ail émincé et le paprika 30 secondes.","Verser le vin et laisser bouillonner 1 min, puis ajouter les tomates, les pommes de terre, le bouillon, le laurier et une pincée de sel ; couvrir et laisser mijoter 15 min.","Pendant ce temps, mélanger la dinde, la chapelure, l''œuf, l''ail râpé, le persil et une bonne pincée de sel et former 12 boulettes avec les mains mouillées.","Cuire les boulettes à l''air fryer à 200 °C pendant 9 à 10 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient dorées.","Ajouter les boulettes et les petits pois à la sauce et laisser mijoter 3 à 4 min à découvert, jusqu''à ce que les pommes de terre soient tendres et les boulettes cuites.","Servir dans des assiettes creuses avec beaucoup de sauce."]},"it":{"title":"Albóndigas di tacchino in friggitrice ad aria con patate al pomodoro","steps":["Scaldare l''olio in un tegame largo con coperchio e stufare cipolla e carota per 4 min, poi aggiungere l''aglio a fettine e la paprica per 30 secondi.","Versare il vino e farlo sfumare 1 min, poi unire pomodori, patate, brodo, alloro e un pizzico di sale; coprire e cuocere a fuoco dolce 15 min.","Nel frattempo impastare tacchino, pangrattato, uovo, aglio grattugiato, prezzemolo e un buon pizzico di sale e formare 12 polpette con le mani bagnate.","Cuocere le polpette in friggitrice ad aria a 200 °C per 9–10 min, scuotendo a metà, finché sono dorate.","Unire polpette e piselli al sugo e cuocere scoperto per 3–4 min finché le patate sono tenere e le polpette cotte.","Servire in piatti fondi con abbondante sugo."]}}'::jsonb),
  ('af2d856a-7536-5d5f-8b81-f02327abae2a'::uuid, '{"fr":{"title":"Huevos a la flamenca, pommes de terre et petits pois","steps":["Cuire les pommes de terre 8 min dans une casserole d''eau salée bouillante en ajoutant les petits pois et les haricots verts les 3 dernières minutes ; égoutter.","Pendant ce temps, chauffer l''huile dans une grande poêle avec couvercle et faire revenir le chorizo et la moitié du jambon 2 min, jusqu''à ce que le chorizo rende son gras rouge.","Ajouter l''oignon et le poivron et cuire 5 min jusqu''à ce qu''ils soient tendres, puis l''ail et le paprika 30 secondes.","Verser les tomates avec une pincée de sel et laisser mijoter 5 min jusqu''à ce que la sauce épaississe.","Incorporer les pommes de terre, les petits pois et les haricots, creuser quatre puits et y casser un œuf dans chacun.","Parsemer du reste de jambon, couvrir et cuire à feu doux 6 à 8 min jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer de persil et servir directement dans la poêle."]},"it":{"title":"Huevos a la flamenca con patate e piselli","steps":["Lessare le patate in una pentola d''acqua salata per 8 min, aggiungendo piselli e fagiolini negli ultimi 3 min; scolare.","Nel frattempo scaldare l''olio in una padella grande con coperchio e rosolare il chorizo e metà del prosciutto per 2 min finché il chorizo rilascia il suo grasso rosso.","Unire cipolla e peperone e cuocere 5 min finché sono morbidi, poi aglio e paprica per 30 secondi.","Versare i pomodori con un pizzico di sale e cuocere 5 min finché il sugo si addensa.","Incorporare patate, piselli e fagiolini, formare quattro conche e rompervi un uovo ciascuna.","Distribuire sopra il resto del prosciutto, coprire e cuocere a fuoco basso per 6–8 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere di prezzemolo e servire direttamente in padella."]}}'::jsonb),
  ('de68f89e-56c1-57c8-8b4b-2f5d4067110f'::uuid, '{"fr":{"title":"Pulao aux œufs et petits pois, raïta au concombre","steps":["Plonger les œufs dans une casserole d''eau bouillante et les cuire 9 min, puis les refroidir, les écaler et les piquer partout à la fourchette.","Pendant ce temps, rincer le riz à plusieurs eaux jusqu''à ce que l''eau soit claire.","Chauffer l''huile dans une casserole avec couvercle et faire grésiller le cumin, le laurier, la cardamome et la cannelle 30 secondes, puis cuire l''oignon 5 min jusqu''à ce qu''il soit doré.","Ajouter l''ail, le gingembre, la tomate, la carotte, le curcuma, le garam masala et le piment et cuire 2 min, puis rouler les œufs dans ce masala 1 min.","Ajouter le riz et les petits pois, verser 300 ml d''eau avec une bonne pincée de sel, porter à ébullition, couvrir et cuire 12 min à feu doux ; laisser reposer 3 min.","Pour la raïta, mélanger le yaourt avec le concombre, la menthe et une pincée de sel.","Égrener délicatement le pulao, poser dessus les œufs coupés en deux, parsemer de coriandre et servir avec la raïta."]},"it":{"title":"Pulao di uova e piselli con raita di cetriolo","steps":["Immergere le uova in una pentola d''acqua bollente e cuocerle 9 min, poi raffreddarle, sgusciarle e bucherellarle con una forchetta.","Nel frattempo sciacquare il riso in più acque finché l''acqua è limpida.","Scaldare l''olio in un tegame con coperchio e far sfrigolare cumino, alloro, cardamomo e cannella per 30 secondi, poi cuocere la cipolla per 5 min finché è dorata.","Unire aglio, zenzero, pomodoro, carota, curcuma, garam masala e peperoncino e cuocere 2 min, poi girare le uova in questo masala per 1 min.","Unire riso e piselli, versare 300 ml d''acqua con un buon pizzico di sale, portare a bollore, coprire e cuocere a fuoco basso per 12 min; far riposare 3 min.","Per la raita mescolare lo yogurt con il cetriolo, la menta e un pizzico di sale.","Sgranare delicatamente il pulao, adagiarvi sopra le uova tagliate a metà, cospargere di coriandolo e servire con la raita."]}}'::jsonb),
  ('a021169b-4ba3-50ef-9b7a-deec16739d7e'::uuid, '{"fr":{"title":"Tinola de poulet à la papaye verte, épinards et riz","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis laisser reposer à couvert.","Chauffer l''huile dans une grande casserole et faire revenir l''oignon, l''ail et le gingembre à feu moyen 2 à 3 min jusqu''à ce qu''ils embaument.","Ajouter le poulet et la sauce poisson et remuer 3 min jusqu''à ce que le poulet devienne opaque.","Verser le bouillon, porter à ébullition et laisser frémir 5 min en écumant.","Ajouter la papaye verte et laisser frémir 8 à 10 min jusqu''à ce qu''elle soit tendre sous la pointe d''un couteau.","Incorporer les épinards hors du feu jusqu''à ce qu''ils tombent, puis poivrer et rectifier avec de la sauce poisson.","Servir la tinola dans des bols avec le riz à côté."]},"it":{"title":"Tinola di pollo con papaya verde, spinaci e riso","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare coperto.","Scaldare l''olio in una pentola capiente e soffriggere cipolla, aglio e zenzero a fuoco medio per 2–3 min finché profumano.","Unire il pollo e la salsa di pesce e mescolare per 3 min finché il pollo diventa opaco.","Versare il brodo, portare a bollore e cuocere a fuoco dolce 5 min, schiumando.","Unire la papaya verde e cuocere 8–10 min finché è tenera alla punta del coltello.","Incorporare gli spinaci fuori dal fuoco finché appassiscono, poi pepare e regolare con altra salsa di pesce.","Servire la tinola nelle ciotole con il riso a parte."]}}'::jsonb),
  ('b25b5c62-875d-559f-8c41-50052fcbfd0d'::uuid, '{"fr":{"title":"Ayam masak merah aux petits pois et riz","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis laisser reposer à couvert.","Frotter le poulet avec le curcuma et une pincée de sel. Piler ou mixer la moitié de l''oignon avec l''ail, le gingembre, le piment et 2 c. à soupe d''eau pour obtenir une pâte.","Chauffer l''huile dans une poêle avec couvercle et saisir le poulet à feu vif 4 à 5 min jusqu''à ce qu''il soit doré ; le retirer.","Faire revenir la pâte avec la citronnelle, la badiane et la cannelle à feu moyen 3 à 4 min en remuant, jusqu''à ce qu''elle fonce et que l''huile se sépare.","Ajouter les tomates, le ketchup, le sucre et l''oignon émincé, remettre le poulet, couvrir et laisser mijoter 8 min jusqu''à ce que la sauce soit épaisse et rouge.","Ajouter les petits pois et cuire encore 3 min ; saler.","Retirer les épices entières et servir avec le riz et le concombre en tranches."]},"it":{"title":"Ayam masak merah con piselli e riso","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare coperto.","Massaggiare il pollo con la curcuma e un pizzico di sale. Pestare o frullare metà della cipolla con aglio, zenzero, peperoncino e 2 cucchiai d''acqua fino a ottenere una pasta.","Scaldare l''olio in una padella con coperchio e rosolare il pollo a fuoco vivo per 4–5 min finché è dorato; toglierlo.","Soffriggere la pasta con citronella, anice stellato e cannella a fuoco medio per 3–4 min, mescolando, finché scurisce e l''olio si separa.","Unire pomodori, ketchup, zucchero e la cipolla affettata, rimettere il pollo, coprire e cuocere a fuoco dolce 8 min finché la salsa è densa e rossa.","Unire i piselli e cuocere altri 3 min; salare.","Togliere le spezie intere e servire con il riso e il cetriolo a fette."]}}'::jsonb),
  ('77465ae6-5bc1-5aec-8bde-63d806d4b60a'::uuid, '{"fr":{"title":"Tavuk sote, pilaf de boulgour et cacık","steps":["Pour le pilaf, mélanger le boulgour et 1 c. à café de concentré de tomate avec le bouillon et une pincée de sel dans une casserole, porter à ébullition, couvrir et cuire 12 min à feu doux ; laisser reposer 5 min hors du feu.","Chauffer l''huile dans une grande poêle à feu vif, assaisonner le poulet et le saisir 4 à 5 min jusqu''à ce qu''il soit doré ; le retirer.","Faire revenir l''oignon et les poivrons 5 min dans la même poêle jusqu''à ce qu''ils soient tendres, puis ajouter l''ail 30 secondes.","Ajouter la pâte de poivron et le reste du concentré de tomate 1 min, puis la tomate, le paprika, l''origan et 4 c. à soupe d''eau.","Remettre le poulet et laisser mijoter 5 à 6 min jusqu''à ce que la tomate forme une sauce épaisse et que le poulet soit cuit.","Pour le cacık, mélanger le yaourt avec le concombre pressé et une pincée de sel.","Égrener le boulgour et servir avec le tavuk sote, le cacık, une pincée de piment d''Alep et le persil."]},"it":{"title":"Tavuk sote con pilaf di bulgur e cacık","steps":["Per il pilaf mescolare in una pentola il bulgur e 1 cucchiaino di concentrato con il brodo e un pizzico di sale, portare a bollore, coprire e cuocere 12 min a fuoco basso; far riposare 5 min fuori dal fuoco.","Scaldare l''olio in una padella grande a fuoco vivo, condire il pollo e rosolarlo per 4–5 min finché è dorato; toglierlo.","Stufare cipolla e peperoni nella stessa padella per 5 min finché sono morbidi, poi unire l''aglio per 30 secondi.","Unire la pasta di peperoni e il resto del concentrato per 1 min, poi pomodoro, paprica, origano e 4 cucchiai d''acqua.","Rimettere il pollo e cuocere a fuoco dolce 5–6 min finché il pomodoro diventa un sugo denso e il pollo è cotto.","Per il cacık mescolare lo yogurt con il cetriolo strizzato e un pizzico di sale.","Sgranare il bulgur e servirlo con il tavuk sote, il cacık, un pizzico di pepe di Aleppo e il prezzemolo."]}}'::jsonb),
  ('cca6fe9b-0172-4d9d-a3fd-a702cd9f7788'::uuid, '{"fr":{"title":"Larb de bœuf thaï, riz jasmin et haricots verts","steps":["Faire griller la cuillère de riz cru dans une poêle sèche à feu moyen, en secouant souvent, 4 à 5 min jusqu''à ce qu''il soit bien doré. Le moudre grossièrement au mortier ou au moulin à épices.","Rincer le riz jasmin et le cuire à couvert dans 225 ml d''eau 12 min à feu doux.","Poser les haricots verts sur le riz, recouvrir et cuire à la vapeur 5 min, puis laisser reposer hors du feu.","Dans la même poêle, cuire le bœuf avec 3 c. à soupe d''eau à feu moyen-vif en l''émiettant, 5 à 6 min, jusqu''à ce qu''il ne soit plus rosé et que le liquide ait presque disparu.","Retirer du feu. Incorporer la sauce poisson, le jus de citron vert, le piment et le sucre, puis les échalotes, la poudre de riz grillé, les oignons nouveaux, la menthe et la coriandre. Goûter : c''est acide, salé et piquant.","Servir le larb avec le riz, les haricots verts, le concombre et les feuilles de laitue."]},"it":{"title":"Larb di manzo thai con riso jasmine e fagiolini","steps":["Tostare il cucchiaio di riso crudo in una padella asciutta a fuoco medio, scuotendo spesso, 4-5 min finché è ben dorato. Macinarlo grossolanamente nel mortaio o nel macinaspezie.","Sciacquare il riso jasmine e cuocerlo coperto in 225 ml d''acqua per 12 min a fuoco basso.","Adagiare i fagiolini sul riso, coprire di nuovo e cuocere a vapore 5 min, poi lasciar riposare fuori dal fuoco.","Nella stessa padella cuocere il manzo con 3 cucchiai d''acqua a fuoco medio-alto, sgranandolo, 5-6 min finché non è più rosa e il liquido è quasi evaporato.","Togliere dal fuoco. Unire salsa di pesce, succo di lime, peperoncino e zucchero, poi scalogni, polvere di riso tostato, cipollotti, menta e coriandolo. Assaggiare: deve essere aspro, sapido e piccante.","Servire il larb con il riso, i fagiolini, il cetriolo e le foglie di lattuga."]}}'::jsonb),
  ('651d32fd-5eb0-43da-9364-2fbd2b03b8e0'::uuid, '{"fr":{"title":"Fajitas de bœuf au air fryer, poivrons et salsa fraîche","steps":["Mélanger le chili en poudre, le cumin, le paprika, l''origan, l''ail, la moitié de l''huile, la moitié du jus de citron vert et une bonne pincée de sel. Y enrober les lanières de bœuf.","Mélanger les poivrons et l''oignon avec le reste d''huile et une pincée de sel. Cuire au air fryer à 200 °C 8 min en secouant une fois, jusqu''à ce qu''ils soient tendres et grillés sur les bords.","Ajouter le bœuf dans le panier sur les légumes et cuire encore 5 à 6 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré dehors et juste rosé à cœur.","Pendant ce temps, mélanger les tomates, la coriandre, le piment, le reste du jus de citron vert et une pincée de sel pour la salsa.","Réchauffer les tortillas une à une dans une poêle sèche à feu vif, environ 20 s par face, jusqu''à ce qu''elles soient légèrement grillées.","Garnir les tortillas de bœuf et de poivrons, de salsa et d''une cuillerée de yaourt."]},"it":{"title":"Fajitas di manzo in friggitrice ad aria con peperoni e salsa fresca","steps":["Mescolare chili in polvere, cumino, paprika, origano, aglio, metà dell''olio, metà del succo di lime e un buon pizzico di sale. Condire le strisce di manzo.","Condire peperoni e cipolla con il resto dell''olio e un pizzico di sale. Cuocere in friggitrice ad aria a 200 °C per 8 min, scuotendo una volta, finché sono morbidi e abbrustoliti ai bordi.","Aggiungere il manzo nel cestello sopra le verdure e cuocere altri 5-6 min, scuotendo a metà, finché è rosolato fuori e appena rosa dentro.","Intanto mescolare pomodori, coriandolo, peperoncino, il resto del succo di lime e un pizzico di sale per la salsa.","Scaldare le tortillas una alla volta in una padella asciutta a fuoco vivo, circa 20 s per lato, finché sono leggermente abbrustolite.","Farcire le tortillas con manzo e peperoni, salsa e un cucchiaio di yogurt."]}}'::jsonb),
  ('d5b912f8-0d70-4774-a415-1a5fa020a743'::uuid, '{"fr":{"title":"Chow fun au bœuf, germes de soja et pak choï","steps":["Mélanger le bœuf avec la fécule, le vin de riz et 1 c. à café de sauce soja.","Faire tremper les nouilles dans de l''eau tout juste bouillante dans un grand saladier 8 à 10 min, jusqu''à ce qu''elles soient souples mais encore fermes. Égoutter, rincer à l''eau froide et bien secouer.","Mélanger la sauce soja noire, le reste de sauce soja, la sauce huître et le sucre.","Chauffer la moitié de l''huile dans un wok à feu vif jusqu''à ce qu''elle fume. Saisir le bœuf en une couche 1 min par face, jusqu''à ce qu''il soit doré mais encore rosé, puis le retirer.","Ajouter le reste d''huile, le gingembre et l''oignon et faire sauter 1 min, puis le pak choï 1 min.","Ajouter les nouilles et la sauce et faire sauter à feu vif 2 min en soulevant depuis le fond, jusqu''à ce que les nouilles soient uniformément brunes et un peu grillées.","Remettre le bœuf avec les germes de soja et les oignons nouveaux et faire sauter 30 s, juste le temps que les germes s''attendrissent. Servir aussitôt."]},"it":{"title":"Chow fun di manzo con germogli di soia e pak choi","steps":["Condire il manzo con amido, vino di riso e 1 cucchiaino di salsa di soia.","Mettere in ammollo i noodles in acqua appena bollita in una ciotola capiente per 8-10 min, finché sono flessibili ma ancora sodi. Scolare, sciacquare sotto l''acqua fredda e scuotere bene.","Mescolare la salsa di soia scura, il resto della salsa di soia, la salsa d''ostriche e lo zucchero.","Scaldare metà dell''olio nel wok a fuoco vivo finché fuma. Scottare il manzo in un solo strato 1 min per lato finché è rosolato ma ancora rosa, poi toglierlo.","Aggiungere il resto dell''olio, lo zenzero e la cipolla e saltare 1 min, poi il pak choi per 1 min.","Unire i noodles e la salsa e saltare a fuoco vivo 2 min sollevando dal fondo, finché i noodles sono uniformemente bruniti e un po'' abbrustoliti.","Rimettere il manzo con germogli e cipollotti e saltare 30 s, giusto finché i germogli appassiscono. Servire subito."]}}'::jsonb),
  ('6e7bb3d3-506f-45a4-9097-8c2b6803a312'::uuid, '{"fr":{"title":"Tagliata, roquette, tomates cerises et pommes de terre au air fryer","steps":["Mélanger les pommes de terre avec 1 c. à soupe d''huile, le romarin, l''ail et une pincée de sel. Cuire au air fryer à 200 °C 18 à 20 min en secouant deux fois, jusqu''à ce qu''elles soient dorées et tendres.","Sortir le steak du réfrigérateur pendant la cuisson des pommes de terre. Le frotter avec 1 c. à café d''huile, saler et poivrer.","Quand il reste 10 min aux pommes de terre, chauffer une poêle-gril ou une poêle épaisse à feu vif. Saisir le steak 3 à 4 min par face pour une cuisson saignante (environ 52 °C à cœur).","Laisser reposer le steak sur une planche, couvert d''aluminium sans serrer, 5 min.","Mélanger la roquette et les tomates avec le reste d''huile, le balsamique et une pincée de sel, et les répartir dans les assiettes.","Trancher finement le steak dans le sens contraire des fibres, le poser sur la salade avec son jus, parsemer de copeaux de parmesan et servir avec les pommes de terre."]},"it":{"title":"Tagliata con rucola, pomodorini e patate in friggitrice ad aria","steps":["Condire le patate con 1 cucchiaio d''olio, il rosmarino, l''aglio e un pizzico di sale. Cuocere in friggitrice ad aria a 200 °C per 18-20 min, scuotendo due volte, finché sono dorate e tenere.","Togliere la bistecca dal frigo mentre cuociono le patate. Massaggiarla con 1 cucchiaino d''olio, salare e pepare.","Quando mancano 10 min alle patate, scaldare una bistecchiera o una padella pesante a fuoco vivo. Cuocere la bistecca 3-4 min per lato per una cottura al sangue (circa 52 °C al cuore).","Far riposare la bistecca su un tagliere, coperta senza stringere con alluminio, per 5 min.","Condire rucola e pomodorini con il resto dell''olio, l''aceto balsamico e un pizzico di sale, e distribuirli nei piatti.","Tagliare la bistecca a fette sottili contro fibra, adagiarla sull''insalata con il suo sugo, cospargere di scaglie di parmigiano e servire con le patate."]}}'::jsonb),
  ('54cae69c-e6c8-4569-9b05-9254fa2cb357'::uuid, '{"fr":{"title":"Arayes (pitas farcies au bœuf épicé), yaourt au tahini et salade","steps":["Mélanger le bœuf avec l''oignon râpé, le persil, l''ail, le paprika, le cumin, le piment de la Jamaïque, la coriandre, 0,5 c. à café de sel et du poivre.","Ouvrir les pitas et étaler une fine couche régulière de viande à l''intérieur de chacune, jusqu''aux bords. Les aplatir et badigeonner l''extérieur d''huile.","Chauffer une poêle-gril ou une poêle épaisse à feu moyen. Cuire les arayes 5 à 6 min par face en appuyant avec une spatule, jusqu''à ce que le pain soit croustillant et la viande cuite.","Pendant ce temps, fouetter le tahini avec le yaourt, le jus d''un demi-citron, une pincée de sel et un peu d''eau jusqu''à ce que ce soit lisse.","Mélanger les tomates, le concombre, la laitue et l''oignon rouge avec le jus de l''autre demi-citron et une pincée de sel.","Couper les arayes en triangles et servir avec le yaourt au tahini et la salade."]},"it":{"title":"Arayes (pita ripiene di manzo speziato) con yogurt al tahini e insalata","steps":["Mescolare il manzo con cipolla grattugiata, prezzemolo, aglio, paprika, cumino, pimento, coriandolo, 0,5 cucchiaini di sale e un po'' di pepe.","Aprire le tasche di pita e stendere all''interno di ciascuna uno strato sottile e uniforme di carne, fino ai bordi. Schiacciarle e spennellare l''esterno con l''olio.","Scaldare una bistecchiera o una padella pesante a fuoco medio. Cuocere gli arayes 5-6 min per lato premendo con una spatola, finché il pane è croccante e la carne cotta.","Intanto sbattere il tahini con lo yogurt, il succo di mezzo limone, un pizzico di sale e un goccio d''acqua fino a renderlo liscio.","Condire pomodori, cetriolo, lattuga e cipolla rossa con il succo dell''altro mezzo limone e un pizzico di sale.","Tagliare gli arayes a spicchi e servire con lo yogurt al tahini e l''insalata."]}}'::jsonb),
  ('b23711c2-533a-423a-80ab-b602acff9574'::uuid, '{"fr":{"title":"Bibim-guksu au bœuf saisi (nouilles froides épicées coréennes)","steps":["Porter une casserole d''eau à ébullition. Y plonger les œufs et les cuire 7 min, puis les refroidir à l''eau froide et les écaler.","Mélanger le gochujang, le vinaigre, le sucre, 1 c. à soupe de sauce soja, l''ail et l''huile de sésame pour la sauce.","Mélanger le bœuf avec le reste de sauce soja. Chauffer l''huile dans une poêle à feu vif et saisir le bœuf en une couche 1 à 2 min par face, jusqu''à ce qu''il soit doré.","Cuire les nouilles dans l''eau des œufs selon le paquet, environ 3 min. Égoutter et rincer sous l''eau froide en les frottant entre les mains jusqu''à ce qu''elles soient froides ; bien égoutter.","Mélanger les nouilles avec la plus grande partie de la sauce et le kimchi.","Dresser dans des bols avec la laitue, le concombre et la carotte, garnir de bœuf et d''un œuf coupé en deux, napper le bœuf du reste de sauce et parsemer de sésame."]},"it":{"title":"Bibim-guksu con manzo scottato (noodles freddi piccanti coreani)","steps":["Portare a ebollizione una pentola d''acqua. Calarvi le uova e cuocerle 7 min, poi raffreddarle in acqua fredda e sgusciarle.","Mescolare gochujang, aceto, zucchero, 1 cucchiaio di salsa di soia, aglio e olio di sesamo per la salsa.","Condire il manzo con il resto della salsa di soia. Scaldare l''olio in una padella a fuoco vivo e scottare il manzo in un solo strato 1-2 min per lato, finché è rosolato.","Cuocere i noodles nell''acqua delle uova come indicato sulla confezione, circa 3 min. Scolarli e sciacquarli sotto l''acqua fredda strofinandoli con le mani finché sono freddi; scolarli bene.","Condire i noodles con gran parte della salsa e il kimchi.","Disporre nelle ciotole con lattuga, cetriolo e carota, completare con il manzo e mezzo uovo, versare il resto della salsa sul manzo e cospargere di sesamo."]}}'::jsonb),
  ('1d4fa9dd-bb13-4362-860a-9653141bc724'::uuid, '{"fr":{"title":"Pad kra pao au porc, riz jasmin et œuf au plat","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau 12 min à feu doux, puis le laisser reposer hors du feu.","Piler l''ail et les piments en pâte grossière au mortier, ou les hacher finement ensemble.","Chauffer 2 c. à café d''huile dans un wok à feu vif. Faire revenir la pâte ail-piment 20 s, puis ajouter le porc et le faire sauter 3 à 4 min en l''émiettant, jusqu''à ce qu''il ne soit plus rosé.","Ajouter l''oignon et les haricots verts et faire sauter 2 min avec 2 c. à soupe d''eau, jusqu''à ce que les haricots soient vert vif.","Ajouter la sauce huître, la sauce soja, la sauce poisson et le sucre et faire sauter 1 min, jusqu''à ce que le porc soit brillant. Hors du feu, incorporer le basilic sacré juste le temps qu''il fane.","Essuyer le wok, chauffer le reste d''huile à feu moyen-vif et cuire les œufs 2 à 3 min, jusqu''à ce que les bords soient croustillants et les jaunes encore coulants.","Servir le porc sur le riz, un œuf par-dessus."]},"it":{"title":"Pad kra pao di maiale con riso jasmine e uovo all''occhio di bue","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Pestare aglio e peperoncini in una pasta grossolana nel mortaio, o tritarli finemente insieme.","Scaldare 2 cucchiaini d''olio nel wok a fuoco vivo. Soffriggere la pasta di aglio e peperoncino 20 s, poi unire il maiale e saltarlo 3-4 min sgranandolo, finché non è più rosa.","Aggiungere cipolla e fagiolini e saltare 2 min con 2 cucchiai d''acqua, finché i fagiolini sono verde brillante.","Unire salsa d''ostriche, salsa di soia, salsa di pesce e zucchero e saltare 1 min, finché il maiale è lucido. Fuori dal fuoco aggiungere il basilico sacro e mescolare finché appassisce.","Pulire il wok, scaldare il resto dell''olio a fuoco medio-alto e cuocere le uova 2-3 min, finché i bordi sono croccanti e i tuorli ancora morbidi.","Servire il maiale sul riso con un uovo sopra."]}}'::jsonb),
  ('47bf5056-24ad-4c5e-88a0-4117ac56b477'::uuid, '{"fr":{"title":"Filet mignon de porc au mojo au air fryer, haricots noirs et riz","steps":["Mélanger le jus d''orange et de citron vert, l''ail, le cumin, l''origan, 1 c. à soupe d''huile et une bonne pincée de sel et de poivre : c''est le mojo. En frotter 2 c. à soupe sur le porc.","Cuire le porc au air fryer à 200 °C 18 à 20 min en le retournant à mi-cuisson, jusqu''à 63 °C au plus épais. Le laisser reposer 5 min.","Pendant ce temps, rincer le riz et le cuire à couvert dans 225 ml d''eau salée 12 min à feu doux, puis le laisser reposer hors du feu.","Chauffer le reste d''huile dans une poêle à feu moyen et faire fondre l''oignon et le poivron 6 à 7 min.","Ajouter les haricots noirs, 3 c. à soupe de mojo et 4 c. à soupe d''eau et laisser mijoter 5 min en écrasant quelques haricots pour épaissir. Assaisonner.","Une fois les haricots retirés, faire bouillonner le reste du mojo 30 s dans la poêle, ou simplement le tiédir.","Trancher le porc, le napper de mojo chaud et servir avec le riz, les haricots et la coriandre."]},"it":{"title":"Filetto di maiale al mojo in friggitrice ad aria con fagioli neri e riso","steps":["Mescolare succo d''arancia e di lime, aglio, cumino, origano, 1 cucchiaio d''olio e un buon pizzico di sale e pepe: è il mojo. Massaggiarne 2 cucchiai sul maiale.","Cuocere il maiale in friggitrice ad aria a 200 °C per 18-20 min, girandolo a metà, finché segna 63 °C nel punto più spesso. Farlo riposare 5 min.","Intanto sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata per 12 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Scaldare il resto dell''olio in una padella a fuoco medio e appassire cipolla e peperone 6-7 min.","Unire i fagioli neri, 3 cucchiai di mojo e 4 cucchiai d''acqua e cuocere 5 min, schiacciando qualche fagiolo per addensare. Regolare di sale.","Tolti i fagioli, far sobbollire il resto del mojo nella padella per 30 s, o semplicemente intiepidirlo.","Affettare il maiale, nappare con il mojo caldo e servire con riso, fagioli e coriandolo."]}}'::jsonb),
  ('61a67fe4-ed20-43c4-8c9f-baf3e10b7374'::uuid, '{"fr":{"title":"Bún thịt nướng au air fryer (bols de nouilles au porc à la citronnelle)","steps":["Mélanger la citronnelle, 2 gousses d''ail, l''échalote, 1 c. à soupe de sauce poisson, 1 c. à soupe de sucre, la sauce soja et l''huile. Y enrober les tranches de porc.","Pour le nuoc cham, dissoudre le reste du sucre (1 c. à soupe) dans 4 c. à soupe d''eau tiède, puis ajouter le jus de citron vert, les 2 c. à soupe de sauce poisson restantes, la dernière gousse d''ail et le piment.","Cuire les vermicelles dans l''eau bouillante 3 à 4 min, égoutter, rincer à l''eau froide et bien laisser égoutter.","Étaler le porc en couche fine dans le panier du air fryer et cuire à 200 °C 8 à 10 min en retournant à mi-cuisson, jusqu''à ce qu''il soit caramélisé sur les bords.","Répartir les nouilles dans deux bols avec la laitue, le concombre, la carotte, les germes de soja et les herbes.","Ajouter le porc et les cacahuètes et servir avec le nuoc cham à verser dessus."]},"it":{"title":"Bún thịt nướng in friggitrice ad aria (ciotole di noodles con maiale alla citronella)","steps":["Mescolare citronella, 2 spicchi d''aglio, scalogno, 1 cucchiaio di salsa di pesce, 1 cucchiaio di zucchero, salsa di soia e olio. Condire le fettine di maiale.","Per il nuoc cham sciogliere il cucchiaio di zucchero rimasto in 4 cucchiai d''acqua tiepida, poi unire succo di lime, i 2 cucchiai di salsa di pesce rimasti, l''ultimo spicchio d''aglio e il peperoncino.","Cuocere i vermicelli in acqua bollente 3-4 min, scolarli, sciacquarli sotto l''acqua fredda e lasciarli sgocciolare bene.","Stendere il maiale in uno strato sottile nel cestello e cuocere in friggitrice ad aria a 200 °C per 8-10 min, girando a metà, finché è caramellato ai bordi.","Dividere i noodles in due ciotole con lattuga, cetriolo, carota, germogli di soia ed erbe.","Completare con il maiale e le arachidi e servire con il nuoc cham da versare sopra."]}}'::jsonb),
  ('0e197b9e-dc69-441f-a2d1-cd9136bbec72'::uuid, '{"fr":{"title":"Nouilles dan dan au porc et pak choï","steps":["Porter une grande casserole d''eau à ébullition pour les nouilles.","Dans un grand bol, mélanger la pâte de sésame, 1,5 c. à soupe de sauce soja, le vinaigre noir, le piment, le poivre du Sichuan et le sucre, puis détendre avec 3 c. à soupe d''eau chaude.","Chauffer l''huile dans un wok à feu vif. Faire sauter le porc 5 à 6 min en l''émiettant, jusqu''à ce qu''il soit doré et un peu croustillant. Ajouter le gingembre, le vin de riz, le cinq-épices et le reste de sauce soja et cuire encore 1 min.","Cuire les nouilles selon le paquet en ajoutant le pak choï les 2 dernières minutes.","Égoutter les nouilles et le pak choï en gardant une tasse d''eau de cuisson. Mélanger les nouilles avec la sauce en ajoutant un peu d''eau pour bien les enrober.","Répartir dans des bols avec le pak choï, garnir de porc, d''oignons nouveaux et de cacahuètes, et mélanger à table."]},"it":{"title":"Noodles dan dan con maiale e pak choi","steps":["Portare a ebollizione una pentola d''acqua per i noodles.","In una ciotola ampia mescolare pasta di sesamo, 1,5 cucchiai di salsa di soia, aceto nero, peperoncino, pepe di Sichuan e zucchero, poi diluire con 3 cucchiai d''acqua calda.","Scaldare l''olio nel wok a fuoco vivo. Saltare il maiale 5-6 min sgranandolo, finché è rosolato e un po'' croccante. Aggiungere zenzero, vino di riso, cinque spezie e il resto della salsa di soia e cuocere ancora 1 min.","Cuocere i noodles come indicato sulla confezione, aggiungendo il pak choi negli ultimi 2 min.","Scolare noodles e pak choi tenendo da parte una tazza d''acqua di cottura. Condire i noodles con la salsa, aggiungendo un goccio d''acqua perché siano ben avvolti.","Dividere nelle ciotole con il pak choi, completare con maiale, cipollotti e arachidi e mescolare a tavola."]}}'::jsonb),
  ('ff31b27c-f7a0-4a2c-8178-b6c5f0362213'::uuid, '{"fr":{"title":"Pinchos morunos au air fryer, pain plat et salade de poivrons","steps":["Mélanger l''huile, le paprika, le cumin, la coriandre, le curcuma, l''origan, l''ail, le jus de citron et une bonne pincée de sel. Y enrober le porc et l''enfiler sur 4 petites brochettes.","Mélanger les tomates, le poivron, l''oignon et le persil avec le vinaigre, 1 c. à café d''huile et une pincée de sel, et laisser reposer la salade pendant la cuisson du porc.","Cuire les brochettes au air fryer à 200 °C 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et à 63 °C à cœur.","Réchauffer les pains plats dans une poêle sèche à feu moyen, 1 min par face.","Laisser reposer les brochettes 2 min, puis servir avec les pains et la salade de poivrons, en versant le jus de la salade sur le pain."]},"it":{"title":"Pinchos morunos in friggitrice ad aria con pane piatto e insalata di peperoni","steps":["Mescolare olio, paprika, cumino, coriandolo, curcuma, origano, aglio, succo di limone e un buon pizzico di sale. Condire il maiale e infilarlo su 4 spiedini corti.","Condire pomodori, peperone, cipolla e prezzemolo con aceto, 1 cucchiaino d''olio e un pizzico di sale, e lasciar riposare l''insalata mentre cuoce il maiale.","Cuocere gli spiedini in friggitrice ad aria a 200 °C per 10-12 min, girandoli a metà, finché sono rosolati e a 63 °C al cuore.","Scaldare i pani piatti in una padella asciutta a fuoco medio, 1 min per lato.","Far riposare gli spiedini 2 min, poi servire con i pani e l''insalata di peperoni, versando il sugo dell''insalata sul pane."]}}'::jsonb),
  ('e81736b7-c0d3-4850-96f2-1412807c26dc'::uuid, '{"fr":{"title":"Bols de riz au porc caramélisé à la vietnamienne et légumes marinés minute","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau 12 min à feu doux, puis le laisser reposer hors du feu.","Mélanger le concombre et la carotte avec le vinaigre, 1 c. à café de sucre et une pincée de sel et laisser mariner légèrement pendant la cuisson.","Chauffer l''huile dans une poêle à feu moyen-vif et faire revenir l''ail et l''échalote 1 min.","Ajouter le porc et cuire 4 à 5 min en l''émiettant, jusqu''à ce qu''il ne soit plus rosé et que le liquide se soit évaporé.","Ajouter la cassonade, la sauce poisson et beaucoup de poivre noir. Cuire 3 à 4 min en remuant seulement de temps en temps, jusqu''à ce que le porc soit foncé, collant et caramélisé, sans le laisser brûler.","Incorporer les oignons nouveaux et servir le porc sur le riz avec les légumes marinés, la laitue, les herbes, le piment et le citron vert."]},"it":{"title":"Ciotole di riso con maiale caramellato alla vietnamita e verdure in salamoia veloce","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Condire cetriolo e carota con aceto, 1 cucchiaino di zucchero e un pizzico di sale e lasciarli marinare leggermente durante la cottura.","Scaldare l''olio in una padella a fuoco medio-alto e soffriggere aglio e scalogno 1 min.","Aggiungere il maiale e cuocere 4-5 min sgranandolo, finché non è più rosa e il liquido è evaporato.","Unire zucchero di canna, salsa di pesce e abbondante pepe nero. Cuocere 3-4 min mescolando solo ogni tanto, finché il maiale è scuro, appiccicoso e caramellato, senza farlo bruciare.","Unire i cipollotti e servire il maiale sul riso con le verdure marinate, la lattuga, le erbe, il peperoncino e il lime."]}}'::jsonb),
  ('0995e5ef-558a-4c4a-bf22-99ea716d1664'::uuid, '{"fr":{"title":"Şiş kebab d''agneau au air fryer, pilaf de boulgour et salade du berger","steps":["Mélanger l''agneau avec 1 c. à café d''huile, le paprika, le cumin, le piment, l''ail, le jus d''un demi-citron et une bonne pincée de sel. L''enfiler sur 4 brochettes.","Faire fondre l''oignon haché dans une petite casserole avec un peu de bouillon 3 min, incorporer le concentré de tomate, puis ajouter le boulgour et le reste du bouillon. Couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu 5 min.","Pendant ce temps, cuire les brochettes au air fryer à 200 °C 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées dehors et encore un peu rosées dedans.","Pour la salade, mélanger les tomates, le concombre, le poivron, l''oignon rouge et le persil avec la mélasse de grenade, 1 c. à café d''huile, le jus de l''autre demi-citron et une pincée de sel.","Égrener le boulgour à la fourchette et servir avec les brochettes et la salade."]},"it":{"title":"Şiş kebab di agnello in friggitrice ad aria con pilaf di bulgur e insalata del pastore","steps":["Condire l''agnello con 1 cucchiaino d''olio, paprika, cumino, peperoncino, aglio, il succo di mezzo limone e un buon pizzico di sale. Infilarlo su 4 spiedini.","Appassire la cipolla tritata in un pentolino con un goccio di brodo per 3 min, unire il concentrato di pomodoro, poi il bulgur e il resto del brodo. Coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco 5 min.","Intanto cuocere gli spiedini in friggitrice ad aria a 200 °C per 10-12 min, girandoli a metà, finché sono rosolati fuori e ancora un po'' rosa dentro.","Per l''insalata condire pomodori, cetriolo, peperone, cipolla rossa e prezzemolo con melassa di melograno, 1 cucchiaino d''olio, il succo dell''altro mezzo limone e un pizzico di sale.","Sgranare il bulgur con una forchetta e servire con gli spiedini e l''insalata."]}}'::jsonb),
  ('874599a2-12ae-4d54-9074-856cc0bc7876'::uuid, '{"fr":{"title":"Hashweh (riz libanais à l''agneau épicé) et salade tomate-concombre","steps":["Faire griller les pignons dans une sauteuse sèche à feu moyen 2 à 3 min jusqu''à ce qu''ils soient dorés, puis les réserver.","Dans la même sauteuse, faire dorer l''agneau à feu moyen-vif 5 min en l''émiettant. Retirer l''excédent de gras à la cuillère.","Ajouter l''oignon et l''ail et cuire 3 min, puis incorporer le piment de la Jamaïque, la cannelle, la muscade, le sel et le poivre.","Ajouter le riz, bien l''enrober, verser le bouillon et porter à ébullition. Couvrir et cuire à feu doux 12 min, jusqu''à absorption du liquide, puis laisser reposer hors du feu 5 min.","Pendant ce temps, mélanger les tomates, le concombre, le persil et la menthe avec le jus de citron, l''huile et une pincée de sel.","Égrener le riz, parsemer de pignons et servir avec la salade."]},"it":{"title":"Hashweh (riso libanese con agnello speziato) e insalata di pomodori e cetrioli","steps":["Tostare i pinoli in una padella fonda asciutta a fuoco medio 2-3 min finché sono dorati, poi metterli da parte.","Nella stessa padella rosolare l''agnello a fuoco medio-alto 5 min, sgranandolo. Togliere con un cucchiaio il grasso in eccesso.","Aggiungere cipolla e aglio e cuocere 3 min, poi unire pimento, cannella, noce moscata, sale e pepe.","Aggiungere il riso, mescolare per insaporirlo, versare il brodo e portare a ebollizione. Coprire e cuocere a fuoco basso 12 min, finché il liquido è assorbito, poi lasciar riposare fuori dal fuoco 5 min.","Intanto condire pomodori, cetriolo, prezzemolo e menta con succo di limone, olio e un pizzico di sale.","Sgranare il riso, cospargere di pinoli e servire con l''insalata."]}}'::jsonb),
  ('59da88c3-74fc-46a4-a2a0-7888fa770b1e'::uuid, '{"fr":{"title":"Tranches de gigot d''agneau au air fryer, salsa verde et haricots blancs","steps":["Frotter les tranches avec 0,5 c. à café d''huile, le romarin, du sel et du poivre.","Cuire l''agneau au air fryer à 200 °C 8 à 10 min en le retournant à mi-cuisson, pour qu''il reste rosé à cœur. Le laisser reposer 5 min.","Pendant ce temps, hacher finement ensemble le persil, la menthe, les câpres et l''anchois, puis incorporer la moutarde, le vinaigre, 1 c. à soupe d''huile et 1 c. à soupe d''eau : c''est la salsa verde.","Chauffer le reste d''huile dans une poêle à feu moyen et faire revenir l''ail 1 min. Ajouter les tomates et cuire 3 min jusqu''à ce qu''elles commencent à éclater.","Ajouter les haricots avec 4 c. à soupe d''eau et laisser mijoter 3 min, puis incorporer les épinards jusqu''à ce qu''ils tombent. Assaisonner.","Trancher l''agneau et le servir sur les haricots, nappé de salsa verde."]},"it":{"title":"Fette di cosciotto d''agnello in friggitrice ad aria con salsa verde e fagioli bianchi","steps":["Massaggiare le fette con 0,5 cucchiaini d''olio, il rosmarino, sale e pepe.","Cuocere l''agnello in friggitrice ad aria a 200 °C per 8-10 min, girandolo a metà, perché resti rosa al centro. Farlo riposare 5 min.","Intanto tritare finemente insieme prezzemolo, menta, capperi e acciuga, poi unire senape, aceto, 1 cucchiaio d''olio e 1 cucchiaio d''acqua: è la salsa verde.","Scaldare il resto dell''olio in una padella a fuoco medio e soffriggere l''aglio 1 min. Aggiungere i pomodorini e cuocere 3 min finché iniziano ad aprirsi.","Unire i fagioli con 4 cucchiai d''acqua e cuocere 3 min, poi aggiungere gli spinaci finché appassiscono. Regolare di sale.","Affettare l''agnello e servirlo sui fagioli con la salsa verde sopra."]}}'::jsonb),
  ('78369880-0b00-4bb0-84dc-4793dc5d2869'::uuid, '{"fr":{"title":"Seekh kebabs d''agneau au air fryer, pain plat, kachumber et raïta à la menthe","steps":["Mélanger l''agneau avec l''oignon râpé, l''ail, le gingembre, le piment, la moitié de la coriandre, le garam masala, le cumin, le chili en poudre et 0,5 c. à café de sel. Pétrir 1 min jusqu''à ce que ce soit collant.","Les mains mouillées, former 6 longs boudins autour de brochettes, ou simplement des rouleaux.","Cuire au air fryer à 200 °C 10 à 12 min en retournant à mi-cuisson, jusqu''à ce qu''ils soient dorés et cuits à cœur.","Pendant ce temps, mélanger les tomates, le concombre, l''oignon rouge, le reste de coriandre, le jus de citron et une pincée de sel pour le kachumber. Incorporer la menthe et une pincée de sel au yaourt pour la raïta.","Réchauffer les pains plats dans une poêle sèche à feu moyen, 1 min par face.","Servir les kebabs sur les pains avec le kachumber et la raïta."]},"it":{"title":"Seekh kebab di agnello in friggitrice ad aria con pane piatto, kachumber e raita alla menta","steps":["Mescolare l''agnello con cipolla grattugiata, aglio, zenzero, peperoncino, metà del coriandolo, garam masala, cumino, chili in polvere e 0,5 cucchiaini di sale. Impastare 1 min finché è appiccicoso.","Con le mani bagnate formare 6 salsicciotti lunghi attorno agli spiedini, o semplicemente dei cilindri.","Cuocere in friggitrice ad aria a 200 °C per 10-12 min, girando a metà, finché sono rosolati e cotti.","Intanto mescolare pomodori, cetriolo, cipolla rossa, il resto del coriandolo, succo di limone e un pizzico di sale per il kachumber. Unire la menta e un pizzico di sale allo yogurt per la raita.","Scaldare i pani piatti in una padella asciutta a fuoco medio, 1 min per lato.","Servire i kebab sui pani con kachumber e raita."]}}'::jsonb),
  ('02e62558-d688-467d-ac0d-e78729da69be'::uuid, '{"fr":{"title":"Mie goreng aux crevettes","steps":["Cuire les nouilles dans l''eau bouillante selon le paquet, égoutter, rincer rapidement et mélanger avec quelques gouttes d''huile.","Mélanger le kecap manis, la sauce soja et le ketchup.","Chauffer la moitié de l''huile dans un wok à feu vif. Brouiller les œufs 1 min jusqu''à ce qu''ils soient juste pris, puis les pousser sur le côté.","Ajouter le reste d''huile, l''ail, l''échalote et le piment et faire sauter 30 s, puis les crevettes 1 à 2 min jusqu''à ce qu''elles deviennent roses.","Ajouter le chou et la carotte et faire sauter 2 min, jusqu''à ce que le chou commence à s''attendrir.","Ajouter les nouilles et la sauce et faire sauter vigoureusement 2 min jusqu''à ce qu''elles soient bien enrobées et un peu collantes. Ajouter les germes de soja et les oignons nouveaux 30 s et servir avec le citron vert."]},"it":{"title":"Mie goreng con gamberi","steps":["Cuocere i noodles in acqua bollente come indicato sulla confezione, scolarli, sciacquarli velocemente e condirli con qualche goccia d''olio.","Mescolare kecap manis, salsa di soia e ketchup.","Scaldare metà dell''olio nel wok a fuoco vivo. Strapazzare le uova 1 min finché sono appena rapprese, poi spingerle da un lato.","Aggiungere il resto dell''olio, aglio, scalogno e peperoncino e saltare 30 s, poi i gamberi per 1-2 min finché diventano rosa.","Unire cavolo e carota e saltare 2 min, finché il cavolo inizia ad appassire.","Aggiungere noodles e salsa e saltare energicamente 2 min finché sono ben conditi e un po'' appiccicosi. Unire germogli di soia e cipollotti per 30 s e servire con il lime."]}}'::jsonb),
  ('c80be323-9ad6-44cc-b065-7c8a50d3cf1e'::uuid, '{"fr":{"title":"Crevettes piri-piri au air fryer, pommes de terre écrasées et salade de tomates","steps":["Cuire les pommes de terre dans l''eau salée frémissante 15 à 18 min jusqu''à ce qu''elles soient tendres.","Pendant ce temps, mixer ou hacher finement les piments et l''ail, puis les mélanger avec le paprika, l''origan, le jus d''un demi-citron, le vinaigre, 1,5 c. à soupe d''huile et une pincée de sel : c''est le piri-piri. En enrober les crevettes avec la moitié.","Cuire les crevettes au air fryer à 200 °C 6 à 7 min en secouant à mi-cuisson, jusqu''à ce qu''elles soient roses et juste fermes.","Mélanger les tomates, l''oignon rouge et la laitue avec 1 c. à café d''huile, un filet de citron et une pincée de sel.","Égoutter les pommes de terre, les écraser grossièrement à la fourchette et les mélanger avec le reste d''huile, le persil et une pincée de sel.","Servir les crevettes sur les pommes de terre, arrosées du reste de piri-piri, avec la salade et des quartiers de citron."]},"it":{"title":"Gamberi piri-piri in friggitrice ad aria con patate schiacciate e insalata di pomodori","steps":["Cuocere le patate in acqua salata a bollore leggero 15-18 min finché sono tenere.","Intanto frullare o tritare finemente peperoncini e aglio, poi mescolarli con paprika, origano, il succo di mezzo limone, aceto, 1,5 cucchiai d''olio e un pizzico di sale: è il piri-piri. Condire i gamberi con metà.","Cuocere i gamberi in friggitrice ad aria a 200 °C per 6-7 min, scuotendo a metà, finché sono rosa e appena sodi.","Condire pomodori, cipolla rossa e lattuga con 1 cucchiaino d''olio, un goccio di limone e un pizzico di sale.","Scolare le patate, schiacciarle grossolanamente con una forchetta e condirle con il resto dell''olio, il prezzemolo e un pizzico di sale.","Servire i gamberi sulle patate, irrorati con il resto del piri-piri, con l''insalata e spicchi di limone."]}}'::jsonb),
  ('241db188-c71f-493f-bdb8-6799bb6b8cb7'::uuid, '{"fr":{"title":"Garides saganaki (crevettes à la tomate et à la feta) et orzo","steps":["Cuire l''orzo dans l''eau bouillante salée selon le paquet, environ 9 min, puis égoutter.","Pendant ce temps, chauffer l''huile dans une grande poêle à feu moyen et faire fondre l''oignon 5 min. Ajouter l''ail et le piment 1 min.","Verser le vin et laisser bouillonner 1 min, puis ajouter les tomates et l''origan et laisser mijoter 8 min jusqu''à ce que la sauce épaississe. Assaisonner.","Enfoncer les crevettes dans la sauce et laisser mijoter 3 à 4 min en les retournant une fois, jusqu''à ce qu''elles soient roses et juste cuites.","Incorporer les épinards à l''orzo égoutté pour qu''ils tombent à la chaleur.","Émietter la feta sur les crevettes, parsemer de persil et servir avec l''orzo."]},"it":{"title":"Garides saganaki (gamberi al pomodoro e feta) con orzo","steps":["Cuocere l''orzo in acqua bollente salata come indicato sulla confezione, circa 9 min, poi scolarlo.","Intanto scaldare l''olio in un''ampia padella a fuoco medio e appassire la cipolla 5 min. Aggiungere aglio e peperoncino per 1 min.","Sfumare con il vino e far sobbollire 1 min, poi unire pomodori e origano e cuocere 8 min finché il sugo si addensa. Regolare di sale.","Adagiare i gamberi nel sugo e cuocere 3-4 min, girandoli una volta, finché sono rosa e appena cotti.","Mescolare gli spinaci all''orzo scolato perché appassiscano con il calore.","Sbriciolare la feta sui gamberi, cospargere di prezzemolo e servire con l''orzo."]}}'::jsonb),
  ('3c207655-1bf3-4635-8387-61f1ffd51f09'::uuid, '{"fr":{"title":"Yaki udon aux crevettes, chou et champignons","steps":["Mettre les udon dans un saladier, couvrir d''eau tout juste bouillante 1 min pour les détacher, puis égoutter.","Mélanger la sauce soja, la sauce huître, le mirin et l''huile de sésame.","Chauffer l''huile dans un wok ou une grande poêle à feu vif. Faire sauter les crevettes 1 à 2 min jusqu''à ce qu''elles soient roses, puis les retirer.","Ajouter l''ail, l''oignon et la carotte et faire sauter 1 min, puis le chou et les champignons 2 à 3 min, jusqu''à ce que le chou soit tombé mais encore croquant.","Ajouter les udon, la sauce et les oignons nouveaux et faire sauter 1 à 2 min jusqu''à ce que les nouilles soient chaudes et brillantes.","Remettre les crevettes, faire sauter 30 s et servir avec les graines de sésame."]},"it":{"title":"Yaki udon con gamberi, cavolo e funghi","steps":["Mettere gli udon in una ciotola, coprirli con acqua appena bollita per 1 min per staccarli, poi scolarli.","Mescolare salsa di soia, salsa d''ostriche, mirin e olio di sesamo.","Scaldare l''olio nel wok o in un''ampia padella a fuoco vivo. Saltare i gamberi 1-2 min finché sono rosa, poi toglierli.","Aggiungere aglio, cipolla e carota e saltare 1 min, poi cavolo e funghi per 2-3 min, finché il cavolo è appassito ma ancora croccante.","Unire udon, salsa e cipollotti e saltare 1-2 min finché i noodles sono caldi e lucidi.","Rimettere i gamberi, saltare 30 s e servire con i semi di sesamo."]}}'::jsonb),
  ('79e23166-0c39-45a8-87a9-14327984483e'::uuid, '{"fr":{"title":"Crevettes kung pao et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau 12 min à feu doux, puis le laisser reposer hors du feu.","Mélanger les crevettes avec 1 c. à café de fécule et le vin de riz. Mélanger la sauce soja, le vinaigre noir, le sucre, le reste de fécule et 3 c. à soupe d''eau pour la sauce.","Chauffer l''huile dans un wok à feu moyen et faire revenir les piments et le poivre du Sichuan 30 s, jusqu''à ce qu''ils embaument et foncent sans brûler.","Passer à feu vif, ajouter les crevettes et les faire sauter 1 à 2 min jusqu''à ce qu''elles deviennent roses.","Ajouter l''ail, le gingembre, le poivron et le céleri et faire sauter 2 min.","Remuer la sauce, la verser et faire sauter 1 min jusqu''à ce qu''elle soit brillante et épaisse. Ajouter les oignons nouveaux et les cacahuètes et servir avec le riz."]},"it":{"title":"Gamberi kung pao con riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Condire i gamberi con 1 cucchiaino di amido e il vino di riso. Mescolare salsa di soia, aceto nero, zucchero, il resto dell''amido e 3 cucchiai d''acqua per la salsa.","Scaldare l''olio nel wok a fuoco medio e soffriggere peperoncini e pepe di Sichuan 30 s, finché profumano e scuriscono senza bruciare.","Alzare a fuoco vivo, unire i gamberi e saltarli 1-2 min finché diventano rosa.","Aggiungere aglio, zenzero, peperone e sedano e saltare 2 min.","Mescolare la salsa, versarla e saltare 1 min finché è lucida e densa. Unire cipollotti e arachidi e servire con il riso."]}}'::jsonb),
  ('4c3ac09a-6ddc-4a37-b664-f6952cc1dddf'::uuid, '{"fr":{"title":"Calamars sel et poivre au air fryer, nouilles à l''ail et pak choï","steps":["Bien sécher les calamars. Mélanger la fécule, le poivre du Sichuan, le poivre blanc et le sel et y enrober les calamars en secouant l''excédent.","Disposer les calamars en une couche dans le panier du air fryer, vaporiser ou badigeonner de 2 c. à café d''huile et cuire à 200 °C 8 à 10 min en secouant à mi-cuisson, jusqu''à ce qu''ils soient croustillants et dorés.","Pendant ce temps, cuire les nouilles dans l''eau bouillante selon le paquet en ajoutant le pak choï la dernière minute, puis égoutter.","Chauffer le reste d''huile dans un wok à feu moyen-vif et faire revenir l''ail, le piment et la moitié des oignons nouveaux 1 min jusqu''à ce qu''ils embaument.","Ajouter les nouilles, le pak choï, la sauce soja et la sauce huître et faire sauter 1 à 2 min jusqu''à ce que ce soit chaud et bien enrobé.","Faire sauter les calamars 20 s dans le wok avec le reste des oignons nouveaux, ou les parsemer dessus, et servir aussitôt avec le citron."]},"it":{"title":"Calamari sale e pepe in friggitrice ad aria con noodles all''aglio e pak choi","steps":["Asciugare molto bene i calamari. Mescolare amido, pepe di Sichuan, pepe bianco e sale e passarvi i calamari, scuotendo l''eccesso.","Disporre i calamari in un solo strato nel cestello, spruzzarli o spennellarli con 2 cucchiaini d''olio e cuocere in friggitrice ad aria a 200 °C per 8-10 min, scuotendo a metà, finché sono croccanti e dorati.","Intanto cuocere i noodles in acqua bollente come indicato sulla confezione, aggiungendo il pak choi nell''ultimo minuto, poi scolare.","Scaldare il resto dell''olio nel wok a fuoco medio-alto e soffriggere aglio, peperoncino e metà dei cipollotti 1 min finché profumano.","Aggiungere noodles, pak choi, salsa di soia e salsa d''ostriche e saltare 1-2 min finché è tutto caldo e condito.","Saltare i calamari nel wok con il resto dei cipollotti per 20 s, o cospargerli sopra, e servire subito con il limone."]}}'::jsonb),
  ('2c55825a-ebe6-49d8-b575-a44e3f3a2337'::uuid, '{"fr":{"title":"Linguine aux moules, courgette et vin blanc","steps":["Porter à ébullition une grande casserole d''eau légèrement salée pour les pâtes. Jeter les moules qui restent ouvertes quand on les tapote.","Chauffer 1 c. à soupe d''huile dans une grande sauteuse avec couvercle à feu moyen et faire revenir 1 gousse d''ail 30 s. Ajouter les moules et le vin, couvrir et cuire à feu vif 3 à 4 min en secouant, jusqu''à ce qu''elles s''ouvrent.","Verser les moules dans une passoire posée sur un saladier pour recueillir le jus. Jeter celles restées fermées, en décortiquer environ les deux tiers et filtrer le jus au tamis fin.","Cuire les linguine 2 min de moins que le temps indiqué.","Pendant ce temps, essuyer la sauteuse, chauffer le reste d''huile et faire revenir la courgette avec le reste d''ail et le piment à feu moyen-vif 4 à 5 min jusqu''à ce qu''elle soit légèrement dorée.","Ajouter le jus des moules filtré et les linguine égouttées et faire sauter à feu vif 2 min en ajoutant un peu d''eau de cuisson, jusqu''à ce que les pâtes soient al dente et bien enrobées.","Ajouter toutes les moules et le persil, faire sauter 30 s pour réchauffer, poivrer et servir."]},"it":{"title":"Linguine con cozze, zucchine e vino bianco","steps":["Portare a ebollizione una pentola d''acqua leggermente salata per la pasta. Scartare le cozze che restano aperte se picchiettate.","Scaldare 1 cucchiaio d''olio in un''ampia padella con coperchio a fuoco medio e soffriggere 1 spicchio d''aglio 30 s. Aggiungere cozze e vino, coprire e cuocere a fuoco vivo 3-4 min, scuotendo la padella, finché si aprono.","Versare le cozze in uno scolapasta sopra una ciotola per raccogliere il liquido. Scartare quelle rimaste chiuse, sgusciarne circa due terzi e filtrare il liquido con un colino fine.","Cuocere le linguine 2 min meno del tempo indicato.","Intanto pulire la padella, scaldare il resto dell''olio e rosolare le zucchine con il resto dell''aglio e il peperoncino a fuoco medio-alto 4-5 min finché sono leggermente dorate.","Aggiungere il liquido filtrato delle cozze e le linguine scolate e saltare a fuoco vivo 2 min, aggiungendo un po'' d''acqua di cottura, finché la pasta è al dente e ben condita.","Unire tutte le cozze e il prezzemolo, saltare 30 s per scaldarle, pepare e servire."]}}'::jsonb),
  ('fe97a411-d8af-458a-8532-f3fab76ba358'::uuid, '{"fr":{"title":"Calamars aux pois chiches, chorizo et paprika fumé","steps":["Chauffer l''huile dans une grande sauteuse à feu moyen et faire revenir le chorizo 2 min jusqu''à ce qu''il rende son huile rouge.","Ajouter l''oignon et le poivron et les faire fondre 6 min, puis l''ail 1 min.","Incorporer le paprika, puis aussitôt la tomate râpée et le vin, et laisser mijoter 4 min jusqu''à consistance de confiture.","Ajouter les pois chiches et 100 ml d''eau et laisser mijoter 4 min.","Monter le feu, ajouter les calamars et cuire 2 min, juste jusqu''à ce qu''ils deviennent opaques, puis incorporer les épinards jusqu''à ce qu''ils tombent.","Assaisonner, ajouter le jus de citron et le persil et servir dans des bols."]},"it":{"title":"Calamari con ceci, chorizo e paprika affumicata","steps":["Scaldare l''olio in un''ampia padella a fuoco medio e rosolare il chorizo 2 min finché rilascia il suo olio rosso.","Aggiungere cipolla e peperone e appassirli 6 min, poi l''aglio per 1 min.","Unire la paprika, poi subito il pomodoro grattugiato e il vino, e cuocere 4 min finché è denso come una marmellata.","Aggiungere i ceci e 100 ml d''acqua e cuocere 4 min.","Alzare la fiamma, unire i calamari e cuocere 2 min, giusto finché diventano opachi, poi aggiungere gli spinaci finché appassiscono.","Regolare di sale, aggiungere succo di limone e prezzemolo e servire in ciotole."]}}'::jsonb),
  ('b691ac47-1e7f-4fcc-a0c8-e540b5d03fe1'::uuid, '{"fr":{"title":"Ojingeo bokkeum (calamars sautés épicés à la coréenne) et riz","steps":["Rincer le riz et le cuire à couvert dans 195 ml d''eau 12 min à feu doux, puis le laisser reposer hors du feu.","Mélanger le gochugaru, le gochujang, la sauce soja, le sucre, l''ail, le gingembre et 1 c. à soupe d''eau en pâte.","Chauffer l''huile dans un wok à feu vif et faire sauter l''oignon, la carotte et le chou 2 à 3 min, jusqu''à ce qu''ils commencent à s''attendrir.","Ajouter les calamars et la pâte et faire sauter 2 à 3 min, juste jusqu''à ce que les calamars deviennent opaques et s''enroulent.","Ajouter le piment et les oignons nouveaux et faire sauter 30 s, puis retirer du feu et incorporer l''huile de sésame.","Servir sur le riz avec les graines de sésame."]},"it":{"title":"Ojingeo bokkeum (calamari saltati piccanti alla coreana) con riso","steps":["Sciacquare il riso e cuocerlo coperto in 195 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Mescolare gochugaru, gochujang, salsa di soia, zucchero, aglio, zenzero e 1 cucchiaio d''acqua fino a ottenere una pasta.","Scaldare l''olio nel wok a fuoco vivo e saltare cipolla, carota e cavolo 2-3 min, finché iniziano ad ammorbidirsi.","Unire i calamari e la pasta e saltare 2-3 min, giusto finché i calamari diventano opachi e si arricciano.","Aggiungere peperoncino e cipollotti e saltare 30 s, poi togliere dal fuoco e unire l''olio di sesamo.","Servire sul riso con i semi di sesamo."]}}'::jsonb),
  ('022f20e9-59c3-4056-8aa0-eb4976b7dab3'::uuid, '{"fr":{"title":"Saumon à la chermoula au air fryer, couscous et poivrons","steps":["Préparer la chermoula : mélanger la coriandre, le persil, l''ail, le cumin, le paprika, le piment, le zeste et le jus de citron, 1 c. à soupe d''huile et une bonne pincée de sel.","Mélanger les poivrons et l''oignon avec le reste d''huile et une pincée de sel, puis les cuire au air fryer à 200 °C 12 min en secouant une fois, jusqu''à ce qu''ils soient tendres et grillés sur les bords.","Pousser les légumes sur les côtés, poser le saumon côté peau au centre et le napper d''un tiers de la chermoula.","Cuire au air fryer à 200 °C 8 min, jusqu''à ce que le saumon s''effeuille tout en restant juste rosé à cœur.","Pendant ce temps, verser le bouillon bouillant sur le couscous dans un saladier, couvrir et laisser gonfler 5 min, puis égrener à la fourchette.","Incorporer les poivrons et l''oignon au couscous, poser le saumon dessus et napper du reste de chermoula. Servir avec des quartiers de citron."]},"it":{"title":"Salmone alla chermoula in friggitrice ad aria con cuscus e peperoni","steps":["Preparare la chermoula: mescolare coriandolo, prezzemolo, aglio, cumino, paprica, peperoncino, scorza e succo di limone, 1 cucchiaio d''olio e un buon pizzico di sale.","Condire peperoni e cipolla con il resto dell''olio e un pizzico di sale e cuocerli in friggitrice ad aria a 200 °C per 12 min, scuotendo una volta, finché sono morbidi e abbrustoliti ai bordi.","Spostare le verdure ai lati, adagiare il salmone al centro con la pelle in basso e spalmarvi un terzo della chermoula.","Cuocere in friggitrice ad aria a 200 °C per 8 min, finché il salmone si sfalda ma resta appena rosato al centro.","Intanto versare il brodo bollente sul cuscus in una ciotola, coprire e lasciar riposare 5 min, poi sgranarlo con una forchetta.","Unire peperoni e cipolla al cuscus, adagiarvi sopra il salmone e condire con il resto della chermoula. Servire con spicchi di limone."]}}'::jsonb),
  ('59c18924-ccc7-497f-a5c4-9e94989bf0d3'::uuid, '{"fr":{"title":"Poke bowl au saumon, edamame et concombre","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert dans 230 ml d''eau 12 min à feu doux. Le laisser reposer 5 min hors du feu, couvercle fermé.","Verser de l''eau bouillante sur les edamame, laisser 3 min et égoutter.","Mélanger la sauce soja, l''huile de sésame, le vinaigre et le gingembre dans un bol.","Ajouter le saumon, l''oignon émincé et la moitié de l''oignon nouveau et mélanger délicatement. Réserver au frais pendant que le riz repose, pas plus de 15 min.","Répartir le riz tiède dans deux bols. Garnir du saumon et de son jus, des edamame, du concombre et de l''avocat.","Finir avec le reste d''oignon nouveau et les graines de sésame, et déguster aussitôt."]},"it":{"title":"Poke bowl di salmone con edamame e cetriolo","steps":["Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto in 230 ml d''acqua per 12 min a fuoco basso. Lasciarlo riposare 5 min fuori dal fuoco, con il coperchio.","Versare acqua bollente sugli edamame, lasciarli 3 min e scolarli.","Mescolare salsa di soia, olio di sesamo, aceto e zenzero in una ciotola.","Aggiungere il salmone, la cipolla affettata e metà del cipollotto e mescolare delicatamente. Tenere in frigo mentre il riso riposa, non più di 15 min.","Dividere il riso tiepido in due ciotole. Completare con il salmone e il suo sugo, gli edamame, il cetriolo e l''avocado.","Finire con il resto del cipollotto e il sesamo e mangiare subito."]}}'::jsonb),
  ('bd2199fd-6c52-4d10-a4ca-386b688186d8'::uuid, '{"fr":{"title":"Curry vert thaï au saumon, riz jasmin et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 230 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Chauffer l''huile dans une sauteuse et faire revenir la pâte de curry 1 min en remuant, jusqu''à ce qu''elle embaume.","Ajouter le lait de coco, le bouillon, la sauce de poisson, le sucre et les feuilles de combava, et porter à frémissement.","Ajouter les haricots verts et le poivron et laisser frémir 4 min, jusqu''à ce qu''ils soient juste tendres.","Glisser le saumon, couvrir et laisser frémir doucement 5 à 6 min, sans trop remuer, jusqu''à ce que les morceaux soient opaques.","Assaisonner avec le jus de citron vert, un peu plus de sauce de poisson si besoin, parsemer de basilic thaï et servir avec le riz."]},"it":{"title":"Curry verde thai di salmone con riso jasmine e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 230 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare l''olio in una padella profonda e soffriggere la pasta di curry per 1 min mescolando, finché profuma.","Unire latte di cocco, brodo, salsa di pesce, zucchero e foglie di lime kaffir e portare a sobbollire.","Aggiungere fagiolini e peperone e sobbollire 4 min, finché sono appena teneri.","Unire il salmone, coprire e sobbollire piano 5-6 min, mescolando poco, finché i pezzi sono opachi.","Insaporire con il succo di lime e, se serve, altra salsa di pesce, cospargere di basilico thai e servire con il riso."]}}'::jsonb),
  ('58d8795f-34d0-4e1d-b21e-ffda56e65731'::uuid, '{"fr":{"title":"Saumon tandoori au air fryer, riz au cumin et kachumber","steps":["Rincer le riz. Faire fondre le beurre dans une casserole, faire grésiller le cumin 30 s, ajouter le riz et 230 ml d''eau avec une pincée de sel, couvrir et cuire 12 min à feu doux. Laisser reposer 5 min hors du feu.","Mélanger le yaourt, le paprika, le piment en poudre, le garam masala, le curcuma, l''ail, le gingembre, la moitié du jus de citron et une bonne pincée de sel.","Enrober généreusement le saumon du yaourt épicé.","Cuire le saumon au air fryer sur une feuille de papier cuisson à 200 °C 9 min, jusqu''à ce qu''il soit grillé sur les bords et juste cuit à cœur.","Pendant ce temps, mélanger les tomates, le concombre, l''oignon et la coriandre avec le reste du jus de citron et une pincée de sel pour le kachumber.","Égrener le riz à la fourchette et le servir avec le saumon et le kachumber."]},"it":{"title":"Salmone tandoori in friggitrice ad aria con riso al cumino e kachumber","steps":["Sciacquare il riso. Sciogliere il burro in una casseruola, far sfrigolare i semi di cumino 30 s, unire il riso e 230 ml d''acqua con un pizzico di sale, coprire e cuocere 12 min a fuoco basso. Lasciar riposare 5 min fuori dal fuoco.","Mescolare yogurt, paprica, peperoncino in polvere, garam masala, curcuma, aglio, zenzero, metà del succo di limone e un buon pizzico di sale.","Ricoprire bene il salmone con lo yogurt speziato.","Cuocere il salmone in friggitrice ad aria su un foglio di carta forno a 200 °C per 9 min, finché è abbrustolito ai bordi e appena cotto al centro.","Intanto, per il kachumber, condire pomodori, cetriolo, cipolla e coriandolo con il resto del succo di limone e un pizzico di sale.","Sgranare il riso con una forchetta e servirlo con il salmone e il kachumber."]}}'::jsonb),
  ('f708ce15-5178-43bc-b7ee-702b77e3e205'::uuid, '{"fr":{"title":"Saumon citron-origan, orzo, épinards et tomates","steps":["Assaisonner le saumon de sel, de poivre, du zeste de citron et de la moitié de l''origan.","Chauffer l''huile dans une grande sauteuse avec couvercle et saisir le saumon 2 min de chaque côté. Le réserver sur une assiette.","Faire fondre l''oignon dans la même sauteuse 3 min, ajouter l''ail, l''orzo et le reste de l''origan et remuer 1 min.","Verser le bouillon et laisser frémir 8 min en remuant souvent pour que l''orzo n''attache pas.","Ajouter les tomates, poser le saumon dessus, couvrir et cuire 6 min à feu doux, jusqu''à ce que l''orzo soit tendre et que le saumon s''effeuille.","Retirer le saumon, incorporer les épinards et le jus de citron à l''orzo jusqu''à ce que les feuilles tombent, puis servir avec le saumon dessus et l''aneth."]},"it":{"title":"Salmone al limone e origano con orzo, spinaci e pomodorini","steps":["Condire il salmone con sale, pepe, la scorza di limone e metà dell''origano.","Scaldare l''olio in un''ampia padella con coperchio e rosolare il salmone 2 min per lato. Trasferirlo su un piatto.","Appassire la cipolla nella stessa padella per 3 min, unire aglio, orzo e il resto dell''origano e mescolare 1 min.","Versare il brodo e sobbollire 8 min, mescolando spesso perché l''orzo non si attacchi.","Unire i pomodorini, adagiare sopra il salmone, coprire e cuocere 6 min a fuoco basso, finché l''orzo è tenero e il salmone si sfalda.","Togliere il salmone, mescolare spinaci e succo di limone nell''orzo finché le foglie appassiscono, poi servire con il salmone sopra e l''aneto."]}}'::jsonb),
  ('6549101f-d482-4c79-a6a7-9afde73166f9'::uuid, '{"fr":{"title":"Burrito bowl au saumon au air fryer, quinoa, haricots noirs et pico de gallo","steps":["Cuire la quinoa à couvert dans 280 ml d''eau salée 15 min, puis la laisser 5 min hors du feu et l''égrener.","Frotter le saumon avec l''huile, le piment en poudre, le cumin, le paprika et une pincée de sel.","Cuire le saumon au air fryer à 200 °C 8 min, jusqu''à ce qu''il s''effeuille.","Pendant ce temps, réchauffer les haricots noirs et le maïs dans une petite casserole avec un filet d''eau et une pincée de sel, 3 min.","Pour le pico de gallo, mélanger les tomates, l''oignon, le piment, la coriandre et la moitié du jus de citron vert avec une pincée de sel.","Mélanger la quinoa avec le reste du jus de citron vert. Composer les bols avec la salade, la quinoa, les haricots et le maïs, le saumon effeuillé et le pico de gallo."]},"it":{"title":"Burrito bowl di salmone in friggitrice ad aria con quinoa, fagioli neri e pico de gallo","steps":["Cuocere la quinoa coperta in 280 ml d''acqua salata per 15 min, poi lasciarla 5 min fuori dal fuoco e sgranarla.","Massaggiare il salmone con olio, peperoncino in polvere, cumino, paprica e un pizzico di sale.","Cuocere il salmone in friggitrice ad aria a 200 °C per 8 min, finché si sfalda.","Intanto scaldare fagioli neri e mais in un pentolino con un goccio d''acqua e un pizzico di sale, 3 min.","Per il pico de gallo, mescolare pomodori, cipolla, peperoncino, coriandolo e metà del succo di lime con un pizzico di sale.","Condire la quinoa con il resto del succo di lime. Comporre le ciotole con lattuga, quinoa, fagioli e mais, salmone a scaglie e pico de gallo."]}}'::jsonb),
  ('8cd2d154-7c73-419f-bd7a-7e5867400f4e'::uuid, '{"fr":{"title":"Saumon sauce aux haricots noirs, nouilles et brocoli","steps":["Cuire les nouilles dans l''eau bouillante selon le paquet en ajoutant le brocoli pour les 2 dernières minutes. Égoutter.","Mélanger le vin de riz, la sauce soja, le sucre et la fécule avec 80 ml d''eau.","Chauffer la moitié de l''huile dans un wok à feu vif, dorer le saumon 2 min en le retournant délicatement, puis le retirer.","Ajouter le reste d''huile et faire sauter les haricots noirs, l''ail, le gingembre et le blanc des oignons nouveaux 30 s, puis le poivron 2 min.","Verser la sauce et laisser bouillonner jusqu''à ce qu''elle soit brillante, environ 1 min. Remettre le saumon et le vert des oignons nouveaux et remuer délicatement 1 à 2 min, jusqu''à ce que le poisson soit juste cuit.","Servir sur les nouilles et le brocoli."]},"it":{"title":"Salmone in salsa di fagioli neri fermentati con noodles e broccoli","steps":["Cuocere i noodles in acqua bollente come indicato sulla confezione, aggiungendo i broccoli negli ultimi 2 min. Scolare.","Mescolare vino di riso, salsa di soia, zucchero e amido con 80 ml d''acqua.","Scaldare metà dell''olio nel wok a fuoco vivo, rosolare il salmone 2 min girandolo con delicatezza e toglierlo.","Aggiungere il resto dell''olio e saltare fagioli neri, aglio, zenzero e la parte bianca dei cipollotti per 30 s, poi il peperone per 2 min.","Versare la salsa e lasciarla bollire finché è lucida, circa 1 min. Rimettere il salmone e la parte verde dei cipollotti e girare piano 1-2 min, finché il pesce è appena cotto.","Servire sopra i noodles e i broccoli."]}}'::jsonb),
  ('33a89e95-3c35-4277-a5b4-880b975634ef'::uuid, '{"fr":{"title":"Sinigang na isda (soupe aigre au tamarin et merlu) et riz","steps":["Rincer le riz et le cuire à couvert dans 240 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Porter 900 ml d''eau à ébullition avec l''oignon et les tomates et laisser frémir 5 min, jusqu''à ce que les tomates ramollissent.","Ajouter le daikon et l''aubergine et laisser frémir 5 min.","Incorporer la pâte de tamarin et la sauce de poisson, puis ajouter les haricots verts et le piment et laisser frémir 3 min. Goûter : le bouillon doit être franchement acide et salé.","Glisser le merlu et le pocher doucement 4 à 5 min, sans remuer, jusqu''à ce qu''il s''effeuille.","Ajouter les épinards, les laisser tomber 1 min et servir la soupe dans des bols avec le riz à côté."]},"it":{"title":"Sinigang na isda (zuppa acidula al tamarindo con nasello) e riso","steps":["Sciacquare il riso e cuocerlo coperto in 240 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Portare a bollore 900 ml d''acqua con cipolla e pomodori e sobbollire 5 min, finché i pomodori si ammorbidiscono.","Aggiungere daikon e melanzana e sobbollire 5 min.","Unire pasta di tamarindo e salsa di pesce, poi aggiungere fagiolini e peperoncino e sobbollire 3 min. Assaggiare: il brodo deve essere decisamente acidulo e sapido.","Unire il nasello e cuocerlo piano 4-5 min, senza mescolare, finché si sfalda.","Aggiungere gli spinaci, lasciarli appassire 1 min e servire la zuppa nelle ciotole con il riso a parte."]}}'::jsonb),
  ('4ef6481f-d6d1-443e-923f-912d65ebac62'::uuid, '{"fr":{"title":"Pescado sudado (cabillaud à l''étouffée, tomate et ají) et riz","steps":["Rincer le riz et le cuire à couvert dans 240 ml d''eau salée 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Chauffer l''huile dans une grande sauteuse avec couvercle et faire revenir l''ail, l''ají amarillo et le cumin 1 min.","Disposer la moitié de l''oignon, du poivron et de la tomate, poser le cabillaud salé dessus et le recouvrir du reste des légumes.","Verser le fumet et le vinaigre, parsemer de la moitié de la coriandre, couvrir hermétiquement et cuire à l''étouffée 10 min à feu moyen-doux, jusqu''à ce que le poisson s''effeuille.","Goûter le jus et rectifier le sel, puis servir le poisson et les légumes avec leur jus sur le riz, avec le reste de la coriandre et des quartiers de citron vert."]},"it":{"title":"Pescado sudado (merluzzo stufato al pomodoro e ají) con riso","steps":["Sciacquare il riso e cuocerlo coperto in 240 ml d''acqua salata per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare l''olio in un''ampia padella con coperchio e soffriggere aglio, ají amarillo e cumino per 1 min.","Disporre metà della cipolla, del peperone e del pomodoro, adagiare sopra il merluzzo salato e ricoprirlo con il resto delle verdure.","Versare il brodo e l''aceto, cospargere con metà del coriandolo, coprire bene e cuocere al vapore 10 min a fuoco medio-basso, finché il pesce si sfalda.","Assaggiare il sugo e regolare di sale, poi servire pesce e verdure con il loro brodo sul riso, con il resto del coriandolo e spicchi di lime."]}}'::jsonb),
  ('ba8a84c5-00bf-4b05-93dc-7cadaecd18c0'::uuid, '{"fr":{"title":"Bar au air fryer, nam jim, riz jasmin et salade de concombre","steps":["Rincer le riz et le cuire à couvert dans 240 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Pour le nam jim, piler ou hacher finement l''ail, 1,5 piment et les tiges de coriandre, puis ajouter le jus de citron vert, la sauce de poisson et 2 c. à café de sucre en remuant jusqu''à dissolution.","Pour la salade, mélanger le concombre et l''échalote avec le vinaigre, le reste du sucre, le dernier demi-piment émincé et une pincée de sel.","Sécher le bar, le frotter d''huile et de sel, puis le cuire au air fryer côté peau vers le haut à 200 °C 7 à 8 min, jusqu''à ce que la peau soit croustillante et la chair s''effeuille.","Servir le poisson sur le riz nappé de nam jim, avec la salade de concombre à côté, parsemé de feuilles de coriandre."]},"it":{"title":"Branzino in friggitrice ad aria con nam jim, riso jasmine e insalata di cetrioli","steps":["Sciacquare il riso e cuocerlo coperto in 240 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Per il nam jim, pestare o tritare finemente aglio, 1,5 peperoncini e i gambi di coriandolo, poi unire succo di lime, salsa di pesce e 2 cucchiaini di zucchero mescolando finché si scioglie.","Per l''insalata, condire cetriolo e scalogno con l''aceto, il resto dello zucchero, l''ultimo mezzo peperoncino a fettine e un pizzico di sale.","Asciugare il branzino, ungerlo con l''olio e salarlo, poi cuocerlo in friggitrice ad aria con la pelle in alto a 200 °C per 7-8 min, finché la pelle è croccante e la carne si sfalda.","Servire il pesce sul riso condito con il nam jim, con l''insalata di cetrioli a parte, e cospargere di foglie di coriandolo."]}}'::jsonb),
  ('bb3fc801-6cbe-481c-b05d-fb04dd359d6b'::uuid, '{"fr":{"title":"Chả cá Lã Vọng (merlu au curcuma, aneth et vermicelles de riz)","steps":["Mélanger le merlu avec le curcuma, le gingembre, la moitié de l''ail, 1 c. à soupe de sauce de poisson, 1 c. à café de sucre et la fécule.","Pour la sauce, mélanger le reste de sauce de poisson et de sucre avec le jus de citron vert, 4 c. à soupe d''eau, le reste de l''ail et le piment.","Cuire les vermicelles dans l''eau bouillante selon le paquet, les rincer à l''eau froide et bien égoutter.","Chauffer l''huile dans une poêle à feu moyen-vif et faire dorer le poisson 2 à 3 min de chaque côté, jusqu''à ce qu''il soit juste cuit.","Ajouter les oignons nouveaux et l''aneth dans la poêle et les mélanger au poisson 30 s, juste le temps qu''ils tombent.","Servir le poisson et les herbes sur les vermicelles avec la salade, les cacahuètes et la coriandre, et la sauce à verser dessus."]},"it":{"title":"Chả cá Lã Vọng (nasello alla curcuma con aneto e vermicelli di riso)","steps":["Condire il nasello con curcuma, zenzero, metà dell''aglio, 1 cucchiaio di salsa di pesce, 1 cucchiaino di zucchero e l''amido.","Per la salsa, mescolare il resto della salsa di pesce e dello zucchero con il succo di lime, 4 cucchiai d''acqua, il resto dell''aglio e il peperoncino.","Cuocere i vermicelli in acqua bollente come indicato sulla confezione, sciacquarli sotto l''acqua fredda e scolarli bene.","Scaldare l''olio in padella a fuoco medio-alto e rosolare il pesce 2-3 min per lato, finché è dorato e appena cotto.","Aggiungere cipollotti e aneto nella padella e girarli con il pesce per 30 s, giusto finché appassiscono.","Servire pesce ed erbe sui vermicelli con lattuga, arachidi e coriandolo, e la salsa da versare sopra."]}}'::jsonb),
  ('da238c68-2dc8-45fe-8dc5-e6e86a857332'::uuid, '{"fr":{"title":"Bar à l''acqua pazza, tomates cerises, fenouil et pain croustillant","steps":["Chauffer l''huile, l''ail et le piment dans une grande sauteuse avec couvercle à feu moyen 1 min, sans laisser colorer l''ail.","Ajouter le fenouil et le faire fondre 4 min, puis les tomates 2 min, jusqu''à ce qu''elles commencent à s''affaisser.","Verser le vin et 150 ml d''eau, saler et laisser frémir 3 min.","Déposer les filets salés côté peau, les arroser d''un peu de bouillon, couvrir et pocher à feu doux 5 à 6 min, jusqu''à ce que la chair soit opaque.","Pendant ce temps, faire griller le pain.","Servir le poisson dans des assiettes creuses avec les tomates et le bouillon, parsemer de persil et saucer avec le pain."]},"it":{"title":"Branzino all''acqua pazza con pomodorini, finocchio e pane croccante","steps":["Scaldare olio, aglio e peperoncino in un''ampia padella con coperchio a fuoco medio per 1 min, senza far colorire l''aglio.","Aggiungere il finocchio e appassirlo 4 min, poi i pomodorini per 2 min, finché iniziano ad afflosciarsi.","Versare il vino e 150 ml d''acqua, salare e sobbollire 3 min.","Adagiare i filetti salati con la pelle in basso, irrorarli con un po'' di brodo, coprire e cuocere a fuoco basso 5-6 min, finché la carne è opaca.","Intanto tostare il pane.","Servire il pesce in piatti fondi con pomodorini e brodo, cospargere di prezzemolo e fare la scarpetta con il pane."]}}'::jsonb),
  ('17a428e4-0b49-4531-8331-a55c82dad034'::uuid, '{"fr":{"title":"Samke harra au air fryer (cabillaud épicé au tahini) et boulgour","steps":["Cuire le boulgour à couvert dans 300 ml d''eau salée 12 min, puis le laisser gonfler 5 min hors du feu.","Frotter le cabillaud avec 1 c. à café d''huile, le paprika, le cumin et du sel, puis le cuire au air fryer à 200 °C 9 à 10 min, jusqu''à ce qu''il s''effeuille.","Pendant ce temps, faire fondre l''oignon dans le reste d''huile à la poêle 6 min, ajouter l''ail, le piment et les noix et cuire encore 2 min, puis incorporer presque toute la coriandre.","Fouetter le tahini, le yaourt et les trois quarts du jus de citron avec 3 à 4 c. à soupe d''eau et une pincée de sel pour obtenir une sauce nappante.","Mélanger la tomate et le concombre avec le reste du jus de citron et une pincée de sel.","Servir le cabillaud sur le boulgour, napper de sauce au tahini, couvrir du mélange d''oignons épicés et finir avec le reste de la coriandre, avec la salade à côté."]},"it":{"title":"Samke harra in friggitrice ad aria (merluzzo piccante al tahini) con bulgur","steps":["Cuocere il bulgur coperto in 300 ml d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Massaggiare il merluzzo con 1 cucchiaino d''olio, paprica, cumino e sale, e cuocerlo in friggitrice ad aria a 200 °C per 9-10 min, finché si sfalda.","Intanto appassire la cipolla nel resto dell''olio in padella per 6 min, unire aglio, peperoncino e noci e cuocere altri 2 min, poi aggiungere quasi tutto il coriandolo.","Sbattere tahini, yogurt e tre quarti del succo di limone con 3-4 cucchiai d''acqua e un pizzico di sale fino a ottenere una salsa fluida.","Condire pomodoro e cetriolo con il resto del succo di limone e un pizzico di sale.","Servire il merluzzo sul bulgur, versare la salsa al tahini, coprire con il misto di cipolla piccante e finire con il resto del coriandolo, con l''insalata a parte."]}}'::jsonb),
  ('7b7783ab-776d-4480-a787-1c97ecf7dc6b'::uuid, '{"fr":{"title":"Poisson Amritsari au air fryer, galettes, yaourt à la menthe et salade d''oignon","steps":["Mélanger la farine de pois chiche, le piment, l''ajowan, le curcuma, le garam masala, le gingembre, l''ail, 1 c. à soupe de jus de citron, une bonne pincée de sel et 2 à 3 c. à soupe d''eau pour obtenir une pâte épaisse.","Enrober le poisson de cette pâte, le poser dans le panier huilé du air fryer et le badigeonner d''huile.","Cuire au air fryer à 200 °C 10 min en retournant à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant.","Pendant ce temps, mélanger le yaourt avec la menthe, la coriandre, le piment vert et une pincée de sel.","Mélanger l''oignon, le concombre et la tomate avec le reste du jus de citron et une pincée de sel.","Réchauffer les galettes 30 s de chaque côté dans une poêle sèche.","Saupoudrer le poisson de chaat masala et le servir dans les galettes avec la salade d''oignon et le yaourt à la menthe."]},"it":{"title":"Pesce Amritsari in friggitrice ad aria con piadine, yogurt alla menta e insalata di cipolla","steps":["Mescolare farina di ceci, peperoncino, ajwain, curcuma, garam masala, zenzero, aglio, 1 cucchiaio di succo di limone, un buon pizzico di sale e 2-3 cucchiai d''acqua fino a ottenere una pastella densa.","Ricoprire il pesce con la pastella, disporlo nel cestello unto della friggitrice ad aria e spennellarlo d''olio.","Cuocere in friggitrice ad aria a 200 °C per 10 min, girando a metà, finché è dorato e croccante.","Intanto mescolare lo yogurt con menta, coriandolo, peperoncino verde e un pizzico di sale.","Condire cipolla, cetriolo e pomodoro con il resto del succo di limone e un pizzico di sale.","Scaldare le piadine 30 s per lato in una padella asciutta.","Cospargere il pesce di chaat masala e servirlo nelle piadine con l''insalata di cipolla e lo yogurt alla menta."]}}'::jsonb),
  ('c40a37d3-7131-4565-8b3d-1566d266554b'::uuid, '{"fr":{"title":"Thon snacké, soba froides, edamame et concombre","steps":["Cuire les soba dans l''eau bouillante selon le paquet en ajoutant les edamame pour les 3 dernières minutes. Rincer à l''eau froide en frottant les nouilles pour retirer l''amidon, et bien égoutter.","Fouetter la sauce soja, le vinaigre, le mirin, l''huile de sésame et le gingembre.","Mélanger les nouilles, les edamame, le concombre, la carotte, les pois gourmands et presque tout l''oignon nouveau avec les deux tiers de la sauce.","Saler le thon et presser les graines de sésame sur les deux faces.","Chauffer l''huile dans une poêle à feu vif et saisir le thon 1 à 1,5 min de chaque côté pour qu''il reste rosé à cœur. Laisser reposer 1 min et trancher.","Répartir les nouilles dans des bols, poser le thon dessus, arroser du reste de sauce et parsemer du reste d''oignon nouveau."]},"it":{"title":"Tonno scottato con soba fredda, edamame e cetriolo","steps":["Cuocere le soba in acqua bollente come indicato sulla confezione, aggiungendo gli edamame negli ultimi 3 min. Sciacquare sotto l''acqua fredda strofinando i noodles per eliminare l''amido e scolare bene.","Sbattere salsa di soia, aceto, mirin, olio di sesamo e zenzero.","Condire noodles, edamame, cetriolo, carota, taccole e quasi tutto il cipollotto con due terzi del condimento.","Salare il tonno e premere i semi di sesamo su entrambi i lati.","Scaldare l''olio in padella a fuoco vivo e scottare il tonno 1-1,5 min per lato, perché resti rosato all''interno. Lasciar riposare 1 min e affettare.","Dividere i noodles nelle ciotole, adagiarvi il tonno, irrorare con il resto del condimento e cospargere con il cipollotto rimasto."]}}'::jsonb),
  ('d75b1169-6877-4ca8-8496-deb6828a39b3'::uuid, '{"fr":{"title":"Pasta tonno e zucchine (pâtes au thon, courgettes et citron)","steps":["Cuire les pâtes al dente dans une grande quantité d''eau bien salée, environ 11 min. Garder une tasse d''eau de cuisson.","Pendant ce temps, chauffer l''huile dans une grande poêle et faire fondre l''échalote et l''ail 2 min.","Ajouter les courgettes avec une pincée de sel et cuire 6 à 7 min à feu moyen-vif, jusqu''à ce qu''elles soient tendres et dorées par endroits.","Verser le vin et le laisser s''évaporer, puis ajouter le thon émietté et le piment et réchauffer 2 min.","Égoutter les pâtes et les faire sauter dans la poêle avec un peu d''eau de cuisson, le zeste et le jus de citron et le persil, jusqu''à ce qu''elles soient brillantes.","Servir avec le basilic et un tour de moulin à poivre."]},"it":{"title":"Pasta tonno e zucchine al limone","steps":["Cuocere la pasta al dente in abbondante acqua ben salata, circa 11 min. Tenere da parte una tazza di acqua di cottura.","Intanto scaldare l''olio in un''ampia padella e appassire scalogno e aglio per 2 min.","Aggiungere le zucchine con un pizzico di sale e cuocere 6-7 min a fuoco medio-alto, finché sono tenere e dorate qua e là.","Sfumare con il vino e lasciarlo evaporare, poi unire il tonno sbriciolato e il peperoncino e scaldare 2 min.","Scolare la pasta e saltarla in padella con un goccio di acqua di cottura, scorza e succo di limone e prezzemolo, finché è lucida.","Servire con il basilico e una macinata di pepe."]}}'::jsonb),
  ('b3af1747-1bd4-4ce2-a8ba-1bed3e564400'::uuid, '{"fr":{"title":"Atún encebollado (thon aux oignons fondants) et pommes de terre","steps":["Cuire les pommes de terre 12 à 14 min dans l''eau salée, jusqu''à ce qu''elles soient tendres, et égoutter.","Pendant ce temps, chauffer l''huile dans une grande sauteuse et cuire les oignons, le poivron, l''ail et le laurier avec une pincée de sel à feu moyen 12 min en remuant souvent, jusqu''à ce qu''ils soient fondants et légèrement dorés.","Ajouter le paprika, puis le vin et le vinaigre, et laisser bouillonner 2 min.","Saler le thon, l''enfouir dans les oignons, couvrir et cuire 3 à 4 min à feu doux en le retournant une fois, jusqu''à ce qu''il soit juste rosé à cœur.","Servir le thon et les oignons avec les pommes de terre en les arrosant du jus, et parsemer de persil."]},"it":{"title":"Atún encebollado (tonno con cipolle stufate) e patate","steps":["Lessare le patate in acqua salata per 12-14 min, finché sono tenere, e scolarle.","Intanto scaldare l''olio in un''ampia padella e cuocere cipolle, peperone, aglio e alloro con un pizzico di sale a fuoco medio per 12 min, mescolando spesso, finché sono morbidi e leggermente dorati.","Unire la paprica, poi vino e aceto, e lasciar bollire 2 min.","Salare il tonno, adagiarlo tra le cipolle, coprire e cuocere 3-4 min a fuoco basso girandolo una volta, finché è appena rosato al centro.","Servire tonno e cipolle con le patate, irrorando con il sugo, e cospargere di prezzemolo."]}}'::jsonb),
  ('a68ec850-a7a8-4494-abc8-c41fa57e15e4'::uuid, '{"fr":{"title":"Pan bagnat au thon, œuf et tomate","steps":["Plonger les œufs dans l''eau bouillante et les cuire 9 min, puis les refroidir dans l''eau froide, les écaler et les trancher.","Ouvrir les pains et frotter les faces coupées avec l''ail.","Fouetter l''huile et le vinaigre avec une pincée de sel et en badigeonner presque tout sur les faces coupées.","Disposer les tomates sur les moitiés inférieures pour que leur jus imbibe le pain, puis le poivron, les radis et l''oignon.","Ajouter le thon, les tranches d''œuf, les anchois, les olives et le basilic, arroser du reste de vinaigrette et refermer les pains.","Presser fermement chaque pain avec la main, ou l''emballer et le lester quelques minutes, pour que le pain s''imbibe des jus. Déguster aussitôt ou emballé pour un pique-nique."]},"it":{"title":"Pan bagnat (panino nizzardo con tonno, uova e pomodoro)","steps":["Calare le uova in acqua bollente e cuocerle 9 min, poi raffreddarle in acqua fredda, sgusciarle e affettarle.","Aprire i panini e strofinare le superfici tagliate con l''aglio.","Emulsionare olio e aceto con un pizzico di sale e spennellarne quasi tutto sulle superfici tagliate.","Disporre i pomodori sulle metà inferiori perché il loro succo bagni il pane, poi peperone, ravanelli e cipolla.","Aggiungere tonno, fette di uovo, acciughe, olive e basilico, condire con il resto della vinaigrette e chiudere i panini.","Premere bene ogni panino con la mano, oppure avvolgerlo e metterci sopra un peso per qualche minuto, perché il pane assorba i succhi. Mangiare subito o portare incartato per un picnic."]}}'::jsonb),
  ('b0be422c-c1c9-4b9b-a518-9cf99c35992c'::uuid, '{"fr":{"title":"Bibimbap au thon, épinards, courgette, carotte et œuf au plat","steps":["Rincer le riz et le cuire à couvert dans 210 ml d''eau 12 min à feu doux, puis le laisser reposer 5 min hors du feu.","Mélanger le gochujang, le miel, le vinaigre et 1 c. à café d''huile de sésame avec 1 c. à soupe d''eau pour la sauce.","Chauffer un peu d''huile dans une poêle et faire sauter les légumes l''un après l''autre avec une pincée de sel : la carotte et la courgette 2 min chacune, les pousses de soja 1 min, puis les épinards avec l''ail jusqu''à ce qu''ils tombent. Réserver chacun.","Assaisonner les épinards avec la sauce soja et le reste d''huile de sésame. Réchauffer le thon 1 min dans la poêle.","Cuire les œufs au plat dans le reste d''huile jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Remplir les bols de riz, disposer les légumes et le thon par sections, ajouter un œuf et une cuillerée de sauce, puis tout mélanger à table."]},"it":{"title":"Bibimbap al tonno con spinaci, zucchina, carota e uovo all''occhio di bue","steps":["Sciacquare il riso e cuocerlo coperto in 210 ml d''acqua per 12 min a fuoco basso, poi lasciarlo riposare 5 min fuori dal fuoco.","Mescolare gochujang, miele, aceto e 1 cucchiaino di olio di sesamo con 1 cucchiaio d''acqua per la salsa.","Scaldare un po'' d''olio in padella e saltare le verdure una alla volta con un pizzico di sale: carota e zucchina 2 min ciascuna, germogli di soia 1 min, poi spinaci con l''aglio finché appassiscono. Tenere da parte ognuna.","Condire gli spinaci con la salsa di soia e il resto dell''olio di sesamo. Scaldare il tonno in padella per 1 min.","Cuocere le uova all''occhio di bue nel resto dell''olio finché gli albumi sono rappresi e i tuorli ancora morbidi.","Riempire le ciotole di riso, disporvi sopra a spicchi verdure e tonno, aggiungere un uovo e un cucchiaio di salsa e mescolare tutto a tavola."]}}'::jsonb),
  ('8a982386-b3eb-46db-91d5-ba0b6caec5b2'::uuid, '{"fr":{"title":"Donburi de maquereau teriyaki au air fryer et pak choï","steps":["Rincer le riz et le cuire à couvert dans 230 ml d''eau 12 min à feu doux. Poser le pak choï dessus, recouvrir et laisser cuire à la vapeur 4 min hors du feu.","Mélanger la sauce soja, le mirin, le saké, le sucre et le gingembre pour la sauce teriyaki.","Sécher le maquereau, le frotter d''huile et d''une pincée de sel, puis le cuire au air fryer côté peau vers le haut à 200 °C 7 à 8 min, jusqu''à ce que la peau soit croustillante et la chair opaque.","Pendant ce temps, faire réduire la sauce dans une petite casserole 2 à 3 min, jusqu''à ce qu''elle soit sirupeuse et brillante.","Retourner le maquereau cuit dans la sauce pour le laquer.","Remplir les bols de riz, ajouter le pak choï et le maquereau, napper du reste de sauce et finir avec l''oignon nouveau et les graines de sésame."]},"it":{"title":"Donburi di sgombro teriyaki in friggitrice ad aria con pak choi","steps":["Sciacquare il riso e cuocerlo coperto in 230 ml d''acqua per 12 min a fuoco basso. Adagiarvi sopra il pak choi, coprire di nuovo e cuocere a vapore 4 min fuori dal fuoco.","Mescolare salsa di soia, mirin, sakè, zucchero e zenzero per la salsa teriyaki.","Asciugare lo sgombro, ungerlo con l''olio e un pizzico di sale e cuocerlo in friggitrice ad aria con la pelle in alto a 200 °C per 7-8 min, finché la pelle è croccante e la carne opaca.","Intanto far ridurre la salsa in un pentolino per 2-3 min, finché è sciropposa e lucida.","Passare lo sgombro cotto nella salsa per glassarlo.","Riempire le ciotole di riso, aggiungere il pak choi e lo sgombro, condire con il resto della salsa e finire con cipollotto e sesamo."]}}'::jsonb),
  ('a2384340-1caf-457a-90aa-b35463171d1f'::uuid, '{"fr":{"title":"Sardines à la portugaise au air fryer, pommes de terre et salade de poivrons grillés","steps":["Cuire les pommes de terre 15 à 18 min dans l''eau salée, jusqu''à ce qu''elles soient tendres, et égoutter.","Pendant ce temps, mélanger les poivrons avec 1 c. à café d''huile et les cuire au air fryer à 200 °C 12 min, jusqu''à ce qu''ils soient tendres et cloqués.","Mélanger les poivrons chauds avec l''oignon, l''ail, le vinaigre, la moitié de l''huile restante et une pincée de sel.","Frotter les sardines de gros sel et les cuire au air fryer en une seule couche à 200 °C 8 à 10 min en les retournant une fois, jusqu''à ce que la peau soit croustillante et que la chair se détache de l''arête.","Mélanger les pommes de terre avec le reste d''huile, le persil et du sel, et servir avec les sardines, la salade de poivrons et des quartiers de citron."]},"it":{"title":"Sardine alla portoghese in friggitrice ad aria con patate e insalata di peperoni arrostiti","steps":["Lessare le patate in acqua salata per 15-18 min, finché sono tenere, e scolarle.","Intanto condire i peperoni con 1 cucchiaino d''olio e cuocerli in friggitrice ad aria a 200 °C per 12 min, finché sono morbidi e abbrustoliti.","Condire i peperoni caldi con cipolla, aglio, aceto, metà dell''olio rimasto e un pizzico di sale.","Strofinare le sardine con sale grosso e cuocerle in friggitrice ad aria in un solo strato a 200 °C per 8-10 min, girandole una volta, finché la pelle è croccante e la carne si stacca dalla lisca.","Condire le patate con il resto dell''olio, il prezzemolo e sale, e servire con le sardine, l''insalata di peperoni e spicchi di limone."]}}'::jsonb),
  ('bb8f91b7-7ead-48a7-b419-e1476bfc8284'::uuid, '{"fr":{"title":"Truite poêlée, pois chiches à la harissa, tomates et épinards","steps":["Chauffer les deux tiers de l''huile dans une casserole et faire fondre l''oignon 4 min, puis ajouter l''ail, la harissa et le cumin 1 min.","Ajouter les tomates, les pois chiches et le bouillon et laisser mijoter 6 à 8 min en écrasant quelques pois chiches, jusqu''à ce que les tomates s''affaissent et que la sauce épaississe.","Incorporer les épinards jusqu''à ce qu''ils tombent et assaisonner de sel et d''un filet de citron.","Pendant ce temps, assaisonner la truite, chauffer le reste de l''huile dans une poêle et la cuire côté peau 3 min, jusqu''à ce qu''elle soit croustillante, puis 1 min de l''autre côté.","Servir la truite sur les pois chiches à la harissa avec une cuillerée de yaourt, la coriandre, et des quartiers de citron."]},"it":{"title":"Trota in padella con ceci alla harissa, pomodorini e spinaci","steps":["Scaldare due terzi dell''olio in una casseruola e appassire la cipolla per 4 min, poi unire aglio, harissa e cumino per 1 min.","Aggiungere pomodorini, ceci e brodo e sobbollire 6-8 min schiacciando qualche cece, finché i pomodorini si disfano e il sugo si addensa.","Unire gli spinaci finché appassiscono e condire con sale e una spruzzata di limone.","Intanto condire la trota, scaldare il resto dell''olio in padella e cuocerla dal lato della pelle per 3 min, finché è croccante, poi 1 min dall''altro lato.","Servire la trota sui ceci alla harissa con un cucchiaio di yogurt, il coriandolo, e spicchi di limone."]}}'::jsonb),
  ('22b6241d-3e59-411e-9fd3-2c7eda838123'::uuid, '{"fr":{"title":"Balık ekmek au air fryer (sandwich au maquereau d''Istanbul) et oignons au sumac","steps":["Mélanger l''oignon avec le sumac, le persil, la moitié du jus de citron et une pincée de sel, et laisser attendrir.","Frotter le maquereau avec l''huile, le piment et du sel.","Cuire au air fryer côté peau vers le haut à 200 °C 7 à 8 min, jusqu''à ce que la peau soit croustillante et la chair s''effeuille.","Pendant ce temps, ouvrir le pain et toaster les faces coupées dans une poêle sèche bien chaude 1 à 2 min.","Garnir le pain de salade, de tomate et du maquereau, presser le reste du citron sur le poisson et ajouter les oignons au sumac."]},"it":{"title":"Balık ekmek in friggitrice ad aria (panino di sgombro di Istanbul) con cipolle al sommacco","steps":["Condire la cipolla con sommacco, prezzemolo, metà del succo di limone e un pizzico di sale e lasciarla ammorbidire.","Massaggiare lo sgombro con olio, peperoncino e sale.","Cuocere in friggitrice ad aria con la pelle in alto a 200 °C per 7-8 min, finché la pelle è croccante e la carne si sfalda.","Intanto aprire il pane e tostare le superfici tagliate in una padella asciutta ben calda per 1-2 min.","Farcire il pane con lattuga, pomodoro e sgombro, spremere il resto del limone sul pesce e aggiungere le cipolle al sommacco."]}}'::jsonb),
  ('3cdabe28-1cd3-448c-8f71-eaae284a4ce1'::uuid, '{"fr":{"title":"Pasta con le sarde (pâtes siciliennes aux sardines, fenouil, raisins secs et pignons)","steps":["Faire tremper les raisins secs dans de l''eau chaude et le safran dans 2 c. à soupe d''eau chaude pendant que vous commencez.","Cuire le fenouil émincé 6 min dans une grande casserole d''eau salée, le retirer, puis cuire les pâtes al dente dans la même eau.","Pendant ce temps, faire dorer la chapelure 2 min dans une grande poêle sèche et la réserver.","Chauffer l''huile dans la poêle et faire fondre l''oignon 4 min, puis y faire fondre les anchois.","Ajouter les filets de sardine et cuire 3 à 4 min en les émiettant un peu, puis incorporer le fenouil, les raisins égouttés, l''eau safranée, les pignons et une louche d''eau des pâtes, et laisser frémir 2 min.","Égoutter les pâtes, les mélanger à la sauce jusqu''à ce qu''elles soient bien enrobées et servir parsemées de chapelure grillée et de pluches de fenouil hachées."]},"it":{"title":"Pasta con le sarde","steps":["Mettere a bagno l''uvetta in acqua calda e lo zafferano in 2 cucchiai d''acqua calda mentre si inizia.","Lessare il finocchio affettato in una pentola d''acqua salata per 6 min, toglierlo, poi cuocere la pasta al dente nella stessa acqua.","Intanto tostare il pangrattato in un''ampia padella asciutta per 2 min, finché è dorato, e metterlo da parte.","Scaldare l''olio nella padella e appassire la cipolla per 4 min, poi farvi sciogliere le acciughe.","Aggiungere i filetti di sarda e cuocere 3-4 min sbriciolandoli un po'', poi unire finocchio, uvetta scolata, acqua allo zafferano, pinoli e un mestolo di acqua della pasta e sobbollire 2 min.","Scolare la pasta, saltarla nel condimento finché è ben condita e servire con il pangrattato tostato e le barbe di finocchio tritate."]}}'::jsonb),
  ('15925b98-3003-474e-bb56-1d95b3da4213'::uuid, '{"fr":{"title":"Truite au air fryer, salsa criolla et quinoa au maïs","steps":["Cuire la quinoa à couvert dans 280 ml d''eau salée 15 min. Ajouter le maïs et laisser 5 min hors du feu, couvercle fermé.","Pour la salsa criolla, rincer l''oignon à l''eau froide, égoutter et le mélanger avec l''ají amarillo, le jus d''un citron vert et demi, 1 c. à café d''huile, la moitié de la coriandre et une pincée de sel.","Frotter la truite avec l''ail, le cumin, le reste de l''huile et du sel.","Cuire au air fryer côté peau vers le haut à 200 °C 6 à 7 min, jusqu''à ce que la chair s''effeuille.","Égrener la quinoa avec le reste du jus de citron vert et de la coriandre, et servir avec la truite et la salsa criolla par-dessus."]},"it":{"title":"Trota in friggitrice ad aria con salsa criolla e quinoa al mais","steps":["Cuocere la quinoa coperta in 280 ml d''acqua salata per 15 min. Unire il mais e lasciare 5 min fuori dal fuoco, con il coperchio.","Per la salsa criolla, sciacquare la cipolla in acqua fredda, scolarla e condirla con ají amarillo, il succo di un lime e mezzo, 1 cucchiaino d''olio, metà del coriandolo e un pizzico di sale.","Massaggiare la trota con aglio, cumino, il resto dell''olio e sale.","Cuocere in friggitrice ad aria con la pelle in alto a 200 °C per 6-7 min, finché la carne si sfalda.","Sgranare la quinoa con il resto del succo di lime e del coriandolo e servire con la trota e la salsa criolla sopra."]}}'::jsonb),
  ('5f5e4869-7d40-56ba-bd0a-2e009c50c98d'::uuid, '{"fr":{"title":"Tofu satay au air fryer, riz, concombre et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux pendant 12 min.","Sécher le tofu et l''enrober de sauce soja, de curry et de curcuma, puis de fécule et d''huile.","Cuire le tofu au air fryer à 200 °C pendant 15 min en secouant le panier à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant sur les bords.","Poser les haricots verts sur le riz, recouvrir et cuire à la vapeur 5 min, puis retirer du feu.","Fouetter le beurre de cacahuète avec la sauce soja, le jus de citron vert, le miel, la sriracha, l''ail et 3 à 4 c. à soupe d''eau chaude pour obtenir une sauce fluide.","Servir le tofu sur le riz avec les haricots et le concombre, napper de sauce satay et parsemer d''oignon nouveau et de coriandre."]},"it":{"title":"Tofu satay in friggitrice ad aria con riso, cetriolo e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min.","Asciugare il tofu e condirlo con salsa di soia, curry e curcuma, poi con l''amido e l''olio.","Cuocere il tofu in friggitrice ad aria a 200 °C per 15 min, scuotendo il cestello a metà, finché è dorato e croccante ai bordi.","Disporre i fagiolini sul riso, coprire di nuovo e cuocere a vapore 5 min, poi togliere dal fuoco.","Sbattere il burro di arachidi con salsa di soia, succo di lime, miele, sriracha, aglio e 3-4 cucchiai d''acqua calda fino a una salsa fluida.","Servire il tofu sul riso con fagiolini e cetriolo, nappare con la salsa satay e completare con cipollotto e coriandolo."]}}'::jsonb),
  ('d5da07c5-ead2-5fba-a56c-d6763c2ea440'::uuid, '{"fr":{"title":"Tofu sel et poivre au air fryer, riz et pak-choï","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Mélanger la fécule avec le poivre du Sichuan, le poivre blanc et le sel. Y rouler le tofu bien sec, puis l''enrober de 2 c. à café d''huile.","Cuire au air fryer à 200 °C pendant 12 à 15 min en secouant deux fois, jusqu''à ce qu''il soit croustillant de partout.","Chauffer le reste d''huile dans un wok et faire sauter l''ail, le piment et le poivron 2 min.","Ajouter le pak-choï, la sauce soja et 2 c. à soupe d''eau et faire sauter 2 à 3 min, jusqu''à ce que les feuilles tombent mais que les tiges restent croquantes. Réserver dans les assiettes.","Faire sauter le tofu chaud dans le wok avec l''oignon nouveau et l''huile de sésame 30 secondes et servir avec le riz et le pak-choï."]},"it":{"title":"Tofu sale e pepe in friggitrice ad aria con riso e pak choi","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Mescolare l''amido con pepe di Sichuan, pepe bianco e sale. Passarvi il tofu ben asciutto, poi condirlo con 2 cucchiaini d''olio.","Cuocere in friggitrice ad aria a 200 °C per 12-15 min, scuotendo due volte, finché è croccante su tutti i lati.","Scaldare il resto dell''olio nel wok e saltare aglio, peperoncino e peperone per 2 min.","Aggiungere il pak choi, la salsa di soia e 2 cucchiai d''acqua e saltare 2-3 min, finché le foglie appassiscono ma i gambi restano croccanti. Disporre nei piatti.","Saltare il tofu caldo nel wok con cipollotto e olio di sesamo per 30 secondi e servire con riso e pak choi."]}}'::jsonb),
  ('72a7a213-1c8e-5209-9e43-c124015224dd'::uuid, '{"fr":{"title":"Tofu citronnelle et piment au air fryer, vermicelles de riz et herbes","steps":["Mélanger la citronnelle, l''échalote, les deux tiers de l''ail, la moitié du piment, la sauce soja, le sucre, le curcuma et l''huile. Y rouler le tofu.","Cuire le tofu avec toute sa citronnelle au air fryer à 190 °C pendant 12 à 15 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant.","Cuire les vermicelles 3 à 4 min dans l''eau bouillante, jusqu''à ce qu''ils soient juste tendres, puis les égoutter et les rincer à l''eau froide.","Mélanger le jus de citron vert, la sauce soja, le sucre, le reste d''ail et de piment et 3 c. à soupe d''eau jusqu''à ce que le sucre soit dissous.","Garnir deux bols de salade, de vermicelles, de concombre, de carotte et de germes de soja.","Ajouter le tofu, gratter par-dessus la citronnelle croustillante restée dans le panier, ajouter les herbes et les cacahuètes et arroser de sauce."]},"it":{"title":"Tofu alla citronella e peperoncino in friggitrice ad aria con spaghetti di riso ed erbe","steps":["Mescolare citronella, scalogno, due terzi dell''aglio, metà del peperoncino, salsa di soia, zucchero, curcuma e olio. Passarvi il tofu.","Cuocere il tofu con tutta la sua citronella in friggitrice ad aria a 190 °C per 12-15 min, scuotendo a metà, finché è dorato e croccante.","Cuocere gli spaghetti di riso in acqua bollente per 3-4 min, finché sono appena teneri, poi scolarli e sciacquarli sotto l''acqua fredda.","Mescolare succo di lime, salsa di soia, zucchero, il resto di aglio e peperoncino e 3 cucchiai d''acqua finché lo zucchero si scioglie.","Riempire due ciotole con insalata, spaghetti di riso, cetriolo, carota e germogli di soia.","Aggiungere il tofu, raschiarvi sopra la citronella croccante rimasta nel cestello, unire erbe e arachidi e condire con la salsa."]}}'::jsonb),
  ('93f84af9-8cb0-52ab-a5c0-55db1ea75204'::uuid, '{"fr":{"title":"Tofu shogayaki, riz et chou émincé","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Mélanger le gingembre, l''ail, la sauce soja, le mirin, le saké et le sucre.","Sécher le tofu et le fariner de fécule. Le dorer dans l''huile dans une grande poêle à feu moyen-vif, 3 min de chaque côté.","Pousser le tofu sur le côté, ajouter l''oignon et cuire 3 min, jusqu''à ce qu''il soit tendre.","Verser la sauce et laisser bouillonner 1 à 2 min en retournant le tofu, jusqu''à ce qu''elle le laque.","Servir le tofu et l''oignon avec leur sauce à côté du riz, d''un petit tas de chou émincé et de la tomate, parsemés d''oignon nouveau."]},"it":{"title":"Tofu shogayaki con riso e cavolo a julienne","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Mescolare zenzero, aglio, salsa di soia, mirin, sake e zucchero.","Asciugare il tofu e infarinarlo con l''amido. Rosolarlo nell''olio in una padella larga a fuoco medio-alto, 3 min per lato, finché è dorato.","Spostare il tofu di lato, aggiungere la cipolla e cuocerla 3 min, finché è morbida.","Versare la salsa e lasciarla sobbollire 1-2 min girando il tofu, finché lo glassa.","Servire tofu e cipolla con il loro sugo accanto al riso, a un mucchietto di cavolo a julienne e al pomodoro, con cipollotto sopra."]}}'::jsonb),
  ('8ec374bf-9573-5d4e-80e0-8501c425e6b4'::uuid, '{"fr":{"title":"Mie goreng au tempeh et à l''œuf","steps":["Cuire les nouilles 3 à 4 min dans l''eau bouillante, les égoutter et les rincer à l''eau froide.","Faire dorer le tempeh dans 1 c. à soupe d''huile dans un wok à feu moyen-vif 4 à 5 min en le retournant. Le réserver.","Ajouter le reste d''huile et faire sauter l''échalote, l''ail et le piment 1 min, puis la carotte et le chou 2 min.","Pousser les légumes sur le côté, casser les œufs et les brouiller jusqu''à ce qu''ils soient juste pris.","Ajouter les nouilles, le kecap manis, la sauce soja et les germes de soja et faire sauter à feu vif 2 min, jusqu''à ce que les nouilles soient brillantes et chaudes.","Remettre le tempeh et l''oignon nouveau, mélanger et servir avec des quartiers de citron vert."]},"it":{"title":"Mie goreng con tempeh e uovo","steps":["Cuocere i noodles in acqua bollente per 3-4 min, scolarli e sciacquarli sotto l''acqua fredda.","Rosolare il tempeh in 1 cucchiaio d''olio nel wok a fuoco medio-alto per 4-5 min, girandolo, finché è dorato. Toglierlo.","Aggiungere il resto dell''olio e saltare scalogno, aglio e peperoncino per 1 min, poi carota e cavolo per 2 min.","Spostare le verdure di lato, rompere le uova e strapazzarle finché sono appena rapprese.","Aggiungere noodles, kecap manis, salsa di soia e germogli e saltare a fuoco vivo per 2 min, finché i noodles sono lucidi e caldi.","Rimettere tempeh e cipollotto, mescolare e servire con spicchi di lime."]}}'::jsonb),
  ('a8f3e6c9-03a6-5fea-9810-d15ac7cf6e94'::uuid, '{"fr":{"title":"Pad kra pao au tempeh et œuf frit","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Chauffer fortement 1 c. à soupe d''huile dans un wok et y frire les œufs un par un 2 min en les arrosant d''huile, jusqu''à ce que les bords soient croustillants et le jaune encore coulant. Réserver.","Piler ou hacher finement l''ail et les piments ensemble. Mélanger la sauce soja, la sauce soja foncée, le sucre et 2 c. à soupe d''eau.","Ajouter le reste d''huile dans le wok, faire revenir l''ail et le piment 30 secondes, puis le tempeh 3 min, jusqu''à ce qu''il soit doré.","Ajouter les haricots et l''oignon et faire sauter 2 min, puis la sauce 1 min, jusqu''à ce qu''elle enrobe le tout.","Retirer le wok du feu et incorporer le basilic jusqu''à ce qu''il flétrisse. Servir sur le riz, surmonté d''un œuf frit."]},"it":{"title":"Pad kra pao con tempeh e uovo fritto","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Scaldare bene 1 cucchiaio d''olio nel wok e friggere le uova una alla volta per 2 min, bagnandole con l''olio, finché i bordi sono croccanti e il tuorlo ancora morbido. Toglierle.","Pestare o tritare finemente aglio e peperoncini insieme. Mescolare salsa di soia, salsa di soia scura, zucchero e 2 cucchiai d''acqua.","Aggiungere il resto dell''olio nel wok, soffriggere aglio e peperoncino per 30 secondi, poi il tempeh per 3 min, finché è rosolato.","Aggiungere fagiolini e cipolla e saltare 2 min, poi la salsa per 1 min, finché avvolge tutto.","Togliere il wok dal fuoco e unire il basilico finché appassisce. Servire sul riso con un uovo fritto sopra."]}}'::jsonb),
  ('5bbf80f0-4280-559d-840e-8a3798e4f5d4'::uuid, '{"fr":{"title":"Chana saag et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Faire revenir l''oignon dans l''huile dans une sauteuse à feu moyen 5 min, jusqu''à ce qu''il soit tendre et doré.","Ajouter l''ail, le gingembre, le piment, le cumin, la coriandre et le curcuma et remuer 1 min, jusqu''à ce que ça embaume.","Ajouter les tomates et cuire 3 min, puis les pois chiches et 100 ml d''eau. Laisser mijoter 5 min en écrasant quelques pois chiches pour épaissir la sauce.","Incorporer les épinards poignée par poignée jusqu''à ce qu''ils tombent, puis le garam masala. Saler.","Servir le chana saag avec le riz."]},"it":{"title":"Chana saag con riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Soffriggere la cipolla nell''olio in una padella larga a fuoco medio per 5 min, finché è morbida e dorata.","Aggiungere aglio, zenzero, peperoncino, cumino, coriandolo e curcuma e mescolare 1 min, finché profumano.","Aggiungere i pomodori e cuocere 3 min, poi i ceci e 100 ml d''acqua. Sobbollire 5 min, schiacciando qualche cece per addensare il sugo.","Unire gli spinaci una manciata alla volta finché appassiscono, poi il garam masala. Salare.","Servire il chana saag con il riso."]}}'::jsonb),
  ('a2a8754c-0660-5b6f-af79-763c22ea9e69'::uuid, '{"fr":{"title":"Tostadas aux haricots noirs au air fryer, avocat et oignon pickles","steps":["Mélanger l''oignon avec le jus d''un citron vert et une pincée de sel et le laisser rosir pendant la cuisson.","Badigeonner légèrement les tortillas d''1 c. à café d''huile et les cuire au air fryer par deux ou trois à 190 °C pendant 5 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient croustillantes.","Pendant ce temps, chauffer le reste d''huile dans une poêle avec l''ail, le cumin et le piment 1 min.","Ajouter les haricots et 4 c. à soupe d''eau et cuire 5 min en les écrasant en purée grossière et tartinable. Ajouter le jus du second citron vert et saler.","Tartiner les tostadas de haricots et garnir de salade, de tomate, d''avocat, d''oignon égoutté, de coriandre et de sauce piquante."]},"it":{"title":"Tostadas di fagioli neri in friggitrice ad aria con avocado e cipolla in agrodolce","steps":["Condire la cipolla con il succo di 1 lime e un pizzico di sale e lasciarla diventare rosa durante la cottura.","Spennellare leggermente le tortillas con 1 cucchiaino d''olio e cuocerle in friggitrice ad aria due o tre alla volta a 190 °C per 5 min, girandole a metà, finché sono croccanti.","Nel frattempo scaldare il resto dell''olio in padella con aglio, cumino e peperoncino per 1 min.","Aggiungere i fagioli e 4 cucchiai d''acqua e cuocere 5 min schiacciandoli in una purea grossolana e spalmabile. Aggiungere il succo del secondo lime e salare.","Spalmare i fagioli sulle tostadas e completare con insalata, pomodoro, avocado, cipolla scolata, coriandolo e salsa piccante."]}}'::jsonb),
  ('18921f2f-7942-5bfa-8c44-66a4de953264'::uuid, '{"fr":{"title":"Pasta e fagioli (soupe de pâtes aux haricots)","steps":["Faire suer l''oignon, la carotte et le céleri dans 1 c. à soupe d''huile dans une grande casserole à feu moyen 6 min.","Ajouter l''ail, le romarin et le concentré de tomate et remuer 1 min.","Ajouter les tomates, les haricots et le bouillon, porter à ébullition et laisser frémir 3 min.","Prélever une louche de haricots, les écraser à la fourchette et les remettre pour épaissir la soupe.","Ajouter les pâtes et cuire 9 à 10 min en remuant souvent, jusqu''à ce qu''elles soient al dente et la soupe épaisse. Ajouter un peu d''eau si elle devient trop sèche.","Retirer le romarin, laisser reposer 2 min, puis servir avec le reste d''huile, du poivre noir et le parmesan."]},"it":{"title":"Pasta e fagioli","steps":["Far appassire cipolla, carota e sedano in 1 cucchiaio d''olio in una pentola capiente a fuoco medio per 6 min.","Aggiungere aglio, rosmarino e concentrato di pomodoro e mescolare 1 min.","Aggiungere pomodori, fagioli e brodo, portare a bollore e sobbollire 3 min.","Prelevare un mestolo di fagioli, schiacciarli con una forchetta e rimetterli per addensare la minestra.","Aggiungere la pasta e cuocere 9-10 min mescolando spesso, finché è al dente e la minestra è densa. Allungare con poca acqua se si asciuga troppo.","Togliere il rosmarino, lasciar riposare 2 min, poi servire con il resto dell''olio, pepe nero e parmigiano."]}}'::jsonb),
  ('0bea3390-8cab-59e2-96c7-b2464bd0572a'::uuid, '{"fr":{"title":"Musabaha, pita chaude et salade hachée","steps":["Couvrir les pois chiches d''eau dans une casserole, ajouter le cumin et laisser frémir 10 à 12 min, jusqu''à ce qu''ils soient très tendres.","Fouetter le tahini avec les trois quarts du jus de citron, l''ail, une pincée de sel et 3 à 4 c. à soupe d''eau froide pour obtenir une sauce lisse.","Mélanger la tomate, le concombre, l''oignon et le persil avec le reste du jus de citron, 1 c. à café d''huile et du sel.","Égoutter les pois chiches en gardant un peu d''eau de cuisson. Écraser grossièrement un tiers des pois chiches avec la moitié de la sauce tahini et 2 à 3 c. à soupe de liquide.","Réchauffer les pitas dans la casserole vide 1 min de chaque côté.","Étaler la purée dans des bols, poser les pois chiches entiers dessus, arroser du reste de sauce et d''huile, saupoudrer de paprika et servir avec la salade et la pita."]},"it":{"title":"Musabaha con pita calda e insalata tritata","steps":["Coprire i ceci d''acqua in un pentolino, aggiungere il cumino e sobbollire 10-12 min, finché sono molto morbidi.","Sbattere la tahina con tre quarti del succo di limone, l''aglio, un pizzico di sale e 3-4 cucchiai d''acqua fredda fino a una salsa liscia.","Mescolare pomodoro, cetriolo, cipolla e prezzemolo con il resto del succo di limone, 1 cucchiaino d''olio e sale.","Scolare i ceci tenendo un po'' di liquido. Schiacciarne grossolanamente un terzo con metà della salsa tahina e 2-3 cucchiai di liquido.","Scaldare le pite nel pentolino vuoto 1 min per lato.","Stendere la purea nelle ciotole, disporre sopra i ceci interi, condire con il resto della salsa e dell''olio, spolverare di paprika e servire con l''insalata e la pita."]}}'::jsonb),
  ('14e68d98-f16b-54ea-bb06-2b58e9a9b9fc'::uuid, '{"fr":{"title":"Soupe ezogelin au beurre de menthe et pain","steps":["Faire suer l''oignon dans l''huile dans une grande casserole à feu moyen 4 min.","Ajouter le concentré de tomate et le paprika et remuer 1 min, puis la tomate râpée 1 min.","Ajouter les lentilles, le boulgour et le bouillon, porter à ébullition et laisser frémir à demi couvert 18 à 20 min en remuant de temps en temps, jusqu''à ce que les lentilles se défassent et que la soupe épaississe.","Saler et ajouter un peu d''eau chaude si elle est trop épaisse.","Faire fondre le beurre dans une petite poêle, ajouter la menthe séchée et le piment d''Alep et laisser grésiller 30 secondes.","Servir la soupe en bols, arroser de beurre à la menthe et servir avec des quartiers de citron et du pain."]},"it":{"title":"Zuppa ezogelin al burro alla menta e pane","steps":["Far appassire la cipolla nell''olio in una pentola capiente a fuoco medio per 4 min.","Unire concentrato di pomodoro e paprika e mescolare 1 min, poi il pomodoro grattugiato per 1 min.","Aggiungere lenticchie, bulgur e brodo, portare a bollore e sobbollire semicoperto per 18-20 min mescolando ogni tanto, finché le lenticchie si sfaldano e la zuppa è densa.","Salare, aggiungendo poca acqua calda se è troppo densa.","Sciogliere il burro in un padellino, aggiungere menta secca e pepe di Aleppo e lasciar sfrigolare 30 secondi.","Versare la zuppa nelle ciotole, condire con il burro alla menta e servire con spicchi di limone e pane."]}}'::jsonb),
  ('984accea-cf2e-515c-adc4-8fe25da6a904'::uuid, '{"fr":{"title":"Huevos motuleños aux haricots noirs et petits pois","steps":["Cuire la tomate, l''oignon, l''ail et le piment dans 1 c. à café d''huile dans une casserole 8 min en écrasant à la cuillère pour obtenir une sauce épaisse. Ajouter les petits pois les 3 dernières minutes et assaisonner.","Pendant ce temps, réchauffer les haricots dans une poêle avec 4 c. à soupe d''eau 4 min en les écrasant en purée épaisse. Assaisonner, réserver dans un bol et essuyer la poêle.","Badigeonner les tortillas d''un peu d''huile et les cuire au air fryer à 180 °C pendant 3 à 4 min, jusqu''à ce qu''elles soient légèrement croustillantes mais encore souples.","Faire cuire les œufs au plat dans le reste d''huile dans la poêle 3 min, jusqu''à ce que les blancs soient pris et les jaunes coulants.","Tartiner chaque tortilla de haricots et poser un œuf au plat dessus.","Napper de sauce tomate aux petits pois et finir avec le queso fresco et la coriandre."]},"it":{"title":"Huevos motuleños con fagioli neri e piselli","steps":["Cuocere pomodoro, cipolla, aglio e peperoncino in 1 cucchiaino d''olio in un pentolino per 8 min, schiacciando con un cucchiaio fino a un sugo rustico. Aggiungere i piselli negli ultimi 3 min e regolare di sale.","Nel frattempo scaldare i fagioli in padella con 4 cucchiai d''acqua per 4 min, schiacciandoli in una purea densa. Salare, metterli in una ciotola e pulire la padella.","Spennellare le tortillas con poco olio e cuocerle in friggitrice ad aria a 180 °C per 3-4 min, finché sono appena croccanti ma ancora flessibili.","Cuocere le uova all''occhio di bue nel resto dell''olio nella padella per 3 min, finché l''albume è rappreso e il tuorlo morbido.","Spalmare ogni tortilla di fagioli e metterci sopra un uovo.","Nappare con il sugo di pomodoro e piselli e finire con queso fresco e coriandolo."]}}'::jsonb),
  ('eceda964-0519-5e5a-b221-5f8a182e1afc'::uuid, '{"fr":{"title":"Egg foo young, riz et sauce au soja","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Battre les œufs avec la sauce soja et le poivre blanc, puis incorporer les germes de soja, les champignons, la carotte, les petits pois et l''oignon nouveau.","Chauffer la moitié de l''huile dans une poêle à feu moyen-vif. Y verser trois galettes de mélange à la louche et les cuire 2 min de chaque côté, jusqu''à ce qu''elles soient dorées et prises.","Les garder au chaud sur une assiette et cuire le reste du mélange de la même façon dans le reste d''huile.","Fouetter le bouillon, les deux sauces soja, le sucre, la fécule et l''huile de sésame, verser dans la poêle et remuer 1 à 2 min, jusqu''à ce que la sauce soit brillante et épaisse.","Servir les galettes sur le riz, nappées de sauce."]},"it":{"title":"Egg foo young con riso e salsa di soia","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Sbattere le uova con salsa di soia e pepe bianco, poi unire germogli, funghi, carota, piselli e cipollotto.","Scaldare metà dell''olio in padella a fuoco medio-alto. Versare con il mestolo tre frittatine di composto e cuocerle 2 min per lato, finché sono dorate e rapprese.","Tenerle in caldo su un piatto e cuocere il resto del composto allo stesso modo nel resto dell''olio.","Sbattere brodo, le due salse di soia, zucchero, amido e olio di sesamo, versare in padella e mescolare 1-2 min, finché la salsa è lucida e densa.","Servire le frittatine sul riso, nappate con la salsa."]}}'::jsonb),
  ('7d9bcee4-ff19-50c8-aa9e-2c4e7e147ba4'::uuid, '{"fr":{"title":"Bibimbap au tofu au air fryer et œufs au plat","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Mélanger le tofu avec la moitié de la sauce soja, puis la fécule, et le cuire au air fryer à 200 °C pendant 12 à 15 min en secouant à mi-cuisson, jusqu''à ce qu''il soit croustillant.","Blanchir les épinards 30 secondes et les germes de soja 1 min dans une poêle d''eau bouillante. Égoutter, presser les épinards et assaisonner chacun d''un peu d''ail, d''huile de sésame, de sauce soja et de sel.","Sécher la poêle, chauffer la moitié de l''huile végétale et faire sauter la carotte puis la courgette 2 min chacune, en salant.","Cuire les œufs au plat dans le reste d''huile 2 à 3 min, jusqu''à ce que les blancs soient pris et les jaunes coulants.","Mélanger le gochujang avec le miel, le vinaigre, le reste d''huile de sésame et 1 c. à soupe d''eau.","Remplir des bols de riz, disposer les légumes et le tofu en sections, poser un œuf et des graines de sésame et servir avec la sauce à mélanger."]},"it":{"title":"Bibimbap con tofu in friggitrice ad aria e uova all''occhio di bue","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Condire il tofu con metà della salsa di soia, poi con l''amido, e cuocerlo in friggitrice ad aria a 200 °C per 12-15 min, scuotendo a metà, finché è croccante.","Sbollentare gli spinaci per 30 secondi e i germogli per 1 min in una padella d''acqua bollente. Scolare, strizzare gli spinaci e condire ciascuno con poco aglio, olio di sesamo, salsa di soia e sale.","Asciugare la padella, scaldare metà dell''olio di semi e saltare la carota e poi la zucchina per 2 min ciascuna, salando.","Cuocere le uova all''occhio di bue nel resto dell''olio per 2-3 min, finché l''albume è rappreso e il tuorlo morbido.","Mescolare il gochujang con miele, aceto, il resto dell''olio di sesamo e 1 cucchiaio d''acqua.","Riempire le ciotole di riso, disporre verdure e tofu a spicchi, completare con un uovo e sesamo e servire con la salsa da mescolare."]}}'::jsonb),
  ('4c670d9d-c2d4-5210-b5a1-1b41458ccad7'::uuid, '{"fr":{"title":"Bol de riz au tofu et à l''œuf, épinards","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min.","Retirer le riz du feu et le laisser reposer 5 min à couvert.","Faire tomber les épinards dans une poêle avec 2 c. à soupe d''eau 1 à 2 min. Les presser et les assaisonner d''1 c. à café de sauce soja et des graines de sésame.","Dans la même poêle, porter à frémissement 150 ml d''eau, le dashi, le reste de sauce soja, le mirin et le sucre, ajouter l''oignon et cuire 3 min, puis ajouter le tofu et laisser frémir 2 à 3 min, jusqu''à ce qu''il soit chaud.","Battre légèrement les œufs et en verser les deux tiers sur l''oignon et le tofu. Couvrir et cuire 1 min, puis ajouter le reste et cuire encore 30 à 60 secondes, jusqu''à ce qu''ils soient juste pris et encore moelleux.","Répartir le riz dans des bols, y faire glisser le tofu, l''œuf et le bouillon et parsemer d''oignon nouveau. Servir les épinards à côté."]},"it":{"title":"Ciotola di riso con tofu e uova, spinaci","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min.","Togliere il riso dal fuoco e lasciarlo riposare coperto 5 min.","Far appassire gli spinaci in padella con 2 cucchiai d''acqua per 1-2 min. Strizzarli e condirli con 1 cucchiaino di salsa di soia e il sesamo.","Nella stessa padella portare a sobbollire 150 ml d''acqua, il dashi, il resto della salsa di soia, il mirin e lo zucchero, aggiungere la cipolla e cuocere 4-5 min, finché è morbida.","Sbattere leggermente le uova e versarne due terzi su cipolla e tofu. Coprire e cuocere 1 min, poi aggiungere il resto e cuocere ancora 30-60 secondi, finché sono appena rapprese e ancora morbide.","Distribuire il riso nelle ciotole, farvi scivolare sopra tofu, uovo e brodo e cospargere di cipollotto. Servire gli spinaci a parte."]}}'::jsonb),
  ('2dab32e5-2df9-5f3a-97c8-0e1b1330c3c5'::uuid, '{"fr":{"title":"Chilli paneer au air fryer et nouilles Hakka","steps":["Enrober le paneer d''1 c. à soupe de sauce soja et du piment du Cachemire, puis de la fécule et d''1 c. à café d''huile.","Cuire au air fryer à 200 °C pendant 10 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et croustillant sur les bords.","Pendant ce temps, cuire les nouilles 3 à 4 min dans l''eau bouillante, les égoutter et les rincer à l''eau froide.","Chauffer le reste d''huile dans un wok et faire sauter l''ail, le gingembre et le piment 30 secondes, puis l''oignon, le poivron, le chou et la carotte 3 min à feu vif.","Ajouter la sauce soja, le ketchup, le vinaigre et la sriracha avec les nouilles et faire sauter 2 min, jusqu''à ce que tout soit chaud et enrobé.","Ajouter le paneer et l''oignon nouveau, mélanger et servir aussitôt."]},"it":{"title":"Chilli paneer in friggitrice ad aria con noodles Hakka","steps":["Condire il paneer con 1 cucchiaio di salsa di soia e il peperoncino del Kashmir, poi con l''amido e 1 cucchiaino d''olio.","Cuocere in friggitrice ad aria a 200 °C per 10 min, scuotendo a metà, finché è dorato e croccante ai bordi.","Nel frattempo cuocere i noodles in acqua bollente per 3-4 min, scolarli e sciacquarli sotto l''acqua fredda.","Scaldare il resto dell''olio nel wok e saltare aglio, zenzero e peperoncino per 30 secondi, poi cipolla, peperone, cavolo e carota per 3 min a fuoco vivo.","Aggiungere salsa di soia, ketchup, aceto e sriracha con i noodles e saltare 2 min, finché tutto è caldo e ben condito.","Unire paneer e cipollotto, mescolare e servire subito."]}}'::jsonb),
  ('bfc455fb-ac6c-51b3-b897-bfa60df0bde4'::uuid, '{"fr":{"title":"Kadai paneer au air fryer et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau à feu doux 12 min, puis laisser reposer 5 min hors du feu.","Mélanger le paneer, les poivrons et l''oignon avec 1 c. à café d''huile, le piment du Cachemire et du sel. Cuire au air fryer à 200 °C pendant 8 min en remuant à 4 min, jusqu''à ce que les bords grillent.","Torréfier les graines de coriandre et le cumin à sec dans une poêle 1 min, puis les concasser.","Chauffer le reste d''huile dans la poêle, faire revenir l''ail et le gingembre 1 min, puis ajouter les tomates et les épices concassées et cuire 7 à 8 min, jusqu''à ce que la sauce soit épaisse et confite.","Incorporer le garam masala, les feuilles de fenugrec froissées entre les paumes et un peu d''eau.","Ajouter le paneer et les légumes et mélanger 2 min pour les enrober. Parsemer de coriandre et servir avec le riz."]},"it":{"title":"Kadai paneer in friggitrice ad aria con riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua a fuoco basso per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Condire paneer, peperoni e cipolla con 1 cucchiaino d''olio, il peperoncino del Kashmir e sale. Cuocere in friggitrice ad aria a 200 °C per 8 min, mescolando a 4 min, finché i bordi sono abbrustoliti.","Tostare i semi di coriandolo e il cumino in una padella asciutta per 1 min, poi pestarli grossolanamente.","Scaldare il resto dell''olio nella padella, soffriggere aglio e zenzero 1 min, poi aggiungere i pomodori e le spezie pestate e cuocere 7-8 min, finché il sugo è denso e ristretto.","Unire il garam masala, le foglie di fieno greco sbriciolate tra i palmi e un goccio d''acqua.","Aggiungere paneer e verdure e mescolare 2 min per insaporire. Cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('b98b523a-deb3-5ab2-9dac-6d5aa531cac0'::uuid, '{"fr":{"title":"Souvlaki de halloumi, pommes de terre au citron au air fryer et tzatziki","steps":["Mélanger les pommes de terre avec 2 c. à café d''huile, la moitié de l''origan, le zeste du citron et du sel. Cuire au air fryer à 200 °C pendant 18 à 20 min en secouant deux fois, jusqu''à ce qu''elles soient dorées et tendres.","Presser le concombre et le mélanger au yaourt avec l''ail, la menthe et une pincée de sel pour faire le tzatziki.","Enfiler le halloumi, le poivron et l''oignon sur des brochettes et les badigeonner du reste d''huile et d''origan.","Cuire les brochettes dans une poêle-gril bien chaude 6 à 8 min en les retournant, jusqu''à ce que le halloumi soit doré et les légumes grillés.","Presser la moitié du citron sur les pommes de terre et le reste sur les brochettes.","Servir les brochettes avec les pommes de terre, les tomates cerises et le tzatziki."]},"it":{"title":"Souvlaki di halloumi con patate al limone in friggitrice ad aria e tzatziki","steps":["Condire le patate con 2 cucchiaini d''olio, metà dell''origano, la scorza del limone e sale. Cuocere in friggitrice ad aria a 200 °C per 18-20 min, scuotendo due volte, finché sono dorate e tenere.","Strizzare il cetriolo e mescolarlo allo yogurt con aglio, menta e un pizzico di sale per fare lo tzatziki.","Infilare halloumi, peperone e cipolla sugli spiedini e spennellarli con il resto dell''olio e dell''origano.","Cuocere gli spiedini su una piastra rovente per 6-8 min, girandoli, finché l''halloumi è dorato e le verdure abbrustolite.","Spremere metà del limone sulle patate e il resto sugli spiedini.","Servire gli spiedini con le patate, i pomodorini e lo tzatziki."]}}'::jsonb),
  ('1083724c-2fbf-5649-a032-0662c173bfc0'::uuid, '{"fr":{"title":"Fajitas de halloumi au air fryer et pico de gallo","steps":["Mélanger les poivrons et les trois quarts de l''oignon avec l''huile, le cumin, le paprika, le piment, l''origan et une pincée de sel.","Cuire au air fryer à 200 °C pendant 8 min en secouant à mi-cuisson.","Poser le halloumi par-dessus (sans saler, il l''est déjà) et cuire au air fryer à 180 °C encore 6 à 7 min, jusqu''à ce qu''il soit doré.","Mélanger les tomates, le reste d''oignon haché fin, le piment, la coriandre et le jus d''un demi-citron vert pour faire le pico de gallo. Ajouter le reste du jus de citron vert au yaourt.","Réchauffer les tortillas dans une poêle sèche 30 secondes de chaque côté.","Garnir les tortillas de poivrons et de halloumi, de pico de gallo et de yaourt au citron vert."]},"it":{"title":"Fajitas di halloumi in friggitrice ad aria con pico de gallo","steps":["Condire i peperoni e tre quarti della cipolla con olio, cumino, paprika, peperoncino, origano e un pizzico di sale.","Cuocere in friggitrice ad aria a 200 °C per 8 min, scuotendo a metà.","Disporre sopra l''halloumi (senza sale, è già sapido) e cuocere in friggitrice ad aria a 180 °C per altri 6-7 min, finché è dorato.","Mescolare pomodori, il resto della cipolla tritata fine, peperoncino, coriandolo e il succo di mezzo lime per il pico de gallo. Unire il resto del succo di lime allo yogurt.","Scaldare le tortillas in una padella asciutta per 30 secondi per lato.","Farcire le tortillas con peperoni e halloumi, pico de gallo e yogurt al lime."]}}'::jsonb),
  ('a476feca-aa30-5999-a7c5-c8719997ae14'::uuid, '{"fr":{"title":"Orzo au citron, épinards, pois chiches et feta","steps":["Faire suer l''échalote et l''ail dans l''huile dans une sauteuse à feu moyen 2 min.","Ajouter l''orzo et remuer 1 min pour le nacrer légèrement.","Verser le bouillon, porter à frémissement et cuire 8 min en remuant souvent pour que ça n''attache pas.","Ajouter les pois chiches et cuire encore 2 à 3 min, jusqu''à ce que l''orzo soit tendre et ait absorbé presque tout le bouillon.","Incorporer les épinards jusqu''à ce qu''ils tombent, puis retirer du feu et ajouter le zeste du citron, le jus d''un demi-citron et l''aneth. Assaisonner.","Servir parsemé de feta, avec le reste du citron en quartiers."]},"it":{"title":"Orzo al limone con spinaci, ceci e feta","steps":["Far appassire scalogno e aglio nell''olio in una padella profonda a fuoco medio per 2 min.","Aggiungere l''orzo e mescolare 1 min per tostarlo leggermente.","Versare il brodo, portare a sobbollire e cuocere 8 min mescolando spesso perché non attacchi.","Aggiungere i ceci e cuocere altri 2-3 min, finché l''orzo è tenero e ha assorbito quasi tutto il brodo.","Unire gli spinaci finché appassiscono, poi togliere dal fuoco e aggiungere la scorza del limone, il succo di mezzo limone e l''aneto. Regolare di sale.","Servire con la feta sopra e il resto del limone a spicchi."]}}'::jsonb),
  ('a0e60ae9-0495-574e-9edd-3e70131dce05'::uuid, '{"fr":{"title":"Pilaf de boulgour aux lentilles, légumes au air fryer et feta","steps":["Faire cuire les lentilles dans beaucoup d''eau frémissante 10 min, jusqu''à ce qu''elles soient presque tendres, puis les égoutter.","Pendant ce temps, mélanger l''aubergine, le poivron et la courgette avec 2 c. à café d''huile, le cumin, le piment d''Alep et du sel. Cuire au air fryer à 200 °C pendant 18 min en secouant deux fois, jusqu''à ce qu''ils soient fondants et dorés.","Faire dorer l''oignon dans le reste d''huile dans une casserole 6 min. Ajouter le concentré de tomate et remuer 1 min.","Ajouter le boulgour, les lentilles et le bouillon chaud, assaisonner, couvrir et cuire à feu doux 12 min, jusqu''à absorption du liquide.","Laisser reposer le pilaf couvert 3 min, puis l''égrener à la fourchette et ajouter la moitié du persil.","Servir le pilaf garni des légumes, de la feta et du reste de persil, avec des quartiers de citron."]},"it":{"title":"Pilaf di bulgur e lenticchie con verdure in friggitrice ad aria e feta","steps":["Cuocere le lenticchie in abbondante acqua a bollore leggero per 10 min, finché sono quasi tenere, poi scolarle.","Nel frattempo condire melanzana, peperone e zucchina con 2 cucchiaini d''olio, cumino, pepe di Aleppo e sale. Cuocere in friggitrice ad aria a 200 °C per 18 min, scuotendo due volte, finché sono morbide e dorate.","Rosolare la cipolla nel resto dell''olio in una casseruola per 6 min, finché è dorata. Unire il concentrato di pomodoro e mescolare 1 min.","Aggiungere bulgur, lenticchie e brodo caldo, salare, coprire e cuocere a fuoco basso per 12 min, finché il liquido è assorbito.","Lasciar riposare il pilaf coperto 3 min, poi sgranarlo con una forchetta e unire metà del prezzemolo.","Servire il pilaf con sopra le verdure, la feta e il resto del prezzemolo, con spicchi di limone."]}}'::jsonb),
  ('32a459d6-6e4c-5c14-99e3-530a6b68ae80'::uuid, '{"fr":{"title":"Ful medames aux œufs, pita et salade de tomates","steps":["Cuire les œufs 8 min dans l''eau bouillante, les refroidir à l''eau froide et les écaler.","Faire revenir l''oignon et le cumin dans 2 c. à café d''huile dans une casserole à feu moyen 3 min, puis ajouter l''ail et le piment 1 min.","Ajouter les fèves et 100 ml d''eau, porter à ébullition et laisser frémir 5 min.","Écraser grossièrement les fèves au presse-purée en en laissant quelques-unes entières, puis ajouter les deux tiers du jus de citron et du sel.","Mélanger la tomate, le concombre et le persil avec le reste du jus de citron et du sel. Réchauffer les pitas dans une poêle sèche 1 min de chaque côté.","Répartir le ful dans des bols, arroser du tahini allongé d''un peu d''eau et du reste d''huile, et servir avec les œufs coupés en deux, la salade et la pita."]},"it":{"title":"Ful medames con uova, pita e insalata di pomodori","steps":["Cuocere le uova in acqua bollente per 8 min, raffreddarle in acqua fredda e sgusciarle.","Soffriggere cipolla e cumino in 2 cucchiaini d''olio in un pentolino a fuoco medio per 3 min, poi aggiungere aglio e peperoncino per 1 min.","Aggiungere le fave e 100 ml d''acqua, portare a bollore e sobbollire 5 min.","Schiacciare grossolanamente le fave con lo schiacciapatate lasciandone alcune intere, poi unire due terzi del succo di limone e sale.","Condire pomodoro, cetriolo e prezzemolo con il resto del succo di limone e sale. Scaldare le pite in una padella asciutta 1 min per lato.","Distribuire il ful nelle ciotole, condire con la tahina allungata con poca acqua e il resto dell''olio e servire con le uova tagliate a metà, l''insalata e la pita."]}}'::jsonb),
  ('f2420a6b-ce8c-5857-8883-92d0993e81dc'::uuid, '{"fr":{"title":"Kuru fasulye (haricots blancs à la turque), pilaf de riz et cacık","steps":["Rincer le riz et le nacrer dans le beurre dans une petite casserole 1 min, puis ajouter 250 ml d''eau bouillante et une pincée de sel, couvrir et cuire à feu doux 12 min. Laisser reposer 5 min hors du feu.","Faire suer l''oignon et le poivron dans l''huile dans une casserole à feu moyen 5 min, puis ajouter l''ail 1 min.","Ajouter le concentré de tomate et le piment d''Alep et remuer 1 min, puis les tomates.","Ajouter les haricots et 250 ml d''eau et laisser mijoter 12 à 15 min, jusqu''à ce que la sauce épaississe et que les haricots s''en imprègnent. Assaisonner.","Pour le cacık, presser le concombre et le mélanger au yaourt avec l''ail, la moitié de la menthe, un peu d''eau et du sel.","Égrener le riz, le napper de haricots et servir avec le cacık parsemé du reste de menthe."]},"it":{"title":"Kuru fasulye (fagioli bianchi alla turca) con pilaf di riso e cacık","steps":["Sciacquare il riso e tostarlo nel burro in un pentolino per 1 min, poi aggiungere 250 ml d''acqua bollente e un pizzico di sale, coprire e cuocere a fuoco basso 12 min. Lasciar riposare 5 min fuori dal fuoco.","Far appassire cipolla e peperone nell''olio in una casseruola a fuoco medio per 5 min, poi aggiungere l''aglio per 1 min.","Unire concentrato di pomodoro e pepe di Aleppo e mescolare 1 min, poi i pomodori.","Aggiungere i fagioli e 250 ml d''acqua e sobbollire 12-15 min, finché il sugo è denso e i fagioli si sono insaporiti. Regolare di sale.","Per il cacık, strizzare il cetriolo e mescolarlo allo yogurt con aglio, metà della menta, un goccio d''acqua e sale.","Sgranare il riso, coprirlo con i fagioli e servire con il cacık cosparso con il resto della menta."]}}'::jsonb),
  ('da583daf-e2c4-5b19-a514-ea13247580cd'::uuid, '{"fr":{"title":"Piperade aux œufs brouillés et pain de campagne","steps":["Faire fondre l''oignon et les poivrons dans l''huile dans une grande poêle à feu moyen 10 min en remuant, jusqu''à ce qu''ils soient tendres sans colorer.","Ajouter l''ail et le thym 1 min, puis les tomates et la moitié du piment d''Espelette. Cuire 6 à 7 min, jusqu''à ce que le jus soit presque évaporé. Assaisonner.","Griller le pain pendant que les légumes finissent de cuire.","Battre les œufs avec une pincée de sel, baisser le feu et les verser sur les légumes.","Remuer doucement 1 à 2 min, jusqu''à ce que les œufs forment des grumeaux moelleux et crémeux, et retirer la poêle du feu quand ils sont encore un peu baveux.","Saupoudrer du reste de piment d''Espelette et de persil et servir avec le pain grillé."]},"it":{"title":"Piperade con uova strapazzate morbide e pane casereccio","steps":["Far appassire cipolla e peperoni nell''olio in una padella larga a fuoco medio per 10 min, mescolando, finché sono morbidi ma non coloriti.","Aggiungere aglio e timo per 1 min, poi i pomodori e metà del peperoncino d''Espelette. Cuocere 6-7 min, finché il liquido è quasi evaporato. Regolare di sale.","Tostare il pane mentre le verdure finiscono di cuocere.","Sbattere le uova con un pizzico di sale, abbassare il fuoco e versarle sulle verdure.","Mescolare delicatamente per 1-2 min, finché le uova formano grumi morbidi e cremosi, e togliere dal fuoco quando sono ancora leggermente morbide.","Cospargere con il resto del peperoncino d''Espelette e il prezzemolo e servire con il pane tostato."]}}'::jsonb),
  ('52eefa89-ce22-5513-9f00-9911d9455167'::uuid, '{"fr":{"title":"Bols de quinoa aux haricots noirs, salsa de maïs et avocat","steps":["Cuire le quinoa à couvert dans 300 ml d''eau salée 13 à 15 min, jusqu''à absorption de l''eau. Laisser reposer 2 min et l''égrener.","Chauffer l''huile dans une poêle avec l''ail, le cumin et le piment 1 min, ajouter les haricots et 3 c. à soupe d''eau et réchauffer 4 à 5 min. Ajouter le jus d''un demi-citron vert et du sel.","Mélanger le maïs, le poivron, la tomate, l''oignon, le piment et la moitié de la coriandre avec le jus d''un citron vert et du sel.","Arroser l''avocat du reste de jus de citron vert.","Remplir des bols de quinoa, ajouter les haricots, la salsa de maïs et l''avocat et finir avec le reste de coriandre."]},"it":{"title":"Bowl di quinoa e fagioli neri con salsa di mais e avocado","steps":["Cuocere la quinoa coperta in 300 ml d''acqua salata per 13-15 min, finché l''acqua è assorbita. Lasciar riposare 2 min e sgranarla.","Scaldare l''olio in padella con aglio, cumino e peperoncino per 1 min, aggiungere i fagioli e 3 cucchiai d''acqua e scaldare 4-5 min. Unire il succo di mezzo lime e sale.","Mescolare mais, peperone, pomodoro, cipolla, peperoncino e metà del coriandolo con il succo di 1 lime e sale.","Condire l''avocado con il resto del succo di lime.","Riempire le ciotole con la quinoa, aggiungere fagioli, salsa di mais e avocado e finire con il resto del coriandolo."]}}'::jsonb),
  ('7c0e8388-e897-555c-9ea0-ba6b55bb6a19'::uuid, '{"fr":{"title":"Poulet à la moutarde, pommes vapeur et haricots verts","steps":["Cuire les pommes de terre 15 min dans l''eau salée en ajoutant les haricots verts pour les 6 dernières minutes, puis égoutter.","Saler et poivrer le poulet et le dorer dans l''huile et le beurre à feu moyen-vif 4 à 5 min, puis le réserver.","Faire revenir les échalotes 2 min dans la même poêle, verser le vin et laisser réduire de moitié, environ 2 min.","Ajouter le bouillon, le thym et le poulet et laisser mijoter 5 min jusqu''à ce que le poulet soit cuit à cœur.","Incorporer les deux moutardes et la crème fraîche et mijoter doucement 2 min jusqu''à ce que la sauce nappe la cuillère, sans faire bouillir fort.","Servir le poulet et sa sauce avec les pommes de terre et les haricots, parsemé de persil."]},"it":{"title":"Pollo alla senape con patate al vapore e fagiolini","steps":["Lessare le patate in acqua salata per 15 min aggiungendo i fagiolini negli ultimi 6 min, poi scolare.","Salare e pepare il pollo e rosolarlo nell''olio e nel burro a fuoco medio-alto per 4-5 min, poi metterlo da parte.","Appassire gli scalogni nella stessa padella per 2 min, versare il vino e lasciarlo ridurre della metà, circa 2 min.","Aggiungere il brodo, il timo e il pollo e sobbollire 5 min finché il pollo è cotto.","Unire le due senapi e la crème fraîche e sobbollire piano 2 min finché la salsa vela il cucchiaio, senza farla bollire forte.","Servire il pollo con la salsa, le patate e i fagiolini, con prezzemolo."]}}'::jsonb),
  ('e4d19897-95ca-5b08-bc75-a7524f426999'::uuid, '{"fr":{"title":"Poulet au marsala, tagliatelles et épinards","steps":["Porter à ébullition une grande casserole d''eau salée pour les pâtes.","Aplatir les morceaux de poulet à 1 cm d''épaisseur, les assaisonner et les fariner légèrement.","Cuire le poulet dans l''huile à feu moyen-vif 3 min de chaque côté jusqu''à ce qu''il soit doré et cuit, puis le réserver.","Faire dorer les champignons 5 min dans la même poêle, puis ajouter l''ail 30 secondes.","Cuire les tagliatelles selon le paquet, environ 8 min.","Verser le marsala sur les champignons et laisser bouillonner 2 min, ajouter le bouillon et mijoter 3 min jusqu''à une sauce un peu sirupeuse.","Remettre le poulet 1 à 2 min pour le réchauffer, puis incorporer le beurre hors du feu.","Égoutter les pâtes, y mélanger les épinards jusqu''à ce qu''ils tombent, et servir avec le poulet, la sauce aux champignons et le persil."]},"it":{"title":"Pollo al marsala con tagliatelle e spinaci","steps":["Portare a bollore una pentola capiente di acqua salata per la pasta.","Battere i pezzi di pollo a 1 cm di spessore, condirli e infarinarli leggermente.","Cuocere il pollo nell''olio a fuoco medio-alto 3 min per lato finché è dorato e cotto, poi metterlo da parte.","Rosolare i funghi nella stessa padella per 5 min, poi aggiungere l''aglio per 30 secondi.","Cuocere le tagliatelle come indicato sulla confezione, circa 8 min.","Sfumare i funghi con il marsala per 2 min, aggiungere il brodo e sobbollire 3 min finché la salsa è leggermente sciropposa.","Rimettere il pollo per 1-2 min, poi mantecare con il burro a fuoco spento.","Scolare la pasta, mescolarvi gli spinaci finché appassiscono e servire con il pollo, la salsa ai funghi e il prezzemolo."]}}'::jsonb),
  ('bb33dad4-b7b9-5152-8e07-42e7fc9d9b6b'::uuid, '{"fr":{"title":"Riz a djej (poulet et riz aux vermicelles libanais), fruits secs grillés et salade","steps":["Cuire le poulet à couvert dans le bouillon avec le bâton de cannelle, le laurier et la cardamome 15 min, jusqu''à cuisson à cœur.","Pendant ce temps, faire revenir les vermicelles dans l''huile à feu moyen 2 min en remuant, jusqu''à ce qu''ils soient bien dorés.","Ajouter le riz, le piment de la Jamaïque, la cannelle moulue et du poivre, puis verser 300 ml du bouillon chaud du poulet.","Couvrir et cuire le riz à feu doux 15 min, puis le laisser gonfler hors du feu 3 min.","Faire griller les amandes et les pignons à sec 2 à 3 min jusqu''à ce qu''ils soient dorés.","Mélanger la tomate, le concombre et le persil avec le jus de citron et une pincée de sel.","Sortir le poulet, l''effilocher, l''assaisonner de sel et d''un peu de piment de la Jamaïque et l''humidifier d''une cuillerée de bouillon.","Disposer le poulet sur le riz, parsemer de fruits secs et servir avec la salade et le yaourt."]},"it":{"title":"Riz a djej (pollo e riso con vermicelli alla libanese) con frutta secca tostata e insalata","steps":["Cuocere il pollo coperto nel brodo con la stecca di cannella, l''alloro e il cardamomo per 15 min, finché è cotto.","Nel frattempo tostare i vermicelli nell''olio a fuoco medio per 2 min, mescolando, finché sono ben dorati.","Unire il riso, il pimento, la cannella in polvere e abbondante pepe, poi versare 300 ml del brodo caldo del pollo.","Coprire e cuocere il riso a fuoco basso per 15 min, poi lasciarlo riposare fuori dal fuoco 3 min.","Tostare mandorle e pinoli in padella asciutta per 2-3 min finché sono dorati.","Condire pomodoro, cetriolo e prezzemolo con il succo di limone e un pizzico di sale.","Togliere il pollo, sfilacciarlo, condirlo con sale e un po'' di pimento e bagnarlo con un cucchiaio di brodo.","Disporre il pollo sul riso, cospargere di frutta secca e servire con l''insalata e lo yogurt."]}}'::jsonb),
  ('c89ba93f-ed33-576d-9ff1-98d36515c932'::uuid, '{"fr":{"title":"Poulet hunter''s (lard, sauce barbecue et cheddar), potatoes au air fryer et petits pois","steps":["Préchauffer le four à 200 °C.","Mélanger les quartiers de pommes de terre avec l''huile, le paprika et du sel et les cuire au air fryer à 200 °C pendant 20 à 22 min en secouant deux fois, jusqu''à ce qu''ils soient dorés et croustillants.","Assaisonner les blancs de poulet, les enrouler de tranches de lard et les poser jointure dessous sur une plaque recouverte de papier.","Cuire le poulet 18 min au four jusqu''à ce que le lard soit croustillant et le poulet presque cuit.","Napper le poulet de sauce barbecue, couvrir de cheddar et cuire encore 5 min jusqu''à ce que ça bouillonne et que le poulet soit cuit (75 °C à cœur).","Cuire les petits pois 3 min dans l''eau salée et les égoutter.","Servir le poulet avec les potatoes et les petits pois."]},"it":{"title":"Pollo hunter''s (pancetta, salsa barbecue e cheddar) con spicchi di patate in friggitrice ad aria e piselli","steps":["Scaldare il forno a 200 °C.","Condire gli spicchi di patate con olio, paprika e sale e cuocerli in friggitrice ad aria a 200 °C per 20-22 min, scuotendo due volte, finché sono dorati e croccanti.","Condire i petti di pollo, avvolgerli nelle fette di pancetta e disporli con la chiusura verso il basso su una teglia foderata.","Cuocere il pollo in forno per 18 min finché la pancetta è croccante e il pollo quasi cotto.","Coprire il pollo con la salsa barbecue e il cheddar e cuocere altri 5 min finché bolle e il pollo è cotto (75 °C al cuore).","Lessare i piselli in acqua salata per 3 min e scolarli.","Servire il pollo con gli spicchi di patate e i piselli."]}}'::jsonb),
  ('80957d70-d4e9-5143-b879-cbd5c4ce5d2e'::uuid, '{"fr":{"title":"Tajine de poulet aux pommes de terre et petits pois","steps":["Enrober le poulet de gingembre, de curcuma, de poivre, de safran et d''une pincée de sel.","Faire revenir l''oignon et l''ail dans l''huile dans une sauteuse ou un tajine à feu moyen 3 min, ajouter le poulet et le tourner dans les épices 3 min, puis le réserver.","Ajouter les pommes de terre et l''eau, couvrir et mijoter 10 min jusqu''à ce qu''elles soient presque tendres.","Remettre le poulet avec les petits pois, la moitié des herbes, le citron confit et les olives, couvrir et mijoter 6 à 7 min jusqu''à ce que le poulet soit cuit.","Découvrir et laisser réduire la sauce 1 à 2 min, puis servir parsemé du reste des herbes."]},"it":{"title":"Tajine di pollo con patate e piselli","steps":["Condire il pollo con zenzero, curcuma, pepe, zafferano e un pizzico di sale.","Soffriggere cipolla e aglio nell''olio in una padella larga o in un tajine a fuoco medio per 3 min, aggiungere il pollo e girarlo nelle spezie per 3 min, poi toglierlo.","Aggiungere le patate e l''acqua, coprire e sobbollire 10 min finché le patate sono quasi tenere.","Rimettere il pollo con i piselli, metà delle erbe, il limone confit e le olive, coprire e sobbollire 6-7 min finché il pollo è cotto.","Scoprire e far restringere il sugo 1-2 min, poi servire con il resto delle erbe."]}}'::jsonb),
  ('546e41d8-88ea-522b-8bd4-783564dc0901'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet piri-piri au air fryer, riz et salade mixte","steps":["Écraser ou mixer les piments, l''ail, le paprika, l''origan, le jus de citron, le vinaigre, 2 c. à soupe d''huile et une bonne pincée de sel en une sauce piri-piri fluide.","Enrober le poulet de la moitié de la sauce et le cuire au air fryer à 200 °C pendant 16 à 18 min en le retournant à mi-cuisson et en le badigeonnant d''un peu de sauce, jusqu''à ce qu''il soit grillé et cuit.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Mélanger les tomates, l''oignon et la salade avec l''huile, un trait de vinaigre et du sel.","Servir le poulet sur le riz avec la salade et le reste de sauce à côté."]},"it":{"title":"Sovracosce di pollo piri-piri in friggitrice ad aria con riso e insalata mista","steps":["Pestare o frullare peperoncini, aglio, paprika, origano, succo di limone, aceto, 2 cucchiai d''olio e un bel pizzico di sale in una salsa piri-piri fluida.","Condire il pollo con metà della salsa e cuocerlo in friggitrice ad aria a 200 °C per 16-18 min, girandolo a metà e spennellandolo con altra salsa, finché è abbrustolito e cotto.","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Condire pomodori, cipolla e lattuga con l''olio, un goccio d''aceto e sale.","Servire il pollo sul riso con l''insalata e la salsa rimasta a parte."]}}'::jsonb),
  ('79f06879-912e-5951-aac6-7802f2f96566'::uuid, '{"fr":{"title":"Poulet al chilindrón (poivrons, tomate et jambon serrano) et pain de campagne","steps":["Assaisonner le poulet et le dorer dans l''huile dans une sauteuse à feu moyen-vif 4 min, puis le réserver.","Ajouter le jambon, l''oignon et les poivrons et cuire 5 min jusqu''à ce qu''ils s''attendrissent, puis ajouter l''ail et le paprika 30 secondes.","Verser le vin et laisser bouillonner 1 min.","Ajouter les tomates, le laurier et le poulet, couvrir et mijoter 12 min en remuant de temps en temps, jusqu''à ce que le poulet soit tendre et la sauce épaisse.","Rectifier le sel et servir avec le persil et le pain pour saucer."]},"it":{"title":"Pollo al chilindrón (peperoni, pomodoro e prosciutto serrano) con pane casereccio","steps":["Condire il pollo e rosolarlo nell''olio in una padella larga a fuoco medio-alto per 4 min, poi toglierlo.","Aggiungere prosciutto, cipolla e peperoni e cuocere 5 min finché si ammorbidiscono, poi unire aglio e paprika per 30 secondi.","Sfumare con il vino per 1 min.","Aggiungere i pomodori, l''alloro e il pollo, coprire e sobbollire 12 min mescolando ogni tanto, finché il pollo è tenero e il sugo denso.","Regolare di sale e servire con prezzemolo e il pane per fare la scarpetta."]}}'::jsonb),
  ('504053fb-d532-5d57-a3af-20c5bba801ee'::uuid, '{"fr":{"title":"Rouleaux musakhan au air fryer (poulet au sumac et oignons), yaourt et salade","steps":["Cuire les oignons dans 2 c. à soupe d''huile avec une pincée de sel à feu moyen 10 à 12 min en remuant souvent, jusqu''à ce qu''ils soient fondants et doux sans croustiller.","Faire griller les pignons à sec 2 min et les réserver.","Ajouter le poulet aux oignons avec le piment de la Jamaïque, la cannelle, la cardamome et le poivre et cuire 6 à 7 min jusqu''à cuisson complète.","Incorporer le sumac et les pignons et rectifier le sel.","Répartir la farce le long du bord de chaque galette, rabattre les côtés et rouler bien serré.","Badigeonner les rouleaux du reste d''huile et les cuire au air fryer, jointure dessous, à 190 °C pendant 6 à 7 min jusqu''à ce qu''ils soient dorés et croustillants.","Mélanger la tomate et le concombre avec le jus de citron, le persil et du sel, et servir avec les rouleaux et le yaourt, saupoudré d''un peu de sumac."]},"it":{"title":"Rotoli musakhan in friggitrice ad aria (pollo al sommacco e cipolle) con yogurt e insalata","steps":["Cuocere le cipolle in 2 cucchiai d''olio con un pizzico di sale a fuoco medio per 10-12 min, mescolando spesso, finché sono morbide e dolci ma non croccanti.","Tostare i pinoli in padella asciutta per 2 min e metterli da parte.","Unire il pollo alle cipolle con pimento, cannella, cardamomo e pepe e cuocere 6-7 min finché è cotto.","Aggiungere il sommacco e i pinoli e regolare di sale.","Distribuire il ripieno lungo il bordo di ogni piadina, ripiegare i lati e arrotolare stretto.","Spennellare i rotoli con l''olio rimasto e cuocerli in friggitrice ad aria con la chiusura in basso a 190 °C per 6-7 min finché sono dorati e croccanti.","Condire pomodoro e cetriolo con succo di limone, prezzemolo e sale e servire con i rotoli e lo yogurt, spolverizzato di altro sommacco."]}}'::jsonb),
  ('1186e3b2-9887-52a7-90d7-c900d587fc90'::uuid, '{"fr":{"title":"Couscous tunisien au poulet, pois chiches, carottes et courgette","steps":["Faire dorer le poulet et l''oignon dans l''huile dans une sauteuse à feu moyen-vif 5 min.","Ajouter l''ail, le concentré de tomate, la harissa, le paprika, le carvi et la coriandre et faire revenir 1 min jusqu''à ce que le concentré fonce.","Ajouter les carottes et le bouillon, couvrir et mijoter 8 min.","Ajouter la courgette et les pois chiches et mijoter à découvert 8 min jusqu''à ce que les légumes soient tendres et le poulet cuit.","Mettre la semoule dans un saladier avec l''huile et une pincée de sel, verser 200 ml du bouillon rouge chaud de la sauteuse, couvrir 5 min puis égrainer à la fourchette.","Servir la semoule en bols, garnie du poulet, des légumes et d''un peu plus de bouillon, avec du persil."]},"it":{"title":"Cuscus tunisino di pollo con ceci, carote e zucchina","steps":["Rosolare pollo e cipolla nell''olio in una padella larga a fuoco medio-alto per 5 min.","Unire aglio, concentrato di pomodoro, harissa, paprika, carvi e coriandolo e soffriggere 1 min finché il concentrato scurisce.","Aggiungere le carote e il brodo, coprire e sobbollire 8 min.","Aggiungere la zucchina e i ceci e sobbollire scoperto 8 min finché le verdure sono tenere e il pollo cotto.","Mettere il cuscus in una ciotola con l''olio e un pizzico di sale, versarvi 200 ml del brodo rosso caldo della padella, coprire 5 min e sgranare con una forchetta.","Servire il cuscus nelle ciotole con pollo, verdure e altro brodo, con prezzemolo."]}}'::jsonb),
  ('4011ea03-d3f9-5415-8dfb-79349ee13da5'::uuid, '{"fr":{"title":"Poulet au vinaigre, riz et carottes glacées","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Mettre les carottes dans une petite casserole avec le beurre, le sucre, une pincée de sel et de l''eau à hauteur, et cuire 12 à 15 min à gros bouillons jusqu''à évaporation et qu''elles soient glacées.","Assaisonner le poulet et le dorer dans l''huile à feu moyen-vif 4 min de chaque côté, puis le réserver.","Faire revenir les échalotes et l''ail 2 min, puis verser le vinaigre et laisser réduire de moitié, environ 2 min.","Ajouter le vin, le concentré, les tomates et le bouillon, remettre le poulet, couvrir et mijoter 8 min jusqu''à cuisson complète.","Sortir le poulet, faire bouillir la sauce 2 min jusqu''à ce qu''elle soit sirupeuse, puis y fouetter le beurre hors du feu.","Servir le poulet et la sauce avec le riz et les carottes, parsemé d''estragon."]},"it":{"title":"Pollo all''aceto con riso e carote glassate","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Mettere le carote in un pentolino con burro, zucchero, un pizzico di sale e acqua a filo e cuocere a fuoco vivace 12-15 min finché l''acqua evapora e sono glassate.","Condire il pollo e rosolarlo nell''olio a fuoco medio-alto 4 min per lato, poi toglierlo.","Appassire scalogni e aglio 2 min, poi versare l''aceto e lasciarlo ridurre della metà, circa 2 min.","Unire vino, concentrato, pomodori e brodo, rimettere il pollo, coprire e sobbollire 8 min finché è cotto.","Togliere il pollo, far bollire il sugo 2 min finché è sciropposo, poi montarlo con il burro a fuoco spento.","Servire il pollo con il sugo, il riso e le carote, con dragoncello."]}}'::jsonb),
  ('4bb1f1b5-a354-5343-a11e-facbac16796d'::uuid, '{"fr":{"title":"Kotopoulo lemonato (poulet au citron), pommes de terre au citron au air fryer et salade grecque","steps":["Mélanger les pommes de terre avec 1 c. à soupe d''huile, la moitié du jus de citron, 1 c. à café d''origan et du sel, et les cuire au air fryer à 200 °C pendant 22 min en secouant deux fois, jusqu''à ce qu''elles soient dorées et tendres.","Frotter le poulet avec l''ail, le zeste, la moutarde, le reste d''origan, du sel et du poivre.","Cuire le poulet dans 2 c. à café d''huile à feu moyen 5 à 6 min de chaque côté jusqu''à ce qu''il soit doré et cuit.","Verser le bouillon et le reste du jus de citron et laisser bouillonner 2 min en retournant le poulet, jusqu''à une sauce brillante.","Disposer la tomate, le concombre, l''oignon et les olives dans un saladier, poser la feta dessus, saupoudrer d''origan et arroser du vinaigre et du reste d''huile.","Servir le poulet et sa sauce au citron avec les pommes de terre et la salade."]},"it":{"title":"Kotopoulo lemonato (pollo al limone) con patate al limone in friggitrice ad aria e insalata greca","steps":["Condire le patate con 1 cucchiaio d''olio, metà del succo di limone, 1 cucchiaino di origano e sale e cuocerle in friggitrice ad aria a 200 °C per 22 min, scuotendo due volte, finché sono dorate e tenere.","Massaggiare il pollo con aglio, scorza, senape, il resto dell''origano, sale e pepe.","Cuocere il pollo in 2 cucchiaini d''olio a fuoco medio 5-6 min per lato finché è dorato e cotto.","Versare il brodo e il resto del succo di limone e lasciar bollire 2 min girando il pollo, finché il sugo è lucido.","Disporre pomodoro, cetriolo, cipolla e olive in una ciotola, adagiarvi sopra la feta, cospargere di origano e condire con l''aceto e l''olio rimasto.","Servire il pollo con il sugo al limone, le patate e l''insalata."]}}'::jsonb),
  ('96f7ec19-afcf-5e6a-9d55-7b131db9d31d'::uuid, '{"fr":{"title":"Ragù blanc de poulet aux rigatoni","steps":["Faire revenir l''oignon, la carotte et le céleri dans l''huile à feu moyen 6 min jusqu''à ce qu''ils soient tendres.","Ajouter le poulet, l''ail, le romarin et la sauge et cuire 5 min en émiettant la viande, jusqu''à ce qu''elle ne soit plus rose et commence à dorer.","Verser le vin et le laisser s''évaporer, environ 2 min.","Ajouter le bouillon, assaisonner et mijoter à demi-couvert 8 à 10 min jusqu''à ce que le ragù soit moelleux sans être liquide.","Pendant ce temps, cuire les rigatoni dans l''eau bouillante salée 1 min de moins que le temps indiqué.","Égoutter les pâtes en gardant une tasse d''eau de cuisson et les mélanger au ragù avec la moitié du parmesan et un peu d''eau jusqu''à ce qu''elles soient brillantes.","Servir avec le reste du parmesan, du poivre et du persil."]},"it":{"title":"Rigatoni al ragù bianco di pollo","steps":["Soffriggere cipolla, carota e sedano nell''olio a fuoco medio per 6 min finché sono morbidi.","Aggiungere il pollo, l''aglio, il rosmarino e la salvia e cuocere 5 min sgranando la carne, finché non è più rosa e inizia a colorire.","Sfumare con il vino e lasciarlo evaporare, circa 2 min.","Aggiungere il brodo, regolare di sale e pepe e sobbollire semicoperto 8-10 min finché il ragù è morbido ma non brodoso.","Nel frattempo cuocere i rigatoni in acqua bollente salata 1 min meno del tempo indicato.","Scolare la pasta tenendo una tazza d''acqua di cottura e saltarla nel ragù con metà del parmigiano e un goccio d''acqua finché è lucida.","Servire con il resto del parmigiano, pepe nero e prezzemolo."]}}'::jsonb),
  ('e7ba4eea-8b8a-5979-8259-c61a2df7bc23'::uuid, '{"fr":{"title":"Poulet Kiev au air fryer, pommes de terre nouvelles et brocoli","steps":["Écraser le beurre froid avec l''ail, le persil, le zeste de citron et une pincée de sel, puis le façonner en 2 petits boudins.","Entailler une poche profonde dans le côté épais de chaque blanc sans le transpercer, y glisser un boudin de beurre et refermer en pressant.","Assaisonner le poulet, le fariner, le tremper dans l''œuf puis le presser dans le panko pour bien l''enrober, en scellant l''ouverture avec un peu plus de chapelure.","Arroser d''huile et cuire au air fryer à 190 °C pendant 18 min en retournant délicatement à mi-cuisson, jusqu''à ce qu''il soit doré et cuit (75 °C au plus épais).","Pendant ce temps, cuire les pommes de terre 15 min dans l''eau salée en ajoutant le brocoli pour les 4 dernières minutes, puis égoutter.","Laisser reposer les Kiev 2 min et servir avec les pommes de terre, le brocoli et des quartiers de citron, en nappant du beurre à l''ail qui s''en échappe."]},"it":{"title":"Pollo Kiev in friggitrice ad aria con patate novelle e broccoli","steps":["Lavorare il burro freddo con aglio, prezzemolo, scorza di limone e un pizzico di sale, poi formare 2 piccoli cilindri.","Praticare una tasca profonda nel lato spesso di ogni petto senza bucarlo, inserire un cilindro di burro e premere per chiudere.","Condire il pollo, infarinarlo, passarlo nell''uovo e premerlo nel panko per impanarlo bene, sigillando l''apertura con altro pangrattato.","Irrorare con l''olio e cuocere in friggitrice ad aria a 190 °C per 18 min, girando con delicatezza a metà, finché è dorato e cotto (75 °C nel punto più spesso).","Nel frattempo lessare le patate in acqua salata per 15 min aggiungendo i broccoli negli ultimi 4 min, poi scolare.","Far riposare i Kiev 2 min e servire con patate, broccoli e spicchi di limone, versando sopra il burro all''aglio che fuoriesce."]}}'::jsonb),
  ('21214849-426e-5a20-85fc-4f4df2e36c03'::uuid, '{"fr":{"title":"Pollo en pepitoria (sauce aux amandes et safran), riz et haricots verts","steps":["Cuire l''œuf 10 min pour qu''il soit dur, le refroidir dans l''eau froide et l''écaler.","Rincer le riz et le cuire à couvert dans 300 ml d''eau salée 12 min en posant les haricots verts dessus pour les 6 dernières minutes, puis laisser reposer hors du feu.","Faire dorer les amandes, le pain et l''ail dans l''huile à feu moyen 2 min, puis les mettre dans le bol d''un mixeur.","Assaisonner le poulet et le dorer 4 min dans la même poêle, puis ajouter l''oignon et cuire 4 min jusqu''à ce qu''il soit tendre.","Verser le xérès et laisser bouillonner 1 min, puis ajouter le bouillon et le laurier et mijoter 5 min.","Mixer les amandes, le pain et l''ail avec le safran, le jaune d''œuf et une louche de bouillon en une picada lisse.","Incorporer la picada dans la poêle et mijoter 3 à 4 min jusqu''à ce que la sauce épaississe et que le poulet soit cuit.","Servir avec le riz et les haricots, parsemé du blanc d''œuf haché et de persil."]},"it":{"title":"Pollo en pepitoria (salsa di mandorle e zafferano) con riso e fagiolini","steps":["Rassodare l''uovo per 10 min, raffreddarlo in acqua fredda e sgusciarlo.","Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua salata per 12 min, adagiandovi sopra i fagiolini negli ultimi 6 min, poi lasciar riposare fuori dal fuoco.","Dorare mandorle, pane e aglio nell''olio a fuoco medio per 2 min, poi metterli nel bicchiere del frullatore.","Condire il pollo e rosolarlo 4 min nella stessa padella, poi aggiungere la cipolla e cuocere 4 min finché è morbida.","Sfumare con lo sherry per 1 min, poi aggiungere brodo e alloro e sobbollire 5 min.","Frullare mandorle, pane e aglio con lo zafferano, il tuorlo e un mestolo di brodo fino a una picada liscia.","Unire la picada in padella e sobbollire 3-4 min finché la salsa si addensa e il pollo è cotto.","Servire con riso e fagiolini, con l''albume tritato e il prezzemolo."]}}'::jsonb),
  ('4a614931-5ab2-5e8b-8931-0c77d0f912cb'::uuid, '{"fr":{"title":"Pide au poulet haché au air fryer et salade du berger","steps":["Faire revenir l''oignon et le poivron vert dans l''huile 3 min, ajouter le poulet et cuire 4 min en l''émiettant, puis ajouter la tomate, la pâte de poivron, le cumin, la moitié du piment d''Alep, du sel et du poivre et cuire 2 min jusqu''à ce que la farce soit presque sèche. Ajouter la moitié du persil.","Couper la pâte en 4 et étirer chaque morceau en ovale d''environ 22 x 10 cm.","Étaler la farce au centre de chaque ovale, replier les longs bords sur la farce et pincer les extrémités en pointe pour former des barques.","Badigeonner les bords de pâte d''œuf battu.","Cuire les pides deux par deux sur du papier cuisson au air fryer à 200 °C pendant 7 à 8 min jusqu''à ce que la pâte soit dorée et croustillante dessous.","Mélanger la tomate, le concombre, l''oignon rouge et le reste du persil avec le jus de citron, l''huile, le reste du piment d''Alep et du sel.","Couper les pides en tranches et servir avec la salade et le yaourt."]},"it":{"title":"Pide di pollo macinato in friggitrice ad aria con insalata del pastore","steps":["Soffriggere cipolla e peperone verde nell''olio per 3 min, aggiungere il pollo e cuocere 4 min sgranandolo, poi unire pomodoro, pasta di peperoni, cumino, metà del peperoncino di Aleppo, sale e pepe e cuocere 2 min finché il ripieno è quasi asciutto. Unire metà del prezzemolo.","Dividere l''impasto in 4 pezzi e stendere ognuno in un ovale di circa 22 x 10 cm.","Distribuire il ripieno al centro di ogni ovale, ripiegare i bordi lunghi sopra il ripieno e pizzicare le estremità a punta per formare delle barchette.","Spennellare i bordi con l''uovo sbattuto.","Cuocere le pide due alla volta su carta forno in friggitrice ad aria a 200 °C per 7-8 min finché l''impasto è dorato e croccante sotto.","Condire pomodoro, cetriolo, cipolla rossa e il resto del prezzemolo con succo di limone, olio, il resto del peperoncino di Aleppo e sale.","Tagliare le pide a fette e servire con l''insalata e lo yogurt."]}}'::jsonb),
  ('b96227fc-a4ea-4f49-ae27-f7234eccf631'::uuid, '{"fr":{"title":"Phở gà (soupe vietnamienne de nouilles au poulet)","steps":["Faire noircir les moitiés d''oignon et le gingembre côté coupé dans une marmite à sec à feu vif pendant 5 min, jusqu''à ce qu''ils soient brûlés par endroits.","Ajouter l''anis étoilé, les graines de coriandre et la cannelle, torréfier 30 s, puis verser le bouillon et porter à ébullition.","Plonger les blancs de poulet, couvrir et frémir très doucement 12 à 14 min jusqu''à cuisson à cœur (plus de rose au plus épais), puis les sortir et les laisser reposer.","Pendant ce temps, cuire les nouilles de riz dans une casserole d''eau bouillante selon le paquet (en général 4 à 6 min), égoutter et rincer rapidement à l''eau chaude.","Assaisonner le bouillon avec la sauce de poisson et le sucre, frémir encore 2 min, puis le filtrer et le remettre à gros bouillons.","Trancher finement le poulet dans le sens contraire des fibres.","Répartir les nouilles dans des bols creux, ajouter le poulet et la moitié des germes de soja, puis verser le bouillon bouillant.","Parsemer d''oignon nouveau et servir avec la coriandre, le basilic thaï, le piment, les quartiers de citron vert et le reste des germes de soja à ajouter à table."]},"it":{"title":"Phở gà (zuppa vietnamita di noodles al pollo)","steps":["Abbrustolire le metà di cipolla e lo zenzero dal lato tagliato in una pentola asciutta a fuoco vivo per 5 min, finché sono anneriti a chiazze.","Aggiungere anice stellato, semi di coriandolo e cannella, tostare 30 s, poi versare il brodo e portare a bollore.","Immergere i petti di pollo, coprire e sobbollire molto dolcemente 12-14 min finché cotti (niente rosa nel punto più spesso), poi toglierli e farli riposare.","Nel frattempo cuocere i noodles di riso in una pentola d''acqua bollente come indicato sulla confezione (di solito 4-6 min), scolarli e sciacquarli rapidamente in acqua calda.","Insaporire il brodo con salsa di pesce e zucchero, sobbollire altri 2 min, poi filtrarlo e riportarlo a bollore vivace.","Tagliare il pollo a fettine sottili contro fibra.","Dividere i noodles in ciotole fonde, aggiungere il pollo e metà dei germogli di soia e versare sopra il brodo bollente.","Completare con il cipollotto e servire con coriandolo, basilico thai, peperoncino, spicchi di lime e i germogli rimasti da aggiungere a tavola."]}}'::jsonb),
  ('5432ab66-f6b2-4acd-b22f-ec9a21814ede'::uuid, '{"fr":{"title":"Curry panang au poulet, riz jasmin et haricots verts","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Chauffer l''huile et 4 c. à soupe de la partie la plus épaisse du lait de coco dans un wok à feu moyen environ 2 min, jusqu''à ce qu''il bouillonne et que le gras commence à se séparer.","Y faire revenir la pâte de curry 1 à 2 min en remuant, jusqu''à ce qu''elle embaume et fonce légèrement.","Ajouter le poulet et le faire sauter 3 min jusqu''à ce qu''il ne soit plus rose à l''extérieur.","Verser le reste du lait de coco, ajouter les haricots verts, la sauce de poisson, le sucre et la moitié des feuilles de combava, puis mijoter 5 min.","Ajouter le poivron et mijoter encore 3 min, jusqu''à ce que le poulet soit cuit et que la sauce nappe la cuillère.","Servir sur le riz, garni du reste des feuilles de combava, des cacahuètes, du basilic thaï et du piment."]},"it":{"title":"Curry panang di pollo con riso jasmine e fagiolini","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Scaldare l''olio e 4 cucchiai della parte più densa del latte di cocco in un wok a fuoco medio per circa 2 min, finché sobbolle e il grasso comincia a separarsi.","Soffriggervi la pasta di curry 1-2 min mescolando, finché è profumata e leggermente più scura.","Aggiungere il pollo e saltarlo 3 min finché non è più rosa all''esterno.","Versare il resto del latte di cocco, aggiungere fagiolini, salsa di pesce, zucchero e metà delle foglie di lime e sobbollire 5 min.","Aggiungere il peperone e sobbollire altri 3 min, finché il pollo è cotto e la salsa vela il cucchiaio.","Servire sul riso con le foglie di lime rimaste, le arachidi, il basilico thai e il peperoncino."]}}'::jsonb),
  ('1dbeb2e6-6a34-4c40-a9cc-75487a348f8c'::uuid, '{"fr":{"title":"Poulet aigre-doux au air fryer, poivrons, ananas et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Mélanger le poulet avec une pincée de sel et 1 c. à café de sauce soja, puis avec la fécule et la moitié de l''huile pour bien enrober chaque morceau.","Cuire le poulet au air fryer à 200 °C pendant 12 min en une seule couche, en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et cuit.","Pendant ce temps, fouetter le ketchup, le vinaigre, le sucre, la sauce soja, le jus d''ananas, 3 c. à soupe d''eau et la fécule pour la sauce.","Faire sauter l''oignon, les poivrons et l''ail dans le reste d''huile dans un wok très chaud pendant 3 min, jusqu''à ce qu''ils soient juste tendres mais encore croquants.","Ajouter l''ananas 1 min, puis verser la sauce et laisser bouillonner 1 min jusqu''à ce qu''elle épaississe et brille.","Ajouter le poulet, bien l''enrober et servir aussitôt sur le riz."]},"it":{"title":"Pollo in agrodolce in friggitrice ad aria con peperoni, ananas e riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Condire il pollo con un pizzico di sale e 1 cucchiaino di salsa di soia, poi con l''amido e metà dell''olio finché ogni pezzo è ricoperto.","Cuocere il pollo in friggitrice ad aria a 200 °C per 12 min in un solo strato, scuotendo a metà, finché è dorato e cotto.","Nel frattempo sbattere ketchup, aceto, zucchero, salsa di soia, succo d''ananas, 3 cucchiai d''acqua e l''amido per la salsa.","Saltare cipolla, peperoni e aglio nell''olio rimasto in un wok rovente per 3 min, finché appena ammorbiditi ma ancora croccanti.","Aggiungere l''ananas per 1 min, poi versare la salsa e farla bollire 1 min finché densa e lucida.","Unire il pollo, mescolare per ricoprirlo e servire subito sul riso."]}}'::jsonb),
  ('8113b4b3-f76a-494e-a5c5-d84d0356e3d6'::uuid, '{"fr":{"title":"Chow mein au poulet, chou et germes de soja","steps":["Mélanger le poulet avec 1 c. à café de sauce soja, 1 c. à café de vin de riz et la fécule.","Cuire les nouilles dans l''eau bouillante selon le paquet (en général 3 à 4 min), égoutter, rincer à l''eau froide, bien secouer et mélanger avec l''huile de sésame.","Mélanger la sauce d''huître, la sauce soja, la sauce soja foncée, le reste du vin de riz, le sucre, une bonne pincée de poivre blanc et 2 c. à soupe d''eau.","Faire sauter le poulet dans 1 c. à soupe d''huile dans un wok très chaud 3 à 4 min jusqu''à cuisson complète, puis le réserver sur une assiette.","Ajouter le reste d''huile, puis l''ail, la carotte et le chou, et faire sauter 2 min.","Ajouter les nouilles et la sauce et mélanger à feu vif 2 min, jusqu''à ce que les nouilles soient bien colorées et commencent à croustiller par endroits.","Remettre le poulet avec les germes de soja et les oignons nouveaux, faire sauter encore 1 min et servir."]},"it":{"title":"Chow mein di pollo con cavolo e germogli di soia","steps":["Condire il pollo con 1 cucchiaino di salsa di soia, 1 cucchiaino di vino di riso e l''amido.","Cuocere i noodles in acqua bollente come indicato sulla confezione (di solito 3-4 min), scolarli, sciacquarli in acqua fredda, sgocciolarli bene e condirli con l''olio di sesamo.","Mescolare salsa d''ostrica, salsa di soia, salsa di soia scura, il resto del vino di riso, lo zucchero, un bel pizzico di pepe bianco e 2 cucchiai d''acqua.","Saltare il pollo in 1 cucchiaio d''olio in un wok rovente per 3-4 min finché cotto, poi metterlo da parte su un piatto.","Aggiungere l''olio rimasto, poi aglio, carota e cavolo e saltare 2 min.","Unire noodles e salsa e saltare a fuoco vivo per 2 min, finché i noodles sono colorati in modo uniforme e iniziano a diventare croccanti qua e là.","Rimettere il pollo con germogli di soia e cipollotti, saltare ancora 1 min e servire."]}}'::jsonb),
  ('7a3a5822-8944-4bae-8473-493e30aee3a1'::uuid, '{"fr":{"title":"Dak kalguksu (soupe coréenne de nouilles au poulet)","steps":["Porter le bouillon à ébullition avec l''oignon et les 2 gousses d''ail écrasées, ajouter le poulet, couvrir et frémir doucement 12 à 14 min jusqu''à cuisson complète.","Pendant ce temps, mélanger la sauce soja, le gochugaru, l''ail râpé, la moitié de l''oignon nouveau, l''huile et les graines de sésame pour la sauce.","Sortir le poulet et l''effilocher avec deux fourchettes.","Ajouter la pomme de terre au bouillon et frémir 5 min.","Secouer les nouilles pour ôter l''excès de farine, les ajouter avec la courgette et frémir 3 à 4 min, jusqu''à ce que les nouilles soient tendres et la pomme de terre fondante.","Remettre le poulet et saler le bouillon à son goût.","Servir dans des bols creux, parsemer du reste d''oignon nouveau et accompagner de la sauce à mélanger."]},"it":{"title":"Dak kalguksu (zuppa coreana di noodles al pollo)","steps":["Portare a bollore il brodo con la cipolla e i 2 spicchi d''aglio schiacciati, aggiungere il pollo, coprire e sobbollire dolcemente 12-14 min finché cotto.","Nel frattempo mescolare salsa di soia, gochugaru, aglio grattugiato, metà del cipollotto, olio e semi di sesamo per la salsa.","Togliere il pollo e sfilacciarlo con due forchette.","Aggiungere la patata al brodo e sobbollire 5 min.","Scuotere i noodles per togliere la farina in eccesso, unirli con la zucchina e sobbollire 3-4 min, finché i noodles sono teneri e la patata morbida.","Rimettere il pollo e regolare di sale il brodo.","Servire in ciotole fonde con il cipollotto rimasto e accompagnare con la salsa da mescolare."]}}'::jsonb),
  ('91ab3b25-463b-475e-a3b6-a6a44ba4b226'::uuid, '{"fr":{"title":"Chicken 65 au air fryer, riz au citron et raïta au concombre","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée avec 0,25 c. à café de curcuma à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Mélanger le poulet avec le yaourt, le gingembre, l''ail, le piment, le curcuma, le garam masala et une bonne pincée de sel, puis avec la fécule et la moitié de l''huile pour qu''il soit bien enrobé.","Cuire au air fryer à 200 °C pendant 12 à 14 min en une seule couche, en secouant à mi-cuisson, jusqu''à ce que les bords soient croustillants et le poulet cuit.","Pendant ce temps, mélanger le concombre au yaourt avec une pincée de sel et de cumin, et assaisonner la tomate et l''oignon rouge d''un filet de citron.","Chauffer le reste d''huile dans une poêle et y faire éclater les graines de moutarde, puis ajouter les cacahuètes, les feuilles de curry et le piment vert 1 min.","Mélanger à la fourchette la moitié de ce mélange et le reste du jus de citron au riz.","Faire sauter le poulet 1 min dans la poêle avec le reste du mélange et servir avec le riz au citron, la raïta et la salade de tomate."]},"it":{"title":"Chicken 65 in friggitrice ad aria con riso al limone e raita di cetriolo","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata con 0,25 cucchiaino di curcuma a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Mescolare il pollo con yogurt, zenzero, aglio, peperoncino, curcuma, garam masala e un bel pizzico di sale, poi con l''amido e metà dell''olio finché ben ricoperto.","Cuocere in friggitrice ad aria a 200 °C per 12-14 min in un solo strato, scuotendo a metà, finché i bordi sono croccanti e il pollo è cotto.","Nel frattempo unire il cetriolo allo yogurt con un pizzico di sale e cumino e condire pomodoro e cipolla rossa con un po'' di limone.","Scaldare l''olio rimasto in una padella e farvi scoppiettare i semi di senape, poi aggiungere arachidi, foglie di curry e peperoncino verde per 1 min.","Mescolare con una forchetta metà del soffritto e il resto del succo di limone nel riso.","Saltare il pollo 1 min in padella con il soffritto rimasto e servire con il riso al limone, la raita e l''insalata di pomodoro."]}}'::jsonb),
  ('b09ea84f-1679-4fbd-8a54-1faf5a24c7b1'::uuid, '{"fr":{"title":"Bánh mì au poulet citronnelle au air fryer, carotte et daikon marinés","steps":["Dissoudre le sucre du pickle et une pincée de sel dans le vinaigre et 3 c. à soupe d''eau tiède, ajouter la carotte et le daikon et laisser mariner pendant la cuisson.","Mélanger la citronnelle, l''ail, la sauce de poisson, la sauce soja, le sucre et l''huile, et en enrober les hauts de cuisse.","Cuire les hauts de cuisse à plat au air fryer à 200 °C pendant 14 min en les retournant à mi-cuisson, jusqu''à ce qu''ils soient grillés sur les bords et cuits (75 °C à cœur).","Laisser reposer le poulet 2 min, puis le trancher.","Réchauffer les baguettes au air fryer à 180 °C pendant 2 min pour qu''elles soient croustillantes, puis les ouvrir dans la longueur.","Garnir de poulet, des pickles égouttés, de concombre, de coriandre, de piment et d''un peu de sriracha."]},"it":{"title":"Bánh mì al pollo alla citronella in friggitrice ad aria con carota e daikon in agrodolce","steps":["Sciogliere lo zucchero per il sottaceto e un pizzico di sale nell''aceto con 3 cucchiai d''acqua tiepida, aggiungere carota e daikon e lasciarli marinare durante la cottura.","Mescolare citronella, aglio, salsa di pesce, salsa di soia, zucchero e olio e ricoprirvi le cosce di pollo.","Cuocere le cosce distese in friggitrice ad aria a 200 °C per 14 min, girandole a metà, finché abbrustolite ai bordi e cotte (75 °C al cuore).","Far riposare il pollo 2 min, poi affettarlo.","Scaldare le baguette in friggitrice ad aria a 180 °C per 2 min finché croccanti, poi aprirle per il lungo.","Farcire con pollo, sottaceti scolati, cetriolo, coriandolo, peperoncino e un po'' di sriracha."]}}'::jsonb),
  ('c234f8c1-e739-4a1b-abe2-4a0cda115c49'::uuid, '{"fr":{"title":"Pad see ew au poulet et brocoli","steps":["Faire tremper les nouilles dans de l''eau très chaude selon le paquet (environ 8 à 10 min) jusqu''à ce qu''elles soient souples mais encore fermes, égoutter et mélanger avec 1 c. à café de sauce soja foncée.","Mélanger le reste de sauce soja foncée, la sauce soja, la sauce d''huître, le sucre, le vinaigre et 2 c. à soupe d''eau.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif, faire revenir l''ail 10 s, puis faire sauter le poulet 3 à 4 min jusqu''à cuisson complète.","Ajouter les tiges de brocoli, puis les fleurettes et les feuilles avec un trait d''eau, et faire sauter 2 min jusqu''à ce qu''ils soient bien verts.","Pousser le tout sur le côté, ajouter le reste d''huile, casser les œufs et les brouiller jusqu''à ce qu''ils soient juste pris.","Ajouter les nouilles et la sauce et mélanger 2 à 3 min en les laissant de temps en temps contre le wok brûlant pour qu''elles grillent par endroits.","Servir avec une pincée de poivre blanc et de piment en flocons."]},"it":{"title":"Pad see ew con pollo e broccoli","steps":["Ammollare i noodles in acqua molto calda come indicato sulla confezione (circa 8-10 min) finché morbidi ma ancora sodi, scolarli e condirli con 1 cucchiaino di salsa di soia scura.","Mescolare il resto della salsa di soia scura, la salsa di soia, la salsa d''ostrica, lo zucchero, l''aceto e 2 cucchiai d''acqua.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo, soffriggere l''aglio 10 s, poi saltare il pollo 3-4 min finché cotto.","Aggiungere i gambi di broccolo, poi le cimette e le foglie con un goccio d''acqua e saltare 2 min finché verde brillante.","Spostare tutto su un lato, aggiungere l''olio rimasto, rompere le uova e strapazzarle finché appena rapprese.","Unire noodles e salsa e saltare 2-3 min, lasciandoli ogni tanto a contatto con il wok rovente perché si abbrustoliscano qua e là.","Servire con un pizzico di pepe bianco e peperoncino in fiocchi."]}}'::jsonb),
  ('7bcf6900-1eeb-4919-8de4-c5ca6830b771'::uuid, '{"fr":{"title":"Poulet « devilled » sri-lankais au air fryer et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Mélanger le poulet avec la sauce soja, le piment en poudre et beaucoup de poivre noir, puis avec la fécule et 1 c. à café d''huile.","Cuire au air fryer à 200 °C pendant 12 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et cuit.","Pendant ce temps, mélanger le ketchup, la sauce soja, le piment en flocons, le vinaigre et 2 c. à soupe d''eau.","Chauffer le reste d''huile dans un wok à feu vif, faire revenir l''ail et le gingembre 30 s, puis l''oignon et le poivron 3 min jusqu''à ce qu''ils soient grillés sur les bords mais encore croquants.","Ajouter la tomate 1 min, puis la sauce, et laisser bouillonner 1 min.","Ajouter le poulet 1 min pour qu''il soit bien laqué et servir avec le riz."]},"it":{"title":"Pollo devilled dello Sri Lanka in friggitrice ad aria con riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Condire il pollo con salsa di soia, peperoncino in polvere e abbondante pepe nero, poi con l''amido e 1 cucchiaino d''olio.","Cuocere in friggitrice ad aria a 200 °C per 12 min, scuotendo a metà, finché dorato e cotto.","Nel frattempo mescolare ketchup, salsa di soia, peperoncino in fiocchi, aceto e 2 cucchiai d''acqua.","Scaldare l''olio rimasto in un wok a fuoco vivo, soffriggere aglio e zenzero 30 s, poi cipolla e peperone per 3 min finché abbrustoliti ai bordi ma ancora croccanti.","Aggiungere il pomodoro per 1 min, poi la salsa, e far bollire 1 min.","Unire il pollo per 1 min finché lucido e servire con il riso."]}}'::jsonb),
  ('fd22e8d3-097f-4f4d-a0bb-2e031183ba9a'::uuid, '{"fr":{"title":"Ayam percik au air fryer, riz et concombre","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Frotter le poulet avec le curcuma et une pincée de sel.","Hacher très finement ensemble les échalotes, l''ail, la citronnelle, le gingembre et les piments (ou les mixer avec 2 c. à soupe d''eau) pour obtenir une pâte grossière.","Faire revenir la pâte dans l''huile dans une petite casserole à feu moyen 4 min en remuant, jusqu''à ce qu''elle soit fondante et parfumée.","Ajouter le lait de coco, le tamarin, le sucre et une pincée de sel et mijoter 8 min en remuant souvent, jusqu''à obtenir une sauce épaisse.","Pendant ce temps, cuire le poulet à plat au air fryer à 200 °C pendant 10 min.","Badigeonner généreusement le poulet d''environ la moitié de la sauce et poursuivre 4 à 5 min au air fryer, jusqu''à ce que la sauce cloque et grille par endroits et que le poulet soit cuit (75 °C à cœur).","Trancher et servir avec le riz, le concombre, le citron vert et le reste de sauce."]},"it":{"title":"Ayam percik in friggitrice ad aria con riso e cetriolo","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Strofinare il pollo con la curcuma e un pizzico di sale.","Tritare molto finemente insieme scalogni, aglio, citronella, zenzero e peperoncini (o frullarli con 2 cucchiai d''acqua) fino a una pasta grossolana.","Soffriggere la pasta nell''olio in un pentolino a fuoco medio per 4 min mescolando, finché morbida e profumata.","Aggiungere latte di cocco, tamarindo, zucchero e un pizzico di sale e sobbollire 8 min mescolando spesso, finché si riduce a una salsa densa.","Nel frattempo cuocere il pollo disteso in friggitrice ad aria a 200 °C per 10 min.","Spennellare il pollo abbondantemente con circa metà della salsa e cuocere altri 4-5 min, finché la salsa fa le bolle e si abbrustolisce a chiazze e il pollo è cotto (75 °C al cuore).","Affettare e servire con riso, cetriolo, lime e la salsa rimasta."]}}'::jsonb),
  ('3bc79fd1-6944-40e2-afe3-3384c6df21d8'::uuid, '{"fr":{"title":"Soto ayam (soupe indonésienne au poulet et au curcuma) aux vermicelles","steps":["Hacher très finement ensemble les échalotes, l''ail et le gingembre, puis y mélanger le curcuma et la coriandre moulue.","Faire revenir la pâte dans l''huile dans une marmite à feu moyen avec la citronnelle et les feuilles de combava pendant 3 min, jusqu''à ce qu''elle embaume.","Ajouter le bouillon et les hauts de cuisse, porter à ébullition, couvrir et frémir 15 min jusqu''à ce que le poulet soit cuit.","Pendant ce temps, cuire les œufs 8 min dans une petite casserole, les refroidir à l''eau froide, les écaler et les couper en deux ; verser de l''eau bouillante sur les vermicelles, laisser 3 à 5 min jusqu''à ce qu''ils soient tendres et égoutter.","Sortir le poulet, l''effilocher et le remettre dans la marmite ; saler le bouillon et ajouter un filet de citron vert.","Répartir les vermicelles, le chou et les germes de soja dans des bols creux et verser dessus le bouillon bouillant et le poulet.","Garnir des œufs et de l''oignon nouveau et servir avec des quartiers de citron vert et du piment."]},"it":{"title":"Soto ayam (zuppa indonesiana di pollo alla curcuma) con vermicelli","steps":["Tritare molto finemente insieme scalogni, aglio e zenzero, poi unire curcuma e coriandolo in polvere.","Soffriggere la pasta nell''olio in una pentola a fuoco medio con citronella e foglie di lime per 3 min, finché profumata.","Aggiungere il brodo e le cosce di pollo, portare a bollore, coprire e sobbollire 15 min finché il pollo è cotto.","Nel frattempo cuocere le uova 8 min in un pentolino, raffreddarle in acqua fredda, sgusciarle e tagliarle a metà; versare acqua bollente sui vermicelli, lasciarli 3-5 min finché morbidi e scolarli.","Togliere il pollo, sfilacciarlo e rimetterlo nella pentola; regolare il brodo di sale e un po'' di lime.","Dividere vermicelli, cavolo e germogli di soia in ciotole fonde e versarvi sopra il brodo bollente con il pollo.","Completare con le uova e il cipollotto e servire con spicchi di lime e peperoncino."]}}'::jsonb),
  ('831a6241-ea1d-4c9f-b882-78713c367a20'::uuid, '{"fr":{"title":"Pancit bihon au poulet, chou et haricots verts","steps":["Faire tremper les vermicelles dans l''eau froide 5 à 10 min jusqu''à ce qu''ils soient souples, puis égoutter.","Chauffer l''huile dans un wok ou une grande poêle et faire revenir l''oignon et l''ail 2 min jusqu''à ce qu''ils soient tendres.","Ajouter le poulet et le faire sauter 4 min jusqu''à cuisson complète.","Ajouter la carotte et les haricots verts 2 min, puis le chou 1 min ; retirer la moitié des légumes et les réserver.","Verser le bouillon et la sauce soja avec beaucoup de poivre noir et porter à ébullition.","Ajouter les vermicelles et mélanger à feu moyen-vif 4 à 5 min, jusqu''à ce qu''ils aient absorbé le liquide et soient tendres.","Remettre les légumes réservés, mélanger et servir avec des quartiers de citron à presser."]},"it":{"title":"Pancit bihon con pollo, cavolo e fagiolini","steps":["Ammollare i vermicelli in acqua fredda 5-10 min finché morbidi, poi scolarli.","Scaldare l''olio in un wok o in una padella larga e soffriggere cipolla e aglio 2 min finché morbidi.","Aggiungere il pollo e saltarlo 4 min finché cotto.","Aggiungere carota e fagiolini per 2 min, poi il cavolo per 1 min; togliere metà delle verdure e tenerle da parte.","Versare brodo e salsa di soia con abbondante pepe nero e portare a bollore.","Unire i vermicelli e saltarli a fuoco medio-alto 4-5 min, finché hanno assorbito il liquido e sono teneri.","Rimettere le verdure tenute da parte, mescolare e servire con spicchi di limone da spremere."]}}'::jsonb),
  ('6c5bdac0-bd42-458f-b0a0-1afc9a981ced'::uuid, '{"fr":{"title":"Gaeng jued woon sen (soupe thaïe aux vermicelles de soja et boulettes de poulet)","steps":["Faire tremper les vermicelles de soja 10 min dans l''eau tiède, égoutter et les couper plus courts aux ciseaux.","Mélanger le poulet avec la sauce soja, l''ail râpé, les tiges de coriandre, la fécule et une bonne pincée de poivre blanc.","Porter le bouillon à ébullition avec l''ail écrasé et la carotte.","Y déposer des cuillerées à café bombées de farce et frémir 5 min, jusqu''à ce que les boulettes remontent et soient cuites.","Ajouter le chou et les champignons et frémir 4 min jusqu''à ce que le chou soit tendre.","Ajouter les vermicelles et frémir 2 min jusqu''à ce qu''ils deviennent translucides, puis assaisonner avec la sauce de poisson, la sauce soja et le poivre blanc.","Servir dans des bols et parsemer d''oignon nouveau et de feuilles de coriandre."]},"it":{"title":"Gaeng jued woon sen (zuppa thai di spaghetti di soia con polpettine di pollo)","steps":["Ammollare gli spaghetti di soia in acqua tiepida per 10 min, scolarli e accorciarli con le forbici.","Mescolare il pollo con salsa di soia, aglio grattugiato, gambi di coriandolo, amido e un bel pizzico di pepe bianco.","Portare a bollore il brodo con l''aglio schiacciato e la carota.","Versarvi cucchiaini colmi di impasto e sobbollire 5 min, finché le polpettine salgono a galla e sono cotte.","Aggiungere cavolo e funghi e sobbollire 4 min finché il cavolo è tenero.","Unire gli spaghetti di soia e sobbollire 2 min finché diventano trasparenti, poi insaporire con salsa di pesce, salsa di soia e pepe bianco.","Servire nelle ciotole con cipollotto e foglie di coriandolo."]}}'::jsonb),
  ('25df8f45-66ea-40af-a171-c28749ca3e5b'::uuid, '{"fr":{"title":"Mie ayam (nouilles indonésiennes au poulet, pak-choï et champignons)","steps":["Faire revenir les échalotes dans l''huile dans une poêle à feu moyen 2 min, puis ajouter l''ail et le gingembre 1 min.","Ajouter le poulet et le cuire 5 min en l''émiettant, jusqu''à ce qu''il ne soit plus rose.","Ajouter les champignons 2 min, puis le kecap manis, la sauce soja, la sauce d''huître, une pincée de poivre blanc et 100 ml d''eau, et mijoter 4 min jusqu''à ce que ce soit brillant et épais.","Pendant ce temps, chauffer le bouillon dans une petite casserole avec la moitié de l''oignon nouveau et le maintenir frémissant.","Cuire les nouilles dans une casserole d''eau bouillante selon le paquet (en général 3 à 4 min), en ajoutant le pak-choï les 2 dernières minutes, puis égoutter.","Mélanger les nouilles dans les bols avec l''huile de sésame et la sauce soja.","Garnir de poulet et de pak-choï, parsemer du reste d''oignon nouveau et servir le bouillon chaud et le piment à côté."]},"it":{"title":"Mie ayam (noodles indonesiani al pollo con pak choi e funghi)","steps":["Soffriggere gli scalogni nell''olio in una padella a fuoco medio per 2 min, poi aggiungere aglio e zenzero per 1 min.","Aggiungere il pollo e cuocerlo 5 min sgranandolo, finché non è più rosa.","Aggiungere i funghi per 2 min, poi kecap manis, salsa di soia, salsa d''ostrica, un pizzico di pepe bianco e 100 ml d''acqua, e sobbollire 4 min finché lucido e denso.","Nel frattempo scaldare il brodo in un pentolino con metà del cipollotto e tenerlo a sobbollire.","Cuocere i noodles in una pentola d''acqua bollente come indicato sulla confezione (di solito 3-4 min), aggiungendo il pak choi negli ultimi 2 min, poi scolare.","Condire i noodles nelle ciotole con olio di sesamo e salsa di soia.","Completare con pollo e pak choi, il cipollotto rimasto e servire a parte il brodo caldo e il peperoncino."]}}'::jsonb),
  ('f1694737-c846-4e5d-80f8-b9e4449b3c80'::uuid, '{"fr":{"title":"Aubergines yu xiang au poulet haché et riz","steps":["Rincer le riz et le cuire à couvert dans 225 ml d''eau salée à feu doux pendant 12 min, puis le laisser reposer 5 min à couvert hors du feu.","Mélanger l''aubergine avec 2 c. à café d''huile et une pincée de sel et la cuire au air fryer à 200 °C pendant 12 à 14 min en secouant deux fois, jusqu''à ce qu''elle soit fondante et dorée.","Pendant ce temps, mélanger la sauce soja, le vinaigre noir, le sucre, le vin de riz, la fécule et 100 ml d''eau.","Chauffer le reste d''huile dans un wok à feu vif et faire sauter le poulet 4 min en l''émiettant, jusqu''à ce qu''il soit bien égrené et cuit.","Ajouter le doubanjiang et faire revenir 1 min jusqu''à ce que l''huile devienne rouge, puis l''ail, le gingembre et le blanc des oignons nouveaux 30 s.","Verser la sauce et laisser bouillonner jusqu''à ce qu''elle épaississe, environ 1 min.","Incorporer l''aubergine 2 min pour qu''elle absorbe la sauce, parsemer du vert des oignons nouveaux et servir sur le riz."]},"it":{"title":"Melanzane yu xiang con pollo macinato e riso","steps":["Sciacquare il riso e cuocerlo coperto in 225 ml d''acqua salata a fuoco basso per 12 min, poi lasciarlo riposare coperto fuori dal fuoco per 5 min.","Condire la melanzana con 2 cucchiaini d''olio e un pizzico di sale e cuocerla in friggitrice ad aria a 200 °C per 12-14 min, scuotendo due volte, finché morbida e dorata.","Nel frattempo mescolare salsa di soia, aceto nero, zucchero, vino di riso, amido e 100 ml d''acqua.","Scaldare l''olio rimasto in un wok a fuoco vivo e saltare il pollo 4 min sgranandolo, finché è sgranato e cotto.","Aggiungere il doubanjiang e soffriggere 1 min finché l''olio diventa rosso, poi aglio, zenzero e la parte bianca dei cipollotti per 30 s.","Versare la salsa e farla bollire finché si addensa, circa 1 min.","Unire la melanzana per 2 min perché assorba la salsa, completare con la parte verde dei cipollotti e servire sul riso."]}}'::jsonb),
  ('61a4614d-2258-4b07-a812-256fc42b6897'::uuid, '{"fr":{"title":"Tacos al pastor au poulet et à l''ananas à l''air fryer","steps":["Couvrir les piments d''eau bouillante et les laisser tremper 10 min jusqu''à ce qu''ils ramollissent.","Mixer les piments égouttés avec 50 g d''ananas, l''ail, le vinaigre, le cumin, l''origan, le paprika, 1 c. à café de sel et 3 c. à soupe d''eau de trempage jusqu''à obtenir une pâte lisse.","Enrober les lanières de poulet de cette pâte et de l''huile. Couper le reste de l''ananas en morceaux de 1,5 cm.","Cuire le poulet et les quartiers d''oignon en une seule couche à l''air fryer à 200 °C pendant 8 min.","Ajouter l''ananas, secouer le panier et cuire encore 6 à 7 min, jusqu''à ce que le poulet soit grillé sur les bords et cuit à cœur (74 °C).","Pendant ce temps, chauffer les tortillas 30 s de chaque côté dans une poêle sèche et les garder enveloppées dans un torchon.","Hacher grossièrement le poulet, l''oignon et l''ananas, en garnir les tortillas et ajouter l''oignon cru haché, la coriandre, un filet de citron vert et de la sauce piquante si on le souhaite."]},"it":{"title":"Tacos al pastor di pollo con ananas in friggitrice ad aria","steps":["Coprire i peperoncini con acqua bollente e lasciarli in ammollo 10 min finché sono morbidi.","Frullare i peperoncini scolati con 50 g di ananas, l''aglio, l''aceto, il cumino, l''origano, la paprica, 1 cucchiaino di sale e 3 cucchiai dell''acqua di ammollo fino a una pasta liscia.","Condire le strisce di pollo con la pasta e l''olio. Tagliare il resto dell''ananas a pezzi di 1,5 cm.","Cuocere il pollo e gli spicchi di cipolla in un solo strato in friggitrice ad aria a 200 °C per 8 min.","Aggiungere l''ananas, scuotere il cestello e cuocere altri 6-7 min, finché il pollo è abbrustolito ai bordi e cotto al cuore (74 °C).","Nel frattempo scaldare le tortillas in una padella asciutta 30 s per lato e tenerle avvolte in un canovaccio.","Tritare grossolanamente pollo, cipolla e ananas, farcire le tortillas e completare con cipolla cruda tritata, coriandolo, un po'' di lime e salsa piccante a piacere."]}}'::jsonb),
  ('6dc60573-1dbd-4738-8575-53499b6ab0d7'::uuid, '{"fr":{"title":"Ají de gallina, pommes de terre, riz et salsa criolla","steps":["Porter le bouillon à frémissement, y ajouter le poulet, les rondelles de pomme de terre et l''œuf, et pocher doucement 12 à 15 min jusqu''à ce que le poulet soit cuit et les pommes de terre tendres. Tout retirer et garder le bouillon.","Pendant ce temps, mettre le riz dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu.","Faire tremper le pain dans le lait. Rincer l''oignon rouge émincé à l''eau froide, l''égoutter et le mélanger avec le jus de citron vert, la coriandre, le piment et une pincée de sel pour la salsa criolla.","Faire revenir l''oignon haché dans l''huile à feu moyen 6 min jusqu''à ce qu''il soit tendre et doré. Ajouter l''ail, la pâte d''ají amarillo et le curcuma et cuire 2 min.","Mixer le pain trempé et le lait avec les noix jusqu''à obtenir une crème lisse, verser dans la poêle avec 200 ml du bouillon de cuisson et laisser mijoter 4 à 5 min en remuant, jusqu''à ce que la sauce soit épaisse et onctueuse.","Effilocher le poulet dans la sauce, incorporer le parmesan et détendre avec un peu de bouillon si besoin. Saler et poivrer.","Servir le poulet sur le riz avec les pommes de terre, garnir de l''œuf en quartiers et des olives, et accompagner de la salsa criolla."]},"it":{"title":"Ají de gallina con patate, riso e salsa criolla","steps":["Portare il brodo a sobbollore, aggiungere il pollo, le fette di patata e l''uovo e cuocere dolcemente 12-15 min finché il pollo è cotto e le patate sono tenere. Scolare tutto e tenere da parte il brodo.","Nel frattempo mettere il riso in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco.","Mettere in ammollo il pane nel latte. Sciacquare la cipolla rossa affettata in acqua fredda, scolarla e condirla con succo di lime, coriandolo, peperoncino e un pizzico di sale per la salsa criolla.","Soffriggere la cipolla tritata nell''olio a fuoco medio per 6 min finché è morbida e dorata. Aggiungere l''aglio, la pasta di ají amarillo e la curcuma e cuocere 2 min.","Frullare il pane ammollato e il latte con le noci fino a una crema liscia, versarla in padella con 200 ml del brodo e cuocere 4-5 min mescolando, finché la salsa è densa e cremosa.","Sfilacciare il pollo nella salsa, unire il parmigiano e allungare con un po'' di brodo se serve. Regolare di sale e pepe.","Servire il pollo sul riso con le patate, completare con l''uovo a spicchi e le olive, e accompagnare con la salsa criolla."]}}'::jsonb),
  ('5864a3c5-72aa-4762-aff5-8cd8914c7334'::uuid, '{"fr":{"title":"Anticuchos de pollo à l''air fryer, pommes de terre et maïs","steps":["Mettre les pommes de terre dans une casserole d''eau froide salée, porter à ébullition et cuire 15 min jusqu''à ce qu''elles soient tendres, en ajoutant les tronçons de maïs pour les 6 dernières minutes.","Mélanger la pâte d''ají panca, l''ail, le vinaigre, le cumin, l''origan, l''huile, ½ c. à café de sel et du poivre. Y enrober le poulet et l''enfiler sur 4 petites brochettes, en gardant le reste de marinade.","Cuire les brochettes à l''air fryer à 200 °C pendant 12 à 14 min, en les retournant et en les badigeonnant du reste de marinade à mi-cuisson, jusqu''à ce qu''elles soient grillées sur les bords et cuites à cœur (74 °C).","Mélanger la pâte d''ají amarillo avec le jus de citron vert, l''oignon nouveau, la coriandre, 1 c. à soupe d''eau et une pincée de sel pour la sauce.","Égoutter les pommes de terre et le maïs.","Servir les brochettes avec les pommes de terre et le maïs, et la sauce à l''ají pour tremper."]},"it":{"title":"Anticuchos de pollo in friggitrice ad aria con patate e mais","steps":["Mettere le patate in una pentola di acqua fredda salata, portare a bollore e cuocere 15 min finché sono tenere, aggiungendo le rondelle di mais negli ultimi 6 min.","Mescolare la pasta di ají panca, l''aglio, l''aceto, il cumino, l''origano, l''olio, ½ cucchiaino di sale e pepe. Condire il pollo e infilarlo su 4 spiedini corti, tenendo da parte la marinata avanzata.","Cuocere gli spiedini in friggitrice ad aria a 200 °C per 12-14 min, girandoli e spennellandoli con la marinata a metà cottura, finché sono abbrustoliti ai bordi e cotti al cuore (74 °C).","Mescolare la pasta di ají amarillo con succo di lime, cipollotto, coriandolo, 1 cucchiaio d''acqua e un pizzico di sale per la salsa.","Scolare patate e mais.","Servire gli spiedini con patate e mais e la salsa all''ají per intingere."]}}'::jsonb),
  ('862414f6-3de8-4073-8567-200d720b2563'::uuid, '{"fr":{"title":"Galinhada (riz brésilien au poulet et au curcuma)","steps":["Assaisonner le poulet avec le jus de citron vert, la moitié de l''ail, ½ c. à café de sel et du poivre.","Chauffer l''huile dans une cocotte large à feu moyen-vif et faire dorer le poulet 5 min en remuant de temps en temps.","Ajouter l''oignon et le poivron et cuire 3 min jusqu''à ce qu''ils ramollissent, puis le reste de l''ail, la tomate et le curcuma pendant 1 min.","Incorporer le riz 1 min pour bien l''enrober, verser le bouillon chaud, porter à ébullition, couvrir et cuire à feu doux 12 min.","Répartir les petits pois sur le riz, couvrir de nouveau et cuire encore 4 à 5 min jusqu''à ce que le riz soit tendre et le liquide absorbé.","Laisser reposer 2 min hors du feu, puis incorporer le persil et les oignons nouveaux et rectifier le sel."]},"it":{"title":"Galinhada (riso brasiliano con pollo e curcuma)","steps":["Condire il pollo con il succo di lime, metà dell''aglio, ½ cucchiaino di sale e pepe.","Scaldare l''olio in una pentola larga a fuoco medio-alto e rosolare il pollo per 5 min, mescolando ogni tanto.","Aggiungere cipolla e peperone e cuocere 3 min finché si ammorbidiscono, poi il resto dell''aglio, il pomodoro e la curcuma per 1 min.","Unire il riso e tostarlo 1 min, versare il brodo caldo, portare a bollore, coprire e cuocere a fuoco basso 12 min.","Distribuire i piselli sul riso, coprire di nuovo e cuocere altri 4-5 min finché il riso è tenero e il liquido assorbito.","Lasciar riposare 2 min fuori dal fuoco, poi incorporare prezzemolo e cipollotti e regolare di sale."]}}'::jsonb),
  ('3c498c93-195c-4b11-a061-ca0fc9abf27e'::uuid, '{"fr":{"title":"Strogonoff de frango (émincé de poulet à la crème) et riz","steps":["Mettre le riz dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu.","Saler et poivrer le poulet et le faire dorer dans l''huile dans une grande poêle à feu vif 4 à 5 min. Le réserver sur une assiette.","Baisser le feu, ajouter le beurre et l''oignon et cuire 3 min, puis l''ail et les champignons pendant 5 min jusqu''à ce que leur eau se soit évaporée.","Remettre le poulet avec le concentré de tomate, le ketchup, la moutarde et le bouillon et laisser mijoter 3 min jusqu''à ce que le poulet soit cuit.","Incorporer la crème et chauffer 1 à 2 min sans faire bouillir. Rectifier l''assaisonnement.","Servir le strogonoff sur le riz, parsemé de persil."]},"it":{"title":"Strogonoff de frango (straccetti di pollo alla panna) con riso","steps":["Mettere il riso in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco.","Salare e pepare il pollo e rosolarlo nell''olio in una padella grande a fuoco vivo per 4-5 min. Metterlo da parte su un piatto.","Abbassare il fuoco, aggiungere il burro e la cipolla e cuocere 3 min, poi l''aglio e i funghi per 5 min finché la loro acqua è evaporata.","Rimettere il pollo con concentrato di pomodoro, ketchup, senape e brodo e cuocere 3 min finché il pollo è cotto.","Unire la panna e scaldare 1-2 min senza far bollire. Regolare di sale e pepe.","Servire lo strogonoff sul riso con il prezzemolo."]}}'::jsonb),
  ('65496410-7e58-455e-b55c-83c49578e92b'::uuid, '{"fr":{"title":"Pollo a la provenzal, pommes de terre à l''air fryer et salade composée","steps":["Mélanger les pommes de terre avec 1 c. à café d''huile et une pincée de sel et les cuire à l''air fryer à 200 °C pendant 20 min, en secouant deux fois, jusqu''à ce qu''elles soient dorées et croustillantes.","Mélanger l''ail, le persil, le piment, 1,5 c. à soupe d''huile et une pincée de sel : c''est la provenzal.","Assaisonner le poulet et le cuire dans 1 c. à café d''huile dans une poêle à feu moyen-vif 4 à 5 min de chaque côté, jusqu''à ce qu''il soit doré et cuit à cœur (74 °C).","Baisser le feu, napper le poulet de la moitié de la provenzal et chauffer 30 s sans laisser l''ail colorer.","Mélanger la laitue, les tomates et l''oignon rouge avec le vinaigre, le reste d''huile et une pincée de sel.","Mélanger les pommes de terre chaudes avec le reste de provenzal et servir avec le poulet et la salade."]},"it":{"title":"Pollo a la provenzal con patate in friggitrice ad aria e insalata mista","steps":["Condire le patate con 1 cucchiaino d''olio e un pizzico di sale e cuocerle in friggitrice ad aria a 200 °C per 20 min, scuotendo due volte, finché sono dorate e croccanti.","Mescolare aglio, prezzemolo, peperoncino, 1,5 cucchiai d''olio e un pizzico di sale: è la provenzal.","Condire il pollo e cuocerlo con 1 cucchiaino d''olio in padella a fuoco medio-alto per 4-5 min per lato, finché è dorato e cotto al cuore (74 °C).","Abbassare il fuoco, versare sul pollo metà della provenzal e scaldare 30 s senza far colorire l''aglio.","Condire lattuga, pomodori e cipolla rossa con l''aceto, l''olio rimasto e un pizzico di sale.","Saltare le patate calde con il resto della provenzal e servire con il pollo e l''insalata."]}}'::jsonb),
  ('86831f68-34ef-4bff-968a-1190df8a396a'::uuid, '{"fr":{"title":"Curry de poulet et pommes de terre de Trinidad, riz","steps":["Mélanger les oignons nouveaux, la coriandre, le thym et l''ail (green seasoning). Enrober le poulet de la moitié de ce mélange, d''1 c. à café de curry et de ½ c. à café de sel.","Mettre le riz dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu.","Délayer le reste du curry et le cumin dans 3 c. à soupe d''eau. Chauffer l''huile dans une cocotte, ajouter la pâte et cuire 1 à 2 min en remuant, jusqu''à ce qu''elle fonce et soit presque sèche.","Ajouter l''oignon et le reste du green seasoning et cuire 2 min, puis le poulet en remuant pour bien l''enrober, pendant 3 min.","Ajouter les pommes de terre, la tomate, le piment et 300 ml d''eau, porter à ébullition et laisser mijoter à moitié couvert 15 min, jusqu''à ce que les pommes de terre soient tendres et commencent à épaissir la sauce.","Retirer le piment, rectifier l''assaisonnement et servir le curry avec le riz."]},"it":{"title":"Curry di pollo e patate di Trinidad con riso","steps":["Mescolare cipollotti, coriandolo, timo e aglio (green seasoning). Condire il pollo con metà del composto, 1 cucchiaino di curry e ½ cucchiaino di sale.","Mettere il riso in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco.","Stemperare il resto del curry e il cumino in 3 cucchiai d''acqua. Scaldare l''olio in una pentola, aggiungere la pasta e cuocere 1-2 min mescolando, finché scurisce ed è quasi asciutta.","Aggiungere la cipolla e il resto del green seasoning e cuocere 2 min, poi il pollo, mescolando per insaporirlo, per 3 min.","Aggiungere patate, pomodoro, peperoncino e 300 ml d''acqua, portare a bollore e cuocere semicoperto 15 min, finché le patate sono tenere e iniziano a disfarsi addensando il sugo.","Togliere il peperoncino, regolare di sale e servire il curry con il riso."]}}'::jsonb),
  ('deeb91fe-6475-4d50-9c7e-e913db5f79c4'::uuid, '{"fr":{"title":"Étouffée de poulet sur riz","steps":["Mettre le riz dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu.","Enrober le poulet de la moitié de l''assaisonnement cajun et le faire dorer dans l''huile dans une sauteuse à fond épais à feu vif 4 min. Le réserver.","Mettre le beurre et la farine dans la sauteuse et remuer à feu moyen 5 à 6 min jusqu''à ce que le roux prenne la couleur du beurre de cacahuète.","Ajouter l''oignon, le poivron et le céleri et cuire 5 min en remuant jusqu''à ce qu''ils soient tendres. Incorporer l''ail, le concentré de tomate et le reste de l''assaisonnement cajun 1 min.","Verser le bouillon petit à petit en fouettant, ajouter le laurier et laisser mijoter 5 min jusqu''à ce que la sauce épaississe.","Remettre le poulet et laisser mijoter 4 min jusqu''à ce qu''il soit cuit. Ajouter la sauce piquante, la plupart des oignons nouveaux et le persil, puis rectifier l''assaisonnement.","Servir sur le riz avec le reste des oignons nouveaux."]},"it":{"title":"Étouffée di pollo con riso","steps":["Mettere il riso in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco.","Condire il pollo con metà delle spezie cajun e rosolarlo nell''olio in una casseruola dal fondo spesso a fuoco vivo per 4 min. Toglierlo.","Mettere nella casseruola burro e farina e mescolare a fuoco medio 5-6 min finché il roux ha il colore del burro di arachidi.","Aggiungere cipolla, peperone e sedano e cuocere 5 min mescolando, finché sono morbidi. Unire aglio, concentrato di pomodoro e il resto delle spezie per 1 min.","Versare il brodo poco alla volta mescolando con la frusta, aggiungere l''alloro e cuocere 5 min finché si addensa.","Rimettere il pollo e cuocere 4 min finché è cotto. Aggiungere la salsa piccante, gran parte dei cipollotti e il prezzemolo e regolare di sale.","Servire sul riso con i cipollotti rimasti."]}}'::jsonb),
  ('227348ae-dfc7-41c9-a052-1b8d46c72a76'::uuid, '{"fr":{"title":"Poulet « blackened » à l''air fryer, maque choux et pommes de terre nouvelles","steps":["Cuire les pommes de terre 15 min dans l''eau bouillante salée jusqu''à ce qu''elles soient tendres.","Mélanger le paprika, le thym, l''origan, le cayenne, le poivre et ½ c. à café de sel. Frotter le poulet avec l''huile puis l''enrober entièrement d''épices.","Cuire le poulet à l''air fryer à 200 °C pendant 14 à 16 min en le retournant à mi-cuisson, jusqu''à ce que la croûte soit très foncée et le cœur à 74 °C. Laisser reposer 3 min.","Pendant ce temps, faire fondre le beurre dans une poêle et cuire l''oignon, le poivron et le céleri à feu moyen 5 min.","Ajouter l''ail et le maïs et cuire 4 min jusqu''à ce que quelques grains dorent, puis les tomates 2 min. Incorporer les oignons nouveaux et assaisonner : c''est le maque choux.","Égoutter les pommes de terre, trancher le poulet et servir avec le maque choux."]},"it":{"title":"Pollo «blackened» in friggitrice ad aria con maque choux e patate novelle","steps":["Cuocere le patate in acqua bollente salata per 15 min finché sono tenere.","Mescolare paprica, timo, origano, cayenna, pepe nero e ½ cucchiaino di sale. Ungere il pollo con l''olio e ricoprirlo completamente di spezie.","Cuocere il pollo in friggitrice ad aria a 200 °C per 14-16 min, girandolo a metà, finché la crosta è molto scura e il cuore raggiunge 74 °C. Lasciar riposare 3 min.","Nel frattempo sciogliere il burro in padella e cuocere cipolla, peperone e sedano a fuoco medio per 5 min.","Aggiungere aglio e mais e cuocere 4 min finché alcuni chicchi si dorano, poi i pomodorini per 2 min. Unire i cipollotti e regolare di sale: è il maque choux.","Scolare le patate, affettare il pollo e servire con il maque choux."]}}'::jsonb),
  ('b85afec3-ff92-4b1a-8281-70cc6566442d'::uuid, '{"fr":{"title":"Wraps au poulet buffalo à l''air fryer, salade de céleri et carotte","steps":["Mélanger le poulet avec la fécule, le paprika, ½ c. à café de sel et l''huile.","Cuire à l''air fryer à 200 °C pendant 10 à 12 min en secouant à mi-cuisson, jusqu''à ce qu''il soit doré et cuit à cœur (74 °C).","Faire fondre le beurre dans une petite casserole et y fouetter la sauce piquante.","Mélanger le céleri, la carotte et la laitue. Mélanger le yaourt avec le jus de citron, la ciboulette, l''ail, une pincée de sel et le bleu si on en met.","Enrober le poulet chaud de sauce buffalo. Chauffer les tortillas 20 s chacune dans la poêle sèche.","Garnir chaque tortilla de salade, de poulet et d''une cuillerée de sauce, rouler bien serré et couper en deux."]},"it":{"title":"Wrap di pollo buffalo in friggitrice ad aria con insalata di sedano e carota","steps":["Condire il pollo con amido, paprica, ½ cucchiaino di sale e l''olio.","Cuocere in friggitrice ad aria a 200 °C per 10-12 min, scuotendo a metà, finché è dorato e cotto al cuore (74 °C).","Sciogliere il burro in un pentolino e unire la salsa piccante con la frusta.","Mescolare sedano, carota e lattuga. Mescolare lo yogurt con succo di limone, erba cipollina, aglio, un pizzico di sale e il gorgonzola se si usa.","Ripassare il pollo caldo nella salsa buffalo. Scaldare le tortillas nella padella asciutta 20 s ciascuna.","Farcire ogni tortilla con insalata, pollo e un cucchiaio di salsa, arrotolare stretta e tagliare a metà."]}}'::jsonb),
  ('413dc209-59c0-4ec8-8329-7f9a9305613c'::uuid, '{"fr":{"title":"Suya de poulet à l''air fryer, pain plat, tomate et oignon","steps":["Moudre finement les cacahuètes au mixeur ou au moulin à épices, par à-coups pour qu''elles ne tournent pas en beurre. Mélanger avec le paprika, le cayenne, le gingembre et ½ c. à café de sel (yaji) et en réserver 2 c. à soupe.","Enrober le poulet de l''ail, de l''huile et du reste de yaji, puis l''enfiler sur des brochettes.","Cuire à l''air fryer à 200 °C pendant 12 à 14 min en retournant à mi-cuisson, jusqu''à ce qu''il soit grillé sur les bords et cuit à cœur (74 °C).","Pendant ce temps, émincer l''oignon, les tomates et le concombre.","Chauffer les pains plats dans une poêle sèche 30 s de chaque côté.","Saupoudrer le suya chaud du yaji réservé et servir avec l''oignon, la tomate, le concombre, les pains et le citron vert."]},"it":{"title":"Suya di pollo in friggitrice ad aria con pane piatto, pomodoro e cipolla","steps":["Macinare finemente le arachidi nel frullatore o nel macinaspezie, a impulsi perché non diventino burro. Mescolarle con paprica, cayenna, zenzero e ½ cucchiaino di sale (yaji) e tenerne da parte 2 cucchiai.","Condire il pollo con aglio, olio e il resto dello yaji, poi infilarlo su spiedini.","Cuocere in friggitrice ad aria a 200 °C per 12-14 min, girando a metà, finché è abbrustolito ai bordi e cotto al cuore (74 °C).","Nel frattempo affettare cipolla, pomodori e cetriolo.","Scaldare i pani piatti in una padella asciutta 30 s per lato.","Cospargere il suya caldo con lo yaji tenuto da parte e servire con cipolla, pomodoro, cetriolo, pane e lime."]}}'::jsonb),
  ('385b83b5-8fee-43d8-8d1f-2c5863cbf5c4'::uuid, '{"fr":{"title":"Tchakhokhbili (ragoût géorgien de poulet à la tomate) et pain","steps":["Assaisonner le poulet et le faire dorer dans le beurre dans une sauteuse à feu moyen-vif 5 min en le retournant une fois. Le réserver.","Mettre les oignons dans la sauteuse et cuire à feu moyen 6 min jusqu''à ce qu''ils soient tendres et légèrement dorés.","Incorporer l''ail, le khmeli suneli et le piment 1 min, puis ajouter les tomates et une pincée de sel.","Remettre le poulet, couvrir à moitié et laisser mijoter 10 à 12 min, jusqu''à ce que la sauce soit épaisse et le poulet tendre et cuit.","Incorporer la moitié des herbes, retirer du feu et laisser reposer 2 min, puis parsemer du reste.","Trancher le pain et le servir avec le ragoût pour saucer."]},"it":{"title":"Chakhokhbili (spezzatino georgiano di pollo e pomodoro) con pane","steps":["Condire il pollo e rosolarlo nel burro in una padella larga a fuoco medio-alto per 5 min, girandolo una volta. Toglierlo.","Mettere le cipolle in padella e cuocerle a fuoco medio per 6 min finché sono morbide e leggermente dorate.","Unire aglio, khmeli suneli e peperoncino per 1 min, poi aggiungere i pomodori e un pizzico di sale.","Rimettere il pollo, coprire parzialmente e cuocere 10-12 min, finché il sugo è denso e il pollo tenero e cotto.","Incorporare metà delle erbe, togliere dal fuoco e lasciar riposare 2 min, poi cospargere con il resto.","Affettare il pane e servirlo con lo spezzatino per raccogliere il sugo."]}}'::jsonb),
  ('bf979208-43d1-47cf-93a4-ee683be8a56c'::uuid, '{"fr":{"title":"Kotlet persans au poulet et aux herbes à l''air fryer, pain plat et crudités","steps":["Râper grossièrement la pomme de terre et l''oignon, les mettre dans un torchon propre et les presser pour en extraire le plus de liquide possible.","Les mélanger avec le poulet, l''œuf, le persil, la coriandre, la chapelure, le curcuma, 1 c. à café de sel et ½ c. à café de poivre jusqu''à obtenir un mélange homogène.","Les mains mouillées, former 6 galettes ovales d''environ 1,5 cm d''épaisseur et les badigeonner d''huile.","Cuire à l''air fryer à 200 °C pendant 12 à 14 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et cuites à cœur (74 °C).","Pendant ce temps, disposer les tomates, le concombre, les radis, la laitue et la menthe sur une assiette, avec les cornichons et le citron si on en met.","Réchauffer les pains plats 1 min à l''air fryer à la fin et servir les kotlet roulés dans le pain avec les crudités et les herbes."]},"it":{"title":"Kotlet persiani di pollo alle erbe in friggitrice ad aria con pane piatto e insalata","steps":["Grattugiare grossolanamente la patata e la cipolla, metterle in un canovaccio pulito e strizzarle per eliminare quanto più liquido possibile.","Mescolarle con pollo, uovo, prezzemolo, coriandolo, pangrattato, curcuma, 1 cucchiaino di sale e ½ cucchiaino di pepe fino a un composto omogeneo.","Con le mani bagnate formare 6 polpette ovali spesse circa 1,5 cm e spennellarle d''olio.","Cuocere in friggitrice ad aria a 200 °C per 12-14 min, girando a metà, finché sono ben dorate e cotte al cuore (74 °C).","Nel frattempo disporre pomodori, cetriolo, ravanelli, lattuga e menta su un piatto, con cetriolini e limone se si usano.","Scaldare i pani piatti in friggitrice per 1 min alla fine e servire i kotlet avvolti nel pane con l''insalata e le erbe."]}}'::jsonb),
  ('963bae66-37e6-4df7-b9f0-7da20c482b25'::uuid, '{"fr":{"title":"Kotlety z kurczaka (boulettes de poulet polonaises), pommes de terre à l''aneth et mizeria","steps":["Cuire les pommes de terre 15 à 18 min dans l''eau bouillante salée jusqu''à ce qu''elles soient tendres.","Saupoudrer le concombre de ½ c. à café de sel et laisser 10 min, puis l''essorer et le mélanger avec le yaourt, le vinaigre, le sucre et un tiers de l''aneth pour la mizeria.","Faire tremper le pain 2 min dans le lait, l''essorer et l''émietter dans le poulet avec l''œuf, l''oignon, l''ail, un tiers de l''aneth, ¾ c. à café de sel et du poivre. Bien mélanger.","Les mains mouillées, former 4 galettes ovales d''environ 2 cm d''épaisseur et les enrober de chapelure.","Les cuire dans l''huile dans une poêle à feu moyen 5 à 6 min de chaque côté jusqu''à ce qu''elles soient dorées et cuites à cœur (74 °C).","Égoutter les pommes de terre, les mélanger avec le beurre et le reste de l''aneth et servir avec les galettes et la mizeria."]},"it":{"title":"Kotlety z kurczaka (polpette polacche di pollo) con patate all''aneto e mizeria","steps":["Cuocere le patate in acqua bollente salata per 15-18 min finché sono tenere.","Cospargere il cetriolo con ½ cucchiaino di sale e lasciarlo 10 min, poi strizzarlo e mescolarlo con yogurt, aceto, zucchero e un terzo dell''aneto per la mizeria.","Ammollare il pane nel latte per 2 min, strizzarlo e sbriciolarlo nel pollo con uovo, cipolla, aglio, un terzo dell''aneto, ¾ di cucchiaino di sale e pepe. Mescolare bene.","Con le mani bagnate formare 4 polpette ovali spesse circa 2 cm e passarle nel pangrattato.","Cuocerle nell''olio in padella a fuoco medio per 5-6 min per lato finché sono dorate e cotte al cuore (74 °C).","Scolare le patate, condirle con il burro e il resto dell''aneto e servire con le polpette e la mizeria."]}}'::jsonb),
  ('7be6c3d7-5a6e-4703-93fc-0a652a74598e'::uuid, '{"fr":{"title":"Albóndigas de pollo (boulettes de poulet) sauce tomate-chipotle et riz","steps":["Mettre le riz dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min, puis laisser reposer hors du feu.","Mixer les tomates, la pâte de chipotle, l''oignon, 1 gousse d''ail et l''origan jusqu''à obtenir une sauce lisse.","Mélanger le poulet avec l''œuf, la chapelure, la menthe, le cumin, l''autre gousse d''ail écrasée et ¾ c. à café de sel, et façonner 14 à 16 boulettes de la taille d''une noix avec les mains mouillées.","Chauffer l''huile dans une sauteuse, verser la sauce tomate et la faire revenir 3 min en remuant jusqu''à ce qu''elle fonce. Ajouter le bouillon et la carotte et porter à frémissement.","Ajouter les boulettes, couvrir et laisser mijoter doucement 8 min.","Ajouter la courgette, couvrir et laisser mijoter encore 5 min, jusqu''à ce que les boulettes soient cuites et les légumes tendres. Rectifier l''assaisonnement.","Servir les albóndigas et leur sauce sur le riz, parsemées de coriandre."]},"it":{"title":"Albóndigas de pollo (polpette di pollo) in salsa di pomodoro e chipotle con riso","steps":["Mettere il riso in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min, poi lasciar riposare fuori dal fuoco.","Frullare pomodori, pasta di chipotle, cipolla, 1 spicchio d''aglio e origano fino a una salsa liscia.","Mescolare il pollo con uovo, pangrattato, menta, cumino, l''altro spicchio d''aglio schiacciato e ¾ di cucchiaino di sale e formare 14-16 polpette grandi come una noce con le mani bagnate.","Scaldare l''olio in una padella larga, versare la salsa e farla soffriggere 3 min mescolando, finché scurisce. Aggiungere il brodo e la carota e portare a sobbollore.","Unire le polpette, coprire e cuocere dolcemente 8 min.","Aggiungere la zucchina, coprire e cuocere altri 5 min, finché le polpette sono cotte e le verdure tenere. Regolare di sale.","Servire le albóndigas con la salsa sul riso e il coriandolo."]}}'::jsonb)
) as v(id, translations)
where (x.id = v.id or (x.copied_from = v.id and x.title = (select s.title from public.recipes s where s.id = v.id)))
  and x.translations is distinct from v.translations;

