  ('deeb91fe-6475-4d50-9c7e-e913db5f79c4'::uuid, 814::real, 49.3::real, false),
  ('227348ae-dfc7-41c9-a052-1b8d46c72a76'::uuid, 696::real, 50.8::real, false),
  ('b85afec3-ff92-4b1a-8281-70cc6566442d'::uuid, 844::real, 54.3::real, false),
  ('413dc209-59c0-4ec8-8329-7f9a9305613c'::uuid, 740::real, 44.8::real, false),
  ('385b83b5-8fee-43d8-8d1f-2c5863cbf5c4'::uuid, 742::real, 45.7::real, false),
  ('bf979208-43d1-47cf-93a4-ee683be8a56c'::uuid, 806::real, 48.7::real, false),
  ('963bae66-37e6-4df7-b9f0-7da20c482b25'::uuid, 820::real, 45.7::real, false),
  ('7be6c3d7-5a6e-4703-93fc-0a652a74598e'::uuid, 849::real, 48.3::real, false)
) as v(id, kcal, protein, estimated)
where (x.id = v.id or x.copied_from = v.id)
  and (x.kcal_per_serving, x.protein_g_per_serving) is distinct from (v.kcal, v.protein);

-- Content of seed recipes loaded earlier, as in recipes.json.
update public.recipes x set title = v.title, servings = v.servings, original_servings = v.original_servings,
  total_min = v.total_min, prep_min = v.prep_min, cook_min = v.cook_min, steps = v.steps, tags = v.tags,
  cuisine = v.cuisine, difficulty = v.difficulty, equipment = v.equipment, source_name = v.source_name, source_url = v.source_url
from (values
  ('d8e4ac12-403d-4d06-97cf-022682d08894'::uuid, 'Arrosto di tacchino alle erbe', 2, 4::int, 140::int, 15::int, 110::int, '["Legare il petto di tacchino con lo spago da cucina.","Massaggiarlo con rosmarino, salvia, origano, curry, sale e pepe.","Scaldare l''olio in un tegame con carota, cipolla, sedano e aglio a pezzi grossi e rosolare la carne su tutti i lati.","Sfumare con il vino bianco.","Cuocere coperto a fuoco basso per circa 45 minuti, oppure in forno a 180 °C coperto con alluminio per circa un''ora.","Lasciar riposare la carne prima di tagliarla a fette.","Frullare le verdure di cottura con un po'' di fondo, scaldare la salsa e servirla con l''arrosto."]'::jsonb, array['italian', 'mediterranean', 'oven', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":["blender"]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/ricettechepassione/arrosto-di-tacchino/'),
  ('7cb87b97-df20-4ea6-8837-a97aa96c651f'::uuid, 'Coniglio alla ligure con olive taggiasche', 2, 4::int, 110::int, 20::int, 90::int, '["Tagliare il coniglio a pezzi, eliminare grasso, fegato e reni, sciacquarlo e asciugarlo.","Tritare finemente la cipolla e tritare l''aglio senza anima insieme agli aghi di rosmarino.","Scaldare l''olio con il trito e il coniglio e rosolare la carne su tutti i lati a fuoco basso senza bruciare il soffritto.","Sfumare con il vino rosso alzando la fiamma finché l''alcol è evaporato.","Aggiungere alloro, timo, olive e un mestolo di brodo caldo, coprire e cuocere piano, unendo altro brodo solo se serve.","Dopo circa un''ora, quando la carne si stacca dall''osso, scoprire e far restringere il sugo in eccesso."]'::jsonb, array['italian', 'mediterranean', 'stew', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/coniglio-alla-ligure-la-ricetta-originale-con-olive-taggiasche/'),
  ('17c37e4b-5dc1-4114-8e36-27664bd290ca'::uuid, 'Cozze alla tarantina', 2, 4::int, 100::int, 15::int, 25::int, '["Tieni le cozze in acqua salata per almeno un''ora, poi strofina i gusci ed elimina il bisso.","In una padella rosola uno spicchio d''aglio schiacciato in metà dell''olio, senza farlo scurire.","Aggiungi le cozze e un rametto di prezzemolo, sfuma con il vino e copri finché si aprono.","Filtra il liquido di cottura con un colino fine e tieni da parte le cozze.","In una padella pulita scalda l''olio rimasto con l''aglio a fettine e il peperoncino spezzettato.","Unisci i pelati schiacciandoli con una forchetta, aggiungi il liquido delle cozze e fai restringere a fuoco basso per circa 10 minuti.","Rimetti le cozze nel sugo con il prezzemolo tritato, lascia insaporire qualche minuto e servi con pane abbrustolito."]'::jsonb, array['italian', 'mediterranean', 'stew', 'comfort']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/cozze-alla-tarantina-al-sugo'),
  ('bacd2ed3-0463-40f3-bb43-f496642a30b8'::uuid, 'Frittata di zucchine e ricotta al forno', 2, 4::int, 45::int, 15::int, 30::int, '["Preriscalda il forno a 180 °C statico.","Lava e asciuga le zucchine, spuntale e tagliale a rondelle sottili.","Sbatti le uova in una ciotola, incorpora ricotta e parmigiano, regola di sale e pepe e unisci le zucchine.","Fodera una piccola tortiera con carta forno (leggermente unta o inumidita), versa il composto e livellalo.","Cuoci 30 minuti in modalità statica, poi altri 5 minuti ventilato finché la superficie è dorata.","Sforna, taglia a fette e servi tiepida o fredda."]'::jsonb, array['italian', 'oven', 'light', 'vegetarian']::text[], 'italian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/cottoinunclick/ricetta-frittata-zucchine-e-ricotta-al-forno/'),
  ('27b821b2-edb6-4621-9429-c3073510739c'::uuid, 'Insalata di farro con tonno e ceci', 2, 2::int, 30::int, 10::int, 20::int, '["Lessa il farro in abbondante acqua salata secondo i tempi della confezione, scolalo e lascialo raffreddare.","Scola e sciacqua i ceci; sgocciola bene il tonno.","Unisci al farro i ceci e il tonno sbriciolato, condisci con olio e un pizzico di sale e mescola.","Taglia in quattro i pomodorini, lava e asciuga la rucola.","Aggiungi pomodorini e rucola al farro, mescola, regola il condimento e servi subito o tieni in frigo fino al momento."]'::jsonb, array['italian', 'mediterranean', 'salad', 'light']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/studentiaifornelli/insalata-di-farro-tonno-e-ceci/'),
  ('78ed85bf-8d00-444e-b619-63a462d21934'::uuid, 'Involtini di pollo al forno', 2, 4::int, 35::int, 10::int, 20::int, '["Stendere le fette di pollo su un tagliere.","Coprire ciascuna con una fettina di fontina e una di prosciutto cotto.","Arrotolarle strette su se stesse.","Sbattere leggermente l''uovo con sale e pepe e passarvi gli involtini.","Rotolarli nel pangrattato e sistemarli su carta forno in una teglia, con un filo d''olio.","Cuocere in forno a 180 °C per 25 minuti."]'::jsonb, array['italian', 'oven', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/involtini-di-pollo-al-forno/'),
  ('e895582c-375e-49f7-95de-d738448185c2'::uuid, 'Medaglioni di filetto di maiale ai funghi', 2, 4::int, 30::int, 5::int, 10::int, '["Rifilare il filetto da grasso e pellicine, tagliarlo a medaglioni spessi almeno 3 cm e tamponarli con carta da cucina.","Sciogliere il burro chiarificato con la salvia in una padella antiaderente e scottare i medaglioni a fuoco alto circa 2 minuti per lato, salando e pepando leggermente.","Sfumare con il vino bianco e far evaporare l''alcol, poi tenere da parte la carne al caldo.","Nella stessa padella cuocere i funghi affettati sottili con la panna, a fuoco basso e coperto.","Regolare di sale, addensare la salsa con l''amido di mais, rimettere i medaglioni a scaldare e servire."]'::jsonb, array['italian', 'fancy', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/medaglioni-di-filetto-di-maiale/'),
  ('5bdecccd-5a1b-46a8-8887-5bdebc040da6'::uuid, 'Merluzzo alla livornese', 2, 4::int, 25::int, 5::int, 15::int, '["Sbuccia l''aglio ed elimina l''anima interna.","Fai dorare l''aglio nell''olio senza bruciarlo, poi toglilo dalla padella.","Adagia i filetti di merluzzo e rosolali circa 5 minuti per lato.","Bagna con il vino bianco e lascia evaporare a fiamma alta.","Aggiungi la passata, i capperi sciacquati e le olive, e cuoci finché il sugo si restringe.","Poco prima di spegnere unisci il prezzemolo tritato fine e una macinata di pepe."]'::jsonb, array['italian', 'mediterranean', 'stew', 'light', 'quick', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/merluzzo-alla-livornese/'),
  ('686a6848-a856-4bbe-b6f3-f2f4dae462d8'::uuid, 'Orata al cartoccio', 2, 4::int, 55::int, 15::int, 40::int, '["Preriscalda il forno a 180 °C.","Pulisci l''orata incidendo la pancia, eviscerala, squamala raschiando contro il verso delle squame, poi lavala e asciugala.","Affetta l''aglio, la cipolla, le carote e il limone.","Farcisci la pancia del pesce con alloro, aglio, rosmarino, timo e un pizzico di sale.","Adagia l''orata su un foglio di alluminio con carote, cipolla e limone, condisci con olio, sale e pepe e chiudi bene il cartoccio.","Cuoci in forno per circa 40 minuti.","Apri il cartoccio, elimina erbe e verdure aromatiche e servi con un filo d''olio crudo."]'::jsonb, array['italian', 'mediterranean', 'oven', 'light', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/orata-al-cartoccio/'),
  ('5d1e5db1-40e3-4f53-9d61-d92916584684'::uuid, 'Pasta e lenticchie', 2, 4::int, 65::int, 20::int, 45::int, '["Se usi lenticchie secche, mettile in ammollo circa 2 ore (accorcia la cottura); se in scatola, sciacquale e basta.","Trita finemente sedano, carota e cipolla.","Scalda l''olio in una pentola e fai soffriggere le verdure con rosmarino e aglio per qualche minuto.","Aggiungi la pancetta e le lenticchie, copri con il brodo caldo e cuoci a fuoco basso: circa 25 minuti se ammollate, 50 se secche non ammollate.","Quando le lenticchie sono tenere, unisci la pasta con altro brodo quanto basta a coprirla e cuoci circa 10 minuti mescolando.","Regola di sale e pepe e servi caldo con un filo d''olio a crudo."]'::jsonb, array['italian', 'mediterranean', 'soup', 'comfort', 'one-pot']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/allacciateilgrembiule/pasta-e-lenticchie/'),
  ('17aad271-1907-4d68-b566-8d66d014c39e'::uuid, 'Pasta tonno e ceci cremosa', 2, 4::int, 20::int, 5::int, 15::int, '["Metti a bollire l''acqua salata per la pasta.","In una padella scalda l''olio del tonno insieme all''olio extravergine.","Trita finemente la cipolla e falla appassire nell''olio a fuoco medio.","Unisci i ceci scolati e il tonno sbriciolato; per una salsa più cremosa frulla metà dei ceci con un po'' di acqua.","Cuoci la pasta al dente e scolala tenendo da parte un mestolo di acqua di cottura.","Versa la pasta in padella, aggiungi l''acqua di cottura e manteca qualche istante.","Servi con erba cipollina tritata."]'::jsonb, array['italian', 'mediterranean', 'quick', 'comfort']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/adryincucina/pasta-tonno-e-ceci/'),
  ('99a3f1c7-6d4d-4439-a8b2-a3e06f9c8a07'::uuid, 'Pesce spada alla siciliana', 2, 4::int, 30::int, 5::int, 25::int, '["Lava e taglia a metà i pomodorini; sbuccia l''aglio e trita il peperoncino se lo usi.","In una padella larga scalda un filo d''olio con aglio, peperoncino, capperi e olive per un paio di minuti.","Unisci i pomodorini con origano, basilico e un pizzico di sale; copri e cuoci 10 minuti.","Adagia le fette di pesce spada sul fondo in un solo strato, copri e cuoci altri 10 minuti.","Scopri, gira il pesce e lascia andare 5 minuti perché il sugo si restringa un po''; servi subito."]'::jsonb, array['italian', 'mediterranean', 'light', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/chezbibia/ricetta-pesce-spada-alla-siciliana/'),
  ('61e1e664-8f21-4039-82b4-008367e27c96'::uuid, 'Petto di pollo alla cacciatora', 2, 4::int, 45::int, 15::int, 30::int, '["Pulire i funghi e tagliarli a pezzi.","Tagliare il petto di pollo a bocconi piuttosto grandi.","Sbucciare l''aglio togliendo l''anima e affettare lo scalogno.","Scaldare l''olio con aglio e funghi a fuoco basso per circa 10 minuti.","Aggiungere scalogno e pollo, sfumare con il vino e rosolare finché la carne è colorita in modo uniforme.","Unire i pelati schiacciati e le olive, salare e pepare.","Cuocere dolcemente per circa 10 minuti e servire con basilico fresco."]'::jsonb, array['italian', 'mediterranean', 'stew', 'comfort', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/petto-di-pollo-alla-cacciatora/'),
  ('567369ff-11d7-4696-a56a-38bcb709f826'::uuid, 'Petto di pollo alla pizzaiola light', 2, 2::int, 30::int, 10::int, 20::int, '["In una padella larga cuocere la polpa di pomodoro con l''aglio schiacciato, sale, pepe e origano a fuoco basso per 10-15 minuti.","Regolare di sale, allungare con mezzo bicchiere d''acqua e cuocere ancora un paio di minuti.","Adagiare le fettine di pollo nel sugo, coprirle di salsa e spolverare con altro origano.","Cuocere a fuoco medio con il coperchio socchiuso per circa 10 minuti, girando la carne a metà cottura.","A fuoco spento aggiungere, se si vuole, un filo d''olio a crudo e servire con il sugo."]'::jsonb, array['italian', 'mediterranean', 'one-pot', 'light', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/lacucinasottosopra/petto-di-pollo-alla-pizzaiola-light/'),
  ('2523169e-7128-44b0-9c23-174778b41c14'::uuid, 'Polpo in umido con patate', 2, 4::int, 70::int, 10::int, 60::int, '["Pulisci il polpo togliendo occhi, becco e interiora, sciacqualo bene e taglialo a pezzetti.","Affetta sottilmente la cipolla e mettila in una pentola con olio, passata, aglio e il polpo; sala, pepa e mescola.","Copri e cuoci a fuoco basso per 40 minuti senza aggiungere acqua: il polpo cuoce nel suo liquido.","Sbuccia le patate, tagliale a pezzi regolari, sciacquale e uniscile alla pentola.","Prosegui la cottura coperto per altri 20 minuti (fino a 30 in più se il polpo è grande), finché una forchetta lo infilza senza resistenza.","Regola di sale e pepe, completa con prezzemolo fresco e un pizzico di peperoncino e servi caldo con il sugo."]'::jsonb, array['italian', 'mediterranean', 'stew', 'comfort', 'one-pot', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/cucinoperpassione/ricetta-polpo-in-umido-con-patate/'),
  ('99e6987f-43cf-4bb6-a6d2-33eca8e6d6c9'::uuid, 'Risotto ai gamberi e arancia', 2, 4::int, 30::int, 10::int, 20::int, '["Sguscia i gamberi eliminando testa e carapace.","Rosolali in padella con l''olio e l''aglio finché cambiano colore, poi tienili da parte.","In una casseruola fai appassire lo scalogno tritato nel burro, aggiungi il riso e tostalo 2-3 minuti.","Sfuma con il vino bianco e lascia evaporare.","Porta a cottura aggiungendo il brodo bollente un mestolo alla volta, mescolando spesso (circa 16-18 minuti).","Pochi minuti prima della fine unisci i gamberi e la scorza d''arancia; regola di sale.","Spegni, manteca con il burro freddo, lascia riposare un paio di minuti e servi."]'::jsonb, array['italian', 'risotto', 'fancy', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Ricette dal Mondo', 'https://www.ricettedalmondo.it/risotto-ai-gamberi.html'),
  ('48ebc83a-a38f-414e-9c34-86c41a6e7c2c'::uuid, 'Salmone in crosta di pistacchi e mandorle', 2, 2::int, 25::int, 10::int, 15::int, '["Preriscalda il forno a 200 °C.","Trita pistacchi e mandorle e mescolali con pangrattato, un pizzico di sale e l''olio fino a ottenere un composto compatto.","Ungi leggermente una pirofila e sistema i tranci di salmone.","Distribuisci la crosta sulla superficie dei tranci premendo bene.","Cuoci in forno per circa 15 minuti, finché la crosta è dorata, e servi."]'::jsonb, array['italian', 'oven', 'quick', 'fancy', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/ricetta-salmone-in-crosta-di-pistacchi-e-mandorle/'),
  ('620775f7-df12-48a6-acee-5a00dcdfeba6'::uuid, 'Saltimbocca alla romana', 2, 4::int, 20::int, 10::int, 10::int, '["Togliere grasso e nervetti dalle fettine di vitello e salarle appena, il prosciutto è già sapido.","Passare le fettine nella farina in modo uniforme.","Appoggiare su ognuna una fetta di prosciutto e una foglia di salvia, fermando con uno stuzzicadenti.","Sciogliere il burro in padella e dorare le fettine.","Bagnare con il vino bianco e lasciarlo evaporare del tutto.","Coprire e proseguire la cottura per circa 2 minuti, poi servire subito ben caldi."]'::jsonb, array['italian', 'mediterranean', 'quick', 'fancy']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/valeriaciccotti/saltimbocca-alla-romana/'),
  ('015f5e6a-260f-4598-bd56-b3e794d5a80f'::uuid, 'Scaloppine di pollo al limone', 2, 2::int, 20::int, 3::int, 15::int, '["Infarinare le fettine di pollo su entrambi i lati, scuotendo l''eccesso.","Scaldare un filo d''olio con il pizzico d''aglio in una padella antiaderente.","Rosolare le scaloppine da entrambi i lati finché sono dorate, poi salarle.","Versare il succo di limone e un bicchiere d''acqua e lasciare restringere finché si forma una salsina cremosa.","Incorporare il miele per smorzare l''acidità e girare di nuovo le fettine nel fondo.","Completare con scorza di limone grattugiata e pepe macinato, far riposare un attimo e servire con prezzemolo e il sughetto."]'::jsonb, array['italian', 'mediterranean', 'quick', 'light', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/ilcaldosaporedelsud/scaloppine-di-pollo-al-limone-facili-e-veloci/'),
  ('60fe0e85-846c-4255-941b-f36927ddbfb8'::uuid, 'Sovracoscia di tacchino al limone in padella', 2, 4::int, 75::int, 5::int, 60::int, '["Eliminare eventuali penne residue e, se si vuole, disossare la sovracoscia con un coltello.","Scaldare l''olio in padella e adagiare la carne con fette e succo di limone, sale, pepe, rosmarino e alloro.","Rosolare a fiamma vivace finché è dorata, poi girarla e dorare l''altro lato.","Sfumare con il vino bianco e far evaporare l''alcol.","Coprire, abbassare al minimo e cuocere circa un''ora, senza aggiungere acqua.","Alzare la fiamma per ridurre i liquidi e caramellare la carne nel suo fondo, girandola.","Lasciar riposare coperto 5-10 minuti prima di servire."]'::jsonb, array['italian', 'mediterranean', 'one-pot', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/ilcaldosaporedelsud/sovracoscia-di-tacchino-in-padella/'),
  ('63131dca-fae3-4d10-8d21-eb0d75a2cdc5'::uuid, 'Spaghetti alle vongole', 2, 4::int, 140::int, 5::int, 15::int, '["Metti le vongole a bagno in acqua fredda con il sale grosso per circa 2 ore, così rilasciano la sabbia.","In una padella ampia scalda l''olio con lo spicchio d''aglio e i gambi di prezzemolo per circa 1 minuto.","Aggiungi le vongole scolate, copri e cuoci a fuoco vivace finché non si aprono tutte.","Filtra e conserva il liquido di cottura, sguscia circa due terzi delle vongole ed elimina aglio e gambi.","Lessa gli spaghetti in acqua salata e scolali 5 minuti prima del tempo indicato, tenendo da parte un po'' di acqua di cottura.","Rimetti gli spaghetti in padella con le vongole, il loro liquido filtrato e un po'' di acqua di cottura; salta finché il fondo diventa denso e cremoso.","Completa con prezzemolo tritato fine e una macinata di pepe, poi servi subito."]'::jsonb, array['italian', 'mediterranean', 'fancy', 'make ahead']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/spaghetti-alle-vongole'),
  ('10e1f9f4-df57-4d78-9f93-c707704a3740'::uuid, 'Spezzatino di vitello con patate', 2, 5::int, 125::int, 15::int, 80::int, '["Pelare carota e cipolla, pulire il sedano e tagliare tutto a pezzi grossolani.","Scaldare l''olio e far appassire le verdure con le erbe aromatiche a fiamma bassa per 20-25 minuti, senza acqua.","Tagliare il vitello a cubi di 3-5 cm, eliminando grasso e cartilagini.","Unire la carne al soffritto e mescolare finché cambia colore su tutti i lati.","Sfumare con il vino rosso a fiamma alta finché evapora del tutto.","Versare il brodo caldo e cuocere a fiamma bassissima per circa un''ora, coprendo se il liquido cala troppo.","Pelare le patate, tagliarle a pezzi di almeno 4 cm e aggiungerle allo spezzatino.","Cuocere ancora circa 20 minuti, finché le patate sono tenere e il sugo è denso."]'::jsonb, array['italian', 'mediterranean', 'stew', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/spezzatino-di-vitello-con-patate/'),
  ('e602a672-019f-4399-a580-26a8268d9a62'::uuid, 'Straccetti di manzo con rucola e pomodorini', 2, 4::int, 20::int, 10::int, 7::int, '["Lavare e asciugare la rucola; lavare i pomodorini e tagliarli a metà.","Battere le fettine di manzo per assottigliarle, ridurle a strisce e passarle velocemente nella farina setacciata.","Scaldare l''olio con l''aglio in una padella antiaderente e far dorare gli straccetti a fuoco vivo per 2-3 minuti.","Salare e pepare, unire i pomodorini e saltare per circa un minuto.","Aggiungere metà della rucola, mescolare ancora un minuto e spegnere.","Impiattare su un letto di rucola e pomodorini crudi, adagiare la carne sopra e finire con un filo d''olio e aceto balsamico."]'::jsonb, array['italian', 'mediterranean', 'stir-fry', 'light', 'quick']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/renatabriano/ricetta-straccetti-di-manzo-con-rucola-pomodorini-e-aceto-balsamico/'),
  ('4147d3f8-71f3-493a-987d-035d634235c5'::uuid, 'Straccetti di manzo con verdure', 2, 2::int, 40::int, 15::int, 15::int, '["Tagliare la carne a striscioline e marinarla circa 15 minuti con salsa di soia, un filo d''olio, zenzero, aglio schiacciato e amido di mais.","Ridurre carota e zucchine a bastoncini e il cipollotto a rondelle.","Saltare le verdure in padella con poco olio e un pizzico di sale a fuoco vivace per pochi minuti, lasciandole croccanti.","In un''altra padella con un filo d''olio rosolare gli straccetti per un paio di minuti, mescolando sempre.","Riunire carne e verdure, aggiungere i semi di sesamo e saltare a fuoco alto per 1-2 minuti; servire subito."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'light']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'GialloZafferano', 'https://blog.giallozafferano.it/pelledipollo/ricetta-straccetti-di-manzo-con-verdure/'),
  ('6293ce0d-a630-48c6-b558-37f7a09ff101'::uuid, 'Tagliata di manzo con rucola e parmigiano', 2, 4::int, 75::int, 10::int, 10::int, '["Tirare fuori la carne dal frigo un''ora prima per portarla a temperatura ambiente.","Scaldare bene la griglia e cospargerla di sale grosso.","Cuocere il controfiletto 3 minuti per lato.","Lasciarlo riposare un minuto su un tagliere, poi affettarlo a circa mezzo centimetro e pepare.","Lavare e asciugare la rucola, togliendo i gambi lunghi.","Disporre rucola e fette di carne nel piatto, completare con scaglie di parmigiano e un filo d''olio."]'::jsonb, array['italian', 'mediterranean', 'grill', 'light', 'fancy', 'high protein']::text[], 'italian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/tagliata-di-manzo/'),
  ('eed99dab-45c0-4360-afbb-73c4b4ebc594'::uuid, 'Blanc de poulet à la basquaise', 2, 4::int, 45::int, 15::int, 30::int, '["Ouvrir chaque blanc de poulet en deux dans l''épaisseur pour obtenir de fines escalopes.","Émincer l''oignon et l''ail, épépiner le poivron et le tailler en fines lanières.","Monder la tomate 30 s dans l''eau bouillante, la peler et la concasser ; couper le jambon en lanières.","Saisir oignon, ail et poivron dans l''huile à feu vif environ 8 min, puis les réserver.","Dans la même poêle, dorer les escalopes quelques minutes de chaque côté.","Remettre les légumes, ajouter jambon, tomate et piment d''Espelette, saler, poivrer et mélanger délicatement.","Verser le vin blanc et le faire réduire à gros bouillons 3 min.","Baisser le feu et laisser mijoter environ 15 min en remuant souvent."]'::jsonb, array['french', 'stew', 'light', 'high protein']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Evous', 'https://www.evous.fr/recettes-de-cuisine/Recettes-Plat/Recette-Blanc-de-poulet-a-la,1116941/'),
  ('f57e24d7-670a-41d7-89de-13783e359454'::uuid, 'Blanquette de veau légère', 2, 2::int, 55::int, 15::int, 40::int, '["Porter une cocotte d''eau à ébullition ; pendant ce temps, éplucher et émincer oignon, échalote et carottes.","Plonger la viande et les légumes dans l''eau bouillante avec le thym, saler, poivrer, couvrir et cuire 30 min.","Égoutter le tout, le remettre dans la cocotte avec les champignons égouttés et faire revenir brièvement.","Incorporer la crème et le jus de citron en mélangeant bien jusqu''à ce que la sauce nappe.","Servir aussitôt, par exemple avec des haricots verts."]'::jsonb, array['french', 'stew', 'light', 'comfort', 'high protein']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, '750g', 'https://www.750g.com/blanquette-de-veau-version-light-r32377.htm'),
  ('449a378d-34ee-45e9-b50d-4fd3ee78ab88'::uuid, 'Blanquette de veau one pot', 2, 4::int, 110::int, 20::int, 90::int, '["Couper le veau en gros morceaux, les carottes en rondelles, les champignons en quartiers ; hacher oignon et ail, et éplucher puis couper la pomme de terre en dés.","Dans une grande cocotte, saisir rapidement le veau dans l''huile sans trop le colorer.","Ajouter oignon et ail, saupoudrer de farine et remuer 1 min.","Ajouter carottes, champignons, pomme de terre, thym et laurier, verser le bouillon chaud, saler légèrement, poivrer et mélanger.","Couvrir et cuire à feu doux 1 h 15 à 1 h 30 en remuant de temps en temps, jusqu''à ce que la viande soit fondante.","Hors du feu, fouetter la crème avec le jaune d''œuf et le jus de citron, puis l''incorporer doucement sans refaire bouillir.","Parsemer de persil et servir."]'::jsonb, array['french', 'one-pot', 'stew', 'comfort', 'high protein']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Croq''Kilos', 'https://www.croq-kilos.com/actus/recette-de-one-pot-blanquette'),
  ('50ecea78-6439-45fa-8702-4656b35e676d'::uuid, 'Brandade de morue légère', 2, 4::int, 1485::int, 20::int, 40::int, '["La veille, rincer la morue et la laisser dessaler 24 h au réfrigérateur dans de l''eau froide, en renouvelant l''eau 3 à 4 fois.","Éplucher et couper les pommes de terre, puis les cuire à l''eau bouillante jusqu''à ce qu''elles soient tendres.","Mettre la morue et l''ail écrasé dans de l''eau froide et pocher 8 à 10 minutes à petits frémissements, sans bouillir.","Égoutter la morue, ôter peau et arêtes, puis l''effilocher finement.","Écraser les pommes de terre en ajoutant le lait tiède petit à petit, puis incorporer le yaourt ou le skyr.","Mélanger la morue à la purée en versant l''huile d''olive en filet, puis poivrer et ajouter un peu de muscade.","Réchauffer à feu doux ou 10 minutes au four à 180 °C, puis servir parsemé de persil."]'::jsonb, array['french', 'oven', 'comfort', 'make ahead', 'high protein']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Croq''Kilos', 'https://www.croq-kilos.com/actus/recette-de-brandade-de-morue-leger'),
  ('e1a56986-8c34-4f97-b92c-a9595a04b081'::uuid, 'Bœuf bourguignon', 2, 6::int, 200::int, 20::int, 180::int, '["Facultatif : la veille, faire mariner les cubes de bœuf au frais dans le vin avec un peu de carotte, l''ail écrasé et le bouquet garni.","Égoutter la viande en gardant le liquide, l''éponger, saler, poivrer et la fariner légèrement.","Saisir le bœuf par petites quantités à feu vif dans l''huile chaude d''une cocotte, puis réserver.","Dans la cocotte, faire revenir les lardons puis la carotte en rondelles 5 min.","Remettre la viande, saupoudrer du reste de farine, ajouter le concentré de tomate, puis le vin (ou la marinade filtrée), le bouillon et le bouquet garni ; porter à ébullition.","Couvrir et enfourner à 150 °C pendant 2 h 30 à 3 h, en remuant de temps en temps.","Environ 45 min avant la fin, poêler les champignons au beurre ; dans une autre poêle, glacer les oignons grelots avec un peu de beurre, de sucre et d''eau.","Ajouter champignons et oignons dans la cocotte pour les 30 dernières minutes et rectifier l''assaisonnement.","Retirer le bouquet garni, parsemer de persil et servir bien chaud."]'::jsonb, array['french', 'stew', 'comfort', 'make ahead', 'high protein']::text[], 'french', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/recette/boeuf-bourguignon-traditionnel-2988'),
  ('589fb2e8-d8cb-4568-93b3-16cca96d832b'::uuid, 'Cabillaud épicé au four et ses légumes', 2, 6::int, 55::int, 15::int, 40::int, '["Préchauffer le four à 200 °C.","Couper pommes de terre et courgettes en rondelles, l''oignon en dés et le poivron en lanières.","Mélanger ces légumes avec les tomates cerises, l''huile d''olive, le jus de citron, les gousses d''ail pelées et un peu de sel.","Étaler le tout dans un grand plat et rôtir 25 minutes.","Pendant ce temps, mélanger l''huile, le jus de citron, le paprika, le curcuma et le piment d''Espelette, puis en badigeonner les morceaux de cabillaud.","Poser le poisson sur les légumes et prolonger la cuisson de 15 minutes.","Servir parsemé de persil haché, avec des quartiers de citron."]'::jsonb, array['french', 'oven']::text[], 'french', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/cabillaud-epice-au-four-43138'),
  ('c4df5fda-28c9-43a2-96e7-7e5561d1ce17'::uuid, 'Dos de cabillaud à la basquaise', 2, 4::int, 35::int, 15::int, 20::int, '["Préchauffer le four à 210 °C. Plonger les tomates 30 secondes dans l''eau bouillante pour les peler facilement.","Épépiner les tomates et les couper en dés ; couper le poivron en cubes, émincer l''oignon et hacher l''ail.","Mettre les légumes dans une sauteuse avec un petit verre d''eau, le piment et le bouquet garni, couvrir et laisser compoter à feu doux.","Saler, poivrer, puis retirer le piment et le bouquet garni.","Cuire le riz environ 20 minutes à l''eau bouillante salée, l''égoutter et le garder au chaud.","Étaler la compotée de légumes dans un plat à gratin, poser les morceaux de cabillaud dessus, saler, poivrer et enfourner 10 minutes.","Servir le poisson et sa basquaise avec le riz."]'::jsonb, array['french', 'oven', 'light']::text[], 'french', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'WW', 'https://www.weightwatchers.com/fr/recette/dos-de-cabillaud-a-la-basquaise/5625ac93b7878c0b34e6abdf'),
  ('484ced08-5bb5-47ec-ac0a-be7990951eef'::uuid, 'Filet mignon de porc à la moutarde', 2, 4::int, 40::int, 5::int, 35::int, '["Émincer finement l''oignon.","Chauffer beurre et huile dans une sauteuse et saisir le filet mignon sur toutes ses faces.","Faire fondre l''oignon 5 min dans la matière grasse, déglacer au vin blanc et remettre la viande.","Couvrir et cuire 20 min à feu moyen, puis réserver la viande sur une assiette.","Verser la crème dans la sauteuse en raclant les sucs, saler, poivrer et délayer les deux moutardes.","Couper le filet en tranches épaisses, les remettre dans la sauce, napper et laisser mijoter doucement 10 min."]'::jsonb, array['french', 'comfort']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, '750g', 'https://www.750g.com/filet-mignon-de-porc-a-la-moutarde-r74670.htm'),
  ('77447388-35a3-4563-83f0-2ca7a120c528'::uuid, 'Filet mignon moutarde, pommes de terre et brocoli', 2, 1::int, 80::int, 10::int, 40::int, '["Fouetter moutarde, sirop d''érable, sauce soja et un peu d''huile, enrober le filet mignon et le laisser mariner au frais au moins 30 min.","Préchauffer le four à 190 °C et trancher finement les pommes de terre.","Étaler les pommes de terre dans un plat, assaisonner de sel, poivre, thym et huile, puis enfourner 15 min.","Détailler le brocoli en fleurettes.","Ajouter le filet et le brocoli à côté des pommes de terre, assaisonner et rôtir 25 à 30 min, jusqu''à 63 °C à cœur.","Laisser reposer la viande quelques minutes, la trancher et servir avec les légumes."]'::jsonb, array['french', 'oven', 'light', 'high protein']::text[], 'french', 'medium', '{"pots":1,"oven":true,"special":["thermometer"]}'::jsonb, 'Jow', 'https://jow.com/fr/recipes/filet-mignon-a-la-moutarde-pommes-de-terre-et-brocoli-8v4x3uwufp5c03fx11wy/print'),
  ('9b3c2f12-57fa-470a-81df-b5393ed78c87'::uuid, 'Moules marinières', 2, 4::int, 20::int, 10::int, 10::int, '["Rincer soigneusement les moules et jeter celles qui sont cassées ou qui restent ouvertes quand on les tapote.","Couper le céleri en petits dés, hacher les échalotes et le persil.","Faire fondre le beurre dans une cocotte et y faire suer doucement échalotes et céleri, sans coloration.","Ajouter les moules, le vin blanc, une bonne dose de poivre, le bouquet garni et le persil.","Couvrir et cuire à feu vif 3 à 4 minutes en mélangeant à mi-cuisson, jusqu''à ce que toutes les moules soient ouvertes.","Remuer une dernière fois pour enrober les moules de jus, retirer le bouquet garni et servir aussitôt."]'::jsonb, array['french', 'one-pot', 'quick', 'light']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, '750g', 'https://www.750g.com/la-meilleure-facon-de-faire-des-moules-marinieres-r207667.htm'),
  ('3716d87e-51ea-489d-9fc2-2d1322423904'::uuid, 'Navarin d''agneau léger', 2, 4::int, 95::int, 20::int, 75::int, '["Éplucher et couper carotte, navet et pommes de terre ; émincer poireau et oignon, concasser la tomate et équeuter les haricots. Dégraisser l''agneau.","Saisir l''agneau 5 à 7 min dans l''huile chaude, puis le réserver.","Faire suer l''oignon et l''ail dans la cocotte et, si souhaité, les saupoudrer de farine.","Remettre l''agneau, ajouter bouillon, tomate, carotte, navet, poireau et bouquet garni ; couvrir et laisser frémir 45 min.","Ajouter pommes de terre et haricots verts et cuire encore 15 à 20 min jusqu''à ce qu''ils soient tendres.","Rectifier l''assaisonnement, retirer le bouquet garni et servir en assiettes creuses parsemées de persil."]'::jsonb, array['french', 'stew', 'light', 'one-pot']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Croq''Kilos', 'https://www.croq-kilos.com/actus/recette-du-navarin-d-agneau-leger'),
  ('a939f34c-48e2-4fd3-bc1a-216d1801b422'::uuid, 'Navarin d''agneau printanier', 2, 4::int, 90::int, 20::int, 70::int, '["Saler et poivrer l''agneau, puis le saisir à feu vif dans l''huile chaude en cocotte, environ 3 min par face.","Ajouter carotte, navet et oignon coupés et les faire revenir 5 min à feu moyen.","Verser le vin, porter à ébullition et laisser réduire d''un tiers.","Ajouter ail, laurier, clous de girofle et thym, couvrir de bouillon, assaisonner et laisser frémir 30 min.","Ajouter les pommes de terre, le céleri et la tomate en morceaux ainsi que les petits pois.","Couvrir et poursuivre la cuisson à petit feu 20 à 30 min, jusqu''à ce que les pommes de terre soient tendres.","Parsemer de persil ciselé et servir."]'::jsonb, array['french', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, '750g', 'https://www.750g.com/navarin-printanier-r204373.htm'),
  ('f2fd383a-9f87-4d59-8b6f-1bcb8af6b4ba'::uuid, 'Papillote de cabillaud au fromage et aux poivrons', 2, 5::int, 35::int, 20::int, 10::int, '["Préchauffer le four à 180 °C (th. 6).","Laver, épépiner et peler les poivrons, puis les tailler en fines lanières.","Ciseler finement l''estragon et couper le fromage en tranches de 3 mm.","Faire fondre les lanières de poivron dans une poêle chaude avec un peu d''huile d''olive, ajouter l''estragon en fin de cuisson, assaisonner et réserver.","Retirer la peau du cabillaud et couvrir chaque filet de tranches de fromage.","Sur des feuilles de papier cuisson, disposer les poivrons puis un filet de poisson, arroser d''un filet d''huile, assaisonner et fermer hermétiquement les papillotes.","Cuire 10 minutes au four, puis servir les papillotes ouvertes à table."]'::jsonb, array['french', 'oven', 'light']::text[], 'french', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Qui veut du fromage', 'https://www.quiveutdufromage.com/r-papillote-de-cabillaud-au-fromage-et-aux-poivrons'),
  ('6fd24020-984a-437d-8c7e-66f378f054a4'::uuid, 'Papillote de cabillaud au gingembre et citron vert', 2, 4::int, 117::int, 25::int, 32::int, '["Préparer la marinade : mélanger l''ail haché, le zeste et le jus du citron vert, le gingembre râpé, le miel, l''huile d''olive et la sauce soja.","Enrober les pavés de cabillaud de marinade, couvrir et réserver 1 heure au réfrigérateur.","Préchauffer le four à 210 °C. Tailler les carottes en bâtonnets et émincer la courgette et les mange-tout.","Précuire les carottes 10 minutes à l''eau bouillante, puis les mange-tout et la courgette 2 minutes ; égoutter.","Répartir les légumes sur de grandes feuilles de papier cuisson, poser le cabillaud dessus, arroser du reste de marinade et parsemer de coriandre ciselée.","Fermer les papillotes et cuire 20 minutes au four."]'::jsonb, array['french', 'oven', 'light', 'make ahead']::text[], 'french', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'WW', 'https://www.weightwatchers.com/be/fr/recipe/papillote-cabillaud-au-gingembre-citron-vert/5d67b72532f27600dc549bec'),
  ('7e1759e4-48d3-4b1a-9b65-d3c31e93172d'::uuid, 'Pavés de saumon sur lit de lentilles', 2, 4::int, 45::int, 15::int, 30::int, '["Piquer l''oignon avec les clous de girofle, puis le mettre dans une casserole d''eau avec les lentilles, le laurier, 1 c. à soupe d''huile, du sel et du poivre.","Laisser frémir environ 25 minutes jusqu''à ce que les lentilles soient tendres, puis égoutter et retirer l''oignon et le laurier.","Dans une poêle, faire suer les échalotes dans le reste de l''huile.","Verser le vin blanc, ajouter le zeste de citron et laisser réduire de moitié.","Ajouter les lentilles, réchauffer 2 minutes, incorporer le basilic, rectifier l''assaisonnement et garder au chaud.","Allumer le gril du four. Déposer le saumon dans un plat, le badigeonner de miel et le parsemer de chapelure.","Passer sous le gril, sur la grille du haut, 5 à 7 minutes selon l''épaisseur.","Découper le saumon en pavés et les servir sur les lentilles."]'::jsonb, array['french', 'oven', 'comfort', 'high protein']::text[], 'french', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Ricardo', 'https://www.ricardocuisine.com/recettes/551-paves-de-saumon-sur-lit-de-lentilles'),
  ('0987bb18-6284-465e-9872-55a3a4917212'::uuid, 'Petit salé aux lentilles', 2, 4::int, 75::int, 15::int, 60::int, '["Rincer les lentilles à l''eau froide et les égoutter.","Dans une cocotte, faire revenir l''oignon en dés dans l''huile d''olive.","Ajouter les carottes en dés et l''ail, puis les lentilles, et remuer environ 1 minute.","Déposer le petit salé et la saucisse, verser le bouillon, puis ajouter le laurier, le thym et du poivre.","Couvrir et laisser mijoter 45 minutes à 1 heure, jusqu''à ce que les lentilles soient fondantes et la viande cuite ; ajouter un peu d''eau chaude si nécessaire.","Retirer le laurier et le thym, trancher la saucisse et parsemer de persil.","Servir bien chaud avec la moutarde à l''ancienne."]'::jsonb, array['french', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/petit-sale-aux-lentilles-38097'),
  ('e28bf347-b869-4708-97e6-b7edec18d66e'::uuid, 'Poulet au vin blanc et à l''estragon, carottes', 2, 4::int, 70::int, 15::int, 55::int, '["Préchauffer le four à 190 °C (170 °C chaleur tournante).","Disposer les blancs de poulet dans un plat à gratin et les saler.","Faire dorer les échalotes émincées dans l''huile, puis les répartir sur le poulet.","Mélanger la majeure partie du bouillon avec le vin et le fromage frais, ajouter l''estragon haché et poivrer.","Verser sur le poulet, couvrir et enfourner 30 à 35 min jusqu''à cuisson complète.","Pendant ce temps, faire revenir les carottes dans le beurre fondu, mouiller avec le reste du bouillon et cuire environ 15 min.","Ajouter le persil aux carottes, assaisonner et servir avec le poulet, décoré d''estragon."]'::jsonb, array['french', 'oven', 'light', 'high protein']::text[], 'french', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'WW', 'https://www.weightwatchers.com/ch/fr/recette/poulet-sauce-au-vin-et-lestragon/659fabb3ce8846a01bc40d10'),
  ('c342d26f-6184-4e3a-898e-bf58347b4ac2'::uuid, 'Poulet mijoté aux olives', 2, 6::int, 60::int, 10::int, 50::int, '["Saler et poivrer les morceaux de poulet, puis les dorer environ 10 min dans une cocotte avec un filet d''huile d''olive.","Retirer le poulet et faire fondre l''oignon et l''ail émincés dans la cocotte.","Remettre le poulet, mouiller avec le vin blanc et un petit verre d''eau, puis ajouter les olives égouttées.","Assaisonner avec les herbes de Provence, sel et poivre, couvrir et laisser mijoter 40 min à feu doux.","Goûter, rectifier l''assaisonnement, prolonger de quelques minutes si besoin et servir."]'::jsonb, array['french', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/recette/poulet-mijote-aux-olives-1947'),
  ('a317f775-694d-4e3d-80c1-cdd2f0e6368a'::uuid, 'Poulet à l''estragon', 2, 4::int, 40::int, 10::int, 30::int, '["Hacher finement l''ail et les échalotes et couper chaque cuisse en deux.","Chauffer l''huile dans une sauteuse, y faire fondre le beurre et dorer le poulet à feu moyen sur toutes les faces.","Ajouter ail, échalotes et estragon, puis déglacer avec le vin blanc.","Saler, poivrer, couvrir et laisser mijoter environ 20 min en remuant de temps en temps.","Retirer le poulet, incorporer la crème à la sauce et chauffer doucement jusqu''aux premiers frémissements.","Remettre le poulet dans la sauce à l''estragon et servir."]'::jsonb, array['french', 'stew', 'comfort']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Île aux épices', 'https://ileauxepices.com/blog/2014/09/25/recette-poulet-a-lestragon/wpid5861/'),
  ('c0a07491-dc99-4dc0-8895-b6358173175c'::uuid, 'Rôti de porc au lait et à la moutarde', 2, 6::int, 115::int, 10::int, 105::int, '["Préchauffer le four à 150 °C.","Peler et dégermer l''ail, puis le mettre dans une casserole avec le lait, le laurier, la moutarde et le bouillon ; saler, poivrer et mélanger.","Porter à ébullition puis laisser frémir très doucement environ 15 min.","Saisir le rôti à feu vif sur toutes ses faces dans l''huile, dans une cocotte allant au four, puis jeter la graisse.","Verser le lait infusé sur la viande, couvrir et enfourner 1 h 30.","Trancher le rôti et le servir nappé de sauce."]'::jsonb, array['french', 'oven', 'comfort', 'high protein']::text[], 'french', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/recette/roti-de-porc-a-la-moutarde-1256'),
  ('8e07faeb-77dd-4637-ac75-c74706aeb411'::uuid, 'Saumon rôti aux lentilles vertes', 2, 4::int, 60::int, 15::int, 45::int, '["Éplucher les carottes et les couper en dés ; peler l''ail et l''oignon, puis piquer l''oignon du clou de girofle.","Ficeler les herbes du bouquet garni.","Mettre les lentilles rincées dans une casserole d''eau froide avec les carottes, l''oignon, l''ail, le morceau de lard et le bouquet garni.","Porter à ébullition puis laisser frémir 30 minutes à demi-couvert, en salant à mi-cuisson.","Environ 10 minutes avant la fin, passer les pavés de saumon sous le gril du four, côté peau vers la chaleur.","Égoutter les lentilles en retirant l''oignon et le bouquet garni ; couper le lard en dés et le faire dorer dans la moitié de l''huile.","Ajouter les lentilles au lard, mélanger et garder au chaud.","Retirer la peau du saumon, saler, poivrer, arroser du reste d''huile et servir sur les lentilles."]'::jsonb, array['french', 'stew', 'comfort', 'high protein']::text[], 'french', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'La Cuisine de Julie', 'https://lacuisinedejulie.fr/recette/saumon-roti-aux-lentilles-vertes/'),
  ('419c8ae2-41ee-4db8-afd8-c6f6ff0e11be'::uuid, 'Saumon à l''oseille des frères Troisgros', 2, 4::int, 35::int, 20::int, 15::int, '["Ôter les arêtes du saumon à la pince, puis le détailler en fines escalopes d''environ 140 g.","Aplatir légèrement les escalopes entre deux feuilles de papier cuisson huilées pour obtenir une épaisseur régulière.","Effeuiller l''oseille en retirant les tiges et les nervures, la rincer et déchirer les grandes feuilles.","Dans une sauteuse, réunir l''échalote finement hachée, le fumet, le vin et le vermouth, puis réduire jusqu''à obtenir un liquide sirupeux.","Ajouter la crème et laisser frémir jusqu''à ce que la sauce nappe légèrement.","Plonger l''oseille 10 secondes en remuant la sauteuse sans fouetter, puis assaisonner de quelques gouttes de citron et de sel.","Saisir les escalopes salées dans une poêle antiadhésive très chaude, environ 10 secondes par face, en les laissant à peine cuites.","Napper des assiettes chaudes de sauce, poser le saumon dessus et servir immédiatement."]'::jsonb, array['french', 'fancy', 'high protein']::text[], 'french', 'hard', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Gilles Pudlowski', 'https://www.gillespudlowski.com/257271/recettes/recette-de-confinement-le-saumon-a-loseille-des-freres-troisgros'),
  ('df8c039d-295f-4d5a-b25a-7f45780c4209'::uuid, 'Turbot sauce vierge', 2, 4::int, 25::int, 10::int, 15::int, '["Préchauffer le four à 175 °C (350 °F).","Saler et poivrer le poisson et le déposer dans un plat ou sur une plaque couverte de papier cuisson.","Enfourner 10 à 15 minutes selon l''épaisseur des filets.","Pendant ce temps, mélanger les dés de tomate, l''huile d''olive, les câpres, le vinaigre et les herbes, puis saler et poivrer ; ajouter un peu de sucre si les tomates manquent de goût.","Sortir le poisson et le servir aussitôt nappé de sauce vierge, avec du riz ou une purée et un légume."]'::jsonb, array['french', 'oven', 'quick', 'light']::text[], 'french', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Noovo Moi', 'https://www.noovomoi.ca/cuisiner/recettes/recette.turbot-sauce-vierge.1.1423555.html'),
  ('caa6c099-644e-4533-b07e-55ea51423d4c'::uuid, 'Œufs pochés, épinards et lentilles', 2, 4::int, 30::int, 15::int, 15::int, '["Dans une grande poêle, faire revenir l''oignon, l''ail et le gingembre dans l''huile environ 3 minutes.","Ajouter le garam masala et le curcuma et remuer 30 secondes.","Ajouter la tomate râpée, les lentilles et la moitié des épinards, couvrir et cuire environ 5 minutes jusqu''à ce que les épinards tombent.","Retirer le couvercle, ajouter le reste des épinards, les laisser tomber puis saler et poivrer.","Former des creux dans la préparation et y casser les œufs.","Couvrir et laisser mijoter 5 à 6 minutes, jusqu''à ce que les blancs soient pris.","Parsemer de feta, ajouter un trait de sriracha et servir."]'::jsonb, array['french', 'one-pot', 'vegetarian', 'light']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Ricardo', 'https://www.ricardocuisine.com/recettes/8946-oeufs-poches-epinards-et-lentilles'),
  ('5a5c66cd-2943-431e-8885-d31eebc8d30e'::uuid, 'Beef bulgogi rice bowls', 2, 6::int, 105::int, 90::int, 15::int, '["Slice the beef very thinly and put it in a bowl.","Blitz the pear, onion, marinade garlic, ginger, soy sauce, brown sugar, pepper and sesame oil to a smooth purée.","Pour the purée over the beef, add half the spring onion and the carrot, mix and refrigerate at least 1 hour (overnight is best).","Cook the rice.","Heat a cast-iron pan over high heat and sear the beef in batches with a little oil, 1–2 minutes until caramelised, turning once; scrape the pan clean between batches.","Fill bowls with rice and top with the beef, kimchi, sliced raw garlic, shishito and remaining spring onion.","Finish with sesame seeds and serve with ssamjang on the side."]'::jsonb, array['korean', 'asian', 'bowl', 'make ahead']::text[], 'korean', 'medium', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'The Woks of Life', 'https://thewoksoflife.com/bulgogi-bowls'),
  ('39fd3a34-7eb2-497f-8ff1-3d247f845ea0'::uuid, 'Beef rendang', 2, 6::int, 200::int, 20::int, 180::int, '["Blitz the chilies, onion, garlic, sliced lemongrass, galangal, ginger and paste oil in a food processor until very fine.","Heat the browning oil in a heavy pot over high heat and sear the beef in batches; set aside.","Lower the heat to medium-low and fry the spice paste for 2–3 minutes until it darkens.","Return the beef with all the remaining curry ingredients, bring to a simmer and turn down to a very gentle bubble.","Cover and cook for 1 hour 15 minutes, then check the beef.","Uncover, raise the heat to medium and cook for 30–40 minutes, stirring often, until the oil separates and the sauce reduces to a dark paste clinging to the beef (add a splash of water and keep going if the meat isn''t tender yet).","Serve with steamed rice."]'::jsonb, array['asian', 'indonesian', 'curry', 'comfort', 'fancy', 'high protein']::text[], 'indonesian', 'medium', '{"pots":2,"oven":false,"special":["food processor"]}'::jsonb, 'RecipeTin Eats', 'https://recipetineats.com/beef-rendang'),
  ('48233154-365a-485a-b65e-f5d981d9d5f7'::uuid, 'Bibimbap with Korean beef', 2, 4::int, 70::int, 25::int, 25::int, '["Stir the gochujang, mirin, rice vinegar, soy sauce, sugar, grated garlic and sesame oil together until the sugar dissolves.","Mix the grated apple, garlic, ginger, soy sauce, honey and sesame oil, add the beef and marinate 30 minutes (or up to overnight).","Soak the dried shiitake in boiling water for 30 minutes, then squeeze dry and slice; cook the rice.","Sauté the shiitake, carrot, zucchini and spinach one after another in a little oil, seasoning each lightly with salt, garlic, soy and sugar.","Blanch the bean sprouts, drain and cool, then dress with sesame oil, a little garlic and the fish sauce.","Drain the beef and sear it in a very hot pan with a little oil for 3–4 minutes; keep warm.","Fry the eggs to your liking.","Fill bowls with warm rice, arrange the vegetables and beef on top, add the egg, sprinkle with sesame seeds and a drizzle of sesame oil, and serve with the sauce to mix in."]'::jsonb, array['korean', 'asian', 'bowl']::text[], 'korean', 'hard', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'RecipeTin Eats', 'https://www.recipetineats.com/wprm_print/37012'),
  ('df078eb0-325b-4dde-897e-a5fdefb5ec92'::uuid, 'Cantonese steamed fish with ginger and scallion', 2, 2::int, 20::int, 5::int, 15::int, '["Julienne the spring onions and ginger and roughly chop the coriander; keep about a third aside for topping.","Stir the soy sauce, salt and sugar into 2 tbsp hot water until dissolved.","Bring 2–5 cm of water to a boil in a steamer setup (a wok with a rack and lid works).","Put the rinsed fillet on a heatproof plate, set it in the steamer, cover and steam over medium heat 7–10 minutes (4–5 for thin fillets), until a knife slides easily through the thickest part.","Pour off the liquid on the plate and scatter the reserved aromatics over the fish.","Heat the oil in a small pan, fry the remaining ginger about 1 minute, add the white spring onion for 30 seconds, then the green parts and coriander.","Add the soy mixture, let it bubble about 30 seconds until the greens just wilt, then pour it over the fish and serve with steamed rice."]'::jsonb, array['chinese', 'asian', 'light', 'quick']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":["steamer"]}'::jsonb, 'The Woks of Life', 'https://thewoksoflife.com/cantonese-steamed-fish/'),
  ('a7ed4529-c101-447e-8900-f9b038ec9bf2'::uuid, 'Chicken larb in lettuce cups', 2, 4::int, 30::int, 15::int, 15::int, '["Toast the raw rice in a dry wok over low heat for about 10 minutes until golden and fragrant, then grind it to a coarse powder.","Heat the oil in the wok over high heat and fry half the shallots until crisp; lift them out and keep the oil in the wok.","Get the wok smoking hot again, add the minced chicken and stir-fry until browned and slightly crispy.","Season with the sugar, fish sauce and lime juice.","Stir in the toasted rice powder, chili, the remaining raw shallots, spring onion, coriander and mint and toss for about a minute.","Taste and balance with salt, chili, fish sauce or lime as needed.","Spoon into lettuce leaves and scatter the crispy shallots on top."]'::jsonb, array['asian', 'thai', 'salad', 'light', 'high protein']::text[], 'thai', 'medium', '{"pots":1,"oven":false,"special":["mortar and pestle"]}'::jsonb, 'The Woks of Life', 'https://thewoksoflife.com/chicken-larb/'),
  ('79682a8a-d507-4826-91a4-133add95113d'::uuid, 'Chinese beef and broccoli', 2, 3::int, 20::int, 10::int, 10::int, '["Stir the cornstarch into a little water until smooth, then mix in the sugar, both soy sauces, rice wine, five-spice, sesame oil and pepper.","Slice the beef thinly and toss it with about 1.5 tbsp of the sauce.","Heat the oil in a skillet or wok over high heat, spread the beef out and let it brown undisturbed for about 1 minute.","Toss the beef, add the garlic and ginger and stir-fry until the meat is no longer pink.","Pour in the rest of the sauce plus about 170 ml water and stir quickly.","Once bubbling, add the cooked broccoli, coat it in the sauce and simmer about 1 minute until glossy and thick.","Take off the heat and serve over rice, scattered with sesame seeds."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'quick']::text[], 'chinese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'RecipeTin Eats', 'https://www.recipetineats.com/chinese-beef-and-broccoli/'),
  ('28d94d63-942b-407b-b0b5-b31c5de37faa'::uuid, 'Chinese cashew chicken', 2, 4::int, 21::int, 15::int, 6::int, '["Whisk the cornstarch into the soy sauce until smooth, then add the rice wine, oyster sauce, sesame oil and white pepper.","Toss the chicken with about 1 tbsp of the sauce and leave at least 10 minutes.","Heat the oil in a wok over high heat and stir-fry the garlic and onion for about 1 minute.","Add the chicken and cook about 2 minutes, then add the bell pepper for another minute.","Pour in the remaining sauce with about 3 tbsp water and stir about 1 minute until it simmers and thickens.","Toss in the cashews, take off the heat and serve right away with rice."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'quick']::text[], 'chinese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'RecipeTin Eats', 'https://www.recipetineats.com/chinese-cashew-chicken/comment-page-24/'),
  ('00396751-d223-4187-b0ba-b2793c5f3b91'::uuid, 'Crispy scallion ginger salmon', 2, 4::int, 25::int, 10::int, 15::int, '["Heat a frying pan over medium-high heat with half the oil and lay the salmon in skin-side down.","Leave it alone to sear, 4–7 minutes per side depending on thickness, until no raw centre remains; lift it out.","Mix the soy sauce, sugar, sesame oil and salt with about 60 ml water.","Add the remaining oil to the same pan and fry the ginger until crisp, then add the spring onion until wilted.","Pour in the soy mixture, bring to a boil and switch off the heat.","Serve the salmon on rice, spooning the ginger-scallion sauce over it and scattering coriander on top."]'::jsonb, array['chinese', 'asian', 'quick', 'light']::text[], 'chinese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'The Woks of Life', 'https://thewoksoflife.com/scallion-ginger-salmon/'),
  ('2d025e3c-c006-4ef1-873b-677587924532'::uuid, 'Cá kho (Vietnamese caramelised braised mackerel)', 2, 4::int, 135::int, 15::int, 120::int, '["Cut the mackerel into thick steaks of about 4 cm, discarding the heads; rub with salt, rinse and pat dry.","Melt the sugar with a splash of water in a small pan and let it bubble, then lower the heat and cook until it turns a dark caramel colour.","Take the caramel off the heat and carefully stir in about 140 ml water to make a dark amber braising liquid.","Line a heavy pot with galangal, shallot and most of the tomato, lay the fish on top in one layer and scatter over the rest of the aromatics, tomato and chili.","Add the fish sauce, soy sauce, caramel liquid and black pepper; top up with a little water so the fish is just covered.","Bring to a boil, add the lime juice, then cover and simmer gently for about 1½ hours, basting the fish from time to time (add hot water if it dries out).","Uncover, taste, and keep braising with the lid ajar until only a thin layer of glossy sauce coats the bottom of the pot.","Serve with steamed rice."]'::jsonb, array['asian', 'vietnamese', 'stew', 'comfort', 'high protein']::text[], 'vietnamese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Delightful Plate', 'https://delightfulplate.com/?p=84242'),
  ('cb707aa6-b026-4732-a344-0eb8ba339d56'::uuid, 'Dak galbi (spicy chicken stir-fry)', 2, 3::int, 55::int, 10::int, 15::int, '["If the rice cakes are pre-packaged, separate them and soak in warm water for 10 minutes.","Stir together the gochujang, rice wine, gochugaru, soy sauce, sugar, garlic, ginger, curry powder, grated onion and a little pepper.","Coat the chicken in the marinade and leave at least 30 minutes (up to overnight for more flavour).","Heat the oil in a large skillet over medium-high heat and spread out the sweet potato, carrot, cabbage, perilla and rice cakes, with the chicken on top.","Cook 3–4 minutes, then lower to medium/medium-low and keep cooking 10–15 minutes, stirring often, until the chicken and sweet potato are cooked through (a lid speeds it up).","Serve hot with rice."]'::jsonb, array['korean', 'asian', 'stir-fry', 'comfort', 'high protein']::text[], 'korean', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'My Korean Kitchen', 'https://mykoreankitchen.com/dak-galbi/'),
  ('7604daa9-9518-4943-8ab8-875c445fe5b9'::uuid, 'Filipino chicken adobo', 2, 4::int, 120::int, 10::int, 50::int, '["Crush the garlic in a mortar, then combine with the chicken and soy sauce and marinate for at least 1 hour.","Lift the chicken out, keeping the marinade and garlic separately.","Heat most of the oil in a pot and sear the chicken for about 2 minutes per side; set aside.","Add the rest of the oil and the marinated garlic and fry until it just starts to colour.","Return the chicken with the leftover marinade, peppercorns, bay leaves and about 180 ml water; bring to a boil, cover and simmer for about 30 minutes until tender.","Pour in the vinegar and let it boil for 1 minute without stirring, then stir and simmer uncovered for 15 minutes to reduce.","Season with sugar and salt and serve hot with rice."]'::jsonb, array['asian', 'filipino', 'stew', 'comfort', 'high protein']::text[], 'filipino', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Panlasang Pinoy', 'https://panlasangpinoy.com/filipino-chicken-adobo-recipe'),
  ('f6b65e75-59a5-479d-908f-dcb0781077a6'::uuid, 'Goan-style fish curry', 2, 4::int, 35::int, 10::int, 25::int, '["Blend most of the coriander with the ginger, chili, garlic, chopped spring onion, half the lemon juice, the paste curry powder, a pinch of salt and half the coconut milk until smooth.","Cook the paste in a deep pan for a few minutes until fragrant, then add the remaining coconut milk and simmer until slightly thickened.","Rinse the rice and simmer it, covered, in water until tender and the liquid is absorbed; keep covered.","Cut the fish into strips and toss in the flour seasoned with salt and the remaining curry powder.","Shallow-fry the fish in the oil until golden and just cooked through.","Check the sauce seasoning, add the lemon juice to taste, slip in the fish to warm through and serve with the rice, shredded spring onion and remaining coriander."]'::jsonb, array['asian', 'indian', 'curry']::text[], 'indian', 'medium', '{"pots":3,"oven":false,"special":["blender"]}'::jsonb, 'Tesco Real Food', 'https://realfood.tesco.com/recipes/goan-style-fish-curry.html'),
  ('25a49043-ae42-4755-8b99-fe6b204a5964'::uuid, 'Gyudon (beef and onion rice bowl)', 2, 4::int, 40::int, 10::int, 30::int, '["Cook the rice.","Heat half the oil in a pan over medium-high heat and cook the onions about 10 minutes, stirring often, until soft.","Add the beef and sugar and stir until the beef is lightly browned.","Pour in the mirin, soy sauce and dashi and simmer 10–15 minutes until reduced to a thin sauce; taste and adjust.","Meanwhile fry the eggs sunny-side up in another pan with the remaining oil, keeping the yolks runny.","Spoon rice into bowls, pile on the beef and onions with some sauce, top each with an egg and finish with spring onion and sesame seeds."]'::jsonb, array['japanese', 'asian', 'bowl', 'comfort', 'high protein']::text[], 'japanese', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'The Woks of Life', 'https://thewoksoflife.com/gyudon-recipe-beef-rice/'),
  ('63ace58e-5c2b-45c1-9b70-599b42c3908e'::uuid, 'Gà nướng sả (Vietnamese lemongrass grilled chicken)', 2, 4::int, 240::int, 195::int, 45::int, '["Whisk all the marinade ingredients together in a bowl.","Coat the chicken well and refrigerate for at least 3 hours, ideally overnight.","Heat the grill (or a grill pan) to about 200°C.","Grill the chicken, turning now and then, until charred on both sides and 74°C in the thickest part.","Rest for 5 minutes, then slice.","Serve hot with rice or rice vermicelli."]'::jsonb, array['asian', 'vietnamese', 'grill', 'make ahead', 'high protein']::text[], 'vietnamese', 'medium', '{"pots":1,"oven":false,"special":["thermometer","barbecue"]}'::jsonb, 'Vietnamese Food Recipes', 'https://www.vietnamesefoodrecipes.com/vietnamese-grilled-chicken-with-lemongrass-ga-nuong-sa/'),
  ('60542698-8098-4b4a-9ff6-37e012332afc'::uuid, 'Healthy chicken tikka masala with spinach', 2, 4::int, 65::int, 15::int, 45::int, '["Blend the onion, garlic and ginger into a smooth paste.","Fry the paste in half the oil over medium heat for about 15 minutes until golden and sweet; scrape it out and wipe the pan.","Brown the chicken in the rest of the oil, then stir in the tikka spice and cayenne.","Add back the onion paste with the tomatoes and about 200 ml water and simmer uncovered for 15 minutes.","Stir in the ground almonds and spinach and cook 10 minutes more.","Season, take off the heat, stir through the yogurt and coriander and serve with brown basmati rice."]'::jsonb, array['asian', 'indian', 'curry', 'light', 'high protein']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'BBC Good Food', 'https://bbcgoodfoodme.com/recipes/healthy-tikka-masala'),
  ('072df74c-2984-46e1-b4fc-241bd3c22c69'::uuid, 'Kung pao chicken', 2, 4::int, 40::int, 30::int, 10::int, '["Toast the peanuts in the small amount of oil over medium heat, stirring nonstop for about 3 minutes; take off the heat, keep stirring a minute more, then let them cool and crisp up.","Toss the chicken cubes with the marinade oil, cornstarch, rice wine, salt and white pepper and leave for 20 minutes.","Combine both soy sauces, the vinegar, sugar, cornstarch and about 1.5 tbsp water in a small bowl.","Get a wok very hot, add two-thirds of the frying oil and sear the chicken until browned and just cooked; lift it out.","Turn the heat down, add the rest of the oil and fry the garlic, ginger, chilies, Sichuan pepper and spring onion until aromatic.","Put the chicken back, turn the heat to high and stir-fry for 1 minute.","Re-stir the sauce, pour it in and toss for about 1 minute until it thickens and coats the chicken.","Fold in the peanuts and serve straight away with rice."]'::jsonb, array['chinese', 'asian', 'stir-fry']::text[], 'chinese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'The Woks of Life', 'https://www.thewoksoflife.com/kung-pao-chicken/'),
  ('61be8075-e45c-435e-8e16-5746e7dbddf4'::uuid, 'Malaysian nasi goreng with chicken, prawns and egg', 2, 4::int, 30::int, 10::int, 20::int, '["Stir-fry the nasi goreng paste with the chicken and onion over medium heat for about 6 minutes.","Add the prawns and green beans and cook 5 minutes more.","Tip in the cooked rice and toss until every grain is coated and piping hot.","Divide between two bowls.","Fry the eggs and set one on each bowl; serve with lettuce, cucumber and tomato on the side."]'::jsonb, array['asian', 'malaysian', 'stir-fry', 'high protein']::text[], 'malaysian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Ayam', 'https://ayam.com/recipes/malaysian-nasi-goreng'),
  ('ef7a2f1d-b2e6-44f8-b3e8-4198959fa625'::uuid, 'Miso salmon with rice and greens', 2, 2::int, 35::int, 10::int, 25::int, '["Boil the rice in salted water until tender, then drain.","Whisk the miso, rice vinegar, ginger and garlic with 100 ml water.","Season the salmon and pan-fry it skin-side down until crisp, then turn it over.","Pour the miso sauce into the pan and slide it under a hot grill until the sauce bubbles and reduces.","Meanwhile boil the bok choy, sugar snaps and baby corn briefly until just tender, then drain.","Plate the rice and greens, set the salmon on top, spoon over the sauce and finish with spring onion."]'::jsonb, array['japanese', 'asian', 'light', 'high protein']::text[], 'japanese', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Olive Magazine', 'https://www.olivemagazine.com/recipes/healthy/miso-salmon/'),
  ('52ce91db-4179-47c8-8c68-268c31a607be'::uuid, 'Oven tandoori chicken', 2, 4::int, 415::int, 15::int, 40::int, '["Mix the yogurt, ginger-garlic paste, ground spices, salt, fenugreek leaves, oil and lemon juice; taste and adjust salt and heat.","Cut 2–3 deep slits into each piece of chicken, coat thoroughly in the marinade and refrigerate for 6 hours or overnight.","Take the chicken out of the fridge 20 minutes before cooking and heat the oven to 240°C.","Stir together the chili powder and oil for the chili oil.","Set an oiled rack over a foil-lined tray, space the chicken out on it and roast for 15 minutes; baste with leftover marinade or chili oil.","Turn the pieces and roast another 12–15 minutes, then brush with chili oil.","Move to the top shelf under the grill for 3–4 minutes until lightly charred; the thickest part should reach 75°C.","Garnish with coriander and serve with onion, cucumber and lemon wedges."]'::jsonb, array['asian', 'indian', 'oven', 'grill', 'make ahead', 'high protein']::text[], 'indian', 'medium', '{"pots":1,"oven":true,"special":["thermometer"]}'::jsonb, 'Swasthi''s Recipes', 'https://www.indianhealthyrecipes.com/tandoori-chicken/'),
  ('d5fbc6b0-5548-4b44-a525-d4671dd07f89'::uuid, 'Oyakodon (chicken and egg rice bowl)', 2, 2::int, 25::int, 15::int, 10::int, '["Cook the rice.","Slice the chicken on the diagonal into roughly 2.5 cm pieces.","Bring the mirin and sake to a boil in a large frying pan over medium-high heat, then add the dashi, soy sauce and sugar and return to a boil.","Spread the onion over the pan in one layer, lay the chicken on top, cover and bring back to a boil.","Skim off any foam and fat, then simmer over medium heat about 10 minutes until the chicken is cooked.","Drizzle the beaten eggs slowly over everything, cover and cook just until the egg is softly set, shaking the pan now and then.","Scatter over the spring onion, then slide the chicken, egg and some sauce onto bowls of rice."]'::jsonb, array['japanese', 'asian', 'bowl', 'comfort', 'quick', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Just One Cookbook', 'https://www.justonecookbook.com/recipes/oyakodon/'),
  ('b47b1a25-61a8-4ea7-8e06-77330e0d02d0'::uuid, 'Pad krapow gai (Thai basil chicken with fried egg)', 2, 1::int, 20::int, 10::int, 10::int, '["Fry the eggs in a wok in the frying oil, basting the tops with hot oil instead of flipping, until the edges are crisp; drain and keep aside.","Cut the chicken into bite-sized pieces; roughly pound the garlic and chilies in a mortar (or mince them) and pick the basil leaves.","Heat the wok over high heat with the stir-fry oil and toss the garlic and chili for about 20 seconds until fragrant, without letting them burn.","Add the chicken and stir-fry until almost cooked through, adding a tiny splash of water if the pan gets dry.","Season with oyster sauce, light and dark soy sauce and sugar, and keep tossing for about 30 seconds.","Throw in the holy basil, fold it through and take the wok off the heat as soon as it wilts.","Serve over steamed jasmine rice with the fried egg on top."]'::jsonb, array['asian', 'thai', 'stir-fry', 'quick', 'high protein']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Eating Thai Food', 'https://eatingthaifood.com/thai-basil-chicken-recipe'),
  ('7b6d0406-a5ed-4bfa-839a-a993a3868f64'::uuid, 'Satay chicken drumsticks with peanut sauce', 2, 4::int, 235::int, 10::int, 45::int, '["Cut three shallow slashes (about 5 mm deep) into the meaty side of each drumstick.","Stir together the marinade ingredients, coat the drumsticks and work the mixture into the cuts; marinate 3 hours or overnight in the fridge (optional but best).","Heat the oven to 200°C (180°C fan) and set a rack over a foil-lined tray.","Lay the drumsticks on the rack and dab any remaining marinade on top.","Bake for 35 minutes, then switch to the grill on high for 3–5 minutes to char the skin.","Meanwhile whisk all the sauce ingredients in a small pan and simmer on medium-low for about 5 minutes, stirring, until it is pourable but coats a spoon; keep warm.","Serve the drumsticks with jasmine rice and the peanut sauce for dipping."]'::jsonb, array['asian', 'thai', 'oven', 'make ahead', 'high protein']::text[], 'thai', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'RecipeTin Eats', 'https://www.recipetineats.com/satay-chicken-legs-with-peanut-sauce/'),
  ('57abb0a5-0fc5-4e5e-b5e7-7130b2e204ed'::uuid, 'Taiwanese three cup chicken', 2, 4::int, 20::int, 8::int, 10::int, '["Mix the light and dark soy, sugar and rice wine in a small bowl.","Warm the oil in a non-stick pan over medium-low and sizzle the ginger and chili for about 30 seconds.","Turn the heat to high, add the chicken and cook until the outside turns white though still raw inside; add the garlic and stir 30 seconds.","Pour in the sauce, bring to a bubble, then lower to medium/medium-high for a steady simmer.","Simmer about 5 minutes, stirring, until the chicken is coloured and the sauce has reduced to a thin syrup (add a splash of water if it reduces too fast).","Stir in the sesame oil and basil until the leaves wilt, then serve on rice with all the pan syrup."]'::jsonb, array['taiwanese', 'asian', 'stir-fry', 'quick']::text[], 'taiwanese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'RecipeTin Eats', 'https://www.recipetineats.com/taiwanese-three-cup-chicken/'),
  ('6001b71f-a4b5-458e-b945-13665dd61028'::uuid, 'Teriyaki chicken with rice', 2, 4::int, 40::int, 10::int, 30::int, '["Heat the oven to 220°C (200°C fan). Whisk the soy sauce, sugar, vinegar, half the oil, garlic and ginger together.","Toss the chicken with half of this sauce in a baking dish and roast 20–25 minutes until cooked through and sticky.","Meanwhile cook the rice as the packet directs.","Soften the onion in the remaining oil over medium heat for 5–8 minutes until lightly golden; set aside.","Stir the cornstarch into the rest of the sauce and bubble it in the pan until thick, then return the onion and add the roasted chicken.","Serve on the rice with any juices from the baking dish and the spring onion on top."]'::jsonb, array['japanese', 'asian', 'oven']::text[], 'japanese', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'BBC Good Food', 'https://www.bbcgoodfoodme.com/recipes/teriyaki-chicken/'),
  ('133f9e39-76f2-420d-954d-e311510897f2'::uuid, 'Thai green curry with chicken', 2, 4::int, 35::int, 15::int, 20::int, '["Heat the oil in a heavy pan over medium-high heat.","Fry the green curry paste with the garlic, ginger and lemongrass for 2–3 minutes until most of the moisture has cooked off (keep your face away from the fumes).","Pour in the stock and coconut milk and stir until the paste dissolves.","Season with the fish sauce and sugar, add the lime leaves and bring to a simmer.","Add the chicken, turn the heat down to a gentle bubble and cook for 7 minutes.","Add the eggplant and simmer about 5 minutes until soft; taste and adjust salt and sweetness.","Add the snow peas for 2 minutes, then stir in the basil and lime juice and take off the heat straight away.","Serve over jasmine rice."]'::jsonb, array['asian', 'thai', 'curry', 'comfort']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'RecipeTin Eats', 'https://www.recipetineats.com/thai-green-curry/'),
  ('66ead8f3-045d-4124-a93c-2ee801a03fef'::uuid, 'Brazilian fish stew (moqueca)', 2, 4::int, 35::int, 10::int, 25::int, '["Pat the fish dry, cut into large chunks and rub with salt, lime zest and lime juice; set aside.","In a wide pan, sauté the onion in the oil with a pinch of salt until soft.","Add carrot, red pepper, garlic and jalapeño and cook a few minutes more.","Stir in the tomato paste, paprika, cumin and stock, bring to a simmer, add the tomatoes, cover and cook until the carrots are tender.","Pour in the coconut milk and adjust the salt.","Tuck the fish into the sauce and simmer gently, spooning broth over, until just cooked (thick pieces can finish in a 175°C oven).","Add a squeeze of lime, scatter with herbs and serve over rice."]'::jsonb, array['brazilian', 'stew', 'comfort', 'high protein']::text[], 'brazilian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Feasting at Home', 'https://www.feastingathome.com/brazilian-fish-stew-aka-moqueca'),
  ('259ada42-4c9b-4936-88ec-79c0ba6bb82b'::uuid, 'Cajun salmon and sweet potato chowder', 2, 4::int, 35::int, 15::int, 20::int, '["Heat the oil in a saucepan over medium-high heat, add the carrot, onion and celery, cover and cook about 5 minutes until softened.","Add the bell pepper and Cajun seasoning and cook 2 minutes more.","Add the sweet potato, stock and about 120 ml water, bring to a boil, then cover and simmer about 10 minutes until the potato is tender.","Add the salmon and corn and simmer about 3 minutes until the fish is just opaque in the centre.","Turn the heat to low, stir in the half-and-half, basil and salt and warm through for 1 minute.","Take off the heat, stir in the lemon juice and serve."]'::jsonb, array['american', 'soup', 'light']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'WW', 'https://www.weightwatchers.com/us/recipe/cajun-salmon-sweet-potato-chowder/56d82afd0ac646df0ee3e08f'),
  ('d939ecdf-9a41-49f5-87f1-33289d9daeea'::uuid, 'Cajun salmon with sweet potato wedges', 2, 2::int, 40::int, 10::int, 30::int, '["Heat the oven to 200C (180C fan).","Toss the wedges on a non-stick tray with half the oil, the rosemary and some salt and roast 25-30 minutes until crisp outside and soft inside.","Rub the salmon with a little oil and coat it in the Cajun seasoning.","For the last 10 minutes of the wedges, roast the salmon on a small tray alongside.","Dress the rocket with the remaining oil and the vinegar and serve with the salmon and wedges."]'::jsonb, array['american', 'oven']::text[], 'american', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Olive Magazine', 'https://www.olivemagazine.com/recipes/fish-and-seafood/cajun-salmon-with-rosemary-sweet-potato-wedges/'),
  ('376e8ca0-3d31-4b62-852c-ac2fdc9e9648'::uuid, 'Carne asada bowls with chipotle crema', 2, 4::int, 70::int, 30::int, 10::int, '["Combine oil, soy sauce, lime juice, cumin, chipotle powder, coriander and garlic in a zip bag.","Add the steak and marinate in the fridge at least 30 minutes (up to 8 hours).","Heat a grill to high, take the steak out of the marinade, salt both sides and grill about 5 minutes per side.","Rest the steak loosely covered for 5-10 minutes, then slice across the grain and dice.","Toss the cooked rice with coriander and lime juice.","Blend the crema, chipotle, garlic, lime and salt until smooth.","Fill bowls with rice, steak, pico de gallo, avocado, jalapeño, radish and cheese, then drizzle with the chipotle crema."]'::jsonb, array['mexican', 'bowl', 'grill', 'high protein']::text[], 'mexican', 'medium', '{"pots":0,"oven":false,"special":["blender","barbecue"]}'::jsonb, 'Whitney Bond', 'https://whitneybond.com/carne-asada-bowl/'),
  ('7dfb17b4-788e-4166-8e3f-0327f79e3794'::uuid, 'Chicken and sweet potato traybake', 2, 4::int, 60::int, 15::int, 45::int, '["Heat the oven to 200C (180C fan).","Toss the sweet potato, onion and garlic with the thyme, rosemary, most of the oil and some seasoning, and roast 15 minutes.","Stir, nestle in the chicken, drizzle with the rest of the oil, add the lemon juice and smoked paprika and roast 15 minutes more.","Add the broccoli and most of the stock and roast a final 15-20 minutes, topping up with stock if the tray dries, until the chicken is cooked through.","Squeeze the soft garlic out of its skins over the tray and serve with lemon wedges."]'::jsonb, array['british', 'oven', 'light', 'high protein']::text[], 'british', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Tesco Real Food', 'https://www.tesco.com/recipes/en-GB/recipe/chicken-and-sweet-potato-traybake'),
  ('27e46b96-2742-476c-bc1f-e5c23aa41f11'::uuid, 'Chicken souvlaki with tzatziki', 2, 4::int, 200::int, 5::int, 15::int, '["Whisk the oil, lemon juice, garlic, oregano, salt and pepper into a marinade.","Coat the chicken cubes in it and leave in the fridge for 3-4 hours.","Soak wooden skewers in water, then thread on the chicken and brush with the leftover marinade.","Grill for 10-15 minutes, turning now and then, until cooked through.","Warm the pitas on the grill.","Serve the skewers on the pitas with tomato slices and tzatziki."]'::jsonb, array['greek', 'mediterranean', 'grill', 'wrap', 'make ahead', 'high protein']::text[], 'greek', 'medium', '{"pots":0,"oven":false,"special":["barbecue"]}'::jsonb, 'SBS Food', 'https://www.sbs.com.au/food/recipe/chicken-souvlaki/j847ixvsa'),
  ('7fa7da2a-36aa-4a38-95f7-b0269eae6257'::uuid, 'Chicken tinga', 2, 6::int, 30::int, 10::int, 20::int, '["Heat the oil over medium heat and fry the sliced onion about 3 minutes.","Add the garlic and cook 2 more minutes until fragrant.","Stir in the tomatoes and parsley, reduce the heat and cook 6-7 minutes until the tomatoes break down (add a splash of water if dry).","Add the shredded chicken and chopped chipotle and simmer about 8 minutes so the flavours meld.","Season with salt and pepper, garnish with parsley and serve with rice and salad or on tostadas."]'::jsonb, array['mexican', 'stew', 'light']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Mexico in My Kitchen', 'https://www.mexicoinmykitchen.com/chicken-tinga-recipe/'),
  ('c48e4b57-7ea0-42c9-b482-1f84126f5951'::uuid, 'Doro wat', 2, 4::int, 155::int, 35::int, 120::int, '["Rub the chicken with lemon juice, rinse well, season with salt and leave 30 minutes.","Cook the onions in a dry saucepan over medium-low heat, stirring now and then, for at least an hour until deeply caramelised.","Add the oil and keep cooking the onions 15-20 minutes until they turn darker.","Stir in the berbere, garlic, ginger, cardamom and ghee.","Add the chicken, cover and cook 10 minutes, then add about 250 ml water, cover again and cook 30 minutes more.","Meanwhile boil the eggs about 10 minutes, chill in iced water, peel and cut into pieces.","Add the eggs to the stew, season with mekelesha and salt, and serve with rice or injera."]'::jsonb, array['ethiopian', 'african', 'stew', 'comfort', 'curry', 'high protein']::text[], 'ethiopian', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Eggs.ca', 'https://eggs.ca/recipes/doro-wat/'),
  ('eab5838e-660b-4b5f-9444-00603cb201fa'::uuid, 'Greek baked fish (psari plaki)', 2, 6::int, 40::int, 10::int, 30::int, '["Heat the oven to 200°C (400°F) with a rack in the middle.","In an oven-safe pan, cook the onion in the olive oil with a pinch of salt until soft and lightly golden.","Stir in the garlic, then the tomatoes, oregano and pepper; crush the tomatoes, bring to a boil and simmer 10-15 minutes.","Dry the fish and season both sides with salt, oregano, paprika and cumin; squeeze half the lemon over it.","Settle the fish into the sauce and spoon some sauce on top.","Bake 15-25 minutes until the fish is opaque and flakes easily; check so it doesn''t overcook.","Scatter with parsley and serve with the remaining lemon in wedges, plus bread or rice."]'::jsonb, array['greek', 'mediterranean', 'oven', 'light']::text[], 'greek', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'The Mediterranean Dish', 'https://www.themediterraneandish.com/baked-greek-fish-psari-plaki'),
  ('88cbc523-853f-41c7-b63a-f0f761e56e3b'::uuid, 'Harissa roast salmon with herby grains', 2, 2::int, 35::int, 10::int, 20::int, '["Simmer the grains in salted water for 20-25 minutes until just tender.","Heat the oven to 180°C (160°C fan); mix harissa, oil, honey and the juice of half the lemon.","Toss the salmon and tomatoes in the harissa mix in a baking dish and roast 15 minutes.","In a large bowl combine the spring onions, most of the herbs, the rest of the lemon juice and a little oil.","Drop the peas into the grains for the last minute, then drain thoroughly.","Stir the leftover herbs into the yogurt with salt and a splash of water to loosen.","Toss the grains and peas with the spring onion mix, plate, top with salmon and tomatoes and add the yogurt dressing."]'::jsonb, array['north african', 'mediterranean', 'oven', 'bowl', 'light', 'high protein']::text[], 'north african', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Olive Magazine', 'https://olivemagazine.com/recipes/fish-and-seafood/harissa-roast-salmon-with-warm-herby-grains-and-yogurt-dressing'),
  ('21e7d4dc-7424-4a23-b4c8-b3410109c188'::uuid, 'Healthy cottage pie', 2, 6::int, 90::int, 15::int, 65::int, '["Spray a casserole with oil and soften the onion over medium heat.","Add the garlic, carrot, celery, salt, herbs, sugar and bay leaf and cook about 8 minutes.","Add the mince, breaking it up, and cook until well browned.","Stir in the tomato paste, then the balsamic, soy and Worcestershire sauce.","Add the squash and stock, partly cover and simmer 30 minutes; thicken with the cornstarch slaked in a little cold water and remove the bay leaf.","Meanwhile boil the potatoes in salted water about 15 minutes until tender, drain (keeping a splash of the water) and mash with the yogurt or fromage frais.","Heat the oven to 220C, spread the filling in a baking dish, cover with the mash and rough up the top with a fork.","Sprinkle with parmesan and bake 30-35 minutes until golden; rest 10 minutes before serving with green veg."]'::jsonb, array['british', 'oven', 'comfort']::text[], 'british', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Supergolden Bakes', 'https://www.supergoldenbakes.com/wprm_print/healthy-cottage-pie'),
  ('b0816cc0-d7b8-4649-88e0-b13c37a64404'::uuid, 'Healthy turkey chili', 2, 6::int, 55::int, 10::int, 45::int, '["Heat the oil in a large pot over medium-high heat and cook the onion, garlic and pepper for 5-7 minutes, stirring often.","Add the turkey and break it up with a spoon until it is no longer pink.","Stir in the chili powder, cumin, oregano, cayenne and salt and toast for about 20 seconds.","Add the tomatoes, stock, kidney beans and corn and bring to a boil.","Lower the heat and simmer 30-45 minutes until thick, then adjust the seasoning.","Serve topped with a little cheese, avocado or coriander if you like."]'::jsonb, array['american', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Ambitious Kitchen', 'https://ambitiouskitchen.com/seriously-the-best-healthy-turkey-chili'),
  ('72202527-c9b6-4d93-a159-0f71b4d22001'::uuid, 'Irish lamb stew', 2, 6::int, 210::int, 15::int, 135::int, '["Toss the lamb with half the garlic, the rosemary and the white wine and leave to marinate for 1 hour; drain and discard the liquid.","Heat the oil in a heavy pot and brown the lamb on all sides in small batches; set aside.","Soften the onion in the same pot for about 4 minutes, then add the remaining garlic for 1 minute.","Return the lamb with the chili flakes, roasted peppers, tomato, bay leaf and red wine; bring to a boil and simmer 15 minutes.","Pour in the stock and cook gently on low for 1.5-2 hours until the lamb is very tender.","Season with salt and pepper and serve with rice or crusty bread."]'::jsonb, array['irish', 'stew', 'comfort', 'make ahead', 'high protein']::text[], 'irish', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'IrishCentral', 'https://irishcentral.com/culture/food-drink/healthy-lamb-stew-recipe'),
  ('8415659c-0fbe-4c0f-879f-6902ec41c28b'::uuid, 'Jerk chicken curry with beans', 2, 4::int, 45::int, 5::int, 40::int, '["Rub the drumsticks with a little of the jerk seasoning plus salt and pepper.","Brown them in half the oil, then lift out onto a plate.","Add the rest of the oil and soften the onion and coriander stalks for about 5 minutes, stirring in the remaining jerk seasoning for the last minute.","Put the chicken back, add the tomatoes, bring to a simmer, cover and cook 20 minutes; start the rice meanwhile.","Uncover, add the beans and simmer 10 minutes more until the chicken is cooked through.","Scatter with coriander leaves and serve with the rice."]'::jsonb, array['caribbean', 'curry', 'comfort', 'high protein']::text[], 'caribbean', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'BBC Good Food', 'https://www.bbcgoodfoodme.com/recipes/jerk-chicken-curry-with-beans'),
  ('ff2f10ad-8161-4b4b-aba7-4d79a27d86cb'::uuid, 'Jerk chicken with sweet potato fries', 2, 2::int, 55::int, 15::int, 40::int, '["Heat the oven to 200C (180C fan) and line two baking trays.","Cut the sweet potatoes into finger-thick chips, toss with most of the oil and a pinch of salt and spread on one tray.","Rub the jerk seasoning into the chicken and lay it on the second tray.","Roast 20 minutes with the chicken on the top shelf and the chips below, then swap the trays and roast 15-20 minutes more until the chips are tender and charred and the chicken is cooked.","Meanwhile mix the tomatoes, onion and chilli with the lime zest, half the lime juice, a drizzle of oil and a pinch of salt.","Serve the chicken and chips with the tomato salad, lamb''s lettuce and the rest of the lime in wedges."]'::jsonb, array['caribbean', 'oven', 'light', 'high protein']::text[], 'caribbean', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Abel & Cole', 'https://www.abelandcole.co.uk/box-recipes/jerked-chicken-with-sweet-potato-fries-tomato-salad'),
  ('7ff5c0bd-3b85-48ab-8595-8379faa87fc3'::uuid, 'Lamb kofta with herby yogurt', 2, 4::int, 35::int, 10::int, 15::int, '["Combine the lamb with the garlic, grated onion, spices, herbs, salt and pepper.","Split into 4 portions, press each around a skewer into a long kofta and chill 10-15 minutes if time allows.","Stir the yogurt with the garlic, lemon juice, herbs and seasoning; keep cold.","Heat a grill or barbecue to medium-high and brush the koftas with oil.","Grill 12-15 minutes, turning often, until browned and cooked through (70°C inside).","Serve with warm flatbreads, the yogurt sauce, lettuce, cucumber and red onion."]'::jsonb, array['middle eastern', 'mediterranean', 'grill', 'wrap']::text[], 'middle eastern', 'easy', '{"pots":0,"oven":false,"special":["barbecue"]}'::jsonb, 'Hampshire Fare', 'https://hampshirefare.co.uk/recipes/lamb-kofta-with-herby-yogurt-and-flatbreads/'),
  ('1e932845-59bf-429a-9ef5-73ddfd24e7ee'::uuid, 'Lebanese chicken shawarma wraps', 2, 4::int, 210::int, 10::int, 20::int, '["Mix the garlic, lemon juice, yogurt, salt, spices and olive oil into a marinade.","Coat the chicken in it and refrigerate 3 hours or overnight (at least 1 hour if pressed).","Heat the frying oil in a wide pan until very hot.","Cook the chicken in a single uncrowded layer, about 2 minutes per side for thin breast slices, until browned and cooked through.","Cut the cooked chicken into strips.","Spread toum down the centre of each pita, add the chicken, pickles and fries if using.","Roll up tightly and halve to serve."]'::jsonb, array['lebanese', 'mediterranean', 'wrap', 'make ahead']::text[], 'lebanese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Munaty Cooking', 'https://www.munatycooking.com/chicken-shawarma/'),
  ('e31d848c-77d0-4a82-852f-d6885f91706a'::uuid, 'Lighter Swedish meatballs', 2, 4::int, 40::int, 10::int, 30::int, '["Soften the onion and garlic in the oil, add the celery and parsley for a couple of minutes, then let the mix cool.","Combine the turkey, beef, egg, cooled vegetables, breadcrumbs, salt, pepper and allspice; shape into 8 meatballs.","Bring the broth to a boil in a skillet, lower to a simmer and add the meatballs.","Cover and poach about 20 minutes until cooked through, then lift the meatballs out.","Strain the broth and blend it with the cream cheese until smooth.","Return the sauce and meatballs to the skillet and simmer a few minutes until the sauce thickens slightly; garnish with parsley."]'::jsonb, array['swedish', 'one-pot', 'comfort', 'high protein']::text[], 'swedish', 'medium', '{"pots":1,"oven":false,"special":["blender"]}'::jsonb, 'Skinnytaste', 'https://www.skinnytaste.com/swedish-meatballs/'),
  ('fc33d4ff-b75f-430a-b4e4-bff6fcb450a4'::uuid, 'Lighter chicken paprikash', 2, 4::int, 25::int, 10::int, 15::int, '["Put a pan of salted water on to boil and cook the egg noodles while you make the sauce.","Heat the oil in a large skillet over medium-high heat and cook the chicken until no longer pink; lift it out.","Soften the onion in the same pan, then add the garlic for about a minute.","Return the chicken with both paprikas, the stock, tomatoes, salt and pepper; bring to a boil and cook about 2 minutes until a little thicker.","Take the pan off the heat and stir in the yogurt (off the heat so it doesn''t split); adjust the seasoning.","Spoon over the noodles and finish with parsley."]'::jsonb, array['hungarian', 'stew', 'quick', 'comfort', 'high protein']::text[], 'hungarian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Recipe Runner', 'https://reciperunner.com/easy-smokey-chicken-paprikash/'),
  ('5bfdb175-f3b8-4a0a-a4ac-d972e6504617'::uuid, 'Moroccan chicken tagine with olives and lemon', 2, 4::int, 90::int, 15::int, 75::int, '["Mix most of the garlic with all the ground spices; finely chop one zest strip and mix it with the remaining garlic.","Pat the chicken dry, season, and brown it well in hot oil in a heavy pot, in batches; set aside.","Pour off most of the fat, then soften the onion with the remaining zest strips.","Stir in the spice paste for about 30 seconds, then add carrots, stock and honey, scraping the pot.","Return the chicken and juices, cover and simmer gently until tender, about 1 hour for thighs (add breast pieces only for the last 20 minutes).","Lift out the chicken and keep warm; skim the sauce, add the olives and simmer until slightly thickened and the carrots are soft.","Put the chicken back, stir in the garlic-zest mix, coriander and lemon juice, adjust seasoning and serve."]'::jsonb, array['moroccan', 'north african', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'moroccan', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'America''s Test Kitchen', 'https://www.americastestkitchen.com/recipes/5189-moroccan-chicken-tagine-with-olives-and-lemon-djej-emshmel'),
  ('89dd9707-0a47-4448-9592-cdae9bfb9fb4'::uuid, 'Peruvian roast chicken with green sauce', 2, 4::int, 480::int, 20::int, 90::int, '["Blitz the marinade ingredients (oil, lime juice, garlic, salt, spices, oregano, sugar) until smooth.","Dry the chicken, loosen the skin over breast and legs, push most of the marinade underneath and rub the rest outside.","Refrigerate at least 6 hours or overnight.","Heat the oven to 220°C (425°F) with a rack low-middle; set the chicken on an oiled rack over a foil-lined pan and tie the legs.","Roast 20 minutes until golden, then lower to 190°C (375°F) and roast until the juices run clear (about 70 minutes for a 1.8 kg bird, less for a smaller one); tent with foil if browning too fast.","Blend jalapeños, coriander, garlic, mayonnaise, sour cream, lime juice, salt and pepper, then stream in the oil with the motor running; chill to thicken.","Rest the chicken under foil about 20 minutes, carve and serve with the green sauce."]'::jsonb, array['peruvian', 'oven', 'comfort', 'make ahead', 'high protein']::text[], 'peruvian', 'medium', '{"pots":1,"oven":true,"special":["blender"]}'::jsonb, 'Once Upon a Chef', 'https://onceuponachef.com/recipes/peruvian-style-roast-chicken-with-green-sauce.html/comment-page-4'),
  ('f0116db7-383f-4d62-870c-ab0b0417a431'::uuid, 'Seared harissa salmon with cauliflower and chickpeas', 2, 4::int, 60::int, 15::int, 35::int, '["Stir the harissa and honey together; set aside.","In a large bowl toss the chickpeas with part of the oil, the lemon juice and the shallot.","Cook the cauliflower with most of the ground coriander, half the salt and more oil in a covered nonstick skillet until starting to soften, then uncover and cook until spotty brown.","Add the cauliflower to the chickpeas with the olives, coriander and mint; keep warm and wipe out the pan.","Season the salmon with the rest of the coriander and salt and sear it, skinned side up, in the remaining oil until deeply browned.","Flip and cook until the centre reaches about 50°C (125°F) for medium-rare.","Off the heat brush the fillets with the harissa-honey, re-toss the vegetables, season and serve together."]'::jsonb, array['north african', 'mediterranean', 'one-pot', 'fancy', 'high protein']::text[], 'north african', 'medium', '{"pots":1,"oven":false,"special":["thermometer"]}'::jsonb, 'America''s Test Kitchen', 'https://www.americastestkitchen.com/recipes/16707-one-pan-seared-salmon-with-cauliflower-chickpeas-and-harissa'),
  ('a609b57d-8c52-4d05-a917-cc6e7675b365'::uuid, 'Sherry-braised chicken with chorizo and chickpeas', 2, 4::int, 45::int, 25::int, 20::int, '["Trim any fat off the chicken thighs and cut each into 2-3 pieces.","Season the chicken and brown it on both sides in half the oil over high heat; lift it out.","Deglaze the hot pan with the sherry, scraping up the browned bits, and pour it into a jug.","Lower the heat a little, add the rest of the oil with the chorizo, onion and garlic, and cook until the onion turns translucent.","Return the sherry and chicken with the stock, chickpeas, peppers and seasoning; bring to a simmer.","Cover and cook gently about 15 minutes until the chicken is cooked through.","Finish with chopped parsley."]'::jsonb, array['spanish', 'mediterranean', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'spanish', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Sainsbury''s Magazine', 'https://sainsburysmagazine.co.uk/recipes/mains/sherry-braised-chicken-with-chorizo-and-chickpeas'),
  ('9a677bea-e590-4684-94e4-663476eb8ad3'::uuid, 'West African chicken peanut stew', 2, 4::int, 55::int, 15::int, 40::int, '["Soften the onion in half the oil for about 5 minutes, then add the sweet potato and pepper and cook 10 minutes more; set aside.","Whisk the peanut butter into the hot stock until smooth.","Cook the rice according to the packet.","Heat the remaining oil and fry the chicken with the garlic, ginger, ground coriander, cumin and chilli for about 5 minutes until golden.","Return the vegetables, pour in the peanut stock and simmer about 20 minutes until thick and the chicken is cooked through.","Serve over rice, scattered with coriander leaves and chopped peanuts."]'::jsonb, array['african', 'stew', 'comfort', 'high protein']::text[], 'african', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Tesco Real Food', 'https://www.tesco.com/recipes/en-GB/recipe/west-african-style-chicken-peanut-stew'),
  ('a726112c-2fbf-49c6-b3bc-784875bbf69e'::uuid, 'Çılbır (Turkish eggs in garlic yogurt)', 2, 2::int, 20::int, 10::int, 5::int, '["Let the yogurt come to room temperature (take it out about 30 minutes ahead).","Crush the garlic with a pinch of salt into a paste, stir it through the yogurt and spread it over two plates.","Bring a small pan of salted water with the vinegar to the boil.","Swirl the water, slip in one egg and poach 2-3 minutes until the white sets but the yolk stays runny; repeat with the second.","Meanwhile warm the olive oil over low-medium heat, add the pul biber, let it infuse about 30 seconds and take off the heat.","Drain the eggs on kitchen paper, set them on the yogurt, spoon over the chilli oil, salt and scatter with herbs.","Serve straight away with bread."]'::jsonb, array['turkish', 'mediterranean', 'quick', 'vegetarian', 'light']::text[], 'turkish', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Olive Magazine', 'https://olivemagazine.com/recipes/vegetarian/cilbir-turkish-style-poached-eggs-in-garlicky-yogurt'),
  ('352bee18-6d6b-43cb-a91e-e71ac786c563'::uuid, 'Adjaruli Khachapuri', 2, 4::int, 135::int, 25::int, 20::int, '["Put a pizza stone in the middle of the oven and heat to 260°C (500°F); oil a large bowl.","Mix yeast, sugar, oil, about 80 ml lukewarm water, flour and salt with a dough hook: 2-3 minutes on low, then 3-4 minutes on medium-low, until smooth and slightly wet.","Place in the oiled bowl, cover and leave somewhere warm 50-60 minutes until nearly doubled.","Mix the mozzarella and feta; crack the egg into a small cup, keeping the yolk whole.","Shape the dough into a ball, cover loosely and rest 15 minutes.","On floured baking paper, roll to a 25 cm round about 3 mm thick, spread with half the cheese leaving a small border, roll two opposite sides inward and pinch and twist the ends into a boat; fill the centre with the remaining cheese.","Leave uncovered 15 minutes to puff slightly, brush the edges with oil and slide onto the hot stone.","Bake 14-16 minutes until lightly golden and melted, pour the egg into the centre and bake 3-4 minutes more until the white just sets.","Dot with butter and serve hot, stirring egg and butter into the cheese at the table."]'::jsonb, array['georgian', 'oven', 'vegetarian', 'comfort', 'treat']::text[], 'georgian', 'hard', '{"pots":1,"oven":true,"special":["stand mixer","rolling pin"]}'::jsonb, 'Saveur', 'https://www.saveur.com/adjaruli-khachapuri-georgian-cheese-bread-recipe'),
  ('b4a417db-84c5-4375-9e34-ed701092ccaa'::uuid, 'Canadian Poutine', 2, 4::int, 10::int, 2::int, 8::int, '["Prepare the gravy according to the packet instructions and keep it hot over low heat.","Deep-fry the fries in oil at 350°F (175°C) until golden and crisp.","Drain the fries on a tray lined with paper towels.","Pile the fries onto plates, scatter the cheese curds on top and ladle over the hot gravy.","Eat straight away while the curds are just starting to melt."]'::jsonb, array['canadian', 'comfort', 'quick', 'treat']::text[], 'canadian', 'hard', '{"pots":2,"oven":false,"special":["thermometer"]}'::jsonb, 'An Affair from the Heart', 'https://anaffairfromtheheart.com/wprm_print/canadian-poutine-recipe'),
  ('292f619c-527e-4bce-8623-235114ca29bf'::uuid, 'Croque-monsieur maison', 2, 4::int, 25::int, 10::int, 15::int, '["Fondre le beurre dans une casserole, ajouter la farine, puis verser le lait petit à petit en fouettant pour obtenir une béchamel lisse.","Laisser épaissir, assaisonner de sel, poivre et muscade, puis retirer du feu.","Faire fondre la moitié de l''emmental dans la béchamel chaude.","Beurrer une face de chaque tranche de pain ; sur la face non beurrée de la moitié des tranches, étaler un peu de béchamel, poser le jambon et un peu de fromage, puis refermer.","Dorer les sandwichs à la poêle 3 à 4 min de chaque côté.","Les poser sur une plaque recouverte de papier cuisson, napper du reste de béchamel et parsemer du fromage restant.","Passer sous le gril environ 5 min jusqu''à ce que le dessus soit gratiné, et servir aussitôt avec une salade."]'::jsonb, array['french', 'grill', 'comfort', 'quick', 'treat']::text[], 'french', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/recette/croque-monsieur-maison-2990'),
  ('6ca01774-0338-4521-8c4e-9940cb329731'::uuid, 'Fish and Chips', 2, 2::int, 40::int, 10::int, 30::int, '["Preheat the oven to 220°C (200°C fan). Cut the potatoes, skin on, into chunky chips.","Parboil the chips for 2-3 minutes, drain well and let them steam dry.","Toss them with the vegetable oil in a roasting tin and roast 25-30 minutes, turning once, until golden.","About 15 minutes before the chips are ready, heat the olive oil in a large heavy frying pan and dust the cod with flour.","Fry the cod skin-side down for 4-5 minutes, turn and cook 5-6 minutes more until just flaking (finish very thick pieces in the oven for 5 minutes); move to warm plates.","In the same pan, sizzle the gherkins and capers for 1 minute, add the lemon juice and bubble 30 seconds on high, then take off the heat and stir in the herbs.","Top each fillet with a spoon of mayonnaise and the caper mixture, and serve with the chips."]'::jsonb, array['british', 'oven', 'comfort', 'treat']::text[], 'british', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'delicious. magazine', 'https://www.deliciousmagazine.co.uk/?p=791'),
  ('8bd9287e-0b96-4c35-8e0b-c23f0212da32'::uuid, 'Korean Fried Chicken (Yangnyeom-tongdak)', 2, 3::int, 60::int, 15::int, 40::int, '["Heat about 5 cm of oil in a heavy pot over medium-high heat for 10-12 minutes until it reaches 165-175°C; a test piece of chicken should bubble immediately.","In a large bowl, mix the wings by hand with salt, pepper, starch, flour, baking soda and eggs until evenly coated.","Add the chicken to the oil piece by piece (in batches if needed) and fry about 12 minutes, turning, until golden and crunchy.","Lift the wings onto a wire strainer set over a bowl to drain.","For the sauce, heat the oil in a large skillet, fry the garlic about 30 seconds until lightly golden, stir in ketchup, rice syrup, gochujang and vinegar, then simmer on low until bubbling and take off the heat.","Let the frying oil come back to temperature (about 2 minutes) and fry the wings a second time for about 12 minutes until extra crunchy.","Bring the sauce back to a bubble over medium-high heat, add the hot wings and toss until glossy.","Sprinkle with sesame seeds and serve, ideally with pickled radish."]'::jsonb, array['korean', 'asian', 'comfort', 'fancy', 'treat']::text[], 'korean', 'hard', '{"pots":2,"oven":false,"special":["thermometer"]}'::jsonb, 'Maangchi', 'https://www.maangchi.com/?p=11562'),
  ('42b2a8e9-670f-4c85-8abe-400bc2463633'::uuid, 'Lasagne verdi alla bolognese', 2, 8::int, 180::int, 30::int, 150::int, '["Scaldare olio e burro in una casseruola e rosolare il macinato a fiamma bassa per circa 10 minuti.","Alzare il fuoco, bagnare con il vino bianco e lasciarlo evaporare del tutto.","Unire i pelati passati e il basilico, poi cuocere circa 1 ora e mezza con il coperchio appoggiato.","Intanto cuocere gli spinaci in pentola coperta per 5 minuti senza condimento, scolarli, farli raffreddare e strizzarli bene in un canovaccio.","Frullare gli spinaci, aggiungere le due farine, l''uovo, il tuorlo e un pizzico di sale e impastare; avvolgere nella pellicola e far riposare 30 minuti.","Per la besciamella sciogliere il burro, tostare la farina fino a un roux dorato, poi versare il latte caldo in più riprese mescolando; salare e profumare con la noce moscata.","Stendere la pasta sottilissima (circa mezzo millimetro) e tagliarla a rettangoli.","Sbollentare le sfoglie 30 secondi in acqua salata con un filo d''olio, raffreddarle in acqua fredda e asciugarle su un canovaccio.","In una teglia imburrata alternare sfoglia, besciamella, ragù e parmigiano per 5 strati, chiudendo con besciamella e parmigiano.","Cuocere in forno già caldo a 170 °C per 40 minuti."]'::jsonb, array['italian', 'mediterranean', 'oven', 'comfort', 'treat']::text[], 'italian', 'hard', '{"pots":4,"oven":true,"special":["blender","rolling pin"]}'::jsonb, 'Scatti di Gusto', 'https://www.scattidigusto.it/2021/02/11/lasagne-alla-bolognese-ricetta-originale-con-ragu-cremoso-e-sfoglia-verde/'),
  ('0d73508c-6359-434b-bd0d-9ba7e7c3440d'::uuid, 'Parmigiana di melanzane in padella', 2, 4::int, 105::int, 10::int, 35::int, '["Lavare le melanzane, eliminare il picciolo e tagliarle a fette.","Disporle in uno scolapasta, cospargerle di sale e lasciarle spurgare per circa 1 ora.","Nel frattempo scaldare un cucchiaio d''olio con la passata e un po'' d''acqua, salare e cuocere a fuoco basso 10 minuti; aggiungere il basilico e spegnere.","Sciacquare le melanzane e strizzarle delicatamente.","Grigliarle poche alla volta su una piastra antiaderente appena unta finché sono morbide e segnate.","In una padella antiaderente da 24 cm alternare strati di melanzane, sugo, parmigiano e mozzarella fino a esaurire gli ingredienti.","Coprire e cuocere a fuoco medio-basso per 20-25 minuti finché la mozzarella è fusa."]'::jsonb, array['italian', 'mediterranean', 'vegetarian', 'one-pot', 'comfort', 'treat']::text[], 'italian', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Dissapore', 'https://www.dissapore.com/ricette/parmigiana-di-melanzane-in-padella-ricetta/'),
  ('ebf5318c-01b3-4cdd-98d9-9e16ab0442f6'::uuid, 'Prawn Okonomiyaki', 2, 2::int, 30::int, 10::int, 20::int, '["Whisk together ketchup, Worcestershire sauce, oyster sauce and sugar to make the okonomiyaki sauce.","Combine flour, baking powder and salt in a large bowl, beat in the stock and eggs, then fold in the cabbage and most of the spring onions.","Heat half the oil in a nonstick pan with a lid over medium heat and spoon in half the batter as a thick round about 15 cm wide; don''t press it down.","Push half the prawns into the top, cover and cook 3-5 minutes until set and golden underneath.","Flip, cover again and cook another 3-5 minutes until golden and cooked through; give each side an extra minute if needed.","Slide onto a plate, drizzle with mayonnaise and sauce, scatter with spring onions and serve with pickled ginger.","Repeat with the remaining oil, batter and prawns for the second pancake."]'::jsonb, array['japanese', 'asian', 'comfort', 'treat']::text[], 'japanese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Waitrose', 'https://www.waitrose.com/content/waitrose/en/home/recipes/recipe_directory/o/okonomiyaki.html'),
  ('badc30ce-6a6a-450a-9bcf-5e4afcf32573'::uuid, 'Rösti with Fried Eggs', 2, 4::int, 40::int, 15::int, 25::int, '["Coarsely grate the potatoes, either raw or cooked and cooled.","Finely dice half the onion and mix it into the potatoes, seasoning if you like.","Melt butter in a large pan over high heat, add the potato mixture and stir a few minutes until warmed through.","Turn the heat to medium-high and press the mixture into a flat round cake about 1-1.5 cm thick.","Slip a little extra butter around the edge and cook 5-10 minutes until a crust forms underneath.","Meanwhile, dice the remaining onion and the carrot and steam them with the peas (or spinach) in a little water under a lid.","Flip the rösti onto a plate, slide it back into the pan and cook on medium-low until crisp on the second side.","Remove the rösti, fry the eggs in the same pan and serve them on top with the vegetables alongside."]'::jsonb, array['swiss', 'vegetarian', 'comfort', 'treat']::text[], 'swiss', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Based Cooking', 'https://git.pikami.org/random-mirrors/based.cooking/src/branch/master/content/roesti.md'),
  ('72695646-987b-4eed-9407-29049d511fea'::uuid, 'Tartiflette traditionnelle', 2, 6::int, 60::int, 10::int, 50::int, '["Faire revenir l''oignon émincé et l''ail haché dans un filet d''huile jusqu''à ce qu''ils deviennent translucides, puis réserver.","Dorer les lardons dans la même poêle, remettre oignon et ail, puis déglacer au vin blanc.","Laisser le vin s''évaporer complètement, verser dans un bol et incorporer la crème, le sel, le poivre et la muscade.","Mettre les pommes de terre épluchées dans l''eau froide salée et les cuire environ 15 min : elles doivent rester un peu fermes.","Couper les pommes de terre en fines rondelles.","Frotter un plat à gratin beurré avec de l''ail, puis alterner couches de pommes de terre et de mélange aux lardons.","Gratter la croûte du reblochon, le couper en morceaux et le poser croûte vers le haut sur le dessus.","Enfourner à 180 °C pour 30 à 35 min, jusqu''à ce que le fromage soit fondu et doré, et servir bien chaud."]'::jsonb, array['french', 'oven', 'comfort', 'treat']::text[], 'french', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Demotivateur Food', 'https://www.demotivateur.fr/food/recette/tartiflette-traditionnelle-2597'),
  ('44f8d889-4d68-471f-a12e-050437c6f2d4'::uuid, 'Halal-cart chicken over rice', 2, null::int, 40::int, 15::int, 25::int, '["Toss the chicken with cumin, ground coriander, oregano, half the turmeric, 1 garlic clove, the juice of half the lemon, 1 tbsp oil, salt and pepper. Leave 10 min.","Rinse the rice. Fry it 1 min in a little oil with the rest of the turmeric, add the stock, cover and simmer 12 min; rest 5 min off the heat.","Meanwhile, cook the chicken in a hot pan with a little oil, 5-6 min per side until charred and cooked through. Rest, then chop into bite-size pieces.","Mix the yogurt, mayonnaise, vinegar, the remaining garlic, a squeeze of lemon, salt and pepper to make the white sauce.","Serve the rice topped with chicken, lettuce and tomato, drizzled with white sauce and hot sauce."]'::jsonb, array['street food', 'high protein', 'generous', 'american']::text[], 'american', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('83f42f74-df4c-4c45-be95-fa38674d1b1c'::uuid, 'Gochujang salmon rice bowl', 2, null::int, 25::int, 10::int, 15::int, '["Cook the rice according to the packet.","Toss the cucumber with the rice vinegar, a pinch of salt and a pinch of sugar; set aside to quick-pickle.","Mix gochujang, soy sauce, honey and sesame oil. Toss the salmon in half of it.","Cook the edamame in boiling water for 3 min, then drain.","Sear the salmon in a hot pan with a little oil for 3-4 min, turning, then add the remaining glaze and toss 30 s until sticky.","Fill bowls with rice, salmon, cucumber, edamame and carrot. Top with spring onion and sesame seeds."]'::jsonb, array['bowl', 'healthy', 'quick', 'asian', 'korean']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6f72d2b5-6a40-4b91-bf03-6c6a3cb4b4fb'::uuid, 'Pasta e ceci', 2, null::int, 35::int, 10::int, 25::int, '["Gently fry the onion in 2 tbsp olive oil for 5 min. Add garlic, rosemary and chilli for 1 min, then stir in the tomato paste.","Add the chickpeas and stock and simmer 10 min. Remove the rosemary and mash or blend about a third of the chickpeas to thicken.","Add the pasta and cook in the soup, stirring often, until al dente (add a splash of water if it gets too thick).","Season, then serve with Parmesan, black pepper and a drizzle of olive oil."]'::jsonb, array['soup', 'vegetarian', 'budget', 'comfort', 'italian']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('921fc083-e3e0-43a0-a015-814ba0a3fa48'::uuid, 'Poulet basquaise', 2, null::int, 55::int, 15::int, 40::int, '["Season the chicken and brown it skin-side down in a little oil in a casserole, 6-7 min, then turn for 2 min. Set aside.","In the same pot, cook the onion, peppers and ham for 8 min until soft. Add the garlic and Espelette for 1 min.","Deglaze with the wine, then add the tomatoes, bay and thyme. Return the chicken, skin up.","Cover and simmer gently 25 min, then uncover for the last 5 min to thicken the sauce.","Meanwhile, cook the rice. Serve the chicken and peppers over rice."]'::jsonb, array['one-pot', 'stew', 'french']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7375c699-23ee-487c-9121-73adc3d46728'::uuid, 'Chicken shawarma traybake', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220 °C. Mix the spices, 2 garlic cloves, the juice of half the lemon, 2 tbsp oil and salt.","Toss the chicken and onion wedges in the marinade and spread on a tray in one layer.","Roast 25-30 min until the chicken is charred at the edges. Rest 5 min, then slice.","Mix the yogurt with the remaining garlic, a squeeze of lemon and salt.","Toss tomato, cucumber and parsley with lemon juice and oil. Serve the chicken and onions with flatbreads, garlic yogurt and salad."]'::jsonb, array['oven', 'high protein', 'generous', 'middle eastern']::text[], 'middle eastern', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('7ccb7672-07ff-4746-b7b9-165af1682c26'::uuid, 'Turkey taco lettuce wraps', 2, null::int, 22::int, 10::int, 12::int, '["Cook the onion in 1 tsp oil for 3 min. Add the turkey and brown, breaking it up, 5-6 min.","Stir in garlic, chipotle, cumin, paprika and tomato paste for 1 min, then add the beans and a splash of water. Simmer 2 min until saucy.","Season with salt and the juice of half the lime.","Spoon the filling into lettuce cups and top with tomato, avocado, yogurt, coriander and lime wedges."]'::jsonb, array['low carb', 'high protein', 'diet', 'quick', 'mexican']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d31d3553-44c2-493a-ae47-a5ef771dfc03'::uuid, 'Chana masala', 2, null::int, 35::int, 10::int, 25::int, '["Start the rice according to the packet.","Heat 2 tbsp oil and sizzle the cumin seeds for 30 s. Add the onion and cook 8 min until golden.","Add garlic, ginger and chilli for 1 min, then the ground spices for 30 s.","Add the tomatoes and cook 5 min until thick, then the chickpeas and 150 ml water. Simmer 10 min, lightly crushing some chickpeas.","Season with salt and lemon juice, scatter with coriander and serve with the rice."]'::jsonb, array['curry', 'vegetarian', 'vegan', 'make ahead', 'indian']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bfa142e0-6a9e-458a-b320-536bf8aa8e76'::uuid, 'Chicken teriyaki donburi', 2, null::int, 25::int, 10::int, 15::int, '["Cook the rice. Mix soy sauce, mirin, sake and sugar.","Steam or boil the broccoli for 3-4 min.","Cook the chicken skin-side down in a little oil over medium heat for 7 min until crisp, then turn and cook 4 min more.","Wipe out excess fat, pour in the sauce and simmer 1-2 min, turning the chicken until glossy.","Slice the chicken and serve over rice with broccoli, extra sauce, spring onion and sesame."]'::jsonb, array['bowl', 'quick', 'asian', 'japanese']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('cf55fbb6-d6f4-4ed9-a1f1-b5675ef81fa4'::uuid, 'Shakshuka with feta', 2, null::int, 30::int, 10::int, 20::int, '["Cook the onion and pepper in 2 tbsp olive oil for 8 min until soft.","Add garlic and spices for 1 min, then the tomatoes. Simmer 6-8 min until thick; season.","Make 5 wells in the sauce and crack in the eggs. Cover and cook on low for 5-7 min until the whites are set and yolks still runny.","Scatter with feta and parsley and serve straight from the pan with bread."]'::jsonb, array['vegetarian', 'one-pot', 'breakfast', 'quick', 'north african', 'middle eastern']::text[], 'middle eastern', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('22aa9226-5726-4893-ab82-6cb10720509d'::uuid, 'Beef & broccoli stir-fry', 2, null::int, 25::int, 15::int, 10::int, '["Cook the rice. Toss the beef with 1 tsp cornflour and 1 tbsp soy sauce.","Mix the sauce: 2 tbsp soy, oyster sauce, sugar, sesame oil, 1 tsp cornflour and 80 ml water.","Heat a wok until smoking, add 1 tbsp oil and sear the beef in one layer, 1-2 min, without overcooking. Remove.","Add a little oil, the broccoli and 2 tbsp water; stir-fry 3 min until bright and just tender. Add garlic and ginger for 30 s.","Return the beef, pour in the sauce and toss 1 min until glossy. Serve over rice."]'::jsonb, array['stir-fry', 'high protein', 'fakeaway', 'quick', 'asian', 'chinese']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('438ce1d6-39d6-46b8-b1b4-8358a3a7e801'::uuid, 'Normandy pork medallions with apples and mash', 2, null::int, 45::int, 15::int, 30::int, '["Cut the potatoes into chunks, cover with cold salted water, bring to the boil and simmer 20 min, until a knife slides in easily.","Meanwhile, season the pork. Heat the oil and 10 g butter in a large frying pan over medium-high heat and sear the medallions 3 min per side until golden; set aside on a plate.","Core the apples and cut each into 8 wedges. Cook them in the same pan with 10 g butter for 4–5 min, turning, until golden at the edges; add them to the pork.","Soften the shallot in the pan for 2 min, then pour in the cider and scrape up the browned bits. Boil 3 min, until reduced by half.","Stir in the crème fraîche, mustard and thyme leaves and simmer 1 min. Return the pork, apples and their juices and simmer gently 3–4 min, turning, until the pork is just cooked (faintly pink in the centre).","Drain the potatoes and mash them with the remaining butter and the hot milk; season with salt and pepper.","Serve the medallions and apples on the mash with the cider sauce spooned over."]'::jsonb, array['french', 'comfort', 'autumn']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('733a1520-f3d1-47af-9be0-d422b48b2c69'::uuid, 'Warm lentil salad with beetroot and goat cheese', 2, null::int, 35::int, 10::int, 25::int, '["Toast the walnuts in the dry saucepan over medium heat for 2–3 min, until fragrant; tip them out.","Rinse the lentils, put them in the same pan with the bay leaf and thyme, cover with three times their volume of cold water and simmer 20–25 min, until tender but still holding their shape. Salt at the end.","Meanwhile, whisk the mustard, vinegar, salt and pepper, then whisk in the oil and stir in the shallot.","Drain the lentils, remove the herbs and toss them while warm with two-thirds of the dressing. Leave 5 min to absorb.","Toss the beetroot with the rest of the dressing in a separate bowl so it doesn''t stain the lentils.","Lay the rocket on plates, top with the warm lentils and beetroot, then crumble over the goat cheese and scatter the walnuts and parsley. Serve warm with the baguette slices, toasted."]'::jsonb, array['french', 'salad', 'vegetarian', 'autumn', 'winter']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('01e7604e-bc71-4e31-9a4f-180475fe8ddb'::uuid, 'Pan-fried trout with mustard lentils', 2, null::int, 40::int, 10::int, 30::int, '["Rinse the lentils and put them in a saucepan with the carrot, half the shallot and the bay leaf. Cover with 3 cm of cold water and simmer 20–25 min, until tender. Drain, keeping 3 tbsp of the cooking water.","Return the lentils to the pan over low heat with the rest of the shallot, both mustards, the vinegar, the crème fraîche and the reserved water. Stir in the spinach until it wilts, about 1 min; season and keep warm.","Pat the trout dry, score the skin lightly and season both sides.","Heat the oil in a frying pan over medium-high heat. Lay the fillets skin side down, press them flat for 10 s and cook 3–4 min, until the skin is crisp and the flesh is opaque two-thirds of the way up.","Turn the fillets, add the butter and cook 1 min more, basting.","Spoon the lentils onto plates, top with the trout and serve with lemon wedges and dill."]'::jsonb, array['french', 'healthy', 'high protein']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a28a8bc9-457a-4379-b12a-e0367cc7a7cc'::uuid, 'Chicken with leeks and mushrooms', 2, null::int, 45::int, 15::int, 30::int, '["Cook the rice in a pan of boiling salted water for 12 min (or as the packet says), then drain.","Season the chicken. Brown it in the oil in a large sauté pan over medium-high heat for 5–6 min, until golden all over; set aside.","Add the butter and mushrooms to the pan and cook 4–5 min over high heat, until their water has evaporated and they colour.","Add the leeks, garlic, thyme and a pinch of salt and cook over medium heat for 6–8 min, until soft but not browned.","Pour in the wine and boil 1 min, then add the stock and the chicken. Cover and simmer 10 min, until the chicken is cooked through.","Stir in the crème fraîche and mustard and simmer uncovered for 2 min, until the sauce coats a spoon. Adjust the seasoning.","Serve with the rice, scattered with parsley."]'::jsonb, array['french', 'comfort', 'autumn', 'winter']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('37a05a33-7df2-470d-aa32-2ffa85f7c61c'::uuid, 'Ratatouille tart with green salad', 2, null::int, 75::int, 20::int, 55::int, '["Heat 2 tbsp oil in a large frying pan and soften the onion for 5 min over medium heat; add the garlic for 1 min.","Add the aubergine and pepper and cook 8 min over medium-high heat, stirring often.","Add the courgette, tomatoes, herbes de Provence and salt and cook uncovered 10–12 min, until everything is tender and the juices have evaporated; a dry ratatouille keeps the pastry crisp. Let it cool a little.","Heat the oven to 200 °C. Line a 20–22 cm tart tin with the pastry, prick the base with a fork and spread it with the mustard.","Beat the eggs with the milk, half the emmental, salt and pepper.","Spread the ratatouille in the case, pour over the egg mixture and scatter with the remaining cheese.","Bake 30–35 min, until the pastry is deep golden and the filling is just set in the centre. Rest 5 min.","Dress the lettuce with the vinegar, the remaining oil and a pinch of salt, and serve it with the tart, topped with torn basil."]'::jsonb, array['french', 'tart', 'vegetarian', 'oven', 'summer']::text[], 'french', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('912fa9d1-a5c7-4e51-9ba9-94e7b79e82ca'::uuid, 'Truite aux amandes with green beans and potatoes', 2, null::int, 35::int, 10::int, 25::int, '["Boil the potatoes in salted water for 15–18 min, adding the green beans for the last 6 min. Drain, halve the potatoes and keep everything warm in the pot.","Season the trout and dust the fillets in flour, shaking off the excess.","Heat the oil and 10 g butter in a large frying pan over medium-high heat. Cook the fillets skin side down for 3 min, until crisp, then turn and cook 1–2 min more. Transfer to warm plates.","Wipe the pan, add the remaining butter over medium heat and, when it foams, add the almonds. Stir 1–2 min, until pale golden; watch closely, they burn quickly.","Take the pan off the heat and add the juice of half the lemon and the parsley.","Spoon the almond butter over the trout and serve with the potatoes, green beans and the rest of the lemon in wedges."]'::jsonb, array['french', 'healthy']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('526726ea-ddcf-42ae-b3bc-d66740174c06'::uuid, 'Courgettes farcies with turkey', 2, null::int, 50::int, 20::int, 30::int, '["Heat the oven to 200 °C. Halve the courgettes lengthways and scoop out the flesh with a spoon, leaving a 1 cm shell; chop the flesh. Set the shells cut side up in an oiled baking dish, season and pre-bake them for 12 min while you make the stuffing.","Soften the onion in the oil in a frying pan for 4 min, then add the garlic and the chopped courgette flesh and cook 5 min, until the moisture has gone.","Add the turkey, breaking it up, and cook 5 min until no longer pink. Add the tomatoes, tomato paste and herbs and cook 3 min more.","Off the heat, let it cool for a few minutes, then stir in the parsley, egg, half the breadcrumbs, salt and pepper.","Take the dish out and fill the pre-baked shells generously with the stuffing.","Mix the rest of the breadcrumbs with the parmesan, scatter over the top and drizzle with a little oil.","Bake 18–20 min, until the courgettes are tender to the point of a knife and the tops are golden. Serve with baguette."]'::jsonb, array['french', 'oven', 'healthy', 'summer']::text[], 'french', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('6fce5d8d-5b15-48e1-bbbc-a4f27311e708'::uuid, 'Smoked salmon and leek quiche', 2, null::int, 60::int, 15::int, 45::int, '["Heat the oven to 190 °C. Line a 20–22 cm tart tin with the pastry, prick the base and chill it while you make the filling.","Wash the leeks and sweat them in the butter with a pinch of salt, covered, for 10 min, until soft; uncover for the last 2 min to dry them. Let them cool slightly.","Beat the eggs with the crème fraîche, milk, nutmeg and pepper; add only a little salt, as the salmon is salty.","Spread the leeks over the pastry, scatter over the salmon, dill and emmental, then pour in the custard.","Bake 30–35 min, until puffed and golden and the centre barely wobbles.","Rest 10 min before cutting, and serve with a green salad."]'::jsonb, array['french', 'tart', 'oven']::text[], 'french', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('3c54ff1d-21f9-40f7-ac17-447d4677f6e0'::uuid, 'Galette complète', 2, null::int, 100::int, 10::int, 25::int, '["Whisk the flour with 0.5 tsp salt, then gradually whisk in 220 ml cold water to a smooth batter the texture of thin cream. Cover and chill for at least 1 hour (2 hours is better).","Whisk the batter again. Heat a large non-stick or crêpe pan (about 28 cm) over medium-high heat and grease it with a little butter.","Pour in a small ladle of batter (about 70 ml) and swirl it thin. Cook 1.5–2 min, until the edges lift and crisp, then turn and cook 30 s. Stack and repeat to make 4 galettes.","Return one galette to the buttered pan over medium heat. Scatter a quarter of the emmental in the centre, crack an egg on top and gently spread the white with a spatula, keeping the yolk whole.","Lay a slice of ham around the yolk and cook 3–4 min, covering the pan for a minute, until the white is set and the base is crisp.","Fold the four edges in to make a square, leaving the yolk showing. Slide onto a plate, season with pepper and chives, and repeat with the rest."]'::jsonb, array['french', 'comfort', 'budget']::text[], 'french', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('dc443c39-5da5-4243-8dd2-eb0da76ad765'::uuid, 'Roast chicken thighs with carrots and potatoes', 2, null::int, 60::int, 15::int, 45::int, '["Heat the oven to 200 °C.","Toss the potatoes, carrots, onion and garlic in a roasting tin with 1.5 tbsp oil, the thyme, salt and pepper, and spread them in one layer.","Pat the chicken thighs dry, rub them with the remaining oil, season well and set them skin side up on the vegetables.","Pour the stock into the tin around the vegetables, not over the chicken skin.","Roast 45 min, basting the vegetables once halfway, until the skin is crisp, the juices run clear (75 °C near the bone) and the vegetables are tender. For extra-crisp skin, finish 3 min under the grill.","Rest 5 min, squeeze the soft garlic into the pan juices and serve, scattered with parsley."]'::jsonb, array['french', 'oven', 'one-pot', 'comfort']::text[], 'french', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('32702abe-4094-459f-80a5-53f01914b4d3'::uuid, 'Pork chops with mustard white beans', 2, null::int, 30::int, 10::int, 20::int, '["Pat the chops dry, snip the fat at the edge in two or three places so they stay flat, and season.","Heat the oil in a large frying pan over medium-high heat. Cook the chops 4–5 min per side, until golden and 63 °C in the centre (still slightly pink), standing them on the fat edge for 1 min to render it. Rest under foil.","Lower the heat, add the butter and soften the shallot for 2 min, then add the garlic and thyme for 30 s.","Pour in the wine, scraping up the browned bits, and reduce 1 min. Add the stock and beans and simmer 4 min, crushing a few beans to thicken the sauce.","Stir in both mustards and the crème fraîche, then the spinach until it wilts, about 1 min. Add the chops'' resting juices and season.","Serve the chops on the beans, scattered with parsley, with baguette to mop up the mustard sauce."]'::jsonb, array['french', 'comfort', 'high protein']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a1f1bf80-ba8c-445f-919f-eb1dfa24d82f'::uuid, 'Roast celeriac steaks with Puy lentils', 2, null::int, 60::int, 15::int, 45::int, '["Heat the oven to 200 °C. Brush the celeriac slices with 1.5 tbsp oil, season, add the thyme and roast on a lined tray for 40–45 min, turning halfway, until deep golden and tender to a knife. Dot with the butter for the last 5 min.","Meanwhile, soften the onion, carrot and celery in 0.5 tbsp oil in a saucepan for 5 min.","Add the lentils, bay leaf, garlic and 500 ml water and simmer 20–25 min, until tender, adding a splash of water if needed. Salt at the end.","Mix the crème fraîche with 1 tsp mustard, half the parsley, salt and pepper.","Drain the lentils if needed, remove the bay leaf and stir in the vinegar, the remaining mustard and oil and the rest of the parsley. Season.","Serve the lentils topped with the celeriac steaks, a spoonful of mustard crème fraîche and the walnuts."]'::jsonb, array['french', 'vegetarian', 'oven', 'autumn', 'winter']::text[], 'french', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('5486ba0e-eda7-4b34-9db4-c6ded42efe68'::uuid, 'Sea bass with crushed potatoes, tomatoes and olives', 2, null::int, 35::int, 10::int, 25::int, '["Boil the potatoes in salted water for 15–20 min, until tender. Drain and let them steam dry for 2 min.","Crush them roughly with a fork in the pot with 2 tbsp oil, the lemon zest, salt and pepper; keep them chunky, not a purée. Cover to keep warm.","Heat 1 tbsp oil in a frying pan, add the garlic for 30 s, then the tomatoes for 3–4 min until they start to burst. Add the olives, capers and a splash of water, season and tip into a bowl. Wipe the pan.","Pat the fish dry, score the skin and season. Heat the remaining oil over medium-high heat and lay the fillets skin side down, pressing for 10 s. Cook 3–4 min, until the skin is crisp, then turn and cook 1 min.","Serve the fish on the crushed potatoes with the tomatoes and olives, torn basil and a squeeze of lemon."]'::jsonb, array['french', 'mediterranean', 'healthy', 'summer']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('10bc39c8-9e08-45f4-8b8d-083d4485392e'::uuid, 'Sole meunière with potatoes and green beans', 2, null::int, 35::int, 10::int, 25::int, '["Boil the potatoes in salted water for 15–18 min, adding the green beans for the last 6 min. Drain and keep warm.","Pat the sole dry, season both sides and dredge in flour, shaking off the excess.","Heat the oil and 10 g butter in a large frying pan over medium-high heat until foaming. Cook the fillets 2 min, turn them carefully and cook 1–2 min more, until golden and opaque; work in two batches if needed. Keep warm on plates.","Wipe the pan, add the remaining butter over medium heat and let it foam until it turns hazelnut brown and smells nutty, 2–3 min.","Take the pan off the heat and add the juice of half the lemon (it will sizzle) and the parsley.","Pour the brown butter over the fish and potatoes and serve with the green beans and lemon wedges."]'::jsonb, array['french', 'fancy']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a50426c9-afb6-41ab-ae5c-a0c08d84695c'::uuid, 'Salade niçoise with tuna and green beans', 2, null::int, 30::int, 15::int, 15::int, '["Put the potatoes in a pan of boiling salted water. After 6 min, lower in the eggs; after 4 more min, add the green beans; 5 min later drain everything and cool under cold water (eggs 9 min, potatoes 15 min).","Peel and quarter the eggs, halve the potatoes and cut the beans in two.","Whisk the mustard, vinegar, salt and pepper, then whisk in the oil.","Salt the tomato wedges lightly.","Arrange the lettuce on a large plate with the potatoes, beans, tomatoes and spring onion. Flake over the tuna and top with the eggs, anchovies, olives and capers.","Drizzle with the vinaigrette and scatter with basil just before serving."]'::jsonb, array['french', 'salad', 'mediterranean', 'summer']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0a467eb7-d057-498a-8acc-597b35c741b4'::uuid, 'Lapin à la moutarde', 2, null::int, 85::int, 15::int, 70::int, '["Season the rabbit. Heat the oil and butter in a casserole over medium-high heat and brown the legs well on all sides, about 8 min; set aside.","Lower the heat and cook the lardons, onion and shallot for 5 min, until soft and lightly golden.","Return the rabbit and coat it all over with both mustards. Pour in the wine and boil 2 min, then add the stock and bouquet garni.","Cover and simmer gently for 50 min, turning the legs halfway, until the meat comes away easily from the bone.","Towards the end, cook the tagliatelle in salted boiling water as the packet says, and drain.","Lift out the rabbit and bouquet garni. Stir the crème fraîche into the sauce and boil 3–4 min, until it coats a spoon. Season and return the rabbit to warm through.","Serve the rabbit and sauce with the tagliatelle, scattered with parsley."]'::jsonb, array['french', 'stew', 'comfort', 'fancy']::text[], 'french', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('72030c48-cb4d-4400-8a24-e49c0be5316c'::uuid, 'Hachis parmentier', 2, null::int, 70::int, 20::int, 50::int, '["Cover the potatoes with cold salted water, bring to the boil and simmer 20 min, until very tender.","Meanwhile, soften the onion and carrot in the oil in a frying pan for 6–7 min, then add the garlic for 1 min.","Raise the heat, add the beef and brown it for 5–6 min, breaking it up. Stir in the tomato paste, thyme leaves and stock and simmer 10 min, until the liquid is mostly absorbed but the meat is still moist. Stir in the parsley and season.","Heat the oven to 200 °C. Drain the potatoes and mash them with the butter, hot milk, nutmeg and salt until smooth and soft.","Spread the meat in a buttered gratin dish (about 20 × 15 cm), cover with the mash, smooth it and mark ridges with a fork. Scatter with the emmental.","Bake 20–25 min, until the top is golden and the edges bubble. Rest 5 min before serving."]'::jsonb, array['french', 'comfort', 'gratin', 'oven', 'freezer-friendly', 'winter']::text[], 'french', 'easy', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('d1469ff0-250b-44af-9740-b897725d64a9'::uuid, 'Calamars à la provençale', 2, null::int, 25::int, 10::int, 15::int, '["Cook the rice in boiling salted water for 12 min, then drain.","Meanwhile, pat the squid very dry with kitchen paper and season.","Soften the onion in 1.5 tbsp oil in a large frying pan for 5 min, then add two-thirds of the garlic for 1 min.","Add the tomatoes, herbes de Provence, bay leaf and wine and simmer briskly for 8 min, until thick. Season and tip the sauce into a bowl; wipe the pan.","Heat the remaining oil in the pan over high heat until very hot and sear the squid in one layer for 1.5–2 min, just until opaque; any longer and it turns rubbery.","Return the sauce to the pan and toss for 1 min. Off the heat, stir in the parsley mixed with the rest of the garlic and the chilli.","Serve straight away with the rice."]'::jsonb, array['french', 'quick', 'mediterranean', 'summer']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('fc1f7890-aff1-46d1-a531-9eeb03b6ba6f'::uuid, 'Bavette à l''échalote with potatoes and green beans', 2, null::int, 25::int, 5::int, 20::int, '["Boil the potatoes in salted water for 15 min, adding the green beans for the last 7 min, until both are just tender. Drain and toss with 5 g butter.","Meanwhile, pat the steak dry and salt it. Heat the oil in a heavy frying pan over high heat until smoking and sear the steak 2–3 min per side for rare to medium-rare; bavette toughens past medium.","Rest the steak on a warm plate under foil for 5 min.","Lower the heat to medium, add 15 g butter and the shallots to the pan and cook 4–5 min, stirring, until soft and golden.","Add the vinegar and wine, scrape up the browned bits and boil 1–2 min, until syrupy. Off the heat, swirl in the remaining butter, the parsley, the steak''s resting juices and plenty of pepper.","Slice the steak thinly across the grain, spoon over the shallots and serve with the potatoes and green beans."]'::jsonb, array['french', 'quick', 'high protein']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('e6a9b053-18c1-4083-bff9-6dd9c29a9b25'::uuid, 'Soupe au pistou with white beans', 2, null::int, 50::int, 20::int, 30::int, '["Heat 1 tbsp oil in a large pot and soften the onion and leek for 5 min.","Add the carrot, potato, tomato, thyme, 1.1 l water and salt. Bring to the boil and simmer 10 min.","Add the green beans, courgette, white beans and pasta and simmer 10 min, stirring now and then, until the pasta and vegetables are tender.","Check the consistency: the soup should be thick, so add a little hot water only if needed, and adjust the salt.","Meanwhile, make the pistou: crush the garlic with a pinch of coarse salt to a paste (in a mortar or with the flat of a knife), add the basil and pound or chop until fine, then work in the parmesan and the 3 tbsp oil.","Take the pot off the heat, remove the thyme and stir in half the pistou. Serve with the rest at the table."]'::jsonb, array['french', 'soup', 'vegetarian', 'one-pot', 'summer']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('cf3604f7-00c4-4439-ae7c-a23dd60cdc25'::uuid, 'Lemon, pea and ricotta pasta', 2, null::int, 22::int, 10::int, 12::int, '["Bring a large pot of salted water to the boil and cook the pasta 1 min short of the packet time.","Meanwhile mash the ricotta in a large bowl with the lemon zest, half the lemon juice, the garlic, the olive oil, half the parmesan, salt and plenty of pepper.","Add the peas to the pasta for the last 3 min of cooking.","Scoop out a mug of the cooking water, then drain the pasta and peas.","Tip them into the bowl and toss with the ricotta, adding cooking water a splash at a time until the sauce is creamy and coats the pasta.","Taste, add the rest of the lemon juice if you like, and serve topped with the remaining parmesan, the parsley and a pinch of chili flakes."]'::jsonb, array['italian', 'vegetarian', 'quick', 'mediterranean', 'spring']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('91e8fa61-df06-405b-a7c2-209948b7784f'::uuid, 'Mushroom and spinach frittata with bread', 2, null::int, 35::int, 10::int, 25::int, '["Heat the oven to 180°C.","Warm the oil in a 24 cm ovenproof frying pan over medium heat and soften the onion for 5 min.","Add the mushrooms, garlic and thyme and cook for 6–8 min, until the mushrooms are golden and their liquid has gone.","Add the spinach a handful at a time and stir until wilted and the pan is dry, about 2 min; season.","Beat the eggs with the milk, the parmesan, salt and pepper.","Pour the eggs over the vegetables, spread everything evenly and cook on low heat for 3–4 min, until the edges start to set.","Bake for 10–12 min, until the centre is just set and springs back when pressed.","Rest for 2 min, cut into wedges and serve warm with the bread."]'::jsonb, array['italian', 'vegetarian', 'oven', 'light']::text[], 'italian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('a22633f5-d714-4ccc-bc98-4d7d2c560bd9'::uuid, 'Turkey meatballs with tomato sauce and polenta', 2, null::int, 50::int, 20::int, 30::int, '["Mix the turkey, egg, breadcrumbs, half the parmesan, the grated garlic, parsley, salt and pepper with your hands, without overworking it.","Roll into 12 meatballs the size of a walnut.","Brown the meatballs in 1 tbsp oil in a wide frying pan over medium-high heat for 5 min, turning, then lift them out.","In the same pan, soften the onion and sliced garlic in the remaining oil for 4 min, then add the passata, salt and a splash of water.","Return the meatballs, cover and simmer gently for 15 min, until cooked through and the sauce has thickened; tear in the basil.","Meanwhile bring 450 ml salted water and the milk to the boil, rain in the polenta while whisking and cook for 5–8 min (see packet), stirring, until thick and smooth.","Stir the rest of the parmesan into the polenta and serve it in bowls topped with the meatballs and sauce."]'::jsonb, array['italian', 'comfort', 'high protein']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('966cf969-f9be-46cc-8715-4c5085874d48'::uuid, 'Mushroom, lentil and walnut ragù', 2, null::int, 45::int, 15::int, 30::int, '["Soften the onion, carrot and celery in the oil in a wide pan over medium heat for 6 min.","Add the mushrooms and walnuts and cook for 6 min, stirring, until the mushrooms have given up their liquid and start to brown.","Stir in the garlic and tomato paste for 1 min, then pour in the wine and let it bubble until reduced by half.","Add the tomatoes, stock, lentils, soy sauce, thyme and bay leaf, bring to a simmer, cover partly and cook for 18–20 min, stirring now and then, until the lentils are soft and the sauce is thick; add a splash of water if it gets dry.","Meanwhile cook the pasta in salted boiling water until al dente, keeping a mug of the cooking water.","Remove the thyme and bay leaf, season the ragù and toss with the pasta, loosening with cooking water; serve with basil."]'::jsonb, array['italian', 'vegan', 'vegetarian', 'comfort', 'freezer-friendly']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ef9af9e4-429a-41fc-a675-41c9b617379a'::uuid, 'Ribollita', 2, null::int, 95::int, 20::int, 75::int, '["Warm 2 tbsp oil in a large heavy pot over low heat and gently cook the onion, carrot, celery, garlic and thyme for 10 min, until soft but not coloured.","Add the potato, cavolo nero and cabbage, season and stir for 3–4 min until the greens collapse.","Add the tomatoes, tomato paste and stock, bring to a simmer and cook, partly covered, for 40 min.","Mash half the beans to a coarse purée with a fork or potato masher and a ladle of the soup.","Stir the bean purée and the whole beans into the pot and simmer for another 15 min.","Push the bread into the soup and cook for 10 min, stirring, until it breaks down and the soup is thick enough to hold a spoon; add a little water if needed.","Season and serve with a thread of raw olive oil, black pepper and parmesan. It is even better reheated the next day."]'::jsonb, array['italian', 'soup', 'comfort', 'vegetarian', 'make ahead', 'autumn', 'winter']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8ffa559e-9ee1-4db0-b46c-a4956b1290be'::uuid, 'Roasted pepper and mozzarella gnocchi', 2, null::int, 40::int, 10::int, 30::int, '["Heat the oven to 220°C.","Toss the peppers, onion, cherry tomatoes, garlic and thyme with 2 tbsp oil, salt and pepper in a large roasting dish.","Roast for 15 min, until the peppers are soft and blistered and the tomatoes have burst.","Squash the garlic and tomatoes with a fork to make a rough sauce and discard the thyme stalks.","Add the gnocchi straight from the pack with the remaining oil and a splash of water, toss well and roast for 10 min, until the gnocchi are tender.","Scatter over the mozzarella and parmesan and bake for 5 min more, until the cheese is melted and golden in places.","Serve topped with basil."]'::jsonb, array['italian', 'vegetarian', 'oven', 'comfort']::text[], 'italian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('44542c57-7489-4eeb-ba0c-2a8923c197a8'::uuid, 'Orzotto ai funghi', 2, null::int, 50::int, 10::int, 40::int, '["Bring the stock to a gentle simmer in a saucepan and keep it hot.","In a wide pan, fry the mushrooms in the oil with the garlic and rosemary over high heat for 6–8 min, until golden; season, then set a third aside for the top and discard the garlic and rosemary.","Add half the butter and the shallot to the pan and soften over medium heat for 3 min.","Add the barley and toast it for 2 min, stirring, then pour in the wine and let it evaporate.","Add the hot stock a ladle at a time, stirring often and waiting until each is mostly absorbed, for 30–35 min, until the barley is tender but still has a little bite.","Off the heat, stir in the rest of the butter and the parmesan and rest for 1 min; it should be creamy and loose.","Serve topped with the reserved mushrooms, parsley and black pepper."]'::jsonb, array['italian', 'vegetarian', 'risotto', 'comfort', 'autumn']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4ac67db3-15f0-4505-a682-a9989c256c89'::uuid, 'Prawn, courgette and lemon linguine', 2, null::int, 22::int, 10::int, 12::int, '["Cook the linguine in a large pot of salted boiling water until al dente, keeping a mug of the cooking water.","Meanwhile heat 2 tbsp oil in a large frying pan over high heat and fry the courgette for 4–5 min, until golden at the edges; season and set aside.","Add the remaining oil, the garlic and a pinch of chili flakes to the pan for 30 s, then add the prawns and cook for 2–3 min, turning once, until pink all over.","Return the courgette and add the lemon zest and half the juice.","Tip in the drained linguine with a splash of cooking water and toss over the heat for 1 min, until glossy.","Add the parsley, more lemon juice to taste, salt and pepper, and serve straight away."]'::jsonb, array['italian', 'quick', 'mediterranean', 'summer']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4172c8f0-f681-446f-be3b-0a1848a9606c'::uuid, 'Spinach and mushroom lasagne', 2, null::int, 85::int, 25::int, 50::int, '["Heat the oven to 200°C.","Make the béchamel: melt the butter in a saucepan, stir in the flour for 1 min, then whisk in the milk little by little and simmer for 5 min, stirring, until thick. Season with salt, pepper and nutmeg and stir in two thirds of the parmesan.","Fry the mushrooms in the oil with the garlic in a large frying pan over high heat for 8 min, until golden; add the wine and let it evaporate, then season.","Add the spinach to the pan and stir until just wilted; tip off any liquid.","Spread a thin layer of béchamel in a 20 × 20 cm dish, then layer lasagne sheets, a third of the mushrooms and spinach and a quarter of the béchamel; repeat twice more.","Finish with a last layer of sheets covered with the remaining béchamel and parmesan.","Bake for 30–35 min, until bubbling and golden and a knife slides easily through the pasta.","Rest for 10 min before cutting."]'::jsonb, array['italian', 'vegetarian', 'oven', 'comfort', 'make ahead']::text[], 'italian', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('a5aace29-d33e-4a90-9a9a-5ec39bbd6f9b'::uuid, 'Tomato and mozzarella flatbread pizzas', 2, null::int, 22::int, 10::int, 12::int, '["Heat the oven to 220°C and put a baking tray in to heat.","Pat the sliced tomatoes and the torn mozzarella dry with kitchen paper.","Mix the passata with the garlic, a pinch of oregano and salt, and spread it thinly over the flatbreads, leaving a narrow border.","Scatter over the grated mozzarella, then the tomato slices and torn mozzarella; season and drizzle with the oil.","Slide onto the hot tray and bake for 10–12 min, until the base is crisp and the cheese is bubbling and browned in spots.","Finish with fresh basil and a pinch of chili flakes, and cut into slices."]'::jsonb, array['italian', 'pizza', 'treat', 'quick', 'vegetarian']::text[], 'italian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('05fd4eac-be99-4274-a403-ad8b8821f794'::uuid, 'Pumpkin, sausage and sage risotto', 2, null::int, 55::int, 15::int, 40::int, '["Heat the oven to 200°C. Toss the pumpkin with the oil, half the sage, salt and pepper on a baking tray and roast for 25 min, until soft and caramelised at the edges.","Meanwhile bring the stock to a simmer in a saucepan and keep it hot.","In a wide pan, crumble the sausage and fry over medium heat for 5 min, until browned; lift it out, leaving the fat.","Add half the butter, the onion and the rest of the sage to the pan and soften for 5 min.","Add the rice and toast for 2 min, then pour in the wine and let it evaporate.","Add the hot stock a ladle at a time, stirring and letting each be absorbed, for 16–18 min, until the rice is creamy and al dente; stir in the sausage and half the pumpkin, crushed, halfway through.","Off the heat, stir in the remaining butter and the parmesan, cover and rest for 2 min.","Serve topped with the rest of the roasted pumpkin and the crisp sage leaves."]'::jsonb, array['italian', 'risotto', 'comfort']::text[], 'italian', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('4f5355b3-f2fd-4dbd-921a-d50d37544580'::uuid, 'Tuna, tomato and spinach pasta bake', 2, null::int, 40::int, 10::int, 30::int, '["Heat the oven to 180°C.","Cook the pasta in salted boiling water 2 min short of the packet time, then drain.","Meanwhile soften the onion and garlic in the oil in an ovenproof frying pan over medium heat for 4 min.","Add the tomatoes, oregano, salt, pepper and a splash of water and simmer for 5–8 min, until slightly thickened.","Stir the spinach into the sauce until wilted, then take the pan off the heat and stir in the pasta.","Fold in the tuna in large flakes and scatter the mozzarella on top.","Bake for 15–20 min, until the cheese is golden and the sauce is bubbling at the edges; rest for 3 min before serving."]'::jsonb, array['italian', 'oven', 'comfort', 'high protein', 'budget']::text[], 'italian', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('24abeaf1-16d2-4545-92bb-0c275f122522'::uuid, 'Spinach and ricotta stuffed pasta shells', 2, null::int, 55::int, 25::int, 30::int, '["Heat the oven to 200°C.","Wilt the spinach in a large pot with a splash of water for 2–3 min, drain, cool, squeeze dry and chop finely.","Mix the spinach with the ricotta, the egg, two thirds of the parmesan, a grating of nutmeg, salt and pepper.","Refill the pot with salted water and cook the shells for half the packet time (about 6 min); drain, rinse under cold water and toss with a little oil.","Mix the passata with the garlic, the rest of the oil, salt and the basil and spread it over the base of a baking dish.","Fill each shell with a heaped spoonful of the ricotta mixture and sit them side by side in the sauce.","Scatter over the remaining parmesan, bake for 20 min, until golden on top and the sauce is bubbling."]'::jsonb, array['italian', 'vegetarian', 'oven', 'comfort', 'make ahead']::text[], 'italian', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('55823f6d-25c8-4972-b71a-6303a4330168'::uuid, 'Sardine, lemon and breadcrumb spaghetti', 2, null::int, 22::int, 10::int, 12::int, '["Cook the spaghetti in a large pot of salted boiling water until al dente, keeping a mug of the cooking water.","Meanwhile toast the breadcrumbs in 1 tbsp oil in a large frying pan over medium heat for 3–4 min, stirring, until golden and crisp; mix in the lemon zest and a pinch of salt and tip into a bowl.","Wipe the pan, add the remaining oil, the garlic, capers and a pinch of chili flakes and cook gently for 1–2 min, without browning the garlic.","Add the sardines and break them into chunks with a spoon; warm through for 1 min.","Add the drained spaghetti with a splash of cooking water, the lemon juice and most of the parsley and toss until glossy.","Serve topped with the crisp breadcrumbs, the rest of the parsley and black pepper."]'::jsonb, array['italian', 'quick', 'budget', 'mediterranean', 'high protein']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d05206b1-877d-46fa-bc31-639b46637ae4'::uuid, 'Turkey bolognese tagliatelle', 2, null::int, 45::int, 15::int, 30::int, '["Soften the carrot, onion and celery in the oil in a heavy pan over medium heat for 8 min.","Add the turkey and garlic, turn up the heat and cook for 6–8 min, breaking it up, until it loses its pink colour and starts to brown.","Stir in the tomato paste for 1 min, then pour in the wine and let it bubble until almost gone.","Add the tomatoes, milk, bay leaf, a grating of nutmeg, salt and pepper, bring to a simmer and cook gently, partly covered, for 15 min, until thick; add a splash of water if it catches.","Meanwhile cook the tagliatelle in salted boiling water until al dente, keeping a little cooking water.","Remove the bay leaf, toss the pasta with the sauce and a splash of cooking water, and serve with parmesan."]'::jsonb, array['italian', 'comfort', 'high protein', 'freezer-friendly']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b52abd15-1267-4830-a431-c33e87f52e3d'::uuid, 'Lemon prawn and pea risotto', 2, null::int, 40::int, 10::int, 30::int, '["Bring the stock to a simmer in a saucepan and keep it hot.","In a wide pan, soften the shallot and garlic in the butter and 1 tbsp oil over medium heat for 4 min.","Add the rice and stir for 2 min, until the grains look translucent at the edges, then pour in the wine and let it evaporate.","Add the hot stock a ladle at a time, stirring and letting each be absorbed before the next, for about 12 min.","Stir in the peas and prawns and keep adding stock for 5–6 min more, until the prawns are pink and the rice is creamy and al dente.","Off the heat, stir in the lemon juice, the remaining oil, most of the parsley and a pinch of chili flakes; season, cover and rest for 1 min.","Serve topped with the lemon zest and the rest of the parsley."]'::jsonb, array['italian', 'risotto', 'high protein', 'spring']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4c97e702-12b8-4dc5-a739-715df1150d37'::uuid, 'Pea and asparagus lemon risotto', 2, null::int, 40::int, 10::int, 30::int, '["Cut the asparagus tips off and keep them; slice the stems into 2 cm pieces.","Bring the stock to a simmer in a saucepan and keep it hot.","In a wide pan, soften the shallot in half the butter and the oil over medium heat for 4 min.","Add the rice and toast for 2 min, then pour in the wine with half the lemon juice and let it evaporate.","Add the hot stock a ladle at a time, stirring and letting each be absorbed, for about 10 min; then add the asparagus stems.","After 4 min more, add the tips and the peas and keep adding stock for 4–5 min, until the rice is creamy and al dente and the asparagus is just tender.","Off the heat, stir in the remaining butter, the parmesan, the egg yolk, the lemon zest and the rest of the juice; season, cover and rest for 1 min.","Serve with the mint scattered over."]'::jsonb, array['italian', 'risotto', 'vegetarian']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4427b42a-5623-490b-af00-1004887dfb98'::uuid, 'Sea bass with fennel and orange salad', 2, null::int, 35::int, 15::int, 20::int, '["Boil the potatoes in salted water for 15–18 min, until tender; drain and toss with 1 tbsp oil, the parsley and salt.","Meanwhile cut the peel and pith off 1.5 oranges and slice them into rounds; squeeze the remaining half.","Toss the fennel, orange slices, red onion and olives with the orange juice, half the lemon juice, 2 tbsp oil, salt and pepper; leave for 10 min.","Pat the fish dry, score the skin a few times and season both sides.","Heat the remaining oil in a frying pan over medium-high heat and cook the fillets skin side down for 3–4 min, pressing them flat at first, until the skin is crisp.","Turn and cook for 1–2 min more, until the flesh is just opaque; finish with the rest of the lemon juice.","Serve the fish on the salad, scattered with fennel fronds, with the potatoes alongside."]'::jsonb, array['italian', 'light', 'mediterranean', 'fancy']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7f8f28eb-fb9c-48ec-9d27-6298066de40a'::uuid, 'Baked gnocchi with pumpkin and blue cheese', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C and bring a pot of salted water to the boil.","Cook the pumpkin with the oil and sage in a large ovenproof frying pan over medium heat for 12–15 min, covered for the first 5 min, until tender; season and crush about half of it with a fork.","Push the pumpkin to one side, melt the butter in the pan, stir in the flour for 1 min, then whisk in the milk and simmer for 3 min until lightly thickened.","Add the gorgonzola and stir over low heat until melted and mixed with the pumpkin; season with pepper and a little nutmeg.","Cook the gnocchi in the boiling water until they rise to the surface, 2–3 min, then drain and fold them into the pan.","Scatter with the parmesan and walnuts and bake for 10 min, until bubbling with a golden crust; rest for 3 min before serving."]'::jsonb, array['italian', 'vegetarian', 'oven', 'comfort', 'gratin']::text[], 'italian', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('2fd32898-57b1-45e1-83f9-89850157adf0'::uuid, 'Smoked salmon and pea spaghetti', 2, null::int, 22::int, 10::int, 12::int, '["Cook the spaghetti in a large pot of salted boiling water, adding the peas for the last 3 min.","Meanwhile whisk the yogurt, cream, egg yolk, parmesan, lemon zest, salt and plenty of pepper in a bowl.","Keep a mug of the cooking water, then drain the pasta and peas and return them to the pot off the heat with 3 tbsp of the water.","Pour in the sauce and toss over very low heat for 1–2 min, until creamy and coating the pasta; don''t let it boil or the egg will scramble.","Fold in the smoked salmon and most of the chives, add a squeeze of lemon and loosen with more cooking water if needed.","Serve straight away with the rest of the chives and black pepper."]'::jsonb, array['italian', 'quick', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6c246a38-571f-4eb9-b95c-baad65375613'::uuid, 'Chicken pesto and tomato traybake', 2, null::int, 40::int, 10::int, 30::int, '["Heat the oven to 220°C (200°C fan). Toss the quartered potatoes with the oil, salt and pepper on a large baking tray and roast for 12 min.","Meanwhile, coat the chicken thighs with 2 tbsp of the pesto and a little salt and pepper.","Push the potatoes aside, add the chicken and onion wedges to the tray and roast for 12 min.","Add the cherry tomatoes and roast 6-8 min more, until the tomatoes blister and the chicken is cooked through, with clear juices.","Loosen the remaining pesto with the lemon juice and spoon it over the chicken. Scatter with basil and serve from the tray."]'::jsonb, array['italian', 'oven', 'high protein', 'kid-friendly', 'mediterranean']::text[], 'italian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('67056eba-a09c-484e-98ec-cf1f2b086b9e'::uuid, 'Mushroom and mozzarella calzones', 2, null::int, 110::int, 25::int, 25::int, '["Mix the flour, yeast and salt, add 160 ml lukewarm water and 1 tbsp oil, and knead for 8-10 min until smooth and springy. Cover and leave to rise for about 1 hour, until doubled.","Fry the mushrooms in the remaining oil over high heat for 5-6 min until golden and dry; add the garlic and thyme for the last minute.","Add the spinach and stir for 1-2 min until wilted and the pan is dry. Season with salt and pepper and leave to cool.","Heat the oven to 230°C with a baking tray inside. Mix the ricotta with the parmesan and some pepper.","Divide the dough in two and stretch or roll each piece into a 25 cm round on a floured surface.","Spread the passata over one half of each round, leaving a 2 cm border, then add the ricotta, the mushroom mixture and the mozzarella.","Fold the dough over, press and crimp the edges tightly, cut a small steam hole and brush the top with a little oil.","Slide the calzones onto the hot tray and bake for 15-18 min, until puffed and deep golden. Rest 5 min before cutting."]'::jsonb, array['italian', 'treat', 'pizza', 'oven', 'vegetarian', 'comfort']::text[], 'italian', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('f8703f9d-af88-479d-bf23-0d5a062540bc'::uuid, 'Ricotta and lemon ravioli with peas', 2, null::int, 85::int, 45::int, 10::int, '["Mound the flour, break in the eggs and mix with a fork, then knead for 8-10 min until smooth and elastic. Wrap and rest for 30 min.","Mix the ricotta, parmesan, lemon zest, nutmeg, salt and plenty of pepper into a firm filling.","Roll the dough out very thin (about 1 mm, until you can almost see your hand through it) with a rolling pin or pasta machine, and cut it into two long sheets.","Put teaspoons of filling 4 cm apart on one sheet, brush around them with water, lay the second sheet on top and press out the air around each mound.","Cut out the ravioli, press the edges well to seal and lay them on a floured tray.","Cook the ravioli in a large pot of salted, gently boiling water for 3-4 min, adding the peas for the last 2 min.","Meanwhile, melt the butter in a large pan over low heat with a squeeze of lemon juice.","Lift the ravioli and peas into the pan with a slotted spoon, add a small ladle of cooking water and toss gently for 1 min until glossy. Serve with mint, pepper and extra parmesan."]'::jsonb, array['italian', 'vegetarian', 'fancy', 'spring']::text[], 'italian', 'hard', '{"pots":2,"oven":false,"special":["rolling pin"]}'::jsonb, 'Claude', null),
  ('3ee4b676-aad6-4e46-8795-8605729489d0'::uuid, 'Orecchiette with broccoli and sausage', 2, null::int, 35::int, 10::int, 25::int, '["Bring a large pot of salted water to the boil and cook the broccoli florets, covered, for 6-7 min until tender. Lift them out with a slotted spoon and keep the water.","Meanwhile, warm the oil in a large frying pan with the garlic, then add the crumbled sausage, rosemary, thyme and chilli and cook over medium-high heat for 6-7 min until browned.","Pour in the wine and let it bubble for 1 min until almost gone.","Add the broccoli and cook 3-4 min, crushing some of the florets with the spoon. Remove the garlic and season with pepper.","Bring the broccoli water back to the boil and cook the orecchiette until just al dente.","Transfer the pasta into the pan with a slotted spoon, add a ladle of cooking water and toss over the heat for 2 min until creamy. Serve with parmesan."]'::jsonb, array['italian', 'comfort', 'high protein']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('25acb8ff-311c-4665-944e-84f483b0e912'::uuid, 'Espinacas con garbanzos', 2, null::int, 35::int, 10::int, 25::int, '["Lower the eggs into boiling water and cook for 9 min, then cool them in cold water and peel.","Wilt the spinach in a large frying pan with a splash of water over medium heat for 2-3 min, then drain, squeeze and chop it finely.","Wipe the pan, heat the oil and fry the whole garlic cloves and the bread over medium heat for 2-3 min until golden. Lift them out, keeping the oil in the pan.","Pound the garlic and bread in a mortar with the cumin, paprika, chilli and a pinch of salt, then work in the vinegar, the passata and 3 tbsp water to make a smooth paste.","Reheat the oil, add the spinach and stir for 2 min, then stir in the paste and cook 2 min more.","Add the chickpeas and about 100 ml water and simmer for 5 min, stirring, until thick and saucy. Season to taste.","Serve in shallow bowls topped with the halved eggs and a little pepper, with the crusty bread for scooping."]'::jsonb, array['spanish', 'vegetarian', 'budget', 'healthy', 'mediterranean']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":["mortar and pestle"]}'::jsonb, 'Claude', null),
  ('6307f25f-d0c5-41b7-9da7-b1c9edcf87e7'::uuid, 'Tomato-poached cod with white beans', 2, null::int, 40::int, 10::int, 30::int, '["Soften the onion and pepper in the oil in a wide pan over medium heat for 8 min.","Add the garlic and paprika and stir for 30 s, then pour in the wine and let it bubble for 1 min.","Add the tomatoes and bay leaf, season and simmer for 10 min until the sauce thickens.","Stir in the beans and simmer 3 min.","Season the cod, nestle it into the sauce, cover and poach over low heat for 7-8 min until the fish is opaque and flakes easily.","Scatter with parsley and serve straight from the pan with crusty bread for the sauce."]'::jsonb, array['spanish', 'one-pot', 'stew', 'healthy', 'mediterranean']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('3c4bc8c3-19f4-40b7-b916-4f9a3660a44f'::uuid, 'Tortilla de patatas with tomato salad', 2, null::int, 45::int, 15::int, 30::int, '["Cut the potatoes into 2-3 mm slices. Cover the base of a 20 cm non-stick frying pan with 1 cm of olive oil and heat over medium heat.","Add the potatoes and onion with a pinch of salt and cook gently for 15-20 min, turning now and then, until soft but hardly coloured.","Drain the potatoes in a sieve over a bowl, keeping the oil for another use.","Beat the eggs with salt, fold in the warm potatoes and leave for 5 min.","Heat 1 tbsp of the oil in the pan over medium-high heat, pour in the mixture and cook for 3-4 min, shaking the pan, until the edges are set.","Cover the pan with a plate, turn the tortilla onto it and slide it back in. Cook 2-3 min more, leaving the centre slightly soft.","Slice the tomatoes onto a plate, add the red onion and dress with 1 tbsp oil, the vinegar, salt and oregano. Serve with the tortilla, warm or at room temperature, and bread."]'::jsonb, array['spanish', 'picnic', 'comfort', 'mediterranean']::text[], 'spanish', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c47e6281-33c2-439b-ae58-28c4ee81253b'::uuid, 'Paprika hake with peppers and potatoes', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C. Toss the potatoes, peppers and onion with 2 tbsp oil, salt and pepper in a roasting dish.","Roast for 20 min, stirring once, until the potatoes are tender and starting to colour.","Season the hake, lay it on the vegetables skin side down and roast for 8-10 min until the flesh is opaque and just flakes.","Meanwhile, fry the garlic in the remaining 2 tbsp oil in a small pan over medium-low heat for 2-3 min until pale golden.","Take the pan off the heat, stir in the paprika and then the vinegar.","Spoon the hot paprika oil over the fish, scatter with parsley and serve."]'::jsonb, array['spanish', 'oven', 'healthy', 'high protein', 'mediterranean']::text[], 'spanish', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('0dce17d0-cb2a-43f8-9113-4566cf6ea46b'::uuid, 'Gambas al ajillo with white beans', 2, null::int, 20::int, 10::int, 10::int, '["Toast the bread slices in a dry frying pan for 1-2 min per side, then set aside.","Pat the prawns dry and season with a pinch of salt.","Warm the oil, garlic and chilli in the pan over medium heat for 2-3 min, until the garlic is just turning golden.","Raise the heat, add the prawns and cook 1 min per side until pink.","Pour in the sherry, sprinkle over the paprika and let it bubble for 30 s.","Add the beans and toss for 2-3 min until hot and coated in the garlic oil. Finish with a squeeze of lemon and the parsley and serve with the toast for dipping."]'::jsonb, array['spanish', 'quick', 'high protein', 'mediterranean']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f42e4280-fed9-47cc-9ccd-5bb37ad400ea'::uuid, 'Gazpacho with eggs and jamón', 2, null::int, 155::int, 20::int, 15::int, '["Put the tomatoes, pepper, cucumber, garlic and bread in a blender with the vinegar, 100 ml cold water and 1 tsp salt and blend for 2 min until completely smooth.","With the blender running, pour in the oil until the soup turns creamy. Taste and adjust salt and vinegar.","Press through a sieve for a silky texture if you like, then chill for at least 2 hours.","Lower the eggs into boiling water, cook 10 min, cool in cold water, peel and chop.","Crisp the diced jamón in a dry frying pan over medium heat for 3-4 min, then toast the bread cubes in the same pan for 2-3 min.","Pour the cold gazpacho into bowls and top with the egg, jamón and croutons."]'::jsonb, array['spanish', 'soup', 'light', 'make ahead', 'summer']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('5ad1bda9-8aca-4746-92bc-c6ea865e640e'::uuid, 'Cod with crispy chickpeas and spinach', 2, null::int, 35::int, 10::int, 25::int, '["Heat the oven to 220°C. Toss the well-dried chickpeas with 2 tbsp oil, the paprika, cumin and salt on a lined baking tray.","Roast the chickpeas for 15 min, shaking the tray once, until they start to crisp.","Push them to one side, add the seasoned cod, drizzle with a little oil and roast 10-12 min until the fish flakes easily and the chickpeas are crunchy.","Meanwhile, fry the garlic in the remaining oil in a large frying pan over medium heat for 1 min, add the spinach and stir 2-3 min until wilted. Season and add a squeeze of lemon.","Serve the cod on the spinach, scatter over the crispy chickpeas and add lemon wedges and crusty bread."]'::jsonb, array['spanish', 'oven', 'healthy', 'high protein', 'mediterranean']::text[], 'spanish', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('4c174849-6e53-4371-be0e-fa0e67e4d60f'::uuid, 'Arroz con gambas', 2, null::int, 50::int, 15::int, 30::int, '["Heat the stock with the saffron in a small pan and keep it hot.","Heat the oil in a wide frying pan or paella pan over high heat, sear the prawns for 1 min and set them aside.","Lower the heat to medium and cook the onion, garlic, pepper and bay leaf together for 7 min until soft.","Add the grated tomato and cook 4 min over medium-high heat until it darkens and the pan is almost dry.","Stir in the paprika for a few seconds, then the rice for 1 min to coat it in the sofrito.","Pour in the hot stock, season with salt, spread the rice evenly and simmer over medium heat for 10 min without stirring.","Lower the heat and cook 7-8 min more; lay the prawns on top for the last 3 min, until the rice is tender and the stock absorbed.","Take off the heat, cover with a clean tea towel and rest 5 min. Serve with parsley and lemon."]'::jsonb, array['spanish', 'comfort', 'high protein', 'mediterranean']::text[], 'spanish', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a5894a47-22ee-42d7-9927-2b4caead1eef'::uuid, 'Arroz con pollo y chorizo', 2, null::int, 50::int, 15::int, 30::int, '["Season the chicken and brown it in the oil in a wide, deep pan over medium-high heat for 5 min. Set aside.","Add the chorizo, onion and pepper and cook over medium heat for 6 min, until the chorizo releases its red oil and the vegetables soften.","Stir in the garlic, paprika and grated tomato and cook 2 min.","Add the rice and stir for 1 min to coat it.","Pour in the stock, crumble in the saffron, add the bay leaf and the chicken, season and bring to the boil.","Cover and simmer on low heat for 16 min; scatter the peas over for the last 5 min, until the rice is tender and still a little moist.","Rest 5 min off the heat, then serve with parsley."]'::jsonb, array['spanish', 'one-pot', 'comfort', 'generous', 'high protein']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b44c86ec-e86c-4a74-94e1-d8ec335c05f4'::uuid, 'Pollo al ajillo', 2, null::int, 40::int, 10::int, 30::int, '["Heat the oven to 220°C. Toss the potato cubes with 1 tbsp oil and salt on a tray and roast for 25-30 min, turning once, until golden (instead of the traditional fried potatoes).","Fry the garlic cloves in the remaining oil in a large frying pan over medium heat for 3-4 min until the skins are toasted. Lift them out.","Season the chicken, dust it lightly with flour and brown it in the garlic oil over high heat for 8 min, turning, until golden all over.","Pour off excess oil, squeeze over the lemon and return the garlic. Add the sherry and bay leaf and let it bubble for 2 min.","Add the stock and simmer briskly for 10-12 min, turning the chicken, until it is cooked through and the sauce has reduced and coats it.","Scrape up the bottom of the pan, scatter with parsley and serve with the potatoes."]'::jsonb, array['spanish', 'comfort', 'high protein', 'mediterranean']::text[], 'spanish', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('a914da25-8a4d-40fd-b3ae-1857d48c52a8'::uuid, 'Lentejas con chorizo', 2, null::int, 75::int, 15::int, 60::int, '["Rinse the lentils.","Soften the onion, pepper and carrot in the oil in a large pot over medium heat for 8 min.","Add the garlic, paprika and grated tomato and cook 3 min.","Add the lentils, potato, bay leaf, 900 ml water and a little salt. Bring to the boil, then cover and simmer gently for 40 min, stirring now and then.","Add the chorizo and simmer uncovered 15 min more, until the lentils are tender and the broth is thick and red. Add a splash of water if it gets too dry.","Adjust the salt and rest 5 min before serving."]'::jsonb, array['spanish', 'stew', 'comfort', 'one-pot', 'freezer-friendly', 'winter']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6fa70574-b4d3-46d1-83db-4e22739a81cf'::uuid, 'Bacalhau à Brás', 2, null::int, 1500::int, 20::int, 30::int, '["Soak the salt cod in plenty of cold water in the fridge for 24-36 hours, changing the water every 6-8 hours.","Heat the oven to 220°C. Rinse and dry the potato matchsticks well, toss with 1.5 tbsp oil and a pinch of salt and spread on a lined tray.","Bake for 20-25 min, turning twice, until golden and crisp (instead of the traditional deep-fried straw potatoes).","Meanwhile, remove the skin and bones from the cod and shred it finely by hand.","While the potatoes bake, cook the onion and garlic in the remaining oil in a large frying pan over medium-low heat for 10 min until soft and golden.","Add the cod and cook 3-4 min, stirring, until it soaks up the oil. Stir in the potatoes.","Beat the eggs with pepper, pour them over on low heat and stir for 1-2 min; take off the heat while still creamy, before they set.","Serve at once topped with parsley and black olives."]'::jsonb, array['portuguese', 'comfort', 'high protein', 'make ahead']::text[], 'portuguese', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('a6c31957-1d9a-4114-b952-8037f62d3528'::uuid, 'Pisto manchego con huevo', 2, null::int, 80::int, 20::int, 60::int, '["Halve the tomatoes and grate them on a box grater, discarding the skins.","Cook the onion and garlic in 3 tbsp oil in a wide pan over low heat for 12 min until soft.","Add the peppers and cook 15 min more, stirring now and then, until very tender.","Add the zucchini and cook 8 min.","Stir in the grated tomato, sugar, salt and pepper and cook over medium-low heat for 20-25 min, uncovered, until thick, jammy and no longer watery.","Make 4 hollows in the pisto, crack an egg into each, cover and cook on low for 5-6 min until the whites are set and the yolks still runny.","Serve straight from the pan with plenty of bread."]'::jsonb, array['spanish', 'comfort', 'budget', 'mediterranean', 'summer']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('65b65923-4205-4160-98a0-f2a6c4e1c9d7'::uuid, 'Mejillones a la marinera', 2, null::int, 45::int, 20::int, 25::int, '["Scrub the mussels and pull off the beards; discard any that are broken or stay open when tapped.","Put them in a large pot with the bay leaves and 100 ml water, cover and cook over high heat for 3-4 min, shaking the pot, until they open. Discard any that stay closed.","Lift out the mussels, strain the cooking liquid through a fine sieve and keep 200 ml.","In the dried pot, cook the onion and garlic in the oil over medium heat for 8 min until golden.","Stir in the flour for 1 min, then take off the heat and stir in the paprika and chilli.","Pour in the wine and the reserved mussel liquid and simmer for 5 min, stirring, until lightly thickened.","Return the mussels, add most of the parsley and toss for 1-2 min until hot and coated. Serve with the rest of the parsley and bread for the sauce."]'::jsonb, array['spanish', 'fancy', 'high protein', 'mediterranean', 'autumn']::text[], 'spanish', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b3a53206-d2e6-46c6-8914-d174f6f6000d'::uuid, 'Baked falafel in pitta', 2, null::int, 830::int, 25::int, 25::int, '["Soak the dried chickpeas overnight in plenty of cold water (do not use canned chickpeas, the mixture would be too wet), then drain and dry them well.","Pulse the chickpeas in a food processor with the onion, 1 garlic clove, parsley, cumin, coriander, paprika, flour, 1 tbsp oil and 1 tsp salt until finely chopped and holding together when pressed.","Chill the mixture for at least 1 hour.","Heat the oven to 200°C and brush a baking tray with half the remaining oil.","Shape the mixture into walnut-sized patties, set them on the tray and brush the tops with the remaining oil.","Bake for 25 min, turning halfway, until golden and crisp outside.","Meanwhile, whisk the tahini with the lemon juice, the remaining garlic, grated, a pinch of salt and 3-4 tbsp cold water until smooth and pourable.","Warm the pittas, cut them in half, open the pockets and fill with lettuce, tomato, cucumber, the falafel and plenty of tahini sauce."]'::jsonb, array['middle eastern', 'vegetarian', 'oven', 'street food', 'sandwich', 'make ahead']::text[], 'middle eastern', 'medium', '{"pots":1,"oven":true,"special":["food processor"]}'::jsonb, 'Claude', null),
  ('e7f345b6-ff62-406f-9461-f8f36fd5b1b1'::uuid, 'Turkey kofta pitta platter', 2, null::int, 32::int, 20::int, 12::int, '["Mix the turkey, onion, parsley, most of the mint, paprika, cumin, cinnamon, allspice, breadcrumbs, 0.5 tsp salt and pepper with your hands until well combined.","Shape into 6 oval koftas around skewers if you have them and chill for 10 min while you prepare the rest.","Mix the yogurt with the lemon zest and juice, garlic, the remaining mint and a pinch of salt.","Toss the tomatoes, cucumber and red onion with a little salt.","Heat a griddle or frying pan over medium-high heat, brush the koftas with the oil and cook for 10-12 min, turning every few minutes, until browned and cooked through (74°C in the centre).","Warm the pittas in the pan for 30 s per side and cut into strips.","Arrange the koftas, pitta, salad and garlic yogurt on a platter and serve."]'::jsonb, array['turkish', 'high protein', 'grill', 'street food']::text[], 'turkish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b75b8190-ec3f-49c7-86f1-ccd3ae433c1e'::uuid, 'Pork souvlaki pitas', 2, null::int, 95::int, 20::int, 12::int, '["Mix the juice of half the lemon, the crushed garlic, vinegar, honey, 1 tsp oregano, paprika, cumin, 2 tbsp oil, salt and pepper. Toss the pork in it, cover and chill at least 1 h (up to overnight).","Grate half the cucumber, squeeze it dry and stir it into the yogurt with the extra garlic clove, the dill, a squeeze of lemon, salt and a drizzle of oil.","Dice the rest of the cucumber and toss with the tomato, red onion, the remaining oregano, a little oil and salt.","Thread the pork onto 4 skewers. Heat a griddle pan over high heat until smoking.","Grill the skewers 8-10 min, turning every 2 min, until charred outside and just cooked through, with no more than a blush of pink. Rest 3 min.","Warm the pitas 30 s per side in the hot pan.","Fill each pita with tzatziki, pork, tomato salad and a squeeze of lemon; fold and serve."]'::jsonb, array['greek', 'street food', 'wrap', 'grill', 'high protein', 'mediterranean', 'summer']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f8d5e8fc-4632-4270-9051-27105174a375'::uuid, 'Gemista with beef', 2, null::int, 125::int, 30::int, 85::int, '["Heat the oven to 180°C. Cut the tops off the peppers and tomatoes and keep them as lids. Seed the peppers; scoop the tomato flesh into a bowl and chop it finely, keeping the juice.","Sprinkle the insides of the shells with salt and a pinch of sugar and stand them in a baking dish.","Soften the onion in 2 tbsp oil over medium heat, 5 min. Add the beef and brown it 5 min, breaking it up, then stir in the garlic.","Add the rice and stir 1 min, then the tomato paste, half the chopped tomato flesh and 100 ml water. Simmer 5 min until the rice is half-cooked; off the heat stir in the parsley, mint, salt and pepper.","Fill the shells three-quarters full (the rice swells), spoon the rest of the tomato flesh over and put the lids on.","Tuck the potato wedges between the vegetables, season, drizzle everything with 2 tbsp oil and pour 200 ml water into the dish.","Cover with foil and bake 50 min, then uncover and bake 25-30 min more, basting once, until the rice is tender and the tops are blistered. Add a splash of water if the dish dries out.","Rest 10 min and serve warm with the feta."]'::jsonb, array['greek', 'oven', 'mediterranean', 'generous', 'summer']::text[], 'greek', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('b635672f-00b1-4632-b8a6-4c0172b0cc29'::uuid, 'Beef kofta with tomato bulgur', 2, null::int, 45::int, 20::int, 25::int, '["Squeeze the grated onion dry, then knead it with the beef, garlic, parsley, cumin, paprika, chili flakes, salt and pepper for 2 min until sticky.","Divide into 6 and press each around a skewer into a 12 cm sausage. Chill while you start the bulgur.","Soften the chopped onion in the butter and 1 tbsp oil over medium heat, 5 min. Stir in the tomato paste for 1 min, then the grated tomato for 2 min.","Add the bulgur, stock and a pinch of salt. Bring to the boil, cover and cook on the lowest heat 12 min, until the liquid is absorbed.","Take off the heat, lay a clean tea towel under the lid and leave 10 min to steam.","Meanwhile brush the koftas with oil and cook in a very hot griddle pan 8-10 min, turning every 2 min, until browned and cooked through.","Fluff the bulgur and serve with the koftas, the yogurt and lemon wedges."]'::jsonb, array['turkish', 'grill', 'high protein', 'mediterranean']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f3ca2b5c-b4ad-4f57-869b-798303f6f839'::uuid, 'Lentil and aubergine moussaka', 2, null::int, 110::int, 25::int, 75::int, '["Heat the oven to 200°C. Brush the aubergine and potato slices with 3 tbsp oil, season and roast on a lined tray 25 min, turning once, until soft and golden.","Meanwhile soften the onion in 1 tbsp oil in a saucepan, 6 min. Add the garlic, oregano and cinnamon for 1 min.","Add the rinsed lentils, passata, tomato paste and 300 ml water. Simmer, partly covered, 30 min, until the lentils are tender and the sauce is thick. Season and spoon into a small baking dish (about 20 x 15 cm), alternating with the vegetables: sauce, vegetables, sauce, vegetables.","Rinse the saucepan. Melt the butter, stir in the flour for 1 min, then whisk in the milk a little at a time and simmer 3-4 min, whisking, until thick. Season with salt, pepper and nutmeg.","Off the heat, whisk in the egg and half the parmesan.","Pour the béchamel over the vegetables, scatter the rest of the parmesan and bake at 180°C for 35 min, until golden and bubbling.","Rest 10 min before cutting, so the layers hold."]'::jsonb, array['greek', 'vegetarian', 'oven', 'comfort', 'make ahead', 'mediterranean']::text[], 'greek', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('a72b6524-b539-48e5-9e9c-77744a5cb4dc'::uuid, 'Gigantes plaki', 2, null::int, 50::int, 15::int, 30::int, '["In a wide, deep pan, gently cook the onion, carrot and celery in 4 tbsp oil with a pinch of salt for 8 min, until soft but not browned.","Add the garlic and chili flakes for 30 s, then the tomato paste for 1 min.","Add the canned tomatoes, stock, bay leaf, sugar and half the dill. Bring to a simmer, season, then fold in the beans.","Cover and simmer gently 20 min, stirring now and then, until the beans are very tender and the sauce is thick and jammy. Add a splash of water if it catches.","Remove the bay leaf, stir in the rest of the dill and leave 5 min off the heat (it is best warm rather than hot).","Serve with the feta crumbled over, a drizzle of oil, the parsley and the bread."]'::jsonb, array['greek', 'vegetarian', 'one-pot', 'comfort', 'budget', 'mediterranean']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d03d756a-f782-4067-8ef2-a6c2887809d7'::uuid, 'Arni me melitzanes (lamb and aubergine stew)', 2, null::int, 160::int, 25::int, 135::int, '["Heat the oven to 180°C. Season the lamb with salt and pepper.","In an ovenproof casserole, brown the aubergine slices in 2 tbsp oil over medium-high heat, 2-3 min per side, adding a little oil only if the pan is dry. Set aside.","Brown the lamb in 1 tbsp oil in the same casserole, 6-8 min, turning, until coloured all over. Pour in the wine and let it bubble 1 min.","Push the lamb aside and soften the onion and celery for 5 min, then add the garlic, oregano, paprika and cumin for 1 min.","Add the tomatoes, 100 ml water and the rosemary, season and bring to a simmer. Lay the aubergine over the top.","Cover and bake 1 h 45 min, until the lamb is very tender. Uncover, stir so some lamb sits on top and bake 15 min more to colour.","Meanwhile, about 20 min before the end, cook the rice: simmer it covered in 200 ml salted water 12 min, then rest 5 min.","Serve the stew over the rice with a spoonful of yogurt."]'::jsonb, array['greek', 'stew', 'oven', 'comfort', 'mediterranean']::text[], 'greek', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('d79d51a5-0384-4a66-b807-ef9f7af3a3ef'::uuid, 'Mercimek çorbası (Turkish lentil soup)', 2, null::int, 40::int, 10::int, 30::int, '["Soften the onion in 2 tbsp oil with a pinch of salt over medium-low heat, 6-8 min.","Add the garlic, cumin and tomato paste and fry 3 min, stirring, until the paste darkens.","Add the lentils, carrot, potato and stock. Bring to the boil, skim, then cover and simmer gently 18-20 min, until everything is very soft.","Blend until smooth with a stick blender; loosen with a little hot water if too thick, and season with salt and pepper.","In a small pan, melt the butter with 1 tbsp oil, add the Aleppo pepper and swirl 1 min over low heat until the fat turns red.","Ladle the soup into bowls, drizzle with the red butter, add parsley and serve with lemon to squeeze over and the bread."]'::jsonb, array['turkish', 'soup', 'vegetarian', 'budget', 'comfort']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('10663b06-3c7d-4f2f-a1f9-e2aded01352b'::uuid, 'Sabich', 2, null::int, 45::int, 20::int, 25::int, '["Heat the oven to 220°C. Brush the aubergine slices generously with oil on both sides, season and roast on a lined tray 25 min, turning once, until deep golden and creamy.","Meanwhile lower the eggs into simmering water and cook 9 min, then cool under cold water, peel and slice.","Whisk the tahini with 1 crushed garlic clove, the juice of half the lemon, a pinch of salt and 3-4 tbsp cold water until smooth and pourable.","Roughly crush the chickpeas with a fork, the other garlic clove, the cumin, 1 tbsp oil, a squeeze of lemon and salt.","Mix the tomato, cucumber, onion and half the parsley with a squeeze of lemon, a drizzle of oil and salt.","Warm the pitas in the oven for 2 min, then open them into pockets.","Spread the chickpeas inside, then layer aubergine, egg and salad, drizzling tahini between the layers. Finish with tahini, a drizzle of amba and parsley, and eat straight away."]'::jsonb, array['middle eastern', 'vegetarian', 'street food', 'sandwich']::text[], 'middle eastern', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('7ff53ecb-a890-45d5-b340-46719ce3ae64'::uuid, 'Cauliflower and chickpea shawarma platter', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C and line a large baking tray.","Whisk 3 tbsp oil with the juice of half the lemon, 2 garlic cloves, the cumin, ground coriander, paprika, turmeric, cinnamon, chili powder and 1 tsp salt.","Toss the cauliflower, chickpeas and onion in the spice oil and spread in a single layer on the tray.","Roast 30 min, shaking the tray halfway, until the cauliflower is tender and charred at the edges and the chickpeas are crisp. Warm the pitas on the oven rack for the last 2 min.","Meanwhile whisk the tahini, yogurt, honey, the remaining garlic, the zest and juice of the other lemon half, a pinch of salt and enough water to make it pourable.","Spread the vegetables on a platter, drizzle with the tahini sauce and scatter with parsley. Serve with the pitas, torn, and gherkins."]'::jsonb, array['middle eastern', 'vegetarian', 'oven', 'healthy']::text[], 'middle eastern', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('92e6216c-d5d6-4d6c-9483-31a0b88ceac4'::uuid, 'Halloumi and peach couscous salad', 2, null::int, 25::int, 15::int, 10::int, '["Put the couscous in a bowl with 1 tsp oil and a pinch of salt, pour over the boiling stock, cover and leave 5 min.","Whisk 2 tbsp oil, the juice of the lemon, the honey, mustard, chili flakes, salt and pepper.","Fluff the couscous with a fork and toss it with half the dressing and the red onion; leave to cool a little.","Heat a griddle or non-stick pan over medium-high heat. Brush the peach wedges with a little oil and cook 1-2 min per side until marked. Set aside.","Pat the halloumi dry and cook it in the same pan 2 min per side, until golden.","Toss the couscous with the arugula and mint, top with the peaches and hot halloumi, drizzle with the rest of the dressing and scatter the pistachios."]'::jsonb, array['mediterranean', 'salad', 'vegetarian', 'quick', 'light']::text[], 'mediterranean', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('69d6a6a6-0d99-43e5-b62f-57968b7e02c9'::uuid, 'Lamb burgers with feta and tomato salad', 2, null::int, 45::int, 20::int, 10::int, '["Squeeze the grated tomato in your hand to drain it, then mix it into the lamb with the garlic, half the oregano, the mint, parsley, salt and pepper. Shape 2 patties 2 cm thick and chill 15 min.","Mash the feta into the yogurt with a little pepper to make a thick sauce.","Toss the tomato wedges, cucumber, red onion and olives with the vinegar, 1 tbsp oil, the rest of the oregano and salt.","Heat a griddle pan over medium-high heat and cook the burgers 4-5 min per side, until well browned and cooked through. Rest 2 min.","Toast the cut sides of the buns in the pan, 1 min.","Spread the buns with feta sauce, add the burgers and serve the tomato salad on the side."]'::jsonb, array['greek', 'burger', 'grill', 'mediterranean', 'summer']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a8b8e77d-d4d8-4caa-9ef0-913a096603a2'::uuid, 'Lamb kleftiko', 2, null::int, 340::int, 20::int, 170::int, '["Mix the juice of the lemon, the wine, 3 tbsp oil, 1 chopped garlic clove, the oregano, 1 tsp salt and pepper. Rub it over the lamb, cover and chill 2 h (or overnight). Take it out 30 min before cooking.","Heat the oven to 160°C. Lay two long sheets of baking paper crosswise in a roasting dish.","Pile the potatoes, onion, pepper and tomatoes in the middle, season, then put the lamb on top with its marinade and the remaining garlic cloves, halved, and the rosemary.","Bring the paper up over everything and fold or tie it tightly into a sealed parcel; cover the dish with foil as well.","Bake 2 h 30 min, until the lamb pulls apart with a fork. If it resists, seal and bake 20 min more.","Lift the lamb onto a plate and cover. Raise the oven to 200°C, open the parcel, scatter the feta over the vegetables and roast 20 min, until the potatoes brown at the edges.","Serve the lamb with the potatoes and spoon the juices over."]'::jsonb, array['greek', 'oven', 'one-pot', 'comfort', 'fancy', 'mediterranean']::text[], 'greek', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('2f2c73a4-dbc5-4175-9822-235754fff440'::uuid, 'Beef stifado', 2, null::int, 175::int, 25::int, 150::int, '["Heat the oven to 170°C. Season the beef and brown it in batches in 2 tbsp oil in an ovenproof casserole over medium-high heat, 2-3 min per side. Set aside.","Lower the heat to medium and brown the pearl onions in the same pot, 5 min, shaking the pan, then add the garlic and tomato paste for 1 min.","Pour in the wine and vinegar and bubble 2 min, scraping up the browned bits.","Add the tomatoes, stock, cinnamon, cloves, allspice and bay leaf, return the beef and its juices and bring to a simmer.","Cover and bake 2 h, until the beef is fork-tender and the onions are soft but whole.","About 25 min before the end, boil the potatoes in salted water 20 min until tender, drain and crush roughly with 2 tbsp oil, salt and pepper.","If the sauce is thin, simmer the stew uncovered on the hob 10 min. Remove the cinnamon, cloves and bay, check the seasoning and serve over the potatoes with parsley."]'::jsonb, array['greek', 'stew', 'comfort', 'freezer-friendly', 'mediterranean', 'winter']::text[], 'greek', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('1f05ce54-f8c8-49bf-a3d4-5cba3cdbdbc8'::uuid, 'Youvetsi (beef and orzo bake)', 2, null::int, 160::int, 20::int, 130::int, '["Season the beef and brown it in 2 tbsp oil in an ovenproof casserole over medium-high heat, 2-3 min per side. Set aside.","Lower the heat and soften the onion and carrot 4 min, then add the garlic for 1 min and the tomato paste for 1 min.","Pour in the wine and let it bubble 1 min, then add the tomatoes, cinnamon, bay leaf, 350 ml of the stock and the beef with its juices.","Cover and simmer gently 1 h 30 min, stirring now and then, until the beef is very tender. Heat the oven to 180°C towards the end.","Bring the remaining 400 ml stock to the boil. Stir the orzo and hot stock into the casserole, season and bring back to a simmer.","Bake uncovered 25-30 min, stirring once halfway, until the orzo is tender and has drunk most of the sauce.","Rest 10 min (it thickens as it sits), remove the cinnamon and bay, and serve with the kefalotyri."]'::jsonb, array['greek', 'one-pot', 'oven', 'comfort', 'mediterranean']::text[], 'greek', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('91ce129b-6f6d-476b-8e00-f0497a49ac72'::uuid, 'Karnıyarık (stuffed aubergines)', 2, null::int, 50::int, 20::int, 30::int, '["Heat the oven to 220°C. Score the cut side of each aubergine half deeply in a criss-cross without piercing the skin, salt it and leave 10 min, then pat dry.","Brush the aubergines all over with 3 tbsp oil and roast cut side down in a baking dish 20 min, until soft and browned.","Meanwhile soften the onion and pepper in 1 tbsp oil over medium heat, 6 min. Add the beef and cook 5 min, breaking it up, until its liquid has evaporated.","Add the garlic, tomato paste and Aleppo pepper for 1 min, then half the diced tomato. Simmer 3 min, season and stir in most of the parsley.","Turn the aubergines cut side up and press the flesh open with a spoon to make a deep split. Fill with the meat, top with the remaining tomato, and pour 100 ml water into the dish.","Return the dish to the oven at 220°C, uncovered, for 10 min, until the filling is bubbling and the tops are browned.","Warm the bread on the oven rack for the last 3 min.","Serve the aubergines with their juices, the bread, yogurt and the remaining parsley."]'::jsonb, array['turkish', 'oven', 'comfort', 'mediterranean', 'summer']::text[], 'turkish', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('ba157b8e-c181-409e-b432-61f3f90fc64e'::uuid, 'Menemen', 2, null::int, 25::int, 10::int, 15::int, '["Heat the butter and 1 tbsp oil in a wide frying pan over medium heat. Add the pepper (and onion, if using) with a pinch of salt and cook 5 min until soft.","Add the tomatoes and Aleppo pepper, cover and cook 5-6 min, stirring once, until the tomatoes collapse into a thick sauce.","Beat the eggs lightly with salt and pepper.","Lower the heat, pour in the eggs and stir slowly with a spatula for 2-3 min, folding them into the sauce, until just set and still soft.","Scatter with feta and parsley and serve straight from the pan with the bread."]'::jsonb, array['turkish', 'quick', 'vegetarian', 'one-pot', 'budget']::text[], 'turkish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6b1436ee-7841-465f-b752-b7b18bd352ba'::uuid, 'Fattoush with grilled chicken', 2, null::int, 55::int, 20::int, 15::int, '["Rub the chicken with 1 tbsp oil, 2 garlic cloves, 1 tsp sumac, the paprika, the juice of half a lemon and salt. Leave 20 min.","Heat the oven to 200°C. Split the pitas, tear into bite-size pieces, toss with 1 tbsp oil and a pinch of salt and bake 8-10 min until crisp and golden.","Whisk 3 tbsp oil with the juice of 1 lemon, the vinegar, the remaining garlic and sumac, salt and pepper.","Heat a griddle pan over medium-high heat and cook the chicken 5-6 min per side, until charred and cooked through (no pink in the middle). Rest 5 min, then slice.","Toss the lettuce, tomato, cucumber, radish, spring onion, parsley and mint with the dressing.","Fold in the pita chips just before serving, top with the chicken and squeeze over the last lemon half."]'::jsonb, array['lebanese', 'salad', 'light', 'high protein', 'mediterranean', 'summer']::text[], 'lebanese', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('2a07c7e1-2a5b-461d-b203-27a73373f305'::uuid, 'Shish tawook with garlic sauce', 2, null::int, 155::int, 20::int, 12::int, '["Whisk the plain yogurt, juice of 1 lemon, 1 tbsp oil, tomato paste, mustard, 3 garlic cloves, paprika, sumac, cinnamon, 1 tsp salt and pepper. Coat the chicken, cover and chill at least 2 h (up to overnight).","For the garlic sauce, mash the last garlic clove with a pinch of salt to a paste, then whisk it into the Greek yogurt with 1 tbsp oil and a squeeze of lemon. Chill.","Thread the chicken onto skewers, alternating with the pepper and onion if using.","Heat a griddle pan over medium-high heat, brush it with oil and cook the skewers 10-12 min, turning every 3 min, until charred at the edges and cooked through.","Rest 5 min under foil while you warm the pitas in the pan.","Serve the skewers with the pitas, garlic sauce, tomato, gherkins and the rest of the lemon in wedges."]'::jsonb, array['lebanese', 'grill', 'high protein', 'street food', 'mediterranean']::text[], 'lebanese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0c76e1d2-3d8c-460e-b515-bb545d5fa83f'::uuid, 'Mujadara with halloumi', 2, null::int, 50::int, 10::int, 30::int, '["Cover the lentils with 500 ml water in a saucepan, bring to the boil and simmer 15 min, until just tender but holding their shape. Drain, keeping the liquid.","At the same time, cook the onions in 4 tbsp oil with a pinch of salt in a wide frying pan over medium heat, stirring often, 25-30 min, until deep golden brown; turn up the heat for the last 3 min so some crisp.","Return the lentils to the saucepan with the rice, cumin, allspice, 1 tsp salt, pepper and 280 ml of the lentil liquid (top up with water). Bring to the boil, cover and cook on the lowest heat 15 min.","Off the heat, fork two-thirds of the onions and their oil into the pot, cover and rest 10 min. Keep the rest of the onions on a plate.","Meanwhile wipe the frying pan and cook the halloumi over medium-high heat 2 min per side, until golden.","Top the mujadara with the crisp onions and the halloumi and serve with yogurt and a chopped tomato, cucumber and parsley salad."]'::jsonb, array['lebanese', 'vegetarian', 'comfort', 'budget', 'middle eastern']::text[], 'lebanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6ed4612b-73f6-4d13-bbe9-4b00aaa15141'::uuid, 'Chickpea and apricot tagine with couscous', 2, null::int, 45::int, 15::int, 30::int, '["Cook the onion in 2 tbsp oil with a pinch of salt in a wide pot over medium heat, covered, 8 min until soft and glossy.","Add the garlic, ginger and ras el hanout and stir 1 min until fragrant.","Add the carrot and sweet potato and stir to coat, then the chickpeas, tomatoes, stock and apricots. Bring to the boil, cover and simmer 20 min, until the vegetables are tender and the sauce has thickened.","Meanwhile put the couscous in a bowl with the grated zest of the lemon, 1 tsp oil and a pinch of salt, pour over 130 ml boiling water, cover and leave 5 min, then fluff with a fork.","Toast the almonds in a dry pan for 2 min until golden, watching closely.","Season the tagine with salt, pepper and a squeeze of lemon. Serve over the couscous, topped with almonds, a spoonful of yogurt and the coriander."]'::jsonb, array['moroccan', 'north african', 'vegetarian', 'stew', 'one-pot', 'budget']::text[], 'moroccan', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c24af535-ff47-498a-a075-d6f86716f8c9'::uuid, 'Lamb meatballs with tomato chickpeas', 2, null::int, 50::int, 20::int, 30::int, '["Mix the lamb with the grated onion, 1 garlic clove, most of the parsley, 1 tsp cumin, 1 tsp paprika, the cinnamon, salt and pepper. Shape into 14-16 walnut-size balls.","Brown the meatballs in 1 tbsp oil in a wide pan over medium-high heat, 6-8 min, turning, then lift them onto a plate.","Soften the chopped onion in the same pan over medium heat for 6 min, then add the remaining garlic, cumin and paprika and the harissa and stir 1 min.","Add the tomatoes, chickpeas and 100 ml water, season and bring to a simmer.","Return the meatballs, cover and simmer gently 15 min, until cooked through and the sauce has thickened.","Scatter with the rest of the parsley and serve with warm flatbread."]'::jsonb, array['north african', 'stew', 'comfort', 'high protein']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('3d018581-d136-4665-a2dc-1caf7eef3fbd'::uuid, 'Couscous royal', 2, null::int, 120::int, 30::int, 90::int, '["Brown the lamb in 1 tbsp oil in a large pot over medium-high heat, 5 min. Add the onion and cook 3 min.","Stir in the tomato paste, 1.5 tsp ras el hanout, the paprika, salt and pepper, pour in the stock and simmer gently, half-covered, 30 min.","Add the carrots and turnip and simmer 15 min.","Meanwhile brown the chicken thighs in a frying pan with a little oil, 4 min per side, then add them to the pot with the courgettes, chickpeas and saffron; simmer 25 min more, until the lamb is tender.","Fry the merguez in the frying pan over medium heat, 8-10 min, turning, until browned and cooked through.","Put the couscous in a bowl with the rest of the ras el hanout, a pinch of salt and a little oil; pour over 180 ml of the hot broth, cover and leave 5 min.","Fluff the couscous with a fork, working in the butter.","Serve the couscous topped with the meats and vegetables, with a bowl of broth on the side and a little harissa stirred into it for those who like heat."]'::jsonb, array['north african', 'stew', 'generous', 'comfort', 'high protein']::text[], 'north african', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('9a6ee5cf-200e-4579-9433-3f98f473c9de'::uuid, 'Tajine d''agneau aux pruneaux', 2, null::int, 125::int, 15::int, 110::int, '["Soften the onion in 1 tbsp oil in a heavy pot over medium heat, 3-4 min.","Add the lamb, cinnamon stick, turmeric, ginger, plenty of pepper and a little salt; turn to coat, then pour in 300 ml water.","Bring to the boil, cover and simmer very gently for 1 h 15, until the lamb is almost tender; add a splash of water if it gets dry.","Add the prunes and cook 20 min more, covered.","Stir the honey with the ground cinnamon into the sauce and simmer uncovered 15 min, until it turns thick and glossy.","Meanwhile toast the almonds in a dry frying pan over medium heat, 3-4 min, shaking, until golden.","Serve the tagine scattered with almonds and sesame seeds, with bread to mop up the sauce."]'::jsonb, array['north african', 'moroccan', 'stew', 'comfort', 'high protein']::text[], 'north african', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5f6175e0-2fa4-486d-a240-ed5a45569174'::uuid, 'Tajine de kefta aux œufs', 2, null::int, 50::int, 20::int, 30::int, '["Mix the beef with the grated onion, half the parsley, 1 tsp cumin, 1 tsp paprika, the cinnamon, salt and pepper. Roll into small balls about 3 cm across.","Soften the chopped onion and garlic in 1 tbsp oil in a wide lidded pan (or a tagine) over medium heat, 4 min.","Add the remaining cumin and paprika, the turmeric and chilli, then the tomatoes and 100 ml water; season and simmer 8 min, until slightly thickened.","Lay the meatballs in the sauce, cover and simmer gently 12 min, turning them once.","Make 3 hollows between the meatballs and crack an egg into each. Cover and cook 5-6 min, until the whites are set and the yolks still soft.","Scatter with the rest of the parsley and the coriander and serve straight from the pan with bread."]'::jsonb, array['north african', 'moroccan', 'one-pot', 'comfort', 'high protein']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8f203224-5bb8-48d2-8fcc-dfa1e8e3c43b'::uuid, 'Harira', 2, null::int, 85::int, 20::int, 65::int, '["Brown the lamb in 1 tbsp oil in a large pot over medium-high heat, 5 min.","Add the onion, celery and most of the parsley and cook 5 min, then stir in the ginger, turmeric, cinnamon, 0.5 tsp pepper and the tomato paste for 1 min.","Add the tomatoes, lentils and stock, bring to the boil, then cover and simmer gently 40 min, until the lamb and lentils are tender.","Add the chickpeas and vermicelli and simmer 8 min.","Whisk the flour with 100 ml cold water until smooth, pour it into the soup in a thin stream, stirring, and simmer 3-4 min until it thickens to a velvety texture.","Beat the egg, then drizzle it into the gently bubbling soup while stirring so it sets in fine strands; season with salt.","Serve with the rest of the parsley, the coriander and lemon wedges to squeeze over."]'::jsonb, array['north african', 'moroccan', 'soup', 'comfort', 'high protein', 'autumn', 'winter']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5d13af89-d872-4a64-91e2-ab41f15ff8a1'::uuid, 'Tajine de poisson with cod', 2, null::int, 55::int, 25::int, 30::int, '["Make the chermoula: mix the parsley, coriander, garlic, cumin, paprika, chilli, the lemon juice, 2 tbsp oil and a good pinch of salt.","Coat the cod with half the chermoula and leave it in the fridge while you prepare the vegetables.","Spread the onion over the base of a wide lidded pan (or a tagine) with the remaining 1 tbsp oil. Layer the carrot, then the potatoes, and season with the turmeric, ginger, salt and pepper.","Lay the tomato and pepper on top, spoon over the rest of the chermoula and add 120 ml water.","Cover and cook over medium heat 18-20 min, until the potatoes are almost tender when pierced with a knife.","Set the cod on top with the olives and the preserved lemon peel, cover and cook 8-10 min, until the fish flakes easily and the liquid has reduced to a sauce.","Serve straight from the pan."]'::jsonb, array['north african', 'moroccan', 'stew', 'one-pot', 'healthy']::text[], 'north african', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bbf7ab1c-0133-41c4-be33-4ff4253271c4'::uuid, 'Merguez and roast vegetable couscous', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C. Toss the aubergine, courgette, pepper and onion on a large tray with 3 tbsp oil, the ras el hanout, salt and pepper, and spread in one layer.","Roast 12 min, then stir and lay the merguez on top.","Roast 15 min more, turning the merguez once, until they are browned and the vegetables soft and caramelised at the edges.","Meanwhile bring the stock to the boil, pour it over the couscous in a bowl with 1 tsp oil, cover and leave 5 min.","Fluff the couscous with a fork and fold in the roast vegetables with the tray juices and the lemon juice.","Serve topped with the merguez, mint and a little harissa."]'::jsonb, array['north african', 'oven', 'generous', 'summer']::text[], 'north african', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('ea0abd75-bf32-4718-9c3a-4ccfd8fc9917'::uuid, 'Chermoula prawns with couscous', 2, null::int, 20::int, 12::int, 8::int, '["Mix the coriander, parsley, garlic, cumin, paprika, chilli, the zest and juice of half the lemon, 2 tbsp oil and a pinch of salt into a loose chermoula.","Toss the prawns with half the chermoula and leave 5 min.","Bring the stock to the boil, pour it over the couscous in a bowl with 1 tsp oil, cover and leave 5 min, then fluff with a fork and stir in the grated carrot.","Cook the prawns in a hot frying pan with the remaining oil over medium-high heat, 3-4 min, turning once, until pink and just cooked through.","Spoon the prawns over the couscous, drizzle with the rest of the chermoula and serve with the other lemon half in wedges."]'::jsonb, array['north african', 'quick', 'healthy', 'high protein']::text[], 'north african', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c4a8b76a-90e0-4bbd-9679-d04cd71870d9'::uuid, 'Red lentil coconut dal with rice', 2, null::int, 40::int, 10::int, 30::int, '["Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; leave to steam 5 min off the heat.","Meanwhile soften the onion in 1 tbsp oil in a saucepan over medium heat, 5 min.","Add the garlic, ginger and chilli and cook 1 min, then the cumin, ground coriander, turmeric and cinnamon for 30 s.","Add the lentils, tomato, coconut milk and 450 ml water. Bring to the boil, then simmer half-covered 20 min, stirring often, until the lentils collapse into a thick purée; add water if needed.","Season with salt and the lemon juice.","Heat 1 tbsp oil in a small pan, add the mustard seeds and let them pop for 30 s, then pour over the dal. Serve with the rice and coriander."]'::jsonb, array['indian', 'asian', 'curry', 'vegan', 'budget', 'comfort']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('da808dc3-7d41-43cd-9e70-cb82f2e4f7bd'::uuid, 'Kerala chicken curry', 2, null::int, 50::int, 20::int, 30::int, '["Toss the chicken with half the turmeric, half the garam masala, the pepper, a pinch of chilli powder and 0.5 tsp salt; leave while you prepare the rest.","Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Fry the onion in 2 tbsp oil in a heavy pan over medium heat, 8 min, until golden. Add the ginger and garlic and cook 1 min.","Add the tomato and cook 3 min until soft, then stir in the ground coriander, the rest of the chilli powder, turmeric and garam masala with 3 tbsp water and cook 1 min.","Add the chicken and stir over medium-high heat 3-4 min until it turns opaque. Pour in 100 ml water, cover and cook on low 12 min, until tender.","Stir in the coconut milk and simmer uncovered 4 min, until slightly thickened; check the salt.","In a small pan, fry the shallot in 1 tbsp oil until golden, add the curry leaves and chilli flakes and fry 30 s, until the leaves crisp, then pour over the curry. Serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'dairy-free', 'high protein']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f47d0b89-d4b8-425b-8d63-dc0b9302e262'::uuid, 'Aloo chana chaat', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C. Toss the potatoes and chickpeas on a large tray with 2 tbsp oil, 1 tsp cumin, the chilli powder and salt.","Roast 30 min, turning halfway, until the potatoes are golden and the chickpeas crisp.","Meanwhile finely chop the mint, most of the coriander and the chilli and stir them into 3 tbsp of the yogurt with half the lime juice and a pinch of salt to make a green chutney.","Stir the tamarind paste with the sugar, the remaining cumin and 3 tbsp hot water into a thin sweet-sour chutney. Whisk the rest of the yogurt with a pinch of salt.","Pile the hot potatoes and chickpeas on plates, spoon over the yogurt and both chutneys and sprinkle with the chaat masala.","Scatter with the onion, tomato, sev and the rest of the coriander, squeeze over the remaining lime and serve at once, before the sev softens."]'::jsonb, array['indian', 'asian', 'street food', 'vegetarian', 'oven']::text[], 'indian', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('5b716b9c-544f-4b6e-89b1-5787ec0d5d4d'::uuid, 'Cauliflower and pea biryani', 2, null::int, 55::int, 15::int, 30::int, '["Rinse the rice until the water runs clear and soak it in cold water 20 min, then drain.","Heat 2 tbsp oil in a heavy lidded pot over medium heat, add the bay leaf, cinnamon, star anise, cloves and cashews and fry 1 min, then add the onion and cook 8-10 min until golden.","Add the garlic and ginger for 1 min, then half the mint, the chilli and the tomato, and cook 3 min until soft.","Add the cauliflower, peas, cardamom, cumin, turmeric, chilli powder, garam masala, ground coriander and 1 tsp salt and stir 2 min to coat.","Stir in 50 g of the yogurt, then the drained rice and 300 ml boiling water. Bring to the boil, cover tightly and cook on the lowest heat 15 min.","Leave to rest, covered, 10 min off the heat, then fluff gently with a fork.","Mix the rest of the yogurt with the cucumber, the remaining mint and a pinch of salt for a raita and serve it with the biryani."]'::jsonb, array['indian', 'asian', 'vegetarian', 'one-pot', 'comfort']::text[], 'indian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6bc1c089-e3e1-4387-b021-e752bd4966a1'::uuid, 'Coconut chickpea and pumpkin curry', 2, null::int, 45::int, 15::int, 30::int, '["Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Heat 2 tbsp oil in a wide pan over medium heat, add the mustard seeds and cumin and let them sizzle and pop for 30 s.","Add the onion, garlic, ginger and curry leaves and cook 5 min until the onion is soft, then the tomato, ground coriander, turmeric, chilli powder and salt, and cook 3 min until the tomato breaks down.","Add the pumpkin, chickpeas and 250 ml water, cover and simmer 15 min, until the pumpkin is tender.","Stir in the coconut milk and garam masala and simmer uncovered 3 min, until the sauce thickens slightly.","Finish with the lime juice and coriander and serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'vegan', 'budget']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('fef780b4-874f-4404-af16-299d19f45262'::uuid, 'Goan coconut prawn curry with green beans', 2, null::int, 35::int, 15::int, 20::int, '["Toss the prawns with 0.25 tsp turmeric and a pinch of salt.","Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Heat 2 tbsp oil in a wide pan over medium heat and fry the curry leaves and chilli 30 s, until they sizzle. Add the onion and cook 6-7 min, until soft and lightly golden, then the garlic and ginger for 1 min.","Stir in the paprika, chilli powder, ground coriander, cumin and remaining turmeric with 3 tbsp water and fry 2 min, until the oil starts to separate.","Pour in the coconut milk and 150 ml water, add the green beans and simmer 6 min, until the beans are just tender.","Add the prawns and simmer 3-4 min, until pink and cooked through.","Stir in the tamarind paste, sugar and salt to taste; it should be tangy. Serve with the rice, coriander and lime wedges."]'::jsonb, array['indian', 'asian', 'curry', 'dairy-free', 'high protein']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a3ae4eef-b13b-417a-ab48-06aa0416f834'::uuid, 'Palak paneer with rice', 2, null::int, 50::int, 20::int, 30::int, '["Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Wilt the spinach with the chilli and cashews in 1 tbsp oil in a large pan over medium heat, 3 min, just until collapsed. Cool briefly, then blend with 4 tbsp water to a smooth purée.","Melt the butter in the same pan, add the cumin seeds for 30 s, then the onion and fry 8 min until golden.","Add the garlic and ginger for 1 min, then the tomatoes and a pinch of salt and cook 5 min until soft and jammy.","Stir in the garam masala and ground coriander for 1 min, add 150 ml water, cover and cook 5 min, then crush in the dried fenugreek leaves.","Lower the heat, stir in the spinach purée and bring just to a bubble, 2-3 min; do not boil it hard or it will turn dull.","Fold in the paneer and heat 2 min, then swirl in the cream. Serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'vegetarian', 'comfort']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('4c3bafea-b644-4721-b329-1da8f0824459'::uuid, 'Keema aloo', 2, null::int, 40::int, 10::int, 30::int, '["Heat 2 tbsp oil in a heavy lidded pan over medium heat, add the cumin seeds, bay leaf, cinnamon and cloves and fry 1 min, until fragrant.","Add the onion and cook 5 min until golden, then the garlic and ginger for 1 min.","Add the beef and cook over medium-high heat 5-6 min, breaking it up, until browned and its liquid has evaporated.","Stir in the ground coriander, ground cumin, turmeric, chilli powder and 1 tsp salt for 2 min, then add the tomatoes and potatoes.","Pour in 200 ml water, cover and simmer on low heat 15 min, stirring now and then, until the potatoes are tender and the oil rises to the top.","Add the peas and garam masala and cook 3 min more, uncovered, until the sauce clings to the meat.","Finish with the lemon juice, coriander and green chilli and serve with warm flatbread."]'::jsonb, array['indian', 'asian', 'curry', 'one-pot', 'comfort', 'budget']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8213da9d-3b1b-46a3-b4b2-70bfcbbfc392'::uuid, 'Saag gosht with basmati rice', 2, null::int, 105::int, 20::int, 85::int, '["Brown the lamb in 1 tbsp oil in a heavy lidded pot over medium-high heat, in two batches, 5 min, then set aside.","Add the butter, cumin seeds and bay leaf to the pot for 30 s, then the onion, and cook 8-10 min until golden.","Add the garlic and ginger for 1 min, then the tomatoes, turmeric, ground coriander, ground cumin and chilli powder, and cook 8 min until thick and the fat separates; add a splash of water if it catches.","Return the lamb with 300 ml water and 1 tsp salt, cover and simmer gently 50 min.","Whisk the yogurt and stir it in off the boil, then add the spinach a handful at a time and let it wilt. Cover and simmer 15 min more, until the lamb is tender and the sauce thick and green.","Meanwhile rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Stir the garam masala and the dried fenugreek leaves, crushed between your palms, into the curry, check the salt and serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'comfort', 'high protein']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('3ce76142-b963-43c3-be17-260ca39b916d'::uuid, 'Paneer tikka skewers with cucumber rice', 2, null::int, 70::int, 20::int, 20::int, '["Mix the yogurt with the garlic, ginger, garam masala, chilli powder, paprika, cumin, turmeric, the juice of half the lemon, 1 tbsp oil and 0.5 tsp salt. Fold in the paneer, pepper and onion and leave in the fridge 30 min.","Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat, then spread out to cool slightly.","Heat the oven grill to high (or 230°C). Thread the paneer, pepper and onion onto skewers and lay them on an oiled tray.","Grill 12-15 min, turning once, until the paneer is charred at the edges and the vegetables are tender.","Fold the cucumber, mint, a squeeze of lemon and a pinch of salt into the warm rice.","Serve the skewers on the cucumber rice with the remaining lemon in wedges."]'::jsonb, array['indian', 'asian', 'vegetarian', 'grill']::text[], 'indian', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('0f1721fb-aa3a-4130-b668-700a02491983'::uuid, 'Rajma chawal', 2, null::int, 40::int, 10::int, 30::int, '["Heat the butter with 1 tbsp oil in a saucepan over medium heat, add the cumin seeds and bay leaf for 30 s, then the onion and chilli, and cook 5-6 min until golden.","Add the garlic and ginger for 1 min, then the tomatoes, and cook 3-4 min until the raw smell has gone.","Stir in the chilli powder, ground coriander, ground cumin, turmeric, half the garam masala and 1 tsp salt and cook 3 min until the masala thickens and glistens with oil.","Add the beans and 300 ml hot water and simmer 15 min, mashing a few beans against the side of the pan to thicken the gravy.","Meanwhile rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Stir the rest of the garam masala, the crushed dried fenugreek leaves and the lemon juice into the rajma, scatter with coriander and serve over the rice with the yogurt on the side."]'::jsonb, array['indian', 'asian', 'curry', 'vegetarian', 'comfort', 'budget']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('db823cde-4d7a-4643-83ef-da6dc18ff628'::uuid, 'Chicken jalfrezi', 2, null::int, 25::int, 10::int, 15::int, '["Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest off the heat until needed.","Toss the chicken with the lemon juice, a pinch of chilli powder and salt.","Stir-fry the peppers, onion chunks and chilli in 1 tbsp oil in a large frying pan over high heat, 3 min, until charred at the edges but still crunchy; tip onto a plate.","Add 1 tbsp oil and the chopped onion to the pan and fry over medium-high heat 4 min, then add the garlic and ginger for 1 min.","Add the chicken and stir-fry 3 min until it turns pale, then the remaining chilli powder, garam masala, ground coriander, cumin and turmeric for 30 s.","Pour in the tomatoes with 3 tbsp water and cook 5-6 min, stirring, until the chicken is cooked through and the sauce is thick and clinging.","Return the peppers and onion with the dried fenugreek leaves, crushed, and toss 1 min to heat, check the salt and serve with the rice and coriander."]'::jsonb, array['indian', 'asian', 'curry', 'quick', 'spicy', 'high protein']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('442ff452-d938-4eab-96a9-6d100a2a00df'::uuid, 'Anda curry', 2, null::int, 45::int, 15::int, 30::int, '["Boil the eggs 9 min in simmering water, cool them in cold water and peel. Prick each egg 3-4 times with a fork.","Rinse the rice, add it to the same pot with 300 ml salted water, cover and cook 12 min on low heat; rest 5 min off the heat.","Meanwhile, fry the eggs in the butter with a pinch of turmeric in a wide pan, 2-3 min, rolling them until golden and blistered. Set aside.","Heat the oil in the same pan, add the bay leaf, cinnamon and cardamom for 30 s, then the onions; cook 8 min on medium heat until golden.","Add the garlic and ginger for 1 min, then the tomatoes; cook 5 min until thick and mushy.","Stir in the chili powder, ground coriander, garam masala, the rest of the turmeric and salt; cook 2 min until the oil separates.","Pour in 250 ml water, cover and simmer 6 min until the gravy thickens.","Add the eggs and simmer 3-4 min so they take on the sauce; crumble in the fenugreek leaves, stir in the cream, scatter with coriander and serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'vegetarian', 'comfort']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1ab9739c-acbe-4eba-9ade-d3384a505962'::uuid, 'Rogan josh', 2, null::int, 135::int, 15::int, 120::int, '["Fry the onion in 1 tbsp oil in a heavy pot over medium heat, 8-10 min, until deep golden. Lift out onto a plate.","Add the rest of the oil, then the bay leaf, cardamom, cloves and cinnamon; let them sizzle 30 s.","Add the lamb, sear 2 min on high heat, then cook 5 min on medium until lightly browned all over.","Whisk the yogurt with the Kashmiri chili powder, ground fennel, ginger and salt. Take the pot off the heat and stir the yogurt in a spoonful at a time so it doesn''t split.","Return to medium heat, cover and cook 4 min, then add 250 ml hot water. Cover and simmer on low heat 1 h 30-1 h 45, stirring every 15 min and adding a splash of hot water if it gets dry, until the lamb is very tender.","For the last 20 min, stir in the fried onion and the garam masala.","Meanwhile, rinse the rice and cook it covered in 300 ml salted water, 12 min on low heat; rest 5 min.","When the sauce is thick and red oil shows on the surface, adjust the salt and serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'stew', 'comfort', 'high protein']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('aff85e70-95e3-4537-a252-0b668f27c213'::uuid, 'Chicken biryani', 2, null::int, 105::int, 25::int, 60::int, '["Rinse the rice until the water runs clear, cover with water and soak 30 min; drain.","Meanwhile, fry the onions in the oil in a heavy pot over medium heat, 12-15 min, until deep golden. Lift out a third for the top.","Add the bay leaf, cinnamon, cardamom and cloves for 30 s, then the garlic and ginger for 1 min.","Add the chicken and cook 3 min until pale, then season with salt, garam masala, chili powder and turmeric and fry 3 min more.","Stir in the yogurt, cover and cook 15-20 min on medium-low heat until the chicken is tender and the sauce is thick, not watery.","Meanwhile, bring 2 l salted water to the boil with the caraway seeds, add the rice and boil 5-6 min until about 90% cooked, still firm in the centre; drain. Soak the saffron in the warm milk.","Scatter the mint and coriander over the chicken, spread the rice on top, then add the reserved onions, the saffron milk and the melted butter.","Seal the pot with foil and the lid and cook on the lowest heat 15 min. Rest 10 min off the heat before opening, then fold gently and serve."]'::jsonb, array['indian', 'asian', 'comfort', 'fancy', 'high protein']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8cf5200c-38b4-4aa5-aa57-44228ae164ec'::uuid, 'Matar paneer', 2, null::int, 25::int, 8::int, 17::int, '["Rinse the rice and cook it covered in 250 ml salted water, 12 min on low heat; rest 5 min.","Brown the paneer in half the butter in a frying pan, 1-2 min per side, until golden. Set aside.","Add the oil and the rest of the butter, the cumin seeds for 30 s, then the onion; cook 5 min until light golden.","Add the garlic and ginger for 1 min, then the turmeric, chili powder and ground coriander for 30 s.","Pour in the passata with a little salt and cook 4 min, stirring, until thick and the oil separates.","Add the peas and 150 ml water and simmer 5 min.","Crumble in the fenugreek leaves, add the paneer and garam masala and simmer 2 min. Stir in the cream, scatter with coriander and serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'vegetarian', 'quick']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('aba8ad6d-ca4c-4d94-a688-3adb95587555'::uuid, 'Prawn masala', 2, null::int, 40::int, 15::int, 25::int, '["Rinse the rice and cook it covered in 300 ml salted water, 12 min on low heat; rest 5 min.","Toss the prawns with a pinch each of turmeric, Kashmiri chili powder and salt and leave them while you start the sauce.","Heat the oil in a frying pan, add the cumin seeds and curry leaves for 30 s, then the onion; cook 6-7 min until golden.","Add the garlic and ginger for 1 min, then the tomatoes and a little salt; cook 6 min until broken down and thick.","Stir in the rest of the turmeric and Kashmiri chili powder, the ground coriander and garam masala; cook 1-2 min until the oil separates.","Add the coconut milk and 100 ml water and simmer 4-5 min to a thick but pourable gravy.","Lower the heat, add the prawns and cook 3-4 min, just until pink and curled into a C. Add a squeeze of lemon and the coriander and serve with the rice."]'::jsonb, array['indian', 'asian', 'curry', 'high protein']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('24505ac8-cfec-4400-bede-ce4bae130d8a'::uuid, 'Pork and cabbage stir-fry with rice', 2, null::int, 35::int, 15::int, 20::int, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Toss the pork with the Shaoxing wine, 1 tsp dark soy sauce, a little of the ginger and 1 tsp cornstarch; leave 10 min.","Mix the soy sauce with the rest of the dark soy sauce and the sugar. Stir the remaining cornstarch into 1 tbsp water.","Heat 1 tbsp oil in a wok over high heat, spread the pork in one layer, leave 1 min, then stir-fry 1 min more until just cooked. Set aside.","Add the rest of the oil, the garlic and ginger and stir 20 s until fragrant.","Add the cabbage and stir-fry 3-4 min until it just turns tender but keeps some crunch.","Pour in the sauce, return the pork, add the cornstarch mix and stir 1 min until glossy. Season with salt and chili flakes and serve over the rice."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8374c9b3-57b9-4cc7-be98-c4ae66518e2a'::uuid, 'Ginger beef lettuce cups with rice', 2, null::int, 35::int, 15::int, 20::int, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Heat the oil in a large frying pan over high heat and brown the beef, breaking it up, 5-6 min until well caramelised at the edges. Set aside.","In the same pan, cook the onion, pepper, carrot, garlic and ginger 3-4 min until softened.","Return the beef, add the oyster sauce, hoisin, soy sauce, stock and water chestnuts and stir-fry 3-4 min until the liquid has gone and the mince is dry and sticky.","Stir in the sesame oil and take off the heat.","Spoon the beef into the lettuce leaves, top with spring onion, peanuts and chili flakes and serve with the rice."]'::jsonb, array['chinese', 'asian', 'light', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('feea91a4-24a0-4ece-adb4-46b6944cafcc'::uuid, 'Chicken and vegetable fried rice', 2, null::int, 75::int, 15::int, 30::int, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat. Spread it on a tray and leave to cool completely, at least 30 min (or cook it the day before and chill).","Toss the chicken with 1 tsp soy sauce, the cornstarch and the sesame oil. Mix the rest of the soy sauce with the dark soy sauce, sugar, a pinch of salt, pepper and 1 tbsp hot water.","Heat 1 tbsp oil in a wok over medium-high heat, scramble the eggs until just set and lift them out.","Add 1 tbsp oil, sear the chicken in one layer over high heat and stir-fry 3-4 min until cooked through. Set aside.","Add the last of the oil, stir-fry the onion and carrot 3 min, then the peas 1 min.","Add the cold rice, breaking up the clumps, and stir-fry 4-5 min until hot and the grains are separate.","Pour over the sauce and toss until evenly coloured, then add the chicken, eggs, bean sprouts and spring onion and stir-fry 1 min.","Drizzle the Shaoxing wine around the hot edge of the wok, toss 20 s and serve."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'fakeaway', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('aa00c4b7-db7b-4b8a-8ea5-5637a1fb4bdf'::uuid, 'Pork meatballs in ginger broth with noodles', 2, null::int, 45::int, 20::int, 25::int, '["Bring the stock to the boil with the ginger matchsticks and smashed garlic, then simmer gently 10 min.","Meanwhile, mix the pork with the spring onion whites, grated ginger, grated garlic, 1 tbsp soy sauce, the Shaoxing wine, sesame oil, cornstarch, 2 tbsp water and pepper. Beat 1 min until sticky.","With wet hands, shape into about 14 walnut-size balls.","Lower the meatballs and carrot into the simmering broth and poach 8 min without boiling hard.","Meanwhile, cook the noodles in boiling water as the packet says, drain and divide between two bowls.","Add the bok choy to the broth and simmer 3-4 min until tender and the meatballs are cooked through, with no pink inside.","Season the broth with the rest of the soy sauce, the vinegar and sugar, ladle it over the noodles and top with the spring onion greens and chili flakes."]'::jsonb, array['chinese', 'asian', 'soup', 'comfort', 'light']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('03b4b489-6e9f-4433-8687-bbb43c7193ee'::uuid, 'Mushroom and cabbage potstickers', 2, null::int, 105::int, 75::int, 30::int, '["Mix the flour and salt with 120 ml warm water, knead 5 min until smooth, cover and rest 30 min.","Toss the cabbage with 0.5 tsp salt, leave 10 min, then squeeze out as much water as you can.","Fry the mushrooms and carrot in 1 tbsp oil 5-6 min until dry, add the garlic and ginger for 1 min and let cool.","Mix the tofu, cabbage, mushrooms, spring onion, 1 tbsp soy sauce, the sesame oil and cornstarch into a firm filling.","Cut the dough into 24 pieces, roll each into a thin 8 cm round and dust with cornstarch.","Put a heaped tablespoon of filling in the centre of each round, fold in half and pleat the edges to seal.","Cook in three batches: heat 1 tbsp oil in a lidded non-stick pan, fry the potstickers 3-4 min until the bases are golden, add 60 ml water, cover and steam 5-6 min until the water has gone, then uncover and crisp 1 min.","Mix the rest of the soy sauce with the black vinegar and chili flakes and serve as a dipping sauce."]'::jsonb, array['chinese', 'asian', 'vegetarian', 'freezer-friendly']::text[], 'chinese', 'hard', '{"pots":1,"oven":false,"special":["rolling pin"]}'::jsonb, 'Claude', null),
  ('97b513b6-d70b-4491-a7ad-f9277ee94a14'::uuid, 'Chicken and mushroom noodle soup', 2, null::int, 40::int, 10::int, 30::int, '["Fry the mushrooms in the vegetable oil in a large pot over high heat, 5-6 min until golden. Lift them out.","Pour the stock into the pot with the ginger, garlic, soy sauce and Shaoxing wine and bring to the boil.","Add the chicken, lower the heat and poach at a bare simmer 15-18 min until cooked through, with no pink in the thickest part.","Lift out the chicken, rest it 5 min and shred it with two forks.","Meanwhile, cook the noodles in the broth for the time on the packet, adding the bok choy for the last 3 min.","Divide the noodles, bok choy and broth between bowls, top with the chicken and mushrooms and finish with the sesame oil, spring onion and chili flakes."]'::jsonb, array['chinese', 'asian', 'soup', 'light', 'comfort', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d7790ac8-391f-4ae9-92b6-2274a94cb910'::uuid, 'Hoisin pork and broccoli noodles', 2, null::int, 30::int, 15::int, 15::int, '["Toss the pork with 1 tbsp soy sauce and the cornstarch; leave 10 min.","Mix the hoisin with the rest of the soy sauce, the honey, vinegar, sesame oil and chili flakes.","Cook the noodles in boiling water as the packet says, adding the broccoli for the last 2 min. Keep 60 ml of the water, then drain.","Heat 1 tbsp oil in a wok over high heat and sear the pork in one layer 2-3 min, turning once, until browned and just cooked. Set aside.","Add the rest of the oil, the garlic, ginger and carrot and stir-fry 1 min.","Add the noodles, broccoli, pork, sauce and a splash of the cooking water and toss 1-2 min until glossy and hot.","Serve topped with the peanuts and spring onion."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'fakeaway', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('261d4acf-50fc-4e1b-be3f-9558751ad743'::uuid, 'Ginger salmon with pak choi and noodles', 2, null::int, 60::int, 10::int, 20::int, '["Mix the soy sauce, ginger, garlic, honey, sesame oil and sriracha. Pour two-thirds over the salmon and leave in the fridge 30 min.","Heat the oven to 220°C (200°C fan).","Bake the salmon on a lined tray 12-14 min until it flakes easily.","Meanwhile, cook the noodles as the packet says, adding the pak choi for the last 2 min, and drain.","Heat the oil in the empty pot, add the spring onion, the rest of the marinade and the vinegar and bubble 1 min, then toss in the noodles and pak choi.","Serve the salmon on the noodles and scatter with sesame seeds."]'::jsonb, array['chinese', 'asian', 'oven', 'light', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('a0cb6512-daf4-4ea6-b97d-8730541d8c4f'::uuid, 'Crispy tofu with orange ginger sauce and rice', 2, null::int, 55::int, 15::int, 25::int, '["Wrap the tofu in a clean towel, put a heavy pan on top and press 20 min.","Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Cut the tofu into 2.5 cm cubes, toss with 1 tbsp soy sauce, then with 2 tbsp cornstarch until coated.","Pan-fry the tofu in the oil over medium-high heat 8-10 min, turning, until crisp and golden on all sides. Set aside on a rack.","Whisk the orange juice and zest, the rest of the soy sauce, the vinegar, sugar, chili flakes and 3 tsp cornstarch.","In the same pan, cook the ginger and garlic 30 s, pour in the sauce and simmer 2-3 min, stirring, until thick and glossy.","Off the heat, toss the tofu in the sauce and serve over the rice with spring onion and sesame seeds."]'::jsonb, array['chinese', 'asian', 'vegetarian', 'vegan', 'fakeaway']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('cf5613cb-4635-4714-bf7b-da5b7ac6a5d9'::uuid, 'Mapo tofu', 2, null::int, 40::int, 15::int, 25::int, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Toast the Sichuan pepper in a dry wok 2 min until fragrant, grind it finely and set aside.","Bring 600 ml salted water with the dark soy sauce to a simmer in the wok, slide in the tofu for 3 min, then lift it out gently and empty the wok.","Heat 1 tbsp oil over high heat and fry the beef 4-5 min until browned and a little crisp; add 1 tsp soy sauce and set aside.","Lower the heat, add the rest of the oil, the garlic and ginger for 90 s, then the black beans and doubanjiang for 2-3 min, stirring constantly, and the chili powder and paprika for 30 s until the oil turns red.","Pour in the stock and the rest of the soy sauce, bring to a bubble and slide in the tofu. Simmer 8-10 min, nudging the tofu with the back of a spatula rather than stirring.","Add the beef, sugar and half the Sichuan pepper. Pour the cornstarch mixed with 3 tbsp water over the top and stir gently until glossy and thickened.","Stir in the spring onion and sesame oil, sprinkle with the rest of the Sichuan pepper and serve over the rice."]'::jsonb, array['chinese', 'asian', 'spicy', 'comfort', 'high protein']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c27f8d79-6a7d-40f6-b374-34634d94bd69'::uuid, 'Hong shao rou', 2, null::int, 105::int, 15::int, 90::int, '["Boil the eggs 8 min, cool in cold water and peel.","Put the pork in a heavy pot, cover with cold water, bring to the boil and boil 2 min. Drain, rinse and wipe the pot dry.","Melt the sugar in the oil over low heat 3-4 min until it turns a light amber caramel.","Add the pork, raise the heat to medium and toss 3-4 min until coated and lightly browned.","Add the ginger, spring onion and star anise, pour in the Shaoxing wine and cook 1 min, then add both soy sauces and about 400 ml hot water, enough to almost cover.","Cover and simmer gently 60-75 min, stirring every 10-15 min and adding water if it gets dry; add the eggs after 30 min.","For the last 20 min, rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","When the pork is fork-tender, lay the bok choy on top, cover 4 min and lift it out. Uncover, turn up the heat and boil 5-8 min, stirring, until the sauce is a sticky glaze. Serve with the rice and greens."]'::jsonb, array['chinese', 'asian', 'stew', 'comfort', 'treat']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('2e88837a-8303-4192-b86e-937e56874383'::uuid, 'Tomato and egg stir-fry', 2, null::int, 25::int, 8::int, 17::int, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Beat the eggs with the Shaoxing wine, a pinch of salt and pepper.","Mix the tomato paste, cornstarch and sugar with 3 tbsp water.","Heat 2 tbsp oil in a wok over medium-high heat and scramble the eggs 1-2 min until just set but still glossy. Tip them into a bowl.","Add the rest of the oil, the tomatoes and spring onion whites with a pinch of salt and cook 3 min until soft and juicy but still holding their shape.","Stir in the tomato paste mixture until it thickens, return the eggs and fold for 30 s.","Turn off the heat, drizzle with sesame oil, scatter with the spring onion greens and serve over the rice."]'::jsonb, array['chinese', 'asian', 'quick', 'vegetarian', 'comfort']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b43b0cd3-cfe4-4513-9b78-fc0e2c6d9a22'::uuid, 'Char siu pork with greens', 2, null::int, 295::int, 15::int, 30::int, '["Mix the hoisin, 1 tbsp soy sauce, honey, sugar, 0.5 tbsp oyster sauce, Shaoxing wine, five-spice, sesame oil and garlic. Coat the pork, keep 2 tbsp of the marinade aside and refrigerate at least 4 h, or overnight.","Heat the oven to 220°C. Set the pork on a rack over a foil-lined tray.","Roast 20-25 min, turning and basting with the reserved marinade every 10 min, until it reaches 63°C in the centre.","Switch to the grill for the last 2 min to char the edges, then rest 10 min.","Meanwhile, rinse the rice and cook it covered in 300 ml water, 12 min on low heat; lay the bok choy on top for the last 4 min to steam, then rest 5 min.","Mix 1 tbsp oyster sauce with the rest of the soy sauce and 1 tbsp hot water and spoon it over the greens.","Slice the pork across the grain and serve with the rice and greens, scattered with sesame seeds and spring onion."]'::jsonb, array['chinese', 'asian', 'oven', 'make ahead', 'high protein']::text[], 'chinese', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('beeb1367-a9d8-4d08-aac1-88fd80b58e0a'::uuid, 'Cumin lamb stir-fry', 2, null::int, 25::int, 10::int, 15::int, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Toss the lamb with the soy sauce, Shaoxing wine, a pinch of salt, the baking soda and cornstarch; leave 10 min.","Mix the cumin, Sichuan pepper and sugar.","Heat 1.5 tbsp oil in a wok over high heat and cook the lamb in two batches: spread it out, leave 30 s, then toss 1 min until golden. Set aside.","Add the rest of the oil, the chillies, ginger and garlic for 10 s, then the onion; stir-fry 2 min until just softening.","Return the lamb, sprinkle over the spice mix and toss 1 min until coated.","Toss in the coriander and sesame seeds and serve straight away over the rice."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'quick', 'spicy', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1894de61-71cb-45f7-aba5-7cdf36e2e69e'::uuid, 'Nasu dengaku with tofu and soba', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C. Halve the aubergines lengthways, score the flesh deeply in a criss-cross without cutting the skin, and brush the cut sides with most of the oil.","Pat the tofu dry and brush it with the rest of the oil.","Roast the aubergines cut side up and the tofu on one lined tray 20-25 min, turning the tofu once, until the aubergine flesh is soft right through and golden.","Whisk the miso, mirin, sake and sugar to a smooth glaze.","Switch the oven to the grill on high, spread the glaze over the aubergines and tofu and grill 3-4 min until it bubbles and spots brown; watch closely as it burns quickly.","Meanwhile, cook the soba as the packet says, rinse under cold water and toss with the soy sauce, sesame oil and spring onion.","Serve the aubergines and tofu scattered with sesame seeds, with the soba alongside."]'::jsonb, array['japanese', 'asian', 'vegetarian']::text[], 'japanese', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('52915883-18c7-40b1-9500-09f4efc12426'::uuid, 'Teriyaki tofu with broccoli and rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Pat the tofu very dry with a clean cloth and toss the cubes in 1 tbsp cornstarch with a pinch of salt.","Whisk the soy sauce, honey, vinegar, garlic, ginger, 80 ml water and the 2 tsp cornstarch into a smooth teriyaki sauce.","Fry the tofu in 1.5 tbsp oil in a large non-stick pan over medium-high heat, turning, 10-12 min until golden on all sides. Lift it out.","Add the rest of the oil and the broccoli with 2 tbsp water and stir-fry 4-5 min until bright green and crisp-tender.","Lower the heat, pour in the sauce and stir about 30 s until it bubbles and thickens, then return the tofu and toss to glaze.","Serve over the rice, scattered with sesame seeds and spring onion."]'::jsonb, array['japanese', 'asian', 'bowl', 'stir-fry', 'vegetarian', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('62893e4f-bac6-47e6-9a16-28e32690738a'::uuid, 'Miso mushroom udon soup with tofu and egg', 2, null::int, 30::int, 10::int, 20::int, '["Lower the eggs into boiling water and cook 6.5 min for jammy yolks; cool them in cold water and peel. Empty the pot.","In the same pot, bring 800 ml water and the dashi to a simmer with the ginger and garlic.","Add the mushrooms and soy sauce and simmer 5 min until the mushrooms are tender.","Add the udon, tofu and bok choy and simmer 2-3 min, until the noodles loosen and the bok choy wilts.","Take the pot off the heat. Whisk the miso with a ladle of broth until smooth and stir it back in; do not let it boil again.","Ladle into bowls, top with the halved eggs and spring onion, and finish with sesame oil, sesame seeds and chilli."]'::jsonb, array['japanese', 'asian', 'soup', 'comfort', 'one-pot', 'vegetarian']::text[], 'japanese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('9b05494a-6b38-47d3-a478-7965c5cf3c64'::uuid, 'Seared tuna with sesame spinach and rice', 2, null::int, 35::int, 15::int, 20::int, '["Rinse the rice until the water runs clear, then simmer it covered in 180 ml water for 12 min and rest 10 min off the heat.","Warm the vinegar with 1 tsp sugar and 0.5 tsp salt until dissolved and fold it gently into the hot rice.","Toast 2 tbsp sesame seeds in a dry frying pan for 2 min until golden, then crush them roughly and mix with 1 tbsp soy sauce and the remaining 1 tsp sugar.","Wilt the spinach in the same pan with a splash of water, about 2 min; squeeze out the water, chop it and toss with the sesame dressing. Wipe the pan.","Pat the tuna dry, brush it with the sesame oil, salt it lightly and press the remaining sesame seeds onto both sides.","Heat the vegetable oil in the pan over high heat and sear the tuna 1 min per side for a rare centre (2 min for medium). Rest 2 min.","Slice the tuna against the grain and serve on the rice with the spinach, pickled ginger, spring onion and the rest of the soy sauce."]'::jsonb, array['japanese', 'asian', 'bowl', 'healthy', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ff1bfc7c-f6d4-4c1e-a75e-45eb3b87e0dc'::uuid, 'Baked chicken katsu with rice and cabbage', 2, null::int, 50::int, 20::int, 30::int, '["Heat the oven to 200°C. Toss the panko with 1.5 tbsp oil on the baking tray and toast it in the oven 4-5 min, stirring once, until golden; tip into a plate to cool.","Butterfly each breast and pound it to an even 1-1.5 cm thickness; season with salt and pepper.","Beat the egg with the remaining oil. Coat each cutlet in flour, then egg, then press firmly into the toasted panko.","Lay the cutlets on a rack over the same tray and bake 20-25 min, until the juices run clear (74°C inside).","Meanwhile rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Stir the ketchup, Worcestershire sauce, soy sauce and sugar into a quick tonkatsu sauce. Soak the cabbage in iced water 5 min and drain well.","Rest the katsu 2 min, slice it into strips and serve with the rice, cabbage, lemon and the sauce drizzled over."]'::jsonb, array['japanese', 'asian', 'oven', 'comfort', 'fakeaway', 'high protein']::text[], 'japanese', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('3d4d6f57-5e42-4208-af77-afff5162cee1'::uuid, 'Tofu and edamame sushi rice salad', 2, null::int, 55::int, 20::int, 20::int, '["Rinse the rice until the water runs clear, simmer it covered in 180 ml water for 12 min and rest 10 min off the heat.","Dissolve 2 tbsp vinegar, the sugar and 0.5 tsp salt, fold into the rice, spread it out on a plate and leave to cool 15 min.","Cook the edamame 3 min in a frying pan with a splash of water until hot, then drain and cool them.","Pat the tofu dry and fry it in the oil in the same pan over medium-high heat, 8 min, until golden; add 1 tbsp soy sauce and toss until it is absorbed.","Whisk the remaining soy sauce and vinegar with the sesame oil into a dressing.","Divide the rice between two bowls and top with the tofu, edamame, cucumber, carrot and avocado.","Drizzle with the dressing and finish with pickled ginger, sesame seeds and spring onion."]'::jsonb, array['japanese', 'asian', 'salad', 'bowl', 'vegetarian', 'make ahead', 'summer']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('85118fd3-d36c-4fb3-83b3-c39289e6bc96'::uuid, 'Tsukune donburi', 2, null::int, 35::int, 15::int, 20::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Knead the chicken, most of the spring onion, the ginger, the egg, the cornstarch and a pinch of salt by hand for 1-2 min until sticky.","With wet hands, shape 10-12 small flat patties.","Cook the broccoli in a frying pan with 3 tbsp water, covered, 3-4 min until just tender; set aside.","Heat the oil in the pan over medium heat and cook the tsukune 3-4 min per side until browned and cooked through.","Mix the soy sauce, mirin, sake and sugar, pour into the pan and let it bubble 1-2 min, turning the meatballs until glossy and glazed.","Serve the tsukune and broccoli over the rice with the pan glaze, a raw yolk on top if you like, sesame seeds, chilli and the rest of the spring onion."]'::jsonb, array['japanese', 'asian', 'bowl', 'comfort', 'high protein']::text[], 'japanese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f2f27077-f5bc-493c-9769-5f62aefa34eb'::uuid, 'Butaniku shōgayaki', 2, null::int, 25::int, 8::int, 17::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Mix the ginger, garlic, soy sauce, mirin, sake and sugar into the sauce. Season the pork lightly with salt and pepper.","Heat the oil in a large frying pan over medium-high heat and cook the onion 2 min.","Spread the pork slices in the pan and cook 1-2 min per side until browned.","Pour in the sauce and let it bubble 1-2 min, turning the pork, until the sauce reduces and coats the meat.","Serve the pork and its sauce with a mound of raw shredded cabbage and the rice, topped with spring onion."]'::jsonb, array['japanese', 'asian', 'quick', 'stir-fry', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a6face1b-b335-4aae-b9cd-603f4dd6b7c1'::uuid, 'Nikujaga', 2, null::int, 45::int, 15::int, 30::int, '["Peel the potatoes, cut them into large chunks, round off the sharp edges so they hold their shape, and soak 10 min in cold water.","Heat the oil in a pot over medium heat and cook the onion, carrot and drained potatoes 3 min until the potato edges turn translucent.","Add the beef and stir until it just loses its pink colour.","Pour in 300 ml water with the dashi, bring to the boil and skim off the foam. Add the sake, mirin and sugar first, cover with a piece of baking paper laid on the surface and simmer 12 min.","Meanwhile rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Add the soy sauce to the stew and simmer 10 min more, without stirring, spooning the broth over, until the potatoes are tender and the liquid has reduced by about half.","Add the green beans for the last 3 min. Serve in bowls with a little broth, with the rice alongside."]'::jsonb, array['japanese', 'asian', 'stew', 'comfort']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('96bd3c95-432e-4410-b43d-d745112aa97b'::uuid, 'Saba shioyaki', 2, null::int, 23::int, 5::int, 18::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Salt the mackerel generously on both sides and leave it 10 min while the rice cooks; then pat off the moisture that comes out.","Toss the cucumber with a pinch of salt, wait 5 min, squeeze it and dress with the vinegar and sugar.","Line a frying pan with foil, brush it with the oil and heat over medium heat.","Cook the mackerel skin side down 4-5 min until crisp and browned, then turn and cook 3-4 min more until opaque through.","Serve the fish with the rice, the cucumber salad sprinkled with sesame, lemon wedges and grated daikon with a drop of soy sauce."]'::jsonb, array['japanese', 'asian', 'quick', 'grill', 'healthy', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('179efe64-fe23-4da3-97b2-836e0e98e0cf'::uuid, 'Japanese chicken curry', 2, null::int, 45::int, 15::int, 30::int, '["Season the chicken with salt and pepper and brown it in the oil in a heavy pot over medium-high heat, about 5 min. Lift it out.","Lower the heat, add the onion, garlic and ginger and cook, stirring, 6-7 min until soft and golden.","Add the butter, then stir in the flour and curry powder and cook 2 min until the roux smells toasty.","Whisk in the stock little by little, then add the chicken, carrots, potato, apple, Worcestershire sauce, ketchup and bay leaf. Cover and simmer 15 min, stirring now and then, until the vegetables are tender and the sauce is thick.","Meanwhile rinse the rice and simmer it covered in 280 ml water for 12 min; rest 5 min off the heat.","Stir in the peas, simmer 2 min, then taste for salt. Serve beside the rice."]'::jsonb, array['japanese', 'asian', 'curry', 'comfort', 'kid-friendly']::text[], 'japanese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('090b603f-91ab-4c37-8c40-93b84e835d51'::uuid, 'Cold soba with tofu and edamame', 2, null::int, 30::int, 15::int, 15::int, '["Bring 240 ml water, the dashi, soy sauce, sake and sugar to the boil in a pot and boil 1 min. Pour into a bowl and chill it (a few ice cubes speed this up).","Pat the tofu dry and fry it in the oil in a frying pan over medium-high heat, 3 min per side, until golden. Cut into strips.","Bring a large pot of water to a rolling boil, add the edamame and soba, stir, and cook for the time on the soba packet (usually 4-5 min).","Drain and rinse under cold running water, rubbing the noodles to wash off the starch, then plunge briefly into iced water and drain well.","Pile the soba and edamame on plates with the tofu and cucumber.","Serve the cold dipping sauce in small bowls with spring onion and grated daikon to stir in, and sesame seeds to sprinkle."]'::jsonb, array['japanese', 'asian', 'light', 'vegetarian', 'high protein', 'summer']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('2f9185f2-8f3c-45a9-809f-8577f36a66dc'::uuid, 'Crispy tofu bánh mì', 2, null::int, 45::int, 25::int, 20::int, '["Toss the carrot and daikon with the vinegar, 1 tbsp sugar and 0.5 tsp salt; leave to pickle at least 20 min, stirring now and then.","Heat the oven to 200°C. Pat the tofu dry and dredge the slices in the cornstarch, shaking off the excess.","Fry the tofu in the vegetable oil in a non-stick pan over medium-high heat, 4-5 min per side, until crisp and golden. Lift it out.","Lower the heat, cook the garlic in the sesame oil 1 min, then add the soy sauce, the remaining sugar and 3 tbsp water. Return the tofu with the lime zest and toss 1-2 min until glazed.","Warm the baguette pieces directly on the oven rack for 5-6 min until crusty.","Mix the mayonnaise, sriracha and 1 tbsp lime juice.","Split the bread, spread with the sriracha mayo and fill with the tofu, drained pickles, cucumber, coriander and chilli."]'::jsonb, array['vietnamese', 'asian', 'sandwich', 'street food', 'vegetarian']::text[], 'vietnamese', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('bd6e4d1a-f6e3-4a40-b674-40721b9a6a01'::uuid, 'Pad Thai with prawns', 2, null::int, 25::int, 15::int, 10::int, '["Soak the noodles in warm water for 15-20 min until pliable but still firm; drain.","Warm the sugar with 2 tbsp water until it melts, then stir in the tamarind paste and fish sauce.","Stir-fry the tofu and prawns in 1 tbsp oil in a wok over high heat, 2-3 min until the prawns turn pink. Set aside.","Add the rest of the oil and fry the garlic and shallot 30 s until fragrant.","Add the noodles and sauce and toss over high heat 1-2 min until the noodles soften and soak up the sauce.","Push the noodles aside, crack in the eggs, let them set 30 s, then return the prawns and tofu and toss everything together.","Add the bean sprouts and spring onion, toss 30 s, and serve with the peanuts, the lime in wedges and chilli flakes."]'::jsonb, array['thai', 'asian', 'stir-fry', 'quick', 'fakeaway', 'high protein']::text[], 'thai', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bb6e3cf8-439f-4f5b-93df-b86fb163c981'::uuid, 'Aubergine and tofu green curry', 2, null::int, 35::int, 10::int, 25::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Pat the tofu dry and fry it in the oil in a wok or wide pan over medium-high heat, 6-8 min, until golden. Lift it out.","Fry the curry paste in the pan with 3 tbsp of the thickest coconut milk for 2 min, until fragrant and the oil separates.","Stir in the rest of the coconut milk and 100 ml water, add the aubergine and simmer 8-10 min until soft.","Add the green beans and tofu and simmer 4 min more, until the beans are just tender.","Season with the soy sauce, sugar and lime juice, taste, then stir in the Thai basil off the heat. Serve with the rice and chilli."]'::jsonb, array['thai', 'asian', 'curry', 'vegetarian', 'spicy']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b5647c45-2692-45ca-8ee6-c01a1edcf529'::uuid, 'Prawn and avocado rice paper rolls', 2, null::int, 30::int, 25::int, 5::int, '["Cook the vermicelli in boiling water for 3-4 min (or as the packet says), rinse under cold water and drain well.","Whisk the peanut butter, soy sauce, honey, juice of half the lime, chilli and 3-4 tbsp warm water into a smooth dipping sauce.","Squeeze the rest of the lime over the avocado so it does not brown.","Dip one rice paper sheet in warm water for 10-15 s until just soft and lay it on a damp tea towel.","Lay a row of prawn halves, cut side up, across the middle, then lettuce, noodles, carrot, avocado and herbs on top.","Fold the bottom over the filling, fold in the sides and roll up tightly. Repeat to make 8 rolls.","Serve straight away with the peanut sauce for dipping."]'::jsonb, array['vietnamese', 'asian', 'light', 'healthy', 'high protein', 'summer']::text[], 'vietnamese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('788cd98a-23e9-42b2-94d2-c323fbb2ec0b'::uuid, 'Massaman beef curry', 2, null::int, 155::int, 15::int, 140::int, '["Heat the oven to 160°C. Brown the beef in the oil in a flameproof casserole over high heat, 5 min.","Add the onion, garlic and curry paste and stir 2 min until fragrant.","Add the cinnamon, cardamom, stock and half the coconut milk, bring to a simmer, cover and braise in the oven for 1 h 15 min.","Stir in the potatoes, peanuts, the rest of the coconut milk, the fish sauce and sugar, and return to the oven uncovered for 50-60 min, until the beef is tender and the potatoes cooked.","About 20 min before the end, rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Season the curry with the juice of half the lime and more fish sauce or sugar to balance sweet, salty and sour.","Serve with the rice, coriander and the rest of the lime in wedges."]'::jsonb, array['thai', 'asian', 'curry', 'comfort', 'oven', 'batch cooking']::text[], 'thai', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('6ea6bed6-f994-4c4e-b9dc-7e3c29d833b6'::uuid, 'Thai red curry with butternut and chicken', 2, null::int, 35::int, 10::int, 25::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Fry the curry paste gently in the oil in a wok for 1-2 min until it sizzles and smells fragrant.","Stir in the coconut milk and 100 ml water, bring to a simmer, add the squash and simmer 10 min until nearly tender.","Add the chicken and simmer 6-8 min until cooked through.","Add the tomatoes and cook 2 min until they begin to split.","Season with the fish sauce a little at a time and the juice of half the lime, then scatter over the Thai basil. Serve with the rice and the rest of the lime."]'::jsonb, array['thai', 'asian', 'curry', 'comfort', 'high protein']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('3f39c7bd-f6c1-4ad1-86e9-0d865aaf83f2'::uuid, 'Gai yang with cucumber salad', 2, null::int, 215::int, 15::int, 20::int, '["Grate the lemongrass and garlic very finely (or blitz with a stick blender) and mix with the chopped coriander stems, 1.5 tbsp fish sauce, both soy sauces, 1.5 tbsp sugar, the oil and plenty of black pepper.","Coat the chicken in the marinade, cover and refrigerate at least 3 h (overnight is best).","Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Heat a griddle or non-stick pan (or barbecue) until hot, add the chicken and turn the heat to medium; cook 5-6 min per side until charred at the edges and cooked through. Rest 3 min.","Meanwhile toss the cucumber and shallot with the juice of the lime, the remaining fish sauce and sugar, and chilli to taste.","Slice the chicken and serve with the rice and the cucumber salad, scattered with peanuts and coriander leaves."]'::jsonb, array['thai', 'asian', 'grill', 'make ahead', 'high protein', 'summer']::text[], 'thai', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6b6848a2-12e1-4dde-a6cb-7291243dbc57'::uuid, 'Bún chả', 2, null::int, 75::int, 25::int, 20::int, '["Mix the shallot, 3 cloves garlic, lemongrass, oyster sauce, 1.5 tbsp fish sauce, 1 tbsp sugar and plenty of pepper. Mix half with the ground pork and half with the pork slices; marinate 30 min.","Toss the green papaya and carrot with a pinch of salt, 1 tsp sugar and the vinegar to pickle quickly.","Make the dipping broth: dissolve the remaining sugar in 200 ml hot water, then add the remaining fish sauce, the juice of 1 lime, the last garlic clove and chilli.","Heat the oven grill to high. With oiled hands, shape the ground pork into 10 small flat patties and lay them with the pork slices on an oiled rack over a tray.","Grill 10-12 min, turning once, until charred at the edges and cooked through.","Meanwhile cook the vermicelli in boiling water 3-4 min (or as the packet says), rinse under cold water and drain.","Put the grilled pork and pickled papaya and carrot in bowls of the warm broth and serve with the noodles, lettuce, herbs and the remaining lime half; dip everything into the broth as you eat."]'::jsonb, array['vietnamese', 'asian', 'grill', 'street food', 'high protein']::text[], 'vietnamese', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('b5fa3fe8-d226-4eda-88a3-7ea404bc6380'::uuid, 'Bò lúc lắc', 2, null::int, 25::int, 8::int, 17::int, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","While the rice cooks, toss the beef with the garlic, oyster sauce, both soy sauces, fish sauce, sugar, cornstarch and 0.5 tsp black pepper; leave 15 min.","Arrange the lettuce, tomatoes and sliced red onion on two plates. Mix the lime juice with a good pinch each of salt and pepper for the dip.","Heat the oil in a wok over high heat until smoking. Add the beef in one layer, leave 1 min to brown, then shake and toss 2-3 min until seared all over.","Add the butter, the onion squares and spring onion and toss 1-2 min more, until the onion just softens and the beef is still pink inside.","Spoon the beef over the salad and serve with the rice and the lime-pepper dip."]'::jsonb, array['vietnamese', 'asian', 'quick', 'stir-fry', 'high protein']::text[], 'vietnamese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('09155c6a-9a2d-49d0-beb9-32ed4b7d3e9e'::uuid, 'Gado-gado with egg and tofu', 2, null::int, 45::int, 20::int, 25::int, '["Put the potatoes and eggs in a pan of cold salted water, bring to the boil and cook 9 min. Lift out the eggs into cold water.","Add the green beans to the potatoes and cook 4 min more, until both are just tender. Lift them out with a slotted spoon.","Drop the cabbage and bean sprouts into the same water for 1 min, then drain and squeeze out the excess water.","Heat the oil in a frying pan and fry the tofu 2-3 min per side over medium-high heat until golden. Drain on paper towel.","Wipe the pan, then simmer the peanut butter, coconut milk, 80 ml water, garlic, curry paste, kecap manis and salt 4-5 min, stirring, until it coats a spoon. Add the juice of half the lime and the chili, and loosen with water if needed.","Peel and halve the eggs. Arrange the potatoes, beans, cabbage, sprouts, cucumber, tofu and eggs on two plates.","Spoon over the warm peanut sauce, scatter with peanuts and serve with the rest of the lime in wedges."]'::jsonb, array['indonesian', 'asian', 'salad', 'vegetarian']::text[], 'indonesian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('24a6e5dd-6a48-4027-bef7-93b4fbe4694a'::uuid, 'Singapore noodles', 2, null::int, 25::int, 15::int, 10::int, '["Soak the vermicelli in just-boiled water for 3-4 min (or as the packet says) until soft, drain and rinse under cold water.","Mix the soy sauce, Shaoxing wine, curry powder, sugar and a good pinch of pepper in a small bowl.","Heat 1 tsp oil in a wok over medium-high heat, pour in the eggs and swirl into a thin omelette. Once set, roll it up, slice into ribbons and set aside.","Add 1 tbsp oil and stir-fry the prawns 1-2 min until just pink. Set aside with the egg.","Add the remaining oil and stir-fry the onion, garlic and ginger 1-2 min, then the bell pepper 1 min.","Add the noodles and the sauce and toss with tongs for 1-2 min until evenly yellow.","Add the char siu with the prawns and egg with the bean sprouts and spring onion, toss 1 min until hot and serve straight away."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'quick', 'high protein']::text[], 'chinese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('903e26bc-8498-48e9-9a80-8ea3175bd84c'::uuid, 'Gochujang tofu with sesame rice and cucumber', 2, null::int, 35::int, 15::int, 20::int, '["Rinse the rice until the water runs clear, then simmer it covered with 200 ml water and a pinch of salt on low heat for 15 min; rest 10 min off the heat.","Halve the cucumber lengthways and slice thinly. Toss with 1 tbsp vinegar, the sugar and a pinch of salt and leave to pickle.","Whisk the gochujang, soy sauce, honey, the remaining 1 tbsp vinegar, 2 tsp sesame oil, garlic, ginger and 2 tbsp water.","Pat the tofu dry and toss it in the cornstarch. Fry it in the vegetable oil over medium-high heat for 8-10 min, turning, until crisp and golden on all sides.","Lower the heat, pour in the sauce and toss 1-2 min until it bubbles and coats the tofu in a sticky glaze.","Fork the remaining sesame oil and the sesame seeds through the rice.","Serve the rice topped with the tofu and the drained cucumber, scattered with spring onion."]'::jsonb, array['korean', 'asian', 'bowl', 'vegetarian', 'spicy']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('e4fbec5b-2877-472e-b90f-9cce17e906d4'::uuid, 'Kimchi fried rice with tuna, mushrooms and egg', 2, null::int, 35::int, 10::int, 25::int, '["Cook the rice in 200 ml water, covered, on low heat for 15 min. Spread it on a plate to cool and dry a little (day-old rice is even better).","Heat 1 tbsp oil in a large frying pan over medium-high heat and fry the onion and mushrooms 4-5 min until the mushrooms are browned.","Add the kimchi, gochugaru, gochujang and sugar and stir-fry 3 min until the kimchi softens and smells toasty.","Add the rice and kimchi juice and stir-fry 3-4 min, pressing the rice against the pan so it takes colour.","Fold in the tuna, half the spring onion and the sesame oil and heat through 1 min. Divide between two bowls.","Fry the eggs in the remaining oil 2-3 min until the whites are set but the yolks still runny.","Top each bowl with a fried egg, the rest of the spring onion and the sesame seeds."]'::jsonb, array['korean', 'asian', 'stir-fry', 'comfort', 'spicy']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('18d7da88-e0e2-45d7-9951-6b9728624038'::uuid, 'Japchae', 2, null::int, 40::int, 20::int, 20::int, '["Mix the soy sauce, sugar, sesame oil, garlic and plenty of pepper. Toss the beef with 1.5 tbsp of this sauce, then with the cornstarch, and leave while you prep.","Cook the noodles in boiling water for 6-7 min (or as the packet says) until soft and chewy. Drain, rinse in cold water and snip into shorter lengths with scissors.","Beat the eggs with a pinch of salt and cook into a thin omelette in a lightly oiled wok over medium heat, 1 min per side. Roll it up and slice into thin ribbons.","Heat 1 tsp oil in the wok over high heat and sear the beef in one layer, 1-2 min per side, until browned. Transfer to a large bowl.","Add 1 tbsp oil and fry the mushrooms 4 min until browned and dry; add them to the bowl.","Add the remaining oil and stir-fry the carrot, onion and spring onion with a pinch of salt for 3 min until just tender; add to the bowl.","Toss the spinach in the hot wok for 1 min until wilted, then add it to the bowl with the noodles.","Pour over the remaining sauce, add the egg ribbons and sesame seeds and toss with your hands or tongs until the noodles are glossy. Serve warm."]'::jsonb, array['korean', 'asian', 'stir-fry', 'high protein']::text[], 'korean', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a5433dcb-2462-4141-a7c2-64971329e1d1'::uuid, 'Kimchi jjigae', 2, null::int, 40::int, 10::int, 30::int, '["Cook the rice in 200 ml water, covered, on low heat for 15 min, then rest it off the heat.","Put the pork belly in a heavy pot over medium heat and fry 4-5 min, stirring, until some fat has rendered and the edges brown.","Add the onion, garlic, ginger and kimchi and stir-fry 4 min until the kimchi is soft and fragrant.","Stir in the gochugaru, gochujang, sugar, soy sauce, kimchi juice and 500 ml water. Bring to the boil, then simmer 15 min, partly covered.","Lay the tofu on top, spoon some broth over it and simmer 5 min more, until the pork is tender and the tofu hot through. Taste and adjust with salt or more gochugaru.","Scatter with the spring onion, drizzle with the sesame oil and serve bubbling from the pot with the rice."]'::jsonb, array['korean', 'asian', 'stew', 'spicy', 'comfort']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b5aa2a92-5715-4729-9059-11df4a1ed144'::uuid, 'Jeyuk bokkeum', 2, null::int, 65::int, 15::int, 20::int, '["Stir the gochujang, gochugaru, soy sauce, vinegar, sugar, honey, sesame oil, garlic and ginger together until the sugar dissolves.","Toss the pork, onion and spring onion in the marinade, rubbing it in well. Cover and chill 30 min (up to a few hours).","Meanwhile cook the rice in 200 ml water, covered, on low heat for 15 min, then rest it off the heat.","Heat the oil in a large frying pan or wok over high heat until shimmering.","Stir-fry the pork in two batches, 3-4 min each, until cooked through and caramelised at the edges; don''t crowd the pan or it will steam.","Scatter with sesame seeds and serve with the rice and lettuce leaves for wrapping."]'::jsonb, array['korean', 'asian', 'stir-fry', 'spicy', 'high protein']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bb35f3c2-7532-45fa-a110-e430a3f4f1c5'::uuid, 'Andong jjimdak', 2, null::int, 45::int, 15::int, 30::int, '["Soak the glass noodles in warm water for about 30 min, while you prep and cook, until pliable.","Mix the soy sauce, sugar, oyster sauce, sesame oil, garlic and ginger in a bowl.","Heat the oil in a wide pot over medium-high heat and brown the chicken 5 min, turning.","Pour in the sauce, 450 ml water and the chili, bring to the boil and cook 8 min at a lively simmer.","Add the potato, carrot and onion and simmer 12 min, stirring now and then, until the potato is tender and the sauce has reduced by about a third.","Drain the noodles and stir them in with the spring onion. Cook 4-5 min until the noodles are glossy and translucent and have soaked up some sauce.","Scatter with sesame seeds and serve straight away."]'::jsonb, array['korean', 'asian', 'stew', 'comfort', 'high protein']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6bc515fb-1db9-4a26-a278-d6dea10855c3'::uuid, 'Chicken and pepper fajitas', 2, null::int, 60::int, 15::int, 15::int, '["Mix 2 tsp oil with the garlic, lime zest, half the lime juice, cumin, oregano, chili powder, smoked paprika and 0.5 tsp salt. Coat the chicken and leave 30 min (or up to a day in the fridge).","Heat the remaining oil in a large heavy frying pan over medium-high heat. Add the peppers, onion, sugar and a pinch of salt and cook 6-8 min, stirring, until softened and charred in places.","Splash in 3 tbsp water to lift the browned bits, let it evaporate, then tip the vegetables onto a plate.","Cook the chicken in the same hot pan 3-4 min per side until well browned and cooked through. Rest 3 min, then slice into strips and squeeze over the rest of the lime.","Warm the tortillas in a dry pan for 20 seconds per side, or wrapped in foil in a low oven.","Return the peppers to the pan with the chicken to reheat for 1 min and serve with the tortillas, yogurt, avocado and coriander."]'::jsonb, array['mexican', 'wrap', 'high protein', 'kid-friendly']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('2484fa78-780d-4b2b-9a12-2d64bc9f6410'::uuid, 'Black bean and sweet potato chilli', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oil in a large pot over medium heat and soften the onion 6-7 min.","Add the sweet potato, garlic, chili powder, cumin, smoked paprika and oregano and stir 2 min until the spices smell toasted.","Add the black beans, tomatoes and stock and bring to the boil.","Cover, lower the heat and simmer 18-20 min, stirring now and then, until the sweet potato is tender. Uncover for the last 5 min if you want it thicker.","Season with salt and the juice of half the lime; lightly crush a few beans against the pot to thicken it.","Serve topped with the yogurt, avocado, coriander and the rest of the lime in wedges."]'::jsonb, array['mexican', 'stew', 'vegetarian', 'one-pot', 'batch cooking']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('dbb3e9ce-6c2a-4fd6-855e-868e35eb2ecb'::uuid, 'Black bean and pepper quesadillas', 2, null::int, 30::int, 10::int, 20::int, '["Heat the oil in a large frying pan over medium heat and cook the pepper and onion 5 min until soft.","Add the beans, corn, cumin and chili powder and cook 3 min, lightly crushing about a third of the beans, until any moisture has evaporated. Season and stir in the spring onion. Tip into a bowl and wipe the pan.","Mix the tomato with a squeeze of lime, a pinch of salt and the coriander for a quick salsa.","Scatter a quarter of the cheese over half of each tortilla, spoon the bean filling on top and finish with the rest of the cheese. Fold over and press gently.","Cook the quesadillas two at a time in the dry pan over medium-low heat, 2-3 min per side, until golden and the cheese has melted.","Cut into wedges and serve with the salsa, yogurt and lime wedges."]'::jsonb, array['mexican', 'vegetarian', 'kid-friendly', 'budget']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('e65fe071-853c-4a03-a5e5-5f8a90979328'::uuid, 'Smoky prawn tacos with cabbage and avocado', 2, null::int, 20::int, 15::int, 5::int, '["Toss the prawns with the smoked paprika, cumin, chili powder, oregano, garlic, half the oil and a pinch of salt.","Toss the cabbage with the juice of 1 lime and a pinch of salt just before assembling, so it stays crunchy.","Stir the yogurt with the hot sauce and a squeeze of lime.","Warm the tortillas in a dry frying pan, 20 seconds per side, and keep them wrapped in a tea towel.","Heat the remaining oil in the pan over high heat and cook the prawns 1-2 min per side until pink and lightly charred.","Fill the tortillas with cabbage, prawns and avocado, spoon over the smoky yogurt and finish with coriander and lime wedges."]'::jsonb, array['mexican', 'street food', 'quick', 'high protein']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d2793b68-f90b-4f5f-9649-da6b652d910a'::uuid, 'Sweet potato and black bean burgers', 2, null::int, 50::int, 20::int, 30::int, '["Heat the oven to 200°C. Prick the sweet potato all over and microwave it on high 7-8 min, turning once, until very soft (a leftover baked sweet potato works too).","Meanwhile, simmer the quinoa in 100 ml water, covered, for 15 min until the water is absorbed; leave to cool.","Scoop the sweet potato flesh into a bowl and mash. Add the beans and crush half of them with a fork.","Mix in the quinoa, egg, breadcrumbs, spring onion, cumin, smoked paprika, salt and pepper. It should hold its shape; add a few more breadcrumbs if too wet.","Shape 2 large or 4 small patties about 2 cm thick on an oiled, lined tray and brush the tops with oil.","Bake 20 min, carefully turning once after 12 min, until firm and browned. Rest 5 min so they firm up.","Stir the yogurt with a squeeze of lime and a pinch of salt.","Fill the toasted buns with lettuce, the patties, tomato, avocado and the lime yogurt."]'::jsonb, array['american', 'burger', 'vegetarian', 'oven']::text[], 'american', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('1ce30af4-0557-44c0-90a7-943b7db38432'::uuid, 'Chicken and roasted pepper enchiladas', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 200°C. Heat the oil in a large frying pan over medium-high heat and cook the onion 3 min until starting to soften.","Add the chicken with a pinch of salt and cook 5-6 min, stirring, until lightly browned and cooked through. Stir in the roasted peppers and tip everything into a bowl.","In the same pan, fry the garlic, cumin, chili powder and oregano 1 min. Add the tomatoes and stock and simmer 8 min until slightly thickened; season.","Mix 4 tbsp of the sauce into the chicken and peppers.","Spread a few spoonfuls of sauce in a baking dish. Fill each tortilla with the chicken mixture, roll up tightly and lay seam-side down in the dish.","Pour over the rest of the sauce and scatter with the cheddar.","Bake 12-15 min until the cheese has melted and the sauce bubbles at the edges. Serve with spring onion and yogurt or sour cream."]'::jsonb, array['mexican', 'oven', 'comfort', 'high protein']::text[], 'mexican', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('458a777c-279e-44f9-b835-9a4c4c9a99a5'::uuid, 'Roasted squash and black bean burritos', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 200°C. Toss the squash and red onion with 1 tbsp oil, half the cumin, the smoked paprika, chili powder and salt and roast on a tray for 20 min.","Meanwhile, simmer the rice in 160 ml salted water, covered, for 12 min; rest 5 min, then fluff with a squeeze of lime and the coriander.","Toss the beans with the garlic, the rest of the cumin and oil, add them to the tray and roast 8-10 min more, until the squash is tender and caramelised. Lightly crush the beans with a fork and squeeze over some lime.","Warm the tortillas wrapped in foil in the oven for the last 3 min.","Down the middle of each tortilla, layer rice, beans, squash, spinach, feta and a spoonful of yogurt.","Fold in the sides and roll up tightly. Halve and serve with the remaining yogurt."]'::jsonb, array['mexican', 'wrap', 'vegetarian', 'oven']::text[], 'mexican', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('8af92bc9-e7f4-4b51-b5c5-f3e158947f63'::uuid, 'Beef and black bean burrito bowls', 2, null::int, 35::int, 15::int, 20::int, '["Simmer the rice in 280 ml salted water, covered, for 12 min; rest 5 min, then fork through the juice of 1 lime and half the coriander.","Meanwhile, heat the oil in a frying pan over medium heat and soften the onion 4 min.","Turn the heat up, add the beef and brown it 5-6 min, breaking it up, until no pink remains.","Stir in the garlic, spices and tomato paste for 1 min, then add 60 ml water and simmer 2-3 min until saucy. Season.","Toss the beans, corn and tomato with the juice of half a lime and a pinch of salt.","Divide the rice between two bowls and top with the beef, bean salsa, lettuce and avocado.","Finish with cheddar, a spoonful of yogurt, the rest of the coriander and lime wedges."]'::jsonb, array['mexican', 'bowl', 'high protein', 'kid-friendly']::text[], 'mexican', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1c8911ac-cb21-4de7-afe8-c3501009222f'::uuid, 'Lomo saltado', 2, null::int, 30::int, 10::int, 20::int, '["Cook the fries in the air fryer at 200°C for 15-18 min, shaking halfway, until crisp.","Meanwhile, simmer the rice in 240 ml salted water, covered, for 12 min, then rest off the heat.","Toss the beef with the cumin, half the vinegar, half the soy sauce, pepper and a pinch of salt; leave 10 min.","Heat 1 tbsp oil in a wok over very high heat. Lift the beef out of its marinade and sear it in two batches, 2 min per batch, until browned outside but pink inside. Set aside.","Add the remaining oil and stir-fry the onion, garlic and ají amarillo paste 1 min, keeping the onion crunchy.","Add the tomatoes, the rest of the vinegar and soy sauce and the stock and toss 30 seconds, just until the tomatoes start to soften.","Return the beef with its juices, add the fries and toss 15 seconds. Scatter with parsley and serve at once with the rice."]'::jsonb, array['peruvian', 'stir-fry', 'high protein', 'comfort']::text[], 'peruvian', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('40812162-f84f-4848-8ce1-d2dcbc36e3ee'::uuid, 'Ropa vieja', 2, null::int, 160::int, 20::int, 140::int, '["Season the beef with salt and pepper.","Heat the oil in a heavy pot over medium heat and soften the onion and peppers 4 min. Set aside a third of the peppers for later.","Stir in the garlic, oregano, cumin, paprika and bay leaf for 1 min, then add the wine and let it bubble 1 min.","Add the passata and stock, nestle in the beef so it is covered, and bring to a simmer.","Cover with the lid slightly ajar and simmer very gently for 2 hours, adding a splash of water if needed, until the beef pulls apart easily.","Lift out the beef, discard the bay leaf and shred the meat into thin strands with two forks.","Return the beef to the pot with the reserved peppers, the olives and the vinegar and simmer uncovered 15 min until the sauce coats the meat. Adjust the seasoning.","About 20 min before the end, simmer the rice in 280 ml salted water, covered, for 12 min, rest 5 min and serve with the ropa vieja."]'::jsonb, array['cuban', 'stew', 'comfort', 'high protein', 'freezer-friendly']::text[], 'cuban', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0d15fc3d-576a-46cd-a6a3-ff2552e7beea'::uuid, 'Carnitas tacos', 2, null::int, 155::int, 15::int, 140::int, '["Heat the oven to 150°C. Trim any thick fat from the pork, leaving a thin layer.","Put the pork in a lidded ovenproof pot with the orange zest and juice, the juice of 1 lime, bay leaves, cumin, oregano, garlic, the onion chunks, 1 tsp salt, pepper and 400 ml water.","Bring to a simmer on the hob, cover and braise in the oven for 2 hours until the pork is very tender.","Lift the pork onto a lined tray. Boil the cooking liquid hard, uncovered, for 8-10 min until reduced to a few syrupy spoonfuls.","Pull the pork into large shreds, toss with the reduced liquid and spread out on the tray.","Switch the oven to its grill setting and grill the pork 10-15 cm from the element for 5-8 min, turning once, until crisp at the edges. Watch it closely.","Warm the tortillas in a dry pan and fill with the carnitas, diced onion, avocado and coriander. Serve with lime wedges and hot sauce."]'::jsonb, array['mexican', 'street food', 'comfort', 'high protein']::text[], 'mexican', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('96b56819-e22c-40cb-a356-bfd932ee56c1'::uuid, 'Sopa de tortilla with chicken', 2, null::int, 55::int, 15::int, 30::int, '["Toast the guajillos in a dry large pot over medium heat, 30-60 seconds per side, until fragrant but not burnt. Put them in a bowl, cover with 250 ml just-boiled water and soak 10 min until soft.","Meanwhile, heat the oven to 200°C. Toss the tortilla strips with a little oil and a pinch of salt and bake on a tray 8-10 min, shaking once, until golden and crisp; add the pasilla strips for the last 1-2 min.","Blend the guajillos with their soaking water, the tomatoes, onion, garlic and a pinch of salt until completely smooth.","Heat the oil in the pot over medium-high heat, pour in the purée (it will spit) and cook 8 min, stirring, until thick and darker in colour.","Add the stock and the parsley sprig, bring to a simmer, add the chicken and poach it gently 15 min until cooked through.","Lift out the chicken, shred it and return it to the soup. Remove the parsley and season with salt and a squeeze of lime.","Put the tortilla strips in bowls, ladle over the soup and top with avocado, queso fresco, crème fraîche, pasilla strips, coriander and lime wedges."]'::jsonb, array['mexican', 'soup', 'comfort', 'high protein']::text[], 'mexican', 'medium', '{"pots":2,"oven":true,"special":["blender"]}'::jsonb, 'Claude', null),
  ('117b8579-55c5-4e44-8073-d822afcd3fca'::uuid, 'Ceviche with sweet potato', 2, null::int, 50::int, 25::int, 15::int, '["Boil the sweet potato rounds in salted water for 12-15 min until just tender. Drain and chill them completely.","Soak the sliced onion in iced water for 10 min, then drain well.","Make the leche de tigre: grate the garlic and ginger, chop the celery and coriander stems finely, and stir into the lime juice with 1 tsp salt and 2 tbsp cold water. Leave 5 min, then strain.","Cut the fish into 2 cm cubes and put it in a chilled bowl. Season with a pinch of salt and stir in the ají amarillo paste.","Pour the leche de tigre over the fish and toss. Leave 3-5 min, just until the outside of the cubes turns opaque.","Fold in the onion and the coriander leaves. Taste and add salt or lime.","Serve straight away with its juices, the cold sweet potato and the corn on the side."]'::jsonb, array['peruvian', 'light', 'high protein', 'fancy', 'spring', 'summer']::text[], 'peruvian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('674abcb4-f1db-4f7d-b760-966a0e335502'::uuid, 'Steak with chimichurri and potatoes', 2, null::int, 60::int, 20::int, 25::int, '["Make the chimichurri: mix the hand-chopped parsley, garlic, oregano, chilli flakes, 1.5 tbsp vinegar and 3 tbsp oil with salt and pepper. Leave at least 20 min.","Take the steak out of the fridge 30 min before cooking, pat it dry and salt it well.","Boil the potatoes in salted water for 15 min until tender. Drain and leave to steam dry.","Crisp the potatoes in a frying pan with 1 tbsp oil over medium-high heat, 8 min, turning. Keep warm.","Wipe the pan and heat it until smoking. Sear the steak 3-4 min per side for medium-rare (52-55 °C inside). Rest 5-10 min.","Slice the tomatoes and onion and season them with salt, the rest of the vinegar and a little oil.","Slice the steak across the grain, spoon over the chimichurri and serve with the potatoes and tomato salad."]'::jsonb, array['argentinian', 'grill', 'high protein', 'generous', 'summer']::text[], 'argentinian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8660ca5e-d5ae-4f8c-8013-fc19defba212'::uuid, 'Picadillo with rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice, put it in a pan with 300 ml water and a pinch of salt, cover and simmer 12 min. Rest 5 min off the heat.","Meanwhile soften the onion and pepper in 1 tbsp oil over medium heat for 5 min. Add the garlic for 1 min.","Add the beef and break it up. Cook 5 min until it loses its pink colour.","Stir in the cumin, oregano and bay leaf, pour in the wine and let it bubble 1 min.","Add the passata and raisins and simmer uncovered for 10 min, stirring now and then, until thick.","Stir in the olives, capers and vinegar, and season with salt and pepper.","Serve the picadillo over the rice."]'::jsonb, array['cuban', 'comfort', 'high protein', 'budget']::text[], 'cuban', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a3d15426-1a21-4284-8cf5-5d39c27353d5'::uuid, 'Smoked haddock and sweetcorn chowder', 2, null::int, 40::int, 10::int, 30::int, '["Melt the butter in a saucepan and soften the onion, celery and potato over low heat for 10 min without colouring.","Pour in the stock and milk and bring to a gentle simmer. Cook 15 min until the potato is tender; don''t let it boil hard.","Crush a few potato pieces against the side of the pan to thicken the soup.","Add the sweetcorn, lay the haddock on top and poach very gently for 5 min until it just flakes.","Break the fish into large flakes and season with pepper. Taste before adding salt, as smoked fish is salty.","Serve in bowls scattered with parsley, with crusty bread on the side."]'::jsonb, array['british', 'soup', 'comfort', 'one-pot', 'high protein', 'winter']::text[], 'british', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f9ed364b-8350-45b8-ac5b-aca582be6f94'::uuid, 'Salmon fishcakes with peas and lemon yogurt', 2, null::int, 65::int, 25::int, 25::int, '["Boil the potatoes in salted water for 12-15 min until tender. Drain, leave to steam dry 2 min, then mash roughly.","Meanwhile poach the salmon in a frying pan of barely simmering water for 6-8 min until just cooked. Drain and flake.","Mix the mash, salmon, lemon zest, spring onions, half the dill, salt and pepper. Shape into 4 cakes about 3 cm thick and chill 15 min.","Dust the cakes with flour, dip them in the egg, then coat them in breadcrumbs.","Wipe the frying pan, heat the oil over medium heat and fry the fishcakes 4 min per side until golden and hot through.","Cook the peas in boiling water for 3 min, drain and season.","Mix the yogurt with 1 tbsp lemon juice, the rest of the dill and a pinch of salt.","Serve the fishcakes with the peas, the lemon yogurt and lemon wedges."]'::jsonb, array['british', 'comfort', 'kid-friendly', 'high protein']::text[], 'british', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b76ef299-3036-48ea-94ff-e8d5f575d475'::uuid, 'Sausage and root vegetable tray roast', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220 °C (200 °C fan) with a large baking tray inside.","Toss the parsnips, carrots, potatoes and onion with the oil, thyme, salt and pepper.","Spread them on the hot tray in one layer, tuck the sausages in among them and roast 15 min.","Turn everything and roast 10 min more.","Mix the honey and mustard, toss it over the sausages and parsnips and roast a final 5 min until sticky and the sausages are cooked through."]'::jsonb, array['british', 'oven', 'comfort', 'one-pot', 'autumn', 'winter']::text[], 'british', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('080fcab4-3b09-4071-8cc8-d2871c61b0c3'::uuid, 'Cod and potato fish pie', 2, null::int, 70::int, 20::int, 50::int, '["Heat the oven to 200 °C (180 °C fan). Boil the potatoes in salted water for 15 min until tender.","Meanwhile put the cod and haddock in a pan with 350 ml milk and the bay leaf. Bring just to a simmer and poach 4 min. Lift out the fish and pour the milk into a jug.","Melt 20 g butter in the same pan, stir in the flour for 1 min, then whisk in the poaching milk a little at a time. Simmer 3-4 min until thick; add the mustard, parsley and pepper.","Flake the fish into large chunks in a baking dish, scatter over the prawns and pour the sauce over.","Drain the potatoes and mash them with the remaining butter and milk. Season.","Spread the mash over the filling, rough it up with a fork and scatter over the cheddar.","Bake 25-30 min until golden and bubbling at the edges."]'::jsonb, array['british', 'oven', 'comfort', 'high protein']::text[], 'british', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('7e540a97-e2de-41ac-a97e-3781fce9f828'::uuid, 'Turkey and leek puff pastry pie', 2, null::int, 70::int, 20::int, 40::int, '["Brown the turkey in the oil in a wide pan over high heat for 4 min. Lift it out onto a plate.","Melt the butter in the same pan and cook the leeks over medium-low heat for 8 min until soft.","Stir in the flour for 1 min, then add the stock gradually and simmer 3 min until thick. Stir in the crème fraîche, mustard, thyme and turkey; season. Leave to cool 10 min.","Heat the oven to 200 °C (180 °C fan).","Spoon the filling into a small pie dish, cover with the pastry, press the edges to seal and cut a small steam hole. Brush with egg.","Bake 25 min until the pastry is puffed and deep golden. Rest 5 min before serving."]'::jsonb, array['british', 'tart', 'oven', 'comfort', 'high protein', 'autumn', 'winter']::text[], 'british', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('f2838b36-f8a4-4800-b348-062ecb0ab0b0'::uuid, 'Four-cheese baked macaroni with broccoli', 2, null::int, 35::int, 10::int, 25::int, '["Cook the macaroni in salted boiling water for 1 min less than the packet says, adding the broccoli for the last 3 min. Drain and heat the oven grill to high.","Melt the butter in the same pot, stir in the flour for 1 min, then whisk in the milk a little at a time. Simmer 5 min, stirring, until it coats a spoon.","Off the heat, stir in the cheddar, emmental, half the parmesan, the mustard and nutmeg. Season.","Return the pasta and broccoli to the pot, stir well, tip into a baking dish and dot with the mozzarella.","Mix the breadcrumbs with the rest of the parmesan, scatter over and grill 5-6 min until golden and bubbling."]'::jsonb, array['british', 'treat', 'comfort', 'gratin', 'oven', 'vegetarian']::text[], 'british', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('0932be9e-079a-4987-8170-c331087fb0a7'::uuid, 'Pan-fried hake with pea and mint mash', 2, null::int, 30::int, 10::int, 20::int, '["Boil the potatoes in salted water for 15 min until tender, adding the peas for the last 3 min.","Drain, then mash with the butter, warm milk, mint, salt and pepper, leaving some texture. Keep warm.","Pat the hake dry, score the skin lightly and season both sides.","Heat the oil in a frying pan over medium-high heat. Fry the hake skin side down for 4 min until crisp, then turn and cook 2-3 min until just opaque in the centre.","Serve the fish on the mash with a squeeze of lemon."]'::jsonb, array['british', 'light', 'high protein', 'spring']::text[], 'british', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('052505d0-dfea-4d39-abe9-1eb80426e276'::uuid, 'Tuna and sweetcorn jacket potatoes', 2, null::int, 25::int, 7::int, 18::int, '["Prick the potatoes all over, rub with a little oil and salt and microwave on high for 6 min. Turn and microwave 5-7 min more until soft to a knife.","Meanwhile heat the oven grill to high and mix the tuna, sweetcorn, yogurt, mayonnaise, spring onions, lemon juice and pepper.","Put the potatoes under the grill for 5 min to crisp the skins.","Split them, fluff the insides with a fork and pile in the tuna mix.","Top with cheddar and grill 2 min until melted. Serve with salad leaves."]'::jsonb, array['british', 'quick', 'comfort', 'budget', 'high protein']::text[], 'british', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('86ac5a18-9832-4b71-b7a5-72f531f53ddf'::uuid, 'Lamb chops with crushed peas and potatoes', 2, null::int, 50::int, 10::int, 25::int, '["Rub the chops with the garlic, rosemary, 1 tbsp oil and pepper. Leave 20 min at room temperature.","Boil the potatoes in salted water for 15 min until tender, adding the peas for the last 3 min.","Drain, then crush the potatoes and peas roughly with the butter, 1 tbsp oil, the mint, lemon zest and salt. Keep warm.","Season the chops with salt. Heat a frying pan over high heat and stand the chops on their fat edge for 2 min to render it.","Lay them flat and cook 3 min per side for pink. Rest 5 min.","Serve the chops on the crushed peas and potatoes with lemon wedges."]'::jsonb, array['british', 'high protein', 'fancy', 'spring']::text[], 'british', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5d85fa6b-aadc-4188-ac08-ae090e153778'::uuid, 'Mushroom and chestnut pot pie', 2, null::int, 70::int, 15::int, 45::int, '["Soak the porcini in 250 ml hot water for 15 min.","Meanwhile soften the onion in the oil in a wide pan over medium heat for 10 min.","Turn the heat up, add the fresh mushrooms and fry 4-5 min until browned.","Drain the porcini, keeping the liquid, and add them to the pan with the chestnuts and thyme. Season well.","Pour in the cider and 150 ml of the porcini liquid, bring to the boil and simmer gently for 15 min until reduced. Stir in the cream, take off the heat and leave to cool 15 min.","Heat the oven to 200 °C (180 °C fan). Spoon the filling into 2 small pie dishes, brush the rims with egg yolk, lay the pastry on top and press to seal. Glaze with yolk and chill 5 min.","Bake 15-20 min until the pastry is risen and browned."]'::jsonb, array['british', 'vegetarian', 'comfort', 'tart', 'oven', 'autumn', 'winter']::text[], 'british', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('c6232350-6113-4114-8a14-4cdec962f675'::uuid, 'Cauliflower cheese with crispy potato topping', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220 °C (200 °C fan). Boil the cauliflower and potato slices together in salted water for 5 min. Drain well, put the cauliflower in a baking dish and set the potatoes aside.","Melt the butter in the same pot, stir in the flour for 1 min, then whisk in the milk gradually. Simmer 4 min, stirring, until thick.","Off the heat, stir in three quarters of the cheddar, the mustard and nutmeg. Season.","Pour the sauce over the cauliflower.","Overlap the potato slices on top, brush them with the oil, season and scatter over the remaining cheddar and the parmesan.","Bake 20 min until the potatoes are crisp and golden at the edges. Rest 5 min before serving."]'::jsonb, array['british', 'vegetarian', 'comfort', 'gratin', 'oven', 'winter']::text[], 'british', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('f445cd76-b382-4065-8f94-eb2d927749e5'::uuid, 'Beef meatball subs with mozzarella', 2, null::int, 40::int, 15::int, 25::int, '["Mix the beef, breadcrumbs, egg, parmesan, 1 garlic clove, oregano, salt and pepper. Roll into 10 balls.","Brown the meatballs in the oil in a non-stick frying pan over medium-high heat for 5 min, turning.","Add the passata, the rest of the garlic and the sugar. Cover and simmer 12 min until the meatballs are cooked through.","Heat the oven grill to high. Split the rolls and toast them cut side up for 2 min.","Fill the rolls with the meatballs and some sauce and top with the mozzarella.","Grill 3-4 min until the cheese melts and browns. Scatter with basil and serve with the rest of the sauce."]'::jsonb, array['american', 'treat', 'sandwich', 'comfort', 'kid-friendly']::text[], 'american', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('579eee8b-5bb0-4a2d-a485-40c468fcf68e'::uuid, 'Lamb and lentil shepherd''s pie', 2, null::int, 85::int, 20::int, 65::int, '["Simmer the lentils in water for 15 min, until half cooked. Drain.","Brown the lamb in a dry pan over high heat for 6 min, then spoon off most of the fat. Add the onion and carrot and cook 6 min.","Stir in the garlic, flour and tomato paste for 1 min. Add the stock, worcestershire sauce, thyme, rosemary and lentils, cover and simmer 25 min until the lentils are tender and the sauce is thick. Season.","Meanwhile boil the potatoes in salted water for 15 min until tender. Drain and mash with the butter and warm milk; season.","Heat the oven to 200 °C (180 °C fan). Spoon the filling into a baking dish, cover with the mash and rough the top with a fork.","Bake 25 min until golden on top and bubbling at the edges."]'::jsonb, array['british', 'comfort', 'oven', 'freezer-friendly', 'high protein', 'autumn', 'winter']::text[], 'british', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('547accca-910e-44d6-8b35-b5f9621f0bd1'::uuid, 'Chicken Caesar-style wraps', 2, null::int, 22::int, 10::int, 12::int, '["Flatten the chicken to an even 1.5 cm and season with the oil, lemon zest, salt and pepper.","Cook it in a hot frying pan for 4-5 min per side until cooked through. Rest 3 min, then slice.","Whisk the yogurt, mayonnaise, garlic, anchovies, mustard, worcestershire sauce, lemon juice, half the parmesan and plenty of pepper to make the dressing.","Wipe the pan and warm the tortillas in it for 20 s per side.","Toss the lettuce with most of the dressing. Fill each tortilla with lettuce, chicken, the rest of the dressing and parmesan, roll up tightly and cut in half."]'::jsonb, array['british', 'wrap', 'quick', 'high protein']::text[], 'british', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('18c1a899-e68c-4b75-8eb3-38adbd2e2aae'::uuid, 'Smoked mackerel, beetroot and potato salad', 2, null::int, 30::int, 15::int, 15::int, '["Boil the potatoes in salted water for 15 min until tender, adding the eggs for the last 8 min. Cool the eggs in cold water, then peel and halve them.","Mix the crème fraîche, horseradish, mustard, lemon juice, half the dill, salt and pepper.","Toss the sliced onion with the vinegar and a pinch of salt and leave 10 min.","Toss the warm potatoes with the onion, its vinegar and half the dressing.","Arrange the potatoes, beetroot, mackerel and rocket on plates, top with the eggs and the rest of the dressing, and scatter with the remaining dill."]'::jsonb, array['danish', 'salad', 'light', 'high protein']::text[], 'danish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('159dedbb-14c3-4d5a-9b03-6d4f1f6f6f3f'::uuid, 'Chicken schnitzel with slaw and potato wedges', 2, null::int, 55::int, 25::int, 30::int, '["Heat the oven to 220 °C (200 °C fan). Cut the potatoes into slim wedges about 1.5 cm thick, toss with 1 tbsp olive oil, the paprika and salt on a tray and roast 30 min, turning once, until crisp.","Mix the cabbage and carrot with the yogurt, mayonnaise, mustard, vinegar and salt. Leave to soften.","Halve each chicken breast horizontally, then pound the pieces between cling film to 5 mm thick. Season.","Dip each piece in flour, then beaten egg, then breadcrumbs, coating it lightly without pressing.","Heat the vegetable oil in a large frying pan until a crumb sizzles at once (about 170 °C). Fry the schnitzels 2-3 min per side, gently swirling the pan so the crust puffs, until deep golden.","Drain on kitchen paper, salt lightly and serve with lemon wedges, the slaw and the wedges."]'::jsonb, array['german', 'comfort', 'kid-friendly', 'oven', 'high protein']::text[], 'german', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('0fed55e8-6259-459c-8b4c-b64a8add53da'::uuid, 'Sausages with braised cabbage and mash', 2, null::int, 45::int, 15::int, 30::int, '["Put the potatoes on to boil in salted water; they need 15-20 min until tender.","Meanwhile brown the sausages in the oil in a large casserole over medium heat for 8 min, turning. Lift them out.","Add the onion to the casserole and cook 4 min until soft, then add the cabbage, caraway and bay leaf and stir 3 min until the cabbage wilts.","Pour in the wine, stock and vinegar, season and put the sausages back on top. Cover and braise over medium-low heat for 12-15 min until the cabbage is tender and the sausages are cooked through.","Drain the potatoes and mash them with the butter, hot milk and nutmeg.","Serve the sausages and cabbage with the mash and mustard."]'::jsonb, array['german', 'comfort', 'stew', 'winter']::text[], 'german', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a789c5f2-85b3-4e2d-816d-a159b7989c55'::uuid, 'Sweet potato and peanut stew', 2, null::int, 40::int, 10::int, 30::int, '["Start the rice: simmer it covered in 1.5 times its volume of salted water for 12 min, then rest 5 min off the heat.","Meanwhile, soften the onion in the oil in a pot over medium-low heat for 6-8 min.","Add the garlic, ginger, cumin, ground coriander and cayenne and stir for 1 min until fragrant.","Add the tomatoes, stock, sweet potato and chickpeas with salt and pepper. Bring to the boil, then simmer uncovered for 12-15 min until the sweet potato is tender.","Whisk the peanut butter with a ladle of the hot liquid until smooth, then stir it into the pot and simmer 2-3 min until it thickens.","Stir in the spinach until it wilts, about 1 min, and adjust the salt.","Serve over the rice, topped with chopped peanuts and coriander."]'::jsonb, array['african', 'stew', 'vegetarian', 'vegan', 'comfort', 'budget']::text[], 'african', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8bb592e0-9ca3-454e-92f6-15e3a6d0d82d'::uuid, 'Beef stroganoff with tagliatelle', 2, null::int, 40::int, 15::int, 25::int, '["Put a pot of salted water on to boil for the tagliatelle.","Brown the mushrooms in half the oil in a large frying pan over high heat for 5-6 min, season, and tip into a bowl.","Add the rest of the oil and sear the beef strips in one layer for 1-2 min per side, just browned but still pink inside. Season and add to the mushrooms.","Lower the heat to medium, melt the butter and cook the onion with the tomato paste and paprika for 5-6 min until soft and lightly golden.","Stir in the flour for 30 s, then whisk in the stock and wine, scraping the pan. Simmer 2-3 min until it coats a spoon.","Meanwhile, cook the tagliatelle according to the packet, usually 8-10 min, and drain.","Take the pan off the heat, stir in the mustard and crème fraîche, then return the beef, mushrooms and their juices and warm through for 1 min without boiling.","Serve the stroganoff over the tagliatelle with parsley."]'::jsonb, array['russian', 'comfort', 'high protein', 'generous']::text[], 'russian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('54c25855-82be-4d48-9e67-689d4b21866c'::uuid, 'Baked trout with dill potatoes and pressgurka', 2, null::int, 40::int, 15::int, 25::int, '["Heat the oven to 200°C. Put the potatoes in a pot of cold salted water with the dill stalks, bring to the boil and simmer 15-20 min until tender.","For the pressgurka, stir the vinegar, sugar, 2 tbsp water and a pinch of salt until dissolved, add the cucumber and a little dill, and leave to steep while you cook.","Lay the trout skin side down in an oiled baking dish, season, dot with half the butter and add a few lemon slices.","Bake 10-12 min until the flesh is opaque and flakes easily.","Mix the crème fraîche with the mustard, a squeeze of lemon, half the remaining dill, salt and pepper.","Drain the potatoes and toss them with the rest of the butter and dill.","Serve the trout with the dill potatoes, the drained cucumber and the dill sauce."]'::jsonb, array['swedish', 'oven', 'light', 'healthy', 'summer']::text[], 'swedish', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('f494248a-e37a-4325-a232-ee05373d514e'::uuid, 'Gołąbki with mushrooms, spinach and rice', 2, null::int, 110::int, 40::int, 70::int, '["Soak the dried porcini in 200 ml hot water for 20 min, then lift them out, chop them and keep the soaking liquid.","Cut out the cabbage core and simmer the whole head in a large pot of salted water for 8-10 min, peeling off 8 leaves as they soften. Shave down the thick rib of each leaf.","Empty the pot and cook the rice in the strained porcini liquid topped up with water to 300 ml for 8-10 min until half-cooked and the liquid is absorbed.","Meanwhile, fry the onion in the oil and butter for 8 min until golden, add the fresh and soaked mushrooms, garlic and thyme and cook 6-8 min until dry, then stir in the spinach until wilted.","Heat the oven to 180°C. Mix the rice and mushroom mixture, and season well.","Put a heaped spoonful of filling at the base of each leaf, fold in the sides and roll up. Set the rolls seam side down in a baking dish lined with a few spare leaves.","Season the passata, thin it with 100 ml water and pour it over the rolls. Cover with a lid or foil.","Bake 50 min until the cabbage is very tender. Serve with a spoonful of crème fraîche and dill."]'::jsonb, array['polish', 'vegetarian', 'oven', 'comfort']::text[], 'polish', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('3386f80c-25ff-468e-bd8a-ec26b70c7749'::uuid, 'Joojeh kabab with saffron rice', 2, null::int, 285::int, 20::int, 25::int, '["Grind the saffron with a pinch of sugar or salt and steep it in 3 tbsp hot water for 10 min.","Mix the grated onion, the juice of the lemon, the yogurt, oil, turmeric, two thirds of the saffron water, salt and pepper. Coat the chicken in it, cover and chill at least 4 h, ideally overnight.","Rinse the rice until the water runs clear, then simmer it covered in 250 ml salted water with the butter for 12 min and rest 5 min off the heat.","Spoon a few tablespoons of rice into the rest of the saffron water and set aside to stir through when serving.","Thread the chicken onto skewers, shaking off the excess marinade. Heat a griddle pan or barbecue until very hot.","Grill the skewers 10-12 min, turning every few minutes, until charred at the edges and cooked through. Grill the tomato halves alongside for 5-6 min.","Fluff the white rice, top it with the saffron rice and serve with the kababs, grilled tomatoes and a squeeze of lemon."]'::jsonb, array['persian', 'middle eastern', 'grill', 'high protein', 'make ahead', 'summer']::text[], 'persian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f96f71e7-3799-457e-bcee-84a98bd7bcad'::uuid, 'Kuku sabzi', 2, null::int, 25::int, 10::int, 15::int, '["Wash the herbs and spring onions and dry them very well, then chop them finely with the garlic in a food processor using short pulses (or by hand).","Beat the eggs with the turmeric, baking powder, salt and pepper, then fold in the herbs and walnuts. The mixture should look more green than yellow.","Heat the oil in a 22-24 cm non-stick pan over medium-low heat, pour in the mixture and level it.","Cover and cook 8-10 min until the edges are set and the base is well browned.","Cut it into quarters, flip each one and cook uncovered another 4-5 min until set in the middle.","Serve warm or at room temperature with the yogurt and warm flatbread."]'::jsonb, array['persian', 'middle eastern', 'vegetarian', 'quick', 'spring']::text[], 'persian', 'easy', '{"pots":1,"oven":false,"special":["food processor"]}'::jsonb, 'Claude', null),
  ('27951550-45d9-4434-95ac-acb66e9a2444'::uuid, 'Jollof rice with chicken', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C. Rub the chicken with half the curry powder, the paprika, half the thyme, a little oil, salt and pepper. Roast skin side up on a tray for 22-25 min until golden and cooked through.","Meanwhile, blend the tomato, bell pepper, half the onion, the garlic, ginger and scotch bonnet to a smooth purée.","Chop the rest of the onion and fry it in the oil in a heavy pot over medium-high heat for 3 min.","Add the purée and cook, stirring, 6-7 min until thick and the oil starts to separate. Stir in the tomato paste, the remaining curry powder and thyme and fry 2 min.","Add the stock, bay leaf, butter and salt, bring to the boil, then stir in the rice.","Cover tightly and cook on low heat 18-20 min without stirring, until the rice is tender and the liquid is absorbed. Add a splash of water if it dries before the rice is done.","Rest 5 min off the heat, fluff with a fork and serve with the roast chicken."]'::jsonb, array['african', 'oven', 'spicy', 'comfort', 'high protein']::text[], 'african', 'medium', '{"pots":2,"oven":true,"special":["blender"]}'::jsonb, 'Claude', null),
  ('9859e619-b04e-460a-b38f-d101ff535774'::uuid, 'Poulet yassa', 2, null::int, 165::int, 15::int, 30::int, '["Mix the onions, the juice of the lemons, the mustard, garlic, scotch bonnet, 1 tbsp oil, salt and pepper. Turn the chicken in it, cover and chill at least 2 h, or overnight.","Lift the chicken out of the marinade and pat it dry. Brown it in the rest of the oil in a casserole over medium-high heat, 3 min per side, then set aside.","Drain the onions from the marinade, keeping the liquid. Cook them in the same casserole over medium heat for 12 min, stirring often, until soft and golden.","Add the marinade liquid, stock and bay leaf, then return the chicken. Cover and simmer gently for 12 min until the chicken is cooked through, adding the olives for the last 5 min.","Meanwhile, cook the rice in 1.5 times its volume of salted water, covered, for 12 min and rest 5 min.","Taste the sauce: it should be tangy but rounded; add a little more mustard or a pinch of sugar if too sharp. Serve over the rice."]'::jsonb, array['senegalese', 'african', 'stew', 'comfort', 'high protein']::text[], 'senegalese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('cc15f857-8ba8-43a4-b185-6b48713f7f16'::uuid, 'Brown stew chicken with rice and peas', 2, null::int, 165::int, 15::int, 30::int, '["Toss the chicken with the onion, pepper, carrot, garlic, ginger, spring onions, allspice, paprika, scotch bonnet, thyme, soy sauce, salt and pepper. Cover and chill at least 2 h, or overnight.","Heat the oil and sugar in a heavy pot over medium heat until the sugar turns dark brown and starts to smoke, 2-3 min, watching closely.","Lift the chicken out of the vegetables and brown it in the caramel for 3 min per side until deep brown.","Add the marinated vegetables and fry 3 min, then stir in the ketchup and stock. Cover and simmer gently for 12 min.","Meanwhile, for the rice and peas, put the rice, beans, coconut milk, 150 ml water, a sprig of thyme and salt in a pot, bring to the boil, cover and cook on low heat 15 min, then rest 5 min.","Uncover the chicken and simmer another 6-8 min until the meat is cooked through and the sauce thick and glossy.","Serve the chicken and gravy with the rice and peas."]'::jsonb, array['caribbean', 'stew', 'comfort', 'spicy', 'make ahead']::text[], 'caribbean', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5e6779a0-957a-4af7-9775-d03c9b70b678'::uuid, 'Gulyás', 2, null::int, 125::int, 20::int, 105::int, '["Melt the butter in a heavy pot over medium heat and cook the onions 8-10 min until golden.","Add the beef and brown it on all sides for 8 min.","Add the bell pepper, tomato and garlic and cook 5 min.","Take the pot off the heat and stir in the paprika and caraway so the paprika does not scorch.","Pour in the stock, add the bay leaf and salt, bring to the boil, then cover and simmer gently for 1 h.","Add the carrots and potatoes and simmer, covered, another 30-40 min until the beef is very tender and the potatoes are cooked.","Remove the bay leaf, season and serve in deep bowls with a spoonful of crème fraîche and bread."]'::jsonb, array['hungarian', 'soup', 'comfort', 'one-pot', 'winter']::text[], 'hungarian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('109d6d4a-1ff5-4003-9980-ec0e6c98e33c'::uuid, 'Bigos', 2, null::int, 175::int, 25::int, 150::int, '["Soak the dried porcini in 250 ml hot water for 20 min, then chop them and strain the liquid.","Fry the bacon in the oil in a large heavy pot over medium heat until it renders its fat, then add the pork and brown it on all sides for 8 min. Add the kielbasa for the last 2 min.","Add the onion and fresh mushrooms and cook 6-8 min until soft.","Stir in the tomato paste for 1 min, then add the sauerkraut, cabbage, porcini and their liquid, prunes, wine, bay, allspice, caraway and pepper.","Bring to a simmer, cover and cook on very low heat for 2 h, stirring now and then and adding a splash of water if it starts to catch.","Uncover for the last 15 min to thicken. Season, and serve with rye bread. It is even better reheated the next day."]'::jsonb, array['polish', 'stew', 'comfort', 'batch cooking', 'one-pot', 'winter']::text[], 'polish', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('263af3c6-ef74-4605-91cb-056837b47a7c'::uuid, 'Chkmeruli', 2, null::int, 25::int, 5::int, 20::int, '["Season the chicken with salt and pepper. Lay it skin side down in a large frying pan with the oil over medium-high heat and press it flat with a heavy pan or plate.","Cook 8-10 min until the skin is deep golden and crisp, then turn and cook 4-5 min more until cooked through. Pour off most of the fat.","Lower the heat, add the garlic paste around the chicken and stir it in the fat for 30-60 s without letting it brown.","Pour in the milk and cream, add the ground coriander and chili, and simmer 4-5 min, spooning the sauce over the chicken, until slightly thickened.","Stir in the parsley, scatter with coriander and serve straight from the pan with bread to mop up the sauce."]'::jsonb, array['georgian', 'quick', 'comfort', 'high protein']::text[], 'georgian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6c4dd985-1d88-4985-a862-18e27c911a1d'::uuid, 'Carbonnade flamande', 2, null::int, 200::int, 20::int, 180::int, '["Melt half the butter in a casserole over medium-low heat and cook the onions, covered, for 12-15 min until soft and golden. Add the lardons for the last 3 min, then lift everything out.","Raise the heat, add the rest of the butter and brown the beef in batches, 6-8 min in all, until well coloured. Season.","Sprinkle the beef with the flour and sugar and stir 1-2 min until the sugar caramelises.","Return the onions and lardons, pour in the beer, add the bouquet garni and scrape up the bottom of the pot.","Spread the gingerbread slices with the mustard and lay them on top, mustard side down, without stirring.","Cover and simmer on very low heat for 2 h 30 min to 3 h, until the beef is very tender and the gingerbread has melted into a thick sauce. Uncover for the last 15 min if the sauce is thin.","About 25 min before the end, boil the potatoes in salted water for 20 min until tender and drain.","Remove the bouquet garni, stir in the vinegar, adjust the seasoning and serve with the potatoes and parsley."]'::jsonb, array['belgian', 'stew', 'comfort', 'batch cooking', 'winter']::text[], 'belgian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('21256741-4c74-4be1-afeb-973446df94e4'::uuid, 'Waterzooi', 2, null::int, 50::int, 20::int, 30::int, '["Melt the butter in a large pot over medium-low heat and sweat the leek, carrots, celery and onion for 5 min without colouring.","Add the stock and bouquet garni, bring to a simmer, then add the chicken pieces and potatoes.","Poach gently, partly covered, for 15 min until the chicken is cooked through and the potatoes are tender.","Remove the bouquet garni and check a piece of chicken and potato are cooked through.","Whisk the cream, egg yolk and cornstarch in a bowl, then whisk in a ladle of hot broth.","Take the pot off the boil, stir in the cream mixture and heat gently for 2-3 min, stirring, until the broth thickens slightly. Do not let it boil.","Season with salt, pepper and a squeeze of lemon, and serve in deep plates with parsley and chives."]'::jsonb, array['belgian', 'soup', 'comfort', 'one-pot']::text[], 'belgian', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5cad9345-d8b4-438f-a6b8-4f4a657d32ac'::uuid, 'Jambalaya', 2, null::int, 45::int, 15::int, 30::int, '["Season the chicken with half the Creole seasoning. Brown it in the oil in a heavy pot over medium-high heat for 4 min, then set aside.","Brown the andouille in the same pot for 2 min and set aside with the chicken.","Cook the onion, celery and bell pepper in the fat for 5 min until soft, add the garlic for 30 s, then stir in the tomato paste for 1 min.","Add the tomatoes, stock, the rest of the seasoning, thyme and bay leaf, scrape the bottom, and return the chicken and andouille.","Bring to the boil, stir in the rice, then cover and cook on low heat 15 min without stirring.","Scatter the prawns over the rice, cover again and cook 4-5 min until they turn pink and the rice is tender.","Rest 5 min off the heat, fluff, season and serve with spring onions."]'::jsonb, array['creole', 'american', 'spicy', 'one-pot', 'generous']::text[], 'creole', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('751145c3-7b69-4ccb-a0f5-a608ed92d0d8'::uuid, 'Frikadeller with potatoes and cucumber salad', 2, null::int, 45::int, 20::int, 25::int, '["Put the potatoes in cold salted water, bring to the boil and simmer 15-20 min until tender.","Stir the vinegar, sugar, 1 tbsp water and a pinch of salt until dissolved and toss in the cucumber; leave to steep.","Mix the pork, veal, onion, egg, flour, milk, nutmeg, 1 tsp salt and pepper until sticky and smooth. Fry a teaspoon to check the seasoning.","Shape into 8 oval patties with a wet spoon or wet hands.","Fry them in the butter and oil in a frying pan over medium heat for 10-12 min, turning halfway, until well browned and cooked through.","Drain the potatoes and toss them with a little of the pan butter and parsley. Serve with the frikadeller and the drained cucumber scattered with dill."]'::jsonb, array['danish', 'comfort', 'kid-friendly', 'high protein']::text[], 'danish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('86344908-27c8-4c77-90f7-299d2972fb69'::uuid, 'Lemon salmon, potato and green bean traybake', 2, null::int, 40::int, 10::int, 30::int, '["Heat the oven to 220°C. Toss the quartered potatoes with 1 tbsp oil, salt and pepper on a large baking tray and roast 18 min.","Mix the rest of the oil with the garlic, the zest of the lemon and half its juice, half the dill, salt and pepper.","Push the potatoes to the sides, add the green beans tossed in a little of the lemon oil, and set the salmon in the middle, skin side down.","Spoon the rest of the lemon oil over the salmon and add a few lemon slices.","Roast 10-12 min until the salmon flakes easily and the beans are tender but still bright.","Scatter with the rest of the dill and serve with lemon wedges."]'::jsonb, array['british', 'oven', 'healthy', 'light', 'high protein']::text[], 'british', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('d473cbb0-83df-4bdb-bd0c-3fac1f8b2c83'::uuid, 'Pea and mint omelette with potatoes', 2, null::int, 25::int, 5::int, 20::int, '["Heat the oil in a 24 cm ovenproof non-stick pan over medium heat. Add the potato slices with a pinch of salt, cover and cook 10-12 min, turning now and then, until tender and golden in places.","Add the spring onions and frozen peas and cook uncovered 2 min until the peas are thawed.","Heat the oven grill. Beat the eggs with most of the mint, salt and pepper.","Pour the eggs into the pan, scatter over the feta and cook on medium-low heat 4-5 min, drawing the edges in once or twice, until the base is set and golden.","Slide the pan under the grill for 2-3 min until the top is puffed and just set.","Scatter with the remaining mint, cut into wedges and serve."]'::jsonb, array['british', 'vegetarian', 'quick', 'light', 'budget', 'spring']::text[], 'british', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('946f92ac-6411-45df-8501-3e4e1c32c64b'::uuid, 'Turkey burgers with roasted peppers and feta', 2, null::int, 40::int, 15::int, 25::int, '["Heat the oven to 220°C. Toss the pepper strips with 1 tbsp oil and salt on a tray and roast 20-25 min until soft and charred at the edges.","Mix the turkey with the oregano, half the garlic, the breadcrumbs, salt and pepper, and shape into 2 patties about 2 cm thick.","Stir the yogurt with the rest of the garlic, a squeeze of lemon and a pinch of salt.","Cook the patties in the rest of the oil in a frying pan over medium heat for 5-6 min per side until cooked through (74°C in the centre, no pink).","Top the patties with the feta for the last minute and cover the pan so it softens. Toast the buns cut side down in the pan or oven.","Fill the buns with lettuce, the burgers, the roasted peppers and a spoonful of the yogurt sauce."]'::jsonb, array['mediterranean', 'burger', 'high protein', 'kid-friendly']::text[], 'mediterranean', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, 'Sweet potato and feta hash with eggs', 2, null::int, 25::int, 8::int, 17::int, '["Heat the oil in a large lidded frying pan over medium-high heat. Add the sweet potato and onion with salt, cover and cook 8 min, stirring twice.","Uncover and cook 4-5 min more, stirring now and then, until the sweet potato is tender and browned at the edges.","Stir in the garlic, paprika and cumin for 1 min, then add the spinach and a squeeze of lemon and stir until wilted.","Make 4 wells in the hash, crack an egg into each, season and scatter the feta around.","Cover and cook on medium-low heat 4-5 min until the whites are set and the yolks still runny. Serve with chili flakes."]'::jsonb, array['american', 'vegetarian', 'quick', 'one-pot', 'healthy']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7c747998-0a21-4b64-913d-489d9d25bb52'::uuid, 'Pot-au-feu', 2, null::int, 235::int, 25::int, 210::int, '["Put the beef in a large pot, cover with 2.5 l cold water and bring slowly to the boil over medium heat (about 20 min), skimming off the grey foam as it rises.","Add the clove-studded onion, the bouquet garni, the peppercorns and 1 tbsp coarse salt, lower to a bare simmer and cook partly covered for 2 h, skimming now and then.","Add the carrots, turnips, leeks and celery and simmer 1 h more, until the meat is tender enough to cut with a spoon and the vegetables are soft.","Half an hour before the end, boil the potatoes in salted water (or a ladle of the broth topped up with water) for 20-25 min, until a knife slides in.","Lift out the meat and vegetables, slice the meat across the grain and keep everything warm in a little broth.","Strain the broth and spoon off the fat; season it to taste.","Serve a cup of broth first, then the meat, vegetables and potatoes with coarse salt, Dijon mustard and gherkins."]'::jsonb, array['french', 'comfort', 'stew', 'make ahead', 'winter']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0cf3abed-cbf5-41be-a48b-9b9513390ce2'::uuid, 'Endives au jambon', 2, null::int, 60::int, 15::int, 45::int, '["Trim the endive bases and cut out the small bitter cone at the root.","Put the endives in a lidded pan with 10 g butter, the lemon juice, the sugar, a pinch of salt and 3 tbsp water; cover and cook over low heat for 20 min, turning once, until tender to the point of a knife.","Drain the endives in a colander, pressing gently to squeeze out their juices, and heat the oven to 200°C.","Melt 20 g butter in a saucepan, stir in the flour and cook 1-2 min; whisk in the cold milk a little at a time and simmer 5 min, stirring, until it coats a spoon. Season with salt, pepper and nutmeg and stir in half the cheese.","Wrap each endive in a slice of ham and lay them seam-down in a gratin dish greased with the last of the butter.","Pour the béchamel over and scatter with the rest of the cheese.","Bake 20-25 min, until bubbling and golden, and rest 5 min before serving."]'::jsonb, array['french', 'gratin', 'comfort', 'oven', 'winter']::text[], 'french', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('e212f673-d1cc-44d6-b9a0-9ce0ec956d75'::uuid, 'Asparagus with soft-boiled eggs and ham', 2, null::int, 35::int, 15::int, 20::int, '["Boil the potatoes in salted water; after 10 min lower in the eggs and cook 6 min more, until a knife slides into the potatoes. Lift the eggs into iced water for 2 min and peel them carefully; drain the potatoes and keep warm.","Snap off the woody ends of the asparagus; peel white asparagus from just under the tip down, and green ones only on the lower third.","Cook the asparagus in a wide pan of boiling salted water until a knife tip goes in easily (green 4-6 min, white 10-15 min), then drain on a clean tea towel.","Whisk the mustard and vinegar with salt and pepper, whisk in the oil, then stir in the shallot and chives.","Arrange the asparagus, potatoes and both hams on plates, set the eggs on top, cut them open and spoon the vinaigrette over."]'::jsonb, array['french', 'light', 'healthy']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ae0c6d16-3076-4f9e-be47-67c892c439c3'::uuid, 'Petits pois à la française with roast chicken thighs', 2, null::int, 45::int, 15::int, 30::int, '["Heat the oven to 220°C. Toss the potatoes on a roasting tray with half the oil and a pinch of salt; pat the chicken thighs dry, rub with the rest of the oil, salt, pepper and thyme and set them skin up among the potatoes.","Roast 25-30 min, until the chicken skin is crisp, the juices run clear and the potatoes are golden and tender.","Meanwhile melt half the butter in a wide pan over medium-low heat (render the lardons first if using) and soften the spring onions for 5 min without colouring.","Add the peas, lettuce, sugar, stock and a pinch of salt, cover and simmer gently for 10 min (15-20 min for fresh peas), until the peas are tender and the lettuce has melted.","Uncover and let it bubble 2-3 min until only a few spoonfuls of liquid remain, then swirl in the rest of the butter off the heat.","Rest the chicken 5 min, stir a spoonful of its roasting juices into the peas and serve with the potatoes."]'::jsonb, array['french', 'oven', 'comfort', 'high protein', 'spring']::text[], 'french', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('f009535a-d269-4003-bba7-327628ed59c1'::uuid, 'Pumpkin and sage risotto', 2, null::int, 45::int, 15::int, 30::int, '["Bring the stock to a bare simmer in a saucepan and keep it hot.","Soften the shallot in the oil and 10 g butter in a wide pan over medium-low heat for 4 min, then add half the pumpkin and 3 chopped sage leaves and cook 5 min.","Add the rice and toast it 2 min, stirring, until the edges turn translucent; pour in the wine and stir until it has evaporated.","Add the stock a ladle at a time, stirring often and adding the next only when the last is almost absorbed; after 8 min add the rest of the pumpkin. Cook 17-18 min in all, until the rice is al dente and the first pumpkin has melted into it.","Meanwhile fry the remaining whole sage leaves in 10 g butter in a small pan for about 1 min, until crisp.","Off the heat, beat in the remaining butter and the parmesan with a splash of stock so the risotto flows (all''onda); season, cover and rest 2 min.","Serve topped with the crisp sage and black pepper."]'::jsonb, array['italian', 'risotto', 'vegetarian', 'comfort']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0969a7fb-e600-4b76-83a3-93d7652f0ba9'::uuid, 'Vignarola with poached eggs', 2, null::int, 55::int, 25::int, 30::int, '["Prepare the artichokes: snap off the tough outer leaves until you reach the pale ones, cut off the top third, peel the stems, quarter them, scoop out any choke and drop them into water with the lemon juice.","If the broad beans are bigger than a thumbnail, blanch them 1 min, cool and slip off their skins.","Render the guanciale in half the oil in a wide pan over medium heat for 4 min, add the spring onions and cook 3 min until soft.","Add the drained artichokes, toss 2 min, pour in the wine and let it bubble 1 min; add the stock, cover and simmer 12-15 min, until a knife goes easily into the base of the artichokes.","Add the broad beans and peas, cover and cook 5 min; stir in the lettuce and mint and cook 2 min more, until wilted. Season; the vegetables should sit in a little glossy juice.","Meanwhile bring a pan of water to a bare simmer with the vinegar, slide in the eggs one at a time from a cup and poach 3 min, then lift out with a slotted spoon.","Spoon the vignarola into shallow bowls, top each with 2 eggs, drizzle with the remaining oil and add pepper and pecorino if you like; serve with bread."]'::jsonb, array['italian', 'stew', 'light']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d4edda52-05e2-4715-a6cf-c38c88a78de8'::uuid, 'Spinach and ricotta gnudi with tomato sauce', 2, null::int, 85::int, 30::int, 25::int, '["Drain the ricotta in a sieve for 15 min.","Wilt the spinach in a dry pan for 2 min, let it cool, then squeeze it very dry in a clean tea towel and chop it finely.","Mix the ricotta, spinach, egg, 50 g parmesan, a grating of nutmeg, salt, pepper and 40 g flour into a soft dough that just holds its shape.","With floured hands roll walnut-size balls (16-18), roll them in the remaining flour, set them on a floured tray and chill 30 min.","For the sauce, warm the oil with the garlic over low heat for 1 min, add the passata and a pinch of salt and simmer 15 min; stir in the butter and the basil.","Cook the gnudi in batches in a wide pan of gently simmering salted water: they float after about 2 min; give them 1 min more and lift out with a slotted spoon. Test one first and add a spoon of flour to the dough if it falls apart.","Serve the gnudi in the sauce with the remaining parmesan."]'::jsonb, array['italian', 'vegetarian', 'comfort', 'spring']::text[], 'italian', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('95646b15-2042-4f16-9635-9e0c9dc5fe63'::uuid, 'Habas con jamón', 2, null::int, 30::int, 10::int, 20::int, '["Cook the onion gently in 1.5 tbsp oil in a lidded pan over medium-low heat for 8 min, until soft; add the garlic for 1 min.","Add the ham and stir 1-2 min, without letting it crisp.","Add the broad beans and the wine, let it bubble 1 min, then add 100 ml water, cover and cook over low heat 10-15 min (about 8 min for frozen beans), until tender; add a splash of water if it dries. Season with pepper and only a little salt.","Fry the eggs in the remaining oil in a small pan for about 3 min, until the edges are crisp and the yolks still runny.","Serve the beans topped with the fried eggs and a few mint leaves, with bread."]'::jsonb, array['spanish', 'quick', 'high protein']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a86e96e9-62db-412d-b135-71e84c0cbfef'::uuid, 'Lahmacun', 2, null::int, 110::int, 30::int, 20::int, '["Mix the flour, yeast and salt, add 160 ml lukewarm water and the oil and knead 8 min to a smooth dough; cover and leave to rise for 1 h, until doubled.","Squeeze the chopped onion, tomato, pepper and chilli in your hands to get rid of excess juice, then mix them with the lamb, garlic, parsley, tomato paste, Aleppo pepper, paprika, cumin, a pinch of salt and pepper into a spreadable paste.","Heat the oven to its maximum (250°C) with a baking tray inside, for at least 20 min.","Divide the dough into 4 and roll each piece very thin, into an oval of about 25-30 cm, on a floured surface.","Spread a quarter of the meat thinly over each, right to 1 cm from the edge, pressing it into the dough.","Slide one or two at a time on baking paper onto the hot tray and bake 7-9 min, until the edges are crisp and the meat is cooked.","Toss the sliced red onion with the sumac and parsley; serve the lahmacun hot with the onion salad and lemon to squeeze, rolled up to eat."]'::jsonb, array['turkish', 'street food', 'oven', 'generous']::text[], 'turkish', 'medium', '{"pots":1,"oven":true,"special":["rolling pin"]}'::jsonb, 'Claude', null),
  ('73fdf41a-9d25-4cb3-bfb6-6e7c3c74026a'::uuid, 'Hünkar beğendi', 2, null::int, 115::int, 25::int, 90::int, '["Brown the lamb in the oil in a heavy pot over high heat for about 5 min, in two batches.","Add the onion and cook 5 min, then the garlic and green pepper for 2 min and the tomato paste for 1 min. Add the tomatoes, 300 ml hot water, salt and pepper, cover and simmer gently 75-90 min, until the lamb is tender and the sauce thick; add a splash of water if needed.","Meanwhile prick the aubergines and char them directly over a gas flame for 10-15 min, or under the grill at 240°C for 25-30 min, turning, until collapsed and blackened.","Scoop out the flesh, leave it 5 min in water with the lemon juice, squeeze it dry and chop it very finely.","Melt the butter in a saucepan, stir in the flour for 1-2 min, then whisk in the milk a little at a time and cook 4-5 min, until thick.","Stir in the aubergine and cook 3-4 min, then add the cheese, a little nutmeg and salt and beat until smooth and creamy.","Spread the beğendi on plates, spoon the lamb and its sauce in the middle and sprinkle with Aleppo pepper."]'::jsonb, array['turkish', 'stew', 'comfort', 'generous']::text[], 'turkish', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('ee925082-69bb-44b0-940b-cb647bfd021f'::uuid, 'Kibbeh bil sayniyeh', 2, null::int, 90::int, 40::int, 50::int, '["Rinse the bulgur, cover with cold water and soak 15 min, then drain and squeeze it very dry in your hands.","For the filling, soften the chopped onion in half the oil over medium heat for 8 min; add the 120 g lamb and brown 6-8 min, breaking it up. Season with 0.5 tsp allspice, 0.5 tsp cinnamon, salt and pepper. Toast the pine nuts in a dry pan for 2-3 min and stir them in.","For the shell, process the bulgur with the 200 g lamb, the grated onion, the rest of the allspice and cinnamon, the cumin, salt and 2-3 tbsp iced water for about 2 min (or knead 5 min by hand) into a smooth paste.","Heat the oven to 190°C and oil a 20 cm baking dish. With wet hands, press half the shell evenly over the base, about 1 cm thick.","Spread the filling over it, cover with the rest of the shell in flattened pieces and smooth the top with wet hands.","Score the top into diamonds right down to the base, run a knife around the edge and pour the melted butter and the remaining oil over.","Bake 35-40 min, until deep golden with crisp edges; rest 10 min and serve with the yogurt."]'::jsonb, array['lebanese', 'middle eastern', 'oven', 'comfort', 'make ahead']::text[], 'lebanese', 'medium', '{"pots":2,"oven":true,"special":["food processor"]}'::jsonb, 'Claude', null),
  ('b7df0ef0-eeb6-4a50-95f6-c661bca1e47d'::uuid, 'Kotopoulo me araka', 2, null::int, 70::int, 15::int, 55::int, '["Season the chicken and brown it in the oil in a wide pot over medium-high heat, about 4 min a side; set aside.","Soften the onion and spring onions in the same pot for 5 min, then add the garlic for 1 min and the tomato paste for 1 min.","Add the tomatoes and 250 ml water, return the chicken, cover and simmer 20 min.","Add the potatoes and carrots with enough water to almost cover, season and simmer covered 15 min.","Add the peas and most of the dill and simmer uncovered 15 min, until the peas are soft, the potatoes tender and the sauce reduced and glossy with oil.","Rest 10 min off the heat, scatter with the remaining dill and serve warm, with feta if you like."]'::jsonb, array['greek', 'stew', 'one-pot', 'comfort', 'spring']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('10a782bb-b319-44ce-9ab0-8507659369f8'::uuid, 'Ispanaklı yumurta', 2, null::int, 25::int, 10::int, 15::int, '["Stir the yogurt with the garlic and a pinch of salt and set aside.","Soften the onion in the oil and half the butter in a wide lidded pan over medium heat for 5 min; add the tomato paste, cumin and half the Aleppo pepper for 1 min, then the grated tomato for 2 min.","Add the spinach by handfuls and stir until wilted, 2-3 min; season and cook off most of the liquid for 1-2 min.","Make 4 hollows, crack an egg into each, season, cover and cook over low heat 5-7 min, until the whites are set and the yolks still runny.","Melt the remaining butter in a small pan with the rest of the Aleppo pepper until it sizzles, about 30 s.","Spoon the garlic yogurt alongside, drizzle the pepper butter over the eggs and serve with bread."]'::jsonb, array['turkish', 'quick', 'vegetarian', 'light', 'spring']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('66f1f64b-259c-441a-8fe9-bef4680372ca'::uuid, 'Méchoui-style slow-roast lamb shoulder', 2, null::int, 225::int, 15::int, 210::int, '["Heat the oven to 160°C. Lightly score the fat of the lamb and rub it all over with the butter mashed with the garlic, 2 tsp cumin, the paprika, coriander and 1 tsp salt.","Set the lamb in a snug roasting dish with 150 ml water, cover tightly with foil and roast 3 h, basting with the juices every hour.","Uncover, raise the oven to 210°C and roast 25-30 min more, basting twice, until deep brown and the meat pulls easily from the bone.","Rest 10 min under loose foil.","Meanwhile mix 1 tsp cumin with 1 tsp salt for dipping, and toss the tomato, onion and parsley with the oil and a pinch of salt if making the salad.","Pull the meat off the bone with two forks, moisten with the pan juices and serve with the cumin salt, bread and salad."]'::jsonb, array['north african', 'moroccan', 'oven', 'generous', 'comfort']::text[], 'north african', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('c51f2da3-e80a-4036-a893-3720852ff2cb'::uuid, 'Lablabi', 2, null::int, 30::int, 10::int, 20::int, '["Crush the garlic with 1 tsp salt and 1.5 tsp cumin into a paste.","Warm 1 tbsp oil in a pot, fry the garlic paste 1 min, then add the chickpeas, stock and harissa and simmer 15 min; crush a few chickpeas against the side to thicken the broth a little.","Meanwhile lower the eggs into boiling water for 6 min, cool them in cold water and peel.","Put the torn bread into 2 deep bowls.","Ladle the chickpeas and broth over the bread and let it soak 1 min.","Top each bowl with an egg broken open, the capers, the tuna and parsley if using, the remaining cumin, a squeeze of lemon and the rest of the oil, with extra harissa to stir in."]'::jsonb, array['north african', 'soup', 'quick', 'budget', 'spicy']::text[], 'north african', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4ee738a3-579e-4c06-8cfa-0037f8174975'::uuid, 'Loubia with lamb', 2, null::int, 120::int, 15::int, 105::int, '["Brown the lamb in the oil in a heavy pot over medium-high heat for 5 min, then add the onion and cook 5 min more.","Stir in the garlic, tomato paste, paprika, cumin and chili powder for 1 min.","Add the tomatoes, bay leaf, 700 ml water, salt and pepper; cover and simmer gently 75 min, until the lamb is tender. (With soaked dried beans, add them now and allow 1 h 30.)","Add the canned beans and simmer uncovered 20 min, until the sauce is thick and the beans creamy.","Rest 5 min, scatter with coriander and serve with bread."]'::jsonb, array['north african', 'stew', 'comfort', 'one-pot', 'winter']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('01b1b8cb-5f7b-49dc-abb6-34d82d55a942'::uuid, 'Chicken korma', 2, null::int, 95::int, 15::int, 45::int, '["Mix the chicken with half the yogurt, the garlic, ginger and 0.5 tsp salt and leave to marinate 30 min.","Soak the cashews in hot water for 15 min. Fry the onions in the oil and butter in a heavy pan over medium heat for 12-15 min, stirring, until deep golden; lift out half of them.","Blend the lifted onions with the drained cashews, the rest of the yogurt and 4 tbsp water to a smooth paste.","Fry the cardamom, cloves, cinnamon and bay leaf in the pan with the remaining onions for 30 s, add the chicken and cook 5 min until opaque outside, then stir in the ground coriander and chili powder for 1 min.","Add the onion-cashew paste and 150 ml water and simmer covered over low heat 20-25 min, stirring now and then, until the chicken is tender and the sauce thick with a sheen of oil; keep it below a hard boil so the yogurt does not split.","Meanwhile rinse the rice, simmer it covered in 1.5 times its volume of salted water for 12 min and rest 5 min off the heat.","Stir the garam masala and the cream (if using) into the korma, season and serve with the rice and coriander."]'::jsonb, array['indian', 'curry', 'comfort']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('e99891d7-dc00-4d5a-a242-8694b13603cd'::uuid, 'Fish tikka', 2, null::int, 75::int, 20::int, 15::int, '["Pat the fish dry, toss with the juice of half the lemon and a pinch of salt and leave 10 min.","Toast the gram flour in a dry pan for 1-2 min until nutty, let it cool, then mix with the Greek yogurt, ginger, garlic, chili powder, garam masala, turmeric, ajwain, half the oil and 0.5 tsp salt.","Fold the fish gently into the marinade and leave in the fridge 30 min (no more than 1 h).","Heat the oven to 230°C with the grill on. Thread the fish onto skewers, or space it out on an oiled rack set over a foil-lined tray.","Cook 8-10 min, brush with the remaining oil, then grill 2-3 min more, until charred at the edges and the fish flakes.","Meanwhile blend the mint, most of the coriander, the chilli, plain yogurt and a pinch of salt into a chutney, and toss the tomato, cucumber and onion with the remaining lemon juice, coriander and salt.","Sprinkle the tikka with chaat masala and serve with the chutney, the salad and warm bread."]'::jsonb, array['indian', 'grill', 'healthy', 'high protein']::text[], 'indian', 'easy', '{"pots":1,"oven":true,"special":["blender"]}'::jsonb, 'Claude', null),
  ('d74e1f57-ab1d-49a7-8beb-1c44ff52a3ed'::uuid, 'Moong dal khichdi with fried eggs', 2, null::int, 35::int, 10::int, 25::int, '["Rinse the dal and rice together in several changes of water until it runs clear, then drain.","Heat 20 g ghee in a heavy pot over medium heat, add the cumin seeds and let them sizzle 30 s, then add the ginger and chilli for 30 s and the tomato for 2 min; stir in the turmeric.","Add the dal and rice and stir 1 min, then pour in 900 ml water with 1 tsp salt. Bring to the boil, cover and simmer on low 20-25 min, stirring now and then, until both are soft and the khichdi is like a thick porridge; add hot water for a looser one.","Fry the eggs in the remaining ghee in a pan for about 3 min, until the edges are crisp, and sprinkle with the chili powder and a pinch of salt.","Serve the khichdi topped with the eggs, with yogurt and coriander."]'::jsonb, array['indian', 'quick', 'comfort', 'budget', 'one-pot']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0a6c1c2e-111e-451b-8264-41a7301d11c7'::uuid, 'Salmon, asparagus and new potato traybake', 2, null::int, 40::int, 10::int, 30::int, '["Heat the oven to 220°C. Boil the potatoes in salted water for 8 min, drain and leave to steam dry 2 min.","Toss the potatoes on a large tray with 1 tbsp oil, salt and pepper and roast 10 min.","Snap the woody ends off the asparagus and toss the spears with 1 tbsp oil, the garlic and a pinch of salt.","Push the potatoes to the sides, add the asparagus and lay the salmon on top skin-side down; season and top with the lemon slices.","Roast 12-15 min, until the salmon is opaque and just flakes and the asparagus is tender.","Mix the dill, lemon juice, mustard and remaining oil with a pinch of salt.","Spoon the dressing over the salmon and vegetables and serve straight from the tray."]'::jsonb, array['british', 'oven', 'healthy', 'high protein']::text[], 'british', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('dfafcd91-634f-43f4-8416-3ef33e412692'::uuid, 'Hot and sour soup with pork and tofu', 2, null::int, 50::int, 20::int, 15::int, '["Soak the wood ear mushrooms in hot water for 20 min, then drain, cut out any hard bits and slice them thinly.","Start the rice: simmer it covered in 1.5 times its volume of water for 12 min, then rest 5 min off the heat. Toss the pork with 1 tsp of the soy sauce and 1 tsp of the cornstarch and leave it while you cut everything else.","Bring the stock to the boil in a pot, add the wood ears, shiitake and bamboo shoots and simmer 3 min.","Add the pork, stirring to separate the strips, and simmer 2 min until it turns pale; add the tofu, the rest of the soy sauce, the dark soy sauce and the sugar.","Mix the rest of the cornstarch with 4 tbsp cold water, stir it into the simmering soup and cook 1 min until it thickens slightly and turns glossy.","Lower the heat and pour in the beaten eggs in a thin stream while stirring slowly in one direction, so they set in ribbons; leave 30 seconds.","Off the heat, stir in the black vinegar, white pepper and sesame oil. Taste and add salt, vinegar or pepper: it should be clearly sour and peppery.","Ladle into bowls, scatter with spring onion and serve with the rice."]'::jsonb, array['chinese', 'asian', 'soup', 'spicy', 'comfort']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('37907ecd-1bda-4dbd-9ff7-457883f41468'::uuid, 'Lion''s head meatballs with cabbage', 2, null::int, 70::int, 20::int, 50::int, '["Mix the pork with the ginger, two thirds of the spring onion, the rice wine, 1 tbsp soy sauce, the sugar, the egg, 1 tbsp cornstarch, the white pepper and 0.5 tsp salt. Stir hard in one direction for 3-4 min until the mixture is sticky and springy.","With wet hands, shape 4 large meatballs of about 90 g each.","Heat the oil in a casserole over medium heat and brown the meatballs gently on all sides, 6-8 min; lift them out.","Fry the thick cabbage stems in the same fat for 2 min, set the meatballs on top and tuck the leaves over them.","Pour in the stock, the rest of the soy sauce and the dark soy sauce. Bring to the boil, cover and simmer on low heat 35-40 min, until the meatballs are tender and the cabbage silky.","Meanwhile, rinse the rice and simmer it covered in 1.5 times its volume of water for 12 min, then rest 5 min off the heat.","Lift the meatballs and cabbage into bowls. Thicken the broth with the rest of the cornstarch mixed into 2 tbsp water, boil 1 min, then add the sesame oil.","Spoon the sauce over, sprinkle with the remaining spring onion and serve with the rice."]'::jsonb, array['chinese', 'asian', 'comfort', 'stew', 'winter']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('55043b76-d1aa-4e87-ad98-d03ada43f562'::uuid, 'Prawn and asparagus stir-fry', 2, null::int, 25::int, 10::int, 15::int, '["Start the rice: simmer it covered in 1.5 times its volume of water for 12 min, then rest 5 min off the heat.","Toss the prawns with a pinch of salt, 1 tsp cornstarch and half the rice wine. Mix the oyster sauce, soy sauce, sugar, white pepper, the rest of the cornstarch and 4 tbsp water in a bowl.","Heat 1 tbsp oil in a wok over high heat until it smokes and sear the prawns about 1 min per side until just pink; tip them onto a plate.","Add the rest of the oil, then the garlic and ginger for 15 seconds, then the asparagus with a pinch of salt. Stir-fry 2 min, add 2 tbsp water and toss 1 min more until bright green and crisp-tender.","Return the prawns, splash the rest of the rice wine around the hot edge of the wok, pour in the sauce and toss 30-60 seconds until glossy.","Off the heat, drizzle with the sesame oil and serve with the rice."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'quick', 'light']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ee587622-6ee2-467e-8fda-bb22df3a49a0'::uuid, 'Yakisoba with pork', 2, null::int, 25::int, 10::int, 15::int, '["Mix the Worcestershire sauce, oyster sauce, ketchup, soy sauce and sugar in a small bowl.","Cook the dried noodles in boiling water for 1 min less than the packet says, drain, rinse under cold water and toss with a few drops of oil. Fresh yakisoba noodles only need loosening under hot water.","Heat the oil in a large frying pan or wok over medium-high heat and fry the pork belly 3-4 min until golden and crisp at the edges; season with pepper.","Add the onion and carrot and stir-fry 2 min, then the cabbage for 2 min until it just wilts.","Add the noodles, the bean sprouts and 2 tbsp water and toss 2 min to heat through.","Pour in the sauce, add the spring onion and toss over high heat 1-2 min until the noodles are evenly brown and catch slightly on the pan.","Serve topped with the red pickled ginger."]'::jsonb, array['japanese', 'asian', 'stir-fry', 'quick', 'street food']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ab67d2ee-23c9-4012-ba25-0beea79e587c'::uuid, 'Hambāgu (Japanese hamburg steak)', 2, null::int, 42::int, 20::int, 22::int, '["Cook the onion in 1 tsp of the oil over medium heat for 6-8 min until soft and light golden, then let it cool. Soak the panko in the milk.","Start the rice: simmer it covered in 1.5 times its volume of water for 12 min, then rest 5 min off the heat.","Put the beef, pork, cooled onion, soaked panko, egg, nutmeg, 0.5 tsp salt and some pepper in a bowl and knead 1-2 min until sticky.","Divide in two. Toss each half from hand to hand to knock out the air, shape into an oval about 2 cm thick and press a dimple into the centre.","Wipe the onion pan, add the rest of the oil over medium-high heat and brown the patties 3 min. Turn them, pour in the wine, cover and cook on low heat 8 min, until the juices run clear when pressed.","Meanwhile, cook the broccoli in the rice pot: lay it on the rice for the last 5 min of its cooking, covered, so it steams.","Move the patties to plates. Add the ketchup, Worcestershire sauce and butter to the pan juices and simmer 1 min until glossy.","Spoon the sauce over the patties and serve with the rice and broccoli."]'::jsonb, array['japanese', 'asian', 'comfort', 'kid-friendly']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1730bc57-55bd-4af6-a13e-c743c60afdbd'::uuid, 'Asparagus butabara maki with rice', 2, null::int, 35::int, 20::int, 15::int, '["Start the rice: simmer it covered in 1.5 times its volume of water for 12 min, then rest 5 min off the heat.","Peel the bottom third of the asparagus if thick. Blanch the spears 1 min in boiling salted water in the frying pan, drain, cool under cold water and pat completely dry; wipe the pan.","Mix the soy sauce, mirin, sake and sugar in a small bowl.","Wrap each spear in a slice of pork belly in a spiral, overlapping slightly. Season lightly with salt and pepper and dust with the cornstarch.","Heat the oil in the pan over medium heat and lay the rolls in seam-side down. Cook 2 min until the seams set, then turn and cook 5-6 min more until golden all over.","Dab away most of the fat with kitchen paper, pour in the sauce and let it bubble 1-2 min, rolling the asparagus until coated in a sticky glaze.","Cut each roll in half and serve over the rice with the pan glaze and sesame seeds."]'::jsonb, array['japanese', 'asian']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d9057435-15c8-4de0-902f-aa8741ca003f'::uuid, 'Phở bò', 2, null::int, 195::int, 30::int, 165::int, '["Char the onion halves and ginger cut-side down in a dry heavy pan over high heat for 8-10 min until blackened in patches; rinse off any loose burnt skin.","Put the brisket in a pot, cover with cold water, boil 3 min, then drain and rinse the meat and the pot: this keeps the broth clear.","Return the brisket to the pot with the stock, 1 l water, the charred onion and ginger, 1 tbsp fish sauce and the sugar. Bring to a bare simmer and cook uncovered 2-2.5 h, skimming now and then, until the brisket is tender.","For the last 45 min, toast the star anise, cinnamon, cloves, coriander seeds and cardamom in the dry pan for 2 min until fragrant and add them to the broth in a tea infuser or tied in muslin.","Lift out the brisket and slice it thinly. Strain the broth and season it with the rest of the fish sauce and salt; you want about 1.2 l of clear, well-seasoned broth.","Soak or cook the rice noodles as the packet says, drain and divide between two large bowls.","Top the noodles with the brisket, the raw steak slices and the sliced onion. Bring the broth back to a rolling boil and ladle it over, so it cooks the raw beef to pink.","Scatter with spring onion and coriander and serve with the bean sprouts, Thai basil, lime, chilli, hoisin and sriracha on the side."]'::jsonb, array['vietnamese', 'asian', 'soup', 'comfort']::text[], 'vietnamese', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('21c5d365-a70b-47b4-86f0-da46e6a9f976'::uuid, 'Cà ri gà (Vietnamese chicken curry)', 2, null::int, 80::int, 20::int, 30::int, '["Toss the chicken with 1 tbsp curry powder, 1 tbsp fish sauce, the sugar and a third of the garlic and leave 30 min.","Heat the oil in a pot over medium heat and fry the shallot, the rest of the garlic, the ginger and the lemongrass for 2 min, then stir in the rest of the curry powder for 30 seconds.","Add the chicken and brown it 5 min, turning.","Pour in the stock and coconut milk, add the carrot and sweet potato and bring to a simmer.","Simmer uncovered 20 min, until the chicken is cooked through, the vegetables are tender and the sauce has thickened a little.","Season with the rest of the fish sauce and salt and take out the lemongrass.","Serve in bowls topped with spring onion and coriander, with the baguette for dipping."]'::jsonb, array['vietnamese', 'asian', 'curry', 'one-pot', 'comfort']::text[], 'vietnamese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f32ce680-abc9-44ed-b155-d09e4329c413'::uuid, 'Ayam kecap (Indonesian sweet soy chicken)', 2, null::int, 55::int, 15::int, 30::int, '["Toss the chicken with the juice of half the lime and 0.5 tsp salt and leave 10 min.","Start the rice: simmer it covered in 1.5 times its volume of water for 12 min, then rest 5 min off the heat.","Heat the oil in a wok or large frying pan over medium-high heat and fry the chicken in one layer for 6-8 min, turning, until golden; lift it out.","In the remaining oil, fry the shallots 3-4 min until golden, then add the garlic, ginger and chilli for 1 min.","Return the chicken, add the kecap manis, soy sauce, nutmeg, some pepper and 150 ml water. Simmer uncovered 12-15 min, turning the pieces, until the sauce reduces to a sticky glaze and the chicken is cooked through.","Add the tomato and spring onion for the last 2 min, just until softened.","Serve with the rice and lime wedges."]'::jsonb, array['indonesian', 'asian', 'comfort']::text[], 'indonesian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('9a075ad1-e1c7-489b-ba5a-1a94b5f9a182'::uuid, 'Haemul pajeon (seafood pancake)', 2, null::int, 30::int, 15::int, 15::int, '["Make the dipping sauce: mix the soy sauce, vinegar, 1 tbsp water, the gochugaru and the sesame seeds.","Whisk the flour, cornstarch and salt with 180 ml ice-cold water until just smooth; the batter should be as thin as single cream.","Heat 1.5 tbsp oil in a 24-26 cm frying pan over medium-high heat. Lay in half the spring onions side by side, scatter over half the prawns, squid and chilli, and pour half the batter evenly over to bind them.","Drizzle half the beaten egg over the top and cook 3-4 min until the underside is crisp and golden.","Flip the pancake, add a little more oil around the edge, press it down and cook 3 min until the seafood is cooked and the second side crisp.","Slide it out and make the second pancake the same way.","Cut into squares and serve straight away with the dipping sauce."]'::jsonb, array['korean', 'asian', 'street food']::text[], 'korean', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('77e695ba-765c-416d-879e-ee52967eb6a7'::uuid, 'Bossam (Korean boiled pork wraps)', 2, null::int, 90::int, 25::int, 65::int, '["In a pot, bring about 2 l water to the boil with the onion, the white parts of 3 spring onions, 6 garlic cloves, the ginger, doenjang, rice wine, peppercorns and bay leaves, and boil 5 min.","Add the pork so it is fully covered, return to the boil, then cover and simmer on medium-low heat 50-60 min, until a chopstick slides through the thickest part easily.","Meanwhile, toss the daikon with 0.5 tsp salt, leave 10 min and squeeze out the water lightly. Mix it with the gochugaru first to colour it, then with the fish sauce, sugar, vinegar, 1 grated garlic clove, the chopped remaining spring onions and the sesame seeds.","Rinse and dry the cabbage leaves. Slice the remaining garlic thinly and put it, the kimchi and the ssamjang into small dishes.","Lift the pork out of the pot, rest it 5 min and slice it 5 mm thick.","To eat, wrap a slice of pork in a cabbage leaf with some radish salad, kimchi, a slice of garlic and a dab of ssamjang."]'::jsonb, array['korean', 'asian', 'generous']::text[], 'korean', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7202212f-7f30-4815-9536-2eeff0208cb9'::uuid, 'Feijoada', 2, null::int, 140::int, 25::int, 115::int, '["Heat the oil in a heavy casserole over medium-high heat and fry the bacon 4 min until the fat runs. Add the pork and brown it 6-8 min, then the sausage for 2 min.","Add the onion and two thirds of the garlic and cook 5 min until soft.","Add the bay leaves, 600 ml water and some pepper, bring to the boil, cover and simmer on low heat 1 h, until the pork is nearly tender.","Add the beans and simmer uncovered 40 min, stirring now and then. Mash a ladleful of beans against the side of the pot so the stew turns dark and creamy; season (the bacon and sausage are already salty).","Meanwhile, simmer the rice covered in 1.5 times its volume of salted water for 12 min, then rest 5 min off the heat.","Just before serving, fry the rest of the garlic in a little oil in a frying pan for 30 seconds, add the kale with a pinch of salt and toss 2-3 min until bright green and just wilted.","Serve the feijoada with the rice, the greens, the orange slices and hot sauce."]'::jsonb, array['brazilian', 'stew', 'comfort', 'generous']::text[], 'brazilian', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('606c2941-260f-444a-9ee9-55904482bfef'::uuid, 'Huevos rancheros', 2, null::int, 25::int, 10::int, 15::int, '["Blend the tomatoes, the chunk of onion, the garlic, the chilli and a pinch of salt until smooth.","Heat 1 tsp oil in a saucepan, pour in the salsa (it will spit) and simmer 8-10 min until slightly thickened; season.","Meanwhile, heat 1 tsp oil in a frying pan and fry the chopped onion 3 min. Add the beans and 3 tbsp water and mash with a fork into a rough purée over the heat for 3 min; season and tip into a bowl.","Wipe the pan and warm the tortillas in it dry, 30 seconds per side, until soft and lightly toasted; wrap them in a tea towel.","Heat the rest of the oil in the pan and fry the eggs over medium heat about 3 min, until the whites are set and the yolks still runny.","Put 2 tortillas on each plate, spread with the beans, top each with an egg and spoon the warm salsa around. Finish with queso fresco, avocado and coriander."]'::jsonb, array['mexican', 'quick', 'vegetarian', 'comfort']::text[], 'mexican', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('065cf384-d091-4686-9e88-f46b9f905af0'::uuid, 'Empanadas de carne', 2, null::int, 125::int, 60::int, 25::int, '["Make the dough: mix the flour and salt, add the melted butter and about 100 ml warm water little by little, and knead 5 min until smooth and soft. Wrap and rest 30 min.","Boil 2 of the eggs 10 min, cool them in cold water, peel and chop.","Heat the oil in a frying pan and cook the onion and spring onion whites over medium heat 8 min until soft. Add the beef, break it up and cook 5 min until no longer pink. Season with the paprika, cumin, chili flakes, oregano, salt and pepper, stir in the spring onion greens and leave to cool completely, at least 30 min in the fridge.","Heat the oven to 200°C. Roll the dough out 2-3 mm thick and cut 12 cm discs, re-rolling the scraps; you should get 8-10.","Put a heaped spoonful of filling in the centre of each disc with some chopped egg, olives and raisins. Brush the edge with water, fold into a half-moon, press to seal and twist the edge over itself to crimp.","Set the empanadas on a lined baking tray, brush with the last egg, beaten, and prick each once with a fork.","Bake 18-20 min until deep golden. Rest 5 min before eating."]'::jsonb, array['argentinian', 'oven', 'street food', 'comfort', 'picnic']::text[], 'argentinian', 'hard', '{"pots":3,"oven":true,"special":["rolling pin"]}'::jsonb, 'Claude', null),
  ('bd00c98e-1568-44a4-89e9-94a79fa0d62f'::uuid, 'Fesenjan', 2, null::int, 95::int, 15::int, 80::int, '["Toast the walnuts in a dry heavy pot over medium heat 4-5 min until fragrant, cool, then grind them in a food processor to a fine, damp crumb.","Heat the oil in the same pot and cook the onion 8 min until golden. Stir in the turmeric, add the chicken and brown it 5 min; lift the chicken out.","Add the ground walnuts and stock to the pot, bring to a simmer, cover and cook on low heat 30 min, stirring often so it does not catch, until the sauce darkens and a little oil rises.","Stir in the pomegranate molasses, cinnamon, sugar, salt and pepper, return the chicken and simmer covered 30-40 min, until the chicken is tender and the sauce thick and dark brown. Taste and balance sour and sweet with more molasses or sugar.","Meanwhile, rinse the rice and simmer it covered in 1.5 times its volume of salted water, with the saffron, for 12 min; rest 5 min off the heat.","Serve the fesenjan over the rice, scattered with parsley."]'::jsonb, array['persian', 'middle eastern', 'stew', 'fancy', 'autumn', 'winter']::text[], 'persian', 'medium', '{"pots":2,"oven":false,"special":["food processor"]}'::jsonb, 'Claude', null),
  ('8b20d202-eae1-49a5-aa90-14874c2a0c0e'::uuid, 'Thieboudienne', 2, null::int, 115::int, 35::int, 80::int, '["Make the rof: pound or chop the parsley, garlic, spring onions, a pinch of chili flakes, 0.5 tsp salt and some pepper to a rough paste. Cut 2 deep slits in each fish steak and stuff them with half the rof.","Heat the oil in a wide pot over medium heat and brown the fish 2 min per side; lift it out.","Cook the onion in the same oil 6-8 min until soft. Add the tomato paste loosened with 100 ml water and fry 5-8 min, stirring, until it darkens to brick red and the oil separates.","Add the stock, bay leaf, whole scotch bonnet and the rest of the rof and bring to the boil. Add the carrots, turnip, cassava and cabbage and simmer 15 min, then the eggplant and the fish for 10-15 min more, until the fish flakes and the vegetables are tender.","Lift the fish and vegetables onto a dish, cover with foil and keep warm; take out the scotch bonnet. Leave about 450 ml of broth in the pot and set the rest aside.","Rinse the rice, stir it into the broth, cover tightly and cook on low heat 20-25 min until it has absorbed the liquid and is tender, adding a little reserved broth if it dries out. Turn the heat up for the last 2 min so the bottom crisps.","Spread the rice on a large platter, arrange the fish and vegetables on top, spoon over some of the reserved broth and serve with lime wedges."]'::jsonb, array['senegalese', 'african', 'one-pot', 'comfort']::text[], 'senegalese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('2967ec22-b774-49f7-b93c-f359f1cb02ed'::uuid, 'Käsespätzle', 2, null::int, 65::int, 15::int, 35::int, '["Beat the flour, eggs, milk, salt and nutmeg with a wooden spoon for 3-4 min until smooth, thick and bubbly, so it falls from the spoon in slow ribbons. Rest it 15 min.","Melt 20 g butter in a frying pan over medium-low heat and cook the onions 15-20 min, stirring now and then, until deep golden; turn the heat up for the last 2 min to crisp them.","Heat the oven to 180°C and butter an ovenproof dish with the rest of the butter.","Bring a large pot of salted water to the boil. In 3 batches, press the batter through a spätzle press or a colander with large holes, or scrape thin strips off a wet board into the water. When they float, after 1-2 min, lift them out with a slotted spoon.","Layer the hot spätzle in the dish with the cheese and some pepper, finishing with cheese.","Bake 10 min until the cheese has melted, then top with the crisp onions and chives and serve with a green salad."]'::jsonb, array['german', 'treat', 'comfort', 'oven', 'vegetarian', 'winter']::text[], 'german', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('518315a0-7551-4a2c-a8bb-e97d40a780b6'::uuid, 'Borscht with beef', 2, null::int, 145::int, 25::int, 120::int, '["Put the beef in a large pot with 1.5 l cold water, bring to the boil and skim. Add the bay leaves, peppercorns and 1 tsp salt and simmer partly covered 1.5 h, until the beef is tender.","Lift out the beef, cut it into bite-size pieces and return it to the broth.","Meanwhile, heat the oil in a frying pan and cook the onion and carrot 5 min. Add the beetroot, tomato paste, 1 tbsp vinegar, the sugar and a ladle of broth, cover and stew 15 min, stirring now and then (the vinegar keeps the colour bright).","Add the potatoes to the broth and simmer 10 min.","Add the cabbage and simmer 5 min.","Stir in the beetroot mixture and the garlic and simmer 5 min. Season with salt and the rest of the vinegar until sweet-sour, add half the dill and, if you can, rest the soup 10 min off the heat.","Serve with a spoonful of crème fraîche, the rest of the dill and rye bread."]'::jsonb, array['soup', 'comfort', 'batch cooking', 'winter']::text[], 'ukrainian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('9244b1f2-c079-4d75-9219-3455d670a6ae'::uuid, 'Misir wot with eggs', 2, null::int, 65::int, 15::int, 50::int, '["Cook the onions in a dry pot over medium-low heat 8-10 min, stirring, until soft and just starting to colour.","Add 30 g butter, the cardamom, garlic and ginger and cook 3 min.","Stir in 1.5 tbsp berbere and the tomato paste with a splash of water and fry 2 min, until dark red and fragrant; add water if the spice starts to catch.","Add the lentils and 800 ml hot water, bring to the boil and simmer partly covered 30-35 min, stirring often and adding water if needed, until the lentils collapse into a thick, spoonable stew.","Meanwhile, boil the eggs 9 min, cool them in cold water, peel and score the surface lightly with a knife.","Stir the rest of the butter and berbere into the wot and season with salt. Add the eggs and simmer 5 min so they take on the colour.","Serve on injera, with the eggs halved on top."]'::jsonb, array['ethiopian', 'african', 'stew', 'vegetarian', 'spicy']::text[], 'ethiopian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1a70bffe-f24f-41c8-871e-d950aaa404e7'::uuid, 'Radish, egg and smoked trout salad with new potatoes', 2, null::int, 35::int, 15::int, 20::int, '["Boil the potatoes in salted water 15-18 min until tender, adding the eggs for the last 8 min.","Drain, cool the eggs in cold water, then peel and quarter them. Halve the potatoes while still warm.","Mix the crème fraîche, mustard, lemon juice, half the dill, salt and pepper into a dressing.","Toss the warm potatoes with the shallot and half the dressing.","Add the radishes, cucumber and arugula, then arrange the eggs and flaked trout on top.","Spoon over the rest of the dressing and finish with the remaining dill and the chives."]'::jsonb, array['danish', 'salad', 'light', 'spring']::text[], 'danish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d57419c4-5bac-533f-a864-773905989892'::uuid, 'Air-fryer lemon chicken with herby bulgur, peas and lemon-herb yogurt', 2, null::int, 25::int, 10::int, 15::int, '["Rub the chicken with the olive oil, half the lemon zest, the oregano, half the garlic, salt and pepper.","Air-fry the chicken at 200°C for 12–15 min, turning halfway, until it reaches 75°C in the thickest part; rest it 3 min.","Meanwhile bring the bulgur and stock to the boil in a pot, cover and simmer gently for 10 min.","Stir in the peas, cover and cook 3 min more, then stir in the spinach off the heat until it wilts.","Mix the yogurt with half the lemon juice, the rest of the garlic, half the mint and parsley and a pinch of salt.","Fork the remaining lemon juice, zest and herbs through the bulgur, slice the chicken and serve on top with the yogurt."]'::jsonb, array['mediterranean', 'healthy', 'high protein', 'bowl', 'quick']::text[], 'mediterranean', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('64156951-1c4e-5eff-aae3-b139edfc8c3c'::uuid, 'Peanut-lime chicken noodles with carrot and pepper', 2, null::int, 27::int, 15::int, 12::int, '["Cook the rice noodles in a pot of boiling water as the pack says (usually 4–6 min), drain and rinse under cold water.","Whisk the peanut butter, soy sauce, lime zest and juice, honey, sriracha, garlic and ginger with 3–4 tbsp hot water until smooth and pourable.","Heat the oil in a wok or large frying pan over high heat and stir-fry the chicken for 4–5 min until golden and cooked through.","Add the pepper and carrot and stir-fry 2 min so they stay crisp.","Add the noodles and the sauce and toss over the heat for 1 min until everything is coated; loosen with a splash of water if needed.","Serve scattered with spring onion, coriander and chopped peanuts."]'::jsonb, array['asian', 'stir-fry', 'high protein', 'kid-friendly']::text[], 'asian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('43b6a6ab-8a49-504d-a5d0-0bdff76e2627'::uuid, 'Air-fryer pesto chicken with crushed new potatoes and green beans', 2, null::int, 30::int, 10::int, 20::int, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer for 15 min.","Season the chicken and spread it with 2 tbsp of the pesto.","Air-fry the chicken at 200°C for 12–14 min, until it reaches 75°C in the thickest part; rest it 3 min.","Add the green beans to the potatoes for their last 4 min, then drain everything well.","Lift out the beans, then lightly crush the potatoes in the pot with the olive oil, the rest of the pesto, a squeeze of lemon, salt and pepper.","Slice the chicken and serve it with the potatoes and beans, with parmesan on top."]'::jsonb, array['italian', 'high protein', 'kid-friendly']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('2ad7bb6d-b208-58bf-b258-1f95e64ea400'::uuid, 'Air-fryer harissa chicken with pepper and chickpea couscous', 2, null::int, 30::int, 15::int, 15::int, '["Mix the harissa with 1 tbsp of the oil, half the lemon juice and a pinch of salt, and coat the chicken; leave it while you prepare the rest.","Air-fry the chicken at 200°C for 12–15 min, turning halfway, until it reaches 75°C in the thickest part; rest it 3 min.","Meanwhile heat the rest of the oil in a deep frying pan and soften the pepper and onion for 6 min over medium heat.","Add the chickpeas and cumin and cook 1 min, then stir in the couscous and pour over the boiling stock.","Take off the heat, cover and leave 5 min, then fluff with a fork with the rest of the lemon juice and half the mint.","Slice the chicken and serve it on the couscous with the yogurt and the rest of the mint."]'::jsonb, array['north african', 'spicy', 'high protein', 'healthy']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('733ec69d-3777-5784-86c3-674f2fc480d3'::uuid, 'Miso-ginger chicken with soba and broccoli', 2, null::int, 25::int, 10::int, 15::int, '["Whisk the miso, soy sauce, mirin, honey, ginger, garlic, rice vinegar and sesame oil with 3 tbsp water.","Cook the soba in a pot of boiling water for 4–5 min, adding the broccoli for the last 2 min; drain and rinse briefly under cold water.","Heat the oil in a large frying pan over medium-high heat and cook the chicken for 5–6 min until golden and cooked through.","Pour in the miso sauce and let it bubble for 1 min until it glazes the chicken.","Add the noodles and broccoli and toss for 1 min to warm through and coat.","Serve sprinkled with sesame seeds and spring onion."]'::jsonb, array['japanese', 'high protein', 'quick', 'healthy']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4624f1fb-2e42-5728-bc55-0198cd2918ca'::uuid, 'Air-fryer honey gochujang chicken thighs with rice and cucumber', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and cook it in a pot with 300 ml water: bring to the boil, cover and simmer on low for 12 min, then rest 5 min off the heat.","Mix the gochujang, honey, soy sauce, sesame oil and garlic into a glaze; toss the chicken in a third of it.","Air-fry the chicken at 200°C for 8 min, then turn it, brush with the rest of the glaze and cook 4–6 min more until sticky and 75°C inside.","Meanwhile lightly smash the cucumber with a rolling pin or the flat of a knife and break it into bite-size pieces.","Toss the cucumber with the rice vinegar, sugar, a pinch of salt and half the sesame seeds.","Slice the chicken and serve it over the rice with the cucumber, the rest of the sesame seeds and the spring onion."]'::jsonb, array['korean', 'asian', 'spicy', 'bowl']::text[], 'korean', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('079ff286-d35c-5eda-b67b-aee1962e87e9'::uuid, 'Air-fryer chicken thighs with tahini-lemon sauce, quinoa and kale', 2, null::int, 28::int, 10::int, 18::int, '["Simmer the quinoa in a pot with 280 ml salted water, covered, for 15 min until the water is absorbed; rest 5 min.","Rub the chicken with the cumin, paprika, half the oil, salt and pepper.","Air-fry the chicken at 200°C for 12–14 min, turning halfway, until browned and 75°C inside.","Whisk the tahini with half the lemon juice, 1 grated garlic clove, a pinch of salt and 4–5 tbsp cold water until smooth and pourable.","Heat the rest of the oil in a frying pan, add the second garlic clove, sliced, and the kale with a splash of water and cook 3–4 min until tender.","Fold the kale and the rest of the lemon juice into the quinoa, top with the sliced chicken, the tahini sauce and the parsley."]'::jsonb, array['middle eastern', 'healthy', 'high protein', 'bowl']::text[], 'middle eastern', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('f006e547-e528-5078-be45-4fe999de4982'::uuid, 'Cajun chicken wraps with sweetcorn salsa', 2, null::int, 27::int, 15::int, 12::int, '["Toss the chicken with the Cajun seasoning and a pinch of salt.","Mix the corn, tomato, red onion, coriander and the juice of half the lime for the salsa; season with salt.","Stir the zest and remaining lime juice into the yogurt.","Heat the oil in a large frying pan over medium-high heat and cook the chicken and pepper for 8–10 min, stirring, until the chicken is charred at the edges and cooked through.","Wipe the pan and warm the tortillas in it for 20 seconds a side.","Spread each tortilla with lime yogurt, add lettuce, chicken and pepper and a spoonful of salsa, and roll up."]'::jsonb, array['american', 'wrap', 'spicy', 'kid-friendly']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7279a898-d04d-57eb-b82b-e31b57e6571a'::uuid, 'Air-fryer sweet chilli-lime chicken thighs with rice noodle salad', 2, null::int, 45::int, 15::int, 14::int, '["Mix 2 tbsp of the sweet chilli sauce with the soy sauce, the zest of 1 lime, the garlic and the ginger; coat the chicken and leave 15 min.","Air-fry the chicken at 200°C for 12–14 min, turning halfway and brushing with 1 tbsp more sweet chilli sauce for the last 3 min, until sticky and 75°C inside.","Meanwhile cook the noodles in a pot of boiling water as the pack says (usually 3–4 min), then drain and rinse under cold water.","Whisk the rest of the sweet chilli sauce with the fish sauce, the juice of both limes and 1 tbsp water.","Toss the noodles with the carrot, cucumber, herbs and most of the dressing.","Slice the chicken, lay it on the noodles, drizzle with the last of the dressing and scatter with peanuts."]'::jsonb, array['asian', 'salad', 'high protein']::text[], 'asian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('0cabb57a-3d4c-5c88-9932-e0c5a59cac95'::uuid, 'Chicken thighs with salsa verde, new potatoes and asparagus', 2, null::int, 40::int, 15::int, 25::int, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer 15–18 min until tender.","Season the chicken and cook it in 1 tbsp oil in a frying pan over medium-high heat, 6–7 min a side, until well browned and 75°C inside; rest 3 min.","Meanwhile mix the parsley, basil, capers, anchovies, garlic, mustard and vinegar, then stir in the 3 tbsp olive oil and season with pepper.","Add the asparagus to the potatoes for their last 3 min, then drain.","Toss the potatoes and asparagus with a spoonful of the salsa verde.","Slice the chicken and serve it with the vegetables and the rest of the salsa verde spooned over."]'::jsonb, array['italian', 'high protein']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ee06f3e4-ef46-5b0a-b781-30f1a1934e5c'::uuid, 'Turkey steaks with chimichurri, air-fryer wedges and tomato salad', 2, null::int, 37::int, 15::int, 22::int, '["Toss the wedges with 1 tbsp olive oil, the paprika and salt, and air-fry at 200°C for 20–22 min, shaking twice, until crisp and golden.","For the chimichurri, mix the parsley, garlic, oregano, chilli flakes and vinegar with a pinch of salt, then stir in the 3 tbsp olive oil; leave it to stand.","Toss the tomatoes and red onion with a pinch of salt and a spoonful of the chimichurri.","When the wedges have 6 min left, season the turkey and cook it in the vegetable oil in a hot frying pan for 2–3 min a side until golden and just cooked through (74°C).","Rest the turkey 2 min, then slice it.","Serve the turkey with the wedges and tomato salad, with the chimichurri spooned over."]'::jsonb, array['american', 'high protein', 'grill']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('6964efee-3927-5498-af12-87b83d2534ae'::uuid, 'Air-fryer turkey shawarma flatbreads with tahini sauce', 2, null::int, 47::int, 15::int, 12::int, '["Mix the spices, 1 garlic clove, half the lemon juice, the olive oil and a good pinch of salt, and toss the turkey in it; leave 20 min (or up to a day in the fridge).","Whisk the tahini, yogurt, the rest of the garlic and a squeeze of lemon with 1–2 tbsp water and a pinch of salt.","Toss the cabbage with the rest of the lemon juice and a pinch of salt.","Spread the turkey in the air-fryer basket and cook at 200°C for 8–10 min, shaking halfway, until charred at the edges and cooked through.","Warm the pitas in a dry frying pan for 30 seconds a side.","Spread the pitas with tahini sauce and fill with cabbage, tomato, turkey, gherkins and parsley."]'::jsonb, array['middle eastern', 'street food', 'wrap', 'high protein']::text[], 'middle eastern', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b91c4fb8-73a7-5b7f-87e3-3b902ea315a9'::uuid, 'Air-fryer turkey tikka with spinach pilau rice', 2, null::int, 53::int, 15::int, 18::int, '["Mix the yogurt, garam masala, paprika, chilli powder, turmeric, half the cumin, the garlic, ginger, the juice of half the lemon, the fenugreek and a good pinch of salt; coat the turkey and leave at least 20 min.","Heat the oil in a pot, soften the onion with the bay leaf and the rest of the cumin for 4 min, then stir in the rice.","Add 300 ml water and a pinch of salt, bring to the boil, cover and cook on low for 12 min.","Meanwhile air-fry the turkey at 200°C for 10–12 min, turning halfway, until charred at the edges and 74°C inside.","Lay the spinach on top of the rice, cover again and leave off the heat for 5 min, then fold it through.","Serve the turkey on the rice with coriander and the rest of the lemon in wedges."]'::jsonb, array['indian', 'curry', 'high protein', 'spicy']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('71449b68-635a-5e6a-9e94-d662693b30d1'::uuid, 'Turkey escalopes with honey mustard leeks and potatoes', 2, null::int, 35::int, 10::int, 25::int, '["Boil the potatoes in salted water for 15–18 min until tender, then drain.","Season the escalopes and dust them with the flour.","Heat the oil in a large frying pan over medium-high heat and cook the turkey 3 min a side until golden and just cooked through; set aside on a plate.","Lower the heat, add the butter, leeks, thyme and a pinch of salt and cook 6–8 min until soft.","Stir in the stock, both mustards and the honey and bubble for 2 min, then stir in the crème fraîche.","Return the turkey and its juices to the pan for 1–2 min to heat through, and serve with the potatoes and parsley."]'::jsonb, array['french', 'high protein', 'comfort']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('91ff547e-b20b-5179-815e-98b0e7f66a74'::uuid, 'Air-fryer turkey souvlaki with bulgur, tomato salad and tzatziki', 2, null::int, 50::int, 20::int, 15::int, '["Toss the turkey with the olive oil, the lemon zest and half the juice, the oregano, 1 garlic clove, salt and pepper; leave 15 min and thread onto skewers if you like.","Bring the bulgur and stock to the boil in a pot, cover and simmer gently for 10–12 min, then rest off the heat.","For the tzatziki, coarsely grate half the cucumber, squeeze out the liquid and mix it with the yogurt, the rest of the garlic, the dill and a pinch of salt.","Air-fry the turkey at 200°C for 10–12 min, turning halfway, until golden at the edges and 74°C inside.","Dice the rest of the cucumber and toss it with the tomatoes, red onion, feta and the rest of the lemon juice.","Fluff the bulgur and serve it with the turkey, the salad and the tzatziki."]'::jsonb, array['greek', 'mediterranean', 'high protein', 'healthy']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('324e881a-69b4-581b-90e6-1056bc56fe28'::uuid, 'Steak with romesco, air-fryer potatoes and broccoli', 2, null::int, 50::int, 15::int, 25::int, '["Toss the potatoes with 1 tbsp olive oil, 1 tsp smoked paprika and salt, and air-fry at 200°C for 20–22 min, shaking twice, until crisp.","Blend the roasted peppers, almonds, garlic, tomato paste, vinegar, the rest of the paprika and the 2 tbsp olive oil to a thick, slightly rough sauce; season with salt.","Take the steaks out of the fridge 10 min before cooking, pat dry and season well.","Boil the broccoli in a pot of salted water for 3–4 min until just tender, then drain.","Sear the steaks in the vegetable oil in a very hot frying pan for 2–3 min a side for medium-rare, then rest them 5 min.","Slice the steaks and serve with the potatoes, broccoli and a generous spoonful of romesco."]'::jsonb, array['spanish', 'high protein', 'generous']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":["blender","air fryer"]}'::jsonb, 'Claude', null),
  ('ab56082b-eb3f-5fe6-9fb7-ef4cf68508ad'::uuid, 'Air-fryer teriyaki beef meatballs with rice and green beans', 2, null::int, 33::int, 15::int, 18::int, '["Rinse the rice and put it in a pot with 300 ml water; bring to the boil, cover and simmer on low for 12 min.","Mix the beef, panko, egg, half the spring onion, the garlic, the ginger and a pinch of salt, and roll into 12 meatballs.","Air-fry the meatballs at 200°C for 10–12 min, shaking halfway, until browned and cooked through.","Lay the green beans on top of the rice for its last 6 min, cover again, then leave everything to rest 5 min off the heat.","For the teriyaki, bring the soy sauce, mirin, honey and 3 tbsp water to a simmer in a small pan, stir in the cornstarch mixed with 1 tbsp cold water and bubble 1 min until glossy.","Toss the meatballs in the sauce and serve on the rice with the beans, sesame seeds and the rest of the spring onion."]'::jsonb, array['japanese', 'asian', 'kid-friendly']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('68a03d91-944b-5da3-954a-1d168df79923'::uuid, 'Harissa beef with roasted squash and couscous', 2, null::int, 40::int, 15::int, 25::int, '["Heat the oven to 220°C. Toss the squash with the 1 tbsp oil, half the cumin and salt on a tray and roast for 25 min, turning once, until soft and caramelised.","Heat the 1 tsp oil in a frying pan and soften the onion for 5 min.","Add the beef and garlic and cook over high heat for 5–6 min, breaking it up, until browned.","Stir in the harissa, tomato paste, the rest of the cumin and 100 ml water and simmer 5 min until saucy; season with salt.","Meanwhile pour the boiling stock over the couscous in a bowl, cover and leave 5 min, then fluff with a fork.","Serve the couscous topped with the beef and squash, a spoonful of yogurt and the mint."]'::jsonb, array['north african', 'spicy', 'high protein']::text[], 'north african', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('eb23031d-172b-5243-816a-c74788837fc3'::uuid, 'Honey gochujang beef noodles with spinach', 2, null::int, 25::int, 10::int, 15::int, '["Toss the beef with the cornstarch and 1 tsp soy sauce.","Whisk the gochujang, honey, 1 tbsp soy sauce, rice vinegar, garlic and sesame oil with 2 tbsp water.","Cook the noodles in a pot of boiling water as the pack says (usually 4 min), then drain.","Heat the oil in a wok over high heat and stir-fry the beef for 2 min until browned; lift it out.","Stir-fry the onion and spring onion for 2 min, then add the spinach and stir 1 min until it just wilts.","Return the beef with the noodles and sauce and toss for 1 min until sticky; serve with sesame seeds."]'::jsonb, array['korean', 'asian', 'stir-fry', 'spicy', 'quick']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c6ba679c-0cf6-522d-a8e9-237a8b75c15d'::uuid, 'Black pepper beef udon with cabbage', 2, null::int, 22::int, 10::int, 12::int, '["Toss the beef with the cornstarch and 1 tsp soy sauce; mix the 2 tbsp soy sauce, oyster sauce, sugar, pepper and 4 tbsp water for the sauce.","Put the udon in a bowl, cover with boiling water from the kettle for 1 min to loosen, then drain.","Heat the oil in a wok over high heat and stir-fry the beef for 2 min until browned; lift it out.","Stir-fry the onion, garlic and cabbage for 3–4 min until the cabbage is wilted but still crunchy.","Add the udon, the beef and the sauce and toss for 2 min until the noodles are hot and coated in the peppery sauce.","Serve straight away with spring onion."]'::jsonb, array['asian', 'chinese', 'stir-fry', 'quick']::text[], 'asian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('be62c0b2-60d2-547b-84c7-e6d0a13b3c07'::uuid, 'Air-fryer honey mustard pork chops with potatoes and Brussels sprouts', 2, null::int, 32::int, 10::int, 22::int, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer 15 min.","Mix both mustards, the honey, olive oil and garlic; season the chops and brush them with half of it.","Air-fry the chops at 200°C for 10–12 min, turning halfway, until 63°C in the centre; rest them 5 min.","Add the sprouts to the potatoes for their last 6 min, then drain and toss with the butter, salt and pepper.","Bring the rest of the honey mustard and the stock to the boil in a small pan and bubble 1–2 min until slightly thickened.","Serve the chops with the potatoes and sprouts, with the sauce poured over."]'::jsonb, array['british', 'high protein', 'comfort']::text[], 'british', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('05a8e01f-949a-5a2e-bf71-1b877f338bc1'::uuid, 'Air-fryer jerk pork tenderloin with rice and peas and slaw', 2, null::int, 50::int, 15::int, 20::int, '["Rub the pork with the jerk seasoning, the oil and the juice of half a lime; leave 15 min (or up to a day in the fridge).","Put the rice, coconut milk, 150 ml water, beans, half the spring onion, the garlic, thyme, allspice and a pinch of salt in a pot; bring to the boil, cover and simmer on low for 15 min, then rest 5 min.","Cut the tenderloin into two shorter pieces and air-fry at 200°C for 16–18 min, turning halfway, until 63°C in the centre.","Rest the pork 5 min while you toss the cabbage and carrot with the juice of 1 lime and a pinch of salt.","Remove the thyme from the rice and fluff it with a fork.","Slice the pork and serve with the rice and peas, the slaw, the rest of the spring onion and lime wedges."]'::jsonb, array['caribbean', 'spicy', 'high protein', 'generous']::text[], 'caribbean', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b0dcc451-b61c-5159-81e5-e140eb635520'::uuid, 'Pork and green bean stir-fry with chilli-garlic sauce and rice', 2, null::int, 25::int, 10::int, 15::int, '["Cook the rice in a pot with 300 ml water: bring to the boil, cover and simmer on low for 12 min, then rest 5 min.","Mix the sriracha, soy sauce, oyster sauce, sugar, rice vinegar and sesame oil with 2 tbsp water.","Heat the oil in a wok over high heat and stir-fry the green beans for 4–5 min until blistered and just tender; push them to the side.","Add the pork and cook 4–5 min, breaking it up, until browned and a little crisp.","Add the garlic, ginger and chilli and stir-fry 1 min until fragrant.","Pour in the sauce and toss 1 min until it coats everything; serve over the rice with spring onion."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'spicy', 'quick']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a043608c-b12a-5954-9def-cfb521936032'::uuid, 'Air-fryer pork satay with rice and quick cucumber pickle', 2, null::int, 55::int, 20::int, 15::int, '["Mix the soy sauce, coriander, turmeric, sugar, oil and garlic, toss the pork in it and leave 20 min; thread onto skewers that fit your air fryer.","Cook the rice in a pot with 300 ml water: bring to the boil, cover and simmer on low for 12 min, then rest 5 min.","Toss the cucumber and red onion with the rice vinegar, the pickle sugar and a pinch of salt.","Air-fry the skewers at 200°C for 8–10 min, turning once, until charred at the edges and cooked through.","Meanwhile warm the peanut butter, coconut milk, soy sauce, honey and sriracha in a small pan, stirring, for 2–3 min until smooth and thick; add lime juice to taste.","Serve the skewers on the rice with the satay sauce and the cucumber pickle."]'::jsonb, array['indonesian', 'asian', 'high protein', 'street food']::text[], 'indonesian', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8ff6285f-bed7-538b-b68f-bc3d0973f4a8'::uuid, 'Pork medallions with salsa verde and courgette couscous', 2, null::int, 30::int, 15::int, 15::int, '["For the salsa verde, mix the parsley, basil, mint, capers, garlic, mustard and vinegar, then stir in the 3 tbsp olive oil and season with pepper.","Heat half the oil in a large frying pan over high heat and fry the courgette for 5–6 min until golden; season and tip into a bowl.","Add the couscous and the boiling stock to the bowl, cover and leave 5 min.","Flatten the medallions slightly, season them and fry in the rest of the oil in the same pan for 3 min a side until golden and just cooked (63°C).","Fluff the couscous with the lemon zest and juice and a spoonful of the salsa verde.","Serve the pork on the couscous with the rest of the salsa verde spooned over."]'::jsonb, array['mediterranean', 'italian', 'high protein']::text[], 'mediterranean', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4afb5fe7-2ef2-452e-86a5-81da6eebe426'::uuid, 'Air-fryer teriyaki salmon with rice and broccoli', 2, null::int, 45::int, 10::int, 20::int, '["Mix the soy sauce, mirin, honey, garlic and ginger. Pour a third over the salmon in a dish and leave it 15 min while you start the rice.","Rinse the rice and simmer it covered in 225 ml water for 12 min on low heat.","Scatter the broccoli over the rice, put the lid back on and steam 5 min more, then rest off the heat 5 min.","Heat the air fryer to 200°C. Lay the salmon skin-side down in the basket and air-fry 8-9 min, until it flakes but is still just pink in the very centre.","Meanwhile, simmer the rest of the sauce in a small pan with the cornstarch mixed into 2 tbsp water, 1-2 min, until glossy and thick enough to coat a spoon.","Toss the broccoli with the sesame oil and a pinch of salt.","Serve the salmon on the rice with the broccoli, spoon the teriyaki over and finish with sesame seeds and spring onion."]'::jsonb, array['japanese', 'asian', 'healthy', 'high protein', 'bowl']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('38b6fe91-83fe-46ac-8292-00b83183c374'::uuid, 'Pesto salmon pasta with peas and spinach', 2, null::int, 25::int, 5::int, 20::int, '["Bring a large pot of salted water to the boil and cook the pasta for the time on the packet.","Meanwhile, season the salmon and fry it in the oil in a non-stick pan over medium-high heat, 4 min on the first side and 2-3 min on the second, until just cooked. Lift it out and break it into large flakes.","Add the peas to the pasta for its last 2 min of cooking.","Scoop out a mug of the cooking water, then drain the pasta and peas and tip them into the salmon pan off the heat.","Stir in the spinach, the pesto, the lemon zest and juice and 3-4 tbsp of the cooking water, tossing until the spinach wilts and the sauce turns glossy; add a little more water if it is thick.","Fold the salmon flakes through gently, season with pepper and serve with the parmesan."]'::jsonb, array['italian', 'healthy', 'high protein', 'quick']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a5a62f16-c919-45cc-a99b-d43250a82878'::uuid, 'Air-fryer honey mustard salmon with new potatoes and leeks', 2, null::int, 35::int, 10::int, 25::int, '["Cover the potatoes with cold salted water in a pot, bring to the boil and simmer 15-18 min, until a knife slides in easily. Drain.","Meanwhile, melt the butter in a frying pan, add the leeks with a pinch of salt and 2 tbsp water and cook gently 10-12 min, stirring now and then, until soft and sweet.","Mix both mustards with the honey, the oil and a pinch of salt and pepper.","Heat the air fryer to 200°C. Brush the glaze thickly over the salmon and air-fry it skin-side down for 8-9 min, until the top is caramelised and the fish flakes.","Squeeze the lemon over the leeks, then fold in the potatoes and crush them lightly with a fork.","Serve the salmon on the potatoes and leeks, scattered with parsley."]'::jsonb, array['british', 'healthy', 'high protein']::text[], 'british', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a4e50e5b-ed5a-49de-84e0-dca7c097cc76'::uuid, 'Salmon with peanut-lime noodles and crunchy veg', 2, null::int, 25::int, 15::int, 10::int, '["Soak or boil the rice noodles as the packet says, then drain and rinse under cold water so they don''t stick.","Whisk the peanut butter with the soy sauce, lime juice, honey, garlic, ginger, sriracha and 3-4 tbsp warm water into a pourable sauce.","Season the salmon with salt and fry it in the oil in a non-stick pan over medium-high heat, 3-4 min per side, until golden and just cooked through.","Toss the noodles with the carrot, cucumber and most of the sauce.","Divide the noodles between bowls, break the salmon over the top in large flakes and spoon over the rest of the sauce.","Finish with the peanuts and coriander."]'::jsonb, array['asian', 'thai', 'healthy', 'high protein', 'quick', 'bowl']::text[], 'asian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('299a87a7-23bf-411f-87b5-7eaaa7301c7c'::uuid, 'Air-fryer salmon pittas with tzatziki', 2, null::int, 25::int, 15::int, 10::int, '["Toss the salmon with the oil, oregano, paprika, lemon zest, salt and pepper.","For the tzatziki, mix the yogurt with the cucumber, garlic, dill, a squeeze of lemon and a pinch of salt.","Heat the air fryer to 200°C. Spread the salmon cubes in one layer in the basket and air-fry 6-7 min, until lightly charred at the edges and just cooked.","Meanwhile, warm the pittas in a dry frying pan, 1 min per side.","Rinse the red onion under cold water and toss with a squeeze of lemon.","Spread the pittas with tzatziki, fill with lettuce, tomato, onion and the salmon, and add a last spoonful of tzatziki."]'::jsonb, array['greek', 'mediterranean', 'healthy', 'high protein', 'quick', 'sandwich']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8e9b0f20-5586-444c-8b0a-15a882664811'::uuid, 'Cod with romesco, potatoes and green beans', 2, null::int, 35::int, 15::int, 20::int, '["Put the potatoes in a pot of cold salted water, bring to the boil and simmer 15 min; add the green beans for the last 5 min. Drain.","Meanwhile, blend the peppers, almonds, garlic, paprika, vinegar, 1 tbsp of the oil and a pinch of salt into a thick, slightly coarse romesco.","Pat the cod dry, season it and dust it lightly with the flour.","Heat the rest of the oil in a non-stick pan over medium-high heat and fry the cod 4 min without moving it, until golden underneath; turn and cook 2-3 min more, until it flakes.","Toss the potatoes and beans with a pinch of salt and any oil left in the pan.","Spread a thick spoonful of romesco on each plate, set the cod on top and serve with the potatoes and beans and the parsley."]'::jsonb, array['spanish', 'mediterranean', 'healthy', 'high protein']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('359db6c0-fa7c-4415-808c-1678f959a128'::uuid, 'Air-fryer harissa hake with couscous and courgettes', 2, null::int, 22::int, 10::int, 12::int, '["Mix the harissa with 1 tsp of the oil and the lemon zest and spread it over the hake.","Heat the air fryer to 200°C and air-fry the hake for 9-10 min, until it is opaque and flakes easily.","Meanwhile, pour the hot stock over the couscous in a bowl, cover and leave 5 min.","Fry the courgettes in the rest of the oil in a frying pan over high heat with the cumin and a pinch of salt, 5-6 min, until browned in patches but still firm.","Fluff the couscous with a fork and stir in the courgettes, half the lemon juice, the mint and the parsley.","Season the yogurt with a little lemon juice and salt and serve it with the hake on the couscous."]'::jsonb, array['north african', 'moroccan', 'healthy', 'high protein', 'quick']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a8d2ed16-8c58-4da3-bbbe-2a4bbc59e8cb'::uuid, 'Air-fryer miso-ginger cod with rice and pak choi', 2, null::int, 50::int, 10::int, 20::int, '["Mix the miso, mirin, honey, soy sauce and two thirds of the ginger. Coat the cod with it and leave it in the fridge for 20-30 min.","Rinse the rice and simmer it covered in 240 ml water for 12 min on low heat, then rest it 5 min off the heat.","Heat the air fryer to 200°C. Wipe off any thick lumps of marinade, lay the cod on a piece of baking paper in the basket and air-fry 9-10 min, until the top is caramelised and the fish flakes.","Meanwhile, heat the vegetable oil in a frying pan, add the garlic and the rest of the ginger, then the pak choi cut-side down. Cook 2 min, add 2 tbsp water, cover and steam 2 min until the stems are just tender.","Drizzle the pak choi with the sesame oil.","Serve the cod on the rice with the pak choi, scattered with sesame seeds and spring onion."]'::jsonb, array['japanese', 'asian', 'healthy', 'high protein', 'bowl']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('75d1230d-4daf-4a3c-89e3-592b242ea24b'::uuid, 'Air-fryer Cajun cod tacos with lime slaw', 2, null::int, 25::int, 15::int, 10::int, '["Toss the cod gently with the oil and the Cajun seasoning.","For the slaw, mix the mayonnaise, yogurt, lime zest, half the lime juice and a pinch of salt, then toss with the cabbage, carrot and coriander.","Heat the air fryer to 200°C. Lay the cod in one layer in the basket and air-fry 8-9 min without turning, until it flakes.","Warm the tortillas in a dry frying pan, 30 seconds per side.","Fill the tortillas with slaw and cod, squeeze over the rest of the lime and add the chilli."]'::jsonb, array['american', 'mexican', 'healthy', 'high protein', 'quick']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8d8e85d0-95ef-45dc-b599-bcb0846aed0a'::uuid, 'Hake with salsa verde, new potatoes and asparagus', 2, null::int, 35::int, 15::int, 20::int, '["Cover the potatoes with cold salted water in a pot, bring to the boil and simmer 15 min; add the asparagus for the last 3 min. Drain.","For the salsa verde, mix the parsley, mint, capers, anchovies, mustard, vinegar and 2 tbsp of the oil with a little pepper; loosen with a spoon of water if needed.","Pat the hake dry and season it. Heat the rest of the oil in a non-stick pan over medium-high heat and fry the hake skin-side down for 4 min, pressing it flat for the first few seconds, until the skin is crisp.","Turn the fish and cook 1-2 min more, until it just flakes; squeeze over the lemon.","Toss the potatoes and asparagus with a spoonful of the salsa verde.","Serve the hake on the potatoes and asparagus with the rest of the salsa verde spooned over."]'::jsonb, array['italian', 'mediterranean', 'healthy', 'high protein']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c3065a27-e6d3-4d46-8179-c8d9990ea1b8'::uuid, 'Air-fryer honey gochujang prawns with rice and cucumber', 2, null::int, 25::int, 10::int, 15::int, '["Rinse the rice and simmer it covered in 225 ml water for 12 min on low heat; add the edamame on top for the last 4 min, then rest 5 min off the heat.","Toss the cucumber with the rice vinegar, sugar and a pinch of salt and leave it to pickle lightly.","Mix the gochujang, honey, soy sauce, garlic and sesame oil in a small pan.","Heat the air fryer to 200°C. Pat the prawns dry, toss them with the vegetable oil and a pinch of salt and air-fry 6-7 min, shaking halfway, until pink and curled.","Warm the sauce for 1 min until it bubbles, then toss the hot prawns through it.","Serve the prawns over the rice and edamame with the cucumber, scattered with sesame seeds and spring onion."]'::jsonb, array['korean', 'asian', 'spicy', 'high protein', 'bowl', 'quick']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a41c4225-ba5e-410f-83b8-44767b52d719'::uuid, 'Black pepper prawn noodles with mangetout', 2, null::int, 20::int, 10::int, 10::int, '["Cook the noodles in boiling water as the packet says, drain and rinse briefly so they don''t clump.","Mix the oyster sauce, soy sauce, sugar, black pepper and cornstarch with 4 tbsp water.","Heat the oil in a wok over high heat and stir-fry the prawns 2 min, until pink on both sides; lift them out.","Add the butter, garlic, ginger and the white part of the spring onions and stir 30 seconds until fragrant.","Add the mangetout and pepper and stir-fry 2 min, until bright but still crisp.","Return the prawns with the noodles and the sauce and toss 1-2 min, until everything is glossy and the prawns are cooked through.","Stir in the green spring onion and serve straight away."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'high protein', 'quick']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('e734e3d4-55e6-4745-a4e1-23a64efe8e9e'::uuid, 'Satay prawn noodles with pak choi', 2, null::int, 22::int, 10::int, 12::int, '["Soak or boil the rice noodles as the packet says, then drain.","Whisk the peanut butter, coconut milk, soy sauce, lime juice, honey and curry powder into a smooth sauce.","Heat the oil in a wok over high heat, add the garlic, ginger, carrot and pak choi stems and stir-fry 2 min.","Add the prawns and stir-fry 2-3 min, until they turn pink.","Pour in the sauce and the pak choi leaves and bubble 1 min, until the leaves wilt; loosen with a splash of water if thick.","Toss in the noodles until coated and hot, then serve with the chilli and coriander."]'::jsonb, array['malaysian', 'asian', 'stir-fry', 'high protein', 'quick']::text[], 'malaysian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b5b1cd3f-52f7-47b0-8e3c-b0f1cf3c75cb'::uuid, 'Air-fryer prawn tikka wraps with mint yogurt', 2, null::int, 40::int, 15::int, 8::int, '["Mix 3 tbsp of the yogurt with the garam masala, paprika, cumin, turmeric, chilli powder, garlic, ginger, half the lemon juice, the oil and a pinch of salt. Coat the prawns and leave them 15-20 min.","Stir the mint, the cucumber, a squeeze of lemon and a pinch of salt into the rest of the yogurt.","Toss the red onion with the rest of the lemon juice.","Heat the air fryer to 200°C. Spread the prawns in one layer in the basket and air-fry 6-7 min, turning once, until pink and charred in spots.","Warm the wraps in a dry frying pan, 30 seconds per side.","Fill each wrap with lettuce, prawns, onion and a good spoonful of mint yogurt, then roll up."]'::jsonb, array['indian', 'spicy', 'high protein', 'wrap']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('864233ec-efae-4266-b3c1-855a9a78f606'::uuid, 'Air-fryer chimichurri prawn quinoa bowls', 2, null::int, 30::int, 15::int, 15::int, '["Simmer the quinoa covered in 280 ml salted water for 12-15 min, until the water is absorbed; rest it 5 min, then fluff.","For the chimichurri, mix the parsley, garlic, oregano, chilli flakes, vinegar, 2 tbsp of the oil and a good pinch of salt.","Toss the prawns with 1 tbsp of the chimichurri. Heat the air fryer to 200°C and air-fry them 6-7 min, shaking halfway, until pink and curled.","Meanwhile, fry the pepper and corn in the rest of the oil in a frying pan over high heat, 4-5 min, until charred in spots.","Stir the pepper, corn, tomatoes and lime juice into the quinoa.","Divide between bowls, top with the prawns and spoon over the rest of the chimichurri."]'::jsonb, array['american', 'healthy', 'high protein', 'bowl', 'gluten-free']::text[], 'american', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('ee123b44-5c1b-473b-ac0c-bd5f9c59c493'::uuid, 'Air-fryer sweet chilli tofu with noodles and peppers', 2, null::int, 33::int, 15::int, 18::int, '["Pat the tofu dry, toss it with 1 tsp of the oil and a pinch of salt, then with the cornstarch until coated.","Heat the air fryer to 200°C and air-fry the tofu 15 min, shaking twice, until golden and crisp.","Meanwhile, cook the noodles as the packet says, drain and rinse briefly.","Mix the sweet chilli sauce, soy sauce, lime juice and garlic.","Heat the rest of the oil in a wok over high heat and stir-fry the peppers and white spring onion 3 min, until just tender.","Add the noodles and half the sauce and toss 1 min; toss the hot tofu with the rest of the sauce.","Serve the noodles topped with the tofu, green spring onion, sesame seeds and coriander."]'::jsonb, array['thai', 'asian', 'vegan', 'stir-fry', 'high protein']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b9133b27-97e0-4c11-9752-f03233863717'::uuid, 'Air-fryer tofu katsu curry with rice', 2, null::int, 45::int, 20::int, 25::int, '["Rinse the rice and simmer it covered in 210 ml water for 12 min on low heat, then rest it 5 min off the heat.","For the curry sauce, soften the onion and carrot in 1 tsp of the oil in a saucepan over medium heat, 6-7 min. Add the garlic, 1 tbsp of the flour and the curry powder and stir 1 min.","Whisk in the stock little by little, then the soy sauce and maple syrup, and simmer 10-12 min, stirring often, until thick enough to coat a spoon. Blend smooth if you like.","Meanwhile, whisk the rest of the flour with about 60 ml water and a pinch of salt into a thick batter. Dip each tofu slab in it, then press into the panko on both sides.","Heat the air fryer to 200°C. Brush or spray the tofu with the rest of the oil and air-fry 12-14 min, turning once, until deep golden and crunchy.","Slice the katsu and serve it on the rice with the shredded cabbage, the curry sauce poured alongside."]'::jsonb, array['japanese', 'asian', 'vegan', 'curry', 'comfort']::text[], 'japanese', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('097a3158-2f72-4ef2-9407-d7bc62b5421b'::uuid, 'Black pepper tofu with rice and green beans', 2, null::int, 40::int, 15::int, 25::int, '["Rinse the rice and simmer it covered in 210 ml water for 12 min on low heat, then rest it 5 min off the heat.","Toss the tofu in the cornstarch. Heat the oil in a large non-stick frying pan over medium-high heat and fry the tofu 8-10 min, turning, until crisp and golden on all sides. Lift it onto kitchen paper.","Pour off all but a film of oil, add the butter, shallots, chilli, garlic and ginger and cook over medium heat 6-8 min, stirring, until soft and glossy.","Add the green beans and 3 tbsp water, cover and cook 3-4 min until just tender.","Stir in the black pepper, soy sauce and sugar, then return the tofu and toss 1 min to coat and warm through.","Stir in the spring onions and serve with the rice."]'::jsonb, array['asian', 'malaysian', 'vegetarian', 'spicy', 'stir-fry']::text[], 'asian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ee18cbd5-03f1-4c48-b68e-1c26e8c8e29e'::uuid, 'Air-fryer harissa tofu with bulgur and carrots', 2, null::int, 35::int, 15::int, 20::int, '["Bring the stock to the boil in a saucepan, stir in the bulgur, cover and simmer on low heat 12 min, then rest 5 min off the heat.","Toss the tofu with 1 tsp of the oil, a pinch of salt and the cornstarch. Heat the air fryer to 200°C and air-fry 12 min, shaking halfway.","Meanwhile, fry the carrots in 1 tbsp of the oil in a frying pan over medium-high heat with the cumin and a pinch of salt, 10-12 min, stirring, until tender and browned at the edges.","Mix the harissa with the maple syrup, toss the tofu in it and air-fry 2-3 min more, until sticky and charred at the edges.","Fluff the bulgur and stir in the carrots, the lemon juice, the rest of the oil, the parsley and the mint.","Serve the harissa tofu on the bulgur."]'::jsonb, array['north african', 'middle eastern', 'vegan', 'healthy', 'spicy']::text[], 'north african', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('5eed3550-e582-4410-9023-f70fde4cac4f'::uuid, 'Tahini-lemon tofu with roast squash and quinoa', 2, null::int, 43::int, 15::int, 28::int, '["Heat the oven to 220°C. Toss the squash with 2 tsp of the oil, half the cumin and paprika and a pinch of salt, spread it on a large tray and roast 10 min.","Toss the tofu with the rest of the oil and spices and a pinch of salt, add it to the tray and roast 15-18 min more, turning once, until the squash is soft and browned and the tofu golden.","Meanwhile, simmer the quinoa covered in 280 ml salted water for 12-15 min, until the water is absorbed; rest it 5 min.","Whisk the tahini with the lemon juice, garlic, maple syrup, a pinch of salt and 2-3 tbsp water into a pourable sauce.","Stir the spinach into the hot quinoa so it wilts, then the parsley.","Serve the quinoa topped with the squash and tofu and drizzled with the tahini-lemon sauce."]'::jsonb, array['middle eastern', 'vegan', 'healthy', 'oven', 'gluten-free']::text[], 'middle eastern', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, 'Claude', null),
  ('cdbeba47-7c9a-4b38-b153-1ef98c28b768'::uuid, 'Air-fryer halloumi with chickpea couscous and tahini-lemon', 2, null::int, 25::int, 10::int, 15::int, '["Heat the air fryer to 200°C. Toss the chickpeas and pepper with 2 tsp of the oil, the cumin, paprika and a pinch of salt and air-fry 8 min, shaking halfway.","Lay the halloumi slices on top and air-fry 6-7 min more, until the halloumi is golden at the edges and the chickpeas are crisp.","Meanwhile, bring the stock to the boil in a saucepan, stir in the couscous and the lemon zest, cover off the heat and leave 5 min.","Whisk the tahini with half the lemon juice, the garlic, a pinch of salt and 2-3 tbsp water into a pourable sauce.","Fluff the couscous with a fork and stir in the cucumber, herbs, the rest of the lemon juice and oil, and the chickpeas and pepper.","Serve the couscous topped with the halloumi and drizzled with the tahini-lemon sauce."]'::jsonb, array['mediterranean', 'middle eastern', 'vegetarian', 'healthy', 'high protein', 'quick']::text[], 'mediterranean', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('22ac2fdb-6c42-4e22-8be1-8969ffeeae90'::uuid, 'Air-fryer paneer kathi rolls', 2, null::int, 45::int, 15::int, 12::int, '["Mix 3 tbsp of the yogurt with the garam masala, paprika, turmeric, chilli powder, garlic, ginger, the oil, a squeeze of lemon and a pinch of salt. Toss the paneer in it and leave 15-20 min.","Blend or very finely chop the coriander, mint and green chilli and stir into the rest of the yogurt with a squeeze of lemon and a pinch of salt.","Cut half the onion into wedges and slice the other half thinly; toss the thin slices with a little lemon juice and salt.","Heat the air fryer to 200°C. Add the paneer, pepper and onion wedges in one layer and air-fry 10-12 min, shaking halfway, until the paneer is charred at the edges.","Warm the wraps in a dry frying pan, 30 seconds per side.","Spread each wrap with the green chutney yogurt, add the paneer and vegetables and the sliced onion, roll up tightly and serve."]'::jsonb, array['indian', 'vegetarian', 'street food', 'wrap', 'high protein']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('27449cd5-b106-4b6d-88e8-622045c10586'::uuid, 'Gochujang egg fried rice with edamame', 2, null::int, 35::int, 10::int, 25::int, '["Rinse the rice and simmer it covered in 225 ml water for 12 min, then spread it on a large plate to steam off and cool for 5-10 min.","Mix the gochujang, honey, soy sauce and sesame oil.","Heat 1 tsp of the oil in a wok or large frying pan over medium heat, pour in 4 beaten eggs with a pinch of salt and scramble into large soft curds, about 1 min. Tip them out.","Add the rest of the oil and turn the heat to high. Stir-fry the carrot, edamame, garlic and white spring onion 2-3 min.","Add the rice and stir-fry 3-4 min, pressing it against the pan, until hot and lightly toasted. Stir in the sauce until every grain is coated, then fold the scrambled eggs back in.","Meanwhile, fry the remaining 2 eggs in a little oil in a frying pan until the whites are set and the yolks still runny.","Serve the fried rice topped with a fried egg, the green spring onion and sesame seeds."]'::jsonb, array['korean', 'asian', 'vegetarian', 'high protein', 'spicy', 'budget']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8c6694d6-a78f-4a4e-b68a-0aa18ebd4294'::uuid, 'Black bean and egg burritos with tomato salsa', 2, null::int, 22::int, 10::int, 12::int, '["For the salsa, mix the tomatoes, red onion, half the coriander, the chilli, half the lime juice and a pinch of salt.","Warm the tortillas one at a time in a dry frying pan, 30 seconds per side, and keep them wrapped in a clean tea towel.","Heat 1 tsp of the oil in the same pan over medium heat and soften the onion 4 min. Add the garlic, cumin and paprika for 30 seconds, then the beans and 3 tbsp water.","Cook the beans 3 min, mashing about half of them with a fork, until thick; season with salt and the rest of the lime juice and spoon them onto the tortillas.","Wipe the pan, add the rest of the oil and scramble the beaten eggs with salt and pepper over low heat, 2 min, until just set and soft.","Top the beans with the eggs, cheddar, salsa and the rest of the coriander, fold in the sides and roll up tightly."]'::jsonb, array['mexican', 'vegetarian', 'high protein', 'wrap', 'quick', 'budget']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6ccd0cfe-4e21-4d8d-9693-dff751a4886b'::uuid, 'Puy lentils with salsa verde, soft eggs and new potatoes', 2, null::int, 40::int, 15::int, 25::int, '["Cover the lentils with plenty of cold water in a pot, add the bay leaf and simmer 20-25 min, until tender but still holding their shape. Salt them only at the end, then drain.","Meanwhile, put the potatoes in a second pot of cold salted water, bring to the boil and simmer 15-18 min, until tender.","Lower the eggs into the potato water for the last 6.5 min, then lift them into cold water, peel and halve.","For the salsa verde, mix the parsley, basil, capers, garlic, mustard, 1 tbsp of the vinegar and 2 tbsp of the oil with a pinch of salt and pepper.","Toss the warm lentils with the shallot, the rest of the vinegar and oil and half the salsa verde. Drain the potatoes.","Serve the lentils with the potatoes and rocket, topped with the soft eggs and the rest of the salsa verde."]'::jsonb, array['french', 'vegetarian', 'healthy', 'high protein']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('63e8ac66-626b-56dc-ad74-a1f52919bee4'::uuid, 'Air-fryer chicken yakitori rice bowls with green beans', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice, put it in a pot with 210 ml water, bring to the boil, cover and cook on low heat for 12 min, then rest off the heat with the lid on.","Boil the green beans in a small pan of salted water for 4 min, drain and keep warm.","In the same small pan, simmer the soy sauce, mirin, sake and sugar for 3–4 min until syrupy; this is the tare.","Thread the chicken and spring onion alternately onto short skewers that fit the basket and brush with the oil.","Air-fry at 190°C for 6 min, brush with tare, turn, brush again and cook 5–6 min more, until glossy and 75°C in the centre.","Spoon the rice into bowls, add the beans and skewers, drizzle over the rest of the tare and finish with sesame seeds and chilli."]'::jsonb, array['japanese', 'asian', 'bowl', 'healthy', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('be8267a1-d52e-53ab-85e6-83aef1458b18'::uuid, 'Chicken and broccoli noodles in oyster sauce', 2, null::int, 25::int, 10::int, 15::int, '["Toss the chicken with the soy sauce and 1 tsp of the cornstarch. Whisk the oyster sauce, Shaoxing wine, sugar, stock and the rest of the cornstarch in a jug.","Cook the noodles in a pot of boiling water as the pack says, adding the broccoli and carrot for the last 2 min; drain.","Heat the vegetable oil in a wok over high heat and stir-fry the chicken for 3–4 min until golden and cooked through.","Add the garlic and ginger and stir-fry 30 seconds until fragrant.","Pour in the sauce and let it bubble for 1 min until it thickens and turns glossy.","Toss in the noodles and vegetables for 1–2 min until coated and hot, then add the sesame oil and spring onion and serve."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'healthy', 'high protein', 'quick']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('43a904db-41c6-56c6-9efe-ee6b7ae30125'::uuid, 'Air-fryer chermoula chicken with tomato and cucumber couscous', 2, null::int, 28::int, 12::int, 16::int, '["Make the chermoula: mix the parsley, coriander, garlic, cumin, paprika, chilli flakes, lemon zest, half the lemon juice, 1 tbsp olive oil and a pinch of salt.","Halve the chicken fillets horizontally into thinner steaks and rub them with two-thirds of the chermoula.","Air-fry at 200°C for 12–15 min, turning halfway, until charred at the edges and 75°C in the thickest part.","Meanwhile pour the hot stock over the couscous in a pot off the heat, cover and leave 5 min.","Fluff the couscous with a fork and stir in the tomato, cucumber, red onion, the rest of the lemon juice and oil.","Stir the remaining chermoula into the yogurt.","Slice the chicken and serve it on the couscous with the chermoula yogurt."]'::jsonb, array['north african', 'moroccan', 'healthy', 'high protein', 'bowl']::text[], 'north african', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('c7c319b4-d176-59d8-9705-957d1456be40'::uuid, 'Penne arrabbiata with chicken and courgette', 2, null::int, 28::int, 8::int, 20::int, '["Bring a large pot of salted water to the boil for the penne.","Heat the oil in a large frying pan over medium-high heat, season the chicken and brown it for 4–5 min until golden; lift out.","Add the courgette to the pan and cook 3 min, then add the garlic and chilli flakes for 1 min without letting the garlic brown.","Stir in the tomatoes and tomato paste, return the chicken and simmer for 10 min until the sauce thickens.","Meanwhile cook the penne until al dente, about 10–11 min, and keep a cup of the water.","Drain the penne and toss them in the sauce with a splash of the water until glossy; serve with basil and a little parmesan."]'::jsonb, array['italian', 'spicy', 'healthy', 'high protein']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8ab64d4f-2865-591c-a2ca-1d6d643e0ad1'::uuid, 'Air-fryer chipotle chicken tacos with charred corn and cabbage slaw', 2, null::int, 27::int, 12::int, 15::int, '["Mix the chipotle paste, garlic, cumin, oregano, the juice of half a lime, the oil and a pinch of salt; toss the chicken in it.","Air-fry the chicken at 200°C for 10–12 min, shaking halfway, until lightly charred and cooked through.","Meanwhile toss the cabbage and red onion with the juice of 1 lime and a pinch of salt.","Char the corn in a dry frying pan over high heat for 4–5 min, stirring now and then; tip it out.","Warm the tortillas in the same pan for 20–30 seconds a side.","Fill the tortillas with slaw, chicken and corn, add a spoonful of yogurt, coriander and the last lime in wedges."]'::jsonb, array['mexican', 'street food', 'spicy', 'healthy', 'high protein']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('149d32ed-4e91-5b66-b0fe-145e8bd1f1f5'::uuid, 'Air-fryer chicken pinchos morunos with new potatoes and pepper salad', 2, null::int, 30::int, 12::int, 18::int, '["Cook the potatoes in a pot of salted boiling water for 15–18 min until tender; drain.","Meanwhile mix the cumin, smoked paprika, coriander, thyme, garlic, half the lemon juice, 1 tbsp olive oil and a good pinch of salt; toss the chicken in it.","Thread the chicken onto short skewers that fit the basket.","Air-fry at 190°C for 12–14 min, turning halfway, until browned and cooked through.","For the salad, toss the pepper, tomato and red onion with the vinegar, the rest of the oil and a pinch of salt.","Toss the warm potatoes with the parsley and the rest of the lemon juice, and serve with the skewers and salad."]'::jsonb, array['spanish', 'mediterranean', 'grill', 'healthy', 'high protein']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('c18003ce-3b5d-56be-acc1-86393d87785b'::uuid, 'Pad prik khing with chicken, green beans and jasmine rice', 2, null::int, 25::int, 10::int, 15::int, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min, then rest 5 min with the lid on.","Heat the oil in a wok over medium heat and fry the curry paste for 1 min, stirring, until fragrant.","Turn the heat up, add the chicken and stir-fry 3 min until it turns white all over.","Add the green beans and 3 tbsp water and stir-fry 4–5 min until the beans are tender-crisp and the chicken is cooked.","Season with the fish sauce and sugar, toss in the lime leaves and cook 30 seconds more.","Serve over the jasmine rice with sliced chilli if you like more heat."]'::jsonb, array['thai', 'asian', 'stir-fry', 'spicy', 'healthy', 'high protein', 'quick']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('03cda661-245c-51fc-9d5e-8eb63aae54ee'::uuid, 'Air-fryer achari chicken with naan and kachumber', 2, null::int, 29::int, 15::int, 14::int, '["Toast the mustard, fennel and nigella seeds in a dry small pan for 1 min until they pop, then crush them roughly.","Mix the crushed seeds with the cumin, chilli powder, turmeric, garlic, ginger, yogurt, half the lemon juice and a good pinch of salt.","Coat the chicken in the achari yogurt and spread it in one layer in the air-fryer basket.","Air-fry at 200°C for 12–14 min, shaking halfway, until charred at the edges and cooked through.","Meanwhile make the kachumber: toss the cucumber, tomato, red onion, coriander and mint with the rest of the lemon juice and a pinch of salt.","Warm the naan in the air fryer for the last 2 min, then serve with the chicken and the kachumber."]'::jsonb, array['indian', 'spicy', 'healthy', 'high protein']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a14ad196-a3cd-54f6-9528-638660d11e5d'::uuid, 'Air-fryer Korean soy-garlic chicken with rice and spinach namul', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min, then rest off the heat.","Toss the chicken with the cornstarch and a pinch of salt and air-fry at 200°C for 16–18 min, shaking twice, until crisp and cooked through.","Meanwhile wilt the spinach in a frying pan with a splash of water for 1–2 min, drain, squeeze out the water and toss with the sesame oil, a little of the garlic and a pinch of salt.","Wipe the pan and simmer the soy sauce, honey, the rest of the garlic, the ginger, vinegar and 2 tbsp water for 2–3 min until sticky.","Toss the hot chicken in the glaze until coated.","Serve over the rice with the spinach namul, spring onion and sesame seeds."]'::jsonb, array['korean', 'asian', 'bowl', 'healthy', 'high protein']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a11d46fd-8dc9-521a-bcc0-ae7cb3f950f9'::uuid, 'Greek lemon chicken orzo with spinach and cherry tomatoes', 2, null::int, 30::int, 8::int, 22::int, '["Season the chicken with salt, pepper and half the oregano and brown it in the oil in a wide lidded pan over medium-high heat for 5 min.","Add the onion and cook 3 min, then the garlic and the rest of the oregano for 30 seconds.","Stir in the orzo, the stock and the lemon zest and bring to the boil.","Cover and simmer for 10–12 min, stirring now and then, until the orzo is tender and most of the stock is absorbed.","Stir in the cherry tomatoes and spinach and cook 2 min until the spinach wilts.","Add the lemon juice, check the seasoning and serve with feta and dill on top."]'::jsonb, array['greek', 'mediterranean', 'one-pot', 'healthy', 'high protein']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bf976172-3ded-5855-82f6-e6f0db648843'::uuid, 'Chicken in black bean sauce with peppers and noodles', 2, null::int, 27::int, 12::int, 15::int, '["Toss the chicken with the Shaoxing wine, 1 tsp cornstarch and 1 tsp of the soy sauce. Mix the rest of the soy sauce, the sugar, stock and remaining cornstarch.","Cook the noodles in a pot of boiling water as the pack says, drain and rinse briefly.","Heat the oil in a wok over high heat and stir-fry the chicken for 3–4 min until browned; lift out.","Stir-fry the onion and peppers for 2 min, then add the black beans, garlic and ginger for 30 seconds.","Return the chicken, pour in the sauce and toss for 1–2 min until thick and glossy.","Serve over the noodles, with sliced chilli if you like."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'healthy', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d7abf651-5d99-580a-8c8f-3a5ce00d0f20'::uuid, 'Pollo saltado with air-fryer potatoes and rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and cook it covered in 210 ml salted water on low heat for 12 min, then rest with the lid on.","Toss the potato batons with 1 tsp oil and a pinch of salt and air-fry at 200°C for 18–20 min, shaking twice, until golden and crisp.","Season the chicken with the cumin, salt and pepper.","When the potatoes have 8 min left, heat the rest of the oil in a wok over very high heat and sear the chicken for 4–5 min until browned and cooked through.","Add the garlic and aji amarillo paste, then the onion, and toss for 1 min so the onion stays crunchy.","Add the tomato, then pour the soy sauce and vinegar around the hot wok and toss for 30 seconds until it sizzles into a light sauce.","Fold in the potatoes and coriander and serve straight away with the rice."]'::jsonb, array['peruvian', 'stir-fry', 'healthy', 'high protein']::text[], 'peruvian', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8abe1f0a-a0f1-5620-b8e9-123b6e298553'::uuid, 'Gà kho gừng (Vietnamese ginger chicken) with rice and pak choi', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min.","Toss the chicken with 1 tbsp of the fish sauce and plenty of black pepper.","Melt the sugar with 1 tbsp water in a lidded frying pan over medium heat, without stirring, for 3–4 min until it turns a deep amber caramel.","Add the oil, shallot, garlic and ginger and stir 30 seconds, then add the chicken and turn it in the caramel for 2 min.","Pour in the rest of the fish sauce and 100 ml water, cover and simmer 10 min, then uncover and reduce 3 min until the sauce is dark and sticky.","Meanwhile lay the pak choi on the rice for its last 4 min, put the lid back on and let it steam.","Serve the chicken and its sauce with the rice and pak choi, scattered with spring onion."]'::jsonb, array['vietnamese', 'asian', 'healthy', 'high protein']::text[], 'vietnamese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('020a9392-2512-55f1-9700-d31508a57a3e'::uuid, 'Air-fryer mojo chicken with rice and black beans', 2, null::int, 30::int, 10::int, 20::int, '["Whisk the orange and lime juice with the garlic, half the cumin, the oregano, the oil, salt and pepper: this is the mojo.","Toss the chicken in a third of the mojo and air-fry at 200°C for 16–18 min, turning halfway, until browned and 75°C inside.","Meanwhile rinse the rice and cook it covered in 180 ml salted water on low heat for 12 min.","In a second pan, soften the onion and green pepper in 2 tbsp of the mojo for 5 min, then add the black beans, bay leaf, the rest of the cumin and 4 tbsp water and simmer 8 min.","Slice the chicken and spoon the remaining mojo over it.","Serve with the rice and black beans, scattered with coriander."]'::jsonb, array['cuban', 'caribbean', 'healthy', 'high protein']::text[], 'cuban', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('6ade88fa-f405-5314-bbfb-0c109e97ec93'::uuid, 'Turkey keema matar with chapatis', 2, null::int, 30::int, 10::int, 20::int, '["Heat the oil in a large frying pan over medium heat and sizzle the cumin seeds for 30 seconds.","Add the onion and cook 5–6 min until golden, then add the garlic, ginger and green chilli for 1 min.","Add the turkey and cook 5 min over high heat, breaking it up with a spoon, until it loses its pink colour.","Stir in the ground coriander, turmeric, chilli powder and tomato with a pinch of salt and cook 4 min until the tomato breaks down.","Add the peas and 4 tbsp water and simmer 4 min until the peas are tender and the keema is moist but not runny.","Stir in the garam masala and lemon juice.","Warm the chapatis in a dry frying pan for 20 seconds a side and serve with the keema and coriander."]'::jsonb, array['indian', 'curry', 'healthy', 'high protein']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7cda71ea-f66d-5583-9dd7-ec507c77a788'::uuid, 'Turkey dan dan noodles with pak choi', 2, null::int, 25::int, 10::int, 15::int, '["Whisk the tahini, 1.5 tbsp of the soy sauce, black vinegar, chilli oil, Sichuan pepper, sugar and half the garlic in the serving bowls.","Heat the oil in a frying pan over high heat and fry the turkey for 5–6 min, breaking it up, until browned and a little crisp.","Add the rest of the garlic, the ginger, Shaoxing wine, hoisin, five-spice and the remaining soy sauce and cook 1 min until the pan is almost dry.","Cook the noodles in a pot of boiling water as the pack says, adding the pak choi for the last 2 min.","Stir 3 tbsp of the noodle water into the sauce in each bowl, then drain the noodles and pak choi and divide them between the bowls.","Top with the turkey, spring onion and peanuts and mix everything together at the table."]'::jsonb, array['chinese', 'asian', 'spicy', 'healthy', 'high protein', 'quick']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7796bb98-ab0a-5372-8642-dff105dc2ccd'::uuid, 'Air-fryer piri-piri turkey with spicy rice', 2, null::int, 30::int, 10::int, 20::int, '["Mash or blend the chillies, garlic, smoked paprika, oregano, lemon juice, vinegar, olive oil and a good pinch of salt into a loose piri-piri sauce.","Fry the onion and pepper in 1 tbsp of the sauce in a lidded pan for 4 min.","Stir in the rinsed rice and turmeric, pour in the stock, bring to the boil, cover and cook on low heat for 12 min.","Meanwhile brush the turkey steaks with half the remaining sauce.","Air-fry at 200°C for 10–12 min, turning halfway, until lightly charred and 75°C in the centre; rest 3 min.","Scatter the peas and corn over the rice, cover and cook 3 min more, then fluff with a fork.","Slice the turkey and serve on the rice with the rest of the piri-piri sauce."]'::jsonb, array['portuguese', 'spicy', 'healthy', 'high protein']::text[], 'portuguese', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('3bf77e79-a503-567b-86b2-d41c2d351516'::uuid, 'Turkey soboro don with egg and green beans', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min.","Lay the green beans on top of the rice for the last 4 min, put the lid back on and let them steam; then rest off the heat.","Beat the eggs with 1 tsp sugar and a pinch of salt and cook them in a non-stick frying pan over medium-low heat, stirring constantly with chopsticks, for 2 min into fine soft crumbs; tip out.","Put the turkey, ginger, soy sauce, mirin, sake and the rest of the sugar in the same pan, cold, and stir well to break up the meat.","Cook over medium heat for 6–7 min, stirring all the time with chopsticks, until the meat is in fine crumbs and the liquid has nearly gone.","Fill the bowls with rice and arrange the turkey, egg and green beans on top in three sections; add pickled ginger."]'::jsonb, array['japanese', 'asian', 'bowl', 'kid-friendly', 'healthy', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a7902387-e1b1-5e72-8f75-c3b7264fddfc'::uuid, 'Air-fryer turkey escalopes with sauce vierge and crushed potatoes', 2, null::int, 30::int, 12::int, 18::int, '["Boil the potatoes in a pot of salted water for 15–18 min until tender, adding the green beans for the last 5 min.","Meanwhile make the sauce vierge: mix the tomato, shallot, lemon juice, basil, olives, 1.5 tbsp olive oil, salt and pepper and leave it to stand.","Rub the escalopes with 1 tsp olive oil, the herbes de Provence, salt and pepper.","Air-fry at 200°C for 8–10 min, turning halfway, until golden and no longer pink inside.","Drain the potatoes and beans, lightly crush the potatoes with a fork and the rest of the oil, and season.","Serve the turkey on the crushed potatoes with the green beans, and spoon the sauce vierge over."]'::jsonb, array['french', 'mediterranean', 'healthy', 'high protein']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8e59d959-5ac0-5c4a-a475-c526e235adf0'::uuid, 'Air-fryer turkey albóndigas with potatoes in tomato sauce', 2, null::int, 30::int, 12::int, 18::int, '["Heat the oil in a wide lidded pan and soften the onion and carrot for 4 min, then add the sliced garlic and paprika for 30 seconds.","Pour in the wine and let it bubble 1 min, then add the tomatoes, potatoes, stock, bay leaf and a pinch of salt; cover and simmer 15 min.","Meanwhile mix the turkey, breadcrumbs, egg, grated garlic, parsley and a good pinch of salt and roll into 12 balls with wet hands.","Air-fry the meatballs at 200°C for 9–10 min, shaking halfway, until browned.","Add the meatballs and peas to the sauce and simmer uncovered for 3–4 min until the potatoes are tender and the meatballs cooked through.","Serve in shallow bowls with plenty of the sauce."]'::jsonb, array['spanish', 'comfort', 'kid-friendly', 'healthy', 'high protein']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('af2d856a-7536-5d5f-8b81-f02327abae2a'::uuid, 'Huevos a la flamenca with potatoes and peas', 2, null::int, 30::int, 8::int, 22::int, '["Boil the potatoes in a pot of salted water for 8 min, adding the peas and green beans for the last 3 min; drain.","Meanwhile heat the oil in a large lidded frying pan and fry the chorizo and half the ham for 2 min until the chorizo releases its red fat.","Add the onion and pepper and cook 5 min until soft, then the garlic and paprika for 30 seconds.","Pour in the tomatoes with a pinch of salt and simmer 5 min until thick.","Stir in the potatoes, peas and beans, make four wells and crack an egg into each.","Scatter over the rest of the ham, cover and cook on low heat for 6–8 min until the whites are set and the yolks still runny.","Sprinkle with parsley and serve straight from the pan."]'::jsonb, array['spanish', 'comfort', 'healthy', 'high protein']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('de68f89e-56c1-57c8-8b4b-2f5d4067110f'::uuid, 'Egg pulao with peas and cucumber raita', 2, null::int, 30::int, 10::int, 20::int, '["Lower the eggs into a pot of boiling water and cook 9 min, then cool in cold water, peel and prick them all over with a fork.","Meanwhile rinse the rice in several changes of water until it runs clear.","Heat the oil in a lidded pan and sizzle the cumin, bay leaf, cardamom and cinnamon for 30 seconds, then cook the onion for 5 min until golden.","Add the garlic, ginger, tomato, carrot, turmeric, garam masala and chilli and cook 2 min, then turn the eggs in this masala for 1 min.","Stir in the rice and peas, pour in 300 ml water with a good pinch of salt, bring to the boil, cover and cook on low heat for 12 min; rest 3 min.","For the raita, mix the yogurt with the cucumber, mint and a pinch of salt.","Fluff the pulao gently, halve the eggs on top, scatter with coriander and serve with the raita."]'::jsonb, array['indian', 'vegetarian', 'healthy', 'high protein']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a021169b-4ba3-50ef-9b7a-deec16739d7e'::uuid, 'Chicken tinola with green papaya, spinach and rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min, then rest with the lid on.","Heat the oil in a large pot and cook the onion, garlic and ginger over medium heat for 2–3 min until fragrant.","Add the chicken and fish sauce and stir for 3 min until the chicken turns opaque.","Pour in the stock, bring to the boil and simmer 5 min, skimming any foam.","Add the green papaya and simmer 8–10 min until it is tender when pierced with a knife.","Stir in the spinach off the heat until it wilts, then season with pepper and more fish sauce to taste.","Serve the tinola in bowls with the rice on the side."]'::jsonb, array['filipino', 'asian', 'soup', 'healthy', 'high protein']::text[], 'filipino', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b25b5c62-875d-559f-8c41-50052fcbfd0d'::uuid, 'Ayam masak merah with peas and rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and cook it covered in 210 ml water on low heat for 12 min, then rest with the lid on.","Rub the chicken with the turmeric and a pinch of salt. Pound or blend half the onion with the garlic, ginger, chilli flakes and 2 tbsp water into a paste.","Heat the oil in a lidded frying pan and sear the chicken over high heat for 4–5 min until golden; lift out.","Fry the paste with the lemongrass, star anise and cinnamon over medium heat for 3–4 min, stirring, until it darkens and the oil separates.","Add the tomatoes, ketchup, sugar and sliced onion, return the chicken, cover and simmer 8 min until the sauce is thick and red.","Stir in the peas and cook 3 min more; season with salt.","Remove the whole spices and serve with the rice and sliced cucumber."]'::jsonb, array['malaysian', 'asian', 'curry', 'spicy', 'healthy', 'high protein']::text[], 'malaysian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('77465ae6-5bc1-5aec-8bde-63d806d4b60a'::uuid, 'Tavuk sote with bulgur pilavı and cacık', 2, null::int, 30::int, 10::int, 20::int, '["For the pilaf, stir the bulgur and 1 tsp tomato paste in a pot with the stock and a pinch of salt, bring to the boil, cover and simmer on low heat for 12 min; rest 5 min off the heat.","Heat the oil in a large frying pan over high heat, season the chicken and sear it for 4–5 min until golden; lift out.","Cook the onion and peppers in the same pan for 5 min until soft, then add the garlic for 30 seconds.","Stir in the red pepper paste and the rest of the tomato paste for 1 min, then add the tomato, paprika, oregano and 4 tbsp water.","Return the chicken and simmer 5–6 min until the tomato has broken down into a thick sauce and the chicken is cooked through.","For the cacık, mix the yogurt with the squeezed cucumber and a pinch of salt.","Fluff the bulgur and serve with the tavuk sote, the cacık, a pinch of Aleppo pepper and parsley."]'::jsonb, array['turkish', 'middle eastern', 'healthy', 'high protein']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('cca6fe9b-0172-4d9d-a3fd-a702cd9f7788'::uuid, 'Thai beef larb with jasmine rice and green beans', 2, null::int, 25::int, 10::int, 15::int, '["Toast the 1 tbsp raw rice in a dry frying pan over medium heat, shaking often, 4-5 min until deep golden. Grind it coarsely in a mortar or spice grinder.","Rinse the jasmine rice and simmer it covered in 225 ml water for 12 min on low heat.","Lay the green beans on top of the rice, cover again and steam 5 min, then rest off the heat.","In the same frying pan, cook the beef with 3 tbsp water over medium-high heat, breaking it up, 5-6 min until no pink remains and most of the liquid has gone.","Take the pan off the heat. Stir in the fish sauce, lime juice, chili flakes and sugar, then the shallots, toasted rice powder, spring onions, mint and coriander. Taste: it should be sour, salty and hot.","Serve the larb with the rice, green beans, cucumber and lettuce leaves."]'::jsonb, array['thai', 'asian', 'healthy', 'high protein', 'salad', 'spicy', 'quick']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('651d32fd-5eb0-43da-9364-2fbd2b03b8e0'::uuid, 'Air-fryer steak fajitas with peppers and fresh salsa', 2, null::int, 25::int, 10::int, 15::int, '["Mix the chili powder, cumin, paprika, oregano, garlic, half the oil, half the lime juice and a good pinch of salt. Toss the steak strips in it.","Toss the peppers and onion with the rest of the oil and a pinch of salt. Air-fry at 200°C for 8 min, shaking once, until soft and charred at the edges.","Add the steak to the basket over the vegetables and air-fry 5-6 min more, shaking halfway, until the beef is browned outside and just pink inside.","Meanwhile, mix the tomatoes, coriander, chilli, the remaining lime juice and a pinch of salt for the salsa.","Warm the tortillas one at a time in a dry frying pan over high heat, about 20 s a side, until lightly charred.","Fill the tortillas with the steak and peppers, the salsa and a spoonful of yogurt."]'::jsonb, array['mexican', 'healthy', 'high protein', 'wrap', 'fakeaway', 'quick']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('d5b912f8-0d70-4774-a415-1a5fa020a743'::uuid, 'Beef chow fun with bean sprouts and pak choi', 2, null::int, 25::int, 15::int, 10::int, '["Toss the beef with the cornstarch, rice wine and 1 tsp of the soy sauce.","Soak the noodles in just-boiled water in a large bowl for 8-10 min, until pliable but still firm. Drain, rinse under cold water and shake dry.","Mix the dark soy, the rest of the soy sauce, the oyster sauce and sugar.","Heat half the oil in a wok over high heat until smoking. Sear the beef in one layer 1 min a side until browned but still pink, then lift it out.","Add the rest of the oil, the ginger and onion and stir-fry 1 min, then the pak choi for 1 min.","Add the noodles and sauce and toss over high heat 2 min, lifting from the bottom, until the noodles are evenly brown and slightly charred.","Return the beef with the bean sprouts and spring onions and toss 30 s, just until the sprouts wilt. Serve at once."]'::jsonb, array['chinese', 'asian', 'healthy', 'high protein', 'stir-fry', 'fakeaway', 'quick']::text[], 'chinese', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6e7bb3d3-506f-45a4-9097-8c2b6803a312'::uuid, 'Tagliata with rocket, cherry tomatoes and air-fryer potatoes', 2, null::int, 30::int, 10::int, 20::int, '["Toss the potatoes with 1 tbsp oil, the rosemary, garlic and a pinch of salt. Air-fry at 200°C for 18-20 min, shaking twice, until golden and tender.","Take the steak out of the fridge while the potatoes cook. Rub it with 1 tsp oil and season with salt and pepper.","When the potatoes have 10 min left, heat a griddle or heavy frying pan over high heat. Sear the steak 3-4 min a side for medium-rare (about 52°C in the centre).","Rest the steak on a board, loosely covered with foil, for 5 min.","Toss the rocket and tomatoes with the rest of the oil, the balsamic and a pinch of salt, and spread them on the plates.","Slice the steak thinly across the grain, lay it over the salad with its juices, scatter the parmesan and serve with the potatoes."]'::jsonb, array['italian', 'healthy', 'high protein', 'grill', 'salad']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('54cae69c-e6c8-4569-9b05-9254fa2cb357'::uuid, 'Arayes (spiced beef-stuffed pitta) with tahini yogurt and salad', 2, null::int, 27::int, 15::int, 12::int, '["Mix the beef with the grated onion, parsley, garlic, paprika, cumin, allspice, coriander, 0.5 tsp salt and some pepper.","Open the pitta pockets and spread a thin, even layer of the meat inside each one, right to the edges. Press them flat and brush the outsides with the oil.","Heat a griddle or heavy frying pan over medium heat. Cook the arayes 5-6 min a side, pressing down with a spatula, until the bread is crisp and the meat cooked through.","Meanwhile, whisk the tahini with the yogurt, the juice of half the lemon, a pinch of salt and a splash of water until smooth.","Toss the tomatoes, cucumber, lettuce and red onion with the juice of the other lemon half and a pinch of salt.","Cut the arayes into wedges and serve with the tahini yogurt and salad."]'::jsonb, array['lebanese', 'middle eastern', 'healthy', 'high protein', 'street food', 'sandwich']::text[], 'lebanese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b23711c2-533a-423a-80ab-b602acff9574'::uuid, 'Bibim-guksu with seared beef (Korean spicy cold noodles)', 2, null::int, 25::int, 10::int, 15::int, '["Bring a pan of water to the boil. Lower in the eggs and boil 7 min, then cool them in cold water and peel.","Mix the gochujang, vinegar, sugar, 1 tbsp of the soy sauce, the garlic and sesame oil for the sauce.","Toss the beef with the rest of the soy sauce. Heat the oil in a frying pan over high heat and sear the beef in one layer 1-2 min a side, until browned.","Cook the noodles in the egg water as the packet says, about 3 min. Drain and rinse under cold running water, rubbing them with your hands, until cold; drain well.","Toss the noodles with most of the sauce and the kimchi.","Pile into bowls with the lettuce, cucumber and carrot, top with the beef and a halved egg, spoon the rest of the sauce over the beef and scatter sesame seeds."]'::jsonb, array['korean', 'asian', 'healthy', 'high protein', 'spicy', 'summer', 'quick']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1d4fa9dd-bb13-4362-860a-9653141bc724'::uuid, 'Pad kra pao with pork, jasmine rice and a fried egg', 2, null::int, 25::int, 10::int, 15::int, '["Rinse the rice and simmer it covered in 225 ml water for 12 min on low heat, then rest it off the heat.","Pound the garlic and chillies to a rough paste in a mortar, or chop them finely together.","Heat 2 tsp oil in a wok over high heat. Fry the garlic-chilli paste 20 s, then add the pork and stir-fry 3-4 min, breaking it up, until no longer pink.","Add the onion and green beans and stir-fry 2 min, splashing in 2 tbsp water, until the beans are bright green.","Add the oyster sauce, soy sauce, fish sauce and sugar and toss 1 min, until the pork is glossy. Off the heat, stir in the holy basil until it just wilts.","Wipe the wok, heat the rest of the oil over medium-high heat and fry the eggs 2-3 min, until the edges are crisp and the yolks still runny.","Serve the pork over the rice with an egg on top."]'::jsonb, array['thai', 'asian', 'healthy', 'high protein', 'stir-fry', 'spicy', 'quick']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('47bf5056-24ad-4c5e-88a0-4117ac56b477'::uuid, 'Air-fryer mojo pork tenderloin with black beans and rice', 2, null::int, 30::int, 10::int, 20::int, '["Mix the orange and lime juice, garlic, cumin, oregano, 1 tbsp oil and a good pinch of salt and pepper: this is the mojo. Rub 2 tbsp of it over the pork.","Air-fry the pork at 200°C for 18-20 min, turning halfway, until it reads 63°C in the thickest part. Rest it 5 min.","Meanwhile, rinse the rice and simmer it covered in 225 ml salted water for 12 min on low heat, then rest it off the heat.","Heat the rest of the oil in a frying pan over medium heat and soften the onion and pepper 6-7 min.","Add the black beans, 3 tbsp of the mojo and 4 tbsp water and simmer 5 min, lightly crushing a few beans to thicken. Season.","Bring the rest of the mojo to a bubble in the pan for 30 s after the beans come out, or simply warm it.","Slice the pork, spoon the warm mojo over it and serve with the rice, beans and coriander."]'::jsonb, array['cuban', 'healthy', 'high protein', 'caribbean', 'bowl']::text[], 'cuban', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('61a67fe4-ed20-43c4-8c9f-baf3e10b7374'::uuid, 'Air-fryer bún thịt nướng (lemongrass pork noodle bowls)', 2, null::int, 30::int, 20::int, 10::int, '["Mix the lemongrass, 2 cloves of the garlic, the shallot, 1 tbsp fish sauce, 1 tbsp sugar, the soy sauce and oil. Toss the pork slices in it.","For the nuoc cham, stir the remaining 1 tbsp sugar into 4 tbsp warm water, then add the lime juice, the remaining 2 tbsp fish sauce, the last clove of garlic and the chilli.","Cook the vermicelli in boiling water 3-4 min, drain, rinse under cold water and leave to drain well.","Spread the pork in the air-fryer basket in a thin layer and air-fry at 200°C for 8-10 min, turning halfway, until caramelised at the edges.","Divide the noodles between two bowls with the lettuce, cucumber, carrot, bean sprouts and herbs.","Top with the pork and peanuts and serve with the nuoc cham to pour over."]'::jsonb, array['vietnamese', 'asian', 'healthy', 'high protein', 'bowl', 'street food']::text[], 'vietnamese', 'medium', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('0e197b9e-dc69-441f-a2d1-cd9136bbec72'::uuid, 'Dan dan noodles with pork and pak choi', 2, null::int, 25::int, 10::int, 15::int, '["Bring a large pan of water to the boil for the noodles.","In a wide bowl, mix the sesame paste, 1.5 tbsp of the soy sauce, the black vinegar, chili flakes, Sichuan pepper and sugar, then loosen with 3 tbsp of the hot water.","Heat the oil in a wok over high heat. Stir-fry the pork 5-6 min, breaking it up, until browned and a little crisp. Add the ginger, rice wine, five-spice and the rest of the soy sauce and cook 1 min more.","Cook the noodles as the packet says, adding the pak choi for the last 2 min.","Drain the noodles and pak choi, keeping a cup of the water. Toss the noodles in the sauce, adding a splash of the water so they are well coated.","Divide between bowls with the pak choi, top with the pork, spring onions and peanuts, and mix at the table."]'::jsonb, array['chinese', 'asian', 'healthy', 'high protein', 'spicy', 'quick']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ff31b27c-f7a0-4a2c-8178-b6c5f0362213'::uuid, 'Air-fryer pinchos morunos with flatbread and pepper salad', 2, null::int, 27::int, 15::int, 12::int, '["Mix the oil, paprika, cumin, coriander, turmeric, oregano, garlic, lemon juice and a good pinch of salt. Toss the pork in it and thread onto 4 short skewers.","Toss the tomatoes, pepper, onion and parsley with the vinegar, 1 tsp oil and a pinch of salt, and leave the salad to sit while the pork cooks.","Air-fry the skewers at 200°C for 10-12 min, turning halfway, until browned and 63°C in the centre.","Warm the flatbreads in a dry frying pan over medium heat, 1 min a side.","Rest the skewers 2 min, then serve with the flatbreads and pepper salad, spooning the salad juices over the bread."]'::jsonb, array['spanish', 'healthy', 'high protein', 'grill', 'street food']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('e81736b7-c0d3-4850-96f2-1412807c26dc'::uuid, 'Vietnamese caramelised pork rice bowls with quick-pickled vegetables', 2, null::int, 30::int, 15::int, 15::int, '["Rinse the rice and simmer it covered in 225 ml water for 12 min on low heat, then rest it off the heat.","Toss the cucumber and carrot with the vinegar, 1 tsp sugar and a pinch of salt and leave to pickle lightly while you cook.","Heat the oil in a frying pan over medium-high heat and fry the garlic and shallot 1 min.","Add the pork and cook 4-5 min, breaking it up, until no longer pink and the liquid has cooked off.","Add the brown sugar, fish sauce and plenty of black pepper. Cook 3-4 min, stirring only now and then, until the pork is dark, sticky and caramelised; do not let it burn.","Stir in the spring onions and serve the pork over the rice with the pickled vegetables, lettuce, herbs, chilli and lime."]'::jsonb, array['vietnamese', 'asian', 'healthy', 'high protein', 'bowl']::text[], 'vietnamese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0995e5ef-558a-4c4a-bf22-99ea716d1664'::uuid, 'Air-fryer lamb şiş kebab with bulgur pilaf and shepherd''s salad', 2, null::int, 30::int, 15::int, 15::int, '["Toss the lamb with 1 tsp oil, the paprika, cumin, chili flakes, garlic, the juice of half the lemon and a good pinch of salt. Thread onto 4 skewers.","Soften the chopped onion in a small pan with a splash of the stock for 3 min, stir in the tomato paste, then add the bulgur and the rest of the stock. Cover and simmer on low 12 min, then rest off the heat 5 min.","Meanwhile, air-fry the skewers at 200°C for 10-12 min, turning halfway, until browned outside and still a little pink inside.","For the salad, toss the tomatoes, cucumber, pepper, red onion and parsley with the pomegranate molasses, 1 tsp oil, the juice of the other lemon half and a pinch of salt.","Fluff the bulgur with a fork and serve with the kebabs and salad."]'::jsonb, array['turkish', 'healthy', 'high protein', 'grill', 'middle eastern']::text[], 'turkish', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('874599a2-12ae-4d54-9074-856cc0bc7876'::uuid, 'Hashweh (Lebanese spiced lamb rice) with tomato-cucumber salad', 2, null::int, 30::int, 10::int, 20::int, '["Toast the pine nuts in a dry, deep frying pan or wide pan over medium heat 2-3 min until golden, then tip them out.","In the same pan, brown the lamb over medium-high heat 5 min, breaking it up. Spoon off any excess fat.","Add the onion and garlic and cook 3 min, then stir in the allspice, cinnamon, nutmeg, salt and pepper.","Add the rice, stir to coat, pour in the stock and bring to the boil. Cover and cook on low heat 12 min, until the liquid is absorbed, then rest off the heat 5 min.","Meanwhile, toss the tomatoes, cucumber, parsley and mint with the lemon juice, oil and a pinch of salt.","Fluff the rice, scatter the pine nuts over and serve with the salad."]'::jsonb, array['lebanese', 'healthy', 'high protein', 'middle eastern', 'one-pot']::text[], 'lebanese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('59da88c3-74fc-46a4-a2a0-7888fa770b1e'::uuid, 'Air-fryer lamb leg steaks with salsa verde and white beans', 2, null::int, 25::int, 10::int, 15::int, '["Rub the steaks with 0.5 tsp oil, the rosemary, salt and pepper.","Air-fry the steaks at 200°C for 8-10 min, turning halfway, for pink in the middle. Rest them 5 min.","Meanwhile, finely chop the parsley, mint, capers and anchovy together, then stir in the mustard, vinegar, 1 tbsp oil and 1 tbsp water: this is the salsa verde.","Warm the rest of the oil in a frying pan over medium heat and fry the garlic 1 min. Add the tomatoes and cook 3 min until they start to burst.","Add the beans with 4 tbsp water and simmer 3 min, then stir in the spinach until it wilts. Season.","Slice the lamb and serve on the beans with the salsa verde spooned over."]'::jsonb, array['mediterranean', 'healthy', 'high protein', 'grill', 'quick']::text[], 'mediterranean', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('78369880-0b00-4bb0-84dc-4793dc5d2869'::uuid, 'Air-fryer lamb seekh kebabs with flatbread, kachumber and mint raita', 2, null::int, 27::int, 15::int, 12::int, '["Mix the lamb with the grated onion, garlic, ginger, chilli, half the coriander, the garam masala, cumin, chili powder and 0.5 tsp salt. Knead 1 min until sticky.","With wet hands, shape into 6 long sausages around skewers, or simply into logs.","Air-fry at 200°C for 10-12 min, turning halfway, until browned and cooked through.","Meanwhile, mix the tomatoes, cucumber, red onion, the rest of the coriander, the lemon juice and a pinch of salt for the kachumber. Stir the mint and a pinch of salt into the yogurt for the raita.","Warm the flatbreads in a dry frying pan over medium heat, 1 min a side.","Serve the kebabs on the flatbreads with the kachumber and raita."]'::jsonb, array['indian', 'healthy', 'high protein', 'grill', 'spicy']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('02e62558-d688-467d-ac0d-e78729da69be'::uuid, 'Mie goreng with prawns', 2, null::int, 22::int, 10::int, 12::int, '["Cook the noodles in boiling water as the packet says, drain, rinse briefly and toss with a few drops of the oil.","Mix the kecap manis, soy sauce and ketchup.","Heat half the oil in a wok over high heat. Scramble the eggs 1 min until just set, then push them to one side.","Add the rest of the oil, the garlic, shallot and chilli and stir-fry 30 s, then the prawns for 1-2 min until they just turn pink.","Add the cabbage and carrot and stir-fry 2 min, until the cabbage starts to wilt.","Add the noodles and sauce and toss vigorously 2 min until evenly coated and slightly sticky. Toss in the bean sprouts and spring onions for 30 s and serve with lime."]'::jsonb, array['indonesian', 'asian', 'healthy', 'high protein', 'stir-fry', 'street food', 'quick']::text[], 'indonesian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c80be323-9ad6-44cc-b065-7c8a50d3cf1e'::uuid, 'Air-fryer piri-piri prawns with crushed potatoes and tomato salad', 2, null::int, 30::int, 10::int, 20::int, '["Simmer the potatoes in salted water 15-18 min until tender.","Meanwhile, blitz or finely chop the chillies and garlic, then mix with the paprika, oregano, the juice of half the lemon, the vinegar, 1.5 tbsp oil and a pinch of salt: this is the piri-piri. Toss the prawns in half of it.","Air-fry the prawns at 200°C for 6-7 min, shaking halfway, until pink and just firm.","Toss the tomatoes, red onion and lettuce with 1 tsp oil, a squeeze of lemon and a pinch of salt.","Drain the potatoes, crush them lightly with a fork, and toss with the rest of the oil, the parsley and a pinch of salt.","Serve the prawns on the potatoes, drizzled with the rest of the piri-piri, with the salad and lemon wedges."]'::jsonb, array['portuguese', 'healthy', 'high protein', 'spicy']::text[], 'portuguese', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('241db188-c71f-493f-bdb8-6799bb6b8cb7'::uuid, 'Garides saganaki with orzo', 2, null::int, 30::int, 10::int, 20::int, '["Cook the orzo in boiling salted water as the packet says, about 9 min, then drain.","Meanwhile, heat the oil in a wide frying pan over medium heat and soften the onion 5 min. Add the garlic and chili flakes for 1 min.","Pour in the wine and let it bubble 1 min, then add the tomatoes and oregano and simmer 8 min until thickened. Season.","Nestle the prawns into the sauce and simmer 3-4 min, turning once, until pink and just cooked.","Stir the spinach into the drained orzo so it wilts in the heat.","Crumble the feta over the prawns, scatter with parsley and serve with the orzo."]'::jsonb, array['greek', 'healthy', 'high protein', 'mediterranean']::text[], 'greek', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('3c207655-1bf3-4635-8387-61f1ffd51f09'::uuid, 'Prawn yaki udon with cabbage and mushrooms', 2, null::int, 20::int, 10::int, 10::int, '["Put the udon in a bowl, cover with just-boiled water for 1 min to loosen, then drain.","Mix the soy sauce, oyster sauce, mirin and sesame oil.","Heat the oil in a wok or large frying pan over high heat. Stir-fry the prawns 1-2 min until pink, then lift them out.","Add the garlic, onion and carrot and stir-fry 1 min, then the cabbage and mushrooms for 2-3 min, until the cabbage is wilted but still has bite.","Add the udon, sauce and spring onions and toss 1-2 min until the noodles are hot and glossy.","Return the prawns, toss 30 s and serve with sesame seeds."]'::jsonb, array['japanese', 'asian', 'healthy', 'high protein', 'stir-fry', 'quick']::text[], 'japanese', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('79e23166-0c39-45a8-87a9-14327984483e'::uuid, 'Kung pao prawns with rice', 2, null::int, 25::int, 10::int, 15::int, '["Rinse the rice and simmer it covered in 225 ml water for 12 min on low heat, then rest it off the heat.","Toss the prawns with 1 tsp cornstarch and the rice wine. Mix the soy sauce, black vinegar, sugar, the rest of the cornstarch and 3 tbsp water for the sauce.","Heat the oil in a wok over medium heat and fry the chillies and Sichuan pepper 30 s, until fragrant and darkening but not burnt.","Turn the heat to high, add the prawns and stir-fry 1-2 min until they turn pink.","Add the garlic, ginger, pepper and celery and stir-fry 2 min.","Stir the sauce, pour it in and toss 1 min until glossy and thick. Toss in the spring onions and peanuts and serve with the rice."]'::jsonb, array['chinese', 'asian', 'healthy', 'high protein', 'stir-fry', 'spicy', 'fakeaway', 'quick']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4c3ac09a-6ddc-4a37-b664-f6952cc1dddf'::uuid, 'Air-fryer salt and pepper squid with garlic noodles and pak choi', 2, null::int, 30::int, 15::int, 15::int, '["Pat the squid very dry. Mix the cornstarch, Sichuan pepper, white pepper and salt and toss the squid in it, shaking off the excess.","Lay the squid in the air-fryer basket in one layer, spray or brush with 2 tsp of the oil and air-fry at 200°C for 8-10 min, shaking halfway, until crisp and golden.","Meanwhile, cook the noodles in boiling water as the packet says, adding the pak choi for the last minute, then drain.","Heat the rest of the oil in a wok over medium-high heat and fry the garlic, chilli and half the spring onions 1 min until fragrant.","Add the noodles, pak choi, soy sauce and oyster sauce and toss 1-2 min until hot and coated.","Toss the squid in the wok with the rest of the spring onions for 20 s, or scatter them over, and serve at once with lemon."]'::jsonb, array['chinese', 'asian', 'healthy', 'high protein', 'fakeaway']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('2c55825a-ebe6-49d8-b575-a44e3f3a2337'::uuid, 'Linguine with mussels, courgette and white wine', 2, null::int, 30::int, 15::int, 15::int, '["Bring a large pan of lightly salted water to the boil for the pasta. Throw away any mussels that stay open when tapped.","Heat 1 tbsp oil in a wide pan with a lid over medium heat and fry 1 clove of the garlic 30 s. Add the mussels and wine, cover and cook over high heat 3-4 min, shaking the pan, until they open.","Tip the mussels into a colander over a bowl to catch the juices. Discard any that stay shut, shell about two thirds, and strain the juices through a fine sieve.","Cook the linguine 2 min less than the packet says.","Meanwhile, wipe the wide pan, heat the rest of the oil and fry the courgette with the rest of the garlic and the chili flakes over medium-high heat 4-5 min until lightly golden.","Add the strained mussel juices and the drained linguine and toss over high heat 2 min, adding a little pasta water, until the pasta is al dente and coated.","Add all the mussels and the parsley, toss 30 s to warm through, season with pepper and serve."]'::jsonb, array['italian', 'healthy', 'high protein', 'mediterranean']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('fe97a411-d8af-458a-8532-f3fab76ba358'::uuid, 'Squid with chickpeas, chorizo and smoked paprika', 2, null::int, 30::int, 10::int, 20::int, '["Heat the oil in a wide pan over medium heat and fry the chorizo 2 min until it releases its red oil.","Add the onion and pepper and soften 6 min, then the garlic for 1 min.","Stir in the paprika, then straight away the grated tomato and wine, and simmer 4 min until jammy.","Add the chickpeas and 100 ml water and simmer 4 min.","Turn the heat up, add the squid and cook 2 min, just until it turns opaque, then stir in the spinach until it wilts.","Season, add the lemon juice and parsley and serve in bowls."]'::jsonb, array['spanish', 'healthy', 'high protein', 'stew', 'one-pot']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b691ac47-1e7f-4fcc-a0c8-e540b5d03fe1'::uuid, 'Ojingeo bokkeum (Korean spicy squid) with rice', 2, null::int, 25::int, 15::int, 10::int, '["Rinse the rice and simmer it covered in 195 ml water for 12 min on low heat, then rest it off the heat.","Mix the gochugaru, gochujang, soy sauce, sugar, garlic, ginger and 1 tbsp water to a paste.","Heat the oil in a wok over high heat and stir-fry the onion, carrot and cabbage 2-3 min, until just softening.","Add the squid and the paste and stir-fry 2-3 min, just until the squid turns opaque and curls.","Add the chilli and spring onions and toss 30 s, then take off the heat and stir in the sesame oil.","Serve over the rice with sesame seeds."]'::jsonb, array['korean', 'asian', 'healthy', 'high protein', 'stir-fry', 'spicy', 'quick']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('022f20e9-59c3-4056-8aa0-eb4976b7dab3'::uuid, 'Air-fryer chermoula salmon with couscous and peppers', 2, null::int, 30::int, 10::int, 20::int, '["Make the chermoula: mix the coriander, parsley, garlic, cumin, paprika, chilli, lemon zest and juice, 1 tbsp of the oil and a good pinch of salt.","Toss the peppers and onion with the rest of the oil and a pinch of salt and air-fry them at 200°C for 12 min, shaking once, until soft and charred at the edges.","Push the vegetables to the sides, lay the salmon skin-side down in the middle and spread a third of the chermoula over it.","Air-fry at 200°C for 8 min, until the salmon flakes but is still just pink in the centre.","Meanwhile, pour the boiling stock over the couscous in a bowl, cover and leave 5 min, then fluff it with a fork.","Fold the peppers and onion through the couscous, top with the salmon and spoon over the rest of the chermoula. Serve with lemon wedges."]'::jsonb, array['moroccan', 'north african', 'healthy', 'high protein']::text[], 'moroccan', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('59c18924-ccc7-497f-a5c4-9e94989bf0d3'::uuid, 'Salmon poke bowl with edamame and cucumber', 2, null::int, 30::int, 12::int, 18::int, '["Rinse the rice until the water runs clear, then simmer it covered in 230 ml water for 12 min on low heat. Rest it off the heat, lid on, for 5 min.","Pour boiling water over the edamame, leave 3 min and drain.","Mix the soy sauce, sesame oil, vinegar and ginger in a bowl.","Add the salmon, sliced onion and half the spring onion and toss gently. Leave it in the fridge while the rice rests, no longer than 15 min.","Divide the warm rice between two bowls. Top with the salmon and its juices, the edamame, cucumber and avocado.","Finish with the rest of the spring onion and the sesame seeds and eat straight away."]'::jsonb, array['american', 'bowl', 'healthy', 'high protein']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bd2199fd-6c52-4d10-a4ca-386b688186d8'::uuid, 'Thai green curry salmon with jasmine rice and green beans', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and simmer it covered in 230 ml water for 12 min on low heat, then rest it 5 min off the heat.","Heat the oil in a deep frying pan and fry the curry paste for 1 min, stirring, until fragrant.","Stir in the coconut milk, stock, fish sauce, sugar and lime leaves and bring to a simmer.","Add the green beans and pepper and simmer 4 min, until just tender.","Slide in the salmon, cover and simmer gently 5-6 min, without stirring much, until the chunks are opaque.","Season with the lime juice, more fish sauce if needed, scatter the Thai basil over and serve with the rice."]'::jsonb, array['thai', 'asian', 'curry', 'healthy', 'high protein', 'spicy']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('58d8795f-34d0-4e1d-b21e-ffda56e65731'::uuid, 'Air-fryer tandoori salmon with jeera rice and kachumber', 2, null::int, 30::int, 15::int, 15::int, '["Rinse the rice. Melt the butter in a pan, sizzle the cumin seeds 30 s, add the rice and 230 ml water with a pinch of salt, cover and cook 12 min on low heat. Rest 5 min off the heat.","Mix the yogurt, paprika, chilli powder, garam masala, turmeric, garlic, ginger, half the lemon juice and a good pinch of salt.","Coat the salmon thickly in the spiced yogurt.","Air-fry the salmon on a piece of baking paper at 200°C for 9 min, until charred at the edges and just cooked in the centre.","Meanwhile, toss the tomatoes, cucumber, onion and coriander with the rest of the lemon juice and a pinch of salt for the kachumber.","Fluff the rice with a fork and serve it with the salmon and the kachumber."]'::jsonb, array['indian', 'healthy', 'high protein', 'spicy']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('f708ce15-5178-43bc-b7ee-702b77e3e205'::uuid, 'Lemon-oregano salmon with orzo, spinach and tomatoes', 2, null::int, 30::int, 8::int, 22::int, '["Season the salmon with salt, pepper, the lemon zest and half the oregano.","Heat the oil in a wide lidded pan and sear the salmon 2 min on each side. Lift it onto a plate.","Soften the onion in the same pan for 3 min, add the garlic, the orzo and the rest of the oregano and stir 1 min.","Pour in the stock and simmer 8 min, stirring often so the orzo doesn''t stick.","Stir in the tomatoes, nestle the salmon on top, cover and cook 6 min on low heat, until the orzo is tender and the salmon flakes.","Lift the salmon out, stir the spinach and lemon juice into the orzo until the leaves wilt, then serve with the salmon on top and the dill over."]'::jsonb, array['greek', 'mediterranean', 'one-pot', 'healthy', 'high protein']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6549101f-d482-4c79-a6a7-9afde73166f9'::uuid, 'Air-fryer salmon burrito bowl with quinoa, black beans and pico de gallo', 2, null::int, 30::int, 15::int, 15::int, '["Simmer the quinoa in 280 ml salted water, covered, for 15 min, then leave it 5 min off the heat and fluff it.","Rub the salmon with the oil, chilli powder, cumin, paprika and a pinch of salt.","Air-fry the salmon at 200°C for 8 min, until it flakes.","Meanwhile, warm the black beans and corn in a small pan with a splash of water and a pinch of salt, 3 min.","For the pico de gallo, mix the tomatoes, onion, chilli, coriander and half the lime juice with a pinch of salt.","Toss the quinoa with the rest of the lime juice. Build the bowls with lettuce, quinoa, beans and corn, flaked salmon and the pico de gallo."]'::jsonb, array['mexican', 'bowl', 'healthy', 'high protein']::text[], 'mexican', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8cd2d154-7c73-419f-bd7a-7e5867400f4e'::uuid, 'Salmon in black bean sauce with noodles and broccoli', 2, null::int, 27::int, 12::int, 15::int, '["Cook the noodles in boiling water as the packet says, adding the broccoli for the last 2 min. Drain.","Mix the rice wine, soy sauce, sugar and cornstarch with 80 ml water.","Heat half the oil in a wok over high heat, brown the salmon 2 min, turning carefully, and lift it out.","Add the rest of the oil and stir-fry the black beans, garlic, ginger and the white of the spring onions 30 s, then the pepper 2 min.","Pour in the sauce and let it bubble until glossy, about 1 min. Return the salmon and the green of the spring onions and turn gently 1-2 min, until the fish is just cooked.","Serve over the noodles and broccoli."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'healthy', 'high protein']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('33a89e95-3c35-4277-a5b4-880b975634ef'::uuid, 'Sinigang na isda (Filipino sour tamarind hake soup) with rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and simmer it covered in 240 ml water for 12 min on low heat, then rest it 5 min off the heat.","Bring 900 ml water to the boil with the onion and tomatoes and simmer 5 min, until the tomatoes soften.","Add the daikon and eggplant and simmer 5 min.","Stir in the tamarind paste and fish sauce, then add the green beans and chilli and simmer 3 min. Taste: the broth should be clearly sour and salty.","Slide in the hake and poach gently 4-5 min, without stirring, until it flakes.","Add the spinach, let it wilt for 1 min and serve the soup in bowls with the rice alongside."]'::jsonb, array['filipino', 'asian', 'soup', 'healthy', 'high protein']::text[], 'filipino', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4ef6481f-d6d1-443e-923f-912d65ebac62'::uuid, 'Pescado sudado (Peruvian steamed cod in tomato and ají) with rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and simmer it covered in 240 ml salted water for 12 min on low heat, then rest it 5 min off the heat.","Heat the oil in a wide lidded pan and fry the garlic, ají amarillo and cumin 1 min.","Lay in half the onion, pepper and tomato, put the salted cod on top and cover it with the rest of the vegetables.","Pour in the stock and vinegar, scatter half the coriander, cover tightly and steam 10 min over medium-low heat, until the fish flakes.","Taste the juices for salt, then serve the fish and vegetables with their broth over the rice, with the rest of the coriander and lime wedges."]'::jsonb, array['peruvian', 'healthy', 'high protein', 'stew']::text[], 'peruvian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('ba8a84c5-00bf-4b05-93dc-7cadaecd18c0'::uuid, 'Air-fryer sea bass with nam jim, jasmine rice and cucumber salad', 2, null::int, 30::int, 15::int, 15::int, '["Rinse the rice and simmer it covered in 240 ml water for 12 min on low heat, then rest it 5 min off the heat.","For the nam jim, pound or finely chop the garlic, 1.5 chillies and the coriander stems, then stir in the lime juice, fish sauce and 2 tsp of the sugar until it dissolves.","For the salad, toss the cucumber and shallot with the vinegar, the rest of the sugar, the last half chilli, sliced, and a pinch of salt.","Pat the sea bass dry, rub with the oil and salt, and air-fry skin-side up at 200°C for 7-8 min, until the skin is crisp and the flesh flakes.","Serve the fish on the rice with the nam jim spooned over, the cucumber salad on the side, and coriander leaves scattered over."]'::jsonb, array['thai', 'asian', 'healthy', 'high protein', 'spicy']::text[], 'thai', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('bb3fc801-6cbe-481c-b05d-fb04dd359d6b'::uuid, 'Chả cá Lã Vọng (turmeric hake with dill and rice noodles)', 2, null::int, 30::int, 15::int, 15::int, '["Toss the hake with the turmeric, ginger, half the garlic, 1 tbsp fish sauce, 1 tsp sugar and the cornstarch.","For the dipping sauce, stir the rest of the fish sauce and sugar with the lime juice, 4 tbsp water, the rest of the garlic and the chilli.","Cook the noodles in boiling water as the packet says, rinse under cold water and drain well.","Heat the oil in a frying pan over medium-high heat and fry the fish 2-3 min on each side, until golden and just cooked.","Add the spring onions and dill to the pan and turn them through the fish for 30 s, just until they wilt.","Serve the fish and herbs over the noodles with the lettuce, peanuts and coriander, and the dipping sauce to pour over."]'::jsonb, array['vietnamese', 'asian', 'healthy', 'high protein']::text[], 'vietnamese', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('da238c68-2dc8-45fe-8dc5-e6e86a857332'::uuid, 'Sea bass acqua pazza with cherry tomatoes, fennel and crusty bread', 2, null::int, 28::int, 10::int, 18::int, '["Warm the oil, garlic and chilli in a wide lidded pan over medium heat for 1 min, without letting the garlic brown.","Add the fennel and soften it 4 min, then the tomatoes for 2 min, until they start to collapse.","Pour in the wine and 150 ml water, season with salt and simmer 3 min.","Lay the salted fillets in skin-side down, spoon some broth over, cover and poach on low heat 5-6 min, until the flesh is opaque.","Toast the bread meanwhile.","Serve the fish in shallow bowls with the tomatoes and broth, scatter the parsley over and mop up with the bread."]'::jsonb, array['italian', 'mediterranean', 'one-pot', 'healthy', 'high protein']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('17a428e4-0b49-4531-8331-a55c82dad034'::uuid, 'Air-fryer samke harra (spicy cod with tahini) and bulgur', 2, null::int, 30::int, 10::int, 20::int, '["Simmer the bulgur in 300 ml salted water, covered, for 12 min, then leave it 5 min off the heat.","Rub the cod with 1 tsp of the oil, the paprika, cumin and salt, and air-fry at 200°C for 9-10 min, until it flakes.","Meanwhile, soften the onion in the rest of the oil in a frying pan for 6 min, add the garlic, chilli and walnuts and cook 2 min more, then stir in most of the coriander.","Whisk the tahini, yogurt and three quarters of the lemon juice with 3-4 tbsp water and a pinch of salt into a pourable sauce.","Toss the tomato and cucumber with the rest of the lemon juice and a pinch of salt.","Serve the cod on the bulgur, pour over the tahini sauce, pile the spicy onion mixture on top and finish with the rest of the coriander, with the salad on the side."]'::jsonb, array['lebanese', 'middle eastern', 'healthy', 'high protein', 'spicy']::text[], 'lebanese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('7b7783ab-776d-4480-a787-1c97ecf7dc6b'::uuid, 'Air-fryer Amritsari fish with flatbreads, mint yogurt and onion salad', 2, null::int, 27::int, 15::int, 12::int, '["Mix the gram flour, chilli powder, ajwain, turmeric, garam masala, ginger, garlic, 1 tbsp lemon juice, a good pinch of salt and 2-3 tbsp water into a thick paste.","Coat the fish in the paste, lay it in the oiled air-fryer basket and brush it with the oil.","Air-fry at 200°C for 10 min, turning halfway, until crisp and golden.","Meanwhile, stir the yogurt with the mint, coriander, green chilli and a pinch of salt.","Toss the onion, cucumber and tomato with the rest of the lemon juice and a pinch of salt.","Warm the flatbreads 30 s each side in a dry frying pan.","Sprinkle the fish with chaat masala and serve it in the flatbreads with the onion salad and mint yogurt."]'::jsonb, array['indian', 'street food', 'wrap', 'healthy', 'high protein', 'spicy']::text[], 'indian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('c40a37d3-7131-4565-8b3d-1566d266554b'::uuid, 'Seared tuna with cold soba, edamame and cucumber', 2, null::int, 22::int, 12::int, 10::int, '["Cook the soba in boiling water as the packet says, adding the edamame for the last 3 min. Rinse under cold water, rubbing the noodles to remove the starch, and drain well.","Whisk the soy sauce, vinegar, mirin, sesame oil and ginger.","Toss the noodles, edamame, cucumber, carrot, snow peas and most of the spring onion with two thirds of the dressing.","Season the tuna with salt and press the sesame seeds onto both sides.","Heat the oil in a frying pan over high heat and sear the tuna 1-1.5 min on each side, so it stays pink inside. Rest 1 min and slice.","Pile the noodles into bowls, lay the tuna on top, drizzle over the rest of the dressing and scatter the last of the spring onion."]'::jsonb, array['japanese', 'asian', 'salad', 'healthy', 'high protein', 'quick']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('d75b1169-6877-4ca8-8496-deb6828a39b3'::uuid, 'Pasta tonno e zucchine (tuna and courgette pasta with lemon)', 2, null::int, 23::int, 8::int, 15::int, '["Cook the pasta in well-salted boiling water until al dente, about 11 min. Keep a cup of the cooking water.","Meanwhile, heat the oil in a large frying pan and soften the shallot and garlic 2 min.","Add the courgettes with a pinch of salt and cook 6-7 min over medium-high heat, until golden in places and tender.","Pour in the wine and let it evaporate, then add the tuna in flakes and the chilli and warm through 2 min.","Drain the pasta and toss it in the pan with a splash of cooking water, the lemon zest and juice and the parsley until glossy.","Serve with the basil and a grind of pepper."]'::jsonb, array['italian', 'healthy', 'high protein', 'quick']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b3af1747-1bd4-4ce2-a8ba-1bed3e564400'::uuid, 'Atún encebollado (tuna with sweet onions) and potatoes', 2, null::int, 30::int, 10::int, 20::int, '["Boil the potatoes in salted water for 12-14 min, until tender, and drain.","Meanwhile, heat the oil in a wide pan and cook the onions, pepper, garlic and bay leaf with a pinch of salt over medium heat for 12 min, stirring often, until soft and lightly golden.","Stir in the paprika, then the wine and vinegar, and let them bubble 2 min.","Season the tuna with salt, nestle it into the onions, cover and cook 3-4 min on low heat, turning once, until just pink in the centre.","Serve the tuna and onions with the potatoes, spooning the juices over, and scatter with parsley."]'::jsonb, array['spanish', 'healthy', 'high protein']::text[], 'spanish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a68ec850-a7a8-4494-abc8-c41fa57e15e4'::uuid, 'Pan bagnat (Niçoise tuna, egg and tomato sandwich)', 2, null::int, 25::int, 15::int, 10::int, '["Lower the eggs into boiling water and cook 9 min, then cool them in cold water, peel and slice.","Split the rolls and rub the cut sides with the garlic.","Whisk the oil and vinegar with a pinch of salt and brush most of it over the cut sides.","Lay the tomatoes on the bottom halves so their juice soaks into the bread, then the pepper, radish and onion.","Add the tuna, egg slices, anchovies, olives and basil, drizzle over the rest of the dressing and close the rolls.","Press each one down firmly with your hand, or wrap and weigh it down for a few minutes, so the bread takes up the juices. Eat now or wrapped on a picnic."]'::jsonb, array['french', 'sandwich', 'picnic', 'summer', 'healthy', 'high protein', 'quick']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('b0be422c-c1c9-4b9b-a518-9cf99c35992c'::uuid, 'Tuna bibimbap with spinach, courgette, carrot and fried egg', 2, null::int, 30::int, 12::int, 18::int, '["Rinse the rice and simmer it covered in 210 ml water for 12 min on low heat, then rest it 5 min off the heat.","Mix the gochujang, honey, vinegar and 1 tsp sesame oil with 1 tbsp water for the sauce.","Heat a little of the oil in a frying pan and stir-fry the vegetables one after the other with a pinch of salt: the carrot and courgette 2 min each, the bean sprouts 1 min, then the spinach with the garlic until wilted. Set each aside.","Season the spinach with the soy sauce and the rest of the sesame oil. Warm the tuna in the pan for 1 min.","Fry the eggs in the rest of the oil until the whites are set and the yolks still runny.","Fill bowls with rice, arrange the vegetables and tuna on top in sections, add an egg and a spoonful of sauce, and mix everything together at the table."]'::jsonb, array['korean', 'asian', 'bowl', 'healthy', 'high protein', 'spicy']::text[], 'korean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8a982386-b3eb-46db-91d5-ba0b6caec5b2'::uuid, 'Air-fryer teriyaki mackerel don with pak choi', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 230 ml water for 12 min on low heat. Lay the pak choi on top, cover again and steam 4 min off the heat.","Mix the soy sauce, mirin, sake, sugar and ginger for the teriyaki sauce.","Pat the mackerel dry, rub with the oil and a pinch of salt and air-fry skin-side up at 200°C for 7-8 min, until the skin is crisp and the flesh opaque.","Meanwhile, simmer the sauce in a small pan for 2-3 min, until syrupy and glossy.","Turn the cooked mackerel in the sauce to glaze it.","Fill bowls with rice, add the pak choi and the mackerel, spoon over the rest of the sauce and finish with spring onion and sesame seeds."]'::jsonb, array['japanese', 'asian', 'bowl', 'healthy', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a2384340-1caf-457a-90aa-b35463171d1f'::uuid, 'Air-fryer Portuguese sardines with potatoes and roasted pepper salad', 2, null::int, 30::int, 8::int, 22::int, '["Boil the potatoes in salted water for 15-18 min, until tender, and drain.","Meanwhile, toss the peppers with 1 tsp of the oil and air-fry at 200°C for 12 min, until soft and blistered.","Toss the hot peppers with the onion, garlic, vinegar, half the remaining oil and a pinch of salt.","Rub the sardines with coarse salt and air-fry them in one layer at 200°C for 8-10 min, turning once, until the skin is crisp and the flesh lifts off the bone.","Toss the potatoes with the rest of the oil, the parsley and salt, and serve with the sardines, the pepper salad and lemon wedges."]'::jsonb, array['portuguese', 'mediterranean', 'healthy', 'high protein']::text[], 'portuguese', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('bb8f91b7-7ead-48a7-b419-e1476bfc8284'::uuid, 'Pan-fried trout with harissa chickpeas, tomatoes and spinach', 2, null::int, 25::int, 8::int, 17::int, '["Heat two thirds of the oil in a saucepan and soften the onion 4 min, then stir in the garlic, harissa and cumin for 1 min.","Add the tomatoes, chickpeas and stock and simmer 6-8 min, crushing a few chickpeas, until the tomatoes collapse and the sauce thickens.","Stir in the spinach until it wilts and season with salt and a squeeze of lemon.","Meanwhile, season the trout, heat the rest of the oil in a frying pan and cook it skin-side down 3 min, until crisp, then 1 min on the other side.","Serve the trout on the harissa chickpeas with a spoonful of yogurt, the coriander, and lemon wedges."]'::jsonb, array['north african', 'healthy', 'high protein', 'quick']::text[], 'north african', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('22b6241d-3e59-411e-9fd3-2c7eda838123'::uuid, 'Air-fryer balık ekmek (Istanbul mackerel sandwich) with sumac onions', 2, null::int, 22::int, 12::int, 10::int, '["Toss the onion with the sumac, parsley, half the lemon juice and a pinch of salt and leave it to soften.","Rub the mackerel with the oil, chilli flakes and salt.","Air-fry skin-side up at 200°C for 7-8 min, until the skin is crisp and the flesh flakes.","Meanwhile, split the bread and toast the cut sides in a hot dry frying pan for 1-2 min.","Fill the bread with lettuce, tomato and the mackerel, squeeze the rest of the lemon over the fish and pile on the sumac onions."]'::jsonb, array['turkish', 'street food', 'sandwich', 'healthy', 'high protein', 'quick']::text[], 'turkish', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('3cdabe28-1cd3-448c-8f71-eaae284a4ce1'::uuid, 'Pasta con le sarde (Sicilian sardine pasta with fennel, raisins and pine nuts)', 2, null::int, 30::int, 10::int, 20::int, '["Soak the raisins in hot water and the saffron in 2 tbsp hot water while you start.","Boil the sliced fennel in a large pan of salted water for 6 min, lift it out, then cook the pasta in the same fennel water until al dente.","Meanwhile, toast the breadcrumbs in a large dry frying pan for 2 min, until golden, and tip them out.","Heat the oil in the pan and soften the onion 4 min, then melt in the anchovies.","Add the sardine fillets and cook 3-4 min, breaking them up a little, then stir in the fennel, drained raisins, saffron water, pine nuts and a ladle of pasta water and simmer 2 min.","Drain the pasta, toss it in the sauce until coated, and serve topped with the toasted breadcrumbs and chopped fennel fronds."]'::jsonb, array['italian', 'mediterranean', 'healthy', 'high protein']::text[], 'italian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('15925b98-3003-474e-bb56-1d95b3da4213'::uuid, 'Air-fryer trout with salsa criolla and corn quinoa', 2, null::int, 28::int, 12::int, 16::int, '["Simmer the quinoa in 280 ml salted water, covered, for 15 min. Stir in the corn and leave it 5 min off the heat, lid on.","For the salsa criolla, rinse the onion in cold water, drain and toss with the ají amarillo, the juice of 1.5 limes, 1 tsp oil, half the coriander and a pinch of salt.","Rub the trout with the garlic, cumin, the rest of the oil and salt.","Air-fry skin-side up at 200°C for 6-7 min, until the flesh flakes.","Fluff the quinoa with the rest of the lime juice and coriander, and serve with the trout and the salsa criolla piled on top."]'::jsonb, array['peruvian', 'healthy', 'high protein']::text[], 'peruvian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('5f5e4869-7d40-56ba-bd0a-2e009c50c98d'::uuid, 'Air-fryer tofu satay with rice, cucumber and green beans', 2, null::int, 27::int, 10::int, 17::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min.","Pat the tofu dry and toss it with the soy sauce, curry powder and turmeric, then with the cornstarch and oil.","Air-fry the tofu at 200°C for 15 min, shaking the basket halfway, until crisp and golden at the edges.","Lay the green beans over the rice, cover again and steam 5 min, then leave off the heat.","Whisk the peanut butter with the soy sauce, lime juice, honey, sriracha, garlic and 3-4 tbsp hot water into a pourable sauce.","Serve the tofu on the rice with the beans and cucumber, spoon the satay sauce over and scatter with spring onion and coriander."]'::jsonb, array['malaysian', 'asian', 'vegetarian', 'healthy', 'high protein', 'bowl']::text[], 'malaysian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('d5da07c5-ead2-5fba-a56c-d6763c2ea440'::uuid, 'Air-fryer salt and pepper tofu with rice and pak choi', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Mix the cornstarch with the Sichuan pepper, white pepper and salt. Toss the dry tofu in it, then with 2 tsp of the oil.","Air-fry at 200°C for 12-15 min, shaking twice, until crisp all over.","Heat the rest of the oil in a wok and stir-fry the garlic, chilli and pepper for 2 min.","Add the pak choi, soy sauce and 2 tbsp water and toss 2-3 min, until the leaves wilt but the stems still crunch. Tip onto plates.","Toss the hot tofu in the wok with the spring onion and sesame oil for 30 seconds and serve with the rice and pak choi."]'::jsonb, array['chinese', 'asian', 'vegetarian', 'healthy', 'high protein', 'stir-fry']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('72a7a213-1c8e-5209-9e43-c124015224dd'::uuid, 'Air-fryer lemongrass chilli tofu with rice noodles and herbs', 2, null::int, 30::int, 15::int, 15::int, '["Mix the lemongrass, shallot, two thirds of the garlic, half the chilli, the soy sauce, sugar, turmeric and oil. Toss the tofu in it.","Air-fry the tofu with all its lemongrass bits at 190°C for 12-15 min, shaking halfway, until golden and crisp.","Cook the noodles in boiling water for 3-4 min, until just tender, then drain and rinse under cold water.","Stir the lime juice, soy sauce, sugar, the rest of the garlic and chilli and 3 tbsp water into a dressing, until the sugar dissolves.","Fill two bowls with lettuce, noodles, cucumber, carrot and bean sprouts.","Top with the tofu, scrape over the crisp lemongrass from the basket, add the herbs and peanuts and pour over the dressing."]'::jsonb, array['vietnamese', 'asian', 'vegetarian', 'healthy', 'high protein', 'bowl']::text[], 'vietnamese', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('93f84af9-8cb0-52ab-a5c0-55db1ea75204'::uuid, 'Tofu shogayaki with rice and shredded cabbage', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Mix the ginger, garlic, soy sauce, mirin, sake and sugar.","Pat the tofu dry and dust it with the cornstarch. Fry it in the oil in a large frying pan over medium-high heat, 3 min per side, until golden.","Push the tofu to the side, add the onion and cook 3 min, until soft.","Pour in the sauce and let it bubble 1-2 min, turning the tofu, until it glazes the slices.","Serve the tofu and onion with their sauce next to the rice, a mound of shredded cabbage and the tomato, with spring onion on top."]'::jsonb, array['japanese', 'asian', 'vegetarian', 'healthy', 'high protein']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('8ec374bf-9573-5d4e-80e0-8501c425e6b4'::uuid, 'Mie goreng with tempeh and egg', 2, null::int, 25::int, 10::int, 15::int, '["Cook the noodles in boiling water for 3-4 min, drain and rinse under cold water.","Fry the tempeh in 1 tbsp oil in a wok over medium-high heat for 4-5 min, turning, until golden. Lift out.","Add the rest of the oil and stir-fry the shallot, garlic and chilli for 1 min, then the carrot and cabbage for 2 min.","Push the vegetables aside, crack in the eggs and scramble them until just set.","Add the noodles, kecap manis, soy sauce and bean sprouts and toss over high heat for 2 min, until the noodles are glossy and hot.","Toss the tempeh and spring onion back in and serve with lime wedges."]'::jsonb, array['indonesian', 'asian', 'vegetarian', 'healthy', 'high protein', 'stir-fry', 'quick']::text[], 'indonesian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a8f3e6c9-03a6-5fea-9810-d15ac7cf6e94'::uuid, 'Pad kra pao with tempeh and a fried egg', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Heat 1 tbsp oil in a wok until very hot and fry the eggs one at a time for 2 min, spooning oil over, until the edges are crisp and the yolks still runny. Lift out.","Pound or finely chop the garlic and chillies together. Mix the soy sauce, dark soy sauce, sugar and 2 tbsp water.","Add the rest of the oil to the wok, fry the garlic and chilli for 30 seconds, then the tempeh for 3 min, until browned.","Add the beans and onion and stir-fry 2 min, then the sauce for 1 min, until it coats everything.","Take the wok off the heat and stir in the basil until it just wilts. Serve over the rice with a fried egg on top."]'::jsonb, array['thai', 'asian', 'vegetarian', 'healthy', 'high protein', 'stir-fry', 'spicy']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5bbf80f0-4280-559d-840e-8a3798e4f5d4'::uuid, 'Chana saag with rice', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Fry the onion in the oil in a wide pan over medium heat for 5 min, until soft and golden.","Add the garlic, ginger, chilli, cumin, coriander and turmeric and stir 1 min, until fragrant.","Add the tomatoes and cook 3 min, then the chickpeas and 100 ml water. Simmer 5 min, crushing a few chickpeas to thicken the sauce.","Stir in the spinach a handful at a time until wilted, then the garam masala. Season with salt.","Serve the chana saag with the rice."]'::jsonb, array['indian', 'vegetarian', 'healthy', 'high protein', 'curry']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a2a8754c-0660-5b6f-af79-763c22ea9e69'::uuid, 'Air-fryer black bean tostadas with avocado and pickled onion', 2, null::int, 25::int, 10::int, 15::int, '["Toss the onion with the juice of 1 lime and a pinch of salt and leave it to turn pink while you cook.","Brush the tortillas lightly with 1 tsp of the oil and air-fry them two or three at a time at 190°C for 5 min, flipping halfway, until crisp.","Meanwhile, warm the rest of the oil in a pan with the garlic, cumin and chili powder for 1 min.","Add the beans and 4 tbsp water and cook 5 min, mashing them into a rough, spreadable purée. Add the juice of the second lime and salt.","Spread the beans on the tostadas and top with lettuce, tomato, avocado, the drained pickled onion, coriander and hot sauce."]'::jsonb, array['mexican', 'vegetarian', 'healthy', 'high protein', 'street food', 'quick']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('18921f2f-7942-5bfa-8c44-66a4de953264'::uuid, 'Pasta e fagioli', 2, null::int, 30::int, 10::int, 20::int, '["Soften the onion, carrot and celery in 1 tbsp of the oil in a large pot over medium heat for 6 min.","Add the garlic, rosemary and tomato paste and stir 1 min.","Add the tomatoes, beans and stock, bring to the boil and simmer 3 min.","Scoop out a ladle of beans, mash them with a fork and stir them back in to thicken the soup.","Add the pasta and cook 9-10 min, stirring often, until al dente and the soup is thick. Add a splash of water if it gets too dry.","Remove the rosemary, rest 2 min, then serve with the rest of the oil, black pepper and parmesan."]'::jsonb, array['italian', 'vegetarian', 'healthy', 'high protein', 'soup', 'one-pot']::text[], 'italian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('0bea3390-8cab-59e2-96c7-b2464bd0572a'::uuid, 'Musabaha with warm pitta and chopped salad', 2, null::int, 25::int, 10::int, 15::int, '["Cover the chickpeas with water in a pan, add the cumin and simmer 10-12 min, until very soft.","Whisk the tahini with three quarters of the lemon juice, the garlic, a pinch of salt and 3-4 tbsp cold water into a smooth sauce.","Mix the tomato, cucumber, onion and parsley with the rest of the lemon juice, 1 tsp of the oil and salt.","Drain the chickpeas, keeping a little liquid. Roughly mash a third of them with half the tahini sauce and 2-3 tbsp of the liquid.","Warm the pitta in the empty pan for 1 min per side.","Spread the mash in bowls, pile the whole chickpeas on top, pour over the rest of the sauce and oil, dust with paprika and serve with the salad and pitta."]'::jsonb, array['middle eastern', 'lebanese', 'vegetarian', 'healthy', 'high protein', 'quick']::text[], 'middle eastern', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('14e68d98-f16b-54ea-bb06-2b58e9a9b9fc'::uuid, 'Ezogelin soup with mint butter and bread', 2, null::int, 30::int, 5::int, 25::int, '["Soften the onion in the oil in a large pot over medium heat for 4 min.","Stir in the tomato paste and paprika for 1 min, then the grated tomato for 1 min.","Add the lentils, bulgur and stock, bring to the boil and simmer partly covered for 18-20 min, stirring now and then, until the lentils collapse and the soup is thick.","Season with salt, adding a little hot water if it is too thick.","Melt the butter in a small pan, add the dried mint and Aleppo pepper and let it sizzle 30 seconds.","Ladle the soup into bowls, drizzle with the mint butter and serve with lemon wedges and bread."]'::jsonb, array['turkish', 'vegetarian', 'healthy', 'high protein', 'soup']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('984accea-cf2e-515c-adc4-8fe25da6a904'::uuid, 'Huevos motuleños with black beans and peas', 2, null::int, 28::int, 10::int, 18::int, '["Cook the tomato, onion, garlic and scotch bonnet in 1 tsp of the oil in a pan for 8 min, crushing with a spoon into a chunky sauce. Add the peas for the last 3 min and season.","Meanwhile, warm the beans in a frying pan with 4 tbsp water for 4 min, mashing them into a thick purée. Season and spoon into a bowl; wipe the pan.","Brush the tortillas with a little oil and air-fry them at 180°C for 3-4 min, until lightly crisp but still pliable.","Fry the eggs in the rest of the oil in the frying pan for 3 min, until the whites are set and the yolks runny.","Spread each tortilla with beans and top with a fried egg.","Spoon the tomato and pea sauce over and finish with queso fresco and coriander."]'::jsonb, array['mexican', 'vegetarian', 'healthy', 'high protein', 'spicy']::text[], 'mexican', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('eceda964-0519-5e5a-b221-5f8a182e1afc'::uuid, 'Egg foo young with rice and soy gravy', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Beat the eggs with the soy sauce and white pepper, then stir in the bean sprouts, mushrooms, carrot, peas and spring onion.","Heat half the oil in a frying pan over medium-high heat. Ladle in three patties of the mixture and fry 2 min per side, until golden and set.","Keep them warm on a plate and fry the rest of the mixture the same way in the rest of the oil.","Whisk the stock, both soy sauces, sugar, cornstarch and sesame oil, pour into the pan and stir 1-2 min, until glossy and thickened.","Serve the patties on the rice with the gravy poured over."]'::jsonb, array['chinese', 'asian', 'vegetarian', 'healthy', 'high protein']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7d9bcee4-ff19-50c8-aa9e-2c4e7e147ba4'::uuid, 'Bibimbap with air-fryer tofu and fried eggs', 2, null::int, 30::int, 12::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Toss the tofu with half the soy sauce, then the cornstarch, and air-fry at 200°C for 12-15 min, shaking halfway, until crisp.","Blanch the spinach for 30 seconds and the bean sprouts for 1 min in a pan of boiling water. Drain, squeeze the spinach and season each with a little garlic, sesame oil, soy sauce and salt.","Dry the pan, heat half the vegetable oil and stir-fry the carrot and then the zucchini for 2 min each, seasoning with salt.","Fry the eggs in the rest of the oil for 2-3 min, until the whites are set and the yolks runny.","Mix the gochujang with the honey, vinegar, the rest of the sesame oil and 1 tbsp water.","Fill bowls with rice, arrange the vegetables and tofu in sections, top with an egg and sesame seeds and serve with the sauce to mix in."]'::jsonb, array['korean', 'asian', 'vegetarian', 'healthy', 'high protein', 'bowl']::text[], 'korean', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('4c670d9d-c2d4-5210-b5a1-1b41458ccad7'::uuid, 'Tofu and egg rice bowl with spinach', 2, null::int, 26::int, 8::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min.","Take the rice off the heat and leave it covered to rest 5 min.","Wilt the spinach in a frying pan with 2 tbsp water for 1-2 min. Squeeze it dry and dress it with 1 tsp of the soy sauce and the sesame seeds.","In the same pan, bring 150 ml water, the dashi, the rest of the soy sauce, the mirin and sugar to a simmer, add the onion and cook 3 min, then lay in the tofu and simmer 2-3 min, until hot through.","Lightly beat the eggs and pour two thirds over the onion and tofu. Cover and cook 1 min, then add the rest of the egg and cook 30-60 seconds more, until just set and still soft.","Spoon the rice into bowls, slide the tofu, egg and broth on top and scatter with spring onion. Serve the spinach alongside."]'::jsonb, array['japanese', 'asian', 'vegetarian', 'healthy', 'high protein', 'bowl']::text[], 'japanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('2dab32e5-2df9-5f3a-97c8-0e1b1330c3c5'::uuid, 'Air-fryer chilli paneer with Hakka noodles', 2, null::int, 25::int, 10::int, 15::int, '["Toss the paneer with 1 tbsp soy sauce and the chili powder, then the cornstarch and 1 tsp of the oil.","Air-fry at 200°C for 10 min, shaking halfway, until golden and crisp at the edges.","Meanwhile, cook the noodles in boiling water for 3-4 min, drain and rinse under cold water.","Heat the rest of the oil in a wok and stir-fry the garlic, ginger and chilli for 30 seconds, then the onion, pepper, cabbage and carrot for 3 min over high heat.","Add the soy sauce, ketchup, vinegar and sriracha with the noodles and toss 2 min, until hot and coated.","Toss in the paneer and spring onion and serve straight away."]'::jsonb, array['indian', 'chinese', 'vegetarian', 'healthy', 'high protein', 'stir-fry', 'quick']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('bfc455fb-ac6c-51b3-b897-bfa60df0bde4'::uuid, 'Air-fryer kadai paneer with rice', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml water on low heat for 12 min, then rest 5 min off the heat.","Toss the paneer, peppers and onion with 1 tsp of the oil, the chili powder and salt. Air-fry at 200°C for 8 min, stirring at 4 min, until charred at the edges.","Toast the coriander seeds and cumin in a dry pan for 1 min, then crush them coarsely.","Heat the rest of the oil in the pan, fry the garlic and ginger 1 min, then add the tomatoes and the crushed spices and cook 7-8 min, until thick and jammy.","Stir in the garam masala, the fenugreek leaves crushed between your palms and a splash of water.","Add the paneer and vegetables and toss 2 min to coat. Scatter with coriander and serve with the rice."]'::jsonb, array['indian', 'vegetarian', 'healthy', 'high protein', 'curry']::text[], 'indian', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b98b523a-deb3-5ab2-9dac-6d5aa531cac0'::uuid, 'Halloumi souvlaki with air-fryer lemon potatoes and tzatziki', 2, null::int, 30::int, 10::int, 20::int, '["Toss the potatoes with 2 tsp of the oil, half the oregano, the lemon zest and salt. Air-fry at 200°C for 18-20 min, shaking twice, until golden and tender.","Squeeze the cucumber dry and stir it into the yogurt with the garlic, mint and a pinch of salt to make the tzatziki.","Thread the halloumi, pepper and onion onto skewers and brush with the rest of the oil and oregano.","Cook the skewers in a hot griddle pan for 6-8 min, turning, until the halloumi is golden and the vegetables charred.","Squeeze half the lemon over the potatoes and the rest over the skewers.","Serve the skewers with the potatoes, cherry tomatoes and tzatziki."]'::jsonb, array['greek', 'mediterranean', 'vegetarian', 'healthy', 'high protein', 'grill']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('1083724c-2fbf-5649-a032-0662c173bfc0'::uuid, 'Air-fryer halloumi fajitas with pico de gallo', 2, null::int, 25::int, 10::int, 15::int, '["Toss the peppers and three quarters of the onion with the oil, cumin, paprika, chili powder, oregano and a pinch of salt.","Air-fry at 200°C for 8 min, shaking halfway.","Lay the halloumi on top (no salt: it is salty already) and air-fry at 180°C for 6-7 min more, until golden.","Mix the tomatoes, the rest of the onion, finely chopped, the chilli, coriander and the juice of half the lime into a pico de gallo. Stir the rest of the lime juice into the yogurt.","Warm the tortillas in a dry frying pan for 30 seconds per side.","Fill the tortillas with the peppers and halloumi, pico de gallo and lime yogurt."]'::jsonb, array['mexican', 'vegetarian', 'healthy', 'high protein', 'wrap', 'quick']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('a476feca-aa30-5999-a7c5-c8719997ae14'::uuid, 'Lemon orzo with spinach, chickpeas and feta', 2, null::int, 23::int, 8::int, 15::int, '["Soften the shallot and garlic in the oil in a deep frying pan over medium heat for 2 min.","Add the orzo and stir 1 min to toast it lightly.","Pour in the stock, bring to a simmer and cook 8 min, stirring often so it doesn''t stick.","Add the chickpeas and cook 2-3 min more, until the orzo is tender and most of the stock is absorbed.","Stir in the spinach until it wilts, then take off the heat and add the lemon zest, the juice of half the lemon and the dill. Season.","Serve topped with the feta and the rest of the lemon in wedges."]'::jsonb, array['greek', 'mediterranean', 'vegetarian', 'healthy', 'high protein', 'one-pot', 'quick']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('a0e60ae9-0495-574e-9edd-3e70131dce05'::uuid, 'Lentil bulgur pilaf with air-fryer vegetables and feta', 2, null::int, 30::int, 5::int, 25::int, '["Simmer the lentils in plenty of water for 10 min, until almost tender, then drain.","Meanwhile, toss the aubergine, pepper and zucchini with 2 tsp of the oil, the cumin, Aleppo pepper and salt. Air-fry at 200°C for 18 min, shaking twice, until soft and browned.","Fry the onion in the rest of the oil in a pan for 6 min, until golden. Stir in the tomato paste for 1 min.","Add the bulgur, lentils and hot stock, season, cover and cook on low heat for 12 min, until the liquid is absorbed.","Rest the pilaf covered for 3 min, then fluff it with a fork and stir in half the parsley.","Serve the pilaf topped with the vegetables, feta and the rest of the parsley, with lemon wedges."]'::jsonb, array['turkish', 'mediterranean', 'vegetarian', 'healthy', 'high protein']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('32a459d6-6e4c-5c14-99e3-530a6b68ae80'::uuid, 'Ful medames with eggs, pitta and tomato salad', 2, null::int, 25::int, 10::int, 15::int, '["Boil the eggs for 8 min, cool them in cold water and peel.","Fry the onion and cumin in 2 tsp of the oil in a pan over medium heat for 3 min, then add the garlic and chilli for 1 min.","Add the beans and 100 ml water, bring to the boil and simmer 5 min.","Crush the beans roughly with a potato masher, leaving some whole, and stir in two thirds of the lemon juice and salt.","Toss the tomato, cucumber and parsley with the rest of the lemon juice and salt. Warm the pitta in a dry pan for 1 min per side.","Spoon the ful into bowls, drizzle with the tahini thinned with a little water and the rest of the oil, and serve with the halved eggs, salad and pitta."]'::jsonb, array['middle eastern', 'african', 'vegetarian', 'healthy', 'high protein', 'quick']::text[], 'middle eastern', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f2420a6b-ce8c-5857-8883-92d0993e81dc'::uuid, 'Kuru fasulye with rice pilaf and cacık', 2, null::int, 30::int, 8::int, 22::int, '["Rinse the rice and fry it in the butter in a small pan for 1 min, then add 250 ml boiling water and a pinch of salt, cover and cook on low heat 12 min. Rest 5 min off the heat.","Soften the onion and pepper in the oil in a pan over medium heat for 5 min, then add the garlic for 1 min.","Stir in the tomato paste and Aleppo pepper for 1 min, then the tomatoes.","Add the beans and 250 ml water and simmer 12-15 min, until the sauce is thick and the beans have soaked up the flavour. Season.","For the cacık, squeeze the cucumber and stir it into the yogurt with the garlic, half the mint, a splash of water and salt.","Fluff the rice, top it with the beans and serve with the cacık sprinkled with the rest of the mint."]'::jsonb, array['turkish', 'vegetarian', 'healthy', 'high protein', 'stew']::text[], 'turkish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('da583daf-e2c4-5b19-a514-ea13247580cd'::uuid, 'Piperade with soft scrambled eggs and country bread', 2, null::int, 30::int, 10::int, 20::int, '["Soften the onion and peppers in the oil in a wide frying pan over medium heat for 10 min, stirring, until soft but not browned.","Add the garlic and thyme for 1 min, then the tomatoes and half the Espelette pepper. Cook 6-7 min, until the juices have mostly evaporated. Season.","Toast the bread while the vegetables finish.","Beat the eggs with a pinch of salt, lower the heat and pour them over the vegetables.","Stir gently for 1-2 min, until the eggs form soft, creamy curds, and take the pan off the heat while they are still slightly loose.","Sprinkle with the rest of the Espelette pepper and the parsley and serve with the toasted bread."]'::jsonb, array['french', 'vegetarian', 'healthy', 'high protein']::text[], 'french', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('52eefa89-ce22-5513-9f00-9911d9455167'::uuid, 'Black bean and quinoa bowls with corn salsa and avocado', 2, null::int, 25::int, 10::int, 15::int, '["Simmer the quinoa in 300 ml salted water, covered, for 13-15 min, until the water is absorbed. Rest 2 min and fluff.","Warm the oil in a pan with the garlic, cumin and chili powder for 1 min, add the beans and 3 tbsp water and heat 4-5 min. Add the juice of half a lime and salt.","Mix the corn, pepper, tomato, onion, chilli and half the coriander with the juice of 1 lime and salt.","Toss the avocado with the rest of the lime juice.","Fill bowls with quinoa, add the beans, corn salsa and avocado and finish with the rest of the coriander."]'::jsonb, array['american', 'mexican', 'vegetarian', 'healthy', 'high protein', 'bowl', 'quick']::text[], 'american', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7c0e8388-e897-555c-9ea0-ba6b55bb6a19'::uuid, 'Poulet à la moutarde with steamed potatoes and green beans', 2, null::int, 30::int, 10::int, 20::int, '["Boil the potatoes in salted water for 15 min, adding the green beans for the last 6 min, then drain.","Season the chicken and brown it in the oil and butter over medium-high heat for 4-5 min until golden all over, then lift it out.","Soften the shallots in the same pan for 2 min, pour in the wine and let it bubble until reduced by half, about 2 min.","Add the stock, thyme and chicken and simmer for 5 min until the chicken is cooked through.","Stir in both mustards and the crème fraîche and simmer gently for 2 min until the sauce coats a spoon; do not let it boil hard.","Serve the chicken and sauce with the potatoes and beans, scattered with parsley."]'::jsonb, array['french', 'quick', 'comfort']::text[], 'french', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('e4d19897-95ca-5b08-bc75-a7524f426999'::uuid, 'Chicken marsala with tagliatelle and spinach', 2, null::int, 28::int, 10::int, 18::int, '["Bring a large pan of salted water to the boil for the pasta.","Pound the chicken pieces to an even 1 cm, season them and dust lightly with the flour.","Fry the chicken in the oil over medium-high heat for 3 min a side until golden and cooked through, then set aside.","Brown the mushrooms in the same pan for 5 min, then add the garlic for 30 seconds.","Cook the tagliatelle as the packet says, about 8 min.","Pour the marsala into the mushrooms and let it bubble for 2 min, add the stock and simmer 3 min until slightly syrupy.","Return the chicken for 1-2 min to warm through, then swirl in the butter off the heat.","Drain the pasta, toss the spinach through it until wilted, and serve with the chicken and mushroom sauce and parsley."]'::jsonb, array['italian', 'quick']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bb33dad4-b7b9-5152-8e07-42e7fc9d9b6b'::uuid, 'Riz a djej (Lebanese chicken and vermicelli rice) with toasted nuts and salad', 2, null::int, 30::int, 10::int, 20::int, '["Simmer the chicken in the stock with the cinnamon stick, bay leaf and cardamom, covered, for 15 min until cooked through.","Meanwhile fry the vermicelli in the oil over medium heat for 2 min, stirring, until deep golden.","Stir in the rice, allspice, ground cinnamon and plenty of black pepper, then ladle in 300 ml of the hot stock from the chicken pan.","Cover the rice and cook on low heat for 15 min, then leave it to steam off the heat for 3 min.","Toast the almonds and pine nuts in a dry pan for 2-3 min until golden.","Toss the tomato, cucumber and parsley with the lemon juice and a pinch of salt.","Lift out the chicken, shred it, season with salt and a little allspice and moisten with a spoon of stock.","Pile the chicken on the rice, scatter with the nuts and serve with the salad and yogurt."]'::jsonb, array['lebanese', 'middle eastern', 'healthy']::text[], 'lebanese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('c89ba93f-ed33-576d-9ff1-98d36515c932'::uuid, 'Hunter''s chicken with air-fryer wedges and peas', 2, null::int, 30::int, 8::int, 22::int, '["Heat the oven to 200°C.","Toss the potato wedges with the oil, paprika and salt and air-fry at 200°C for 20-22 min, shaking twice, until crisp and golden.","Season the chicken breasts, wrap each in bacon rashers and lay them seam-side down on a lined tray.","Bake the chicken for 18 min until the bacon is crisp and the chicken is nearly cooked through.","Spoon the barbecue sauce over the chicken, top with the cheddar and bake 5 min more until bubbling and cooked through (75°C inside).","Simmer the peas in salted water for 3 min and drain.","Serve the chicken with the wedges and peas."]'::jsonb, array['british', 'comfort', 'kid-friendly', 'fakeaway']::text[], 'british', 'easy', '{"pots":2,"oven":true,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('80957d70-d4e9-5143-b879-cbd5c4ce5d2e'::uuid, 'Moroccan chicken tagine with potatoes and peas', 2, null::int, 30::int, 8::int, 22::int, '["Toss the chicken with the ginger, turmeric, pepper, saffron and a pinch of salt.","Cook the onion and garlic in the oil in a wide pan or tagine over medium heat for 3 min, add the chicken and turn it in the spices for 3 min, then lift the chicken out.","Add the potatoes and water, cover and simmer for 10 min until the potatoes are almost tender.","Return the chicken with the peas, half the herbs and the preserved lemon and olives, cover and simmer 6-7 min until the chicken is cooked through.","Uncover and let the sauce reduce for 1-2 min, then serve scattered with the rest of the herbs."]'::jsonb, array['moroccan', 'north african', 'healthy', 'one-pot']::text[], 'moroccan', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('546e41d8-88ea-522b-8bd4-783564dc0901'::uuid, 'Air-fryer piri-piri chicken thighs with rice and mixed salad', 2, null::int, 28::int, 10::int, 18::int, '["Mash or blitz the chillies, garlic, paprika, oregano, lemon juice, vinegar, 2 tbsp oil and a good pinch of salt into a loose piri-piri sauce.","Toss the chicken with half the sauce and air-fry at 200°C for 16-18 min, turning halfway and brushing with a little more sauce, until charred and cooked through.","Meanwhile rinse the rice and simmer it covered in 300 ml salted water for 12 min, then rest 5 min off the heat.","Toss the tomatoes, onion and lettuce with the oil, a splash of vinegar and salt.","Serve the chicken on the rice with the salad, with the remaining sauce for spooning over."]'::jsonb, array['portuguese', 'spicy', 'healthy', 'quick']::text[], 'portuguese', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('79f06879-912e-5951-aac6-7802f2f96566'::uuid, 'Pollo al chilindrón with crusty bread', 2, null::int, 30::int, 8::int, 22::int, '["Season the chicken and brown it in the oil in a wide pan over medium-high heat for 4 min, then lift it out.","Add the ham, onion and peppers and cook for 5 min until softened, then stir in the garlic and paprika for 30 seconds.","Pour in the wine and let it bubble for 1 min.","Add the tomatoes, bay leaf and chicken, cover and simmer for 12 min, stirring now and then, until the chicken is tender and the sauce thick.","Taste for salt and serve with parsley and the bread for mopping up the sauce."]'::jsonb, array['spanish', 'stew', 'healthy', 'one-pot']::text[], 'spanish', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('504053fb-d532-5d57-a3af-20c5bba801ee'::uuid, 'Air-fryer musakhan rolls with yogurt and chopped salad', 2, null::int, 30::int, 6::int, 24::int, '["Cook the onions in 2 tbsp of the oil with a pinch of salt over medium heat for 10-12 min, stirring often, until soft and sweet but not crisp.","Toast the pine nuts in a dry pan for 2 min until golden and set aside.","Add the chicken to the onions with the allspice, cinnamon, cardamom and pepper and cook for 6-7 min until cooked through.","Stir in the sumac and pine nuts and check the salt.","Spoon the filling along the lower edge of each flatbread, fold in the sides and roll up tightly.","Brush the rolls with the last of the oil and air-fry seam-side down at 190°C for 6-7 min until crisp and golden.","Toss the tomato and cucumber with the lemon juice, parsley and salt and serve with the rolls and the yogurt, dusted with a little more sumac."]'::jsonb, array['middle eastern', 'wrap', 'street food']::text[], 'middle eastern', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('1186e3b2-9887-52a7-90d7-c900d587fc90'::uuid, 'Tunisian chicken couscous with chickpeas, carrots and courgette', 2, null::int, 30::int, 10::int, 20::int, '["Brown the chicken and onion in the oil in a wide pan over medium-high heat for 5 min.","Stir in the garlic, tomato paste, harissa, paprika, caraway and coriander and fry for 1 min until the paste darkens.","Add the carrots and stock, cover and simmer for 8 min.","Add the courgette and chickpeas and simmer, uncovered, for 8 min until the vegetables are tender and the chicken cooked through.","Put the couscous in a bowl with the oil and a pinch of salt, pour over 200 ml of the hot red broth from the pan, cover for 5 min, then fluff with a fork.","Serve the couscous in bowls topped with the chicken, vegetables and more of the broth, with parsley."]'::jsonb, array['north african', 'spicy', 'healthy', 'one-pot']::text[], 'north african', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4011ea03-d3f9-5415-8dfb-79349ee13da5'::uuid, 'Poulet au vinaigre with rice and glazed carrots', 2, null::int, 30::int, 8::int, 22::int, '["Rinse the rice and simmer it covered in 300 ml salted water for 12 min, then rest 5 min off the heat.","Put the carrots in a small pan with the butter, sugar, a pinch of salt and water just to cover, and boil for 12-15 min until the water has gone and they are glazed.","Season the chicken and brown it in the oil over medium-high heat for 4 min a side, then lift it out.","Soften the shallots and garlic in the pan for 2 min, then pour in the vinegar and let it reduce by half, about 2 min.","Stir in the wine, tomato paste, tomatoes and stock, return the chicken, cover and simmer 8 min until cooked through.","Lift out the chicken, boil the sauce 2 min until syrupy, then whisk in the butter off the heat.","Serve the chicken and sauce with the rice and carrots, scattered with tarragon."]'::jsonb, array['french', 'healthy']::text[], 'french', 'easy', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('4bb1f1b5-a354-5343-a11e-facbac16796d'::uuid, 'Kotopoulo lemonato with air-fryer lemon potatoes and horiatiki', 2, null::int, 30::int, 8::int, 22::int, '["Toss the potatoes with 1 tbsp oil, half the lemon juice, 1 tsp oregano and salt, and air-fry at 200°C for 22 min, shaking twice, until golden and tender.","Rub the chicken with the garlic, zest, mustard, remaining oregano, salt and pepper.","Fry the chicken in 2 tsp oil over medium heat for 5-6 min a side until golden and cooked through.","Pour in the stock and remaining lemon juice and let it bubble for 2 min, turning the chicken, until the sauce is glossy.","Arrange the tomato, cucumber, onion and olives in a bowl, set the feta on top, sprinkle with oregano and dress with the vinegar and remaining oil.","Serve the chicken and its lemon sauce with the potatoes and the salad."]'::jsonb, array['greek', 'mediterranean', 'healthy']::text[], 'greek', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('96f7ec19-afcf-5e6a-9d55-7b131db9d31d'::uuid, 'Ragù bianco di pollo with rigatoni', 2, null::int, 30::int, 10::int, 20::int, '["Cook the onion, carrot and celery in the oil over medium heat for 6 min until soft.","Add the chicken, garlic, rosemary and sage and cook for 5 min, breaking up the mince, until it loses its pink colour and starts to colour.","Pour in the wine and let it evaporate, about 2 min.","Add the stock, season and simmer, half-covered, for 8-10 min until the ragù is moist but not runny.","Meanwhile cook the rigatoni in boiling salted water for 1 min less than the packet says.","Drain the pasta, keeping a cup of the water, and toss it in the ragù with half the parmesan and a splash of the water until glossy.","Serve with the rest of the parmesan, black pepper and parsley."]'::jsonb, array['italian', 'healthy']::text[], 'italian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('e7ba4eea-8b8a-5979-8259-c61a2df7bc23'::uuid, 'Air-fryer chicken Kiev with new potatoes and broccoli', 2, null::int, 30::int, 12::int, 18::int, '["Mash the cold butter with the garlic, parsley, lemon zest and a pinch of salt, then shape it into 2 small logs.","Cut a deep pocket into the thick side of each breast without going through, push in a butter log and press the opening closed.","Season the chicken, dust it with flour, dip it in the egg and press it into the panko so it is well coated, sealing the opening with extra crumbs.","Drizzle with the oil and air-fry at 190°C for 18 min, turning carefully halfway, until golden and cooked through (75°C in the thickest part).","Meanwhile boil the potatoes in salted water for 15 min, adding the broccoli for the last 4 min, then drain.","Rest the Kievs for 2 min and serve with the potatoes, broccoli and lemon wedges, spooning over any garlic butter that escapes."]'::jsonb, array['british', 'comfort', 'kid-friendly', 'fakeaway']::text[], 'british', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('21214849-426e-5a20-85fc-4f4df2e36c03'::uuid, 'Pollo en pepitoria with saffron rice and green beans', 2, null::int, 30::int, 10::int, 20::int, '["Hard-boil the egg for 10 min, cool it in cold water and peel it.","Rinse the rice and simmer it covered in 300 ml salted water for 12 min, laying the green beans on top for the last 6 min, then rest off the heat.","Fry the almonds, bread and garlic in the oil over medium heat for 2 min until golden, then lift them into a blender jug.","Season the chicken and brown it in the same pan for 4 min, then add the onion and cook 4 min until soft.","Pour in the sherry and let it bubble 1 min, then add the stock and bay leaf and simmer 5 min.","Blend the almonds, bread and garlic with the saffron, the egg yolk and a ladle of the stock into a smooth picada.","Stir the picada into the pan and simmer 3-4 min until the sauce thickens and the chicken is cooked through.","Serve with the rice and beans, topped with the chopped egg white and parsley."]'::jsonb, array['spanish', 'healthy']::text[], 'spanish', 'easy', '{"pots":3,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('4a614931-5ab2-5e8b-8931-0c77d0f912cb'::uuid, 'Air-fryer chicken kıymalı pide with shepherd''s salad', 2, null::int, 30::int, 5::int, 25::int, '["Fry the onion and green pepper in the oil for 3 min, add the chicken and cook 4 min, breaking it up, then stir in the tomato, pepper paste, cumin, half the aleppo pepper, salt and pepper and cook 2 min until fairly dry. Stir in half the parsley.","Cut the dough into 4 pieces and stretch each into an oval about 22 x 10 cm.","Spread the filling down the middle of each oval, fold the long edges up over the filling and pinch the ends into points to make boats.","Brush the dough edges with the egg.","Air-fry the pides two at a time on baking paper at 200°C for 7-8 min until the crust is golden and crisp underneath.","Toss the tomato, cucumber, red onion and remaining parsley with the lemon juice, oil, remaining aleppo pepper and salt.","Cut the pides into slices and serve with the salad and the yogurt."]'::jsonb, array['turkish', 'street food', 'healthy']::text[], 'turkish', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b96227fc-a4ea-4f49-ae27-f7234eccf631'::uuid, 'Phở gà (Vietnamese chicken noodle soup)', 2, null::int, 30::int, 10::int, 20::int, '["Char the onion halves and ginger cut side down in a dry soup pot over high heat for 5 min, until blackened in patches.","Add the star anise, coriander seeds and cinnamon and toast 30 s, then pour in the stock and bring to the boil.","Lower in the chicken breasts, cover and simmer very gently for 12-14 min until cooked through (no pink at the thickest point), then lift them out to rest.","Meanwhile cook the rice noodles in a pan of boiling water as the packet says (usually 4-6 min), drain and rinse briefly in hot water.","Season the broth with the fish sauce and sugar, simmer 2 min more, then strain out the aromatics and bring it back to a rolling boil.","Slice the chicken thinly across the grain.","Divide the noodles between deep bowls, top with the chicken and half the bean sprouts, and ladle over the boiling broth.","Scatter with spring onion and serve with the coriander, Thai basil, chilli, lime wedges and remaining bean sprouts to add at the table."]'::jsonb, array['vietnamese', 'asian', 'soup', 'healthy', 'light', 'dairy-free']::text[], 'vietnamese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('5432ab66-f6b2-4acd-b22f-ec9a21814ede'::uuid, 'Panang chicken curry with jasmine rice and green beans', 2, null::int, 28::int, 8::int, 20::int, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Heat the oil and 4 tbsp of the thickest coconut milk in a wok over medium heat for about 2 min, until it bubbles and the fat starts to separate.","Fry the curry paste in it for 1-2 min, stirring, until fragrant and a shade darker.","Add the chicken and stir-fry 3 min until it is no longer pink on the outside.","Pour in the rest of the coconut milk, add the green beans, fish sauce, sugar and half the lime leaves, and simmer 5 min.","Add the pepper and simmer 3 min more, until the chicken is cooked through and the sauce is thick enough to coat a spoon.","Serve over the rice, topped with the remaining lime leaves, the peanuts, Thai basil and chilli."]'::jsonb, array['thai', 'asian', 'curry', 'spicy', 'dairy-free']::text[], 'thai', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('1dbeb2e6-6a34-4c40-a9cc-75487a348f8c'::uuid, 'Air-fryer sweet and sour chicken with peppers, pineapple and rice', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Toss the chicken with a pinch of salt and 1 tsp soy sauce, then with the cornstarch and half the oil until every piece is coated.","Air-fry the chicken at 200°C for 12 min in a single layer, shaking halfway, until golden and cooked through.","Meanwhile whisk the ketchup, vinegar, sugar, soy sauce, pineapple juice, 3 tbsp water and the cornstarch for the sauce.","Stir-fry the onion, peppers and garlic in the remaining oil in a very hot wok for 3 min, until just softened but still crisp.","Add the pineapple for 1 min, then pour in the sauce and bubble for 1 min until thick and glossy.","Toss in the chicken until coated and serve straight away over the rice."]'::jsonb, array['chinese', 'asian', 'fakeaway', 'kid-friendly', 'dairy-free']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('8113b4b3-f76a-494e-a5c5-d84d0356e3d6'::uuid, 'Chicken chow mein with cabbage and bean sprouts', 2, null::int, 22::int, 10::int, 12::int, '["Toss the chicken with 1 tsp soy sauce, 1 tsp of the rice wine and the cornstarch.","Cook the noodles in boiling water as the packet says (usually 3-4 min), drain, rinse under cold water, shake dry and toss with the sesame oil.","Mix the oyster sauce, soy sauce, dark soy sauce, the rest of the rice wine, the sugar, a good pinch of white pepper and 2 tbsp water.","Stir-fry the chicken in 1 tbsp oil in a very hot wok for 3-4 min until cooked through, then tip it onto a plate.","Add the remaining oil, then the garlic, carrot and cabbage, and stir-fry 2 min.","Add the noodles and the sauce and toss over high heat for 2 min, until the noodles are evenly coloured and starting to crisp in places.","Return the chicken with the bean sprouts and spring onions, toss 1 min more and serve."]'::jsonb, array['chinese', 'asian', 'stir-fry', 'fakeaway', 'quick', 'dairy-free']::text[], 'chinese', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7a3a5822-8944-4bae-8473-493e30aee3a1'::uuid, 'Dak kalguksu (Korean chicken noodle soup)', 2, null::int, 30::int, 8::int, 22::int, '["Bring the stock to the boil with the onion and the 2 crushed garlic cloves, add the chicken, cover and simmer gently for 12-14 min until cooked through.","Meanwhile mix the soy sauce, gochugaru, grated garlic, half the spring onion, the sesame oil and sesame seeds into a dipping sauce.","Lift out the chicken and shred it with two forks.","Add the potato to the broth and simmer 5 min.","Shake the excess flour off the noodles, add them with the courgette and simmer 3-4 min, until the noodles are tender and the potato is soft.","Return the chicken and season the broth with salt to taste.","Ladle into deep bowls, scatter with the remaining spring onion and serve with the sauce to stir in."]'::jsonb, array['korean', 'asian', 'soup', 'comfort', 'healthy', 'dairy-free']::text[], 'korean', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('91ab3b25-463b-475e-a3b6-a6a44ba4b226'::uuid, 'Air-fryer chicken 65 with lemon rice and cucumber raita', 2, null::int, 30::int, 10::int, 20::int, '["Rinse the rice and simmer it covered in 225 ml salted water with 0.25 tsp turmeric on low heat for 12 min, then leave it covered off the heat for 5 min.","Mix the chicken with the yogurt, ginger, garlic, chilli powder, turmeric, garam masala and a good pinch of salt, then with the cornstarch and half the oil until it clings.","Air-fry at 200°C for 12-14 min in a single layer, shaking halfway, until the edges are crisp and the chicken is cooked through.","Meanwhile stir the cucumber into the yogurt with a pinch of salt and cumin, and toss the tomato and red onion with a squeeze of the lemon.","Heat the remaining oil in a frying pan and fry the mustard seeds until they pop, then add the peanuts, curry leaves and green chilli for 1 min.","Fork half the tempering and the rest of the lemon juice through the rice.","Toss the chicken in the pan with the remaining tempering for 1 min and serve with the lemon rice, raita and tomato salad."]'::jsonb, array['indian', 'asian', 'spicy', 'fakeaway', 'high protein']::text[], 'indian', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b09ea84f-1679-4fbd-8a54-1faf5a24c7b1'::uuid, 'Air-fryer lemongrass chicken bánh mì with pickled carrot and daikon', 2, null::int, 30::int, 15::int, 15::int, '["Dissolve the pickle sugar and a pinch of salt in the vinegar and 3 tbsp warm water, add the carrot and daikon and leave to pickle while you cook.","Mix the lemongrass, garlic, fish sauce, soy sauce, sugar and oil, and coat the chicken thighs in it.","Air-fry the thighs flat at 200°C for 14 min, turning halfway, until charred at the edges and cooked through (75°C inside).","Rest the chicken 2 min, then slice it.","Warm the baguettes in the air fryer at 180°C for 2 min until crusty, then split them lengthways.","Fill with the chicken, the drained pickles, cucumber, coriander, chilli and a little sriracha."]'::jsonb, array['vietnamese', 'asian', 'sandwich', 'street food', 'healthy', 'dairy-free']::text[], 'vietnamese', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('c234f8c1-e739-4a1b-abe2-4a0cda115c49'::uuid, 'Pad see ew with chicken and broccoli', 2, null::int, 24::int, 12::int, 12::int, '["Soak the noodles in very hot water as the packet says (about 8-10 min) until pliable but still firm, drain and toss with 1 tsp of the dark soy sauce.","Mix the remaining dark soy sauce, the soy sauce, oyster sauce, sugar, vinegar and 2 tbsp water.","Heat 1 tbsp oil in a wok over high heat, fry the garlic 10 s, then stir-fry the chicken 3-4 min until cooked through.","Add the broccoli stems, then the florets and leaves with a splash of water, and stir-fry 2 min until bright green.","Push everything to one side, add the remaining oil, crack in the eggs and scramble until just set.","Add the noodles and sauce and toss for 2-3 min, letting them sit against the hot wok now and then so they char in places.","Serve with a pinch of white pepper and chilli flakes."]'::jsonb, array['thai', 'asian', 'stir-fry', 'fakeaway', 'quick', 'dairy-free']::text[], 'thai', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7bcf6900-1eeb-4919-8de4-c5ca6830b771'::uuid, 'Air-fryer Sri Lankan devilled chicken with rice', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Toss the chicken with the soy sauce, chilli powder and plenty of black pepper, then with the cornstarch and 1 tsp of the oil.","Air-fry at 200°C for 12 min, shaking halfway, until browned and cooked through.","Meanwhile mix the ketchup, soy sauce, chilli flakes, vinegar and 2 tbsp water.","Heat the remaining oil in a wok over high heat, fry the garlic and ginger 30 s, then the onion and pepper for 3 min until charred at the edges but still crisp.","Add the tomato for 1 min, then the sauce, and bubble 1 min.","Toss in the chicken for 1 min until glossy and serve with the rice."]'::jsonb, array['asian', 'spicy', 'stir-fry', 'fakeaway', 'dairy-free']::text[], 'asian', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('fd22e8d3-097f-4f4d-a0bb-2e031183ba9a'::uuid, 'Air-fryer ayam percik with rice and cucumber', 2, null::int, 30::int, 12::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Rub the chicken with the turmeric and a pinch of salt.","Chop the shallots, garlic, lemongrass, ginger and chillies very finely together (or blitz with 2 tbsp water) into a coarse paste.","Fry the paste in the oil in a small pan over medium heat for 4 min, stirring, until soft and fragrant.","Add the coconut milk, tamarind, sugar and a pinch of salt and simmer 8 min, stirring often, until reduced to a thick sauce.","Meanwhile air-fry the chicken flat at 200°C for 10 min.","Brush the chicken thickly with about half the sauce and air-fry 4-5 min more, until the sauce blisters and chars in spots and the chicken is cooked through (75°C inside).","Slice and serve with the rice, cucumber, lime and the remaining sauce."]'::jsonb, array['malaysian', 'asian', 'spicy', 'grill', 'dairy-free']::text[], 'malaysian', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('3bc79fd1-6944-40e2-afe3-3384c6df21d8'::uuid, 'Soto ayam (Indonesian turmeric chicken soup) with vermicelli', 2, null::int, 30::int, 8::int, 22::int, '["Chop the shallots, garlic and ginger very finely together, then mix in the turmeric and ground coriander.","Fry the paste in the oil in a soup pot over medium heat with the lemongrass and lime leaves for 3 min, until fragrant.","Add the stock and chicken thighs, bring to the boil, cover and simmer 15 min until the chicken is cooked through.","Meanwhile boil the eggs for 8 min in a small pan, cool them in cold water, peel and halve; then pour boiling water over the vermicelli and leave 3-5 min until soft, and drain.","Lift out the chicken, shred it and return it to the pot; season the broth with salt and a squeeze of lime.","Divide the vermicelli, cabbage and bean sprouts between deep bowls and ladle the boiling broth and chicken over them.","Top with the eggs and spring onion and serve with lime wedges and chilli."]'::jsonb, array['indonesian', 'asian', 'soup', 'healthy', 'dairy-free']::text[], 'indonesian', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('831a6241-ea1d-4c9f-b882-78713c367a20'::uuid, 'Pancit bihon with chicken, cabbage and green beans', 2, null::int, 27::int, 12::int, 15::int, '["Soak the noodles in cold water for 5-10 min until pliable, then drain.","Heat the oil in a wok or large frying pan and fry the onion and garlic 2 min until soft.","Add the chicken and stir-fry 4 min until cooked through.","Add the carrot and green beans for 2 min, then the cabbage for 1 min; lift out half the vegetables and set aside.","Pour in the stock and soy sauce with plenty of black pepper and bring to the boil.","Add the noodles and toss over medium-high heat for 4-5 min, until they have absorbed the liquid and are tender.","Return the reserved vegetables, toss and serve with lemon wedges to squeeze over."]'::jsonb, array['filipino', 'asian', 'stir-fry', 'healthy', 'dairy-free']::text[], 'filipino', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('6c5bdac0-bd42-458f-b0a0-1afc9a981ced'::uuid, 'Gaeng jued woon sen (Thai glass noodle soup with chicken meatballs)', 2, null::int, 27::int, 12::int, 15::int, '["Soak the glass noodles in warm water for 10 min, drain and cut them into shorter lengths with scissors.","Mix the chicken with the soy sauce, grated garlic, coriander stalks, cornstarch and a good pinch of white pepper.","Bring the stock to the boil with the smashed garlic and carrot.","Drop in heaped teaspoons of the chicken mixture and simmer 5 min, until the meatballs float and are cooked through.","Add the cabbage and mushrooms and simmer 4 min until the cabbage is tender.","Add the glass noodles and simmer 2 min until they turn clear, then season with the fish sauce, soy sauce and white pepper.","Ladle into bowls and scatter with spring onion and coriander leaves."]'::jsonb, array['thai', 'asian', 'soup', 'healthy', 'light', 'dairy-free']::text[], 'thai', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('25df8f45-66ea-40af-a171-c28749ca3e5b'::uuid, 'Mie ayam (Indonesian chicken noodles with pak choi and mushrooms)', 2, null::int, 28::int, 10::int, 18::int, '["Fry the shallots in the oil in a frying pan over medium heat for 2 min, then add the garlic and ginger for 1 min.","Add the chicken and cook 5 min, breaking it up, until it is no longer pink.","Add the mushrooms for 2 min, then the kecap manis, soy sauce, oyster sauce, a pinch of white pepper and 100 ml water, and simmer 4 min until glossy and thick.","Meanwhile heat the stock in a small pan with half the spring onion and keep it at a simmer.","Cook the noodles in a pan of boiling water as the packet says (usually 3-4 min), adding the pak choi for the last 2 min, then drain.","Toss the noodles in the serving bowls with the sesame oil and soy sauce.","Top with the chicken and pak choi, scatter with the rest of the spring onion and serve the hot broth and chilli alongside."]'::jsonb, array['indonesian', 'asian', 'healthy', 'comfort', 'dairy-free']::text[], 'indonesian', 'easy', '{"pots":3,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('f1694737-c846-4e5d-80f8-b9e4449b3c80'::uuid, 'Yu xiang aubergine with minced chicken and rice', 2, null::int, 28::int, 10::int, 18::int, '["Rinse the rice and simmer it covered in 225 ml salted water on low heat for 12 min, then leave it covered off the heat for 5 min.","Toss the aubergine with 2 tsp of the oil and a pinch of salt and air-fry at 200°C for 12-14 min, shaking twice, until soft and golden.","Meanwhile mix the soy sauce, black vinegar, sugar, rice wine, cornstarch and 100 ml water.","Heat the remaining oil in a wok over high heat and stir-fry the chicken 4 min, breaking it up, until crumbly and cooked.","Add the doubanjiang and fry 1 min until the oil turns red, then the garlic, ginger and spring onion whites for 30 s.","Pour in the sauce and bubble until it thickens, about 1 min.","Fold in the aubergine for 2 min so it soaks up the sauce, scatter with the spring onion greens and serve over the rice."]'::jsonb, array['chinese', 'asian', 'spicy', 'stir-fry', 'dairy-free']::text[], 'chinese', 'medium', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('61a4614d-2258-4b07-a812-256fc42b6897'::uuid, 'Air-fryer chicken al pastor tacos with pineapple', 2, null::int, 27::int, 12::int, 15::int, '["Cover the chillies with boiling water and soak for 10 min until soft.","Blend the drained chillies with 50 g of the pineapple, the garlic, vinegar, cumin, oregano, paprika, 1 tsp salt and 3 tbsp of the soaking water to a smooth paste.","Toss the chicken strips with the paste and the oil. Cut the rest of the pineapple into 1.5 cm chunks.","Air-fry the chicken and onion wedges in one layer at 200 °C for 8 min.","Add the pineapple, shake the basket and cook 6-7 min more, until the chicken is charred at the edges and cooked through (74 °C inside).","Meanwhile warm the tortillas in a dry frying pan for 30 s a side and keep them wrapped in a tea towel.","Roughly chop the chicken, onion and pineapple, pile onto the tortillas and top with chopped raw onion, coriander, a squeeze of lime and hot sauce if you like."]'::jsonb, array['mexican', 'street food', 'spicy', 'quick', 'healthy']::text[], 'mexican', 'easy', '{"pots":1,"oven":false,"special":["blender","air fryer"]}'::jsonb, 'Claude', null),
  ('6dc60573-1dbd-4738-8575-53499b6ab0d7'::uuid, 'Ají de gallina with potatoes, rice and salsa criolla', 2, null::int, 30::int, 10::int, 20::int, '["Bring the stock to a simmer, add the chicken, potato slices and the egg, and poach gently for 12-15 min until the chicken is cooked through and the potatoes are tender. Lift everything out and keep the stock.","Meanwhile put the rice in a pan with 300 ml water and a pinch of salt, cover and cook on low heat for 12 min, then rest off the heat.","Soak the bread in the milk. Rinse the sliced red onion in cold water, drain, and toss with the lime juice, coriander, chilli and a pinch of salt for the salsa criolla.","Fry the chopped onion in the oil over medium heat for 6 min until soft and golden. Add the garlic, ají amarillo paste and turmeric and cook 2 min.","Blend the soaked bread and milk with the walnuts until smooth, add to the pan with 200 ml of the poaching stock and simmer 4-5 min, stirring, until thick and creamy.","Shred the chicken into the sauce, stir in the parmesan and loosen with a little more stock if needed. Season with salt and pepper.","Serve the chicken over the rice with the potato slices, topped with the quartered egg and the olives, and the salsa criolla on the side."]'::jsonb, array['peruvian', 'comfort', 'spicy', 'quick']::text[], 'peruvian', 'medium', '{"pots":3,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null),
  ('5864a3c5-72aa-4762-aff5-8cd8914c7334'::uuid, 'Air-fryer anticuchos de pollo with potatoes and corn', 2, null::int, 28::int, 10::int, 18::int, '["Put the potatoes in a pan of cold salted water, bring to the boil and cook 15 min until tender, adding the corn rounds for the last 6 min.","Mix the ají panca paste, garlic, vinegar, cumin, oregano, oil, ½ tsp salt and some pepper. Toss the chicken in it and thread onto 4 short skewers, keeping the leftover marinade.","Air-fry the skewers at 200 °C for 12-14 min, turning and brushing with the leftover marinade halfway, until charred at the edges and cooked through (74 °C inside).","Stir the ají amarillo paste with the lime juice, spring onion, coriander, 1 tbsp water and a pinch of salt for the dipping sauce.","Drain the potatoes and corn.","Serve the skewers with the potatoes and corn, with the ají sauce to dip."]'::jsonb, array['peruvian', 'street food', 'grill', 'quick', 'healthy']::text[], 'peruvian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('862414f6-3de8-4073-8567-200d720b2563'::uuid, 'Galinhada (Brazilian chicken and turmeric rice)', 2, null::int, 30::int, 8::int, 22::int, '["Season the chicken with the lime juice, half the garlic, ½ tsp salt and pepper.","Heat the oil in a wide pot over medium-high heat and brown the chicken for 5 min, stirring now and then.","Add the onion and pepper and cook 3 min until softened, then the rest of the garlic, the tomato and the turmeric for 1 min.","Stir in the rice for 1 min to coat it, pour in the hot stock, bring to the boil, cover and cook on low heat for 12 min.","Scatter the peas over the rice, cover again and cook 4-5 min more until the rice is tender and the liquid is absorbed.","Rest 2 min off the heat, then fold in the parsley and spring onions (cheiro-verde) and check the salt."]'::jsonb, array['brazilian', 'one-pot', 'quick', 'healthy', 'kid-friendly']::text[], 'brazilian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('3c498c93-195c-4b11-a061-ca0fc9abf27e'::uuid, 'Strogonoff de frango with rice', 2, null::int, 28::int, 8::int, 20::int, '["Put the rice in a pan with 300 ml water and a pinch of salt, cover and cook on low heat for 12 min, then rest off the heat.","Season the chicken with salt and pepper and brown it in the oil in a large frying pan over high heat for 4-5 min. Lift out onto a plate.","Lower the heat, add the butter and onion and cook 3 min, then the garlic and mushrooms for 5 min until the mushrooms have given off their liquid and it has evaporated.","Return the chicken with the tomato paste, ketchup, mustard and stock and simmer 3 min until the chicken is cooked through.","Stir in the cream and warm 1-2 min without boiling. Season to taste.","Serve the strogonoff over the rice with the parsley on top."]'::jsonb, array['brazilian', 'comfort', 'quick', 'kid-friendly']::text[], 'brazilian', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('65496410-7e58-455e-b55c-83c49578e92b'::uuid, 'Pollo a la provenzal with air-fryer potatoes and mixed salad', 2, null::int, 30::int, 10::int, 20::int, '["Toss the potatoes with 1 tsp of the oil and a pinch of salt and air-fry at 200 °C for 20 min, shaking twice, until golden and crisp.","Mix the garlic, parsley, chili flakes, 1.5 tbsp of the oil and a pinch of salt: this is the provenzal.","Season the chicken and cook it in 1 tsp oil in a frying pan over medium-high heat for 4-5 min a side until golden and cooked through (74 °C inside).","Lower the heat, spoon half the provenzal over the chicken and warm for 30 s, without letting the garlic brown.","Toss the lettuce, tomatoes and red onion with the vinegar, the remaining oil and a pinch of salt.","Toss the hot potatoes with the rest of the provenzal and serve with the chicken and the salad."]'::jsonb, array['argentinian', 'quick', 'healthy', 'kid-friendly']::text[], 'argentinian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('86831f68-34ef-4bff-968a-1190df8a396a'::uuid, 'Trinidad curry chicken and potatoes with rice', 2, null::int, 30::int, 10::int, 20::int, '["Mix the spring onions, coriander, thyme and garlic (green seasoning). Toss the chicken with half of it, 1 tsp of the curry powder and ½ tsp salt.","Put the rice in a pan with 300 ml water and a pinch of salt, cover and cook on low heat for 12 min, then rest off the heat.","Mix the rest of the curry powder and the cumin with 3 tbsp water. Heat the oil in a pot, add the paste and cook 1-2 min, stirring, until darker and almost dry.","Add the onion and the rest of the green seasoning and cook 2 min, then the chicken, stirring to coat it, for 3 min.","Add the potatoes, tomato, scotch bonnet and 300 ml water, bring to the boil and simmer partly covered for 15 min, until the potatoes are tender and starting to break down into a thick gravy.","Remove the scotch bonnet, season to taste and serve the curry with the rice."]'::jsonb, array['caribbean', 'curry', 'spicy', 'quick', 'healthy']::text[], 'caribbean', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('deeb91fe-6475-4d50-9c7e-e913db5f79c4'::uuid, 'Chicken étouffée over rice', 2, null::int, 30::int, 8::int, 22::int, '["Put the rice in a pan with 300 ml water and a pinch of salt, cover and cook on low heat for 12 min, then rest off the heat.","Toss the chicken with half the cajun seasoning and brown it in the oil in a heavy pan over high heat for 4 min. Lift out.","Add the butter and flour to the pan and stir over medium heat for 5-6 min until the roux is the colour of peanut butter.","Add the onion, pepper and celery and cook 5 min, stirring, until soft. Stir in the garlic, tomato paste and the rest of the cajun seasoning for 1 min.","Whisk in the stock a little at a time, add the bay leaf and simmer 5 min until it thickens to a gravy.","Return the chicken and simmer 4 min until cooked through. Add the hot sauce, most of the spring onions and the parsley and season.","Serve over the rice with the rest of the spring onions."]'::jsonb, array['creole', 'american', 'spicy', 'comfort', 'healthy']::text[], 'creole', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('227348ae-dfc7-41c9-a052-1b8d46c72a76'::uuid, 'Air-fryer blackened chicken with maque choux and new potatoes', 2, null::int, 28::int, 8::int, 20::int, '["Cook the potatoes in boiling salted water for 15 min until tender.","Mix the paprika, thyme, oregano, cayenne, black pepper and ½ tsp salt. Rub the chicken with the oil, then coat it all over with the spice mix.","Air-fry the chicken at 200 °C for 14-16 min, turning halfway, until the crust is very dark and the inside reaches 74 °C. Rest 3 min.","Meanwhile melt the butter in a frying pan and cook the onion, pepper and celery over medium heat for 5 min.","Add the garlic and corn and cook 4 min until some kernels brown, then the tomatoes for 2 min. Stir in the spring onions and season: this is the maque choux.","Drain the potatoes, slice the chicken and serve with the maque choux."]'::jsonb, array['american', 'creole', 'spicy', 'quick', 'healthy']::text[], 'american', 'easy', '{"pots":2,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('b85afec3-ff92-4b1a-8281-70cc6566442d'::uuid, 'Air-fryer buffalo chicken wraps with celery-carrot slaw', 2, null::int, 24::int, 12::int, 12::int, '["Toss the chicken with the cornstarch, paprika, ½ tsp salt and the oil.","Air-fry at 200 °C for 10-12 min, shaking halfway, until golden and cooked through (74 °C inside).","Melt the butter in a small pan and whisk in the hot sauce.","Mix the celery, carrot and lettuce. Stir the yogurt with the lemon juice, chives, garlic, a pinch of salt and the blue cheese if using.","Toss the hot chicken in the buffalo sauce. Warm the tortillas in the dry pan for 20 s each.","Fill each tortilla with slaw, chicken and a spoonful of dressing, roll up tightly and cut in half."]'::jsonb, array['american', 'wrap', 'spicy', 'fakeaway', 'quick', 'healthy']::text[], 'american', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('413dc209-59c0-4ec8-8329-7f9a9305613c'::uuid, 'Air-fryer chicken suya with flatbread, tomato and onion', 2, null::int, 24::int, 10::int, 14::int, '["Grind the peanuts to a fine powder in a blender or spice grinder, in short pulses so they don''t turn to butter. Mix with the paprika, cayenne, ginger and ½ tsp salt (yaji) and set 2 tbsp aside.","Toss the chicken with the garlic, oil and the rest of the yaji until well coated, then thread onto skewers.","Air-fry at 200 °C for 12-14 min, turning halfway, until charred at the edges and cooked through (74 °C inside).","Meanwhile slice the onion, tomatoes and cucumber.","Warm the flatbreads in a dry frying pan for 30 s a side.","Sprinkle the hot suya with the reserved yaji and serve with the onion, tomato, cucumber, flatbreads and lime."]'::jsonb, array['african', 'street food', 'grill', 'spicy', 'quick', 'healthy']::text[], 'african', 'easy', '{"pots":1,"oven":false,"special":["blender","air fryer"]}'::jsonb, 'Claude', null),
  ('385b83b5-8fee-43d8-8d1f-2c5863cbf5c4'::uuid, 'Chakhokhbili (Georgian chicken and tomato stew) with bread', 2, null::int, 30::int, 8::int, 22::int, '["Season the chicken and brown it in the butter in a wide pan over medium-high heat for 5 min, turning once. Lift out.","Add the onions to the pan and cook over medium heat for 6 min until soft and lightly golden.","Stir in the garlic, khmeli suneli and chilli for 1 min, then add the tomatoes and a pinch of salt.","Return the chicken, cover partly and simmer 10-12 min, until the sauce is thick and the chicken is tender and cooked through.","Stir in half the herbs, take off the heat and rest 2 min, then scatter over the rest.","Slice the bread and serve it with the stew to mop up the sauce."]'::jsonb, array['georgian', 'stew', 'quick', 'healthy']::text[], 'georgian', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('bf979208-43d1-47cf-93a4-ee683be8a56c'::uuid, 'Air-fryer Persian chicken and herb kotlet with flatbread and salad', 2, null::int, 26::int, 12::int, 14::int, '["Coarsely grate the potato and onion, put them in a clean tea towel and squeeze out as much liquid as you can.","Mix them with the chicken, egg, parsley, coriander, breadcrumbs, turmeric, 1 tsp salt and ½ tsp pepper until evenly combined.","With wet hands shape 6 oval patties about 1.5 cm thick and brush them with the oil.","Air-fry at 200 °C for 12-14 min, turning halfway, until deep golden and cooked through (74 °C inside).","Meanwhile arrange the tomatoes, cucumber, radishes, lettuce and mint on a plate, with the gherkins and lemon if using.","Warm the flatbreads in the air fryer for 1 min at the end and serve the kotlet wrapped in the bread with the salad and herbs."]'::jsonb, array['persian', 'middle eastern', 'quick', 'kid-friendly', 'healthy']::text[], 'persian', 'easy', '{"pots":1,"oven":false,"special":["air fryer"]}'::jsonb, 'Claude', null),
  ('963bae66-37e6-4df7-b9f0-7da20c482b25'::uuid, 'Kotlety z kurczaka (Polish chicken patties) with dill potatoes and mizeria', 2, null::int, 30::int, 12::int, 18::int, '["Cook the potatoes in boiling salted water for 15-18 min until tender.","Sprinkle the cucumber with ½ tsp salt and leave 10 min, then squeeze out the liquid and mix with the yogurt, vinegar, sugar and a third of the dill for the mizeria.","Soak the bread in the milk for 2 min, squeeze and crumble it into the chicken with the egg, onion, garlic, a third of the dill, ¾ tsp salt and some pepper. Mix well.","With wet hands shape 4 oval patties about 2 cm thick and coat them in the breadcrumbs.","Fry in the oil in a frying pan over medium heat for 5-6 min a side until golden and cooked through (74 °C inside).","Drain the potatoes, toss with the butter and the rest of the dill and serve with the patties and the mizeria."]'::jsonb, array['polish', 'quick', 'kid-friendly', 'healthy']::text[], 'polish', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, 'Claude', null),
  ('7be6c3d7-5a6e-4703-93fc-0a652a74598e'::uuid, 'Albóndigas de pollo in chipotle-tomato sauce with rice', 2, null::int, 30::int, 12::int, 18::int, '["Put the rice in a pan with 300 ml water and a pinch of salt, cover and cook on low heat for 12 min, then rest off the heat.","Blend the tomatoes, chipotle paste, onion, 1 clove of garlic and the oregano until smooth.","Mix the chicken with the egg, breadcrumbs, mint, cumin, the other clove of garlic (crushed) and ¾ tsp salt, and roll into 14-16 walnut-sized balls with wet hands.","Heat the oil in a wide pan, pour in the tomato sauce and fry it for 3 min, stirring, until it darkens. Add the stock and carrot and bring to a simmer.","Drop in the meatballs, cover and simmer gently for 8 min.","Add the zucchini, cover and simmer 5 min more, until the meatballs are cooked through and the vegetables tender. Season.","Serve the albóndigas and sauce over the rice with coriander on top."]'::jsonb, array['mexican', 'spicy', 'comfort', 'quick', 'healthy']::text[], 'mexican', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, 'Claude', null)
) as v(id, title, servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, difficulty, equipment, source_name, source_url)
where x.id = v.id and x.household_id is null
  and (x.title, x.servings, x.original_servings, x.total_min, x.prep_min, x.cook_min, x.steps, x.tags, x.cuisine, x.difficulty, x.equipment, x.source_name, x.source_url)
  is distinct from (v.title, v.servings, v.original_servings, v.total_min, v.prep_min, v.cook_min, v.steps, v.tags, v.cuisine, v.difficulty, v.equipment, v.source_name, v.source_url);

-- Ingredient lines of seed recipes 1-100, as in recipes.json: gone lines removed.
